-- Duzelis86: ky/et push templates for the daily notification job (values from the reviewed source-bound bundles).
ALTER TABLE public.pregnancy_day_notifications ADD COLUMN IF NOT EXISTS title_ky text, ADD COLUMN IF NOT EXISTS body_ky text, ADD COLUMN IF NOT EXISTS title_et text, ADD COLUMN IF NOT EXISTS body_et text;
ALTER TABLE public.mommy_day_notifications ADD COLUMN IF NOT EXISTS title_ky text, ADD COLUMN IF NOT EXISTS body_ky text, ADD COLUMN IF NOT EXISTS title_et text, ADD COLUMN IF NOT EXISTS body_et text;
ALTER TABLE public.scheduled_notifications ADD COLUMN IF NOT EXISTS title_ky text, ADD COLUMN IF NOT EXISTS body_ky text, ADD COLUMN IF NOT EXISTS title_et text, ADD COLUMN IF NOT EXISTS body_et text;
UPDATE public.pregnancy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('e07ed45f-67ec-4ce6-a8d6-4499daea0b9d'::uuid,'Жаңы саякат башталат! 🚀','Сиздин денеңиз улуу кереметти тосуп алууга даярданууда. Бул укмуштуудай саякатка даярсызбы?','Uus teekond algab! 🚀','Sinu keha valmistub suureks imeks. Kas oled selleks uskumatuks teekonnaks valmis?'),
('3ff0a063-2126-4cd6-a3ce-f5e944bb5487'::uuid,'Витаминдериңизди ичүүнү унуттуңузбу? 💊','Фолий кислотасы учурда сиздин эң жакын досуңуз! Келечектеги балаңыздын ден соолугунун пайдубалы үчүн "Тамактануу" бөлүмүн карап көрүңүз!','Kas võtsid vitamiinid? 💊','Foolhape on praegu sinu parim sõber! Tulevase beebi tervisliku vundamendi jaoks heida pilk toitumise sektsiooni!'),
('a2855683-73b8-4bf4-af85-cc599724b360'::uuid,'Бүгүн өзүңүздү кандай сезип жатасыз? 🌈','Жаңы барак ачылып жатканда, сезимдериңиз ар кандай болушу мүмкүн. Бүгүн "Маанай күндөлүгүнө" сезимдериңизди жазып, абалыңызга көз салыңыз.','Kuidas sul täna läheb? 🌈','Selle uue peatüki alguses võivad emotsioonid olla seinast seina. Pane oma tunded täna meeleolupäevikusse kirja ja jälgi, kuidas sul läheb.'),
('f1a0230f-d87a-49ad-b1c8-d849ef306a7f'::uuid,'Мен азырынча микроскопиялык өлчөмдөмүн! 🔬','Улуу окуялар көбүнчө кичинекей нерседен башталат. Азыр келечектеги балаңыз болгону бир ой болушу мүмкүн, бирок анын потенциалы чексиз!','Olen praegu veel mikroskoopiline! 🔬','Suured lood saavad sageli alguse pisikestest asjadest. Praegu on sinu tulevane beebi alles algusjärgus, kuid tema potentsiaal on tõeliselt piiritu!'),
('137ef65d-9ea9-410c-9d5d-bbb4811b21f8'::uuid,'Детокс убактысы! 🚫','Тамеки, алкоголь же ашыкча кофеинби? Алар менен коштошууга эң сонун убакыт. Дени сак эне — наристенин дени сак башталышы.','Aeg puhastuseks! 🚫','Sigaretid, alkohol või liigne kofeiin? See on ideaalne aeg nendega hüvasti jätta. Terve ema tähendab sinu pisikesele tervislikku algust.'),
('f4bccccc-158d-4658-9abe-6ea45b62e469'::uuid,'Суу идишиңиз жаныңыздабы? 💧','Суюктук ичүү азыр эки эсе маанилүү. Күнүмдүк суу ичүү нормасын толтурууну унутпаңыз.','Kas veepudel on käepärast? 💧','Piisav vedelikutarbimine on nüüd kaks korda olulisem. Ära unusta oma igapäevast veenormi täita.'),
('29fd118b-28ca-4783-a20d-0dfe1f9257be'::uuid,'Келечегиңизди пландап жатабыз 💭','Кош бойлуулук альбомуңузга биринчи "башталыш" сүрөтүн жүктөөгө даярсызбы?','Planeerime sinu kaunist tulevikku 💭','Kas oled valmis oma raseduse albumisse esimese "alguse" foto üles laadima?'),
('e0c08939-6705-4af3-8c21-9e0d55be665b'::uuid,'Шшш... Мен уктап жатам 😴','Менин мээм ушунчалык тез өнүгүп жаткандыктан, мен көп убактымды уктоо менен өткөрөм. Сиз да эс алышыңыз керек, апа.','Ššš... ma magan 😴','Minu aju areneb nii uskumatult kiiresti, et veedan suure osa ajast magades. Puhka sina ka, emme.'),
('aa7e5901-964e-4a5b-a2e3-24bbf3210a04'::uuid,'Негиз түзүүдөбүз 🏗️','Денеңиз жаңы кереметке даярданууда, этек кириңиз аяктап калды. Фолий кислотасы (B9) келечектеги балаңыздын дени сак өнүгүүсү үчүн абдан маанилүү. Биздин "Тамактануу" бөлүмүндөгү бай менюну карап чыктыңызбы? 🥑','Paneme alustalasid paika 🏗️','Sinu keha valmistub uueks imeks ja menstruatsioon on lõppemas. Foolhape (B9) on sinu tulevase beebi tervislikuks arenguks hädavajalik. Kas oled juba uurinud meie toitumise sektsiooni rikkalikke menüüvalikuid? 🥑'),
('9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2'::uuid,'Таттуу уйкуңузду баалаңыз 😴','Энергияңызды үнөмдөөгө убакыт келди! Уйкусуз түндөр келгенге чейин, күнүнө жок дегенде 8 саат уктоого аракет кылыңыз.','Naudi oma magusat und 😴','Aeg energiat säästa! Enne kui saabuvad unetud ööd, püüa magada vähemalt 8 tundi ööpäevas.'),
('e9c7a1d0-36f4-4892-aa41-43d1c6c5e948'::uuid,'Көк чөптөр менен күч алыңыз! 🥦','Ысманак менен брокколи жөн гана жашылча эмес, алар витаминдердин табигый булагы! Бүгүн тамагыңызга бир аз жашылдык кошууну унутпаңыз.','Lae end rohelisega! 🥦','Spinat ja brokkoli pole lihtsalt köögiviljad; need on looduslikud vitamiinipommid! Lisa täna kindlasti oma taldrikule midagi rohelist.'),
('95c500c4-d966-4eca-85e3-f43263957e13'::uuid,'Дарыгериңизди тандадыңызбы? 👩‍⚕️','Өзүңүз ишенген адистерди азыртан изилдей баштаңыз. "Дарыгерлер жана клиникалар" бөлүмүндөгү сын-пикирлерди окуп, тандооңузду тактасаңыз болот.','Kas oled arsti valinud? 👩‍⚕️','Alusta juba praegu spetsialistide uurimist, keda usaldad. Saad oma valikut täpsustada, lugedes arvamusi meie arstide ja kliinikute sektsioonis.'),
('572d6539-f881-4ec9-a3f9-b12c236e3b0d'::uuid,'Денеңиз белги берип жатабы? 🌡️','Овуляция жакындап калды! Дене табыңызга көз салыңыз; бул күндөр — бойго бүтүү үчүн эң ыңгуулу учур!','Kas su keha saadab signaale? 🌡️','Ovulatsioon on lähenemas! Jälgi oma kehatemperatuuri; need on sinu kõige viljakamad päevad!'),
('bd4effb9-20aa-4b2c-9886-28f1a8aa42f4'::uuid,'Жаңгактан даам татуу убактысы! 🥜','Чипсыларды таштап, жаңгактардан шам-шум этиңиз! Омега-3 сиз үчүн да, келечектеги балаңыз үчүн да өтө маанилүү.','Aeg pähkliseks maiuspalaks! 🥜','Jäta krõpsud vahele ja haara vahepalaks pähkleid! Oomega-3-rasvhapped on üliolulised nii sulle kui ka sinu tulevasele beebile.'),
('186bdc98-bb17-499f-bf7e-d9ff9eaa5492'::uuid,'Өзүңүзгө кам көрүүнү биринчи орунга коюңуз 💆‍♀️','Стресс гормондорунан арылалы! Бүгүн сүйүктүү тасмаңызды көрүңүз же жылуу душка түшүп эс алыңыз.','Sea enese eest hoolitsemine esikohale 💆‍♀️','Pagendame stressihormoonid! Vaata täna oma lemmikfilmi või naudi lõõgastavat sooja dušši.'),
('caca7263-c7a5-4d9a-92e5-c7d0658633f3'::uuid,'Кичинекей башталыштын керемети 🫧','Азырынча көзгө көрүнбөйт! Келечектеги балаңыз болгону бир клетка, бирок анын чоң пландары бар!','Pisikese alguse ime 🫧','Palja silmaga veel nähtamatu! Sinu tulevane beebi on alles üksik rakk, kuid tal on juba suured plaanid!'),
('c71b2b52-957c-4d0d-918e-02a81d0c792c'::uuid,'Сыйкырдуу көз ирмемди күтүп жатасызбы? ✨','Уруктануу адатта ушул күндөрү болот. Сиз аны сезбесеңиз да, кереметтүү процесс башталып калды.','Ootad oma maagilist hetke? ✨','Viljastumine toimub tavaliselt nendel päevadel. Isegi kui sa seda ei tunne, on imeline protsess juba alanud.'),
('00106d30-5d19-414e-a507-c025fa6d17d2'::uuid,'Протеин менен күчтөнүңүз! 🍳','Эртең мененки тамакка жумурткабы? Белок клеткалардын жаңылануусу үчүн абдан маанилүү! Тамагыңыз таттуу болсун!','Lae end valguga! 🍳','Muna hommikusöögiks? Valgud on rakkude uuenemiseks hädavajalikud! Head isu!'),
('ff01c295-45c4-493a-ab43-5a6c543c478d'::uuid,'Сергитерлик сейилдөөгө кандай карайсыз? 👟','Таза аба маанайыңызды көтөрөрү шексиз! "Көнүгүүлөр" бөлүмүндөгү жеңил сейилдөө программасын карап көрүңүз.','Kuidas oleks värskendava jalutuskäiguga? 👟','Värske õhk turgutab kindlasti tuju! Heida pilk meie treeningute sektsioonis olevasse rahuliku kõnni programmi.'),
('6f8a4fbb-f3ef-409d-a1cc-75f70eff873b'::uuid,'Жүрөгүңүз айланып жатабы? 🤢','Эртең менен өзүңүздү начар сезип жатасызбы? Зензебил чайы же лимон кошулган суу жардам бериши мүмкүн. Ач карын жүрбөгөнгө аракет кылыңыз!','Kas on iiveldus? 🤢','Kas hommikud tunduvad rasked? Ingveritee või sidrunivesi võivad leevendust pakkuda. Püüa vältida tühja kõhtu!'),
('113c2ffd-412e-42e7-9340-2d6ba48c6d05'::uuid,'Энергияңыз кайтып жатканын сезип жатасызбы? 🔋','Бүгүн өзүңүздү кандай сезип жатасыз? "Симптомдорду көзөмөлдөө" бөлүмүнө белгилеп коюңуз! ✅','Tunned, kuidas energia naaseb? 🔋','Kuidas sa end täna tunned? Tee märge oma sümptomite jälgijasse! ✅'),
('d2eb5bbc-3775-4f57-aa9a-087ca149ab57'::uuid,'Чоң өзгөрүүлөр жүрүп жатат! 🚧','Балаңыздын мээси жана жүлүндөрү өнүгүп жатат! Фолий кислотасын ичүүнү улантыңыз.','Suur areng on käimas! 🚧','Sinu beebi aju ja seljaaju arenevad! Jätka hoolikalt foolhappe võtmist.'),
('90d7f6db-e46c-4431-84a4-08c7cb36dff8'::uuid,'Эртең мененки жүрөк айлануу кыйнап жатабы? 🤢','Төшөгүңүздүн жанына бир аз туздуу крекер коюп, тура электе бир нечесин жеп көрүңүз. Аз-аздан бат-баттан тамактануу кандагы канттын деңгээлин туруктуу кармоого жардам берет.','Hommikune iiveldus kimbutab? 🤢','Hoia voodi kõrval soolaseid küpsiseid ja söö paar tükki juba enne voodist tõusmist. Väikeste ja sagedaste toidukordade söömine aitab hoida veresuhkru tasakaalus.'),
('ee028003-7c13-49d6-a074-6279f0809a0e'::uuid,'Дүк-дүк... Угуп жатасызбы? 💓','Менин жүрөгүм сого баштады! Бул кичинекей "кыймылдаткычты" угууга даярсызбы? Календарга биринчи УЗИге баруу күнүн белгилөөнү унутпаңыз! 🖊️','Tuks-tuks... Kas kuuled seda? 💓','Minu süda on hakanud lööma! Kas oled põnevil, et seda väikest "mootorit" kuulda? Ära unusta oma esimest ultraheli aega kalendrisse märkida! 🖊️'),
('b0910e0e-cc92-44f5-8046-b09a58173a6b'::uuid,'Расмий тастыктоо убактысы! ✅','Эгер али бара элек болсоңуз, дарыгердин биринчи кабыл алуусуна жазылууну сунуштайбыз. Ылайыктуу варианттарды "Дарыгерлер" бөлүмүнөн таба аласыз.','Aeg ametlikuks kinnituseks! ✅','Kui sa pole seda veel teinud, on hea mõte broneerida oma esimene arstiaeg. Sobivad valikud leiad meie arstide sektsioonist.'),
('55b6e494-7a56-4309-af7f-8fd6e4c2696c'::uuid,'Биринчи жүрөк кагышы 💓','Сиз али уга элек болсоңуз да, ал кичинекей жүрөк сого баштады — мүнөтүнө 100дөн ашык жолу!','Esimesed südamelöögid 💓','Kuigi sa seda veel kuulda ei saa, on see pisike süda juba lööma hakanud – üle 100 korra minutis!'),
('4268dd91-2b9a-483a-aa93-8f2b7d7809a9'::uuid,'Кош бойлуулар үчүн витаминди унуттуңузбу? 😬','Фолий кислотасы — менин келечектеги омурткамдын пайдубалы! "Дары-дармектерди эскертүү" бөлүмүн текшериңиз — бүгүнкү дозаны ичтиңизби? ✅','Unustasid rasedate vitamiinid? 😬','Foolhape on minu tulevase selgroo vundament! Kontrolli oma ravimite meeldetuletust – kas oled tänase annuse võtnud? ✅'),
('45bd19ab-fec8-4848-87b2-8afc6fee3b1d'::uuid,'Кан аралаш бөлүнүү нормалдуубу? 🩸','Кабатыр болбоңуз, бул имплантациялык кан кетүү болушу мүмкүн. Эгер күмөн санасаңыз же тынчсыздансаңыз, кеңеш алуу үчүн "Дарыгерлер" бөлүмүн караңыз.','Kas määrimine on normaalne? 🩸','Ära muretse, see võib olla pesastumisverejooks. Kui oled ebakindel või mures, vaata juhiste saamiseks arstide sektsiooni.'),
('549f62ec-94b7-42af-8ae8-87ad5504509a'::uuid,'Темир жетиштүүбү? 🥩','Кан көлөмүңүз көбөйөт. Анемиянын алдын алуу үчүн кызыл эт же жасмык сыяктуу темирге бай азыктарды көбүрөөк колдонуңуз!','Kas saad piisavalt rauda? 🥩','Sinu veremaht suureneb. Turguta end rauaga, süües punast liha või läätsesid, et aidata aneemiat ennetada!'),
('3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6'::uuid,'Толкундануу менен күтүү... 🧘‍♀️','Этек кириңиз келе турган убак жакындап калды. Стресстен арылуу үчүн «Ак ызы-чуу» (White Noise) бөлүмүн угуп көрүңүз.','Elevil ootusärevus... 🧘‍♀️','Menstruatsioon on lähenemas. Stressi leevendamiseks proovi kuulata jaotist „Valge müra“.'),
('648746b5-1de4-41ff-8fb8-976e17ef9c18'::uuid,'Календарыңызды текшердиңизби? 🗓️','Эгер этек кириңиз кечигип жатса, балким, кош бойлуулук тестин жасай турган убак келгендир? Кубанычтуу кабарыңыз менен биз менен бөлүшүңүз!','Kontrollisid kalendrit? 🗓️','Kui päevad hilinevad, siis ehk on aeg teha rasedustest? Jaga meiega oma imelist uudist!'),
('df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9'::uuid,'Күнжүт данындай чоңдукта! 🌱','Сиздин бөбөгүңүз азыр расмий түрдө эмбрион деп аталат! Ал абдан тез өсүп жатат, сиз дагы аны менен кошо өзгөрүүдөсүз.','Seesamiseemne suurune! 🌱','Sinu pisikest kutsutakse nüüd ametlikult embrüoks! Ta kasvab nii kiiresti ja sina muutud koos temaga.'),
('1466cb19-fd27-4f75-a79c-d709e1623239'::uuid,'Апийим данындай кичинекей 🌱','Бөбөгүңүз жатындагы өз ордуна жайгашып жатат. Ал азырынча кичинекей болсо да, кичинекей жүрөгү кагып баштады.','Pisike nagu mooniseeme 🌱','Sinu beebi sätib end juba emakas mugavalt sisse. Kuigi ta on imetilluke, hakkab tema süda juba moodustuma.'),
('b119316e-3eaf-473d-92b5-cf9d282e6e05'::uuid,'Брокколи гүлүндөй чоңдукта! 🥦','Менин май катмарым көбөйүп, колдорум менен буттарым толо баштады.','Brokoliõisiku suurune! 🥦','Minu rasvakiht kasvab ning käed ja jalad muutuvad pontsakamaks.'),
('ad5cb90c-5ee0-41f0-8e3f-90512dcf6636'::uuid,'Сиздин уникалдуу ДНК топтомуңуз даяр! 🧬','Бөбөгүңүздүн көзүнүн түсү, чачы жана ал тургай жынысы да аныкталып калды! Ал кимге окшош болот деп ойлойсуз?','Sinu unikaalne DNA-pakett on valmis! 🧬','Sinu beebi silmavärv, juuksed ja isegi sugu on juba paigas! Kelle sarnane ta sinu arvates tuleb?'),
('77a7a0c4-cbc4-4060-9824-f3657b9506c0'::uuid,'Мөмө-жемиштерден ырахат алыңыз! 🍓','Малинабы же кулпунайбы? Антиоксидантка бай бул мөмө-жемиштер иммунитетиңизди көтөрүүгө жардам берет.','Naudi marjade plahvatust! 🍓','Vaarikad või maasikad? Need antioksüdantidest pakatavad marjad aitavad tugevdada sinu immuunsust.'),
('5b28b973-6a08-480a-befc-a57bb7fa577b'::uuid,'Темир ичүү убактысы! 🏗️','Мен кызыл кан клеткаларын жасоо менен алекмин. Мага уй этин, шпинат же жасмык жеп жардам бериңиз!','Aeg raua jaoks! 🏗️','Olen ametis punaste vereliblede tootmisega. Aita mind ja söö veiseliha, spinatit või läätsesid!'),
('c13826a2-03b2-4512-bcfb-084ebb8c2f13'::uuid,'Тынч революция жүрүп жатат! 🤫','Уруктанган жумуртка жатыныңызга жайгашып жатат. Азырынча сезбесеңиз да, укмуштуудай саякат башталды!','Vaikne revolutsioon on käimas! 🤫','Viljastatud munarakk kinnitub emakasse. Isegi kui sa seda veel ei tunne, on uskumatu teekond alanud!'),
('fb1313b6-50fc-44e5-80b6-0c243b450b62'::uuid,'Сөөктөр бекем болушу үчүн кальций 🥛','Сүт, йогурт же сыр? Бүгүн сүт азыктарын жегенди унутпаңыз – бул бөбөгүңүздүн скелетинин өнүгүшү үчүн абдан маанилүү!','Kaltsium tugevate luude jaoks 🥛','Piim, jogurt või juust? Ära unusta täna piimatooteid – need on beebi luustiku arenguks üliolulised!'),
('33a29a12-915d-4926-a3e0-77d719ad233b'::uuid,'Өтө чарчап жатасызбы? Себеби бар! 🥱','Прогестерон гормонуңуздун деңгээли жогорулоодо. Эгер уйкуңуз келип жатса, өзүңүздү мажбурлабаңыз – денеңизди угуп, эс алыңыз!','Tunned end kurnatuna? Selleks on põhjus! 🥱','Sinu progesterooni tase tõuseb. Kui voodi sind kutsub, ära ütle ei – kuula oma keha ja puhka!'),
('e7c343f8-73b3-41d3-a74d-ee9ee11dc752'::uuid,'Лимондуу суунун сыйкыры 🍋','Сууну жетиштүү ичүү жүрөк айланууну азайтып, өзүңүздү жакшы сезүүгө жардам берет. Суусуздануу көп учурда баш ооруга алып келет!','Sidrunivee maagia 🍋','Piisav vedelikutarbimine aitab vähendada iiveldust ja hoiab enesetunde heana. Vedelikupuudus võib sageli põhjustada peavalu!'),
('06ad8151-63c5-48be-b794-51e51402550d'::uuid,'Алсырап жатасызбы? 🔋','Энергияңыз тез эле түгөнүп калышы мүмкүн. Түштөн кийин кыска убакытка уктап алуу сизге абдан пайдалуу болот.','Tunned end tühjana? 🔋','Sinu energia võib kiiresti raugeda. Lühike uinak pärastlõunal tuleb sulle ainult kasuks.'),
('ae668457-885f-4308-8392-39228dd44060'::uuid,'Мага бассейн керек! 🏊‍♀️','Сиз мен сүзүп жүргөн сууну (амниотикалык суюктук) жаратып жатасыз, апа. Суу ичүү графигиңизди текшериңиз. Бир стакан суу ичтиңизби? ✅','Vajan basseini! 🏊‍♀️','Sa lood vett, milles ma ujun (lootevesi), emme. Kontrolli oma veejälgijat. Kas jõid juba klaasi vett? ✅'),
('d2d789ff-23ab-49d2-829b-2a59a12e57ec'::uuid,'Эмоционалдык сезимдердин өйдө-ылдый болушу 🎢','Бир мүнөт күлүп, кийинки мүнөттө ыйлап жатасызбы... Гормондоруңуз сизди жинди кылган жок, алар жөн гана талыкпай иштеп жатышат!','Emotsionaalsed ameerika mäed 🎢','Ühel hetkel naerad, teisel nutad... Hormoonid ei tee sind hulluks, nad lihtsalt teevad kõvasti tööd!'),
('b80da43f-4fa0-465f-a1f5-d415c59577d5'::uuid,'Жыттарга сезимтал болуп жатасызбы? 👃','Өзүңүзгө жакпаган тамактарды жегенге мажбурлабаңыз. Башка варианттарды көрүү үчүн «Тамактануу» бөлүмүн караңыз.','Kas oled lõhnade suhtes tundlik? 👃','Ära sunni end sööma toite, mis sulle ei maitse. Vaata alternatiivide leidmiseks jaotist „Toitumine“.'),
('e7025bb0-45af-4595-8380-1e2af3adb2b9'::uuid,'Мээнин өнүгүүсү тез жүрүүдө! 🧠','Нерв түтүгү жабылып жатат. Фолий кислотасын ичүүнү токтотпоңуз – келечектеги генийиңиздин пайдубалы түптөлүп жатат!','Aju areng on täies hoos! 🧠','Neuraaltoru sulgub. Ära lõpeta foolhappe võtmist – paned aluse oma tulevasele geeniusele!'),
('1af4d57c-0075-4fda-8ae2-57d6f0df3dd7'::uuid,'Имбирь чайы жардамга келет! 🍵','Дагы эле жүрөгүңүз айланып жатабы? Имбирь ашказаныңызды тынчтандырууга жардам берет. «Тамактануу» бөлүмүнөн пайдалуу рецепттерди карап көрүңүз.','Ingveritee appi! 🍵','Võitled ikka iiveldusega? Ingver võib aidata kõhtu rahustada. Vaata jaotisest „Toitumine“ mõningaid lohutavaid retsepte.'),
('ee6d0fe8-1439-46ca-a99d-71bece3db7ff'::uuid,'Чарчоо чегине жеттиби? 😴','Денеңиз энергия фабрикасы сыяктуу иштеп жатат! Түштөн кийин кыска убакытка уктап алуу – болочок эне катары сиздин укугуңуз!','Kas väsimus on haripunktis? 😴','Sinu keha töötab nagu energiatehas! Lühike pärastlõunane uinak on sinu kui tulevase ema õigus!'),
('6a854983-edba-4550-9294-f82d79978af6'::uuid,'Сиздин кичинекей буурчагыңыз! 🟢','Бою болжол менен 6 мм! Колдорум менен буттарым кичинекей бүчүр сыяктуу пайда боло баштады. Кандай гана кичинекей сүзгүч!','Sinu väike hernetera! 🟢','Umbes 6 mm! Minu käed ja jalad hakkavad ilmuma pisikeste pungadena. Milline väike ujuja!'),
('68d813b6-47ae-4b82-ac7f-506d3dacf437'::uuid,'Жарыш унаасындай тез кыймылдап жатат! 🏎️','Анын жүрөгү мүнөтүнө 100-160 жолу кагат – сиздикинен эки эсе тез! Бул үн сиз үчүн эң жагымдуу музыкадай болот.','Liigun nagu võidusõiduauto! 🏎️','Tema süda lööb 100–160 korda minutis – kaks korda kiiremini kui sinul! See heli on kui muusika sinu kõrvadele.'),
('20943f1e-d4df-412e-9bff-ad93646d91c9'::uuid,'Бир аз жай кыймылдоо убактысы 🧘‍♀️','Денеңизди кыймылдаткыңыз келип жатабы? «Көнүгүүлөр» бөлүмүнөн сизге эмне ылайыктуу экенин карап көрөлү!','Aeg õrnaks liikumiseks 🧘‍♀️','Tunned, et tahaksid end liigutada? Uurime koos jaotisest „Harjutused“, mis sulle sobiks!'),
('2781a73f-51c3-4a91-8e1e-4ee828c3f885'::uuid,'Ич катууну жеңиңиз! 🏃‍♀️','Дары-дармектин ордуна көп суу ичип, кара өрүк жана киви жеңиз.','Võitle kõhukinnisusega! 🏃‍♀️','Ravimite asemel joo rohkelt vett ning söö ploome ja kiivit.'),
('1eea9abf-8e8e-49f8-aca7-b449e73948c5'::uuid,'Кандагы канттын деңгээлин туруктуу кармаңыз! 📉','Ашказаныңыз бош калганда жүрөк айлануу күчөшү мүмкүн. Сумкаңызда дайыма крекер же кургатылган жемиштерди алып жүрүңүз.','Hoia veresuhkur stabiilsena! 📉','Iiveldus võib süveneda, kui kõht on tühi. Hoia kotis alati küpsiseid või kuivatatud puuvilju.'),
('83b88cf3-52f6-408b-8331-beef50dfe19f'::uuid,'Дааратканага тез-тез каттап жатасызбы? 🚻','Бөйрөгүңүз ашыкча иштеп жаткандыктан, дааратканага тез-тез баруу – бул кадыресе көрүнүш. Бирок суу ичүүнү азайтпаңыз, тескерисинче, көбүрөөк ичиңиз!','Sagedased tualetipausid? 🚻','Sage tualetis käimine on täiesti normaalne, sest neerud töötavad ületunde. Kuid ära vähenda vee joomist, joo hoopis rohkem!'),
('f2d72cc5-1dfe-472f-b0dd-cab7471cb46d'::uuid,'Жүрөгүңүз айланып жатабы? Абдан өкүнүчтүү! 🥺','Гормондорум кече уюштуруп жатышат, күнөө менде! Сизди ыңгайсыз абалга салып жатамбы? Балким, бир аз туздуу крекер жеп көрөсүзбү? 🍪','Kas on iiveldus? Nii kahju! 🥺','Minu hormoonid peavad pidu ja mina olen selles süüdi! Kas ma tekitan sulle ebamugavust? Kuidas oleks soolaste küpsistega? 🍪'),
('4395d8a1-8cd6-4561-9d88-e944bb78801d'::uuid,'Бүгүн балык күнү! 🐟','Курамында сымап жок балыктарды тандаңыз. Омега-3 мээнин өнүгүшү үчүн абдан зарыл.','Täna on kalapäev! 🐟','Vali elavhõbedavaba kala. Omega-3 on aju arenguks asendamatu.'),
('d24fadf2-1d24-4001-b4cd-1006ba1390b4'::uuid,'Ымыркайдын бети калыптанып жатат! 👀','Көзү, мурду жана кулактары калыптанып жатат. Азырынча алар кара тактардай көрүнөт, бирок кичинекей жүзү калыптанып келе жатат.','Beebi nägu hakkab kujunema! 👀','Tema silmad, nina ja kõrvad moodustuvad. Praegu näevad need välja nagu tumedad täpid, kuid tema väike nägu hakkab kuju võtma.'),
('98979663-767c-4d48-9b7b-786f81533442'::uuid,'Витамин B6 кайда? 🍌','Банан, авокадо же тоок эти... Булар жүрөк айланууну басаңдатууга жардам берет.','Kus on B6-vitamiin? 🍌','Banaanid, avokaadod või kana... Need võivad aidata iiveldust leevendada.'),
('b82ae448-8da6-41fb-9588-70bee70788e8'::uuid,'Жашыруун бий кечеси! 💃','Азырынча сезбесеңиз да, ал кыймылдап жатат. Анын алгачкы кыймылдары кичинекей чыйрыкка окшош.','Salajane tantsupidu! 💃','Isegi kui sa seda veel ei tunne, liigub ta juba. Tema esimesed liigutused on kui pisikesed tõmblused.'),
('32c29664-93a4-4e94-bb42-a62ada8dcf6a'::uuid,'Каалоолор: Туздалган бадыраңбы же шоколадбы? 🥒','Кызыктай тамактарды каалоо – бул кадыресе көрүнүш. Бирок канттан сак болуңуз! Диетаңыз үчүн дени сак альтернативалар бар.','Isu: hapukurgid või šokolaad? 🥒','Kummalised isud on normaalsed. Kuid jälgi suhkrut! Sinu toitumises on tervislikke alternatiive.'),
('6ff4b2b8-64a6-4583-a2a6-a17dcd93d858'::uuid,'Кофеинди азайтып жатасызбы? ☕','Күнүнө 1 чыныдан ашык ичпеңиз. Кофеини жок же чөп чайларын ичип көрүңүз.','Vähendad kofeiini tarbimist? ☕','Piirdu maksimaalselt 1 tassiga päevas. Proovi kofeiinivaba kohvi või taimeteesid.'),
('75ccffd0-f3f8-457f-9109-f503ba1c9c27'::uuid,'Ымыркайыңыз кубанычтуу бийлеп жатат! 🕺','Колдору менен буттарын кыймылдатып жатат. Бөбөгүңүз жатыныңызда акробатика жасап жатат, бирок сиз аны азырынча сезе элексиз.','Sinu beebi teeb rõõmutantsu! 🕺','Tema käed ja jalad painduvad. Sinu beebi teeb emakas akrobaatikat, kuid sina ei saa seda veel tunda.'),
('471326ec-b4e0-411d-b639-63ddc151da1f'::uuid,'Аш болумдуу жашылча шорпосуна кандай карайсыз? 🥣','Эгер ашказаныңыз оор тамактарды көтөрө албай жатса, жеңил шорпо ичип көрүңүз. Бул витамин да, суюктук да!','Kuidas oleks toitva köögiviljasupiga? 🥣','Kui su kõht ei kannata raskeid toite, proovi kerget suppi. See annab nii vitamiine kui ka vedelikku!'),
('3efe947d-4b4b-4c7f-9958-16d89faba8db'::uuid,'Атасын да тартыңыз! 🗣️','Бул жөн гана сиздин саякатыңыз эмес. Биринчи УЗИ сүрөтүн чогуу карап, келечектеги пландарыңыз жөнүндө сүйлөшүңүз.','Kaasa isa! 🗣️','See pole ainult sinu teekond. Vaadake koos esimest ultrahelipilti ja rääkige oma tulevikuplaanidest.'),
('5efd10b2-de1a-4b0e-b6df-24a9fc762806'::uuid,'Жайлуу май катмары топтолууда! 🧸','Наристеңиз жылуу жүрүү үчүн май катмарын топтой баштады.','Kogun hubast rasvakihti! 🧸','Sinu beebi hakkab soojas püsimiseks rasvakihti koguma.'),
('410a1e31-b41d-4130-8526-c1b0f94d7fcb'::uuid,'Тиштерим кычышкан жок... азырынча! 😬','Сүт, йогурт, сыр... Булар бүгүнкү рационуңузда барбы? 🥛','Mu igemed ei sügele... veel! 😬','Piim, jogurt, juust... Kas need on täna sinu toidunimekirjas? 🥛'),
('a94e0a87-fa0f-44bc-96ea-31a14e8e1954'::uuid,'Өспүрүм куракпы? 😳','Бетке бүдүрлөр чыгышы мүмкүн. Мунун баары гормондордон! Териңизди таза кармаңыз, бирок күчтүү дары-дармектерден алыс болуңуз.','Teismelise režiim? 😳','Võid märgata näol mõningaid vistrikke. Süüdista hormoone! Hoia nahk puhas, kuid väldi tugevatoimelisi ravimeid.'),
('bb01f67b-68b6-46f0-9ecd-af5b6f80b28b'::uuid,'Биринчи сүрөткө түшүү убактысы келдиби? 🤰','Курсагыңыздын биринчи сүрөтүн галереяга жүктөп коюңуз! ✨','Aeg meie esimeseks fotoks? 🤰','Laadi galeriisse üles oma esimene beebikõhu foto! ✨'),
('a8178689-8b83-4c18-aed1-047d8befc921'::uuid,'Ич катуу маселесиби? 🚽','Көп суу ичүү жана клетчаткага бай тамактар сиздин эң жакын жардамчыңыз. Киви жана кургатылган өрүк абдан жакшы жардам берет.','Hädas kõhukinnisusega? 🚽','Rohke vesi ja kiudainerikkad toidud on sinu sõbrad. Kiivi ja kuivatatud aprikoosid võivad teha imesid.'),
('54999531-d81c-49ad-a8e5-0a766a343a4f'::uuid,'Суунун деңгээли азайып баратат... 💧','Бул тунук, мол сууда сүзүү мага абдан жагат! Апа, менин ордума дагы бир стакан суу ичип коёсузбу? 🥺','Minu veetase langeb... 💧','Mulle lihtsalt meeldib selles selges ja külluslikus vees hõljuda! Kas saaksid minu jaoks ühe klaasi vett juurde juua, emme? 🥺'),
('6fc47392-9629-4d33-8e40-e40e2521230e'::uuid,'Бир аз кысылып жатасызбы? Ой! 😬','Салмагыңыз азырынча анча өзгөрө элек болсо да, мен өзүмдү үйдөгүдөй сезип жатам! Келиңиз, тар шымдарды чечип, ыңгайлуу кийимдерге өтөлү. 🤰','Tunned end veidi kokkusurutuna? Ups! 😬','Isegi kui sinu kaal pole veel palju muutunud, sätin end juba sisse! Viskame need kitsad püksid kõrvale ja paneme midagi mugavamat selga. 🤰'),
('9fae4e34-d2bb-467a-bd40-2f0853238a4e'::uuid,'Кычкыл же шоколад жегиңиз келип жатабы? 🍫','Тамактануу бөлүмүн карап көрүңүз! Бүгүн менюда кандай пайдалуу тамактар бар? 😋','Isutab hapu või šokolaadi järele? 🍫','Vaata jaotist „Toitumine“! Millised tervislikud valikud on täna menüüs? 😋'),
('c1f145fd-3d01-40af-8a31-7f261ae6105a'::uuid,'Даам сезүү жөндөмү өнүгүүдө! 👅','Тилимде даам сезүүчү бүчүрлөр пайда болууда. Жакында сиз жеген тамактардын даамын мен да сезе баштайм!','Maitsmispungad arenevad! 👅','Minu keelele moodustuvad maitsemeeled. Varsti hakkan tundma nende toitude maitset, mida sina sööd!'),
('e6b9a24b-da46-4708-9e5b-b659c3de661e'::uuid,'Эт жегиңиз келбей жатабы? 🥩','Сизге белок керек! Эгер эт жей албасаңыз, аны жасмык, нокот же жаңгактар менен алмаштырыңыз.','Vastumeelsus liha suhtes? 🥩','Sa vajad valku! Kui sa ei saa liha süüa, asenda see läätsede, kikerherneste või pähklitega.'),
('44977c78-f7ae-4f0e-9e98-b634c325ef0b'::uuid,'Бюстгалтериңиз кысып жатабы? 👙','Эмчегиңиз чоңоюп, сезгич болуп баратат. Ыңгайлуу, зымсыз спорттук бюстгальтерлерге же кош бойлуулар үчүн атайын ич кийимдерге өтүүчү убакыт келди.','Kas rinnahoidja on kitsaks jäänud? 👙','Sinu rinnad kasvavad ja muutuvad tundlikumaks. On aeg vahetada need mugavate, traadita spordirinnahoidjate või rasedate pesu vastu.'),
('494e490f-741c-402a-90a1-087cb49feebd'::uuid,'Денеңизге суу керек! 💧','Суусуздануу баш ооруга алып келиши мүмкүн. Суу көзөмөлдөөчү бөлүмгө кирип, бир стакан суу ичиңиз! ✅','Sinu keha küsib vett! 💧','Vedelikupuudus võib põhjustada peavalu. Mine veejälgijasse ja joo klaas vett! ✅'),
('91f2c1e3-6e09-405e-873b-1c7871ae42d1'::uuid,'Наристеңиздин жүзү адамдыкындай болуп калды! 👶','Ал эми жүзүңүздөгү ошол белгилүү «кош бойлуулуктун нуру» жөнүндө эмне айтууга болот? ✨ Бул сулуулукту Галереяңызга түбөлүккө сактап калыңыз!','Sinu pisikesel on juba inimese nägu! 👶','Ja mis saab sellest kuulsast raseduse särast sinu näol? ✨ Jäädvusta see ilu oma galeriisse!'),
('6632cd55-3fc2-4b5a-99ae-1934d4d07a48'::uuid,'С витамининин булагы! 🍊','Апельсин, киви же болгар калемпири... Иммунитетиңизди болоттой бекем сактаңыз – оорубаңыз!','C-vitamiini sutsakas! 🍊','Apelsinid, kiivid või paprikad... Hoia oma immuunsüsteem tugevana – haigused ei tohi ligi pääseda!'),
('0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5'::uuid,'Бөйрөктөр күчөтүлгөн режимде иштеп жатат! 🚽','Бул укмуштуудай, бирок алар азыртан эле заара кылып жатышат! Алар амниотикалык суюктукту жутуп, кайра бөлүп чыгарышат. Цикл башталды!','Neerud töötavad ületundidega! 🚽','See on uskumatu, aga ta pissib juba! Ta neelab ja väljutab lootevett. Tsükkel on alanud!'),
('d77d400f-027c-4514-b287-ee1cd4aff422'::uuid,'Грейпфруттун көлөмүндөй! 🍊','Белиңиз жооноюп баратат окшойт. Сандар өзгөрдүбү? Салмак көзөмөлдөөчү бөлүмгө жазып коюңуз! 📈','Greibi suurune! 🍊','Sinu vööümbermõõt võib suureneda. Kas numbrid on muutunud? Märgi see kaalujälgijasse! 📈'),
('5d87369c-e5c4-4b67-b09a-fc38d7a668d6'::uuid,'Экинчи скринингден өтө турган убакыт келдиби? 🗓️','11-14 жума аралыгы абдан маанилүү. Даун синдромунун коркунучун текшерүү үчүн дарыгериңиз менен кеңешиңиз.','Kas on aeg kaksiktestiks? 🗓️','Periood 11.–14. nädalani on oluline. Räägi oma arstiga, et kontrollida Downi sündroomi riski.'),
('9b258cde-4bf1-416d-abf2-57eb7d09c208'::uuid,'Ачкасызбы же суусадыңызбы? 🤔','Кээде мээңиз сизди алдап коюшу мүмкүн. Алгач бир стакан суу ичиңиз. Эгер дагы деле ачка болсоңуз, анда чындап тамактануу убактысы келгендир!','Näljane või janune? 🤔','Mõnikord võib aju sulle vingerpussi mängida. Kõigepealt joo klaas vett. Kui oled ikka näljane, siis on tõesti aeg süüa!'),
('827f46df-37d3-4f5e-80af-9e3b8db96d01'::uuid,'Кош бойлуулар үчүн көнүгүүлөрдү жасай турган убакыт! 🤸','Алар азыртан эле муштумун түйүп, оозун ачып жатышат. Сиз сезбесеңиз да, ичиңизде чыныгы Олимпиада өтүп жатат!','Aeg rasedusaegseks võimlemiseks! 🤸','Ta juba surub käsi rusikasse ja avab suud. Isegi kui sa seda ei tunne, toimuvad sees tõelised olümpiamängud!'),
('b247c7cf-7ded-4d8a-b64f-d3854d3be583'::uuid,'Наристеңиз күн сайын акылдуу болуп баратат! 🧠','Йод мээнин өнүгүшү үчүн өтө маанилүү. Йоддолгон туз, балык же сүт азыктары рационуңузда барбы?','Sinu pisike muutub iga päevaga targemaks! 🧠','Jood on aju arenguks hädavajalik. Kas jodeeritud sool, kala või piimatooted on sinu menüüs?'),
('9dfe8f42-50e3-422f-b528-dfdbb8ba5b68'::uuid,'Мен чоюлуп жатам! 🤸','Кыймылдап турууну унутпаңыз, Апа. Көнүгүүлөр бөлүмүндөгү жеңил йога менен алектенсеңиз кандай болот?','Ma sirutan end! 🤸','Ära unusta end liigutada, emme. Kuidas oleks õrnade joogaharjutustega jaotisest „Treeningud“?'),
('6d2e668d-18e8-41a3-a260-749a9ad4112f'::uuid,'Кальцийди унутпаңыз! 🥛','Тиш бүчүрлөрү калыптанып жатат. Быштак, сыр же йогурт... булар алардын келечектеги жылмаюусу үчүн керек!','Ära unusta kaltsiumi! 🥛','Hambaalged moodustuvad. Kodujuust, tavaline juust või jogurt... need on vajalikud tema tulevase naeratuse jaoks!'),
('36af91e4-7cdc-478f-b431-003ca4f4075f'::uuid,'Баш оору тынчсыздандырып жатабы? 🤕','Дары ичүүгө шашпаңыз. Караңгы бөлмө, муздак компресс же жеңил массаж ооруну басууга жардам берет.','Kas peavalud kiusavad? 🤕','Ära kiirusta ravimite võtmisega. Pime tuba, külm kompress või õrn massaaž võivad pakkuda paremat leevendust.'),
('17a77385-a0f0-43f1-b604-ef36e1b9f457'::uuid,'Кан айланууңуз тездеп жатат! 🌊','Кандын көлөмү көбөйүп, жүрөгүңүз тез иштеп жатат. Бул системаны муздатуу үчүн суу өтө маанилүү. Башыңыз айланбашы үчүн суу ичүүнү унутпаңыз! ✅','Sinu vereringe kiireneb! 🌊','Sinu veremaht suureneb ja süda töötab kiiremini. Vesi on hädavajalik, et seda süsteemi jahutada. Ära unusta pearingluse vältimiseks vett juua! ✅'),
('75908864-8ad0-496c-8a26-f45ae3d7e742'::uuid,'Курулуш иштери жүрүүдө! 🏗️','Наристеңизге кальций керек! Тамактануу бөлүмүнөн сүт азыктарын карап көрүңүз. 🧀','Ehitustööd käivad! 🏗️','Sinu beebi vajab kaltsiumi! Vaata jaotisest „Toitumine“ piimatooteid. 🧀'),
('2ba98fa8-fbf2-4460-81c1-96e992eb2cff'::uuid,'Денедеги сызыктарга (стрияларга) ''жок'' деп айтыңыз! 🧴','Курсагыңыз азырынча билинбесе да, териңизди нымдап туруңуз. Бадам же кокос майы кычышууну басаңдатат.','Ütle venitusarmidele „ei“! 🧴','Isegi kui kõht pole veel näha, niisuta nahka. Mandli- või kookosõli võivad samuti sügelust leevendada.'),
('cbca369c-5e1a-4ee2-86f1-c37e9a851106'::uuid,'Сүйүнчү кабарды бөлүшө турган убакыт келдиби? 📢','Биринчи триместр дээрлик аяктады! Коркунучтар бир топ азайды. Сүйүнчү кабарыңызды досторуңуз менен бөлүшүүгө даярсызбы?','Aeg jagada suuri uudiseid? 📢','Esimene trimester on peaaegu läbi! Risk on märgatavalt vähenenud. Kas oled valmis oma imelist uudist sõpradega jagama?'),
('c3c5cda3-e24a-4bf6-8134-243e683db4d1'::uuid,'Сөөктөр бекемделип жатат! 🦴','Жумшак кемирчектер сөөккө айланып баратат. Наристеңиздин бекем өсүшү үчүн кальций запасын толуктап туруңуз!','Luud tugevnevad! 🦴','Pehmed kõhred muutuvad luudeks. Täienda oma kaltsiumivarusid, et aidata oma pisikesel tugevaks kasvada!'),
('0c81e884-eb3b-459e-9e4c-250ee35d9884'::uuid,'Наристеңиздин дүйнөсү — бул океан! 🌊','Амниотикалык суюктук жаңыланып турат. Наристеңиз таза бассейнде сүзүшү үчүн көп суу ичүүнү унутпаңыз.','Sinu beebi maailm on ookean! 🌊','Lootevesi uueneb. Ära unusta juua rohkelt vett, et beebi saaks ujuda puhtas basseinis.'),
('5b178828-ade2-47ab-8de7-afb567ca7a86'::uuid,'Курсагыңыз кычышып жатабы? 🌵','Курсагыңыз чоңойгон сайын теринин кычышуусу кадыресе көрүнүш. Жеңилдетүү үчүн бадам майын же созулууга каршы атайын крем сүйкөп көрүңүз.','Kas kõhuke sügeleb? 🌵','Sügelev nahk on tavaline, kui kõht kasvab ja venib. Proovi leevenduse leidmiseks määrida mandliõli või spetsiaalset venitusarmide kreemi.'),
('a2d117f1-96df-4258-ab55-9a8d07073a66'::uuid,'Сага Апа деп айтам... 🥺','Үн байламталарым калыптанып жатат! Азырынча унчукпай турам, бирок мени биринчи жолу чакыра турган күнүңүздү кыялданып жатасызбы? Анткени мен кыялданып жатам...','Hakkan sind emmeks kutsuma... 🥺','Minu häälepaelad moodustuvad! Olen praegu vait, aga kas unistad päevast, mil kuulen sind esimest korda kutsumas? Sest mina küll unistan...'),
('2743aaf7-db86-4143-a5f6-a342a96beb63'::uuid,'Клетчаткага бай азыктар — сиздин жардамчыңыз! 🌾','Тамак сиңирүүнү жакшыртуу үчүн сулу, жашылча жана жемиштерге басым жасаңыз. Тамактануу бөлүмүнөн даамдуу салаттарды таба аласыз.','Kiudainerikkad toidud on su parimad sõbrad! 🌾','Seedimise parandamiseks eelista kaerahelbeid, köögivilju ja puuvilju. Jaotisest „Toitumine“ leiad maitsvaid salateid.'),
('0aec0374-a2a9-4f72-92ad-01577161b993'::uuid,'Оор нерселерди көтөрүп жатасызбы? Этият болуңуз! 🏋️‍♀️','Бөбөгүңүз май катмарын топтоп, сөөктөрү катууланууда. Биз тез салмак кошуп жатабыз!','Tõstad raskusi? Ole ettevaatlik! 🏋️‍♀️','Sinu beebi kogub juba rasvakihti ja tema luustik tugevneb. Võtame kiiresti kaalus juurde!'),
('0e8f121b-aec8-4bf1-b771-2456d0bdda0c'::uuid,'Азык заттардын агымы көбөйүүдө!','Бүгүн кандай пайдалуу тамактардан даам таттыңыз? Тамактануу күндөлүгүңүздү текшериңиз! 🥦','Toitainete vool on tõusuteel!','Milliseid tervislikke toite sa täna nautisid? Kontrolli oma toitumispäevikut! 🥦'),
('e5a543f3-7d41-4d55-8690-ab14ba108363'::uuid,'Ал бармагын соруп жатат! 👍','УЗИ учурунда бөбөгүңүздүн бармагын соруп жатканын көрүп калышыңыз мүмкүн! Бул анын төрөлгөндөн кийинки соруу рефлексине даярдыгы.','Ta imeb pöialt! 👍','Võid ultrahelis näha, kuidas beebi pöialt imeb! See on harjutus imemisrefleksi jaoks pärast sündi.'),
('1b07a663-2dbb-41a5-b9a0-2b4b252d015a'::uuid,'Сууда сүзүү сизге жагып жатабы? 🏊‍♀️','Бөбөгүңүз суюктукта жашайт. Амниотикалык суюктук таза жана жетиштүү болушу үчүн күн бою сууну көп ичишиңиз керек.','Naudid ujumist? 🏊‍♀️','Sinu beebi elab lootevees. Et lootevesi püsiks puhas ja seda oleks piisavalt, joo päeva jooksul rohkelt vett.'),
('4e185ebb-b0f4-4552-9a03-4a4c79c95d4f'::uuid,'Сүйлөшүңүз! 🗣️','Бөбөгүңүз сиздин үнүңүздү жана жүрөгүңүздүн согушун даана уга алат. Ага бешик ырын ырдап баштаңыз – бул абдан тынчтандырат. 🎶','Räägi minuga! 🗣️','Sinu beebi kuuleb juba selgelt sinu häält ja südamelööke. Hakka talle hällilaule laulma – see on uskumatult rahustav. 🎶'),
('1228f5ed-c94b-45f8-bf5f-7e475683d6ed'::uuid,'Сиз темирдей бекем айымсыз! 🦸‍♀️','Башыңыз айланбашы үчүн кызыл эт же жасмык жеңиз. Рецепттерди «Тамактануу» бөлүмүнөн таба аласыз.','Sa oled tõeline raudne leedi! 🦸‍♀️','Peapöörituse vältimiseks söö punast liha või läätsesid. Retsepte leiad toitumise jaotisest.'),
('f99f033a-c9d9-464f-8a73-afdf2f8530ec'::uuid,'Тиш этиңиз канап жатабы? 😬','Гормондор тиштин этин сезгич кылып коюшу мүмкүн. Жумшак тиш щеткасын колдонуңуз жана туздуу суу менен чайкаңыз.','Kas su igemed veritsevad? 😬','Hormoonid võivad muuta igemed tundlikuks. Kasuta pehmet hambaharja ja loputa soolveega.'),
('5b358e1c-fd56-41ad-b947-12dea0b15c36'::uuid,'Сени угуп жатам, Апа! 👂','Анын кулагындагы сөөктөр катууланууда. Ал сиздин үнүңүздүн тембрин, күлкүңүздү жана жүрөгүңүздүн согушун тааный алат.','Ma kuulen sind, emme! 👂','Kõrvade luud tugevnevad. Ta tunneb juba ära sinu hääletooni, naeru ja südamelöögid.'),
('e95b0195-5d3f-434c-9f11-c74aa50f4ba5'::uuid,'Наристенин сөөктөрү бекемделип жатат! 🦴','Бөбөгүңүз сиздин кальций запасыңызды түгөтпөшү үчүн сүт, йогурт же бадам жеп туруңуз.','Beebi luud tugevnevad! 🦴','Söö piima, jogurtit või mandleid, et beebi ei ammendaks sinu kaltsiumivarusid.'),
('22f8517a-e978-4689-beff-108150f23b01'::uuid,'Сол капталга жатууну унутпаңыз! 🛌','Чалкаңыздан жатуу кан айланууну кыйындатышы мүмкүн. Сол капталыңызга жатуу сизге да, бөбөгүңүзгө да көбүрөөк кычкылтек берет.','Pea meeles magada vasakul küljel! 🛌','Selili magamine võib raskendada vereringet. Vasakul küljel lamamine tagab nii sulle kui ka beebile rohkem hapnikku.'),
('bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea'::uuid,'Жаңгактын күчү! 🐿️','Омега-3 мээнин өнүгүүсү үчүн өтө маанилүү. Жаныңызда жаңгак алып жүрүңүз: ал сизди ток кармап, бөбөгүңүздүн акыл-эсин өстүрөт.','Pähklite vägi! 🐿️','Oomega-3 on aju arenguks ülioluline. Hoia pähkleid kotis: need hoiavad kõhu täis ja toidavad beebi intelligentsust.'),
('6b4229bd-ff86-4124-a6db-5ad3cc3444fe'::uuid,'Алтын триместр башталды! ✨','Куттуктайбыз! Экинчи триместрге өттүңүз. Энергияңыз көбөйүп, тобокелдиктер азаят. Эми кош бойлуулугуңуздан ырахат ала турган убак!','Kuldne trimester algab! ✨','Palju õnne! Oled jõudnud teise trimestrisse. Sinu energiatase tõuseb ja riskid vähenevad. Nüüd on aeg rasedust nautida!'),
('0e5bf60f-0c98-4770-8559-a9df3a31089c'::uuid,'Энергияңыз азайып жатабы? Күч топтоо убактысы! 💥','Бөбөгүңүз тез өсүп жатат. Кызыл эт, жумуртка же буурчак өсүмдүктөрү... Темир жана белок запасыңызды толуктоону унутпаңыз.','Energiat on vähe? Aeg turgutuseks! 💥','Sinu beebi kasvab kiiresti. Punane liha, munad või kaunviljad... Ära unusta oma raua- ja valguvarusid täiendada.'),
('f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed'::uuid,'Лимондун көлөмүндөй! 🍋','Бою болжол менен 7-8 см! Ал башын буруп, кабагын түйө алат. Анын бет булчуңдары өнүгүүдө!','Sidruni suurune! 🍋','Umbes 7-8 cm! Ta oskab juba pead pöörata ja kulmu kortsutada. Tema miimika areneb!'),
('1a084eb2-2d29-44b6-a691-ad102b5c44de'::uuid,'Кийим шкафыңызды текшере турган убакыт келди! 👗','Шымдын топчусу илинбей жатабы? Тар шымдарды унутуңуз. Табигый кездемеден тигилген кенен, ыңгайлуу кийимдерге өтүңүз.','Aeg garderoob üle vaadata! 👗','Nööbid ei lähe kinni? Jäta kitsad püksid sinnapaika. Vali mugavad, looduslikest materjalidest avaramad riided.'),
('0b20c112-5b84-42c9-aa1a-637151b2cd33'::uuid,'Уулбу же кызбы? 🩷💙','Жыныс органдары толук калыптанып бүттү. УЗИде көрүү кыйын болсо да, бөбөгүңүз өзүнүн ким экенин билет! Сиздин оюңузча ал ким?','Poiss või tüdruk? 🩷💙','Suguelundid on täielikult moodustumas. Isegi kui ultrahelis on raske öelda, teab beebi juba, kes ta on! Mida sa arvad, kes ta on?'),
('000cbfe1-b7f7-4d1c-8e2e-4509f7ace829'::uuid,'Спа күнүнө убакыт келдиби? ✨','Бөбөктүн териси амниотикалык суюктукта бырышпашы үчүн атайын май менен капталган. Ал эми сизчи? Бүгүн өзүңүзгө бир аз убакыт бөлүңүз! 💆‍♀️','Kas on aeg spaapäevaks? ✨','Beebi nahk on kaetud spetsiaalse kreemiga, et vältida kortsude teket lootevees. Kuidas on lood sinuga? Võta täna aega iseendale! 💆‍♀️'),
('bec50930-1201-4fc9-8c19-535459114067'::uuid,'Мен жарыкты көрүп жатам! 💡','Көзү жумук болсо да, ал жарыкты сезе алат. Эгер курсагыңызга фонарик менен жарык кылсаңыз, ал бетин буруп кетиши мүмкүн.','Ma näen valgust! 💡','Isegi suletud silmalaugudega tunneb ta eredat valgust. Kui suunad taskulambi kõhule, võib ta pea ära pöörata.'),
('fcdb41b2-8b6a-4d75-be79-f72070d4756a'::uuid,'Негизги сыр эмнеде? 🔑','Унутчаактык – бул кадыресе көрүнүш. Мээңиз азыр алда канча маанилүү иш менен алек: адам жаратып жатат! Эсиңизде калтыруу үчүн тизме түзүп баштаңыз.','Mis on võti? 🔑','Unustamine on täiesti normaalne. Sinu aju on praegu hõivatud palju tähtsama ülesandega: inimese loomisega! Hakka asjade meelespidamiseks nimekirju koostama.'),
('2ac8ff81-e925-4d31-8ac2-6b55896aedfb'::uuid,'Бутуңуз тартышып жатабы? 🦵','Сизде магний жана кальций жетишсиз болушу мүмкүн. Банан, бадам же йогурт жеңиз. Сууну көп ичүүнү да унутпаңыз!','Kas jalakrambid kiusavad? 🦵','Sul võib olla magneesiumi- ja kaltsiumipuudus. Söö banaane, mandleid või jogurtit. Ära unusta ka rohkelt vett juua!'),
('937d5186-cb49-4a6c-a7a2-0e5731c4ae78'::uuid,'Алмуруттун көлөмүндөй! 🍐','Ал узарып, денеси тиктей баштады. Ал эми башын толук кармай алат! Ал өсүп жатат, сиз болсо гүлдөп жатасыз!','Umbes pirni suurune! 🍐','Ta pikeneb ja tema keha muutub püstisemaks. Ta suudab juba pead täielikult püsti hoida! Tema kasvab ja sina särad!'),
('77993f33-af63-4a22-9cb2-3af058c96f19'::uuid,'Курсагыңыз тартышып же чоюлуп жатабы? 😣','Кескин кыймылдардан качыңыз. Жылуу душ же жеңил массаж ыңгайсыздыкты басууга жардам берет.','Kas kõht on pingul või venib? 😣','Väldi järske liigutusi. Soe dušš või õrn massaaž aitavad ebamugavustunnet leevendada.'),
('0cc5cbcc-4e89-43b3-8303-b5765d583930'::uuid,'Наристенин манжа издери даяр! 🖐️','Дүйнөдө эч кимде жок уникалдуу издер калыптанып бүттү. Ал азыркы учурда өзүнчө инсан. Бул укмуштуудай эмеспи?','Beebi sõrmejäljed on valmis! 🖐️','Need ainulaadsed mustrid, mis erinevad kõigist teistest maailmas, on juba moodustunud. Ta on juba isiksus. Kas pole see imeline?'),
('f36e06df-bab1-456a-b2ec-00d5e38377c7'::uuid,'Абдан ачка болуп жатасызбы? 😋','Таттуу табит жакшы, бирок «эки киши үчүн жеш керек» деген – бул жомок. Сапаттуу калорияларды тандаңыз: жаңгак, мөмө-жемиштер, жашылчалар.','Kas kõht on eriti tühi? 😋','Suurenenud söögiisu on tore, kuid kahe eest söömine on müüt. Vali kvaliteetsed kalorid: kreeka pähklid, puu- ja köögiviljad.'),
('9c22925e-f028-48cf-85a0-9499c06415cb'::uuid,'Мурун бүтүп жатабы? 🤧','Сиз ооруган жоксуз, бул кош бойлуулук ринити болушу мүмкүн. Туздуу спрей колдонуп жана бөлмөңүздү нымдап көрүңүз.','Kas nina on kinni? 🤧','Sa ei ole haige, see on tõenäoliselt rasedusaegne nohu. Proovi soolalahuse pihustit ja toa õhuniiskuse tõstmist.'),
('1ea8357f-773e-45c8-a5ce-b632b68c81c2'::uuid,'Төрөт жакындап калды! 🚚','Ачка болгонумда, сизге бир аз түрткүлөп коюшум мүмкүн. Бүгүн «Тамактануу» бөлүмүндө кандай пайдалуу варианттар бар? 😋','Kiire tarne on tulekul! 🚚','Kui ma olen näljane, võin hakata sind vaikselt müksama. Milliseid tervislikke valikuid toitumise jaotises täna on? 😋'),
('d03c23f6-2e1d-4083-b90a-157da0e6e6f4'::uuid,'Ич катуу дагы деле барбы? 🚽','Клетчаткага бай тамактар жана көп суу – сиздин эң жакын жардамчыңыз. Ичеги-карындын иштешин жакшыртуу үчүн күн сайын сейилдеп туруңуз!','Kõhukinnisus ei kao kuhugi? 🚽','Kiudainerikkad toidud ja rohke vesi on sinu parimad liitlased. Ole aktiivne ja käi igapäevaselt jalutamas, et seedimine toimiks sujuvalt!'),
('0deb48f1-6a30-484b-9569-decc49f2c37c'::uuid,'Наристенин сөөктөрү бекемделип жатат! 🦴','Резина сыяктуу жумшак кемирчектер сөөккө айланууда. Бөбөгүңүздүн сөөктөрүн болоттой бекем кылуу үчүн кальцийди көбүрөөк колдонуңуз!','Beebi luud tugevnevad! 🦴','Pehme kõhr muutub nagu kumm luuks. Varu kaltsiumi, et muuta beebi luustik terasest tugevamaks!'),
('b9294383-8fdd-4af3-9a0e-31820d8761cf'::uuid,'Баш айлануу менен коштошуңуз! 🛑','Кандын көлөмү көбөйгөн сайын темирге болгон муктаждык да өсөт. Шпинат, гречка же кызыл эт... Буларды менюңузга кошууну унутпаңыз!','Jäta pearinglusega hüvasti! 🛑','Veremahu suurenedes kasvab vajadus raua järele. Spinat, tatar või punane liha... Lisa need kindlasti oma menüüsse!'),
('38d34d85-388f-49ed-9594-2287f8011443'::uuid,'Наристеңиз курсакта бийлеп жатабы? 💃','Мен бул жерде оодарылып жатам! Сезип жатасызбы?','Kas beebi peab tantsupidu? 💃','Ma õpin siin kukerpalle tegema! Kas tundsid seda?'),
('2496cef6-77ee-4345-81fb-7ae6ee89a5c4'::uuid,'Акыркы убакта кызык түштөрдү көрүп жатасызбы? 😴','Гормондор кээде түндөрүңүздү кино сыяктуу кылып коюшу мүмкүн! Кабатыр болбоңуз, бул толугу менен нормалдуу көрүнүш. Түштөрүңүздү «Маанай күндөлүгүнө» жазып көрүңүз!','Viimasel ajal kummalised unenäod? 😴','Hormoonid võivad mõnikord muuta su ööd filmilikuks! Ära muretse, see on täiesti normaalne. Proovi oma unenägusid meeleolupäevikusse kirja panna!'),
('a0a2da1d-904a-4c50-8ef1-d362ba476da8'::uuid,'Ал өзүнүн табигый кремин сүйкөп жатат! 🧴','Бырышпашы үчүн бөбөктүн териси верникс казеоза деп аталган ак, сыр сыяктуу зат менен капталган. Бул жаратылыштын өзүнүн коргоочу креми!','Määrib endale looduslikku kreemi peale! 🧴','Kortsude vältimiseks on beebi nahk kaetud valge juustja ainega, mida nimetatakse vernix caseosa''ks. See on looduse oma kaitsekreem!'),
('d4b39ae6-9d34-4c4d-8a69-951fc75c6f59'::uuid,'Темирдин эң жакын досу ким? 🍊','Эгер темир дарыларын ичип жатсаңыз, аны С витамини менен бирге ичиңиз. Бул темирдин сиңишин бир топ жакшыртат!','Kes on raua parim sõber? 🍊','Kui võtad rauapreparaate, tarbi neid koos C-vitamiiniga. See tõstab märgatavalt raua imendumist!'),
('9ad99447-3f71-4bc4-9dff-13a64a93c8f4'::uuid,'Белиңиз ооруп жатабы? 👠','Бийик такалуу бут кийимдерди алып коюңуз, апа – ыңгайлуу боло турган убак! Ортопедиялык, ыңгайлуу бут кийимдерди тандаңыз.','Kas selg valutab? 👠','Pane kõrged kontsad kappi, emme – nüüd on aeg mugavuse jaoks! Vali toetavad ortopeedilised jalanõud.'),
('a4dafbff-3c24-457e-81b5-bb659a58fa4b'::uuid,'Капталыңыз чоюлуп жатабы? ⚡','Күтүлбөгөн жерден булчуңдардын тартылышы мүмкүн – кабатыр болбоңуз, мен жөн гана үйүмдү кеңейтип жатам! «Көнүгүүлөр» бөлүмүндөгү эс алдыруучу көнүгүүлөрдү карап көрүңүз. 🤸‍♀️','Tunned külgedes venitust? ⚡','Võid tunda äkilisi krampe – ära muretse, ma lihtsalt laiendan oma kodu! Vaata treeningute jaotisest lõõgastavaid harjutusi. 🤸‍♀️'),
('039c5d10-ebc0-436e-9936-a148242fd9a3'::uuid,'Наристеңиздин паспорту даяр! 🛂','Манжа издери толук калыптанды! Дүйнөдө эч кимде жок ал уникалдуу издер азыр сиздин бөбөгүңүздө. Чыныгы уникалдуу инсан келе жатат!','Sinu beebi pass on valmis! 🛂','Sõrmejäljed on täielikult moodustunud! Need ainulaadsed mustrid, mida kellelgi teisel maailmas ei ole, on nüüd sinu pisikesel olemas. Tõeliselt unikaalne inimene on teel!'),
('f1613176-745a-48b4-a20e-1dee77f819cf'::uuid,'Суунун даамы сизге жакпай жатабы? 💧','Эгер жөнөкөй суу ичүү кыйын болсо, бадыраң, дарбыз же жалбыз кошулган сууну ичип көрүңүз. Суусуздануу баш ооруга алып келиши мүмкүн!','Kas vesi tundub veidi mage? 💧','Kui tavalise vee joomine on raske, proovi kurgiviile, arbuusi või mündivett. Vedelikupuudus võib põhjustada peavalu!'),
('f319fe10-d32c-42c4-938c-e7358782f1f1'::uuid,'Апа, мен сени угуп жатам! 👂','Сиздин үнүңүз мага бешик ырындай угулат, ал эми жүрөгүңүздүн согушу – эң сонун ритм. Мени менен көбүрөөк сүйлөшүңүз; мен сизди тааныгым келет.','Emme, ma kuulen sind! 👂','Sinu hääl kõlab mulle nagu hällilaul ja sinu südamelöögid on kõige kaunim rütm. Räägi minuga rohkem; tahan sind tundma õppida.'),
('08cbf45e-1a2d-4043-a7ff-cbce10cda3f8'::uuid,'Цинк: Көзгө көрүнбөгөн баатыр 🛡️','Клеткаларым тез бөлүнүп жатат, мага көп курулуш материалы керек! Бүгүн менюңузда кызыл эт, сыр же жаңгак барбы?','Tsink: tunnustamata kangelane 🛡️','Minu rakud jagunevad kiiresti ja vajan palju ehitusmaterjali! Kas punane liha, juust või pähklid on täna sinu menüüs?'),
('08979df0-c3a9-4a97-8501-c4fbc032480c'::uuid,'Мен мангонун көлөмүндөймин! 🥭','Болжол менен 15 см. Терим дагы деле жука, бирок май катмарым калыптана баштады. Азыр бир аз томолок болуп калдым, апа!','Olen mango suurune! 🥭','Umbes 15 cm. Mu nahk on veel õhuke, kuid rasvakiht hakkab moodustuma. Näen juba natuke pontšakam välja, emme!'),
('9cb3f2ab-0aed-4e06-977f-d372f91e236f'::uuid,'Тигини сездиңизби? Тепкенди! ⚽','Апа, мен ойгоомун! Ал жеңил кыймыл – менин салам айтканым. Колуңузду курсагыңызга коюңуз, балким дагы бир жолу кайталайм?','Kas tundsid seda? See oli löök! ⚽','Emme, ma olen ärkvel! See kerge liblikate lendamine on minu viis tere öelda. Pane käsi kõhule, äkki teen seda uuesti?'),
('c42cae82-ff16-485c-8a26-23b4bfd30c8b'::uuid,'Уулбу же кызбы? 💙💗','Жынысымды биле турган УЗИ күнү жакындап калды! Толкуп жатасызбы?','Poiss või tüdruk? 💙💗','Ultraheliuuring, kus selgub minu sugu, on varsti tulemas! Kas oled põnevil?'),
('6ada1169-9af2-4ce3-bb7e-de40ea64dfd1'::uuid,'Наристенин биринчи оюнчугу!','Мен киндигим менен ойноп жатам, кээде аны кысып да коём! Кичинекей манжаларым кармоону үйрөнүп жатат.','Beebi esimene mänguasi!','Mängin oma nabanööriga, vahel isegi pigistan seda! Minu väikesed sõrmed õpivad juba haarama.'),
('7529d4a8-1e26-4d8b-8bcf-18154f789283'::uuid,'Маанилүү кабыл алуу күнү! 🗓️','18-22-апталар көбүнчө эң деталдуу УЗИ жасала турган убак. Алар манжаларымды санап, жүрөгүмдү текшеришет, баарын! УЗИге жазылдыңызбы?','Suur visiidipäev! 🗓️','18.-22. nädal on tavaliselt aeg, mil tehakse kõige põhjalikum ultraheli. Nad loevad mu sõrmi, kontrollivad südant, kõike! Kas oled aja juba kirja pannud?'),
('6fb4f290-31ce-473d-a17d-ea607c5d055d'::uuid,'Банандын көлөмүндөй! 🍌','Мен азыр болжол менен 18-20 см узундуктамын! Мени баштан согончокко чейин өлчөшөт, денем чоюлуп, даана боло баштады.','Banaani suurune! 🍌','Olen nüüd umbes 18-20 cm pikk! Mind mõõdetakse pealaest kannani ja mu keha sirutub ning muutub selgemaks.'),
('8731dd9d-3325-4b84-b0cd-b6cef3da8f89'::uuid,'Шшш, мен уктап жатам 😴','Менин да уйку графигим бар, апа! Сиз басып жүргөндө, мен термелип уктап жатам. Бирок сиз жатканыңызда, мен ойгонуп бийлей баштайм! Кечириңиз! 😇','Ššš, ma magan 😴','Mul on ka unegraafik, emme! Kui sina kõnnid, siis mina kiigun ja magan. Aga kui sa pikali heidad, ärkan mina ja teen tantsupeo! Vabandust! 😇'),
('61323e5e-ad2b-4a40-a3f3-72d99e6d77ef'::uuid,'Жарым жолду басып өттүк! 🏁','Куттуктайбыз! Сиз расмий түрдө 20-аптага жеттиңиз – кош бойлуулуктун тең ортосу! Сиз укмуштуудай иш жасап жатасыз; бул чоң жетишкендикти сөзсүз белгилөө керек!','Pool teed on käidud! 🏁','Palju õnne! Oled ametlikult jõudnud 20. nädalani – raseduse poole peale! Teed suurepärast tööd; see verstapost väärib kindlasti tähistamist!'),
('5d030bf9-1346-4234-959d-a123523b7611'::uuid,'Жүктөлүүдө... 50% ⏳','Куттуктайбыз! Биз тең ортосуна жеттик. Бул жетишкендикти Галереяда сүрөткө түшүп белгилей турган учур! ✨','Laadimine... 50% ⏳','Palju õnne! Oleme jõudnud poole peale. See on verstapost, mida tasub galeriis fotoga tähistada! ✨'),
('5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf'::uuid,'Атасы мени сезе алабы?','Эгер колуңузду курсагыңызга койсоңуз, балким мен аларга да салам айтам.❤️','Kas issi tunneb mind?','Kui paned käe kõhule, äkki ütlen neile ka tere.❤️'),
('dafe2e2c-e054-4c05-a7f0-7e5828a0bd40'::uuid,'Түстүү түштөрдү көрүп жатасызбы?','Кош бойлуу кездеги түштөр кино сыяктуу эмеспи? Мен сиздин түшүңүздө башкы ролдомунбу? 😴','Kas näed värvilisi unenägusid?','Rasedusaegsed unenäod võivad olla nagu filmid, eks? Kas mina mängin sinu omades peaosa? 😴'),
('23bdc5ce-4bf9-4c06-b27f-3cf7672d0391'::uuid,'Өз ритмимди таап жатам 🥁','Жүрөгүм бир калыпта согуп жатат, мен дем алууну машыгып жатам. Кээде, мен ыкылыктап да калам!','Leian oma rütmi 🥁','Mu süda lööb ühtlaselt ja ma harjutan hingamist. Mõnikord tulevad mul isegi luksumishood!'),
('fae74e2f-98a8-45d5-8202-44383d0eb18a'::uuid,'Даамдарды таанып жатам! 👅','Амниотикалык суюктуктун даамы сиз жеген тамакка жараша өзгөрөт. Ачуу калемпир жедиңизби? Мен анын даамын сезем!','Avastan maitseid! 👅','Lootevee maitse muutub vastavalt sellele, mida sa sööd. Sõid vürtsikaid pipraid? Ma tunnen seda maitset!'),
('b707fa58-b376-47be-9e74-acc0d0bc553a'::uuid,'Өзүңүзгө кам көрүү күнү! 💅','Эгер кош бойлуулук тактарын байкасаңыз, өзүңүздү күндөн коргоңуз. Бүгүн бетке маска жасап, өзүңүздү сыйласаңыз кандай болот?','Enesehoolitsuse päev! 💅','Kui märkad raseduslaike, kaitse end päikese eest. Kuidas oleks, kui hellitaksid end täna näomaskiga?'),
('6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a'::uuid,'Шымдарыңыз кысып жатабы? 👖','Баштапкы салмагыңызды Салмак көзөмөлдөгүчкө жаздыңызбы? 📈','Kas püksid on kitsaks jäänud? 👖','Kas oled oma algkaalu kaalujälgijasse märkinud? 📈'),
('e7c711cf-139e-409a-9191-4e2baba06f95'::uuid,'Алманын көлөмүндөй 🍎','Шымыңыздын топчусун чечип, ыңгайланып алыңыз! 😄','Umbes õuna suurune 🍎','Tunne end vabalt, ava püksinööp ja ole mugavalt! 😄'),
('323b3eda-82d0-406d-9ef8-03c3ba37648c'::uuid,'Бутуңуз шишип жатабы? 👠','Шишик башталышы мүмкүн. Жумушта же үйдө, мүмкүнчүлүк болгондо бутуңузду өйдө көтөрүп туруңуз. Ыңгайлуу бут кийим тандаңыз!','Kas jalad paistetavad? 👠','Võib alata tursumine. Tööl või kodus olles tõsta jalad võimalusel kõrgemale. Vali mugavad jalanõud!'),
('e5b18866-69e0-4ac8-9b93-de4b2812e136'::uuid,'Ик... Ик... 🤭','Курсагыңыз ритм менен кыймылдап жатабы? Кабатыр болбоңуз, апа, бул жөн гана ыкылык! Мен диафрагмам менен машыгып жатам.','Luks... luks... 🤭','Kas su kõht tõmbleb rütmiliselt? Ära muretse, emme, need on lihtsalt luksumishood! Harjutan oma vahelihasega.'),
('b050527e-1e40-44a0-ab00-fb32d6abb570'::uuid,'Бет түзүлүшүн изилдеп жатат! 👶','Мен колум менен бетимди, мурдумду, ал тургай киндигимди кармап жатам. Сезимдерим өнүгүүдө. Мен өзүмдү таанып жатам!','Avastab oma nägu! 👶','Katsun kätega oma nägu, nina ja isegi nabanööri. Minu kompimismeel areneb. Hakkan iseennast tundma õppima!'),
('866256da-856c-40a8-a2d6-0e562a2b89fa'::uuid,'Туздалган бадыраң менен балмуздакпы? 🥒🍦','Адаттан тыш тамактарды каалап жатасызбы? Денеңиз сизге сигнал берип жатат. Бирок кант менен тузду тең салмакта кармаганга аракет кылыңыз.','Hapukurk ja jäätis? 🥒🍦','Kas sul on isusid ebatavaliste koosluste järele? Sinu keha saadab sulle signaale. Kuid püüa hoida suhkru ja soola tarbimine tasakaalus.'),
('b5881822-5bbb-4123-8e83-7e5e1502c2a2'::uuid,'Кокостун көлөмүндөй! 🥥','Мен болжол менен 28 см узундуктамын жана салмагым жарым килодон ашты! Эми менин тээп жатканым ого бетер күчтүү.','Umbes kookospähkli suurune! 🥥','Olen umbes 28 cm pikk ja kaalun üle poole kilo! Nüüd on mu müksud veelgi tugevamad.'),
('b4b9bd27-17f0-4aee-8b06-793656f6ef67'::uuid,'Музыка угалыбы? 🎶','Апа, мен сырткы дүйнөнүн үндөрүн уга алам! Мен да сиздин сүйүктүү ырларыңызды жакшы көрөм. Экөөбүз чогуу бийлейлиби?','Kas mängime veidi muusikat? 🎶','Emme, ma kuulen helisid välismaailmast! Mulle meeldivad ka sinu lemmiklaulud. Kas tantsime koos?'),
('88a2f76b-bbca-49e6-a2ea-fe93e58a6be7'::uuid,'Көздөрүм кыймылдап жатат...','Көзүм жумулуу болсо да, мен азыртан эле түш көрүп жатам. Кандай деп ойлойсуз, эмне жөнүндө түш көрүп жатам?','Mu silmad tantsivad...','Kuigi mu silmalaud on suletud, näen ma juba und. Mida sa arvad, millest ma und näen?'),
('302938ba-54dd-42b1-8785-76afddeea091'::uuid,'Зарна болуп жатабы? 🔥','Жатыныңыз ашказаныңызга басым жасап жатат. Тамакты аз-аздан, тез-тез жеп туруңуз. Тамактангандан кийин дароо жатпаңыз; тик отуруңуз.','Kõrvetised? 🔥','Sinu emakas surub maole. Söö väikeste portsjonite kaupa ja tihedamini. Ära heida kohe pärast söömist pikali; istu sirgelt.'),
('486ac2e6-38fa-429a-b2e0-197066312def'::uuid,'Марафонубуз аяктап баратат! 🏁','Бул экинчи триместриңиздин акыркы күндөрү. Үчүнчү триместр башталганга чейин мүмкүн болушунча жакшылап эс алып алыңыз!','Lõpusirge on käes! 🏁','Need on teise trimestri viimased päevad. Puhka ja maga nii palju kui võimalik, enne kui kolmas trimester algab!'),
('473ac730-c42b-4a8b-8df8-3ff17fbbb8fc'::uuid,'Киндигиңиз чыгып калдыбы? 🔘','Курсагыңыз чоңойгон сайын, киндигиңиз сыртка чыгып калышы мүмкүн. Кабатыр болбоңуз, төрөттөн кийин баары мурдагы калыбына келет!','Kas su naba on punnis? 🔘','Kõhu kasvades võib naba väljapoole tulla. Ära muretse, pärast sünnitust läheb see tagasi normaalseks!'),
('3993d773-d077-4047-afc5-47cd2550cb94'::uuid,'Брекстон-Хикс толгоосубу же чыныгысыбы? 🤔','Курсагыңыз катууланып жатабы? Бул Брэкстон-Хикс жыйрылуулары болушу мүмкүн. Жатыныңыз төрөткө даярданып жатат. Эгерде оорутпаса, бул кадимки көрүнүш.','Braxton Hicksi kokkutõmbed või päris asjad? 🤔','Kas kõht läheb kõvaks? Need võivad olla Braxton-Hicksi kokkutõmbed. Sinu emakas valmistub sünnituseks. Kui need on valutud, on see normaalne.'),
('60d55b22-fbf7-460c-942e-d9f7e0731669'::uuid,'Туздуу тамактардан алыс болуңуз! 🧂','Эгер бутуңуз шишип жатса, тузду азыраак колдонуңуз. Көп суу ичүү жана петрушка жардам берет. Шакегиңиз манжаңызга кысып баштадыбы?','Hoia soolastest snäkkidest eemale! 🧂','Kui jalad paistetavad, vähenda soola tarbimist. Rohke vesi ja petersell võivad aidata. Kas sõrmus hakkab sõrmes kitsaks jääma?'),
('6de7574a-4dcf-48fd-a091-4641ee581b82'::uuid,'Кичинекей фабрикабыз кызуу иштеп жатат! 🏭','Боорум эми кан клеткаларын чыгарбайт, азыр муну жилик чучугум аткарууда. Мага жардам берүү үчүн темирге бай кандай тамактарды жеп жатасыз?','Väike tehas sumiseb! 🏭','Minu maks ei tooda enam vererakke, seda teeb nüüd luuüdi. Et mind aidata, milliseid rauarikkaid toite sa sööd?'),
('a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae'::uuid,'Шшш, мен уктап жатам... 🤫','Апа, эмнеге кыймылдабай жатам деп ойлобоңуз. Анткени мен күнү бою уктап жатам. Мен уктаганда сиз да эс алыңыз.','Kuss, ma magan... 🤫','Emme, miks ma ei liiguta? See on sellepärast, et ma magan suurema osa päevast. Puhka siis, kui minagi puhkan.'),
('cb6d62d7-338e-4fb3-907d-9bfa587ddc19'::uuid,'Жашыруун көнүгүү жасоо убактысы келди! 🧘‍♀️','Кегель көнүгүүлөрүн унутпаңыз! Отурган жериңизде жамбаш түбүнүн булчуңдарын кысып, кайра бошотуңуз. Бул төрөт учурунда абдан маанилүү болот!','Aeg väikeseks salajaseks trenniks! 🧘‍♀️','Ära unusta Kegeli harjutusi! Pinguta ja lõdvesta vaagnapõhjalihaseid istudes. Need on sünnituse ajal väga olulised!'),
('26be4f7a-020a-4656-9916-24ee79dcc7a2'::uuid,'Биринчи дем алуу көнүгүүлөрү! 🫁','Өпкөмдө сурфактант пайда болууда. Бул зат төрөлгөндө биринчи демимди алууга жардам берет. Мен машыгып жатам!','Esimesed hingamisharjutused! 🫁','Minu kopsudesse tekib surfaktant. See aine aitab mul pärast sündi esimest korda hingata. Ma harjutan juba!'),
('ba959c1d-a66b-4198-9703-7d204b6d9029'::uuid,'Ал кандай добуш эле, апа? 🔊','Капыстан чыккан катуу үндөр мени чочутат. Сиз тынч болсоңуз, мен да тынчмын. Мага бешик ырын ырдап бере аласызбы?','Mis heli see oli, emme? 🔊','Äkilised valjud helid ehmatavad mind. Kui sina oled rahulik, olen ka mina. Kas laulaksid mulle unelaulu?'),
('52571825-8dff-470b-9a01-2096ca6a9ef9'::uuid,'Сиз менин бешигимсиз... 💤','Сиз басканда, мен термелип уктап калам. Сиз токтогондо, мен ойгоном! Мени уктатуу үчүн жай басып сейилдөөнү уланталыбы? 🚶‍♀️','Sina oled mu häll... 💤','Kui sa kõnnid, kiigun mina unne. Kui sa peatud, ärkan üles! Kas jätkame rahulikku jalutamist, et mind uuesti magama uinutada? 🚶‍♀️'),
('1184b7b9-b4b5-43fa-a2bc-fd09d7701438'::uuid,'Таттуу суусундук ичтиңизби? 🥤','Гестациялык диабетке текшерилүү абдан маанилүү. Менин да, сиздин да ден соолугуңуз үчүн сөзсүз текшерилип алыңыз.','Kas sa jõid midagi magusat? 🥤','Rasedusdiabeedi test on oluline. Veendu, et teed selle nii minu kui ka enda tervise huvides.'),
('27ba2d28-f6c7-4448-bd98-0c87bc789c84'::uuid,'Linea nigra (курсактагы кара сызык) көрүнүп калдыбы? ➖','Ал кара сызык (Linea Nigra) гормондорго байланыштуу. Кабатыр болбоңуз, төрөттөн кийин ал жоголот. Сиз ар дайым сулуусуз!','Kas linea nigra on nähtaval? ➖','See Linea Nigra on tingitud hormoonidest. Ära muretse, see tuhmub pärast sünnitust. Sa oled igati kaunis!'),
('352b7abf-9862-4591-888e-8f478b7b349c'::uuid,'Менин дени сак төрөлүү мүмкүнчүлүгүм дагы жогорулады! 🌟','Мага 24 жума болду! Медициналык жактан алганда, мен азыр жашоого жөндөмдүүмүн. Бул чоң жетишкендик, апа.','Minu ellujäämisvõimalused just kasvasid! 🌟','Olen 24 nädalat vana! Meditsiiniliselt peetakse mind nüüd eluvõimeliseks. See on suur verstapost, emme.'),
('48f71f64-0f7f-494d-bb7e-d0d4e9ee139b'::uuid,'Зарна болуп жатасызбы? 🔥','Зарнаны чачым эмес, апа, жатыныңыздын ашказаныңызга басым жасаганы пайда кылууда! Тамактангандан кийин дароо жатпаңыз; тик отуруңуз.','Kas sul on kõrvetised? 🔥','Kõrvetisi ei põhjusta minu juuksed, emme, vaid sinu emakas, mis surub maole! Ära heida kohe pärast söömist pikali; istu sirgelt.'),
('20bf8c66-4b67-4eac-9759-383a08875de7'::uuid,'Апа, мен тажадым! 🤸','Сиз кыймылсыз калганда, мен ойгоном. Курсагыңызды сылаңыз; балким, мен да сизге бир аз тепкилеп жооп берермин?','Emme, mul on igav! 🤸','Kui sa oled paigal, ärkan mina üles. Silitada oma kõhtu; äkki annan sulle väikese müksu vastu?'),
('db0c5fae-71f1-477b-b321-634c423e0906'::uuid,'Мен азыр коондоймун! 🍈','Азыр салмагым 600 граммдай. Мага орун бир аз тар болуп баратат. Тепкилегендерим катуураак болушу мүмкүн, кечириңиз! 🦶','Olen kantaluubi suurune! 🍈','Olen nüüd umbes 600 grammi. Mu ruum hakkab kitsaks jääma. Mu löögid võivad olla tugevamad, vabandust! 🦶'),
('526f7ea7-3f69-40d2-905e-c2bffa0601cc'::uuid,'Бут кийимиңиз тар болуп баратабы? 👟','Бут кийимиңиздин өлчөмү чоңоюшу мүмкүн. Азыр модадан көрө ыңгайлуулук маанилүү. Кеңири спорттук бут кийимдерди тандаңыз!','Kas su kingad jäävad kitsaks? 👟','Sinu jalanumber võib suureneda. Mugavus on nüüd tähtsam kui stiil. Vali avarad spordijalatsid!'),
('2383cc1a-d388-4623-bfbc-9b03b5278f79'::uuid,'Чачым өз түсүнө кирип жатат! 🎨','Генетикалык лотерея башталды! Мен сары чачтуу, кара чачтуу же кызыл чачтуу боломбу? Чачымдын пигменти калыптанып жатат. Кимге окшош болом деп ойлойсуз?','Mu juuksed saavad oma värvi! 🎨','Geneetiline loterii on alanud! Kas olen blond, brünett või punapea? Minu juuksepigment hakkab kujunema. Kelle sarnane ma sinu arvates olen?'),
('d07f0b6e-c86e-44de-8e9f-d89a09f2ec43'::uuid,'Шишик барбы? 🎈','Бул парадоксалдуу угулса да, чындык: көп суу ичүү шишикти (эдеманы) азайтууга жардам берет! Бадыраң жана дарбыз сыяктуу суусу көп азыктар да жардам берет. Өтө туздуу тамактардан алыс болууга аракет кылыңыз.','Kas tunned end paistes? 🎈','See on paradoksaalne, kuid tõsi: rohke vee joomine aitab tegelikult paistetust (ödeemi) vähendada! Niisutavad toidud nagu kurk ja arbuus võivad samuti aidata. Püüa vältida liigset soola.'),
('fec31592-3149-479f-9be0-155a720e090b'::uuid,'Мен уялып жатам...','Терим эми айнектей тунук эмес! Капиллярларым канга толуп, өңүм кызгылт тартып баратат. Өзүңүздүн кан айланууңуз үчүн ''Суу көзөмөлдөгүч'' аркылуу суу ичүүнү унутпаңыз! 🥤','Ma punastan...','Mu nahk ei ole enam klaasjalt läbipaistev! Mu kapillaarid täituvad verega ja mu värv muutub roosakaks. Oma vereringe toetamiseks ära unusta vett juua, kasutades ''Veejälgijat''! 🥤'),
('5b81d2cf-3568-4e53-b14d-b0aeaec2f43f'::uuid,'Атамдын үнүн угуп жатамбы? 🗣️','Төмөнүрөөк үн жакшыраак угулат, мен аны даанараак уга алам. Атасы менен сүйлөшүңүз, ага мага жомок окуп берүүсүн сураныңыз!','Kas ma kuulen issi häält? 🗣️','Sügavam hääl kostab paremini ja ma kuulen seda selgemalt. Räägi issiga ja palu tal mulle lugu lugeda!'),
('cf9fd374-f357-4b58-bc32-9c2c7983b9f8'::uuid,'Сиз менин коргоочумсуз!','Иммундук системам өнүгүп жатат жана мен сиздин антителолоруңузду алып жатам. Сиз мени оорулардан коргоп жатасыз, апа. ❤️','Sina oled mu kaitsja!','Minu immuunsüsteem areneb ja ma saan sinu antikehi. Sa kaitsed mind haiguste eest, emme. ❤️'),
('6631a482-e880-499b-a108-1eb7cfe533ac'::uuid,'Бутуңуз тырышып жатабы? 🦶','Түнкүсүн бутуңуздун булчуңдары тырышып жатабы, апа? Бул магнийдин жетишсиздигинин белгиси болушу мүмкүн. Банан, бадам же йогурт сыяктуу азыктар жардам берет. Булчуңдарыңыз эс алууга муктаж!','Kas sul on krambid? 🦶','Kas sul on öösiti säärekrambid, emme? See võib olla märk magneesiumipuudusest. Banaanid, mandlid või jogurt võivad aidata. Sinu lihased vajavad lõõgastust!'),
('67d7589f-358a-44b0-9ee8-70aca8b6ffc6'::uuid,'Көздөрүм ачылып жатат! 👀','Бул жер караңгы болсо да, мен көзүмдү ача алам. Кирпиктеримди да ирмеп жатам! Дүйнөнү көрө турган күнүмө да көп калган жок!','Mu silmad avanevad! 👀','Kuigi siin on pime, saan ma juba silmalaud avada. Ma isegi pilgutan ripsmeid! Pole enam kaua jäänud päevani, mil saan maailma näha!'),
('6a3d4aec-a08e-46ec-9845-95181acaa958'::uuid,'Жарык келе жатат, апа! ☀️','Мен көзүмдү ирмеп жатам! Эгерде курсагыңызга күн нуру тийсе, мен ал жарыкты көрө алам. Дүйнө кандай түстөргө бай деп ойлойсуз?','Valgus paistab, emme! ☀️','Ma pilgutan silmi! Kui päikesevalgus paistab su kõhule, näen ma seda eredat kuma. Milliseid värve sinu arvates maailm peidab?'),
('79b3dcb1-a984-4729-ab92-c057730e6f8d'::uuid,'Крем сүйкөө убактысы! 🧴','Курсагыңыз тез чоңоюп, териңиз тартылып жатат. Кычышууну алдын алуу үчүн күн сайын нымдандыруучу крем сүйкөп туруңуз.','Aeg kreemitada! 🧴','Sinu kõht kasvab kiiresti ja nahk venib. Sügeluse vältimiseks kasuta iga päev niisutavat kreemi.'),
('11db6f3d-a2eb-4392-b358-993a953c992e'::uuid,'Сиздин биринчи коргооңуз менден башталат! 🛡️','Антителолор сизден мага өтүп жатат. Бул төрөлгөндөн кийинки алгачкы айларымда мени коргойт.','Sinu esimene kaitse tuleb minult! 🛡️','Antikehad liiguvad sinult minule. See kaitseb mind esimestel kuudel pärast sündi.'),
('ecec560e-f533-42fa-b81c-743ce51e2fa4'::uuid,'Туздалган бадыраңбы? Бүгүн эмес! 🚫','Эгер бутуңуз шишип жатса, тузду азыраак колдонуңуз. Туздуу тамактар даамдуу болгону менен шишикти пайда кылышы мүмкүн. Анын ордуна лимон кошулган сууну ичип көрүңүз.','Hapukurgid? Mitte täna! 🚫','Kui jalad paistetavad, vähenda soola tarbimist. Soolased toidud on maitsvad, kuid võivad põhjustada ödeemi. Proovi hoopis sidrunivett.'),
('eb78f9b1-0793-4172-8289-9ad69826fa75'::uuid,'Дүйнө абдан ызы-чуу экен... 🔊','Кулагым азыр абдан сезимтал, сырттагы үндөрдү да уга алам! Келиңиз, бир аз тынчтаналыбы? ''Ак ызы-чуу'' функциябыздан жамгырдын үнүн коюп, экөөбүз чогуу уктап кетели. 🌧️','Maailm on üsna mürarikas... 🔊','Mu kõrvad on nüüd nii tundlikud, et kuulen isegi väliseid helisid! Kas rahuneksime veidi? Pane mängima vihmaheli meie ''Valge müra'' funktsioonist ja uinume koos. 🌧️'),
('2a7b5422-c620-43f8-9faf-09db6234cc0f'::uuid,'Кош келиңиз, Үчүнчү триместр! 🏁','Акыркы артка саноо башталды! Азыр денеңиз оорлошуп калды, апа, бирок марага да аз калды. Сабырдуу болуңуз, менин кымбат апам!','Tere tulemast, kolmas trimester! 🏁','Lõpuspurt on alanud! Sinu keha tundub nüüd raskem, emme, aga finišijoon on tõesti silmapiiril. Ole kannatlik, mu kallis emme!'),
('153927df-2197-4033-aa1c-31dfbfdf9083'::uuid,'Ой! Ал кандай добуш эле? 😳','Эшик катуу жабылганда чочуп кеттим. Угуу жөндөмүм абдан жакшы, апа. Тынч музыка коюңуз, экөөбүз чогуу эс алалы.','Ohoo! Mis heli see oli? 😳','Ehmatasin, kui uks paukus. Mu kuulmine on väga hea, emme. Pane vaikset muusikat, lõõgastume koos.'),
('4de979ce-b173-440f-bc60-e4d333797f19'::uuid,'Мурунум ачылып калгандай! 👃','Мурун тешиктерим жабык болчу, эми ачылды. Мен дем алууга машыгып жатам!','Mu nina on puhas! 👃','Mu ninasõõrmed olid kinni, aga nüüd on need avatud. Harjutan hingamist!'),
('2efc37a3-7408-4f42-8512-00545c8b1565'::uuid,'Ичеги-карыныңыз жай иштеп жатабы? 🐌','Прогестерон ичегиңиздин иштешин жайлатат. Кургатылган өрүк, кара өрүк жана кара буудай наны сиздин куткаруучуңуз боло алат.','Kas su seedimine on aeglane? 🐌','Progesteroon aeglustab sinu soolestiku tööd. Kuivatatud aprikoosid, ploomid ja täisteraleib võivad olla sinu päästjad.'),
('32fe315d-64ad-42bb-8357-047270382c70'::uuid,'Жумшак жаздыктардан чеп куруп алыңыз! 🏰','Төшөктө жайлуу боло албай жатасызбы? Буттарыңыздын ортосуна жана курсагыңыздын астына жаздык коюп көрүңүз. Жакшы колдоо абдан маанилүү!','Ehita hubane padjakindlus! 🏰','Kas sul on voodis raske mugavat asendit leida? Proovi asetada padi jalgade vahele ja kõhu alla. Hea tugi on võtmetähtsusega!'),
('99d63bff-e50d-4a8d-89f1-525eee8af207'::uuid,'Мен бул жерде кичинекей йогмун! 🦶','Ишенбейсиз, бирок мен бутумдун бармагын кармап, оозума сала алам! Мен абдан ийкемдүүмүн. Сизге акыркы күндөрү ийилүү кыйын болуп жатабы?','Olen siin nagu väike joogi! 🦶','Sa ei usu seda, aga ma suudan oma varbast kinni võtta ja suhu pista! Olen väga paindlik. Kas sul on viimasel ajal raskem kummarduda?'),
('9c19e501-078c-4145-9bf4-28096c2e69da'::uuid,'Көздөрүм ачык! 👀','Апа, ишенбейсиз, бирок мен көзүмдү ача баштадым. Караңгы болсо да, көз карашым калыптанып жатат. Сизди көрө турган күнүмө аз калды!','Mu silmad on lahti! 👀','Emme, sa ei usu, aga olen hakanud silmalauge avama. Kuigi on pime, hakkab mu pilk juba kujunema. Pole enam kaua jäänud, kuni sind näen!'),
('c1685f6c-ebb8-432c-88df-49144f8b19c4'::uuid,'Ашказаныңыз күйүп жатабы? 🔥','Жатыныңыз ашказаныңызды өйдө түртүп жатат. Сүт ичүү же бир ууч чийки бадам жеп алуу күйүү сезимин басууга жардам берет.','Kas su kõhus kõrvetab? 🔥','Sinu emakas surub magu ülespoole. Piima joomine või peotäis tooreid mandleid võib aidata kõrvetustunnet leevendada.'),
('0a1c9fc7-d6fb-46ee-b640-782093d821ef'::uuid,'Уя даярдап жатабызбы? 🐣','Бешигим, кичинекей кийимдерим... Атасы менен ''Биргелешкен соода'' тизмесин даярдап коюңуз! 📝','Kas me punume pesa? 🐣','Minu voodi, pisikesed riided... Pane issiga koos nimekiri valmis ''Jagatud ostunimekirjas''! 📝'),
('f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea'::uuid,'Сиздин кан тобуңуз Резус-терс (Rh-) экендигин билесизби? 🩸','Бул Rh-терс (резус-фактору терс) энелер үчүн маанилүү жума. Иммуноглобулин саймасы (RhoGAM) керек болушу мүмкүн. Сөзсүз дарыгериңиз менен кеңешиңиз!','Kas su vererühm on reesusnegatiivne? 🩸','See on kriitiline nädal Rh-negatiivsetele emadele. Võib vaja minna immunoglobuliini süsti (RhoGAM). Räägi kindlasti oma arstiga!'),
('6e18672f-c08d-4df7-a33d-ffe41885dcb7'::uuid,'Кирпиктерим узарып жатат! 👁️','Көзүмдү ачып-жумуп жатам, эми жарык менен караңгыны айырмалай алам! Эгер курсагыңызга фонарик менен жарык кылсаңыз, балким, бетимди буруп кетем. Байкап көрөсүзбү?','Mu ripsmed kasvavad pikaks! 👁️','Ma avan ja sulgen silmi ning suudan nüüd eristada valgust ja pimedust! Kui suunad taskulambi kõhule, pööran tõenäoliselt näo ära. Tahad proovida?'),
('382ecc0d-761f-4375-83d6-da7672e029c4'::uuid,'Балык, балык, балык! 🐟','Бул менин мээмдин эң тез өнүгүп жаткан мезгили! Мага Омега-3 абдан керек. Жумасына эки жолу балык жеп жатасызбы?','Kala, kala, kala! 🐟','See on minu aju kiireima arengu periood! Vajan väga Omega-3 rasvhappeid. Kas sööd kaks korda nädalas kala?'),
('6c259c3a-0864-4b21-9205-87b10a98dab6'::uuid,'Мен келдим, апа! 👋','Кээде тынчмын, кээде бийлеп жатам! Тепкилегендеримди санап жатасызбы? Баары жакшы, жөн гана менин орунум тар болуп баратат.','Ma olen siin, emme! 👋','Vahel olen rahulik, vahel tantsin! Kas loed mu mükse? Kõik on korras, mul hakkab lihtsalt ruum otsa saama.'),
('90084ac3-06b5-4f06-ab1a-792e7c238804'::uuid,'Варикоз чыгып жатабы? 🕸️','Варикоздук тамырлар көйгөй жаратышы мүмкүн. Узак убакыт тик туруудан качыңыз. Кечинде буттарыңызды дубалга жөлөп көтөрүп жатыңыз – бул кан айланууга абдан жардам берет!','Veenilaiendid? 🕸️','Veenilaiendid võivad muret tekitada. Püüa vältida pikka seismist. Õhtuti tõsta jalad seina vastu – see aitab vereringet tõesti parandada!'),
('7a6fc4a8-e1e2-4415-a61f-8af42944c1a1'::uuid,'Менин кан фабрикам тынбай иштеп жатат! 🩸','Буга чейин боорум кан клеткаларын чыгарып келсе, эми жилик чучугум бул ишти өзүнө алды! Бул менин сырттагы көз карандысыз жашоомо даярдануунун бир бөлүгү.','Mu veretehas teeb kõvasti tööd! 🩸','Siiani on mu maks tootnud vererakke, aga nüüd on luuüdi selle üle võtnud! See on kõik osa ettevalmistusest iseseisvaks eluks väljaspool.'),
('c0cb44c3-4840-4ac8-9cb6-1e444e960d76'::uuid,'Темир жана С витамини: эң сонун жуп! 🥩🍊','Анемиянын алдын алуу үчүн: Эт жегенде жанына апельсин ширесин ичиңиз! С витамини темирдин сиңишин эки эсеге көбөйтөт.','Raud ja C-vitamiin: täiuslik paar! 🥩🍊','Aneemia ennetamiseks: kui sööd liha, joo kõrvale apelsinimahla! C-vitamiin võib raua imendumist kahekordistada.'),
('5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed'::uuid,'Капустадай чоңойдум! 🥬','Терим жылмакайланып, беттерим толо баштады. Сизди көрүүнү чыдамсыздык менен күтүп жатам!','Kapsapea suurune! 🥬','Mu nahk muutub siledamaks ja põsed prullakamaks. Ma ei jõua ära oodata, millal sind näen!'),
('a1284943-8afb-4514-a518-910d7434b8db'::uuid,'Дем алууңуз кыйындап жатабы? 😮‍💨','Өйдө карай жылып, диафрагмаңызга басым жасап жатам. Терең дем алууга аракет кылыңыз, апа. Төмөн түшө турган күнүмө аз калды.','Kas oled hingetu? 😮‍💨','Ülespoole liikudes surun ma sinu diafragmale. Püüa sügavalt hingata, emme. Pole enam kaua jäänud, kuni ma allapoole liigun.'),
('283efed7-5c27-4325-a5d1-abc7b9874001'::uuid,'Баламдын мүнөзү кандай болот болду экен? ✨','Өжөрбү же сезимталбы? Төрөт күнүмө карата зодиак белгим эмне дейт? Сиздин белгиңиз менен төп келеби? Келиңиз, гороскопту текшерип көрөлү! 🌠','Milline on mu beebi iseloom? ✨','Kangekaelne või emotsionaalne? Mida ütleb minu tähtkuju sünnitustähtaja järgi? Kas sobime sinu tähemärgiga? Vaatame horoskoopi! 🌠'),
('2d850fd8-33a5-4d99-8d38-9501167a4a14'::uuid,'Кабыргаңыз ооруп жатабы? 🥊','Ой, кечириңиз апа! Бул жерде орун тар болуп баратат. Бутумду сунганда кабыргаңызды тепкилеп алышым мүмкүн. Тик отуруу сизге ыңгайлуураак болууга жардам берет.','Kas roided valutavad? 🥊','Ups, vabandust emme! Mul hakkab siin ruum otsa saama. Kui sirutan jalgu, võin su ribidesse müksata. Sirgelt istumine võib aidata sul end mugavamalt tunda.'),
('881c71cb-32af-4e22-9bf1-839ae870e7a5'::uuid,'Тепкилегендеримди санап жатасызбы? 🦶','Мен эми үзгүлтүксүз кыймылдай баштадым. ''Тепкилөө эсептегичине'' кирип, кыймылдарымды көзөмөлдөп туруңуз. Баары жайындабы?','Kas sa loed mu lööke? 🦶','Hakkan kujundama regulaarset liikumismustrit. Mine ''Loote liigutuste loendurisse'' ja jälgi minu aktiivsust. Kas kõik on korras?'),
('9d46b716-6bee-4533-9dcb-2ebd6327811f'::uuid,'Мээмде бырыштар пайда болуп жатат! 🧠','Мээм мурда жылмакай болчу, эми бырыштар жана оюктар (гири жана сулкустар) пайда болууда! Бул миллиарддаган нейрондор активдүү байланышып жатканын билдирет. Кичинекей гений келе жатат!','Mu aju saab oma kurrud! 🧠','Mu aju oli varem sile, aga nüüd tekivad kurrud ja vaod! See tähendab, et miljardid neuronid loovad aktiivselt ühendusi. Väike geenius on tulemas!'),
('b2fb0049-069a-46c3-bea3-307a0c34873c'::uuid,'Зарна сизди кыйнап жатабы? 🔥','Ашказан кычкылы тамагыңызга чыгып жатабы? Тамактангандан кийин сагыз чайноо же жылуу сүт ичүү жардам берет.','Kas refluks vaevab sind? 🔥','Kas maohape tõuseb kurku? Pärast sööki nätsu närimine või sooja piima joomine võib aidata.'),
('88619dd2-a8e1-47a0-8257-5ec0eff6998d'::uuid,'Мен азыр ашкабактаймын! 🎃','Боюм 39-40 см, салмагым 1.2 кг! Сизге оордук кылып жатамбы? Кечириңиз, апа, бирок мен дагы салмак кошушум керек.','Olen kõrvitsa suurune! 🎃','Olen umbes 39-40 cm pikk. Kaalun 1,2 kg! Kas muutun sinu jaoks raskeks? Vabandust, emme, aga pean veel kaalus juurde võtma.'),
('8e4d973a-778f-424e-8c3a-935a1a80329f'::uuid,'Төрөт үйүнө керектүү сумкаңызды даярдадыңызбы? 👜','Эрте эмес! Ооруканага керектүү буюмдардын тизмесин карап чыгыңыз. Жетишпеген нерселерди азыр толуктап коюу стрессти азайтат.','Kas oled haiglakotile mõelnud? 👜','Pole liiga vara! Vaata üle haiglakoti nimekiri. Puuduvate asjade varumine vähendab stressi.'),
('5e65c444-b9a6-406f-9ff5-56e21f7ef978'::uuid,'Сизге бир сыр айтайынбы? 🤫','Сиз уктап жатканда, үнүңүздүн ыргагы мени уйкуга тартат. Кимди түш көрүп жатканымды билесизби? Албетте, сизди! 🥰','Kas ma tohin sulle saladuse öelda? 🤫','Kui sa magad, uinutab su hääle kõla mind unne. Arva ära, kellest ma und näen? Muidugi sinust! 🥰'),
('d7852d04-73e0-436f-88c1-c1f3779215e1'::uuid,'Шоколад жегиңиз келип жатабы? 🍫','Ммм, даамын бул жактан эле сезип жатам! Азыр энергияга толуп кеттим. Келиңиз, апа, бийлейли! 💃','Šokolaadiisu? 🍫','Mmm, ma tundsin selle maitset lausa siia sisse! Mu energia on nüüd laes. Tantsime, emme! 💃'),
('cbb3164b-a073-4125-89bc-aa96300b8738'::uuid,'Мен азыр ашкабактаймын! 🎃','Беттерим толо баштады, төрөлгөндө аларды акырын «тиштеп» алгыңыз келет! Бул жерде бир аз тар болуп баратат, бирок сиздин жаныңызда болуу баары бир сонун.','Olen kõrvitsa suurune! 🎃','Mu põsed muutuvad nii pontsakaks, et tahad neid kindlasti õrnalt „näksata“, kui ma kohale jõuan! Siin hakkab juba veidi kitsas, aga sinu lähedal olla on ikkagi imeline.'),
('24a71b37-df5d-44b3-a005-e5736c2b3038'::uuid,'Мен тескери карап алдым! 🙃','Бул жактан көрүнүш абдан сонун! Мен төрөткө даярданып жатам, апа. Бул абалда мен сизге ого бетер жакыныраак сезип жатам.','Ma pöörasin end pea peale! 🙃','Siit avaneb päris hea vaade! Valmistun sünnituseks, emme. Selles asendis tunnen end sulle veelgi lähemal.'),
('2bb496d6-7982-41e7-af5d-07497cf28d32'::uuid,'Курсагыңыз тартышып жатабы? 🤰','Кабатыр болбоңуз, периштеңиз! Бул жөн гана машыгуу. Биз бир командабыз, чоң күнгө даярданып жатабыз!','Kas su kõht tundub pingul? 🤰','Ära muretse, mu inglike! See on alles harjutus. Oleme meeskond ja valmistume suureks päevaks!'),
('6c2d3dce-218d-4319-8647-5e91a8fe5c40'::uuid,'Атамдын үнү угулуп жатат! 🧔','Анын үнүн укканда жүрөгүм ого бетер тез согот! Ага мен да ушул жерде экенимди, салам айтып жатканымды жеткирип коюңузчу! 👋','Issi hääl on siin! 🧔','Kui ma tema häält kuulen, lööb mu süda veel kiiremini! Ütle talle, et mina olen ka siin ja saadan tervitusi! 👋'),
('8564b0d7-d9cc-487d-822b-1f8072415eb2'::uuid,'Сөөктөрүмдү бекемдөөгө жардам бериңиз! 💪','Мага кальций керек, апа. Эгер бир стакан сүт ичип же йогурт жесеңиз, экөөбүз тең абдан күчтүү болобуз! 🥛','Aita mul tugevaid luid kasvatada! 💪','Vajan kaltsiumi, emme. Kui jood klaasi piima või sööd jogurtit, saame mõlemad supertugevaks! 🥛'),
('15ce00b6-4caf-41e5-8ad8-51691c8f30be'::uuid,'Так-так! Ким бар? ✊','Тепкилегендерим кээде катуу сезилип жатабы? Кечириңиз! 🥺 Жөн гана сизге тийгим келип жатат.','Kop-kop! Kes seal on? ✊','Kas mu müksud tunduvad vahel liiga tugevad? Vabandust! 🥺 Ma lihtsalt tahan sind väga puudutada.'),
('b989ed16-7146-4f41-9b58-332ae708a0f2'::uuid,'Дем жетпей жатабы? 😮‍💨','Бир аз өйдөрөөк жылдым, өпкөңүзгө басым жасап жатам. Кечириңиз, апа, жакында ылдый түшөм, ошондо эркин дем аласыз! 🤞','Kas sul on õhupuudus? 😮‍💨','Olen veidi ülespoole nihkunud ja surun su kopsudele. Vabandust, emme, varsti vajun allapoole ja sul on kergem hingata! 🤞'),
('030e064d-37b0-4189-9cde-718dbc4298a7'::uuid,'Мен сиздин жытыңызды тааный баштайм...','Мени кучагыңызга ала турган учурду ойлонуп жатасызбы? Мен да күн сайын ошол учурду кыялданып чоңоюп жатам, апа! 🌸','Hakkan su lõhna ära tundma...','Kas mõtled juba sellele hetkele, mil mind oma süles hoiad? Kasvan iga päev ja unistan sellest hetkest, emme! 🌸'),
('e03f95b4-ad0c-4331-ae04-096968066425'::uuid,'Үйүм бир аз тар болуп баратат... 🏠','Кыймыл-аракетим муштум жана чыканак менен түрткүлөргө айланып баратат. Баары жайындабы? Келиңиз, «Тепкилерди эсептегичти» чогуу текшерип көрөлү!','Mu kodu jääb veidi kitsaks... 🏠','Mu liigutused muutuvad aina tugevamateks löökideks. Kas kõik on korras? Kontrollime koos loote liigutusi!'),
('76a21abd-5509-4070-92f1-19d3342eec20'::uuid,'Таза абага чыгуу убактысы 🌿','Бүгүн үйүбүздөн чыгып, таза абада, жагымдуу жерде чай ичип келсек кандай болот? «Апаларга ыңгайлуу жайлар» функциясын карап көрүүнү унутпаңыз!','Aeg värske õhu jaoks 🌿','Kuidas oleks, kui läheksime täna kodust välja ja naudiksime värskes õhus mõnes mõnusas kohas teed? Ära unusta vaadata meie „Emmesõbralike kohtade“ funktsiooni!'),
('24bc4a35-8099-475a-bea1-67cccf403b8e'::uuid,'Чоң күн жакындап калды! ✨','Шашылыш эч нерсе жок, бирок төрөт үйүнө керектүү сумкабызды акырындап даярдай баштасак болот. «Төрөт үйүнө керектүү буюмдардын тизмесинде» эмнелер бар?','Suur päev on lähenemas! ✨','Pole vaja kiirustada, aga hea mõte on hakata tasapisi haiglakotti pakkima. Mis on „Haiglakoti kontrollnimekirjas“?'),
('c28b4b45-5df1-4c21-963d-2cd627f1bb02'::uuid,'Мага кандай ат коёсуз? 👶','Эгер али чече элек болсоңуз, апа, атасы менен бирге «Ымыркайлардын ысымдары» тизмесин карап көрүңүз. Кайсынысы мага көбүрөөк жарашат деп ойлойсуз?','Mis nime sa mulle paned? 👶','Kui sa pole veel otsustanud, emme, vaata koos issiga beebinimede nimekirja. Milline neist sobib mulle sinu arvates kõige paremini?'),
('c121195f-505c-434b-b2d9-c9f6d23b400a'::uuid,'Менин бөлмөм, бешигим, кичинекей буюмдарым... 🐣','Бизге керектүү нерселердин баарын сатып алдыңызбы? «Сунушталган товарларды» карап көрүңүз, балким бир нерсе унутулуп калгандыр.','Minu tuba, minu voodi, minu asjad... 🐣','Kas oled kõik vajaliku ostnud? Vaata üle soovitatud tooted, äkki on midagi kahe silma vahele jäänud.'),
('c3f0f3b0-ee69-4cef-beda-1bb1348e7009'::uuid,'Жатыныңыздын булчуңдары төрөткө даярданып жатат.','Кабатыр болбоңуз, булар жөн гана машыгуу толгоолору. Эгер ооруу тез-тез кайталана баштаса, «Толгоо таймери» менен аралыгын текшерип көрүңүз!','Sinu emakalihased valmistuvad sünnituseks.','Ära muretse, need on vaid harjutuskontraktsioonid. Kui valud muutuvad sagedaseks, kontrolli nende vahesid kontraktsiooniloenduriga!'),
('8dfa3145-c829-45b1-afeb-aa3c0845ee68'::uuid,'Кичинекей тырмактарым даяр!','Ишенбейсиз, бирок тырмактарым манжаларымдын учуна чейин жетип калды.','Mu väikesed küüned on valmis!','Sa ei usu, aga mu küüned on juba sõrmeotsteni kasvanud.'),
('59ee96ac-8001-4e85-87e8-bcbd686717cb'::uuid,'Дарыгерге көрүнүү убактысы жакындады! 🩺','Төрөт үйүн жана дарыгериңизди тандап бүттүңүзбү? Тандоо үчүн «Дарыгерлер жана клиникалар» тизмесин карап көрүңүз! ✅','Arstivisiite on nüüd tihedamini! 🩺','Kas oled sünnitusmaja ja arsti juba välja valinud? Vaata valikuid „Arstide ja kliinikute“ nimekirjast! ✅'),
('ca64b110-70d5-455b-a30e-4c256cab3188'::uuid,'Бирде күлүп, бирде ыйлап жатасызбы?','Ал гормондор дагы эле өз ишин кылып жатышат! Сиз мени менен жолугушуунун чексиз кубанычы менен төрөт коркунучун аралаш сезип жаткандырсыз. Ичиңиздеги сезимдерди «Маанай күндөлүгүңүзгө» жазып, тынчтык табыңыз. ❤️','Ühel hetkel naerad, teisel nutad?','Hormoonid jälle möllavad! Võid tunda segu sünnitushirmust ja tohutust rõõmust minuga kohtumise ees. Vala oma tunded „Meeleolupäevikusse“ ja leia rahu. ❤️'),
('715eeefe-c617-4bf3-bb6a-6c3fba21c1f5'::uuid,'Мен сизден супер күч алып жатам! 🛡️','Суранам, оорубаңыз, апа! Сиздин иммунитетиңиз менин эң биринчи калканым болот. Биз жеңилгис командабыз! 💪','Saan sinult supervõimed! 🛡️','Palun ära jää haigeks, emme! Sinu immuunsus on minu kõige esimene kilp. Oleme võitmatu meeskond! 💪'),
('c1070439-01ff-45b2-8b26-5012c32a3638'::uuid,'Дагы бир уйкусуз түнбү? 🥺','Мен таттуу уйкудамын. Көзүңүздү жумуп, мени элестетиңиз... Балким, түшүбүз бир жерден кезигип калаар? 🌙','Jälle unetu öö? 🥺','Magasin sügavalt. Pane silmad kinni, kujuta mind ette... Äkki meie uned kohtuvad? 🌙'),
('8be6aa28-e9ad-4b76-b7b7-9a3182c371dc'::uuid,'Сөөктөрүм бекемделип жатат! 🦴','Бирок ушунчалык өсүш үчүн сиздин запастарыңыздан бир аз алып жатам... Ой! 🙈 Келиңиз, бир стакан сүт ичип, экөөбүз тең толуктанып алалыбы? 🥛','Mu luud muutuvad tugevaks! 🦴','Kogu selle kasvu juures laenan ma veidi sinu varusid... Ups! 🙈 Äkki teeme tasa, kui jood klaasi piima? 🥛'),
('80a0c6d7-ffbe-49de-90ea-da3074257deb'::uuid,'Ал ырды дагы бир жолу ырдап бериңизчи! 🎶','Үнүңүз мага ушунчалык бейпилдик тартуулайт... Сиз ырдаганда, ичиңизде бир аз бийлеп алам! Сезип жатасызбы? 💃','Laula seda laulu uuesti! 🎶','Sinu hääl pakub mulle nii palju lohutust... Kui sa laulad, teen ma sees väikese tantsu! Kas tunned seda? 💃'),
('8a02111b-8b8b-4912-a2f8-2e33ed9f29ac'::uuid,'Дубалдар кысып баратат! 🏠','Бул жерде орун абдан тар болуп баратат, апа. Бутумду сунсам эле кабыргаңызга тийип кетет... Эгер оорутуп алсам, өөп койсом баары жакшы болуп кетеби? 💋','Seinad tulevad vastu! 🏠','Mul hakkab siin tõesti kitsas, emme. Sirutan jalga ja see müksab otse su ribidesse... Kui ma sulle haiget teen, kas tohin musi teha ja kõik korda teha? 💋'),
('d8af3bb6-0839-43e8-86c1-22d12e84c887'::uuid,'Кичинекей кийимдерим үтүктөлдүбү? 👗','Мен аларды азыр эле сезип жатам! Мени ошол кичинекей кийимдер менен көргүңүз келип жатканын билем! 🥰','Kas mu pisikesed riided on triigitud? 👗','Ma juba tunnen nende lõhna! Tean, et sa ei jõua ära oodata, millal mind nendes väikestes riietes näed! 🥰'),
('2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b'::uuid,'Мен жолду изилдеп жатам! 🔦','Башым ылдый карап, чыгуучу жолду карап турам. Жөн гана терең дем алыңыз, баары сонун болот!','Uurin teed! 🔦','Mu pea on allpool ja vaatab väljapääsu poole. Hinga lihtsalt sügavalt sisse, kõik saab olema suurepärane!'),
('1f094983-199a-44c0-ba29-5474fcd1ba0b'::uuid,'Бул кимдин жылуу колу? 🖐️','Бул атамбы? Анын колун сезгенде өзүмдү абдан тынч сезем. Ага мен да колумду сунуп жатканымды айтыңызчы – келиңиз, «беш» коюп коёлу! ✋','Kelle soe käsi see on? 🖐️','Kas see on issi? Tunnen end nii rahulikult, kui tunnen tema puudutust. Ütle talle, et mina sirutan ka käe – teeme viis! ✋'),
('586cf1f5-c7b6-4014-aa9e-8da51416de7e'::uuid,'Көздөрүм бакырайып ачык! 👀','Бул жер караңгы болсо да, мен баарын байкап турам! Кимге көбүрөөк окшош болом экен: сизгеби же атамабы? Экөөңүздөр мелдешип көрдүңүздөрбү? 😄','Mu silmad on pärani lahti! 👀','Kuigi siin on pime, jälgin ma kõike! Huvitav, kas ma lähen rohkem sinu või issi nägu? Kas olete juba kihlveo sõlminud? 😄'),
('450a79a5-c3df-4f37-ba9e-30274759f7a8'::uuid,'Шшш... мен уктап жатам! 😴','Мээм абдан тез өнүгүп жаткандыктан, көп уктоом керек. Мага кошулуп эс аласызбы, апа? 🛌','Kuss... ma magan! 😴','Mu aju areneb nii kiiresti, et vajan palju und. Kas tuled minuga koos magama, emme? 🛌'),
('be58ff2d-88eb-4c07-a49c-bb64ed9da351'::uuid,'Уя даярдап жатасызбы? 🌪️','Баарын тазалап, шкафтарды иретке келтиргиңиз келип жатабы... Бул «уя салуу» инстинкти! Бирок ашыкча чарчабаңыз, мага эс алган апа керек.','Kas sa punud pesa? 🌪️','Tahad kõike koristada, kappe korrastada... See on pesitsemisinstinkt! Aga ära pinguta üle, vajan puhanud emmet.'),
('d4a9673c-e78e-49b9-8680-f5a870142dec'::uuid,'Бул жерде бир аз тар болуп баратат! 🏠','Оодарылгым келет, бирок орун жок. Эгер чыканагымды чыгарсам, ичиңиз бир жакка кыйшайып калат. Сиз карап күлөсүз! 😄','Siin jääb veidi kitsaks! 🏠','Tahaksin end keerata, aga ruumi pole. Kui küünarnuki välja lükkan, näeb su kõht viltune välja. Sa vaatad ja naerad! 😄'),
('ad62dd64-4e59-4e08-8d87-d88f11192fd8'::uuid,'Мага пайдалуу майлар керек! 🥑','Авокадо, жаңгак же зайтун майы... Мени толук жана дени сак кылуунун ачкычы сиздин колуңузда!','Vajan tervislikke rasvu! 🥑','Avokaado, kreeka pähklid või oliiviõli... Sinu käes on võti, kuidas mind mõnusalt pontsakaks teha!'),
('7ab48424-114b-4f93-bf60-a6a791cf5a3b'::uuid,'Сиздин жүрөгүңүздүн согушу — менин бешик ырым... 💓','Башым ылдый карап, кулагым жүрөгүңүзгө жакыныраак болуп калды. Ошол ыргак мени чындап тынчтандырган жалгыз музыка.','Sinu südamelöögid on mu hällilaul... 💓','Mu pea on allpool ja kõrv on nüüd su südamele lähemal. See rütm on ainus muusika, mis mind tõeliselt rahustab.'),
('1eaf3d66-fce7-4349-aeaf-3af62fb5c512'::uuid,'Бала бөлмөсү даярбы? 🧸','Бешигимди карап, кыялдарга батып жатасызбы? Ал жерге мени үчүн койгон оюнчукту кучактаган күндү чыдамсыздык менен күтүп жатам! 🥰','Kas lastetuba on valmis? 🧸','Kas vaatad mu võrevoodit ja unistad? Ma ei jõua ära oodata, millal saan kaisutada mänguasja, mille sa mulle sinna panid! 🥰'),
('23ae0c73-2d4e-42be-98d5-a256a7fc152c'::uuid,'Мен ылдый түшүп баратамын, сезип жатасызбы? ⬇️','Мен жамбаш сөөгүңүзгө карай жайгашып жатам. Эми эркин дем аласыз, бирок дааратканага тез-тез чуркайсыз! 🤭','Laskun allapoole, kas sa tunned mind? ⬇️','Olen end su vaagnasse sättimas. Nüüd on sul kergem hingata, aga tualetis pead käima tihedamini! 🤭'),
('10bb8281-56bc-44a1-b78e-8cb23edb7f86'::uuid,'Иммунитетим бекемделип жатат! 🛡️','Сизден алып жаткан антителолорум мени микробдор дүйнөсүнө даярдап жатат. Сүтүңүз да мени коргойт, апа!','Mu immuunsüsteem muutub tugevamaks! 🛡️','Antikehad, mida sinult saan, valmistavad mind ette pisikute maailmaks. Sinu piim kaitseb mind samuti, emme!'),
('2e44c870-ae65-48e2-ad71-57a350b34616'::uuid,'Менин биринчи кийимим кайда? 👕','Төрөт үйүнө керектүү сумкаңызды даярдадыңызбы? Мени кийинте турган кичинекей кийимди акырын сылап коюңузчу...','Kus on mu esimene riietus? 👕','Kas oled haiglakoti pakkinud? Paita õrnalt seda pisikest sipupükste paari, mille mulle selga paned...'),
('deba1190-6096-4dec-88eb-70e669fb3ccb'::uuid,'Сизди көрүүнү чыдамсыздык менен күтөм! 👀','Көзүм ачык, бирок бул жер караңгы. Сиздин жүзүңүздү жана сулуу жылмаюуңузду көрө турган күндү санап жатам. Аз калды! ⏳','Ei jõua sind ära oodata! 👀','Mu silmad on lahti, aga siin on pime. Loen päevi, mil saan näha su nägu ja kaunist naeratust. Enam pole palju jäänud! ⏳'),
('eff2a55b-f3e4-4d2a-b53a-483716c9d978'::uuid,'Терим жылмакай болуп баратат! 🧖‍♀️','Түктөрүм (лануго) түшүп, май катмарым өсүп жатат. Сиздин назик колуңузга даярданып жатам, апа. Мен абдан жумшак болом! ☁️','Mu nahk muutub siledamaks! 🧖‍♀️','Mu peened karvakesed (lanuugo) tulevad maha ja rasvakiht kasvab. Valmistun su õrnadeks puudutusteks, emme. Minust saab nii pehme beebi! ☁️'),
('b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32'::uuid,'Мен күч топтоп жатам! ⚡','Акыркы күндөрү көп кыймылдабай жатамбы? Кабатыр болбоңуз, апа. Азыр мага уйку керек. Чоң күн үчүн бардык күчүмдү топтоп жатам. Сиз да эс алыңыз! 🛌','Kogun jõudu! ⚡','Kas ma ei liiguta viimasel ajal nii palju? Ära muretse, emme. Vajan nüüd und. Kogun kogu jõu suureks päevaks. Puhka sina ka! 🛌'),
('222ef9f4-b496-4bfc-b795-b205f25d7c39'::uuid,'Чыканагымды сездиңизби? 💪','Кечириңиз, апа! Чоюлгум келет, бирок орун аз. Ичиңиз кыйшайып калганда мага күлөсүзбү? 😄','Kas tundsid mu küünarnukki? 💪','Vabandust, emme! Tahan end sirutada, aga mul pole palju ruumi. Kas naerad minu üle, kui su kõht viltu vajub? 😄'),
('4659f949-94b4-4bda-af43-5053a4d85dd9'::uuid,'Пингвиндей басып жатасызбы? 🤭','Төмөн түшкөнүм басыгыңызды өзгөрткөн болушу мүмкүн, бирок ар бир кадамыңызда сиз дүйнөдөгү эң сулуу апасыз! ❤️','Kõnnid nagu pingviin? 🤭','Minu allapoole liikumine võis su kõnnakut muuta, aga igal sammul oled sa maailma kõige ilusam emme! ❤️'),
('fa6077ec-5cef-4d3a-887a-ecb99696e48f'::uuid,'Ик... Ик... 😲','Дагы эле ичим тартылып жатат! Диафрагмамды машыктырып жатам. Эгер ичиңиз ыргак менен секирип жатса, бул мен экенимди биле бериңиз!','Hikk... Hikk... 😲','Mul on jälle luksumine! Harjutan oma diafragmat. Kui su kõht rütmiliselt hüppab, tead, et see olen mina!'),
('ac593045-989b-4db2-a1c0-5cf1b85a8800'::uuid,'Дарыгерге көрүндүкпү? 👩‍⚕️','Ичиңизге сүйкөгөн муздак гель мени кытыгылайт! 🙈 Бирок жүрөгүмдүн согушун угуу сизге тынчтык берерин билем, туурабы?','Kas käisime arsti juures? 👩‍⚕️','See külm geel su kõhul kõditab mind! 🙈 Aga tean, et mu südamelöökide kuulmine toob sulle rahu, eks ole?'),
('f1b0e4ba-30ba-4a1d-82af-0d740c3ae044'::uuid,'Биз бир командабыз! 🤝','Толгоо башталганда коркпоңуз. Терең дем алыңыз. Биз муну чогуу жеңебиз, убада берем!','Oleme meeskond! 🤝','Kui kontraktsioonid algavad, ära karda. Hinga sügavalt sisse. Saame sellest koos üle, luban!'),
('8bb10475-6f0a-4fa8-839d-6d4d4f784276'::uuid,'Төрөт үйүнө керектүү сумкалар даярбы? 🎒','Мен каалаган учурда «Сюрприз!» деп чыгып келишим мүмкүн. Төрөт үйүнө керектүү сумкаңызга мени кийинте турган биринчи баш кийимди салдыңызбы? Тоңуп калгым келбейт! 🧢','Kas haiglakotid on pakitud? 🎒','Võin igal hetkel öelda „Üllatus!“. Kas oled haiglakotti pakkinud selle esimese mütsikese, mille mulle pähe paned? Ma ei taha külmetada! 🧢'),
('884382e7-c971-4251-a601-ff9e5d8d7bc2'::uuid,'Марага аз калды! 🏆','37 жума дээрлик аяктады! Биз азыр мөөнөтүнө жеткен мезгилдебиз. Ошондуктан, бүгүн төрөлсөм да, өпкөлөрүм дем алууга даяр болот!','Finiš on peaaegu käes! 🏆','37 nädalat on peaaegu täis! Oleme nüüd varajase sünnituse perioodis. Nii et isegi kui ma täna sünniksin, oleksid mu kopsud hingamiseks valmis!'),
('9848ae06-dfd4-4fde-8a6f-3787325bfeb8'::uuid,'Сизди түшүмдө көрдүм... 💤','Үнүңүз, жытыңыз, жылуулугуңуз... Ойгонуп, сизди кучактаган күндү чыдамсыздык менен күтүп жатам, апа!','Nägin sinust und... 💤','Sinu hääl, sinu lõhn, sinu soojus... Ma ei jõua ära oodata, millal ärkan ja saan sind päriselt kallistada, emme!'),
('7461f26e-8ba4-4a54-a57e-84bed4745dfc'::uuid,'Ичиңиз катуулашып жатабы? 🤰','Бул жөн гана машыгуубу же чындап эле жолго чыктымбы? Эгер ишенбесеңиз, «Толгоо таймерин» ачыңыз. Ал сизге так айтат: Төрөт үйүнө бара турган убакыт болдубу же эс ала бересизби?','Kas kõht läheb pingule? 🤰','Kas see on alles harjutus või olen tõesti teel? Kui oled ebakindel, ava „Kontraktsiooniloendur“. See ütleb sulle täpselt: kas on aeg haiglasse minna või voodisse tagasi?'),
('0e2e37ee-dd10-44ae-98a1-2379b737ce2b'::uuid,'Мен дагы деле ушул жердемин! 👋','Орунум абдан тар болуп калды, ошондуктан мурдагыдай көп кыймылдабай калышым мүмкүн. Бирок кабатыр болсоңуз, «Тепкилерди эсептегичке» кирип, чогуу эсептейли! 🦶','Olen ikka veel siin! 👋','Mul hakkab siin kitsas, nii et ma ei pruugi enam nii palju liikuda. Aga kui oled mures, ava „Loote liigutuste loendur“ ja loeme koos! 🦶'),
('0add760f-e392-4d33-9e33-dd2c593a0a0c'::uuid,'Байпагымды кийгиздиңизби? 🧦','Тоңгум келбейт, апа! Суранам, «Төрөт үйүнө керектүү буюмдардын тизмесин» акыркы жолу текшерип коюңуз. Менин биринчи кийимим ал жердеби? 🥰','Kas panid mulle sokid jalga? 🧦','Ma ei taha külmetada, emme! Palun kontrolli veel viimast korda „Haiglakoti kontrollnimekirja“. Kas mu kõige esimene riidekomplekt on seal? 🥰'),
('c98ad2e9-dab2-435c-b719-03a62f1368f2'::uuid,'Уйкуңуз качып жатабы? 🥺','Уктай албай жатасызбы? Төрөлгөндө мага угуза турган үндөрдү угуп көрөлү. «Ак ызы-чуу» (White Noise) бөлүмү экөөбүздү тең тынчтандырат. 🌊','Kas uni ei tule? 🥺','Ei saa magama jääda? Kuulame helisid, mida mulle pärast sündi mängid. Valge müra sektsioon rahustab meid mõlemaid. 🌊'),
('73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2'::uuid,'Сумкаларым даяр, эшиктин алдында күтүп жатам! 🚪','38 жума! Мен расмий түрдө жарык дүйнөгө келүүгө даярмын. Өпкөлөрүм, мээм, баары толук өнүгүп бүттү.','Kotid on pakitud ja ootan ukse taga! 🚪','38 nädalat! Olen ametlikult valmis oma suureks saabumiseks. Mu kopsud, aju ja kõik muu on täiuslikult arenenud ja valmis.'),
('b02641e8-c8b3-4941-8bbc-12e86e7720ae'::uuid,'Сууңуз кетсе, эмне кылууну пландадыңыз? 💦','Дүрбөлөңгө түшүүнүн кажети жок! Блог бөлүмүндөгү «Төрөттүн 3 негизги белгиси» деген макаланы окуп чыгыңыз.','Mis on su plaan, kui veed tulevad? 💦','Pole vaja paanitseda! Loe blogist artiklit „Sünnituse 3 peamist märki“.'),
('8013f167-1549-4b4a-8e28-e01b854ddc4c'::uuid,'Мен ылдый түшүп жатам! ⬇️','Жамбаш сөөктөрүңүзгө басым жасап жатканымды билем, апа. Бирок сиз менен жолугушуунун бирден-бир жолу ушул. Менин чыдамкай жана күчтүү апам! ❤️','Liigun allapoole! ⬇️','Tean, et surun su vaagnaluudele, emme. Aga see on ainus viis, kuidas saan sinuga lõpuks kohtuda. Minu kannatlik ja tugev emme! ❤️'),
('d154d2c7-ec75-47ac-ba69-4fbe92885614'::uuid,'Уйкусуз түндөр алдыдабы? 🥱','Төрөт күнү жакындаган сайын, жакшы уктоо кыйындашы мүмкүн. Бул денеңиздин сизди «ымыркай режимине» даярдап жатканы!','Kas ees ootavad unetud ööd? 🥱','Tähtaja lähenedes võib ööuni muutuda katkendlikuks. See on su keha viis valmistada sind ette „beebirežiimiks“!'),
('b3effc18-3aca-4ae1-9929-0aa55b124180'::uuid,'Кичинекей жүрөгүм кандай согуп жатат? 💓','Мени сагынганда, колуңузду ичиңизге коюңуз. Жүрөгүбүз бир согот. Баары жайында; биз жөн гана жолугуша турган күнүбүздү күтүп жатабыз. 🗓️','Kuidas mu süda tuksub? 💓','Kui igatsed mind, pane lihtsalt käsi kõhule. Meie südamed löövad ühes rütmis. Kõik on hästi; me lihtsalt ootame oma kohtumispäeva. 🗓️'),
('777b97b8-95e9-4f43-a5c2-c68495d48777'::uuid,'Ток-ток, бул менмин! ✊','Толгоо келип-кетип жатабы? Убакытты текке кетирбеңиз, «Толгоо таймери» баскычын басыңыз. Эгер аралыгы кыскарып жатса, демек бүгүн ошол чоң күн болушу мүмкүн! 🚑','Kop-kop, see olen mina! ✊','Kas tunned, et kontraktsioonid tulevad ja lähevad? Ära raiska aega, vajuta kontraktsiooniloenduri nuppu. Kui vahed lühenevad, võib täna olla see suur päev! 🚑'),
('23425b07-63ff-4191-a065-718ed3a783d1'::uuid,'«Алтын суюктук» келдиби? ✨','Эмчегиңизден саргыч суюктук чыгып жатканын байкашыңыз мүмкүн, бул ымыркайдын биринчи «вакцинасы» – ууз сүт! Эмчек эмизүү тууралуу блогдорубуздан кененирээк окуңуз. 📖','Kas „vedel kuld“ on juba kohal? ✨','Võid märgata rinnast tulevat kollakat vedelikku, mis on tegelikult beebi esimene „vaktsiin“ – ternespiim! Loe rinnaga toitmise kohta lähemalt meie blogidest. 📖'),
('85c5a987-f8eb-414a-99b9-ec981bbc08cd'::uuid,'Брекстон-Хикс толгоосубу же чыныгыбы? 🤔','Ичиңиз катуулашып, кайра бошоп жатабы? Эгерде толгоо үзгүлтүксүз болбосо, бул Брэкстон-Хикс толгоолору болушу мүмкүн. Ишенүү үчүн, «Толгоо таймерин» ачып, текшерип көрүңүз!','Braxtoni-Hicksi kokkutõmbed või päris asi? 🤔','Kas su kõht läheb kõvaks ja siis jälle lõdvestub? Kui tuhud pole regulaarsed, on need tõenäoliselt Braxton-Hicksi kokkutõmbed. Et kindel olla, ava tuhude loendur ja testi järele!'),
('55b51f8f-337f-485f-a7bb-0d388895d70b'::uuid,'Кан аралаш бөлүнүүлөр барбы? 🩸','Эгерде коюу бөлүнүп чыккан суюктукту байкасаңыз, бул жатын моюнчаңыз жумшарып, ачыла баштаганын билдириши мүмкүн. Кабатыр болбоңуз, апаке, бул денеңиздин даярдануу белгиси!','Määrimine? 🩸','Kui oled märganud paksemat voolust, võib see tähendada, et emakakael hakkab pehmenema ja avanema. Ära muretse, emme, see on lihtsalt su keha märguanne, et aeg on end valmis seada!'),
('e3c60e6b-f031-49de-9d1e-df5e6adaec56'::uuid,'Шап! Бул суу кеткениби? 💦','Эгерде сууңуз кетсе, дүрбөлөңгө түшүүнүн кажети жок. Жөн гана терең дем алып, дарыгериңизге кабарлаңыз. Мен жолдомун! 🌊','Plumps! Kas need olid veed? 💦','Kui looteveed puhkevad, pole vaja paanitseda. Hinga lihtsalt sügavalt sisse ja anna oma arstile teada. Olen teel! 🌊'),
('a7c9fb31-732f-48c9-869e-cb25de2cc6bf'::uuid,'Эс ала турган убакыт келди! 😮‍💨','Толкунданып жатасызбы? «Көнүгүүлөр» бөлүмүнөн «Төрөт учурундагы дем алуу ыкмаларын» азыр үйрөнүп алыңыз. Булар толгоо учурунда абдан керек болот!','Aeg lõõgastuda! 😮‍💨','Tunned elevust? Õpi nüüd selgeks „Sünnitusaegsed hingamistehnikad“ jaotises „Harjutused“. Need on tuhude ajal uskumatult kasulikud!'),
('508da239-e1ff-41bc-b69e-7ac41310e57b'::uuid,'Кыймылдарым азайып жатабы? 🦶','Апаке, мага бул жерде орун аздык кылып жатат! Бирок сиз менин кыймылымды дагы деле сезишиңиз керек. Эгерде тынчсыздансаңыз, таттуураак нерсе жеп, «Тыйпылдарды эсептегичти» колдонуп көрүңүз.','Kas mu liigutused on aeglasemaks jäänud? 🦶','Mul hakkab siin kitsaks jääma, emme! Aga sa peaksid ikka mu liigutusi tundma. Kui oled mures, söö midagi magusat ja kasuta loote liigutuste loendurit.'),
('94a030ca-34dd-44fe-9971-596b00948ae5'::uuid,'Бардык маанилүү документтериңиз даярбы? 📄','Документтер, анализдер... Төрөт үйүнө баштыгыңызды акыркы жолу текшерип алыңыз. «Төрөт үйүнө керектүү буюмдар» тизмесиндеги баарын белгиледиңизби? ✅','Kas kõik tähtsad dokumendid on valmis? 📄','Isikut tõendav dokument, analüüside vastused... Kontrolli haiglakott veel viimast korda üle. Kas oled haiglakoti kontrollnimekirjas kõik märkinud? ✅'),
('8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0'::uuid,'Көзүңүздү жумуңуз... 😌','Төрөттөн коркпоңуз. Мени биринчи жолу кучагыңызга алган учурду элестетиңиз. Ошол жыт баардык ооруну унуттурат.','Pane silmad kinni... 😌','Ära karda sünnitust. Kujuta lihtsalt ette seda hetke, kui mind esimest korda süles hoiad. See lõhn paneb sind kogu valu unustama.'),
('c87d28dc-caee-4571-989c-8e696b1ae968'::uuid,'Жатын моюнчаңыз 🗝️','Жашыруун миссия аткарылууда! Жатын моюнчаңыз жумшарып, ичкерип жана ачылып жатат. Сиз сезбесеңиз да, денеңиз мен үчүн эшикти ачууга даярданууда.','Sinu emakakael 🗝️','Käimas on salajane missioon! Sinu emakakael pehmeneb, õheneb ja avaneb. Isegi kui sa seda ei tunne, valmistub su keha mulle ust avama.'),
('76e46ae6-114d-4692-9572-4e285ec80590'::uuid,'Бүгүн ошол күнбү? 🗓️','Кырк апта толду! Календар бүгүнкү күндү көрсөтүп турат. Азыр келейинби же дагы бир аз күттүрөйүнбү? Каалаган учурда сюрприз кылышым мүмкүн! Даяр болуңуз! 🎁','Kas täna on see päev? 🗓️','Nelikümmend nädalat on täis! Kalender näitab tänast päeva. Kas tulen nüüd või peaksin sind veel natuke ootel hoidma? Võin sind igal hetkel üllatada! Ole valmis! 🎁'),
('98686d18-af97-4647-942d-188f1dec2753'::uuid,'Мен кечиккен жокмун, жөн гана салтанаттуу түрдө келип жатам! 👑','Апаке, эң негизгиси акыркы болуп келет! Дагы бир аз күттүрө турайын, анан сөзсүз келем. Сабырдуу болуңуз! 😌','Ma ei ole hiljaks jäänud, ma lihtsalt teen suurejoonelise sissepääsu! 👑','Ainult tähed teevad oma suure etteaste viimasena, emme! Ma mängin veel natuke raskesti kättesaadavat, siis olen kohal. Ole kannatlik! 😌'),
('0247f27e-7ddb-489d-b670-ca491d8ccd50'::uuid,'Кош бойлуулукка керектүү салмакты кошуп жатам! ⚖️','Бул жерде канчалык көп болсом, ошончолук толуп жатам. Беттерим таттуу болуп баратат, бирок сиздин ишиңиз кыйындап баратат. Кечириңиз! 🙈','Kogun tervislikke raseduskilosid! ⚖️','Iga päev, mil ma siin olen, muutun ma natuke pontšakamaks. Mu põsed lähevad armsamaks, aga sinu töö muutub raskemaks. Vabandust! 🙈'),
('87267b60-6c8e-4a16-ba93-8c4128e465bd'::uuid,'Сумкаңызга жеңил тамак салып алдыңызбы? 🍫','Төрөттөн кийин абдан ачка болосуз! Төрөт үйүнө баштыгыңызга сүйүктүү печеньеңизди же шоколадыңызды салып алыңыз.','Kas panid kotti ka mõne suupiste? 🍫','Pärast sünnitust on sul väga kõht tühi! Lisa oma lemmikküpsised või šokolaad haiglakotti.'),
('8ec6da93-6997-4754-83f8-6c1f12fd0335'::uuid,'Жолдошуңуз (плацента) жетилип жатабы? 🍂','Дарыгер сууңузду текшерип жатабы? Мен кычкылтек алып жаткан учурда эч кандай көйгөй жок. Булар биздин чогуу өткөрүп жаткан акыркы күндөрүбүз.','Kas platsenta on küpsemas? 🍂','Kas arst kontrollib lootevett? Kuni ma hapnikku saan, pole probleemi. Need on lihtsalt meie viimased päevad koos.'),
('5b55999e-5ad0-4f78-afa8-f94623d8adca'::uuid,'Кечээ түнү толгоо болдубу? 🌙','Сизди ойготкон ошол оору... Чыныгы толгообу? Убакытты текке кетирбей, «Толгоо таймерин» иштетиңиз. Балким, бүгүн ошол түн чыгаар! 🚑','Kas tundsid öösel kokkutõmbeid? 🌙','See valu, mis sind üles äratab... Kas see on päris? Ära raiska aega, käivita tuhude loendur. Äkki on täna SEE ÖÖ! 🚑'),
('1f7612ce-6ffd-41c2-b5d1-de2a40214c65'::uuid,'«Жолго чыгуу» убактысы келдиби? 📢','Дарыгер төрөттү стимулдаштыруу жөнүндө айтып жатабы? Кабатыр болбоңуз. Эң негизгиси — менин аман-эсен кучагыңызга келишим. Жол маанилүү эмес!','Kas on aeg minna? 📢','Kas arst räägib esilekutsumisest? Ära muretse. Peamine on see, et jõuaksin turvaliselt sinu sülle. Teekond pole oluline!'),
('4f2c691b-071d-4e41-bb69-0e7f415e73df'::uuid,'Кош бойлуу кезиңиздеги акыркы сүрөтүңүз... 📸','Бул ичиңизди акыркы жолу карап коюңуз. Эртең мен кучагыңызда болушум мүмкүн. Өзүңүздүн кереметтүү денеңиз менен сыймыктаныңыз, апаке!','Sinu viimane rasedusfoto... 📸','Heida veel viimane pilk sellele kõhule. Homme võin ma juba sinu süles olla. Ole uhke oma imelise keha üle, emme!'),
('e6c910e7-1cd4-4a57-af91-421a76624e12'::uuid,'Төрөттү тездетүүнүн табигый жолдору 🍍','Курма менен ананас жатын моюнчасын жумшартат дешет. Бүгүн «Тамактануу» бөлүмүнөн аларды менюңузга кошуп алыңыз. 🥗','Loomulikud viisid sünnituse soodustamiseks 🍍','Öeldakse, et datlid ja ananass pehmendavad emakakaela. Lisa need täna oma menüüsse jaotises „Toitumine“. 🥗'),
('0b2b54c8-9ff4-43bd-80a3-8a3a373a1975'::uuid,'Кичинекей жүрөгүм согуп жатат... ❤️','40 аптадан кийин плацентанын абалын текшерүү үчүн КТГ (кардиотокография) маанилүү. Баары жайында экенине ынаныңыз.','Mu süda tuksub... ❤️','Pärast 40. nädalat on oluline teha KTG (kardiotokograafia), et kontrollida platsenta seisundit. Veendu, et kõik on korras.'),
('52d95173-f625-471a-8fd4-bc36c2714133'::uuid,'Тепкич менен чыгып көрөлүбү? 🪜','Мага жол көрсөтүңүз! Тепкич менен басуу же отуруп-туруу көнүгүүлөрү менин ылдый түшүүмө жардам берет. «Көнүгүүлөр» бөлүмүн караңыз.','Kas ronime trepist üles? 🪜','Juhi mind õigele teele! Trepist käimine või kükid võivad aidata mul allapoole liikuda. Vaata jaotist „Harjutused“.'),
('c54d6aec-cbfd-44de-8deb-f24fc551c345'::uuid,'Бул жерде баары сонун! 🌡️','Жылуу, караңгы жана жайлуу... Чыккым келбей жатат десем, таарынбайсызбы? 🥺 Тамашаладым, мен келе жатам!','Siin sees on kõik imeline! 🌡️','Soe, pime ja hubane... Sa ei pahandaks, kui ütleksin, et ma ei taha veel välja tulla, eks? 🥺 Nalja teen, tulen küll!'),
('e0f642a2-57ae-48a0-88a3-c592939d5139'::uuid,'Кичинекей жүрөгүм кандай согуп жатат? 💓','КТГ үчүн дарыгерге келдикпи? «Дүк-дүк» деген үндү укканда кандай жеңилдеп каласыз...','Kuidas mu süda tuksub? 💓','Kas oleme arsti juures KTG-s? Kui kergendatult sa end tunned, kui kuuled seda „tuks-tuks“ heli...'),
('a43fd2c0-9279-47da-b7ee-4898765553ab'::uuid,'Курма жеп жатасызбы? 🌴','Табигый төрөт үчүн даамдуу аракет кылууга арзыйт!','Kas sööd datleid? 🌴','See on maitsev katsetus loomuliku sünnituse nimel!')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('fcfa5044-061e-4832-8787-ddd94f46ab93'::uuid,'Жаңы сөздөрдү ачуу 🗣️','Бүгүн наристеңиз кандай жаңы сөз айтты?','Uute sõnade avastamine 🗣️','Mis uue sõna nad täna ütlesid?'),
('f9d59314-c8fe-45fa-9d77-efb82ec57626'::uuid,'Кечки күлкүлөр 📸','Уктаар алдындагы анын кызыктуу жоруктарын өткөрүп жибербеңиз!','Õhtune itsitamine 📸','Ära maga maha seda naljakat asja, mida nad enne magamaminekut teevad!'),
('40782485-009f-459f-b399-6e2d09a90f95'::uuid,'Сиз бүгүнкү күндүн баатырысыз! 🌟','Анын күн сайын үйрөнгөн ар бир жаңы жөндөмү – Сиздин мээнетиңиздин натыйжасы.','Oled tänane kangelane! 🌟','Iga uus oskus, mida nad iga päev õpivad, on sinu pühendumuse tulemus.'),
('228ed9a7-6c09-4e18-b632-934b4149caf5'::uuid,'Курсак менен жатуу!','Күн сайын бир нече мүнөт көмкөрөсүнөн жаткыруу анын моюн булчуңдарын бекемдөөгө жардам берет.','Kõhuli olemise aeg!','Mõni minut kõhuli olemist iga päev aitab tugevdada nende kaelalihaseid.'),
('f175db80-862d-40e7-9aed-5b0a0c4423e3'::uuid,'Суу ичүү адаттарын калыптандыруу. 💧','Кошумча тамак менен бирге суу берүүнү унутпаңыз.','Tervislike joomisharjumuste kujundamine. 💧','Ära unusta pakkuda tahke toidu kõrvale vett.'),
('fa5fc8d8-4263-4a99-9f46-297b1d6ea219'::uuid,'Башын жогорураак кармап жатат! 🐢','Көмкөрөсүнөн жатуу убактысын көңүлдүү өткөрүңүз!','Hoiab pead juba kõrgemal! 🐢','Muuda kõhuli olemine lõbusaks!'),
('3ad2c870-178d-449f-aabd-6c01acacefd8'::uuid,'Эмгектеп көрүү аракеттери 🐢','Ал тизелеп, ары-бери термелип жатабы? Демек, сойлогонго даярданууда!','Esimesed roomamiskatsed 🐢','Kas nad on põlvili ja õõtsuvad edasi-tagasi? Nad valmistuvad roomama!'),
('96187549-321c-4f4b-8ab6-e849804b2e3f'::uuid,'Бөбөгүңүз уктап жатканда эс алыңыз! 😴','Бүгүнкү маанайыңызды ''Маанай күндөлүгүнө'' жазып коюуну унутпаңыз.','Puhka, kui beebi magab! 😴','Ära unusta oma tänaseid tundeid ''Meeleolupäevikusse'' kirja panna.'),
('c1c4c9b0-cdd8-4321-a494-3bb43739df94'::uuid,'Сизди жана үнүңүздү таануу! 😍','Бөлмөгө киргениңизде анын кандай сүйүнөрүн байкаңыз. 😊','Tunneb sind ja su häält! 😍','Pane tähele, kui rõõmsaks nad muutuvad, kui sa tuppa astud. 😊'),
('2df49d87-7d2b-44bb-bb5a-a25b24863389'::uuid,'Күндүз менен түндүн айырмасын түшүнө баштадыңызбы? 🛌','Тиркеме аркылуу наристеңиздин уйку режимин жана күнүмдүк тартибин көзөмөлдөңүз, ал уктаганда Сиз да эс алганга аракет кылыңыз.','Kas su arusaam ööst ja päevast on muutunud? 🛌','Jälgi rakenduse abil beebi uneaegu ja igapäevaseid rutiine ning püüa puhata siis, kui nemadki puhkavad.'),
('ded576fe-d3fa-4078-9b83-36eaf5b495d5'::uuid,'Анын өнүгүүсүн кадам сайын байкаңыз. 📏','Салмак көзөмөлдөгүчкө наристеңиздин баш айланасын, боюн жана салмагын киргизүүнү унутуп калдыңызбы? Азыр жазып коюңуз.','Jälgi arengut samm-sammult. 📏','Unustasid beebi peaümbermõõdu, pikkuse ja kaalu andmed kaalujälgijasse sisestada? Tee seda nüüd.'),
('7bc61271-cc44-4b34-a12b-faa852a23b6c'::uuid,'Куттуктайбыз, бөбөгүңүз 2 жумалык болду! 🎈','Бул кичинекей жетишкендикти белгилөө үчүн, ''Наристе фотосессиясы'' бөлүмүндөгү кызыктуу темаларды колдонуңуз.','Palju õnne, beebi on 2-nädalane! 🎈','Selle väikese verstaposti tähistamiseks kasuta beebifotode sektsioonis olevaid põnevaid teemasid.'),
('e2414d34-11c4-4990-9c63-38d30534a147'::uuid,'Сүйлөмдөр узарып баратат 🗣️','Эми ал сөздөрдү бириктирип, өзүнүн өзгөчө логикасы менен кызыктуу сүйлөмдөрдү түзүп жатат. Бул ирмемдерди өткөрүп жибербеңиз; анын ширин сөздөрүн түбөлүккө сактоо үчүн видеого тартып алыңыз.','Laused muutuvad pikemaks 🗣️','Nad panevad nüüd sõnu ritta, moodustades huvitavaid lauseid oma unikaalse loogikaga. Ära maga neid hetki maha; jäädvusta nende armsad dialoogid videole, et neid igavesti meeles pidada.'),
('0ed5afeb-bfa9-4fba-a6c1-40d487f8789c'::uuid,'Бөбөгүңүздүн күчтүү соруу рефлекси! 🍼','Наристеңиздин жетиштүү тамактанып жатканын билүү үчүн, ар бир эмизүү же тамактандыруу убактысын таймер менен көзөмөлдөңүз.','Beebi tugev imemisrefleks! 🍼','Jälgi iga toitmist taimeriga, et veenduda, kas nad saavad piisavalt süüa.'),
('b42303f7-3c77-46e1-97e5-9a1b1e60430c'::uuid,'Түнкү уйкуга даярдануу. 🌙','Уктаар алдында бөлмөнүн температурасын тууралап, Anacan''дын уйку таймерин иштетиңиз.','Ööuneks valmistumine. 🌙','Reguleeri enne magamaminekut toatemperatuuri ja käivita Anacani unetaimer.'),
('e9631c46-1105-44f2-b850-b1671ee6df45'::uuid,'Бүгүн позитивдүү маанайда бололу! ✨','Маанай күндөлүгүңүздү ачып, наристеңиз Сизди эң көп жылмайткан ирмемди жазып коюңуз. Anacan AI Сизди угуп жатат!','Täna on positiivsete emotsioonide päev! ✨','Ava oma meeleolupäevik ja märgi üles hetk, mil beebi sind kõige rohkem naeratama pani. Anacan AI kuulab!'),
('ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f'::uuid,'Караңгыдагы оюндар 🐰','Жарык өчкөндө ал коркуп жатабы? Бөлмөнү толугу менен караңгылатып, кол чырактын жардамы менен дубалга көлөкө оюндарын жасаңыз. Коркунучту кызыктуу оюнга айлантып, караңгылыкка көнүүсүнө жардам бериңиз.','Mängud pimedas 🐰','Kas nad kardavad, kui tuled kustuvad? Tee tuba täiesti pimedaks ja tee taskulambiga seinale varjuteatrit. Aita neil pimedusega rahu teha, muutes hirmu lõbusaks mänguks.'),
('da08e82c-f1b1-4615-9a78-803ac91a2d92'::uuid,'Төрөттөн кийинки депрессияны сезип жатасызбы? 😢','Мындай сезимде болуу толугу менен табигый нерсе! Сиз өз сезимдериңиз менен бөлүшүп, Anacan AI же биздин камкор Коомчулуктан колдоо таба аласыз.','Tunned beebibluusi? 😢','See on täiesti loomulik, et tunned end nii! Saad oma tundeid jagada ja tuge leida Anacan AI-lt või meie hoolivast kogukonnast.'),
('ef4b3736-bd78-46e0-af19-3bceb15bf443'::uuid,'Сыртка сейилдөөгө убакыт келди!','Эс ала турган, балдарга ыңгайлуу жер издеп жатасызбы? Биздин ''Энелерге ыңгайлуу жерлер'' блогубузду сөзсүз окуп чыгыңыз.','Aeg õue jalutama minna!','Otsid lapsesõbralikku kohta, kus saaksid lõõgastuda? Vaata kindlasti meie ''Emadesõbralike kohtade'' blogi.'),
('498afb20-12cf-4e99-872a-93ae66ffadf8'::uuid,'Мүмкүнчүлүк болгондо окуп, үйрөнүңүз. 📚','Жаңы төрөлгөн ымыркайдын өнүгүүсү жана ага кам көрүү боюнча эң пайдалуу макалалар Сизди ''Блогдор'' бөлүмүндө күтөт.','Loe ja õpi alati, kui saad. 📚','Blogide sektsioonis ootavad sind kõige kasulikumad artiklid vastsündinu arengu ja hoolduse kohta.'),
('005f91e2-a696-4de0-bf24-bb840b614746'::uuid,'Өсүү жана салмак кошуу 📏','Шымы кайрадан кичинекей болуп калдыбы? Анын бою тез өсүп жатат! Учурдагы өлчөмдөрүн Өнүгүү көзөмөлдөгүчүнө киргизип, уйкусуз түндөрүңүздүн үзүрү болгон өсүү ийри сызыгын сыймыктануу менен байкаңыз.','Kasvu- ja kaaluhüpe 📏','Kas püksid jäid jälle väikseks? Neil on kasvuspurt! Sisesta praegused mõõdud arengujälgijasse ja vaata uhkusega tõusvat kasvukõverat – sinu unetute ööde vili.'),
('a1d43ae2-7007-4910-b05d-6c1d71529cf9'::uuid,'Биринчи текшерүүгө убакыт жакындап калды.','Наристеңиздин ушул күнгө чейинки салмагын жана боюн ''Өсүү көзөмөлдөгүчү'' бөлүмүнө жазып коюуну унутпаңыз.','Esimene kontrollaeg läheneb.','Veendu, et salvestad beebi kaalu ja pikkuse kasvu arengujälgija sektsioonis.'),
('2b4adff1-6ebf-471c-9dc4-e4e39cc16323'::uuid,'Көңүл буруу убактысы узарып баратат!','Эми наристеңиз ак жана кара контрасттуу түстөрдү алда канча жакшы ажырата алат. Көмкөрөсүнөн жаткан учурда жогорку контрасттуу карточкаларды колдонууну унутпаңыз.','Tähelepanuvõime kasvab!','Sinu beebi suudab nüüd mustvalgeid kontrastsuseid palju paremini eristada. Ära unusta kõhuli olemise ajal kasutada kontrastseid kaarte.'),
('5e1b47e3-2994-433f-a7c8-b1e6a121de30'::uuid,'Акыркы жолу кайсы эмчектен эмизгениңизди унутуп калдыңызбы? 🤱','Таймердин жардамы менен оң же сол эмчектен эмизип жатканыңызды белгилеңиз, ал эми ''Тамактануу көзөмөлдөгүчү'' баарын эстеп калат!','Unustasid, kummast rinnast viimati toitsid? 🤱','Märgi taimeriga, kas toidad paremast või vasakust rinnast, ja lase toitmise jälgijal kõike meeles pidada!'),
('77ad5a07-cc0a-4fb4-b323-d177412300b1'::uuid,'Апталык статистикаңыз даяр! 📊','Акыркы күндөрү уйку жана тамактануу сунуштарын канчалык деңгээлде аткарып жатканыңызды талдоо үчүн тиркемеге кириңиз.','Sinu iganädalane statistika on valmis! 📊','Logi rakendusse sisse, et analüüsida, kui hästi oled viimastel päevadel une- ja toitumissoovitusi järginud.'),
('fee5ed13-dd9c-4182-b62b-254289a55cec'::uuid,'Бөбөгүңүздү уктатуу кыйын болуп жатабы? 🎶','Тиркемебиздеги ''Ак ызы-чуу'' куралын күйгүзүп, наристеңизге эненин курсагындагыдай терең уйкуга кетүүсүнө жардам бериңиз.','Kas beebi uinumine on raske? 🎶','Lülita meie rakenduses sisse ''Valge müra'' tööriist ja aita beebil sügavasse unne vajuda, täpselt nagu nad tegid emaüsas.'),
('8fac7e6d-3d63-4646-99a7-c927a088e849'::uuid,'Таза аба табитти ачат!','Наристеңизди күн сайын таза абага алып чыгууну унутпаңыз. Бул Сиз үчүн да, кичинекейиңиз үчүн да абдан пайдалуу.','Värske õhk parandab söögiisu!','Veendu, et viid beebi iga päev õue. See on väga kasulik nii sulle kui ka sinu pisikesele.'),
('dd0fbf42-9f2a-4cb9-8c66-db4c46ee2124'::uuid,'Эне сүтүнүн сапатын жогорулатыңыз. 🍲','Ден соолукка пайдалуу жана даамдуу тамактар үчүн тиркемедеги ''Пайдалуу рецепттер'' бөлүмүн карап чыгыңыз.','Tõsta rinnapiima kvaliteeti. 🍲','Tervislike ja maitsvate toitude jaoks vaata rakenduse tervislike retseptide sektsiooni.'),
('4d0ac53a-0a7d-40d8-a958-4dd99382d977'::uuid,'Себепсиз ойгонуулар 😭','Түн ортосунда кыйкырып ойгондубу? Сарсанаа болбоңуз. Бул өсүү оорусубу же түнкү коркуубу экенин билүү үчүн ''ыйды талдоо куралын'' колдонуңуз, андан соң аны акырын бооруңузга кысыңыз.','Seletamatud ärkamised 😭','Ärkas keset ööd karjudes? Ära paanitse. Kasuta ''nutuanalüüsi tööriista'', et näha, kas tegemist on kasvuspurtist tingitud valuga või öise hirmuhoohoogudega, ja seejärel kaisuta neid rahulikult.'),
('45b225f1-1304-44c7-93ed-fd6649d6138a'::uuid,'Киндик кургак жана таза болушу керек. ⏱️','Эгерде киндик калдыгы суу болуп калса, аны жакшылап кургатуу керек жана дарыгериңиз жазып берген антисептик эритмени күн сайын сүйкөп туруу зарыл.','Nabanödi peab püsima kuiva ja puhtana. ⏱️','Kui nabanööri könt saab märjaks, tuleb see põhjalikult kuivatada ja kanda sellele iga päev arsti määratud antiseptilist lahust.'),
('7a36ad44-2dba-4854-82a6-8b3c27a56c6f'::uuid,'Муздак кофе ичкиңиз келип жатабы? ☕','Кофе куюп, аны 3 сааттан кийин ичүү – энеликтин жазылбаган мыйзамы. Бүгүн башкача кылыңыз. Балаңызды оюнчуктары менен калтырып, ошол кофени 10 мүнөттүн ичинде ысык бойдон ичип ырахат алыңыз!','Jääkohvi isu ☕','Kohvi valamine ja selle 3 tundi hiljem joomine on emaduse mitteametlik seadus. Täna tee midagi teisiti. Jäta laps mänguasjadega ja naudi seda kohvi kuumalt 10 minuti jooksul!'),
('ed8acfc1-dd31-48da-a8f2-04bd91f60de7'::uuid,'Өзүңүзгө ыраазы болуңуз! 💖','Сиз эң татаал болгон биринчи айды артта калтырдыңыз. ''Маанай күндөлүгүнө'' кирип, бул айдагы баатырдык жетишкендигиңизди жазып коюңуз.','Tänan iseennast! 💖','Oled läbinud esimese ja kõige keerulisema kuu. Ava oma meeleolupäevik ja märgi üles selle kuu kangelaslik saavutus.'),
('2037f6e8-905d-4847-8172-fdba3ba09cf5'::uuid,'Кечки тартибиңиз бузулдубу? 🌙','Кабатыр болбоңуз! Наристеңиз өзүн эненин курсагындагыдай коопсуз сезиши үчүн ''Ак ызы-чуудан'' жүрөктүн кагышынын үнүн тандаңыз.','Kas õhtune rutiin on sassis? 🌙','Ära muretse! Vali valge müra hulgast südamelöökide heli, et aidata beebil tunda end sama turvaliselt kui emaüsas.'),
('63fcc8ee-0343-4d14-8f0d-e6d98a5377e8'::uuid,'Кээде сизге жөн гана кичинекей тыныгуу керек. ☕','Наристеңиз уктаганда, ''Уйку таймерин'' иштетип, өзүңүзгө тынч убакыт бөлүңүз.','Mõnikord on vaja lihtsalt väikest pausi. ☕','Kui beebi magab, käivita unetaimer ja võta endale veidi rahulikku aega.'),
('b61a8e62-d1c0-449f-9d5b-6bb72079c512'::uuid,'Ойгоо убактысы узарып баратат.','Аны менен чогуу убакыт өткөрүү жана өнүгүүсүн колдоо үчүн ''Блогдор'' бөлүмүндөгү оюн сунуштарын окуп чыгыңыз.','Ärkveloleku aeg pikeneb.','Loe blogide sektsioonist mängusoovitusi, mis aitavad sul nendega suhelda ja nende arengut toetada.'),
('a63353e6-5360-4f33-ba4b-ae8f83d9831a'::uuid,'Энелер үчүн витаминдүү тамактануу: Өтө маанилүү! 🥗','Күч-кубатыңызды калыбына келтирүүгө жардам берген ''Пайдалуу рецепттер'' бөлүмүбүз менен таанышып чыгыңыз.','Vitamiinirikas toitumine emale: nii oluline! 🥗','Tutvu meie tervislike retseptide sektsiooniga, mis aitab sul jõudu ja energiat taastada.'),
('111e6f27-8aef-4cfb-a5ab-60fea52474e0'::uuid,'Кийинки айга даярдануу. 🛒','Эгерде наристеңиздин жаңы айына ылайыктуу жалаяк жана кам көрүү каражаттарын издеп жатсаңыз, биздин ''Сунушталган өнүмдөр'' бөлүмүбүз Сизге сөзсүз пайдалуу болот.','Valmistumine järgmiseks kuuks. 🛒','Kui otsid beebi uue kuu jaoks sobivaid mähkmeid ja hooldustooteid, on meie soovitatud toodete sektsioon kindlasti abiks.'),
('713d2aac-0316-483d-9c46-781631bb7e21'::uuid,'Сиз укмуштуудай энесиз!','Сиздердин бирге болгонуңуздарга 30 күн болду! ''Наристе альбомуна'' анын биринчи күнү менен бүгүнкү күндүн айырмасын көрсөткөн коллаж кошуңуз.','Oled imeline ema!','Olete koos olnud 30 päeva! Lisa beebialbumisse kollaaž, mis näitab erinevust nende esimese päeva ja tänase vahel.'),
('b24ba903-09d2-4243-a80b-995524b45caf'::uuid,'Күндүзгү уйкудагы кыйынчылыктар 🥱','Уктоодон таптакыр баш тартып жатабы? 2,5 жаштын тегерегинде кээ бир балдар күндүзгү уйкусун таштай башташат. Уктоого мажбурлоонун ордуна, аны 30 мүнөттүк ''Тынч китеп окуу убактысы'' менен алмаштырыңыз.','Probleemid uinakutega 🥱','Keeldub kategooriliselt magama minemast? Umbes 2,5-aastaselt hakkavad mõned lapsed päevaseid uinakuid ära jätma. Selle asemel, et und sundida, asenda see 30-minutilise ''rahuliku lugemisajaga''.'),
('5bfad78e-cb6a-405d-8517-a356018909ca'::uuid,'Өсүүсү жана салмак кошуусу кандай? 📏','Жаңы жетишкендиктерди ''Өсүү көзөмөлдөгүчү'' бөлүмүнө киргизип, балаңыздын жеке өнүгүү диаграммасын карап чыгыңыз.','Kuidas kasv ja kaalutõus edenevad? 📏','Logi uued verstapostid arengujälgija sektsiooni ja vaata üle oma lapse personaliseeritud arengugraafik.'),
('d87d1938-6445-47b1-b0eb-19c7a9941726'::uuid,'Таза аба издеп!','Наристеңиз менен ыңгайлуу сейилдөө үчүн, коляска менен басууга ылайыктуу жакын жерди тандаңыз.','Värske õhu otsingul! 🌳','Mugavaks väljasõiduks beebiga vali lähedalolev koht, kuhu pääseb hõlpsasti lapsevankriga.'),
('fa1d2aaa-c80f-46e8-82ed-6c8fa2ce54f1'::uuid,'Anacan AI ар дайым сиздин жаныңызда! 🤖','Анын уйку режими боюнча суроолоруңуз барбы? Жөн гана биздин AI''дан сураңыз, ал дароо жооп берет!','Anacan AI on alati sinu jaoks olemas! 🤖','Kas sul on küsimusi nende unerutiini kohta? Lihtsalt küsi meie AI-lt ja saad kohese vastuse!'),
('0ac0ad4d-776b-416d-a345-c0bddd639ff1'::uuid,'Бөбөгүңүздүн көңүл буруусу жакшырып баратат! 👀','Наристеңиздин бөлмөдөгү буюмдарды кантип карап, ээрчип жатканын байкаңыз. Анын өнүгүүсү тууралуу көбүрөөк маалымат алуу үчүн биздин ''Блогдор'' бөлүмүнө кириңиз.','Beebi keskendumisvõime paraneb! 👀','Jälgi, kuidas beebi ruumis objekte jälgib. Rohkem teadmisi nende arengu kohta leiad meie blogidest.'),
('c7ce3717-a6e8-4d86-ba21-d6964fb4fd5f'::uuid,'Энелерге энергия керек! 🍳','Биздин пайдалуу рецепттерибизден даярдоого оңой, даамдуу смузи менен күч-кубатыңызды калыбына келтириңиз.','Emad vajavad energiat! 🍳','Taasta oma energia maitsva ja lihtsalt valmistatava smuutiga meie tervislike retseptide hulgast.'),
('282baeb2-eb26-44cb-9eff-2eb2d88677a2'::uuid,'Күндүн чарчоосун жууп салыңыз. 🛁','Бүгүн өзүңүзгө убакыт бөлүп, сезимдериңизди ''Маанай күндөлүгүнө'' жазуу менен эс алыңыз.','Pese päeva väsimus maha. 🛁','Võta hetk iseendale ja lõõgastu, kirjutades täna oma tunded meeleolupäevikusse.'),
('77d01c80-0ffb-4089-a192-db04bf909aa1'::uuid,'Уктай албай жатасызбы? 🌙','Кичинекейиңиз терең уйкуга кетип жатканда, ''Ак ызы-чуудан'' океан толкундарынын үнүн тандап, бир аз тынчтык табыңыз.','Kas uinumine on raske? 🌙','Vali valge müra hulgast ookeanilainete heli ja leia rahu, samal ajal kui su pisike sügavasse unne vajub.'),
('367f3154-4760-43d6-b507-b914372b7538'::uuid,'Жылмаюуга даярданыңыз! 😊','Ал сүйкүмдүү социалдык жылмаюулар каалаган убакта башталышы мүмкүн! Камераңызды даяр кармаңыз.','Valmistu naeratusteks! 😊','Need armsad sotsiaalsed naeratused võivad alata igal hetkel! Hoia kaamera valmis.'),
('e8719824-5aaa-4cf3-a9a0-c265fa3bf36c'::uuid,'Алар сизди жытыңыздан жана үнүңүздөн тааныйт! 👃','Ошондуктан Сиз бөлмөдөн чыкканда, наристеңиз өзүн тынчсызданып же коопсуз эмес сезиши мүмкүн.','Nad tunnevad sind lõhna ja hääle järgi! 👃','Seetõttu võib beebi tunda end ebakindlalt või ebaturvaliselt, kui toast lahkud.'),
('afe3841b-76da-4cfe-9cf7-b2077153f607'::uuid,'Биринчи «гу-гу» үндөрүн угуу!','Анын кеп өнүгүүсүн колдоо үчүн, ал чыгарган үндөрдү кайталап, аны менен сүйлөшүңүз.','Esimesed kurguhääled!','Nende keelelise arengu toetamiseks korda helisid, mida nad teevad, ja räägi nendega.'),
('22e06076-dd91-4e1b-834c-b78c42879a13'::uuid,'Үйдөн сырткары ыңгайлуулук. ☕','Курбуларыңыз менен жолугушууну пландап жатасызбы? Биздин ''Энелерге ыңгайлуу жерлер'' картабызды карап чыкпастан үйдөн чыкпаңыз!','Mugavus kodust eemal. ☕','Planeerid sõpradega kokkusaamist? Ära lahku kodust enne, kui oled kontrollinud meie emadesõbralike kohtade kaarti!'),
('54501d8f-f370-4895-a96c-448bca275b4e'::uuid,'Төмөн караңызчы, ал жерде эмне бар? 👣','Ал жылаңайлак басып, ар кандай беттерге (кум, килем, таш) тийгенди өзгөчө жакшы көрөбү? Таманындагы нервдердин стимулдашуусу анын неврологиялык өнүгүүсү үчүн баа жеткис мааниге ээ.','Vaata alla, mis seal on? 👣','Kas neile meeldib eriti paljajalu kõndida ja erinevaid pindu (liiv, vaip, kivi) puudutada? Taldade närvilõpmete stimuleerimine on nende neuroloogilisele arengule hindamatu väärtusega.'),
('56603835-e00b-48c0-82ab-bbdf1844d6ac'::uuid,'Жакшы тартип уйкунун сапатын жогорулатат. 🛁','Наристеңизди киринтип, тамактандырыңыз, андан соң тиркемеде анын күнүмдүк уйку режимин көзөмөлдөө үчүн уйку таймерин колдонуңуз.','Hea rutiin parandab une kvaliteeti. 🛁','Vannita beebit, toida neid ja kasuta seejärel unetaimerit, et jälgida rakenduses nende igapäevaseid unerežiime.'),
('173da4aa-4d6e-4106-ab0c-34773a383b02'::uuid,'Курсак менен жатуу убактысы узарып баратат! 🐢','Эми наристеңиз башын алда канча туруктуу кармап калды. Моюнду бекемдөөчү бул көнүгүүлөрдү күнүмдүк тартибиңизге кошуңуз.','Kõhuli olemise aeg pikeneb! 🐢','Sinu beebi hoiab nüüd pead kindlamalt. Lisa need kaela tugevdavad harjutused oma igapäevarutiini.'),
('3c5122e2-a92c-4444-baa3-d7b7fdd4786f'::uuid,'Жалаяк алмаштыруу статистикаңызды текшерип көрөлү! 📊','Anacan тиркемесине кирип, наристеңиздин акыркы күндөрдөгү жалаяк маалыматтарын салыштырыңыз. Баары жайындабы?','Kontrollime mähkmevahetuse statistikat! 📊','Logi Anacani rakendusse ja võrdle beebi viimaste päevade mähkmeandmeid. Kas kõik tundub korras olevat?'),
('041b2f2c-3594-4ff1-96a1-f589206d267b'::uuid,'Тамактануу жана тыныгуулар. 🤱','''Тамактануу көзөмөлдөгүчү'' куралын колдонуп, ар бир тамактануу убактысын белгилөө менен күнүмдүк тартибиңизди оптималдаштырыңыз.','Toitmine ja pausid. 🤱','Optimeeri oma rutiini, ajastades iga toitmise toitmise jälgija tööriistaga.'),
('bae9c6f0-b7fe-4fe9-ba7a-7ba60aceb9ec'::uuid,'Кандайсыз, кымбаттуу эне? 💖','Кээде баары оор сезилиши мүмкүн. ''Маанай күндөлүгүңүздү'' ачып, ойлоруңузду жана сезимдериңизди эркин жазыңыз.','Kuidas sul läheb, kallis ema? 💖','Mõnikord võib kõik tunduda üle jõu käivana. Ava oma ''meeleolupäevik'' ja vala oma mõtted ja tunded vabalt välja.'),
('cb8cc6b6-0d64-4498-81ae-bc15f03ad73b'::uuid,'Бөбөгүңүздүн терисине өзгөчө кам көрүү. 🧴','Наристеңиздин баркыттай жумшак териси үчүн эң мыкты өнүмдөрдү биздин ''Энелер жактырган өнүмдөр'' блогубуздан табыңыз.','Erihooldus beebi nahale. 🧴','Avasta meie ''Emade poolt heakskiidetud toodete'' blogist parimad tooted oma beebi sametpehmele nahale.'),
('47a30b46-d385-4b3c-979c-5465d481ef29'::uuid,'Ичтеги газды кетирүү үчүн кыймылдоо! 🚴','Наристеңиз велосипед тебүү кыймылдарын жасап жатканда, аны алаксытуу жана тынчтандыруу үчүн фондо ''Ак ызы-чууну'' күйгүзүп коюңуз.','Liikumine gaasivalude leevendamiseks! 🚴','Kui beebi teeb jalgrattaliigutusi, mängi taustal valget müra, et neid nii lõbustada kui ka rahustada.'),
('a7868664-8e30-4849-9648-70deec39cf3a'::uuid,'6 жумалык өнүгүү секириги жакындап калды! 📈','Наристеңиз кадимкиден көбүрөөк ыйлап жатышы мүмкүн. Бул өнүгүү баскычын жана анын себептерин түшүнүү үчүн ''Блогдор'' бөлүмүн карап чыгыңыз.','6-nädalane arenguhüpe on lähenemas! 📈','Beebi võib nutta tavapärasest rohkem. Uuri blogide sektsiooni, et mõista seda arenguetappi ja selle põhjuseid.'),
('ba4d5548-5eb3-44e1-bb68-bbab9deb11ee'::uuid,'Аталар иш үстүндө: Биргелешкен кам көрүү убактысы. 👨‍🍼','Кечки тамактануудан кийин, атасы анын кекиришине жардам берсин, ал эми Сиз бир аз көз ирмеп эс алып алыңыз.','Isad tegutsevad: ühine hooldusaeg. 👨‍🍼','Pärast õhtust toitmist lase issil tegeleda röhitamisega, samal ajal kui sina teed kiire uinaku.'),
('2a04ee0c-770e-425b-8987-e6ab25472f0b'::uuid,'Эне сүтүн көбөйтүүнүн табигый жолдору. 🥛','Сүтүңүздү көбөйткүңүз келеби? Биздин ''Пайдалуу рецепттер'' бөлүмүндөгү аш болумдуу шорпо жана суусундук рецепттерин жасап көрүңүз.','Looduslikud viisid rinnapiima koguse suurendamiseks. 🥛','Soovid piimatootmist suurendada? Proovi meie tervislike retseptide sektsioonis olevaid toitvate suppide ja jookide retsepte.'),
('6a605601-9da6-47e9-8d07-a1f552eb5fc0'::uuid,'Күнүмдүк тамактануу жана уйкуну тең салмактоо. ⚖','Эртеңки күндү пландаштыруу үчүн ''Тамактанууну көзөмөлдөө'' жана ''Уйку диаграммаларынан'' бүгүнкү статистиканы талдап чыгыңыз.','Igapäevase toitmise ja une tasakaalustamine. ⚖','Analüüsi tänaseid toitmise ja une graafikute statistikat, et planeerida järgmist päeva.'),
('2dcd9888-3b4b-4cb6-a25a-51c4642e3c54'::uuid,'Биздин 40 күндүк чилде мезгилибиз бүгүн аяктады! 🧿','Бул өзгөчө жана салттуу күндү унутулгус кылуу үчүн ''Наристе фотосессиясы'' бөлүмүнөн кызыктуу темаларды тандап, кооз сүрөттөрдү жаратыңыз.','Meie 40-päevane sünnitusjärgne periood lõpeb täna! 🧿','Muuda see eriline ja traditsiooniline päev unustamatuks, valides põnevaid teemasid ja luues kauneid pilte meie beebifotode sektsioonist.'),
('92e4d1aa-c4f4-477c-ab81-176ef4f03a16'::uuid,'Тынч уйкуга өтүңүз. 🌙','Бул өзгөчө күндүн аягында жарыкты басаңдатып, «Ак ызы-чуу» (White Noise) функциясын иштетиңиз жана бөбөгүңүз терең уйкуга кеткенде өзүңүз да тынч эс алыңыз.','Rahulikku uinumist. 🌙','Selle erilise päeva lõpus hämarda tuled, lülita sisse valge müra ja naudi rahulikku und, kuni su beebi sügavasse unne suigub.'),
('ba92608f-780e-4381-a0e7-3f6af86021be'::uuid,'Кандайсыз? ✨','Сиз маанилүү жана өзгөчө 40 күндүк мөөнөттү артта калтырдыңыз! Сиз чыныгы баатырсыз!','Kuidas sa end tunned? ✨','Oled läbinud märkimisväärse ja erilise 40-päevase perioodi! Oled tõeline kangelane!'),
('6dd4f975-8504-4871-83c4-a6f7bc24a950'::uuid,'Күнүңүз кандай өттү? 📝','Бир чыны кофе ичип, бүгүн «Маанай күндөлүгүңүзгө» өз ой-сезимдериңизди жазып, эс алыңыз.','Kuidas su päev möödus? 📝','Vala endale tass kohvi ja lõõgastu, kirjutades täna oma mõtted ja tunded meeleolupäevikusse.'),
('c6c2469c-d36e-4ffe-a532-bee6050f4bac'::uuid,'Чилдеден кийинки жаңы барак! 🌸','Бөбөгүңүз айлана-чөйрөгө көбүрөөк кызыга баштады. Өнүгүүсү үчүн когнитивдик стимулдаштыруучу карталарды колдонуу пайдалуу болот.','Uus peatükk pärast 40-päevast perioodi! 🌸','Sinu beebi tunneb ümbritseva vastu üha suuremat huvi. Kognitiivsed arenduskaardid võivad tema arengule kasuks tulla.'),
('d647162e-98ae-41c0-81b4-cc5ca3e15dff'::uuid,'Тамактануу тартиби кандай болуп жатат? 🍼','Күнүмдүк сунуштамаларды канчалык деңгээлде аткарып жатканыңызды текшерүү үчүн тиркемедеги «Тамактандыруу трекери» жана таймерди колдонуңуз.','Kuidas toitmine edeneb? 🍼','Kasuta rakendusesisest toitmise jälgijat ja taimerit, et kontrollida, kui hästi sa igapäevaseid soovitusi järgid.'),
('06dbea83-4e3d-4be5-8968-0961033df8d5'::uuid,'Түстөрдү жакшыраак айырмалоо! 🔴','Бөбөгүңүздүн көздөрү бөлмөдөгү жаркыраган нерселерди кантип ээрчип жатканына көңүл буруңуз.','Värvide eristamine paraneb! 🔴','Pane tähele, kuidas su beebi silmad jälgivad toas liikuvaid erksavärvilisi esemeid.'),
('295afbf2-1104-44c2-abf4-fb0e41a0ff0e'::uuid,'Таза аба экөөңүзгө тең пайдалуу. 🌳','Сейилдөөгө чыкканда, биздин «Энелер үчүн ыңгайлуу жайлар» картасынан коляска менен барууга ыңгайлуу жерди тандаңыз.','Värske õhk tuleb teile mõlemale kasuks. 🌳','Kui lähed jalutama, vali meie emmesõbralike kohtade kaardilt lapsevankriga hõlpsasti ligipääsetav sihtkoht.'),
('9f7dfdf1-83be-4fad-a93a-817e105844ce'::uuid,'Уйкуга өтүүнү жеңилдетиңиз. 🌙','Кечки жуунуудан кийин, бөбөгүңүздү терең жана тынч уйкуга даярдоо үчүн «Ак ызы-чуу» бөлүмүнөн чач кургаткычтын же жамгырдын үнүн тандаңыз.','Muuda uinumine sujuvamaks. 🌙','Pärast õhtust vannitamist vali valge müra hulgast fööni- või vihmaheli, et aidata beebil sügavasse ja kosutavasse unne jääda.'),
('2e317973-be56-4e35-b4da-81c9dc7b1f3d'::uuid,'Пландуу текшерүүлөр башталат. 💉','Бөбөгүңүздүн бою менен салмагын «Өсүү трекерине» киргизип, анын жеке өсүү графигин түзүңүз!','Rutiinsed kontrollid algavad. 💉','Loo oma beebile isikupärastatud kasvugraafik, sisestades tema pikkuse ja kaalu arengu kasvu jälgijasse!'),
('431cbe5a-0f52-442d-a6e8-ab53cd482a5f'::uuid,'Күнүмдүк статистикаңыз даяр! 📊','Бөбөгүңүз бүгүн канча уктап, канча тамактанганын көрүү үчүн тиркемедеги графиктерди талдап чыгыңыз.','Sinu päevastatistika on valmis! 📊','Analüüsi rakenduses olevaid graafikuid, et näha, kui palju su beebi täna magas ja sõi.'),
('c4adf9ce-d711-4011-af60-94f404f59ae5'::uuid,'Өсүү жана салмак кошууну көзөмөлдөө! 📏','Бөбөгүңүздүн акыркы өлчөөлөрүн «Өсүү трекерине» жаңыртып, анын дени сак өсүү графигине суктаныңыз!','Kasvu ja kaalutõusu jälgimine! 📏','Uuenda beebi uusimad mõõdud kasvu jälgijas ja imetle seejärel tema tervisliku arengu graafikut!'),
('7212233e-c5da-4c83-bd8d-a74e469e3fcc'::uuid,'Жарыкты басаңдатыңыз 🌙','Уйкуга 1 саат калганда үйдөгү бардык ачык жарыктарды жана көк экрандарды өчүрүңүз. Мелатонин гормонунун иштеши үчүн үйдө кечки тынч чөйрө түзүңүз.','Hämarda tuled 🌙','Tund enne magamaminekut lülita kodus välja kõik eredad tuled ja sinised ekraanid. Loo õhtune rahulik keskkond, et soodustada melatoniini tootmist.'),
('1af46170-3a5b-41ea-bb18-ce899698f996'::uuid,'Биринчи күнүңүз кут болсун! 🥳','Бөбөгүңүздүн уйкусун жана тамактануу тартибин көзөмөлдөө үчүн Anacan тиркемесиндеги таймерди колдоно баштаңыз.','Head esimest päeva! 🥳','Alusta Anacani rakenduses taimeri kasutamist, et jälgida beebi une- ja toitumisgraafikut.'),
('ffb18a7a-0d53-482c-b130-00223f89efd3'::uuid,'Апалар үчүн энергия булактары! 🥗','Калыбына келүүңүзгө жардам берүү үчүн тиркемедеги «Аялдар үчүн пайдалуу рецепттер» бөлүмүнөн витаминге бай жана даамдуу тамак тандаңыз.','Energiaallikad emadele! 🥗','Taastumise toetamiseks vali rakenduse tervislike retseptide jaotisest vitamiinirikas ja maitsev roog.'),
('40712cc0-bb4b-4d42-9a36-7942cb47a970'::uuid,'Добуштарга көбүрөөк реакция кылуу! 🎶','Бөбөгүңүз сиздин үнүңүздү укканда тынчтанып калганы кандай сонун, ээ? Бул таттуу көз ирмемдерди «Бөбөк альбомунда» түбөлүккө сактап калыңыз.','Reageerib helidele üha enam! 🎶','Kas pole imeline, kuidas beebi sinu häält kuuldes rahuneb? Hoia neid magusaid hetki igavesti beebialbumis.'),
('efc5b454-d92c-49c6-a2a5-9e995c6d9a84'::uuid,'Дарыгерге көрүнүүдөн чочулоо 🤖','2,5 жаштагы бала үчүн зарыл болгон эмдөөлөр же витаминдер боюнча күмөнүңүз барбы? Коркунучтуу интернет форумдарында адашпаңыз; «Anacan AI» аркылуу дароо так жооп алыңыз.','Ärevus arstivisiidi eel 🤖','Kas sul on kahtlusi 2,5-aastase lapse vaktsineerimise või vitamiinide osas? Ära eksle hirmutavates foorumites, vaid saa koheseid ja täpseid vastuseid Anacan AI-lt.'),
('aa025645-c5cd-4f2b-840e-6fb50bb6398b'::uuid,'Соода кылуу керекпи? 🛍','Бөбөгүңүздүн жаңы өнүгүү баскычына ылайыктуу кам көрүү каражаттары же оюнчуктар үчүн биздин «Сунушталган товарлар» тизмесин карап чыгыңыз.','On vaja sisseoste teha? 🛍','Tutvu meie soovitatud toodete nimekirjaga, et leida beebi uue arenguetapi jaoks vajalikke tarbeid või mänguasju.'),
('c6ae0bdf-11e6-43d9-a0ab-d021b7461194'::uuid,'Жоолуктарды (подгузник) көзөмөлдөөнү унутпаңыз! 🧷','Бөбөгүңүздүн жакшы тамактанып жатканын жана өсүп жатканын камсыз кылуу үчүн анын күнүмдүк жалаяк алмаштыруусун Anacan''га жазып туруңуз.','Jälgi jätkuvalt mähkmete vahetust! 🧷','Märgi Anacanis üles beebi igapäevane mähkmete vahetus, et veenduda tema heas toitumises ja arengus.'),
('99125d76-b832-4f75-8c29-6320b71e5e67'::uuid,'6 жумалык өнүгүү секириги! 📈','Бөбөгүңүз бүгүн бир аз тентек болушу мүмкүн. Кабатыр болбоңуз, колдоо жана кеңеш алуу үчүн Anacan AI менен байланышыңыз.','6. nädala arenguhüpe! 📈','Sinu pisike võib täna veidi nõudlik olla. Ära muretse, võta toe ja juhiste saamiseks ühendust Anacan AI-ga.'),
('9f56ae7d-2431-4cb2-8d79-fa19be16c242'::uuid,'Түнкү ойгонууларды тартипке келтирели. 😴','Бөбөгүңүз ойгонгондо, жарыкты күйгүзбөөгө аракет кылыңыз. Тамактандыруу үчүн Anacan таймерин колдонуңуз, андан кийин «Ак ызы-чуу» менен кайра уктатыңыз.','Loome öiste ärkamiste jaoks rutiini. 😴','Kui beebi ärkab, väldi eredate tulede süütamist. Kasuta toitmiseks Anacani taimerit ja rahusta ta seejärel valge müra abil uuesti magama.'),
('bef1515a-3c39-4799-b9d9-717742d94d5f'::uuid,'Наристеңиз уктап жатканда сиз да эс алыңыз. ⏱️','Уйку таймерин иштетиңиз, бөбөгүңүз уктап жатканда өзүңүз да көз ирмемге эс алып же китеп окуп алыңыз.','Puhka siis, kui beebi puhkab. ⏱️','Käivita unetaimer ja kasuta beebi uinaku ajal hetke, et puhata või lugeda raamatut.'),
('3deddca7-0eae-4a46-a2c9-5a8e2ac8b32c'::uuid,'Кыңылдаган үндөр көбөйүүдө! 🗣️','Бөбөгүңүздүн сиз менен «сүйлөшүүгө» аракет кылган баалуу көз ирмемдерин тартып алыңыз. Бул учур үчүн биздин «Бөбөк фотосессиясы» бөлүмүнөн эң сонун алкакты тандаңыз.','Peagi kuuleb rohkem kudrutamist! 🗣️','Jäädvusta beebi armsad katsed sinuga ''rääkida''. Leia selleks hetkeks ideaalne raam meie beebifotode jaotisest.'),
('235bf352-67d4-4056-94d7-5429271d340f'::uuid,'Майда-чүйдө талаш-тартыштар 🗣️','«Жок, мен чоңмун, мен жакшы билем!» – алар азыр сиз менен талашып, өз жүйөлөрүн келтирип жатышабы? Үнүңүздү көтөрбөй, сабырдуу жана чечкиндүү тон менен жооп бериңиз.','Väikesed nääklemised 🗣️','Ei, mina olen suur ja tean paremini! Kas ta üritab nüüd sulle vastu vaielda ja oma argumente tuua? Vasta häält tõstmata, säilitades rahuliku ja kindla tooni.'),
('c21d305d-a798-46f7-a57b-5ee7fc159b60'::uuid,'Ууз сүт: Наристеңиздин биринчи вакцинасы! 🤱','Тиркемедеги «Тамактануу трекери» аркылуу жеген тамактарыңызды оңой эле жазып туруңуз.','Kolostrum: beebi esimene vaktsiin! 🤱','Logi oma toitumine hõlpsasti rakenduse toitumise jälgija abil.'),
('bcfe1987-8bea-4b53-a1dc-7ef7e234e755'::uuid,'Сезимдериңизди башкарыңыз. 💖','Эне болуу чарчатышы мүмкүн. «Маанай күндөлүгүңүздү» ачып, бүгүн сизди эмне тынчсыздандырып жатканын жазыңыз, ошондо жеңилдеп каласыз.','Valitse oma emotsioone. 💖','Emadus võib olla kurnav. Ava oma meeleolupäevik ja pane kirja, mis sind täna vaevab, et tunda end veidi kergemalt.'),
('4c289cf6-60de-4ba6-9f14-eae4086d8d21'::uuid,'Эмизүү тыныгууларын жөнгө салуу. 🍼','«Тамактандыруу трекери» аркылуу тамактануу жана эс алуу убактысын көзөмөлдөп, бөбөгүңүздүн идеалдуу тартибин түзүңүз.','Toitmispauside kohandamine. 🍼','Pane paika beebi ideaalne rutiin, jälgides toitmise ja puhkeaegu toitmise jälgija abil.'),
('ae99921f-bf29-40ac-a251-a633a4741d07'::uuid,'Өзүңө кам көрүү — өзүмчүлдүк эмес 💆‍♀️','«Балама жетиштүү убакыт бөлбөй жатам» деген синдром ар бир энеде болот. Бирок эсиңизде болсун, чарчаган эне баласына эч нерсе бере албайт. Түштөн кийин өзүңүз үчүн 20 мүнөттүк дем алуу тыныгуусун уюштуруңуз.','Enese eest hoolitsemine pole isekus 💆‍♀️','''Ma ei veeda lapsega piisavalt aega'' sündroom mõjutab iga ema. Kuid pea meeles, et kurnatud emal pole lapsele midagi anda. Loo endale pärastlõunal 20-minutiline hingamispaus.'),
('ee814c6a-2fd2-46fc-a3a3-6fece315052e'::uuid,'Наристеңиздин коргоочу катмары (верникс). 👶 Кабатыр болбоңуз!','Жалаяк алмаштырганда, аны Anacan''га жазып коюуну жана ченемдерди текшерүүнү унутпаңыз!','Beebi kaitsev verniks. 👶 Ära muretse!','Mähkmeid vahetades ära unusta seda Anacanis kirja panna ja norme kontrollida!'),
('7f93cf2f-abf0-4b16-9f93-396050a7ddb9'::uuid,'Дагы суроолоруңуз барбы? 🤖','Бөбөгүм бүгүн аз уктады – бул кадимки көрүнүшпү? Суроолоруңузду Коомчулуктагы башка энелерден сураңыз!','Kas sul on veel küsimusi? 🤖','Mu beebi magas täna vähem – kas see on normaalne? Küsi kõiki oma küsimusi teistelt emadelt kogukonnas!'),
('c505d849-65c8-4ead-80b3-2648f5feaa49'::uuid,'Ичи менен жатуу көнүгүүлөрү! 🐢','Бөбөгүңүз азыр башын узагыраак кармап калды! Моюн булчуңдарын чыңдоо үчүн бул көнүгүүлөрдү күн сайын улантыңыз.','Kõhuli olemise harjutused! 🐢','Sinu beebi hoiab nüüd pead kauem püsti! Jätka neid harjutusi iga päev, et tugevdada tema kaelalihaseid.'),
('ead40251-f5fc-4b01-b344-4b041fbbf0eb'::uuid,'Эң таттуу түйшүк 🫂','Күн бою алар сизди бир аз тажатып, ар нерсеге ыйлашы мүмкүн. Бирок кечинде уктап жатканда, көкүрөгүңүзгө кысылган ошол жылуу, кичинекей дененин жыты... мына ушул дүйнөдөгү эң сонун сезим.','Kõige armsam koorem 🫂','Terve päeva võis ta sind veidi hullutada, nuttes kõige peale. Kuid õhtul, kui ta uinub, see sooja pisikese keha lõhn su rinnal... see on maailma kõige ilusam tunne.'),
('ffd7ff0c-bf80-4552-8a28-8d30f0674b07'::uuid,'Бүгүн жок дегенде 15 мүнөтүңүздү өзүңүзгө арнаңыз. 🛁','Жылуу душка түшүп, тиркемебизден пайдалуу рецепт менен өзүңүздү сыйлаңыз.','Võta täna vähemalt 15 minutit iseendale. 🛁','Hellita end sooja dušiga ja proovi meie rakendusest tervislikku retsepti.'),
('20684bd3-d3fb-479e-89f1-9adf84e485af'::uuid,'Тамактануу тартиби кандай жүрүп жатат? 🤱','Тиркемедеги таймерди иштетиңиз жана «Тамактандыруу трекери» менен тамактануу графигин оңой көзөмөлдөңүз.','Kuidas toitumisrutiin edeneb? 🤱','Käivita rakenduses taimer ja jälgi toitmise graafikut mugavalt toitmise jälgijaga.'),
('41765791-323c-438b-b416-30b7105b9c01'::uuid,'Апа үчүн гана мейкиндик ☕','Күн сайын бир эле паркка баруудан тажадыңызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн балдар да ыңгайлуу ойной турган тынч, башкача кафе таап, бүгүн өзүңүздү эркелетиңиз.','Aeg ainult emale ☕','Tüdinenud iga päev samas pargis käimisest? Avasta ''emmesõbralike kohtade'' hulgast vaikne ja uus kohvik, kus ka lapsed saavad mugavalt mängida, ning hellita end täna.'),
('dc90d262-2720-4f19-9f2a-dcf90cd5da80'::uuid,'Формаларды жана мейкиндикти түшүнүү 🧩','Алар пазлдарды жана ар кандай формаларды өз ордуна коюуга аракет кылып жатышабы? Ката кетиришсе да, кийлигишпеңиз. Алар көйгөйлөрдү чечүүнү дал ушул аракет жана жаңылыштык аркылуу үйрөнүшөт.','Kujundite ja ruumi mõistmine 🧩','Kas ta proovib visalt pusletükke ja kujundeid õigetesse aukudesse sobitada? Ära sekku, isegi kui ta eksib. Ta õpib probleemide lahendamist just katse-eksituse meetodil.'),
('65d67a55-0ffc-4c5f-8c78-443c16c7f697'::uuid,'Аталарды да тартуу керек! 👨‍🍼','Кечки тамактан кийин, өзүңүзгө убакыт бөлүп, бөбөктү кекиртүүнү жана уктатууну атасына тапшырыңыз.','Kaasame issid! 👨‍🍼','Pärast õhtust toitmist lase issil tegeleda krooksutamise ja magamapanekuga, samal ajal kui sina võtad aega iseendale.'),
('c7ab2e50-8e71-4df1-97cc-6432f40c4349'::uuid,'Күн сайын көбүрөөк жылмаюу! 😍','Бөбөгүңүз сизге жылмайган ошол сыйкырдуу көз ирмемди өткөрүп жибербеңиз! Сүрөткө тартып, «Бөбөк альбомундагы» өзгөчө жерге кошуп коюңуз.','Iga päevaga rohkem naeratusi! 😍','Ära maga maha seda maagilist hetke, kui beebi sulle vastu kudrutab! Tee foto ja lisa see beebialbumi erilisse kohta.'),
('dba00752-8e14-4710-8793-6a828172c915'::uuid,'Достор менен кофе ичүүгө убакытпы? ☕','Биздин «Энелер үчүн ыңгайлуу жайлар» функциясын колдонуп, сиз жана бөбөгүңүз үчүн эң ыңгайлуу кафелерди табыңыз.','Kohvipaus sõpradega? ☕','Avasta meie ''emmesõbralike kohtade'' funktsiooni abil lähimad mugavad kohvikud, mis sobivad ideaalselt sulle ja su beebile.'),
('503a0808-7061-4b7d-ae17-f65b9abb87de'::uuid,'Өнүгүүнү кадам сайын көзөмөлдөңүз. 📚','Жаңы төрөлгөн ымыркайлар бул айда кандай көндүмдөрдү өнүктүрөрүн билгиңиз келеби? Блогдор бөлүмүндөгү акыркы макалабызды окуңуз.','Jälgi arengut samm-sammult. 📚','Huvitab, milliseid oskusi vastsündinud sel kuul tavaliselt arendavad? Loe meie uusimat artiklit blogide jaotisest.'),
('aeea52a4-dd88-4cf1-a812-0c13b4f98004'::uuid,'Күнүмдүк уйку талаптары. 🛌','Бөбөгүңүз уктаганда уйку таймерин иштетиңиз жана анын күнүмдүк сунушталган 14-17 сааттык уйкусун алып жатканын талдап көрүңүз.','Igapäevane unevajadus. 🛌','Käivita unetaimer, kui beebi magab, ja analüüsi, kas ta saab kätte soovituslikud 14–17 tundi und.'),
('9d97fdbc-edef-4830-93ad-c388f586d909'::uuid,'Бирге болгонубузга 50 күн! 🎈','Бул сонун жетишкендикти «Бөбөк фотосессиясы» куралыбыз менен өзгөчө сүрөт түзүп белгилеңиз!','50 päeva koos! 🎈','Tähista seda imelist verstaposti, luues meie beebifotode tööriistaga eriline foto!'),
('cb1a5cad-e167-45a8-b0b1-4e8ebe455866'::uuid,'Акыркы 50 күндүн жыйынтыгы. 📈','«Өсүү трекери» жана «Тамактандыруу журналы» бөлүмдөрүн текшерип, бөбөгүңүз бул 50 күндүн ичинде кандай сонун өскөнүн көрүңүз.','Viimased 50 päeva ülevaates. 📈','Avasta, kui kaunilt su beebi on nende 50 päeva jooksul kasvanud, kontrollides kasvu jälgija ja toitmise logi jaotisi.'),
('b67a89c9-d8cf-40c2-97a2-43b27081ed44'::uuid,'Көрүү талаасынын кеңейиши! 👀','Бөбөгүңүз эми кыймылдаган нерселерди алда канча жакшыраак ээрчий алат.','Vaateväli laieneb! 👀','Sinu beebi suudab nüüd liikuvaid esemeid palju paremini jälgida.'),
('42ca0f3b-8083-4338-bf16-9998a33b15c6'::uuid,'Таза абага чыгууга убакыт келди! 🌳','Бөбөгүңүз менен бара турган эң ыңгайлуу жерлерди табуу үчүн «Энелер үчүн ыңгайлуу жайлар» картабызды изилдеңиз.','Aeg värske õhu kätte minna! 🌳','Uuri meie ''emmesõbralike kohtade'' kaarti, et leida kõige mugavamad kohad, kuhu saad beebiga minna.'),
('7fc52d97-b36d-4c5e-a169-0eadba238b0e'::uuid,'Салмагын жана боюнун узундугун көзөмөлдөө. 📏','Бөбөгүңүз кандай өсүп жатат? «Салмак трекерине» жаңы маалыматтарды киргизип, анын өсүү графигин көзөмөлдөңүз.','Kaalu ja pikkuse jälgimine. 📏','Kuidas su beebi kasvab? Jälgi tema unikaalset kasvugraafikut, sisestades uued andmed kaalu jälgijasse.'),
('0c1e843a-b2dc-4995-89cf-7af4230d574e'::uuid,'Колдорун таанып билүү! 👐','Алар буга чейин эле манжаларына кызыгып, оозуна сала башташты!','Avastab oma käsi! 👐','Ta on juba lummatud oma sõrmedest ja viib neid suhu!'),
('816ef2cf-32b6-4eba-b12b-4e8f7936a78f'::uuid,'Сүтүңүздүн көлөмүн сактап калыңыз. 🥛','Суу ичүүнү унутпаңыз! Ал эми кошумча күч алуу үчүн, аялдар үчүн пайдалуу рецепттерибизден эмчек сүтүн көбөйтүүчү суусундук жасап көрүңүз.','Toeta oma piimatootmist. 🥛','Ära unusta juua piisavalt vett! Ja lisaturgutuseks proovi meie tervislike retseptide hulgast imetamist soodustavat jooki.'),
('1de2111f-1bc3-4ba2-9e4a-c85aa4453abb'::uuid,'Сүт аз деп капа болбоңуз! 🥛','Эсиңизде болсун, бөбөгүңүздүн ашказаны дагы эле кичинекей, алчадай гана! Күнүмдүк тамактандыруу статистикаңызды түздөн-түз тиркемеден көзөмөлдөй аласыз.','Ära kurvasta vähese piimakoguse pärast! 🥛','Pea meeles, et beebi kõht on endiselt pisike, umbes kirsi suurune! Saad oma igapäevast toitmise statistikat jälgida otse rakendusest.'),
('1501b0ff-9742-40e2-9aae-ff2e8f8e5188'::uuid,'Үй-бүлөлүк сейилдөөнү пландаңыз! ☕','Бош убактыңызды туура пайдалануу үчүн «Энелер үчүн ыңгайлуу жайлар» тизмебизден жайлуу кафе же ресторан тандаңыз.','Planeeri perega väljasõit! ☕','Vaba aja maksimaalseks nautimiseks vali meie ''emmesõbralike kohtade'' hulgast hubane kohvik või restoran.'),
('59aa01c0-7e8d-4375-9fcd-733a242d640c'::uuid,'Эмизүү тартибин сактоо. 🍼','Алардын табити жогорулап жаткан болушу мүмкүн! Anacan таймерин иштетиңиз жана «Тамактандыруу журналы» аркылуу тамактануу боюнча сунуштамаларды текшериңиз.','Toitmisrutiini hoidmine. 🍼','Tema isu võib suureneda! Käivita Anacani taimer ja kontrolli toitmise juhiseid toitmise logi tööriista abil.'),
('e0925ec9-2283-4167-888a-ee7948c21d0f'::uuid,'Табигый ак ызы-чуу (white noise) 🤫','Уктап кеткенден кийинки алгачкы жарым саат абдан маанилүү. Бөлмөнүн чөйрөсүн жөнгө салуу үчүн үн мониторун колдонуңуз. Кээде жамгырдын жумшак үнү алардын терең уйкуга кетишине жардам берет.','Looduslik valge müra 🤫','Esimene pooltund pärast uinumist on kriitiline aeg. Kasuta helimonitori, et kohandada toa keskkonda. Mõnikord aitab juba õrn vihmaheli neil sügavasse unne vajuda.'),
('ca5bc974-1377-4065-9dfa-50549135eb55'::uuid,'Көңүлүңүздө бир нерсе барбы? 🤖','Түн ортосунда болсо да, Anacan AI жардамчыбыздан «Эмне үчүн баламдын уйкусу бүгүн мынча кыска?» сыяктуу суроолорду сураңыз.','Kas miski vaevab su meelt? 🤖','Isegi keset ööd võid küsida meie Anacan AI assistendilt küsimusi, näiteks: ''Miks on mu beebi uni täna nii lühike?'''),
('a6843443-e0f6-4ec7-a4ec-03cb5d81d392'::uuid,'Ичи менен жатуу оңойлошуп баратат! 🐢','Алар башын түз жана узагыраак кармап калышты. Бул көнүгүүнү күнүмдүк тартибиңизге кошууну унутпаңыз.','Kõhuli olemine muutub lihtsamaks! 🐢','Ta hoiab juba pead sirgemalt ja pikemat aega. Veendu, et lisad selle tegevuse oma igapäevarutiini.'),
('c2daa58e-e7ee-4f2b-917b-6e5273ca2c1d'::uuid,'Күнүмдүк жоолук (подгузник) текшерүүсү. 🧷','Бөбөгүңүздүн жетиштүү тамактанып жатканын камсыз кылуу үчүн ар бир жалаяк алмаштырууну Anacan''га жазып туруңуз.','Igapäevane mähkmete kontroll. 🧷','Jätka iga mähkmevahetuse logimist Anacanis, et veenduda beebi piisavas toitumises.'),
('7764e41d-176a-41d8-8f87-2a21677a36ee'::uuid,'Тартибибизди түзүү. 🛁','Дени сак уйку тартибин түзүү үчүн ар күнү кечинде бир убакта жуунтуп, тамактандырып жана уйку таймерин иштетиңиз.','Rutiini loomine. 🛁','Vannita, toida ja käivita unetaimer igal õhtul samal ajal, et luua tervislik unerutiin.'),
('9754280d-c633-46e8-94c9-6f16ff032551'::uuid,'Өзүңүздү азыктандырууну унутпаңыз, кымбаттуу апа! 🍲','Anacan тиркемесиндеги «Пайдалуу рецепттер» бөлүмүн карап чыгыңыз жана бүгүн өзүңүздү даамдуу тамак менен сыйлаңыз.','Ära unusta ka ennast toita, kallis ema! 🍲','Heida pilk Anacani rakenduse tervislike retseptide jaotisse ja hellita end täna millegi maitsvaga.'),
('b4eb6af7-758b-41ff-a277-ea0ef21a9fb8'::uuid,'Күндүзгү уйку өзгөрүүдө! ⏱️','Тамактандыруу жана уйку таймерлерин колдонуп, ойгоо убакыттарын жана аралыктарын көзөмөлдөө менен жаңы тартип түзүңүз.','Uinakud muutuvad! ⏱️','Loo uus rutiin, jälgides ärkveloleku aknaid ja intervalle toitmise ja une taimerite abil.'),
('32ff20f3-f1f8-47fd-b3be-c14bea1452a2'::uuid,'Тынчсызданууну басаңдатуучу үндөр. 🎶','Эгер бөбөгүңүз бүгүн кечинде тынчсызданып жатса, алаксытуу жана тынчтандыруу үчүн «Ак ызы-чуу» бөлүмүнөн жүрөктүн согушунун үнүн иштетиңиз.','Rahustavad helid murede korral. 🎶','Kui beebi on täna õhtul rahutu, lülita valge müra hulgast sisse südamelöökide heli, et teda tähelepanu hajutada ja rahustada.'),
('a061022a-6a47-4aae-8590-2f0f328fbf09'::uuid,'Оюн убактысы! 🎈','Бөбөгүңүз менен сапаттуу убакыт өткөрүүнү үйрөнүү үчүн Блогдор бөлүмүндөгү өнүктүрүүчү оюндар боюнча кеңештерди окуңуз.','Mänguaeg! 🎈','Avasta, kuidas oma pisikesega kvaliteetaega veeta, lugedes arendavate mängude nippe blogide jaotisest.'),
('b95ca7be-8491-4bbc-afb0-321f795780ea'::uuid,'Соода кылууга убакыт келдиби? 🛍','Бөбөгүңүздүн азыркы айына ылайыктуу, коопсуз оюнчуктарды жана керектүү буюмдарды биздин «Сунушталган товарлар» тизмесинен оңой табыңыз.','Aeg sisseoste teha? 🛍','Leiad meie soovitatud toodete nimekirjast hõlpsalt turvalised mänguasjad ja tarbed, mis sobivad täpselt sinu beebi praeguse vanusega.'),
('633e342d-82b1-442c-9da8-5c5326907322'::uuid,'Бүгүнкү маанилүү маалыматтар 📈','Балаңыздын тамактануу жана уйку графигин көзөмөлдөп, андан соң күнүмдүк тартибиңиздин кандай сонун калыптанып жатканын талдап көрүңүз.','Tänased tähelepanekud 📈','Jälgi toitmis- ja unegraafikuid ning analüüsi, kui kenasti teie rutiin välja kujuneb.'),
('8655d498-c5d9-40f8-bd47-346f815d3e75'::uuid,'Жагымдуу күндөн кийин таттуу түштөр. 🌙','Жарыкты өчүрүп, «Ак ызы-чуу» (White Noises) бөлүмүнөн курсактагы үндөрдү коюп, бөбөгүңүздүн тынч уктап жатканын карап отуруңуз.','Magusaid unenägusid pärast toredat päeva. 🌙','Hämarda tuled, mängi valge müra (White Noises) valikust emakaheli ja vaata, kuidas sinu beebi rahulikult magab.'),
('75f8bf1f-a1b6-48ed-8282-db88f2b4b621'::uuid,'Өзүңүзгө убакыт бөлүңүз. 💆‍♀','Денеңиз төрөттөн кийин калыбына келип жатат. Бүгүн «Маанай күндөлүгүңүзгө» сезимдериңизди жазып, бир аз эс алып алыңыз.','Leia aega iseendale. 💆‍♀','Sinu keha taastub pärast sünnitust. Võta hetk lõõgastumiseks ja pane oma tänased emotsioonid kirja tujupäevikusse (Mood Journal).'),
('97e88a0b-26cf-486d-a17f-2c34cfc6b47d'::uuid,'Бирге болгонубузга 70 күн болду! ✨','Сиз укмуштуудай энесиз! Балаңыздын альбомуна биринчи күн менен бүгүнкү күндүн ортосундагы чоң өзгөрүүнү көрсөткөн коллаж кошуңуз.','70 päeva koos! ✨','Sa oled suurepärane ema! Lisa beebialbumisse kollaaž, mis näitab uskumatut erinevust esimese päeva ja tänase vahel.'),
('0c5e05bb-e0ba-4c0b-a9c9-f1f210abb37a'::uuid,'Биз бир командабыз! 💪','Кээде жалгызсырап же эч ким түшүнбөгөндөй сезилеби? Anacan коомчулугуна кошулуңуз. Ал жерде сиздин абалыңызды так түшүнгөн миңдеген энелер бар. Тажрыйбаңыз менен бөлүшүңүз.','Oleme meeskond! 💪','Kas tunned end mõnikord üksildasena või vääriti mõistetuna? Liitu Anacan kogukonnaga. Seal on tuhandeid teisi emasid, kes mõistavad täpselt, mida sa tunned. Jaga oma kogemust nendega juba täna.'),
('28ff0d8a-2265-4669-8253-5aac2bfb80da'::uuid,'Өзүңүзгө ыраазы болуңуз 🎈','Уйкусуз түндөр, күндүзгү түйшүктөр... Бирок сиз баарына жетиштиңиз. Бүгүн балаңызга үнүңүздү көтөрбөй тарбиялап жатканыңыз үчүн өзүңүзгө «Азаматсыз!» деп коюңуз.','Tänan iseennast 🎈','Magamata ööd, lõputu ruttamine päeval... Aga sa oled kõigega hakkama saanud. Kiida end täna selle eest, et kasvatad oma last ilma häält tõstmata.'),
('60059890-bf5b-4e0b-ba41-fedc82fa6a43'::uuid,'Атасынын кезеги 👨‍🍼','Күндүн чарчоосун унутуңуз. Бүгүн кечинде баланы өнөктөшүңүзгө тапшырып, уктатуу милдетин ага бериңиз. Ал эми өзүңүз бир чыны жылуу чай ичип, тынчтыкта эс алыңыз.','Issi kord 👨‍🍼','Lase päeva väsimusel minna. Anna beebi täna õhtul partneri kätte ja lase tal magamaminekuga tegeleda. Sina aga vala endale tass sooja teed ja naudi rahulikku hetke eemalt.'),
('b1778419-cb70-4711-96e0-a612732e8575'::uuid,'Шилекейи аккан жылмаюулар 🤤','Бөбөгүңүздүн шилекейи көп агып, колун оозуна сала баштадыбы? «Тиш чыгууну көзөмөлдөө» бөлүмүнө биринчи жазууларды киргизиңиз. Ооба, бул кызыктуу даярдыктар эрте башталат!','Süljega naeratused 🤤','Kas sinu beebi ilastab palju ja paneb pidevalt käsi suhu? Tee esimesed sissekanded hammaste tuleku jälgijasse (Teething Tracker). Jah, need põnevad ettevalmistused algavad vara!'),
('0eb4da19-cb98-497a-a36b-a4934f47e071'::uuid,'Тынч көзөмөл 🤫','Бөбөгүңүз уктап калды, бирок үйдөгү ызы-чуудан чочуп кетеби деп кооптонуп жатасызбы? «Үн өлчөгүч» куралын иштетип, анын уйкусун коргоо үчүн бөлмөдөгү децибелди көзөмөлдөңүз.','Vaikne jälgimine 🤫','Kas beebi uinus just, aga sa muretsed koduse müra pärast? Aktiveeri mürataseme mõõtja (Sound Meter) ja jälgi toas olevaid detsibelle, et kaitsta tema und.'),
('9cab0c58-8a4f-4869-b607-be3e284373f0'::uuid,'Сурооңуз барбы? 🤖','Күнүмдүк түйшүктөрдүн арасында бир нерсе тынчсыздандырып жатабы? Тамактануу, уйку же ичтин көбүшү... Кандай болбосун, Anacan AI''дан дароо сурап, так жана илимий жоопторду алыңыз.','Kas sul on küsimus? 🤖','Kas igapäevaste murede keskel vaevab sind miski? Olgu see toitmine, uni või gaasid... Küsi kohe Anacan AI-lt ja saa täpseid teaduspõhiseid vastuseid.'),
('bbcb238e-ee32-4e4b-a429-0c4d99613140'::uuid,'Келгиле, анын уйку режимин талдап көрөлү. ⏱️','Бөбөгүңүз уктаганда, уйку таймерин иштетиңиз жана графиктен анын күнүмдүк уйку нормасын канчалык деңгээлде аткарып жатканын көрүңүз.','Analüüsime beebi unerutiini. ⏱️','Kui beebi magab, aktiveeri unetaimer ja vaata graafikult, kui hästi ta täidab igapäevaseid unesoovitusi.'),
('e6d33eab-abbe-4eca-94e9-c05138d06c07'::uuid,'Мен ушул жердемин! 👀','Бөбөгүңүз эми сизди бөлмөнүн аркы четинен да кунт коюп карап жатат! Көзгө карап баарлашуудагы бул сонун жетишкендикти «Өсүү күндөлүгүнө» жазып, анын өнүгүүсү менен сыймыктаныңыз!','Olen siinsamas! 👀','Sinu pisike jälgib sind nüüd tähelepanelikult isegi teisest toaservast! Pane see imeline silmsidemega seotud verstapost arengu jälgijasse (Growth Tracker) kirja ja ole tema arengu üle uhke!'),
('05925891-b678-4a87-8f54-39f692aa9143'::uuid,'Керектүү буюмдар азайып калдыбы? 🛒','Жоолуктар же нымдуу салфеткалар азайып калдыбы? Баарын эстеп калуунун кажети жок! Аларды азыр «Соода тизмесине» кошуңуз, өнөктөшүңүз үйгө келе жатып алып келет.','Esmatarbekaubad hakkavad otsa saama? 🛒','Kas mähkmed või salvrätikud hakkavad otsa saama? Sa ei pea kõike meeles pidama! Lisa need kohe ostunimekirja ja sinu partner saab need koduteel kaasa haarata.'),
('95ffd69a-c8c2-4b14-b98e-76c322f02229'::uuid,'Тизмесиз соода кылуубу? Эч качан! 🛒','Дүкөнгө барганда эсиңизге таянып, эң керектүү нерсени албай калып жатасызбы? Бул адатты токтотуңуз. Үйдө түгөнгөн ар бир нерсени дароо «Соода тизмесине» кошууну адат кылыңыз.','Sisseostud ilma nimekirjata? Mitte kunagi! 🛒','Kas loodad toidupoes oma mälule ja naased koju ilma kõige olulisema asjata? Lõpeta see harjumus. Muuda rutiiniks lisada iga puuduv asi kohe oma ostunimekirja (Shopping List).'),
('41007feb-f415-4088-b094-428b2275abbf'::uuid,'Сыйкырдуу үндөр дүйнөсү 📖','Кечки тартибиңизди ар түрдүү кылыңыз. «Акылдуу жомоктор» бөлүмүнөн бөбөгүңүз үчүн тынчтандыруучу жомок даярдап, экөөңүздөр үчүн тең уктатуу убактысын жеңилдетиңиз.','Maagiliste helide maailm 📖','Muuda oma õhtust rutiini vaheldusrikkamaks. Vali nutikate muinasjuttude (Smart Tales) hulgast oma pisikesele rahustav lugu ja tee uinumine teie mõlema jaoks kiiremaks.'),
('e23c6a5f-2a6d-45e5-af3a-8681c3bb9e03'::uuid,'Эртең мененки серенада! 🎶','Ал биринчи үндөрүн чыгарып жатабы? Анын тилинде «жооп бериңиз» жана үндөрүнө кайрылыңыз. Бүгүн бул таттуу көз ирмемден ырахат алыңыз жана эч нерсеге шашпаңыз.','Hommikune serenaad! 🎶','Kas ta teeb oma esimesi häälitsusi? "Räägi" temaga vastu tema keeles ja vasta tema helidele. Naudi täna lihtsalt seda armsat hetke ja ära kiirusta kuhugi.'),
('62fbb893-6a1c-4847-a99e-981afea8fa87'::uuid,'Ымыркайдын ыйын түшүнүү 😭','Бөбөгүңүз ачкалыктан же уйкусу келгенден ыйлап жатабы? Кабатыр болбоңуз, «Ыйды талдоо» куралыбыз менен анын ыйы эмнени билдирерин бир нече секундда чогуу аныктайлы.','Beebi nutu dešifreerimine 😭','Kas beebi nutab näljast või unisusest? Ära muretse, selgitame meie nutuanalüüsi (Crying Analysis) abil sekunditega välja, mida need helid tähendavad.'),
('83a0ab90-d44d-4758-bd3f-c7126ae6e20f'::uuid,'Өзүңүзгө карата чынчыл болуңуз 📝','Бүгүн абдан чарчадыңызбы? «Маанай күндөлүгүңүздү» ачып, сезимдериңизди чынчылдык менен жазыңыз. Ар күнү идеалдуу болуунун кажети жок; сиз да адамсыз.','Ole enda vastu aus 📝','Kas tunned end täna täiesti kurnatuna? Ava oma tujupäevik (Mood Journal) ja pane oma tunded ausalt kirja. Sa ei pea olema iga päev täiuslik; sa oled kõigest inimene.'),
('d9e30a3e-ad9b-4b4b-85a6-bcaa444e488c'::uuid,'Бүгүн аны эмне кийиндирсем болот? ⛅','Аба ырайы өзгөрүлмөлүү болуп, бөбөгүңүз үшүп же ысып кетеби деп кооптонуп жатасызбы? Бүгүнкү күнгө ылайыктуу кийимди тандоо үчүн «Аба ырайы жана кийим» куралын дароо текшериңиз.','Mida talle täna selga panna? ⛅','Kas ilm on ettearvamatu ja sa muretsed, et beebil võib hakata liiga külm või soe? Vaata kohe ilma ja riietuse tööriista, et leida tänaseks prognoosiks ideaalne riietus.'),
('6cefc0b3-6f91-4329-bd4c-bf6671e0e8aa'::uuid,'Жылдыздуу түштөр 🌌','Балдар тартипти жакшы көрүшөт. «Акылдуу жомоктор» бөлүмүн колдонуп, бөбөгүңүз үчүн атайын уктатуучу жомок түзүңүз.','Tähised unenäod 🌌','Lapsed armastavad rutiini. Loo oma pisikesele eriline uinumisjutt, kasutades nutikate lugude (Smart Stories) jaotist.'),
('dacdc0bf-3562-4ab5-be87-7acb17a3f2f9'::uuid,'Сиз укмуштуудайсыз! 🌸','Кээде эч нерсеге жетишпей жаткандай сезилеби? Бирок бөбөгүңүздүн дени сак, тынч дем алганын караңыз... Сиз колуңуздан келгендин баарын жасап жатасыз!','Sa oled imeline! 🌸','Kas tunned mõnikord, et ei saa millegagi hakkama? Aga vaata oma beebi tervet ja rahulikku hingamist... Sa annad endast parima!'),
('faace99e-5074-497e-b5c0-f25a9880f5b0'::uuid,'Апа үчүн энергия булагы 🍲','Күнүмдүк түйшүктүн арасында өзүңүз тамактанууну унутуп калдыңызбы? «Дени сак рецепттер» бөлүмүнөн күчүңүздү калыбына келтирүүчү жана сүтүңүздү көбөйтүүчү тез даярдалуучу шорпонун рецептин тандаңыз.','Ema energiaallikas 🍲','Kas unustasid igapäevases saginas ise süüa? Vali tervislike retseptide (Healthy Recipes) alt kiire supiretsept, mis taastab sinu energia ja soodustab rinnapiima teket.'),
('1cd41578-3422-4bf8-9401-e9a058dcad6f'::uuid,'Болгону 15 мүнөт 🛁','Бөбөгүңүз уктадыбы? «Өнөктөш режимине» өтүп, бардык эскертмелерди өнөктөшүңүзгө багыттаңыз. Андан соң ваннага кирип, 15 мүнөт жылуу сууда тынч эс алыңыз.','Vaid 15 minutit 🛁','Beebi magab? Lülitu partnerirežiimi (Partner Mode) ja suuna kõik teavitused oma partnerile. Seejärel lipsa vannituppa ja naudi 15 minutit sooja vett ja õndsat vaikust.'),
('73a10da9-aef9-4c21-b8d7-bca1f62e8528'::uuid,'Тажрыйба бөлүшүү 💬','Бөбөгүңүз акыркы убакта эң күлкүлүү эмне кылды? Anacan коомчулугуна кошулуп, бул көз ирмемди пост катары бөлүшүңүз. Башка энелердин окуяларын окуу сизге да жакшы таасир этет.','Kogemuste jagamine 💬','Mis on kõige naljakam asi, mida sinu beebi viimasel ajal teinud on? Liitu Anacan kogukonnaga ja jaga seda hetke postitusena. Teiste emade lugude lugemine teeb ka sulle head.'),
('acfd33be-87a0-41a3-858d-d5921f61d9a4'::uuid,'Салам, кичинекей алакан! 👋','Бөбөгүңүз колун таап, аны сааттап карап жатабы? Бул күлкүлүү жана кереметтүү өнүгүү учурун өткөрүп жибербеңиз – аны «Баланын фотосессиясы» менен дароо тартып алып, өмүр бою сактаңыз!','Tere, väikesed käed! 👋','Kas sinu beebi avastab oma käsi ja põhitseb neid tunde? Ära maga maha seda naljakat ja imelist arenguhetke – jäädvusta see kohe beebi fotosessiooniga (Baby Photoshoot), et see igaveseks alles jääks!'),
('384efd2a-d9fb-48b6-8e4a-eca7c3a0d8ee'::uuid,'Чарчооңузду кабыл алыңыз 💖','Үй чачылып, кечки тамакты интернеттен заказ кылдыңызбы? Бул эч нерсе эмес. Бул жолдо сиз жалгыз эмессиз.','Võta oma väsimust kui osa teekonnast 💖','Kas kodu on sassis ja õhtusöök tellitud kulleriga? See on täiesti okei. Sa ei ole sellel teekonnal üksi.'),
('8f6c6637-de06-4b9d-8e44-d9e85864f3c8'::uuid,'Эртең мененки жай кыймылдар 🐢','Ал эми башын жогорураак кармап калды! «Ичи менен жатуу» убактысын кызыктуу кылыңыз. Аны күзгү алдына коюп, өзүнүн чагылышына болгон реакциясын караңыз.','Õrnad hommikused liigutused 🐢','Ta hoiab nüüd pead juba kõrgemal! Muuda kõhuliolek (Tummy time) lõbusaks. Pane ta peegli ette ja jälgi tema reaktsioone oma peegelpildile.'),
('049d3744-b2ac-49ea-bf86-ad5e8d0bcb74'::uuid,'Сиздин текшерүү тизмеңиз 📝','Үй тиричилигинин чексиз тизмеси чарчатышы мүмкүн. Баарын эстеп калам деп мээңизди кыйнабаңыз! «Соода тизмесин» ачып, керектүү нерселерди жазыңыз жана бир басуу менен өнөктөшүңүз менен бөлүшүңүз.','Sinu kontrollnimekiri 📝','Lõputu nimekiri kodustest vajadustest võib olla kurnav. Ära koorma oma pead kõige meelespidamisega! Ava oma ostunimekiri (Shopping List), pane kirja, mida vajad, ja jaga nimekirja ühe puudutusega oma partneriga.'),
('12a076b6-d8dc-4bec-a8af-ddc523182bad'::uuid,'Жомок убактысы 📖','Бөбөгүңүздүн келечекте чоң кыялкеч болушу азыртадан башталат. «Акылдуу жомоктор» менен сыйкырдуу жомок түзүп окуп бериңиз жана анын көздөрү акырын жумулуп жатканын карап отуруңуз.','Jutuvestmise aeg 📖','See, et sinu beebist saaks tulevikus suur unistaja, saab alguse juba praegu. Loo nutikate muinasjuttude (Smart Tales) abil maagiline lugu, loe see ette ja vaata, kuidas tema silmad aeglaselt sulguvad.'),
('58ce6bd9-90fd-4e98-a133-ddfda6d59177'::uuid,'Сиздин чөнтөк педиатрыңыз 🤖','Анын салмак кошуусу жакшыбы? Заңынын түсү өзгөрдүбү? Дүрбөлөңгө түшөрдөн мурун, Anacan AI''га жазып, маселени түшүнүп, ишенимдүү маалымат алыңыз.','Sinu taskupediaater 🤖','Kas kaaluiive on piisav? Kas väljaheide on teist värvi? Enne kui paanikasse satud, kirjuta Anacan AI-le, et probleemist aru saada ja rahustavat infot saada.'),
('5543e602-8610-44ac-8995-56ec74a0576e'::uuid,'Акылдуу тынчтык 🤫','Кечинде ыйлоону азайтуу үчүн бөлмөдөгү ызы-чуунун деңгээлин көзөмөлдөө абдан маанилүү. «Үн өлчөгүчтү» иштетиңиз, өтө ызы-чуу чөйрөдөн качыңыз жана бөбөгүңүздү тынч түнгө даярдаңыз.','Nutikas vaikus 🤫','Õhtuste jonnihoogude vähendamiseks on oluline jälgida toas olevat mürataset. Lülita sisse mürataseme mõõtja (Sound Meter), väldi liiga mürarikast keskkonda ja valmista oma pisike ette rahulikuks ööks.'),
('81600590-d6f0-495d-b852-9afcf35b137a'::uuid,'Саякатка кийинип даярдануу ⛅','Сейилдөөгө чыккыңыз келип, бирок аба ырайынан шек санап жатасызбы? «Аба ырайы жана кийим жардамчысы» менен бүгүнкү температурага ылайыктуу кийимди бир нече секундда табыңыз.','Riietumine seiklusteks ⛅','Tahad jalutama minna, aga pole ilmas kindel? Ilma- ja riietusassistendi abil leiad sekunditega tänase temperatuuri jaoks ideaalse kombinatsiooni.'),
('fbf2b91a-0a2a-4aa9-9404-589ba5628b25'::uuid,'Эртең мененки жылмаюу ☀️','Ал көзүн ачып, дароо сизге чоң жылмаюу тартууладыбы? Сиз дүйнөдөгү эң баалуу белекти алдыңыз. Бүгүн ушул көз ирмемди баалап, позитивдүү маанайда болуңуз.','Hommikune naeratus ☀️','Kas ta avas silmad ja kinkis sulle kohe laia naeratuse? Oled saanud maailma kõige kallima kingituse. Ole täna positiivne ja hoia seda hetke endas.'),
('488e046f-44fb-4fcc-80e0-064c20288a56'::uuid,'Командалык майрам 🥂','Бүгүн кечинде өнөктөшүңүзгө 80 күн бою чогуу жасаган эмгегиңиздер үчүн ыраазычылык билдирип коюңуз. Экөөңүздөр тең укмуштуудай иш жасадыңыздар!','Tähistame koos 🥂','Võta täna õhtul hetk, et tänada oma partnerit teie 80 ühise töise päeva eest. Te olete mõlemad teinud suurepärast tööd!'),
('720785a0-3423-4036-a26d-bba9419b8cb2'::uuid,'Сексен сонун күн! 🎉','Сиздер чогуу болгонуңузга туптуура 80 күн болду! «Баланын фотосессиясы» бөлүмүнө өтүп, бул маанилүү күндү атайын 80 күндүк стикерлер менен түбөлүккө калтырыңыз жана коомчулукта эскерүү катары бөлүшүңүз!','Kaheksakümmend imelist päeva! 🎉','Olete olnud koos täpselt 80 päeva! Mine beebi fotosessiooni (Baby Photoshoot) jaotisse, jäädvusta see verstapost eriliste 80-päeva kleepsudega ja jaga seda mälestusena kogukonnas!'),
('7d54b8de-cc42-4891-b97a-5856eefffe9d'::uuid,'Сиздин өз жомогуңуз башталууда 🪄','Бүгүн кечинде бөбөгүңүз башкы каарман болсун! «Акылдуу жомокторго» өтүп, теманы киргизиңиз: «Түнкүсүн уктагысы келбеген кичинекей рыцардын укмуштуу окуялары». AI сиз үчүн уникалдуу жана таттуу жомок түзүп берсин.','Sinu enda muinasjutt hargneb lahti 🪄','Olgu sinu beebi täna õhtul peategelane! Mine nutikate lugude (Smart Stories) juurde ja sisesta teema: Väikese rüütli seiklused, kes ei taha öösel magada. Lase AI-l luua just teile kordumatu ja armas lugu.'),
('28500aa6-3ac1-4fd2-a987-e74e0b2bccb8'::uuid,'Кучактоо менен баланы бузуп коёсуң деген уламыштарга ишенбеңиз! 🤗','Көп кучактаңыз! Бул сиздердин байланышыңызды гана бекемдебестен, сүтүңүздүн көбөйүшүнө да жардам берет.','Ära usu müüte, et kaisutamine hellitab lapse ära! 🤗','Kallistage tihti! See mitte ainult ei tugevda teie sidet, vaid võib aidata kaasa ka rinnapiima teket.'),
('d5c6a987-139f-4c65-bdd8-e9dc3eb4c43a'::uuid,'Маектешүүгө даярсызбы? 🗣️','Ал эми жөн эле үндөрдү чыгарбай, сиздин үнүңүзгө ар кандай обондор менен жооп берүүгө аракет кылып жатат! «Өсүү күндөлүгүн» ачып, бул укмуштуудай баарлашуу секиригин жазыңыз жана анын «тилинде» сүйлөшүңүз.','Oled vestluseks valmis? 🗣️','Ta ei tee enam lihtsalt hääli, vaid püüab sinu häälele erinevate toonidega vastata! Ava arengu jälgija (Growth Tracker), pane see uskumatu suhtlushüpe kirja ja vestle temaga tema "keeles".'),
('f027a882-3827-4905-9807-216432d88e53'::uuid,'Апалардын унутчаактыгы 🌫️','Кечээ эмне жегениңизди эстебей жатасызбы? «Эненин унутчаактыгы» (Baby brain) – бул чындык! Мээңизди кыйнабаңыз; үйгө керектүү нерселердин баарын «Соода тизмесине» жазып коюңуз, өнөктөшүңүз кам көрөт.','Emme ajupudru 🌫️','Ei mäleta, mida sa eile sõid? "Emaaju" on täiesti olemas! Ära koorma oma pead; pane kõik koduks vajalik ostunimekirja (Shopping List) kirja ja sinu partner saab selle eest hoolitseda.'),
('ec24c154-30dc-40d8-8aed-20579933d8fb'::uuid,'Сезимдериңизди сыртка чыгарыңыз 📝','Эч ким сиздин чарчаганыңызды чындап түшүнбөй жаткандай сезилеби? Маанай күндөлүгү сиздин эң жакын сырдашыңыз боло алат. Бардык стрессиңизди, тынчсызданууларыңызды жана жалгыздыгыңызды барактарга төгүп салыңыз; канчалык жеңилдеп калганыңызга таң каласыз.','Lase oma emotsioonid valla 📝','Kas tunned, et keegi ei mõista ega näe sinu kurnatust? Tujupäevik võib olla sinu parim usaldusisik. Vala kogu oma stress, mured ja üksildus selle lehekülgedele; sa üllatud, kui palju kergem sul hakkab.'),
('3258a482-400c-485d-af7c-ccb221416732'::uuid,'Түнкү ойгонуулар сизди чарчатып жатабы? 😴','Бүгүнкү сезимдериңизди «Маанай күндөлүгүңүзгө» жазыңыз, Anacan AI сизге пайдалуу кеңештерди берсин.','Kas öised ärkamised väsitavad sind? 😴','Pane tänased tunded oma tujupäevikusse kirja ja lase Anacan AI-l anda sulle kasulikke nõuandeid.'),
('2e536117-6f18-4388-b1bd-29587c89d3cb'::uuid,'Чачтын баш аламандыгы — бул чындык 💇‍♀️','Күзгүдөн чачыңыз түшүп жатканын көрүү коркунучтуубу? Бул төрөттөн кийинки эң жагымсыз чындыктардын бири! Сиз жалгыз эмессиз – дароо Anacan коомчулугуна кошулуп, башка энелер бул кыйынчылыкты кантип жеңип жатканын окуңуз.','Sassis juuste reaalsus 💇‍♀️','Kas peeglisse vaatamine ja juuste väljalangemine hirmutab sind? See on üks sünnitusjärgse perioodi tüütumaid reaalusi! Sa ei ole üksi – liitu kohe Anacan kogukonnaga ja loe, kuidas teised emad selle väljakutsega toime tulevad.'),
('41393920-01a7-42fe-a049-e26e1148a375'::uuid,'Тынчтык издеп 🤫','Кээде үйдөгү байкалбаган ызы-чуу наристеңиздин уктап кетишине тоскоол болушу мүмкүн. «Үн өлчөгүчтү» иштетип, бөлмөдөгү акустиканы текшериңиз жана алар үчүн идеалдуу тынч чөйрөнү түзүңүз.','Rahu otsimine 🤫','Mõnikord võib märkamatuks jääv kodune müra takistada beebil uinumast. Aktiveeri helimõõtja, kontrolli ruumi akustikat ja loo lapsele ideaalselt rahulik keskkond.'),
('093d545f-b52d-4160-be2f-88e5e1b53427'::uuid,'Жашылчалар менен күрөш уланууда 🥦','Шорподогу кичинекей сабизди көрүп, кайра эле тамак ичпей койдубу? Порциянын көлөмүн азайтып, формасын өзгөртүп көрүңүз. Чыгармачылык — эненин эң чоң куралы.','Köögiviljasõda jätkub 🥦','Kas ta keeldus jälle söömast, sest märkas supi sees tillukest porganditükki? Vähenda portsjoneid ja muuda toidu kuju. Loovus on ema suurim relv.'),
('acb2ca22-b3e3-4ac0-b344-a63734056dfa'::uuid,'Тиш жарып жатабы? 🦷','Наристеңиз баарын, өзгөчө өз колун оозуна салып жатабы? Шылекейи агып баштадыбы? Биринчи белгилерди дароо «Тиш чыгууну көзөмөлдөө» бөлүмүнө жазып алыңыз жана бул узак процесске даяр болуңуз.','Kas tulevad hambad? 🦷','Kas su beebi topib kõike, eriti oma käsi, suhu? Kas ila voolab? Märgi esimesed märgid kohe hammaste tuleku jälgijasse ja ole selleks pikaks protsessiks valmis.'),
('357bed80-6ac0-481c-9f5b-22bc1c97e3fe'::uuid,'Кичинекей колдорду таануу 🤲','Алар асылып турган оюнчуктарга атайылап жетүүгө аракет кылып жатышабы? Мотордук жөндөмдөрү өнүгүүдө! Бул жаңы кызыгуусун колдой турган коопсуз оюнчуктар үчүн «Сунушталган товарлар» бөлүмүн карап көрүңүз.','Väikeste käte avastamine 🤲','Kas ta üritab teadlikult rippuvate mänguasjadeni küündida? Tema motoorika areneb! Vaata jaotisest „Soovitatud tooted“ ohutuid haaramismänguasju, mis toetavad seda uut huvi.'),
('3c4bae00-6309-4214-a502-aa8dcb398a77'::uuid,'Аба ырайына көз салуу ⛅','Сыртка чыккыңыз келип, бирок терезеден карап эле аба ырайын аныктай албай жатасызбы? Наристеңизди ашыкча ороп, тердетип албаңыз. «Аба ырайы жана кийим» куралы бүгүнкү температурага ылайыктуу кийимди секунданын ичинде айтып берет.','Ilmaprognoos ⛅','Tahad õue minna, aga ei oska aknast välja vaadates ilma hinnata? Ära pane beebile liiga palju riideid selga, et ta higistama ei hakkaks. Lase ilma ja riietuse tööriistal sekunditega öelda, milline on tänaseks temperatuuriks ideaalne riietus.'),
('42bfdf13-2735-49dc-b527-89506330c670'::uuid,'Атанын ийини 👨‍👧','Чыдамыңыз түгөнүп, колуңуз ооруп жатабы? Бүгүн кечинде «Өнөктөш режимин» иштетиңиз. Наристени кекиртүү жана терметип уктоо — толугу менен өнөктөшүңүздүн милдети. Сиз болсо диванда эс алыңыз.','Issi õlad 👨‍👧','Kas kannatus on katkemas ja käed valutavad? Aktiveeri täna õhtul partnerirežiim. Beebi röhitamine ja kussutamine on täielikult sinu partneri töö. Sina lihtsalt lõõgastu diivanil.'),
('80a2cd79-a6d6-4c87-b540-c42931228485'::uuid,'Наристеңиздин курсагы чоңоюп жатат','Наристеңиздин канча тамак ичкенин жазып туруу жана күнүмдүк нормасын көзөмөлдөө үчүн «Тамактандырууну көзөмөлдөө» куралын колдонуңуз.','Sinu beebi kõht kasvab','Kasuta toitmise jälgijat, et kirja panna beebi söödud kogus ja jälgida tema päevast toidutarbimist.'),
('3d2a21ef-6e5b-4f36-9011-f9c3474762a4'::uuid,'Ыйлап жатат, бирок ачка эмеспи? 🧩','Эмне кылбаңыз, наристеңиз сооронбой жатабы жана ыйлаганы башкача угулуп жатабы? Божомолдоону токтотуңуз! «Ыйды талдоо» функциясы алардын ыйын угуп, көйгөй ич оорубу, газбы же уйкусу келип жатабы — дароо аныктап берет.','Nutab, aga kõht pole tühi? 🧩','Mida iganes sa ka ei teeks, beebi ei rahune ja tema nutt kõlab teisiti? Lõpeta oletamine! Lase nutuanalüüsil tema nuttu kuulata ja saa kohe teada, kas probleemiks on koolikud, gaasid või unepuudus.'),
('b092d275-f2d6-47ce-b8d0-3f8ced210589'::uuid,'Наушник жана кофе 🎧','Бүгүн чындап эле оор күн болду. Сезимдериңизди «Маанай күндөлүгүнө» төгүп салыңыз. Андан кийин кулакчыныңызды тагып, сүйүктүү музыкаңызды коюп, жылуу суусундук менен 10 мүнөттүк чыныгы тынчтыктан ырахат алыңыз.','Kõrvaklapid ja kohv 🎧','Tänane päev oli tõeliselt väljakutseterohke. Vala oma tunded välja meeleolupäevikusse. Seejärel pane kõrvaklapid pähe, pane mängima oma lemmikmuusika ja naudi 10 minutit tõelist vaikust koos sooja kofeiinijoogiga.'),
('0e43d226-9cd6-4c62-b9a7-e0206f0830ca'::uuid,'Ку-ку! Сюрприз! 🙈','Жашынмак ойноонун эрежелери өзгөрдү! Эми кичинекейиңиз жашынып алып, анан секирип чыгып, кубаныч менен «Мен бул жердемин!» деп кыйкырат. Оюндун эрежелерин алардын ойлоп табышына жол бериңиз жана бул жагымдуу күлкүдөн чогуу ырахат алыңыз.','Kuku! Üllatus! 🙈','Peitusemängu reeglid on muutunud! Nüüd peidab su väike põnn end ära ja hüppab siis välja, hüüdes õhinal: „Siin ma olen!“ Lase tal mängureegleid leiutada ja naudi seda rõõmsat naeru.'),
('6401ca5a-6403-42c9-b967-6741dd863d7c'::uuid,'Таймер тыныгууларды эстетүүгө жардам берет. 🍼','Anacan менен жалаяк алмаштырууну жана тамактандыруу убактысын оңой башкарыңыз.','Taimer aitab sul pause meeles pidada. 🍼','Halda Anacani abil mugavalt mähkmevahetusi ja toitmisaegu.'),
('c6fb2576-7fa6-4e01-b8a4-ec89ac753089'::uuid,'Эртең мененки жалаяк кырсыгы 💩','Наристеңиздин жалаягы толуп, шейшептерин алмаштыруу керек болуп ойгондуңузбу? Бул «жалаяк кырсыгын» «Жалаякты көзөмөлдөө» бөлүмүнө күлкү менен жазып коюңуз. Ооба, энелик бакыттын бир бөлүгү ушундай!','Hommikune mähkmeõnnetus 💩','Kas ärkasid üles ja leidsid, et beebi on mähkmeõnnetusest üleni koos ja voodilinad vajavad vahetust? Märgi see mähkmeäpardus mähkmete jälgijasse koos naeruga. Jah, ka see on emadus!'),
('022a6d7a-76fe-47e7-aae6-a35dad3d3555'::uuid,'Көзөмөлдөө убактысы ⏱️','Туруксуз тамактандыруу сизди чарчатып жатабы? «Тамактандырууну көзөмөлдөө» таймери менен наристеңиздин эмчекте же бөтөлкөдө канча убакыт болгонун өлчөп, анын калыптанып жаткан тартиби менен таанышыңыз.','Aeg kirja panna ⏱️','Kas ebaregulaarne toitmine väsitab sind? Tutvu beebi areneva rutiiniga, mõõtes toitmise jälgija taimeriga, kui kaua ta rinnal või pudelil aega veedab.'),
('39e6032f-d2bf-40b5-98db-1f2ab3a5a379'::uuid,'Түнкү тынчтык 🛀','Эгер бул өжөр жана кыжырдуу кечтердин бири болсо, жылуу ванна эң сонун жардам берет. Сууда ойноого уруксат берүү анын дарылык касиети менен бардык терс энергияны жууп кетишине шарт түзөт.','Öine rahu 🛀','Kui on üks neist jonnakatest ja ärritunud õhtutest, võib soe vann olla just see, mida vaja. Lihtsalt vees mängimine laseb vee teraapilisel jõul kogu negatiivse energia minema uhtuda.'),
('938dd21f-e30f-4b2b-b3e0-d79140f44b59'::uuid,'Келиңиз, дагы бир жолу жомок түзөлү! 🪄','Бул жолу «Акылдуу жомокторго» кызыктуураак тапшырма берели: Атасынын сакалына жашынган эргежээл жөнүндө жомок. Бул жасалма интеллект жараткан жомокту өнөктөшүңүзгө окутуп, бөлмөнү күлкүгө толтуруңуз.','Loome jälle muinasjutu! 🪄','Anname nutikatele lugudele seekord lõbusama ülesande: lugu päkapikust, kes peidab end isa habemesse. Lase partneril seda tehisintellekti loodud lugu jutustada ja täida tuba naeruga.'),
('1f0c7fc3-49b6-44d6-a78b-152d7ead7adc'::uuid,'Таза абадан дем алуу 🏃‍♀️','Үйдө отуруп тажадыңызбы, бирок наристеңиз менен кайда барарыңызды билбей жатасызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн коляска менен кирүүгө мүмкүн болгон жана эмчек эмизүүчү бөлмөсү бар эң жакын кафени таап, бир аз баарлашып келиңиз.','Sõõm värsket õhku 🏃‍♀️','Tunned end kodus vangis, aga ei tea, kuhu beebiga minna? Leia lähim lapsevankrisõbralik kohvik, kus on olemas imetamistuba, jaotises „Emadele sobivad kohad“ ja saa veidi suhelda.'),
('e8ec2cd2-3417-4383-8892-bb623cb07365'::uuid,'Убакытты токтотуу 📸','Алар абдан тез чоңоюп жатышат... Бүгүн кечинде, алар уктап жатканда, кичинекей өзгөчөлүктөрүнө бир көз чаптырыңыз. «Наристенин фотосессиясы» функциясы менен алардын кичинекей колдорун жана жүзүн сүрөткө тартып алып, убакытты токтотуп калыңыз.','Peatame aja 📸','Nad kasvavad nii kiiresti... Täna õhtul, kui nad magavad, võta hetk, et silmitseda nende pisikesi näojooni. Jäädvusta beebi fotosessiooni funktsiooniga pilt nende väikestest kätest ja näost ning trotsi aega.'),
('2a23a61b-4ca6-48f6-8845-f47a357eed0f'::uuid,'Ал үн эмнени билдирет? 🧩','Көзүн ачары менен эле ыйлап жатабы? Эмне үчүн экенин түшүнө албай жатсаңыз, кризисти секунданын ичинде чечмелөө үчүн «Ыйды талдоо» функциясын колдонуңуз.','Mida see hääl tähendab? 🧩','Kas ta niutsub ja nutab kohe, kui silmad avab? Kui sa ei suuda põhjust mõista, kasuta nutuanalüüsi funktsiooni, et kriis sekunditega lahti muukida.'),
('1c648ce0-799c-41f0-964a-90e59cbddc3d'::uuid,'Чоң жеңиш, бөлүшүлгөн сыймык 🥂','100 түн, 100 күн... Сиз менен бул чоң сапарды бөлүшүп жаткан өнөктөшүңүзгө караңыз. 100-күндүн сыймыгын «Маанай күндөлүгүнө» жазып, бири-бириңиздерди кол чабуулар менен куттуктаңыздар. Бул сиздердин командалык жеңишиңиздер!','Suur võit, jagatud uhkus 🥂','100 ööd, 100 päeva... Vaata oma partnerit, kes jagab sinuga seda vägevat teekonda. Kirjuta meeleolupäevikusse oma 100. päeva uhkus ja tehke üksteisele aplaus. See on teie meeskonna võit!'),
('52155593-73d7-4bb9-861d-d87a0ca100e9'::uuid,'Кереметтердин 100 күнү! 🎉','Ооба, жашооңуз түп-тамырынан бери өзгөргөнүнө туптуура 100 күн болду! Сиз укмуштуудай иш жасап жатасыз.','100 päeva imesid! 🎉','Jah, sellest on möödas täpselt 100 päeva, kui su elu põhjalikult muutus! Teed suurepärast tööd.'),
('13cad6d0-aa0a-426b-9515-1e96e73e716a'::uuid,'Жаңы ачылыштар 🤲','Наристеңиз колуна тийген нерсенин баарын оозуна салып жатабы? Дүрбөлөңгө түшпөңүз, бул алардын дүйнөнү таанып-билүү ыкмасы. Болгону, айлана-чөйрөнүн тазалыгына көз салып туруңуз.','Uued avastused 🤲','Kas su beebi topib kõike, mis kätte satub, suhu? Ära paanitse, nii ta maailma avastab. Lihtsalt veendu, et ümbrus oleks puhas.'),
('0695fd99-0b0d-4896-bd12-4ec8e6b49a4e'::uuid,'Өзүңүздү унутпаңыз, апа! 🍲','Алар тойду, бирок сизчи? Күчүңүздү калыбына келтирүү үчүн жакшы тамактанууңуз керек. Бүгүн өзүңүзгө даамдуу жана тоюмдуу тамак заказ кылыңыз.','Ära unusta iseennast, emme! 🍲','Nemad on kõhud täis söönud, aga sina? Pead oma energia taastamiseks hästi toituma. Telli endale täna üks maitsev ja toitev eine.'),
('cdd7b6ae-f340-479e-9d33-221c6775ebb3'::uuid,'Катуу ороону токтотуңуз: наристе эркин кыймылдасын! 🚫','Бала тарбиялоонун заманбап ыкмалары жана баалуу кеңештер үчүн биздин блогдорду окуп чыгыңыз.','Väldi liiga tihedat mähkimist: lase beebil vabalt liikuda! 🚫','Sukeldu meie blogipostitustesse, et leida väärtuslikke teadmisi ja kaasaegseid lähenemisi lapsevanemaks olemisele.'),
('957a90d0-61dc-45f5-a2da-ef7086521cd5'::uuid,'Бөлмөдөн күтүлбөгөн жерден чыккан күлкүнү уктуңузбу? 😂','Ооба, алар буга чейин эле катуу күлүп жатышат! Ошол үн сиздин бардык чарчооңузду унуткарат.','Kas kuulsid toas äkilist naerupahvakut? 😂','Jah, nad naeravad juba valjusti! See heli teeb kogu sinu väsimuse väärtuslikuks.'),
('53a91083-d8e0-4baf-9f90-46ce72a9291d'::uuid,'Сиздин күзгүдөгү досуңуз','Аларды күзгүгө алып барыңыз. Өз чагылышын көрүп таң калып, күлгөнүн көрүү — абдан жагымдуу көз ирмем.','Sinu peeglist sõber','Näita talle peeglit. See, kuidas ta oma peegelpilti imetleb ja itsitab, on üks ütlemata armas tegevus.'),
('2c4fbb59-42cd-4340-ba93-aee620d9df26'::uuid,'Ышкырып ырдоо 🎶','Ойноп жатып, балаңыз эми өзүнүн ойдон чыгарылган сөздөрү менен ыр ырдап жатат. Бул сүйлөө жана угуу жөндөмүнүн өнүгүп жатканынын сонун белгиси! Бул жаңы этапты «Өнүгүүнү көзөмөлдөө» бөлүмүнө жазып коюуну унутпаңыз.','Ümisemine 🎶','Mängides laulab su laps nüüd endale oma väljamõeldud sõnadega laule. See on suurepärane märk nii kõne kui ka kuulmise arengust! Ära unusta seda uut etappi oma arengupäevikusse kirja panna.'),
('491d12b8-51d5-4984-8dda-d40fbb4e95c8'::uuid,'Атанын жомок айтып берүүсү 📖','Бүгүн кечинде бөлмөдө башкача атмосфера түзөлү. Уктаар алдындагы жомокту атасынын терең, ишенимдүү үнүнө тапшырып, өзүңүз бир аз четтеп, чыныгы тынчтыктан ырахат алыңыз.','Issi unejutud 📖','Loome täna õhtul toas teistsuguse atmosfääri. Usalda unejutu lugemine issi sügava ja rahustava hääle hooleks ning astu kõrvale, et nautida täielikku vaikust.'),
('1b82205e-3e0a-48f0-abf7-dac783f4bce8'::uuid,'Сүтүңүз калорияга бай сүткө айланып жатат! 🥛','Эмчек эмизүү таймерин иштетип, наристеңиздин бүгүн канча тамактанганын так өлчөңүз!','Sinu piim muutub toitainerikkamaks! 🥛','Lülita sisse rinnaga toitmise taimer ja mõõda täpselt, kui palju su beebi täna sõi!'),
('96d4756e-270f-426b-9e78-f2a573accdac'::uuid,'Сейилдөө убактысы! 🌳','Төрт дубалдын ичинде отуруп тажадыңызбы? Наристеңизди коляскага салып, жок дегенде 15 мүнөт таза абага чыгып келиңиз. Бул экөөңүздөргө тең абдан пайдалуу болот.','Aeg õue minna! 🌳','Tunned end nelja seina vahel vangis? Pane beebi vankrisse ja mine kasvõi 15 minutiks värske õhu kätte. See mõjub teile mõlemale imehästi.'),
('9a18572b-e386-4df8-ba20-b5eb78b8f99f'::uuid,'Алғашкы 10 күн кандай өттү? 📸','Уйкусуз түндөр, тынчсыздануулар, кээде көз жаш жана чексиз сүйүү... Сиз эң оор башталгыч болгон алгачкы 10 күндү артта калтырдыңыз! Сиз укмуштуудайсыз.','Kuidas möödusid esimesed 10 päeva? 📸','Magamata ööd, mured, vahel pisarad ja ülepeakaela tulvav armastus... Oled juba esimesed 10 päeva, selle kõige raskema alguse, seljataha jätnud! Sa oled uskumatu.'),
('1063f207-152c-4454-9267-2e05e30929d8'::uuid,'Тынчтык жана эс алуу 🤫','Уктап жатканда капыстан чыккан үндөр аларды ойготуп жатабы? Бөлмөдөгү үндүн деңгээлин көзөмөлдөө үчүн «Үн өлчөгүчтү» колдонуңуз.','Teadlik vaikus 🤫','Kas äkilised helid äratavad beebi uinumisel? Kasuta helitaseme mõõdikut, et jälgida toas lubatud detsibellide taset.'),
('17c1a37e-ab5c-4032-afa2-27e4d0964076'::uuid,'Бул оорубу же жөн гана чарчообу? 😭','Наристеңиз эч себепсиз ыйлап жатабы жана ыйлаганы башкача угулуп жатабы? Бул ачкалык эмес, жөн гана уйкусу канбай жаткан болушу мүмкүн. Алардын уйку графигин кылдаттык менен көзөмөлдөңүз.','Kas see on valu või lihtsalt väsimus? 😭','Kas beebi nutab ilma nähtava põhjuseta ja tema nutt kõlab teisiti? See ei pruugi olla nälg, vaid lihtsalt unepuudus. Jälgi hoolikalt tema unegraafikut.'),
('c32299af-eeac-42f3-ab67-01688b0d4551'::uuid,'Апалардын колдоо тобу 💬','Оор чечим кабыл алууга туура келип жатабы? (Бала бакча, горшокко үйрөтүү, уйку). «Anacan коомчулугундагы» тажрыйбалуу энелердин кеңештери китептерде жок эң реалдуу чечимдерди сунуштайт.','Emade tugigrupp 💬','Seisad keerulise valiku ees? (Lasteaed, potitreening, uni). Anacani kogukonna kogenud emade nõuanded pakuvad kõige elulisemaid lahendusi, mida raamatutest sageli ei leia.'),
('0240c7db-30e2-4d5b-86a4-0b27f230557c'::uuid,'Атанын кучагы 🫂','Биринчи жуманын чарчоосу сизди абдан алсыратты. Бүгүн кечинде атасы наристени көкүрөгүнө жаткырып уктатсын жана «Ак ызы-чууну» (White Noise) иштетиңиз. Сиз болсо жылуу душка түшүп, ваннанын эшигинин артында 15 мүнөт баарын унутуп эс алыңыз. Сиз муну жасай аласыз.','Issi süli 🫂','Esimese nädala väsimus on sügavalt sinusse pugenud. Las täna õhtul issi rahustab beebi oma rinnal magama ja pane tööle valge müra. Sina aga võta soe dušš ja unusta 15 minutiks suletud vannitoaukse taga kõik muu. Sa saad hakkama.'),
('e3d8f3ea-e67f-48ce-87e1-b51ae00dba4f'::uuid,'Баары жакшы ✔️','Кээ бир күндөрү эч нерсеге жетишпей жаткандай сезилиши мүмкүн. Бирок наристеңиздин таза кийимине, ток курсагына караңыз. Сиз укмуштуудай энесиз!','Kõik on korras ✔️','Mõnel päeval võib tunduda, et sa ei jõua suurt midagi. Aga vaata oma pisikese puhtaid riideid ja täis kõhtu. Sa teed suurepärast tööd, emme!'),
('8d072236-96cb-4886-b83d-b2d8d6523abb'::uuid,'Жолуңузду эстеп көрүңүз 📈','Ал кездеги коркууларыңызды эстеңиз. Эми өзүңүздүн канчалык жөндөмдүү жана ишенимдүү эне болуп калганыңызга караңыз. Жетишкендиктериңиз менен сыймыктаныңыз!','Mõtiskle oma teekonna üle 📈','Mõtle tagasi neile algusaegade hirmudele. Nüüd vaata, milliseks võimekas ja enesekindlaks emaks oled sa kasvanud. Ole uhke selle üle, kui kaugele oled jõudnud!'),
('1c02ca47-65ab-4daa-8468-3f801795414a'::uuid,'Башаламандыкты кабыл алыңыз! 🌪️','Ар кечинде оюнчуктарды жыйнап чарчадыңызбы? Бүгүн өзүңүзгө эс бериңиз! Үйүңүз музей эмес, бул жерде кичинекей изилдөөчү чоңоюп жаткан жандуу мейкиндик.','Naudi segadust! 🌪️','Oled väsinud igal õhtul samu mänguasju koristamast? Anna endale täna vaba õhtu! Sinu kodu ei ole muuseum; see on elav ruum, kus kasvab väike avastaja ja elu käib.'),
('61f15500-8617-42e1-b833-c482f6ae935c'::uuid,'Наристеңиз оюнчуктарды ыргытып жатабы? 🧸','Алар себеп-натыйжа байланышын үйрөнүп жатышат! Бул этапты колдогон жаңы оюнчуктар үчүн «Сунушталган товарларды» карап көрсөңүз болот.','Kas beebi loobib mänguasju? 🧸','Nad õpivad põhjus-tagajärg seoseid! Uute mänguasjade leidmiseks, mis seda etappi toetavad, tutvu meie soovitatud toodetega.'),
('92d9f590-3160-4e15-966d-3ee82f9db1d0'::uuid,'Ооз аркылуу таануу! 🦷','Алар баарын, өзгөчө манжаларын катуу чайнап жатышабы? «Тиш чыгууну көзөмөлдөө» белги берип жатат! Таза тиш чыгаргычтарды даярдап коюучу убакыт келди.','Suuga avastamine! 🦷','Kas nad närivad intensiivselt kõike, eriti oma sõrmi? Hammaste tuleku jälgija annab märku! On aeg valmis panna puhtad närimisrõngad.'),
('02654c5d-e5dc-4168-b20f-e995771e2a24'::uuid,'Колдоонун күчү 💬','Бүгүн кечинде Anacan коомчулугуна кошулуп, наристеси сиздики менен тең курактагы башка энелер менен таанышып, балаңыздын өнүгүүсү тууралуу ой бөлүшүңүз.','Toe jõud 💬','Liitu täna õhtul Anacani kogukonnaga ja võta ühendust teiste emadega, kelle beebid on sama vanad, et jagada ja arutada oma pisikese arengu üle.'),
('158eaa65-78bb-40d6-8e0b-a66fa8dda6b3'::uuid,'Өзүңүз менен сыймыктаныңыз! 👏','Айланаңызга карап, канчалык жолду басып өткөнүңүздү ойлонуңуз. Алгачкы жумалардагы тынчсыздануулар азыр толук энелик ишенимге айланды. Сиз укмуштуудайсыз!','Ole enda üle uhke! 👏','Vaata enda ümber ja mõtiskle, kui kaugele oled jõudnud. Esimeste nädalate ärevus on asendunud täieliku emaliku enesekindlusega. Sa oled imeline!'),
('7449500c-dd2f-4529-a9a7-67ddeee4fe31'::uuid,'Курсак менен жатуу убактысы! 🐢','Ойгоо кезинде наристеңиздин булчуңдарын чыңдоо үчүн 1-2 мүнөт «Ичи менен жатуу» көнүгүүсүн жасатыңыз.','Kõhuli olemise aeg! 🐢','Lase beebil ärkveloleku ajal 1–2 minutit kõhuli olla, et aidata tal lihaseid tugevdada.'),
('50a6a489-6955-49c4-9f2c-e768f813dd17'::uuid,'Буттун бармактары ооздо! 👣','Алар буттарын таап, оозуна салууга аракет кылып жатышат! Бул күлкүлүү жана сонун өнүгүү этабын сүрөткө тартып алып, жакындарыңыз менен бөлүшүүнү унутпаңыз.','Varbad suhu! 👣','Nad on avastanud oma jalad ja üritavad neid suhu pista! Jäädvusta see naljakas ja imeline arenguetapp, et seda oma lähedastega jagada.'),
('4d4822a8-2d08-4775-b1d8-71202fa22509'::uuid,'Апа үчүн энергия 🔋','Балаңызды эмизип жатканда, сиз да калория жоготосуз! «Дени сак тамактануу» бөлүмүнөн сүтүңүздү көбөйтүүчү жеңил шорпонун рецептин дароо карап көрүңүз.','Energia emmele 🔋','Kui beebi imeb rinda, põletad ka sina kaloreid! Vaata kohe meie Tervislike retseptide jaotisest kerget, rinnapiima teket soodustavat supiretsepti.'),
('890c1216-15b7-4852-b1cb-42e4a141e897'::uuid,'Көздөө жана кармоо ⚾','Кичинекейиңиз эми ыргыткан чоң топту өткөрүп жибербей, аны кармоого аракет кылып жатат! Анын кол жана көз координациясы тездик менен өнүгүүдө. Коридордо аны менен кызыктуу топ оюндарын ойноңуз.','Sihtimine ja püüdmine ⚾','Sinu pisike ei lase enam sinu visatud suurt palli lihtsalt mööda, vaid püüab seda nüüd aktiivselt kinni püüda! Tema käe-silma koordinatsioon areneb kiiresti. Mängi temaga esikus lõbusaid ja interaktiivseid pallimänge.'),
('dac4f6ca-f7b7-40a3-a427-dece1b15eaf7'::uuid,'Өсүүнү көзөмөлдөө: бою жана салмагы! 📏','«Өнүгүүгө көз салуу» бөлүмүнө акыркы көрсөткүчтөрдү киргизиңиз, андан соң балаңыздын дени сак өнүгүү графигин карап, анын жетишкендиктери менен сыймыктаныңыз!','Kasvu jälgimine: pikkus ja kaal! 📏','Uuenda Arengujälgija jaotises viimaseid mõõte, vaata seejärel oma beebi tervisliku arengu graafikut ja tunne tema edusammude üle uhkust!'),
('648c9f9b-15f6-49e6-933c-3da395b58c88'::uuid,'Туруктуу аракеттер! 🐢','Ичи менен жатканда алдыга жылууга аракет кылып, кыжыры келип жатабы? Ал кыймылдоого абдан ынтызар! Оюнчуктарга жетүүгө жана өзүн алдыга түртүүгө үндөңүз.','Püsivad pingutused! 🐢','Kas ta ärritub, kui püüab kõhuli olles edasi liikuda? Ta tahab nii väga liikuda! Julgusta teda mänguasjade poole sirutama ja end edasi lükkama.'),
('903de81c-9443-4b1e-8662-d8cbed1ca54e'::uuid,'Тиш чыгаргычтар жардамга келет! 💧','Кичинекейиңиз баарын оозуна салып изилдеп жатат. Анын коопсуздугун камсыз кылуу жана өнүгүүсүн колдоо боюнча көбүрөөк билүү үчүн биздин блогдорго баш багыңыз.','Närimisrõngad appi! 💧','Sinu pisike avastab maailma, pannes kõike suhu. Mine meie Blogidesse, et lugeda lähemalt, kuidas tagada tema ohutus ja toetada tema arengut.'),
('9dd94bee-b76e-43ec-94c9-51937e10ad6e'::uuid,'Бүгүн үй жыйноо жок! 🛑','Өзүңүздү чарчаңкы сезип жатасызбы? Бул тууралуу жолдошуңузга айтыңыз. Бүгүн тамак жасоо да, тазалоо да жок. Бүгүн жөн гана апалардын эс алуу күнү!','Täna koristamist ei toimu! 🛑','Tunned end kurnatuna? Ütle seda oma partnerile. Täna ei tehta süüa ega koristata. Täna on lihtsalt emme vaba päev!'),
('1a9e3246-5c48-4c5d-9be8-b35243065267'::uuid,'Үйдө эмне жетишпей жатат? 🛒','Шампунь же балдар майы түгөнүп калдыбы? Капа болбоңуз. Жөн гана аны соода тизмесине кошуп коюңуз – калганы жолдошуңуздун милдети!','Mis kodus puudu on? 🛒','Šampoon või beebiõli hakkab otsa saama? Pole vaja muretseda. Lisa see lihtsalt ostunimekirja – ülejäänu on sinu partneri missioon!'),
('6e836ffa-475e-446a-bc5a-eddbd0eeeec4'::uuid,'Чууну чыпкалаңыз 🤫','Көчөдөгү ызы-чуу терең уйкуга тоскоол болушу мүмкүн. Үн өлчөгүчтү текшерип, керек болсо ак ызы-чууну (white noise) колдонуңуз.','Filtreeri müra 🤫','Tänavamüra võib sügavat und häirida. Kontrolli helimõõtjat ja kasuta vajadusel taustaks valget müra.'),
('e31b222d-5c34-45e3-b291-c3f8c8989d13'::uuid,'Сулуу жана кайталангыс Сиз! 💇‍♀️','Көйнөгүңүздө так болушу мүмкүн, чачыңыз иретсиз болушу мүмкүн. Бирок балаңыздын көзүндө сиз дүйнөдөгү эң сулуу адамсыз. Өзүңүзгө өтө катуу талап койбоңуз!','Kaunis ja ehtne sina! 💇‍♀️','Sinu särgil võib olla plekk ja juuksed sassis. Kuid oma beebi silmis oled sa maailma kõige ilusam inimene. Ära ole enda vastu nii karm!'),
('29aebaa9-a1ae-4a00-8854-a771800bf560'::uuid,'Эмизүү тыныгууларын жөнгө салуу. 🍼','«Тамактандырууга көз салуу» куралын колдонуп, тамактандыруу жана ойгоо убактысын белгилөө менен идеалдуу тартипти түзүңүз.','Toitmispauside kohandamine. 🍼','Loo täiuslik rutiin, jälgides toitmise ja ärkveloleku aegu Toitmisjälgija tööriista abil.'),
('3942c763-be60-481b-bb4e-1a53687a8d34'::uuid,'Атанын берилгендиги 💖','Ал да жумушта чарчап келди, бирок эми аталык милдетти аткаруу кезеги анда. Анын баланы акырын уктатып жатканын карап, бул бактылуу көз ирмемден ырахат алыңыз.','Isa pühendumus 💖','Ka temal oli pikk tööpäev, aga nüüd on tema kord isakohustusi täita. Vaata, kuidas ta beebi õrnalt magama paneb, ja naudi seda õnnelikku hetke eemalt.'),
('3cd07d9d-076c-4523-8ba1-47b8737d6bbf'::uuid,'Ку-ку! Мен бул жердемин! 👀','Бөлмөнүн аркы четинен балаңызды атынан чакырып көрүңүз. Ал үн чыккан тарапка бурулуп, түз эле сизге караганын көрөсүз. Анын угуусу жана көңүл буруусу эң сонун өнүгүүдө!','Kuku! Ma olen siin! 👀','Proovi hüüda oma beebit nimepidi teises toanurgas olles. Tõenäoliselt näed, kuidas ta pöörab end heli suunas ja vaatab otse sulle otsa. Tema kuulmine ja tähelepanu arenevad suurepäraselt!'),
('25015c8c-0ca6-43bc-a465-c8490ee6d808'::uuid,'Кичинекейиңиз Сизди абдан жакшы көрөт! 🥰','Кичинекейиңиз эмип жатканда же тамактанып жатканда сизге тигиле карайбы? Ал сиздин жүзүңүздүн өзгөчөлүктөрүн изилдеп жатат жана сизди абдан жакшы көрөт!','Sinu pisike jumaldab sind! 🥰','Kas sinu pisike vaatab sind imetamise või söömise ajal ainiti? Ta uurib sinu näojooni ja jumaldab sind täielikult!'),
('565cbb4c-39dd-4c69-980a-b02d63f6cdb4'::uuid,'Бир аз ыңгайлуулук 🛋️','Оор күндөн кийин сезимдериңизди «Маанай күндөлүгүнө» жазып коюңуз. Эсиңизде болсун, сезимдерди кагазга түшүрүү – эң мыкты акысыз терапия болушу мүмкүн.','Natuke mugavust 🛋️','Pärast rasket päeva pane oma tunded kirja Tujupäevikusse. Pea meeles, et päeviku pidamine ja emotsioonide väljendamine võib olla parim tasuta teraapia.'),
('f0338702-1ba5-495b-840d-9ad790085c24'::uuid,'Сиздин чөнтөк педиатарыңыз 🤖','Балаңыздын заңынын түсү адаттагыдан башкачабы же денесинде бүдүрлөр барбы? Дүрбөлөңгө түшөрдөн мурун, мүмкүн болгон себептерин түшүнүү үчүн Anacan AI''дан жардам сураңыз.','Sinu taskupediaater 🤖','Kas sinu beebi kaka on ebatavalist värvi või on tal väike lööve? Enne paanikasse sattumist küsi Anacan AI-lt abi võimalike põhjuste mõistmiseks.'),
('5996a5e8-c639-4f34-8f02-ccaebf8a96eb'::uuid,'Алек болгон кичинекей колдор! 👐','Балаңыз чоң нерселерди эки колу менен бир убакта кармоого аракет кылып жатабы? Бул жетишкендикти өнүгүү трекерине белгилеп коюңуз жана жумшак топту сунуштап көрүңүз!','Tegevust täis väikesed käed! 👐','Kas sinu beebi püüab haarata suuri esemeid mõlema käega korraga? Märgi see saavutus arengujälgijasse ja proovi talle pakkuda pehmet palli, et näha, mis juhtub!'),
('6dd3138c-1bd5-4dac-80d8-a5b5ffa166ee'::uuid,'Өтө ысыкпы же өтө суукпу? ⛅','Баланы кийиндирүү дайыма табышмакпы? Биздин «Аба ырайы жана кийим» куралыбыз сизге канча катмар кийим кийгизүү керектигин так айтып берет. Акыл-эсиңизди башка маанилүү иштерге сактаңыз!','Liiga palav või liiga külm? ⛅','Kas beebi riietamine on alati paras peamurdmine? Lase meie Ilma ja riietuse tööriistal sulle täpselt öelda, mitu kihti valida. Säästa oma ajumahtu muudeks asjadeks!'),
('a1ca42ca-05ed-42dc-af4a-99af31043623'::uuid,'Апанын үнүнүн сыйкыры 🎶','Эч бир тиркеме эненин бешик ырын алмаштыра албайт. Бүгүн кечинде кичинекейиңизди кучагыңызга бекем кысып, анын сүйүктүү ырын акырын ырдап бериңиз.','Emme hääle võlu 🎶','Ükski äpp ei suuda kunagi asendada ema unelaulu. Täna õhtul hoia oma pisikest lihtsalt rinna vastas ja laula talle vaikselt tema lemmikviisi.'),
('b0613bc2-510c-4582-8829-fd09f1ed2898'::uuid,'Даамдарга кызыгып жатасызбы? 🍽️','Сиз тамактанып жатканда кичинекейиңиз тарелкаңызды жана оозуңузду кунт коюп карап жатабы? Кошумча тамакка (кошумча азыктарга) болгон кызыгуусу акырындап башталып жаткандыр!','Kas oled maitsetest huvitatud? 🍽️','Kas sinu pisike jälgib söömise ajal pingsalt sinu taldrikut ja suud? Huvi tahke toidu (lisatoidu) vastu võib olla tasapisi tekkimas!'),
('cd2a678b-9234-4910-9725-95b0b9e3443e'::uuid,'Кечки тартип: Уйку поездине билетиңиз 🚂','Жылуу ванна, акырын укалоо жана бөлмөнүн жарыгын өчүрүү... Бул тынчтандыруучу кечки тартипти эч качан калтырбаңыз.','Õhtune rutiin: sinu pilet unemaale 🚂','Soe vann, õrn massaaž ja hämar tuba... Ära kunagi jäta seda rahustavat une-eelset rutiini vahele.'),
('cfb5c864-525c-4db1-869c-94c18824f78e'::uuid,'Күнүмдүк шашылышта түшкү тамакты тике туруп ичпеңиз! 🥑','«Дени сак тамактануу» бөлүмүнөн жеңил салат даярдап, отуруп алып ар бир тиштеген тамагыңыздан ырахат алыңыз.','Ära söö lõunat kiirustades püsti seistes! 🥑','Valmista meie Tervislikest retseptidest üks lihtne salat ja istu maha, et nautida iga suutäit.'),
('3325dc87-cd45-494c-a42f-d923bde10bc2'::uuid,'Күлкү ирмеми 📸','Ал күн сайын көбүрөөк күлүп жатат! «Ымыркайдын сүрөт сессиясы» функциясын ачып, күнүңүздөгү бардык терс ойлорду кууп чыга турган кубанычтуу күлкүсүн тартып алыңыз.','Naerusuine hetk 📸','Ta naerab iga päevaga üha rohkem! Ava Beebi fotosessiooni funktsioon ja jäädvusta rõõmus itsitus, mis peletab sinu päevast igasuguse negatiivsuse.'),
('37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8'::uuid,'Жоошутуучу жомок 🪄','«Акылдуу жомоктор» бөлүмүндө кичинекей баатырыңыздын беш айлыгына карата жомок түзүп, бөлмөнү жагымдуу маанайга толтуруңуз.','Lohutav lugu 🪄','Loo Nutikates lugudes muinasjutt oma väikesest kangelasest, kes valmistub oma viiendaks elukuuks, ja täida tuba armsa atmosfääriga.'),
('0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2'::uuid,'Ымыркай тынчтанбай, Сиз чарчап калдыңызбы? 🛑','Балаңызды бешигине коопсуз жаткырып, 5 мүнөткө башка бөлмөгө чыгып кетиңиз. Сиз да бир аз дем алууга татыктуусуз.','Beebi ei rahune ja oled kurnatud? 🛑','Aseta beebi turvaliselt võrevoodisse ja mine vaid 5 minutiks teise tuppa. Ka sina väärid hetke hingetõmbeks.'),
('1f6b52bc-5331-4372-8c65-f0f6ee109098'::uuid,'Ыйды талдоочу 😭','Сиз бөлмөгө кайтып келдиңиз, ал эми наристеңиз кайрадан ыйлап жатат. Кабатыр болбоңуз! Ыйдын анализи функциясын дароо колдонуп, анын эмне үчүн ыйлап жатканын билип алыңыз жана муктаждыгына жараша сооротуңуз.','Nutuanalüsaator 😭','Sa tulid tuppa tagasi ja ta nutab jälle. Ära muretse! Kasuta kohe Nutuanalüüsi funktsiooni, et kuulata tema nuttu ja rahustada teda, vastates tema konkreetsele vajadusele.'),
('90149fde-54c0-4d98-ba95-374230a626e1'::uuid,'Колдорду оозго салып изилдөө 🦷','Наристеңиз баарын эле оозуна салып чайнап жатабы? Жылуу, таза чүпүрөк анын тиш эттерин тынчтандырууга жардам берет.','Kätega suu avastamine 🦷','Kas sinu beebi närib kõike isukalt? Soojad ja puhtad lapid võivad pakkuda tema igemetele rahustavat leevendust.'),
('6065edb3-ae62-4429-96cf-e894b4e2c7d8'::uuid,'Түнкү баатырлар 🦸‍♀️','Түнкүсүн ойгонуу абдан чарчатышы мүмкүн, биз сизди түшүнөбүз. Чарчаганыңызды Маанай күндөлүгүнө жазып коюңуз жана өмүрлүк жолдошуңуздан сизге керектүү колдоо көрсөтүүсүн сураныңыз.','Öised kangelased 🦸‍♀️','Öised ärkamised võivad olla äärmiselt kurnavad, me mõistame seda. Pane oma väsimus kirja Tujupäevikusse ja palu partnerilt hädavajalikku tuge.'),
('ad21218a-5e7d-436c-9c74-264990c096bd'::uuid,'Мени көрүп жатасызбы, апа? 🧸','Оюнчукту жууркандын астына жарым-жартылай катып коюңуз. Наристеңиз аны издеп табабы? Бул анын буюмдардын туруктуулугун түшүнүү жолундагы эң сонун өнүгүү кадамы!','Kas sa näed mind, emme? 🧸','Peida mänguasi pooleldi teki alla. Kas sinu beebi otsib ja leiab selle üles? See on fantastiline arengusamm esemete jäävuse mõistmise suunas!'),
('faba44da-b2fb-4aa7-a374-4d5f04ad9d27'::uuid,'Сейилдөө сөзсүз керек! ⛅','Аба ырайы жана кийим тандоо куралын текшерип, наристеңизди кийиндирип, сейил бакта кеминде 20 мүнөт сейилдеп келиңиз. Бул экөөңүздөр үчүн тең абдан маанилүү!','Jalutuskäigud on kohustuslikud! ⛅','Vaata Ilma ja riietuse tööriista, riieta oma beebi ja jaluta pargis vähemalt 20 minutit. See on teile mõlemale hädavajalik!'),
('ba7edb24-6da8-4a69-9b59-da2faf81dfa6'::uuid,'Биргелешкен алгачкы сейилдөөлөрүңүз! 🌳','Эгер аба ырайы жакшы болсо, сыртка чыгыңыз! Наристеңиздин күн сайын таза абада болушу анын ден соолугу үчүн өтө маанилүү жана пайдалуу.','Teie esimesed ühised väljaskäigud! 🌳','Kui ilm on ilus, minge õue! Sinu beebi jaoks on väga oluline ja kasulik saada iga päev värsket õhku.'),
('46a6fe4d-c7d7-4c66-88f8-3a6a534cd295'::uuid,'Дарыгердей акылдуу 🤖','Наристеңиздин кыймыл-аракетинде бир нерсе туура эместей сезилип жатабы? Интернеттеги кооптуу маалыматтарды окуй бербей, Anacan AI аркылуу так жоопторду алыңыз.','Nii tark kui arst 🤖','Kas sinu beebi liigutustes tundub midagi veidi valesti olevat? Selle asemel, et lugeda internetist hirmutavaid lugusid, saa täpsed vastused Anacan AI-lt.'),
('ac9907ff-b075-4451-8252-dbc842968901'::uuid,'Атадан бешик ыры 👨‍🍼','Өнөктөш режиминде эскертмелер өнөктөшүңүзгө келет. Бүгүн кечинде жомок окуп, бешик ырын ырдоону ага тапшырыңыз, ал эми сиз жөн гана байкоо жүргүзүп эс алыңыз.','Issi hällilaul 👨‍🍼','Partnerirežiimis lähevad teavitused sinu partnerile. Lase tal täna õhtul unejuttu lugeda ja unelaulu laulda, samal ajal kui sina lihtsalt jälgid.'),
('a764d770-048d-4a17-b477-fc4f761c3c2d'::uuid,'Жомоксуз уйку жок 🪄','Бөлмөдөгү жарыкты толугу менен өчүрүңүз. ''Акылдуу жомоктор'' функциясын колдонуп, наристеңиздин тез уктап кетиши үчүн жаратылыш үндөрү (шамал же токой сыяктуу) менен тынчтандыруучу фон түзүңүз.','Ei mingit und ilma loota 🪄','Tee tuba täiesti hämaraks. Kasuta funktsiooni ''Nutikad lood'', et luua sõnadeta rahustav taust vaid loodushelidega (nagu tuul või mets), mis aitab tal kiiremini uinuda.'),
('aedfce5f-449d-49c9-8f9b-a5ac88f1e750'::uuid,'Сиздин таңкы концертиңиз! 🎶','Ал сизге карап, ар кандай муундарды айтып, жылмайып жатабы? Ал азыр сизге эң сонун таңкы концерт тартуулап жатат – кунт коюп угуңуз!','Sinu hommikune kontsert! 🎶','Kas ta vaatab sind ja lallitab laia naeratusega erinevaid silpe? Ta annab sulle praegu kõige ilusama hommikukontserdi – kuula hoolega!'),
('46db3cbc-ae0b-4520-b12e-5586db9977cf'::uuid,'Уйку тартиби боюнча күмөн санап жатасызбы? 🤖','Беш айлык курактагы уйкунун өзгөрүшү боюнча суроолоруңуз барбы? Аларды Anacan коомчулугуна жазып, башка энелерден колдоо алыңыз.','Kas pole kindel unerežiimis? 🤖','Kas sul on küsimusi unemuutuste kohta 5. elukuu paiku? Postita need Anacan Kogukonda ja saa tuge teistelt emadelt.'),
('b203fb94-1780-44e0-8f8f-1e6840729e68'::uuid,'Үндү көзөмөлдөө 🤫','Төртүнчү айдын аягында уктоо кээде бир аз кыйын болушу мүмкүн. Үн өлчөгүчтү күйгүзүп, үн чегин текшериңиз жана бөлмө караңгы экенине ынаныңыз.','Helikontroll 🤫','Uinumine võib neljanda kuu lõpus muutuda veidi keeruliseks. Lülita sisse helimõõtja, kontrolli helipiiri ja veendu, et tuba oleks täiesti pime.'),
('d7985574-7fae-4ef9-b025-2442a8b0b3a6'::uuid,'Сиз сонун кылып жатасыз! 💖','Кемчиликсиз ата-эне деген болбойт, бирок наристеңиз үчүн сиз эң мыкты энесиз.','Sa teed suurepärast tööd! 💖','Täiuslikku lapsevanemat pole olemas, kuid oma beebi jaoks oled sa vaieldamatult parim ema.'),
('2e9ea238-ddc7-4932-b1bd-be8b8ed87bc9'::uuid,'Энергияңызды калыбына келтириңиз! 🍲','Сиз өзүңүздү жакшы сезсеңиз, наристеңиз да жакшы болот. «Дени сак рецепттер» бөлүмүнөн даамдуу жана күч-кубат бере турган торттун рецептин тандап, кофеңиз менен ырахаттанып ичиңиз.','Lae oma energiavarusid! 🍲','Kui sina õitsed, õitseb ka sinu beebi. Vali Tervislikest retseptidest üks maitsev ja energiat andev koogiretsept ning naudi seda koos kohviga.'),
('d25e75e7-0029-43b9-b1e7-c401d6b9ca28'::uuid,'Акылдуу жомокчу 🪄','Бүгүн кечинде «Акылдуу жомоктор» бөлүмүндө наристеңиздин беш айлык болуп, кантип тез чоңоюп жатканы тууралуу өзгөчө, жүрөккө жылуу тийген жомок ойлоп табыңыз.','Nutikas jutuvestja 🪄','Loo täna õhtul Nutikates lugudes eriline ja südamlik muinasjutt sellest, kui kiiresti sinu pisike oma viiendasse elukuusse kasvab.'),
('6a21d9c4-96ab-4453-9d5f-d8979016e2cc'::uuid,'Өз алдынчалыкка карай жолдо! 🤸‍♂️','Наристеңиз чалкасынан ичине оодарылып жатабы? Анын булчуңдары тез өнүгүп жатат! Кыймыл-аракетин өнүктүрүү үчүн аны үзгүлтүксүз атайын төшөкчөгө жаткырып, курсагы менен жатууга көндүрүңүз.','Iseseisvuse teel! 🤸‍♂️','Kas sinu beebi keerab end juba vaevata seljalt kõhule? Tema lihased arenevad kiiresti! Julgusta mugavat liikumist, pannes teda regulaarselt mängumatile kõhuli aega veetma ja maailma avastama.'),
('515f484e-8ce4-4442-bca4-24b38a77b194'::uuid,'Жалаяк которуу расмий түрдө адатка айланды! 👶','Наристеңиздин ден соолугун көзөмөлдөө үчүн анын күнүмдүк жалаяк алмаштыруусун «Жалаяк трекерине» белгилеп туруңуз.','Mähkmevahetus on nüüd ametlikult rutiin! 👶','Taga oma beebi heaolu, märkides tema igapäevased märjad ja mustad mähkmed Mähkmejälgijasse.'),
('c057830d-8790-40ec-a09d-53a252d3ee15'::uuid,'Күнөөлүү сезимден арылыңыз 🛑','Бүгүн чыдамыңыз кетип, үнүңүздү көтөрүп алдыңызбы? Өзүңүздү күнөөлөбөңүз. Сиз чарчабас робот эмессиз. Эртең баарын кайрадан жакшы баштасаңыз болот.','Lase süütundest lahti 🛑','Kas sinu kannatus katkes täna ja sa tõstsid häält? Ära tunne end süüdi. Sa ei ole väsimatu robot. Sa võid alati homme uuesti proovida.'),
('fd786e6d-a723-4c95-b0ff-52e01e6ccb8a'::uuid,'Сиз жалгыз эмессиз 💬','Anacan коомчулугунда башка 5 айлык наристеси бар энелер эмнелерди бөлүшүп жатканын карап көрүңүз. Ар бир үйдөгү окшош түйшүктөрдү, уйкусуз түндөрдү жана чексиз сүйүүнү көрөсүз!','Sa ei ole üksi 💬','Piilu, mida teised 5-kuuste beebide emad Anacan Kogukonnas jagavad. Sa näed igas kodus sama ilusat kaost, samu magamata öid ja sama ülevoolavat armastust!'),
('0f2d9f90-69e8-4777-adab-24eab59b69a5'::uuid,'Тамактануу учурундагы кежирликтер 🥣','Наристеңиз эки тиштегенден кийин эле тоюп калганын айтып, чуркап кетип жатабы? Аны мажбурлабаңыз. Тамак менен туура мамиле түзүү тарелкасын тазалап жегенден алда канча маанилүү.','Söömisaja jonnihood 🥣','Kas sinu pisike ütleb pärast kaht suutäit, et tal on kõht täis, ja jookseb minema? Ära sunni teda. Tervisliku toidusuhte loomine on olulisem kui taldriku tühjaks söömine.'),
('05aab0a6-c49b-4d4d-bd26-b20d5c9af4d5'::uuid,'Уйку келгенинин белгилерин өткөрүп жибербеңиз 🥱','Эгер наристеңиз боштукту тиктеп калса, баарын таштай салыңыз. Уйку убактысын өткөрүп жибербей, дароо төшөгүнө жаткырыңыз.','Ära maga maha beebi unevajaduse märke 🥱','Kui sinu beebi vaatab tühja pilguga kaugusesse, jäta kohe kõik pooleli. Vii ta voodisse, et mitte maha magada tema uneakent.'),
('0ecae509-0e89-4406-80e4-d01161b92754'::uuid,'Тиш чыккандагы куткаруучуңуз 🦷','Наристеңиз баарын тиштей баштадыбы? Муздатылган силикон тиш салгычтар анын ооруган тиштерин дароо басат.','Sinu päästja hammaste tulekul 🦷','Kas sinu pisike püüab kõike närida? Jahutatud silikoonist närimisrõngad rahustavad neid õrnu igemeid koheselt.'),
('60bbb8df-cb46-4930-8422-5f0c6fa7daad'::uuid,'Мен Сизди тааныйм! 🥰','Бөлмөгө киргениңизде наристеңиз сизди өзгөчө кубанычтуу жылмаюу менен тосуп алабы? Ооба, ал сизди баарынан жакшы тааныйт жана сиздин жытыңызды абдан жакшы көрөт!','Ma tunnen sind! 🥰','Kui sa tuppa astud, kas sinu beebi tervitab sind erilise ja elevil naeratusega? Jah, ta tunneb su kindlasti kõigi teiste seast ära ja on sügavalt armunud sinu ainulaadsesse lõhna!'),
('adbfecc6-7186-41fe-a870-83cf6809ec00'::uuid,'Өзүңүзгө убакыт бөлүңүз 🛋️','Наристеңиз уктап жатканда үй жумуштарын эмес, өзүңүзгө убакыт бөлүңүз. Үй бир аз иретсиз болушу мүмкүн, бирок күч-кубатыңызды калыбына келтирүү өтө маанилүү.','Leia aega iseendale 🛋️','Kui sinu beebi magab, pühenda aega endale, mitte majapidamistöödele. Tuba võib olla veidi sassis, kuid oma energia taastamine on absoluutselt hädavajalik.'),
('403b119e-e637-45fc-b072-cf84725abb35'::uuid,'Бул өсүү секириги болушу мүмкүн! 📈','Наристеңиз эч себепсиз эле токтобой ыйлап жатабы? 3 жумалык курак көбүнчө ич оорунун (колик) күчөгөн учуруна туш келет. Дүрбөлөңгө түшпөңүз.','See võib olla kasvuspurt! 📈','Kas sinu beebi nutab lohutamatult ilma nähtava põhjuseta? 3. nädala täitumine langeb sageli kokku koolikute haripunktiga. Ära satu paanikasse.'),
('ba61a641-e703-4b01-b161-601cf36add7a'::uuid,'Табияттын сыйкыры ⛅','Бөбөгүңүз өтө эле маанайсыз болуп, эч бир оюнчук жардам бербей жатабы? Аба ырайын жана кийимин текшерип, дароо таза абага алып чыгыңыз. Жаратылыш – эң мыкты тынчтандыруучу каражат!','Looduse võlu ⛅','Kas su beebi on eriti viril ja ükski mänguasi ei aita? Kontrolli ilma ja riietust ning vii ta kohe õue. Loodus on parim rahustaja!'),
('e97550d4-794b-4a9e-94da-881338077d81'::uuid,'Эмнеге дагы эле ыйлап жатат? 😭','Себепсиз ыйлоо абдан чарчатышы мүмкүн. Божомолдоп убара болбоңуз – ыйдын сырын чечүү үчүн ''Ыйды талдоо'' функциясын колдонуңуз.','Miks nad jälle nutavad? 😭','Seletamatud nutuhood võivad olla äärmiselt kurnavad. Ära väsita end arvamisega – kasuta nutuanalüüsi funktsiooni (''Crying Analysis''), et avastada nutu varjatud sõnum.'),
('1b92930f-874b-4bdc-b9d4-44b2ec744469'::uuid,'Токтоп калган ирмем 📸','Бөбөгүңүз бөлмөдө таттуу ойноп жатканда, ''Бөбөк сүрөттөрү'' функциясын тез ачыңыз. Анын өсүп келе жаткан өзгөчө жүзүн жана жаркыраган көздөрүн эч кандай фильтрсиз, келечек үчүн эстеликке тартып алыңыз.','Hetk, mis on ajas peatunud 📸','Kuni su pisike toas armsalt mängib, ava kiirelt beebifotode funktsioon. Jäädvusta see muutuv nägu ja säravad silmad ilma filtriteta, et neid tuleviku tarbeks hoida.'),
('17096c26-bde5-4bba-9013-08a06133ab4f'::uuid,'Рефлекстер өнүгүүдө!','Бөбөгүңүз манжаңызды канчалык бекем кысат? Бул рефлекс тууралуу көбүрөөк билүү үчүн биздин блог макалаларыбызды окуңуз.','Refleksid arenevad!','Kui tugevalt su beebi su sõrmest kinni haarab? Loe meie blogiartikleid, et selle refleksi kohta rohkem teada saada.'),
('5e32b8c3-c1c2-4dbd-a394-96bbfe39e0ed'::uuid,'Энелик күч 🤖','Айланаңызды карап, 5 айлык чекке жеткениңиз үчүн сыймыктаныңыз. Эгерде кандайдыр бир суроолоруңуз болсо, колдоо алуу үчүн Anacan AI менен байланышыңыз.','Emme vägi 🤖','Vaata ringi ja tunne suurt uhkust, et olete jõudnud 5. kuu tähiseni. Kui sul on muresid, pöördu toe saamiseks Anacan AI poole.'),
('1beec453-866b-4504-9a19-59d21f2305e4'::uuid,'Дагы эле бөлүнүү коркунучубу? 🥺','Жөн гана дааратканага кирсеңиз да, ал эшиктин артында ыйлап күтүп калышы мүмкүн. Бул бөлүнүү коркунучунун кайра пайда болушунун белгиси. Башка бөлмөдөн үн катып, жанында экениңизди жана жакында кайтып келериңизди айтып, аны тынчтандырыңыз.','Jälle lahusolekuärevus? 🥺','Isegi kui astud vaid korraks tualetti, võib ta ukse taga nuttes oodata. See on märk, et eraldumisärevus võib mõnikord tagasi tulla. Rahusta teda teisest toast huigates, andes teada, et oled seal ja tuled varsti tagasi.'),
('af763c83-7a14-4218-b3c2-49cdc7255b18'::uuid,'Түгөйүңүз менен убакыт өткөрүңүз 🥂','Бүгүн кечинде өнөктөшүңүз менен алгачкы күндөрүңүздү эскерип, бирге күлүп алыңыз. Экөөңүздөр тең чоң жолду басып өттүңүздөр!','Ole partneriga lähedane 🥂','Täna õhtul meenutage ja naerge koos partneriga oma esimeste päevade üle. Olete mõlemad läbinud pika teekonna!'),
('01e5d997-771c-4149-81ec-cf5e1b89ede9'::uuid,'Энергияны сарптай турган убакыт! 🌳','Төрт дубал балаңызды тажатып жатабы? Аны коляскага салып же колунан жетелеп, таза абага чыгыңыз. Жаратылыштын тынчтыгы балаңыздын да, өзүңүздүн да маанайыңызга жакшы таасир этет.','Aeg energiat kulutada! 🌳','Kas neli seina teevad su lapse rahutuks või ärritunuks? Pane ta vankrisse või võta käest kinni ja minge õue värske õhu kätte. Looduse rahu mõjub imeliselt nii lapse tujule kui ka sinu enda heaolule.'),
('8b9fb477-8954-40e0-aa32-b586b125f806'::uuid,'Өзүңүзгө кол чабыңыз! 👏','Бардык жазууларыңызды жана өсүү графиктериңизди карап чыгууга убакыт бөлүңүз. Бөбөгүңүз канчалык чоңойгонун жана сиздин кандай мыкты эне болгонуңузду көрүңүз!','Kiida ennast! 👏','Võta hetk, et vaadata tagasi kõigile oma sissekannetele ja kasvukõveratele. Vaata, kui palju su pisike on kasvanud ja kuidas sinust on saanud tõeline proff!'),
('bd07ae62-d716-4470-a226-d2dc1c918f7c'::uuid,'Жеңиштүү кеч 🪄','Бүгүн кечинде ''Акылдуу жомоктор'' бөлүмүнөн сүйүүгө толгон жомокту коюп, өнөктөшүңүз менен биргеликте жетишкендиктериңизди белгилеңиз!','Võidukas õhtupoolik 🪄','Täna õhtul pane nutijuttudes (''Smart Stories'') lihtsalt mängima üks armastust täis lugu ja tähistage koos partneriga oma meeskondlikke võite!'),
('2668e59c-6b79-42c7-903c-24806c9559de'::uuid,'Эне үчүн 10 мүнөттүк тыныгуу ☕','Үй жумуштары качып кетпейт. Бөбөгүңүз уктаары менен эле үй иштерине киришүүгө шашпаңыз. Тескерисинче, өзүңүзгө жылуу кофе куюп, 10 мүнөт эч нерсе кылбай эс алыңыз. Сиз буга татыктуусуз.','10-minutiline paus emmele ☕','Majapidamistööd ei kao kuhugi. Ära tunne survet hakata koristama kohe, kui su pisike magama jääb. Vala endale hoopis soe kohv ja luba endale 10 minutit, et lihtsalt seina vaadata. Oled selle ära teeninud.'),
('99274040-6797-4a0d-b6f8-4369e3e3436d'::uuid,'Кол менен таанып-билүү 🧸','Бөбөгүңүз оюнчукту бир колунан экинчи колуна өткөрө алабы? Бул мээнин эки жарым шарынын эң сонун иштеп жатканынын далили! Бул маанилүү жөндөмдү өнүгүү трекерине жазып коюңуз.','Käest kätte uurimine 🧸','Kas su beebi oskab mänguasja ühest käest teise tõsta? See on suurepärane tõestus, et tema ajupoolkerad teevad ilusasti koostööd! Märgi see oluline oskus kindlasti arengujälgijasse.'),
('cbbe11e5-f7e4-422b-8d0e-cf2a181684c8'::uuid,'Сезимдериңиз менен бөлүшүңүз 📝','Бүгүн өзүңүздү абдан чарчаган же тескерисинче, энергияга толгон сезип жатасызбы? Сезимдериңизди ''Маанай күндөлүгүнө'' чынчылдык менен жазыңыз. Ичиңиздегини чыгаруу сизге сөзсүз жеңилдик берет.','Jaga oma tundeid 📝','Kas tunned end täna täiesti kurnatuna või üllatavalt energilisena? Pane oma emotsioonid ausalt tujupäevikusse kirja. Enese väljendamine teeb sulle kindlasti head.'),
('503f1c6e-f32e-42d4-96c5-cf663fbb57cd'::uuid,'Сыйкырдуу аудио жомоктор 🪄','Бүгүн кечинде бөлмөгө сыйкыр кошолу. ''Акылдуу жомоктор'' бөлүмүндө айга учкан эр жүрөк мышык жөнүндө жомок түзүп, уктоо тартибин кызыктуу кылыңыз.','Maagilised audiolood 🪄','Toome täna õhtul tuppa teistsugust maagiat. Muuda une-eelne rutiin lõbusaks, luues nutijuttudes (''Smart Tales'') loo vaprast kassist, kes lendab kuule.'),
('b7efef49-9c1d-49fe-9e2d-4889969cd685'::uuid,'Табигый тынчтык ⛅','Бөбөгүңүз маанайсыз болуп, үйдө отургусу келбей жатабы? Аба ырайын жана кийимин текшерип, түз эле сейил бакка жөнөңүз. Таза аба – экөөңүздөр үчүн тең эң мыкты даба.','Loomulik rahu ⛅','Kas su pisike on eriti viril ja ei taha toas olla? Kontrolli ilma ja tema riietust ning suunduge otse parki. Sõõm värsket õhku on parim ravim teile mõlemale.'),
('fa1bb3e3-66d0-4cc7-8d63-61478e045e39'::uuid,'Баарын эле оозуна сала береби? 🤤','Бул анын айлана-чөйрөнү таанып-билүү жолу. Болгону, ал кармаган буюмдардын таза жана коопсуз экенине көз салыңыз.','Kõik läheb suhu? 🤤','See on tema viis ümbritsevat maailma avastada ja mõista. Veendu lihtsalt, et asjad, millega ta mängib, on puhtad ja ohutud.'),
('e3aafd70-c5f0-4254-ba79-e24f4dca3567'::uuid,'Шилекей агып жатабы? 🤤','Анын көйнөгүнүн жакасы көп суу болуп жатабы? Силикон тиш чыгаргычтарды даярдап коюңуз!','Süljevoolus missugune! 🤤','Kas tema särgikrae on nüüd tihti märg? Pane silikoonist närimisrõngad valmis!'),
('dcb350dc-49ff-4c0f-b6e7-e4777138873a'::uuid,'Ыйдын маанисин түшүнүү 😭','Эртең мененки ый ачкалыктанбы же тиш жарууданбы? Божомолдоп убара болбоңуз – ''Ыйды талдоо'' функциясын колдонуп, үнүн угуп, эмнеге муктаж экенин тез аныктаңыз.','Nutukoodi lahtimuukimine 😭','Kas need hommikused viginad on tingitud näljast või hammaste tulekust? Ära mängi äraarvamismängu – kasuta nutuanalüüsi funktsiooni, et kuulata tema hääli ja tuvastada kiirelt tema vajadused.'),
('e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4'::uuid,'Чыдамыңыз түгөнүп жатабы? 👨‍👧','Бүгүн кечинде бөбөккө кам көрүүнү атасына толук тапшырыңыз. Кулакчыныңызды тагып, эс алууга убакыт бөлүңүз.','Kannatus katkeb? 👨‍👧','Las issi vastutab täna õhtul pisikese eest täielikult. Pane kõrvaklapid pähe ja võta aega lõõgastumiseks.'),
('eb92cfef-308b-40f6-9214-f36986bb10ba'::uuid,'Биз бир командабыз! 🌟','Өзүңүздү жалгыз жана түшүнүксүз сезип жатасызбы? Терең дем алыңыз. Сиз бул оор күндөрдү басып өтүп жаткан эң күчтүү баатырсыз жана сиз баарын эң сонун аткарып жатасыз.','Oleme meeskond! 🌟','Tunned end üksi ja valesti mõistetuna? Hinga sügavalt sisse. Oled tugevaim kangelane, kes nende raskete päevadega toime tuleb, ja sa saad suurepäraselt hakkama.'),
('20b556a3-1b9a-4c51-bc18-a68bea6af134'::uuid,'Абсолюттук тынчтык 🤫','Уктай албай жатасызбы? Үн өлчөгүч менен бөлмөнүн ызы-чуу деңгээлин текшериңиз. Телевизорду өчүрүп, бөлмөнү толук караңгылатыңыз.','Absoluutne vaikus 🤫','Raskusi uinumisega? Kontrolli toa detsibellide taset helimõõtjaga. Lülita teler välja ja tee tuba täiesti pimedaks.'),
('5cbbbe44-8dae-45f7-8369-18aae825551b'::uuid,'Бүйлөсү кычышып жатабы? 🦷','Манжалары дайыма оозундабы жана шилекейи көп агып жатабы? Муздатылган тиш чыгаргычтарды берүүчү убакыт келди.','Sügelevad igemed? 🦷','Kas tema sõrmed on pidevalt suus ja ta ilastab palju? On aeg pakkuda jahutatud närimislelusid.'),
('f00bd5bd-287a-46fb-8532-9655a797aab3'::uuid,'Өзүңүздү унутпаңыз, апа! 🥑','Бөбөгүңүздү багууга берилип кетип, өзүңүз тамактанууну унутуп калдыңызбы? Биздин рецепттерден 10 мүнөттө даярдала турган, энергия берүүчү пайдалуу тамакты тандаңыз.','Ära unusta iseennast, emme! 🥑','Oled olnud nii keskendunud beebi toitmisele, et unustasid ise süüa? Vali meie retseptide seast energiat andev ja tervislik eine, mille saab valmistada vaid 10 minutiga.'),
('4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c'::uuid,'Түнкү бешик ырлары 🎶','Эненин үнүндөй тынчтандыруучу эч нерсе жок. Бүгүн кечинде бөбөгүңүздү кучагыңызга кысып, анын сүйүктүү бешик ырын акырын ырдап бериңиз.','Õhtused hällilaulud 🎶','Ükski heli pole nii rahustav kui ema hääl. Täna õhtul hoia oma pisikest lihtsalt rinna vastas ja laula talle vaikselt tema lemmik unelaulu.'),
('baf623af-022a-4483-b233-e77e915f194b'::uuid,'Биздин кичинекей тамакты жакшы көргөнүбүз 🥣','Ал пюрелерди сүйүнүп жеп жатабы? Ал чоңоюп калды!','Meie väike suur sööja 🥣','Kas ta sööb nüüd isuga oma püreesid? Ta kasvab suureks!'),
('d935b5ec-1166-4c5b-a013-19977086a00b'::uuid,'Күнүмдүк отчетуңуз даяр! 📊','Бүгүнкү уйку, тамактануу жана жалаяк графиктеринин анализин көрүү үчүн Anacan тиркемесине кириңиз.','Sinu päevakokkuvõte on valmis! 📊','Ava Anacan äpp, et vaadata tänase une, toitmise ja mähkmevahetuste graafikute analüüsi.'),
('57873aa1-acb0-439b-98e9-70fd8b575b47'::uuid,'Бөлмө оюнчуктардын торнадосуна айландыбы? 🌪️','Оюнчуктар чачылып жатабы? Үйдүн башаламандыгы үчүн кабатыр болбоңуз. Сиз кереметтүү энесиз; сиз үчүн биринчи орунда үй эмес, бөбөгүңүз турат.','Kas tuba on nagu mänguasjade tornaado? 🌪️','Mänguasjad on igal pool? Ära muretse sassis kodu pärast. Oled suurepärane ema; sinu prioriteet on beebi, mitte ideaalselt korras kodu.'),
('bb854fb5-befa-49e1-bf95-4f811865fe4f'::uuid,'Башка апалар эмне кылып жатышат? 💬','Тынчсызданып жатасызбы? Anacan коомчулугу менен байланышыңыз. Башка энелердин да ушундай уйкусуз түндөрдү жана кыйынчылыктарды башынан өткөрүп жатканын көрүү сизге чоң сооронуч берет.','Mida teised emmed teevad? 💬','Tunned muret? Liitu Anacan kogukonnaga. Teiste emade nägemine, kes elavad üle samu magamata öid ja katsumusi, pakub suurt lohutust.'),
('149c401f-2cba-4bc8-b3fb-54e3507ca6f5'::uuid,'Караңгылыкка көнүү 🌙','Бөбөгүңүздүн тез уктап кетиши үчүн бөлмөдөгү жарыкты азайтып, планшеттерди өчүрүңүз. Уйку гормону болгон мелатонин тынч жана караңгы чөйрөдө жакшыраак иштелип чыгат.','Pimedusega kohanemine 🌙','Et aidata pisikesel kiiremini uinuda, hämarda toas kõik tuled ja lülita tahvelarvutite ekraanid välja. Unehormoon melatoniin vabaneb rahulikus ja pimedas keskkonnas tõhusamalt.'),
('23720343-b8a6-4414-a95b-f2b2afa5cab1'::uuid,'Керектүү нерселер түгөнүп жатабы? 🛒','Жалаяк же май түгөнүп калдыбы? Бул майда-чүйдө нерселер үчүн башыңызды оорутпаңыз. Жөн гана соода тизмесине кошуп коюңуз, өнөктөшүңүз сыртка чыкканда алып келет.','Varud hakkavad otsa saama? 🛒','Mähkmed või beebiõli hakkavad otsa saama? Ära koorma oma pead nende pisiasjadega. Lisa need lihtsalt ostunimekirja ja su partner saab need väljas käies kaasa haarata.'),
('77df7526-5d53-4e7e-8d03-ef3224240fd5'::uuid,'Сурооңуз барбы? 🤖','Өнүгүү боюнча миңдеген суроолор башыңызды айлантып жатабы? Форумдарды окууга сааттарды кетирбей, Anacan AI''дан кыска жана илимий негизделген жооп сураңыз.','Kas sul on küsimus? 🤖','Kas su peas tiirleb tuhandeid küsimusi lapse arengu kohta? Foorumite lugemisele tundide kulutamise asemel küsi Anacan AI-lt lühikest ja teaduspõhist vastust.'),
('ffb2dcc3-196c-4439-b233-ee14c9337ae5'::uuid,'Күнүмдүк жалаяктарды көзөмөлдөө. 🧷','Бөбөгүңүздүн жетиштүү тамактанып жатканын жана сиңирүү системасын көзөмөлдөө үчүн ар бир жалаяк алмаштырууну Anacan''га жазып туруңуз.','Mähkmete vahetamise jälgimine. 🧷','Et veenduda beebi piisavas toitumises ja jälgida tema seedesüsteemi, märgi iga mähkmevahetus Anacan äppi.'),
('297cb03f-f4bc-4fe0-aba8-dc539d62bcce'::uuid,'Биримдикте күч бар 🛋️','Оор күндөн кийин өнөктөшүңүз менен бетме-бет отуруп сүйлөшүңүз. Бири-бириңизди колдоо жана командалык сезим оорчулукту жеңилдетет.','Ühtsus annab jõudu 🛋️','Pärast rasket päeva istu partneriga näost näkku ja rääkige asjad selgeks. Teineteise toetamine ja meeskonnavaimu tundmine võib koormat tõeliselt kergendada.'),
('74dae015-c762-4d96-ad34-7d706065ef5f'::uuid,'Куттуктайбыз, сиздин эне болгонуңузга 1 жума болду! 🥳','Куттуктайбыз, сиз эне болгонуңузга 1 жума болду! 🥳 ''Бөбөк сүрөттөрү'' бөлүмүн колдонуп, бул өзгөчө күндүн эстелик сүрөтүн тартыңыз.','Palju õnne, oled olnud emme juba 1 nädala! 🥳','Palju õnne, oled nüüdseks olnud ema 1 nädal! 🥳 Tee sellest erilisest päevast meeldejääv pilt, kasutades beebifotode sektsiooni.'),
('3f28d490-5c17-44cf-b02a-a0a5ea44e564'::uuid,'Өзүңүз менен сыймыктаныңыз! 👏','Алгачкы жумалар канчалык оор сезилгенин эстеңиз. Эми болсо баарын кандай кесипкөйлүк менен аткарып жатканыңызды караңыз! Сиз чындап эле укмуштуусуз!','Ole enda üle uhke! 👏','Vaata tagasi ja meenuta, kui hirmutavad need esimesed nädalad tundusid. Nüüd vaata, kui professionaalselt sa kõigega toime tuled! Sa oled tõeliselt hämmastav!'),
('bdd2cc62-7f55-4558-bc57-531c376128b9'::uuid,'Даамдуу ачылыштар күтөт! 🥦','Кошумча тамакка өтө турган бөбөктөр үчүн ''Рецепттер'' бөлүмүнөн алгачкы пюре идеяларын изилдеп, келе жаткан айга даярданыңыз.','Maitsvad avastused ootavad! 🥦','Valmistu tulevaseks kuuks, uurides retseptide sektsioonist esimesi püreeideid lisatoiduga alustavatele beebidele.'),
('1d84618d-c436-422f-bb3e-95d3ae0487d6'::uuid,'Бул эмне болгон шилекей? ☝️','Ал кичинекей манжасы менен баарын көрсөтүп, ''Бул эмне?'' деп сурап жатабы? Ал дүйнөнү сизден таанып-билүүгө ынтызар! Бул анын баарлашуу жөндөмүндөгү чоң кадам. Ал кызыккан ар бир буюмдун атын сабырдуулук менен кайталап бериңиз.','Mis süljeeritus see on? ☝️','Kas ta näitab oma väikese sõrmega kõigele ja küsib ''Mis see on?'' Ta ootab õhinal, et sa talle maailma tutvustaksid! See on tohutu hüpe tema suhtlemisoskuses. Korda kannatlikult iga eseme nime, mille vastu ta huvi tunneb.'),
('6692c328-0a11-48ba-9a13-0443aeead27c'::uuid,'Өз алдынча оодарылуу 🤸‍♂️','Ал чалкасынан ичине оодарылып жатабы? Булчуңдарын эркин кыймылдатып, дүйнөнү изилдеши үчүн аны чоң төшөккө жаткырыңыз.','Iseseisev pööramine 🤸‍♂️','Kas ta keerab end nüüd kergelt seljalt kõhule? Pane ta suurele matile, et ta saaks vabalt oma lihaseid liigutada ja avastada.'),
('e22900db-05e9-4ef6-8e2b-3f0d3690dce5'::uuid,'Ирмемди кармап калыңыз 📸','Ал абдан тез чоңоюп жатат... Ал уктап жатканда, эстелик катары ''Бөбөк сүрөттөрү'' менен анын таттуу, тынч жүзүн тартып алыңыз.','Jäädvusta hetk 📸','Ta kasvab nii kiiresti... Kuni ta magab, jäädvusta need armsad ja rahulikud näojooned beebifotode funktsiooniga, et mälestusi hoida.'),
('42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb'::uuid,'Түнү ойгонуу тартиби 😴','Ар бир ойгонгон сайын жарыкты күйгүзбөңүз. Тамактандыруу үчүн Anacan таймерин колдонуңуз, андан кийин ''Ак ызы-чуу'' (White Noise) менен аны кайра уктатыңыз.','Öised ärkamised 😴','Ära pane tuld põlema iga kord, kui ta ärkab. Kasuta tema toitmiseks Anacan taimerit ja rahusta ta seejärel valge müra abil uuesti magama.'),
('b460ef96-b60f-4ef0-893f-50bb64397d11'::uuid,'Бүгүн үй жыйноо жок! 🛑','Чарчадыңызбы? Өнөктөшүңүзгө айтыңыз. Бүгүн тамак жасоо да, тазалоо да жок. Бүгүн – эненин эс алуу жана кофе ичүү күнү!','Täna koristamist ei toimu! 🛑','Tunned end kurnatuna? Anna sellest oma partnerile teada. Täna ei tehta kodus süüa ega koristata. Täna on ema puhkamise ja kohvi päev!'),
('f10c4519-156b-4eca-8117-28c233b11129'::uuid,'Мени менен сүйлөшүңүз! 🗣️','Ал кунт коюп угуп, ар кандай үндөрдү чыгарып жатабы? Ал сиз менен чыныгы маек куруп жатат! Анын үндөрүнө жооп берип, бул баарлашууну колдоңуз.','Räägi minuga! 🗣️','Kas ta kuulab tähelepanelikult ja teeb erinevaid hääli? Ta peab sinuga päriselt vestlust! Vasta tema häälitsustele ja julgusta seda suhtlust.'),
('01ae2fd5-6c02-4d2d-8691-089f2f85a502'::uuid,'Алгачкы отуруу аракеттери 🪑','Ал отургузулганда башын жана белин түз кармап жатабы? Бул анын булчуңдары чыңдалып жатканын билдирет! Кыска убакыттан отуруу көнүгүүлөрүн баштаңыз.','Esimesed istumiskatsed 🪑','Kas ta hoiab toetatult istudes oma pead ja selga sirgemalt? See näitab, et tema lihased tugevnevad! Alusta lühikeste toetatud istumise harjutustega.'),
('3ae0359c-235f-4ea4-9a97-929da4740dc7'::uuid,'Төрт дубалдан сыртка чыгыңыз ☕','Үйдө отуруу тажаттыбы? Коляска менен кирүүгө ыңгайлуу жакын жердеги кафени таап, жаңы чөйрөдө кофеден ырахат алыңыз.','Põgene nelja seina vahelt ☕','Kas kodus olemine tundub lämmatav? Leia lähim vankrisõbralik kohvik ja naudi kohvi värskendavas keskkonnas.'),
('a66c05d0-980d-472a-8187-902f12cc0e87'::uuid,'Уйкунун белгилери 🥱','Эгер ал көзүн ушалап, боштукту карап жатса, ыйлагыча күтпөңүз. Дароо бөлмөнү караңгылатып, уктоо тартибин баштаңыз.','Unemärgid 🥱','Kui ta hõõrub silmi ja vaatab tühjusesse, ära oota jonnihoogu. Tee tuba kohe pimedaks ja alusta unerutiiniga.'),
('5cacab5c-c142-4162-9118-942fa6678db3'::uuid,'Ачкабы же чарчадыбы? 🧩','Эмне кылсаңыз да ыйлаганы токтобой жатабы? Балким, ал өтө чарчагандыр. Ишенүү үчүн, ыйдын себебин билүү үчүн ''Ыйды талдоо'' функциясын колдонуңуз.','Näljane või väsinud? 🧩','Ükskõik, mida sa ka ei teeks, ta ei lõpeta nutmist? Võib-olla on ta lihtsalt üleväsinud. Et kindel olla, kasuta nutuanalüüsi funktsiooni, et avastada tema nutu põhjus.'),
('92894378-2736-426b-99c1-d408f0e76945'::uuid,'Үндү көзөмөлдөө 🤫','Ымыркайыңыз уктап баратканда күтүүсүз чыккан үндөр аны ойготуп жатабы? Үн өлчөгүчтүн жардамы менен бөлмөдөгү ызы-чуунун деңгээлин көзөмөлдөп туруңуз.','Helikontroll 🤫','Kas äkilised helid äratavad beebi just siis, kui ta on uinumas? Hoia toa mürataset kontrolli all helitaseme mõõtjaga.'),
('aab86ddb-de4e-46b1-a168-2145a68d243b'::uuid,'Апанын энергиясын арттыруу 🔋','Күндүн ортосунда чарчап жатасызбы? Энергияңызды калыбына келтирип, сүтүңүздүн көбөйүшүнө жардам бере турган пайдалуу смузи рецепттерибизди карап көрүңүз.','Emme energialaeng 🔋','Tunned end keset päeva kurnatuna? Vaata meie tervislikke smuutiretsepte, mis annavad sulle energiat ja toetavad piimatootmist.'),
('2f79ccaf-9886-4cc5-8de6-c8151fcbc753'::uuid,'Музыканын күчү 🎶','Эгерде ал күн баткандан кийин себепсиз ыйлай баштаса, аны жай классикалык музыка же ак ызы-чуу (white noise) менен тынчтандырууга аракет кылыңыз.','Muusika vägi 🎶','Kui beebi hakkab hilisel pärastlõunal või õhtul seletamatult nutma, proovi teda rahustada aeglase klassikalise muusika või valge müra abil.'),
('6ac04f2a-cb0e-47b2-91d7-757e201eec80'::uuid,'Аба ырайынын сюрприздери ⛅','Сейилдөөгө чыгарда аба ырайына алданып калбаңыз, ымыркайыңыз үшүп калышы мүмкүн. Сырткы шартка жараша баланы туура кийиндирүү үчүн биздин аба ырайы жана кийим тандоо жардамчыбызды колдонуңуз.','Ilmaüllatused ⛅','Jalutama minnes ära lase end petlikul ilmal eksitada – beebil võib kergesti külm hakata. Kasuta meie ilma- ja riietumisabilist, et riietada oma pisike õues valitsevate olude järgi sobivalt.'),
('e458b23e-9cff-4743-b31b-4ce87556944c'::uuid,'Жаңы даамдарга кызыгасызбы? 🍽️','Тамактанып жатканыңызда тарелкаңызды кунт коюп карап жатабы? Кошумча тамакка даярдык белгилери байкала баштады! Бирок шашпаңыз, 6 ай болгонго чейин күтө туруңуз.','Kas uued maitsed huvitavad? 🍽️','Kas ta jälgib söömise ajal huviga sinu taldrikut? Tahkega toiduga alustamise märgid on ilmnemas! Kuid ära kiirusta, oota, kuni ta on 6-kuune.'),
('25b7edd7-55ed-4b9f-b931-91fdbbe75fb4'::uuid,'Тажрыйба бөлүшүү 💬','Ымыркайыңыздын жаңы жетишкендиги сизди таң калтырдыбы? Anacan коомчулугуна кошулуп, бул кубанычтуу жаңылыкты башка энелер менен бөлүшүңүз.','Kogemuste jagamine 💬','Kas beebi uus arenguetapp üllatas sind? Liitu Anacani kogukonnaga ja jaga seda põnevat avastust teiste emadega.'),
('6e3db4e0-169c-4b26-92b7-3281435ce439'::uuid,'Чексиз жомоктор 📖','Бүгүн кечинде ''Акылдуу жомокторго'' сонун тапшырма бериңиз: асан-үсөндүн үстүндө уктап жаткан периште жөнүндө жомок.','Lõputud lood 📖','Anna täna õhtul „Nutikatele juttudele“ üks kaunis uus ülesanne: lugu vikerkaarel magavast haldjast.'),
('91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8'::uuid,'Сиздин бар болушуңуз жетиштүү! 💖','Бүгүн баары тескери болуп жатабы? Өзүңүздү күнөөлөбөңүз. Сиз робот эмессиз да? Сезимдериңизди кабыл алыңыз, өзүңүздү кечириңиз жана жылмайыңыз.','Sa oled piisav! 💖','Kas täna läks kõik viltu? Ära ennast süüdista. Kas oled robot? Ei ole. Aktsepteeri oma tundeid, anna endale andeks ja naerata.'),
('f295eaa8-f2fa-42e3-9941-4e98a42703f5'::uuid,'Жүктү бөлүшүңүз 🛋️','Эгерде ымыркай уктаганда сиз да кошо уктагыңыз келсе, үй жумуштарын жолдошуңузга тапшырыңыз.','Jaga koormust 🛋️','Kui soovid koos beebiga magama heita, delegeeri muud majapidamistööd oma partnerile.'),
('ff9ff3bc-de2b-4add-9a4b-7f31e78329bd'::uuid,'Энелик унутчаактык менен күрөшүү 📝','Унутчаактык – төрөттөн кийинки мезгилдин кадимки көрүнүшү. Маанилүү нерселер эсиңизден чыгып кетпеши үчүн соода тизмеңизди активдүү колдонуңуз.','Kuidas toime tulla emme-ajuga 📝','Unustamine on sünnitusjärgsel perioodil tavaline ja normaalne. Kasuta aktiivselt ostunimekirja, et miski oluline meelest ei läheks.'),
('05c1eaa2-4a23-478a-a816-f6e336bf8650'::uuid,'Күзгүдөгү дос 👀','Аны күзгү алдына алып барыңыз. Өзүнүн чагылышын карап, былдырлап сүйлөшүү – анын таанып-билүү жөндөмүн өнүктүрүү үчүн эң сонун жана кызыктуу көнүгүү.','Sõber peeglis 👀','Võta beebi peegli ette. Oma peegelduse jälgimine ja sellele vastamine on suurepärane ja lõbus tegevus tema kognitiivseks arenguks.'),
('5e7b7a68-8be5-48ad-9672-e4c1e4de4125'::uuid,'Командалык маек 🥂','Маанай күндөлүгүңүздү ачыңыз, бүгүнкү терс сезимдерди артта калтырып, жолдошуңуз менен бир команда болуп жашоодон ырахат алыңыз.','Meeskonnatöö 🥂','Ava oma meeleolupäevik, jäta tänane negatiivsus seljataha ja naudi partneriga meeskonnana tegutsemist.'),
('d8a2fadb-f854-4f00-9556-bd2eb305be92'::uuid,'Тиш жаруудагы жеңилдик 🦷','Тиштери кычышып, шилекейи көп агып жатабы? Таза тиш чыгаргычтар сиздин жаңы эң жакын досуңузга айланат.','Kuidas leevendada hammaste tulekut 🦷','Kas ila voolab rohkem ja igemed on ärritunud? Puhtad närimisrõngad saavad peagi sinu parimateks sõpradeks.'),
('06a86ce4-2e7a-4f35-a865-7e585114d78f'::uuid,'Мени көрүп жатасызбы? 🧸','Оюнчукту жууркандын астына катып коюңуз. Ал аны издейби? Бул нерселердин туруктуулугун түшүнүү үчүн эң сонун өнүгүү этабы!','Kas sa näed mind? 🧸','Peida mänguasi teki alla. Kas ta otsib seda? See on imeline arenguetapp, mis näitab, et laps mõistab esemete püsivust!'),
('7c7a5fbe-09ea-4f4c-a054-883ad490f939'::uuid,'Биринчи аптанын маалыматтарын карап чыгалыбы? 📊','Anacan тиркемесинен жумалык уйку, жалаяк алмаштыруу жана тамактандыруу статистикаңызды көргүңүз келеби?','Vaatame esimese nädala andmed üle? 📊','Soovid kontrollida oma iganädalast une-, mähkmevahetus- ja toitmise statistikat Anacani äpis?'),
('478917cd-56f0-483c-b59c-a9eb5ad87e67'::uuid,'Ата: Түнкү баатыр 🦸‍♂️','Алтын эреже: бешик ырын ырдоо милдети тең бөлүшүлүшү керек! Бүгүн кечинде ымыркай атасынын кучагында, ал эми сиз эс алыңыз.','Issi: öine kangelane 🦸‍♂️','Esimeste kuude kuldreegel: hällilaulu laulmine peaks olema jagatud kohustus! Täna õhtul on beebi issi süles ja sina saad puhata.'),
('b31044ce-8042-4a44-af14-b71856994efe'::uuid,'Сыртка чыгууга убакыт келди! 🌳','Ымыркайыңызды коляскага салып, жок дегенде 15 мүнөт таза абага чыгыңыз. Таза аба экөөңүзгө тең пайдалуу!','Aeg õue minna! 🌳','Pane pisike vankrisse ja mine vähemalt 15 minutiks värske õhu kätte. Värske õhk tuleb teile mõlemale kasuks!'),
('1c8d40ed-ce45-4ab5-a646-af121febdc6b'::uuid,'Командалык сыймык 🥂','Дагы бир оор күндү артта калтырдыңыз. Ымыркай уктагандан кийин жолдошуңуз менен чай ичип, бири-бириңизди: ''Биз бул ишти абдан сонун аткарып жатабыз!'' деп дем бериңиз.','Meeskonna uhkus 🥂','Oled taas ühe keerulise päeva seljataha jätnud. Kui pisike magab, valage partneriga teed ja motiveerige üksteist öeldes: „Me saame sellega suurepäraselt hakkama!“'),
('d06a4b75-fad1-4ee5-9c5c-c70d98373c0c'::uuid,'Физикалык калыбына келүү 🩹','Денеңиз дагы деле калыбына келип жатат, тигиштериңиз оорушу мүмкүн. Эсиңизде болсун, өзүңүздөн кемчиликсиз болууну талап кылбаңыз.','Füüsiline taastumine 🩹','Sinu keha alles paraneb ja õmblused võivad veel hellad olla. Pea meeles, ära nõua endalt täiuslikkust.'),
('43a61a10-16d2-4518-b6bc-479ff5985526'::uuid,'Эртең мененки концерт 🎶','Ал сизге карап, кең жылмайып, жаңы үндөрдү чыгарып жатат. Ал азыр бөлмөдө эң сонун концерт коюп жатат – кунт коюп угуңуз!','Hommikune kontsert 🎶','Ta vaatab sulle otsa, naeratab laialt ja teeb uusi hääli. Ta annab praegu toas kõige ilusamat kontserti – kuula tähelepanelikult!'),
('d26efa64-1d4b-4147-ad2c-7a309dc2c5a4'::uuid,'Уйкунун негиздери ⏱️','Жылуу ванна, жеңил массаж жана караңгы бөлмө... Тынч түн өткөрүү үчүн уйку тартибин эч качан бузбаңыз.','Une vundament ⏱️','Soe vann, õrn massaaž ja hämar tuba... Ära kunagi riku unerutiini, et tagada rahulikud ööd.'),
('b19556d6-123c-4633-b806-8552c2789139'::uuid,'Аба ырайы өзгөрүлмөлүү ⛅','Аба ырайына алданып, сейилдөө учурунда ымыркайыңызды үшүтүп албаңыз. Терезеден карап эле койбостон, сырткы шартка ылайыктуу кийим тандоо үчүн Аба ырайы жана Кийим жардамчысын колдонуңуз.','Ilm on muutlik ⛅','Ära lase petlikul ilmal end eksitada ja beebil jalutuskäigul külmetada. Ära piilu vaid aknast välja, vaid kasuta ilma- ja riietumisabilist, et valida õueoludesse parim riietus.'),
('d83a6f20-2dc5-45c9-9550-38fedec5c042'::uuid,'Ичеги микрофлорасын чыңдоо!','Эгерде ымыркайыңыздын ичи желдеп ооруса, Anacan тиркемесинин ''Ак ызы-чуу'' бөлүмүндөгү тынчтандыруучу үндөр ага жардам берет.','Terve soolestiku mikrofloora arendamine!','Kui beebil tekivad gaasivalud, aitavad Anacani valge müra sektsiooni rahustavad rütmid tal maha rahuneda.'),
('ddef2887-0bec-40c8-91a4-05edb188b86b'::uuid,'Дарыгердей акылдуу 🤖','Интернеттеги коркунучтуу окуяларга кабатыр болбой, кошумча тамак киргизүү боюнча суроолоруңузду Anacan AI''дан сурап, тынчтаныңыз.','Tark nagu arst 🤖','Selle asemel, et lasta end interneti hirmulugudest heidutada, küsi Anacan AI-lt oma küsimused tahke toidu tutvustamise kohta ja rahusta oma meelt.'),
('6b3cb5c5-1970-4fdc-b099-5f91eda48758'::uuid,'Тынчтыктын кадыры 🤫','Ымыркайыңыз уктап баратканда күтүүсүз чыккан үндөр аны ойготуп жатабы? Үн өлчөгүч менен бөлмөдөгү децибелдин чегин көзөмөлдөңүз.','Teadlik vaikus 🤫','Kas äkilised helid äratavad lapse just siis, kui ta on uinumas? Jälgi toa detsibellide taset helimõõturiga.'),
('d7f16071-fb32-41c6-bf73-3b61867ff844'::uuid,'Баатырдык секириктер 🧗‍♂️','Ымыркайыңыз дивандан жаздыктардын үстүнө секирип жатабы? Ал тартылуу күчүн изилдеп, кайраттуулугун сынап жатат. Ага ''болбойт'' дебей, бөлмөдө коопсуз секирүү аянтын түзүп бериңиз.','Julged hüpped 🧗‍♂️','Sinu väike põngerjas hüppab nüüd diivanilt patjade hunnikusse! Ta avastab gravitatsiooni ja paneb oma julgust proovile. Selle asemel, et öelda „ei“, loo talle toas turvaline hüppetsoon.'),
('092f30cd-002d-4c4e-a83e-0b13c38cc743'::uuid,'Наристеңиздин көз карашы тактала баштады! 👀','Ал эми азыр жүзүңүздү жакшыраак тааныйт! Бул баалуу көз ирмемдерде сезген сезимдериңизди Маанай күндөлүгүнө жазып коюңуз.','Sinu beebi pilk teravneb! 👀','Ta tunneb nüüd sinu nägu palju paremini! Pane kirja tunded, mida need väärtuslikud hetked sinus tekitavad, oma meeleolupäevikusse.'),
('7bed8f71-075d-414c-be3c-9bf2c4a82ea3'::uuid,'Логикага сыйбаган кийимдер 👗','Кээде өтө жука, кээде өтө калың кийинтип жатам деп ойлоносузбу? Тартынбаңыз. Аба ырайын жана кийимин текшерип, ишенимдүү кийиндириңиз.','Riietus, mis trotsib loogikat 👗','Riietad teda vahel liiga õhukeselt, vahel liiga soojalt? Ära kõhkle. Kontrolli ilma ja lapse riietust ning riieta teda enesekindlalt.'),
('8f5769c4-aeb4-4cd1-acf0-052c7e0df753'::uuid,'Сыйкырдуу жомок убактысы 🪄','Акылдуу жомокторду колдонуп, бүгүн кечинде өзгөчө жомок түзүңүз.','Lummav unejutu aeg 🪄','Loo täna õhtuks üks eriline lugu, kasutades nutikaid jutte (Smart Stories).'),
('3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37'::uuid,'Уйкусуз түндөрдү кабыл алуу 😭','Ымыркайыңыз түн ортосунда ойгонуп, кайра уктабай жатабы? Ачууланбоого аракет кылыңыз. Эмне тынчсыздандырып жатканын акырын аныктап, жанында болуп, сылап-сыйпап тынчтандырыңыз.','Magamata ööde aktsepteerimine 😭','Sinu väike laps ärkas keset ööd ega jää uuesti magama. Püüa mitte ärrituda. Selgita õrnalt välja, mis teda vaevata võib, ja paku talle lohutust oma kohaloleku ja õrna silitusega.'),
('8c6679da-fafd-4f32-9db9-54953d4a08fe'::uuid,'Күнүмдүк жалаяк санын көзөмөлдөп жатасызбы? 🧷','Ымыркайыңыздын жалаягы – ал жетиштүү тамактанып жатканынын эң жакшы көрсөткүчү! Ар бир алмаштырууну Anacan тиркемесине жазып коюуну унутпаңыз.','Kas jälgid igapäevast mähkmete arvu? 🧷','Beebi mähkmed on parim näitaja selle kohta, et ta saab piisavalt süüa! Ära unusta iga mähkmevahetust Anacanis kirja panna.'),
('58f18841-d6c8-49e1-84e7-3ca2b96787a6'::uuid,'Сиздер чогуу болгонуңузга 20 күн болду! 🥰','Сиз укмуштуудай энесиз! Бул күндү ''Ымыркай фотосессиясы'' куралы менен кооз түбөлүккө калтырыңыз.','Olete koos olnud 20 päeva! 🥰','Sa oled imeline ema! Jäädvusta see päev kaunilt beebi fotosessiooni tööriistaga.'),
('904ee771-1822-4dbc-a79d-be6697d8f129'::uuid,'Кыйын кырдаалда сабырдуулукту табуу 🛒','Балаңыз дүкөндөн каалаган оюнчугун алып бербегениңиз үчүн ыйлап жатабы? Айланадагы ''кемчиликсиз'' ата-энелердин карашына маани бербеңиз. Сабырдуулук менен көзүнө карап, түшүндүрүп, өз позицияңызда бекем туруңуз.','Kannatlikkuse leidmine kriisihetkel 🛒','Sinu laps karjub, sest sa ei ostnud talle poes soovitud mänguasja. Ära tee välja nende „täiuslike“ vanemate pilkudest enda ümber. Võta rahulikult silmside, selgita olukorda ja jää oma otsusele kindlaks.'),
('c5b71abf-d92a-46da-8996-4282a02052e4'::uuid,'31-айга кош келиңиз! 🎉','Балаңыз эрте балалыктын эң интеллектуалдык, бирок кээде татаал этаптарынын бирине кирип жатат. Ал айткан ар бир жаңы сүйлөм жана ар бир суроо – сиз үчүн баа жеткис ачылыш.','Tere tulemast 31. kuusse! 🎉','Sinu laps on jõudnud ühte kõige intellektuaalselt stimuleerivamasse, kuid sageli ka väljakutseid pakkuvasse varajase lapsepõlve etappi. Iga uus lause, mida ta ütleb, ja iga küsimus, mida ta esitab, on imeline avastus, mida nautida.'),
('c8038ed4-40d8-4c96-b84d-dd22d681496c'::uuid,'Апалар үчүн даамдуу жана пайдалуу варианттар! 🍲','Пайдалуу рецепттер бөлүмүбүз менен энергияңызды толуктаңыз жана өзүңүзгө кам көрүүнү унутпаңыз.','Maitsvad ja tervislikud valikud emmedele! 🍲','Turguta oma energiat meie tervislike retseptide jaotisega ja pea meeles enda eest hästi hoolitseda.'),
('2ef0546f-a471-4ef1-833d-3a8427b3c92c'::uuid,'Наристеңиз абдан тез чоңоюп жатат! ⚖','️ Ымыркайыңыздын жумалык салмагын Өсүү трекерине киргизип, тиркеме аркылуу анын дени сак өсүү графигин көзөмөлдөңүз.','Sinu beebi kasvab nii kiiresti! ⚖','️ Sisesta beebi iganädalane kaal kasvu jälgijasse ja jälgi tema tervisliku arengu kõverat rakenduses.'),
('0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2'::uuid,'Чапалак чабуунун кубанычы 👏','Балаңыз бир нерсени ийгиликтүү аткаргандан кийин өзүнө кол чаап, сыймыктанып жатабы? Ал колдоону күтүп жатат! Анын кубанычына кошулуп, кичинекей жеңиштерин кубаттап, шыктандырыңыз.','Plaksutamise rõõm 👏','Kas su laps plaksutab endale ja särab uhkusest, kui on millegagi hakkama saanud? Ta otsib tunnustust! Rõõmusta koos temaga, kiida tema väikeseid võite ja motiveeri teda oma entusiastliku toetusega.'),
('25c7776c-5416-4926-9ebf-f1fff97f3809'::uuid,'Суроолоруңуз барбы? 🤖','2,5 жаштан кийин балаңыздын бою жана салмагы боюнча кабатырланып жатасызбы? Интернеттеги коркунучтуу макалаларды окугандын ордуна, Anacan AI''дан так жана илимий негизделген маалымат алыңыз.','Kas sul on küsimusi? 🤖','Kas oled mures oma 2,5-aastase lapse pikkuse ja kaalu pärast? Selle asemel, et lugeda hirmutavaid artikleid internetist, saa täpset ja teaduslikult põhjendatud teavet Anacan AI-lt.'),
('84bd0c91-57d2-4afc-a090-33645f6c3336'::uuid,'Сизде суроолор барбы? 🤖','Түн ортосунда болсо да, Anacan AI сиз үчүн даяр! Сизди түйшөлткөн суроолорду берип, дароо колдоо алыңыз.','Kas sul on küsimusi? 🤖','Isegi keset ööd on Anacan AI sinu jaoks olemas! Küsi kõike, mis sind vaevab, ja saa kohest tuge.'),
('dcc95e44-9688-48db-a64f-a544e0720dec'::uuid,'Апа үчүн белек 🥑','Күнүмдүк түйшүктүн арасында тамакты шашып ичпеңиз. Рецепттерибизден жеңил, пайдалуу салат даярдап, отуруп, тамагыңыздан ырахат алыңыз.','Maiuspala emmele 🥑','Kiirel päeval väldi lõunasöögi söömist jooksu pealt. Valmista meie retseptide järgi lihtne ja tervislik salat ning võta hetk, et maha istuda ja oma toitu tõeliselt nautida.'),
('0b493cb3-45ff-4a4a-8782-40ce3d792d2c'::uuid,'Өзүңүзгө кам көрүңүз 🛋️','Ымыркай уктаганда үй жумуштарын эмес, өзүңүздү ойлоңуз. Үй иретсиз болушу мүмкүн, бирок сиздин энергияңыз калыбына келиши керек.','Sea ennast esikohale 🛋️','Kui beebi magab, pühenda aeg endale, mitte kodutöödele. Tuba võib olla sassis, kuid sina vajad oma energia taastamist.'),
('8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2'::uuid,'Атанын күлкүлүү үндөрү 🤡','Кадимки ыкмаларыңыз иштебей калганда, кээде атасынын күлкүлүү үндөрү жардамга келет! Кечки ыйлоолор учурунда ''башкарууну'' ага өткөрүп берип, четтен карап ырахат алыңыз.','Issi naljakad hääled 🤡','Kui su tavapärased nipid ei toimi, on mõnikord issi naljakad hääled just see, mida päeva päästmiseks vaja on! Õhtuste jonnihoogude ajal anna vanemlik „pall“ talle üle ja naudi etendust kõrvaltvaatajana.'),
('0d572d8d-fc2a-4534-aab4-0054197f9297'::uuid,'Көз ирмемди сүрөткө тартыңыз! 📸','Бүгүнкү таттуу көз ирмемдерди Ымыркай альбомуна жүктөп, келечекте жылмайып эстей турган эскерүүлөрдү жаратыңыз.','Jäädvusta hetk! 📸','Laadi tänased armsad hetked beebi albumisse, luues mälestusi, mille peale tulevikus naeratad.'),
('6c45dc56-f21e-446c-bca9-3243c5189d5e'::uuid,'Оюнчуктарды ыргытып, карап жатабы? 🎯','Ал тартылуу күчүн жана себеп-натыйжа байланышын ушинтип үйрөнөт! Сабырдуулук менен оюнчукту кайра берип коюңуз.','Viskab mänguasju ja vaatab pealt? 🎯','Nii õpib ta gravitatsiooni ning põhjus-tagajärg seoseid! Anna mänguasi kannatlikult tagasi.'),
('fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9'::uuid,'Сиз жалгыз эмессиз 💬','Тынчсызданып жатасызбы? Anacan коомчулугуна кошулуп, сурооңузду бериңиз. Ишениңиз, ар бир эне ушундай тажрыйбалардан өтөт.','Sa ei ole üksi 💬','Tunned muret? Liitu Anacani kogukonnaga ja esita oma küsimus. Usu meid, iga ema läbib sarnaseid kogemusi.'),
('186e8c82-10c6-4dcc-8ae8-517e2888e663'::uuid,'Түнкү обондор 🛀','Бир күндүк активдүүлүктөн кийин сиз да, ымыркайыңыз да чарчагандырсыздар. Жылуу ванна жана фондо жай ойнолгон тынчтандыруучу музыка анын нерв системасын толук эс алдырат.','Õhtused meloodiad 🛀','Pärast tegusat päeva olete nii sina kui ka su väike laps kindlasti väsinud. Soe vann koos taustal mängiva vaikse ja rahustava meloodiaga rahustab tema närvisüsteemi täielikult.'),
('2c1d3bb2-7e3e-4938-89fb-c5a7a19e27a2'::uuid,'Уйку менен тамактануунун ортосундагы тең салмактуулукту табуу. 📚','Блогдор бөлүмүндөгү ымыркайлардын өнүгүүсү тууралуу акыркы макалабызды окудуңузбу?','Tasakaalu leidmine une ja toitmise vahel. 📚','Kas oled lugenud meie uusimat artiklit vastsündinu arengust blogide jaotises?'),
('34a5aff2-1b83-44f1-acd3-59c942a78f84'::uuid,'Сүрөттөрдү түшүнүү 📖','Китеп карап жатканда ымыркайыңыз сүрөттөгү жаныбарларга же балдарга тийип, ''бул эмне кылып жатат?'' деп сурайбы? Анын визуалдык кабыл алуусу чындап эле укмуш! Бул мүмкүнчүлүктү колдонуп, каармандар жөнүндө кеңири жомок айтып бериңиз.','Piltide mõistmine 📖','Kas su väike laps puudutab raamatuid vaadates piltidel olevaid loomi või lapsi ja küsib: „Mida ta teeb?“ Tema visuaalne mõistmisvõime on tõeliselt hämmastav! Kasuta seda võimalust, et rääkida talle tegelaste kohta üksikasjalikke lugusid.'),
('638fb01b-1266-441c-a6a2-ad8bcb0172d8'::uuid,'Апа үчүн убакыт 🥑','Күнүмдүк түйшүктүн арасында тамакты шашып ичпеңиз. Пайдалуу рецепттерибизден энергия берүүчү тамак тандап, жок дегенде 10 мүнөт диванга жатып, өзүңүздүн тамактанууңузга артыкчылык бериңиз.','Aeg emale 🥑','Ära söö kiirel päeval lõunat jooksu pealt. Vali meie tervislike retseptide hulgast energiat andev vahepala ja sea oma toitumine esikohale, heites vähemalt 10 minutiks diivanile puhkama.'),
('543664cd-6c89-4ffd-ac7b-d08edd1101b7'::uuid,'Шыбырашып сүйлөшүү 🌙','Бөлмөдөгү жарыктын баарын өчүрүңүз. Балаңыздын жанына жатып, ага күндүн окуялары тууралуу акырын шыбырап айтып бериңиз. Шыбырап сүйлөө – баланын мээсин уйкуга даярдоонун эң сонун жолу.','Sosistatud vestlused 🌙','Kustuta toas kõik tuled. Heida lapse kõrvale ja sosista talle vaikselt päeva jooksul toimunust. Sosistamine on suurepärane viis aidata tema aju uneks ette valmistada.'),
('04916f68-94af-484d-968d-c1e05636c373'::uuid,'Териге кам көрүү убактысы. 🛁','Балаңыздын сезимтал терисине ылайыктуу крем издеп жатасызбы? Биздин «Сунушталган товарлар» тизмеси сизге жардамга келет.','Aeg nahahoolduseks. 🛁','Otsid beebi tundlikule nahale sobivaid kreeme? Meie soovitatud toodete nimekiri on sulle abiks.'),
('43caac7d-8fec-4815-a021-c436856ae779'::uuid,'Үч жумалык болду!','Балаңыздын кичинекей жетишкендигин белгилөө үчүн, «Ымыркайдын сүрөт сессиясы» бөлүмүн колдонуп, жагымдуу көз ирмемдерди түбөлүккө калтырыңыз.','Kolm nädalat vana!','Tähistamaks beebi väikest verstaposti, kasuta beebifotode sektsiooni, et jäädvustada üks armas hetk.'),
('93186474-3eab-43ed-a284-f876b4f1b709'::uuid,'Күч-кубат үчүн темир 🥩','Балаңыз бозоруп же бат чарчап жатабы? Этти лимон же помидор сыяктуу С витаминине бай салаттар менен айкалыштырып, темирдин сиңишин жакшыртыңыз.','Raud annab jõudu 🥩','Kas ta tundub veidi kahvatu või väsib kiiresti? Turguta tema rauaimendumist, pakkudes liharoa kõrvale C-vitamiinirikast salatit, näiteks sidruni või tomatitega.'),
('fd977b6d-8463-4d3e-998c-e4dea887a555'::uuid,'Тизмелердин күчү 🛒','Дүкөнгө барганда дайыма бир нерсени унутуп каласызбы? Соода тизмеңиз тиркемеде сизди күтүп жатат. Керектүү нерселерди ошол жерге жазып коюңуз, ошондо жубайыңыз жумуштан кайтканда керектүү азыктарды так алып келе алат.','Nimekirjade vägi 🛒','Kas unustad poes käies alati midagi ära? Sinu ostunimekiri ootab sind äpis. Pane oma vajadused kirja ja su partner saab töölt tulles täpselt vajaliku kaasa osta.'),
('4600773a-c43e-4163-a5da-2b2294833f5c'::uuid,'Күндүзгү уйку маанилүү. 😴','Балаңыз уктап жатканда, уйку таймерин иштетип, анын күнүмдүк уйку тартибин канчалык сактап жатканын текшериңиз.','Igapäevane uni on oluline. 😴','Kui beebi magab, lülita sisse unetaimer ja vaata, kui hästi ta oma igapäevasest unegraafikust kinni peab.'),
('3cf67221-c8f7-4a51-b0e0-23076d4cd531'::uuid,'Кошумча тамак баштоо 🥣','Алты айга жакындап калды! Биринчи пюрелерди киргизүү боюнча кызыгып жатасызбы? Кошумча тамак баштоо тууралуу негизги маалыматты Anacan AI''дан сураңыз.','Tahke toiduga alustamine 🥣','Peaaegu 6-kuune! Kas oled huvitatud esimeste püreede tutvustamisest? Küsi Anacan AI-lt põhjalikku teavet tahke toiduga alustamise kohta.'),
('7c36b46e-089a-4d1a-adf7-c6f69476bd88'::uuid,'Сезимдериңизди күндөлүккө жазыңыз 📝','Сизди эч ким түшүнбөй жаткандай сезилеби? Же чарчаганыңызды эч ким байкабай жатабы? Маанай күндөлүгү сиздин эң жакын сырдашыңыз боло алат. Бардык стрессти, тынчсызданууну жана жалгыздык сезимдерин жазып чыксаңыз, жеңилдеп калганыңызды байкайсыз.','Pane oma tunded kirja 📝','Tunned end valesti mõistetuna? Või et keegi ei näe sinu kurnatust? Meeleolupäevik võib olla sinu parim usaldusisik. Kirjuta üles kogu oma stress, mured ja üksindustunne ning tunned üllatavat kergendust.'),
('592aca51-491e-44f3-b426-3734a638d0f9'::uuid,'Сурооңуз барбы? 🤖','«Эмне үчүн балам түнкүсүн көп ойгонот?» деген сыяктуу суроолоруңуз болсо, Anacan AI ар дайым жардам берүүгө даяр.','Kas sul on küsimusi? 🤖','Küsimuste korral, mis sind vaevavad, näiteks „Miks mu beebi öösel nii tihti ärkab?“, on Anacan AI alati valmis sind aitama.'),
('9d27d38e-2ae9-4b74-ae13-5eaab2d9f776'::uuid,'Бирге болуунун күчү 🥂','Бүгүн кечинде жубайыңыз менен бул укмуштуудай жетишкендикке кантип жеткениңиздерди талкуулаңыз. Сиздер команда катары эң сонун иш аткардыңыздар!','Koosolemise vägi 🥂','Arutage täna õhtul partneriga, kuidas te mõlemad selle uskumatu verstapostini jõudsite. Olete meeskonnana suurepärast tööd teinud!'),
('b5b01983-be53-446e-a05f-8de98770b472'::uuid,'Меники! 🧸','Балаңыз оюнчуктарын башка балдар менен бөлүшкүсү келбей жатабы? Бул өзүмчүлдүк эмес, ал өзүнүн жеке чек арасын коргоону үйрөнүп жатат. Аны буюмдарын берүүгө мажбурлабастан, өзүңүздүн үлгүңүз менен бөлүшүүгө үйрөтүңүз.','Minu oma! 🧸','Kas su laps ei taha oma mänguasju teiste lastega jagada? See ei ole isekus; ta õpib oma isiklikke piire kaitsma. Õpeta talle jagamist oma eeskujuga, selle asemel et sundida teda oma asjadest loobuma.'),
('989db48b-e318-47e6-9019-f4f957b60d59'::uuid,'Себепсиз ыйлоо абдан чарчатат. 😭','Өзүңүздү өтө чарчатпаңыз; ыйдын себебин билүү үчүн «Ыйды талдоо» функциясын колдонуңуз.','Seletamatud nutuhood on kurnavad. 😭','Ära kurna end ära; kasuta nutianalüüsi funktsiooni, et avastada tema nutu sõnum.'),
('b791e063-932d-483a-b56e-e710cf0815c9'::uuid,'Эркин оюн 🧸','Балаңызды ар бир мүнөт сайын көңүл ачып же оюн ойлоп табуунун кажети жок. Зеригүү – көбүнчө балдардагы чыгармачылыктын башталышы. Аларга бөлмөдө өз алдынча бир нерсе табууга мүмкүнчүлүк бериңиз.','Vaba mäng 🧸','Sa ei pea oma last igal minutil lõbustama ega talle mänge välja mõtlema. Igavus on laste loovuse alguspunkt. Lase tal toas midagi omaette avastada.'),
('a6d43603-e416-4760-8a3f-176e42bf2dc7'::uuid,'«Ку-ку» оюну алардын сүйүктүүсү! 🙈','Бетиңизди жаап-ачып «ку-ку» оюнун ойноңуз, балаңыздын кандай кубанганын көрүңүз! Мындай оюндарды «Блогдор» бөлүмүнөн таба аласыз.','Peitusemäng on nende lemmik! 🙈','Mängi peitust, kattes ja avades oma nägu, ning vaata, kui rõõmsaks ta muutub! Leia rohkem sarnaseid mänge blogide sektsioonist.'),
('a85c19d5-09d8-4302-9d52-6f63acdaebee'::uuid,'Түнкү бешик ыры 🎶','Эненин үнүндөй сооротуучу эч нерсе жок. Бүгүн кечинде наристеңизди кучактап, ага жай гана бешик ырын ырдап бериңиз.','Õhtune hällilaul 🎶','Pole midagi lohutavamat kui ema hääl. Kaisu oma pisike täna õhtul lähedale ja laula talle õrn hällilaul.'),
('4ad69c28-25c9-4155-a875-498e8858786c'::uuid,'Өсүү этаптарын көзөмөлдөө!','Кийинки ай жакындап калды! Тиркемедеги «Өсүү трекери» бөлүмүнө кирип, балаңыздын маалыматтарын жаңыртып коюңуз.','Arenguetappide jälgimine!','Järgmine kuu läheneb! Külasta kindlasti äpi kasvujälgimise sektsiooni ja uuenda oma beebi andmeid.'),
('2fc6e816-81b8-4662-85f5-ea7fd4e748a8'::uuid,'Апа үчүн 10 мүнөт ☕','Бөлмөдөгү башаламандык эч жакка качпайт. Балаңыз уктаганда дароо үй жумуштарына киришпеңиз. Тескерисинче, өзүңүзгө кофе куюп алып, 10 мүнөт эс алыңыз.','10 minutit emale ☕','Toas olev segadus ei kao kuhugi. Ära torma kohe koristama, kui pisike magab. Selle asemel vala endale tass kohvi ja lihtsalt lõõgastu 10 minutit.'),
('8dd01cdf-8e98-4b6a-91ce-2edcc5e6a4df'::uuid,'Ызы-чууну азайтыңыз 🤫','Сырттагы ызы-чуу терең уйкуну бузушу мүмкүн. Үн өлчөгүчтү текшерип, керек болсо «ак ызы-чууну» (white noise) колдонууну ойлонуп көрүңүз.','Filtreeri müra 🤫','Välised helid võivad sügavat und häirida. Kontrolli helimõõdikut ja kaalu vajadusel valge müra kasutamist.'),
('78cdd6a4-a9f3-4cd8-8b42-3de0066371e3'::uuid,'Булганууга уруксат бериңиз! 🏖️','Балаңыз ылай же суу менен ойногусу келеби? Кой, ойносун! Мындай сезимдерди өнүктүрүүчү оюндардан кийин тазалоого оңой болгон каражаттарды «Сунушталган товарлар» бөлүмүнөн табыңыз.','Luba endal olla lohakas! 🏖️','Kas su laps tahab mudaga või veega mängida? Lase tal end määrida! Leia lihtsasti puhastatavaid vahendeid nende sensoorsete tegevuste jaoks soovitatud toodete hulgast.'),
('78429eb3-1c37-4e59-ba1f-884cf298f9f6'::uuid,'Эмчек эмизүү кээде узагыраак убакытты алышы мүмкүн. 🍼','Таймерди колдонуп процессти талдаңыз. Эң негизгиси – сизге да, балаңызга да ыңгайлуу болушу.','Söötmine võib vahel kauem aega võtta. 🍼','Analüüsi protsessi taimeri abil. Peaasi, et nii sina kui ka beebi tunneksite end mugavalt.'),
('ade4c5f5-2712-4328-ae1d-961b6a95f615'::uuid,'Бүгүн өзүңүздү кандай сезип жатасыз? 🧘‍♀️','️ Эне болуу – бул сулуу да, чарчатуучу да нерсе. «Маанай күндөлүгүнө» кирип, бүгүнкү күнүңүзгө баа бериңиз.','Kuidas sa end täna tunned? 🧘‍♀️','️ Emadus on ühtaegu ilus ja kurnav. Sisesta oma meeleolupäevikusse tänane hinnang.'),
('a54926e2-dcf2-4ae7-b48f-de76a56a8b5a'::uuid,'Ызы-чууну чыпкалоо 🤫','Балаңыз уктап баратканда үндөргө сезимталдыгы жогорулайт. Терезеден келген сырткы ызы-чууну басуу үчүн бөлмөдө жай гана «ак ызы-чуу» же жаратылыш үндөрүн коюп көрүңүз.','Müra filtreerimine 🤫','Lapse tundlikkus helide suhtes võib uinumise ajal suureneda. Aknast kostva välise müra summutamiseks proovi toas mängida õrna valget müra või rahustavaid loodushelisid.'),
('b1b0d666-c61e-4108-b645-d26f43bbe56c'::uuid,'Ал жакта эмне бар? Буттарды таануу! 👣','Наристеңиз азыр жылаңайлак басып, килемдин же майда таштардын түзүлүшүн сезгенди жакшы көрөт. Буттун нервдерин стимулдаштыруу тең салмактуулукту жана кыймыл-аракетти өнүктүрүү үчүн абдан маанилүү.','Mis seal all on? Jalgade avastamine! 👣','Sinu pisike naudib nüüd paljajalu kõndimist, tundes vaipade või isegi väikeste kivide tekstuuri. Jalgade närvilõpmete stimuleerimine on äärmiselt oluline tasakaalu ja motoorika arenguks.'),
('da011889-3632-43ce-aa11-c46cc9ffe260'::uuid,'Ымыркайга кам көрүү үчүн кандай буюмдар керек? 🧴','Башка энелер сынап көргөн жана жактырган товарларды «Сунушталган товарлар» бөлүмүнөн табыңыз.','Milliseid esmatarbekaupu sa beebi hooldamiseks vajad? 🧴','Avasta teiste emade poolt proovitud ja armastatud tooteid soovitatud toodete sektsioonist.'),
('9bb7f096-5daa-4e1c-9f5e-688698945f7a'::uuid,'Тиш жарып жатабы? 🦷','Төмөнкү тиштеринде оору же шишик барбы? Балаңыздын биринчи тиштери 6 айында чыга башташы мүмкүн.','Kas hambad tulevad? 🦷','Kas alumistes igemetes on valu või turset? Beebi esimesed hambad võivad hakata ilmuma umbes 6 kuu vanuselt.'),
('3259939c-e2bd-4126-abc3-d15439051dda'::uuid,'Таза абанын күчү 🌳','Эгер балаңыз өтө эле тынчсызданып жатса, аны дароо сыртка алып чыгыңыз. Таза аба – мындай учурларда эң жөнөкөй жана натыйжалуу даба.','Värske õhu vägi 🌳','Kui beebi on väga rahutu, mine temaga kohe õue. Värske õhk on nende hetkede jaoks sageli kõige lihtsam ja tõhusam vahend.'),
('07396f85-0dfe-4998-a9ea-d36af8bc97dd'::uuid,'Жөн гана кучактаңыз 🫂','Бүгүн кечинде оюндарды, китептерди же жомокторду унутуңуз. Жөн гана наристеңизди көкүрөгүңүзгө кысып, анын жытын искеп, караңгыда ага канчалык кымбат экенин шыбырап айтыңыз.','Lihtsalt kallista 🫂','Unusta täna õhtul mängud, raamatud ja unejutud. Lihtsalt hoia oma pisikest tihedalt vastu rinda, hinga sisse tema magusat lõhna ja sosista talle pimeduses, kui kallis ta sulle on.'),
('76b75bd8-766d-4f01-b3d1-e6a56e5ad949'::uuid,'Апа да эс алышы керек! 🛋','️ Таймер менен балаңыздын уйку тартибин белгилеп алдыңыз, эми кезек сизде. Өзүңүзгө чай куюп алып, эс алыңыз.','Ema peab ka puhkama! 🛋','️ Nüüd, kui oled taimeriga beebi unegraafiku kirja pannud, on sinu kord. Vala endale teed ja lõõgastu.'),
('382370f5-d970-4100-b0bc-f8460c0758ae'::uuid,'Кармоонун чебери 👐','Ал чоң нерселерди эки колу менен кармоого аракет кылып жатабы? Ага жумшак топ сунуштап, текшерип көрүңүз.','Haaramise meister 👐','Kas ta üritab suurtest esemetest mõlema käega korraga kinni haarata? Katseta seda, pakkudes talle pehmet palli.'),
('ccbcf153-8cbf-48df-8422-b2c8e63c5f2d'::uuid,'Сыйкырдуу аудио жомоктор 🪄','Бүгүн кечинде «Акылдуу жомоктор» бөлүмүндө 6 айлык болгон эр жүрөк рыцарь тууралуу жомок түзүңүз.','Maagilised audiolood 🪄','Loo täna õhtul „Nutikate lugude“ sektsioonis muinasjutt vaprast rüütlist, kes on saanud 6-kuuseks.'),
('0c781594-9b76-4258-9f91-7171c6608a1a'::uuid,'Тажрыйбаңыз менен бөлүшүңүз 💬','Балаңыздын баарына каршы чыгып жатканы сизди чочутуп жатабы? Интернеттен коркунучтуу макалаларды издебеңиз. Anacan коомчулугундагы тажрыйбалуу энелердин кеңештеринен пайдаланыңыз.','Jaga oma kogemust 💬','Kas lapse trots kõige suhtes teeb sind murelikuks? Ära otsi internetist hirmutavaid artikleid. Kasuta Anacani kogukonna kogenud emade elulisi kogemusi.'),
('7e8ac4ba-1fc8-4ac4-92f2-b519b8fbd60b'::uuid,'Ичтин желдеши (газ) башталып жатабы?','Дүрбөлөңгө түшпөңүз. Анын ичин акырын укалап, алаксытуу жана сооротуу үчүн фондо «Ак ызы-чуу» коюңуз.','Kas gaasivalud on tekkimas?','Ära paanitse. Masseeri õrnalt tema kõhtu ja mängi taustal valget müra, et aidata teda tähelepanu kõrvale juhtida ja rahustada.'),
('598525b6-1a5f-4877-944f-c79292ee0167'::uuid,'Максаттуу кыймыл 🐢','Наристеңиз эми жөн эле баспай, чуркап, сизден жашынып ойноп жатабы! Бөлмөдөгү кооптуу нерселерди алып салып, анын кууп ойноого болгон чексиз энергиясына кошулуңуз!','Sihipärane jooksmine 🐢','Sinu pisike ei lepi enam lihtsalt kõndimisega, vaid tuiskab ringi, jookseb kiiresti ja peidab end sinu eest! Veendu, et oled toast eemaldanud kõik ohtlikud takistused, ning liitu siis tema tagaajamis- ja peitusemänguga piiritu energiaga!'),
('01e01b8e-03c9-4797-b794-5c6f68c813f6'::uuid,'Атанын жомок айтып берүүсү 📖','Бүгүн кечинде үнүңүзгө эс бериңиз! Жомок окуп берүүнү атасына тапшырыңыз, ал балаңыздын сүйүктүү китептерин ар кандай үндөр менен кызыктуу кылып окуп берсин.','Issi unejutud 📖','Anna oma häälepaeltele täna õhtul puhkust! Lase issil unejutud üle võtta, lugedes lapse lemmikraamatuid naljakate häälte ja erinevate toonidega.'),
('f833f5dd-8e28-4c1e-a3cb-e9f3a3133ca5'::uuid,'Эмчек сүтүн көбөйтүүнүн сырлары! 🥛','Эмчек сүтүн көбөйтүүчү табигый азыктар жана смузи рецепттери «Дени сак рецепттер» бөлүмүндө сизди күтөт.','Saladused rinnapiima koguse suurendamiseks! 🥛','Loomulikud rinnapiima soodustavad toidud ja smuutiretseptid ootavad sind tervislike retseptide sektsioonis.'),
('0e21a1c5-4a15-41e9-abfe-8342adaebb92'::uuid,'Кемчиликсиз болуунун кажети жок 🛑','Бүгүн чыдамыңыз кетип же бир аз капа болдуңузбу? Өзүңүздү күнөөлөбөңүз. Сезимдериңизди маанай күндөлүгүнө жазып, бир аз эс алып алыңыз.','Pole vaja olla täiuslik 🛑','Kas kannatus katkes täna või tundsid end veidi pettununa? Ära tunne end halvasti. Pane oma tunded meeleolupäevikusse kirja ja võta hetk lõõgastumiseks.'),
('31e88909-0b90-49e0-8727-857efb6836f3'::uuid,'Атанын бешик ыры 👨‍🍼','«Өнөктөш режиминде» эскертмелер жубайыңызга барат. Бүгүн кечинде балаңыздын уйкуга тынч кетиши үчүн бешик ырын ал ырдап берсин.','Issi hällilaul 👨‍🍼','Partnerirežiimis jõuavad teavitused sinu abikaasani. Lase tal täna õhtul laulda hällilaulu, et uinumine sujuks rahulikult.'),
('687bbb3b-79db-41d1-81e9-02d82200fd25'::uuid,'«Жок» деп айтуу фазасы башталат 🛑','Балаңыз кимдир бирөө өпкөнгө аракет кылганда тартынып, «жок» деп айтабы? Анын денесине болгон укугун сыйлоо абдан маанилүү. Каалабаган тийүүлөргө каршы туруу жөндөмү – анын келечектеги өзүнө болгон ишениминин пайдубалы.','Algab „ei“-faas 🛑','Kas su laps tõmbub eemale ja ütleb kindlalt „ei“, kui keegi üritab teda suudelda? Oluline on austada tema kehalist autonoomiat. Tema võime protesteerida soovimatu puudutuse vastu on vundament tema tulevasele enesekindlusele.'),
('a24757f2-97fa-405f-9959-e4c715aa8ed8'::uuid,'Мен сени издеп жатам! 👀','Ал бөлмөдөн чыгып кеткениңизде көзү менен сизди издеп, ыйлайбы? Бөлүнүү коркунучу (сепарациялык тынчсыздануу) башталып жаткан болушу мүмкүн. Аны сооротуп, жанында экениңизди сездириңиз.','Ma otsin sind! 👀','Kas ta otsib sind pilguga ja nutab, kui toast lahkud? Eraldusärevus võib vaikselt alata. Rahusta teda.'),
('081951c6-0b7d-4045-b641-a4716f751a3d'::uuid,'Атанын ийини 👨‍👧','Бир аз чарчап жатасызбы? «Өнөктөш режимине» өтүңүз. Бүгүн кечинде балага кам көрүүнү толугу менен атасына тапшырыңыз.','Issi õlad 👨‍👧','Tunned end veidi ülekoormatuna? Lülitu partnerirežiimile. Lase issil täna õhtul beebi eest täielikult hoolitseda.'),
('b099b3d8-9148-450c-8795-4ab16ea72b2c'::uuid,'Дагы эле суроолоруңуз барбы? 🤖','«Кайсы жашылча пюресинен баштасам болот?» – бул жана башка суроолоруңузду Anacan AI''дан сурап, так маалымат алыңыз.','Kas sul on veel küsimusi? 🤖','Millise köögiviljapüreega peaksin alustama? – Küsi seda ja kõiki muid küsimusi Anacan AI-lt, et saada täpset teavet.'),
('844e0b7f-c62a-4e7b-b863-965ea3061be3'::uuid,'Кучактоого тойбойсуң!','Балаңызды жаткырарыңыз менен ойгонуп ыйлайбы? Бүгүн аны дайыма көтөрүп жүрүүгө туура келип, чарчап жаткандырсыз. Бирок эсиңизде болсун, бала үчүн эң коопсуз жер – сиздин кучагыңыз. Сабырдуу болуңуз.','Ei saa kunagi piisavalt kaisutusi!','Kas beebi ärkab ja nutab kohe, kui ta voodisse paned? Täna võid tunda end piiratuna, hoides teda pidevalt süles. Kuid pea meeles, et kõige turvalisem koht beebile on sinu süles. Ole kannatlik.'),
('34eb8ef4-b7a5-4969-916d-abfccb27c775'::uuid,'Децибелди көзөмөлдөө 🤫','Бала уктап жатканда үй тиричилигинин үндөрү аны чочутабы? Бөлмөнүн акустикасын текшерүү үчүн үн өлчөгүчтү иштетиңиз.','Detsibellide kontroll 🤫','Kas kodused helid ehmatavad sind, kui beebi magab? Aktiveeri helimõõdik, et kontrollida toa akustikat.'),
('da48ef6d-1a19-4a32-9bdc-d912779edf22'::uuid,'Үй чачык, бала бактылуу 🌪️','Бөлмө оюнчуктарга толуп кеттиби? Жаркыраган таза үй, наристеңиз менен өткөргөн 10 мүнөттүк кубанычтуу убакыттан маанилүү эмес.','Segamini kodu, õnnelik laps 🌪️','Kas tuba on mänguasju täis? Laitmatult puhas kodu pole nii oluline kui 10 rõõmsat minutit koos oma pisikesega.'),
('cb9d6b16-c52e-4770-b96a-4ab41dd866dc'::uuid,'Апа чарчаганда 🛑','Сиз темирден жасалган эмессиз. Эгер бүгүн тамак жасоого күчүңүз жок болсо, макарон кайнатыңыз же даяр тамак заказ кылыңыз. Мыкты эне болуу – баарын өзүң жалгыз жасоо дегенди билдирбейт.','Kui ema on väsinud 🛑','Sa ei ole rauast. Kui sul pole täna energiat süüa teha, keeda makarone või telli toit koju. Täiuslik ema olemine ei tähenda, et pead kõike üksi tegema.'),
('f3dc49b8-e32b-422e-80b3-e76c0488dc0f'::uuid,'Өнөктөшүңүздү бул процесске тартыңыз! 👨‍👩‍👦','Бүгүн кечинде жалаяк алмаштырууну же баланы «Ак ызы-чуу» менен уктатууну ага тапшырыңыз, ал эми сиз эс алыңыз.','Kaasa oma partner protsessi! 👨‍👩‍👦','Lase tal täna õhtul mähkmeid vahetada või beebi valge müra saatel magama panna, sina aga puhka.'),
('ec6f8334-a2ec-4274-9ce3-07c0a3276622'::uuid,'Өз алдынча оодарылуу! 🤸‍♂️','Балаңыз чалкасынан ичине жана ичинен чалкасына оодарылууну үйрөндүбү? Бул жетишкендикти «Өнүгүү трекерине» жазып коюңуз!','Iseseisev pööramine! 🤸‍♂️','Kas beebi on seljalt kõhule ja kõhult seljale pööramise selgeks õppinud? Salvesta see verstapost arengujälgijasse!'),
('27dc11b4-8fdd-4bba-a87f-5fa9b264f28d'::uuid,'Уйкунун белгилери 🥱','Көзүн ушалап жатабы? Ыйлап жиберүүсүн күтпөңүз; дароо жарыкты өчүрүп, уйку алдындагы тартипти баштаңыз.','Unemärgid 🥱','Hõõrub silmi? Ära oota nutuhoogu; hämarda kohe tuled ja alusta oma une-eelset rutiini.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('438805fb-6787-4d0d-b1d5-b2a1a747c30c'::uuid,'Ич катуунун белгилери 💩','Энергиялуу балаңыз чуркап жүрүп суу ичүүнү унутуп калдыбы? Горшоктогу заңынын абалын көзөмөлдөп туруңуз. Алардын рационуна сулу боткосу жана кара өрүк сыяктуу клетчаткага бай азыктарды кошууну унутпаңыз.','Kõhukinnisuse tunnused 💩','Kas sinu energiline laps jookseb nii palju ringi, et unustab vett juua? Jälgi kindlasti tema potil käimist. Ära unusta lisada tema toidulauale kiudainerikkaid toite, nagu kaerahelbed ja ploomid.'),
('788697fe-7a57-4c4c-a3dc-514298d952ed'::uuid,'Өзүңүздү мактап коюңуз 👏','Бардык жазууларыңызды карап чыгыңыз. Алардын канчалык чоңойгонун жана сиздердин канчалык тажрыйба топтоп калганыңыздарды көрүңүз! Сиздер чындап эле укмуштуудай командасыздар.','Kiida ennast 👏','Vaata tagasi kõigile oma sissekannetele. Näe, kui palju nad on kasvanud ja kui palju oled sina õppinud! Te olete tõesti suurepärane meeskond.'),
('7f7b88ee-089c-4ccc-9849-c2f4117d4833'::uuid,'Жеңиштүү кеч 🥂','Бүгүн кечинде, бала уктагандан кийин, өнөктөшүңүз менен отуруңуз. Бул 180 күн үчүн сыймыктаныңыз жана бири-бириңизди бекем кучактап коюңуз!','Võidukas õhtu 🥂','Täna õhtul, kui laps magab, istu koos partneriga maha. Tundke uhkust nende 180 päeva üle ja kallistage teineteist kõvasti!'),
('2ecd0a8e-2817-4551-98e0-4276739c7da9'::uuid,'Биз бир командабыз! 💖','Сиздер 6 айлык уйкусуз түндөрдө бири-бириңиздерге таяныч болдуңуздар. Маанай күндөлүгүңүздү ачып, бул укмуштуудай командалык иш үчүн өнөктөшүңүзгө ыраазычылык билдириңиз.','Me oleme meeskond! 💖','Olete olnud teineteisele toeks läbi 6 kuu unetute ööde. Ava oma meeleolupäevik ja tänage partnerit selle uskumatu meeskonnatöö eest.'),
('ce877206-0633-48d8-aa8f-9241cfab27c3'::uuid,'Атайын отургучтагы укмуштуу окуялар 🪑','Тамактандыруучу отургуч алууну ойлонуп жатасызбы? Эргономикалык жана тазалоого оңой варианттар үчүн биздин «Сунушталган өнүмдөр» бөлүмүн карап чыгыңыз.','Söögitooli seiklused 🪑','Mõtled söögitooli soetamisele? Sirvi meie soovitatud toodete sektsiooni, kust leiad ergonoomilisi ja kergesti puhastatavaid valikuid.'),
('70951e1d-e161-4f61-adb6-2b3b015c6f79'::uuid,'Күндөлүк жалаяк алмаштыруу кандай болуп жатат? 🧷','Балаңыз жетиштүү тамактанып жатканын билүүнүн эң оңой жолу — бул «Жоолук алмаштыруу» жазуулары. Аларды азыр тиркемеге киргизиңиз!','Kuidas igapäevane mähkmete hulk välja näeb? 🧷','Kõige lihtsam viis teada saada, kas su laps sööb piisavalt, on mähkmevahetuste logide kaudu. Sisesta need nüüd rakendusse!'),
('9b230269-a517-40c2-a23b-f2bd57a211d4'::uuid,'Биринчи жылмаюу жакында!','Алардын сиздин жүзүңүздү тике карап турган көз ирмемдерин өткөрүп жибербеңиз. Бул учурлар жараткан сезимдерди Маанай күндөлүгүңүзгө жазып коюңуз.','Esimene naeratus on peagi tulemas!','Ära maga maha hetki, mil nad su nägu tähelepanelikult uurivad. Pane kirja emotsioonid, mida need hetked sinus tekitavad, oma meeleolupäevikusse.'),
('6e0e2948-0156-4f7e-a4e9-342d621f5670'::uuid,'Түгөнбөгөн уктоо алдындагы шоу 🛌','Кичинекейиңиз уктабай төшөктө секирип жатабы? Уйку таймерин коюп, жатуу убактысынын эрежелерин сүйүү менен сактаңыз. Биздин «Ак ызы-чуу» (White Noise) функциясындагы токойдун тынч шыбыры менен бөлмөнү бейпил уйку аймагына айлантыңыз.','Lõputu magamamineku etendus 🛌','Kas su väike põngerjas hüppab voodis, selle asemel et magama jääda? Sea unetaimer ja kehtesta armastavalt magamamineku piirid. Muuda tuba rahulikuks unetsooniks meie valge müra funktsiooni ja metsa rahustava kohinaga.'),
('c7ebe08f-c601-4b91-b115-456e094665de'::uuid,'Кальций калканы 🦴','Сүт ичпей жатабы? Кальций сөөктөр үчүн абдан маанилүү. Сыр, йогурт же брокколинин бүгүнкү өлчөмүн эсептөө жана жетишсиздикти толуктоо үчүн «Тамактануу трекерин» колдонуңуз.','Kaltsiumikilp 🦴','Ei joo piima? Kaltsium on luudele hädavajalik. Kasuta toitumisjälgijat, et arvutada tänane juustu, jogurti või brokoli tarbimine ja korvata võimalikud puudujäägid.'),
('6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed'::uuid,'Күн тартибин түзө баштайлы! 🌙','Балаңызды жуунтуп, бир убакта тамактандырыңыз жана «Ак ызы-чуу» менен уйку таймерин иштетиңиз.','Loome rutiini! 🌙','Vannita last, toida teda samal ajal ja käivita unetaimer koos mängiva valge müra heliga.'),
('b2ff3f80-95a8-44a7-96b9-573095f4b7ba'::uuid,'Апа катары өз муктаждыктарыңызды унутпаңыз. 🛍','Эмчек учуна арналган кремди жана төшөмөлөрдү колдонуу сизге ыңгайлуулук тартуулап, коргоону камсыз кылат.','Ära unusta oma vajadusi emana. 🛍','Nibukreemi ja rinnapatjade kasutamine aitab sul end mugavamalt tunda ja pakub kaitset.'),
('b0e5435a-23a4-401e-a5a2-1b672694e080'::uuid,'Аба ырайынын сюрприздери! ⛅','Аба ырайынын өзгөрүлмөлүүлүгүнө алданып, сейилдөө учурунда балаңызды үшүтүп албаңыз. Жөн гана терезеден карабастан, үйүңүздөн чыгар алдында сырткы чөйрө үчүн эң ылайыктуу кийимди тандоо үчүн «Аба ырайы жана кийим тандоо жардамчысын» колдонуңуз.','Ilmaüllatused! ⛅','Ära lase petlikul ilmal end eksitada ja oma pisikest jalutuskäigul külmetada. Ära piilu vaid aknast välja; kasuta ilma- ja riietusabilist, et määrata enne kodust lahkumist parim kombinatsioon õues viibimiseks.'),
('c7c50614-edd2-448c-a9f6-e76579ba2f11'::uuid,'Түнкү бороон 😭','Түн ортосунда себепсиз ыйлап ойгондубу? Ичи желдеп жатабы же жөн гана уйку коркунучубу? Аны акырын кучактап, үнүңүздү көтөрбөй, тынчтандырып кайра уктатыңыз.','Öine torm 😭','Kas ta ärkas keset ööd nuttes ilma põhjuseta? Kas need on gaasivalud või lihtsalt uneterror? Kallista teda vaikselt ja paku talle häält tõstmata turvatunnet, et ta uuesti uinuks.'),
('1961895f-8e5d-4529-9dd1-eba3d3c72045'::uuid,'Бул өсүү мезгили! 📈','Балаңыз бат-баттан ачка болуп жаткан болушу мүмкүн. «Тамактануу трекериндеги» таймерди колдонуп, алардын тамактануу графигин көзөмөлдөңүз.','See on kasvuspurt! 📈','Sinu laps võib hakata sagedamini süüa küsima. Jälgi tema toitmise graafikut toitmise jälgija taimeri abil.'),
('1297700e-9cfd-4ca4-a9de-fc8b3c3e36fd'::uuid,'Жаңы жомокторду табыңыз 📖','Бүгүн кечти өзгөчө кылалы. «Акылдуу жомоктор» бөлүмүндө жекелештирилген жомок түзүп, бөлмөнү сыйкырга толтуруңуз.','Avasta uusi lugusid 📖','Teeme tänase õhtu eriliseks. Loo nutikate lugude funktsioonis isikupärastatud unejutt ja täida tuba võlumaailmaga.'),
('9d58451e-ede3-4a05-ba21-dd4e0b7f4086'::uuid,'Жалаяк алмаштырууну көзөмөлдөө 🧷','Кошумча тамак киргизүүдөн мурун, алардын тамак сиңирүү системасы жакшы иштеп жатканын текшерүү үчүн ар бир жоолук алмаштырууну Anacan тиркемесине жазып туруңуз.','Mähkmevahetuse jälgimine 🧷','Enne tahke toiduga alustamist logi iga mähkmevahetus Anacanis, et veenduda lapse seedesüsteemi heas toimimises.'),
('ccc01a90-d6a0-43fa-b96b-7ed5976f5309'::uuid,'Бөлүнүүдөн коркуу (сепарациялык тынчсыздануу) 🥺','Сиз дааратканага кирсеңиз эле, алар эшиктин артында ыйлап күтүп калышы мүмкүн. Бул бөлүнүү коркунучу күчөй турган мезгил. Аларга үнүңүздү чыгарып, жанында экениңизди жана жакында чыгарыңызды айтып, сооротуп коюңуз.','Lahkumisärevus 🥺','Isegi kui lähed vaid korraks tualetti, võib ta ukse taga oodata ja nutta. See on faas, kus lahusolekuärevus võib vahel tugevneda. Rahusta teda oma häälega, andes teada, et oled lähedal ja tuled kohe tagasi.'),
('2450c51d-55f8-4e27-b691-cd2f503d7dd4'::uuid,'Кечинде тынчсыздануу көбөйүп жатабы? 🎶','Бул ичтин оорушу же чарчоо болушу мүмкүн. «Ак ызы-чуу» бөлүмүндөгү жаратылыш үндөрү менен балаңызды тынчтандырыңыз.','Kas õhtune rahutus suureneb? 🎶','Need võivad olla gaasivalud või väsimus. Rahusta oma last valge müra sektsiooni loodushelidega.'),
('edc6faba-a997-408a-a40b-e590a39a3721'::uuid,'Мен отуруп калдым! 🪑','Кичинекейиңиз жөлөнгүч менен отурганда өзүн ишенимдүү сезип жатабы? Жаздыктардын жардамы менен отурууга үндөңүз, бирок кыска убакытка гана.','Ma istun juba! 🪑','Kas su väike laps on toetusega istudes enesekindlam? Julgusta teda patjade abil istuma, kuid tee seda vaid lühikest aega.'),
('1f77c97d-063c-457e-9c51-eaecc473dae1'::uuid,'Жаңы досторду табуу 👫','Балаңыз сейил бакта өзү теңдүү балдарга чуркап барууга аракет кылып жатабы? Куттуктайбыз, социалдашуу расмий түрдө башталды! Бул алгачкы аракеттерди сыймыктануу менен байкап, алыстан жумшак коопсуздук камсыз кылыңыз.','Uute sõprade leidmine 👫','Kas su laps üritab pargis joosta ja teiste eakaaslaste juurde minna? Palju õnne, sotsialiseerumine on ametlikult alanud! Jälgi uhkusega neid esimesi katsetusi, pakkudes eemalt õrna turvavõrku.'),
('936424c3-1b30-4fc1-924e-920162d0d5bd'::uuid,'Абсолюттук тынчтык 🤫','Уйкуга жатуу кыйын болуп жатабы? Бөлмөдөгү децибелди текшерүү үчүн үн өлчөгүчтү колдонуңуз жана бөлмө толугу менен караңгы экенине ынаныңыз.','Absoluutne vaikus 🤫','Kas uinumisega on raskusi? Kasuta helimõõdikut, et kontrollida toa detsibelle ja veenduda, et seal on täiesti pime.'),
('6dad4f0a-8c98-4797-a95f-50aab81d4662'::uuid,'Аба ырайынын сюрприздери ⛅','Сейилдөөгө чыгарда аба ырайына алданып, балаңызды үшүтүп албаңыз. Сыртка ылайыктуу кийим тандоо үчүн аба ырайы жана кийим жардамчысын колдонуңуз.','Ilmaüllatused ⛅','Jalutama minnes ära lase ilmal end üllatada ja riski lapse külmetamisega. Kasuta ilma- ja riietusabilist, et valida õues viibimiseks sobiv riietus.'),
('affd2ecc-89d1-4649-8b63-63dfe9a1ced9'::uuid,'Сени издеп жатам! 👀','Балаңыз сиз бөлмөдөн чыгып кеткенде эле ыйлай баштайбы? Бөлүнүү коркунучу толук өнүгүп жатат. Алар жөн гана сиз кайтып келбей каласызбы деп коркушат. Үнүңүз менен аларды сооротуңуз.','Otsin sind! 👀','Kas su laps hakkab nutma kohe, kui toast lahkud? Lahusolekuärevus on täies hoos. Ta lihtsalt kardab, et sa ei tule tagasi. Rahusta teda oma häälega.'),
('c4e8f9e9-c94b-41fc-a23a-61a8c7026386'::uuid,'Тамак сиңирүүдөгү өзгөрүүлөр 🧷','Кошумча тамак киргизгенде, балаңыздын ичегисинин иштеши өзгөрөт. Бул өзгөрүүлөрдү көзөмөлдөө үчүн ар бир жоолук алмаштырууну Anacan тиркемесине жазып туруңуз.','Seedimise muutused 🧷','Tahke toidu tutvustamisel lapse väljaheide muutub. Jälgi neid muutusi, logides iga mähkmevahetuse Anacanis.'),
('3bd59fce-abbd-4e13-ab2d-4379b5c89cac'::uuid,'Ымыркай пюре жебей, тамакты түкүрүп жатабы?','Өзүңүздү жетишсиз сезбеңиз. Бул алар үчүн таптакыр жаңы тажрыйба, андыктан сабырдуу болуңуз.','Kas beebi keeldub püreedest ja sülitab toidu välja?','Ära tunne end ebakindlalt. See on nende jaoks täiesti uus kogemus, seega ole kannatlik.'),
('48005ac4-750b-4fca-b0cd-2711d3eb3c21'::uuid,'Аудио жомоктор 🪄','Бүгүн кечти «Акылдуу жомоктор» бөлүмүндө жомок түзүү менен көңүлдүү аяктаңыз.','Audiolood 🪄','Lõpeta tänane päev lõbusalt, luues Smart Stories funktsioonis üks tore lugu.'),
('ae1cbea0-aaaf-49ff-9518-967813809e3b'::uuid,'Тиш жаруудагы кыйынчылыктар? 🦷','Кошумча тамак киргизүү мезгилинде тиш жаруудагы ыңгайсыздык күчөшү мүмкүн. Дарыгериңиздин кеңеши боюнча тиш гелин колдонуңуз.','Hammaste tuleku mured? 🦷','Hammaste tulekuga seotud ebamugavustunne võib tahke toiduga alustades suureneda. Kasuta igemegeeli vastavalt arsti soovitustele.'),
('4beff801-d69f-40c0-bed1-2e8938edb5f2'::uuid,'Башка апалар эмне кылып жатышат? 💬','Кичинекейиңиз ашкабак пюресин жактырбай жатабы? Башка энелердин тажрыйбасынан үйрөнүү жана жаңы рецепттерди табуу үчүн Anacan коомчулугуна кошулуңуз.','Mida teised emad teevad? 💬','Sinu pisikesele ei meeldi kõrvitsapüree? Liitu Anacani kogukonnaga, et õppida teiste emade kogemustest ja avastada uusi retsepte.'),
('7df7f58f-05e6-4afb-aa2c-73438e6504d4'::uuid,'Уйкунун белгилери 🥱','Эгер алар көзүн ушалап, бош карап жатса, ыйлап жибергенин күтпөңүз. Дароо жарыкты өчүрүп, уйку тартибин баштаңыз.','Unemärgid 🥱','Kui laps hõõrub silmi ja vaatab tühja pilguga, ära oota jonnihoogu. Hämarda kohe tuled ja alusta uneajaga.'),
('8afe4995-9e98-44a1-a9cc-5c970d87a396'::uuid,'Жардамсыз отуруу: Биринчи аракеттер 🪑','Алар эми жаздыкка азыраак таянып жатышабы? Жакында эч кандай жөлөнгүчсүз эле отуруп калышат!','Ise istumine: esimesed katsed 🪑','Kas ta toetub juba vähem patjadele? Peagi istub ta täiesti iseseisvalt!'),
('34c92908-0941-4c15-a946-75240f0ea7f7'::uuid,'Маанайыңыз менен бөлүшүңүз 📝','Бүгүн аябай чарчадыңызбы? Сезимдериңизди маанай күндөлүгүнө чынчылдык менен жазыңыз. Баарын чыгарып салуу сизге жеңилдик берет.','Jaga oma tuju 📝','Kas tunned end täna täiesti kurnatuna? Pane oma tunded ausalt kirja meeleolupäevikusse. Kõikide mõtete välja kirjutamine teeb head.'),
('cd45d0d2-bf31-47be-adf8-84c3b1895339'::uuid,'Бул коликиби же газбы? 😭','Кошумча тамак ичүү ич катууга же газга алып келиши мүмкүн. Эгер эч нерсе жардам бербесе, ыйдын себебин табуу үчүн «Ыйды талдоо» функциясын колдонуңуз.','Kas see on koolik või gaasid? 😭','Tahke toidu alustamine võib põhjustada kõhukinnisust või gaase. Kui miski ei tundu teda rahustavat, kasuta nutuanalüüsi, et leida nutu põhjus.'),
('1f9cc7dc-a0b4-41a4-983b-794c5917ee08'::uuid,'Кол менен изилдөө! 🧸','Балаңыз оюнчуктарды бир колунан экинчи колуна эркин өткөрүп жатабы? Алардын мээсинин жарым шарлары сонун иштеп жатат! Аларга ар кандай текстурадагы буюмдарды сунуштаңыз.','Käest-kätte uurimine! 🧸','Kas su beebi annab mänguasju vabalt ühest käest teise? Tema ajupoolkerad töötavad suurepäraselt! Paku talle erineva tekstuuriga esemeid.'),
('298934a2-9d12-42b8-8c9c-6098d3709ab4'::uuid,'Маектешүү узарып баратат! 🗣️','Да-да-да, ба-ба-ба деген үндөр үйүңүздө жаңырып жатабы? Алардын тил өнүгүүсү тууралуу көбүрөөк окуу үчүн «Блогдор» бөлүмүнө кириңиз.','Vestlused muutuvad pikemaks! 🗣️','Da-da-da ja ba-ba-ba helid kajavad su kodus. Külasta blogide sektsiooni, et lugeda lähemalt lapse keelelise arengu kohta.'),
('89ff16e6-d11a-4deb-ae4f-1ba03e76271d'::uuid,'Ата: Түнкү баатыр 🦸‍♂️','Алгачкы айлардагы эң жакшы эрежелердин бири: бешик ырын кезектешип ырдоо! Бүгүн кечинде бала атасынын кучагында, бул сизге эс алууга мүмкүнчүлүк берет.','Issi: öine kangelane 🦸‍♂️','Üks parimaid reegleid esimesteks kuudeks: vahetage hällilaulude laulmisel! Täna on beebi issi süles, mis annab sulle võimaluse puhata.'),
('5378180a-aa43-4728-9384-08bbcf8838ee'::uuid,'Мени менен сүйлөшүңүз! 🗣️','Алар ''Ба-ба'' жана ''Ма-ма'' сыяктуу муундарды так айтып жатышабы? Алардын үндөрүнө жооп берип, бул баарлашууга үндөңүз.','Räägi minuga! 🗣️','Kas ta ütleb silpe nagu ''ba-ba'' ja ''ma-ma'' juba selgemalt? Vasta tema häälitsustele ja julgusta seda suhtlust.'),
('a4be80bb-cd06-42ba-b875-78d5a32af3ba'::uuid,'Командалык талкуу 🛋️','Оор күндөн кийин өнөктөшүңүз менен отуруп, ой бөлүшүңүз. Бири-бириңизди колдоо жүктү чындап эле жеңилдетет.','Meeskonna arutelu 🛋️','Pärast rasket päeva istu koos partneriga maha ja jaga oma mõtteid. Teineteise toetamine jagab koorma tõepoolest pooleks.'),
('efa880a4-37d0-4521-93db-df2495a01243'::uuid,'Өзүңүз менен сыймыктаныңыз! 👏','Артка кылчайып, алгачкы жумалар канчалык оор болгонун эстеңиз. Эми сиз пюре жасоонун чебери болуп калдыңыз!','Ole enda üle uhke! 👏','Vaata tagasi ja meenuta, kui hirmutavad need esimesed nädalad tundusid. Nüüd oled sa püreetegemises juba proff!'),
('5be2b9be-dabd-44b8-93f3-30aaaab56ccf'::uuid,'Түнкү бешик ыры 🎶','Эненин үнүндөй сооротуучу эч нерсе жок. Бүгүн кечинде кичинекейиңизди кучактап, акырын бешик ырын ырдап бериңиз.','Õhtune hällilaul 🎶','Pole olemas midagi lohutavamat kui ema hääl. Lihtsalt kaisuta täna õhtul oma pisikest ja laula talle õrnalt hällilaulu.'),
('98621899-f977-46d0-ba01-3a49123c5aef'::uuid,'Эмгектеп жүрүү аракеттери! 🐢','Балаңыз ичи менен оодарылып, артка жылып же тизесине турууга аракет кылып жатабы? Бул активдүү өнүгүү көз ирмемдерин дароо «Баланын альбомуна» кошуңуз.','Roomamiskatsed! 🐢','Kas su beebi veereb kõhuli, nihkub tagurpidi või üritab põlvedele tõusta? Lisa need aktiivsed arenguhetked kohe beebialbumisse.'),
('2421fc4d-6878-4078-87b3-b7d35e8743ea'::uuid,'Өзүңүзгө кам көрүүнү унутпаңыз! 🥗','Сиздин ден соолугуңуз — алардын ден соолугу. Күч-кубатыңызды калыбына келтирүү үчүн аялдардын ден соолугуна пайдалуу рецепттерибизден энергия берүүчү тамак тандаңыз.','Ära unusta enda eest hoolitseda! 🥗','Sinu tervis on ka tema tervis. Vali meie tervislike retseptide hulgast üks kosutav vahepala, et taastada oma elujõud.'),
('f5a121b8-a795-4ca6-87d9-f17351b40bec'::uuid,'Өнүгүү боюнча тынчсыздануулар барбы? 🤖','Балам азырынча сойлобой жатат, бул нормалдуубу? – Бул жана башка суроолорду Anacan AI''дан сурап, эксперттик жоопторду алыңыз.','Mured arengu pärast? 🤖','Minu beebi ei rooma veel, kas see on normaalne? – Küsi seda ja muid küsimusi Anacan AI-lt, et saada asjatundlikke vastuseid.'),
('6f0575b2-9379-4dca-bf05-d518a93aead1'::uuid,'Кайсы тараптан эмиздиңиз? 🤱','Кайсы эмчек менен эмизгениңизди көзөмөлдөө үчүн таймерди колдонуңуз, калганын Anacan эстеп калат!','Kummalt poolt sa toitsid? 🤱','Kasuta taimerit, et jälgida, millisest rinnast sa toitsid, ja lase Anacanil kõik enda eest meeles pidada!'),
('3eccfd90-7490-4750-87b2-6db63c387fc8'::uuid,'Пижамадагы күрөш 👕','Уйкуга кийим алмаштыруу күнүмдүк күрөшкө айланып жатабы? Тандоо сунуштаңыз: Кызыл пижаманы киесиңби же көгүнбү? Бул кичинекей амал аларга өзүн башкарып жаткандай сезим берет.','Pidžaama-maadlus 👕','Kas magamaminekuks riietumine muutub õhtuseks võitluseks? Anna talle valikuvõimalus: kas soovid punast või sinist pidžaamat? See väike nipp annab talle kontrollitunde.'),
('d9470e5a-6317-45d8-9bd1-419a7827e3e6'::uuid,'Түнкүсүн ойгонуу тартибин түзүү 😴','Ар ойгонгон сайын жарыкты күйгүзүүдөн качыңыз. Тамактанууну көзөмөлдөө үчүн Anacan таймерин колдонуңуз, андан кийин «Ак ызы-чуу» менен кайра уктатыңыз.','Öiste ärkamiste rutiini loomine 😴','Väldi tulede süütamist iga kord, kui ta ärkab. Kasuta Anacani taimerit toitmise jälgimiseks ja rahusta ta seejärel valge müra abil uuesti magama.'),
('07efb31a-2639-41f8-b1c7-f3807d010a8f'::uuid,'Убакытты токтотуңуз 📸','Алар тез эле чоңоюп баратат... Алар уктап жатканда, түбөлүк эстелик калтыруу үчүн «Баланын фотосессиясын» уюштуруп, ошол таттуу, бейпил жүзүн тартып алыңыз.','Peata aeg 📸','Ta kasvab nii kiiresti... Kui ta magab, jäädvusta need armsad ja rahulikud näojooned beebifotosessiooniga, et luua kestvaid mälestusi.'),
('7deb7b07-a963-4605-b27c-7714e980157d'::uuid,'Суроолоруңуз барбы? 🤖','Кошумча тамак жана суу киргизүү боюнча миңдеген суроолоруңуз барбы? Anacan AI''дан сурап, педиатрдын так кеңешин алыңыз.','Kas sul on küsimusi? 🤖','Kas sul on tuhat küsimust tahke toidu ja vee pakkumise kohta? Küsi Anacan AI-lt ja saa täpseid lastearsti nõuandeid.'),
('ab8df92e-4241-44fb-8ac7-10559ea60a6f'::uuid,'Мен сени тааныдым! 🥰','Бөтөн адам келгенде балаңыз сизге жабышып алабы? Кабатыр болбоңуз, алар жөн гана тааныш жана бейтааныш жүздөрдү айырмалап жатышат. Бул дени сак когнитивдик өнүгүүнүн белгиси.','Ma tunnen su ära! 🥰','Kas su beebi hoiab sinust kinni, kui võõras inimene tuleb? Ära muretse, ta lihtsalt eristab tuttavaid ja võõraid nägusid. See on märk heast kognitiivsest arengust.'),
('0e6fe355-3307-4562-8e24-f479625f3ff6'::uuid,'Экөөңүздөргө тең таза аба керек. 🌳','Эң жакын сейил бакты тандап, күнүңүздү көңүлдүү өткөрүңүз.','Värske õhk teile mõlemale. 🌳','Vali lähim park ja naudi oma päeva.'),
('4085929a-ec71-4c5c-a693-62bb796910ba'::uuid,'Кызыктуу кийим тандоолор! 👗','Балаңыз үшүп жатабы же өтө эле калың кийинтип алдымбы деп кээде тынчсызданасызбы? Тартынбаңыз. Аба ырайын жана ылайыктуу кийимди текшерип, аларды ишенимдүү кийиндириңиз.','Omapärased riietumisvalikud! 👗','Kas muretsed vahel, kas beebil on liiga külm või oled talle liiga soojalt riided selga pannud? Ära kõhkle. Kontrolli ilma ja sobivat riietust ning riieta teda enesekindlalt.'),
('e7ddb2bb-cbd6-4f99-9f52-7fc0bb34e7ba'::uuid,'Стратегиялык тынчтык 🤫','Уктап жатканда капыстан чыккан үндөр аларды ойготуп жатабы? Үн өлчөгүч менен бөлмөнүн децибел чегин көзөмөлдөңүз.','Strateegiline vaikus 🤫','Kas äkilised helid äratavad ta uinumise ajal? Jälgi ruumi detsibellide taset helimõõtjaga.'),
('3e7220fc-a665-4ed2-8b95-f202d84e92a8'::uuid,'Өзүм кармап ичем! 🧸','Бөбөгүңүз асылып турган оюнчуктарды так кармап жатабы? Анын кол жана көз координациясы жакшырып баратат! Аны ачык түстөгү буюмдар менен шыктандырып туруңуз.','Hoian ise! 🧸','Kas su beebi sirutab käsi rippuvate mänguasjade järele juba täie täpsusega? Tema käe-silma koordinatsioon tugevneb! Julgusta teda erksavärviliste esemetega.'),
('bd3843ff-7d20-45e7-9e12-a76db028322e'::uuid,'Кичинекей башын көтөрүү!','Ымыркайдын альбомуна анын курсак менен жаткан учурдагы кыймыл-аракеттери тартылган видеолорду кошуп коюңуз.','Tõstab juba pead!','Lisa beebialbumisse videoid tema liigutustest kõhuli olemise ajal.'),
('747238a1-853b-4e40-a51e-30b2b6d818ac'::uuid,'Өзүңүздү күнөөлөбөңүз! 💖','Бөбөгүңүз менен жетиштүү убакыт өткөрбөй жаткандай сезилип жатабы? Эсиңизде болсун, 10 мүнөттүк сапаттуу жана кубанычтуу баарлашуу стресске толгон бир сааттан алда канча баалуу.','Ära tunne süümepiinu! 💖','Tunned, et ei veeda beebiga piisavalt aega? Pea meeles, et 10 minutit kvaliteetset ja rõõmsat koosolemist on väärtuslikum kui stressirohke tund.'),
('a8ca5021-abaf-413e-abe5-95d715e5127d'::uuid,'Терең уйкуга даярдык 🛀','Жылуу ванна, жайлуу массаж жана караңгылатылган бөлмө... Уйку режими — бул алтын эреже.','Valmistumine sügavaks uneks 🛀','Soe vann, õrn massaaž ja hämar tuba... Une-eelne rutiin on kuldne reegel.'),
('a9a77950-254b-44a6-a42a-1aaac4de986d'::uuid,'Тынч убакыт ☕','Эгер ал уктагысы келбесе, жок дегенде бир саатты «Тынч убакытка» бөлүңүз. Ал төшөгүндө китеп карап жатса, сиз чай ичип, эс алып алыңыз.','Vaikne hetk ☕','Kui ta ei taha uinakut teha, eralda vähemalt tund „vaikseks ajaks“. Lase tal voodis raamatut sirvida, samal ajal kui sina jood teed ja puhkad.'),
('17a57fd8-a4e1-4a40-b13f-cad6191dae2a'::uuid,'Жаңы даамдарды татып көрүү! 🍎','Бүгүн кайсы жемишти же жашылчаны тааныштырасыз? Илхам алуу үчүн «Кошумча тамактандыруу рецепттери» бөлүмүн сөзсүз карап чыгыңыз.','Uute maitsete avastamine! 🍎','Millise puu- või köögivilja sa täna tutvustad? Inspiratsiooni saamiseks vaata kindlasti meie beebide lisatoidu retsepte.'),
('b98f5eb2-8b81-4c72-8526-61cc728e9e49'::uuid,'Түгөнбөс жомоктор 📖','Бүгүн кечинде «Акылдуу жомоктор» бөлүмүнөн эр жүрөк жана акылдуу бала жөнүндө жомок ойлоп табыңыз.','Lõputud lood 📖','Loo täna õhtul „Nutikate lugude“ abil jutt ühest vaprast ja nutikast lapsest.'),
('0ced9920-5225-4ffc-81ba-de83e31f1bd2'::uuid,'Эртең мененки серенада! 🎶','Ал сизге карап, ар кандай муундарды айтып жатабы? Учурда ал бөлмөдөгү эң сонун таңкы концертти тартуулап жатат — кунт коюп угуңуз!','Hommikune serenaad! 🎶','Ta vaatab sulle otsa ja teeb erinevaid silpe. Praegu annab ta toas kõige ilusamat hommikukontserti – kuula hoolega!'),
('db243270-0483-44d0-9aef-b63565c06a9e'::uuid,'Дарыгердей акылдуу 🤖','Кошумча тамактан баштагандан бери бөбөгүңүздүн заңы өзгөрдүбү? Кабатыр болбой, бул нормалдуубу же жокпу, Anacan AI''дан сурап көрүңүз.','Tark kui doktor 🤖','Kas beebi väljaheide on pärast lisatoiduga alustamist muutunud? Selle asemel, et muretseda, küsi Anacan AI-lt, kas see on normaalne.'),
('193d109c-1b4e-4ffc-b28d-b0ef379e189f'::uuid,'Караңгыдагы желмогуздар 🌌','Жарык өчкөндө балаңыз көлөкөдөн коркуп жатабы? Элестетүүсү өнүккөн сайын, коркуу сезими реалдуу сезилиши мүмкүн. Ага керектүү коопсуздук сезимин тартуулоо үчүн «Ак ызы-чуу» (White Noise) функциябыздан эненин курсагындагыдай тынчтандыруучу үндү коюп бериңиз.','Koletised pimeduses 🌌','Kas su laps kardab pimeduse saabudes varje? Kujutlusvõime arenedes võivad hirmud tunduda väga tõelistena. Mängi meie „Valge müra“ funktsioonist emaüsas kostvaid rahustavaid helisid, et pakkuda talle vajalikku turvatunnet.'),
('52e4f8ee-826b-476b-b87c-2f51c60ddd09'::uuid,'Күтүлбөгөн жерден ыйлоо 😭','Бөбөгүңүз эч себепсиз эле ыйлап ойгонуп жатабы? Балким, ал эмоционалдык чарчоону сезип жаткандыр. Anacan AI адисибиз менен баарлашып, тынчтандыруунун жолдорун билип алыңыз.','Äkilised nutuhood 😭','Kas su väike laps ärkab nutuga ilma nähtava põhjuseta? Võib-olla on ta emotsionaalselt ülekoormatud. Avasta rahustavaid tehnikaid, vesteldes meie Anacan AI eksperdiga.'),
('9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14'::uuid,'Таза абадан дем алуу 🌳','Төрт дубалдын арасында өзүңүздү да, балаңызды да кысылып жаткандай сезип жатасызбы? Баары башаламан болуп кеткиче, «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн жакын жердеги сейил бакты табыңыз. Таза аба — экөөңүздөр үчүн тең эң мыкты даба.','Sõõm värsket õhku 🌳','Kas neli seina tekitavad nii sinus kui ka lapses ahistava tunde? Leia enne olukorra pingestumist „Emadele sobivate kohtade“ kaudu lähedal asuv park. Värske õhk on parim ravim teile mõlemale.'),
('51ad8bab-02f3-44e2-b4ec-e672c59c18fa'::uuid,'Жардамчы колдор! 🧹','Пол сүртүп же чаң аарчып жатканыңызда, ал колуңуздагы чүпүрөктү тартып алууга аракет кылабы? Ал өзүн чоң жардамчыдай сезип баштады! Ага өзүнчө кичинекей чүпүрөк берип, «командаңызга» кошуп алыңыз — бул анын өнүгүүсүнө чоң салым кошот.','Abistavad käed! 🧹','Kui sa põrandat pühid või tolmu võtad, kas ta üritab lappi su käest haarata? Ta hakkab end tundma suure abilisena! Anna talle väike oma lapp ja lase tal oma „meeskonnaga“ liituda – see on suurepärane viis tema arengut toetada.'),
('7797557a-9277-450c-98b3-b0fa58923513'::uuid,'Кечки жуунуудан кийинки уйку! 🛁','Түнкү уйкунун алдында бөбөгүңүздү жуунтуу анын тынч уктоосуна абдан пайдалуу.','Magamaminek pärast õhtust vanni! 🛁','Beebi vannitamine enne ööund võib olla väga kasulik rahulikuks ööuneks.'),
('8152dc55-7f72-41b2-bb12-02cf7745f75a'::uuid,'Аталарды да тартуу керек! 👨‍🍼','«Өнөктөш режими» аркылуу аталар да бөбөктүн өнүгүүсү тууралуу жаңылыктардан кабардар болуп турушат.','Kaasame ka issid! 👨‍🍼','Partnerirežiimi kaudu saavad ka isad olla kursis beebi arenguga.'),
('aa639fbc-fe83-44f4-b9ac-8b3bd199a951'::uuid,'Энергияны сарптай турган убакыт! 🌳','Төрт дубал балаңызды тажатып жатабы? Аны коляскага салып же колунан жетелеп, таза абага чыгыңыз. Жаратылыштын тынчтыгы балаңыздын да, өзүңүздүн да маанайыңызга жакшы таасир этет.','Aeg energiat kulutada! 🌳','Kas neli seina teevad su lapse rahutuks või ärritunuks? Pane ta vankrisse või võta käest kinni ja minge õue värske õhu kätte. Looduse rahu mõjub imeliselt nii lapse tujule kui ka sinu enda heaolule.'),
('d88a96c2-0998-4bcd-a181-952127acf518'::uuid,'Караңгылыкка көнүү 🌙','Бөбөгүңүздүн тезирээк уктап кетишине жардам берүү үчүн бөлмөдөгү ашыкча жарыктарды, өзгөчө планшеттин экрандарын өчүрүңүз. Мелатонин караңгы чөйрөдө эң жакшы иштелип чыгат.','Pimedusega kohanemine 🌙','Et aidata väikesel kiiremini uinuda, lülita toas välja kõik lisavalgused, eriti tahvelarvutite ekraanid. Melatoniin toodab end kõige tõhusamalt pimedas keskkonnas.'),
('54448f6d-1a3b-4d93-a54d-a52f199ed706'::uuid,'Жаздыктан жасалган чеп 🏰','Бүгүн кечинде бөлмөнү кызыктуу оюн аянтчасына айлантыңыз! Дивандын жаздыктарынан кичинекей чеп куруп, ичине кирип ойноңуз. Бир аз башаламандык болушу мүмкүн, бирок анын кубанычтуу күлкүсү буга арзыйт.','Padjakindlus 🏰','Muuda täna õhtul tuba kujutlusvõime mänguväljakuks! Ehita diivanipatjadest väike kindlus ja roni sisse. Võib-olla tekib veidi segadust, kuid rõõmus naer on seda igati väärt.'),
('71cd2e71-d81c-477a-9842-72269b236716'::uuid,'Өз алдынча тамактануу баскычы 🥄','Балаңыз кашыкты кармап, баарын чачып жатабы? «Тамактандыруу таймерин» иштетиңиз. Төгүлгөн тамакка эмес, анын өз алдынчалыкка жана ишенимге ээ болуп жатканына көңүл буруп, сыймыктаныңыз!','Ise söömise etapp 🥄','Kas su laps haarab lusika järele ja teeb suure segaduse? Käivita toitmise taimer. Ära keskendu mahavalgunud toidule, vaid iseseisvusele ja enesekindlusele, mida ta omandab, ning ole uhke!'),
('a40edf39-5245-44c1-a544-58bd483fee61'::uuid,'Эртең мененки маанайсыздык ☁️','Ал баарына ыйлап, эч нерсеге ыраазы болбой жатабы? Бөбөгүңүз өсүү мезгилинде болушу мүмкүн! Күндү жеңил өткөрүүнүн эң жакшы жолу — аны кучактап, мээрим төгүү.','Hommikune virilus ☁️','Kas ta ärkab nutuga kõige peale ja teda on võimatu rahustada? Sinu väike võib olla keset kasvuhüpet! Parim viis päev üle elada on pakkuda palju kaisutusi ja kindlustunnet.'),
('08e4a521-2f7a-4298-b56b-2d48b11d0ee9'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Күндүзгү чарчоо жетиштүү болду! Бүгүн кечинде уктоо алдындагы режимди — баланы уктоого даярдоону жана пижамасын кийгизүүнү — атасына тапшырып, сиз жөн гана четтен байкап туруңуз.','Issi öövahetus 👨‍🍼','Oled päevasest väsimusest tüdinud! Anna täna õhtul une-eelne rutiin – lapse magamaminekuks ettevalmistamine ja pidžaama selgapanek – isale, ja lihtsalt jälgi kõrvalt.'),
('352c5750-18d9-48a8-a40c-2d51006fd988'::uuid,'Сөздөрдү кайталоо 🗣️','Балаңыз сиз айткан ар бир жаңы сөздү тоту куштай кайталап жатабы? Анын сөз байлыгы тездик менен өсүп жатат! Айланасында айткан сөздөрүңүзгө жана эмоцияңызга көңүл буруңуз, анткени ал баарын туурап жатат.','Sõnade kordamine 🗣️','Kas su laps kordab kohe iga uut sõna, mida ütled, nagu väike papagoi? Tema sõnavara laieneb kiiresti! Pööra tähelepanu sõnadele ja emotsioonidele, mida tema ümber väljendad, sest ta jäljendab kõike.'),
('3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa'::uuid,'Жашылчаларды байкатпай кошуу! 🥦','Шорпосундагы сабиздин кичинекей бөлүгүн көрүп, кайра тамактан баш тарттыбы? «Тамактануу планы» аркылуу жашылчаларды пюре кылып, котлеттин ичине катып берүү — энелердин эң эски жана пайдалуу амалы.','Peida köögiviljad toidu sisse! 🥦','Kas ta keeldus jälle söömast, kui märkas supi sees väikest porganditükki? Toitumiskava kaudu köögiviljade püreestamine ja lihapallide sisse peitmine on vanim ja kasulikum emade nipp.'),
('5d05da29-b0e2-435e-9e14-f523b38e966b'::uuid,'Уйкусуз түндөрдү кабыл алуу 😭','Бөбөгүңүз түн ортосунда ойгонуп, уктагысы келбей жатабы? Капаланбоого аракет кылыңыз. Себебин (оору, газ, коркуу) акырын аныктап, ал кайра уктаганга чейин сабырдуулук менен кучактап туруңуз.','Magamata ööde aktsepteerimine 😭','Sinu väike ärkas keset ööd ega taha magada. Püüa mitte ärrituda. Tuvasta õrnalt põhjus (valu, gaasid, hirm) ja kaisuta teda kannatlikult, kuni ta uuesti uinub.'),
('7d1bf85e-e587-4da1-8ee8-b719514d8f71'::uuid,'Кетпей турган тактар! 👗','Кийимдеринин дайыма кир болушу сизди капалантып жатабы? Буга капа болбоңуз. Балаңыз тамак-ашты изилдеп жатат! Силикон эмчектиктерди колдонуңуз жана бул түстүү, башаламан көз ирмемдерден ырахат алыңыз.','Kangekaelsed plekid! 👗','Kas pidevalt määrdunud riided ajavad sind kurvaks? Ära pahanda. Sinu laps avastab toitu! Kasuta silikoonpõllesid ja naudi neid värvilisi, segaseid hetki.'),
('f06a8dcb-51df-4b58-a9ac-01e5154e736a'::uuid,'Уйкунун пайдубалы ⏱️','Жылуу ванна, жай укалоо жана караңгылатылган бөлмө... Уйку тартибин эч качан бузбаңыз, ошондо түндөрүңүз тынч өтөт.','Une vundament ⏱️','Soe vann, õrn massaaž ja hämar tuba... Ära kunagi riku une-eelset rutiini, et ööd oleksid rahulikud.'),
('19aba970-f2bf-4842-9b69-4aed1781aeec'::uuid,'Буттарыма карачы! 👣','Балаңыз бут бармактарын таап, аларды оозуна салып жатат! Бул күлкүлүү учурду байкап, анын өнүгүүсүнөн ырахат алыңыз.','Vaata mu varbaid! 👣','Sinu beebi on avastanud oma varbad ja paneb neid suhu! Jälgi kindlasti seda naljakat hetke ja naudi tema arengut.'),
('f3bd302c-47f2-4428-b12d-4062c2445dfe'::uuid,'Күзгүдөгү досум 👀','Аны күзгүгө алып барыңыз. Чагылышына таң калып, ар кандай бет кубулуштарын жасаганын көрүңүз. Бул анын өзүн таанып-билүүсү үчүн сонун көнүгүү.','Minu sõber peeglis 👀','Vii ta peegli ette. Vaata, kuidas ta imetleb oma peegeldust ja teeb erinevaid nägusid. See on suurepärane tegevus tema eneseavastamiseks.'),
('6b5eb8f2-b9ae-4f72-adf0-630e10588b7d'::uuid,'Эне сүтү: дагы деле маанилүү! 🍼','Кошумча тамак берип жатсаңыз да, тамактандыруу таймерин колдонуп, балаңыздын күнүмдүк сүт муктаждыгын камсыз кылыңыз.','Rinnapiim: endiselt hädavajalik! 🍼','Isegi lisatoidu puhul veendu, et beebi igapäevane piimavajadus oleks kaetud, kasutades toitmise taimerit.'),
('c2924eec-8b24-41b0-b28a-f63497f548c2'::uuid,'Тажрыйбаңыз менен бөлүшүңүз 💬','Ымыркайлар үчүн тамак рецепттерин издеп жатасызбы? Сонун идеялар үчүн биздин «Дени сак рецепттер» бөлүмүнө кириңиз!','Jaga oma kogemusi 💬','Otsid beebitoidu retsepte? Sukeldu meie tervislike retseptide sektsiooni, et saada suurepäraseid ideid!'),
('2d910805-1ce0-44fc-88f6-f3f6dfe16cea'::uuid,'Эмгектеп жүрүү аракети! 🐢','Балаңыз курсагы менен артка жылып жатабы же тизесине турууга аракет кылып жатабы? Бул активдүү өнүгүү көз ирмемдерин «Ымыркай альбомуна» түбөлүккө сактап коюңуз.','Roomamiskatsed edenevad! 🐢','Kas su beebi liigub kõhuli olles tagurpidi või üritab põlvedele tõusta? Jäädvusta need aktiivsed arenguhetked beebialbumisse.'),
('21fef948-0fab-41a2-932d-5efc89cc4b78'::uuid,'Уйкунун пайдубалы ⏱️','Туура уйку тартибин түзүү өтө маанилүү. Түндөрүңүз тынч өтүшү үчүн тартипти эч качан бузбаңыз.','Une vundament ⏱️','Korraliku unerutiini loomine on ülioluline. Ära kunagi riku rutiini, et tagada rahulikud ööd.'),
('29cfcc36-87ce-4b4b-b753-dcd4b0ef2352'::uuid,'200 күнгө чейин бир эле күн калды! 🎂','Эртең силерге 200 күн болот! Бул чоң жана сонун жетишкендикти кантип белгилөө керектиги жөнүндө ойлондуңузбу? Пландаштырууну баштай турган убак келди!','Vaid üks päev 200 päevani! 🎂','Homme oled sa 200 päeva vana! Oled mõelnud, kuidas seda suurt ja imelist verstaposti tähistada? On aeg hakata planeerima!'),
('76b44761-7bef-4f9c-b984-97e78f4d78cb'::uuid,'Баары өз нугунда! ✔️','Кээде өзүңүздү жетишсиз сезишиңиз мүмкүн. Бирок анын таза кийимине, ток курсагына караңыз. Сиз сонун иш жасап жатасыз!','Kõik on kontrolli all! ✔️','Mõnikord võib tunduda, et sa ei tee piisavalt. Aga vaata tema puhtaid riideid, täis kõhtu. Sa teed suurepärast tööd!'),
('01da84b5-ee27-4d08-b8e5-12f1d6a1b6e2'::uuid,'Жолуңузду карап чыгыңыз 📈','Алгачкы күндөрдөгү тынчсызданууларыңызды эстеңизчи? Эми караңыз, сиз кошумча тамак киргизүү боюнча адис болуп калдыңыз! Өзүңүз менен сыймыктаныңыз!','Vaata oma teekond üle 📈','Mäletad oma muresid algusaegadel? Nüüd vaata sind, oled lisatoidu tutvustamisel juba proff! Ole enda üle uhke!'),
('87133947-89a5-414b-a6d4-637285ff301e'::uuid,'200 укмуштуудай күн! 🎉','Ишенесизби? Силер чогуу бул сыйкырдуу сапарда 200 күндү артка таштадыңар! Бул көз ирмемди «Ымыркай фотосессиясында» атайын чаптама менен жаркыратып, Коомчулук менен бөлүшүңүз!','200 imelist päeva! 🎉','Kas suudad seda uskuda? Olete olnud sellel maagilisel teekonnal koos juba 200 päeva! Sära seda hetke erilise kleebisega beebifotoseerias ja jaga seda kogukonnaga!'),
('e7927d9c-8cbd-4c7d-b3cf-e5df983f4169'::uuid,'200 күндү белгилөө! 🥂','Бүгүн кечинде, бала уктагандан кийин, бул чоң командалык жеңишти өнөктөшүңүз менен белгилөөнү унутпаңыз!','Tähistame 200 päeva! 🥂','Täna õhtul, kui beebi magab, ära unusta seda suurt meeskonnavõitu partneriga tähistada!'),
('14f79c92-38f1-4965-a9d0-fbcb8e236840'::uuid,'Шилекей көп агат! 🤤','Анын эмчектиги секунданын ичинде эле суу болуп калабы? Тиш жарып жаткан болушу мүмкүн! Силикон эмчектиктер бул учурда чоң жардамчы болот.','Palju ila! 🤤','Kas tema põll on sekunditega läbimärg? Hammaste tulek võib olla lähedal! Silikoonpõlled võivad olla päästjaks.'),
('173f7149-2567-449f-9693-a462d1148849'::uuid,'Биз бир командабыз! 💖','Оор күндөн кийин өнөктөшүңүз менен бетме-бет отуруп, баарлашыңыз. Бири-бириңизди колдоо жүктү эки эсе жеңилдетет.','Me oleme meeskond! 💖','Pärast rasket päeva istu partneriga näost näkku ja rääkige asjad läbi. Üksteise toetamine poolitab koorma.'),
('1af66eec-0d7d-4dcd-9326-d4155d237a55'::uuid,'Бөтөн адамдардан чочулоо башталдыбы? 🙈','Эгер балаңыз сизди көрбөй калганда же чоочун адамды көргөндө ыйласа, бул өнүгүүнүн кадимки бөлүгү болгон «Ажырашуу тынчсыздануусу» болушу мүмкүн. Кеңеш алуу үчүн Anacan AI менен баарлашыңыз.','Kas võõrastusärevus algab? 🙈','Kui beebi nutab, kui sa oled silmist kadunud või näeb uut nägu, on see tõenäoliselt lahkumisärevus, mis on normaalne osa arengust. Küsi nõu Anacan AI-lt.'),
('23068177-6d18-4649-91f5-5ac9ecb37933'::uuid,'Ыкчам жооптор 🤖','Көңүлүңүздү чөгөргөн нерсе барбы? Форумдарды сааттап карап отурбай, Anacan AI''дан сурап, тез жооп алыңыз.','Kiired vastused 🤖','Kas sul on midagi südamel? Selle asemel, et veeta tunde foorumites, saa kiireid vastuseid Anacan AI-lt küsides.'),
('52b2efdc-0a49-4bfa-8a7e-21a3342254cb'::uuid,'Активдүү болуу! 🤸‍♂️','Курсак менен жаткан маалда алдыга сойлоого аракет кылып жатабы? Булчуңдары күн сайын чыңдалууда! Сүйүктүү оюнчугун жетпей турган жерге коюп, аны шыктандырыңыз.','Aktiivsus kasvab! 🤸‍♂️','Kas ta üritab kõhuli olles edasi roomata? Tema lihased muutuvad iga päevaga tugevamaks! Julgusta teda, asetades lemmikmänguasja käeulatusest veidi kaugemale.'),
('97716c97-1bb3-4784-acfc-a5f0354d1864'::uuid,'Музыканын күчү 🎶','Кечки маанайсыздыкты жана түшүнүксүз ыйлоону жай темптеги классикалык музыка менен басууга аракет кылыңыз.','Muusika vägi 🎶','Püüa õhtust rahutust ja seletamatut nuttu rahustada aeglase tempoga klassikalise muusikaga.'),
('9c5c6958-af17-4420-aa80-95cd295c8995'::uuid,'Колуңуз бош учурлардан ырахат алыңыз! 👐','Балаңыз курсак менен жатканда бир колу менен оюнчукка жетип, экинчиси менен таянып жатабы? Анын булчуңдарын башкаруусу сонун өнүгүп жатат!','Naudi vabu käsi! 👐','Kas su beebi sirutab kõhuli olles ühe käe mänguasja järele ja toetab end teisega? Tema lihaskontroll areneb kaunilt!'),
('acd2495b-eae5-4005-8f31-3fdfdc4738aa'::uuid,'Ата менен ойноо убактысы 👨‍👧','Бүгүн бала багуу милдетин бир азга өнөктөшүңүзгө өткөрүп бериңиз. Ал ойноп жатканда, сиз жөн гана бутуңузду сунуп эс алыңыз.','Issi mänguaeg 👨‍👧','Täna anna lapsevanema kohustused partnerile lühikeseks ajaks üle. Lase tal mängida, samal ajal kui sina lihtsalt paned jalad seinale ja puhkad.'),
('094a764e-f3f1-4dd1-8a87-04126b16323f'::uuid,'Өзүңүзгө кам көрүүнү унутпаңыз! 🍲','Кичинекейиңиз пюресин жеп бүттү, бирок сизчи? Энергияңызды калыбына келтирүү үчүн сизге жакшы тамактануу керек. Бүгүн өзүңүзгө даамдуу тамак тартуулаңыз.','Ära unusta enda eest hoolitseda! 🍲','Sinu väike lõpetas oma püree, aga kuidas on lood sinuga? Vajad energiat taastavat head toitu. Hellita end täna ühe toitva einega.'),
('734bd8a8-49ec-4c9f-bb8c-17a8d1fc50b6'::uuid,'Мен сени тааныйм! 👀','Кичинекейиңиз коноктор келгенде сизге жабышып, аларды шектүү карап жатабы? Ажырашуу тынчсыздануусу башталган болушу мүмкүн. Ал өзүн эң коопсуз апасынын жанында сезет, андыктан бул этапты түшүнүү менен кабыл алыңыз.','Ma tunnen sind! 👀','Kas su väike laps hoiab sinust kinni ja vaatab külalisi umbusklikult, kui nad külla tulevad? Lahkumisärevus võib endast märku anda. Ta tunneb end emaga kõige turvalisemalt, seega lähene sellele faasile mõistvalt.'),
('740c028d-4797-4507-a894-816747e5301d'::uuid,'Сиздин сыйкырдуу окуяңыз 🪄','Бүгүн кечинде «Акылдуу жомоктор» куралына таттуу тема берели: «Асмандан түшкөн эң таттуу жылдыздын жомогу». Бөлмөнү ушул жомоктун үнү гана толтурсун.','Sinu enda võlulugu 🪄','Täna õhtul anname „Nutikate lugude“ tööriistale magusa teema: „Lugu kõige magusamast tähest, mis kukkus taevast alla.“ Lase vaid selle jutu helil tuba täita.'),
('6496f6e2-60a8-4932-a5d1-b8cb0c9682cf'::uuid,'Күзгүдөгү дос 👀','Бөбөгүңүздү күзгүгө алып барыңыз. Анын өз чагылышын таң калуу менен карап, жылмайганын көрүү – абдан жагымдуу жана тынчтандыруучу көнүгүү.','Sõber peeglis 👀','Vii oma beebi peegli ette. See, kuidas ta imestunult oma peegeldust vaatab ja sellele naeratab, on imearmas ja rahustav tegevus.'),
('06cfdff1-da31-4945-b562-a0c104f43d15'::uuid,'Мен сени угуп жатам! 🗣️','Ал кунт коюп угуп, «ма-ма» же «ба-ба» сыяктуу муундар менен сизди тууроого аракет кылып жатабы? Демек, ал сиз менен сүйлөшүп жатат! Ага жылмайып, дем берип жооп кайтарыңыз.','Ma kuulen sind! 🗣️','Kas ta kuulab tähelepanelikult ja püüab sinu häälikuid matkida, öeldes ''ma-ma'' või ''ba-ba''? Ta räägib sinuga! Vasta talle rohke naeratuse ja julgustusega.'),
('83caf542-3e86-4833-b9bd-0befb15b04d7'::uuid,'Сыртка чыгууга убакыт келди! 🌳','Аны коляскага салып, 20 мүнөт таза абада сейилдеп келиңиз. Бул экөөңүздөргө тең абдан пайдалуу болот.','Aeg õue minna! 🌳','Pane ta vankrisse ja minge 20 minutiks värske õhu kätte. See teeb teile mõlemale ainult head.'),
('fca627d6-9c72-4d82-999a-3b13347100cd'::uuid,'Түнкү баатыр 🦸‍♂️','Түнкүсүн ойгонуудан чарчадыңызбы? Атасын ойготуудан тартынбаңыз. Үй-бүлө болуу – бул милдеттерди тең бөлүшүү дегенди билдирет.','Öine kangelane 🦸‍♂️','Oled öistest ärkamistest väsinud? Ära kõhkle isa üles ajamast. Meeskonnana tegutsemine tähendab koormuse võrdset jagamist.'),
('4335b974-a43c-4ba3-b369-2006056301ed'::uuid,'Жөлөнбөй отуруу 🪑','Ал эч кандай колдоосуз эле кыска убакытка тик отура алабы? Бул булчуңдардын өнүгүүсүнө кубануу менен байкоо салыңыз, бирок ар дайым анын коопсуздугун камсыз кылыңыз.','Istudes ilma toeta 🪑','Kas ta istub juba lühikest aega ilma toeta? Jälgi tähelepanelikult seda põnevat lihaste arengut, tagades alati tema ohutuse.'),
('5bc047d7-1539-47af-a21f-c1df4aa3461d'::uuid,'Түшкү тамакты шашпай ичиңиз! 🥑','Өзүңүзгө даамдуу салат жасап, 15 мүнөт болсо да өзүңүзгө убакыт бөлүңүз.','Ära kiirusta lõunaga! 🥑','Valmista endale üks maitsev salat ja võta 15 minutit vaid iseendale.'),
('8d02cce6-aec5-439c-aadf-52670f1abd08'::uuid,'Терең уйкуга даярдык 🛀','Жылуу ванна, жеңил массаж жана караңгылатылган бөлмө... Уйку режимин сактоо – түнкүсүн тынч уктоонун сыры.','Valmistumine sügavaks uneks 🛀','Soe vann, õrn massaaž ja hämar tuba... Unerutiini järgimine on katkematu ööune saladus.'),
('a649650d-baa3-4dab-9158-780252d27ef4'::uuid,'Күндүн кооз аягы. ✨','Сиз абдан күчтүү энесиз! Маанай күндөлүгүнө эмне үчүн сыймыктанарыңызды жазыңыз, «Ак ызы-чуу» (White Noise) менен тынчтанып, жакшы эс алыңыз.','Kauni päeva lõpp. ✨','Sa oled nii tugev ema! Pane meeleolupäevikusse kirja, mille üle sa enda puhul uhkust tunned, leia rahu valge müra abil ja naudi kosutavat und.'),
('f5e18de7-aba2-4bda-84e9-b3a568ce950b'::uuid,'Жолуңузду карап чыгыңыз 📈','Ал алгачкы күндөрдө баары канчалык жаңы сезилгенин эстеңизчи? Эми өзүңүздүн кандай тажрыйбалуу эне болгонуңузга караңыз! Өзүңүз менен сыймыктаныңыз!','Vaata oma teekond üle 📈','Kas mäletad, kui uus kõik alguses tundus? Nüüd vaata, milliseks asjatundlikuks emaks oled saanud! Ole enda üle väga uhke!'),
('4650c8e1-3011-45f0-9997-0c6decd79a65'::uuid,'Сиздин тизмеңиз — чыныгы жардамчы 🛒','Күнүмдүк түйшүктө бир нерсени унутуп калдыңызбы? Кабатыр болбоңуз; үйгө керектүү нерселердин баарын «Соода тизмесине» кошуп коюңуз.','Sinu nimekiri on elupäästja 🛒','Unustasid igapäevatoimetuste keskel midagi? Ära muretse; lisa kõik vajalik lihtsalt oma ostunimekirja.'),
('8c057f2d-32f2-4561-9ca5-5bc651edddcc'::uuid,'Сиңирүү процессин көзөмөлдөө. 🧷','Кошумча тамактар заңдын консистенциясын өзгөртөт. Бөбөгүңүздүн жаңы тамакка болгон реакциясын талдоо үчүн ар бир жалаяк алмаштырууну Anacan тиркемесине жазып туруңуз.','Seedimise jälgimine. 🧷','Tahke toit muudab väljaheite konsistentsi. Märgi iga mähkmevahetus Anacani, et analüüsida beebi reaktsiooni uutele toitudele.'),
('9fc39323-52a1-4045-aa65-bf5c16fac78f'::uuid,'Ачкабы же чарчадыбы? 😭','Бөбөгүңүз эч себепсиз эле ыйлап, үнү башкача чыгып жатабы? Дүрбөлөңгө түшүүнүн кажети жок. Көйгөйдүн себебин дароо түшүнүү үчүн «Ыйды талдоо» функциясын колдонуңуз.','Nälg või väsimus? 😭','Kas beebi nutab ilma nähtava põhjuseta ja nutt kõlab teisiti? Pole vaja paanitseda. Kasuta kohe nutianalüüsi funktsiooni, et probleemi põhjus välja selgitada.'),
('05f5ce2b-27c1-4d94-b681-3d4e9ce809b6'::uuid,'Үйдөгү коопсуздук боюнча кеңештер! 🛡','Ал кыймылдуу боло баштаганда, коркунучтар да көбөйөт. Балдар үчүн коопсуздук кулпуларын жана бурч коргогучтарды табуу үчүн биздин «Сунушталган өнүмдөр» тизмебизди карап чыгыңыз.','Koduohutuse nipid! 🛡','Mida liikuvamaks laps muutub, seda rohkem tekib ka ohte. Vaata meie soovitatud toodete nimekirjast turvalukke ja nurgakaitsmeid.'),
('a0d08200-8263-43d9-90a3-313dda8dadc9'::uuid,'Кол менен жей турган тамакка даярбы? 🥦','Бөбөгүңүз тамакты өзү кармап жегиси келип жатабы? Коопсуз жана кызыктуу варианттар үчүн «Кошумча тамакка өтүүчү бөбөктөр үчүн рецепттер» бөлүмүн караңыз!','Kas oled valmis näputoiduks? 🥦','Kas beebi tahab juba ise oma toitu hoida? Vaata ''Retseptid beebidele tahkega alustamiseks'', kust leiad ohutuid ja lõbusaid valikuid!'),
('ef507e65-7f14-47a2-8b48-8ce6e3e1fc96'::uuid,'Эмгектеп жүрүү көнүгүүсү! 🐢','Бөбөгүңүз курсагы менен артка жылып же тизесине турууга аракет кылып жатабы? Эмгектеп кетүүсүнө көмөктөшүүчү көнүгүүлөр үчүн Anacan AI''дан сураңыз.','Roomamisharjutused! 🐢','Kas su väike võsuke liigub kõhuli tagurpidi või üritab põlvedele tõusta? Küsi Anacan AI-lt kasulikke harjutusi, mis toetavad tema roomamise teekonda.'),
('52134c06-b272-4f5f-93b6-cf014fc0e867'::uuid,'Эне сүтү дагы деле маанилүү! 🍼','Кошумча тамак берип баштасаңыз да, эмизүү таймерин колдонуп, анын күнүмдүк сүт муктаждыгын камсыз кылыңыз.','Rinnapiim on endiselt hädavajalik! 🍼','Isegi pärast tahke toiduga alustamist jälgi toitmise taimeri abil, et ta saaks kätte oma igapäevase piimavajaduse.'),
('62cb9c93-e0de-4d15-8d33-e81c1723d1db'::uuid,'Энелер үчүн энергия булагы! 🥗','Сиздин туура тамактанууңуз да абдан маанилүү! Энергияңызды арттыра турган витаминдүү салат же смузи даярдоо үчүн биздин дени сак рецепттерибизди тандаңыз.','Energialaeng emmedele! 🥗','Sinu tervislik toitumine on samuti ülioluline! Vali meie tervislike retseptide hulgast vitamiinidest pakatav salat või smuuti, mis annab sulle energiat juurde.'),
('f25f7637-e945-4232-a1c1-f7594c81a0b3'::uuid,'Тынчтандыруучу үндөр 📖','Бүгүн кечинде бөбөгүңүзгө өз үнүңүз менен кыскача жомок окуп бериңиз. Эненин үнү – бала үчүн эң жагымдуу музыка.','Rahustavad helid 📖','Loe täna õhtul oma väikesele ette üks lühike unejutt oma häälega. Ema hääl on lapse lemmikmuusika.'),
('2a37fc3a-8b98-420a-99ba-c491a8c0f435'::uuid,'Уйкунун белгилери 🥱','Ал көзүн ушалап, эсинегенче күтпөңүз. Көзү бир чекитке кадалып же тунарып калганда эле, дароо уйку режимин баштаңыз.','Unemärgid 🥱','Ära oota, kuni ta silmi hõõrub ja haigutab. Niipea kui tema pilk muutub fikseerituks või klaasjaks, alusta kohe unerežiimiga.'),
('74e14338-c8e1-4b5c-b426-24332f30b919'::uuid,'Апа үчүн 10 мүнөт ☕','Бөбөгүңүз уктаганда, дароо үй жумуштарына чуркабаңыз. Диванга отуруп, кофеңизден ичип, 10 мүнөт дубалды карап, терең дем алыңыз.','10 minutit emale ☕','Kui beebi lõpuks magab, ära torma kohe kodutöid tegema. Istu diivanile, naudi kohvi ja hinga 10 minutit lihtsalt seina vaadates.'),
('bb4d4aaf-f143-4aa9-b4e0-7b7a4fc4ea1f'::uuid,'Эртең мененки маанайсыздык ☁️','Бөбөгүңүз бүгүн эртең менен тынчсызданып жатабы? Бул тиш жаруу же өсүү мезгили болушу мүмкүн! Аны тынчтандыруу үчүн көбүрөөк кучактап, мээрим төгүңүз.','Virilad hommikud ☁️','Kas su väike võsuke on täna hommikul viril? See võib olla hammaste tulek või kasvuhüpe! Paku talle lihtsalt rohkem kaisutusi ja lohutust, et ta end turvaliselt tunneks.'),
('6ac03f7c-34a8-46f5-96a4-c1aa521476a5'::uuid,'Буюмдардын туруктуулугу боюнча оюн! 🧸','Оюнчукту жууркандын астына катып, бөбөгүңүзгө таптырыңыз. Бул кызыктуу интеллектуалдык оюн учурунда анын кубанычын сүрөткө тартып алыңыз.','Objekti püsivuse mäng! 🧸','Peida mänguasi teki alla ja lase lapsel see üles leida. Seda lõbusat intellektuaalset mängu mängides jäädvusta tema siirast rõõmu beebifotodega.'),
('746b1115-b7ff-4fd7-b04a-46935d1a6f43'::uuid,'Балдардын буюмдары чачылып жатабы? 🌪️','Үйүңүздө балдардын буюмдары чачылып жатабы? Мейли, чачыла берсин! Үйдүн иретсиздиги жаман эне экениңизди билдирбейт; бул жөн гана балаңыз сиз үчүн биринчи орунда экенин көрсөтөт.','Beebiasjad igal pool? 🌪️','Kas beebiasjad on üle kodu laiali? Las nad olla! Segamini kodu ei tähenda halba ema; see näitab lihtsalt, et su beebi on sinu prioriteet number üks.'),
('bc99d2a9-e4a6-4af7-937f-bb0a7a91d292'::uuid,'Ыңгайлуулук үчүн үн терапиясы 🎶','Эгер балаңыз жаңы көндүмдөрдү үйрөнгөнүнө толкунданып, бүгүн түнү уктабай жатса, биздин «Ак ызы-чуу» (White Noise) функциясынан «жатындын добуштарын» коюп бериңиз.','Heliteraapia mugavuseks 🎶','Kui beebi ei saa täna uute oskuste põnevuse tõttu magada, mängi talle meie valge müra funktsioonist ''emakahelisid''.'),
('c5b12eaa-4012-417b-bf89-d5bd9d26aee9'::uuid,'Тамактануу тартиби өзгөрүшү мүмкүн. 🍼','Балаңыздын тамактануусун көзөмөлдөө үчүн Anacan таймерин иштетиңиз жана ал күнүмдүк нормасын алып жатканын текшериңиз.','Söömisrutiinid võivad muutuda. 🍼','Beebi toitmise jälgimiseks lülita sisse Anacani taimer ja kontrolli, kas ta saab oma päevase toidukoguse kätte.'),
('24927359-7877-4f99-9dea-0460583a0880'::uuid,'Күнүмдүк жалаяк алмаштырууну белгилеп туралы. 🧷','Балаңыз жетиштүү азыктанып жатканын билүү үчүн, ар бир жалаяк алмаштырууну Anacan тиркемесине каттап туруңуз.','Jälgime igapäevaseid mähkmevahetusi. 🧷','Veendumaks, et beebi saab piisavalt toitaineid, jätka iga mähkmevahetuse logimist Anacanis.'),
('30560050-23fa-4905-9bfc-f3082838579d'::uuid,'Уйкуга кетүү үчүн музыкалык өтүү 🛀','Кечки режим кыйынчылык жаратып жатабы? Балаңыз жылуу ваннага түшүп жатканда фондо жагымдуу музыка коюп көрүңүз. Суунун жана обондун тынчтандыруучу айкалышы эң тентек баланы да жумшарта алат.','Muusikaline üleminek unne 🛀','Kas õhtune rutiin valmistab raskusi? Proovi taustaks mängida rahustavat muusikat, samal ajal kui laps naudib sooja vanni. Vee ja meloodia rahustav kooskõla võib pehmendada ka kõige jonnakamat last.'),
('a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf'::uuid,'Тиш жуудагы күрөш 🦷','Тишин жуугусу келбей жатабы? Муну милдет эмес, оюнга айлантыңыз! Алгач ага өзүңүздүн тишиңизди жуудуртуңуз, андан кийин кезегиңизди алыңыз.','Hammaste pesemise lahing 🦷','Keeldub hammaste pesemisest? Muuda see mänguks, mitte kohustuseks! Lase tal kõigepealt oma hambaid pesta, siis on sinu kord.'),
('c0129df7-df96-4659-882d-c3fd4d3c25e7'::uuid,'Тандап тамактануу менен күрөш 🥣','Кичинекейиңиз эки тиштеп эле тоюп калганын айтып, чуркап кетип жатабы? Мажбурлабаңыз. Тамак менен дени сак мамиле түзүү, тарелкасын тазалатуудан алда канча маанилүү. Андан көрө азыраак порция менен тез-тез тамактандырып көрүңүз.','Valiva sööja lahingud 🥣','Sinu väike võsuke võtab kaks ampsu, teatab, et on kõht täis ja jookseb minema? Ära sunni teda. Tervisliku toitumissuhte kujundamine on palju olulisem kui taldriku tühjaks söömine. Proovi pakkuda väiksemaid ja sagedasemaid portsjoneid.'),
('2f4c11d8-739d-4bb0-9942-69a623d77f66'::uuid,'Гормоналдык бороон 🩸','Таттууга болгон капыстан каалоо жана кыжырдануубу? «Этек кир календарыңызды» текшериңиз. Бул жөн гана ПМС болушу мүмкүн! Өзүңүздү күнөөлөбөңүз. «Дени сак рецепттер» бөлүмүнөн магнийге бай курма кошулган тамактар менен организмиңизди колдоңуз.','Hormoonide torm 🩸','Äkiline magusaisu ja ärrituvus? Kontrolli oma tsüklikalendrit. See võib olla PMS! Ära ole enda vastu karm. Toeta oma keha magneesiumirikaste datlisuupistetega meie tervislike retseptide sektsioonist.'),
('b69b6089-ef94-4c8e-8537-ca4464897520'::uuid,'Эртең мененки ыйлоолор 🛑','Ойгонгондо эле баарына ыйлап жатабы? Эмоционалдык жактан чарчаган балаңызды кантип тынчтандырууну Anacan AI экспертибизден дароо сурап билиңиз.','Hommikused jonnihoogud 🛑','Kas laps ärkab karjudes ja nutab kõige peale? Õpi, kuidas emotsionaalses ülekoormuses last rahulikult lohutada, vesteldes kohe meie Anacan AI eksperdiga.'),
('c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4'::uuid,'Жомокту аягына чейин айтып бериңиз 📖','Бүгүн кечинде жомок окуп жатканда, сүйлөмдүн ортосунда токтоп, балаңызга уланттырып көрүңүз! Бул укмуштуудай тил өнүктүрүү көндүмүн колдоо үчүн Anacan AI''дан диалог боюнча көбүрөөк кеңеш сураңыз.','Lase tal lugu lõpuni kuulata 📖','Täna õhtul juttu lugedes proovi lause keskel peatuda ja lase lapsel see lõpetada! Küsi Anacan AI-lt veel dialooginõuandeid, et toetada seda imelist keelelist arengut.'),
('0b9c3636-088f-48ec-88e8-94ea05f16477'::uuid,'Кир болууга уруксат 🏖️','Балаңыз ылай же суу менен ойногусу келеби? Коё бериңиз, булганып алсын! Мындай сезгичтикти өнүктүрүүчү оюндар үчүн тазалоого оңой болгон буюмдарды «Сунушталган товарлар» бөлүмүнөн табыңыз.','Luba endal olla lohakas 🏖️','Kas laps tahab mudaga või veega mängida? Las ta määrdub! Leia soovitatud toodetest kergesti puhastatavaid tarvikuid nende sensoorsete arengutegevuste jaoks.'),
('28f1c509-c643-44be-b37c-9bbbdb368b42'::uuid,'Күнүмдүк тартибиңизди талдоо ⏱️','Уктоо убактысы бир саатка созулуп жатабы? Уйку графигиңизди текшериңиз. Балким, күндүзгү уйкуну кыскартып, түнкү уйкуну эртелетүү керек болуп жаткандыр.','Sinu rutiini analüüs ⏱️','Kas magamaminek võtab tund aega? Kontrolli uneaegu. Võib-olla on aeg päevaund lühendada ja magamaminekut varasemaks nihutada.'),
('e4b4940d-8946-4ebd-8a09-0e41f12848e2'::uuid,'Бирге тазалоо 🧹','Үйдү жыйноо керекпи? Полду сүртүп жатканда, ал да чүпүрөк менен сүртүп, сизге жардам берсин. Тазалыкты кантип чогуу кызыктуу оюнга айландырууну Блогдордон окуп алыңыз.','Koos koristamine 🧹','Kas pead kodu koristama? Kui tuba koristad, lase tal lapiga aidata. Loe blogist, kuidas koristamisest koos lõbus mäng teha.'),
('08a08f0f-d89f-412b-a0e0-06835ec16be6'::uuid,'Түнкү ый 🤖','Балаңыз түн ортосунда кыйкырып ойгонуп, сизди тааныбай жатабы? Бул түнкү коркунуч (night terror) болушу мүмкүн. Аны кантип туура башкарууну жана ойготпоо сырларын Anacan AI''дан дароо сураңыз.','Kesköine nutt 🤖','Kas laps ärkab keset ööd karjudes ega tunne sind ära? See võib olla öine hirmuhoog. Küsi kohe Anacan AI-lt nõu, kuidas õigesti käituda ja kuidas teda mitte täielikult üles äratada.'),
('0b568eaa-4297-4b84-983b-14d42c18fb06'::uuid,'Түгөнбөгөн ''Эмне үчүн?'' суроосу 🤔','Алар дүйнөнү түшүнүп, баарын билгиси келет. Anacan AI менен чарчабай, алардын чексиз суроолоруна кантип сабырдуулук менен жооп берүүнү үйрөнүңүз. Сиздин сабырдуулугуңуз — алардын келечеги.','Lõputu ''Miks?'' 🤔','Ta tahab maailma mõista ja kõigest aru saada. Õpi Anacan AI abil, kuidas kannatlikult vastata tema lõpututele küsimustele ilma väsimata. Sinu kannatlikkus on tema tulevik.'),
('e029b1ab-4432-4819-9a9e-c44e5506a20c'::uuid,'Ысык кофенин ырахаты ☕','Бөлмө чачыкпы? Мейли, чачыла берсин. Өзүңүзгө 10 мүнөт бөлүп, кофеңиз муздай электе ичип алыңыз. Сиз идеалдуу болууга милдеттүү эмессиз, апаке.','Kuuma kohvi luksus ☕','Kas tuba on sassis? Las olla. Võta 10 minutit iseendale ja naudi lõpuks seda kohvi, kuni see on veel kuum. Sa ei pea olema täiuslik, emme.'),
('7d7930a8-9ab0-45ba-bbf4-3a10238d3d72'::uuid,'Байкатпай шоколад жеш 🍫','Алар карабай калганда ашканага кирип, таттуу жеп алдыңызбы? Өзүңүздү күнөөлөбөңүз! Апа кишинин күнүмдүк түйшүктү көтөрүп кетүүсү үчүн кандагы кантты бир аз көтөрүп алууга толук укугу бар.','Šokolaadi salaja söömine 🍫','Hiilisid kööki, et kiirelt midagi magusat süüa, kui ta ei näinud? Ära tunne süüd! Emal on täielik õigus väikesele veresuhkru tõusule, et päeva kaos üle elada.'),
('946cf6ed-b93e-4326-a1b8-4af737be38ff'::uuid,'Атанын кезектеги ролу 🎭','Сиздин «тамагыңды жеп бүт» деген өтүнүчүңүз иштебей калдыбы? Топту атасына өткөрүп бериңиз. Ал кашыкты учакка айландырганда, баланын өжөрлүгү сыйкырдуу түрдө жоголот. Эс алыңыз да, бул сыйкырды карап отуруңуз.','Issi kord särada 🎭','Sinu palve ''söö toit lõpuni'' enam ei toimi? Anna teatepulk üle isale. Kui tema muudab lusika lendavaks lennukiks, kaob jonnakus imeväel. Lõõgastu ja naudi seda maagiat.'),
('c17a59df-f595-4941-acce-8426080226bf'::uuid,'Туура эмес кашыктан улам ыйлоо 🥄','Сары кашыктын ордуна жашыл кашыкты колдонгонуңуз үчүн эле башаламандык чыктыбы? Терең дем алыңыз. Логика издебеңиз; ал жөн гана өз дүйнөсүн башкаруу жөндөмүн сынап жатат. Жөн гана кашыкты алмаштырып, жылмайып коюңуз.','Vale lusika draama 🥄','Kas tekkis kaos, sest kasutasid toitmiseks rohelist lusikat kollase asemel? Hinga sügavalt sisse. Ära otsi loogikat; ta lihtsalt katsetab oma võimet maailma kontrollida. Vaheta lihtsalt lusikas ja naerata.'),
('202cf19c-e94a-473d-b9ba-56a3c22509c2'::uuid,'Жардам берүү үчүн бул жердемин 🧽','Балаңыз колуңуздагы чүпүрөктү жулуп жатабы? Ал чоң адамдай сезгиси келет! Ага кичинекей, нымдуу чүпүрөк бериңиз. Тазалагандан көрө чачышы мүмкүн, бирок анын өзүнө болгон ишеними абдан өсөт.','Olen siin, et aidata 🧽','Kas laps napsab tolmulapi su käest? Ta tahab end täiskasvanuna tunda! Anna talle väike niiske lapp. Võib-olla teeb ta rohkem segadust kui puhastab, aga tema enesehinnang saab suurepärase tõuke.'),
('4f32f07a-4c87-40d2-83db-3d4785cda04f'::uuid,'Үйдүн акустикасы 🤫','Акыры уктады. Эми үйдөгү эң кичинекей шыбыр да сизди жинди кыла тургандай сезилет. Дароо «Үн өлчөгүчтү» иштетиңиз, терезелерди жабыңыз жана бул баалуу тынчтыктан ырахат алыңыз.','Kodu akustika 🤫','Ta jäi lõpuks päevauinakule. Nüüd tundub iga väiksemgi kriuksumine majas hulluksajavana. Lülita kohe sisse helimõõtja, sulge aknad ja naudi seda väärtuslikku vaikust.'),
('f750ae50-4664-4363-8c07-389c3fa0e9cb'::uuid,'Бут кийим кийүүдөгү күрөш 👟','Оң бут кийимин сол бутуна кийип алып, чечпей жатабы? Мейли, кие берсин. Азыркы учурда эстетика же тууралык анын эркиндик сезиминен маанилүү эмес.','Kingade jalga panemise lahing 👟','Ta pani parema kinga vasakusse jalga ja keeldub kategooriliselt seda ära võtmast? Las olla. Esteetika või korrektsus pole praegu nii olulised kui tema vabadusetunne.'),
('bcbba6df-cc6d-45d3-b424-d121d2ee2ecb'::uuid,'Караңгылык менен достошуу 🌙','Бөлмөдөгү жарыкты толугу менен өчүрүңүз. Балаңыздын жанына жатып, күндүн окуяларын өтө акырын шыбырап айтып бериңиз. Шыбыроо — мээни уйкуга даярдоонун эң табигый ыкмасы.','Pimedusega leppimine 🌙','Lülita toas tuled täielikult välja. Heida lapse kõrvale ja jutusta päeva sündmused väga vaikse sosinaga. Sosistamine on kõige loomulikum meetod aju uneks ettevalmistamiseks.'),
('db4f7065-c5e8-4316-a750-ff341f726db5'::uuid,'Менин кичинекей сүрөтчүм 🎨','Дубалга же кагазга карандаш менен тегерек чийип жатабы? Бул алардын ири моторикасынын чоң секириги!','Minu väike kunstnik 🎨','Joonistab pliiatsiga seinale või paberile ringe? See on suur hüpe lapse peenmotoorikas!'),
('eacddbb3-0cac-4a07-a3b8-0e2751f215e2'::uuid,'Бала бакча издей баштадыңызбы? 🏫','3 жаштагы балаңызды бала бакчага берүү оюңузду тынчсыздандырып жатабы? Эгерде бул тандоону жалгыз жасоодон чарчасаңыз, Anacan коомчулугуна кошулуп, башка энелердин тажрыйбасы жана сунуштары менен таанышыңыз.','Alustad lasteaiakoha otsinguid? 🏫','Kas mõte 3-aastase lapse lasteaeda panemisest ei anna sulle rahu? Kui oled väsinud üksi valikute kaalumisest, liitu Anacani kogukonnaga ja ammuta teiste emade kogemusi ning soovitusi.'),
('37d0e7fb-1a1f-4126-b2cd-6303007be080'::uuid,'Элестеткен чай ичүү кечеси ☕','Сизге бош чөйчөктү сунуп, чай ичүүнү суранып жатабы? Символикалык оюн – бул өнүгүүнүн чыныгы шедеври. Ошол элестетилген, бөлмө температурасындагы чайды чөйчөктөн чоң ырахат менен ичип коюңуз.','Kujuteldav teepidu ☕','Ulatab sulle tühja tassi ja palub teed juua? Sümboolne mäng on arengu meistriteos. Joo seda kujuteldavat toasooja teed tassist suure naudinguga.'),
('aaf79d19-89d8-4b33-8891-ceb716e86559'::uuid,'Такка толгон кийимдер 🎨','Кийими тамак жана боёк болуп кеттиби? Балдар таптаза болуп чоңоюшу керек эмес; алар изилдөө жүргүзүп, булганышы керек! Силикон эмчектен (слюнявчик) колдонуңуз, калганын кир жуугуч машина чечет.','Plekilised riided 🎨','Kas lapse riided on toidust ja värvist koos? Lapsed ei peagi kasvama plekitult; nad peavadki avastades määrduma! Kasuta silikoonpõllesid ja lase pesumasinal ülejäänu eest hoolitseda.'),
('d6cb9a79-b32c-4069-9d3c-ac4297c600b6'::uuid,'Сиздин 15 мүнөттүк эс алууңуз 🛀','Кээде ваннага кирип, эшикти бекитип, телефон карап отуруп каласызбы? Ооба, бул энелердин эң популярдуу эс алуу ыкмасы. Эч кимге отчет бербей, ошол тынчтыктан ырахат алыңыз.','Sinu 15-minutiline põgenemine 🛀','Kas leiad end vahel vannitoast, uks lukus, lihtsalt telefonis kerimas? Jah, see on emade kõige populaarsem põgenemis- ja lõõgastusviis. Naudi seda vaikust, olemata kellelegi aruandekohustuslik.'),
('0db2d13e-0a0c-45f3-a6f3-c4bf73384a78'::uuid,' ''Өппө!'' баскычы 🛑','Туугандары өпкүсү келгенде бурулуп, түртүп жатабы? Алардын дене чек арасына кийлигишпеңиз! Макулдугусуз тийишүүгө каршы туруу алардын келечектеги ден соолугу үчүн өтө маанилүү.','''Ei taha musi!'' faas 🛑','Kas laps pöörab end ära ja tõrjub, kui sugulane teda suudelda tahab? Ära sekku lapse kehalistesse piiridesse! Nõusolekuta puudutuste vastu protestimine on tema tervisliku tuleviku jaoks ülioluline.'),
('aaaf42f2-3e96-489f-b1d3-e331bf487627'::uuid,'Түнкү коркунучтардын чындыгы 😭','Түн ортосунда көзү жумулуу бойдон ыйлап ойгонуп, эч кимди укпай жатабы? Бул түнкү коркунуч (night terror). Аларды силкип же ойготууга аракет кылбаңыз. Жөн гана жанында болуп, сооротуп, колдоо көрсөтүңүз.','Öiste hirmuhoogude reaalsus 😭','Ärkab keset ööd nuttes, silmad kinni, ega tundu kedagi kuulvat? See on öine hirmuhoog. Ära raputa teda ega püüa äratada. Ole lihtsalt tema kõrval, pakkudes lohutust ja turvatunnet.'),
('be944652-2efc-45de-a928-8d34a23e4645'::uuid,'Жаратылыштагы детокс – зарылчылык 🌳','Бүгүн үйдөгү башаламандыкка чыдай албай жатасызбы? Биздин «Аба ырайы жана кийим» куралын тез текшерип, баланы ылайыктуу кийиндирип, түз эле жакынкы сейил бакка жөнөңүз. Таза аба – бала үчүн эң мыкты тынчтандыруучу каражат.','Looduslik detox on hädavajalik 🌳','Kas kodune kaos on täna väljakannatamatu? Kontrolli kiirelt meie ilma ja riietuse tööriista, pane kõigile sobivad riided selga ja suundu otse lähimasse parki. Värske õhk on lapse parim rahusti.'),
('09900d01-e715-436d-95eb-cb7b3165dfb1'::uuid,'Жаңы сөздөрдү ойлоп табуу 🗣️','Суунун ордуна «чу» же чоңдун ордуна «бужук» деп жатабы? Бул абдан таттуу угулат, күлбөө кыйын! Бирок ар дайым сөздүн туура айтылышын акырын кайталап туруңуз, ошондо баланын мээси аны туура кабыл алат.','Uute sõnade väljamõtlemine 🗣️','Ütleb vee asemel "tšuu" või suure asemel "buudžuk"? See kõlab nii armsalt, et raske on mitte naerda! Kuid korda iga kord õrnalt sõna õiget versiooni, et lapse aju saaks selle õigesti salvestada.'),
('5366cee2-8491-4a45-8d5c-88d78aa6eee0'::uuid,'Экинчи айга кош келиңиз!','Балаңыздын өнүгүүсүн колдоо үчүн, күн бою аны менен сүйлөшүп туруңуз.','Tere tulemast teise kuusse!','Lapse arengu toetamiseks räägi temaga terve päeva jooksul.'),
('9853e360-5dcb-4105-84a8-77759e13bdcd'::uuid,'Өз окуясын өздөрү жазсын 🪄','Экөөңүздөр тең классикалык жомоктордон тажадыңыздарбы? Бул жолу жомокту айтып жатып, аягын балаңызга тандатыңыз. «Баатырга ким жардам берди деп ойлойсуң?» деп сурап, анын фантазиясын өстүрүңүз.','Lase neil oma lugu ise kirjutada 🪄','Kas olete mõlemad klassikalistest unejuttudest väsinud? Lase sel korral lapsel fantaasialugudes ise lõpplahendus valida. Küsi temalt: "Kes sinu arvates kangelast aitas?" ja sütita tema kujutlusvõimet.'),
('d5f06496-2705-48a5-8325-2f0c28ac0a0f'::uuid,'Күч-кубат азайганда 🔋','Бүгүн өзүңүздү абдан чарчаңкы сезип жатасызбы? Биздин «Аялдар үчүн пайдалуу тамактар» бөлүмүнөн 5 мүнөттө даярдалуучу, темирге жана витаминге бай смузи жасап ичиңиз. Өзүңүзгө кам көрүүнү унутпаңыз.','Kui energia on otsakorral 🔋','Tunned end täna täiesti tühjana? Valmista 5 minutiga meie tervislike retseptide hulgast raua- ja vitamiinirikas smuuti ja joo seda kasvõi käigu pealt. Ära unusta enda eest hoolitseda.'),
('42bb5c65-e45f-45b5-8da0-322b9acd1ab4'::uuid,'Азык-түлүк тизмеси: Сиздин куткаруучуңуз 🛒','Дүкөнгө барганда эсиңизге таянып, үйгө келгенде памперс алууну унутканыңызды билдиңизби? Мындай нерсе баарыбыздын башыбыздан өтөт! Баарын «Соода тизмесине» кошууну адат кылыңыз, калганын колдон эстеп калат.','Toidupoe nimekiri: sinu päästerõngas 🛒','Lootsid poes mälule ja koju jõudes avastasid, et mähkmed jäid ostmata? Juhtub parimatel! Harjuta end kõike ostunimekirja lisama ja lase äpil enda eest meeles pidada.'),
('756d2914-ecb6-4838-adb6-d312a4bc59a2'::uuid,'Колдорун таанып билүү! 👐','Ал эми колдорун оозуна алып бара алат.','Avastab oma käsi! 👐','Ta oskab nüüd käsi suhu panna.'),
('8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54'::uuid,'Күтүлбөгөн кечки жолугушуу 🥂','Балаңыз күтүлбөгөн жерден эрте уктап калдыбы? Бул сейрек учурду үй жумуштарына коротпоңуз. Өнөктөшүңүз менен бетме-бет отуруп, телевизорду өчүрүп, жөн гана бири-бириңизден күнүңүз кандай өткөнүн сураңыз.','Üllatuslik kohtinguõhtu 🥂','Laps jäi ootamatult vara magama! Ära kuluta seda haruldast hetke kodutöödele. Istu partneriga vastakuti, lülita teler välja ja küsi lihtsalt teineteiselt, kuidas päev möödus.'),
('bf07c6c2-b84c-44ed-9459-f26c37f0e099'::uuid,'Жашынмактын кичинекей устаты 🙈','Бетме-бет (peek-a-boo) оюнун ойноо үчүн бетин колу менен жабуу – анын кечки эң сүйүктүү көңүл ачуусу.','Väike peitusemeister 🙈','Oma näo kätega katmine ja peitusemäng on tema vaieldamatu lemmiktegevus õhtuti.'),
('92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3'::uuid,'Пазл инженериясы 🧩','Формаларды туура тешиктерге салууга аракет кылып жатабы? Ката кетирсе же кыжырданса да, дароо жардам бербеңиз. Ал дал ушул аракеттер аркылуу көйгөйдү чечүүнү үйрөнүп жатат.','Puslede ehitamine 🧩','Kas ta nõuab visalt kujundite õigetesse aukudesse sobitamist? Isegi kui ta eksib või pettub, ära kohe aita. Ta õpib probleemilahendusoskusi just nende katsetuste ja eksimuste kaudu.'),
('346ca24f-e8f9-47c9-9cc2-dc1b86281214'::uuid,'Бөлүнүү кооптонуусу 🥺','Бөлмөдөн бир секундга чыгып кетсеңиз эле артыңыздан ыйлап жатабы? Бөлүнүү коркунучу кээде кайтып келет. Алыстан эле «Мен бул жердемин, ашканадамын, азыр кайтып келем» деп үн катып, аны тынчтандырыңыз.','Lahkumisärevus 🥺','Nutab su järel isegi siis, kui lahkud korraks toast? Lahkumisärevus võib vahel naasta. Rahusta teda eemalt hüüdes: "Olen siin, olen köögis, tulen kohe tagasi."'),
('afa94b0b-8399-4813-8b1a-8a243185fcf4'::uuid,'Кынтыксыз болуу кысымы 🛑','Башка балдар түстөрдү санап жатат, ал эми сиздики кызыкпай жатабы? Салыштырууну токтотуңуз! Ар бир бала өз темпинде өнүгөт. Сиздин балаңыз өзүнө ылайыктуу темпте өсүп жатат, бул – кадимки көрүнүш.','Täiuslikkuse surve 🛑','Teised lapsed loevad juba värve, aga sinu oma pole huvitatud? Lõpeta kohe võrdlemine! Iga laps areneb oma unikaalses tempos. Sinu laps areneb täpselt nii nagu peab ja see on täiesti normaalne.'),
('d5610b5c-f92a-4668-b551-ccf2ba5bd9e4'::uuid,'Атасынын жашыруун тактикасы 👨‍🍼','Күндүзгү чарчоо жетиштүү болду. Кечки тартипти жана тиш жууну атасынын тамашалуу оюнуна өткөрүп бериңиз, ал эми сиз четте отуруп, чайдан ырахат алыңыз.','Issi salajane taktika 👨‍🍼','Oled päevasest väsimusest tüdinud. Delegeeri õhtune une-eelne rutiin ja hammaste pesu isa mängulistele nippidele, samal ajal kui sina vaikselt kõrval teed rüüpad.'),
('47b60c96-b788-4cad-9b79-643917c1b944'::uuid,'Педиатриялык тынчсыздануулар 🤖','32 айлык балаңыздын бою жана салмагы сизди тынчсыздандырып жатабы? Интернет форумдарындагы коркунучтуу диагноздорго ишенбеңиз. Anacan AI аркылуу так, илимий негизделген маалыматты алыңыз.','Mured lastearsti juures 🤖','Kas 32-kuuse lapse pikkuse ja kaalu graafik tekitas äkki muret? Jäta foorumite hirmutavad diagnoosid vahele. Hangi täpset ja teaduslikult põhjendatud infot hoopis Anacan AI-lt.'),
('7f82c861-b627-4e20-b2ed-f2fb9f45756b'::uuid,'Табигый уйку чөйрөсү 🤫','Уктап кеткенден кийинки алгачкы жарым саат – мээ эң сезимтал болгон учур. Терезеден келген үндөрдү басуу үчүн бөлмөгө жагымдуу ак ызы-чуу (мисалы, жамгырдын үнү) коюп коюңуз.','Loomulik uneümbrus 🤫','Esimene pooltund pärast uinumist on aju jaoks kõige tundlikum aeg. Akna tagant kostvate helide summutamiseks lülita toas sisse õrn valge müra (nt vihmaheli).'),
('9bea836b-e06e-49f0-af98-259fe4009523'::uuid,'Түшүндүрүп берейин! ☝️','Баарын көрсөтүп, суроолорду жаадырып жатабы? Ал сизден дүйнөнү атап берүүнү суранып жатат. Бул баарлашуудагы чоң секирик! Чарчасаңыз да, ал нерселердин аттарын сабырдуулук менен кайталап бериңиз.','Lase mul selgitada! ☝️','Näitab kõigele näpuga ja esitab küsimuste laviini? Ta palub, et nimetaksid tema jaoks maailma. See on tohutu hüpe suhtlemises! Isegi kui väsid, korda kannatlikult nende esemete nimesid.'),
('48e4fdbb-6f6b-4c2d-90c9-ebe6d10f8179'::uuid,'Сүттүн чыгышын колдоочу азыктар. 🍲','Биздин «Аялдар үчүн пайдалуу тамактар» бөлүмүнөн эмчек сүтүн көбөйтүүчү шорполор жана суусундуктар менен өзүңүздү сыйлаңыз.','Toidud, mis toetavad piimatootmist. 🍲','Hellita end meie naiste tervislike retseptide rubriigist pärit piimateket soodustavate suppide ja jookidega.'),
('2fb64a2b-9948-4425-9837-80add71d4e54'::uuid,'Атасынын парктагы укмуштуу окуясы 👨‍👧','Энелик – бул 24/7 иштөө эмес! Бүгүнкү сейилдөөнү атасына тапшырыңыз. Алар чогуу ылайга былганып ойношсун, ал эми сиз диванда эс алып, тынчтыктан ырахат алыңыз.','Issi seiklus pargis 👨‍👧','Emadus ei ole 24/7 vahetus! Delegeeri tänane õue-seiklus isale. Lase neil koos mõnusalt mudaseks saada, samal ajal kui sina diivanil puhkad ja vaikust naudid.'),
('9928c8dc-9b21-49a6-b0c4-fd4704041409'::uuid,'Тез өсүү мезгили 📏','Шымы кайрадан кыскарып калдыбы? Ал көз алдыңызда күн сайын чоңоюп жатат! Учурдагы өлчөмдөрүн «Өсүү трекерине» киргизип, уйкусуз түндөрүңүздүн жемиши болгон өнүгүү графигине сыймыктануу менен көз салыңыз.','Kasvuspurt 📏','Püksid on jälle lühikesed? Ta kasvab iga päevaga otse su silme all! Sisesta mõõdud kasvujälgijasse ja vaatle uhkusega arengukõverat – sinu unetute ööde vilja.'),
('ed4eff7e-2e68-4d65-af30-186f1086a150'::uuid,'Классикалык музыканын керемети 🎶','Кечинде түшүнүксүз агрессия башталдыбы? Телевизорду өчүрүп, жарыкты азайтып, бөлмөгө жай классикалык музыка коюңуз. Жумшак үндөрдүн гармониясы атмосфераны өзгөртөт.','Klassikalise muusika ime 🎶','Õhtuti on alanud seletamatu agressiivsus? Lülita teler välja, hämarda tuled ja mängi toas väga vaikset klassikalist muusikat. Pehmete helide ja muusika harmoonia muudab atmosfääri.'),
('331370dc-1940-499c-abdb-15eb6fc3307a'::uuid,'Шорподогу жашыруун агенттер 🥦','Балаңыз жашыл түстөгү тамактардан баш тартып жатабы? Кабатыр болбоңуз! Жашылчаларды пюре кылып, котлетке же соуска жашырып берүү – биздин «Энелер үчүн тамактануу планыбыздагы» классикалык жана эффективдүү ыкма.','Salajased agendid supis 🥦','Kas su väike on kuulutanud boikoti kõigele rohelisele? Ära muretse! Köögiviljade püreestamine ja kavalalt lihapallidesse või kastmetesse peitmine on emade toitumiskava klassikaline ja tõhus nipp.'),
('a9d400f1-6a44-4584-a532-eeed75cc3207'::uuid,'Ырларды ойлоп табуу 🎤','Оюнчуктарын тизип жатып, ойдон чыгарылган сөздөр менен ырдап жатабы? Анын сөз байлыгы жана ритм сезими бир убакта өнүгүп жатат. Бул жаңы музыкалык жетишкендикти «Өнүгүү трекерине» жазып коюңуз.','Laulude väljamõtlemine 🎤','Kas ta laulab mänguasju sättides väljamõeldud sõnadega laule? Tema sõnavara ja rütmitaju arenevad samaaegselt. Pane see uus muusikaline verstapost kindlasti arengupäevikusse kirja.'),
('e7308375-84bd-4b4e-9322-163dcd46ff8e'::uuid,'Өжөр пижамалар 👕','Кийинүү чоң согушка айландыбы? Ага тандоо мүмкүнчүлүгүн бериңиз: «Кызыл пижаманы киесиңби же көгүнбү?» Бул кичинекей амал ага өзүн башкарып жаткандай сезим берет жана көп учурда талаш-тартышты токтотот.','Kangekaelne pidžaama 👕','Kas riietumisest on saanud suur lahing? Anna talle valik: "Kas tahad punast või sinist pidžaamat?" See väike nipp annab talle tunde, et ta kontrollib olukorda, ja peatab sageli jonni.'),
('68ebc7a3-cb63-4696-9089-9b8d5bd20d47'::uuid,'Жөн гана кучактоо 🫂','Бүгүн кечинде оюн, китеп же жомоктун кереги жок. Жөн гана аны кучагыңызга бекем кысып, жытын жыттап, караңгыда анын канчалык баалуу экенин шыбырап айтыңыз.','Lihtsalt üks kallistus 🫂','Täna pole vaja mänge, raamatuid ega muinasjutte. Lihtsalt hoia teda tihedalt vastu rinda, hinga sisse tema magusat lõhna ja sosista pimeduses, kui kallis ta sulle on.'),
('e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513'::uuid,'Бирге жыйноо 🧹','Үйдү жыйноо керекпи? Пол шыпырып жатканда, ал да чүпүрөк менен сүртүп жардам берсин. Тазалыкты кантип командалык оюнга айландыруу керектигин биздин блогдордон окуңуз.','Koos koristamine 🧹','Vaja kodu koristada? Kui pühid tuba, lase tal lapiga aidata. Loe meie blogisid, kuidas muuta koristamine meeskonnatööks ja lõbusaks tegevuseks.'),
('f0084bbf-ef12-44c3-80b2-42b0bd99f526'::uuid,'Аябай чарчадым 🔋','Баары сизден энергия күтүп жатат, бирок сиздин кубатыңыз түгөнүп калды. Бүгүн тамак жасабаңыз, даяр тамак заказ кылыңыз! «Кемчиликсиз» эне болуу – баарын өзүң жасоо дегенди билдирбейт. Өзүңүзгө эс алууга уруксат бериңиз.','Olen nii väsinud 🔋','Kõik ootavad sinult energiat, aga aku on täiesti tühi. Ära täna süüa tee; telli toit koju! "Ideaalne" ema ei pea kõike ise tegema. Anna endale luba puhata.'),
('001946c3-28e7-4dd7-a8dd-6edeeb1c5013'::uuid,'Тегеректерден формаларга чейин 🎨','Дубалга же кагазга карандаш менен тегерек чийип жатабы? Бул «тентектик» чындыгында анын майда моторикасынын өнүгүүсүндөгү укмуштуудай секирик!','Ringidest kujunditeni 🎨','Kas ta joonistab kriidiga seinale või paberile ringe? See "pahandus" on tegelikult fantastiline hüpe lapse peenmotoorika arengus!'),
('447f446e-b226-43bb-8269-02d7d4965189'::uuid,'Суунун тынчтандыруучу гармониясы 🛀','Экөөңүздөр тең күн бою чуркап чарчадыңыздар. Ал жылуу сууга түшүп жатканда, фондо жаратылыштын тынчтандыруучу үндөрүн коюңуз. Суунун жумшак гармониясы эң активдүү баланы да уйкуга даярдайт.','Vee rahustav harmoonia 🛀','Olete mõlemad terve päeva jooksmisest väsinud. Samal ajal kui ta soojas vannis on, mängi taustaks rahustavaid loodushelisid. Vee rahustav harmoonia valmistab ka kõige energilisema lapse uneks ette.'),
('706c71ad-a073-4d24-bc8e-9dc899c5ba4e'::uuid,'Дүкөндөгү кежирлик 🛒','Кассада таттуу үчүн ыйлап жатабы? Айланадагылардын сындаган көз караштарына көңүл бурбаңыз. Сабырдуулук менен көзүнө карап, эрежени түшүндүрүп, өз позицияңызда бекем туруңуз.','Jonn toidupoes 🛒','Karjub poes kommi järele? Ignoreeri täielikult kõrvalseisjate hukkamõistvaid pilke. Võta rahulikult silmside, selgita reeglit ja jää endale kindlaks.'),
('1a8980b4-ba5e-4179-adce-580423431a55'::uuid,'Уйку ченемдерин түшүнүү ⏱️','Ал уктап жатканда, күнүмдүк сунушталган уйку нормасын аткарып жатабы же жокпу, билүү үчүн уйку таймерин иштетиңиз.','Une normide mõistmine ⏱️','Kui ta magab, käivita unetaimer, et näha, kas ta täidab päevase soovitusliku uneaja.'),
('295a4c1e-3bba-40c5-820d-04095aefe60e'::uuid,'Үй иштерин ким жасайт? 🌪️','Үй жумуштары топтолуп калдыбы? Азырынча кала берсин. Өнөктөшүңүздөн бүгүнкү үй жумуштарын өзүнө алуусун сураныңыз. Сиз эс алууга татыктуусуз; сиз бул үйдөгү эң маанилүү адамсыз жана энергияңызды сактап калышыңыз керек.','Kes teeb kodutööd ära? 🌪️','Kodutööd kuhjuvad? Las nad olla. Palu partneril tänased majapidamistööd üle võtta. Sa väärid puhkust; oled selles majas kõige tähtsam inimene ja pead oma energiat säästma.'),
('c86bd995-9231-4eae-b8e0-8f84d6a46b62'::uuid,'Сиз абдан күчтүүсүз! ✨','Кээде кыйын болсо да, унутпаңыз, сиз укмуштуудай энесиз!','Sa oled nii tugev! ✨','Kuigi vahel on raske, pea meeles – sa oled imeline ema!'),
('5b09b018-664d-4b58-86b9-31b6e1d3baf2'::uuid,'«Меники!» баскычы 🛑','Балаңыз кооптуу нерсени колунан алганда капаланып жатабы? Жөн эле «болбойт» дебестен, көңүлүн башка кызыктуу оюнчукка же ачык түстөгү буюмга буруп, бул кичинекей каприздерди оңой чечиңиз.','„Minu oma!“ faas 🛑','Kas su väike läheb pahaseks, kui võtad ära midagi ohtlikku? Selle asemel, et lihtsalt öelda "ei", suuna tema tähelepanu mõnele põnevamale mänguasjale, millel on hääled või erksad värvid, et neid mini-jonnihooge kergemini lahendada.'),
('ea9b5851-8f4a-4a19-990c-97e725808bb5'::uuid,'Атасынын бешик ыры 👨‍🍼','Бүгүн кечинде бешик ыры жана уктаар алдындагы жомокторду айтып берүү — атасынын өзгөчө милдети.','Issi hällilaul 👨‍🍼','Täna õhtul on kõik hällilaulud ja unejutud isa eriline ülesanne.'),
('698ffa60-da73-4003-9656-db865993d1b5'::uuid,'Тарелкаңыздагы искусство чыгармасы 🥦','Кичинекейиңиз пюре жегиси келбей жатабы? Кээде маселе даамында эмес, берилишинде болот. Биздин пайдалуу рецепттерди колдонуп, түстүү жашылчалардан кызыктуу беттерди жасап, анын табитин ачыңыз!','Kunstiteos sinu taldrikul 🥦','Kas su väike ime keeldub püreedest? Mõnikord pole probleem maitses, vaid serveerimises. Kasuta meie tervislikke retsepte ja loo värvilistest köögiviljadest naljakaid nägusid, et lapse isu äratada!'),
('eec20c49-b219-4211-8916-1e602a8ceafb'::uuid,'Уйкуга сезимталдык 🤫','Ал уктап кетээри менен эле кичинекей добуштан чочуп кетеби? Үн өлчөгүч менен бөлмөнүн акустикасын текшерип, терезеден келген үндөрдү басуу үчүн ак ызы-чууну (white noise) иштетиңиз.','Tundlikkus une suhtes 🤫','Kas ta ehmatab vähimagi heli peale kohe, kui on uinunud? Kontrolli ruumi akustikat helimõõtjaga ja mängi valget müra, et summutada aknast kostvaid helisid.'),
('a2641bfd-0346-425a-86be-0a5a6822a3d8'::uuid,'Атасынын тынчтандыруучу үнү 📖','Бүгүн кечинде бөлмөдө башкача атмосфера түзөлү. «Акылдуу жомоктордо» токойдогу эр жүрөк жаныбар жөнүндө жомок түзүп, аны окууну атасынын терең, ишенимдүү үнүнө тапшырыңыз.','Issi rahustav hääl 📖','Loome täna õhtul toas teistsuguse atmosfääri. Vali „Nutikad jutud“ ja loo lugu vaprast metsaelanikust ning usalda selle lugemine isa sügava ja rahustava hääle hoolde.'),
('ba28583a-a3f1-40f6-9657-b7b38af17c60'::uuid,'Төрт дубалдан сырткары ☕','Үй тиричилигинен чарчадыңызбы? Бүгүн башкачараак иш кылыңыз! Жакын жердеги коляска менен кирүүгө ыңгайлуу кафени таап, кофеңизден ырахат алыңыз.','Väljaspool sinu seinu ☕','Tunned end kodurutiinist kurnatuna? Tee täna midagi teisiti! Leia läheduses asuv vankrisõbralik kohvik ja naudi oma kohvi.'),
('ea94213c-026e-4de0-be12-a192e4d22b19'::uuid,'Кичинекейиңиз күн сайын өсүүдө! 🤏','Кичинекейиңиз полдогу эң майда күкүмдөрдү баш бармагы жана сөөмөйү менен кармоого аракет кылып жатабы? Демек, анын майда моторикасы тездик менен өнүгүп жатат!','Sinu väike ime areneb iga päevaga! 🤏','Kas su väike ime üritab pöidla ja nimetissõrmega põrandalt kõige pisematki puru üles korjata? Tema peenmotoorika areneb mühinal!'),
('2ab7b4ab-59b4-4e96-8271-8ddcc86f1911'::uuid,'Эмеректерге чыгуу 🧗‍♂️','Ал диван же отургучту кармап турууга аракет кылып жатабы? Бут булчуңдары өз алдынча турууга даярданууда. Анын коопсуздугун камсыз кылыңыз, бирок бул «альпинисттик» аракеттерине тоскоол болбоңуз.','Mööblile ronimine 🧗‍♂️','Kas ta tõmbab end diivani või tooli najal püsti? Tema jalalihased valmistuvad iseseisvaks seismiseks. Hoia teda, kuid ära takista neid väikeseid „ronija“ katsetusi.'),
('82e71311-374a-4306-bcfc-4f69bc54da1b'::uuid,'Түнкү ыйлоо учурлары 😭','Түн ортосунда эч себепсиз ыйлап ойгондубу? Себебин табуу жана аны сооротуу үчүн Ыйды талдоо функциясын колдонуңуз.','Öised nutuhood 😭','Kas ta ärkas keset ööd nutuga ilma nähtava põhjuseta? Kasuta nutu analüüsimise funktsiooni, et leida põhjus ja teda rahustada.'),
('c7aadd23-e889-42f2-a761-3f955cb9600f'::uuid,'Мээңизге эс алуу бериңиз 🛒','Уйкунун жетишсиздигинен улам унутуп калып жатасызбы? Баарын Соода тизмесине жазып коюңуз, үйгө келе жатканда жолдошуңуз алып келет.','Anna oma ajule puhkust 🛒','Kas unepuudus muudab sind hajameelseks ja toidunimekirjas olevad asjad kipuvad meelest minema? Pane kõik kirja ostunimekirja ja lase partneril need kojutulekul kaasa osta.'),
('4d7eb303-e249-46ed-8460-db2f0a519240'::uuid,'Жаратылыш – эң мыкты дары ⛅','Кичинекейиңиз өтө тынчсызданып, сооротууга мүмкүн болбой жатабы? «Аба ырайы жана кийим» куралын ачып, аба ырайына жараша кийиндирип, дароо паркта 20 мүнөт сейилдеп келиңиз.','Loodus on parim ravim ⛅','Kas su väike ime on äärmiselt viril ja teda on võimatu rahustada? Ava tööriist „Ilm ja riietus“, pane ta ilmastikule vastavalt riidesse ja mine temaga kohe 20-minutilisele jalutuskäigule parki.'),
('4dcbbcf9-87b6-44f2-9ce0-d8fdd1caacf7'::uuid,'Үнсүз көз жаштар 📝','Бүгүн баары оор сезилип, ыйлагыңыз келип жатабы? Бул табигый нерсе... Бардык чарчооңузду Маанай күндөлүгүңүзгө жазыңыз. Сезимдериңизди төгүп салуу сизге жеңилдик берет.','Vaiksed pisarad 📝','Kas kõik tundus täna üle jõu käivana ja tahaksid lihtsalt nutta? See on täiesti loomulik... Kirjuta kogu oma kurnatus üles meeleolupäevikusse. Tunnete väljaelamine teeb olemise kergemaks.'),
('e8e53d71-abc7-400d-80a7-8cf91f3339ab'::uuid,'Биринчи муундарды кайталоо 🗣️','Ал «да-да» же «ба-ба» сыяктуу үндөрдү көп кайталап жатабы? Ал өзүнүн сүйлөө аппаратын сынап жатат. Ал айткан ар бир муунду жылмайып кайталап, диалог түзүүгө үйрөтүңүз.','Esimeste silpide kordamine 🗣️','Kas ta kordab sageli häälikuid nagu „da-da“ või „ba-ba“? Ta katsetab oma kõneaparaadiga. Naerata ja korda iga silpi, mida ta ütleb, et aidata tal õppida dialoogi pidama.'),
('27772b37-d653-4081-a4d8-e2d8e3036d19'::uuid,'Педиатриялык кооптонуулар 🤖','8 айлык кезинде уйкунун бузулушу кадимки көрүнүшпү? Интернеттен чексиз издөө жүргүзүүнүн ордуна, Anacan AI аркылуу 8 айлык кезиндеги уйкунун өзгөрүшү тууралуу так, илимий негизделген фактыларды алыңыз.','Mured lastearsti juures 🤖','Kas on normaalne, et unerežiim on 8-kuuselt häiritud? Selle asemel, et lõputult internetist otsida, saa Anacan AI-lt konkreetsed ja teaduslikult põhjendatud faktid 8-kuuse une-regressiooni kohta.'),
('e5b5ed3f-01d7-4566-8860-0dc049a710b5'::uuid,'Кечки бешик ырлары 🎶','Балаңыз уктагысы келбей жатканда, бөлмөгө жай классикалык музыка коюңуз. Тынчтандыруучу обондор анын ашыкча дүүлүккөн нерв системасын оңой эле тынчтандырат.','Õhtused hällilaulud 🎶','Kui laps uinumisele vastu paneb, mängi toas rahulikku klassikalist muusikat. Rahulikud meloodiad aitavad tema ülestimuleeritud närvisüsteemi hõlpsasti rahustada.'),
('ea452c1a-6484-41b5-9042-60a3abcf409d'::uuid,'Элестетүү оюндарынын башталышы 🧸','Балаңыз оюнчук аюусуна же куурчагына суу ичирүүгө аракет кылып жатабы? Анын фантазиясы өсүп, символдук оюн башталды. Бул таттуу «режиссерду» сырттан карап ырахат алыңыз.','Loovmängu algus 🧸','Kas su beebi üritab oma mängukaru või nukku joota? Tema kujutlusvõime õitseb ja algab sümboolne mäng. Naudi selle armsa „lavastaja“ jälgimist kõrvalt.'),
('3a7b24a5-41c6-4c5d-a602-8a4582791ae2'::uuid,'Түшкү тамакты шашып ичпеңиз. 🥑','Сиз кичинекейиңиздин курсагы ток болушу үчүн баарын жасайсыз. Ал эми өзүңүзчү? Өзүңүз үчүн темирге бай, аш болумдуу атайын тамак даярдап алыңыз.','Ära söö lõunat kiirustades. 🥑','Sa teed kõik, et su väike ime oleks hästi toidetud. Aga kuidas on lood sinuga? Valmista endale üks eriline, toitev ja rauast pakatav eine.'),
('61d3770b-ac23-4b61-a0c4-be4c333cc55a'::uuid,'Сезимдериңиз менен бөлүшүү 💬','«Эмне үчүн балам азырынча сойлобой жатат?» деп тынчсызданып жатасызбы? Дароо Anacan коомчулугуна кошулуңуз. Башка энелердин миңдеген реалдуу окуяларын окуп же суроо берип, ар бир баланын уникалдуу экенине ынаныңыз.','Tunnete jagamine 💬','Kas oled mures ja mõtled: „Miks mu beebi veel ei rooma?“ Liitu kohe Anacan kogukonnaga. Loe tuhandeid teiste emade tõestisündinud lugusid või küsi küsimus, et näha, et iga laps on ainulaadne.'),
('a8ecb50a-232f-401a-97bc-3fbfc63cc92b'::uuid,'Бөлүнүү кооптонуусу 🥺','Бөлмөдөн чыгып кеткениңизде ыйлайбы? Ал сизди кайра келбейт деп ойлошу мүмкүн. «Мен ар дайым жаныңдамын» деп үнүңүз менен ишеним берип, коопсуздук сезимин ойготуңуз.','Lahkumisärevus 🥺','Kas ta nutab, kui toast lahkud? Ta võib arvata, et sa ei tulegi tagasi. Rahusta teda oma häälega, öeldes: „Olen alati siin,“ et sisendada talle turvatunnet.'),
('6666dee6-8da7-4982-b6e5-9cdc982b4a75'::uuid,'Тиштин бүйлөлөрү дагы эле кычышууда 🦷','Балаңыз баарын катуу чайнап, шилекейи агып жатабы? Тоңдургучтан алынган муздак тиш чыгаруучу оюнчуктар мындай күндөрү чыныгы куткаруучу болот.','Sügelus igemetes jätkub 🦷','Kas su beebi närib agressiivselt kõike ja ilastab pidevalt? Sügavkülmast võetud jahutavad närimismänguasjad on nendel päevadel tõelised päästjad.'),
('bedd9e86-f764-4777-9e49-e315e75433fd'::uuid,'Атасынын милдеттери 👨‍🍼','Түнкү ойгонууларды жалгыз өзүңүз көтөрбөңүз. Жолдошуңузду да ойготуңуз, анткени команда болуу — бул жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi kohustused 👨‍🍼','Ära kanna öiseid ärkamisi üksi. Ärata ka oma partner, sest meeskonnana tegutsemine tähendab vastutuse võrdset jagamist.'),
('c36dcca2-2b51-424c-b39c-c98f7988d549'::uuid,'Ку-ку! 🙈','Колуңуз менен бетиңизди жаап, «ку-ку» оюнун ойногондо катуу күлөбү? Бул нерселердин туруктуулугу түшүнүгү толук калыптанып жатканын билдирет. Бул оюнду күнүмдүк жашооңуздун кызыктуу бөлүгүнө айлантыңыз.','Kuku! 🙈','Kas ta naerab valjusti, kui katad kätega näo ja mängid „peitust“? Objektipüsivuse kontseptsioon areneb täielikult. Tee sellest mängust oma igapäevarutiini lõbus osa.'),
('3f339310-d600-43dc-81a3-1b609288885e'::uuid,'Кетиши кыйын тактар 👗','Кошумча тамак берүү — бул кийимдердин жана үйдүн булганышы дегенди билдирет. Буга капа болбоңуз! Силикон эмчекти колдонуңуз жана бул башаламан, бирок түстүү көз ирмемдерден ырахат алыңыз.','Kangekaelsed plekid 👗','Tahke toiduga alustamine tähendab lõputuid plekke riietel ja kodus. Ära lase sel end stressata! Kasuta silikoonpõllesid ja lihtsalt naudi neid segaseid, värvilisi hetki.'),
('60071670-7fa4-4f9f-829f-892d281a9741'::uuid,'Өзүңүздү күнөөлөөнү токтотуңуз 🛑','Бүгүн экранга көп карадыңызбы же үй башаламанбы? Сиз жөн гана чарчаган адамсыз жана колуңуздан келгендин баарын жасап жатасыз.','Lõpeta enda süüdistamine 🛑','Kas veetsid täna liiga palju aega ekraani taga või on kodu sassis? Oled lihtsalt väsinud inimene ja annad endast parima.'),
('fe5cb47e-9f22-41f9-a236-1db4b224e518'::uuid,'Нерселерди таштоо оюну 🥄','Ал оюнчугун отургучтан ыргытып, сиздин алып беришиңизди күтүп жатабы? Ал тартылуу күчүн жана себеп-натыйжа байланышын изилдеп жатат. Сабырдуу болуңуз жана жылмайыңыз.','Asjade loopimise mäng 🥄','Kas ta viskab mänguasja söögitoolist alla ja ootab, et sina selle üles korjaksid? Ta avastab gravitatsiooni ja põhjus-tagajärg seost. Varu kannatust ja naerata.'),
('28d590c8-c8a6-4c89-b78b-e70f2f482c0d'::uuid,'Караңгылыкка көнүү 🌙','Тез уктап кетиши үчүн бөлмөдөгү ашыкча жарыктарды жана экрандарды өчүрүңүз. Мелатонин гормонунун бөлүнүп чыгышы тынч жана караңгы чөйрөдө гана тездейт.','Pimedusega kohanemine 🌙','Et aidata tal kiiremini uinuda, lülita toas välja kõik lisavalgustid ja ekraanid. Melatoniini eritumine kiireneb vaid rahulikus ja pimedas keskkonnas.'),
('31783568-6230-449d-98c8-e7b1b046a34e'::uuid,'Маанайсыз эртең мененки убак ☁️','Ал көзүн ачары менен баарына ыйлап, нааразы болуп жатабы? Балким, ал өсүү мезгилиндедир. Жөн гана аны кучактап, ишеним бериңиз.','Vingused hommikud ☁️','Kas ta nutab kõige pärast ja tundub rahulolematu kohe, kui silmad avab? Võib-olla on ta kasvuspurtide keskel. Lihtsalt anna talle palju kaisutusi ja kinnitust.'),
('38c7f3dd-4cf4-4758-8006-37d59832bac8'::uuid,'Бала уктаганда, үй иштерине шашпаңыз! 🛋️','Диванга жатыңыз, көзүңүздү жумуңуз жана 15 мүнөт бою үйдүн сейрек кездешүүчү тынчтыгынан ырахат алыңыз.','Kui beebi magab, ära kiirusta koristama! 🛋️','Heida diivanile, sule silmad ja sula 15 hinnaliseks minutiks maja haruldasse, täielikku vaikusse.'),
('3b5314f5-fa59-44ed-9fa8-b6cf2bce9e2d'::uuid,'Бир команда катары ата-эне болуу 🥂','Оор күндү артта калтырдыңыз. Бала уктагандан кийин жолдошуңуз менен чай ичип, бири-бириңиздерди баалап, «Биз чындап эле сонун командабыз!» деп айтууну унутпаңыз.','Vanemlus kui meeskonnatöö 🥂','Oled raske päeva seljatanud. Pärast lapse uinumist tee partneriga teed ja ära unusta üksteist tunnustada, öeldes: „Oleme tõesti suurepärane meeskond!“'),
('579d5966-d49f-4125-a264-8acd785d0a8d'::uuid,'Күзгүдөгү дос 👀','Аны күзгүгө алып барыңыз. Өзүнүн чагылышын көрүп, ага тийүүгө аракет кылып жатканына таң калганын караңыз. Бул анын өзүн-өзү таануусу үчүн сонун көнүгүү.','Sõber peeglis 👀','Vii ta peegli ette. Vaata, kui üllatunud ta oma peegelduse üle on ja püüab seda puudutada. See on suurepärane tegevus tema eneseteadvuse arendamiseks.'),
('9099f274-aa9c-4fe9-8624-5cd611699d2d'::uuid,'Тез арада толуктоо 🛒','Балдар майы же нымдуу салфеткалар түгөнүп калдыбы? Колдонмодогу Соода тизмеңиз даяр! Керектүү нерселердин баарын жазып коюңуз, жолдошуңуз жумуштан келе жатканда алып келет.','Kiire varude täiendamine 🛒','Beebiõli või niisked salvrätikud hakkavad otsa saama? Sinu rakenduse ostunimekiri on valmis! Pane kõik vajalik sinna kirja ja lase partneril need töölt tulles kaasa osta.'),
('1d706879-d02b-44cf-bac5-4f53776477d3'::uuid,'Аба ырайынын күтүлбөгөн белеги ⛅','Сыртка чыгарда, алдамчы асманга ишенип, балаңызды үшүтүп албаңыз. Терезеден карап эле койбостон, сырттагы шартка жараша эң туура чечим кабыл алуу үчүн «Аба ырайы жана кийим» жардамчысын колдонуңуз.','Ilmaüllatus ⛅','Välja minnes ära lase petlikul taeval end eksitada, et laps külmetuks. Ära piilu vaid aknast; kasuta „Ilm ja riietus“ abilist, et teha õues valitsevate olude jaoks kõige täpsem otsus.'),
('acd7fb31-0c36-4f0b-9849-cf983e0b0e95'::uuid,'Өзүм жейм! 🥦','Кичинекейиңиз пюрени кашык менен эмес, өз колу менен жегиси келеби? Анын өз алдынчалыгын колдоңуз! Ооба, бир аз башаламандык болот, бирок анын өнүгүүсү тездейт.','Söön ise! 🥦','Kas su väike ime tahab köögivilju oma kätega süüa, selle asemel et lusikaga püreed süüa? Toeta tema iseseisvust! Jah, see teeb segadust, kuid tema areng kiireneb.'),
('e1819391-1d2d-450e-ac14-9ecfa65465d4'::uuid,'Жомок айтуунун сыйкыры 🪄','Бүгүн кечинде «Акылдуу жомоктордо» таптакыр башкача нерсени сынап көрүңүз. Үнүңүздүн обонун жомоктун ыргагына жараша өзгөртүңүз.','Jutuvestmise võlu 🪄','Proovi täna õhtul „Nutikates juttudes“ midagi täiesti teistsugust. Kohanda oma hääletooni vastavalt loo rütmile.'),
('d79d065c-4399-4ac9-8bd9-d4970a686fba'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Күндүзгү чарчоо сизге жетиштүү. Бүгүн кечинде баланы уктоого даярдоо жана пижамасын кийгизүү процессин атасына тапшырып, сиз жөн гана сырттан байкоо салыңыз.','Issi öövahetus 👨‍🍼','Päevasest väsimusest piisab. Anna täna õhtul lapse voodisse panemise ja pidžaamasse riietamise protsess isale üle ja lihtsalt vaatle kõrvalt.'),
('ea309314-6720-4ddf-9fe1-7a4fb805b43f'::uuid,'Сурооңуз барбы? 🤖','8 айлык кезинде балаңыздын өсүү графиги үчүн тынчсызданып жатасызбы? Интернеттеги коркунучтуу макалаларды окуунун ордуна, Anacan AI''дан так, илимий негизделген өсүү графигин сураңыз.','Kas sul on küsimusi? 🤖','Kas oled 8-kuuse beebi kasvukõvera pärast mures? Selle asemel, et lugeda internetist hirmutavaid artikleid, küsi Anacan AI-lt täpset ja teaduslikult põhjendatud kasvukõverat.'),
('1c1e068a-2609-422f-991f-68ad50839ea3'::uuid,'Күч-кубатыңызды толуктаңыз 🍲','Сөөгүңүзгө чейин чарчадыңызбы? Биздин пайдалуу рецепттерден 10 мүнөттө даярдалуучу, сүтүңүздү көбөйтүүгө жана энергияңызды жогорулатууга жардам бере турган атайын смузи тандаңыз!','Taasta oma energia 🍲','Kas väsimus on kontides? Vali meie tervislike retseptide hulgast eriline smuuti, mille valmistamine võtab vaid 10 minutit, toetab piimaeritust ja annab energiat juurde!'),
('51badc42-c8bc-4aa3-b0b8-ec576b19fa07'::uuid,'Үндөрдү иргөө 🤫','Ал уктап кеткенден кийинки алгачкы жарым саат — эң сезимтал мезгил. Үн өлчөгүч менен чөйрөнү текшерип, коңшу бөлмөдөн же телевизордон чыккан капыстан үндөрдү алдын алыңыз.','Helide filtreerimine 🤫','Esimene pooltund pärast uinumist on kõige tundlikum periood. Kontrolli keskkonda helimõõtjaga ja hoia ära äkilised helid kõrvaltoast või telerist.'),
('69f05aef-6a67-462b-8173-638d2cb174d5'::uuid,'Максаттуу сойлоп жүрүү 🐢','Ал буга чейин эле максатын тандап, ага карай тез сойлоп баратат. Бөлмөдөгү полдо жаткан майда, жутуп алууга мүмкүн болгон кооптуу нерселердин баарын дароо алып салыңыз.','Sihipärane roomamine 🐢','Ta on juba sihtmärgi valinud ja roomab kiiresti selle poole. Eemalda kohe põrandalt kõik väikesed, allaneelatavad ja ohtlikud esemed.'),
('7405692f-45e1-45fa-9dd9-b527045b5e7d'::uuid,'Тажрыйба алмашуу 💬','Балаңыздын жаңы кылыгы (мисалы, башын уруу) сизди чочуттубу? Anacan коомчулугуна жазыңыз жана башка энелер бул этаптан кантип өткөнүн окуп көрүңүз.','Kogemuste jagamine 💬','Kas lapse uus käitumine (näiteks pea tagumine) ehmatas sind? Postita Anacan kogukonda ja loe, kuidas teised emad on seda etappi läbinud.'),
('cad415e5-9ff2-468b-bfee-aaed538d25a0'::uuid,'Кайраттуу кадамдарды жасоо 🧗‍♂️','Ал диванды кармап, бир колун коё берүүгө аракет кылып жатабы? Анын тең салмактуулугу тез өнүгүп жатат. Анын коркпогон аракеттерин жылмайып карап, алыстан коопсуздугун көзөмөлдөп туруңуз.','Julged sammud 🧗‍♂️','Kas ta hoiab diivanist kinni ja proovib ühe käega lahti lasta? Tema tasakaalutunnetus areneb kiiresti. Jälgi tema kartmatuid katsetusi naeratusega, veendudes kaugelt, et ta on ohutus kohas.'),
('e2523211-afd7-48c7-8227-2ec7b0b2f0f7'::uuid,'Сезимдериңизди сыртка чыгарыңыз 📝','Өзүңүздү абдан жалгыз жана түшүнүксүз сезип жатасызбы? Бул эң табигый сезим. Сезимдериңизди эч кандай фильтрсиз, чынчылдык менен Маанай күндөлүгүңүзгө жазып алыңыз.','Lase oma emotsioonid valla 📝','Kas tunned end väga üksiku ja mittemõistetuna? See on kõige loomulikum tunne. Pane oma tunded ausalt, ilma filtriteta meeleolupäevikusse kirja.'),
('16c8c619-fdcd-4a82-a21a-ff965106a15f'::uuid,'Үйдөгү башаламандык 🌪️','Оюнчуктар бөлмө ичинде чачылып жатабы? Кичинекейиңиз менен өткөргөн он мүнөттүк шаңдуу убакыт тартиптен алда канча маанилүү. Оюнчуктар эртең да ошол жерде болот, андыктан өзүңүздү чарчатпаңыз!','Kodune kaos 🌪️','Kas mänguasjad on üle toa laiali? Kümme rõõmsat minutit koos lapsega on tähtsamad kui kord majas. Mänguasjad on homme ka alles, nii et ära kurna end ära!'),
('724d9097-f64c-406e-8895-2982258b710d'::uuid,'Жуунуу жана уйку алдындагы обондор 🛀','Кечки тартип кыйын болуп жатабы? Алар жылуу сууга түшүп жатканда фондо жагымдуу музыка коюңуз. Суу менен обондун гармониясы эң тентек баланы да тынчтандырат.','Vanniskäigu ja uneaja meloodiad 🛀','Kas õhtune rutiin muutub keeruliseks? Mängi taustaks rahustavat muusikat, samal ajal kui laps soojas vannis käib. Vee ja meloodia harmoonia rahustab ka kõige jonnakamat last.'),
('12b2ddaa-17a1-4692-8574-725c962b0e1b'::uuid,'Себепсиз ыйдан чарчоо 😭','Себебин таба албаган кризистер адамды алдан тайдырат. Божомолдоону токтотуңуз; ыйдын артында катылган билдирүүнү (оору, чарчоо) дароо аныктоо үчүн «Ыйды талдоо» функциясын колдонуңуз.','Seletamatu nutu kurnavus 😭','Kriisid, mille põhjust sa ei tea, on kurnavad. Lõpeta oletamine; kasuta nutu analüüsimise funktsiooni, et kohe tuvastada heli taga peituv sõnum (valu, väsimus).'),
('19b095ff-5334-4011-abd1-b8df6c79520c'::uuid,'Сыртка чыгууга убакыт келди 🌳','Үйдө отуруп тажадыңызбы? Кичинекейиңизди коляскага салып, жок дегенде 20 мүнөткө таза абага чыгыңыз. Жаратылыштын тынчтыгы балаңызга да, өзүңүздүн абалыңызга да жакшы таасир этет.','Aeg õue minna 🌳','Tunned end nelja seina vahel lõksus? Pane laps vankrisse ja mine värske õhu kätte, kasvõi 20 minutiks. Looduse rahu teeb imesid nii sinu kui ka beebi enesetundega.'),
('b6194099-d4e6-4061-b3f2-d6bc5cce0529'::uuid,'Сөөмөй менен көрсөтүү ☝️','Алар манжасы менен алыстагы нерсени көрсөтүп, анан сизге карап жатабы? Алар сизге «мага кара» же «мен ошону каалайм» деп жатышат! Бул баарлашууда чоң кадам! Ага ал нерсенин атын айтып бериңиз.','Näitav sõrm ☝️','Kas ta näitab sõrmega kaugemal asuvale esemele ja vaatab siis sulle otsa? Ta ütleb sulle „vaata“ või „ma tahan seda“! See on suur hüpe suhtlemises! Ütle talle selle eseme nimi.'),
('b78498d9-706c-458c-aa0f-d6081c7746c6'::uuid,'Түнкү бешик ыры 🎶','Эч бир тиркеме же үн эненин бешик ырынын ордун баса албайт. Бүгүн кечинде кичинекейиңизди кучагыңызга алып, анын эң жакшы көргөн, эң жагымдуу бешик ырын акырын ырдап бериңиз.','Õhtune hällilaul 🎶','Ükski rakendus ega heli ei asenda ema hällilaulu. Täna õhtul lihtsalt hoia oma pisikest lähedal ja laula talle vaikselt tema lemmikut, kõige rahustavamat hällilaulu.'),
('d08b308d-00d3-45c9-9840-df7ac1047703'::uuid,'Кол чабуу 👏','Алар кубанычын кол чабуу менен билдирип жатабы? Бул сонун кыймыл-аракет жөндөмүн көргөн учурда, үйдө кичинекей жеңиш бийин бийлеп, аларга кошулуңуз!','Plaksutamine 👏','Kas ta väljendab rõõmu käsi plaksutades? Sel hetkel, kui näed seda imelist motoorset saavutust, tee kodus väike võidutants ja ühine temaga!'),
('8e6d5e26-758c-4169-81b6-bd9cbcc10cc5'::uuid,'Сонун күндүн жагымдуу аякташы. 🌙','Бөлмөнүн жарыгын өчүрүп, «Ак ызы-чуу» (White Noise) бөлүмүнөн курсактагы үндү коюңуз да, балаңыздын тынч уйкуга кетишин байкаңыз.','Magus lõpp ilusale päevale. 🌙','Hämarusta toas tuled, pane mängima emakaheli valgest mürast ja vaata, kuidas su beebi rahulikult unne suubub.'),
('546e217e-8060-4a89-877d-29e71165dae1'::uuid,'Командалык колдоо 🥂','Оор күндү артта калтырдыңыз. Бала уктагандан кийин, өнөктөшүңүз менен бир чыны чай ичип, бири-бириңизге: «Биз бул ишти абдан сонун аткарып жатабыз!» деп дем бериңиз.','Meeskonna tugi 🥂','Oled selja taha jätnud raske päeva. Pärast lapse uinumist vala endale ja partnerile tass teed ning motiveerige üksteist öeldes: „Me teeme seda tõesti suurepäraselt!“'),
('f23e5345-9d7c-4e2d-871d-a259a849da6f'::uuid,'Сүрөттөрдүн маанисин түшүнүү 📖','Алар китептеги каармандарды кармап, «Бул эмне кылып жатат?» деп сурап жатышабы? Алардын визуалдык кабыл алуусу таң калыштуу! Бирге окуп жаткан китебиңизге жаңы, толугу менен фантазияга бай аягын ойлоп табыңыз.','Piltidest arusaamine 📖','Ta puudutab raamatus tegelasi ja küsib: „Mida see teeb?“. Tema visuaalne taju on hämmastav! Kirjuta koos lapsega loetavale raamatule uus ja täiesti fantaasiarikas lõpp.'),
('3edbcdb0-49d0-4dd6-973b-d76b6099a642'::uuid,'Жыйноо марафону 🌪️','Үйдү тазалап бүткөнүңүз менен 10 мүнөттөн кийин кайра эле башаламан болуп калдыбы? Бүгүн башаламандыкка моюн сунуңуз. Диванга отуруп, кофеңизди ичип бүтмөйүнчө ордуңуздан жылбаңыз.','Koristusmaraton 🌪️','Koristasid just maja, aga 10 minutit hiljem näeb see välja nagu katastroofipiirkond? Täna alistu segadusele. Istu diivanile ja ära liiguta end enne, kui oled kohvi lõpetanud.'),
('10f8db02-014b-4a08-8d7a-e5cbbb260125'::uuid,'Терең уйкуга батыңыз. 😴','«Ак ызы-чуу» бөлүмүнөн чач кургаткычтын үнүн тандап, балаңыз тынч уктап жатканда, «Маанай күндөлүгүнө» сезимдериңизди жазып эс алыңыз.','Uinu sügavasse unne. 😴','Vali valgest mürast föönimüra ja samal ajal kui beebi rahulikult magab, lõõgastu, kirjutades oma tunded meeleolupäevikusse.'),
('dd6cc7ba-db6f-403b-93e6-2447dbb967dc'::uuid,'Тизме – бул тандоо эмес, зарылчылык 🛒','Балаңыздын 8 айлык майрамы үчүн жасалгаларды унутпаңыз! Өзүңүздү кыйнабаңыз – баарын дароо «Соода тизмесине» кошуп, өнөктөшүңүз менен макулдашып алыңыз.','Nimekiri pole valikuline, see on hädavajalik 🛒','Ära unusta kaunistusi beebi 8-kuuseks saamise tähistamiseks! Ära stressa – lisa kõik kohe ostunimekirja ja kooskõlasta partneriga.'),
('7227b833-2ecd-472c-a074-7273a66732d9'::uuid,'Тааныш жүздөр 🥰','Сиз бөлмөгө киргенде анын жүзүндөгү чоң, өзгөчө жылмаюуну көрдүңүзбү? Алар сизди жана өнөктөшүңүздү башкалардан айырмалай алышат. Бул талашсыз сүйүү – эң чоң мотивация.','Tuttavad näod 🥰','Oled näinud seda suurt ja erilist naeratust tema näol, kui tuppa astud? Ta eristab sind ja su partnerit kõigist teistest. See vaieldamatu armastus on suurim motivatsioon.'),
('3eea40c1-536e-46c3-bd20-2051d2e3ccae'::uuid,'Атасынын дипломатиялык чечими 👨‍👧','«Тамагыңды ичип бүт» деген өтүнүчүңүз кулак сыртында калып жатабы? Топту атасына өткөрүп бериңиз. Ал кашыкты учуп бараткан космос кемесине айландырганда, өжөрлүк сыйкырдуу түрдө жоголот. Эс алыңыз жана шоудан ырахат алыңыз.','Issi diplomaatiline lahendus 👨‍👧','Kas sinu palve „söö oma toit ära“ ei jõua kohale? Anna pall üle issile. Kui tema muudab lusika lendavaks kosmoselaevaks, kaob jonnakus imeväel. Lõõgastu ja naudi etendust.'),
('2cd12a68-4486-435f-ad24-55a11a2f62a2'::uuid,'Күнүмдүк тамактандыруу корутундусу. 🍼','Эмчек эмизүү убактыңызды тиркемедеги таймер менен өлчөп, «Тамактануу журналы» бөлүмүнөн тамактануу боюнча көрсөтмөлөрдү текшериңиз.','Päevane toitmise kokkuvõte. 🍼','Mõõda rinnaga toitmise kestust rakenduse taimeriga ja kontrolli toitmise juhiseid toitmise logi jaotisest.'),
('917836b6-b023-4945-8e64-bc144ba97f42'::uuid,'Жаңы үндөрдү ачуу! 🗣️','Алардын таттуу «аа» жана «куу» деген үндөрүн жаздырууну унутпаңыз! Тилдин эрте өнүгүүсү тууралуу көбүрөөк билүү үчүн биздин блогдорду окуңуз.','Uute helide avastamine! 🗣️','Ära unusta salvestada tema armsaid „aah“-hääli ja kudrutamist! Loe meie blogisid, et saada rohkem teada varajase keelearengu kohta.'),
('ac669cdb-bbf4-4741-8460-56b46118bbec'::uuid,'Иш үстүндөгү эртең мененки сүйлөшүүчү 💼','«Мен БУЛ көйнөктү эмес, ТИГИНИ кийем!» Күтүлбөгөн жерден сиз бала менен эмес, кичинекей юрист менен талашып жатасыз. Талашпаңыз; тескерисинче, аларга чечимди өздөрү кабыл алгандай сезим калтыруу үчүн эки тандоо сунуштаңыз.','Hommikune läbirääkija tööl 💼','„Ma ei pane SEDA särki, ma panen SELLE!“ Äkki sa ei vaidle lapsega, vaid väikese advokaadiga. Ära vaidle; paku talle hoopis kahte valikut, et anda talle illusioon, nagu ta teeks otsuse ise.'),
('076945c8-0a00-4e34-b0d0-2a0bb6a70d19'::uuid,'Уйку тартиби өзгөрүп жатабы? 😭','Түн ортосунда ойгонуп, уктагысы келбей жатабы? Ачууланбаңыз. Себебин түшүнүүгө аракет кылыңыз, анан жөн гана жаныңызда экениңизди сездирип, акырын сылап, кайра уктап кетишин сабырдуулук менен күтүңүз.','Kas unegraafik muutub? 😭','Ärkab keset ööd ja ei taha magada? Ära vihasta. Püüa mõista põhjust, seejärel lihtsalt lase tal tunda oma lähedust, paita teda õrnalt ja oota kannatlikult, kuni ta uuesti uinub.'),
('d31b874f-e957-475e-a461-b294c96db59f'::uuid,'Дагы эле уктай элексизби? ⏱️','Уйкунун жалпы үлгүсүн жана күнүмдүк муктаждыктарын талдоо үчүн ар бир ойгонууну уйку трекерине жазып туруңуз.','Kas oled öösel ikka üleval? ⏱️','Salvesta iga ärkamine uneseiresse, et analüüsida tema üldisi uneharjumusi ja igapäevaseid vajadusi.'),
('d491dc2d-f6b9-49dd-8461-5cbffee476e5'::uuid,'Өзүңүзгө артыкчылык бериңиз, апаке! 🥗','Сиздин энергияңыз абдан маанилүү, апа! Аялдар үчүн дени сак рецепттерибизден витаминге бай тамакты тандап, күчүңүздү калыбына келтириңиз.','Sea ennast esikohale, emme! 🥗','Sinu energia on nii oluline, emme! Taasta oma jõud, valides vitamiinirikka eine meie naistele mõeldud tervislike retseptide hulgast.'),
('3d9ffa52-2fa2-4130-82de-58bdbc77e7b6'::uuid,'Аба ырайынын сюрприздери ⛅','Сейилдөөгө чыгасызбы? Күтүлбөгөн аба ырайы сизди даярсыз калтырып, кичинекейиңизди үшүтпөсүн. Терезеден карап эле божомолдобоңуз; сырттагы желге ылайыктуу кийимди табуу үчүн биздин «Аба ырайы жана кийим» жардамчыбызды колдонуңуз жана ишенимдүү чыгыңыз.','Ilmaüllatused ⛅','Lähed jalutama? Ära lase ettearvamatul ilmal end üllatada ja last külmetada. Ära ainult aknast välja vaadates oleta; kasuta meie ilma- ja riietumisabilist, et leida õue tuule jaoks ideaalne riietus ja mine enesekindlalt välja.'),
('50a3f6bc-f0a4-4606-972d-9c8a2cc70695'::uuid,'Эркин оюндун пайдасы 🧸','Аны ар мүнөт сайын көңүлүн ачууга, ага оюндарды ойлоп табууга милдеттүү эмессиз. Зеригүү – балдар үчүн чыгармачылыктын биринчи тепкичи. Бөлмөдө өз алдынча бир нерселерди ачып көрсүн.','Vaba mängu eelised 🧸','Sa ei pea teda igal minutil lõbustama ega talle mänge välja mõtlema. Igavlemine on laste jaoks loovuse esimene samm. Lase tal toas omaette midagi avastada.'),
('6ca1ad26-9f01-4a3a-9164-e9f0d68cc33c'::uuid,'Оюңузда эмне бар? 🤖','Түн ортосунда болсо да, Anacan AI жардамчыбыздан каалаган сурооңузду сурап, эксперттик колдоо алыңыз.','Mis sul mõttes on? 🤖','Isegi keset ööd võid küsida meie Anacan AI-abiliselt mis tahes küsimuse ja saada asjatundlikku tuge.'),
('f710f746-b942-4fd7-a8ca-dd9b5a248195'::uuid,'Жалаяк көзөмөлдөгүчүн текшерип көрөлү. 🧷','Балаңыз жетиштүү тамактанып жатканын текшерүү үчүн анын күнүмдүк жалаяк алмаштыруу санын Anacan''га жазып туруңуз.','Kontrollime mähkmete jälgijat. 🧷','Märgi beebi igapäevane mähkmete arv Anacanis, et veenduda, kas ta saab piisavalt süüa.'),
('0e8938b3-51a2-479f-a598-94b98e255136'::uuid,'Сатып алуулар тизмесинде ката! 🛒','Азык-түлүк дүкөнүнө барганда дайыма бир маанилүү нерсени унутуп каласызбы? Тиркемедеги соода тизмеси функциясы жардамга келет! Керектүү нерселердин баарын жазып коюңуз, өнөктөшүңүз жумуштан кайтып келе жатып, аларды так алып келе алат.','Otsa said! Ostunimekiri 🛒','Kas unustad toidupoodi minnes alati selle ühe olulise asja? Rakenduse ostunimekirja funktsioon on siin, et aidata! Pane kirja kõik vajalik ja su partner saab selle täpselt töölt tulles kaasa osta.'),
('2b8de8fb-82bc-4b54-a795-1fffd716ddd5'::uuid,'Дене тили аркылуу баарлашуу 🗣️','«Кеттикпи?» дегенде алар колдорун көтөрүшөт же каалабаганда башын катуу чайкашат. Алардын түшүнүүсү абдан өстү! Аларга көптөгөн бекемдөөчү сөздөр менен жооп бериңиз.','Kehakeele kaudu suhtlemine 🗣️','Kui ütled „lähme?“, tõstab ta käed või raputab energiliselt pead, kui ta midagi ei taha. Tema arusaamine on hüppeliselt kasvanud! Vasta talle rohke jaatava sõnavaraga.'),
('db645804-58ab-429b-bd1f-cae1d65c9e1e'::uuid,'Музыка менен уйкуга өтүү 🎶','Кечинде пайда болгон түшүнүксүз ыйлоолор үчүн, аларды жагымдуу классикалык музыка менен токтотууга аракет кылыңыз. Бул жөнөкөй, бирок эффективдүү ыкма көп учурда кереметтерди жаратат жана бөлмөгө толук тынчтык алып келет.','Uinumine muusika saatel 🎶','Nende seletamatute õhtuste jonnihoogude puhul proovi need katkestada õrna klassikalise muusikaga. See lihtne, kuid tõhus nipp toimib sageli imeliselt ja toob tuppa täieliku rahu.'),
('4144a3ff-720b-4a72-a2d5-5866dd12fa04'::uuid,'Күн тартиби өзгөрүп жатабы? ⏱️','Уктоо убактысы бир сааттан ашып жатабы? Уйку графигиңизди текшериңиз. Балким, күндүзгү уйкуну кыскартып, түнкү уйкуну эртелетүүгө убакыт келгендир.','Kas rutiin muutub? ⏱️','Kas magamaminek võtab rohkem kui tunni? Kontrolli oma unegraafikut. Võib-olla on viimane aeg lühendada päevaund ja nihutada magamaminek varasemaks.'),
('df56b34d-b5f8-476f-a65e-11a244242a2f'::uuid,'Уйку алдындагы тартип. 🛁','Сууга түшүрүңүз, тамактандырыңыз жана уйку таймерин иштетиңиз. Баары пландагыдай жана үзгүлтүксүз өтсүн!','Õhtune rutiin. 🛁','Vannita, toida ja käivita unetaimer. Las kõik kulgeb sujuvalt ja plaani järgi!'),
('2776b020-9972-4e23-acb7-6a529664582d'::uuid,'Сиздин үнүңүздү угуп жатат! 👂','Алар менен көп сүйлөшүп, көз караштарыңызды көп алмашыңыз. «Блогдор» бөлүмүнөн ар кандай өнүктүрүүчү көнүгүүлөрдү табыңыз.','Kuulab sinu häält! 👂','Räägi temaga sageli ja loo palju silmsidet. Avasta erinevaid arendavaid tegevusi blogide jaotisest.'),
('556e8775-c182-4e9f-b2c6-f0cf109ff616'::uuid,'Жаныбарларды тууроо 🐶','Жөн эле үндөрдү чыгарбастан, иттей сойлоп, мышыктай сүйкөнүп жатабы? Дене тили жана фантазия биригип жатат. Килем үстүндөгү бул оюнга чоң энергия менен кошулуңуз!','Loomade matkimine 🐶','Ei tee ainult hääli, vaid roomab nagu koer ja hõõrub nagu kass? Kehakeel ja kujutlusvõime saavad kokku. Ühine temaga selles mängus vaibal suure energiaga!'),
('b521243e-fc9e-4c87-849b-f17e742b8529'::uuid,'Күндүзгү уйку кризиси 🥱','Уктагысы келбей ыйлап жатабы? 3 жаштын тегерегинде кээ бир балдар уйку менен күрөшө башташат. Урушпастан, «Тынч убакыт» деп жарыялаңыз жана аларга төшөгүндө оюнчуктар менен тынч ойноону сунуштаңыз.','Uinakukriis 🥱','Ei taha magama minna ja nutab? Umbes 3-aastaselt hakkavad mõned lapsed une vastu võitlema. Võitluse asemel kuuluta välja „vaikne aeg“ ja soovita tal voodis vaikselt mänguasjadega mängida.'),
('72abc90e-b301-468a-9629-3f3bb7949709'::uuid,'Бала багуу боюнча суроолоруңуз барбы? 🤖','Anacan коомчулугу сизди соттобой угат жана эң ылайыктуу кеңештерди берет.','Kas sul on beebihooldusest küsimusi? 🤖','Anacani kogukond kuulab sind ilma hinnanguteta ja annab kõige sobivamat nõu.'),
('9d29683b-c9aa-4b14-81df-782b8e1da8f5'::uuid,'Уйку көйгөйү жана караңгыдан коркуубу?','Бөлмөнү толугу менен караңгылатып, колуңуз менен дубалга куштун же иттин көлөкөсүн түшүрүңүз. Коркунучту кызыктуу оюнга айландыруу менен балаңыздын караңгылык менен достошуусуна жардам бериңиз.','Unehäired ja hirm pimeduse ees?','Tee tuba täiesti pimedaks ja tee kätega seinale linnu- või koeravarje. Aita lapsel pimedusega sõbraks saada, muutes hirmu lõbusaks.'),
('a452ae82-775c-477d-b99f-ddd24ddd54fa'::uuid,'Тамактануу белгилери 🥣','Кичинекейиңиз эки кашык жеп, тоюп калганын айтып, отургучунан секирип кетеби? Аны мажбурлабаңыз. Тамак менен дени сак мамиле түзүү, тарелкасын тазалатуудан алда канча маанилүү. Алар чындап ачка болгондо тамак сурашат.','Söömisemärguanded 🥣','Sinu pisike võtab kaks lusikatäit, teatab, et on täis, ja tormab söögitoolist minema? Ära sunni teda. Tervisliku toidusuhte kujundamine on palju tähtsam kui taldriku tühjaks söömine. Ta küsib süüa, kui on tõeliselt näljane.'),
('aa995666-2118-43a4-9171-858348f38b54'::uuid,'Сүрөттүү окуялар 📖','Китептен жаныбарларды же балдарды көргөндө, аларды кармап «Алар эмне кылып жатышат?» деп сурашабы? Алардын визуалдык кабыл алуусу укмуш. Каармандар жөнүндө алар менен бирге терең жана күлкүлүү окуяларды ойлоп табыңыз.','Pildilood 📖','Kui ta näeb raamatus loomi või lapsi, kas ta puudutab neid ja küsib: „Mida nad teevad?“. Tema visuaalne taju on hämmastav. Mõtle koos temaga tegelaste kohta sügavaid ja naljakaid lugusid.'),
('427917df-21f2-46c9-a030-52d511e37ce5'::uuid,'Күнүмдүк отчет. 📊','Балаңыз бүгүн канча уктады жана канча жолу тамактанды? Тиркемедеги диаграммалардан бүгүнкү жалпы статистиканы карап көрүңүз.','Päevaaruanne. 📊','Kui palju beebi täna magas ja mitu korda sõi? Vaata tänast üldstatistikat rakenduse graafikutelt.'),
('90341333-a47d-4dc8-b1bb-8fcf07c769b0'::uuid,'Атасынын кызыктуу мимикалары 🤡','Баланы күлдүрүүнүн эң тез жолу – атасынын күлкүлүү үндөрдү чыгарып, бет кубулуштарын жасоосу. Бүгүн кечинде фондо эс алып, ал шаңдуу күлкүлөрдүн үнүнөн ырахат алыңыз.','Issi naljakad näod 🤡','Kiireim viis beebi naerma ajada on see, kui issi teeb naljakaid hääli ja nägusid. Täna õhtul lõõgastu taustal ja naudi nende rõõmsate kilgete heli.'),
('d4f1084b-2a25-422f-954c-038d4cf53bd2'::uuid,'Форумда адашып калбаңыз 🤖','Кошумча тамактарды киргизүүдө «Бул тамакты берсе болобу?» деген сыяктуу күмөн саноолоруңуз барбы? Сааттап издөөнүн кажети жок – Anacan AI суроолоруңузга чөнтөгүңүздөгү санарип педиатр сыяктуу жооп берсин.','Ära eksi foorumis ära 🤖','Kas sul on kahtlusi tahke toidu tutvustamisel, näiteks „kas seda toitu on ohutu anda“? Pole vaja tunde otsimisele kulutada – lase Anacan AI-l vastata oma küsimustele nagu digitaalne lastearst sinu taskus.'),
('9a0661d6-3164-4575-bc05-58b2efdd3f26'::uuid,'Өз окуясын айтып берсин 📖','Китепти бүгүн четке коюңуз. Окуяны алар айтып берсин! Фантазиянын бул сонун өнүгүүсүн колдоо үчүн Anacan AI''дан диалогдук сунуштарды сураңыз.','Lase neil oma lugu jutustada 📖','Pane raamat täna õhtul kõrvale. Las tema räägib loo! Küsi Anacan AI-lt dialoogiideid, et toetada seda imelist kujutlusvõime arengut.'),
('11c30298-2c39-4c7f-bfc1-dcf22c8e2ebc'::uuid,'Эне үчүн мейкиндик ☕','Үйдө отуруп чарчадыңызбы? Эс алып, өзүңүзгө кичинекей дата тартуулай турган, коляска менен кирүүгө ыңгайлуу тынч кафени табуу үчүн «Апалар үчүн ыңгайлуу жайлар» бөлүмүн карап чыгыңыз.','Aeg emale ☕','Tunned end kodus olemisest kurnatuna? Sirvi meie „emmesõbralike kohtade“ nimekirja, et leida vaikne, vankrisõbralik kohvik, kus saad lõõgastuda ja endale väikese kohtingu lubada.'),
('66c8660e-b8ca-4046-9e3f-578e25572ec7'::uuid,'Таштанды челегин изилдөө 🗑️','Полдон же килемдин четинен эмне тапса да, алар чоң кызыгуу менен изилдешет. Капа болбоңуз жана баарын колунан жулуп албаңыз; алар – изилдөөчү. Болгону, жутуп алууга мүмкүн болгон нерселерден сак болуңуз.','Prügikasti avastamine 🗑️','Kõike, mida nad põrandalt või vaiba servast leiavad, uurivad nad suure huviga. Ära mine närvi ja ära kisu neil kõike käest; nad on väikesed avastajad. Ole lihtsalt ettevaatlik esemetega, mida võib alla neelata.'),
('8d417480-194b-431c-987a-b0b5216ea151'::uuid,'Бүгүнкү сыйкырдуу жомоктор 🪄','«Акылдуу жомоктордо» бир нече күндөн кийин 8 айлык боло турган улуу баатыр жөнүндө жомок түзүңүз. Бул сыйкырдуу жомок түнкү тынчтыкты толтурсун.','Lummavad lood tänaseks 🪄','Loo „Nutikates lugudes“ muinasjutt suurest kangelasest, kes saab juba mõne päeva pärast 8-kuuseks. Las see maagiline lugu täidab öise vaikuse.'),
('7a0d5b5d-2b7e-42a8-a73b-a50ead526d05'::uuid,'Тынчтык жана кофе 🤫','Алар уктап калышты! Идиш жуугучту бошотуунун ордуна, бөлмөнүн тынч караңгылыгында отуруңуз. Үн мониторун иштетиңиз, айлана-чөйрөнү текшериңиз жана 15 мүнөттүк тынчтыктан ырахат алыңыз.','Vaikus ja kohv 🤫','Nad magavad! Selle asemel, et nõudepesumasinat tühjendada, istu toa vaikuses ja hämaruses. Lülita sisse beebimonitor, kontrolli ümbrust ja naudi 15 minutit vaikust.'),
('f72fbb7e-431d-4f4b-9a73-06637ff7bd68'::uuid,'Кемчиликсиздик — бул уламыш 🛑','Бүгүн баары пландагыдай болбой калдыбы? Өзүңүздү жемелебеңиз. Сиз социалдык тармактардагы жасалма сүрөттөр эмес, чыныгы энесиз. Балаңызга болгону СИЗ керек.','Täiuslikkus on müüt 🛑','Kas täna ei läinud miski plaanipäraselt? Ära ole enda vastu liiga karm. Sa oled päris ema, mitte sotsiaalmeedia filtreeritud illusioon. Sinu laps vajab ainult SIND.'),
('61ffa498-18cc-4858-987c-676f525f467c'::uuid,'Эмоционалдык жүктөн арылыңыз 📝','Оор күн болдубу? Бардык стрессиңизди Маанай күндөлүгүңүзгө төгүңүз. Бардык энелер мындай кыйынчылыктарды башынан өткөрүшөт; сиз эч качан жалгыз эмессиз.','Vabane emotsionaalsest koormast 📝','Kas oli raske päev? Vala kogu oma stress välja meeleolupäevikusse. Kõik emad kogevad selliseid väljakutseid; sa pole kohe kindlasti üksi.'),
('3cf29d40-9703-4e58-8a17-b7e68f86c3fa'::uuid,'Кам көрүүбү же оюн убактысыбы? 🧸','Биздин Сунушталган өнүмдөр тизмесинен кичинекейиңиздин өнүгүүсүнө колдоо көрсөтүүчү коопсуз өнүмдөрдү оңой табыңыз.','Hooldus või mänguaeg? 🧸','Leia meie soovitatud toodete nimekirjast hõlpsasti ohutud tooted, mis toetavad sinu pisikese arengut.'),
('c82d9568-ae94-4492-9789-4621c2dbcabc'::uuid,'Оюнчугумду бербейм! 🧸','Колундагы нерсени алганда алар нааразы болуп, катуу ыйлап жатышабы? Алардын ээлик кылуу сезими жана инсандыгы калыптанып жатат. Бул абдан табигый психологиялык этап, ага каршы чыкпаңыз.','Ma ei jaga oma mänguasja! 🧸','Kas nad protestivad ja nutavad valjult, kui sa neil midagi käest võtad? Nende omanditunne ja iseseisvus arenevad. See on väga loomulik psühholoogiline etapp, ära võitle selle vastu.'),
('f865873b-dd5e-4259-93bf-a8d4ef0dc1b0'::uuid,'Жашыл жашылчаларга каршылык 🥦','Кичинекейиңиз тарелкасындагы көк чөптөрдү ыргытып жатабы? Тамактануу убактысын согуш майданына айлантпаңыз. Жашыруун жашылчалары бар үй шартында жасалган кекстердин ден соолукка пайдалуу рецепттерин табыңыз жана керектүү витаминдерди байкатпай бериңиз.','Rohelise köögivilja protest 🥦','Kas su pisike loobib rohelist toitu taldrikult minema? Ära muuda söögiaega lahinguväljaks. Avasta meie tervislikud retseptid köögiviljadega muffinitele ja peida need vajalikud vitamiinid märkamatult toidu sisse.'),
('e6e49938-5987-45e7-8021-a8d016100be4'::uuid,'Өзүңүздү кандай сезип жатасыз? 💖','Бүгүн чарчадыңызбы же энергияңыз ташып жатабы? Маанай күндөлүгүңүздү ачып, күнүңүз кандай өткөнүн жазып коюңуз.','Kuidas sa end tunned? 💖','Kas tunned end täna väsinuna või energilisena? Ava oma meeleolupäevik ja märgi üles, kuidas su päev möödus.'),
('814305c3-77b7-491e-ae0f-134875923d1a'::uuid,'Кайсы тараптан эмиздиңиз? 🤱','Anacan таймери кайсы эмчекти акыркы жолу – оңбу же солбу – колдонгонуңузду көзөмөлдөйт, андыктан сиз эстеп калуунун кажети жок. Эми эмизүүнү баштаңыз!','Kummalt poolt sa toitsid? 🤱','Anacani taimer peab järge, kummast rinnast sa viimati toitsid – kas paremast või vasakust –, nii et sina ei pea seda tegema. Alusta toitmist nüüd!'),
('00bb1bab-f1b2-408a-929e-869ffd6367c6'::uuid,'Шыбырдын сыйкыры 🌙','Бөлмөдөгү жарыкты толугу менен өчүрүңүз. Жанына жатып, күн ичинде болгон окуяларды өтө акырын, кулагына шыбырап айтып бериңиз. Шыбыроо — мээни уйкуга даярдоочу эң табигый жана тынчтандыруучу ыкма.','Sosinate võlu 🌙','Kustuta toas tuled täielikult. Heida lapse kõrvale pikali ja sosista talle väga vaiksel häälel, mis päeva jooksul juhtus. Sosistamine on kõige loomulikum ja rahustavam meetod aju uneks ettevalmistamiseks.'),
('6948f738-9261-43c8-87d9-90b884505db8'::uuid,'Брокколи детектив 🥦','Алар тарелкасындагы жашылчаларды «байкап калып», четке түртүп жатышабы? Эми аларды жашыруу өнөрүн өздөштүрө турган убакыт келди. Дени сак тамактар бөлүмүнөн жашылчаларды пюре кылып, даамдуу котлеттердин ичине катып коюунун амалдарын табыңыз.','Brokolidetektiiv 🥦','Kas nad „avastavad“ taldrikul rohelisi köögivilju ja lükkavad need kõrvale? On aeg omandada maskeerimiskunst. Tervislike retseptide jaotisest leiad nutikaid viise köögiviljade püreestamiseks ja maitsvatesse lihapallidesse peitmiseks.'),
('910b6936-83b0-441d-abe5-33c85153dffe'::uuid,'Таңкы жылмаюулар! 😊','Алардын социалдык жылмаюусу күнүңүздү нурландырып жатат! Бул кубанычты түбөлүккө сактап калуу үчүн ымыркайдын фотосессиясын уюштуруңуз.','Hommikused naeratused! 😊','Nende sotsiaalsed naeratused muudavad su päeva säravamaks! Jäädvusta see rõõm igaveseks beebifotoseansi abil.'),
('fcecf920-146e-4152-abc5-066ce8392fd8'::uuid,'Тынчтандыруучу үн терапиясы. 🎶','Эгерде ымыркайыңыздын ичи желдеп же тынчсызданып жатса, «Ак ызы-чуу» (White Noises) бөлүмүндөгү жүрөктүн согушунун үнү аны эненин курсагындагыдай эле заматта тынчтандырат.','Rahustav heliteraapia. 🎶','Kui beebil on gaasivalud või ta on rahutu, rahustab südamelöökide heli „Valgest mürast“ teda silmapilkselt, täpselt nagu emaüsas.'),
('c7ff87eb-a94f-4bb4-85c6-085ae172efe9'::uuid,'Кичинекей композитордун алгачкы концерти 🎤','Алар оюнчуктарын тизип жатып, өзгөчө сөздөр жана өзгөчө ыргак менен ыр ыңылдап жатышабы? Чыгармачылыктын бул учурун үзбөңүз! Аны «Өсүү трекерине» алардын алгачкы композициясы катары жазып алыңыз.','Väikese helilooja esimene kontsert 🎤','Kas nad ümisevad mänguasju sättides omaette laulu, millel on kordumatud sõnad ja eriline rütm? Ära katkesta seda loovuse puhangut! Salvesta see nende esimese heliteosena arengupäevikusse.'),
('331b6c40-0fb5-4851-9134-928632566339'::uuid,'Жаратылышка чыгуу планы ⛅','Бул төрт дубал экөөңүздү тең бир аз кыжырдантып жатабы? Аба ырайы жана кийим тандоо куралын текшерип, тез эле кийинип, сейил бакка жөнөңүздөр. Таза аба наристенин эң катуу чыргоолугун дароо басаңдата алат.','Plaanime loodusesse minna ⛅','Kas need neli seina muudavad teid mõlemaid pisut ärevaks? Kontrolli ilma ja riietuse tööriista, pane end kiiresti valmis ja suundu parki. Värske õhk võib silmapilkselt leevendada ka kõige ägedamaid väikelapse jonnihooge.'),
('1ef4e046-ea34-4d3c-b7c9-53017c12e5ae'::uuid,'Күндүн аягында эс алыңыз. 🛁','Өзүңүзгө бир аз убакыт бөлүңүз жана бүгүн Маанай күндөлүгүнө ички сезимдериңизди жазып, жүгүңүздү жеңилдетиңиз.','Lõõgastu pärast pikka päeva. 🛁','Võta aega iseendale ja kergenda oma koormat, kirjutades oma sisemised tunded täna meeleolupäevikusse.'),
('818c91c1-bd54-42c5-8ac8-1505ae1830ab'::uuid,'Коомдук жылмаюулар! 😊','Анын ширин жылмаюусу бардык чарчооңузду таратат.','Sotsiaalsed naeratused! 😊','Nende armas naeratus paneb kogu su väsimuse sulama.'),
('56824801-bf77-4597-b1ce-5aa469fe1db9'::uuid,'Алтынга тете тынчтык 🤫','Үйдөгү ызы-чуу акыры басылып, ал катуу уйкуга кетти. Үн өлчөгүчтү ачып, бөлмөнүн тынчтык деңгээлин (децибел) текшериңиз да, 15 мүнөт бою эч кандай экранга карабастан, бул алтын тынчтыкка чөмүлүңүз.','Kuldne vaikus 🤫','Kodune kaos on lõpuks vaibunud ja nad on sügavasse unne vajunud. Ava helimõõtja, kontrolli toa vaikuse taset (detsibellides) ja sula 15 minutiks sellesse kuldsesse vaikusse, ilma et vaataksid ühtegi ekraani.'),
('7614704a-6622-4005-bcc5-442f422f2e2c'::uuid,'Кичинекей модачы 👗','Ал шымын башына кийип алып, бөлмөдө сыймыктануу менен басып жүрөбү? Кийлигишпеңиз. Бул күлкүлүү тажрыйбалар – анын эркиндикке жана жекеликке болгон умтулуусу. Ооба, бул кызыктай көрүнүшү мүмкүн, бирок бул ирмемдер абдан баалуу.','Väike moeguru 👗','Kas nad jalutavad uhkelt toas ringi, püksid peas? Ära sekku. Need koomilised katsed on nende viis otsida vabadust ja iseseisvust. Jah, see võib tunduda naljakas, kuid need hetked on väärtuslikud.'),
('8805c85d-beba-4d76-905f-2991bc6002f2'::uuid,'Горшокко үйрөтүүдөгү ийгилик 🚽','Ал зарылдыкты сезип, түбөккө өз алдынча чуркап бара жатабы? Бул чоң жеңиш!','Potitreeningu võit 🚽','Kas nad tunnevad vajadust ja jooksevad ise potile? See on suur võit!'),
('8d26cab1-ebfd-469f-9ae0-aa66e0f36761'::uuid,'Уктай албай жатасызбы? 🌙','Бөлмөнү караңгылатып, балаңызды терең уйкуга даярдоо үчүн White Noises бөлүмүнөн океан толкунунун добушун тандаңыз.','Kas uinumine on raske? 🌙','Hämarda tuba ja vali „Valgest mürast“ ookeanilainete heli, et valmistada beebi ette sügavaks uneks.'),
('92c57c1c-b876-4895-9dd9-de2d4fc5b8a4'::uuid,'Таза абада сейилдөө убактысы! 🌳','Таза абада сейилдөө балаңыздын өнүгүүсү жана бейпилдиги үчүн абдан маанилүү.','Aeg värske õhu kätte jalutama! 🌳','Värskes õhus jalutamine on beebi arengu ja rahuliku heaolu jaoks äärmiselt oluline.'),
('45e0f5b4-5219-47b6-9a9e-bcadb9ed774d'::uuid,'Дүкөндөгү башаламандык 🛒','Эс тутумуңузга ишенип дүкөнгө барып, бирок эң керектүү нерсени унутуп калып келдиңизби? Бардык муктаждыктарыңызды колдонмодогу «Сатып алуулар тизмесине» жазып алууну адат кылыңыз, санариптик эс тутумуңуз сизге жардамга келсин.','Toidupoe ajupesu 🛒','Kas usaldasid oma mälu, läksid poodi ja tulid tagasi, olles unustanud kõige olulisema asja? Tee endale harjumuseks kirjutada kõik vajadused üles rakenduse ostunimekirja ja lase digitaalsel mälul end päästa.'),
('8cab638c-2941-4e59-9d14-fa8e3dd46600'::uuid,'Көрүнбөгөн коноктор 👻','Алар дивандын бош жерин карап, сүйлөшүп, атүгүл көрүнбөгөн досуна чай куюп жатышабы? Кыялдагы достор доору кызып турган кези! Алар азыр өз дүйнөсүнүн сценаристи. Бул көрүнүшкө жылмаюу менен күбө болуңуз.','Nähtamatud külalised 👻','Kas nad vaatavad diivanil tühja kohta, lobisevad ja pakuvad isegi nähtamatule sõbrale teed? Kujuteldavate sõprade aeg on täies hoos! Nad on nüüd oma maailma stsenaristid. Naudi etendust naeratusega.'),
('b6825824-6eff-4740-b6c1-dc607b41b996'::uuid,'Оюнчуктарга умтулуу! 🧸','Алардын кичинекей ачылыштарын көрүү кандай сонун, ээ? Алар менен ойноп жатканда тарткан видеолоруңузду «Баланын альбомуна» жүктөңүз.','Sirutab mänguasjade järele! 🧸','Kas pole imeline jälgida nende väikeseid avastusi? Laadi beebialbumisse üles videod, mida nendega mängides teed.'),
('bc11c415-3d46-43c3-a8ed-0a204516e9ce'::uuid,'Дени сак эне, дени сак бала 🥑','Темир жана кальций запастарыңыз азайып бараткандай сезилип жатабы? Биздин пайдалуу тамактардын арасынан тез даярдалуучу, күч-кубат берүүчү рецептти тандап, ден соолугуңузду чыңдаңыз.','Terve ema, terve beebi 🥑','Kas tunned, et raua- ja kaltsiumivarud on madalad? Vali meie tervislike valikute hulgast energiat andev ja kiiresti valmiv retsept ning taasta oma jõuvarud.'),
('e386c8f2-240d-4f0f-adaf-e43ea496b8b2'::uuid,'Китептер дүйнөсүн изилдөө 📖','Кичинекейиңиз калың китептердин барактарын өз алдынча барактап, сүрөттөргө реакция кылып жатабы? Анын көрүү эс тутуму эң сонун өнүгүүдө! Бирге окуп, сүрөттөгү жаныбарлардын аттарын атаңыз.','Raamatute maailma avastamine 📖','Kas su pisike keerab iseseisvalt raamatulehti ja reageerib piltidele? Nende visuaalne mälu areneb imeliselt! Lugege koos ja nimetage piltidel olevaid loomi.'),
('d368c6ed-7184-4b38-b97e-6f9c7890966b'::uuid,'Суунун тынчтандыруучу күчү 🛀','Күнү бою чуркап жүрүү баланын да, сиздин да чарчаганыңызга себеп болду. Жылуу ванна — бул жөн гана гигиена эмес; бул чыңалууну басаңдатуучу жана күндүн терс энергиясын жууп кетүүчү суунун сыйкырдуу күчү.','Vee rahustav jõud 🛀','Kogu päeva ringijooksmine on kulutanud nii nende kui ka sinu närve. Soe vann ei ole ainult hügieeni jaoks; see on vee müstilise jõu kasutamine pinge leevendamiseks ja päeva negatiivse energia mahapesemiseks.'),
('052bbdef-be6b-4b3f-bf88-905af0d4abc5'::uuid,'Эс алууну унутпаңыз! 🛋','️ Кичинекейиңиз уктап жатканда, уйку таймерин иштетип, эч кандай күнөөлүү сезимсиз өзүңүзгө убакыт бөлүңүз.','Ära unusta puhata! 🛋','️ Kui su pisike magab, lülita sisse unetaimer ja võta lihtsalt süümepiinadeta aega iseendale.'),
('37a646c6-efce-4c74-8923-488fc7f72713'::uuid,'Атасынын ашканадагы кезеги 👨‍🍳','Эне болуу — бул жалгыз чуркоочу марафон эмес. Бул дем алыш күндөрү түшкү тамакты атасы даярдасын, ал эми сиз диванда эс алып, татыктуу тыныгуудан ырахат алыңыз.','Issi köögivahetus 👨‍🍳','Emadus ei ole soolomaraton. Lase issil sel nädalavahetusel lõunasöök valmistada, samal ajal kui sina diivanil puhkad ja väljateenitud pausi naudid.'),
('38899b21-6787-484d-901a-76cdc0b3deb6'::uuid,'Муну мен эле сезип жатамбы? 💬','Сиз аябай чарчап, сизди эч ким түшүнбөгөндөй сезилип жатабы? Тезинен Anacan коомчулугуна кайрылыңыз. Ал жерде сиз сыяктуу эле уйкусуз түндөрдү өткөрүп жаткан миңдеген энелер сизге күч бере турган «Мен сиз мененмин» деген билдирүүлөрдү жөнөтүшөт.','Kas ma olen ainus, kes nii tunneb? 💬','Kas oled täiesti kurnatud ja tunned, et keegi ei mõista sind? Pöördu kohe Anacani kogukonna poole. Seal saadavad tuhanded emad, kes kogevad samu unetuid öid, sulle „Olen sinuga“ sõnumeid, mis annavad sulle jõudu.'),
('e418c384-8ae3-455b-af14-a223e6595751'::uuid,'Убакытты токтотуу 📸','Алар бөлмөдө таттуу ойноп жатканда, дароо «Баланын фотосессиясы» бөлүмүн ачыңыз. 8 айга толуп жаткан наристеңиздин өзгөчө жүзүн атайын тема менен сүрөткө тартып калыңыз.','Peatame aja 📸','Samal ajal kui nad toas armsalt mängivad, ava kohe „Beebifotoseanss“. Jäädvusta see kordumatu, kasvav nägu, kui nad lähenevad oma 8. kuule erilise teemaga.'),
('4068a45c-e5fe-4a82-8c4b-a81d556f97cc'::uuid,'Бөлүшүү жакшы нерсе 💬','«Анын 8 айлык болуп калганына ишенбей турам!» деген ой сизди толкундатып жатабы? Бул кубанычтуу да, бир аз муңдуу да сезимди Anacan коомчулугундагы башка энелер менен бөлүшүңүз.','Hea on jagada 💬','Kas mõte „Ma ei suuda uskuda, et nad on juba 8-kuused!“ teeb sind emotsionaalseks? Jaga seda ilusat, magusmõru tunnet teiste emadega Anacani kogukonnas.'),
('90c5ba08-9d91-4669-8b26-99e0b48d4cf2'::uuid,'Сыноо жана ката 🧱','Алар эки оюнчук кубикти бири-биринин үстүнө коюуга аракет кылып жатышат, бирок алар кулап калууда. Анын кайрадан кылдаттык менен аракет кылып жатканын байкаңыз! Анын инженердик жана эксперименттик кичинекей аракеттерине сыймыктануу менен көз салыңыз.','Katse ja eksituse meetod 🧱','Nad üritavad kahte klotsi üksteise peale laduda, aga need kukuvad aina ümber. Vaata, kuidas nad ettevaatlikult uuesti proovivad! Jälgi vaikselt ja uhkusega nende väikeseid katsetusi ja inseneritööd.'),
('ed75b4ae-9703-498c-a857-64016faef6cc'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктар алдында бир саат мурун үйдөгү бардык жарыктарды жана экрандарды өчүрүңүз. Мелатонин тынч жана күүгүм чөйрөдө гана тез иштелип чыгат.','Hämarda tuled 🌙','Lülita tund enne magamaminekut majas välja kõik eredad tuled ja ekraanid. Melatoniini toodetakse kiiresti ainult rahulikus ja hämaralt valgustatud keskkonnas.'),
('8f5fde4a-3542-4bb1-be02-6df262d75b50'::uuid,'Баары жайындабы? 📝','Өзүңүздү кандай сезип жатасыз? Чарчадыңызбы же күч-кубатка толдуңузбу? Сиздин Anacan Маанай күндөлүгүңүз — эң ишенимдүү санариптик сырдашыңыз.','Kas kõik on korras? 📝','Kuidas sa end tunned? Väsinuna või energilisena? Sinu Anacani meeleolupäevik on su parim digitaalne usaldusisik.'),
('c34613c3-022a-46ef-a284-68eea41b09f7'::uuid,'Сценарийди өздөрү жазсын 🪄','Экөөңүздөр тең классикалык китептерден тажадыңыздар. Бул жолу «акылдуу жомоктордо» балаңызга окуянын аягын өзү тандоого мүмкүнчүлүк бериңиз. Уктар алдында «Кандай деп ойлойсуң, баатырга ким жардам берди?» деп сурап, анын фантазиясын иштетиңиз.','Lase neil stsenaarium kirjutada 🪄','Te olete mõlemad klassikalistest raamatutest väsinud. Lase seekord nutikates muinasjuttudes lapsel valida loo lõpp. Kaasa tema kujutlusvõime enne und küsimusega: „Kes sinu arvates kangelast aitas?“'),
('29d7734b-e03c-4396-8939-93b0dfe516dc'::uuid,'Эненин тамактануусу 🥗','Баланы тамактандыруу үчүн 3 башка меню ойлоп таап, бирок өзүңүз жолдо баратып эле шам-шум этип алдыңызбы? Биздин пайдалуу рецепттердин ичинен 10 мүнөттө даярдалуучу, витаминдерге бай салатты тандап, өзүңүзгө кам көрүңүз.','Ema toitumisvarud 🥗','Mõtlesid neile välja 3 erinevat menüüd, aga lõpuks haarasid ise midagi käigu pealt? Vali meie tervislike retseptide hulgast vitamiinirikas salat, mis valmib vaid 10 minutiga, ja tunne end väärtustatuna.'),
('f653426f-c687-4b5c-806e-74f597e75cf2'::uuid,'Баары өз нугунда экенине ынануу үчүн. 🤖','Түн ортосунда болсо да, сизди кызыктырган бардык суроолорду Anacan AI''дан сурасаңыз болот.','Et kõik oleks kontrolli all. 🤖','Võid Anacani tehisintellektilt küsida kõike, mis sul südamel on, isegi keset ööd.'),
('bdf82e6a-e184-465d-ab37-a709d395d1d4'::uuid,'Атасынын мимика театры 🤡','Сиздин кадимки ыкмаларыңыз иштебей калганда, атасынын тамашалуу үндөрү кырдаалды дароо жөнгө салат. Кечки ызы-чуу учурунда демилгени ага бериңиз да, четте туруп шайыр күлкүдөн ырахат алыңыз.','Issi pantomiimiteater 🤡','Kui su tavalised nipid enam ei tööta, võivad issi naljakad hääled päeva päästa. Õhtuste jonnihoogude ajal anna pall talle üle ja naudi rõõmsat naeru kõrvaltvaatajana.'),
('f6962d3f-b694-40e4-9faf-0cd32b36de3d'::uuid,'Кичинекей жардамчы 🧽','Алар колуңуздагы чаң сүрткүчтү жулуп алып жатышабы? Алар өздөрүн чоң жардамчы жана команданын бир бөлүгү катары сезгиси келет. Аларга нымдуу аарчы бериңиз. Алар тазалагандан көрө көбүрөөк булгашы мүмкүн, бирок алардын өзүнө болгон ишеними артат.','Väike abiline 🧽','Kas nad haaravad tolmulapi su käest? Nad tahavad tunda end suure abilisena ja meeskonna osana. Anna neile niiske lapp. Nad võivad teha rohkem segadust kui puhastust, aga nende ego on vaimustuses.'),
('3c5f5d9f-939f-4c7e-9bc8-1feef640d854'::uuid,'Сиздин эки айлык өнүгүү отчетуңуз. 📈','Акыркы 60 күндүн ичинде балаңыздын канчалык деңгээлде дени сак өскөнүн Салмак өлчөгүч, жалаяк жана тамактандыруу статистикасынан текшерип көрүңүз.','Sinu kahekuuse arenguaruanne. 📈','Vaata, kui tervislikult on su beebi viimase 60 päeva jooksul kasvanud, kontrollides kaalugraafikut, mähkmete ja toitmise statistikat.'),
('695238eb-b88d-4ffe-800b-82d23636ceb9'::uuid,'Үй жумуштарын ким жасайт? 🌪️','Эртеңки майрамга карата дагы бүтпөгөн иштериңиз барбы? Алар күтө турсун. Үй оокаттарын бүгүн жолдошуңузга тапшырыңыз. Ал эми өзүңүз эртеңки күн үчүн жакшылап эс алып алыңыз.','Kes teeb täna kodutöid? 🌪️','Kas sul on veel homseks väikeseks tähistamiseks asju ajada? Las need ootavad. Palu oma partneril täna kodutööd enda peale võtta. Sina aga puhka homseks.'),
('0574f644-1505-478c-8228-ceb707400249'::uuid,'Көз менен байланышуу маанилүү 🥂','Балаңыз күтүлбөгөн жерден эрте уктап калдыбы? Бул сейрек учурду үй жумуштарына коротпоңуз. Жолдошуңуз менен бетме-бет отуруп, телевизорду өчүрүп, бири-бириңиздердин көзүңүзгө карап, күнүңүздөр кандай өткөнү тууралуу жөн гана баарлашыңыздар.','Silmside on hädavajalik 🥂','Sinu laps uinus ootamatult vara! Ära kuluta seda haruldast hetke kodutöödele. Istu partneriga vastamisi, lülita teler välja ja lihtsalt küsige teineteiselt silma vaadates, kuidas päev möödus.'),
('1ed5f326-68dd-494e-a31c-2d3466644cd0'::uuid,'Энелер үчүн энергия булагы! 🥗','Калыбыңызга келишиңизди тездетүү жана сүтүңүздүн көбөйүшүнө колдоо көрсөтүү үчүн, биздин «Дени сак рецепттер» бөлүмүнөн витаминге бай тамактарды тандаңыз.','Energialaeng emadele! 🥗','Taastumise toetamiseks ja rinnapiima koguse suurendamiseks vali vitamiinirikas retsept meie tervislike retseptide alt.'),
('091c7303-14ec-4220-83cd-0ec1c91a3ce2'::uuid,'Тирүү диктофон 🎙️','Сиз айткан ар бир сөздү кайталап жатабы? Ал — сиздин жандуу күзгүңүз. Жанында айткан сөздөрүңүзгө жана көрсөткөн эмоцияларыңызга өзгөчө көңүл буруңуз; ал баарын сиңирип алат.','Elav salvesti 🎙️','Kas nad kordavad järele isegi kõige suvalisemat sõna, mis su suust tuleb? Nad on sinu elav peegel. Pööra erilist tähelepanu sõnadele ja emotsioonidele, mida nende läheduses väljendad; nad imevad kõik endasse.'),
('e60389be-4932-49bf-9ebd-d4caa963b145'::uuid,'Муздак кофе чындыгы ☕','Кофе куюп алып, үч сааттан кийин муздап калганда ичүү — энеликтин жазылбаган мыйзамы. Бүгүн муну өзгөртүңүз! Балаңызды оюнчуктары менен калтырып, кофеңизди 10 мүнөттүн ичинде ысык кезинде ичип алыңыз. Сиз буга татыктуусуз.','Jahtunud kohvi reaalsus ☕','Kohvi valamine ja selle kolm tundi hiljem jääkülmalt joomine on emaduse kirjutamata seadus. Täna tee muudatus! Jäta laps mänguasjadega omaette ja joo see kohv 10 minuti jooksul kuumalt ära. Sa oled seda väärt.'),
('59041ede-10ec-4754-8f5f-31f415db3701'::uuid,'Гулдуроо үндөрү көбөйүүдө! 🗣️','Балаңыздын сиз менен баарлашуу аракети күч алууда! Анын тил өнүктүрүүсүн колдоо үчүн «Блогдор» бөлүмүндөгү макалаларды окуп чыгыңыз.','Kukrutamine muutub sagedasemaks! 🗣️','Sinu beebi katsed sinuga suhelda sagenevad! Loe blogiartikleid, et toetada tema keelelist arengut.'),
('393a7a2a-b162-45e4-9577-0e4f2d088bf3'::uuid,'Жеңиш бийи 🥂','Бүгүн кечинде жолдошуңуз менен бирге 8 айлык чарчоо, көз жаш жана кубанычтуу күндөрүңүздү белгилеңиз. Шам жагып, бекем команда катары жетишкен ийгилигиңиздерди майрамдаңыздар!','Võidutants 🥂','Tähista täna õhtul koos partneriga 8 kuud väsimust, pisaraid ja rõõmu. Süüta küünal ja aplodeeri teie murdmatule meeskonnavõidule!'),
('4419f2fd-8e6f-4837-aa0e-9d571aac3895'::uuid,'Өткөнгө көз чаптыруу 📈','Кичинекейиңиздин канчалык чоңойгонун караңыз! Алгачкы күндөрдөгү назик коркуу сезимдери чоң ишенимге айланды. Бул 8 айды сыймыктануу менен басып өттүңүз! Сиз чындап эле укмуштуусуз!','Tagasivaade 📈','Vaata, kui kaugele su pisike on jõudnud! Algusaegade õrnad hirmud on asendunud tohutu enesekindlusega. Oled need 8 kuud nii uhkelt läbinud! Sa oled tõeliselt imeline!'),
('28610640-860d-43af-8a5a-381f751b562e'::uuid,'Эненин жашыруун бороону 🩸','Капысынан чарчоо, себепсиз ыйлагыңыз келип жатабы? «Этек кир календарыңызды» ачыңыз. Балким, бул ПМС белгилеридир. Өзүңүздү күнөөлөбөстөн, «Дени сак рецепттерден» магнийге бай тамак даярдап, денеңиздин муктаждыгына кулак салыңыз.','Ema salajane torm 🩸','Äkiline väsimus, seletamatu nutusoov? Ava oma tsüklikalender. Sul võib olla PMS. Ära süüdista ennast; selle asemel valmista tervislike retseptide hulgast magneesiumirikas suupiste ja kuula, mida su keha vajab.'),
('d7b0c908-0d97-40c6-a82a-c5283f30a1d8'::uuid,'Уйку тартибин көзөмөлдөңүз. ⏱️','Балаңыз уктаганда, уйку таймерин иштетип, анын күнүмдүк уйку нормасын аткарып жатканын талдап көрүңүз.','Jälgi unerežiimi. ⏱️','Kui beebi magab, käivita unetaimer ja analüüsi, kas ta täidab oma päevaseid unesoovitusi.'),
('5309698d-6050-4993-9a68-ab592375ed60'::uuid,'Шилекей агып жатат! 💧','Балаңыздын шилекейи азыр көбүрөөк бөлүнүп жаткан болушу мүмкүн.','Süljehoiatus! 💧','Sinu beebil võib nüüd süljeeritus suureneda.'),
('51272fb1-4e13-49cf-9f74-cdaa0749b5ed'::uuid,'Санарип педиатр 🤖','33 айлык бөбөгүңүздүн бою жана салмагы боюнча көрсөткүчтөр сизди кооптондуруп жатабы? Интернеттеги форумдардан коркунучтуу ооруларды издебеңиз; Anacan AI аркылуу так, ыкчам жана илимий негизделген маалыматтарды алыңыз.','Digitaalne lastearst 🤖','Kas su 33-kuuse lapse pikkuse ja kaalu tabel tekitas sulle äkki muret? Ära otsi hirmsaid haigusi veebifoorumitest; saa täpseid, kiireid ja teaduspõhiseid fakte Anacan AI-lt.'),
('2f4fbaac-dfe4-48b5-b844-6636c2bc201a'::uuid,'Сиздин чөнтөк тизмеңиз 🛒','Биринчи туулган күнгө торт заказ кылуу үчүн, Anacan тиркемесиндеги торт варианттары менен таанышып чыгыңыз.','Sinu taskunimekiri 🛒','Esimese sünnipäeva tordi tellimiseks vaata Anacanis saadaolevaid tordivalikuid.'),
('83d11db6-0443-4d69-8d55-9ea20f0cf905'::uuid,'Анын өсүшүн көзөмөлдөө! 📏','Кийинки жумадагы салмак жана бой маалыматтарын Салмакка көз салуу бөлүмүнө киргизип, алардын жеке өсүү графигин жаңыртып туруңуз.','Nende kasvu jälgimine! 📏','Uuenda lapse kasvutabelit, sisestades järgmise nädala kaalu- ja pikkusandmed kaalujälgijasse.'),
('b5429001-8d63-464c-9e9d-56aab19950f8'::uuid,'Моцарт эффектиси 🎶','Кечинде түшүнүксүз агрессия башталдыбы? Телевизорду өчүрүп, жарыкты басаңдатып, бөлмөдө жай классикалык музыка коюңуз. Суунун жана музыканын гармониясы атмосфераны сыйкырдуу түрдө өзгөртөт.','Mozarti efekt 🎶','Õhtuti on tekkinud seletamatu agressiivsus. Lülita teler välja, hämarda tuled ja pane toas mängima väga vaikne klassikaline muusika. Vee ja muusika harmoonia muudab õhkkonna võluväel.'),
('8510671a-e1a9-4df3-abde-5ad11cb9aee4'::uuid,'Канаттарын сынап көрүү 🧗‍♂️','Алар дивандан жаздыктарга секирип жатышат. Алар тартылуу күчүн жана өз эрдигин сынап жатышат. «Жок» деп айтуунун ордуна, бөлмөдө коопсуз секирүү аймагын түзүп бериңиз жана алардын энергиясын чыгаруусуна мүмкүнчүлүк бериңиз.','Tiibade proovimine 🧗‍♂️','Nad hüppavad diivanilt patjadele. Nad testivad gravitatsiooni ja oma julgust. Selle asemel, et öelda "ei", loo tuppa turvaline hüppetsoon ja lase neil see energia välja elada.'),
('8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0'::uuid,'Түнкү ыйдын маанисин чечмелөө 😭','Себепсиз ыйлоо абдан чарчатышы мүмкүн. Божомолдоону токтотуңуз; ыйдын артындагы жашыруун кабарды (оору, чарчоо) түшүнүү жана аларды тынчтандыруу үчүн Ыйды талдоо куралын колдонуңуз.','Öise nutu dešifreerimine 😭','Ilma nähtava põhjuseta nutuhood võivad olla kurnavad. Lõpeta oletamine; kasuta nutuanalüüsi tööriista, et mõista heli taga peituvat sõnumit (valu, väsimus) ja last rahustada.'),
('149e95b1-a682-4369-8b74-5827cc5d31dc'::uuid,'Сезимдериңизди бөлүшүүдөн тартынбаңыз. 📝','Чарчадыңызбы же энергияга толосузбу? Кандай сезимде болсоңуз да, бүгүн Маанай күндөлүгүнө сезимдериңизди жазып, жүгүңүздү жеңилдетиңиз.','Ära kõhkle oma tundeid jagamast. 📝','Väsinud või energiline? Ükskõik, kuidas sa end tunned, kergenda oma koormat, märkides täna oma emotsioonid meeleolupäevikusse.'),
('79b7fb29-fa37-4176-9ae5-409d73ee982e'::uuid,'Жолдогу ыңгайлуулук. ☕','Достор менен кофе ичкиңиз келеби? Үйдөн чыгардан мурун биздин «Энелер үчүн ыңгайлуу жайлар» картасын текшерип алууну унутпаңыз!','Mugavus liikvel olles. ☕','Soovid sõpradega kohvile minna? Ära lahku kodust ilma meie emadesõbralike kohtade kaarti kontrollimata!'),
('a4f7c95b-7fff-41b8-a6d4-80ab1d481977'::uuid,'Камуфляж чебери 🥦','Алар шорпосундагы жашылчаларды микроскоп менен издегендей кылдаттык менен терип жатышабы? Биздин дени сак тамактануу бөлүмүнөн жашылчаларды дээрлик байкалгыс кылып көрсөтө турган соус рецепттерин табыңыз. Чыгармачылык — эненин эң чоң сырдуу куралы.','Kamuflaažimeister 🥦','Kas laps nopib supist köögivilju välja nagu mikroskoobiga otsides? Leia meie tervislike retseptide alt kastmeretsepte, mis panevad köögiviljad peaaegu kaduma. Loovus on ema suurim salarelv.'),
('30d43616-cc93-4cce-b2c3-cdd876b6c9e5'::uuid,'Тиш щеткасы үчүн күрөш 🦷','Алар тиш щеткасын оозуна жакындатпай, өздөрү тазалаганга аракет кылып жатышабы? Муну күрөшкө эмес, оюнга айлантыңыз. Алгач алар сиздин тишиңизди тазаласын, андан кийин кезек сизге келсин.','Hambapesulahing 🦷','Laps ei lase hambaharja suu lähedalegi ja nõuab, et teeks seda ise? Muuda see mänguks, mitte lahinguks. Lase tal kõigepealt sinu hambaid pesta, siis on sinu kord.'),
('075bea5d-3ab7-4404-af70-89a3de20a0ff'::uuid,'Тез тизме 🛒','Кечээ үйдөгү керектүү нерселер түгөнүп калдыбы? Соода тизмеңизди ачып, сүт, жемиш жана башка керектүү нерселерди секунданын ичинде жазып, өнөктөшүңүздүн телефонуна жөнөтүңүз.','Kiire nimekiri 🛒','Kas sul said eile kodus esmatarbed otsa? Ava oma ostunimekiri, pane sekunditega kirja piim, puuviljad ja kõik muu vajalik ning saada see partneri telefonile.'),
('e32c4fc2-e649-4150-9d80-08ebdc4ae2e8'::uuid,'Өнүгүү баскычынан кийинки башаламандык 🌪️','Кечээки 8 айлыктын майрамынан кийин үйүңүз башаламан болуп калдыбы? Тазалоого шашпаңыз. Бүгүнкү күндү жөн гана эс алууга жана 8 айлык бөбөгүңүз менен жаңы оюнчуктарды ачууга арнаңыз.','Arenguetapi järgne kaos 🌪️','Kas kodu on pärast eilset 8 kuu pidu sassis? Ära kiirusta koristama. Pühenda tänane päev lihtsalt puhkamisele ja uute mänguasjade avastamisele koos oma 8-kuuse pisipõnniga.'),
('2c9fa500-5618-49b8-a232-965da7b82ef7'::uuid,'Үндү көзөмөлдөө 🤫','Бөбөгүңүз уктап кеткенден кийинки алгачкы жарым саат эң сезимтал учур болуп саналат. Айлана-чөйрөнү көзөмөлдөө үчүн үн мониторун колдонуңуз жана күтүлбөгөн катуу үндөрдөн, телевизордун же көчөнүн ызы-чуусунан сак болуңуз.','Helikontroll 🤫','Esimene pooltund pärast uinumist on kõige tundlikum aeg. Kasuta beebimonitori keskkonna kontrollimiseks ning väldi äkilisi helisid, teleri häält või tänavamüra.'),
('87a20850-e59a-4ee2-81e8-79c4b5808e7b'::uuid,'Мен Сизди угуп жатам! 🗣️','Бөбөгүңүз сизди кунт коюп угуп, окшош үндөрдү чыгарууга аракет кылып жатабы? Ал сиз менен сүйлөшүп жатат! Ага жылмайып жооп бериңиз жана бул баарлашууну кубаттаңыз.','Ma kuulen sind! 🗣️','Kas beebi kuulab sind tähelepanelikult ja püüab sarnaseid helisid teha? Ta räägib sinuga! Vasta talle naeratustega ja julgusta seda suhtlust.'),
('9c963f32-b147-4e84-aa9a-af699e50681f'::uuid,'Бүгүн чыдамыңыз түгөнүп жатабы? 🛑','Бул үчүн өзүңүздү күнөөлүү сезбеңиз. Интернеттеги жасалма идеалдардан алыс болуңуз. Сиз чыныгы энесиз, сезимдериңизди ачык билдирүүгө укугуңуз бар.','Kannatus hakkab katkema? 🛑','Ära tunne end selle pärast halvasti. Astu eemale internetiillusioonidest. Sa oled päris ema ja on okei oma emotsioone tunda.'),
('0cf5cff8-d958-4ec0-b6df-6f78457976fd'::uuid,'Дарыгердей акылдуу 🤖','8 айдан кийинки өнүгүү этаптары боюнча суроолоруңуз барбы? Интернеттен жооп издеп убара болбой, Anacan AI аркылуу педиатрлар тарабынан жактырылган, илимий негиздүү так жоопторду алыңыз.','Tark kui doktor 🤖','Kas sul on küsimusi arenguetappide kohta pärast 8. kuud? Ära eksi veebiotsingutesse – saa usaldusväärseid, teaduspõhiseid ja lastearstide heakskiidetud vastuseid Anacan AI-lt.'),
('77b45217-21e4-402a-b5dd-d0ee28c29f05'::uuid,'Кол менен жей турган тамактар 🥦','Бөбөгүңүз эми жөн гана пюре жегиси келбей, жашылчаларды өз колу менен кармагысы келип жатабы? Анын өз алдынча тамактануу аракетин колдоңуз. Ал жерди булгаса да, жанында болуп, аны көзөмөлдөп туруңуз.','Sõrmetoidud 🥦','Sinu beebi ei taha enam ainult püreestatud toitu, vaid soovib köögivilju oma kätega hoida! Toeta tema katseid ise süüa. Isegi kui see tekitab segadust, ole kindlasti tema kõrval ja jälgi teda.'),
('dd6d5f01-5a48-4f85-953e-c5e21662ae95'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкүсүн ойгонуу менен жалгыз күрөшпөңүз. Өнөктөшүңүздү да ойготуңуз; команда болуу – жоопкерчиликти тең бөлүшүү дегенди билдирет. Бүгүн түнү аны сооротуп, кайра уктатуу кезеги анда.','Issi öövahetus 👨‍🍼','Ära tegele öiste ärkamistega üksinda. Ärata ka oma partner; meeskonnaks olemine tähendab vastutuse võrdset jagamist. Täna on tema kord laps uuesti magama saada.'),
('918fe7fd-3c85-49ee-b337-c52aba217614'::uuid,'Балаңыз түнү бою сооронбой ыйлап жатабы? 😭','Бөбөгүңүздүн ыйын ''Ыйды талдоо'' функциясы менен угуп көрүңүз, бул жөн гана түнкү коркуу сезимиби же физикалык оорубу, аныктап алыңыз.','Kas beebi nutab öösel lohutamatult? 😭','Kuula heli nutuanalüüsiga, et teha kindlaks, kas tegemist on lihtsalt öise hirmuhoo või füüsilise valuga.'),
('b5dc2a4a-17b6-4c13-ad1b-8f6ccddc9f9b'::uuid,'Музыкага бийлөө 🎶','Шайыр музыка ойноп жатканда ал ыргагы менен термелип жатабы? Угуу жана кыймыл-аракет жөндөмдүүлүгүнүн байланышы эң сонун өнүгүп жатат! Шайыр ыр коюп, аны менен бирге бөлмөдө бийлеңиз.','Muusika saatel tantsimine 🎶','Kas laps õõtsub rütmis, kui mängib rõõmus muusika? Kuulmise ja motoorsete oskuste vaheline seos areneb suurepäraselt! Pane peale rõõmus laul ja tantsi koos temaga toas ringi.'),
('deba3d42-726a-4e83-bbbd-900d2aee20ad'::uuid,'Балаңыз тойдубу? Эми Сиздин кезегиңиз.','Биздин пайдалуу рецепттерден энергия бере турган тамак тандап алыңыз жана кеминде 10 мүнөт диванга жатып, күчүңүздү калыбына келтириңиз.','Beebi kõht täis? Nüüd on sinu aeg.','Vali meie tervislike retseptide hulgast energiat andev suupiste ja lae oma akusid, heites vähemalt 10 minutiks diivanile.'),
('7580f5d5-67e6-4fe8-b318-8dd1f6c00cd6'::uuid,'Эмоционалдык күндөлүк 📝','Өзүңүздү жалгыз жана чарчаңкы сезгенде, сезимдериңизди ''Маанай күндөлүгүнө'' жазыңыз. Бардык аялдар ушундай оор жолдорду басып өтүшөт; сиз күчтүүсүз жана мунун баарын жеңе аласыз!','Emotsioonide päevik 📝','Kui tunned end üksiku ja väsinuna, vala oma tunded meeleolupäevikusse. Kõik naised läbivad neid tormiseid teid; sa oled tugev ja sa saad sellega hakkama!'),
('90ae683e-61a6-4dd5-b894-186c95367ff3'::uuid,'Тиш эттери дагы эле кычышып жатабы? 🦷','Бөбөгүңүздүн манжалары дайыма оозундабы жана шилекейи көп агып жатабы? Муздатылган тиш чыгаргычтарды алып чыгуучу убакыт келди!','Kas igemed sügelevad ikka veel? 🦷','Kas lapse sõrmed on pidevalt suus ja ta ilastab palju? On aeg jahutatud närimisrõngad uuesti välja otsida!'),
('b9bfa71c-cf95-4768-adc9-c82fe1e676ac'::uuid,'Таза аба — дары 🌳','Бөбөгүңүз күн бою ыйлап, тынчсызданып жатабы? Чечими жөнөкөй: аба ырайын жана кийим тандоо куралын текшерип, аны коляскага салып, түз эле сейил бакка барыңыз. Жаратылыш – эң тез сооротуучу каражат.','Värske õhk on kui ravim 🌳','Kas su pisike on terve päeva nutnud ja viril olnud? Lahendus on lihtne: vaata ilma- ja riietustööriista, pane laps vankrisse ja suundu otse parki. Loodus on kiireim viis rahustamiseks.'),
('0a0b2a9c-f56c-4830-8b42-dd0901fc3b1d'::uuid,'Буюмду издөө оюну! 🧸','Оюнчугун жууркандын астына катып, аны өзү таап алышына мүмкүнчүлүк бериңиз.','Objekti püsivuse mäng! 🧸','Peida mänguasi teki alla ja lase lapsel see üles leida.'),
('998faa86-f9bb-47df-aa71-acba217766a9'::uuid,'Сиздин жумалык статистикаңыз даяр! 📊','Акыркы күндөрү уйку жана тамактануу сунуштарын канчалык деңгээлде аткарып жатканыңызды талдоо үчүн тиркемеге кириңиз.','Sinu iganädalane statistika on valmis! 📊','Logi rakendusse sisse, et analüüsida, kui hästi oled viimastel päevadel une- ja toitumissoovitusi järginud.'),
('2e5279b4-ad3c-4da7-866e-49a5932c0601'::uuid,'Оюнчугун алганда кыйкырып жатабы? 🧸','Анын ''меники'' деген сезими күчөп жатат. Бул мүнөздүн калыптанышындагы маанилүү этап.','Kas laps karjub, kui mänguasi ära võtta? 🧸','Tema omanditunne tugevneb. See on oluline osa iseloomu arengust.'),
('d2ac515d-c34a-47d7-a082-82f89c2863e8'::uuid,'Эне сүтү дагы деле эң пайдалуу! 🍼','Кошумча тамак киргизсеңиз да, бөбөгүңүздүн күнүмдүк сүт нормасын алуусун тамактануу таймери аркылуу көзөмөлдөп туруңуз.','Rinnapiim on endiselt parim! 🍼','Isegi lisatoiduga alustades veendu toitmistaimeri abil, et beebi saaks kätte oma igapäevase piimakoguse.'),
('32681963-7779-41a7-9090-772ca76143b7'::uuid,'Башаламандыкка уруксат 🌪️','Оюнчуктарды күн сайын кутуга салуудан тажадыңызбы? Бүгүн жыйноону токтотуңуз! Үйүңүз музей эмес, бул жашоо кайнаган жай. Башаламандыкка эмес, балаңыздын ачылыш жасап жаткандагы кубанычына көңүл буруңуз.','Luba endale segadust 🌪️','Oled väsinud samade mänguasjade iga päev kasti tagasi panemisest? Ära täna koristamisega vaeva näe! Sinu kodu pole muuseum, vaid elav ruum, kus toimub elu. Keskendu mitte segadusele, vaid oma lapse avastamisrõõmule.'),
('31a887b1-fde3-4a67-a32c-13cc6764d41e'::uuid,'Чогуу китеп окуңуз! 📖','Интерактивдүү жана түстүү китептер бөбөгүңүздүн көңүлүн абдан жакшы бурат. Бул билим берүүчү окуу көз ирмемдерин биздин блогдордогу кеңештер менен дагы да байытыңыз.','Lugege koos raamatut! 📖','Interaktiivsed ja värvilised raamatud köidavad tõesti su pisikese tähelepanu. Rikasta neid harivaid lugemishetki veelgi meie blogi nõuannetega.'),
('a82a604d-9504-4486-86ea-c38998236871'::uuid,'Акыркы жолу кайсы эмчегиңизди эмизгениңизди унутуп калдыңызбы? 🤱','Anacan таймери акыркы жолу кайсы эмчектен эмизгениңизди эсинде сактайт. Эмизип баштоо үчүн таймерди азыр иштетиңиз!','Unustasid, kummast rinnast viimati toitsid? 🤱','Anacani taimer jätab meelde, kummast rinnast sa viimati toitsid. Alusta toitmist taimeriga kohe!'),
('d7cab28d-37d6-4301-8e4d-28dfd96b83ab'::uuid,'Суу ичүү адатын калыптандыруу 💧','Кошумча тамак менен кошо суу берүүнү унутпаңыз. Кайсы чөйчөктөр ыңгайлуу экенин биздин ''Сунушталган товарлар'' бөлүмүнөн карап көрүңүз.','Veejoomise harjumuse kujundamine 💧','Ära unusta lisatoidu kõrvale vett pakkuda. Leia meie soovitatud toodete jaotisest, millised nokatassid on kõige sobivamad.'),
('6122dba2-692e-45e2-8027-9ab67ba2bf07'::uuid,'Кана эмесе, бөбөгүм! 👏','Ал кол чаап же колун сизге сунуп жатабы? Бул баарлашуунун эң сонун түрү. Аны кучактап алыңыз!','Tule, väike sõber! 👏','Kas laps plaksutab käsi või sirutab käed sinu poole? See on imeline suhtlusviis. Tee talle kalli!'),
('c555165e-a5c9-4e8c-9a72-cf4d0a16a367'::uuid,'Аталарга да мээрим керек! 👨‍🍼','Бөбөгүңүздүн атасы менен болгон таттуу жана шайыр көз ирмемдерин баалаңыз.','Issid vajavad samuti armastust! 👨‍🍼','Hoia neid armsaid ja lõbusaid hetki, mida beebi isaga jagab.'),
('a73ae95c-98a0-4201-9af1-960893ecd116'::uuid,'Убакытты токтотуу 📸','Ал абдан тез чоңоюп жатат... Уктап жатканда, анын таттуу, бейпил жүзүн сүрөткө тартып, эстелик катары сактап калыңыз.','Peatame aja 📸','Nad kasvavad nii kiiresti... Sel ajal kui laps magab, jäädvusta tema armas ja rahulik nägu fotole, et seda mälestusena hoida.'),
('b8c9eaea-1257-487d-8647-7c1cb6d70a3a'::uuid,'Сурооңуз барбы? 🤖','Бөбөгүңүздүн өнүгүүсү боюнча миңдеген суроолор оюңузду ээлеп жатабы? Anacan AI''дан сураңыз жана педиатрлар тарабынан тастыкталган так кеңештерди алыңыз.','Kas sul on küsimusi? 🤖','Kas su peas keerleb tuhat küsimust beebi arengu kohta? Küsi Anacan AI-lt ja saa täpseid, lastearstide poolt kinnitatud nõuandeid.'),
('500b7216-41e0-45a9-a2b9-20687055dfdc'::uuid,'Кезек атасында! 👨‍🍼','Күндүзгү чарчоо сиз үчүн жетиштүү. Балаңызды уктоого даярдоо, тишин жууп, пижамасын кийгизүү сыяктуу кечки иштерди жолдошуңузга тапшырып, өзүңүз четте отуруп жай гана чай ичип эс алыңыз.','Nüüd on issi kord! 👨‍🍼','Päevane väsimus on sinu jaoks juba piisav. Delegeeri lapse õhtune rutiin – hammaste pesemine ja pidžaamasse panemine – issile, samal ajal kui sina kõrvalt rahulikult teed naudid.'),
('19dff725-11f8-467a-b784-f2971b302ba0'::uuid,'250-күнгө даярдык! 🌟','Эртең чоң маареке! Туптуура 250 күн! Үйдө майрамдык маанай түзүп, бул сан менен сыймыктанууга даярданыңыз.','Valmistume 250. päevaks! 🌟','Homme on suur verstapost! Täpselt 250 päeva! Loo kodus väike pidulik õhkkond ja ole valmis selle numbri üle uhkust tundma.'),
('c304b9f3-2045-4d2f-b423-1096223f0f83'::uuid,'Бүгүн үй жыйноо жок 🛑','Абдан чарчадыңызбы? Бул тууралуу жолдошуңузга айтыңыз. Бүгүн тамак жасоонун кереги жок. Бүгүн — апалардын эс алуу күнү!','Täna koristamist ei toimu 🛑','Tunned end kurnatuna? Anna sellest partnerile teada. Täna kodus süüa ei tehta. Täna on emme vaba päev!'),
('e01d3a10-f5c2-40e8-8168-d7a86ab3c73d'::uuid,'Жомок эч качан бүтпөйт 📖','Бүгүн кечинде «Акылдуу жомоктор» бөлүмүнөн эр жүрөк жана акылдуу бала жөнүндө жомок айтып берип, тынч чөйрө түзүңүз.','Lugu ei lõpe kunagi 📖','Loo täna õhtul rahulik keskkond, mõeldes „Nutikate lugude“ abil välja jutuke vaprast ja nutikast lapsest.'),
('561e1f8b-1a7d-4ace-9ef9-bd3f43b083d2'::uuid,'250 күндү майрамдаңыз! 🥂','Бүгүн кечинде, балаңыз уктагандан кийин, жолдошуңуз экөөңүздөр бул чоң жеңишиңиздерди белгилегенди унутпаңыз!','Tähistame 250 päeva! 🥂','Täna õhtul, kui laps magab, ära unusta koos partneriga oma suurt meeskondlikku võitu tähistada!'),
('8f3f2d4b-5b88-42ed-95c1-db9f61e1f218'::uuid,'Кереметтүү 250 күн! 🎉','Ишенесизби? Сиздер бул сыйкырдуу сапарда чогуу жүргөнүңүзгө туптуура 250 күн болду! Бул көз ирмемди балаңыздын сүрөт сессиясында атайын стикер менен белгилеңиз!','Suurepärased 250 päeva! 🎉','Kas suudad seda uskuda? Olete koos sellel pöörasel ja maagilisel teekonnal olnud täpselt 250 päeva! Tähista seda hetke beebi fotosessioonil erilise kleebisega!'),
('e0e283b4-8f62-4d84-98d9-c186d1f67042'::uuid,'Артка кылчайып караңыз 📈','Ал алгачкы күндөрдөгү коркууларыңызды эстедиңизби? Эми сиз эми гана туруп баштаган бөбөктүн апасысыз! Өзүңүз менен сыймыктаныңыз!','Heida pilk tagasi 📈','Mäletad oma hirme esimestel päevadel? Nüüd oled sa juba püsti tõusma õppiva väikelapse ema! Ole enda üle uhke!'),
('01890bf6-ab5a-403c-96d2-696020ff0863'::uuid,'Полго саякат жана тузактар 🧸','Бөлмөлөр азыр анын изилдөө аймагына айланды! Ал бардык жерде сойлоп жүрөт. Үйдү бала үчүн коопсуз кылуунун убагы келди.','Põrandal avastamine ja ohud 🧸','Toad on nüüd nende avastusretkede tsoon! Nad roomavad kõikjal. On viimane aeg kodu lapsekindlaks muuta.'),
('64b9a99f-59f6-4495-b5ab-9a4825037afc'::uuid,'Тартылуу күчү оюну 🥄','Ал атайылап эле нерселерди ыргытып, сизди карап жатабы? Ал жөн гана себеп-натыйжа байланышын үйрөнүп жатат. Сабырдуу болуңуз жана оюнга кошулуңуз.','Gravitatsioonimäng 🥄','Kas nad viskavad asju meelega maha ja vaatavad sulle otsa? Nad lihtsalt õpivad põhjus-tagajärg seoseid. Ole kannatlik ja ühine mänguga.'),
('b34bf0e6-4ffb-4b59-90eb-68d99299dee1'::uuid,'Муздак кофе чындыгы ☕','Бүгүн да кофеңиз муздап калдыбы? Эч нерсе эмес, сиз тынымсыз кыймылдагы супер баатырсыз! Бүгүнкү жагымдуу башаламандыкты Маанай күндөлүгүңүзгө тамаша менен жазып коюңуз.','Jahtunud kohvi reaalsus ☕','Kas su kohv läks jälle külmaks? See on täiesti okei, oled ju pidevalt liikuv superkangelane! Pane tänane rõõmus kaos huumoriga kirja oma meeleolupäevikusse.'),
('026d603e-c612-41a2-9525-f4d00f730669'::uuid,'Душка түшүү ырахаты 🛀','Күнү бою анын артынан чуркап чарчадыңыз. Башкарууну жолдошуңузга өткөрүп бериңиз да, ваннада же душта 15 мүнөт эч ким тоскоолдук кылбаган эс алуу тартуулаңыз.','Hetk luksuslikku dušiaega 🛀','Nende järel jooksmine on sind terve päeva väsitanud. Anna ohjad partnerile ja luba endale 15 minutit segamatut lõõgastust vannis või duši all.'),
('1c49ef6a-c84a-47c7-a1bc-352a17833a3d'::uuid,'Диванды бойлоп басуу 🛋️','Ал эмеректерге таянып туруп, басып жатабы? Бул өз алдынчалыкка карай чоң кадам! Бул көз ирмемди өнүгүү трекерине жазып коюуну унутпаңыз.','Diivani ääres kõndimine 🛋️','Kas nad tõusevad mööbli najal püsti ja liiguvad mööda tuba? See on suur samm iseseisvuse poole! Salvesta see hetk kindlasti arengupäevikusse.'),
('b5c1158f-415c-414a-b3ec-c9879bf6e9d9'::uuid,'Ал өз атын билет! 🗣️','Бөбөгүңүз башка бөлмөдөн атын атаганыңызда бурулуп карайбы? Анын угуусу жана түшүнүүсү өсүп жатат! Атынан атап, аны менен көп сүйлөшүп туруңуз.','Ta teab juba oma nime! 🗣️','Kas su väike laps pöörab end ja vaatab, kui teda teisest toast nimepidi hüüad? Tema kuulmine ja mõistmine arenevad jõudsalt! Suhtle temaga tihti, kasutades tema nime.'),
('21f7df85-0fd1-4e90-a27b-52045487116f'::uuid,'Түнкү ойгонуулар 🌙','Тиши чыгып жаткан учурда балаңыз түнкүсүн көп ойгонуп жатабы? Сабырдуу болуңуз; тиштин оорусу аны тынчсыздандырууда. Жанында экениңизди сездириңиз.','Öised ärkamised 🌙','Kas beebi ärkab hammaste tuleku ajal öösiti tihti? Ole kannatlik; igemevalu teeb talle liiga. Las ta tunneb sinu lähedust.'),
('b80481ba-8798-458c-83d8-f359b3802548'::uuid,'Тынчтык ирмеми ☕','Ал башаламандык эч жакка качпайт. Балаңыз өз алдынча ойноп жатканда, дароо тазалоого шашылбаңыз. Диванга отуруп, 10 мүнөт эс алыңыз.','Hetk rahu ☕','See segadus ei kao kuhugi. Kui laps mängib rõõmsalt omaette, siis ära tunne sundi kohe koristama hakata. Istu diivanile ja lihtsalt puhka 10 minutit.'),
('125f59de-0644-435e-8593-de05b7cc7065'::uuid,'Аудио жомоктор 🎶','Эч бир тиркеме эненин бешик ырын алмаштыра албайт. Бүгүн кечинде балаңызды кучагыңызга алып, анын сүйүктүү бешик ырын акырын ырдап бериңиз.','Audioraamatud ja lood 🎶','Ükski äpp ei asenda ema hällilaulu. Täna õhtul lihtsalt hoia oma beebit kaisus ja laula talle vaikselt tema lemmiklaulu.'),
('63093c63-3ea0-4bb2-90bb-318617d51b7e'::uuid,'Пюре кечеси! 🥣','Бети, мурду, ал тургай чачы да тамакка боёлуп калдыбы? Капа болбой, бул татынакай көз ирмемди «Баланын сүрөт сессиясы» менен түбөлүккө калтырыңыз!','Püree-pidu! 🥣','Kas tema nägu, nina ja isegi juuksed on toiduga koos? Selle asemel, et stressata, jäädvusta see armas hetk beebi fotosessiooniga!'),
('104420b5-a415-4abb-81d8-7f7b520d18bd'::uuid,'Тиш эттери менен таануу 🦷','Ал баарын катуу чайнап, шилекейи агып жатабы? Анын өнүгүүсүн Тиш чыгуу трекеринен байкап туруңуз. Муздак тиш салгычтар бул учурда чыныгы куткаруучу!','Avastamine igemetega 🦷','Kas nad närivad agressiivselt kõike ja ilastavad ohtralt? Jälgi nende arengut hammaste tuleku jälgijas. Jahutavad närimisrõngad on sel ajal tõelised päästjad!'),
('c9c8946d-7797-4bd6-8476-9f649f770a6e'::uuid,'Биз бир командабыз! 💪','Жалгыз жана чарчаган сезимдесизби? Терең дем алыңыз. Сиз жана жолдошуңуз бул оор күндөрдүн эң күчтүү баатырларысыздар.','Oleme meeskond! 💪','Tunned end üksiku ja väsinuna? Hinga sügavalt sisse. Sina ja su partner olete nende keeruliste päevade kõige tugevamad kangelased.'),
('9ff73499-a2bd-41b7-96fa-1ec2d780279f'::uuid,'Өзүңүздү күнөөлөбөңүз! 💖','Балаңызга жетиштүү убакыт бөлбөй жатам же үй жумуштарына үлгүрбөй жатам деп ойлойсузбу? Өзүңүздү күнөөлөөнү токтотуңуз. Сиз эң сонун апасыз.','Ära tunne süümepiinu! 💖','Kas tunned, et ei veeda lapsega piisavalt aega või ei jõua kodutöid teha? Lõpeta enda süüdistamine. Teed suurepärast tööd.'),
('f8790842-2782-419a-aaaa-3c8c1fc497de'::uuid,'Аба ырайы жана кийим боюнча кеңештер ⛅','Сыртка чыгарда балага эмне кийгизсем деп стресс болбоңуз. Аба ырайы жана кийим тандоо куралын колдонуп, идеалдуу кийимди секунданын ичинде табыңыз да, таза абадан ырахат алыңыз.','Ilm ja riietussoovitused ⛅','Ära muretse, mida lapsele õue seiklusteks selga panna. Kasuta ilma ja riietuse tööriista, et leida sekunditega ideaalne komplekt, ja mine naudi värsket õhku.'),
('bb4b0ba8-0880-4332-8a97-7715f01a7ba8'::uuid,'Шкаф издектөөчүлөрү 🕵️‍♂️','Ашканадагы шкафтар кичинекей изилдөөчүңүздүн сүйүктүү жериби? Төмөнкү тартмаларга коопсуз идиш-аяктарды салып коюңуз, ал өзүнүн «казыналарын» таап, сааттап ойной берсин!','Kapi-detektiivid 🕵️‍♂️','Kas köögikapid on sinu väikese avastaja lemmikpaik? Pane alumisse sahtlisse mõned ohutud potid-pannid ja lase tal oma „aardeid“ avastada ja tunde mängida!'),
('c24149f4-cca2-46bd-ba68-2442b259ab90'::uuid,'Эсиңизде болсун, Сиз дагы аялсыз 💄','Сиз энесиз, коргоочусуз, бирок сиз ошол эле учурда өзүнчө инсансыз. Күзгүдөн өзүңүздү карап, жылмайыңыз жана бүгүн өзүңүз үчүн кичинекей болсо да бир жакшылык жасаңыз.','Pea meeles, oled ka naine 💄','Oled ema, kaitsja, aga oled ka isiksus. Vaata peeglisse, naerata ja tee täna midagi väikest iseenda heaks.'),
('4283eae1-f0b6-489a-be21-28cec6201152'::uuid,'Форумда адашып калуу 🤖','Бөбөгүңүздүн тамактануу тартиби боюнча суроолоруңуз барбы? Жооп издеп убара болбоңуз! Чөнтөгүңүздөгү педиатрыңыз — Anacan AI бардык суроолоруңузга адис катары жооп берет.','Foorumisse eksimine 🤖','Kahtlused beebi toitumise osas? Pole vaja tunde vastuseid otsida! Lase Anacan AI-l, oma taskupediaatril, anda asjatundlikke vastuseid kõigile oma küsimustele.'),
('743ea03a-9755-40d4-b4aa-1eb6cf8a7495'::uuid,'Атанын жомок айтып берүүсү 📖','Бүгүн кечинде ''Акылдуу жомоктордон'' тоого чыккан эр жүрөк эчки жөнүндө жомок окуп бериңиз. Атасы окуп жатканда, сиз жөн гана тынч көз ирмемдерден ырахат алыңыз.','Issi unejutud 📖','Täna õhtul loo „Nutikate lugude“ abil jutuke vaprast kitsest, kes mägedes ronis. Las issi loeb seda, samal ajal kui sina lihtsalt naudid rahulikku hetke.'),
('fc594ad6-91bd-4ee2-a759-0d1e76e468c0'::uuid,'Кол менен жей турган тамактар 🥦','Бөбөгүңүз эми пюре менен гана чектелбей, жашылчаларды өз колу менен кармагысы келип жатабы? Анын өз алдынча тамактануу аракетин колдоңуз, бирок жанында сөзсүз болуңуз.','Sõrmetoidud 🥦','Beebi ei taha enam ainult püreed, vaid soovib köögivilju oma kätega hoida! Toeta tema katseid ise süüa, kuid ole kindlasti tema kõrval.'),
('5cafdda5-c60b-4328-9530-450093ed8026'::uuid,'Толук тынчтык 🤫','Уйкуга кете албай жатасызбы? Бөлмөнү толук караңгылатып, ызы-чууну жок кылыңыз. Караңгылык жана тынчтык — анын уйкусунун эң жакшы шериктери.','Absoluutne vaikus 🤫','Kas uinumisega on raskusi? Tee tuba täiesti pimedaks ja eemalda müra. Pimendus ja vaikus on lapse parimad unekaaslased.'),
('8ee71700-bb17-4782-940b-c0fc02328f1a'::uuid,'Заңынын өңү өзгөрдүбү? 💩','Кошумча тамак киргизгенден кийин заңынын түсү өзгөргөнүн байкасаңыз, бул кадыресе көрүнүш. Бирок кооптонуп жатсаңыз, себебин түшүнүүгө Anacan AI жардам берет.','Kas kaka värvus on muutunud? 💩','Tahke toidu tutvustamisel on väljaheite värvuse muutumine täiesti normaalne. Kui oled aga mures, lase Anacan AI-l aidata põhjust mõista.'),
('9240cd01-c58e-42aa-be44-a4d2ac461bc2'::uuid,'Чарчоо сезими — бул кадыресе көрүнүш 🔋','Сабырыңыз түгөнүп баратканда, өзүңүздү жаман эне сезбеңиз. Мындай чарчоо — табигый нерсе.','Kurnatus on normaalne 🔋','Kui kannatus hakkab katkema, ära tunne end halva emana. See väsimus on täiesti loomulik.'),
('03f6a4bb-fc20-440d-bf19-5a474e3fa7f6'::uuid,'Өзүңүзгө убакыт бөлүңүз. 🛁','Балаңыз уктап жатканда, өзүңүзгө убакыт бөлүп, чачыңызга жана териңизге кам көрүп эс алып алыңыз.','Võta aega iseendale. 🛁','Samal ajal kui laps magab, võta aega iseendale, et puhata ning hoolitseda oma naha ja juuste eest.'),
('288682cf-7f40-402e-a594-adaf2cbbed34'::uuid,'Жылаңайлак саякаттар 👣','Бөбөгүңүз үйдө байпагын чечип салып жатабы? Буттарынын жерге тийиши мээнин өнүгүүсү үчүн абдан пайдалуу. Жалаң аяк жүрө берсин!','Paljajalu avastused 👣','Kas su väike laps võtab toas sokid jalast? Jalgade kokkupuude põrandaga annab ajule suurepärast sensoorset infot. Lase tal paljajalu ringi liikuda!'),
('2951ca5f-9454-4562-9820-3bfb3531edfd'::uuid,'Тизмелер жашоону жеңилдетет 🛒','«Энелик унутчаактык» эсиңизди чаташтырып жатабы? Самын же жемиш түгөнүп калдыбы? Аны тез арада Соода тизмесине кошуп коюңуз, калганын жолдошуңуз чечсин!','Nimekirjad päästavad elu 🛒','Kas „emme aju“ hägustab endiselt mälu? Seep või puuviljad said otsa? Lisa need kiiresti ostunimekirja ja lase partneril nende eest hoolitseda!'),
('5a72ebf7-bb71-45f2-8047-a9b0ffc32a13'::uuid,'Командалык жолугушуу убактысы 🥂','Бүгүн кечинде балаңыз уктагандан кийин, жолдошуңуз менен бирге ''Маанай күндөлүгүн'' ачып, ушул жумадагы кызыктуу окуяларга чогуу күлүп алыңыз.','Meeskonnakoosoleku aeg 🥂','Täna õhtul, kui beebi magab, ava koos partneriga oma meeleolupäevik ja naerge koos selle nädala kaose üle.'),
('06f3c3ab-79a9-4f2f-94ed-e08927cda8e1'::uuid,'Кайрадан тиш чыгуу түйшүктөрү 🦷','Түшүнүксүз ыйлоолор тиштин чыгышынан улам болгон басымдан болушу мүмкүн. Тиш чыгуу трекерин жаңыртып, муздатылган тиш салгычтарды даярдап коюңуз!','Jälle hammaste tulek 🦷','Need seletamatud pisarad võivad olla tingitud igemete survest. Uuenda hammaste tuleku jälgijat ja haara külmutatud närimisrõngad!'),
('8e728e0f-9970-4b3d-acfc-5e72bc0eb7af'::uuid,'Тынчтык үчүн бөлмө акустикасы 🤫','Уктап жатканда кичинекей эле үндөн ойгонуп кетеби? Үн өлчөгүч менен чөйрөнү текшерип, ак ызы-чуу (white noise) менен уйкусун бекемдеңиз.','Ruumide akustika vaikuse jaoks 🤫','Kas nad ärkavad uinumisel vähimagi heli peale? Kontrolli keskkonda helitaseme mõõtjaga ja toeta und ühtlase valge müra abil.'),
('cefb8b22-0318-4268-adf8-8f7052ad66cc'::uuid,'Бөбөгүңүз сөөмөйү менен көрсөтүп, үн чыгарып жатабы? ☝️','Ал «карачы» же «тигини бер» дегендей ишарат кылып же үндөрдү чыгарып жатабы? Бул баарлашуудагы чоң жетишкендик!','Kas su väike laps näitab näpuga ja häälitseb? ☝️','Kas nad näitavad näpuga või teevad hääli, et öelda „vaata mind“ või „tahan seda“? See on suur suhtlemise verstapost!'),
('2e4d0e7a-db8d-4408-9d88-01d37ed8b303'::uuid,'Уйку терезеси тарып баратат 🥱','Түнкүсүн ойгонуулар сизди чарчатып бүттүбү? Балким, бул 3 күндүзгү уйкудан 2 уйкуга өтүү мезгилидир. Күндүзгү уйку графигин кайра карап чыгыңыз.','Uneaken hakkab kitsenema 🥱','Kas öised ärkamised kurnavad sind? See võib olla üleminekuperiood 3 uinakult 2-le. Vaata uuesti üle nende päevane uinakute graafik.'),
('b19774b6-01ed-4a77-8052-5a03aef4ba22'::uuid,'Чачтагы пюре! 🤦‍♀️','Тамактануу убактысы согуш майданына айланып жатабы? Балаңыздын тамакты кармалап изилдөөсү — анын сезүү органдарынын өнүгүүсүнүн бир бөлүгү. Чачылган тамакка кабатыр болбоңуз!','Püree juustes! 🤦‍♀️','Kas söögiaeg muutub lahinguväljaks? See, et laps toitu katsub ja uurib, on osa tema sensoorsest arengust. Ära muretse segaduse pärast!'),
('f1d99477-a71b-4368-b9eb-c5c699e49b39'::uuid,'Жаратылыш жардамга келет 🌳','Бөбөгүңүз өтө эле тынчсызданып, ордуна бата албай жатабы? Аба ырайы жана кийим тандоо жардамчысынан кеңеш алып, 20 мүнөттүк сергитүүчү сейилдөөгө чыгыңыз!','Loodus appi 🌳','Kas su väike laps on eriti viril ja ronib mööda seinu? Võta kiire nipp ilma ja riietuse assistendilt ja suundu 20-minutilisele värskendavale jalutuskäigule parki!'),
('2958c07b-39da-4ecb-ac79-c0f1640a7d1a'::uuid,'Өзүңүздү башкаларга салыштырбаңыз 🛑','«Тигинин баласы басып кетти» деген сөздөрдү унутуңуз. Ар бир баланын өнүгүү жолу уникалдуу. Anacan коомчулугундагы пикирлеш энелер менен байланышып, тажрыйба бөлүшүңүз.','Ära võrdle end teistega 🛑','Unusta see, et „teiste beebi juba kõnnib“. Iga lapse arenguteekond on unikaalne. Suhtle ja jaga kogemusi teiste sarnaste emadega Anacani kogukonnas.'),
('da431940-9d6b-4ed8-a933-fd80b83687d9'::uuid,'''Апа'' деген сөздү таттуу күтүү 🥰','Ал ар кандай муундарды айтып жатабы? Биринчи аң-сезимдүү «Апа» же «Ата» деген сөзү жакындап калды! Анын үндөрүнө сүйүү менен жооп берип, шыктандырыңыз.','Magus ootus: „Emme“ 🥰','Kas nad teevad erinevaid silpe? Esimene teadlik „emme“ või „issi“ võib olla kohe-kohe tulemas! Vasta nende häälitsustele armastusega, et neid julgustada.'),
('f40e6c18-873e-481a-ba28-76a5634b977a'::uuid,'Музыка жан дүйнөнү азыктандырат 🎶','Кечинде түшүнүксүз ыйлоолорун жай классикалык музыка менен басууга аракет кылыңыз. Көбүнчө бул жөнөкөй ыкма кереметтерди жаратат.','Muusika toidab hinge 🎶','Proovi seletamatuid õhtuseid nutuhooge rahustada õrna klassikalise muusikaga. Tihti teeb see lihtne nipp imesid.'),
('0c385e87-5c02-4870-85f8-9ab052891af8'::uuid,'Эне үчүн витаминдер 🥑','Сиз бөбөгүңүздүн азыктануусу үчүн баарын жасап жатасыз, ал эми өзүңүзчү? «Дени сак рецепттер» бөлүмүнөн темирге жана кальцийге бай жеңил түшкү тамак менен өзүңүздү сыйлаңыз.','Vitamiinid emmele 🥑','Teed kõik, et oma last toita, aga kuidas on lood sinuga? Hellita end tervislike retseptide sektsioonist leitud raua- ja kaltsiumirikka kerge lõunasöögiga.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('effeac28-8d9e-4d0e-b754-fb4004990432'::uuid,'Экрандардан эс алыңыз 📱','Уктоо убактысына 1 саат калганда үйдөгү бардык сыналгыларды жана экрандарды өчүрүңүз. Мелатонин гормону тынч жана караңгы чөйрөдө гана жакшы иштелип чыгат.','Puhka ekraanidest 📱','Lülita kõik telerid ja ekraanid majas välja 1 tund enne magamaminekut. Melatoniini tootmine hoogustub vaid rahulikus ja pimedas keskkonnas.'),
('47fc8d5e-d99d-4104-9258-c8e18ad15266'::uuid,'Бул түндүн сыйкырдуу темасы кандай? 🪄','Бүгүн кечинде AI жазган ''Оюнчуктарын издеген кичинекей тыйын чычкан'' жомогун окуп бериңиз. Түнкү тынчтыкты сиздин жагымдуу үнүңүз гана бузсун.','Mis on tänane maagiline teema? 🪄','Täna õhtul lase AI-l kirjutada lugu: „Väike orav, kes otsis oma mänguasju“. Las vaid sinu õrn hääl rikub öö vaikust.'),
('856e1374-a46f-4ac4-b093-11e46392180f'::uuid,'Сиздин кичинекей туурагычыңыз 🦜','Ал сиздин жөтөлгөнүңүздү, күлгөнүңүздү же кол кыймылдарыңызды туурап жатабы? Сиз анын эң жакшы күзгүсүсүз! Ага бардык сонун эмоцияларыңызды көрсөтүңүз!','Sinu väike järeleahvija 🦜','Kas nad matkivad sinu köhimist, naeru või käeliigutusi? Oled nende parim peegel! Näita neile kõiki neid imelisi ilmeid!'),
('e263bb82-67f5-4f23-9107-f117b8634a27'::uuid,'Сезимдериңизди сыртка чыгарыңыз 📝','Кээде эшикти жаап алып, катуу ыйлагыңыз келеби? Бул кадыресе көрүнүш. Ичиңиздегини чыгаруу — абдан жеңилдетет; сезимдериңизди Маанай күндөлүгүнө жазып коюңуз.','Lase tunded valla 📝','Mõnikord tahaks lihtsalt ukse kinni panna ja korralikult nutta, eks? See on täiesti normaalne. Tunnete väljendamine võib olla nii tervendav; vala oma tunded meeleolupäevikusse.'),
('3c29a397-ae21-4b66-9ae6-c3001d2f3e36'::uuid,'Анын көз карашын кармоо 👀','Бөлмөнүн кайсы бурчунда болбоңуз, алардын көзү сизден түшпөйт. Сиз алар үчүн бейпилдик жана коопсуздуктун булагысыз. Чыдамыңыз түгөнүп баратканда, бул чексиз сүйүүнү эстеңиз.','Pilkkontakti loomine 👀','Ükskõik kus sa toas ka ei viibiks, nende pilk on suunatud sinule. Sina oled nende turvapaik ja kindlustunne. Kui kannatus hakkab katkema, tuleta endale meelde seda tingimusteta armastust.'),
('b3560b09-ab82-494c-a5e9-d6be5d4cb35a'::uuid,'Башаламандык искусствосу 🌪️','Оюнчуктарынын баары чачылып жатабы? Учурда үйүңүздүн тазалыгына караганда, сиздин эс алууңуз маанилүүрөөк. Оюнчуктар эртең да ошол жерде болот, бирок бүгүн сизге энергиялуу эне керек!','Segaduse kunst 🌪️','Kas kõik nende mänguasjad on laiali pillutud? Sinu puhkus on praegu tähtsam kui korras kodu. Mänguasjad on homme ka alles, kuid täna vajab laps eelkõige puhanud ja energilist emmet!'),
('fe563692-e0de-40b2-aa34-9d6335348a54'::uuid,'Түнкү тынчтык 🤫','Эгерде унаанын же сырттын ызы-чуусу аларды тынчсыздандырса, фондо дайыма бир калыптагы ак ызы-чуу (white noise) булагын колдонуңуз.','Öine vaikus 🤫','Kui auto- või välismüra last häirib, veendu, et taustal oleks ühtlane valge müra.'),
('268d0edd-f8c9-45fd-af24-4b1bd27e458d'::uuid,'Атасынын массаж жасоо убактысы 💆‍♀️','Ымыркайды уктатууну өнөктөшүңүзгө тапшырыңыз, андан кийин ал сизге моюн булчуңдарыңызды жазуу үчүн 5 мүнөттүк массаж жасап берсин!','Issi massaažiaeg 💆‍♀️','Lase partneril laps magama panna ja palu tal seejärel oma pinges kaelalihaseid 5 minutit masseerida!'),
('b1d60979-35c2-486a-9e3b-5e85d1d3dbdf'::uuid,'Тамактануу учурундагы күрөштөр 🥣','Кичинекейиңиз пюрени түртүп жатабы? Мажбурлабаңыз. Тамак менен жакшы мамиле түзүү үчүн, тамактануу убактысын оюнга айлантып, коомчулуктагы башка рецепттерди сынап көрүңүз.','Söögiaja lahingud 🥣','Kas su väike põnn lükkab püreed tagasi? Ära sunni teda sööma. Positiivse toidusuhte loomiseks muuda söögiajad mänguliseks ja proovi kogukonna soovitatud alternatiivseid retsepte.'),
('73d0b947-9db1-4d57-a222-c8c22a2a895b'::uuid,'Мүнөзү калыптанып жатат 🌟','Алар эмнени жактырып, эмнени жактырбасын азыртан эле ачык көрсөтүп жатышат. Алардын өжөрлүгү сизди чарчатса, бул алардын инсан катары калыптанып жатканынын белгиси экенин унутпаңыз.','Isiksus lööb õitsele 🌟','Nad annavad juba selgelt märku, mis neile meeldib ja mis mitte. Kui nende jonnakus sind väsitab, pea meeles, et tegelikult kujundavad nad sel moel oma isiksust.'),
('9596d063-607c-465f-9e92-b73f9f6f0ece'::uuid,'Энелердин достугу 💬','Кыйынчылыктарыңыз менен бөлүшүү жүгүңүздү жеңилдетет. Anacan коомчулугунда миңдеген аялдар сиз сезип жаткан сезимдерди баштан кечирүүдө. Пикир алышуу жана колдоо алуу ар дайым бекер.','Emmede sõprussuhted 💬','Murede jagamine kergendab koormat. Anacani kogukonnas on tuhandeid naisi, kes tunnevad sedasama, mida sinagi. Ühenduse loomine ja üksteise toetamine on alati tasuta.'),
('fb27143e-60bd-4519-b45e-80c5584417a4'::uuid,'Атасынын мээрими 🫂','Түнкү тынчсыздануулар менен жалгыз күрөшпөңүз. Өнөктөшүңүздү бул ишке тартыңыз. Кээде башка жыт жана кучактоо ымыркайды заматта тынчтандырышы мүмкүн.','Issi lohutab 🫂','Ära ürita öiste muredega üksi toime tulla. Kaasa partner protsessi. Mõnikord võib teine lõhn ja kallistus lapse hetkega rahustada.'),
('4e869b86-0b42-4c4a-86f7-22a0999a3387'::uuid,'Кол чабыңыз! 👏','Алар кубанганын билдириш үчүн кол чаап жатышабы? Бул укмуштуудай кыймыл-аракет жөндөмүн ''Өнүгүү күндөлүгүнө'' жазып коюңуз жана үйдө кичинекей майрам уюштуруңуз!','Plaksuta käsi! 👏','Kas nad plaksutavad rõõmust käsi? Salvesta see imeline motoorne oskus arengupäevikusse ja korralda kodus väike võidutants!'),
('72a32149-c4d7-4a45-b296-5cc7c5b673ad'::uuid,'Тез текшерүү 🤖','9 айлык ымыркайдын өнүгүү этаптарына кызыгып жатасызбы? Чексиз макалаларды окуунун кажети жок. Anacan AI''дан түз сурап, педиатр тарабынан тастыкталган жоопторду алыңыз.','Kiire kontroll 🤖','Huvitab 9-kuuse lapse areng? Jäta lõputud artiklid vahele. Küsi otse Anacan AI-lt ja saa pediaatri tasemel täpseid vastuseid.'),
('df74b674-d83b-4306-a6c3-1477bd965efe'::uuid,'Уктоого даярдык 🛀','Жылуу ванна ар дайым кереметтерди жаратат. Кечки тартипти эч качан бузбаңыз, анткени бул алардын мээсине уктоо убактысы келгенин билдирет.','Uinumise ettevalmistus 🛀','Soe vann teeb alati imesid. Ära kunagi riku õhtust rutiini, sest see annab lapse ajule märku, et on aeg magama minna.'),
('5e8f6838-89c2-40a6-940e-2ef8b752a179'::uuid,'Орток эскерүүлөр 📸','Алар ушундай сулуу жылмайып жатышат! Уктап калганга чейин ал күнөөсүз жүзүн сүрөткө тартып алыңыз; мындай көз ирмемдер кайра кайталанбайт.','Ühised mälestused 📸','Nad naeratavad nii kaunilt! Jäädvusta see süütu nägu enne, kui nad uinuvad; need hetked ei tule enam kunagi tagasi.'),
('912ca02c-47d0-4e27-8bdb-7afe9ba868be'::uuid,'Темирдин көлөмүн көтөрүү 🥩','Анемия балаңыздын табитине да, энергия деңгээлине да таасирин тийгизиши мүмкүн. Алардын тамактануу тартибин карап чыгыңыз жана керек болсо, Anacan AI''дан темирге бай азыктар тууралуу сураңыз.','Rauavarude täiendamine 🥩','Aneemia võib mõjutada nii lapse söögiisu kui ka energiataset. Vaata üle nende toitumine ja vajadusel küsi Anacan AI-lt nõu rauarikaste toitude kohta.'),
('0135df6f-fe6e-4faf-9136-dc65b2b29e33'::uuid,'Кош айтышып кол булгалоо 👋','Бирөө үйүнөн чыгып баратканда алар кол булгалап коштошуп жатышабы? Бул социалдык өнүгүүнүн абдан таттуу белгиси! Аларды мактап, кубаттап коюңуз.','„Head aega“ lehvitamine 👋','Kas nad lehvitavad hüvastijätuks, kui keegi kodust lahkub? See on väga armas märk sotsiaalsest arengust! Julgusta neid selle eest kindlasti.'),
('44260d05-153e-4b6b-b9dd-6f07fb02c462'::uuid,'Тынчтыкты издөө ⛅','Чыңалуу күчөгөндө, кээде эң жакшы чечим — жөн гана сыртка чыгуу. Аба ырайын карап, кичинекейиңизди коляскага салып, сергитүүчү сейилдөө менен башыңызды тазалаңыз.','Vaikuse otsingul ⛅','Kui pinge kasvab, on parim lahendus vahel lihtsalt õue minna. Kontrolli ilma, pane väike põnn vankrisse ja puhasta oma mõtteid värskendava jalutuskäiguga.'),
('67247d93-ddf7-4fcc-adef-5828dde725b4'::uuid,'Кынтыксыздык иллюзиясы 🛑','Бүгүн баары пландагыдай болбой калдыбы? Өзүңүздү күнөөлөбөңүз. Сиз социалдык тармактардагы жасалма сүрөттөрдөгүдөй эмес, чыныгы энесиз.','Täiuslikkuse illusioon 🛑','Kas täna ei läinud miski plaanipäraselt? Ära süüdista ennast. Oled päris ema, mitte sotsiaalmeedia filtreeritud illusioon.'),
('4e8edba3-fd16-4c28-a7ff-08ff9853211e'::uuid,'Күнүмдүк керектөөлөрдү унутуу 🛒','Жоолукча же памперс түгөнүп баратабы? Аны соода тизмесине кошуп коюңуз, өнөктөшүңүз дүкөндөн кайтып келе жатканда алып келет.','Igavene unustamine 🛒','Kas mähkmed või niisked salvrätikud hakkavad otsa saama? Lisa need ostunimekirja ja lase partneril need poest tulles kaasa haarata.'),
('5f49ad4f-107b-4550-adae-e4aab3aa9d5b'::uuid,'Эки жолу уктоо режимине өтүү 🥱','Күнүнө 3 жолу уктап жүргөн балаңыз эми акыркы уйкудан баш тартып жатабы? Алар чоңоюп жатышат! Уйку тартибин эки жолкуга өзгөртүүгө убакыт келди.','Üleminek kahele unele 🥱','Kas su laps, kes varem magas 3 korda päevas, hakkab nüüd viimasest uinakust keelduma? Ta kasvab! On aeg kohandada unegraafik kahele uinakule.'),
('7ee44a70-ee6e-4b49-a487-76ff5581f580'::uuid,'Жаңы кайраттуу кадамдар 🧗‍♂️','Алар эмеректерди кармап, бир колун коё берүүгө аракет кылып жатышабы? Тең салмактуулукту сактоо жөндөмү өнүгүүдө. Колунан кармап, аларга бир аз ишеним бериңиз.','Julged uued sammud 🧗‍♂️','Kas nad hoiavad mööblist kinni ja proovivad ühe käega lahti lasta? Nende tasakaalutunnetus areneb. Hoia neist kinni ja anna neile veidi enesekindlust.'),
('aba537d3-5a0f-4b17-b02b-4754b93f711f'::uuid,'Кайсы тараптан эмизгениңизди унутуп калдыңызбы? 🤱','Таймерди колдонуп кайсы эмчекти колдонгонуңузду жазып алыңыз, Anacan бардык майда-чүйдөсүн сиз үчүн эстеп калат!','Unustasid, kummalt poolt toitsid? 🤱','Kasuta taimerit, et märkida, kummast rinnast toitsid, ja lase Anacanil kõik detailid enda eest meeles pidada!'),
('97d44a72-2ca4-4c0f-b997-91c31aeabbef'::uuid,'Биримдик үчүн тост 🥂','''Маанай күндөлүгүн'' ачып, бул айлар экөөңүздөрдү кантип өзгөрткөнү тууралуу өнөктөшүңүз менен сүйлөшүңүз. Команда болуп иштөө — эң чоң күч.','Terviseks koosolemisele 🥂','Ava oma ''Meeleolupäevik'' ja aruta partneriga, kuidas need kuud on teid mõlemaid muutnud. Meeskonnana tegutsemine on suurim tugevus.'),
('ff86bc54-face-4f54-a1de-cc0ec9cccbc2'::uuid,'Баары жакшы ✔️','Кээде коркуу сезими сизди басып жатабы? Алардын таза кийимине, ток курсагына жана сизге карап жылмайган көздөрүнө көз чаптырыңыз. Сиз чындап эле укмуштуудай иш жасап жатасыз!','Kõik on korras ✔️','Kas hirmud kipuvad vahel üle pea kasvama? Vaata nende puhtaid riideid, täis kõhtu ja neid silmi, mis sulle vastu naeratavad. Sa teed uskumatult head tööd!'),
('be6a944e-f3ba-401c-9b99-70457d5df68b'::uuid,'Апа, мага караңыз! 👀','Сиз телефон карап же башка иш менен алек болуп жатканыңызда, алар келип, жүзүңүздү өздөрүнө бурабы? Алар сиздин толук көңүлүңүздү каалап жатышат. Көз караштарыңызды бириктирип, аларды угуп жатканыңызды, алар сиз үчүн маанилүү экенин жана аларды чындап көрүп турганыңызды сездириңиз.','Emme, vaata mind! 👀','Kas nad tulevad ja pööravad su näo enda poole, kui sa telefoni vaatad või midagi muud teed? Nad otsivad sinu täit tähelepanu. Loo silmside ja lase neil tunda, et nad on kuuldud, tähtsad ja tõeliselt märgatud.'),
('5a4dd587-0176-4bbf-bb1c-d0eab0227cdc'::uuid,'Аталардын байланыш убактысы. 👨‍🍼','Кечки тамактан кийин, баланын кекиригин чыгарууну жана уктатууну атасына тапшырып, өзүңүз бир аз эс алып алыңыз.','Isside ja lapse side 👨‍🍼','Pärast õhtust toitmist lase issil tegeleda krooksutamise ja magamapanekuga, samal ajal kui sina puhkad.'),
('e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c'::uuid,'Сүйлөмдөр жомокко айланат 🗣️','Алар азыр сөздөрдү бириктирип, кызыктуу, ойдон чыгарылган окуяларды айтып жатышабы? Сөздүк корунун жарылуусу жүрүп жатат!','Lauseist saavad muinasjutud 🗣️','Kas nad kombineerivad nüüd sõnu ja räägivad naljakaid, fantaasiarikkaid lugusid? Toimumas on sõnavara plahvatus!'),
('13a8c002-9f52-4112-970b-14cac50a9b5c'::uuid,'Бөлмө акустикасы 🤫','Уктап жатканда алардын сезгичтиги жогорулайт. Терезеден келген үндөрдү басаңдатуу үчүн, үн өлчөгүчтү текшерип, бөлмөдө жай ак ызы-чуу (white noise) чыгаруучу аппаратты күйгүзүңүз.','Ruumi akustika 🤫','Uinumise ajal on laps tundlikum. Välishelide neutraliseerimiseks kontrolli helitaset ja lülita toas sisse õrn valge müra seade.'),
('4892459c-b0fb-4a8c-89d7-1bb93e680c5b'::uuid,'Кичинекей инженер 🤔','Муну ыргытсам эмне болот? Бул баскыч эмне үчүн керек? Алар тынымсыз физикалык эксперименттерди жүргүзүп жатышат. Алар үйрөнүп жатышат! Үйүңүздүн коопсуздугун алардын көз карашы менен дагы бир жолу карап чыгыңыз.','Väike insener 🤔','Mis juhtub, kui ma selle viskan? Milleks see nupp on? Nad teevad pidevalt füüsilisi katseid. Nad õpivad! Vaata oma kodu turvalisust uuesti lapse silmade kõrguselt.'),
('dc8c6058-0791-46ab-b5d1-2637ff0b924e'::uuid,'Терезеге ишенбеңиз ⛅','Сейилдөөгө чыгарда терезеден көрүнгөн аба ырайына алданбаңыз. Сырттагы чыныгы шамалдын ылдамдыгын жана температураны эске алуу менен ылайыктуу кийим тандоо үчүн аба ырайы жана кийим тандоо боюнча жардамчыны колдонуңуз, ошондо үйүңүздөн ишенимдүү чыга аласыз.','Ära usalda akent ⛅','Ära lase end petta sellest, mida aknast välja vaadates näed. Kasuta ilma- ja riietumisabilist, et valida täiuslik riietus vastavalt tegelikule tuulele ja temperatuurile, ning lahku kodust enesekindlalt.'),
('7325d8d6-eeac-417b-abca-d32163dd16b4'::uuid,'Азык-түлүк дүкөнүндөгү куткаруучу 🛒','Азык-түлүк дүкөнүнө барганда дайыма бир маанилүү нерсени унутуп каласызбы? Тиркемедеги соода тизмеси функциясы жардамга келет! Керектүү нерселердин баарын жазып коюңуз, өнөктөшүңүз жумуштан кайтып келе жатып, аларды так алып келе алат.','Päästja toidupoes 🛒','Kas unustad toidupoodi minnes alati selle ühe olulise asja? Rakenduse ostunimekirja funktsioon on siin, et aidata! Pane kirja kõik vajalik ja su partner saab selle täpselt töölt tulles kaasa osta.'),
('d7e75209-c901-4086-8f01-b71b4374f127'::uuid,'Суу терапиясы 🛀','Экөөңүздөр тең күн бою чуркап чарчадыңыздар. Жылуу ваннага түшүп жатканда, фондо жаратылыштын тынчтандыруучу үндөрүн коюңуз. Суунун гармониясы эң тентек баланы да уйкуга даярдайт.','Vee-teraapia 🛀','Olete mõlemad terve päeva jooksmisest väsinud. Sooja vanni ajal mängi taustaks rahustavaid loodushelisid. Vee harmoonia valmistab ka kõige jonnakama lapse uneks ette.'),
('f55edde1-4803-4d20-96d6-d40197fda19c'::uuid,'Чечкиндүү ''Жок!'' 🛑','Кимдир бирөө аларды өпкөнгө аракет кылганда, алар тартынып, катуу «жок» деп айтышабы? Алардын денесинин кол тийбестигин сыйлаңыз. Каалабаган тийүүгө каршы чыга алуу жөндөмү алардын дени сак психологиялык өнүгүүсү үчүн өтө маанилүү.','Kindlameelne „Ei!“ 🛑','Kas nad tõmbuvad eemale ja ütlevad kindlalt ei, kui keegi tahab neid suudelda? Austa nende kehalist autonoomiat. Oskus soovimatule puudutusele vastu seista on nende tervislikuks psühholoogiliseks arenguks ülioluline.'),
('a279684f-8916-4183-8bdf-0b058193de01'::uuid,'Атасынын үнүнүн күчү 📖','Бүгүн кечинде үн байламталарыңызды эс алдырыңыз. Балаңыздын сүйүктүү китептерин ар кандай, ойдон чыгарылган жана күлкүлүү үндөр менен окуп берүү милдетин атасына тапшырыңыз.','Issi hääle võlu 📖','Anna oma häälepaeltele täna õhtul puhkust. Lase issil lugeda lapse lemmikraamatuid erinevate, väljamõeldud ja naljakate häältega.'),
('acb821ae-037d-451e-905f-fae976b254b3'::uuid,'Менин өздүк буюмдарым 🧸','Алар конокко келген балага оюнчуктарын бергиси келбей жатабы? Бул өзүмчүлдүк эмес; бул жеке чектерди белгилөө. Аларды бөлүшүүгө мажбурлап эмес, өзүңүз үлгү көрсөтүү менен үйрөтүңүз.','Minu oma asjad 🧸','Kas nad ei taha oma mänguasju külla tulnud lapsega jagada? See ei ole isekus, vaid isiklike piiride seadmine. Õpeta neid jagama eeskuju näidates, mitte sundides.'),
('ee52c904-b97d-4a34-b7fb-b60ab86aadcd'::uuid,'Эненин энергия булагы 🥑','Күнүмдүк шашылыш иштердин арасында түшкү тамакты шашып ичпеңиз. Дени сак рецепттерибизден энергия берүүчү тамак тандап, кеминде 10 мүнөт диванга жатып, өзүңүздүн тамактанууңузга кам көрүңүз.','Emme energiaamps 🥑','Ära haara igapäevases saginas lõunat käigu pealt. Vali meie tervislike retseptide hulgast energiat andev vahepala ja prioriteedi oma toitumist, heites vähemalt 10 minutiks diivanile puhkama.'),
('51decf20-cf70-4c72-beb9-3712b300a999'::uuid,'Куушуп ойноо марафону 🏃‍♂️','Алар эми жөн эле басуу менен чектелбей калышты; сиз чакырганда, алар тез чуркап барып жашынышат. Бөлмөдөгү кооптуу тоскоолдуктарды тазалап, бул кубанычтуу куушма оюнга сиз да кошулуңуз!','Tagaajamise maraton 🏃‍♂️','Nad ei lepi enam lihtsalt kõndimisega; kui sa neid hüüad, jooksevad nad kiiresti peitu. Korista toast ohtlikud takistused ja ühine selle rõõmsa tagaajamisega!'),
('aff77c93-ed92-44bc-9afd-e64eb6ce5292'::uuid,'Акыл-эсиңизди изилдеңиз 📱','Балаңыздын тынымсыз «жок» деп айтканы сизди чарчатып жатабы? Мээсиндеги бул өнүгүү секиригинин терең себептерин түшүнүү үчүн тиркемедеги психологиялык блогдорду окуп чыгыңыз.','Avasta oma mõtteid 📱','Kas lapse pidev ''ei'' ajab sind närvi? Sukeldu rakenduse psühholoogilistesse blogidesse, et mõista selle arenguhüppe sügavamaid põhjuseid nende ajus.'),
('e18b761a-6fd6-438d-896c-ec7bd458b9c2'::uuid,'Караңгылыктын күчү 🌙','Алардын тезирээк уктап кетишине жардам берүү үчүн, бөлмөдөгү бардык ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин караңгы жана технологиясыз чөйрөдө гана тез бөлүнүп чыгат.','Pimeduse vägi 🌙','Et aidata neil kiiremini uinuda, lülita toas välja kõik lisatuled ja tahvelarvutite ekraanid. Melatoniini eraldub kiiresti vaid pimedas ja tehnoloogiavabas keskkonnas.'),
('5a4437a7-7519-4a4e-9c66-e797d5e763f5'::uuid,'Кичинекей режиссер иште! 🎭','Балаңыз сүрөттүү китептеги каармандардан шыктанып, толугу менен ойдон чыгарылган окуяларды айтып жатабы? Алардын фантазиясы чындап эле өсүп жатат! Аларды бөлбөстөн, бул укмуштуудай жомокторду сыймыктануу менен угуңуз.','Väike lavastaja töös! 🎭','Kas su laps jutustab täiesti väljamõeldud lugusid, inspireerituna pildiraamatu tegelastest? Nende kujutlusvõime tõepoolest õitseb! Kuula uhkusega neid erakordseid jutte ilma vahele segamata.'),
('932de885-b10a-4cc0-af8a-8db540c3d060'::uuid,'Жылуу чай жана бейпилдик 🍵','Үй жумуштарын унутуңуз; баары күтө турат. Дени сак рецепттерден лимон чөбүнөн чай демдеп, өзүңүз менен жалгыз калуунун тынчтыгынан ырахат алыңыз.','Soe tee ja rahu 🍵','Unusta kodutööd; kõik võib oodata. Valmista tervislike retseptide järgi melissiteed ja naudi lihtsalt rahu, olles iseendaga.'),
('ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424'::uuid,'Сейил бактагы терапия 🌳','Төрт дубалдын ичинде камалып калгандай сезилип жатасызбы? Аба ырайы суук болсо да, аларды жылуу ороп, 20 мүнөткө сейил бакка чыгыңыз. Жалбырактарды жана таштарды изилдешине мүмкүнчүлүк бериңиз; таза аба алардын мээсин кычкылтек менен байытат.','Pargiteraapia 🌳','Tunned end nelja seina vahel vangis? Isegi kui ilm on jahe, pane nad soojalt riidesse ja suundu 20 minutiks parki. Lase neil lehti ja kive uurida; värske õhk rikastab nende aju hapnikuga.'),
('12d65ca5-dc2d-4959-8af5-51ab64abb6bf'::uuid,'Тарелкадагы искусство 🥦','Тамагын жебей жатабы? Кээде маселе даамында эмес, берилишинде болот. Аппетитин ачуу үчүн түстүү жашылчалардан күлкүлүү беттерди жасап көрүңүз жана тамактанууну оюнга айлантыңыз.','Kunst sinu taldrikul 🥦','Ei söö oma toitu? Mõnikord pole probleem maitses, vaid serveerimises. Proovi teha värvilistest köögiviljadest naljakaid nägusid, et äratada nende isu ja muuta söömine mänguks.'),
('27428d92-902e-4e8b-a566-975a32a7bf6a'::uuid,'Шаттыктуу күлкү 🤡','Сиздин аракеттериңиз натыйжа бербей жатканда, атасынын күлкүлүү үндөрү жардамга келиши мүмкүн. Кечки ыйлоолор учурунда, демилгени ага өткөрүп бериңиз жана жөн гана четте туруп жылмайып коюңуз.','Rõõmsad kilked 🤡','Kui sinu pingutused ei toimi, võivad issi naljakad hääled päeva päästa. Õhtuste jonnihoogude ajal anna pall talle üle ja naerata lihtsalt kõrvalt.'),
('71ce1c15-b947-45d9-8c0e-c8a77ece4ef7'::uuid,'Үйдөгү тентектер! 🐶','Ал жөн эле үн чыгарбастан, иттей сойлоп, мышыктай эркелеп жатабы? Дене тили жана фантазия укмуштуудай айкалышууда. Килемдин үстүндөгү бул оюнга сиз да кошулуңуз.','Metsikud tegelased kodus! 🐶','Kas ta mitte ainult ei tee hääli, vaid roomab nagu koer ja nurrub nagu kass? Kehakeel ja kujutlusvõime ühinevad hämmastaval moel. Liitu temaga vaibal ja mängi kaasa.'),
('c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133'::uuid,'Жалаң аяктуу укмуштуу окуялар 👣','Кичинекейиңиз өзгөчө жылаңайлак басууну жана ар кандай беттерди изилдөөнү жакшы көрөбү? Тамандын нервдерин стимулдаштыруу алардын неврологиялык өнүгүүсү үчүн баа жеткис, андыктан алардын байпаксыз жүрүүсүнө уруксат бериңиз!','Paljajalu seiklused 👣','Kas su väike põnn armastab eriti paljajalu käia ja erinevaid tekstuure uurida? Taldade närvilõpmete stimuleerimine on nende neuroloogilisele arengule hindamatu, seega lase neil sokivabalt ringi toimetada!'),
('c3c4fb6d-e99b-442f-b18d-4a0a69488a0a'::uuid,'Сиздин санариптик эс тутумуңуз 🛒','Дүкөнгө барганда бир нерсени унутуп кала бересизби? Соода тизмеңиз тиркемеде сизди күтүп жатат. Керектүү нерселериңизди ошол жерге жазып коюңуз, ошондо жолдошуңуз жумуштан кайтып келе жатып, так керектүү нерселерди сатып ала алат.','Sinu digitaalne mälu 🛒','Unustad poes käies alati midagi ära? Sinu ostunimekiri ootab sind äpis. Pane oma vajadused sinna kirja ja su kaaslane saab töölt tulles täpselt vajaliku kaasa osta.'),
('cb069764-7f58-461b-a159-7d553277ecda'::uuid,'Үн менен элестетүү 🪄','Акылдуу жомоктордун жардамы менен бүгүн кечинде балаңыз үчүн өзгөчө укмуштуу окуяны түзүңүз: чаң соргучтан коркпогон эр жүрөк коён жөнүндөгү жомок. Жомок айтып берүү менен коркуу сезимдерин жеңүү абдан оңой.','Hääleline kujutlusvõime 🪄','Loo neile täna õhtul eriline seiklus nutikate lugude abil: lugu vaprast jänesest, kes ei karda tolmuimejat. Hirmude ületamine on jutuvestmise abil nii lihtne.'),
('62149695-6298-4aba-847f-c8ce0b1eb19a'::uuid,'Жабыркаган намыс 🛑','Балаңыз «өзүм эле жасайм!» деп, эч кимдин жардамын каалабай жатабы? Бут кийимин тескери кийип алса да, кийлигишпегенге аракет кылыңыз. Баланын өзүнө болгон ишениминин сакталышы, туура кийилген бут кийимден алда канча маанилүү.','Riivatud ego 🛑','Kas su laps kuulutab „Ma teen ise!“ ja keeldub igasugusest abist? Isegi kui kingad saavad valesse jalga, püüa mitte sekkuda. Terve ego on palju tähtsam kui ideaalselt jalas olevad kingad.'),
('86650154-88a4-4c7d-ab75-32f1a232aa9d'::uuid,'Шектенүүлөрүңүздү токтотуңуз 🤖','Балаңыздын жүрүм-турумундагы күтүүсүз өзгөрүүлөр сизди тынчсыздандырып жатабы? Интернет форумдарынан коркунучтуу ооруларды издебеңиз; Anacan AI аркылуу так, ыкчам жана илимий жактан негизделген маалыматтарды алыңыз.','Lõpeta oma kahtlused 🤖','Kas lapse käitumise äkilised muutused teevad sind murelikuks? Ära otsi internetifoorumitest hirmutavaid haigusi; saa täpseid, kiireid ja teaduslikult põhjendatud fakte Anacan AI-lt.'),
('d8fdf53e-3f50-42fc-a36a-84c2b2cbfbee'::uuid,'Уйку сакчысы 🤫','Уйкуга кеткенден кийинки алгачкы жарым саат — мээ эң активдүү иштеген учур. Бөлмөдөгү ызы-чууну жөнгө салуу үчүн үн өлчөгүчтү колдонуңуз. Кээде жамгырдын жай үнү аларды терең уйкуга батырышы мүмкүн.','Unevalvur 🤫','Esimene pooltund pärast uinumist on aeg, mil aju on kõige aktiivsem. Kasuta helimõõdikut, et tuba kohandada. Mõnikord võib õrn vihmasabin nad sügavasse unne uinutada.'),
('5820d5b6-2a79-44ac-a012-46235cfe81f4'::uuid,'1000 күнгө чейин болгону 5 күн калды! 🎈','Санак аяктап баратат! Сиз укмуштуудай жана тарыхый 1000 күндүк саякатты аяктоо алдында турасыз. Жылмайыңыз, мааракелик майрамдарды жана кызыктуу идеяларды азыртадан пландаштырып баштаңыз!','Veel vaid 5 päeva 1000 päevani! 🎈','Lõpusirge on peaaegu käes! Oled lõpetamas uskumatut ja legendaarset 1000-päevast teekonda. Naerata ja hakka juba planeerima aastapäeva tähistamist ja lõbusaid ideid!'),
('7ac49f38-01ad-4503-8e74-f0a0bf7621d8'::uuid,'Тынч окуу сааты 🥱','Уктоодон баш тартып, каршылык көрсөтүп жатабы? Кээ бир балдар бул мезгилде күндүзгү уйкудан баш тартышат. Урушпай эле, «тынч убакыт» жарыялап, төшөктө жатып китеп карап чыгууну сунуштаңыз.','Vaikne lugemistund 🥱','Keeldub magamaminekust ja võitleb vastu? Mõned lapsed jätavad sel perioodil päevased uinakud vahele. Selle asemel, et võidelda, kuuluta välja „vaikne tund“ ja soovita voodis lihtsalt raamatut sirvida.'),
('d50eb553-5709-43ce-81ea-ce5014437b1a'::uuid,'Сыймыктануу баракчасы 📝','Ушунчалык узак жана түйшүктүү жолдогу эң чоң күчүңүз — ага болгон сүйүүңүз. Маанай күндөлүгүн ачыңыз жана ага келечекте окуй турган, сыймыктануу сезимин ойгото турган кичинекей кат жазыңыз.','Uhke hetke leht 📝','Sellel pikal ja käänulisel teel on teie suurim jõud armastus tema vastu. Ava meeleolupäevik ja kirjuta talle väike, uhkust täis kiri, mida ta tulevikus lugeda saab.'),
('20a1ef6d-4573-433a-a2b7-db48ed6c1114'::uuid,'Кичинекей жардамчы 🧸','Суранганда бут кийимин алып келе алабы? Алардын сөз байлыгы жана түшүнүү жөндөмү туу чокусунда! Үй жумуштарына кичинекей тапшырмалар менен тартуу аркылуу алардын өзүнө болгон ишенимин арттырыңыз.','Väike abiline 🧸','Kas nad toovad tõesti kingad, kui sa palud? Nende sõnavara ja mõistmine on tipus! Tõsta nende enesekindlust, kaasates neid väikestesse kodutöödesse.'),
('9d370453-5ab2-46ed-b11b-b4f3648ebe3e'::uuid,'Башаламан үй, бактылуу эне 🌪','Кирлер үйүлүп, идиш жуугуч толуп калдыбы? Күтө турсун. Бүгүн үй жумуштарын жолдошуңузга тапшырыңыз. Сиз эс алыңыз – сиз бул үйдүн негизги түркүгүсүз.','Segamini kodu, õnnelik ema 🌪','Pesuhunnik on suur, nõudepesumasin täis? Las see ootab. Palu kaaslasel tänased kodutööd enda peale võtta. Puhka – sina oled selle kodu peamine tugisammas.'),
('7794de7c-0d82-4deb-b825-a11099a42226'::uuid,'Уйкусуздук тууралуу кабар 🥱','Уктоодон баш тартып, чыр салып жатабы? Кээ бир балдар бул мезгилде күндүзгү уйкусун таштай башташат. Күрөшүүнүн ордуна, ''Тынч убакыт'' жарыялап, төшөктө оюнчуктар менен тынч ойноону сунуштаңыз.','Teadaanne unetusest 🥱','Keeldub magamaminekust ja võitleb vastu? Mõned lapsed jätavad sel perioodil päevased uinakud vahele. Selle asemel, et võidelda, kuuluta välja „vaikne tund“ ja soovita neil voodis vaikselt mänguasjadega mängida.'),
('a2143b10-3a17-415c-a09b-d16e4c9ace11'::uuid,'Түнкү ыйдын сырын чечүү 😭','Түн ортосунда көзү жумулуу ыйлап ойгонуп, эч кимди укпай жатабы? Ыйдын анализин угуңуз; эгер бул түнкү коркуу болсо, аны ойготууга аракет кылбаңыз. Жөн гана жанында болуп, тынчтандырыңыз.','Öiste nuttude dešifreerimine 😭','Nad on keset ööd nuttes ärganud, silmad kinni, ega kuule kedagi. Kuula nutuanalüüsi; kui tegemist on öise hirmuhoo ehk ööterroriga, ära püüa neid äratada. Ole lihtsalt nende kõrval ja paku lohutust.'),
('df260082-4554-4a41-9637-0bed22c395ae'::uuid,'Тандап жеген мезгилдер 🍝','Кечээ эле жакшы көрүп жеген тамагынан баш тартып жатабы? Тамактануучу үстөлдүн согуш талаасына айланышына жол бербеңиз. Тамактануу трекери менен анын жумалык балансын текшерип, Дени сак рецепттер бөлүмүнөн кызыктуу, креативдүү жасалгаларды табыңыз.','Valiva sööja etapid 🍝','Kas nad keelduvad toidust, mida eile veel jumaldasid? Ära lase õhtusöögilauast saada lahinguvälja. Kontrolli nende iganädalast tasakaalu toitumisjälgijaga ja avasta lõbusaid, loomingulisi esitusviise jaotises Tervislikud retseptid.'),
('32252794-61c5-419d-b7e8-539bc9987fc9'::uuid,'Анатомия сабагы 👀','''Ийиндериң кайда?'' деп сураганыңызда, кармап көрсөтүп жатабы? Анын акыл-эсинин кабыл алуусу тез өсүүдө! Сөз байлыгын байытуу үчүн оюнду дененин татаалыраак мүчөлөрү менен улантыңыз.','Anatoomiatund 👀','Kui küsid „Kus su õlad on?“, kas nad puudutavad ja näitavad neid? Nende vaimne mõistmine on tõusuteel! Jätka mängu keerulisemate kehaosadega, et rikastada nende sõnavara.'),
('520e2a70-086b-4229-864f-4de7f51683ae'::uuid,'Суунун касиети 🛀','Күнү бою чуркап жүрүп, сиз да, балаңыз да чарчадыңыз. Жылуу ванна даярдап, фондо жаратылыштын тынчтандыруучу үндөрүн коюңуз. Суунун гармониясы эң өжөр баланы да уйкуга даярдайт.','Vee vägi 🛀','Pärast päevast ringijooksmist olete nii sina kui ka nemad väsinud. Tee soe vann ja mängi taustaks rahustavaid loodushääli. Vee harmoonia valmistab isegi kõige kangekaelsema lapse uneks ette.'),
('36b1e2d3-b43a-467e-b08f-870a612d1bb5'::uuid,'Ымыркайдын ыйын түшүнүү 🧩','Карды ач эмес, жалаягы таза, бирок дагы эле чыргоолонуп жатабы? Эгер себебин табууга кыйналып жатсаңыз, ошол ыйдын артындагы чыныгы муктаждыкты билүү үчүн Ыйдын анализин колдонуңуз.','Nutukoodi lahtimuukimine 🧩','Kõht pole tühi, mähe on puhas, aga ikka viril? Kui sul on raske põhjust leida, kasuta nutuanalüüsi, et teada saada nutu taga peituv tegelik vajadus.'),
('8083b651-9df8-40f8-a78a-23401da54600'::uuid,'Апалар үчүн даамдуу тамак 🥣','Өз идишин түртүп, сиз жеп жаткан тамакка умтулуп жатабы? Балдар көбүнчө ата-энесинин тандоосуна көбүрөөк ишенишет. Дени сак рецепттер бөлүмүнөн экөөңүздөр тең чогуу ырахаттанып жей турган тамактарды табыңыз.','Emme maitsev roog 🥣','Lükkab taldriku eemale ja sirutab käe sinu toidu järele? Lapsed usaldavad sageli vanemate valikuid rohkem. Tervislike retseptide jaotisest leiad roogasid, mida saate mõlemad koos nautida.'),
('23868e91-8f1b-41db-955e-cd3d4e20a70a'::uuid,'Коляска менен сейилдөө сырлары ⛅','Сейилдөөгө чыкканда аба ырайы сизди алдап, балаңызды жука кийинтип алууга жол бербеңиз. Терезеден карап эле чечим кабыл албаңыз; сырттагы желге ылайыктуу идеалдуу айкалышты табуу үчүн ''Аба ырайы жана кийим тандоо жардамчысын'' колдонуп, сыртка бейкам чыгыңыз.','Vankristrateegiad ⛅','Ära lase ilmal end petta, et last jalutama minnes liiga õhukeselt riidesse panna. Ära otsusta vaid aknast välja vaadates; kasuta „Ilma ja riietuse abilist“, et leida õue tuule jaoks ideaalne kombinatsioon ja suundu mugavalt välja.'),
('418dbea1-2468-4df0-ad94-f76ab3c14a42'::uuid,'Мелатонин фабрикасы 🌙','Алардын тезирээк уктап кетишине жардам берүү үчүн, бөлмөдөгү бардык ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин караңгы жана технологиясыз чөйрөдө гана тез бөлүнүп чыгат.','Melatoniinitehas 🌙','Et aidata neil kiiremini uinuda, lülita toas välja kõik lisatuled ja tahvelarvutite ekraanid. Melatoniini eraldub kiiresti vaid pimedas ja tehnoloogiavabas keskkonnas.'),
('dcb96656-d377-4147-b075-f440d05b3b54'::uuid,'Адептүүлүккө үйрөтүү 👋','Бирөө кетип жатканда кичинекейиңиз өз демилгеси менен кол булгап коштошуп жатабы? Анын социалдык интеллекти жана эмпатиясы чындап өнүгүүдө! Мындай сылык ишараттары үчүн аны көбүрөөк кубаттаңыз.','Käitumiskombed kujunemas 👋','Kas su väike laps lehvitab omal algatusel hüvasti, kui keegi lahkub? Nende sotsiaalne intelligentsus ja empaatia tõepoolest arenevad! Kiida neid viisakaid žeste ohtralt.'),
('181acf25-f33b-4b1f-a3df-4084c1837a73'::uuid,'Оюнчуктардын «дарыгери» 🩺','Оюнчугу түшүп калганда, аны акырын сылап «ыйлаба» деп жатабы? Демек, балаңызда боорукерлик сезими ойгонуп жатат! Инсандык өнүгүүнүн бул алтын учурун «Өсүү күндөлүгүнө» дароо жазып коюңуз.','Kaisukaru tohter 🩺','Kui nende mänguasi kukub, kas nad patsutavad seda õrnalt ja ütlevad: „Ära nuta“? Uskumatu empaatiavõime on tärkamas! Salvesta see isiksuse arengu kuldne etapp kindlasti kohe arengupäevikusse.'),
('41b6bff2-f792-4d2c-a887-2fbdd7ee533a'::uuid,'Уйку үчүн мелатонинди чакыруу 🌙','Балаңыздын тез уктап кетиши үчүн бөлмөдөгү ашыкча жарыкты жана көк экрандарды өчүрүңүз. Уйку гормону (мелатонин) караңгы жана технологиясыз чөйрөдө гана тез иштелип чыгат.','Melatoniini kutsumine uneks 🌙','Et aidata neil kiiremini uinuda, lülita toas välja kõik lisavalgustid ja sinise valgusega ekraanid. Unehormoon (melatoniin) eritub kiiresti vaid pimedas, tehnoloogiavabas keskkonnas.'),
('afdd5971-fffc-43af-9956-3bc9d2687359'::uuid,'Аянтчадагы дипломатия 🧸','Паркта челегин башкалар менен бөлүшпөй жатабы? Бул өзүмчүлдүк эмес, болгону жеке менчик түшүнүгүнүн калыптанышы. Аны уятпай, «дипломатиялык кризисти» чечүү үчүн кезектешип ойноону сунуштаңыз.','Mänguväljaku diplomaatia 🧸','Keeldub pargis oma ämbrit jagamast? See pole isekus, see on lihtsalt isikliku vara avastamine. Häbistamise asemel paku välja kordamööda mängimise süsteem, et „diplomaatiline kriis“ lahendada.'),
('32e0ad68-9613-493b-b8b0-dc5729e770dd'::uuid,'Бирге тазалоо 🧹','Үйдү жыйноо керекпи? Пол шыпырып жатканда, балаңызга чүпүрөк менен сүртүп жардам берүүсүнө уруксат бериңиз. Үй иштерин кызыктуу командалык оюнга кантип айландыруу керектигин блогдорубуздан окуңуз.','Koos koristamine 🧹','Vaja kodu koristada? Kui sa pühid, lase neil aidata lapiga pühkida. Loe meie blogisid, et avastada, kuidas muuta koristamine lõbusaks meeskonnatööks.'),
('a3a1222f-3b9a-40aa-a53c-50cc656ba7c7'::uuid,'Күн тартиби өзгөрүп жатабы? ⏱️','Кечинде уктоо убактысы өтө эле созулуп жатабы? Уйку графигин текшериңиз. Балким, күндүзгү уйкуну кыскартуу же таптакыр алып салуу жана түнкү уйкуну эртелетүү мезгили келгендир.','Kas rutiin muutub? ⏱️','Kas magamaminek venib õhtuti liiga pikaks? Kontrolli uneaja graafikut. Võib-olla on viimane aeg päevaseid uinakuid lühendada või need sootuks kaotada ja magamaminekut varasemaks nihutada.'),
('ee3cf122-8fc4-43ea-906b-ef2165dd428d'::uuid,'«Мен чоңойдум!» деп өжөрлөнүү 🛑','Балаңыз ар бир ишке кийлигишип, ишиңизди жайлатып жатабы? Эгемендүүлүк үчүн болгон бул кызыктуу күрөштө, ага кичинекей, өзү чече ала турган тандоолорду сунуштаңыз.','„Olen juba suur!“ nõudmine 🛑','Kas su laps tahab kõigesse sekkuda, aeglustades asjade käiku? Selles lõbusas iseseisvuse lahingus paku neile väikeseid, hallatavaid valikuid.'),
('98562e83-4876-4c00-8dbc-2ad2897e54b5'::uuid,'1000 күндүк керемет! 👑','КУТТУКТАЙБЫЗ! Сиз бул бороондуу, чарчатуучу, бирок укмуштуудай баалуу сапардын 1000 күнүн ийгиликтүү басып өттүңүз! Бул өзгөчө жетишкендикти дароо белгилеп, Anacan коомчулугунда сыймыктануу менен бөлүшүңүз!','1000 päeva ime! 👑','PALJU ÕNNE! Oled edukalt läbinud 1000 päeva seda tormilist, väsitavat, kuid uskumatult väärtuslikku teekonda! Tähista seda erilist verstaposti kohe ja jaga seda uhkusega Anacani kogukonnas!'),
('c186b66b-55e3-4f3f-9de6-a20601b6d88b'::uuid,'Команданын жеңиш бийи 🥂','Бүгүн кечинде өнөктөшүңүз менен бирге 1000 күндүк чарчоону, көз жашты жана кубанычты белгилеңиз. Шам жагып, бекем командаңыздын жеңишин чоң кубаныч менен майрамдаңыз!','Meeskonna võidutants 🥂','Tähista täna õhtul koos kaaslasega 1000 päeva väsimust, pisaraid ja rõõmu. Süüta küünal ja aplodeeri suure rõõmuga oma murdmatu meeskonna võidule!'),
('f26096f7-035d-44ff-ad7c-b1f1eaade001'::uuid,'Сиз муну жасадыңыз! 📈','Балаңыздын канчалык чоңойгонун караңыз! Алгачкы күндөрдөгү коркуу сезимдери азыр чоң ишенимге алмашты. Сиз бул 1000 күндү сыймыктануу менен басып өттүңүз! Сиз чындап эле укмуштуусуз!','Sa said hakkama! 📈','Vaata, kui kaugele su laps on jõudnud! Nende esimeste päevade haprad hirmud on nüüd asendunud tohutu enesekindlusega. Oled need 1000 päeva sellise uhkusega läbinud! Oled tõeliselt imeline!'),
('0953ad75-dec1-4dc2-9d50-5eb074aad008'::uuid,'Жөн гана кучактоо 🫂','Оюндун, китептин же жомоктун кереги жок. Бүгүн кечинде аны кучактап, жытын искеп, караңгыда анын сиз үчүн канчалык баалуу экенин акырын шыбырап айтыңыз.','Lihtsalt üks kallistus 🫂','Pole vaja mänge, raamatuid ega muinasjutte. Täna õhtul lihtsalt kallista neid, hinga sisse nende magusat lõhna ja sosista pimeduses, kui väärtuslikud nad sulle on.'),
('5cf4179d-ca05-4825-ae51-8ae8bda4be3e'::uuid,'Күндөлүккө жазып коюңуз 📝','Балаңыз уктагандан кийин «Маанай күндөлүгүңүздү» ачыңыз. Бүгүн сизди эмне чарчатты жана эмне күлдүрдү? Сезимдериңизди эркин билдирип, оюңузду тазалап алыңыз.','Raport päevikusse 📝','Pärast seda, kui laps magab, ava oma meeleolupäevik. Mis sind täna kõige rohkem väsitas ja mis pani naerma? Luba endal oma tundeid vabalt väljendada ja mõtted selgeks saada.'),
('f9781f63-e578-4e40-8665-b3d4fa014824'::uuid,'Жеңиштен кийинки чындык 🚀','Кечээки мааракеден кийин бүгүн эртең менен чачылган оюнчуктар жана «каалабайм!» деген сөздөр менен ойгондуңузбу? Жашоо уланууда. Терең дем алыңыз – сиз бул кооз башаламандыктын эң мыкты башкаруучусусуз.','Tegelikkus pärast triumfi 🚀','Pärast eilset aastapäeva ärkasime täna hommikul taas laialipillutud mänguasjade ja „Ei taha!“ hüüete peale! Elu läheb edasi. Hinga sügavalt sisse – oled selle kauni kaose kõige imelisem juht.'),
('fde949fd-c8a2-4b0b-a364-0d008da67880'::uuid,'Күндүзгү уйкудагы кыйынчылыктар 🥱','Уктоодон баш тартып, ыйлап жатабы? 3 жаш тегрегинде кээ бир балдар күндүзгү уйкудан баш тарта башташат. Урушпай эле, «Тынч убакыт» деп жарыялап, төшөктө жатып китеп карап чыгууну сунуштаңыз.','Uinakumured 🥱','Keeldub magamaminekust ja nutab? Umbes 3-aastaselt hakkavad mõned lapsed päevaseid uinakuid vahele jätma. Selle asemel, et võidelda, kuuluta välja „vaikne tund“ ja soovita voodis lihtsalt raamatut sirvida.'),
('092fe7ca-f54f-4986-9a3f-884d05ff6c27'::uuid,'Уйкуга жаткыруунун амалдары 🛌','Бешиктен же керебеттен чыгууга аракет кылып жатабы? Бөлмөнүн коопсуздугун текшериңиз. Чоңдордун керебетине өтүү убактысы жакындап калды.','Magamamineku põgenemisplaan 🛌','Kas nad üritavad võrevoodist välja ronida? Vaata tuba ohutuse seisukohalt üle. Üleminek suure lapse voodisse on lähenemas.'),
('9fdf76d2-ea34-465e-99e8-537978d670c9'::uuid,'«Кантип?» деген суроолор башталды 🤔','«Эмне үчүн?» деген суроолор эми «Бул кантип иштейт?» деген суроого өзгөрдүбү? Ал дүйнөнүн түзүлүшүн түшүнүүгө аракет кылып жатат! Сабырдуу болуп, ага кыска жана логикалык түшүндүрмөлөрдү бериңиз.','„Kuidas?“ küsimuste algus 🤔','Kas „Miks?“-küsimused on nüüd muutumas „Kuidas see töötab?“-küsimusteks? Nad üritavad mõista maailma mehhanisme! Varu kannatust ja paku neile lühikesi, loogilisi selgitusi.'),
('62da6149-1edf-4e2a-abc6-d69d21a43fa4'::uuid,'Эртең мененки көнүгүү: жай жана туруктуу 🐢','Балаңыз «курсак менен жатуу» көнүгүүсүн жактырбай ыйлайбы? Мажбурлабаңыз. Anacan AI''дан: «3 айлык ымыркай үчүн курсак менен жатууну кантип кызыктуу кылсам болот?» деп сурап, тез кеңеш алыңыз.','Hommikune trenn: tasa ja targu 🐢','Kas su beebile ei meeldi kõhuli olemine ja ta nutab? Ära sunni teda. Küsi Anacan AI-lt: „Kuidas muuta kõhuli olemine 3-kuuse beebi jaoks lõbusaks?“ ja saa kiireid nippe.'),
('c9428152-a130-431b-ac89-26275023d613'::uuid,'Апа үчүн тыныгуу ☕','Балаңыз өз алдынча ойноп жатканда, дароо үй иштерине чуркабаңыз. Бөлмөдөгү башаламандык эч жакка качпайт, бирок сиздин энергияңыз түгөнүшү мүмкүн. Отуруп, жылуу кофеңизден ырахат алыңыз.','Paus emmele ☕','Kui su laps mängib omaette, ära torma kohe kodutöid tegema. Toas olev segadus ei kao kuhugi, aga sinu energia võib kaduda. Istu maha ja naudi oma sooja kohvi.'),
('4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67'::uuid,'Ал эмне? Машина экен! ☝️','Кичинекейиңиз баарын көрсөтүп «бул эмне?» деп сурап жатабы? Ал дүйнөнү таанып, ат коюуну каалап жатат! Бул баарлашуудагы чоң кадам. Чарчап турсаңыз да, ал нерселердин атын сабырдуулук менен кайталап бериңиз.','Mis see on? Auto! ☝️','Kas su väike laps näitab kõigele ja küsib „Mis see on?“? Nad ootavad, et sa nimetaksid nende maailma! See on tohutu hüpe suhtlemises. Isegi kui oled väsinud, korda kannatlikult nende esemete nimesid.'),
('fb8b7427-667b-4244-909c-df4ca467d79e'::uuid,'Сиз дагы жөн гана адамсыз 🛑','Бүгүн эч нерсе пландалгандай болбой калдыбы? Өзүңүздү күнөөлөбөңүз. Сиз социалдык тармактардагы жасалма сүрөт эмес, чыныгы энесиз. Балаңызга болгону сиз керексиз.','Sa oled ka lihtsalt inimene 🛑','Kas täna ei läinud miski plaanipäraselt? Ära süüdista ennast. Oled päris ema, mitte sotsiaalmeedia filtreeritud illusioon. Su laps vajab lihtsalt sind.'),
('55bafaf5-82ef-4f88-880d-836cf89145d0'::uuid,'Үндүн күчү 🌊','Кечки маал себепсиз тынчсыздануу сааттары сизди абдан чарчатышы мүмкүн. Бөбөгүңүздү бөлмөсүнө алып кирип, ''Ак ызы-чуу'' (White Noise) бөлүмүнөн ''океан толкундары'' же ''чач кургаткычтын үнүн'' тандаңыз, бул айлана-чөйрөнү заматта тынчтандырат.','Heli vägi 🌊','Tunnid seletamatut õhtust rahutust võivad olla kurnavad. Vii beebi tema tuppa, vali White Noise''i alt ''ookeanilained'' või ''föönimüra'' ja rahusta keskkond silmapilkselt.'),
('a6e787a8-1712-42a4-9b2a-4f48a9e5fc87'::uuid,'Апанын энергиясы кайда кетти? 🔋','Күзгүдөн чарчаган көздөрүңүздү көргөндө өзүңүздү күнөөлөбөңүз. Туура тамактанууга көңүл буруп жатасызбы? Ден соолукка пайдалуу рецепттер бөлүмүнөн 10 мүнөттө даярдалуучу, темирге бай энелер үчүн смузини тандап, күчүңүздү калыбына келтириңиз.','Kus on emme energia? 🔋','Ära süüdista ennast, kui vaatad peeglist oma väsinud silmi. Kas pöörad tähelepanu oma toitumisele? Vali tervislike retseptide sektsioonist 10 minutiga valmiv rauarikas smuuti ja taasta oma energia.'),
('269b7d14-00d0-4c42-84b9-6759e61b0baa'::uuid,'Тандап жеген бала менен күрөш 🥦','Нандын четин же бадыраңдын кесимин ''жагымсыз'' көрүнгөнү үчүн жебей жатабы? Тамак тандап жеген учурлар ар кандай формада болушу мүмкүн. Тамактануу планынан жашылчаларды пюре кылып, байкатпай берүүнүн эң акылдуу жолдорун табыңыз.','Valiva sööja väljakutse 🥦','Ei taha süüa leivakoorikut või kurgiviilu, sest see näeb ''kole'' välja? Pirtsakas söömine võib võtta kummalisi vorme. Avasta toitumiskavast nutikad viisid köögiviljade püreestamiseks ja peitmiseks.'),
('3619cb9e-e29f-4149-9f97-e65685c72f61'::uuid,'Эртең мененки концерт башталды! 🎤','Кичинекейиңиз ойгонуп эле эң катуу үн менен ырдай баштайбы? Анын энергиясы эртең мененки саат 7де эле толуп калат! Көзүңүздү ушалап, кичинекей жылдызыңыздын шоусунан жылмайып ырахат алыңыз.','Hommikune kontsert algab! 🎤','Kas su väike ime ärkab ja hakkab kohe täiest kõrist laulma? Kell 7 hommikul on tema energiavarud täis laetud! Hõõru silmi ja naudi naeratusega oma pisikese popstaari etteastet.'),
('801186a2-f617-44a4-bfbe-39fa8b84707d'::uuid,'Түнкү бешик ыры 🎶','Бүгүн кечинде бөлмөнү таптакыр караңгылатыңыз. Эч кандай техника жок, болгону сиздин шыбыраган үнүңүз болсун.','Õhtune hällilaul 🎶','Tee täna õhtul tuba täiesti pimedaks. Ei mingit tehnikat, ainult sinu sosistav hääl.'),
('bcabe7b8-3e78-42a9-bdf0-3f1883219079'::uuid,'Ооруп жатасызбы же чарчадыңызбы? 😭','Бөбөгүңүз ''себепсиз'' ыйлаганда, өзүңүздү жоготпоого аракет кылыңыз. Көйгөйдү тез аныктап, чечүү үчүн ''Ыйды талдоо'' (Cry Analysis) функциясын колдонуңуз.','Kas valutab või oled väsinud? 😭','Kui beebi nutab ''ilma põhjuseta'', püüa mitte tunda end ülekoormatuna. Kasuta nutianalüüsi funktsiooni, et kiiresti probleem tuvastada ja lahendada.'),
('327e6e73-14c5-44c7-86f9-1b01671cc4cc'::uuid,'Өткөнгө көз чаптыруу 📈','Балаңыздын канчалык өскөнүн караңыз! Алгачкы толкундануу туруктуу ишенимге айланды. Сиз бул жолду чоң жеңиш менен басып өттүңүз!','Tagasivaade 📈','Vaata, kui kaugele su laps on jõudnud! Esialgne elevus on õitsenud vankumatuks enesekindluseks. Oled selle teekonna läbinud suure triumfiga!'),
('4b865d9a-0f66-4cb0-98d0-deaa6f061766'::uuid,'Бир аз романтика 💖','Бүгүн кечинде шамдын жарыгында өнөктөшүңүз менен бул 9 айдын чарчоосун жана сыймыгын белгилеңиз. Сиздер эң сонун командасыздар!','Natuke romantikat 💖','Tähista täna õhtul küünlavalgel koos partneriga nende 9 kuu kurnatust ja uhkust. Te olete suurepärane meeskond!'),
('334b387f-4019-4208-b951-95f53c679a8b'::uuid,'Энергияга болгон муктаждык 🍲','Чарчоо сөөккө чейин жетет. Дени сак рецепттерден 10 мүнөттө даярдалуучу, темир жана протеинге бай түшкү тамакты тандап, күч топтоңуз.','Energiavajadus 🍲','Väsimus kontides. Vali tervislike retseptide hulgast 10 minutiga valmiv raua- ja valgurikas lõunasöök ning kogu jõudu.'),
('495a74f3-0952-464a-80e0-08b1cc46205c'::uuid,'Ызы-чууну жөнгө салуу 🤫','Үйдөгү ызы-чуу анын терең уйкусун бузуп жатат. Фондук ызы-чууну турукташтыруу үчүн үн өлчөгүчтү колдонуңуз, ошондо сиз да татыктуу эс ала аласыз.','Müra kontrollimine 🤫','Kodused helid segavad beebi sügavat und. Kasuta helimõõturit taustamüra stabiliseerimiseks, et ka sina saaksid väärilist puhkust.'),
('73c5a297-0a32-46fb-8b7c-4ca9aeac6cb1'::uuid,'«Жок» деп айтуунун күчү 🛑','Жактырбаган тамагын түртүп, башын чайкап ''жок'' деп жатабы? Анын мүнөзү калыптанып жатат! Анын каалоосун сыйлаңыз.','„Ei“ ütlemise vägi 🛑','Kas ta lükkab toitu eemale ja raputab pead, et öelda ei? Tema isiksus kujuneb! Austa tema tahet.'),
('5238f2b7-2892-49ff-9220-f07d0cf3221d'::uuid,'Күндүзгү чарчоо жетишет. 👨‍🍼','Кечки оюн убактысы, мисалы, бөлмөдө бөбөк менен тоголонуп ойноо — аталар үчүн өзгөчө жоопкерчилик.','Päevasest väsimusest aitab. 👨‍🍼','Õhtune mänguaeg, näiteks beebiga toas püherdamine ja mängimine, on isa eriline vastutus.'),
('c89b6b27-fdbd-4cb8-a5cb-f7ddd8bc2ede'::uuid,'Кенч издөө укмуштуу окуялары 🧺','Кир жуучу себетти бошотуу же шкафтарды тинтүү — анын эң чоң көңүл ачуусу. Эркин ойноого уруксат бериңиз; бул анын кыймыл-аракет жөндөмүн чыңдайт.','Aaretejaht 🧺','Pesukorvi tühjendamine või kappides tuhnimine on tema suurim meelelahutus. Lase tal vabalt mängida; see tugevdab tema motoorseid oskusi.'),
('f0057ec1-cc62-4ea5-9364-5327660ddc30'::uuid,'Суроо берүүдөн тартынбаңыз 🤖','Бөбөгүңүздүн тамагына кайсы татымалдар коопсуз экенин билбей жатасызбы? Кызыккан нерсеңиздин баарына Anacan AI аркылуу заматта жооп алыңыз.','Ära kõhkle küsimast 🤖','Pole kindel, millised vürtsid on beebi toidus ohutud? Küsi Anacan AI-lt koheseid vastuseid kõigele, mis sind huvitab.'),
('00632cb5-4d20-4f2d-9bf8-82242042667b'::uuid,'Акылдуу жомок убактысы 🪄','Бүгүн кечинде жаңы жомок окуп көрүңүз: ''Уктаганды жакшы көргөн сыйкырдуу булут''. Үнүңүздү басаңдатып, жагымдуу маанай түзүңүз.','Nutikas unejutt 🪄','Proovi täna õhtul uut unejuttu: ''Võlupilv, kes armastab magada.'' Langeta häält ja loo rahustav õhkkond.'),
('61c9e192-532e-41bc-9ebb-f2c296bb0670'::uuid,'Эмоционалдык жүктү бөлүшүү 💬','Anacan коомчулугуна кошулуңуз. Кээде башка эненин, атүгүл бейтааныш адамдын комментарийин окуу сизге кофеден да көп энергия бере алат.','Jaga emotsionaalset koormat 💬','Liitu Anacani kogukonnaga. Mõnikord võib teise ema kommentaari lugemine, isegi kui ta on võõras, anda sulle rohkem energiat kui kohv.'),
('92c6be75-a837-4908-b755-b4ae97896380'::uuid,'Тыюу салынган аймактарды изилдөө ⚡','Электр розеткалары жана зымдар анын көңүлүн буруп жатат. Үйүңүздөгү ''тыюу салынган'' аймактарды аныктап, балдар үчүн коопсуздук чараларын кайра текшериңиз.','Keelatud alade avastamine ⚡','Pistikupesad ja juhtmed tõmbavad tema tähelepanu. Määra kodus ''keelatud'' tsoonid ja kontrolli lapsekindlus üle.'),
('159ac401-c76f-42ec-b9e1-bb1a6d73130e'::uuid,'Манжалар менен кармоону үйрөнүү 🤏','Ал полдогу эң кичинекей нерсени да манжалары менен терип ала алат! Анын майда моторикасы абдан жакшы өнүгүп жатат.','Avastamine näpitsvõttega 🤏','Ta suudab sõrmeotstega põrandalt üles korjata ka kõige pisema kübeme! Tema peenmotoorika areneb tõesti kiiresti.'),
('306f7e64-ae54-408a-95b9-ac4f9c3c6684'::uuid,'Кечки бейпилдик 🛀','Күнүмдүк тартипти сактаңыз. Көнүмүш ванна, бирдей массаж майы жана дайыма караңгы бөлмө — түнкү уйкунун алтын ачкычы.','Õhtune rahu 🛀','Pea kinni rutiinist. Tuttav vann, sama massaažiõli ja püsivalt pime tuba on hea une kuldsed võtmed.'),
('f3512bb1-5e87-4250-8249-5c396829b593'::uuid,'Үйдө отуруп тажадыңызбы? ☕','Үйдө отуруп тажадыңызбы? Сиз таза абадан дем алып, бөбөгүңүз өзүн ыңгайлуу сезе турган эң жакын ''Энелерге ыңгайлуу жайды'' табыңыз.','Koduseinte vahele kiilumine ☕','Tunned end kodus vangis? Avasta lähim emmesõbralik koht, kus saate mõlemad värsket õhku ja beebil on mugav olla.'),
('1835b0bb-3338-4b12-9da9-167cd1643dc6'::uuid,'Үй иштерин ким жасайт? 🌪️','Чаң соргучтун үнү кичинекейиңизди коркутуп, үй иштери бүтпөй жатабы? Алар күтө турсун. Өнөктөшүңүздөн бүгүнкү үй иштерин өзүнө алуусун сураныңыз.','Kes teeb kodutööd? 🌪️','Kas tolmuimeja hääl hirmutab su pisikest ja majapidamistööd jäävad pooleli? Las need oodata. Palu partneril tänased kodutööd üle võtta.'),
('be2205ed-6711-45b7-b2f3-ab21216eef54'::uuid,'Эмоционалдык күндөлүк 📝','Өзүңүздү жалгыз сезгенде, сезимдериңизди ''Маанай күндөлүгүнө'' жазыңыз. Эсиңизде болсун, көптөгөн аялдар ушундай эле тажрыйбаны башынан өткөрүшөт — сиз күчтүүсүз жана жалгыз эмессиз.','Emotsioonide päevik 📝','Kui tunned end üksikuna, väljenda oma tundeid meeleolupäevikus. Pea meeles, paljud naised kogevad sarnaseid asju – oled tugev ja sa pole üksi.'),
('cd0245fe-8c0d-4f3e-ad23-05cff2186013'::uuid,'Таштанды челегин изилдөө 🗑️','Жерден эмне тапса да, аны чоң кызыгуу менен изилдейт. Ачууланбаңыз жана колундагынын баарын тартып албаңыз; ал изилдөөчү. Жөн гана көз салып туруңуз.','Prügikasti avastamine 🗑️','Mida iganes ta maast leiab, uurib ta suure uudishimuga. Ära pahanda ja võta kõike käest; ta on avastaja. Lihtsalt hoia tal silm peal.'),
('6ff5d725-a5bb-441a-a5ed-1b1b10bf2638'::uuid,'Атанын колдоосу 🫂','Түнкүсүн ойгонгондо өнөктөшүңүз менен кезектешип туруңуз. Кээде атанын ыргактуу, тынчтандыруучу сыйпалоосу бөбөктү кайра уктатуу үчүн дал керек болгон нерсе.','Issi lohutus 🫂','Vahetage partneriga öiste ärkamiste ajal. Mõnikord on isa rütmiline ja rahustav puudutus just see, mida beebi uuesti uinumiseks vajab.'),
('77c04114-1662-45d9-9778-494a99f15f4f'::uuid,'Аба ырайына алданбаңыз ⛅','Сыртка чыгууну чечүү үчүн терезеден эле карабаңыз. Бөбөгүңүзгө эң ылайыктуу кийимдерди тандоо үчүн аба ырайы жана кийим куралын колдонуңуз.','Ära lase ilmal end petta ⛅','Ära vaata õue mineku otsustamiseks ainult aknast välja. Kasuta ilma ja riietuse tööriista, et leida oma pisikesele ideaalne kihiline riietus.'),
('b630415b-1d8a-4088-bd37-659e6494cb2c'::uuid,'Меники! Бөлүшүүнү үйрөнүү 🧸','Колундагы нерсени алганда нааразы болуп ыйлайбы? Анын ээлик кылуу сезими жана инсандыгы калыптанып жатат. Бул абдан табигый психологиялык этап.','Minu oma! Jagama õppimine 🧸','Kas ta protestib ja nutab, kui võtad midagi tema käest? Tema omanditunne ja individuaalsus arenevad. See on väga loomulik psühholoogiline etapp.'),
('5c4470d4-31c9-42e6-98b2-6ebad58cdce5'::uuid,'Балаңыздын ыйын түшүнүү 😭','Көйгөй тиш жаруубу же ичтин көбүшүбү экенин билүү үчүн ''Ыйды талдоо'' (Cry Analyzer) функциясын колдонуңуз жана тынчсызданууңузду азайтыңыз.','Beebi nutu mõistmine 😭','Kasuta koheselt nutianalüsaatorit, et teada saada, kas probleemiks on hammaste tulek või gaasid, ja leevenda oma muresid.'),
('906becee-91c7-4860-a453-bec23a80f855'::uuid,'Тынчтыкка болгон муктаждык 🤫','Тынч бөлмөнү сактоо үчүн Үн өлчөгүчтү колдонуңуз. Түнкү уйкунун бузулушу бөбөгүңүздүн да, өзүңүздүн да эртең мененки маанайыңызга таасир этиши мүмкүн.','Vaikuse vajadus 🤫','Kasuta helimõõturit, et hoida toas rahu. Öine katkendlik uni võib mõjutada nii beebi kui ka sinu enda hommikust tuju.'),
('93f3b238-cc16-44a9-888c-f9d77043f372'::uuid,'Музыкага бийлөө 🎶','Шайыр музыка ойногондо ыргакка жараша термелеби? Угуу жана кыймыл-аракет жөндөмүнүн ортосундагы байланыш түзүлүп жатат! Шайыр ыр коюп, аны менен бирге бийлеңиз.','Muusika saatel tantsimine 🎶','Kas ta õõtsub rõõmsa muusika rütmis? Kuulmise ja motoorika vaheline seos on tekkimas! Pane mängima rõõmsameelne laul ja tantsi koos temaga.'),
('334464c1-4599-4dd4-83dd-d57c384eb650'::uuid,'Китеп барактоо 📖','Кичинекейиңиз китептин барактарын оодарууга аракет кылып жатабы? Ага түстүү жана кармаганга ыңгайлуу жомокторду көп алып бериңиз!','Raamatute lehitsemine 📖','Kas su pisike üritab papist raamatute lehti keerata? Hangi talle palju värvilisi ja kombatavaid juturaamatuid!'),
('d7009029-eb30-44cd-bedc-77f2ddcbdbe4'::uuid,'Пюреден кесек тамактарга өтүү! 🍲','Кичинекейиңиз чайноону талап кылган тамактарды жегенге даярбы? Тиштей турган тамактарды жегенге өтүү үчүн колдонмобуздун ''Кошумча тамактандыруу'' бөлүмүнөн ар кандай текстурадагы пюре жана шорпо рецепттерин карап көрүңүз.','Püreest tükilise toiduni! 🍲','Kas su pisike on valmis toitudeks, mis nõuavad närimist? Uuri meie äpi ''Tahke toidu alustamine'' sektsiooni, kust leiad erinevaid tekstuurseid püree- ja supiretsepte.'),
('f5716668-d412-4d80-9c29-0a69a23f4f4e'::uuid,'Дүкөндөр тизмеси 🛒','Брокколи же сулу жармасы түгөнүп калдыбы? Соода тизмеңизди заматта жаңыртып, суроо-талапты өнөктөшүңүздүн телефонуна жөнөтүңүз.','Ostunimekiri 🛒','Brokkoli või kaerahelbed said otsa? Uuenda koheselt oma ostunimekirja ja saada soovid partneri telefoni.'),
('16369cf1-7620-428e-8c38-c6f5104fb5ab'::uuid,'Оюнчуктарды кутудан чыгаруу! 🧸','Кичинекейиңиз кутучадагы нерселерди бирден чыгарганды жакшы көрөт. Бул кызыктуу, башаламан ачылыш учурун ''Бөбөк фотосессиясы'' менен тартып алыңыз жана жылмайып эскерип жүрүңүз.','Mänguasjade karbist välja võtmine! 🧸','Sinu pisikesele meeldib asju ükshaaval karpidest välja tõmmata. Jäädvusta see lõbus ja segadust tekitav avastamishetk beebifotoseansiga ja mäleta seda naeratusega.'),
('912a7ba7-5cb9-41f1-9daa-dc1c800036eb'::uuid,'Биринчи кадамдар жакындап калдыбы? 🧗‍♂️','Диванга таянып туруу менен эле чектелбей, дубалды кармап басып жатабы? Балдар үчүн коопсуздук чараларын эки эсе күчөтүүчү убакыт келди!','Kas esimesed sammud on kohe tulemas? 🧗‍♂️','Kas ta ei piirdu enam diivanil püsti tõusmisega, vaid liigub juba mööda seina äärt? On aeg lapsekindlust kahekordistada!'),
('ec70551b-eda4-4e87-86a9-151235d2eb3e'::uuid,'Уйку алдындагы жомок 🪄','Биздин ''Акылдуу жомоктор'' функциясы менен эр жүрөк жана сүйүктүү жаныбарлар жөнүндө сыйкырдуу окуяларды түзүп, бөлмөнү жомок дүйнөсүнө айлантыңыз.','Unejutt uinumiseks 🪄','Loo meie ''Nutikate lugude'' funktsiooniga lummavaid jutte vapratest ja armastatud loomadest, muutes toa maagiliseks paigaks.'),
('39498b75-8a2a-463e-a232-aa6ed7188810'::uuid,'Сиздин үнүңүздүн обонун түшүнөт 🗣️','Сиз катуу үн менен ''болбойт'' дегенде бөбөгүңүз токтоп, сизге карап калабы? Ал эмоцияларды жана чек араларды түшүнө баштады!','Mõistab sinu hääletooni 🗣️','Kas beebi peatub ja vaatab sulle otsa, kui ütled kindla häälega ''ei''? Ta hakkab emotsioone ja piire mõistma!'),
('6d030e22-f99a-4fa8-829a-d62a50ce76e0'::uuid,'Өнүгүүсүн текшерүү 🤖','Балаңыздын физикалык өнүгүүсүндө кечигүүлөр бар деп тынчсызданып жатасызбы? 9 айлык баланын кыймыл-аракет жөндөмдөрү тууралуу Anacan AI аркылуу так маалымат алыңыз.','Arengukontroll 🤖','Muretsed lapse füüsilise arengu viivituste pärast? Hangi Anacan AI-lt selget teavet 9-kuuse lapse motoorsete oskuste kohta.'),
('e607d1aa-9be0-4388-9790-764a5c1e94da'::uuid,'Сиңирүү процессин көзөмөлдөө. 🧷','Кошумча тамактар бөбөгүңүздүн ичеги-карын иштешин өзгөртөт. Ар бир жалаяк алмаштырууну Anacan''га жазып, бөбөгүңүздүн ден соолугуна көз салып туруңуз.','Seedimise jälgimine. 🧷','Tahke toit muudab beebi väljaheidet. Jälgi beebi tervist, logides iga mähkmevahetuse Anacani.'),
('57fa0aeb-432f-4b34-915b-98422c100236'::uuid,'Тиш жаруудагы оору 🦷','Тиштери кызарып, шилекейи кайра агып жатабы? Муздак тиш салгычтарды даярдап коюңуз.','Hammaste tuleku valu 🦷','Kas igemed on jälle punased ja ila voolab? Pane külmad närimisrõngad valmis.'),
('bda23a3e-0646-4246-a5dc-febd245b2bb1'::uuid,'Кайсы эмчектен эмизгениңизди унутуп калдыңызбы? 🤱','Anacan таймери акыркы жолу кайсы эмчектен эмизгениңизди көзөмөлдөйт. Эмизип баштоо үчүн таймерди азыр иштетиңиз!','Unustasid, kummast rinnast toitsid? 🤱','Anacani taimer peab arvet, millisest rinnast sa viimati toitsid. Alusta toitmist taimeriga nüüd!'),
('e2296439-aad7-4bdf-a627-05d1e066a3d8'::uuid,'Уйку режимин көзөмөлдөө. ⏱️','Бөбөгүңүз уктаганда уйку таймерин иштетиңиз, андан кийин 9 айлык балаңыздын күнүмдүк уйку сунуштарына жооп берер-бербесин билүү үчүн диаграмманы текшериңиз.','Jälgi unerežiimi. ⏱️','Aktiveeri unetaimer, kui beebi uinub, ja kontrolli seejärel graafikult, kas su 9-kuune vastab oma igapäevastele unesoovitustele.'),
('13322f59-d734-452d-8178-1ffb4e5e9f78'::uuid,'Эмеректерге чыгуу 🧗‍♂️','Жөн эле сойлоп же басуу ага аздык кылып жатабы? Эмеректерге чыгууга аракет кылып жатабы? Кандай укмуштуудай кыймыл-аракет өнүгүүсү! Болгону, абдан жакшы көз салып туруңуз.','Mööblile ronimine 🧗‍♂️','Kas roomamisest või kõndimisest talle ei piisa? Kas ta üritab mööblile ronida? Milline uskumatu motoorne areng! Lihtsalt hoia tal väga tähelepanelikult silm peal.'),
('b349c13b-d822-42ec-876c-d41ccb790846'::uuid,'Таза аба — эң мыкты дары 🌳','Күнү бою ыйлап, тынчсыздандыбы? Чечими жөнөкөй: Аба ырайын жана кийимди текшериңиз, коляскага салып, түз эле сейил бакка жөнөңүз.','Värske õhk on parim rohi 🌳','Kas ta nuttis terve päeva ja oli rahutu? Lahendus on lihtne: kontrolli ilma ja riietust, pane ta vankrisse ja suundu otse parki.'),
('e46eb59c-0196-4f8a-b3f3-e86458e1f828'::uuid,'Бөлмө акустикасы 🤫','Уйку учурунда кичинекей эле үн бөбөгүңүздү ойготушу мүмкүн. Айлана-чөйрөнү талдоо жана үзгүлтүксүз тынчтыкты камсыз кылуу үчүн Үн өлчөгүчтү колдонуңуз.','Ruumi akustika 🤫','Isegi pisike heli võib beebi une ajal äratada. Kasuta helimõõturit keskkonna analüüsimiseks ja katkematu vaikuse tagamiseks.'),
('3ab1636f-ed5f-47f5-93d7-4ac521edd386'::uuid,'Өзүңүздү жетишсиз сезип жатасызбы? 💬','Anacan коомчулугуна азыр кошулуңуз, башка энелердин колдоочу комментарийлерин окуңуз жана өзүңүздү жеңил сезиңиз.','Tunned end ebakindlalt? 💬','Liitu nüüd Anacani kogukonnaga, loe teiste emade toetavaid kommentaare ja tunne end rahulikult.'),
('62964d86-1e07-4c7f-a135-52c48581ffc5'::uuid,'Бүгүн баары тескери кеттиби?','Тынчсызданбаңыз — эгер бөбөгүңүз ток жана таза болсо, сиз эң сонун иш жасап жатасыз жана чындап эле дүйнөдөгү эң мыкты энесиз!','Kas täna läks kõik viltu?','Ära muretse – kui beebi on söönud ja puhas, teed sa suurepärast tööd ja oled tõesti maailma parim ema!'),
('fa0817a9-00d2-41fc-bdcb-8fdae95932ff'::uuid,'Буюмдардын аттарын үйрөнүү 🧸','''Топ кайда?'' деп сураганда, ал көздөрү менен издеп табабы? Анын таанып-билүү жөндөмү абдан жакшы өнүгүп жатат! Күнүмдүк буюмдардын аттарын атап, аны менен оюндарды ойноңуз.','Esemete nimede õppimine 🧸','Kui küsid ''Kus pall on?'', kas ta otsib seda silmadega ja leiab üles? Tema kognitiivsed oskused arenevad tõesti! Mängi temaga mänge, nimetades igapäevaseid esemeid.'),
('93f4fd0f-1f45-436c-b46b-7acc69d1b899'::uuid,'Эки буттап тең салмак сактоо 🤸‍♂️','Аны колтугунан кармаганда, бутуна тикесинен бекем турабы? Бул маанилүү өнүгүү этабын прогресс трекериңизге жазып коюуну унутпаңыз!','Kahel jalal tasakaalustamine 🤸‍♂️','Kui hoiad teda kaenla alt, kas ta seisab püsti ja toetub jalgadele tugevamalt? Logi see oluline arenguetapp kindlasti oma arengujälgijasse!'),
('b0bdf4f4-2902-43a5-876f-e99b39aef4f9'::uuid,'Сыйкырдуу жомок убактысы 🪄','Биздин ''Акылдуу жомоктор'' коллекциясынан ''Кичинекей баатырдын уктоо сырлары'' менен кечки тартибиңизге түс кошуңуз.','Maagiline unejutt 🪄','Lisa oma õhturutiini värvi meie ''Nutikate lugude'' kollektsiooni looga ''Väikese kangelase uneskäimise saladused''.'),
('c6da7887-a402-4a11-8fbf-8de4d7696325'::uuid,'Тизмелер жашоону жеңилдетет 🛒','Күнүмдүк үй тиричилиги эч качан бүтпөйт. Өзүңүздү стресске салбаңыз; соода тизмеңизди толтуруңуз жана өнөктөшүңүз жумуштан келгенде анын баатыр болушуна мүмкүнчүлүк бериңиз.','Nimekirjad päästavad elu 🛒','Igapäevased majapidamistööd ei lõpe kunagi. Ära stressa; täida oma ostunimekiri ja lase partneril olla kangelane, kui ta töölt koju jõuab.'),
('13035ad4-af08-4b79-ba71-a42ceb60fe5b'::uuid,'Үй-бүлөлүк кеңеш 🛋️','Балаңыз уктагандан кийин, өнөктөшүңүз менен бирге Маанай күндөлүгүндөгү жумалык статистикаңызды карап чыгыңыз. Кайсы күндөрү көбүрөөк стресс болдуңуз? Эмнени башкачараак кылсаңыз болмок? Сиздер бир командасыздар!','Meeskonnavestlus 🛋️','Kui laps magab, vaata koos partneriga üle oma iganädalane statistika meeleolupäevikus. Millised päevad olid stressirohkemad? Mida saaksite teisiti teha? Olete ju meeskond!'),
('1b15944e-9198-4fc4-b86d-0b17af6cdd00'::uuid,'Дарыгерден эмнени сураш керек? 🤖','Ай сайын өтүүчү текшерүүгө барар алдында эмнелерди сурашты билбей жатасызбы? Anacan AI-дан 9 айлык текшерүү үчүн керектүү суроолордун тизмесин сураңыз.','Mida arstilt küsida? 🤖','Ei tea, mida igakuisel kontrollvisiidil küsida? Küsi Anacan AI-lt 9. kuu kontrollvisiidi kontrollnimekirja.'),
('1eda7621-0a6a-4ff0-8efe-ec931b28a106'::uuid,'Үй жумуштарындагы кичинекей жардамчыңыз 🧺','Алар кийимдерди бүктөөгө «жардам берип», баарын кайра чачып жатышабы? Аларды четтетпеңиз! «Жардамдашуу» үчүн аларга кичинекей сүлгү же кездеме бериңиз.','Sinu väike abiline majapidamises 🧺','Kas nad „aitavad“ sul pesu voltida, harutades kõik lahti? Ära tõrju neid! Anna neile väike rätik või riidetükk, millega nad saavad „aidata“.'),
('4e5a485c-972c-4f14-b15e-6d0c1f1b8961'::uuid,'Ванна убагындагы суу ташкыны 🛀','Суу менен ойноо тазалыкка караганда, бөлмөнү аквапаркка айландырууга көбүрөөк окшош. Суу чачыратууга уруксат бериңиз! Жылуу суу жана көңүл ачуу күн бою топтолгон бардык тентектикти жууп кетет.','Vanniskandaal 🛀','Veega mängimise puhul pole oluline puhtus, vaid toa muutmine veepargiks. Lase veel pritsida! Soe vesi ja lõbu pesevad maha kogu päeva jooksul kogunenud jonni.'),
('400a0bc6-f5e7-4dd0-9d49-d6e66ce5c9b6'::uuid,'Бутуңузду караңыз! 👣','Алар буттарын таап алышты! Буттарын кармоого аракет кылган ал күлкүлүү жана таттуу учурду өткөрүп жибербеңиз. «Ымыркайдын фотосессиясын» ачып, стикерлер менен кооздоп, өнүгүүнүн бул маанилүү этабын сүрөткө тартып алыңыз.','Vaata oma varbaid! 👣','Nad avastavad juba oma jalgu! Ära maga maha seda naljakat ja armsat hetke, kui nad üritavad varvastest kinni haarata. Ava beebi fotosessioon, kaunista see kleepsudega ja jäädvusta see suur arenguetapp.'),
('59e058ca-af20-4537-9c74-8aa7eb175af6'::uuid,'Сезимдериңизди билдириңиз 📝','Кечки кофеңизди ичип, Маанай күндөлүгүңүзгө кыскача жазуу калтырыңыз, азыркы сезимдериңизди мурунку айлардагы сезимдериңиз менен салыштырыңыз.','Väljenda oma tundeid 📝','Haara õhtune kohv ja tee meeleolupäevikusse kiire märge, võrreldes oma praeguseid tundeid eelmiste kuudega.'),
('30a7e68c-862a-436f-a801-8270fce13b90'::uuid,'Өзүңүзгө кам көрүңүз 🍲','Эгер сиз дени сак болсоңуз, балаңыз да дени сак болот. Биздин пайдалуу рецепттерден жеңил, 10 мүнөттүк «апалар салатын» тандап алып, ырахаттанып жеңиз.','Hoolitse enda eest 🍲','Kui sina oled terve, on ka su beebi terve. Vali meie tervislike retseptide hulgast kerge 10-minutiline „emme salat“ ja naudi seda.'),
('22cad895-d987-4916-ac97-672fe0a05ac0'::uuid,'Дагы бир кыскача маалымат 📖','Уктагыңыз келбей жатабы? Дагы жомок айтып берүүнү суранып жатабы? Кадимки китептерди колдонбоңуз. «Акылдуу жомоктор» бөлүмүндө алар ойлоп тапкан каармандар менен кыскача жомок түзүп, уктоо процессин аягына чыгарыңыз.','Veel üks kiire mõttekäik 📖','Ei taha magama minna? Viivitad veel lugude jutustamisega? Väldi klassikalisi raamatuid. Loo „Nutikate lugude“ abil lühike unejutt tegelastest, mille nad ise välja mõtlesid, et päevale punkt panna.'),
('daf9dd68-0ed6-4ada-9b16-84c4ff46a8e8'::uuid,'Тиш чыккычты издөө 🦷','Балаңыздын шилекейи агып, баарын тиштеп жатабы? Тиш чыгуу трекери эскертүү жөнөттү! «Сунушталган өнүмдөр» бөлүмүнөн таза силикон же жыгачтан жасалган тиш чыгаргычтарды тандоого эң сонун убакыт.','Närimismänguasja jaht 🦷','Pidev ila voolamine ja kõige närimine? Hammaste tuleku jälgija saadab hoiatuse! See on ideaalne aeg uurida soovitatud toodete sektsioonist puhtaid silikoonist või puidust närimisrõngaid.'),
('32607011-b168-4558-b64b-8c8947e8d9a9'::uuid,'Жылуу ванна, укалоо жана бөлмөнү караңгылатуу. 🛀','Уйкунун туруктуу тартибин сактоо — түнкүсүн үзгүлтүксүз уктоонун негизги сыры.','Soe vann, massaaž ja hämar tuba. 🛀','Järjepidev unerežiim on katkematu ööune peamine saladus.'),
('ca309c2b-9bd6-47c4-bfb8-da0eb88d4f08'::uuid,'Жаңы муундарды изилдөө жана толук сүйлөмдөрдү айтууга аракет кылуу 🗣️','Алар өз тилинде узун сүйлөмдөрдү айтып, сүйлөшүп жатышабы? Бөлмөдөгү эң таттуу кичинекей сүйлөгүчтү кунт коюп угуңуз!','Uute silpide avastamine ja tervete lausete katsetamine 🗣️','Kas nad lalisavad, tehes pikki helijadasid, justkui peaksid oma keeles täispikka vestlust? Kuula tähelepanelikult toa kõige armsamat lobisejat!'),
('4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb'::uuid,'Жашыруун шоколад тыныгуусу 🍫','Апа, биз сиздин ашкана шкафынын артында жашыруун таттуу жеп жатканыңызды көрүп турабыз! Өзүңүздү күнөөлөбөңүз. Бардык ызы-чуу жана башаламандыкка туруштук берүү үчүн сизге глюкоза абдан керек.','Salajane šokolaadipaus 🍫','Emme, me näeme, kuidas sa köögikapi taga salaja midagi magusat näksid! Ära süüdista ennast. Sa väärid seda glükoosilaksu, et tulla toime kogu selle müra ja kaosega.'),
('0d132ba6-d6e9-44f6-a85d-e139c66b9760'::uuid,'Тез маек 🤖','Эмне үчүн балаңыз күндүзгү уйкудан баш тартып жатат? Узун макалаларды окууга убактыңыз жокпу? Сурооңузду түздөн-түз Anacan AI-га жазыңыз жана 3 айлык уйку регрессиясы тууралуу кыска, так жооп алыңыз.','Kiire vestlus 🤖','Miks su beebi äkki päevaund keeldub tegemast? Sul pole aega pikki artikleid lugeda. Kirjuta oma küsimus otse Anacan AI-le ja saa lühike ning selge vastus 3-kuuse uneregressiooni kohta.'),
('3d40ac30-86f9-4dfc-9db8-efd1a5dd1198'::uuid,'Жомоктордун философиясы 🪄','«Акылдуу жомоктор» кайрадан иштейт! Системанын ичине: «Күнү бою ойноп чарчаган жана түнкүсүн кооз түштөрдү көргөн пери тууралуу жомок» деп жазыңыз. Балким, окуп жатып өзүңүз да уктап каласыз.','Muinasjuttude filosoofia 🪄','„Nutikad lood“ on tagasi! Kirjuta süsteemi: Lugu haldjast, kes väsib terve päeva mängimisest ja näeb öösel kauneid unenägusid. Võib-olla jääd lugedes isegi ise magama.'),
('c5c0175d-de40-45a7-97f9-43392b324696'::uuid,'Үйдүн кичинекей диктатору 👑','«Бул жерге отур, тигил жерге эмес!» же «Мен кылам, сен эмес!» деп жатабы? Алар баарын өздөрү башкаргысы келет! Алардын эркин сындырбай, «Сен бул жерге отур, мен тигил жерге отурайын» деп тең салмактуулукту табууга аракет кылыңыз.','Maja väike diktaator 👑','Kas on „Istu siin, mitte seal!“ või „Mina teen, mitte sina!“? Nad tahavad ohje enda käes hoida! Ilma nende tahet maha surumata proovi leida tasakaal, öeldes: „Sina istu siin ja mina istun seal.“'),
('2f5f6f47-30c9-4601-933d-5baa445585db'::uuid,'Атанын укалоо сеансы 💆‍♂️','Күнү бою алардын артынан чуркап, белиңиз ооруп калдыбы? Бала уктаары менен өнөктөшүңүздөн 10 мүнөттүк ийин массажын жасап берүүсүн сураныңыз. Сиз үйүңүздүн тирегисиз, ал эми тиректер да эс алууга муктаж.','Issi massaažiseanss 💆‍♂️','Oled terve päeva jalgadel olnud ja neid taga ajanud, kuni selg valutab. Niipea kui laps magab, palu partnerilt 10-minutilist õlamassaaži. Oled oma kodu tugisammas ja isegi sambad vajavad puhkust.'),
('6c6289cf-6e7c-4e83-a178-d01d67cef488'::uuid,'Кош бойлуу кездеги стилдүү сюрприздер 👗','Кээде балаңыз тоңуп калдыбы же ысып кеттиби деп тынчсызданасызбы? Тартынбаңыз. Терезени карап отурбай, дароо «Аба ырайы жана кийим» бөлүмүн текшериңиз жана система сунуштаган кийим катмарлары менен тынчтаныңыз.','Rasedusaja stiiliüllatused 👗','Kas muretsed vahel, et neil on liiga külm või liiga soe? Ära kõhkle. Selle asemel, et lihtsalt aknast välja vaadata, kontrolli kohe sektsiooni „Ilm ja riietus“ ning hinga kergendatult tänu süsteemi pakutud kihilise riietumise soovitustele.'),
('3908e4ee-6364-4b5e-bf19-9883638e23db'::uuid,'Бөлмөдөгү үндөр 🤫','Уктоо кыйын болуп жатабы? Үн өлчөгүч менен бөлмөдөгү децибел деңгээлин текшерип, телевизордун үнүн басаңдатыңыз.','Toa helid 🤫','Kas uinumine on raske? Kontrolli toa detsibellitaset helimõõtjaga ja keera teleri heli taustamüraks.'),
('ce7b77f8-95b5-4071-bf35-61b06d785d85'::uuid,'Биз бир командабыз! 💖','Оор күндөн кийин өнөктөшүңүз менен отуруп, сүйлөшүүгө убакыт бөлүңүз. Бири-бириңизди колдоо жүктү чындап эле жеңилдетет.','Oleme meeskond! 💖','Pärast rasket päeva võta aega, et istuda partneriga maha ja asjad läbi rääkida. Üksteise toetamine võib koorma tõeliselt poole võrra vähendada.'),
('f3fc49f1-990c-4271-ab6c-21a94434e4c2'::uuid,'Өз коомчулугуңузду табуу 💬','Өзүңүздү абдан чарчаган жана дүйнөдөгү эң чыдамсыз апа сезип жатасызбы? Дароо Anacan коомчулугун ачыңыз. Башка апалар да ушундай кыйынчылыктарды башынан өткөрүп жатканын окуу — эң чоң психологиялык колдоо.','Oma kogukonna leidmine 💬','Tunned end täiesti kurnatuna ja maailma kõige kannatamatuma emana? Ava kohe Anacan Community. Lugemine sellest, et teised emad kogevad samu raskusi, on suurim psühholoogiline tugi.'),
('132d4620-5085-4072-ac1e-81f46dc4e74c'::uuid,'Үн монитору менен уйкуну коргоо 🤫','Сиз толкунданып жатасыз, үйдө даярдыктар жүрүп жатат, бирок балаңыздын уйкусу бузулбашы керек. Үн өлчөгүчтү бөлмөдө калтырыңыз жана ызы-чуу деңгээли чектен ашып кеткенин дароо көрүңүз.','Une kaitsmine beebimonitoriga 🤫','Oled elevil, kodus käivad ettevalmistused, kuid beebi und ei tohiks häirida. Jäta helimõõtja tuppa sisse ja näe kohe, kui müratase ületab piiri.'),
('fab0e5e3-a0d0-40d0-843b-ff548b4b816f'::uuid,'''Бул жакка кел'' дегенге жооп берет 👏','Алар колдору менен «бул жакка кел» деп ишарат кылганды үйрөнүштүбү? Бул сүйкүмдүү кыймылды видеого тартып, эстелик альбомуңузга кошуп коюңуз!','Reageerib käsule „tule siia“ 👏','Kas nad on õppinud käega „tule siia“ viipama? Jäädvusta see armas matkimine kindlasti videole ja lisa oma mälestuste albumisse!'),
('0b91a5b0-1518-4473-b0bb-59cec89d7f6f'::uuid,'Маектешүүлөр жанданууда! 🗣','️ Ал таттуу «ма-ма, ба-ба» диалогдорун билим берүүчү кылуу үчүн, Блогдордогу сөз өнүктүрүү боюнча кеңештерибизди окуңуз.','Vestlused muutuvad elavamaks! 🗣','️ Et muuta need armsad „ma-ma, ba-ba“ dialoogid harivaks, loe meie kõne arengu nõuandeid blogidest.'),
('3bcabb18-ba8e-4729-bb3a-959b28fdcaeb'::uuid,'Булуттарды кароонун керемети ⛅','Төрт дубалдын арасында муунуп жатасызбы? Аба ырайына жараша кийинип, сейил бакка барыңыз. Жөн гана отуруп, булуттардан ар кандай формаларды издеңиз. Бул «пассивдүү оюн» мээни эс алдырат жана стимулдайт.','Pilvede vaatamise võlu ⛅','Tunned end nelja seina vahel lämbumas? Riietu vastavalt ilmale ja suundu parki. Lihtsalt istu ja otsi pilvedest kujundeid. See „passiivne mäng“ nii lõdvestab kui ka stimuleerib aju.'),
('ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5'::uuid,'Эне сүтүн көбөйтүүчү азыктар. 🍲','Бүгүн биздин «Аялдар үчүн пайдалуу рецепттер» бөлүмүндөгү эмчек сүтүн көбөйтүүчү шорполорду жасап, күчүңүздү калыбына келтириңиз.','Toidud, mis toetavad rinnapiima teket. 🍲','Turguta täna oma jõudu, proovides meie „Tervislikud retseptid naistele“ sektsiooni piimaeritust soodustavaid suppe.'),
('db929314-83ca-4372-8890-03ef676e68e5'::uuid,'Себепсиз ыйлоо абдан чарчатышы мүмкүн. 😭','Божомолдоп убара болбоңуз! Алардын тынчсыздануусунун себебин түшүнүү үчүн Ыйды талдоо функциясын колдонуңуз.','Seletamatud nutuhood võivad olla kurnavad. 😭','Ära kurna end ära püüdes arvata! Kasuta nutu analüüsi funktsiooni, et mõista nende jonni algpõhjust.'),
('9de02d84-1ac6-4478-a817-67045fcd6af5'::uuid,'Алардын биринчи кичинекей калптарыбы? 🤥','«Сууну мен төккөн жокмун, оюнчук аюум төктү» деп жатабы? Этият болуңуз! Алардын фантазиясы өнүккөнү ошончолук, алар өздөрүнө пайдалуу окуяларды ойлоп таба алышат. Аларды калп айтып жатат деп айыптабаңыз; тескерисинче, жылмайып: «Оюнчук аюуңа мындан ары төкпөсүн деп айтып кой!» деңиз.','Kas need on esimesed väikesed valed? 🤥','Kas on „Mina ei ajanud vett ümber, kaisukaru ajas“? Ole ettevaatlik! Nende kujutlusvõime on arenenud nii kaugele, et nad suudavad enda kasuks lugusid välja mõelda. Ära süüdista neid valetamises; naerata hoopis ja ütle: „Ütle kaisukarule, et ta enam ümber ei ajaks!“'),
('72b7b721-7f37-4054-90fd-05ac29f9ff3c'::uuid,'Тынчсыздануу үчүн музыкалык терапия 🎶','Эгер балаңыз бүгүн кечинде тынчсызданып жатса, Ак ызы-чуу бөлүмүнөн эненин курсагындагы үндү коюп, аны дароо тынчтандырыңыз.','Heliteraapia ärevuse vastu 🎶','Kui beebi on täna õhtul rahutu, rahusta teda kohe, mängides valge müra alt ema üsas kostvaid helisid.'),
('3af3aa71-d08b-4f87-af96-9527f5f91ec1'::uuid,'Эртең мененки көнүгүү! 🤸‍♂️','Сиз дагы эле уйкулуусуз, бирок алар төшөктө секирип жатышабы? Дүйнөдөгү эң катуу, бирок эң сүйкүмдүү ойготкуч! Күнүңүздү алардын чексиз энергиясын кучактап, жылмаюу менен баштаңыз.','Hommikuvõimlemine! 🤸‍♂️','Oled veel poolunes, aga nad hüppavad juba voodis su peal? Maailma kõige valjem, kuid armsaim äratuskell! Alusta oma päeva naeratusega, võttes vastu nende piiritu energia.'),
('9877e456-4a5e-45a3-aee9-e9703be5cf91'::uuid,'Куттуктайбыз! 🥂','Бардык жазууларыңызды жана өсүү графиктериңизди карап чыгыңыз. Кичинекейиңиз канчалык чоңойгонун жана сиз канчалык күчтүү болгонуңузду көрүңүз. Өзүңүз менен сыймыктанууга эң сонун убакыт!','Palju õnne! 🥂','Vaata tagasi kõigile oma märkmetele ja kasvugraafikutele. Näe, kui palju su väike on kasvanud ja kui palju tugevamaks oled sina muutunud. See on ideaalne aeg enda üle uhkust tunda!'),
('8c84402b-2c57-4668-ad1d-96d138e6ba29'::uuid,'Тизмеси жок азык-түлүк алуу 🛒','Базарга барып, эң керектүү нерсени албай кайттыңызбы? Бул «апалардын унутчаактыгы». Эстутумуңузга таянбаңыз; ар бир майда муктаждыкты дароо Соода тизмесине кошууну адат кылыңыз.','Toidupoes ilma nimekirjata 🛒','Käisid poes ja tulid tagasi ilma kõige olulisema asjata? See ongi „emme aju“. Ära looda oma mälule; tee endale harjumuseks lisada iga väike vajadus kohe ostunimekirja.'),
('90c41ad8-7de7-4c6d-ba3d-cf1aad328939'::uuid,'Шам жарыгында чай ичүү 🕯️','Бала уктады. Жарыкты өчүрүп, столго шам жагыңыз. Бул романтика үчүн эмес, жөн гана узак күндөн кийин чарчаган көзүңүздү жана нервиңизди эс алдыруу үчүн.','Küünlavalgel teeaeg 🕯️','Laps magab. Kustuta tuled ja süüta laual küünal. See pole romantika jaoks, vaid lihtsalt selleks, et rahustada oma ülestimuleeritud närve ja väsinud silmi pärast pikka päeva.'),
('b335cc4c-9dc2-482d-a2f2-b6bcbf3a72f9'::uuid,'Уйку алдындагы жомок 🪄','Биздин ''Акылдуу жомоктор'' функциясы менен эр жүрөк жана сүйүктүү жаныбарлар жөнүндө сыйкырдуу окуяларды түзүп, бөлмөнү жомок дүйнөсүнө айлантыңыз.','Unejutt uinumiseks 🪄','Loo meie ''Nutikate lugude'' funktsiooniga lummavaid jutte vapratest ja armastatud loomadest, muutes toa maagiliseks paigaks.'),
('4390f43b-f533-4c56-8aa2-5901fd06c8f5'::uuid,'AI: Чыныгы жардам, реалдуу чечимдер 🤖','Балаңыздын тентектигинин психологиялык себептерин ойлонуп жатасызбы? Интернеттен коркунучтуу макалаларды издебеңиз. Anacan AI-дан 33 айлык балдардын кыяңкечтиги тууралуу илимий, кыскача түшүндүрмө сураңыз.','AI: Päris abi, päris lahendused 🤖','Huvitab lapse trotsi psühholoogiline põhjus? Ära otsi internetist hirmutavaid artikleid. Küsi Anacan AI-lt teaduslikku ja lühikest selgitust 33-kuuste laste jonnihoogude kohta.'),
('36d1de0a-5eb5-4e0f-98ce-a583a10b254e'::uuid,'Аба ырайына алданбаңыз ⛅','Сыртка чыгууну чечүү үчүн терезеден эле карабаңыз. Бөбөгүңүзгө эң ылайыктуу кийимдерди тандоо үчүн аба ырайы жана кийим куралын колдонуңуз.','Ära lase ilmal end petta ⛅','Ära vaata õue mineku otsustamiseks ainult aknast välja. Kasuta ilma ja riietuse tööriista, et leida oma pisikesele ideaalne kihiline riietus.'),
('9b7b163b-1de2-4ecd-becc-21f1f3c0e10e'::uuid,'Командалык жеңиш 💖','Балаңызды атайын уйку таймери менен жаткырыңыз. Эми өнөктөшүңүз менен бетме-бет отуруңуз. Бул 90 күндүн ар бир көз ирмеми үчүн бири-бириңизге ыраазычылык билдириңиз. Бул бала үчүн гана эмес, сиздердин ата-энелик жолуңуздар үчүн да маанилүү үч ай болду!','Meeskondlik võit 💖','Pane beebi magama selle spetsiaalse unetaimeriga. Nüüd istuge partneriga näost näkku. Tänage üksteist iga hetke eest neil möödunud 90 päeval. See pole beebi jaoks vaid kolm kuud, vaid ka teie vanemluse jaoks!'),
('5c67089a-581e-455d-b113-f87f427babb2'::uuid,'Сиздин өзгөчө жомогуңуз 🪄','Бүгүн кечинде «Акылдуу жомокторго» таттуу тема берели: Асмандан түшкөн эң таттуу жылдыз тууралуу жомок. Бөлмөнү ушул жомоктун үнү жана толук тынчтык гана толтурсун.','Sinu enda eriline muinasjutt 🪄','Täna õhtul anname „Nutikatele lugudele“ magusa teema: Lugu kõige armsamast tähest, mis kukkus taevast alla. Las tuppa jääb vaid selle loo heli ja täielik vaikus.'),
('70560836-1d71-42c8-8235-1ad990694b3b'::uuid,'Күнүмдүк тартиптин бузулушу ⏱️','Кечинде уктоо бир сааттан ашык убакытты алабы? Уйку таймеринин графигин текшериңиз. Балким, күндүзгү уйкуну кыскартуу же таптакыр алып салуу жана уктоо убактысын эртелетүү керек болуп жаткандыр.','Rutiini libisemine ⏱️','Kas magamaminek võtab õhtuti kauem kui tund aega? Kontrolli unetaimeri ajakava. Võib-olla on viimane aeg lühendada või isegi kaotada päevased uinakud ja nihutada magamaminek varasemaks.'),
('dfed41fd-982b-4955-b70f-6d43247a4468'::uuid,'Чач тараган кездеги кырсык 🪮','Кичинекейиңиз чачын тараганда же колуңуз тийгенде эле эң чоң азап чегип жаткандай кыйкырабы? Бул күрөштү токтотуңуз. Алгач таракты ага бериңиз, ал сиздин чачыңызды тарасын. Андан кийин, анын кезеги!','Juuste kammimise katastroof 🪮','Kas su väike karjub, nagu oleks juuste kammimine või puudutamine suurim piinamine? Tee võitlusele lõpp. Esmalt anna kamm talle ja lase tal oma juukseid kammida. Siis on nende kord!'),
('66bd508e-0413-4d01-9ea7-c369b0d8cafa'::uuid,'Ата менен ойноо убактысы! 👨‍👧','Чыдамыңыз түгөнүп баратабы? Бүгүн бир аз убакытка ата-энелик милдетти өнөктөшүңүзгө өткөрүп бериңиз. Алар бала менен жалгыз убакыт өткөрүп ырахат алышсын, ал эми сиз бутуңузду сунуп эс алыңыз.','Issi mänguaeg! 👨‍👧','Kannatus hakkab katkema? Anna täna vanemlik vahetus korraks partnerile üle. Las nad naudivad kahekesi olemist ja sina lihtsalt pane jalad seinale ja lõõgastu.'),
('14c6187e-df8b-47e8-b44f-9bc87c4b9143'::uuid,'Түнкү тынчтык 🤫','Эгер унаанын же сырткы ызы-чуулар балаңызды тынчсыздандырса, фондо үзгүлтүксүз ак ызы-чуу булагын камсыз кылыңыз.','Öine vaikus 🤫','Kui auto- või välismüra beebit häirib, paku kindlasti taustaks pidevat valget müra.'),
('5b72c8ce-753e-4283-9bd2-18995d662a91'::uuid,'Темирдин күчү 🥩','Балаңыздын өңү кубарып же табити начарлап жатабы? Тамактануу трекери аркылуу темирдин деңгээлин текшериңиз. Витаминдердин сиңишин дароо жогорулатуу үчүн эт менен кошо лимон кошулган салат бериңиз.','Rauavaru täiendamine 🥩','Kas su laps näeb kahvatu välja või on tal kehv isu? Kontrolli toitumisjälgija abil tema rauatarbimist. Serveeri lihaga alati sidruniga maitsestatud salatit, et vitamiinide imendumist kohe kiirendada.'),
('8474a75e-7aaf-420e-b5ab-acd7d55ac51c'::uuid,'Күлкү убактысы! 😂','Алар эми жөн эле жылмайбай, катуу күлүп жатышат! Алар менен ойноңуз, курсагын кытыгылаңыз. Бул күлкү — уйкусуз түндөрдүн эң сонун сыйлыгы.','Naeru aeg! 😂','Nad ei naerata enam lihtsalt, nad naeravad valjusti! Mängi nendega mänge, kõdita nende kõhtu. See heli on kõige ilusam tasu kõigi nende unetute ööde eest.'),
('0027b4ad-2816-4a79-ae3a-7ddbdcf29e4b'::uuid,'Уйкунун белгилери 🥱','Көзүн ушалап, кулагын тартып же боштукту карап жатабы? Түнкү капризди күтпөңүз. Бул белгилерди байкаарыңыз менен бөлмөнү караңгылатып, уйку алдындагы тартипти баштаңыз.','Unemärgid 🥱','Hõõrub silmi, sikutab kõrvu või vaatab tühjusesse? Ära oota öist kriisi. Niipea kui märkad neid märke, tee tuba pimedaks ja alusta unerežiimiga.'),
('b0a26358-dcc7-4a57-8694-6e91e9d4baaa'::uuid,'Оюнчуктарды бөлүшүү сабагы 🧸','Сейил бакка барардан мурун кичине маектешип алыңыз: «Бүгүн оюнчуктарыбызды кезектешип бөлүшөбүз». Ооба, алар дароо эле бөлүшө албашы мүмкүн, бирок бул түшүнүктү кайталап угуу убакыттын өтүшү менен аң-сезимине сиңет.','Mänguasjade jagamise õppetund 🧸','Enne parki minekut pea väike vestlus: „Täna jagame mänguasju kordamööda.“ Jah, nad ei pruugi veel täiuslikult jagada, kuid selle mõiste kordamine aitab neil aja jooksul asjast aru saada.'),
('c1d1533f-3d3f-4fb5-a549-d74668c72b3d'::uuid,'Атанын уктоо тактикасы 👨‍🍼','Түнкүсүн пижама кийгиси келбей качып жатабы? Топту атасына ыргытыңыз! Ал кийиндирүү процессин күрөш же кызыктуу оюнга айландырганда, бала өзү да байкабай пижамасын кийип калат.','Issi unetaktika 👨‍🍼','Ei taha õhtul pidžaamat selga panna ja jookseb eest ära? Anna pall üle issile! Kui tema muudab riietumise maadlusmatšiks või naljakaks mänguks, on lapsel pidžaama seljas, ilma et ta arugi saaks.'),
('1867104a-7fa8-428a-ad5d-dd10e6890f0f'::uuid,'Ооз аркылуу изилдөө кызыктуу 🤤','Колуна тийген оюнчуктарды, буюмдарды дароо оозуна салып жатабы? Бул анын дүйнөнү таанып-билүү жолу. Баарын тартып албаңыз, жөн гана айланасындагы буюмдардын тазалыгына көз салыңыз.','Suuga avastamise rõõm 🤤','Kas ta topib käsi, mänguasju ja kõike muud otse suhu? See on tema viis maailma avastada. Ära võta kõike ära, veendu lihtsalt, et ümbritsevad esemed oleksid puhtad.'),
('36c8e54c-04ef-4b47-9a2f-c0754b0990c9'::uuid,'Жыгылып, кайра туруу менен үйрөнүү 🧗‍♂️','Диванды карманып басып, жыгылып, кайра дароо туруп жатабы? Ал туруктуулукту үйрөнүп жатат! Эч кандай чочулоосуз, аны жумшак колдоп коюңуз.','Õppimine kukkudes ja uuesti tõustes 🧗‍♂️','Kas ta liigub mööda diivanit, kukub ja tõuseb kohe uuesti püsti? Ta õpib visadust! Julgusta teda õrnalt, ilma liigse ärevuseta.'),
('c0c6e209-b8c8-4325-bc8e-9d4231949abd'::uuid,'Тиш чыгуудагы кыйынчылыктар 🦷','Тиштин бүйлөсү кызарып, шилекейи агып жатабы? Тиш жарып жаткан окшойт! Муздак тиш салгычтарды даярдап коюңуз.','Hammaste tuleku mured 🦷','Igemed punased ja ila voolab jälle? Tundub, et hambad tulevad! Hoia külmad närimisrõngad käepärast.'),
('3aee856b-a30f-48de-84ad-3c91f83ed092'::uuid,'Жаратылыш кереметтери 🍁','Сейил бакта жөн эле баспай, аны оюнга айлантыңыз: «Кел, эң чоң сары жалбыракты табалы!». Жаратылыш — алар үчүн эң мыкты жана интерактивдүү окуу классы.','Looduse imed 🍁','Selle asemel, et lihtsalt pargis jalutada, muuda see mänguks: „Leiame kõige suurema kollase lehe!“ Loodus on nende jaoks parim ja kõige interaktiivsem klassiruum.'),
('4ad3cf84-0aac-46cb-bfdf-5a928764105a'::uuid,'Эмне үчүн үй мынчалык башаламан? 🌪️','Бөлмөнүн ортосундагы оюнчуктарды жана жуулбаган идиштерди карап, өзүңүздү күнөөлөп жатасызбы? Ал идиштер бүгүн ошол жерде эле тура берсин. Бала тарбиялоо — өзү эле чоң эмгек!','Miks on maja nii sassis? 🌪️','Vaatad keset tuba olevat mänguasjahunnikut ja pesemata nõusid ning süüdistad end? Las need nõud jäävad täna sinna, kus nad on. Lapse kasvatamine on juba iseenesest hiiglaslik töö!'),
('65f53c0c-e8ea-4257-8798-e79b9ed847be'::uuid,'Сиз жеп жаткан тамактан даам таткысы келет! 🥣','Сиздин тарелкаңыздагы нерселердин баарына кол сунуп жатабы? Тамакка болгон кызыгуусу туу чокусуна жетти! Өзү кармап жей ала турган кичинекей, коопсуз тамактарды сунуштаңыз.','Tahab maitsta seda, mida sina sööd! 🥣','Kas ta sirutab käe kõige järele, mis su taldrikul on? Huvi toidu vastu on tipus! Paku talle väikeseid ja ohutuid näputoite, mida ta saab ise süüa.'),
('bbfc7848-e7f7-4bfa-a960-a2aeb003f7a4'::uuid,'Эмоционалдык күндөлүк 📝','Жалгыздык сезилип жатабы? Сезимдериңизди «Маанай күндөлүгүнө» төгүңүз. Жазуу абдан жакшы терапия болуп, өзүңүздү жеңил сезүүгө жардам берет.','Emotsioonide päevik 📝','Tunned end üksikuna? Vala oma emotsioonid meeleolupäevikusse. Kirjutamine võib olla uskumatult teraapiline ja aidata sul end paremini tunda.'),
('746f5afe-3705-4073-a3c0-ff69e92f5a25'::uuid,'Кир жуугуч машинага кызыгуу 🧺','Кичинекейиңиз кир жуугуч машинанын айланып жаткан кийимдерин таң калуу менен карап жатабы? Бул таптакыр бекер жана таң калыштуу тынчтандыруучу көңүл ачуу! Анын көңүлүн бурбаңыз; бул учурдан пайдаланып өзүңүз да эс алып алыңыз.','Vaimustus pesumasinast 🧺','Kas su väike laps on pesumasinas pöörlevatest riietest lummatud? See on täiesti tasuta ja üllatavalt rahustav meelelahutus! Ära katkesta tema keskendumist; kasuta võimalust ja puhka ise.'),
('2e4ec0c9-5de6-407d-9e5d-26c67a8ecc5b'::uuid,'Оодарылуу көнүгүүсү 🤸‍♂️','Аркасынан ичине оодарылууга аракет кылып жатабы? Бул кичинекей дене үчүн чоң күрөш. Анын сүйкүмдүү аракеттерин колдоңуз, бирок керебеттин четтеринде өтө этият болуңуз.','Külje keeramise harjutamine 🤸‍♂️','Ta üritab seljalt kõhule keerata! See on selle väikese keha jaoks suur pingutus. Toeta tema armsaid katseid, kuid ole voodiservade läheduses eriti ettevaatlik.'),
('91aad506-9119-4c1d-9011-ca750f77b2da'::uuid,'Сиздин бар болушуңуз жетиштүү! 💖','Бүгүн эртең менен күзгүдөн каранып, чарчаганыңызды, балким, жетишсиз экениңизди сездиңизби? Терең дем алыңыз. Сизди карап турган балаңыздын күнөөсүз көздөрү үчүн сиз дүйнөдөгү эң идеалдуу адамсыз. Сиз жетиштүүсүз!','Sa oled piisav! 💖','Kas vaatasid hommikul peeglisse ja tundsid end väsinuna, võib-olla isegi ebakindlana? Hinga sügavalt sisse. Sinu lapse süütute silmade jaoks, mis sulle alt üles vaatavad, oled sa maailma kõige täiuslikum inimene. Sa oled piisav!'),
('8da8a36e-5d67-4dd0-ac14-245b62a8846a'::uuid,'Маанай күндөлүгүндөгү мойнуна алуу 📝','Телефонуңузду алыңыз. Социалдык тармактарды карагандын ордуна, «Маанай күндөлүгүңүздү» ачып, бүгүн сизди жиндендирген нерселердин баарын жазып, ичиңиздегини чыгарыңыз. Санарип терапиясы иштейт.','Ülestunnistus meeleolupäevikus 📝','Võta telefon kätte. Selle asemel, et sotsiaalmeedias kerida, ava oma meeleolupäevik ja kirjuta üles kõik, mis sind täna marru ajas, kuni oled kogu frustratsiooni välja elanud. Digitaalne teraapia toimib.'),
('71f7d0fb-698f-4308-ad55-a95583a3469b'::uuid,'Мелатонин учуру 🌙','Уйку гормонунун иштешине жардам берүү үчүн, уктаардан кеминде бир саат мурун сыналгы жана планшет сыяктуу көк жарык булактарын өчүрүңүз. Караңгылык жана тынчтык — жакшы уйкунун эң мыкты дабасы.','Melatoniini hetk 🌙','Et aidata unehormoonil tööle hakata, lülita vähemalt tund enne magamaminekut välja sinise valguse allikad, nagu telerid ja tahvelarvutid. Pimedus ja vaikus on hea une parimad ravimid.'),
('9d1de334-e45a-491d-8075-45ce379df7ad'::uuid,'''Мен апамын!'' оюну 🎭','Балаңыз куурчагын сөөмөйү менен коркутуп, сиздин үнүңүз менен сүйлөп жатабы? Бөлмөдө сиздин кичинекей көчүрмөңүз жүрөт! Өзүңүздү анын оюнунан көрүү күлкүлүү да, өз жүрүм-турумуңузга байкоо салуу үчүн жумшак эскертүү да болушу мүмкүн.','„Olen emme!“ mäng 🎭','Kas su laps ähvardab oma nukku viibutava sõrmega, kasutades sinu hääletooni? Sul jookseb toas ringi sinu väike koopia! Enda peegeldust mängus nägemine võib olla nii naljakas kui ka õrn meeldetuletus jälgida omaenda käitumist.'),
('d2c3bcc6-5492-42b4-857f-d6ad8a442199'::uuid,'Өнүгүүнү текшерүү 🤖','Кошумча тамак киргизүү боюнча суроолор тынчсыздандырып жатабы? 9 айлык баланын менюсу үчүн Anacan AI''дан сурап, тынчсызданууңузду азайтыңыз.','Arengu kontroll 🤖','Kas sul on mõtteis küsimusi tahke toidu tutvustamise kohta? Küsi Anacan AI-lt 9-kuuse beebi menüüd, et oma muresid leevendada.'),
('69d7aa9d-fa7f-4594-a0de-a2ff1fbdebb6'::uuid,'Сыйкырдуу жомок убактысы 🪄','Бүгүн кечинде башкача жомок айтып көрүңүз: «Уктаганды жакшы көргөн сыйкырдуу булут». Үнүңүздү акырындатып, уйку үчүн бейпил маанай түзүңүз.','Maagiline jutuvestmise aeg 🪄','Proovi täna õhtul teistsugust unejuttu: „Maagiline pilveke, kes armastas magada.“ Langeta häält ja loo magamiseks rahulik õhkkond.'),
('ae31e811-95f5-438c-9d8f-7b39b14eed84'::uuid,'Буюмдарды ордуна коюуга аракет кылуу 🧸','Оюнчукту кутуга салып, кайра чыгарып жатабы? Ал «ичинде» жана «сыртында» деген түшүнүктөрдү үйрөнүп жатат!','Püüab asju tagasi oma kohale panna 🧸','Kas ta paneb mänguasja karpi ja võtab selle siis jälle välja? Ta avastab „sees“ ja „väljas“ mõisteid!'),
('cc5d4a21-5a6c-4726-9656-04a48085588c'::uuid,'Канчалык чарчадык? 🛋️','Бала уктады, ал эми сизчи? «Маанай күндөлүгүңүздү» ачып, өнөктөшүңүз менен бирге бүгүнкү башаламандыкты тамаша менен жазып коюңуз. Оор күндөр өтөт, бирок ынтымагыңыз калат.','Kui väsinud me oleme? 🛋️','Beebi magab, aga kuidas on lood sinuga? Ava oma meeleolupäevik ja kroonige koos partneriga tänast kaost väikese huumoriga. Rasked päevad mööduvad, aga teie meeskonnavaim jääb.'),
('8557b605-4ddd-4ff9-9e9a-646d4a26ea63'::uuid,'Уйкунун бузулушу жакындап жатабы? 🤖','Балаңыз күтүлбөгөн жерден түнкүсүн көп ойгоно баштадыбы? Кабатыр болбоңуз, 4 айлык уйку регрессиясы болушу мүмкүн. Бул биологиялык процесс тууралуу тез жана ишенимдүү маалыматты дароо Anacan AI''дан алыңыз.','Kas une regressioon on lähenemas? 🤖','Kas su beebi on äkki hakanud öösiti sageli ärkama? Ära muretse, 4-kuune unetaandareng võib olla lähenemas. Hangi Anacan AI-lt kiiresti ja rahustavalt teavet selle bioloogilise protsessi kohta.'),
('fc7921b2-eab6-4a37-aad0-63611df47ad7'::uuid,'Уйкуга жаткыруудагы күрөш 🥱','Уктагысы келбей жатат, бирок көздөрү уйкудан оорлошуп жатабы? Бул каршылык 3 жаш тегрегинде кадимки көрүнүш. Мажбурлабаңыз; бөлмөдөгү жарыкты өчүрүп, «Тынч китеп окуу убактысын» жарыялаңыз.','Uinakuvõitlused 🥱','Ta ei taha magama minna, aga silmad on unest rasked? See vastupanu on 3-aastaste seas klassika. Ära sunni; hämarda toas tuled ja kuuluta välja „vaikne raamatu lugemise aeg“.'),
('2a74e43d-d2e3-45ad-8762-627a59c365b2'::uuid,'Эртең мененки кыжырдануу 🔴','Тамагын жашыл тарелкага сурап, алып келгениңизде «Мен кызыл дедим эле!» деп ыйлап жатабы? Бул жерден логика издебеңиз. Жөн гана тамакты кызыл тарелкага которуп, өз нервиңизди сактап калыңыз.','Hommikune jonnihoog 🔴','Ta palus toitu rohelisel taldrikul, aga kui sa selle tood, puhkeb ta nutma, nõudes: „Ma ütlesin punane!“ Ära vaeva end siin loogika otsimisega. Tõsta toit lihtsalt punasele taldrikule ja säästa oma närve.'),
('88a16b76-764f-4acc-b335-0aa3f126d25a'::uuid,'Сыртка чыгуу убактысы! ⛅','Кийинүү кыйын сезилиши мүмкүн, бирок 20 мүнөттүк таза аба сиздин да, балаңыздын да психикалык абалына абдан жакшы таасир этет. Аба ырайын жана кийимди текшерип (колдонмонун функциясы), кийинип, эшикти ачыңыз — жөн гана терезени эмес!','Aeg õue minna! ⛅','Riietumine võib tunduda väljakutsena, kuid 20 minutit värsket õhku teeb imesid nii sinu beebile kui ka sinu vaimsele tervisele. Kontrolli ilma ja riietust (äpi funktsioon), pane end riidesse ja ava uks – mitte ainult aken!'),
('bb5697de-df9c-4558-a606-a7acef72c755'::uuid,'Ата, түнкү баатыр 🦸‍♂️','Алтын эреже: кекиртүү жана бешик ыры — бул биргелешкен иш! Бүгүн кечинде бала атасынын кучагында, ал эми сиз кулакчыныңызды тагып, музыкадан ырахат алыңыз.','Issi, öine kangelane 🦸‍♂️','Esimeste kuude kuldreegel: röhitamine ja hällilaulud peaksid olema meeskonnatöö! Täna õhtul on beebi issi süles, samal ajal kui sina paned kõrvaklapid pähe ja naudid muusikat.'),
('541b84ef-a3ed-43ff-8a33-aa153668c840'::uuid,'Бороондуу түн 😭','Кичинекейиңиз түнкүсүн эч себепсиз ыйлап ойгондубу? Газбы же түнкү коркунучпу? Божомолдобоңуз! Ыйды талдоо функциясын колдонуп, себебин аныктаңыз жана жумшак кучактоо менен сооротуңуз.','Tormine öö 😭','Kas su väike laps ärkas keset ööd ilma nähtava põhjuseta nuttes? Kas see on gaasivalu või äkki öine hirm? Ära arva! Kasuta nutu analüüsimise funktsiooni, et tuvastada põhjus ja lohutada teda õrna kallistusega.'),
('60323c41-a0d6-4029-8b71-994315dcb0cf'::uuid,'Горшоктон кырсыктар 🚽','Горшокко үйрөтүү учурунда килемге дагы бир жолу «кырсык» болуп кеттиби? Терең дем алыңыз. Капалануу анын кайра артка кетишине гана алып келет. Тазаласа боло турган нерсе үчүн өзүңүздү стресске салбаңыз; бул жөн гана үйрөнүү процесси.','Potiõnnetused 🚽','Kas potitreeningu ajal juhtus vaibal jälle äpardus? Hinga sügavalt sisse. Ärritumine paneb teda vaid tagasi arenema. Ära stressa oma psühholoogiat millegi pärast, mida saab puhastada; see on lihtsalt õppimisprotsess.'),
('4696c250-45bb-4765-b4bf-ee4e94f6361c'::uuid,'Апанын чай ичүүсү ☕','Бүгүн өзүңүз үчүн эмне кылдыңыз? Эч нерсеби? Бала уктаары менен телефонду четке коюңуз. Бир чыны жылуу кофе (же чай) куюп, 10 мүнөт эч нерсе жөнүндө ойлонбоңуз.','Emme teetass ☕','Mida sa oled täna enda heaks teinud? Mitte midagi? Niipea kui beebi uinakule jääb, pane see telefon käest. Vala endale tass sooja kohvi (või teed) ja ära mõtle 10 minutit mitte millelegi.'),
('7831318d-6b24-4373-9578-2c2a43ef02bf'::uuid,'Чач жулуу өнөрү 💇‍♀️','Балаңыз чачыңызды кармап, катуу тартып жатабы? Анын кармоо рефлекси күчөп жатат! Бул күлкүлүү, кээде ооруткан өнүгүү этабын сөзсүз түрдө эстелик катары видеого тартып алыңыз.','Juustest tirimise kunst 💇‍♀️','Kas su beebi haarab kätega otse su juustest ja tõmbab kõvasti? Tema haaramisrefleks muutub tugevamaks! See naljakas, kuid vahel valus arenguetapp on kindlasti väärt videole jäädvustamist mälestuseks.'),
('1a8259f8-8cae-4f18-b5c2-ee44aa10346d'::uuid,'Сиздин кичинекей талашкер 🗣️','Оюнду узартуу үчүн «Дагы 5 мүнөт!» деп жатабы? Аларда убакыт түшүнүгү жок, бирок сүйлөшүү жөндөмү эң сонун! Оюн аркылуу эрежелерди жумшак эскертип туруу үчүн таймерди колдонуңуз.','Sinu väike väitleja 🗣️','Nad ütlevad „Veel ainult 5 minutit!“, et mänguaega pikendada. Neil pole ajataju, kuid nende läbirääkimisoskused on suurepärased! Sea taimer, et mänguliselt ja ilma stressita reegleid meelde tuletada.'),
('bf1a9cee-65ab-4eac-ad90-70c1631bbc46'::uuid,'Тез өсүү мезгили 📏','Шымдарынын бою кыскарып калдыбы? Тез чоңоюп жатат! Өнүгүү күндөлүгүнө учурдагы өлчөмдөрдү киргизип, уйкусуз түндөрүңүздүн үзүрүнө сыймыктануу менен караңыз.','Kasvuspurt 📏','Püksid on lühikeseks jäänud? Ta kasvab kiiresti! Sisesta arengupäevikusse praegused mõõdud ja vaata uhkusega oma unetute ööde vilju.'),
('d66ea07a-276e-489b-bd8f-3ff80abe7258'::uuid,'Тийүүнүн керемети 🫂','Уктабай, бешикке саларыңыз менен ыйлап жатабы? Кээде эч кандай атайын куралдын кереги жок. Жөн гана аны көкүрөгүңүзгө кысып, териден-териге тийүү экөөңүздөрдү тең кантип тынчтандырарын сезиңиз.','Puudutuse ime 🫂','Ei taha magada, nutab kohe, kui ta voodisse paned? Mõnikord pole erilisi vahendeid vaja. Lihtsalt hoia teda oma rinnal ja tunne, kuidas nahk-naha kontakt teid mõlemaid rahustab.'),
('ed4bee35-1ea6-4f7f-ba0b-bb5c2bd4f981'::uuid,'Суу ичүү адатын калыптандыруу 💧','Кошумча тамак менен кошо суу сунуштоону унутпаңыз. Суу ичүүчү чөйчөктөрдү же бөтөлкөлөрдү «Сунушталган өнүмдөр» бөлүмүнөн оңой табыңыз.','Tervisliku joomisharjumuse kujundamine 💧','Ära unusta tahke toidu kõrvale vett pakkuda. Leia sobivad nokaga tassid või veepudelid hõlpsasti soovitatud toodete hulgast.'),
('0b7b3ea8-6539-4606-ac0b-b0428466ace0'::uuid,'Сиздин кичинекей туурагычыңыз 🦜','Сиздин жөтөлүңүздү жана күлкүңүздү туурап жатабы? Сиз анын эң мыкты күзгүсүсүз! Ага эң сонун эмоцияларды үйрөтүңүз.','Sinu väike järeleahvija 🦜','Kas ta jäljendab sinu köhimist ja itsitamist? Sina oled tema parim peegel! Õpeta talle kõige imelisemaid ilmeid.'),
('cff0599d-3a80-4d02-94df-22f42e5f09f2'::uuid,'Жубайлардын эс алуусу 🥂','Кичинекейиңиз акыры уктады. Эми телефонду жана үй жумуштарын четке коюңуз. Өнөктөшүңүз менен кеминде 20 мүнөт бала же төлөмдөр жөнүндө эмес, таптакыр башка нерселер тууралуу сүйлөшүңүз!','Paaride omaaeg 🥂','Väike laps magab lõpuks. Nüüd pane telefonid ja majapidamistööd kõrvale. Veeda vähemalt 20 minutit partneriga millestki täiesti muust rääkides – millest iganes, aga mitte beebist või arvetest!'),
('a99309cf-e0e5-4d40-9004-a8b08226861a'::uuid,'Шилекей агуу: Жакасы ар 10 мүнөт сайын суу болобу?','Тиш чыгаруу трекериндеги алгачкы эскертүүлөр чындыкка айланып баратат. Балаңыздын төмөнкү бүйлөсүн тез-тез текшерип туруңуз; балким, биринчи ак бермети чыгып келе жаткандыр!','Süljeeritus: kas krae on iga 10 minuti tagant märg?','Need esimesed märgid hammaste tuleku jälgijas muutuvad reaalsuseks. Kontrolli sageli oma lapse alumisi igemeid; võib-olla on tema esimene valge pärl teel!'),
('380bef16-ec45-4aa3-8cc8-5ea1cf489dc2'::uuid,'Апалар үчүн энергия берүүчү каражаттар! 🥗','Активдүү бала менен бирге болуу энергияны талап кылат! Энелер үчүн дени сак рецепттерибизден витаминдүү салат же смузи жасап алыңыз.','Energiaallikad emmedele! 🥗','Aktiivse beebiga sammu pidamine nõuab energiat! Valmista meie tervislike emade retseptide järgi vitamiinidest pakatav salat või smuuti.'),
('a261deac-e213-48df-a6bd-e43793de79c9'::uuid,'Атанын укалоо оазиси 💆‍♀️','Бүгүн кечинде баланы уктоо милдетин өнөктөшүңүзгө тапшырыңыз, анан ал сизге моюн булчуңдарыңызды жазуу үчүн 5 мүнөттүк массаж жасап берсин!','Issi massaažioaas 💆‍♀️','Lase partneril täna õhtul beebi magama panna ja palu tal seejärel teha sulle 5-minutiline õlamassaaž pinges kaelalihastele!'),
('5130988b-06fa-4ca0-8477-7c4e5105998f'::uuid,'Жомок айтуунун сыйкыры 🪄','Бүгүн кечинде Smart Stories коллекциябыздан таптакыр башкача жомокту угуп көрүңүз: «Асманды ачкан кичинекей булуттун жомогу». Үнүңүздүн обонун жомоктун ыргагына ылайыктап, аны акырын уктатыңыз.','Jutuvestmise võlu 🪄','Proovi täna õhtul midagi täiesti erinevat meie nutikate lugude kogust: „Lugu väikesest pilvest, kes avastas taeva“. Kohanda oma hääletooni loo rütmiga ja uinuta ta õrnalt magama.'),
('87dbc3cb-466d-4628-b1df-07cce718a3ab'::uuid,'Өз алдынча тамактанууну жакшы көрөт! 🥦','Ымыркайлар кошумча тамакка өткөндө, алар өз алдынча кармап жей ала турган пайдалуу тамактарды биздин «Рецепттер» бөлүмүнөн оңой эле таап, даярдай аласыз.','Ise söömise rõõm! 🥦','Valmista beebile lihtsasti haaratavaid ja toitainerikkaid näputoite, kui alustate lisatoiduga – leiad need meie retseptide sektsioonist.'),
('9b804616-ae80-4d37-b6a9-76004e3e5506'::uuid,'Жөнөкөй буйруктарды түшүнөт! 🧠','Сиз «Муну мага берчи» дегениңизде, ал оюнчукту колуңузга сунабы? Түшүнүү жөндөмүнүн бул укмуштуудай өсүшүн колдоо үчүн биздин блогдордогу өнүгүү боюнча макалаларды окуп чыгыңыз!','Mõistab lihtsaid käsklusi! 🧠','Kui ütled: „Anna see mulle,“ kas laps ulatab sulle mänguasja? Selle uskumatu mõistmisvõime arengu toetamiseks heida pilk meie blogi arenguartiklitele!'),
('f2c9cd05-6f08-42dc-b88f-310abadaba89'::uuid,'Тынч түндөр 🛀','Жылуу ванна, жайлуу массаж жана караңгылатылган бөлмө. Уйкунун туруктуу тартибин сактоо — түнкүсүн тынч уктоонун эң негизги сыры.','Rahulikud ööd 🛀','Soe vann, õrn massaaž ja hämar tuba. Järjepidev unerežiim on katkematu ööune kõige olulisem saladus.'),
('fad6626b-f1fb-4e8d-8e1a-679ccb7c1f85'::uuid,'Тапкан нерселеринин баарын изилдөө! 🗑️','Ал колуна тийгендин баарын кармалап жатканда капа болбоңуз; ал азыр кичинекей изилдөөчү! Жөн гана көз салып туруңуз.','Avastab kõike, mida leiab! 🗑️','Ära pahanda, kui laps kõike haarab; ta on väike avastaja! Hoia tal lihtsalt silm peal.'),
('b14018ad-b2b5-4374-a785-9d281ebdd7e0'::uuid,'Болгону 15 мүнөттүк тынчтык 🤫','Чарчоодон күнү бою башыңыз ооруп жатабы? Балаңызды уктаткандан кийин, айлана-чөйрөнү көзөмөлдөө үчүн «Үн өлчөгүчтү» иштетип, үйдө тынчтык орнотуңуз жана өзүңүзгө керектүү эс алууну тартуулаңыз.','Vaid 15 minutit vaikust 🤫','Kas kurnatus tekitab terve päeva peavalu? Kui paned beebi magama, lülita sisse helimõõtja, et keskkonda jälgida, kuuluta kodus vaikne tund ja anna oma vaimule hädavajalikku puhkust.'),
('c69510ed-a6e2-4456-a462-211d3917dec3'::uuid,'Башка апалар эмне кылып жатышат? 💬','«Мындай нерсе менин гана баламда болобу?» деп ойлонуп жатасызбы? Сиз жалгыз эмессиз! Anacan коомчулугуна кошулуп, башка энелердин реалдуу окуяларын окуп, жеңилдеп калыңыз.','Mida teised emmed teevad? 💬','Kas mõtled: „Kas ainult minu laps teeb nii?“ Sa pole üksi! Liitu Anacani kogukonnaga, loe sealsete emade tõestisündinud lugusid ja hinga kergendatult.'),
('632fc2f4-f865-49e5-8a30-eef5c63d0d4a'::uuid,'''Мага карачы!'' деп сурануу 👀','Сиз телефон карап жатканда, кичинекейиңиз келип колуңузду түртүп же аппаратты тартып алууга аракет кылабы? Ал туура кылып жатат! Ал сиздин толук көңүл бурууңузду каалайт. Ага көз карашыңызды буруп, бир аз убакыт бөлүп, өзүн угулуп жаткандай сездириңиз.','„Vaata mind!“ palve 👀','Kui oled telefonis, kas su väike laps tuleb ligi, lööb käega või üritab seadet haarata? Tal on täielik õigus! Ta igatseb sinu vahetut ja jagamatut tähelepanu. Veendu, et ta tunneks end kuulduna, vaadates talle silma ja pühendades talle hetke oma tähelepanust.'),
('df191a16-4b37-4a90-bbd4-c8972ecc1670'::uuid,'Башаламандык менен көңүл ачуу, чексиз изилдөө 🎨','Пижамасы тамакка, кийимдери боёкко булганганбы? Балдар таптаза болуп чоңоюшу шарт эмес; алар изилдөө жүргүзүп жатканда булганышы керек. Башаламандык — бул алардын чыгармачылыгынын белгиси, андыктан кабатыр болбоңуз.','Sodimine ja piiritu avastamisrõõm 🎨','Kas tema pidžaama on toiduga koos ja riided värviplekilised? Lapsed ei peaks kasvama täiesti puhastena; nad peaksid avastades määrduma. Segadus on nende loovuse hümn, nii et ära muretse.'),
('51cd27c2-62e8-409d-8a08-48c1ba2f8c3b'::uuid,'Күзгүдөгү дос 👀','Балаңызды күзгүгө алып барыңыз. Ал өзүнүн чагылышын кандай таң калуу жана жылмаюу менен карап жатканын байкаңыз. Ал күзгүдөгү өзү экенин азырынча билбейт, бирок бул оюн анын таанып-билүү жөндөмүн өнүктүрүү үчүн эң сонун.','Sõber peeglis 👀','Vii beebi peegli ette. Vaata, kuidas ta imestuse ja naeratusega oma peegeldust jälgib. Ta ei tea veel, et see on tema ise, kuid see mäng on ideaalne tema kognitiivseks arenguks.'),
('1e555e61-fac2-4756-83d5-5c2a2ceaa400'::uuid,'Сиздин өзгөчө окуяңыз 🪄','«Акылдуу жомоктор» менен кечки уйкуга өтүүнү жеңилдетиңиз. Алар үчүн өзгөчө, таттуу жомок ойлоп табыңыз же окуп бериңиз.','Sinu enda eriline lugu 🪄','Muuda õhtune uinumine lihtsamaks Nutikate lugude abil. Loo ja loe talle üks eriline ja armas unejutt.'),
('096e15b3-74ca-4180-ab20-07ce9b214b2a'::uuid,'Шыбырашып сүйлөшүү 🌙','Бөлмөдөгү жарыктын баарын өчүрүңүз. Жанына жатып, күндүн кандай өткөнү тууралуу акырын шыбырап айтып бериңиз. Шыбырап сүйлөө — баланын мээсин уйкуга даярдоонун эң сонун жолу.','Sosistatud vestlused 🌙','Lülita toas kõik tuled välja. Heida tema kõrvale ja sosista vaikselt päeva sündmustest. Sosistamine on suurepärane viis aidata tema ajul uneks valmistuda.'),
('41df7f7d-e272-4737-8498-6c866ab9545a'::uuid,'Тажрыйба бөлүшүү 💬','Балаңыздын тил албастыгы сизди коркуттубу? Интернеттен коркунучтуу макалаларды издебеңиз. Anacan коомчулугундагы тажрыйбалуу энелердин реалдуу окуяларынан пайдаланып, жылмайып коюңуз.','Kogemuste jagamine 💬','Kas lapse trots hirmutas sind? Ära otsi internetist hirmutavaid artikleid. Ammuta jõudu kogenud emade tõelistest kogemustest Anacani kogukonnas ja naerata.'),
('6f416e63-4acf-4dd2-8216-6601a8c26df5'::uuid,'Күнөөлүү сезимден арылыңыз 🛑','Бүгүн чыдамыңыз түгөндүбү? Балким, бир аз капаланып, азыр өзүңүздү күнөөлүү сезип жатасызбы? Токтоңуз. Сиз роботсузбу? Жок. Сезимдериңизди кабыл алыңыз, өзүңүздү кечириңиз жана эртең жаңы күн менен баштаңыз.','Lase süütundest lahti 🛑','Kas kannatus katkes täna? Võib-olla said veidi pahaseks ja tunned nüüd süüd? Peatu. Kas oled robot? Ei. Aktsepteeri oma tundeid, anna endale andeks ja alusta homme puhtalt lehelt.'),
('3995ea79-4422-4b71-b376-6426966b7d85'::uuid,'Таза аба: Эң мыкты дары 🌳','Күнүңүз ызы-чуу жана ый менен өттүбү? Чечим сиз ойлогондон да жөнөкөй болушу мүмкүн: аба ырайын жана кийимин текшерип, коляскага салып, таза абада сейилдөө үчүн түз эле сейил бакка жөнөңүз.','Värske õhk: parim ravim 🌳','Kas oli jonnakas ja nutune päev? Lahendus võib olla lihtsam, kui arvad: kontrolli ilma ja lapse riietust, pane ta vankrisse ja suundu otse parki värsket õhku hingama.'),
('8ac94a1b-a693-498b-9e54-d59e3331d567'::uuid,'Кесипкөй бийчи 🎶','Ал уккан биринчи ритмине, мейли ал жарнамадагы үн болсун, мейли унаанын сигналы болсун, бийлей баштайт. Жашоого ал сыяктуу шаңдуу караңыз! Бөлмөдө ага кошулуп, бир нече мүнөткө шайыр бийлеп алыңыз.','Professionaalne tantsija 🎶','Ta hakkab tantsima esimese rütmi peale, olgu selleks reklaamiheli või auto signaal. Vaata elule sama rõõmsalt kui tema! Ühine temaga toas ja tehke paar minutit pöörast tantsu.'),
('d584b1c4-e42a-483d-b585-e83a9ab20c88'::uuid,'Апа үчүн энергия 🍲','Балаңызды багам деп өзүңүз ачка калдыңызбы? Дени сак рецепттер бөлүмүнө өтүп, сиңимдүү жана энергия бере турган жеңил тамак даярдап алыңыз. Кичинекейиңизге күч берүү үчүн өзүңүз да күчтүү болушуңуз керек.','Energialaks emmele 🍲','Kas oled beebit toites ise nälga jäänud? Suundu tervislike retseptide sektsiooni ja valmista kergesti seeditav, energiat andev suupiste. Pead olema tugev, et anda oma väikesele jõudu.'),
('014e3f07-72e8-47f8-b62e-ff583a9df29e'::uuid,'Мени менен сүйлөшүңүз! 🗣️','Ал сизге карап, адаттан тыш үндөрдү чыгарып жатабы? Анын былдырлаганына жана тыныгууларына жооп бериңиз. Ал чындыгында сиз менен чыныгы диалог куруп жатат! Бул анын тил өнүктүрүүсүндөгү негизги кадам.','Räägi minuga! 🗣️','Kas ta vaatab sulle otsa ja teeb ebatavalisi häälitsusi? Vasta tema lalinale ja pausidele. Ta peab sinuga tegelikult päris dialoogi! See on keelelise arengu oluline samm.'),
('540ed6cc-ab45-42f3-bbdf-f7d1a37e6094'::uuid,'Атасынын жашыруун тактикасы 👨‍🍼','Күндүзгү чарчооңуз жетиштүү болду. Кечинде балаңызды уктоого даярдоо, тишин жуу сыяктуу иштерди атасына тапшырып, өзүңүз бир аз тынч эс алыңыз.','Issi salajane taktika 👨‍🍼','Oled päevasest väsimusest tüdinud. Õhtul lase isal võtta üle mänguline voodisse sättimine ja hammaste pesu, samal ajal kui sina astud kõrvale ja naudid vaikset puhkust.'),
('75bb1e03-07ff-448a-b132-6eec4abf1a2d'::uuid,'Кир жуу цикли 👗','Сиз кирлерди кылдаттык менен бүктөп жатсаңыз, ал келип баарын чачып салдыбы? Капа болгондун ордуна, муну оюнга айлантыңыз: «Кел, ким бул көйнөктү алысыраак ыргытат экен, көрөлү!»','Pesutsükkel 👗','Sina voldid hoolikalt pesu, aga tema tuleb ja ajab selle hetkega laiali. Selle asemel, et pahandada, muuda see mänguks: „Vaatame, kes suudab seda särki kõige kaugemale visata!“'),
('c290d85d-0e02-4b4e-aaab-db6ae8bfcaef'::uuid,'Жашыруун муктаждыктар 🛒','Күнүмдүк түйшүктө бир нерсе түгөнүп калдыбы? Даарат кагазы, памперс, шампунь? Унутуп калбаш үчүн азыр соода тизмеңизге кошуп коюңуз жана аны өнөктөшүңүздүн телефонуна эскертме катары жөнөтүңүз.','Varjatud vajadused 🛒','Kas igapäevases saginas on midagi otsa saamas? Tualettpaber, mähkmed, šampoon? Lisa see kohe ostunimekirja, enne kui unustad, ja saada teavitus oma partneri telefoni.'),
('ca77a3ff-10f8-4690-8926-270fe161b3d5'::uuid,'Өз алдынча тамактануудагы күрөш 🥄','Кичинекейиңиз кашыкты кармап, айлананын баарын булгап жатабы? Тамактануу таймерин коюңуз! Чачылган тамакка көңүл бурбай, анын өз алдынчалыкка карай жасаган кадамын кубаттаңыз.','Ise söömise lahing 🥄','Kas su väike laps haarab lusikast ja tekitab kõikjal suure segaduse? Pane taimer! Selle asemel, et keskenduda laialipillatud toidule, tähista seda imelist iseseisvust, mida ta omandab.'),
('43d613a7-90fe-4d48-880a-a0dadfb94dab'::uuid,'Операция: Жашыруун жашылчалар 🥦','Ал шорпосундагы жашылчаларды микроскоп менен издегендей терип жатабы? «Дени сак рецепттер» бөлүмүнөн жашылчаларды «көрүнбөс» кыла турган соустардын рецептин табыңыз. Чыгармачылык — эненин эң чоң куралы.','Operatsioon: Peidetud köögiviljad 🥦','Kas ta nopib supist köögivilju välja, nagu uuriks neid mikroskoobiga? Leia tervislike retseptide hulgast kastmeid, mis muudavad köögiviljad „nähtamatuks“. Loovus on ema suurim relv.'),
('6fd78011-ad7d-48f0-9941-25d07912808e'::uuid,'Төмөн кароо: Ал жерде эмнени табууга болот? 👣','Балаңыз жылаңайлак басып, ар кандай беттерди изилдөөнү жакшы көрөбү? Бул сезүү органдарынын стимулдашуусу анын тең салмактуулугун өнүктүрүү үчүн өтө маанилүү. Байпаксыз жүрүүсүнө уруксат бериңиз!','Vaadates alla: mida seal avastada on? 👣','Kas su laps armastab paljajalu käia ja uurida erinevaid tekstuure jalataldade all? See sensoorne sisend stimuleerib jalgade närve, mis on tasakaalu arenguks ülioluline. Lase tal sokkideta nautida!'),
('43fbc1cb-7e93-4983-b59f-f5bc67650d3e'::uuid,'Жомок эч качан бүтпөйт 📖','Бүгүн кечинде «Акылдуу жомокторго» чыгармачыл тапшырма бериңиз: «Энесинин жытын издеген кичинекей аюунун жомогу». Түндү сүйүү жана тынчтык менен аяктаңыз.','Lugu ei lõpe kunagi 📖','Täna õhtul anna Nutikatele lugudele loomingulisem ülesanne: „Lugu väikesest karupojast, kes otsib oma ema lõhna.“ Lõpeta õhtu armastava ja rahuliku järeldusega.'),
('da354848-a7ac-41ba-9616-ccf0b8799a86'::uuid,'Уйкунун белгилери 🥱','Эгер кичинекейиңиз көзүн ушалап, боштукту карап жатса, ыйлагыча күтпөңүз. Дароо бөлмөнү караңгылатып, уйку тартибин баштаңыз.','Unemärgid 🥱','Kui su väike laps hõõrub silmi ja vaatab tühjusesse, ära oota jonnihoogu. Pimenda kohe tuba ja alusta unerežiimiga.'),
('049b837c-5a26-4c32-95e4-e745b4a3443b'::uuid,'Бир нерсени алып койгонуңузда кичинекейиңиз каршылык көрсөтөбү? 🧸','Анын менчик сезими жана инсандыгы калыптанып жатат. Бул психологиялык жактан таптакыр табигый этап.','Kas su väike põngerjas protestib, kui sa temalt midagi ära võtad? 🧸','Tema omanditunne ja individuaalsus arenevad. See on täiesti loomulik psühholoogiline etapp.'),
('dcc98b1b-6e09-41d3-9be6-78333aecdab4'::uuid,'Түнкү сакчылар 🧸','Ал караңгыдан коркобу? Сүйүктүү оюнчуктарын керебетинин тегерегине тизип коюп, «Алар сени таң атканча коргойт» деп айтыңыз. Бул визуалдык ишеним абдан жакшы жардам берет.','Öised valvurid 🧸','Kas ta kardab pimedat? Sea tema lemmikud kaisukarud ja mänguasjad ümber voodi ja ütle talle: „Nemad kaitsevad sind hommikuni.“ See visuaalne kindlustunne teeb imesid.'),
('70597740-ab51-4b20-b743-042bccb768a6'::uuid,'Эртең мененки тыбырчылоо 🐢','Ичи менен жатуу мойнунун булчуңдарын чыңдайт. Ыйласа дагы, муну күн сайын кыска убакыттан жасап туруңуз.','Hommikune siputamine 🐢','Kõhuli olemine tugevdab kaelalihaseid. Isegi kui ta nutab, jätka seda iga päev lühikeste perioodide kaupa.'),
('06a37325-84f4-4012-b4a0-ff317ba78e4c'::uuid,'"Кош-кош" деп кол булгалоо! 👋','Кичинекейиңиз «кош бол» деп кол булгаганды үйрөндүбү? Бул сүйкүмдүү учурду «Ымыркайлардын фотосессиясы» менен дароо тартып алыңыз.','Head aega lehvitamine! 👋','Kas su väike laps on õppinud lehvitama? Jäädvusta see armas verstapost koheselt beebifotoseansi abil.'),
('69b02f6b-1a0a-4f09-860a-f56dfb370b0a'::uuid,'Үйдөгү коопсуздук боюнча кеңештер! 🛡','Балаңыз турууга аракет кыла баштаганда, кооптуу жагдайлар көбөйөт. Эмеректердин бурчтарын коргоочу каражаттарды жана кулпуларды биздин «Сунушталган товарлар» тизмесинен текшерип алыңыз.','Koduohutuse nipid! 🛡','Kui väike laps hakkab püsti tõusma, suurenevad võimalikud ohud. Kontrolli kindlasti meie soovitatud toodete nimekirja, et leida turvalukud ja nurgakaitsmed.'),
('3d8d4230-c58c-4f55-bb5e-c5c92f713201'::uuid,'Тынчтыктан ырахат алуу 🤫','Ызы-чуу күндөн кийин, балаңыз уктаганда, бөлмөдөгү тынчтыкты биздин «Үн өлчөгүч» менен ченеп көрүңүз. Ал сандардын нөлгө жакындаганын көрүү эне үчүн дарыдай эле таасир этет.','Vaikuse nautimine 🤫','Pärast lärmakat päeva, kui väike laps on lõpuks magama jäänud, mõõda toas valitsevat vaikust meie helimõõtjaga. Juba nende numbrite nullilähedaseks langemine võib emale mõjuda teraapiliselt.'),
('249e422f-5203-4598-a063-3032744aab4c'::uuid,'Суу менен "салгылашуу" 💧','Кичинекейиңиз өзү чөйчөк кармагысы келет, бирок көбү кийимине төгүлүп жатабы? Анын өз алдынчалыгын кубаттаңыз — нымдуу салфеткалар дал ушул үчүн керек!','Vee-lahing 💧','Sinu väike laps tahab ise tassist juua, aga suurem osa sellest satub riietele? Elavda tema iseseisvust – selleks ongi niisked salvrätid!'),
('88ed955b-e80f-4226-9234-7112a99a4951'::uuid,'Жан шеригиңиздин эс алуу сааты 🔋','Бүгүн бардык энергияңызды балаңызга арнадыңыз. Кечинде бала менен өнөктөшүңүз болсун, ал эми сиз интернеттен чыгып, өзүңүздү калыбына келтириңиз.','Partneri akude laadimise tund 🔋','Oled täna kogu oma energia lapsele andnud. Lase partneril veeta õhtu beebiga, samal ajal kui sina lülitad end välja ja laed akusid.'),
('d2dfb95a-94ec-43c1-97da-20aed6c6d0bb'::uuid,'Алгачкы өз алдынча көз ирмемдер! 🧗‍♂️','Ал диванды кармап туруп, күтүлбөгөн жерден коё бере баштадыбы? Ал тең салмактуулугун издеп жатат! Бул кыска, бирок толкунданткан көз ирмемдерди баалаңыз.','Need esimesed iseseisvad sekundid! 🧗‍♂️','Kas ta laseb äkki diivanist lahti, et püsti seista? Ta otsib oma tasakaalu! Hinda neid lühikesi, kuid põnevaid hetki.'),
('53046b7a-695e-4d17-9dda-231255060141'::uuid,'Эртең мененки чоң "Жок!" 🛑','Сиз бир нерсе сунуштаганда, ал көзүн ача электе эле «Жок!» деп айтабы? «Үч жашарлык» кризисине жакындаганда, суроо берүүдөн качыңыз. Анын ордуна, оюңузду так айтыңыз. «Колу-бетибизди жууйбузбу?» дебей, «Кол-бетибизди жууй турган убакыт келди!» деп айтыңыз.','Hommikune suur „ei!“ 🛑','Kas ta ütleb automaatselt „Ei!“, kui midagi pakud, isegi enne kui silmad on täielikult avatud? Kui ta läheneb „kolmeaastase“ faasile, väldi küsimuste esitamist. Selle asemel väljenda oma kavatsusi selgelt. „Kas peseme käed ja näo?“ asemel ütle: „On aeg käed ja nägu pesta!“'),
('80ecdccb-340a-49ab-94a9-ff073855c0a0'::uuid,'Эмне тамак жасаш керек? Күнүмдүк түйшүк 🍲','Кошумча тамактар боюнча идеялар түгөнүп жатабы? Интернеттен чексиз издөө менен убара болбоңуз. Anacan AI''дан 10 айлык балаңыз үчүн жеңил тамактардын тизмесин сураңыз.','Mida süüa teha? Igapäevane dilemma 🍲','Kas ideedest lisatoidu menüü jaoks jääb puudu? Ära eksle lõpututes internetiotsingutes. Küsi Anacan AI-lt nimekirja lihtsatest näputoitudest oma 10-kuusele lapsele.'),
('b8e6e605-baf6-44b6-9e44-842e0b7a0af0'::uuid,'Маекке кошулат 🗣️','Сиз телефондо сүйлөшүп жатканда, ал өз тилинде катуу «сүйлөйбү»? Анын баарлашуу жөндөмү тез өсүп жатат — бөлмөдө экинчи сүйлөөчү бар!','Liitub vestlusega 🗣️','Kui oled telefonis, kas ta „räägib“ valjult oma keeles? Tema suhtlemisoskused arenevad kiiresti – sul on toas teine kõneleja!'),
('c9db13f9-8aff-4b71-a7fa-bdce47336917'::uuid,'Күтүүсүз ойгонуп ыйлообу? 😭','Түнкү коркуулар башталышы мүмкүн. Балаңыздын ыйын талдап, көйгөй физикалыкпы же психологиялыкпы экенин аныктоо үчүн «Ыйды талдоо» функциясын колдонуңуз.','Äkiline nutuga ärkamine? 😭','Öised hirmuhood võivad alata. Kasuta nutianalüüsi funktsiooni, et kuulata tema nuttu ja teha kindlaks, kas probleem on füüsiline või psühholoogiline.'),
('7a757f5f-8810-4a3e-a344-a9b3d9a89548'::uuid,'Чырбы же чарчадыбы? 😭','Балаңыз эч себепсиз ыйлаганда кабатыр болбоңуз. Көйгөйдү тез түшүнүү жана чечүү үчүн биздин «Ыйды талдоо» куралыбыздан колдоо алыңыз.','Kas ta on pirtsakas või väsinud? 😭','Ära tunne end ülekoormatuna, kui beebi nutab ilma ilmse põhjuseta. Hangi tuge meie nutianalüüsi tööriistast, et probleem kiiresti mõista ja lahendada.'),
('b8cf3d8c-2c7c-497e-8657-18fd989a1928'::uuid,'Сыртка чыгуу убактысы! 🌳','Балаңыз менен кайда барарыңызды билбей жатасызбы? Сейил бакта басуу чарчатып жатабы? Балаңыз менен ыңгайлуу отуруп, кофе иче турган «Энелерге ыңгайлуу жайларды» табыңыз.','Uksest välja saamine! 🌳','Ei tea, kuhu beebiga minna? Kas pargis jalutamine väsitab? Avasta „emadesõbralik koht“, kus saad beebiga mugavalt istuda ja kohvi nautida.'),
('e5f27372-8ce2-40d6-acbc-12281fab28bb'::uuid,'Өзүңүзгө убакыт бөлүңүз 🥑','Дайыма шашылуу сизди чарчатты. Бут үстүндө тез тамактануунун ордуна, «Дени сак рецепттерден» витаминге бай өзгөчө тамак даярдап, жай отуруп жеңиз. Сизге ал энергия сөзсүз керек.','Leia aega ISEENDA jaoks 🥑','Pidev kiirustamine on sind kurnanud. Selle asemel, et püstijalu midagi kiirelt süüa, valmista tervislike retseptide järgi toitev ja vitamiinirikas eriroog ning naudi seda. Sa vajad seda energiat hädasti.'),
('25c4de30-89c3-4f45-952f-3b21fb85b41e'::uuid,'Жылаңайлак изилдөөчү 👣','Балдарыңыз байпак кийүүдөн баш тартып, качып жатабы? Аларга бир аз убакытка жылаңайлак жүрүп, полду, килемди же салкын ташты сезүүгө мүмкүнчүлүк бериңиз. Буттун учундагы нерв учтарынын дүүлүгүүсү алардын тең салмактуулукту өнүктүрүүсү үчүн өтө баалуу.','Paljajalu avastaja 👣','Kas ta keeldub sokke kandmast ja jookseb eest ära, kui proovid neid jalga panna? Lase tal veidi paljajalu põrandat, vaipa või jahedat plaati avastada. Jalataldade närvilõpmete stimuleerimine on tema tasakaalu arenguks uskumatult väärtuslik.'),
('a0e0a012-48a8-4169-b4f6-62857311b266'::uuid,'Уктоо үчүн жарыкты өчүрүү 🌙','Тез уктап кетишине жардам берүү үчүн бөлмөдөгү бардык ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Уйку гормону болгон мелатонин караңгы жана технологиясыз чөйрөдө гана бөлүнүп чыгат.','Tuled kustu, aeg magada 🌙','Et aidata tal kiiremini uinuda, lülita toas välja kõik lisatuled ja tahvelarvutite ekraanid. Unehormoon melatoniin eritub ainult pimedas ja tehnoloogiavas keskkonnas.'),
('7c63492d-1515-406a-bd31-b41ece7e0412'::uuid,'Өзүңүздү мактап коюңуз! 👏','Артка кылчайып карасаңыз, алгачкы күндөрдүн канчалык оор болгонун жана ошондон бери канчалык көп нерсени үйрөнгөнүңүздү түшүнөсүз. Өзүңүз менен сыймыктаныңыз. Балаңыз 100 күн гана чоңойгон жок, сиз дагы 100 күн чоңойдуңуз.','Kiida ennast! 👏','Tagasi vaadates mõistad, kui hirmutavad need esimesed päevad olid ja kui palju oled sellest ajast alates õppinud. Ole enda üle uhke. Sinu laps pole kasvanud mitte ainult 100 päeva; ka sina oled kasvanud 100 päeva.'),
('ac0003df-1b37-4e86-98c2-561682149d03'::uuid,'Жаратылыштан табылга издөө 🍁','Аба ырайына ылайыктуу кийимдерди кийип, сыртка чыгыңыз. Паркта ар кандай таштарды жана түстүү жалбырактарды табуу оюнун ойноңуз. Жаратылыш бул курактагы балдар үчүн эң чоң жана эң кызыктуу оюнчук.','Looduse avastusretk 🍁','Pane talle selga ilmale vastavad riided ja minge õue. Mängige pargis erinevate kivide ja värviliste lehtede otsimise mängu. Loodus on selles vanuses tema jaoks suurim ja interaktiivseim mänguasi.'),
('85540a77-8c0c-40d1-bec5-6ddc93f07354'::uuid,'Дүкөндөгү баш аламандык 🛒','Эс тутумуңузга ишенип, дүкөнгө барып, эң керектүү нерсени унутуп калдыңызбы? Бардык керектүү нерселерди дароо Соода тизмесине жазып алууну адат кылыңыз; колдонмо сиз үчүн эстеп калсын.','Toidupoe ajupesu 🛒','Kas usaldasid oma mälu, läksid poodi ja tulid tagasi, olles kõige olulisema asja unustanud? Tee endale harjumuseks kõik vajadused kohe ostunimekirja kirja panna; lase rakendusel sinu eest meeles pidada.'),
('bd0902bb-9be1-40b5-8e41-73f85b835f0e'::uuid,'Эртең мененки жардамчы 🧑‍🍳','Эртең мененки тамакты даярдоого «жардам берүүнү» талап кылып жатышабы? Ооба, ун төгүлүшү, суу чачырашы жана ашкана башаламан болушу мүмкүн... Бирок булар алардын өсүшүнө жардам берген майда моториканы өнүктүрүүчү маанилүү эксперименттер. Сабырдуу болуңуз!','Hommikune abiline 🧑‍🍳','Kas ta nõuab, et saaks hommikusöögi valmistamisel "aidata"? Jah, jahu võib maha minna, vesi pritsida ja köök võib sassi minna... Kuid need on elutähtsad peenmotoorika katsetused, mis aitavad tal kasvada. Kannatlikkus on võti!'),
('dd50206e-acee-43ac-8f19-c5dd29cf7e62'::uuid,'Тери аркылуу байланыш 🫂','Балаңыз абдан тынчсызданып жатабы? Эгер башка эч нерсе жардам бербесе, аны көкүрөгүңүзгө жаткырыңыз. Сиздин жүрөгүңүздүн согушу — эң мыкты тынчтандыруучу үн.','Nahk-naha kontakt 🫂','Kas su beebi on väga rahutu? Kui miski muu ei aita, aseta ta oma rinnale. Sinu südamelöögid on parim rahustav heli.'),
('cc7b8905-a439-46c1-8d92-ea81667052be'::uuid,'Атасынын жылуу кучагы 🫂','Түнкүсүн ойгонгондо жубайыңыз менен кезектешип туруңуз. Жоопкерчиликти толугу менен тең бөлүшүп, команда катары иштеңиз.','Issi lohutavad kallistused 🫂','Öiste ärkamiste ajal tehke partneriga kordamööda. Jagage vastutus täpselt pooleks ja töötage meeskonnana.'),
('c929f83e-5e59-4728-8c79-df0502607758'::uuid,'Атасынын сыйкырдуу шоусу 🤡','Адаттагы ыкмаларыңыз иштебей калганда, атасынын кызыктай үндөрү жана күлкүлүү жоруктары кырдаалды дароо сактап калышы мүмкүн. Кечки ыйлоолор учурунда милдетти ага өткөрүп бериңиз жана четте туруп, балаңыздын шаңдуу күлкүсүнөн ырахат алыңыз.','Issi mustkunstietendus 🤡','Kui sinu tavalised nipid enam ei toimi, võivad issi tobedad hääled ja naljakad helid päeva hetkega päästa. Nende õhtuste jonnihoogude ajal anna teatepulk talle üle ja naudi kõrvalt rõõmsaid itsitusi.'),
('2c73f922-1b22-4eb6-922b-215d8e623242'::uuid,'Чачты чоюу оюну 💇‍♀️','Чачыңызды кармап, катуу тартып жатышабы? Алардын кармоо рефлекси өнүгүп жатат. Бул бир аз ооруткан, бирок абдан сүйкүмдүү өнүгүү учуруна күлүп караганга аракет кылыңыз.','Juustest tirimise mäng 💇‍♀️','Kas ta mässib oma sõrmed sinu juustesse ja tõmbab kõvasti? Tema haaramisrefleks areneb. Proovi selle veidi valusa, kuid imearmsa arenguhetke peale naerda.'),
('924ff591-18ec-4c20-80af-4008cda2fc41'::uuid,'Жаңы үндөрдү изилдөө 🗣️','Алардын былдырлаган үндөрү катуураак жана ар түрдүү угула баштады. Кунт коюп угуңуз жана алардын үндөрүн туурап, күлдүрүңүз!','Uute helide avastamine 🗣️','Tema lalin on muutunud valjemaks ja mitmekesisemaks. Kuula ja aja ta naerma, imiteerides tema häälitsusi!'),
('61f1a424-1da9-48ab-b336-92c9137ef39e'::uuid,'Жылуу ваннада эс алуу 🛀','Экөөңүздөр тең күн бою чуркап чарчадыңыздар. Балаңыз жылуу ваннада жатып жатканда, фондо жаратылыштын тынчтандыруучу үндөрүн коюңуз. Суунун жагымдуу ыргагы эң активдүү баланы да уйкуга даярдайт.','Soe ja lõõgastav vann 🛀','Olete mõlemad terve päeva ringi jooksmisest kurnatud. Samal ajal kui ta naudib sooja vanni, mängi taustaks rahustavaid loodushelisid. Vee rahustav harmoonia valmistab ka kõige aktiivsema lapse uneks ette.'),
('8ae2c146-2d4a-4919-80fe-7f15c41cdc0e'::uuid,'"Өзүм куям!" деген баскыч 💧','Балаңыз стаканга сууну өзү куюуну талап кылып жатабы? Нымдуу салфеткаларды даярдап коюңуз! Алардын өз алдынча болууга болгон умтулуусун токтотпоңуз. Төгүлүп-чачылышы мүмкүн, бирок бир нече аракеттен кийин, алардын стаканды канчалык этияттык менен толтуруп жатканына таң каласыз.','„Ma tahan ise valada!“ etapp 💧','Sinu laps nõuab, et saaks ise vett klaasi valada? Hoia salvrätikud käepärast! Ära lämmata tema tärkavat iseseisvust. Vett läheb kindlasti maha, kuid pärast paari proovimist oled üllatunud, kui hoolikalt ta suudab selle tassi täita.'),
('f32eaadc-b85c-4f36-b182-6f6665e1eaae'::uuid,'Абсолюттук тынчтык 🤫','Уйкуга кетүү кыйын болуп жатабы? Бөлмөнү толугу менен караңгылатып, бардык ызы-чууну басыңыз. Караңгылык жана тынчтык — алардын эң жакшы уйку шериктери.','Absoluutne vaikus 🤫','Kas uinumisega on raskusi? Tee tuba täiesti pimedaks ja vaigista kõik helid. Pimedus ja vaikus on tema parimad unekaaslased.'),
('f4e3cb01-431f-4e52-a62b-ab96cbc1de4b'::uuid,'Алгачкы тиштер чыга баштадыбы? 🦷','Шилекейи көп агып жатабы? Тиш чыгуу трекерине белгилеп коюңуз жана таза тиш салгычтарды жаныңызда кармаңыз.','Esimesed hambad tulemas? 🦷','Kas ta ilastab palju? Tee märge hammaste lõikumise jälgijasse ja hoia puhtad närimisrõngad käepärast.'),
('c8458955-5810-4609-a23d-82b155bf6112'::uuid,'Чарчоо менен күрөшүү 🔋','Өзүңүздү жетишсиз сезип жатасызбы? Баарын башкара албай жатам деп ойлойсузбу? Коомчулуктагы билдирүүлөрдү караңыз; сиз жалгыз эмессиз жана жетишсиз эмессиз. Сиз бул баланын бүтүндөй дүйнөсүсүз.','Võitlus läbipõlemisega 🔋','Tunned end ebakindlalt? Kas arvad, et ei saa kõigega hakkama? Vaata postitusi kogukonnas; sa ei ole üksi ega ebakindel. Sa oled selle lapse maailm.'),
('87267db7-ab44-41b2-82ed-1d12fea90f71'::uuid,'Наристенин тили жана кызыктуу сөздөрү 🗣️','Балаңыз «мен ачкадым» же «ал барды-келди» сыяктуу өзүнүн уникалдуу грамматикасын ойлоп таап жатабы? Аларды катуу оңдобоңуз. Жөн гана туура сүйлөм түзүлүшүн акырын кайталап жооп бериңиз.','Väikelapse jutt ja omapärane grammatika 🗣️','Kas su laps leiutab oma ainulaadset grammatikat, näiteks "ma näljasin" või "ta läks-tuli"? Ära paranda teda karmilt. Vasta lihtsalt, korrates õrnalt õiget lauseehitust.'),
('724659ec-f59f-4bfe-b20d-efdd3d977217'::uuid,'Өзүмө арналган убакыт 🛋️','Алар өз алдынча ойноп жатканда, дароо үй жумуштарына чуркабаңыз. Отуруп, аларды 5 мүнөт алыстан карап, кофеңизден ырахат алыңыз.','Minu aeg 🛋️','Kui ta mängib iseseisvalt, ära torma kohe majapidamistöid tegema. Istu maha, jälgi teda eemalt vaid 5 minutit ja naudi oma kohvi.'),
('19b97cb2-c4a1-4649-a316-a7b34bb3eed4'::uuid,'Балаңыздын жетишкендиктерине көз салыңыз! 📈','Алгачкы толкундануу ишенимге айланды. Сиз бул жолду ушунчалык күч жана назиктик менен басып өттүңүз — сиз укмуштуудайсыз!','Vaata, kui kaugele su laps on jõudnud! 📈','Algne elevus on kasvanud enesekindluseks. Oled sellel teekonnal liikunud sellise jõu ja graatsiaga – sa oled imeline!'),
('9a6f7d87-06ae-42b3-a4d0-b7eff2923976'::uuid,'Anacan AI кеңештери 🤖','Балаңыздын паркта башка балдар менен баарлашуусу боюнча суроолоруңуз барбы? Интернеттен сааттап издеп убара болбоңуз; Anacan AI''дан сураңыз жана дароо өнүгүүсүнө ылайыктуу, педиатр тарабынан жактырылган кеңештерди алыңыз.','Anacan AI nõuanded 🤖','Kas sul on küsimusi oma lapse suhtlemise kohta teiste lastega pargis? Ära eksi tundideks internetti; küsi Anacan AI-lt ja saa kohest, arengule vastavat ja lastearstide poolt heaks kiidetud nõu.'),
('a3b7ecf2-9668-46df-b331-9c7487819a32'::uuid,'Түнкү коркунучтар 😭','Эгерде алар күтүлбөгөн жерден көздөрүн жумуп ыйлап же кыйкырып башташса, «Ыйды талдоо» функциясын колдонуңуз. Эгер бул түнкү коркунуч болсо, аларды ойготууга аракет кылбастан, жанында болуп, унчукпай сооротуңуз.','Öise hirmu hoiatus 😭','Kui ta hakkab äkki kinniste silmadega nutma või karjuma, kasuta nutuanalüüsi funktsiooni. Kui tegemist on öise hirmuga, jää lihtsalt tema kõrvale ja paku vaikselt turvatunnet, püüdmata teda äratada.'),
('a19b5a5e-db95-4571-b0b8-5f50fabb0b6a'::uuid,'Үчүнчү айга кош келиңиз! 🎉','Сиздин наристеңиз азыр айлана-чөйрөнү кыйла сергек байкап жатат.','Tere tulemast kolmandasse kuusse! 🎉','Sinu beebi jälgib nüüd oma ümbrust palju teadlikumalt.'),
('b69e774e-9d7b-4da5-9fb4-5b192b81f712'::uuid,'Ойдон чыгарылган окуялар 🧸','Балаңыз оюнчук аюусуна жомок айтып жатабы же бош чөйчөктөн «чай ичип» жатабы? Символикалык оюн – анын өнүгүүсүндөгү эң сонун этап. Аны токтотпоңуз, жөн гана бул кичинекей режиссерду четтен байкап туруңуз.','Kujuteldavad olukorrad 🧸','Kas su laps räägib oma mängukarule lugusid või "joob teed" tühjast tassist? Sümbolmäng on tema arengus suurepärane verstapost. Ära sega; lihtsalt jälgi seda väikest lavastajat kõrvalt.'),
('aaed3963-e8dd-47d4-93bd-9b307c2b65fd'::uuid,'Эртең мененки энергия ⚡','Көзүн ачары менен эле былдырап жатабы? Ал сиз менен сүйлөшкүсү келет! Жылмайып жооп бериңиз; бул анын тил өнүгүүсү үчүн өтө маанилүү.','Hommikune energia ⚡','Kas ta koogab kohe, kui silmad avab? Ta tahab sinuga rääkida! Naerata ja vasta; see on tema keelearengu jaoks ülioluline.'),
('bfab4a59-c162-47a2-9035-51b03b7fe911'::uuid,'Үй иштери күтө турат 🛑','Башаламан бөлмөнү көрүп стресс болбоңуз. Сиз адам тарбиялап жатасыз, идеалдуу үй кожойкеси болуу милдеттүү эмессиз.','Kodutööd võivad oodata 🛑','Ära satu segamini tuba vaadates stressi. Sa kasvatad inimest; sa ei pea olema täiuslik perenaine.'),
('63090d6e-b5fb-4db8-bce4-2e5749468a34'::uuid,'Китепке болгон сүйүүнү ойготуу 📖','Кечки тартибиңизге кагаз китептерди кошуңуз. Кичинекейиңиз барактарды өзү оодарууга аракет кылып жатат! Үнүңүздүн обонун жомоктун ыргагына жараша өзгөртүп туруңуз.','Raamatute vastu huvi tekitamine 📖','Kaasa oma õhtusesse rutiini päris raamatud. Sinu pisike proovib juba ise lehti keerata! Kohanda oma hääletooni loo tempoga.'),
('c131d97d-34fe-4f0d-ab19-20860829451c'::uuid,'Тынчтыкка болгон муктаждык 🤫','Уктап кеткенден кийинки алгачкы жарым саат – эң сезимтал учур. Үн өлчөгүчтү колдонуп, айланадагы ызы-чуунун деңгээлин текшериңиз жана коңшу бөлмөдөгү телевизордун үнүн ошого жараша жөндөңүз.','Vaikuse vajadus 🤫','Esimene pooltund pärast uinumist on kõige tundlikum aeg. Kasuta helimõõtjat, et kontrollida ümbritsevat detsibellide taset ja reguleeri kõrvaltoas teleri helitugevust vastavalt sellele.'),
('ca9affc4-d638-41a2-8dc7-75447d9ea222'::uuid,'Атасынын кезеги 👨‍🍼','Бүгүн кечинде баланы сооротуу жана бешик ырын ырдоо – атасынын милдети. Ал эми сиз, эс алып алыңыз.','Issi kord 👨‍🍼','Täna õhtul on krooksutamine ja unelaulude laulmine issi töö. Sina aga mine ja puhka veidi.'),
('a4146327-bb44-44e0-9860-d8e3c1abe5c4'::uuid,'Биз бир командабыз! 💪','Тамагын же кашыгын атайылап ыргытып жиберип, анан сизди карап турабы? Ал чек араны жана тартылуу күчүн сынап жатат! Сабырдуу болууга аракет кылыңыз.','Oleme meeskond! 💪','Tunned end üksiku ja väsinuna? Hinga sügavalt sisse. Sa oled tugevaim kangelane, kes nendel tormistel päevadel kurssi hoiab.'),
('e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b'::uuid,'Паркта баарлашуу 🌳','Балаңыз башка балдар менен чогуу эмес, жанында өзүнчө ойноп жатабы? Параллелдүү оюн бул курак үчүн табигый көрүнүш. Аба ырайын жана эмне кийгизүүнү текшерип, сейил бакка алып барыңыз.','Sotsialiseerumine pargis 🌳','Kas su laps mängib pigem teiste laste kõrval kui otse nendega? Paralleelmäng on selles vanuses täiesti loomulik. Vaata ilma ja mida selga panna, ning vii ta siis parki.'),
('88b776b7-0d43-49f1-b31c-da27294feb6f'::uuid,'Педиатрдын ыкчам кеңештери 🤖','Горшокко үйрөтүүдө артка кетүү байкалдыбы? Өзүңүздү кыйнабаңыз; бул психологиялык процессти жөнгө салуу үчүн Anacan AI''дан кеңеш сураңыз.','Kiired pediaatrilised teadmised 🤖','Kas potitreeningus on tekkinud tagasilöök? Ära stressa; küsi Anacan AI-lt lahendusi selle psühholoogilise protsessiga toimetulekuks.'),
('64ab60a5-a744-4f7e-a8a1-28b04eede9d6'::uuid,'Ой, тамак мунарасы кулап калды! 🥣','Алар атайылап кашыгын же тамагын отургучунан ыргытып, анан сизге тике карап жатышабы? Алар чек араны жана тартылуу күчүн сынап жатышат! Сабырдуу болууга аракет кылыңыз.','Ups, toidutorn kukkus ümber! 🥣','Kas ta viskab meelega oma lusika või toidu söögitoolist maha ja vaatab siis otse sulle otsa? Ta testib piire ja gravitatsiooni! Proovi säilitada kannatlikkust.'),
('cd288f90-d6da-4851-9b9a-2a8e15ba81fb'::uuid,'Сиздин өзгөрүп жаткан денеңиз 👗','Күзгүдөн өзүңүздү караганда төрөттөн кийинки дене түзүлүшүңүзгө капа болуп жатасызбы? Эсиңизде болсун, ал дене адам жаратты! Маанай күндөлүгүңүзгө өзүңүзгө ыраазычылык кат жазыңыз.','Sinu muutuv keha 👗','Tunned end peeglisse vaadates oma sünnitusjärgse keha pärast halvasti? Pea meeles, et see keha lõi inimese! Kirjuta oma tujupäevikusse endale tänusõnum.'),
('0e1a794c-f019-4037-b108-0a10db7b5f9f'::uuid,'Үнсүз баатыр 🤫','Ал уктап кеткенде, үйдөгү ар бир үн бомба жарылгандай сезилет. Үн өлчөгүч менен бөлмөнүн ызы-чуусун көзөмөлдөп жатканда, өзүңүздүн баскан кадамыңызды да акырындатууга аракет кылыңыз.','Vaikne kangelane 🤫','Hetkel, mil ta uinub, võib iga heli majas tunduda nagu plahvatav pomm. Samal ajal kui sa helimõõtjaga toa mürataseme piiri sead, proovi ka oma samme kergemaks muuta.'),
('cb2d76e0-4e92-41f1-9153-3b4a29404a17'::uuid,'Шкафтардын кичинекей изилдөөчүсү! 🕵️‍♀️','Ашканадагы бардык казан-аяктар жердеби? Изилдөөсүнө жол бериңиз! Зыянсыз буюмдар менен ойноо анын логикалык ой жүгүртүүсүн өнүктүрөт. Болгону курч нерселерди алып коюуну унутпаңыз.','Väike kapidetektiiv! 🕵️‍♀️','Kas kõik köögi potid ja pannid on põrandal? Lase tal avastada! Ohutute esemetega mängimine aitab arendada tema loogilist mõtlemist. Veendu lihtsalt, et paned kõik teravad esemed ära.'),
('e3c0355b-40c6-476a-8c2d-f69c78debdb1'::uuid,'Оодарылуудагы ийгилик! 🤸‍♂️','Наристеңиз чалкасынан ичине оодарылууга аракет кылып жатабы? Ал абдан аракет кылып жатат! Бул аракеттерин карап туруңуз, бирок керебет сыяктуу бийик жерде эч качан жалгыз калтырбаңыз.','Vinge küljelt küljele pööramine! 🤸‍♂️','Kas su beebi proovib seljalt kõhule keerata? Ta näeb nii palju vaeva! Jälgi neid katseid, kuid pea meeles, et sa ei tohi teda kunagi üksi kõrgemale pinnale, näiteks voodile, jätta.'),
('d194240e-ae66-4f32-83ef-39ade449ccb6'::uuid,'Энелердин ишеним чөйрөсү 💬','«Эмнеге балам али сойлобой жатат?» деген суроолор оюңуздан кетпей жатабы? Anacan Коомчулугуна жазыңыз – ар бир бала өзүнүн өзгөчө темпи менен өнүгөрүн бат эле түшүнөсүз.','Emmede usaldusring 💬','Kas küsimused nagu "Miks mu beebi veel ei rooma?" kummitavad su peas? Tee postitus Anacani kogukonnas – näed peagi, et iga laps areneb omas täiuslikus tempos.'),
('12c2a250-54bd-4e0d-a366-20c820596148'::uuid,'Педиатрдын тез кеңеши 🤖','Балаңыздын терисинде майда бүдүрлөрдү байкадыңызбы? Дарыгерге барардан мурун, тамак-аш аллергиясынын белгилери тууралуу Anacan AI''дан тез маалымат алыңыз.','Kiire nõuanne lastearstilt 🤖','Märkasid oma beebi nahal väikest löövet? Enne arsti juurde minekut küsi Anacan AI-lt kiiret teavet toiduallergia sümptomite kohta.'),
('181a440f-5684-4f29-a861-16adef184628'::uuid,'Убакыт учкан куштай!','Артка кылчайып, канчалык көп нерсени үйрөнгөнүңүздү караңыз! Кичинекейиңиз дээрлик бардык маселе боюнча сиз менен сүйлөшө алган кичинекей «дипломатка» айланды. Аны менен жана өзүңүз менен сыймыктаныңыз!','Aeg lendab!','Vaata tagasi ja näe, kui palju oled õppinud! Sinu pisikesest on saanud väike läbirääkija, kes suudab sinuga peaaegu igal teemal kaubelda. Ole tema ja enda üle uhke!'),
('532d58e2-50f3-422a-818a-36c88094bb87'::uuid,'Балага эмне кийгизүү керек? ⛅','Сыртка чыгарда эмне кийгизсем деп көп ойлонбоңуз. Аба ырайын жана кийим тандоо куралын колдонуп, идеалдуу айкалышты секунданын ичинде табыңыз.','Mida beebile selga panna? ⛅','Ära mõtle üle, mida talle õue minnes selga panna. Vaata ilma ja riietuse tööriista, et leida ideaalne kombinatsioon sekunditega.'),
('f37039a0-f7af-487a-827e-622e2d9e4d05'::uuid,'Чарчап-чаалыгуу — бул кадимки көрүнүш 🔋','Сабырыңыз түгөнгөндө өзүңүздү жаман эне сезбеңиз. Бул чарчоо – табигый нерсе. Жолдошуңуздан колдоо сурагандан тартынбаңыз.','On normaalne tunda end kurnatuna 🔋','Ära tunne end halva emana, kui su kannatus katkeb. See kurnatus on loomulik. Ära kõhkle oma partnerilt tuge paluda.'),
('31d8e844-a068-4aa5-8b2c-23a9d11616c4'::uuid,'Жомок каарманы 🪄','Классикалык китептерден тажадыңызбы? Smart Stories менен аларды жылдыздарга учкан космонавт кыла аласыз же терең деңиздерди изилдете аласыз. Уктаар алдында алардын фантазиясынын эркин учушуна жол бериңиз.','Muinasjutukangelane 🪄','Oled tüdinenud samadest vanadest klassikalistest raamatutest? Nutikate lugudega saad teha temast tähtede poole lendava astronaudi või avastada süvameresid. Lase tema kujutlusvõimel enne magamaminekut vabalt lennata.'),
('4280853d-50c1-4092-8d31-3279f5e3d68a'::uuid,'Сиз үчүн маанилүү тынчтык мүнөттөрү ☕','Эгерде балаңыз күндүзгү уйкудан таптакыр баш тартса, аны мажбурлабаңыз. Анын ордуна 30 мүнөттүк «тынч убакыт» бөлүңүз. Ал төшөктө китептер менен жалгыз калсын, ал эми сиз бөлмөдө бир аз эс алып алыңыз.','Sinu hädavajalik vaikusehetk ☕','Kui laps keeldub uinakust täielikult, ära sunni teda. Selle asemel määra 30-minutiline "vaikne aeg". Lase tal üksi voodis raamatuid vaadata, kuni sina samas toas hetkeks puhkad.'),
('f94cdd25-2b6b-47df-81dc-6e3cab221652'::uuid,'Сиз эң мыктысыз! 🌸','Бүгүн баары тескери болуп жаткандай сезилип жатабы? Баары жайында. Сиздин наристеңизге сизден башка эч кимдин кереги жок. Сиз ал үчүн эң керектүү адамсыз.','Sa oled piisav! 🌸','Kas täna on üks neist päevadest, kus kõik tundub pea peale pööratud? See on okei. Sinu beebi ei vaja kedagi teist peale sinu. Sa oled talle enam kui küll.'),
('7b4d66d9-a24a-47b0-a1dd-7047f05e45ec'::uuid,'Өз атына жооп берүү! 🗣️','Сиз анын атын атаганда, ал карап гана койбостон, жасап жаткан ишин токтотуп, сизге карай умтулат.','Oma nimele reageerimine! 🗣️','Kui sa teda nimepidi hüüad, ei vaata ta mitte ainult sinu poole, vaid püüab ka oma tegevuse pooleli jätta ja sinu juurde tulla.'),
('10fd3d36-ea93-4f52-8bc2-486b88206869'::uuid,'Маанай күндөлүгү 📝','Телефонуңузду колго алыңыз! Социалдык тармактарды карап отурбай, «Маанай күндөлүгүн» ачып, бүгүн балаңыз жасаган эң күлкүлүү же жүрөк жылытарлык учурду жазып коюңуз – бул келечек үчүн сонун эскерүү болот.','Meeleolupäevik 📝','Võta telefon kätte! Sotsiaalmeedia sirvimise asemel ava meeleolupäevik ja pane kirja tänane kõige naljakam või südantsoojendavam hetk – mälestuseks tulevikuks.'),
('07f48fa2-56fd-416e-adda-88c824f2bd6f'::uuid,'Терең уйкуга даярдык 🛀','Жылуу ванна, жумшак укалоо жана жарым жарык бөлмө... Уйкунун туруктуу тартибин сактоо – тынч түндөрдүн сыры.','Valmistumine sügavaks uneks 🛀','Soe vann, õrn massaaž ja hämardatud tuba... Järjepidev unerutiin on katkematu ööune saladus.'),
('c7423d2f-6f9f-452c-9de2-5dea29b29f93'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктаардан бир саат мурун үйдөгү бардык жаркыраган жарыктарды жана экрандарды өчүрүңүз. Мелатонин гормону тынч жана жарым жарык чөйрөдө гана бөлүнүп чыгат.','Hämarda tuled 🌙','Tund enne magamaminekut lülita majas välja kõik eredad tuled ja ekraanid. Melatoniin eraldub vaid rahulikus ja hämara valgusega keskkonnas.'),
('100bd53c-84e3-4c7e-8a31-2a287a02c440'::uuid,'Ойлоруңузду иретке келтириңиз 📝','Бүгүн наристеңиз менен жетиштүү деңгээлде ойнобой калдым деп кабатырланып жатасызбы? Сапаттуу өткөрүлгөн 10 мүнөт чарчаңкы өткөн бир сааттан алда канча баалуу.','Vala oma mõtted paberile 📝','Muretsed, et sa ei mänginud täna oma pisikesega piisavalt? 10 minutit kvaliteetaega on väärt rohkem kui väsinult veedetud tund.'),
('502d3376-0322-4c07-aee1-71c209315c6b'::uuid,'Операция: Жашыруун жашылчалар 🥦','Ал шорпосундагы жашылчаларды терип, жебей жатабы? Бул үчүн урушпаңыз. Жашылчаларды пюре кылып, соустарга кошуп, аларды байкатпай берүүнүн эң өзгөчө жана акылдуу жолдорун биздин тамактануу планыбыздан табыңыз.','Operatsioon: Peidetud köögiviljad 🥦','Kas laps nopib supist köögivilju välja ja jätab need alles? Ära võitle sellega. Leia oma toitumiskavast nutikaid viise, kuidas köögivilju püreestada ja kastmetesse peita.'),
('828415f3-317f-4e76-8caf-753026dcf9f1'::uuid,'Энелик күнөөлүү сезимден арылыңыз 💖','Наристеңиз менен жетиштүү убакыт өткөрбөй жаткандай сезилип жатабы? Сапаттуу, кубанычка толгон он мүнөттүк баарлашуу стресске толгон бир сааттан алда канча баалуу.','Lase lahti emade süütundest 💖','Tunned, et sa ei veeda oma pisikesega piisavalt aega? Kümme minutit kvaliteetset ja rõõmsat suhtlust on palju väärtuslikum kui stressirohke tund.'),
('15b0ec22-2156-4080-ad64-7a588de85fc5'::uuid,'Башаламандыкка кабатыр болбоңуз 🌪️','Сиздин башкы максатыңыз – идеалдуу үй эмес, дени сак жана бактылуу бала чоңойтуу. Эс алыңыз жана бул сапардан ырахат алыңыз.','Ära muretse segaduse pärast 🌪️','Sinu prioriteet ei ole täiuslik kodu, vaid terve ja õnneliku beebi kasvatamine. Lõõgastu ja naudi seda teekonda.'),
('ad687f75-6bde-4ad1-8992-78906bd61fd5'::uuid,'"Апа, мага карачы!" деген өжөрлүк 👀','Сиз телефон менен алек болуп же иштеп жатканыңызда, балаңыз келип колуңузду түртүп жатабы? Ал толугу менен туура кылып жатат; ал сиздин толук көңүл бурууңузду каалайт. Көзгө карап, сапаттуу өткөрүлгөн 5 мүнөт эле аны толугу менен тынчтандырышы мүмкүн.','„Emme, vaata mind!“ püsivus 👀','Kui oled telefonis või töösse süvenenud, kas laps tuleb ja lükkab su kätt? Tal on täiesti õigus – ta igatseb su jagamatut tähelepanu. Vaid 5 minutit kvaliteetaega koos silmsidemega võib ta sageli täielikult rahustada.'),
('22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea'::uuid,'"Качып кетүү" оюну 🏃‍♂️','Сиз пижама же көйнөк кийгизейин дегениңизде, ал бөлмөдөн күлүп качып жөнөйт. Маселени ачууланбай, оюнга айлантып чечиңиз. Куушмай ойноп кийиндирүү алда канча оңой.','„Suure põgenemise“ mäng 🏃‍♂️','Kui soovid talle pižaamat või särki selga panna, jookseb ta naerdes minema. Ära ärritu, vaid muuda see mänguks. Kullimängu mängides on riietumine palju lihtsam.'),
('f4730701-e02f-4cf0-9730-df8b7e034297'::uuid,'Өзүм кармап ичем! 🧸','Наристеңиз илинип турган оюнчуктарга таамай кол сунуп жатабы? Анын кол жана көз координациясы чыңдалууда! Аны ар кандай түстөгү буюмдар менен кызыктырыңыз.','Hoian ise! 🧸','Kas ta haarab rippuvaid mänguasju muljetavaldava täpsusega? Tema käe-silma koordinatsioon tugevneb! Julgusta teda erinevate värviliste esemetega.'),
('f2dc5d57-91a4-45de-b81b-0b2998a8593b'::uuid,'Шайыр күлкү 😂','Кичинекейиңиз Сиздин жылуу мамилеңизге каткырып жооп берип жатабы? Бул баалуу үндү видеого тартып алууну унутпаңыз!','Kõva naerupahvak 😂','Kas su pisike vastab sinu armsatele žestidele südamliku naeruga? Ära unusta seda kallist heli videosse püüda!'),
('322a385d-8940-4d2a-9d21-4777e2660139'::uuid,'Аба ырайына жараша ⛅','Сейилдөөгө чыгаарда терезеден карап эле жаңылбаңыз. Үйдөн чыгаар алдында сырттагы чыныгы шамалга жана температурага ылайыктуу кийимди тандоо үчүн аба ырайы жана кийим жардамчысын колдонуңуз.','Ilmatark ⛅','Jalutama minnes ära lase end aknast välja vaatamisest petta. Kasuta ilma- ja riietusassistenti, et leida sobivaim riietus vastavalt tegelikule tuulele ja välistemperatuurile.'),
('af1711a8-2ca3-45c1-ae35-556b3b0e2d67'::uuid,'Атасы менен уктоо алдындагы окуу 📖','Бүгүн кечинде бөлмөдө башкача маанай түзөлү. Китеп окуунун ордуна, атасы наристенин таттуу уйкуга кетүүсүнө жардам берип, жай жана ыргактуу бешик ырын ырдап берсин.','Issi unejutud 📖','Loome täna õhtul toas teistsuguse õhkkonna. Raamatu lugemise asemel võib isa laulda pehme rütmilise hällilaulu, mis aitab lapsel õrnalt unne suikuda.'),
('81a8fffa-561b-48b8-9be0-ff9b930a7bac'::uuid,'Сезимдерди сыртка чыгаруу 📝','Бүгүн баары топтолуп калгандай сезилип, чарчап турасызбы? Бардык кыйынчылыктарыңызды жана чарчооңузду Mood Journal (Маанай күндөлүгүнө) жазыңыз. Сезимдериңизди ичиңизге сактабаңыз.','Emotsionaalne vabastamine 📝','Tunned end kurnatuna ja tundub, et kõik kuhjub? Pane kõik oma mured ja väsimus meeleolupäevikusse kirja. Ära hoia emotsioone endas.'),
('42ea49cf-0e72-4699-aaf4-7633e9ea6a82'::uuid,'Токтоп калган ирмем 📸','Наристеңиздин сүйкүмдүү өзгөчөлүктөрү өзгөрүп, ал күндөн-күнгө ымыркайдан кичинекей балага окшоп баратат. Тезинен «Наристе фотосессиясы» бөлүмүн ачып, ушул баалуу өзгөрүүлөрдү тартып калыңыз!','Hetk, mis on ajas peatunud 📸','Ta näeb iga päevaga üha vähem välja nagu beebi ja üha rohkem nagu väike laps, sest need armsad beebinäojooned hakkavad kaduma. Ava kohe beebi fotosessiooni funktsioon ja jäädvusta need kallid muutused!'),
('b2328024-7846-4b25-a276-980c22ebcd52'::uuid,'Апаке, өзүңүзгө кам көрүңүз 🥑','Күнүмдүк шашылыш иштер менен алек болуп, түшкү тамакты бут үстүндө ичпеңиз. Тынч отуруп, темирге жана кальцийге бай өзгөчө салаттын даамын татып, ырахат алыңыз. Сиздин энергияңыз — бул үйдүн кыймылдаткычы.','Emme, toida ennast hästi 🥑','Ära söö lõunat jooksu pealt. Istu maha ja naudi rauast ning kaltsiumist pakatavat salatit. Sinu energia on selle kodu mootor.'),
('87db18be-f6b3-443d-9d07-0e305836d90b'::uuid,'110-күн: Чоң жетишкендик! 🥂','Сиз туура 110 күндөн бери жаңы жашоону башкарып келе жатасыз. Түгөйүңүзгө ыраазычылык билдирип, бүгүн кечинде тынчтыктын ырахатын көрүңүз.','110. päev: Võit! 🥂','Oled uue eluga toime tulnud täpselt 110 päeva. Täna oma kaaslast ja naudi tänaõhtust vaikust.'),
('29cc3dd1-d28b-45c9-93d7-58bfda48629c'::uuid,'Сөөмөйү менен көрсөтө баштады! ☝️','Ал алыстагы мышыкты же оюнчукту сөөмөйү менен көрсөтүп, реакция кылып жатат. Бул — биргелешкен көңүл буруунун жана баарлашуунун жогорку деңгээли!','Näitav sõrm on mängus! ☝️','Ta näeb sõrmega kaugemal asuvale kassile või mänguasjale ja reageerib sellele. See on ühise tähelepanu ja suhtluse kõrge tase!'),
('6eab5294-c731-4890-971d-ad01e35f7d7c'::uuid,'Паркпы же үйбү? ⛅','Сыртка чыккыңыз келип жатабы, бирок шамалбы? Биздин аба ырайы жана кийим жардамчыбыз Сизге температураны гана эмес, кичинекейиңизге кандай шамал өткөрбөй турган кийим керек экенин да айтып берет.','Park või kodu? ⛅','Tahad õue minna, aga väljas on tuuline? Meie ilma- ja riietusassistent ütleb sulle lisaks temperatuurile ka seda, milliseid tuulekindlaid riideid su pisike vajab.'),
('e037ab2c-d2a8-49ed-a1df-aac78a584118'::uuid,'Достукка карай алгачкы кадамдар 👫','Балаңыз сейил бакта башка балага оюнчугун биринчи жолу өз ыктыяры менен бердиби? Бул өнүгүүдөгү чоң кадам! Анын эгоцентризм сезими азайып, боорукердик сапаты калыптанып баратат. Бул жетишкендикти чоң кубаныч менен белгилеңиз!','Esimesed sammud sõpruses 👫','Kas su laps jagas pargis esimest korda vabatahtlikult mänguasja teise lapsega? See on tohutu arenguhüpe! Tema egotsentrilisus hakkab taanduma ja empaatiavõime puhkeb õide. Tähista seda verstaposti suure rõõmuga!'),
('18211145-ceeb-48f3-8053-1e2ff686e384'::uuid,'Үндөрдүн сыйкыры 🌊','Эгерде кечинде ыйлоо башталса, чочубаңыз. Бөлмөдөгү атмосфераны дароо өзгөртүү үчүн балаңызга «Ак ызы-чуу» (White Noise) коюп бериңиз.','Helide võlu 🌊','Kui õhtuti algavad nutuhood, ära paanitse. Muuda kohe toa õhkkonda, mängides beebile valget müra (White Noise).'),
('edfb2fd4-70c3-4b15-b2d1-0fc891b31501'::uuid,'Атасынын күлкүлүү жүздөрү 🤡','Балаңызды күлдүрүүнүн эң жакшы жолу — атасы кызыктуу үндөрдү чыгарышы! Бүгүнкү кубанычтуу көз ирмемдерди «Баланын фотосессиясы» менен тартып алыңыз.','Issi naljakad näod 🤡','Parim viis beebi naerma ajamiseks on sageli see, kui isa teeb naljakaid hääli! Jäädvusta tänaõhtused rõõmsad hetked beebi fotosessiooniga.'),
('9b064bbe-67b8-4d62-b3a0-30f79dc81515'::uuid,'Дайыма апасынын жанында! 🥰','Ваннага кирсеңиз да, ал эшиктин артында күтүп, ыйлап жатабы? Ажырашуудан коркуу сезими туу чокусуна жетти. Ар дайым «Мен ушул жердемин!» деп айтып, аны тынчтандырып туруңуз.','Alati emme lähedal! 🥰','Isegi kui lähed tualetti, ootab ta ukse taga ja nutab. Lahutamiskartus on haripunktis. Rahusta teda iga kord, öeldes: "Ma olen siinsamas!"'),
('92aa3f00-711e-43bd-a2d7-1f3bfbc7744d'::uuid,'"Меники!" деген өжөрлүк 🛑','Балаңыз баарын өзүнүкү деп эсептейби? Бөлүшүү түшүнүгү али толук калыптана элек. Мажбурлабаңыз; анын ордуна «Кезектешип ойнойлу» деген идеяны акырындап киргизиңиз.','„Minu oma!“ nõudlikkus 🛑','Kas su laps tahab kõike endale krabada? Jagamise mõiste pole veel täielikult välja arenenud. Ära sunni teda, vaid tutvusta järk-järgult ideed: "Mängime kordamööda."'),
('e77deeee-d612-4dac-bea4-ec9f16608958'::uuid,'Бүгүнкү сыйкырдуу жомок 🪄','«Акылдуу жомоктор» бөлүмүндө балаңыз башкы каарман болгон өзгөчө жомок түзүңүз: «Күндүз чарчап, түнкүсүн жылдыздарга учкан кичинекей бөбөк».','Tänane võlulugu 🪄','Loo nutikates muinasjuttudes (Smart Fairy Tales) eriline lugu, kus kangelaseks on sinu laps: "Pisike, kes päeval väsib ja öösel tähtede poole lendab."'),
('f0ba97cb-8dd2-4486-865e-1d22a5e551a6'::uuid,'Сиздин чөнтөк соода тизмеңиз 🛒','Мөмө-жемиш пюреси үчүн алма түгөнүп калдыбы? Соода тизмесин жолдошуңузга тапшырыңыз. Аны соода тизмесине кошуңуз; базардан азык-түлүк алуу — анын милдети!','Sinu tasku-ostunimekiri 🛒','Puuviljapüree jaoks said õunad otsa? Delegeeri ostunimekiri oma kaaslasele. Lisa see nimekirja – poeskäik on tema pärusmaa!'),
('adf1cd9b-1322-48c3-a05b-72b8aa90f9cc'::uuid,'Сыйкырдуу түнкү маанай 🪄','Уйкуга кете албай жатасызбы? Жаңы адаттарды үйрөтүү үчүн «Акылдуу жомоктор» бөлүмүндө атайын жомок түзүңүз.','Maagiline öine atmosfäär 🪄','Raske uinuda? Loo "Nutikates lugudes" (Smart Stories) eriline jutt, et uusi harjumusi tutvustada.'),
('26bb2530-b202-43eb-9226-30863365843e'::uuid,'Тамак сиңирүүнү көзөмөлдөө. 🧷','Ар кандай кошумча тамактар заңдын консистенциясын өзгөртүшү мүмкүн. Балаңыздын ден соолугун көзөмөлдөө үчүн ар бир жалаяк алмаштырууну Anacan тиркемесинде белгилеп туруңуз.','Seedimise jälgimine. 🧷','Erinevad tahked toidud võivad muuta väljaheite konsistentsi. Jälgi iga mähkmevahetust Anacanis, et hoida oma beebi tervisel silma peal.'),
('32966fee-53d4-4975-ad1e-195457a2fa5c'::uuid,'Оор түндөр 🥱','Кичинекейиңиз уйкуга каршылык көрсөтүп жатабы? Балким, күндүзгү уйкуларынын бирин кыскартуу убактысы келгендир. Анын күн тартибин карап чыгыңыз.','Väljakutseid pakkuvad ööd 🥱','Kas su pisike paneb uinumisele kõigest väest vastu? Võib-olla on aeg ühest päevasest uinakust loobuda. Vaata tema rutiin üle.'),
('b5660557-30c8-45a9-9c75-69616076d9ce'::uuid,'Апа үчүн гана мейкиндик ☕','Үйдө отуруп чарчадыңызбы? Өзүңүзгө кам көрүңүз! Биздин «Энелер үчүн ыңгайлуу жайлар» тизмесинен балдар менюсу бар жана ыңгайлуу отургучтары бар кафени тандап, өзүңүзгө керектүү «жеке убакытты» өткөрүңүз.','Aeg ainult emale ☕','Tunned end kodus istumisest kurnatuna? Tee endale kingitus! Vali meie emadele sõbralike kohtade (Mom-Friendly Spots) hulgast kohvik, kus on lastemenüü ja mugavad istmed, ning naudi hädavajalikku aega iseendale.'),
('221ab24d-c8af-4cca-b9d8-b4eae15499d0'::uuid,'Өзүңүзгө ишениңиз 👏','Үйдүн башаламандыгына көңүл бурбаңыз; анын ордуна балаңыздын бүгүн канчалык бактылуу экенине караңыз. Сиз эч бир китепте жазылбаган жолдор менен тарбиялаган укмуштуудай энесиз.','Ole enda üle uhke 👏','Ära keskendu segamini toale, vaid vaata, kui õnnelik su pisike täna on. Sa oled imeline ema, tõesti – viisil, mida ükski raamat ei suudaks õpetada.'),
('cdf44716-8a24-472d-9ff5-449bcc14a7fe'::uuid,'Ыргакка жараша бийлөө! 🎶','Телевизордон же телефонуңуздан ритмдүү үндү угары менен ал жамбашын булгалап баштайбы? Анын музыкалык кабыл алуусу өнүгүп жатат — ага кошулуп бийлеңиз!','Tantsime rütmi järgi! 🎶','Niipea kui ta kuuleb telerist või telefonist rütmilist heli, hakkab ta peput võngutama? Tema muusikaline taju tärkab – liitu temaga ja tantsige!'),
('49d00520-8368-4f13-9074-fbe894888b76'::uuid,'AI''дан сураңыз 🤖','Башыңызда миңдеген суроолор айланып жатабы? Издөөгө убакыт коротпоңуз; так жана илимий негизделген жоопторду алуу үчүн Anacan AI кызматынан дароо сураңыз.','Küsi AI-lt 🤖','Peas keerleb tuhat küsimust? Ära raiska aega otsimisele, küsi kohe Anacan AI-lt täpseid ja teaduspõhiseid vastuseid.'),
('d3e69c0c-c087-4266-8819-3e9aa9fc132a'::uuid,'Укалоо убактысы 💆‍♂️','Бала уктагандан кийин, күндүн чарчоосун басуу үчүн жолдошуңуз менен бири-бириңизге ийинге массаж жасаңыз. Эсиңизде болсун, сиздер бир командасыздар!','Massaaži aeg 💆‍♂️','Pärast beebi uinumist korralda koos kaaslasega õlamassaaž, et päeva stressist vabaneda. Pea meeles, te olete meeskond!'),
('33fb356d-029a-4c8c-bf0d-4b2ad8ed6777'::uuid,'Уктоо алдындагы жомок 🪄','«Акылдуу жомоктор» бөлүмүндө музыка жана жаратылыш үндөрүн гана колдонуп, өзгөчө үн пейзажын түзүңүз. Сөзсүз, таза тынчтык гана болсун.','Une-eelsed lood 🪄','Loo "Nutikates lugudes" (Smart Stories) eriline helimaastik, kasutades vaid muusikat ja loodushääli. Ei mingeid sõnu, vaid puhas rahu.'),
('1f9d373c-817c-4a86-9cb9-a9b3d9fac797'::uuid,'Шамдын жарыгында 10 мүнөт 🕯️','Бала уктады, үйдөгү ызы-чуу басылды. Жарыкты өчүрүп, 10 мүнөт бою караңгылыкты же күйүп турган шамды карап отуруңуз, бул оюңузду жана ойлоруңузду толугу менен тазалоого жардам берет.','10 minutit küünlavalgel 🕯️','Beebi magab, kodune kaos on läbi. Kustuta tuled ja vaata 10 minutit lihtsalt pimedusse või värelevat küünlaleeki, lastes oma meelel ja mõtetel täielikult puhata.'),
('e6ea83f7-b8a5-46f7-ba44-81c58175071e'::uuid,'Төмөн караңыз! 👣','Ал буттарынын манжаларын таап жатат! Бул күлкүлүү жана укмуштуудай өнүгүү этабын кунт коюп байкап, анын өсүшүнүн ар бир көз ирмеминен ырахат алыңыз.','Vaata alla! 👣','Ta avastab juba oma varbaid! Jälgi tähelepanelikult seda naljakat ja hämmastavat verstaposti ning naudi iga hetke tema arengust.'),
('7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8'::uuid,'Биздин коомдогу колдоо','«Мен эч качан мурдагыдай боло албайм» деген ойдон улам өзүңүздү жоготуп жатасызбы? Бул оор, бирок убактылуу сезимдериңиз менен Anacan коомчулугундагы башка энелер менен бөлүшүп, керектүү колдоону табыңыз.','Tugi meie kogukonnalt','Kas sind valdab tunne, et sa ei ole enam kunagi endine? Jaga seda keerulist, kuid mööduvat emotsiooni teiste emadega Anacani kogukonnas ja leia vajalikku tuge.'),
('d270bdfa-5a84-42b7-8b44-3231febd32b3'::uuid,'Тармал чачтар менен "салгылашуу" 🪮','Кичинекейиңиз чачын таратууга же байлоого такыр көнбөй жатабы? Күрөштү токтотуңуз! Күзгү алдына туруп, адегенде ага өз чачыңызды «стилдөөгө» уруксат бериңиз, андан кийин анын кезеги келет.','Kangekaelne juuste kammimise lahing 🪮','Kas su pisike keeldub kategooriliselt laskmast sul oma juukseid patsi panna või kammida? Lõpeta see võitlus! Seiske peegli ees ja lase tal kõigepealt sinu soengut "kujundada", seejärel on tema kord.'),
('b155d377-4b41-487e-b8ee-74a365226635'::uuid,'Уктоо алдындагы каршылыктар','Эгерде балаңыз уктоодон баш тартса, мажбурлабаңыз. Аны кайра-кайра уктатууга аракет кылып, өзүңүздү кыйнагандын ордуна, бөлмөсүндө оюнчуктар менен тынч оюн уюштуруп көрүңүз.','Uinakulahingud','Kui su pisike paneb uinakule vastu, ära sunni teda. Selle asemel, et teda korduvalt magama panna ja oma närve kulutada, proovi luua tema toas mänguasjadega vaikne mängurutiin.'),
('de11a3ea-d3e5-4374-adb5-b6c04fb6fc41'::uuid,'Түндүн баатыры 🦸‍♂️','Түнкүсүн ойгонуудан чарчадыңызбы? Атасын ойготуудан тартынбаңыз. Бир команда болуу — бул милдеттерди тең бөлүшүү дегенди билдирет.','Öö kangelane 🦸‍♂️','Oled öistest ärkamistest väsinud? Ära kõhkle isa üles ajamast. Meeskonnaks olemine tähendab koormuse võrdset jagamist.'),
('b7283d95-1357-4ff9-9423-db4159e19c31'::uuid,'Командалык жеңиш! 🥂','Дагы бир оор күндү артта калтырдыңыз. Жолдошуңуз менен бетме-бет отуруп, чай чөйчөктөрүңүздү кагыштырып, мындай деп айтыңыз: «Биз чындап эле легендарлуу командабыз жана биз укмуштуудай иш жасап жатабыз!»','Meeskonna võit! 🥂','Oled järjekordse väljakutseterohke päeva seljatanud. Istuge kaaslasega vastamisi, lööge teetassid kokku ja kinnitage: "Me oleme tõesti legendaarne meeskond ja teeme suurepärast tööd!"'),
('c932a08e-a484-4595-8fa6-e57165ffaf96'::uuid,'Бөлүшүү кыйынчылыгы 🧸','Оюнчуктарын бөлүшпөй жатабы? Бул өзүмчүлдүк эмес, бул өнүгүүнүн бир баскычы. Anacan AI менен 3 жашка чейинки балдарда оюнчуктарды кезектешип колдонууну үйрөтүү жолдорун билип алыңыз.','Jagamine on keeruline 🧸','Ei taha mänguasju jagada? See pole isekus, vaid arenguetapp. Õpi Anacan AI abil, kuidas suunata last kordamööda mängima, mitte ainult jagama, kui ta läheneb 3. eluaastale.'),
('23137ca6-6246-4dc7-b692-cdcd36eeac0f'::uuid,'Үч дөңгөлөктүү велосипеддеги кызыктар 🚴‍♂️','Велосипеддин педалын басууга аракет кылып жатабы? Анын бут булчуңдары жана кыймыл-аракети жаңы деңгээлге жетти! Коопсуз жерлерде аны колдоп туруңуз.','Kolmerattalise rõõmud 🚴‍♂️','Proovib pedaale vajutada ja rattaga sõita? Tema jalalihased ja koordinatsioon on jõudnud uue verstapostini! Julgusta teda turvalises kohas.'),
('b44d4b2a-f3eb-4e26-aa50-0105efb5648c'::uuid,'Апалар үчүн витаминдер','Сиз бөбөгүңүздүн курсагы ток болушу үчүн баарын жасайсыз. Ал эми өзүңүзчү? Биздин пайдалуу тамактар бөлүмүн карап, өзүңүз үчүн темирге жана кальцийге бай жеңил түшкү тамак тандаңыз.','Vitamiinid emale','Teed kõik, et su pisike oleks hästi toidetud. Aga kuidas on lood sinuga? Sirvi meie tervislike retseptide sektsiooni ja vali endale kerge, raua- ja kaltsiumirikas lõunasöök.'),
('c61401b5-5ca0-4aea-9f3d-ce4b09083a8c'::uuid,'Сиз супер-апа болууга милдеттүү эмессиз! 🦸‍♀️','️ Жардам суроодон эч качан тартынбаңыз. Кошумча дем алуу үчүн биздин Блогдор бөлүмүндөгү макалаларды окуп чыгыңыз.','Sa ei pea olema superema! 🦸‍♀️','️ Ära kunagi kõhkle abi küsimast. Täiendava motivatsiooni saamiseks sirvi meie blogiartikleid.'),
('93512cbe-adab-49c7-8e82-4466bf0e00ad'::uuid,'Апанын жеке убактысы ☕','Бөбөгүңүз уктап калганда, дароо үй жумуштарына киришпеңиз. Диванга отуруп, кофеңизден ичип, 10 мүнөт эч нерсени ойлонбой эс алыңыз.','Oma aeg emale ☕','Kui su beebi lõpuks uinub, ära torma kohe kodutöid tegema. Istu diivanile, naudi kohvi ja vaata lihtsalt 10 minutit aknast välja, et end tõeliselt välja lülitada.'),
('f62c402c-4ba9-489a-b6de-dde4e1aa3aae'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкүсүн ойгонуунун түйшүгүн жалгыз өзүңүз тартпаңыз. Өнөктөшүңүздү да ойготуңуз; команда болуу – бул жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi öövahetus 👨‍🍼','Ära kanna öiste ärkamiste koormat üksi. Ärata ka oma partner; meeskonnatöö tähendab kohustuste võrdset jagamist.'),
('8bc219eb-803c-491e-9625-0efec17a7dad'::uuid,'Эстафетаны өткөрүп бериңиз 🛋️','Эгер бөбөгүңүз уктаганда сиз да чарчап жатсаңыз, үй жумуштарын өнөктөшүңүзгө тапшыруудан тартынбаңыз. Сиздин ден соолугуңуз жана абалыңыз баарынан маанилүү.','Anna teatepulk üle 🛋️','Kui tunned, et kukud koos beebiga magama, ära kõhkle teiste kodutööde delegeerimisest partnerile. Sinu tervis ja heaolu on esmatähtsad.'),
('3e6ba90a-e6bd-4527-a0cb-94dcb9fecfac'::uuid,'Парктагы достор 🌳','Бөбөгүңүз коляскада зеригип жатабы? Аба ырайын жана кийимин текшерип, сейил бакта эркин жүрүүсүнө уруксат бериңиз, чөптөрдү жана жалбырактарды кармап көрсүн.','Sõbrad pargis 🌳','Kas su pisike tüdineb vankris? Kontrolli ilma ja riietust, seejärel lase tal pargis vabalt ringi uudistada, katsudes rohtu ja maas olevaid lehti.'),
('10872122-03c1-4660-aabc-490c724034c9'::uuid,'Чөнтөк толтура кенчтер','Сейил бактан келип, чөнтөгүнөн үч таш, куураган жалбырак жана бир бутак таап алдыңызбы? Ал үчүн бул баалуу казына! Сиздин милдет: алар үйгө чачырап кеткиче ''зыянсыздандыруу''.','Taskud täis aardeid','Tulite just pargist ja leidsid tema taskust kolm kivi, kuivanud lehe ja oksarao? Tema jaoks on need väärtuslikud aarded! Sinu missioon: proovi need „neutraliseerida“, enne kui need üle terve maja laiali satuvad.'),
('be9ad5fd-195c-40e7-99c6-7f5f91e01526'::uuid,'Сиздин текшерүү тизмеңиз 🛒','Уйкусуздуктан эсиңиз чаташып жатабы? Үйгө керектүү нерселерди эсиңизде сактоого аракет кылбаңыз – аларды Сатып алуулар тизмесине кошуп коюңуз.','Sinu ostunimekiri 🛒','Kas unepuudus teeb mälu uduseks? Ära looda oma ajule, et meeles pidada kõike vajalikku – lisa see hoopis oma ostunimekirja.'),
('d3bac322-3971-4b22-8636-d789ac7ce8db'::uuid,'Эмеректерге таянып жүрүү! 🧗‍♀️','Эмеректерди кармап басуу – анын сүйүктүү көнүгүүсү. Эми коопсуздук бурчтарын жана курч жерлерди кайра текшерип чыгууга эң ыңгайлуу учур!','Mööda mööblit ringi liikumas! 🧗‍♀️','Mööbli najal kõndimine on tema lemmik uus harjutus. Nüüd on ideaalne aeg kontrollida turvapiirdeid ja teravaid nurki!'),
('8f84e032-e8dd-4d1f-b3c6-5d57937006dd'::uuid,'Логика издебеңиз 👑','Эртең мененки тамакка балмуздак же кечээки шорпону талап кылып жатабы? Үйдө жаңы ''диктатор'' пайда болгон окшойт! Аны дароо башка нерсе менен алаксытып, тандоо сунуштаңыз (мисалы: ''алма жейсиңби же бананбы?'').','Ära otsi loogikat 👑','Nõuab hommikusöögiks jäätist või eilset läätsesuppi? Võib-olla on sul toas uus diktaator! Hajuta tema tähelepanu kohe, pakkudes valikut (nt „Kas tahad õuna või banaani?“).'),
('2226c745-19bb-4270-8e5c-a438c71816d4'::uuid,'Башка апалар эмне кылып жатышат 💬','Тынчсызданып же эмне кылаарыңызды билбей жатасызбы? Anacan Коомчулугуна кошулуп, сурооңузду бериңиз. Ишениңиз, ар бир эне ушундай жолду басып өтөт.','Mida teised emad teevad 💬','Tunned muret või ebakindlust? Liitu Anacan kogukonnaga ja küsi nõu. Usu meid, iga ema läbib sarnaseid kogemusi.'),
('31bb23a0-6713-4c06-9f74-65b7a51a3dd9'::uuid,'Тынчтандыруучу жомок убактысы 📖','Бүгүн кечинде бөбөгүңүзгө жөн гана өз үнүңүз менен жомок окуп бериңиз. Эч кандай кошумча буюмдардын кереги жок; эненин үнү – эң күчтүү сыйкыр.','Rahustav unejutt 📖','Loe täna õhtul oma beebile unejuttu vaid oma häälega. Pole vaja mingeid abivahendeid; ema hääl on kõige võimsam maagia.'),
('907a5bc5-4a7e-48ec-977c-d9c5440faba0'::uuid,'Уктоо алдындагы шылтоолор 🏃‍♂️','Ал күтүлбөгөн жерден суу ичкиси келип, горшокко отургусу келип же парданы өпкүсү келип жатабы... Анын кичинекей мээси уктоодон качуу үчүн шылтоо ойлоп табууда. Чек коюңуз: бир стакан суу жана бүттү. Чечкиндүү болуңуз.','Vabandused magamaminekuks 🏃‍♂️','Ta vajab äkki vett, tahab potile või isegi kardinat suudelda... Tema väike aju leiutab uusi vabandusi, et und edasi lükata. Sea kindlad piirid: ainult üks klaas vett ja kõik. Ole resoluutne.'),
('4699f7a7-a05a-4fb5-bcc3-1031cc990173'::uuid,'Ойдон чыгарылган ишкердик чалуулар','Ал бананды же пультту кармап алып, ойдон чыгарылган тилде ''телефон менен сүйлөшүп'' жатабы? Ал сиздин дене тилиңизди туурап жатат! Видео тартып алыңыз, кийин чогуу күлөсүз.','Kujuteldavad töötelefonikõned','Kas ta hoiab banaani või pulti ja „räägib telefoniga“ väljamõeldud keeles? Ta peegeldab suurepäraselt sinu kehakeelt! Filmi seda ja hoia tulevikuks – saad kõvasti naerda.'),
('34253cb9-0e01-47a7-9def-03c3b3e05aba'::uuid,'Кызыктуу оюндар 🎈','Ал чалкасынан жатып, абада буттары менен ''велосипед тээп'' жатабы? Бул анын жаңы сүйүктүү оюну! Кошулуп, аны кытыгылаңыз.','Lõbusad mängud 🎈','Kas ta lamab selili ja „sõidab õhus jalgrattaga“? See on tema uus lemmiktegevus! Ühine temaga ja kõdita teda.'),
('6498b35b-aa8e-416f-9da1-2596c74b14d0'::uuid,'Кош айтышып кол булгалоо! 👋','Бирөө кетип жатканда өз демилгеси менен коштошуп кол булгалап жатабы? Кандай сонун социалдык жөндөм!','Head aega lehvitamine! 👋','Kui keegi lahkub, kas ta lehvitab ise hüvasti? Milline imeline sotsiaalne refleks!'),
('b49f5612-c3e4-4568-8a0e-3494499a88d1'::uuid,'Түн ортосунда сооробогон ыйдан ойгондуңузбу? 😭','Аны акырын кучактаңыз, бирок ойготпоого аракет кылыңыз. Эмнеге муктаж экенин түшүнүү үчүн Ыйды талдоо (Cry Analysis) функциясын колдонуп, үндөрүн угуңуз.','Ärkasid keset ööd lohutamatu nutu peale? 😭','Kaisuta teda õrnalt, kuid ära proovi teda äratada. Kuula tema hääli nutuanalüüsiga, et mõista, mida ta vajab.'),
('77b18a3d-16c2-454b-9fe4-daea00f5a342'::uuid,'Күн тартиби өзгөрүп жатабы? ⏱️','Ар түнү уктоо бир сааттан ашык убакытты алып жатабы? Балаңыздын уйку графигин текшериңиз. Балким, күндүзгү уйкусун кыскартуу же кечки уйкусун эртелетүү керек чыгар.','Kas rutiin muutub? ⏱️','Kas magamaminek võtab igal õhtul üle tunni? Kontrolli lapse unegraafikut. Võib-olla on aeg päevane uinak täielikult ära jätta või õhtust magamaminekut varasemaks nihutada.'),
('d1e64fb7-d149-4fd0-afca-834eed2264d1'::uuid,'Уйкунун регрессиясыбы? 🌙','Бөбөгүңүз түнкүсүн көп ойгоно баштадыбы? Бул 4 айлык уйку регрессиясынын белгиси болушу мүмкүн. Сабырдуу болуңуз; бул убактылуу гана көрүнүш.','Uneregressioon? 🌙','Kas su beebi on hakanud öösiti sageli ärkama? Need võivad olla 4-kuuse une-regressiooni märgid. Ole kannatlik; see on vaid ajutine faas.'),
('fd05df6d-36c8-4c59-9212-7542837f9f4c'::uuid,'Бөлүшүү – бул жакшы нерсе 💬','Эми эч качан мурдагыдай боло албайм деп кабатырланып жатасызбы? Бул убактылуу сезимди Anacan Коомчулугундагы башка энелер менен бөлүшүңүз – сиз жалгыз эмессиз.','Jagamine on okei 💬','Kas tunned end ülekoormatuna mõttest, et ei saa enam kunagi oma endiseks minaks? Jaga seda tavalist, ajutist tunnet teiste emadega Anacan kogukonnas – sa pole üksi.'),
('9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469'::uuid,'Тиш щеткасы үчүн күрөш 🪥','Тиш щеткасын көргөндө оозун бекем жаап жатабы? Гигиенаны согушка айлантпаңыз. Сунушталган өнүмдөр бөлүмүнөн музыкалык тиш щеткаларды карап, бул тажатма ишти кызыктуу оюнга айлантыңыз.','Hambapesulahing 🪥','Kas ta surub suu kinni, kui näeb hambaharja? Ära muuda hügieeni lahinguks. Vaata soovitatud toodete hulgast muusikalisi hambaharju ja muuda see tüütu rutiin lõbusaks mänguks.'),
('6032f94e-69e7-4802-b291-44567c9f71d1'::uuid,'Атасынын бешик ыры 👨‍🍼','Бүгүн кечинде бөбөктү уктоочу бөлмөсүндө жалгыз уктатуу милдетин өнөктөшүңүз аткарсын.','Issi hällilaul 👨‍🍼','Täna õhtul peaks su partner võtma väljakutse beebi üksi oma toas magama panna.'),
('7b460d4a-b37e-465f-9c70-e137f59bcc07'::uuid,'Үй жыйноо же эс алуу? 🛋️','Бөбөгүңүз уктап калганда, идиш жууганга шашпаңыз. Анын ордуна диванга жатып, көзүңүздү жумуп, 15 мүнөт эс алыңыз. Эсиңизде болсун, сиз робот эмессиз!','Kas koristada või puhata? 🛋️','Kui su beebi lõpuks uinub, ära torma nõudepesumasinat tühjendama. Selle asemel heida diivanile, sule silmad ja lihtsalt hinga 15 minutit. Pea meeles, sa pole robot!'),
('a1392cb5-508d-45a8-9d3d-1985c8d19958'::uuid,'«Жок» деп каршылашуу башталды! 🛑','Жакпаган нерсени сунуштаганда, ал башын чайкап, түртүп жатабы? Анын өз алдынчалыгы калыптанып жатат! Анын кичинекей чечимдерин сыйлоого аракет кылыңыз.','„Ei“-ütlemise ajastu algab! 🛑','Kui pakud talle midagi, mis talle ei meeldi, raputab ta nüüd pead ja lükkab selle eemale. Tema individuaalne tahe kujuneb! Püüa austada tema väikeseid otsuseid.'),
('2cc5ac97-f2b1-4c92-8852-fec32f54b311'::uuid,'Үндү көзөмөлдөө 🤫','Бөбөгүңүз уктагандан кийинки алгачкы жарым саат – эң сезимтал убакыт. Айлана-чөйрөнү текшерүү жана капыстан чыккан үндөрдөн коргоо үчүн үн өлчөгүчтү колдонуңуз.','Helikontroll 🤫','Esimene pooltund pärast lapse uinumist on kõige tundlikum aeg. Kasuta helimõõdikut, et kontrollida keskkonda ja kaitsta teda äkiliste helide eest.'),
('e0b42cd5-f681-4866-a7ec-b0b890444381'::uuid,'Ден соолугу чың апа, ден соолугу чың бала 🥑','Чарчап жатасызбы? Темир жана кальций запасыңыз азайып калган болушу мүмкүн. Күч-кубат берүүчү тез даярдалуучу салаттардын рецепттерин биздин бөлүмдөн карап көрүңүз.','Terve ema, terve laps 🥑','Tunned end kurnatuna? Sinu raua- ja kaltsiumivarud võivad olla madalad. Vaata meie tervislikke retsepte, et leida kiire ja energiat andev salat, mis aitab sul jalul püsida.'),
('4eb27952-4f25-4c0d-8e25-cf21169fe3eb'::uuid,'Өзүңүзгө кам көрүңүз 🥑','Төрөттөн кийинки мезгилде сөөктөрүңүз жана тиштериңиз сезимтал болуп калышы мүмкүн. Тамактанууңузда кальций жетиштүү экенине көз салыңыз. Өзүңүзгө кам көрүңүз!','Hoolitse enda eest 🥑','Sünnitusjärgsel perioodil võivad sinu luud ja hambad muutuda tundlikumaks. Ära unusta lisada oma toidulauale piisavalt kaltsiumi. Hoolitse enda eest!'),
('5e90ebc0-15bf-465f-ae64-eff8a7b0a00c'::uuid,'Бүгүн эртең менен маанайыңыз жокпу? ☁️','Бөбөгүңүз тез өсүү мезгилинде болушу мүмкүн. Ага көбүрөөк мээрим төгүп, өзүн коопсуз жана сүйүктүү сезишине шарт түзүңүз.','Kas tuju on täna hommikul paha? ☁️','Sinu pisike võib läbida kasvuhüpet. Lihtsalt paku talle rohkem kaisutusi ja pane teda tundma end turvaliselt ja armastatuna.'),
('3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a'::uuid,'«Буттарым иштебей жатат» деген каршылык 🛑','Сейил бактан келе жатып, бутум ооруду деп отуруп алып кучактап коюуну суранып жатабы? Бул чарчоо эмес, бул амалкөйлүк. Аны оюнга айлантыңыз: ''Кел, ким коёндой секирип үйгө биринчи жетет экен!''','„Mu jalad ei tööta“ vastasseis 🛑','Kas ta istub pargist koju minnes äkki maha ja palub sülle, väites, et jalad ei tööta? See pole väsimus, vaid kaval taktika. Muuda see mänguks: „Vaatame, kas suudad jänese kombel hüpates koju jõuda!“'),
('b948ea64-f471-4d36-958a-85e04a0250f1'::uuid,'Горшокко үйрөтүүчү оюндар','Табигый муктаждыгы чыкканда парданын артына же дивандын жанына жашынып жатабы? Горшокко үйрөтүүнүн илимий жолдорун окуу үчүн биздин блог бөлүмүнө баш багууга эң сонун учур.','Potitreeningu mängud','Kas ta peidab end kardina taha või diivani äärde, kui loodus kutsub? See on ideaalne aeg külastada meie blogi ja lugeda teaduslikult põhjendatud samme potitreeningu alustamiseks.'),
('813f6345-1636-47fd-9a6b-aee16d069800'::uuid,'Уйкунун белгилери 🥱','Көзүн ушалап, эсинеп баштаганын күтпөңүз. Көз карашы басаңдай баштаган учурда, аны акырындык менен уйку режимине өткөрүңүз.','Unemärgid 🥱','Ära oota, kuni ta hõõrub silmi ja haigutab. Hetkel, mil tema pilk hakkab tuhmuma, on aeg sujuvalt une-rutiiniga alustada.'),
('088b061c-e51f-4931-8636-b06152d7eaff'::uuid,'Бир нерсеге тынчсызданып жатасызбы? 🤖','Форумдарда сааттап отурбай, сурооңузду Anacan AI''га берип, тез жана ишенимдүү жооп алыңыз.','Kas sul on midagi südamel? 🤖','Selle asemel, et veeta tunde foorumites, küsi oma küsimus Anacan AI-lt ja saa kiire, usaldusväärne vastus.'),
('b9e8fff7-f7f2-410b-a103-f4cd6c6231f8'::uuid,'Күндөлүккө ичтегини төгүү 📝','Кимдир бирөө ''Үйдө эле отурасың, эмнеге чарчайсың?'' дедиби? Дароо Маанай күндөлүгүңүздү ачып, бардык нааразычылыгыңызды жазып салыңыз. Жасалма жылмайгандан көрө, чыныгы сезимдериңизди билдирген жакшы.','Mõtete kirjapanek päevikusse 📝','Kas keegi ütles: „Sa oled ju kodus, millest sa väsinud oled?“ Ava kohe oma meeleolupäevik ja vala kogu oma frustratsioon ekraanile. Parem on väljendada oma tõelisi tundeid kui teeselda naeratust.'),
('0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc'::uuid,'Атасынын жомок айтуу шоусу 📖','Бүгүн кечинде жомокту сиз эмес, атасы окусун. Каармандардын үнүн өзгөртүп, жомокту кызыктуу кылып айтып берсин. Сиз болсо четте туруп, алардын күлкүсүнөн ырахат алыңыз.','Issi unejutud 📖','Täna õhtul ei ole toas sinu hääl, vaid issi oma. Lase tal lugeda unejuttu, kasutades tegelaste jaoks naljakaid hääli, tehes neid madalaks või kõrgeks. Sina astu lihtsalt kõrvale ja naudi naeru.'),
('616fd04c-b736-454a-9242-b3c011b0cdc5'::uuid,'Сабырыңыз түгөнүп, колдоруңуз чарчадыбы? 👨‍👧','Бүгүн кечинде бөбөктү атасына берип, эшикти жабыңыз да, өзүңүз үчүн 15 мүнөт убакыт бөлүңүз.','Kannatus katkemas ja käed väsinud? 👨‍👧','Täna õhtul anna beebi issile, sulge uks ja võta 15 väärtuslikku minutit endale.'),
('2fc731d4-47df-4b97-8f67-c7df6aabac96'::uuid,'Апанын жашыруун шоколад кампасы','Баласы карабай калганда дароо шоколад жеп алган энеге: ал глюкоза сиздин татыктуу сыйлыгыңыз! Күн бою ошол энергияны сактап калуу үчүн сизге кубат керек.','Ema salajane šokolaadivaru','Emale, kes pistab kiirelt tüki šokolaadi suhu, kui laps selja pöörab – see glükoos on sinu õigustatud preemia! Vajad energiat, et kogu päeva vältel lapse tempoga sammu pidada.'),
('edb08c0a-b151-4f7a-9713-c903f3f5c584'::uuid,'Менин өзгөчө эң жакын досум 🥄','Кымбат оюнчуктары туруп, ашканадан силикон калакчаны таап алып, күнү бою көтөрүп жүрөбү, ал тургай аны менен уктап жатабы? Баланын фантазиясы укмуш. Тоскоол болбоңуз, калакчасын сүйүүсүнө уруксат бериңиз.','Minu veider parim sõber 🥄','Kõigi nende kallite mänguasjade kõrval on ta leidnud köögist silikoonist spaatli ja kannab seda terve päeva kaasas, isegi magama paneb? Lapse kujutlusvõime on uskumatu. Ära sekku, lase tal oma spaatlit armastada.'),
('36ebb286-2e4d-4e44-a91d-6c026199737c'::uuid,'Жаратылышты таануу','Үйдө отуруп зеригип жатасызбы? Аба ырайын карап, эң сонун кийиниңиз! Сары жалбырактарды издөө миссиясы менен сыртка чыгыңыз – бул балага энергиясын сарптоого жардам берет, ал эми сиз таза абадан дем аласыз.','Looduse avastamine','Tunned end toas olemisest uimasena? Kontrolli ilma ja vali sobiv riietus! Mine välja lihtsale missioonile – otsige kollaseid lehti. See aitab tal energiat kulutada ja sina saad värsket õhku.'),
('188836b2-55a8-4b14-87fe-653f4e05ae3e'::uuid,'Бүгүн ачууңуз бат келип жатабы?','Бөбөгүңүз уктап жатканда, Маанай күндөлүгүңүзгө сезимдериңизди жазып коюңуз. Эртең – жаңы мүмкүнчүлүктөргө толгон жаңы күн.','Kas oled täna ärritunud?','Samal ajal kui beebi magab, võta hetk ja kirjuta oma tunded meeleolupäevikusse. Homne on uus päev, täis värskeid võimalusi.'),
('4d566d24-14b9-45b0-be5d-1940c1563ed9'::uuid,'Тез соода кылуу 🛒','Өнөктөшүңүз жумуштан чыктыбы? Дароо Сатып алуулар тизмесин ачып, сүт, жемиш жана башка керектүү нерселерди секунданын ичинде жөнөтүңүз!','Kiired poeskäigud 🛒','Kas su partner lahkub töölt? Ava kiiresti ostunimekiri ja saada talle vajalikud asjad – piim, puuviljad ja muu vajalik – sekunditega!'),
('fd0252a6-07bf-4750-bd4b-be91888e16f6'::uuid,'Чоңдорду тууроо! 🧹','Сиз үй жыйнап жатканда, ал да чүпүрөктү алып, сизди туурап жатабы? Ал — сиздин кичинекей күзгүңүз, сиз жасаган ар бир кыймылды кайталап жатат!','Täiskasvanute järeleaimamine! 🧹','Kas koristamise ajal haarab laps lapi ja püüab sind jäljendada? Ta on sinu väike peegel, kes kopeerib kõike, mida sa teed!'),
('232de7cd-2ff6-4b62-8cee-002063d545fd'::uuid,'Кереметтүү баш аламандык! 🌪️','Балдардын буюмдары үй ичинде чачылып жатабы? Мейли, чачылып эле турсун! Үйдүн иретсиздиги сиздин жаман эне экениңизди билдирбейт, бул болгону балаңыз сиз үчүн биринчи орунда экенин көрсөтөт.','Kaunis segadus! 🌪️','Kas beebiasjad on mööda maja laiali? Las nad olla! Segamini kodu ei tähenda, et oled halb ema; see näitab lihtsalt, et sinu laps on sinu prioriteet.'),
('a789d8f9-cc5b-43fd-8931-a3c5dbb78c75'::uuid,'Командалык колдоо 🥂','Күндүн чарчоосун басуу үчүн жубайыңыз менен бир чыны чай ичип, бири-бириңизге: «Биз дагы бир күндү ийгиликтүү өткөрдүк!» деп айтып коюңуз.','Meeskonna tugi 🥂','Päevaväsimusest taastumiseks joo koos kaaslasega tass teed ja öelge üksteisele: „Me saime veel ühe päevaga hakkama!“'),
('ac527e8b-ca16-4272-b6ba-964f15ba419b'::uuid,'Педиатриялык маселелер 🤖','10 айлык бөбөгүңүзгө тамактын өлчөмү канча болушу керек деп ойлонуп жатасызбы? Кабатыр болбоңуз! Anacan AI''дан педиатрлар сунуштаган так тамактануу графигин сураңыз.','Mured pediaatriaga 🤖','Muretsed oma 10-kuuse lapse portsjonite suuruse pärast? Ära muretse! Küsi Anacan AI-lt täpset ja lastearsti poolt heaks kiidetud toitumiskava.'),
('4b98ee52-d8a1-4d7a-9183-64cdd8482ef0'::uuid,'Кооптуу сөздөр 🤐','Ал кайсы бир жерден уккан жаман сөздү кайталап, сиздин реакцияңызды күтүп жылмайып жатабы? Сиздин эң чоң куралыңыз — реакция кылбоо. Күлбөңүз, ачууланбаңыз, жөн гана көңүл бурбаңыз. Ал аны тез эле унутуп калат.','Ohtlikud sõnad 🤐','Kas laps kordab kuskilt kuuldud inetut sõna, naeratab ja ootab sinu reaktsiooni? Sinu suurim relv on reaktsiooni puudumine. Ära naera, ära vihastu, lihtsalt ignoreeri seda. Ta unustab selle.'),
('2cbef83d-a5f1-4b69-858b-9d1310e2cac3'::uuid,'Үйдө отуруп тажадыңызбы? ☕','Үйдө отуруп тажадыңызбы? Коляска менен кирүүгө ыңгайлуу жакын жердеги кафелерди табуу үчүн «Энелер үчүн ыңгайлуу жайлар» бөлүмүн карап көрүңүз.','Kas kodus olemisest on villand? ☕','Tunned end koduseinte vahel veidi üksildasena? Uuri jaotist „Emasõbralikud kohad“, et leida lähedal asuv kohvik, kuhu pääseb mugavalt ka vankriga.'),
('e38208ca-c817-4de4-ba96-5a5ca4752901'::uuid,'Тиш чыгуудагы ыңгайсыздык уланууда 🦷','Бөбөгүңүздүн манжалары дайыма оозундабы жана баарын кемирип жатабы? Балким, азуу тиштери чыгып жаткандыр! Бул абалды тиш чыгууну көзөмөлдөөчү күндөлүгүңүзгө жазып коюңуз.','Hammaste tuleku ebamugavus jätkub 🦷','Kas lapse sõrmed on pidevalt suus ja ta närib kõike? Võib-olla on tulemas tagumised hambad! Märgi see üles oma hammaste tuleku jälgijasse.'),
('0535564e-f2c8-4264-bd71-a94e3154d928'::uuid,'Аба ырайына көз салуу ⛅','Сырттагы аба ырайы белгисизби? Биздин «Аба ырайы жана кийим тандоо» куралыбыз аркылуу шамалдын ылдамдыгын (терезеден көрүнбөгөн) заматта билип, балаңызга ылайыктуу кийимдерди тандап алыңыз.','Ilmaprognoos ⛅','Kas ilm on ebakindel? Meie ilma- ja riietustööriist näitab sulle kohe tuule kiirust (mida aknast ei näe) ja soovitab sobivat riietust.'),
('c2b89303-d5b8-4b81-97cd-3a091f15bb05'::uuid,'Тынчтыктын баалуулугу 🤫','Акыры уктадыбы! Үн өлчөгүчүңүздү иштетип, экрандан үн деңгээлин (0-10 децибел) байкап туруңуз. Ал көрсөткүчтөрдүн төмөн экенин көрүү — чарчаган эненин мээси үчүн эң жакшы эс алуу.','Vaiksete hetkede väärtus 🤫','Laps lõpuks magab! Aktiveeri müratase ja jälgi ekraanilt helitaset (0–10 detsibelli). Nende madalate numbrite nägemine on parim palsam väsinud ema ajule.'),
('ff5950e2-aed4-41ca-bc9a-64a1b039968a'::uuid,'Сыйкырдуу жомок убактысы 🪄','«Акылдуу жомоктор» бөлүмүндө бүгүн түн үчүн өзгөчө жомок түзүңүз: Булуттардын үстүндө уктап жаткан эр жүрөк бөбөк тууралуу жомок.','Lummav unejutt 🪄','Loo Smart Tales abil just tänaseks õhtuks eriline lugu: muinasjutt vaprast pisikesest, kes magab pilvedel.'),
('37346c6c-3239-4e07-bcc0-24af9be99f3f'::uuid,'Шилекейи агып жатат! 🤤','Эмчегинин алдындагы алжапкычы заматта эле суу болуп калабы? Демек, бөбөгүңүздүн тиштери жарылып келе жатат! Силикон алжапкычтар азыр сиздин эң жакын жардамчыңыз болот.','Süljevoolus missugune! 🤤','Kas pudipõll saab sekunditega märjaks? Need väikesed igemed valmistuvad hammaste tulekuks! Silikoonist pudipõlled on praegu sinu parimad sõbrad.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('45a51286-f051-4f99-a23c-39a189481dfa'::uuid,'Пижама кийүү үчүн күрөш','Эртең менен кийген кир, так болгон пижамасын кечке чейин чечпей койдубу? Үч жаштагы бала үчүн сырткы көрүнүш маанилүү эмес. Эгер тоңбосо, ыңгайлуу пижамасы менен дагы бир нече саат жүрө берсин.','Võitlus pidžaamade pärast','Laps ei taha hommikust õhtuni oma määrdunud pižaamat seljast võtta? Kolmeaastase jaoks pole esteetika prioriteet. Kui tal pole külm, lase tal neid mugavaid riideid veel paar tundi nautida.'),
('4c871abf-c886-4fbd-909f-95e344736fa3'::uuid,'Сыйкырдуу жомоктогу менин ролум 🪄','Бардык классикалык жомокторду жаттап бүттүңүзбү? «Акылдуу жомоктор» функциясын ачыңыз. Ал жерден балаңыз башкы каарман, ал эми анын бөлмөсү сыйкырдуу дүйнө болгон уникалдуу жомок түзө аласыз.','Minu roll maagilises loos 🪄','Klassikalised unejutud on sul juba peas. Ava Smart Stories funktsioon, kus saad luua erilise unehetke, kus peategelaseks on sinu laps ja võlukohaks tema enda tuba.'),
('86a98c8a-884a-4567-83c1-4d206dccead9'::uuid,'Таза аба — эң мыкты дары 🌳','Эгер бөбөгүңүз өтө эле тынчсызданып жатса, аны дароо таза абага алып чыгыңыз. Таза аба — ыйлаган баланы сооротуунун эң жөнөкөй жана натыйжалуу жолу.','Värske õhk on parim rohi 🌳','Kui beebi on väga rahutu, mine temaga kohe õue. Värske õhk on lihtsaim ja tõhusaim ravim jonnihoogude vastu.'),
('51cec612-e243-435d-9b60-1e3269d69cee'::uuid,'Музыкалык кечелер 🎶','Кечки маалдагы тынчсызданууну басуунун эң оңой жолу — анын сүйүктүү ырын коюп, кучактап алып бийлөө!','Muusikalised õhtud 🎶','Lihtsaim viis õhtuse rahutuse leevendamiseks on panna mängima lapse lemmiklaul, võtta ta sülle ja tantsida!'),
('533a4ec1-68c0-4cf3-92cd-723b3f8c0979'::uuid,'Бут кийимин чечүү 👟','Кийинүү процесси күрөшкө айланып кеттиби? Кичинекейиңиз байпагын жана бут кийимин өзү чечип жатабы? Анын өнүгүп жаткан кыймыл-аракетине суктаныңыз!','Kingade jalast võtmine 👟','Kas riietumisest on saanud maadlusmatš? Sinu pisike oskab juba ise sokke ja kingi jalast võtta. Imetle tema arenevat motoorikat!'),
('9f3be00e-0091-4500-91da-22dc9ba62d93'::uuid,'Мультфильм сынчысы 📺','Ал сизге көргөн мультфильми тууралуу өзүнүн тилинде, ким кайда барганын олуттуу түшүндүрүп жатабы? Таң калгандай болуп, кунт коюп угуңуз. Ал өзүн дүйнөдөгү эң акылдуу адамдай сезсин.','Multikakriitik 📺','Kas laps jutustab sulle oma keeles vaadatud multikast, selgitades tõsiselt, kes kuhu läks? Kuula tähelepanelikult ja üllatunult. Lase tal tunda end maailma targeima inimesena.'),
('ae291c04-b5c7-4ff1-937e-2b2b6d502624'::uuid,'Биз бир командабыз! 💖','Оор күндөн кийин өнөктөшүңүз менен бетме-бет отуруп, сезимдериңиз менен бөлүшүүгө убакыт табыңыз. Бири-бириңизди колдоо түйшүктү эки эсе жеңилдетет.','Me oleme meeskond! 💖','Pärast rasket päeva võta aega, et istuda kaaslasega vastamisi ja jagada oma tundeid. Üksteise toetamine muudab koorma poole kergemaks.'),
('7bbccad8-a83a-493c-82e1-d823d261e04b'::uuid,'Логикалык табышмактар 🧩','Оюнчуктарды кутуга салып, кайра баарын чачып жатабы? Бул анын «ичинде» жана «сыртында» деген логиканы өздөштүрүп жатканы. Бул изилдөөсүнө тоскоол болбоңуз!','Loogikamõistatused 🧩','Kas laps paneb mänguasju kasti ja kallab need siis jälle välja? Nii areneb tema arusaam „sees“ ja „väljas“ loogikast. Ära keela seda avastamisrõõmu!'),
('84cdedf9-5de5-49c9-887b-6f8ccc988990'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкү уйкусуздуктун түйшүгүн жалгыз өзүңүз тартпаңыз. Өнөктөшүңүздү ойготуңуз; команда болуу — бул жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi öövahetus 👨‍🍼','Ära kanna öiste ärkamiste koormat üksinda. Ärata oma kaaslane; meeskonnaks olemine tähendab kohustuste võrdset jagamist.'),
('89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8'::uuid,'Эрте ойгонгондор 🌅','Ал таңкы саат 6да ойгонуп, сиз абдан чарчадыңызбы? Anacan AI''дан бул тартипти кантип жөнгө салууну сураңыз. Унутпаңыз, уйкусуздук түбөлүк эмес; баары өтүп кетет.','Varajased ärkajad 🌅','Laps on kell 6 üleval, aga sina oled täiesti kurnatud? Küsi Anacan AI-lt, kuidas rutiini kohandada. Pea meeles, unetus ei kesta igavesti; kõik möödub.'),
('eabf6802-121e-4850-8036-ab2dbabaf84e'::uuid,'Сезимдериңизди бөлүшүүдөн тартынбаңыз. 📝','Чарчадыңызбы же бактылуусузбу? Кандай болбосун, бүгүнкү сезимдериңизди «Маанай күндөлүгүнө» жазып, жүгүңүздү жеңилдетиңиз.','Ära kõhkle oma tundeid jagamast. 📝','Väsinud või õnnelik? See pole oluline – kergenda oma südant, märkides tänased emotsioonid oma tujupäevikusse.'),
('e229522e-360b-4392-8cfc-620f6326286c'::uuid,'Жубайлардын шампан ичүү учуру 🥂','Бала уктады. Шампан жок болсо да, чөйчөктөргө жылуу чай куюп, өнөктөшүңүз менен «Дагы бир оор күндү жеңдик!» деп чөйчөктөрдү кагыштырыңыз. Сиздер чындап эле сонун командасыздар.','Paaride šampusehetk 🥂','Laps magab. Isegi kui šampanjat pole, vala tassidesse sooja teed, löö kaaslasega kokku ja ütle: „Me elasime veel ühe raske päeva üle!“ Te olete tõesti suurepärane meeskond.'),
('a4c45285-b9cc-4763-a80c-d694137bbb6a'::uuid,'Апалар үчүн ыңгайлуу жерлерди табуу ☕','Ушунча чарчоонун арасында сиз таза аба менен дем алууга татыктуусуз. «Энелер үчүн ыңгайлуу жайлар» функциябызды колдонуп, жакынкы тынч кафени табыңыз жана өзүңүзгө кам көрүңүз.','Emadele sobivate kohtade avastamine ☕','Kogu selle väsimuse keskel väärtid sa hetke iseendale. Leia meie emasõbralike kohtade funktsiooni abil lähedal asuv vaikne kohvik ja hellita end veidi.'),
('5fcfd433-5086-40d6-89d5-0d756fb06e17'::uuid,'Музыканын күчү 🎶','Кечки маанайсыздык же себепсиз ый башталганда, жай темптеги классикалык музыканы коюп көрүңүз. Бул бөбөгүңүздү тынчтандырууга көп жардам берет.','Muusika vägi 🎶','Kui algab õhtune rahutus või seletamatu nutt, proovi mängida aeglase tempoga klassikalist muusikat. See aitab sageli pisikest rahustada.'),
('f802a634-da9b-44e2-a965-9f94ea543fd1'::uuid,'Соода тизмесиндеги күтүлбөгөн нерсе','Дүкөнгө барардан мурун соода тизмеңизди ачсаңыз, бөбөгүңүз акырын келип, телефондун экранын таптап, тизмеге шоколад кошуп койду. Ооба, алар технологияны сизден да жакшы түшүнүшөт!','Üllatus ostunimekirjas','Avasid enne poodi minekut ostunimekirja ja nägid, kuidas sinu pisike hiilis ligi, toksas ekraani ja lisas sinna šokolaadi. Jah, nad tunnevad tehnoloogiat sinust paremini!'),
('0d0524d6-a4ad-4051-b779-b554d981748f'::uuid,'Ваннада узакка жуунуу 🛀','Суу менен ойноо ушунчалык кызыктуу болгондуктан, манжалары бырышып кетсе да ваннадан чыккысы келбейт. Ага 5 мүнөт калганын эскертип, таймер коюңуз. «Таймер чырылдаганда чыгабыз» эрежеси көбүнчө эң сонун иштейт.','Pikk vanniskäik 🛀','Veega mängimine on nii lõbus, et isegi kortsus sõrmedega ei taha laps vannist välja tulla. Anna talle 5 minutit ette teada ja pane taimer käima. Reegel „tuleme välja, kui kell heliseb“ teeb sageli imesid.'),
('1460be31-c5b7-4f0f-9a6b-7ff5c2085c36'::uuid,'Чач жасалгалоо боюнча таймаш 🪮','Эртең менен чачы электрленип, тик туруп ойгондубу? Таракты көргөн замат кууп жеткис оюн башталабы? Тарагандын ордуна, чачын тегиздөө үчүн колуңузду жана бир аз сууну колдонуп, бул күрөштү токтотуңуз.','Soengu tegemise heitlus 🪮','Kas laps ärkas hommikul püsti seisvate juustega, nagu oleks saanud elektrit? Ja niipea kui ta näeb kammi, algab tagaajamine. Kammimise asemel kasuta käsi ja veidi vett, et juukseid siluda ja võitlus lõpetada.'),
('b4113857-b164-4ab8-b41d-4e516341edad'::uuid,'Жаңы кыймылдарды жасоо! 🤸‍♂️','Ичи менен жатканда колдоруна таянып, айлананы караганга аракет кылып жатат. Булчуңдары күн сайын чыңдалууда – азаматсың, бөбөгүм!','Uute liigutuste proovimine! 🤸‍♂️','Kõhuliolekul lükkab laps end kätega üles ja püüab ringi vaadata. Tema lihased muutuvad iga päevaga tugevamaks – tubli töö, pisike!'),
('37e8bf23-2dc4-4b8c-8c8f-49146922ba57'::uuid,'Сыноо жана ката кетирүү 🧱','Бөбөгүңүз эки оюнчук кубикти бири-биринин үстүнө коюуга аракет кылып жатат, бирок алар кулап түшүүдө. Ал кайрадан кылдаттык менен аракет кылууда. Бул кичинекей инженердик аракеттерди унчукпай байкап, анын өжөрлүгүнө суктаныңыз.','Katse-eksituse meetod 🧱','Sinu pisike püüab kahte klotsi üksteise otsa panna, aga need kukuvad muudkui ümber. Ta proovib hoolikalt uuesti. Jälgi vaikselt neid pisikesi inseneripüüdlusi ja imetle tema järjekindlust.'),
('fc5667d9-2c85-42d4-a92c-e90c3b994a0f'::uuid,'Жасалма интеллекттин кеңеши','Балаңызда өзгөчө адат (мисалы, тырмак тиштөө) пайда болуп, интернеттеги макалалар сизди тынчсыздандырып жатабы? Токтоңуз. Педиатр тарабынан тастыкталган себептерин билүү үчүн Anacan AI''дан сураңыз жана өзүңүздү тынчтандырыңыз.','AI vaatenurk','Kas lapsel on tekkinud kummaline harjumus (nt küünte närimine) ja internetiartiklid on tekitanud sinus ärevust? Peatu hetkeks. Küsi Anacan AI-lt lastearstide poolt kinnitatud põhjuseid ja rahusta oma meelt.'),
('732cb07a-0e5f-4dc9-9d15-78470db05396'::uuid,'Тамак-аш идеялары 🍲','Бир эле тамакты жасай берип тажадыңызбы? 10 айлык бөбөктөр үчүн идеалдуу болгон жаңы жана даамдуу тамактарды биздин ден соолукка пайдалуу рецепттерибизден карап көрүңүз.','Ideed toidukordadeks 🍲','Oled väsinud samade toitude valmistamisest? Sirvi meie tervislikke retsepte, et leida uusi ja maitsvaid näputoidu ideid, mis sobivad ideaalselt 10-kuustele.'),
('ec61705b-0071-49b5-a6b0-3849dfa461ac'::uuid,'Баалуу көз ирмемдерди тартып алуу 📸','Алар ушунчалык тез чоңоюп жатышат... Аларды кооз кийинтип, бул баалуу көз ирмемдерди «Бөбөктөрдүн фотосессиясы» менен түбөлүккө сактап калыңыз.','Väärtuslike hetkede jäädvustamine 📸','Lapsed kasvavad nii uskumatult kiiresti... Pane talle selga armas riietus ja jäädvusta need kallid hetked igaveseks beebi fotosessiooniga.'),
('72b166c9-a8f9-4dc5-be7f-5911ccda18ea'::uuid,'Күн сайын күлкү көбөйүүдө! 😂','Ар бир кызыктуу кыймылыңызга бөбөгүңүз сүйкүмдүү күлкүсү менен жооп берип жатабы? Бул баалуу көз ирмемди видеого тартып алууну унутпаңыз!','Iga päevaga rohkem itsitamist! 😂','Laps vastab igale sinu naljakale liigutusele armsa itsitamisega! Ära unusta seda väärtuslikku hetke videole jäädvustada!'),
('01349acb-919c-490a-bfce-f75e04518130'::uuid,'Дарыгериңиз жардам берүүгө даяр 🩺','Оюнчук стетоскопту алып, көкүрөгүңүзгө коюп, дем алууңузду айтып жатабы? Сиз бейтапсыз, ал болсо башкы дарыгер. Оюнга кошулуп, жатып алыңыз жана «дарылануу» учурунда кеминде 5 мүнөт көзүңүздү жумуп эс алыңыз.','Sinu arst on siin, et aidata 🩺','Kas laps paneb oma mängustetoskoobi sulle rinnale ja käsib hingata? Sina oled patsient ja tema on peaarst. Mängi kaasa, heida pikali ja sule silmad, et „ravi“ ajal vähemalt 5 minutit puhata.'),
('d58d064b-a397-425d-9d57-3f6068e31cf1'::uuid,'Энергиянын агымы','Үйдүн ичинде дубалга чыгып жатышабы? Аба ырайын жана кийимин текшерип, сөзсүз сыртка чыгыңыз! Таза абада отуз мүнөт чуркоо – түнкү уйкунун эң жакшы кепилдиги.','Energiasööst','Kas laps ronib kodus mööda seinu üles? Kontrolli ilma ja riietust ning suundu kindlasti õue! Kolmkümmend minutit värskes õhus jooksmist on parim garantii heaks uneajaks.'),
('968ec1c9-36e5-4127-8374-922149e153dc'::uuid,'Уйкунун негиздери ⏱️','Төртүнчү айдан баштап уйкунун туруктуу тартибин түзүү өтө маанилүү. Баарынын тынч укташы үчүн аны так сактаңыз.','Une vundament ⏱️','Järjepideva unerutiini loomine neljandaks elukuuks on äärmiselt oluline. Järgi seda hoolsalt, et tagada kõigile rahulikud ööd.'),
('a387d51e-9e9d-455a-be61-4650ee6ffa63'::uuid,'Тынч бөлмө, тынч акыл 🤫','Уйкуга даярданып жатканда, бөлмөдөгү ызы-чууну азайтуу зарыл. Үнүңүздү жана айланадагы ызы-чуунун деңгээлин текшерүү үчүн үн өлчөгүчтү колдонуңуз.','Vaikne tuba, rahulik meel 🤫','Uinumiseks valmistudes on oluline vähendada toas mürataset. Kasuta helimõõdikut, et kontrollida oma häält ja ümbritsevat müra.'),
('439ac8e3-ab5f-434a-bb69-d98dee8208cd'::uuid,'Уктоо алдындагы өзгөчө жомок 🪄','Болгону 10 күндө чоңойгон каарман жөнүндө «Акылдуу жомок» түзүп, бөлмөнү сыйкырга толтуруңуз.','Eriline unejutt 🪄','Täida tuba võlujõuga, luues Smart Story kangelasest, kes kasvab suureks vaid 10 päevaga.'),
('d96fbe0f-26f7-4473-9f0b-34109da6a744'::uuid,'Шыбырдын сыйкыры 🌙','Бөлмөдөгү бардык жарыкты өчүрүңүз. Жанына жатып, күндүн окуяларын өтө жай, шыбырап айтып бериңиз. Шыбырап сүйлөө – мээни уйкуга даярдоонун эң табигый жана тынчтандыруучу ыкмасы.','Sosistamise maagia 🌙','Kustuta toas kõik tuled. Heida lapse kõrvale ja sosista talle tasa päeva sündmustest. Sosistamine on kõige loomulikum ja rahustavam viis aju uneks ette valmistada.'),
('ff800946-b6d3-4e88-8699-fe114e37b692'::uuid,'Жылмаюуларды тартып алуу 📸','Бөбөгүңүз күн сайын уникалдуу жана сүйкүмдүү адамга айланууда. «Бөбөктүн сүрөтү» функциябызды ачып, стикерлер менен кооздоп, бул кубанычтуу көз ирмемди түбөлүккө сактап калыңыз.','Naeratuste jäädvustamine 📸','Sinu beebi muutub iga päevaga üha erilisemaks ja armsamaks. Ava meie beebifoto funktsioon, kasuta kleepse ja jäädvusta see rõõmus hetk igaveseks.'),
('1fc309f5-659f-4b2e-bf6f-e17296d830ff'::uuid,'Атасы менен ат чапмай 🐴','Дагы эле энергияга толуп, уктагысы келбей жатабы? Атасы менен үйдө ат минип ойноп, күлкүгө бөлөнүү – бул энергияны сарптоонун эң тез жана кызыктуу жолу. Топ эми атасынын колунда!','Issiga hobusemäng 🐴','Laps on ikka veel energiat täis ega taha magama minna? Isale selga ja mööda maja ratsutamine koos naerupahvakutega on kiireim ja lõbusaim viis energiast vabanemiseks. Pall on isa käes!'),
('16cae145-7589-4ff6-ae2c-368fe115d232'::uuid,'Эмоцияларды башкаруу 📝','Нервиңиз жукарып, жарылып кетчүдөй болуп жатасызбы? Бардык стрессиңизди маанай күндөлүгүңүзгө төгүп, терең дем алыңыз.','Emotsioonide juhtimine 📝','Kas närvid on läbi ja tunned, et kohe plahvatad? Vala kogu oma stress tujupäevikusse ja hinga sügavalt sisse.'),
('9b99e928-dd9a-40d6-9254-12459dac4a3d'::uuid,'Караңгылык менен достошуу 🌙','Бөбөгүңүздүн тез уктап кетишине жардам берүү үчүн, кечки тартипке караңгылыкты киргизиңиз. Бөлмөдөгү керексиз жарыктардын баарын өчүрүңүз.','Pimedusega sõbraks saamine 🌙','Et aitamaks lapsel kiiremini uinuda, muuda õhtune rutiin hämaraks. Kustuta toas kõik mittevajalikud tuled.'),
('ee2e2e79-277e-4a7f-9473-05aa36068880'::uuid,'Дене мүчөлөрүн таануу 👀','«Мурунуң кайда?» деп сураганыңызда, ал сөөмөйү менен көрсөтөбү? Анын таанып-билүү жөндөмү абдан тез өсүп жатат!','Kehaosade tundmaõppimine 👀','Kui küsid: „Kus on nina?“, kas laps näitab näpuga? Tema kognitiivne mõistmine areneb jõudsalt!'),
('69846205-68bb-4476-a7e0-45d4e68fae26'::uuid,'Апанын тынчтыкка болгон муктаждыгы','Ар бир үн нервиңизге тийип жатабы? «Этек кир календарыңызды» текшериңиз. Организмиңиз эс алууну талап кылып жаткан болушу мүмкүн. Биздин пайдалуу рецепттерден магнийге бай тамак даярдап, өзүңүзгө бир аз тынч убакыт бөлүңүз.','Ema vajadus rahu järele','Kas iga heli ajab närvi? Kontrolli oma tsüklikalendrit. Sinu keha võib märku anda, et vajab puhkust. Valmista meie tervislike retseptide järgi magneesiumirikas suupiste ja võta endale veidi vaikset aega.'),
('2cb20f11-aee5-456a-b969-c87733104c72'::uuid,'Жеңиштүү кеч 🥂','Бүгүн кечинде, бөбөгүңүз уктагандан кийин, жолдошуңуз менен бирге отуруп, «Биз эң сонун командабыз!» деп айтыңыз. Экөөңүз тең чындап эле укмуштуудай иш жасап жатасыз!','Võidukas õhtu 🥂','Täna õhtul, kui laps magab, tõstke partneriga klaasid ja öelge: „Oleme suurepärane meeskond!“ Teete mõlemad tõesti imelist tööd!'),
('57b926b9-28cb-4c4e-8863-8ce72241c9fe'::uuid,'Аллергия боюнча маселелер 🤖','Жаңы тамак берип, бөбөгүңүздүн бети кызарганын байкадыңызбы? Дүрбөлөңгө түшөрдөн мурун, Anacan AI''дан алгачкы кадамдарды үйрөнүп алыңыз.','Allergiamured 🤖','Proovisid uut toitu ja märkasid beebi põskedel punetust? Enne kui muretsed, uuri Anacan AI-lt, millised on esimesed sammud.'),
('c6dcd330-d5df-4d87-b7a0-d8ab33a73063'::uuid,'Түшүнүксүз ачуулануулар 😭','Көзүн ачары менен эч себепсиз ыйлап жатабы? Бул каприз эмес, бул эмоционалдык ашыкча чарчоо. Мындай учурларда эмне кылуу керектигин Anacan AI адисибиз менен талкуулап билип алыңыз.','Salapärased nutuhood 😭','Kas laps nutab ilma põhjuseta kohe, kui silmad avab? See pole jonnakus, vaid emotsionaalne ülekoormus. Uuri, kuidas nende hetkedega toime tulla, arutades seda meie Anacan AI eksperdiga.'),
('f8c399ff-a31e-4e77-a55d-5aab198bafaa'::uuid,'Сейилдөөгө убакыт келди! ⛅','Биздин аба ырайы жана кийим тандоо куралыбыз менен бир нече секундда аба ырайына ылайыктуу кийимди тандап, таза абада сейилдөөгө чыгыңыз.','Aeg väljasõiduks! ⛅','Meie ilmastiku- ja riietustööriistaga leiad sekunditega ilmaprognoosile sobivaima riietuse, et saaksid õue minna ja värsket õhku nautida.'),
('fb3d810e-9135-4194-bb47-9ce9e588d70c'::uuid,'Атанын ийини 👨‍👧','Бүгүн кечинде бөбөгүңүздү бөлмөдө терметип, уктатуу милдети толугу менен атасынын мойнунда.','Issi õlad 👨‍👧','Täna õhtul on lapse kussutamine ja röhitama panemine täielikult issi ülesanne.'),
('6ac257ab-47ac-4e61-a9e4-2b538df0a8dc'::uuid,'Атасынын ашканадагы кезеги','Бүгүн түшкү тамакты даярдоо жана баланы тамактандыруу атасынын иши! Ал эми сиз бул убакытты өзүңүзгө арнап, жатып эс алыңыз.','Issi köögitoimetused','Täna on lõunasöögi valmistamine ja lapse toitmine issi töö! Sina aga pühenda see aeg endale ja lihtsalt puhka.'),
('ba525880-dd70-46d8-9c0c-f0fb9b49240c'::uuid,'Жаратылыш үндөрү менен сыйкырдуу уйку 🪄','Классикалык музыка жардам бербей жатабы? «Акылдуу жомоктор» бөлүмүндө баяндоону өчүрүп, жамгырдын же токойдун үнүн коюп көрүңүз. Жаратылыштын бир калыптагы үндөрү балдарды сыйкырдуу түрдө тез уктатат.','Maagiline uni loodushelidega 🪄','Kas klassikaline muusika ei aita? Lülita nutikates lugudes jutustus välja ja vali taustaks vihma- või metsahelid. Monotoonsed loodushääled uinutavad lapsed sageli kui võluväel.'),
('65cb82a7-67e0-48b5-80b8-74e806b2980e'::uuid,'Сиздин өзгөчө окуяңыз 🪄','Бүгүн кечинде «Акылдуу жомоктор» бөлүмүнө кирип, бөбөгүңүз үчүн атайын жекелештирилген жомок түзүп окуп бериңиз.','Sinu enda eriline lugu 🪄','Täna õhtul sukeldu nutikatesse lugudesse ja loo eriline, isikupärastatud muinasjutt, mida talle ette lugeda.'),
('9c11d140-acfd-48e4-9fef-141a9e34586d'::uuid,'«Өзүм жейм» деген этап 🥦','Бөбөгүңүз колуңуздагы кашыкты алгысы келип жатабы? Берүүдөн тартынбаңыз! Бир аз чачылышы мүмкүн, бирок бул өз алдынчалык анын өнүгүүсү үчүн абдан маанилүү.','„Söön ise“ faas 🥦','Sinu väike soovib lusikat käest võtta. Luba seda! See võib küll segadust tekitada, kuid iseseisvustunne on lapse arengu jaoks ülioluline.'),
('7fd53d22-26ef-4c4c-83bb-d44647b94560'::uuid,'Келиңиз, чогуу чечели 💬','«Эмне үчүн балам мындай кылып жатат?» деп суроодон чарчадыңызбы? Anacan коомчулугуна кошулуңуз жана миңдеген башка үй-бүлөлөр да дал ушундай абалды баштан кечирип жатканын билип алыңыз!','Mõtleme koos välja 💬','Oled väsinud küsimast: „Miks mu laps nii teeb?“ Liitu Anacani kogukonnaga ja avasta, et tuhanded teised pered kogevad täpselt sama!'),
('ba82984e-ccd6-40f9-b991-bf586ff48b9d'::uuid,'Чоңдордун нааразычылыгы 😔','Диванга отуруп алып, чоң кишилердей терең дем алып, үшкүрүнүп жатабы? Ал сизди так туурап жатат! Анын бул кызыктуу жоруктарын жылмаюу менен гана байкаңыз.','Täiskasvanute nurin 😔','Istub diivanil, hingab äkki sügavalt ja ohkab nagu täiskasvanu? Ta ahvib sind suurepäraselt järele! Naudi tema dramaatilist esitust naeratusega.'),
('09081d67-84a7-403e-b876-3cc97106eb52'::uuid,'Кармаганды үйрөнүү! 🧸','Ал азыр асылып турган оюнчуктарды так кармай алабы? Анын кыймыл-аракет жөндөмү сонун өнүгүп жатат! Анын аракеттерин сүйүү менен карап, дайыма колдоп туруңуз.','Haaramise õppimine! 🧸','Kas ta suudab nüüd rippuvaid mänguasju täpselt haarata? Tema motoorika areneb imeliselt! Jälgi tema pingutusi armastusega ja julgusta teda edasi.'),
('a6ef3f7c-7550-4712-8fc9-23c742a51744'::uuid,'Уйкуга өтүү: Жуунуу убактысы 🛀','Жылуу ванна ар дайым жардам берет. Кечки тартипти эч качан калтырбаңыз, анткени ал бөбөгүңүздүн мээсине уктоо убактысы келгенин билдирет.','Üleminek uneajale: vanniskäik 🛀','Soe vann aitab alati. Ära kunagi jäta õhtust rutiini vahele, sest see annab beebi ajule märku, et on aeg magama minna.'),
('d6154f3b-6df3-4af3-97e7-fdfd798b8cfb'::uuid,'Жыгылып, кайра туруу менен үйрөнүү 🧗‍♂️','Ал туруп, кайра отуруп, күлүп, кайра турат. Бул кичинекей жыгылуулар булчуң эс тутумун калыптандырат; ага көп кийлигишпегенге аракет кылыңыз.','Õppimine kukkudes ja uuesti tõustes 🧗‍♂️','Ta tõuseb püsti, kukub istuli, naerab ja tõuseb uuesti. Need väikesed kukkumised arendavad lihasmälu; püüa mitte liialt sekkuda.'),
('2521dffb-415b-4bec-81f4-b18ee93644d8'::uuid,'Уктоо үчүн караңгылыкка көнүү 🌙','Анын тез уктап кетиши үчүн, бөлмөдөгү ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин гормону тынч жана караңгы чөйрөдө гана тез иштелип чыгат.','Pimedusega harjumine magamiseks 🌙','Et aidata lapsel kiiremini uinuda, kustuta toas kõik lisatuled ja pane tahvelarvutid kinni. Melatoniini tootmine kiireneb vaid rahulikus ja pimedas keskkonnas.'),
('25903ac8-0fd6-44f0-92d8-c3e1bee035e5'::uuid,'Тынчтыкка болгон муктаждык 🤫','Ал уктап баратканда кичинекей эле чырылдоо аны ойготуп жатабы? Үн өлчөгүч менен чөйрөнү талдап, үзгүлтүксүз тынчтыкты камсыз кылыңыз.','Vaikuse vajadus 🤫','Kas pisike krõbin äratab lapse just siis, kui ta on uinumas? Analüüsi keskkonda helimõõtjaga ja taga katkematu vaikus.'),
('3a5c700f-e10c-4819-bba1-cddd9f951f4f'::uuid,'Тизмелер жана апанын унутчаактыгы 🛒','«Энелик унутуу» сезими дагы эле барбы? Үйдөгү майда-чүйдө иштерди ойлоп өзүңүздү кыйнабаңыз. Аларды дароо «Соода тизмесине» кошуп, жолдошуңузга тапшырыңыз.','Nimekirjad ja emme aju 🛒','Kas emme-aju on endiselt uimane? Ära koorma end väikeste koduste toimetuste peale mõtlemisega. Lisa need kohe ostunimekirja ja lase partneril nende eest hoolitseda.'),
('47b342b1-9525-44b6-b917-2eb642240cb2'::uuid,'«Сени жакшы көрөм» деген кучактоо 🫂','Ал күтүлбөгөн жерден келип мойнуңузду кучактап же бетиңизден сылап жатабы? Ал азыр өзүнүн сүйүүсүн физикалык түрдө көрсөтүп жатат. Бул сонун көз ирмемдерди баалаңыз!','„Armastan sind“ kallistus 🫂','Kas ta tuleb äkki sind kallistama või silitab su nägu? Ta väljendab nüüd füüsiliselt oma kiindumust. Hinda neid kauneid hetki!'),
('09817e37-4e65-43f6-968c-dd333358e01e'::uuid,'Бүтпөгөн соода тизмеси 🛒','Күндөлүк түйшүктүн арасында шампунь же памперс түгөнүп калдыбы? Баарын эстеп калууга аракет кылбаңыз – аны «Соода тизмесине» кошуп, жолдошуңуз менен синхрондоштуруңуз.','Lõputu ostunimekiri 🛒','Kas igapäevases saginas said šampoon või mähkmed otsa? Ära püüa kõike meeles pidada – lisa need ostunimekirja ja sünkrooni see partneriga.'),
('1f244347-1957-4238-988d-4563adba7bcd'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Күндүзгү чарчооңуз жетиштүү болду. Кечинде баланы уктоого даярдоо жана жомок окуп берүү толугу менен атасынын милдети.','Issi öövahetus 👨‍🍼','Oled päevasest väsimusest küllalt saanud. Õhtul on beebi magamaminekuks ettevalmistamine ja unejutu lugemine ainult issi töö.'),
('9f618083-9332-44d7-8a8f-8ad3af6c22ac'::uuid,'Баары оюнчук! 🥄','Пластмасса идиштер жана жыгач кашыктар ал үчүн эң кымбат оюнчуктан да кызыктуу. Коюңуз, ашкана буюмдарын эркин изилдесин.','Kõik on mänguasi! 🥄','Plastkarbid ja puulusikad on tema jaoks huvitavamad kui kõige kallim mänguasi. Lase tal köögitarbeid vabalt avastada.'),
('354e039c-3978-4aa3-a008-1a3a7bbe85a3'::uuid,'Колдоо үчүн ыйды анализдөө 😭','Түн ортосунда ойгонуп, ыйлаганын токтотпой жатабы? Божомолдобой, «Ыйды талдоо» куралын колдонуп, себебин дароо аныктаңыз.','Nutuanalüüs toetuseks 😭','Ärkab keset ööd ja ei jää vait? Lõpeta oletamine ja kasuta nutianalüüsi, et põhjus kohe välja selgitada.'),
('8fb53566-815d-4365-b87c-c14288ebb122'::uuid,'Таза аба — жашоо булагы 🌳','Эгер үйдө ыйлоо башталып жатса, аба ырайын жана кийимди текшерип, баланы коляскага салып, түз эле сейил бакка барыңыз. Жаратылыш — аны тынчтандыруунун эң тез жолу.','Värske õhk on päästja 🌳','Kui kodus on tuju paha, vaata ilma ja riietust, pane laps vankrisse ja suundu otse parki. Loodus on kiireim viis teda rahustada.'),
('c87df5f1-fbe2-4462-a617-a6649445ce77'::uuid,'Кыялынын эң жогорку чеги ☁️','Бөбөгүңүз баарына каприз кылып, тынбай ыйлап жатабы? Бул өсүү мезгили же тиш жаруудагы ыңгайсыздык болушу мүмкүн. Жөн гана аны көп кучактап, мээримиңизди төгүңүз.','Jonnihoog haripunktis ☁️','Kas su väike põnn on kõige peale tusane ja nutab lakkamatult? See võib olla kasvuhüpe või hammaste tulek. Lihtsalt kaisuta teda palju.'),
('361e96e8-a6ed-4fdf-a7bb-50e07abcec66'::uuid,'Түндүн тынчтыгы 🪄','Баатыр жана сүйкүмдүү жаныбарлар жөнүндө «Акылдуу жомок» түзүп, бөлмөнү сыйкырдуу жомок дүйнөсүнө айлантыңыз.','Öörahu 🪄','Loo nutikas lugu vapratest ja armsatest loomadest, muutes toa maagiliseks imedemaaks.'),
('a4baaa67-c9fb-4208-aab7-e7515b21f64f'::uuid,'Сиз аны тойгузуу үчүн баарын кыласыз. Ал эми өзүңүзчү?','Энергияңызды толуктаңыз! Биздин пайдалуу рецепттер бөлүмүнөн темирге жана белокко бай эртең мененки тамакты тандаңыз.','Teed kõik, et last toita. Aga kuidas on lood sinuga?','Turguta oma energiat! Vali meie tervislike retseptide sektsioonist raua- ja valgurikas hommikusöök.'),
('c58c8b30-4c95-4f60-98d7-d9580eb48a38'::uuid,'Китептин барактарын ачуу 📖','Ал жоон барактуу китептердин беттерин өз алдынча оодарып жатабы? Бул майда моторикадагы жетишкендикти «Өнүгүү күндөлүгүңүзгө» жазып коюуну унутпаңыз!','Raamatulehtede keeramine 📖','Kas ta keerab juba ise paksude lehtedega raamatute lehti? Ära unusta seda peenmotoorika verstaposti oma arengupäevikusse märkida!'),
('2631ed9f-967a-4f12-9097-1f619f7f1e5f'::uuid,'Бүгүнкү күн пландалгандай болбой калдыбы?','Бөбөгүңүз уктап калганда өзүңүздү күнөөлүү сезбеңиз. Сиз чыныгы энесиз жана баарын эң сонун жасап жатасыз!','Kas tänane päev ei läinud plaanipäraselt?','Ära tunne süümepiinu, kui su laps lõpuks magab. Oled suurepärane ema ja teed kõike õigesti!'),
('34415812-3e31-43f2-99de-a1dd76bb1d9e'::uuid,'Максаттуу ыргытуулар ⚾','Ал оюнчукту атайылап белгилүү бир бутага ыргытууга аракет кылып жатат. Анын кол менен көздүн координациясы тез өнүгүп жатат!','Sihipärased visked ⚾','Ta üritab sihikindlalt mänguasja kindla sihtmärgi pihta visata. Tema käe-silma koordinatsioon areneb kiiresti!'),
('ec7ed8d1-bb0f-4b34-a7a5-da3857dfd5d4'::uuid,'Педиатр менен тез суроо-жооп 🤖','11 айлык баланын күндүзгү уйкусу канча убакыт болушу керек? Каалаган суроолоруңузду Anacan AI''дан дароо сурап, көңүлүңүздү тынчтандырыңыз.','Kiired lastearsti nõuanded 🤖','Kui pikk peaks olema 11-kuuse lapse päevane uinak? Küsi Anacan AI-lt kõike, mis südamel, ja saa murest lahti.'),
('78c638dd-68ed-4cf9-acf9-6738b0e5ec7f'::uuid,'Үйдөгү коркунучтарды аныктоо ⚡','Бөбөгүңүз чоңоюп, мурда жетпеген текчелерге жете баштады. Үйүңүздүн коопсуздугун (курч бурчтар, оор буюмдар) кайрадан карап чыгууга убакыт келди.','Koduste ohtude märkamine ⚡','Sinu väike ime on pikemaks kasvanud ja ulatub nüüd riiuliteni, kuhu varem ei küündinud. On aeg kodu turvalisus üle vaadata (teravad nurgad, rasked esemed).'),
('8a4a7da2-606f-4fbb-8668-101f2d47c03c'::uuid,'Музыканын күчү 🎶','Кечки «каприз» убагында аны жай классикалык музыка менен тынчтандырууга аракет кылыңыз. Көбүнчө бул жөнөкөй ыкма кереметтерди жаратат.','Muusika vägi 🎶','Proovi õhtust rahutust leevendada õrna klassikalise muusikaga. Tihti teeb see lihtne nipp imesid.'),
('0387bc9b-1c64-4eae-ac49-660cb56552f8'::uuid,'Өз оюнчуктарын табуу 🧸','Сиз көз алдынан алып салган оюнчукту ал издеп таап жатабы? Ал «объекттин туруктуулугу» түшүнүгүн толугу менен өздөштүрүп жатат!','Oma mänguasjade leidmine 🧸','Kas ta leiab üles mänguasja, mille sa silma alt ära peitsid? Ta on täielikult mõistnud esemete püsivuse kontseptsiooni!'),
('6b5c2e80-bfa3-452b-805d-82d54c6b5d2d'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкү ойгонуулардын баарын жалгыз өзүңүз көтөрбөңүз. Жолдошуңузду да ойготуңуз; команда болуу — бул жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi öövahetus 👨‍🍼','Ära kanna kõiki öiseid ärkamisi üksi. Ärata ka oma partner; meeskonnana tegutsemine tähendab kohustuste võrdset jagamist.'),
('89a2b668-b451-4cfe-a183-3183fc159297'::uuid,'Сезимдериңизди билдириңиз 📝','Бөбөгүңүз бир жашка чыгып баратканда, анын ушунчалык тез чоңойгонуна карата бир кызыктай кайгыруу же сагыныч сезип жатасызбы? Бул сезимдерди «Маанай күндөлүгүңүзгө» жазып алыңыз.','Väljenda oma tundeid 📝','Kas tunned lapse esimese sünnipäeva lähenedes kummalist kurbust ja imestust, kui kiiresti ta on kasvanud? Jäädvusta need tunded oma meeleolupäevikusse.'),
('d24d332c-e00e-4b7f-8dac-28439e172c26'::uuid,'Апанын кофе тыныгуусу ☕','Бөлмөдөгү баш аламандык эч жакка качпайт, бирок энергияңыз тез түгөнүшү мүмкүн. Балаңыз өз алдынча ойноп жатканда, дароо үй иштерине киришпеңиз. Отуруп, кофеңизден ырахат алыңыз.','Emme kohvipaus ☕','Toas valitsev segadus ei kao kuhugi, aga sinu energia võib kiiresti otsa saada. Kui laps mängib omaette, ära torma kohe koristama. Istu hoopis maha ja naudi kohvi.'),
('8c48dfb8-f3cc-4402-82d4-4c81ed9fc15b'::uuid,'Эне сүтү дагы деле маанилүү! 🍼','Эне сүтү бала бир жашка чыкканга чейин абдан маанилүү. Күнүмдүк сүт муктаждыгын камсыз кылуу үчүн тамактандыруу таймерин колдонуңуз.','Rinnapiim on endiselt hädavajalik! 🍼','Rinnapiim on lapse esimese eluaastani ülioluline. Kasuta toitmise taimerit, et tagada tema igapäevane piimavajadus.'),
('23c2a94e-cf0d-4f81-9604-79b4dcfb2460'::uuid,'Таза абадан дем алуу ⛅','Үйдө отуруп тажадыңызбы? Аба ырайын жана кийимди текшерип, бөбөгүңүзгө сейил бактагы чөптөрдү жана жалбырактарды эркин изилдөөгө мүмкүнчүлүк бериңиз.','Sõõm värsket õhku ⛅','Tunned end kodus kinni? Kontrolli ilma ja riietust, seejärel lase oma väikesel uurijal vabalt tegutseda, katsudes pargis rohtu ja lehti.'),
('77a8c135-4a26-4877-9f24-fc51c941fb7a'::uuid,'Кийинүүгө жардам берүү 👕','Кийиндирип жатканда, ал өз алдынча колун сунуп же бутун көтөрүп жатабы? Ал сиз менен активдүү кызматташып жатат! Бул сүйкүмдүү жардамчы учурду «Өнүгүү күндөлүгүңүзгө» белгилеп коюңуз.','Riietumisel abistamine 👕','Kas ta sirutab riietumisel ise käsi või tõstab jalgu? Ta teeb sinuga aktiivselt koostööd! Märgi see armas abistamishetk oma arengupäevikusse.'),
('9df28291-b590-4e7d-a861-feb0732398b2'::uuid,'Караңгылык менен достошуу 🌙','Анын тез уктап кетишине жардам берүү үчүн, кечки тартипке караңгылыкты киргизиңиз. Бөлмөдөгү ашыкча жарыктардын баарын өчүрүңүз.','Pimedusega sõbraks saamine 🌙','Et aidata tal kiiremini uinuda, muuda õhtune rutiin hämaraks. Lülita toas kõik liigsed tuled välja.'),
('72f5aeb4-94f9-40bc-943e-fa87664da32b'::uuid,'Форумга кошулуңуз 🤖','Балаңыздын кыймылында адаттан тыш нерсе байкадыңызбы? Интернеттен сааттап издебеңиз; түздөн-түз Anacan AI''дан сурап, көңүлүңүздү тынчтандырыңыз.','Sukeldu foorumisse 🤖','Märkad lapse liigutustes midagi ebatavalist? Ära raiska tunde internetis otsimisele; küsi otse Anacan AI-lt ja rahusta oma meeled.'),
('c8b05bf8-0ed8-4eec-86f7-4cba168167e1'::uuid,'Сөздөрдү түшүнүү 🗣️','«Топту алып кел» дегениңизде, ал чын эле издеп барабы? Анын түшүнгөн сөздөрүнүн запасы тез кеңейүүдө. Аны менен татаалыраак сүйлөмдөрдү колдонуп баарлашыңыз!','Sõnade mõistmine 🗣️','Kui ütled „too pall“, kas ta läheb ja otsib selle üles? Tema passiivne sõnavara (sõnad, millest ta aru saab) laieneb kiiresti. Suhtle temaga keerukamate lausetega!'),
('f8aae6d9-1b70-4333-a55c-1937c871c533'::uuid,'Акылдуу жомок убактысы 🪄','«Акылдуу жомоктор» бөлүмүндө бир айдан кийин бир жашка чыга турган баатыр тууралуу жомок түзүңүз. Түнкү тынчтыкты ушул жомок гана бузсун.','Arukas muinasjutt 🪄','Loo „Nutikates lugudes“ muinasjutt kangelasest, kes tähistab kuu aja pärast oma esimest sünnipäeva. Las vaid see lugu murrab öise vaikuse.'),
('0ca61e8f-0ab9-48ea-85e7-af32b2be41a1'::uuid,'Биринчи туулган күнгө керектүү нерселер: жасалгалар жана шарлар 🛒','Көп ойлонбоңуз! Соода тизмеңизди азыртан даярдай баштаңыз.','Esimese sünnipäeva peo põhitõed: kaunistused ja õhupallid 🛒','Ära mõtle üle! Alusta ostunimekirja koostamisega juba praegu.'),
('519cad33-f5e8-4169-8f1d-93f4343568db'::uuid,'Тынымсыз аракеттер 🧗‍♂️','Ал оюнчукту кармап туруп, эмеректерге таянып турууга аракет кылып жатат. Анын тең салмактуулук жөндөмү укмуштуудай бекемделди! Ага кийлигишпей, алыстан байкап туруңуз.','Visad katsed 🧗‍♂️','Ta üritab mänguasja hoides mööbli najal püsti tõusta. Tema tasakaal on uskumatult tugevnenud! Jälgi teda eemalt sekkumata.'),
('aa2fb7c9-acf7-4050-9102-4f2927091b95'::uuid,'Үнсүз баатыр 🤫','Ал уктап калган учурда, үйдөгү ар бир үн жарылуудай сезилет. Үн өлчөгүч менен бөлмөнүн ызы-чуу чегин белгилеп жатып, өзүңүздүн да кадамдарыңызды жеңилдетиңиз!','Vaikne kangelane 🤫','Hetkel, mil laps uinub, tundub iga heli majas plahvatusena. Samal ajal kui seadistad mürataseme mõõtjaga toa piiranguid, liigu ka ise vaiksemalt!'),
('9cba5d69-92c6-472c-bb83-c5522d806018'::uuid,'Апалардын сырдаштары 💬','«Туулган күндү кантип пландаштырам?» деген ой сизди тынчсыздандырып жатабы? Anacan коомчулугуна кайрылыңыз жана башка энелерден чыгармачыл, чөнтөккө ыңгайлуу идеяларды алыңыз.','Emmede usaldusisikud 💬','Kas mõte „Kuidas ma sünnipäevapeo planeerin?“ tekitab sinus stressi? Pöördu Anacani kogukonna poole ja saa teistelt emadelt loomingulisi ning eelarvesõbralikke ideid.'),
('f558e782-e140-4835-8b11-1d5f01a717bf'::uuid,'Көз ирмемди сактап калуу 📸','Алар күн сайын кичинекей балага көбүрөөк окшошуп баратат! «Ымыркайдын фотосессиясы» функциясын дароо ачып, бул табигый бий учурун түбөлүккө сактап калыңыз.','Hetke jäädvustamine 📸','Nad näevad iga päevaga üha enam välja nagu väikesed lapsed! Ava kohe funktsioon „Beebi fotosessioon“ ja jäädvusta see siiras tantsuhetk igaveseks.'),
('f56842a9-3a83-4016-8e93-a096810c45d3'::uuid,'Бий жана ритмдер 🎶','Телевизордон же телефонуңуздан ритмдүү үндү угары менен бийлей башташабы? Алардын музыкалык кабыл алуусу толук иштеп жатат – аларга кошулуп, чогуу бийлеңиз!','Tants ja rütmid 🎶','Kas nad hakkavad tantsima kohe, kui kuulevad telerist või telefonist rütmilist heli? Nende muusikataju on täielikult arenenud – ühine nendega ja tantsi kaasa!'),
('357cf8f4-8f26-47ee-9a7b-b3db1bd2898e'::uuid,'Дени сак апа, дени сак бала 🥑','Сиздин темир жана кальций запастарыңыз азайып калышы мүмкүн. Биздин дени сак рецепттерден энергия берүүчү, тез даярдалуучу салат жасап алыңыз, ал сизге сергек болууга жардам берет.','Terve ema, terve laps 🥑','Sinu raua- ja kaltsiumivarud võivad olla ammendunud. Valmista meie tervislike retseptide järgi energiat andev ja kiirelt valmiv salat, mis aitab sul jalul püsida.'),
('7883fd83-494d-41a3-b42d-58d452de13d7'::uuid,'Атанын шайыр мүнөзү 🤡','Сыртка чыккыңыз келеби, бирок шамал болуп жатабы? Биздин «Аба ырайы жана кийим тандоо» жардамчыбыз сизге температураны гана эмес, кичинекейиңизге шамалга туруктуу кандай кийим кийгизүү керектигин да айтып берет.','Issi mänguline pool 🤡','Parim viis beebit naerma ajada on lasta issil teha naljakaid hääli! Nautige neid rõõmsaid õhtuseid hetki koos oma pisikesega.'),
('981d8d60-ab26-4f64-a20b-eee1dc2fed12'::uuid,'Майдаланган тамактарга толук өтүү! 🍲','Кичинекейиңиз эми чайноону талап кылган тамактарды жей алат! Биздин тиркеменин «Ымыркайлар үчүн катуу тамактар» бөлүмүндөгү рецепттер менен жаңы даамдарды изилдеңиз.','Täielik üleminek tükilisele toidule! 🍲','Sinu pisike saab nüüd süüa toite, mida tuleb närida! Avasta uusi tekstuure meie äpi jaotise „Tahke toit beebidele“ retseptidega.'),
('74f02405-1cdd-401e-bb47-01d87997f231'::uuid,'Өз алдынча ойноо убактысы 🧸','Балаңыз эми 10-15 мүнөт оюнчуктар менен өзүн алаксыта алат! Бул алардын көңүл буруу жөндөмүнүн өнүгүп жатканынын сонун белгиси. Алыстан көз салып, тынчтыктан ырахат алыңыз.','Iseseisev mänguaeg 🧸','Sinu laps suudab nüüd 10–15 minutit mänguasjadega ise mängida! See on suurepärane märk nende arenevast keskendumisvõimest. Jälgi teda eemalt ja naudi hetke rahu.'),
('e8181dea-ccff-4ba2-ae33-93fa07ea8c28'::uuid,'Сурооңуз барбы? 🤖','Уйку, тамактануу же ичтин көбүшү боюнча суроолордон чарчадыңызбы? Чексиз форумдарды издөөнү токтотуп, жөн гана Anacan AI''дан так жана илимий негизделген жоопторду сураңыз.','Kas sul on küsimus? 🤖','Kas tunned end une, toitmise või gaasivaludega seotud küsimuste tõttu ülekoormatuna? Jäta lõputud foorumites tuhnimised vahele ja küsi lihtsalt Anacan AI-lt selgeid, teaduslikult põhjendatud vastuseid.'),
('8d91b32b-a0f2-4a07-a181-da0b746268bc'::uuid,'Паркпы же үйбү? ⛅','Сыртка чыккыңыз келип, бирок шамал болуп жатабы? Биздин Аба ырайы жана Кийим тандоо жардамчыбыз сизге температураны гана эмес, наристеңизге шамалга туруктуу кандай кийим кийгизүү керектигин да айтып берет.','Park või kodu? ⛅','Tahad õue minna, aga on tuuline? Lase meie ilma- ja riietusabilisel öelda mitte ainult temperatuur, vaid ka see, milliseid tuulekindlaid riideid oma pisikesele selga panna.'),
('9890a3bf-dcd7-4d43-8ef7-e98ca087bf8e'::uuid,'Оор түндөр 🥱','Алар уйкуга каршылык көрсөтүп жатышабы? Күндүзгү уйкусун жана жалпы тартибин кайра карап чыгыңыз.','Väljakutseid pakkuvad ööd 🥱','Kas nad tõrguvad unest kogu jõust? Vaata üle nende päevased uinakud ja üldine päevakava.'),
('8ca17d8b-45e4-4184-b598-9b59778d5b0c'::uuid,'Апанын күч-кубат алуу убактысы','Алар тынч эле өз алдынча пазл чогултуп жатышат, 10 мүнөттөн бери үн жок! Сиз бул баалуу убакытты үйдү жыйноого жумшайын деп жатасызбы? Жок! Диванга жатыңыз. Кечти өткөрүү үчүн сизге энергияңызды калыбына келтирүү керек!','Emme taastumisaeg','Nad mängivad vaikselt omaette puslega ja juba 10 minutit on olnud täielik vaikus! Ja sina mõtled, et kasutaksid seda väärtuslikku hetke kodu koristamiseks? Ei! Mine heida diivanile pikali. Sinu aku vajab laadimist, et õhtuni vastu pidada!'),
('395ddd9b-9009-4fec-ba6f-816d156ad432'::uuid,'Кичинекей денедеги чоң сезимдер 🛑','Балаңыз өзү каалаган нерсе болбой калганда ыйлап же кыяңкылык кылып жатабы? Ал азырынча чоң сезимдерин башкарууну үйрөнүп жатат. Анын деңгээлине чейин чөгөлөп отуруп, бул кыйын учурду жеңүүгө жардам берүү үчүн жай сүйлөшүңүз.','Suured tunded, väike keha 🛑','Kas su laps viskab jonni või nutab, kui ta ei saa oma tahtmist? Ta alles õpib oma suuri emotsioone valitsema. Põlvita tema tasemele ja räägi rahulikult, et aidata tal nendest tujudest üle saada.'),
('d824145b-4905-49d1-9f4f-46ade8a730f8'::uuid,'Түндө күтүүсүз ыйлайбы? 😭','Бул түнкү коркуу сезими болушу мүмкүн. Көйгөй физикалыкпы же психологиялыкпы экенин аныктоо үчүн ''Ыйды талдоо'' функциясын колдонуп, балаңыздын ыйын угуп көрүңүз.','Äkiline nutt öösel? 😭','See võib olla uneärevus. Kuula nende nuttu „Nutuanalüüsi“ abil, et teha kindlaks, kas probleem on füüsiline või psühholoogiline.'),
('a7923459-9b74-4330-949d-00e94d185768'::uuid,'«Жок» деп айтуунун күчү 🛑','Кичинекейиңиз туура эмес иш кылганда сиздин реакцияңызды карап жатабы? Тарбиялоонун алгачкы кадамдары тууралуу Anacan AI менен кеңешиңиз.','„Ei“ ütlemise vägi 🛑','Kas su pisike jälgib juba sinu reaktsiooni, kui ta teeb midagi, mida ei tohiks? Konsulteeri Anacan AI-ga distsipliini esimeste sammude osas.'),
('ec1173c9-8c5f-4b55-8ebd-5fdf69b08da1'::uuid,'Укалоо убактысы 💆‍♂️','Бала уктагандан кийин, күндүн чарчоосун басуу үчүн өнөктөшүңүз менен ийинге массаж жасоо сеансын уюштуруңуз. Сиздер бир командасыздар!','Massaaži aeg 💆‍♂️','Pärast beebi uinumist korralda koos partneriga õlamassaaž, et päeva väsimusest vabaneda. Te olete meeskond!'),
('510bccc7-40fa-4c0b-8d0b-8a3105fd00ea'::uuid,'Үйдөгү коопсуздук чаралары! 🛡','Кичинекейиңиз эркин кыймылдай баштаганда, коркунучтар да көбөйөт. Эшик кулпулары жана тепкич тосмолору үчүн биздин Сунушталган өнүмдөр тизмесин текшерип көрүңүз.','Kodu turvalisuse meetmed! 🛡','Kui su pisike hakkab vabalt liikuma, suurenevad ka võimalikud ohud. Kontrolli kindlasti meie soovitatud toodete nimekirja, kust leiad turvaväravad ja kapiukselukud.'),
('959729c5-8ab6-4053-99ca-82aa5fdabc7e'::uuid,'Атасы менен биргеликте кам көрүү 👨‍🍼','Кечки тамактан кийин китеп окуу жана уктоо милдеттерин атасына өткөрүп берип, өзүңүз бир аз уктап алыңыз.','Jagatud hool issiga 👨‍🍼','Pärast õhtust toitmist anna raamatu lugemine ja magamapanek issi hooleks ning tee ise üks kiire uinak.'),
('a478b2eb-eaec-4b54-813a-6f2ba55a5d14'::uuid,'Сөөмөйү менен көрсөтүү! ☝','''Бул эмне?'' деп сурагандын ордуна, кичинекейиңиз баарына манжасы менен көрсөтүп жатабы? Бул кызыктуу учурду түбөлүккө сактап калуу үчүн Ымыркай альбомуна сүрөтүн кошуңуз.','Nimetissõrmega näitamine! ☝','Küsimuse „Mis see on?“ asemel näitab su pisike kõigele näpuga! Jäädvusta see uudishimulik etapp igaveseks beebialbumisse.'),
('97023662-0ba2-4bcd-aff7-bc7adf5883ba'::uuid,'Үндү көзөмөлдөө 🤫','Бала уктап кеткенден кийинки алгачкы жарым саат — эң сезимтал учур. Үн өлчөгүч менен чөйрөнү текшерип, күтүүсүз чыккан үндөрдөн сак болуңуз.','Helikontroll 🤫','Esimene pooltund pärast uinumist on kõige tundlikum aeg. Kontrolli keskkonda helitaseme mõõtjaga ja ole ettevaatlik äkiliste helide suhtes.'),
('d02f135b-16bc-4fa9-978f-0e7d992c1ba4'::uuid,'Үй жыйнообу же эс алуубу? 🛋️','Балаңыз уктап жатканда идиш жууганга шашпаңыз. Диванга жатып, көзүңүздү жумуп, 15 мүнөт жөн гана эс алыңыз.','Koristada või puhata? 🛋️','Kui beebi magab, ära torma nõudepesumasina juurde. Heida diivanile, pane silmad kinni ja lihtsalt hinga 15 minutit.'),
('f12c7751-b89f-4d12-a843-8e331c338393'::uuid,'Кубиктерден сепил куруу! 🧱','Балаңыз эки-үч оюнчук кубикти бири-биринин үстүнө коюуга аракет кылып жатабы? Унчукпай байкап туруңуз жана анын бул алгачкы инженердик аракетин колдоп коюңуз.','Klotsidest lossi ehitamine! 🧱','Sinu laps üritab laduda kahte või kolme klotsi! Jälgi vaikselt ja plaksuta nende esimestele insenerikatsetustele.'),
('35ab2e31-1937-4e58-b764-83729c6e330a'::uuid,'Дене тили менен жооп берүү 🗣️','''Кеттикпи?'' дегениңизде колун сунуп же башын чайкап ''жок'' деп жатабы? Анын түшүнүү жөндөмү чындап эле өнүгүп жатат!','Kehakeelega vastamine 🗣️','Kui ütled „Lähme?“, tõstavad nad käed või raputavad pead „ei“. Nende mõistmisoskus on tõeliselt õide puhkenud!'),
('65a36f4e-0f24-45fe-a038-a2e61c778c81'::uuid,'Өзүңүздү баалаңыз 👏','Үйдүн чачыранды болгонуна эмес, кичинекейиңиздин бүгүн канчалык бактылуу экенине көңүл буруңуз. Сиз эч кандай китеп үйрөтө албаган эң сонун энесиз.','Hinda ennast 👏','Ära keskendu segadusele toas, vaid sellele, kui õnnelik su pisike täna on. Sa oled imeline ema, rohkem kui ükski raamat suudaks õpetada.'),
('7b75b0ec-d253-4e5a-bfac-9ff801269b5f'::uuid,'Бүгүнкү сыйкырдуу жомок 🪄','''Акылдуу жомоктор'' бөлүмүндө балаңыз башкы каарман болгон өзгөчө жомок түзүңүз: биринчи туулган күнүнө даярданып жаткан кичинекей арстан жөнүндө.','Tänane maagiline lugu 🪄','Loo „Nutikates lugudes“ eriline muinasjutt, kus su laps on kangelane: väike lõvi, kes valmistub oma esimeseks sünnipäevaks.'),
('01302c3b-60e6-4b0a-8a88-e63349585527'::uuid,'Биринчи туулган күн коркунучтарыбы? 💬','''Балам али баса элек, кечигип жатабы?'' деген сыяктуу суроолор сизди тынчсыздандырып жатабы? Anacan коомчулугуна жазыңыз. Ар бир бала өзүнүн темпи менен өсөрүн жана сиз жалгыз эмес экениңизди көрөсүз.','Hirmud seoses esimese sünnipäevaga? 💬','Kas küsimused nagu „Mu laps ei kõnni veel, kas ta on arengus maas?“ vaevavad sind? Postita Anacani kogukonda. Näed, et iga laps areneb omas tempos ja sa pole üksi.'),
('51d3f88a-4baa-4ed5-b62c-e84a750f8166'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкү ойгонуулардын баарын жалгыз өзүңүз көтөрбөңүз. Жолдошуңузду да ойготуңуз; команда болуу — бул жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi öövahetus 👨‍🍼','Ära kanna kõiki öiseid ärkamisi üksi. Ärata ka oma partner; meeskonnana tegutsemine tähendab kohustuste võrdset jagamist.'),
('984d2a76-5fec-4059-86ef-85671516c9b6'::uuid,'Аба ырайын текшерүү ⛅','Сырттагы аба ырайы түшүнүксүзбү? ''Аба ырайы жана кийим'' куралы аркылуу шамалдын ылдамдыгын жана эң ылайыктуу кийим тандоону заматта билип алыңыз.','Ilmateade ⛅','Ilm väljas pole päris selge? Lase ilma- ja riietustööriistal koheselt öelda tuule kiirus ja täiuslik riietuse kombinatsioon.'),
('063ccb8e-7bd6-43e4-9c41-f30c172e10a7'::uuid,'Дени сак апа, дени сак бала 🥑','Сиздин темир жана кальций запастарыңыз азайып калышы мүмкүн. Күч-кубат алуу үчүн биздин пайдалуу рецепттерден тез жана оңой даярдалуучу салат жасап алыңыз.','Terve ema, terve laps 🥑','Sinu raua- ja kaltsiumivarud võivad olla ammendunud. Valmista meie tervislike retseptide järgi kiire ja lihtne energiat andev salat, et jõuaksid tegutseda.'),
('caa0a9a0-1a0d-4362-a446-9f103d33e564'::uuid,'Көз ирмемди сактап калуу 📸','Балаңыз бөлмөдө тынч ойноп жатканда, ''Ымыркай фотосессиясы'' функциясын ачып, анын ачылып келе жаткан кичинекей инсандыгын сүрөткө тартып алыңыз.','Hetke jäädvustamine 📸','Samal ajal kui nad toas armsalt mängivad, ava kohe funktsioon „Beebi fotosessioon“ ja jäädvusta nende õitsev isiksus.'),
('3cc5a97d-281f-41bf-8747-fbb71f040e65'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктоо убактысына бир саат калганда үйдөгү бардык жарыктарды жана экрандарды өчүрүңүз. Мелатонин гормону тынч жана жарыгы аз чөйрөдө гана иштелип чыгат.','Hämarda tuled 🌙','Tund enne magamaminekut lülita majas välja kõik eredad tuled ja ekraanid. Melatoniini toodetakse vaid rahulikus ja hämaras keskkonnas.'),
('528b02c4-9d93-4cda-add4-eb9a04a4395a'::uuid,'Эне сүтүн көбөйтүүчү азыктар 🍲','Бүгүн өзүңүздү чыңдоо үчүн биздин аялдар үчүн пайдалуу рецепттер бөлүмүндөгү сүттү көбөйтүүчү шорполорду байкап көрүңүз.','Toidud rinnapiima toetamiseks 🍲','Proovi täna meie naiste tervislike retseptide jaotises olevaid piima tootmist soodustavaid suppe ja turguta end.'),
('a889d8c9-3ffc-4f2f-8c82-a33c81ad3e8d'::uuid,'Акыркы жолу кайсы эмчегиңизди эмизгениңизди унутуп калдыңызбы? 🤱','Anacan таймери акыркы жолу кайсы эмчектен эмизгениңизди — солбу же оңбу — эсинде сактайт, андыктан сиз эстеп отурбайсыз! Эмгизүү процессин таймер менен азыр баштаңыз!','Unustasid, kummast rinnast viimati toitsid? 🤱','Anacani taimer jätab meelde, millisest rinnast sa viimati toitsid – vasakust või paremast –, nii et sina ei pea seda tegema! Alusta toitmist taimeriga kohe!'),
('5c42ea20-5a84-467a-b408-412bcaaf8374'::uuid,'Күндүзгү уйку өзгөрүп жатабы? 🥱','Кичинекейиңиз күндүзгү эки уйкусунун биринен баш тартып жатабы? Биринчи туулган күнүнө жакындап калгандыктан, анын уйку графигин өзгөртүүгө убакыт келгендир.','Kas päevased uinakud muutuvad? 🥱','Kas su pisike tõrgub ühe päevase uinaku vastu? Võib-olla on aeg kohandada nende unegraafikut, kuna esimene sünnipäev läheneb.'),
('b5252c17-b36e-4334-8221-0dc9210bbc77'::uuid,'Үй-бүлөлүк дасторкондогу орду! 🍲','Кичинекейиңиз эми сиз менен бир убакта тамактанууну жакшы көрөт! Биздин тиркемедеги ''Кошумча тамактандыруу'' рецепттеринен үй-бүлөлүк даамдуу тамактарды табыңыз.','Koht perelaua ääres! 🍲','Sinu pisikesele meeldib nüüd süüa samal ajal kui sinule! Avasta meie äpi jaotises „Tahke toit beebidele“ peresõbralikke hõrgutisi.'),
('ee88eee3-00d7-4463-b0db-60b939d85d4e'::uuid,'Сурооңуз барбы? 🤖','Түн ичинде болсо да, Anacan AI жардамчыбыздан ''1 жаштан кийин уй сүтүнө кантип өтүү керек?'' сыяктуу маанилүү суроолоруңузду берип, колдоо алыңыз.','Kas sul on küsimusi? 🤖','Küsi ka hilisõhtul meie Anacan AI assistendilt olulisi küsimusi, näiteks „Kuidas minna üle lehmapiimale pärast 1. eluaastat?“ ja saa tuge.'),
('48047d55-0e81-4b9a-976d-56b580b1a7b7'::uuid,'Педиатриялык кооптонуулар 🤖','Балаңыз бир жашка чыкканда тамактануусунда кандай өзгөрүүлөр болот? Өзүңүздү чарчатпаңыз; педиатр тарабынан жактырылган так тизмени Anacan AI''дан сураңыз.','Mured lastearsti juures 🤖','Millised muudatused toitumises toimuvad, kui beebi läheneb esimesele sünnipäevale? Ära väsita end; küsi Anacan AI-lt täpne, pediaatri heakskiidetud nimekiri.'),
('56284941-dca4-4067-9e31-d61fc4ebeb63'::uuid,'Командалык колдоо 🥂','Күндүн чарчоосун басуу үчүн өнөктөшүңүз менен бир чыны чай ичип, бири-бириңизге: ''Биз дагы бир күндү ийгиликтүү өткөрдүк!'' деп айтыңыз.','Meeskonna tugi 🥂','Päevaväsimuse peletamiseks jaga partneriga tassi teed ja öelge üksteisele: „Me saime veel ühe päevaga hakkama!“'),
('c69bf08f-8c53-4bb9-8c0e-a81edd03f90e'::uuid,'Жөнөкөй буйруктарды толук аткаруу! 🧠','Балаңыз ''Топту бер'' же ''Бул жакка кел'' дегениңизди түшүнүп калды! Бул интеллектуалдык өсүштү биздин Блогдор бөлүмүндөгү макалалар менен дагы да өнүктүрүңүз.','Lihtsate käskluste täielik järgimine! 🧠','Sinu laps saab sinust aru, kui ütled „Anna mulle pall“ või „Tule siia“! Toeta seda intellektuaalset hüpet veelgi meie blogide jaotise artiklitega.'),
('152edc3c-3a8c-41ee-81bb-0df222f2c1ea'::uuid,'Болгону 2 жума калды! 🎈','Туулган күнүнө болгону 14 күн калды! Сагыныч сезими каптап жатабы... Ымыркай фотосессиясын ачып, төрөлгөн күнүндөгү сүрөтүн азыркы сүрөтү менен салыштырып, анын укмуштуудай өсүү жолуна күбө болуңуз.','Ainult 2 nädalat jäänud! 🎈','Sünnipäevani on jäänud vaid 14 päeva! Nostalgialaine tuleb peale... Ava beebi fotosessioon, pane sünnipäeva pilt kõrvuti praegusega ja tunnista seda imelist kasvamist.'),
('87c2d4c6-8130-43a1-8ff7-fa406c018013'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Күндүзгү чарчооңуз жетиштүү болду. Эми баланы уктоого даярдоо жана жомок окуп берүү кезеги атасында. Ал эми сиз болсо, кулакчыныңызды тагып эс алыңыз.','Issi öövahetus 👨‍🍼','Sul on päevasest kurnatusest küllalt. Nüüd on issi kord beebi magamaminekuks ette valmistada ja unejuttu lugeda. Sina aga pane lihtsalt kõrvaklapid pähe.'),
('d1325a58-5701-4db5-a92f-ca67116c5c21'::uuid,'Өзүңүздү жалгыз сезген учурлар 🧗‍♂️','Кичинекейиңиз турганда диванды коё берип, кыска убакытка өз алдынча туруп жатабы? Ал тең салмактуулукту таап жатат!','Hetked, mil tunned end üksi 🧗‍♂️','Kas su pisike laseb seistes diivanist lühikeseks ajaks lahti? Nad otsivad oma tasakaalu!'),
('3beff563-1e72-4a1f-8490-4e977c8b0b7a'::uuid,'«Эмне тамак жасасам?» деген суроо 🍲','1 жашка чыгып жаткан балаңыздын менюсу үчүн идеялар түгөнүп жатабы? Anacan AI''дан балаңыз өзү кармап жей ала турган жеңил тамактардын тизмесин сураңыз.','„Mida süüa teha?“ dilemma 🍲','Kas menüüideed saavad peagi 1-aastaseks saava lapse jaoks otsa? Küsi Anacan AI-lt nimekirja lihtsatest näputoitudest, mida su pisike saab ise kätte võtta ja süüa.'),
('eebfea92-7f8e-43d7-a45c-4a10e720b24c'::uuid,'Караңгылык менен достошуу 🌙','Балаңыздын тезирээк уктап кетишине жардам берүү үчүн кечки тартибине караңгылыкты кошуңуз. Бөлмөдөгү керексиз жарыктарды жана экрандарды өчүрүңүз.','Pimedusega sõbraks saamine 🌙','Et aidata pisikesel kiiremini uinuda, muuda õhtune rutiin pimedamaks. Lülita toas välja kõik mittevajalikud tuled ja ekraanid.'),
('f8f9e691-e184-414d-9abe-ae0a3969929a'::uuid,'Сүйлөшүүгө кошулуу 🗣️','Сиз сүйлөшүп жатканда, кичинекейиңиз өзүнүн ''бала тили'' менен жооп берип, үнүн бийиктетип жатабы? Анын баарлашуу жөндөмү тез өнүгүүдө; бөлмөдө экинчи сүйлөөчү бар – сөзсүз угуңуз!','Vestlusega liitumine 🗣️','Kui sa räägid, kas su pisike „sekundeerib“ oma beebijutuga ja tõstab häält? Nende suhtlemisoskus kiireneb; sul on toas teine kõneleja – kuula teda kindlasti!'),
('20db1e8e-1980-431d-800c-b7aa4ccf158b'::uuid,'Өз алдынча тамактанууга алгачкы аракеттер! 🥄','Кичинекейиңиз кашыкты кармап, оозуна алып барууга аракет кылып жатабы? Бул кызыктуу көз ирмемдерди колдоо үчүн биздин ''Кошумча тамактандыруу'' бөлүмүнөн ылайыктуу тамактарды тандаңыз.','Esimesed katsed ise süüa! 🥄','Kas su pisike üritab juba lusikat hoida ja suhu viia? Nende lõbusate hetkede toetamiseks vali sobivad toidud meie jaotisest „Tahke toit beebidele“.'),
('77cedc71-0d6f-45f7-a8a4-9ddfcd0a5be6'::uuid,'Уйку алдындагы жомоктор 🪄','''Акылдуу жомоктор'' бөлүмүндө музыка жана жаратылыш үндөрүнөн турган өзгөчө фондук үн түзүңүз. Сөзсүз, жөн гана таза тынчтык.','Une-jutud magamiseks 🪄','Loo „Nutikates lugudes“ eriline taustahelide maastik, mis koosneb ainult muusikast ja loodushelidest. Ei mingeid sõnu, vaid puhas rahu.'),
('eca3e78d-00de-4e77-bade-43808f152e4f'::uuid,'Мээримдүү өбүүлөр 🥰','Сиз өпкөнү келгенде, ал эриндерин чүйрүп же бетиңизден өөп жатабы? Анын таттуу өбүүсү бардык чарчооңузду таркатууга кудуреттүү.','Armastavad suudlused 🥰','Kui kummardud suudluseks, kas nad ajavad huuled prunti või annavad põsele märja musi? Nende armsad väikesed suudlused on piisavalt võimsad, et sulatada kogu su väsimus.'),
('863a6afb-427b-4143-a527-2e01fe303116'::uuid,'Атасынын күлкүлүү жүздөрү 🤡','Сыртка чыккыңыз келеби, бирок шамал болуп жатабы? Биздин «Аба ырайы жана кийим тандоо» жардамчыбыз сизге температураны гана эмес, кичинекейиңизге шамалга туруктуу кандай кийим кийгизүү керектигин да айтып берет.','Issi naljakad näod 🤡','Parim viis beebit naerma ajada on lasta issil teha naljakaid hääli! Nautige neid rõõmsaid õhtuseid hetki koos oma pisikesega.'),
('b4676fcf-2967-4b49-adbd-12ebe6a54334'::uuid,'Сырдашуу муктаждыгы 💬','''Кантип эле бир жашка чыгып калды!'' деген ой сизди толкундатып жатабы? Бул сонун сезим менен Anacan коомчулугундагы башка энелер менен бөлүшүңүз.','Vajadus usaldada 💬','Kas mõte „Ma ei suuda uskuda, et nad on juba aastased!“ teeb sind emotsionaalseks? Jaga seda imelist tunnet teiste emadega Anacani kogukonnas.'),
('222d12a8-4347-4dce-afd7-4a0890721d0b'::uuid,'Тынчсыз түндөр 🥱','Кичинекейиңиз уйкуга каршылык көрсөтүп жатабы? Балким, күндүзгү уйкуларынын бирин кыскартуу убактысы келгендир. Анын күн тартибин карап чыгыңыз.','Rahutud ööd 🥱','Kas su pisike paneb uinumisele kõigest väest vastu? Võib-olla on aeg ühest päevasest uinakust loobuda. Vaata tema rutiin üle.'),
('5047e51c-64dc-4fe5-bc38-0409a743d0f6'::uuid,'Боюн жана салмагын көзөмөлдөйлү! 📏','Бөбөгүңүздүн 1 жаштагы текшерүүсү жакындап калды. ''Өнүгүүгө көз салуу'' бөлүмүнө анын акыркы маалыматтарын киргизиңиз жана анын дени сак өсүү графигине карап сыймыктаныңыз!','Jälgime kasvu ja kaalu! 📏','Sinu pisikese 1-aasta kontroll on kohe ukse ees. Uuenda värskeimat infot jaotises „Arengu jälgija“ ja tunne uhkust tema tervisliku kasvukõvera üle!'),
('873f2996-36df-4d67-a2df-ec60f668be2f'::uuid,'Тамактануу учурундагы баш аламандык! 🥣','Балаңыз кашыкты атайылап жерге таштап, сизге карап жатабы? Ал тартылуу күчүн жана сиздин реакцияңызды сынап жатат. Сабырдуу болуңуз – бул оюндун бир бөлүгү!','Söögiaja segadus! 🥣','Kas laps pillab meelega lusikat ja vaatab sulle otsa? Ta katsetab gravitatsiooni ja sinu reaktsioone. Varu kannatust – see kõik on osa mängust!'),
('8cd57628-b75f-4445-8bc9-6b180e6572dc'::uuid,'Бүгүнкү акылдуу жомок 🪄','''Акылдуу жомоктор'' бөлүмүндө балаңыз башкы каарман болгон өзгөчө жомок түзүңүз.','Tänane arukas lugu 🪄','Loo jaotises „Nutilood“ eriline jutt, kus sinu laps on kangelane.'),
('94b60a89-bc34-41d8-818c-174aa7ed663b'::uuid,'Жыйнообу же эс алуубу? 🛋️','Балаңыз уктап жатканда, идиш жуугучка шашпаңыз. Диванга жатып, көзүңүздү жумуп, 15 мүнөт жөн гана эс алыңыз. Сиз робот эмессиз да, туурабы?','Koristada või puhata? 🛋️','Kui beebi magab, ära tõtta nõudepesumasina juurde. Heida diivanile, sulge silmad ja lihtsalt hinga 15 minutit. Kas sa oled robot? Ei.'),
('c7b84129-89ab-4610-b19f-84959d6194f9'::uuid,'Шкаф изилдөөчүсү 🕵️‍♀️','Ашканадагы бардык казан-аяктар жердеби? Зыянсыз тиричилик буюмдары менен ойноо анын логикалык ой жүгүртүүсүн өнүктүрүүгө жардам берет. Анын өзүнүн ''казыналарын'' эркин изилдөөсүнө жол бериңиз!','Kapi-detektiiv 🕵️‍♀️','Kas kõik köögi potid ja pannid on põrandal? Ohutute majapidamistarvetega mängimine arendab loogilist mõtlemist. Lase tal oma „aardeid“ vabalt avastada!'),
('3c7f679a-b11a-4f67-a3ae-5f350e93a451'::uuid,'Өзгөчө жомок убактысы 🪄','''Акылдуу жомоктор'' бөлүмүндө балаңыз башкы каарман болгон өзгөчө жомок түзүңүз.','Eriline unejutu aeg 🪄','Loo jaotises „Nutilood“ eriline jutt, kus sinu laps on kangelane.'),
('15436a4e-52bb-4539-9146-377403746da0'::uuid,'Энелердин ынтымагы 💬','''Эмнеге балам азырынча баспай жатат?'' деген сыяктуу суроолор сизди чарчатып жатабы? Anacan коомчулугуна кошулуңуз, ошондо ар бир бала өз темпи менен өнүгөрүнө ынанасыз.','Emaduse õe-tunne 💬','Kas küsimused nagu „Miks mu laps veel ei kõnni?“ kurnavad sind? Liitu Anacani kogukonnaga ja näed, et iga laps areneb omas tempos.'),
('c145c120-a19a-477b-922c-6f3ffc430787'::uuid,'Чыгармачыл грамматика 🗣️','''Бардым-эттим'' же ''келип-жаткан экен'' деген сыяктуу кызыктуу сөз айкаштарын ойлоп таап жатабы? Анын сөз байлыгы өнүгүп жатат! Аны күлүп оңдобоңуз, жөн гана туура сүйлөмдү кайталап, аны бекемдеп коюңуз.','Loov grammatika 🗣️','Kas ta mõtleb välja veidraid ja naljakaid pöördevorme? Tema sõnavara areneb! Ära naera ega paranda teda, vaid kinnita öeldut, korrates lauset õigesti.'),
('21394622-dd96-488a-a90a-b8f72d718390'::uuid,'Баланын алгачкы бут кийимин тандоо! 👟','Ал кадамдар барган сайын тездей баштады! Буттун өнүгүүсүнө жардам берүүчү ортопедиялык тамандуу жана жумшак тамандуу биринчи бут кийимдер үчүн биздин ''Сунушталган өнүмдөр'' тизмебизди карап чыгыңыз.','Beebi esimeste kingade valimine! 👟','Need sammud muutuvad kiiremaks! Vaata meie soovitatud toodete nimekirjast esimesi jalatseid, mis on ortopeedilise toega ja pehme tallaga, et toetada jala arengut.'),
('c8d8ec20-b116-4c1f-93ec-b76e6f76a1b1'::uuid,'Үйдү бала үчүн коопсуз кылуу! 🛡','️ Ал өз алдынча баса баштаганда, кооптуу жагдайлар көбөйөт. Балдар үчүн коопсуздук кулпулары жана тепкич тосмолорун көрүү үчүн биздин ''Сунушталган өнүмдөр'' бөлүмүнө кириңиз.','Kodu lapsekindlaks muutmine! 🛡','️ Iseseisvalt kõndima hakates kasvavad ka ohud. Vaata meie soovitatud toodete hulgast lapselukke ja trepiväravaid.'),
('cbeda45d-85bc-4e45-b9c0-cc3c3d5c896b'::uuid,'Сиздин өзгөрүп жаткан денеңиз 👗','Күзгүдөн денеңиздеги жаңы өзгөрүүлөрдү көрүп капаланып жатасызбы? Ушул денеңиз менен сиз адам баласын жараттыңыз. Өзүңүздү кучактап, канчалык күчтүү экениңизди эсиңизден чыгарбаңыз.','Sinu muutuv keha 👗','Kas tunned kurbust, vaadates peeglist oma keha uusi kumerusi ja jooni? Selle kehaga lõid sa uue inimese. Kallista end ja mäleta, kui uskumatult tugev sa oled.'),
('f38aba52-8d3a-44ad-96bf-7d9de570ef68'::uuid,'Апасына жакын болуу 🥰','Балаңыз дааратканага киргениңизде да эшиктин артында ыйлап күтүп жатабы? Бул — бөлүнгөндөгү тынчсыздануунун туу чокусу. Ар дайым ''Мен ушул жердемин!'' деп айтып, аны сооротуп туруңуз.','Emme külge klammerdumine 🥰','Kas laps nutab ja ootab ukse taga isegi siis, kui lähed vannituppa? Lahutamiskartus on haripunktis. Rahusta teda iga kord, öeldes: „Ma olen siinsamas!“'),
('03283459-7c0f-4d41-9c06-406552e1c477'::uuid,'Кынтыксыздык иллюзиясы 🛑','Бүгүн баары пландагыдай болбой калдыбы? Өзүңүздү күнөөлөбөңүз. Сиз социалдык тармактардагы жасалма сүрөттөрдөгүдөй эмес, чыныгы энесиз.','Täiuslikkuse illusioon 🛑','Kas täna ei läinud miski plaani kohaselt? Ära süüdista ennast. Sa oled päris ema, mitte sotsiaalmeedia filtreeritud illusioon.'),
('3843a02f-a85f-47a9-97ba-0e63677749e2'::uuid,'Үнсүз баатыр 🤫','Бала уктап калган учурда үйдөгү ар бир дабыш бомба жарылгандай сезилет. Бөлмөдөгү ызы-чуунун деңгээлин өлчөөчү куралды колдонуп жатканда, өзүңүздүн да баскан кадамыңызды акырын таштаңыз.','Vaikne kangelane 🤫','Hetkel, mil ta uinub, tundub iga heli majas pommiplahvatusena. Kasuta mürataset mõõtvat tööriista toa helipiiri seadmiseks ja muuda ka oma sammud kergemaks.'),
('fde65599-b651-49fa-a50a-5b78bed58d9f'::uuid,'Сөөмөй менен көрсөтүүнүн күчү! ☝️','Кичинекейиңиз алыстагы нерселерди көрсөтүп, реакция кылып жатабы? Бул — биргелешкен көңүл буруунун өнүгүп жатканынын сонун белгиси. Ал көрсөткөн нерсени чогуу карап, анын ачылышына ортоктош болуңуз.','Nimetissõrme vägi! ☝️','Sinu pisike näitab kaugetele asjadele ja reageerib! See on suurepärane märk arenevast ühisest tähelepanust. Jaga tema avastust, vaadates eset koos temaga.'),
('069d21f4-a2ef-4d28-91bb-979c8ca3f3f6'::uuid,'Уйдун сүтү менен тааныштыруу 🥛','Кичинекейиңиз бир жашка жакындаган сайын, анын менюсу өзгөрө баштайт. Уй сүтүн же бал сыяктуу азыктарды киргизүү боюнча суроолоруңуз болсо, дароо жооп алуу үчүн Anacan AI''дан сурагандан тартынбаңыз.','Lehmapiima tutvustamine 🥛','Kuna pisikese esimene sünnipäev läheneb, hakkab tema menüü muutuma. Kui sul on küsimusi lehmapiima või mee pakkumise kohta, küsi julgelt Anacan AI-lt kiiret nõu.'),
('6b37b92f-5c61-4852-9ace-caab2bda465b'::uuid,'Үй-бүлөлүк сейилдөөлөр жана пландар! ☕','Туулган күн жакындап калды! Достор жана жакындар менен жолугушуу үчүн коляска менен кирүүгө ыңгайлуу кафелерди ''Энелер үчүн ыңгайлуу жайлар'' бөлүмүнөн табыңыз.','Pere väljasõidud ja plaanid! ☕','Sünnipäev on lähedal! Leia jaotisest „Emasõbralikud kohad“ kohvikuid, kuhu on mugav vankriga siseneda, et sõprade ja perega kohtuda.'),
('fedb8c6b-7722-4e20-9134-1af5ae254e85'::uuid,'Укалоо убактысы 💆‍♂️','Бала уктагандан кийин, күндүн чарчоосун басуу үчүн жолдошуңуз менен бири-бириңизге ийинге массаж жасап бериңиз. Сиздер бир командасыздар!','Massaaži aeg 💆‍♂️','Pärast beebi uinumist tehke partneriga üksteisele lõõgastavat õlamassaaži, et päeva pingetest vabaneda. Te olete meeskond!'),
('51bb1e4c-965f-4d69-b6e7-c79da0dce45c'::uuid,'Апа үчүн гана мейкиндик ☕','Үйдө отуруп чарчадыңызбы? ''Энелер үчүн ыңгайлуу жайлар'' бөлүмүнөн балдар менюсу бар жана отурганга ыңгайлуу кафени тандап, өзүңүзгө бир аз убакыт бөлүңүз.','Aeg ainult emale ☕','Kas kodus olemine kurnab? Vali jaotisest „Emasõbralikud kohad“ lasteala ja mugavate istmetega kohvik ning võta aega iseendale.'),
('814176f3-c727-409b-b14a-fa62636170f1'::uuid,'Китепке болгон сүйүүнү ойготуу 📖','Кечки тартибиңизге кагаз китептерди кошуңуз. Алар азыртадан эле барактарды өздөрү оодарганга аракет кылып жатышат! Үнүңүздү окуянын ыргагына жараша өзгөртүп окуңуз.','Raamatuarmastuse tärkamine 📖','Lisa õhtusesse rutiini paberist raamatud. Ta proovib juba ise lehti pöörata! Kohanda oma hääletooni vastavalt loo tempole.'),
('f73c2769-0def-42bc-93e0-9a021c41b271'::uuid,'Музыкага бийлөө! 🎶','Телевизордон ритмдүү музыка угары менен эле жамбашын кыймылдата баштадыбы? Анын музыкалык кабыл алуусу өнүгүп жатат – кошулуп бийлеп, бул сонун көз ирмемден ырахат алыңыз.','Muusika saatel tantsimine! 🎶','Ta nõksutab puusi kohe, kui kuuleb telerist rütmilist heli! Tema muusikaline taju tärkab – liitu temaga ja nautige seda hetket koos.'),
('4c628627-3074-421f-9cfc-318df363eaf0'::uuid,'Кайсы эмчектен эмизгениңизди унутуп калдыңызбы? 🤱','Anacan таймери акыркы жолу кайсы эмчекти (оң/сол) эмизгениңизди эсинде сактайт. Эмизүү процессин азыр таймер менен баштаңыз!','Unustasid, kummast rinnast toitsid? 🤱','Anacani taimer jätab sinu eest meelde, kumba rinda sa viimati kasutasid (parem/vasak). Alusta toitmist taimeriga kohe!'),
('99abcc3d-bec9-4537-89f9-92bfe6f4056c'::uuid,'Күндүн сонун аякташы ✨','Сиз укмуштуудай энесиз, бир жыл бою чыныгы баатыр болдуңуз! Өзүңүз менен канчалык сыймыктанарыңызды ''Маанай күндөлүгүнө'' жазып коюңуз да, тынч уктаңыз.','Kaunis päeva lõpp ✨','Sa oled uskumatu ema ja oled olnud terve aasta tõeline kangelane! Kirjuta oma „Tujupäevikusse“, kui uhke sa enda üle oled, ja maga rahulikult.'),
('5a7c1a91-4811-4c74-93f4-2ee19bdbb39a'::uuid,'Бирге өткөргөн алгачкы күндөрүңүздү эстеп, күлүп алыңыз.','Сиз бул 1 жылдык маарекеге оңой жеткен жоксуз! Бул сиздердин команда катары жетишкен чоң жеңишиңиздер.','Meenutage ja naerge koos oma esimeste ühiste päevade üle.','Sa ei jõudnud selle 1-aasta tähiseni kergelt! See on teie kui meeskonna võit.'),
('e7879bf6-3dca-4f0b-9981-d7f119d39235'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктаардан бир саат мурун үйдөгү бардык жарыктарды жана экрандарды өчүрүңүз. Мелатонин гормону тынч жана жарым-жартылай караңгы чөйрөдө гана иштелип чыгат.','Hämarda tuled 🌙','Tund enne magamaminekut lülita välja kõik eredad tuled ja ekraanid. Melatoniin tekib vaid rahulikus ja hämara valgusega keskkonnas.'),
('14e209af-2489-4eb6-a1f0-be21be617768'::uuid,'Уктоо алдындагы жомок 🪄','''Акылдуу жомоктор'' бөлүмүндө музыка жана жаратылыш үндөрүнөн гана турган өзгөчө фон түзүңүз. Сөзсүз, жөн гана тынчтык жана күтүү сезими.','Une-eelsed lood 🪄','Loo jaotises „Nutilood“ eriline taust, mis koosneb vaid muusikast ja loodushäältest. Ei mingeid sõnu, vaid rahu ja ootusärevus.'),
('0549edc6-63d2-4caa-a43c-f029f7f39465'::uuid,'Тиш чыгуудагы кыйынчылыктар 🦷','Тиштеринин бүйлөсү кайра кызарып, шилекейи агып жатабы? Балким, биринчи азуу тиштери чыгып келе жаткандыр.','Hammaste tuleku mured 🦷','Kas igemed on jälle punased ja süljevool pidev? Võib-olla on esimesed purihambad tulemas.'),
('1c81021a-496b-49c0-86bc-4bde92ff779d'::uuid,'Үндү көзөмөлдөө 🤫','Бала уктагандан кийинки алгачкы жарым саат — эң сезимтал учур. Үн өлчөгүч менен чөйрөнү текшерип, капыстан чыккан үндөрдөн сак болуңуз.','Helikontroll 🤫','Esimene pooltund pärast uinumist on kõige õrnem aeg. Kontrolli keskkonda müratase-mõõtjaga ja hoidu äkilistest helidest.'),
('262cbb13-eb12-4831-9fe5-37ece168bdfa'::uuid,'Дене тили аркылуу баарлашуу 🗣️','Сиз ''Кеттикпи?'' дегенде колдорун көтөрүшөбү же башын чайкап ''Жок'' деп айтышабы? Алардын түшүнүү жөндөмү чындап эле өстү!','Kehakeele kaudu suhtlemine 🗣️','Ta tõstab käed, kui ütled „Lähme?“, või raputab pead, öeldes „Ei“. Tema arusaamisoskus on tõeliselt kasvanud!'),
('38f7fe28-84d1-4b40-8904-c7ef3e18b0f8'::uuid,'Таза аба — жашоо булагы 🌳','Эгер үйдө ыйлаактык башталып жатса, ''Аба ырайы жана кийим'' функциясын текшерип, бөбөгүңүздү коляскага салып, түз эле сейил бакка жөнөңүз. Жаратылыш — аны тынчтандыруунун эң тез жолу.','Värske õhk on päästja 🌳','Kui kodus on jonnituur tulemas, vaata funktsiooni „Ilm ja riietus“, pane pisike vankrisse ja suundu otse parki. Loodus on kiireim viis rahunemiseks.'),
('39697061-01f6-4b41-8098-183a43f25058'::uuid,'Кубиктерден сепил куруу 🧱','Алар эки же үч оюнчук кубикти бири-биринин үстүнө коюуга аракет кылып жатышат! Унчукпай байкап туруңуз жана бул алгачкы инженердик аракеттерин колдоп коюңуз.','Klotsidest lossi ehitamine 🧱','Ta proovib laduda kahte või kolme klotsi üksteise otsa! Jälgi vaikselt ja kiida neid tärkavaid insenerioskusi.'),
('c5294433-a84c-4be9-ad57-5744718366c9'::uuid,'Бүгүн кыжырданып жатасызбы? 📝','Бала уктагандан кийин, сезимдериңизди ''Маанай күндөлүгүңүзгө'' жазып коюңуз. Эртең жаңы жана андан да кооз күн болот.','Kas oled täna ärritunud? 📝','Kui beebi magab, pane oma tunded „Tujupäevikusse“ kirja. Homme on uus ja veelgi ilusam päev.'),
('0944c4dc-3e95-4efb-97dc-8b4809d96d45'::uuid,'Наристелик курак башталат! 🌟','Ымыркайлык мезгил расмий түрдө артта калды! Бөбөгүңүз эми кичинекей бала болуп, өзүнүн инсандыгын көрсөтүп, баарын ''өзүм жасайм'' деп жатат. Сабырдуулукка жана сүйүүгө толгон жаңы укмуштуу окуя башталды!','Väikelapseea algus! 🌟','Imikuiga on ametlikult seljataga! Sinu pisike on nüüd väikelaps, kes kehtestab end ja tahab kõike „ise“ teha. Uus seiklus täis kannatust ja armastust on alles algamas!'),
('569602c0-f0cf-4229-b498-984bfdabf097'::uuid,'Акылдуу жомок убактысы 🪄','Эми 1 жашка чыккан жана дүйнөнү таанып жаткан чоң баатыр жөнүндө ''Акылдуу жомок'' түзүп, күнүмдүк тартипти улантыңыз.','Nutikas unejutt 🪄','Jätka rutiini, luues „Nutiloo“ suurest kangelasest, kes on nüüd 1-aastane ja avastab maailma.'),
('6e25898e-24d8-4ca6-8cbe-71a271993d6f'::uuid,'Үндү көзөмөлдөө 🤫','Бала уктагандан кийинки алгачкы жарым саат — эң сезимтал учур. Үн өлчөгүч менен чөйрөнү текшерип, капыстан чыккан үндөрдөн сак болуңуз.','Helikontroll 🤫','Esimene pooltund pärast uinumist on kõige õrnem aeg. Kontrolli keskkonda müratase-mõõtjaga ja hoidu äkilistest helidest.'),
('d5e35c42-03ad-4068-b27d-3efca55a35ad'::uuid,'Кашыктан баш тартуу 🥄','Алар кашыкты кармап, пюрени өз алдынча жегенге аябай кызыгып жатышат. Ооба, бир аз чачылышы мүмкүн, бирок бул алардын майда моторикасын өнүктүрүү үчүн өтө маанилүү. Аларга изилдөөгө мүмкүнчүлүк бериңиз!','Lusika tõrjumine 🥄','Ta tahab väga ise lusikat hoida ja püreed süüa. Jah, see tekitab segadust, kuid see on peenmotoorika arenguks ülioluline. Lase tal avastada!'),
('f93e7290-30ca-44fe-a1e4-55044619c9a6'::uuid,'Энергияга болгон муктаждык 🍲','Жашоо ого бетер ыргактуу болуп калды. Күч-кубатыңызды сактоо үчүн биздин дени сак рецепттерден темирге жана белокко бай эртең мененки тамакты тандаңыз.','Energiavajadus 🍲','Elu on muutunud veelgi kiiremaks. Vali meie tervislike retseptide hulgast raua- ja valgurikas hommikusöök, et hoida oma energiataset kõrgel.'),
('10a3d57b-5997-4410-8ceb-fa0dd3d4cee2'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкүсүн ойгонуунун түйшүгүн жалгыз өзүңүз көтөрбөңүз. Өнөктөшүңүздү ойготуңуз; команда болуу — жоопкерчиликти тең бөлүшүүнү билдирет.','Issi öövahetus 👨‍🍼','Ära võta öiseid ärkamisi täielikult enda kanda. Ärata oma partner; meeskonnaks olemine tähendab kohustuste võrdset jagamist.'),
('50b26349-9946-4708-aec2-e87f1b15952f'::uuid,'Өз алдынча алгачкы кадамдарбы? 🧗‍♂️','Балким бүгүн, балким эртең... бөбөгүңүз өз алдынча бир-эки кадам таштоого аракет кылып жатат! Анын өнүгүүсүнө көз салуучу куралыңызда бул кызыктуу учурду белгилөөгө даяр болуңуз!','Esimesed iseseisvad sammud? 🧗‍♂️','Võib-olla täna, võib-olla homme... sinu pisike proovib juba iseseisvalt sammu või paar astuda! Ole valmis märkima see põnev sündmus arengu jälgijasse!'),
('9407d96f-ca5a-4378-a7c6-ee00256c457a'::uuid,'Аба ырайын текшерүү ⛅','Сейилдөөгө чыгаарда терезени карап эле койбоңуз. ''Аба ырайы жана кийим'' куралы сизге шамалдын ылдамдыгын жана эң ылайыктуу кийим тандоону заматта айтып берет.','Ilmateade ⛅','Jalutuskäiku plaanides ära piirdu vaid aknast välja vaatamisega. Lase tööriistal „Ilm ja riietus“ öelda tuule kiirus ja ideaalne riietuskombinatsioon.'),
('3ed836ab-41d4-4203-a7c8-b9e7b1394cd2'::uuid,'Сырдашуу муктаждыгы 💬','1 жаштан кийин баары кыйындайт дегендерден коркуп жатасызбы? Anacan Коомчулугуна жазыңыз жана башка энелердин реалдуу, позитивдүү тажрыйбаларын окуңуз.','Vajadus usaldada 💬','Kas sind hirmutavad need, kes ütlevad, et pärast 1. aastat läheb raskemaks? Postita Anacani kogukonda ja loe teiste emade tõelisi positiivseid kogemusi.'),
('4c27d203-23f5-4e87-918e-d40df5e30875'::uuid,'Түнкү бейпилдик 🛀','Жылуу ванна, жеңил массаж жана караңгылатылган бөлмө. Уйкунун үзгүлтүксүз болушунун негизги сыры — ырааттуу кечки тартипти сактоо.','Öine rahu 🛀','Soe vann, õrn massaaž ja pime tuba. Järjepidev une-eelne rutiin on katkematu ööune peamine saladus.'),
('6ad316f8-edd9-4dff-aac4-f3492d4a602a'::uuid,'Жөнөкөй буйруктарды аткаруу 🧸','Сиз ''Топту алып кел'' дегенде, ал аны таап, сизге алып келеби? Алардын тилди түшүнүү жөндөмү чындап эле туу чокусунда! Интерактивдүү оюндарды көбүрөөк ойнотуңуз.','Lihtsate käskluste järgimine 🧸','Kui ütled „Anna mulle pall“, kas ta tõesti leiab selle ja toob sulle? Tema kõnest arusaamine on tipus! Soodusta rohkem interaktiivseid mänge.'),
('028a5b0d-04de-43dc-984d-eaf6e3427904'::uuid,'Баланын алгачкы бут кийимин тандоо 👟','Бала басууга даярданып жатканда, үйдө бут кийим кийгизиш керекпи деп ойлонушуңуз мүмкүн. Anacan AI''дан биринчи кадам таштоочу бут кийимдер жана жылаңайлак басуунун пайдасы тууралуу сураңыз.','Beebi esimeste kingade valimine 👟','Kui ta valmistub kõndima, võid mõelda, kas ta peaks kodus kingi kandma. Küsi Anacan AI-lt esimese sammu kingade ja paljajalu käimise kasulikkuse kohta.'),
('5d68d6d5-05d2-43b4-bd93-e3f95983e445'::uuid,'Тизмелер — эң чоң жардамчы 🛒','1 жаштан кийин меню өзгөрөт. Уй сүтү же жаңы азыктар керекпи? ''Соода тизмеңизди'' дароо толтуруп, өнөктөшүңүзгө жөнөтүңүз.','Nimekirjad on päästjad 🛒','Pärast 1. aastat menüü muutub. Kas vajad koju lehmapiima või uusi toiduaineid? Täida kohe oma „Ostunimekiri“ ja saada see partnerile.'),
('9a073421-3e36-4699-bbbd-50a69e46f431'::uuid,'Өзүңүзгө убакыт бөлүңүз 🛁','Кыймылы көп бөбөктүн артынан чуркоо оңой эмес. Чарчаганыңызды жазып, ''Маанай күндөлүгүңүзгө'' сезимдериңизди жазуу менен эс алыңыз.','Võta aega iseendale 🛁','Terve päeva liikuva pisikese järel jooksmine pole kerge ülesanne. Leevenda väsimust ja lõõgastu, märkides oma tunded „Tujupäevikusse“.'),
('2cdeb7df-f4f5-4a75-ae9b-552210a168fe'::uuid,'Китептерди барактоо 📖','Алар китептин барактарын өздөрү оодарып, сүрөттөргө реакция кылып жатышабы? Аларга түстүү жомок китептерин көп окуп бериңиз!','Raamatute lehitsemine 📖','Kas ta pöörab ise papist raamatute lehti ja reageerib piltidele? Loe talle palju värvilisi juturaamatuid!'),
('8b98f6cf-24e2-4a41-9bea-c77f1a82d1bd'::uuid,'Өз алдынча алгачкы кадамдар! 🧗‍♂','️ Бөбөгүңүз эмеректи коё берип, өз алдынча туруп, балким көптөн күткөн алгачкы кадамдарын таштап жатат! Бул унутулгус учурду өткөрүп жибербеңиз – видеону дароо анын ''Бөбөк альбомуна'' жүктөп коюңуз.','Esimesed iseseisvad sammud! 🧗‍♂','️ Sinu pisike laseb mööblist lahti ja seisab üksi, võib-olla teeb isegi need esimesed kauaoodatud sammud! Ära maga maha seda unustamatut hetke – laadi video kohe tema beebialbumisse.'),
('beccb06c-7cf4-4f1a-9455-17d5b952ad96'::uuid,'Музыкалык кечелер 🎶','Кечки маалдагы тынчсызданууну басаңдатуунун эң оңой жолу — сүйүктүү ырыңызды коюп, бөбөгүңүздү кучактап, чогуу бийлөө.','Muusikalised õhtud 🎶','Kõige lihtsam viis õhtuse rahutuse leevendamiseks on panna mängima lemmiklaul, hoida oma pisikest lähedal ja koos tantsida.'),
('0c97760a-2746-4ddf-ad12-5f44e1960612'::uuid,'Тынчтыкка болгон муктаждык 🤫','Үн өлчөгүчтүн (Sound Meter) жардамы менен бөлмөдөгү тынч атмосфераны сактаңыз. Түнкүсүн ойгонуу сиздин да, балаңыздын да эртең мененки маанайына терс таасирин тийгизиши мүмкүн.','Vaikuse vajadus 🤫','Hoia toas rahulikku õhkkonda, kasutades Helimõõtjat. Öised ärkamised võivad negatiivselt mõjutada nii beebi kui ka sinu enda hommikust meeleolu.'),
('61d67656-ab73-4417-b42d-5e55ecf64b87'::uuid,'«Жок» деп айтуунун күчү 🛑','Алар бир нерсе сунушталганда башын чайкап «жок» деп айтууну үйрөнүштү! Бул өжөрлүк эмес, өз оюн билдирүүнүн сонун белгиси. Аларга өз алдынча чечим кабыл алууга мүмкүнчүлүк берип, тынчтандырыңыз.','„Ei“ ütlemise vägi 🛑','Ta on õppinud pead raputades "ei" näitama, kui talle midagi pakutakse! See pole kangekaelsus, vaid imeline märk oma arvamuse avaldamisest. Paku valikuid, et aidata tal tunda end iseseisva ja rahulikuna.'),
('b58ae5cb-ec5b-400f-b490-16ff65c6cead'::uuid,'Логикалык оюндар 🧩','Алар оюнчуктарды кутуга салып, кайра баарын төгүп жатышабы? Бул аракет алардын «ичинде» жана «сыртында» деген түшүнүгүн жана логикалык ой жүгүртүүсүн өстүрөт. Бул изилдөөгө тоскоол болбоңуз!','Loogikamängud 🧩','Kas ta viskab mänguasju kasti, et need siis uuesti välja kallata? See tegevus arendab tema arusaama mõistetest "sees" ja "väljas" ning loogilist mõtlemist. Ära keela talle seda avastamisrõõmu!'),
('6b997061-a83d-4040-b848-d55a40a87a1a'::uuid,'Дени сак эне 🥑','Эгер бөбөгүңүз курсагы ток болсо, эми кезек сизде! Биздин пайдалуу рецепттерибизден энергия бере турган тамак тандап алып, диванга жатып кеминде 10 мүнөт эс алыңыз.','Terve ema 🥑','Kui sinu pisikesel on kõht täis, on sinu kord! Vali meie tervislike retseptide seast üks energiat andev vahepala ja pikuta diivanil vähemalt 10 minutit.'),
('8d89c421-922f-4b8a-bc83-525a380ead88'::uuid,'Тепкичтерди изилдөө 🧗‍♂️','Жөн эле полдо басуу аздык кылып жатабы? Тепкичтерге жана эмеректерге чыгууга аракет кылып жатышабы? Бул кыймыл-аракет жөндөмүнүн өнүгүүсү! Аларды көз жаздымда калтырбаңыз.','Treppide avastamine 🧗‍♂️','Kas lihtsalt põrandal kõndimisest enam ei piisa? Kas ta üritab ronida treppidele ja mööblile? See on sihikindel motoorika areng! Hoia tal kindlasti silm peal.'),
('dacf6637-c6dd-4427-9e89-1dc06f453ae5'::uuid,'Сыйкырдуу жомок убактысы 🪄','Кечки тартибиңизди «Акылдуу жомок» бөлүмүндөгү «Кичинекей баатырдын уйку сырлары» аттуу жомок менен көрктөндүрүңүз.','Maagiline unejutt 🪄','Muuda oma õhturutiin säravamaks looga "Nutikad unejutud" kogumikust pealkirjaga "Kõige pisema kangelase unesaladused".'),
('2d2e06b1-2d94-4883-a675-93637a17ca98'::uuid,'Кыялдануунун туу чокусу ☁️','Бөбөгүңүз баарына эле ыйлап, тынчсызданып жатабы? Балким, арткы азуу тиштери чыгып жаткандыр. Муздак тиш салгычтарды даярдап коюңуз!','Jonnituurid on haripunktis ☁️','Kas sinu pisike on rahutu ja nutab iga asja peale? Võib-olla hakkavad tagumised purihambad lõikuma. Hoia külmad närimisrõngad käepärast!'),
('2eeb1f61-7042-48aa-9ecc-41443c68b4a8'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкүсүн ойгонгондо, кезектешип туруңуз – бир түнү сиз, бир түнү жолдошуңуз. Кээде бөбөктү атасынын ыргактуу сооротуусу гана тынчтандыра алат.','Issi öövahetus 👨‍🍼','Öiste ärkamiste puhul tõuske kordamööda – ühel ööl sina, teisel sinu partner. Mõnikord suudab beebit kõige paremini rahustada just isa rütmiline kussutamine.'),
('d1cf73d9-421b-4ad1-b114-e5025146d5b2'::uuid,'Үй иштерин ким жасайт? 🌪️','Үй жумуштары көбөйүп кеттиби? Коё туруңуз! Жолдошуңуздан бүгүнкү үй жумуштарын өзүнө алуусун сураныңыз. Сиз эс алууга татыктуусуз.','Kes teeb kodutöid? 🌪️','Kas majapidamistööd kuhjuvad? Las nad olla! Palu oma partneril täna kodutööde eest hoolitseda. Sa oled puhkuse ära teeninud.'),
('18cb3df2-de24-43c0-a3d0-160051dc5202'::uuid,'Эмоционалдык күндөлүк 📝','Өзүңүздү жалгыз сезгенде, сезимдериңизди Маанай күндөлүгүнө жазыңыз. Бардык энелер ушундай учурларды башынан өткөрүшөт; эсиңизде болсун, сиз күчтүүсүз.','Emotsioonide päevik 📝','Kui tunned end üksi, pane oma tunded kirja Meeleolupäevikusse. Kõik emad kogevad selliseid hetki; pea meeles, et oled tugev.'),
('19c626ef-26a5-49ef-921f-4577f35ab653'::uuid,'Эмчектен же бөтөлкөдөн чыгаруубу? 🍼','Бир жашка толгондон кийин баланы эмчектен же соскиден чыгарууну ойлонуп жатасызбы? Anacan коомчулугундагы башка энелерден эң жумшак ыкмаларды жана кеңештерди сураңыз.','Lutt või pudel maha jätta? 🍼','Kas kaalud lapse luti võõrutamist pärast tema esimest sünnipäeva? Küsi Anacan kogukonna teistelt emadelt nende kõige leebemaid meetodeid ja nippe.'),
('c6a284e9-0bba-433f-9823-bcc74708dbd9'::uuid,'Таза аба — дары 🌳','Бөбөгүңүз күнү бою ыйлап, тынчсызданып жатабы? Чечими жөнөкөй: аба ырайын жана кийимин текшерип, коляскага салып, түз эле сейил бакка жөнөңүз!','Värske õhk on kui ravim 🌳','Kas sinu beebi on terve päeva nutnud ja rahutu olnud? Lahendus on sageli lihtne: vaata ilma ja tema riietust, pane ta vankrisse ja suunduge otse parki!'),
('6e5eaf14-24e1-4f23-8d49-63a035b843ff'::uuid,'Маанай күндөлүгүнөн бейпилдик табыңыз 📝','Сиздин канчалык чарчаганыңызды эч ким көрбөгөндөй сезилип жатабы? Тиркемедеги Маанай күндөлүгү сизди угууга даяр. Бүгүн сизди кыжырданткан майда-чүйдө нерселердин баарын жазып, оюңузду тазартыңыз.','Leia lohutust oma meeleolupäevikust 📝','Kas tundub, et keegi ei näe, kui kurnatud sa oled? Rakenduse Meeleolupäevik on siin, et sind kuulata. Pane kirja kõik pisiasjad, mis sind täna hulluks ajasid, ja puhasta oma mõtted.'),
('f20aef27-fde2-489c-9dd8-fe28386cf1db'::uuid,'Геометриялык фигуралар жана акыл оюндары! 🧩','Алар тегерек же төрт бурчтуу фигураларды өз ордуна салууга аракет кылып жатышат. Бул жагымдуу үйрөнүү учурларын Бөбөктүн альбомуна сактап коюңуз.','Geomeetrilised kujundid ja ajumängud! 🧩','Ta püüab sobitada ringe või ruute vastavatesse aukudesse. Talleta need armsad õppimishetked oma Beebialbumisse.'),
('0955065c-ecf1-48ed-9f6f-735958386a41'::uuid,'Эне үчүн витамин 🥑','Бөбөгүңүздүн курсагын тойгузуу үчүн баарын жасайсыз. Ал эми өзүңүзчү? Биздин пайдалуу рецепттер бөлүмүнөн темирге жана кальцийге бай жеңил түшкү тамак тандаңыз.','Vitamiinid emale 🥑','Sa teed kõik, et sinu pisikesel oleks kõht täis. Aga kuidas on sinuga? Vali meie tervislike retseptide jaotisest kerge, raua- ja kaltsiumirikas lõunasöök.'),
('1d781ae8-7800-48ae-b0ee-fe44c7f13291'::uuid,'Күндүзгү уйку өзгөрүп жатабы? 🥱','Бөбөгүңүз күнүнө эки жолу уктаган уйкусунун бирине такыр каршы болуп жатабы? Бир жолу уктоого өтүү көбүнчө 1 жаш курагында башталат. Күн тартибин акырындап өзгөртүңүз.','Kas päevased uinakud muutuvad? 🥱','Kas sinu pisike keeldub täielikult ühest oma kahest päevasest uinakust? Üleminek ühele uinakule algab sageli umbes 1-aastaselt. Kohanda tema rutiini järk-järgult.'),
('61536a43-b97b-4fe8-8f6a-f358141baefc'::uuid,'Жомок менен уйку 🪄','«Акылдуу жомок» менен эр жүрөк жана сүйкүмдүү жаныбарлар жөнүндө жомок түзүп, бөлмөнү сыйкырдуу дүйнөгө айлантыңыз.','Unele viiv unejutt 🪄','Loo "Nutikate unejuttude" abil lugu julgetest ja armsatest loomadest ning muuda tuba maagiliseks paigaks.'),
('76e3844a-efe7-4daa-855a-4cfd4d92bfc9'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктаардан бир саат мурун үйдөгү жарыкты азайтып, экрандарды өчүрүңүз. Уйку гормону мелатонин тынч жана жарыгы аз чөйрөдө жакшы иштелип чыгат.','Hämarda tuled 🌙','Tund enne magamaminekut hämarda kõik eredad tuled ja lülita majas ekraanid välja. Unehormoon melatoniin tekib kõige paremini rahulikus ja hämaras keskkonnas.'),
('8b586560-e2d2-46b0-ba82-419bb7b56682'::uuid,'Мээнин тумандашы 🛒','«Энелик унутчаактыктан» жапа чегип жатасызбы? Үйгө керектүү майда-чүйдө нерселер үчүн кабатыр болбоңуз; аларды дароо Соода тизмесине кошуп, жолдошуңузга тапшырыңыз.','Ajupudru 🛒','Kas oled hädas "ema aju" unustamisega? Ära muretse väikeste majapidamisostude pärast; lisa need kohe Ostunimekirja ja lase oma partneril nendega tegeleda.'),
('b87394f8-5f2b-4eb7-a491-26b80560c8a3'::uuid,'Таамай ыргытуу! ⚾','Алар колундагы оюнчукту атайылап белгилүү бир бутага ыргытууга аракет кылып жатышат. Кол менен көздүн координациясы тез өнүгүүдө. Чогуу ыргытып-кармап ойноп ырахат алыңыз!','Sihipärased visked! ⚾','Ta püüab meelega visata käes olevat mänguasja kindla sihtmärgi pihta. Tema käe-silma koordinatsioon areneb kiiresti. Nautige koos viskamise ja püüdmise aega!'),
('078c86a9-a3c8-4f20-a27a-3aa00d3961ad'::uuid,'Тамактануу убактысы көңүлдүү! 🥦','Эгерде балаңыз тамак ичпей жатса, «Кошумча тамактандыруу рецепттери» бөлүмүнөн түстүү жана кызыктуу тамактарды даярдаңыз.','Lõbus söögiaeg! 🥦','Kui oled hädas valiva sööjaga, valmista värvilisi ja põnevaid portsu jaotisest "Retseptid lisatoiduga alustavale beebile".'),
('3b7df91a-7022-4a50-9438-82f89b2240b8'::uuid,'Дене мүчөлөрүн таануу 👀','«Көзүң кайда?» деп сураганда, манжасы менен көрсөтүп жатабы? Алардын таанып-билүү жөндөмү өсүүдө! Бул ийгиликти өнүгүү трекерине сыймыктануу менен жазып коюңуз.','Kehaosade tundmaõppimine 👀','Kui küsid: "Kus su silm on?", kas ta näitab sellele näpuga? Tema kognitiivne arusaam areneb mühinal! Pane see uhkusega kirja arengujälgijasse.'),
('f55bcf4b-2f37-47d2-8e08-b8c72b1b9a56'::uuid,'Сиз сонун ийгиликтерге жетишип жатасыз! 💖','Бала тарбиялоо — бул марафон. Бүгүн кечинде өзүңүзгө убакыт бөлүңүз — сүйүктүү тасмаңызды көрүңүз же жөн гана эс алыңыз.','Sa teed suurepärast tööd! 💖','Lapse kasvatamine on maraton. Võta täna õhtul kindlasti aega iseendale – vaata lemmikfilmi või lihtsalt lõõgastu.'),
('18eaf932-80c3-47ae-a394-f6ce083ef215'::uuid,'"Өзүм жасайм!" баскычы 🥦','Алар кашыкты колуңуздан алгысы келип жатабы? Берүүгө уруксат бериңиз. Бир аз чачылышы мүмкүн, бирок бул өз алдынчалыктын башталышы алардын өнүгүүсү үчүн абдан маанилүү.','„Teen ise!“ faas 🥦','Ta tahab lusikat sinu käest ära võtta. Luba tal seda teha. See võib minna segaseks, kuid see tärkav iseseisvus on tema arengu jaoks ülioluline.'),
('b55b3812-173b-489f-a2ae-d2c78611fd35'::uuid,'Караңгылыкты кабыл алуу 🌙','Бөбөгүңүздүн тезирээк уктап кетишине жардам берүү үчүн, кечки тартиптин бир бөлүгү катары караңгылыкты киргизиңиз. Бөлмөдөгү ашыкча жарыктардын баарын өчүрүңүз.','Pimeduse omaksvõtmine 🌙','Et aidata beebil kiiremini uinuda, tutvusta talle pimedust kui osa õhturutiinist. Lülita toas välja kõik üleliigsed tuled.'),
('c9fb44a1-ad82-4f16-a316-50d99863130e'::uuid,'Аллергия боюнча кооптонуулар 🤖','Бир жаштан кийин жаңы тамактарды киргиздиңизби? Эгерде кандайдыр бир суроолоруңуз болсо, Anacan AI''дан дароо кеңеш алыңыз.','Mured allergiate pärast 🤖','Kas olete pärast tema esimest sünnipäeva uutele toitudele üle läinud? Kui sul on muresid, küsi kohe nõu Anacan AI-lt.'),
('159279c3-df89-49cf-a71c-bb577a8dd0c3'::uuid,'Кооптуу аймактарды изилдөө ⚡','Алар бой тартып, мурда жете албаган текчелерге жете башташты. Үйдүн коопсуздугун тез арада текшерип чыгуу убактысы келди.','Ohtlike tsoonide avastamine ⚡','Ta on kasvanud pikemaks ja ulatub nüüd riiuliteni, kuhu ta varem ei ulatunud. On aeg teha kiire koduohutuse kontroll.'),
('3b6ac273-a759-45de-9492-87af2df8cac9'::uuid,'Түнкү тынчтык 🤫','Эгерде унаанын же сырттын ызы-чуусу бөбөгүңүздү тынчсыздандырса, Үн өлчөгүчтү колдонуп чөйрөнү текшериңиз жана фондо ак ызы-чуу (white noise) коюп көрүңүз.','Öine vaikus 🤫','Kui auto- või õuemüra häirib sinu beebit, kasuta keskkonna kontrollimiseks Helimõõtjat ja kaalu taustaks valge müra mängimist.'),
('bc24cbab-3bcd-4b5b-92fb-249b861079c2'::uuid,'Оюнчуктардын кичинекей куюну! 🌪️','Сиздин эс алууңуз таза үйгө караганда маанилүүрөөк. Оюнчуктар эртең да ошол жерде болот, бирок азыр сизге сергек эне керек.','Väike mänguasjatornaado! 🌪️','Sinu puhkus on olulisem kui laitmatult puhas kodu. Mänguasjad on seal ka homme, kuid praegu on vaja puhanud ema.'),
('0693172d-9675-431e-ae2b-b1d735f8da0f'::uuid,'Чарчооңузду артка калтырыңыз.','Бүгүн кечинде бөбөгүңүз уктагандан кийин, жолдошуңуз менен «командалык жеңишиңизди» белгилегенди унутпаңыз!','Jäta väsimus selja taha.','Kui sinu pisike on täna õhtul uinunud, ära unusta tähistada oma "meeskonnavõitu" koos partneriga!'),
('3e6bfa0e-5f58-4921-bf7a-6f47b0eb1125'::uuid,'Өзүңүздү салыштырууну токтотуңуз 🛑','«Тигинин баласы эрте сүйлөптүр» деген сөздөрдү унутуңуз. Ар бир бала өзүнүн уникалдуу темпи менен өнүгөт. Жөн гана аларды сүйүүгө бөлөңүз.','Lõpeta enda võrdlemine 🛑','Unusta ära "Selle ja tolle laps rääkis varem". Iga laps areneb omas ainulaadses tempos. Külva ta lihtsalt armastusega üle.'),
('b9520b22-b9b3-4ca3-a219-de05702404a8'::uuid,'18 айга жакындап калдык! 📸','Бөбөгүңүз 12,5 айлык болду! Сүрөт альбомун ачып, бул активдүү жана шайыр курактын эң кызыктуу учурларын сүрөткө тартып алыңыз.','18 kuud läheneb! 📸','Sinu pisike on juba 12,5 kuud vana! Ava oma beebi fotoalbum ja jäädvusta piltidele selle aktiivse ja elava väikelapseea kõige naljakamad hetked.'),
('0c105765-0e1a-42dd-bd14-0ca4153705c0'::uuid,'Майда моториканы өнүктүрүү 🖍','️ Бөбөгүңүз кагазга чийме тартууну жактырышы мүмкүн. Анын жашына ылайыктуу жоон карандаштарды же боёкторду берип, чыгармачылыгынын ачылышын байкаңыз.','Peenmotoorika arendamine 🖍','️ Sinu pisikesele võib meeldida paberile kritseldada. Anna talle vanusele sobivad jämedad rasvakriidid või värvid ja vaata, kuidas tema loovus avaneb.'),
('1b77ed52-4cf2-48a6-98fc-53d0a94dc968'::uuid,'Уйку тартиби бейпилдик берет 🌙','Ар кечинде бирдей тартипти (ванна, жомок, жарыкты азайтуу) сактоо бөбөгүңүздүн тынч уктап кетишине жардам берет.','Unerutiin toob rahu 🌙','Igal õhtul sama tegevuste jada (vann, unejutt, tulede hämardamine) järgimine aitab sinu beebil rahulikumalt uinuda.'),
('795996e4-e3e1-4fa7-b442-27c8ffa35bff'::uuid,'Тиш чыккандагы ыңгайсыздыктар 🦷','Тиштеринин бүйлөсү кызарып, шилекейи агып жатабы? Бул процессти тиш чыгуу трекерине белгилеп, муздак тиш салгычтарды даярдап коюңуз!','Hammaste tulekuga seotud ebamugavus 🦷','Kas tema igemed on jälle punased ja ta ilastab lakkamatult? Pane see kirja hammaste lõikumise jälgijasse ja hoia külmad närimisrõngad valmis!'),
('452e9fa3-8dba-4774-8bfe-d6afa50d161c'::uuid,'Тизмелер — эң чоң жардамчы 🛒','Тамакка жемиш же сулу жармасы түгөнүп калдыбы? Соода тизмесин дароо толтуруп, керектүү нерселерди жолдошуңуздун телефонуна жөнөтүңүз.','Nimekirjad on päästjad 🛒','Kas puuviljad või kaerahelbed said otsa? Täida kohe Ostunimekiri ja saada vajadused oma partneri telefoni.'),
('8c12c251-a9b5-45cb-92ff-f145e2484025'::uuid,'Дубалды бойлоп басуу 🧗‍♀️','Эмеректерди кармап басуу алардын сүйүктүү иши. Өз алдынча кадам таштоо жакындап калды! Өнүгүү трекериңизди текшериңиз.','Seinu mööda kõndimine 🧗‍♀️','Mööbli ääri mööda kõndimine on tema lemmiktegevus. Iseseisvad sammud on kohe nurga taga! Vaata oma arengujälgijat.'),
('c7e52a2b-46d5-4446-b455-907f7523256e'::uuid,'Үндү көзөмөлдөө 🤫','Уктап кеткенден кийинки алгачкы жарым саат бөбөктөр үчүн эң сезимтал убакыт. Үн өлчөгүчтү колдонуп чөйрөнү текшериңиз жана күтүлбөгөн ызы-чуулардан сак болуңуз.','Helikontroll 🤫','Esimene pooltund pärast uinumist on beebide jaoks kõige tundlikum aeg. Kasuta keskkonna kontrollimiseks Helimõõtjat ja ole ettevaatlik ootamatute helidega.'),
('56403a92-c6d5-492f-b073-20bcd436f218'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкүсүн ойгонуунун түйшүгүн жалгыз өзүңүз тартпаңыз. Жолдошуңузду ойготуңуз; команда болуу — жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi öövahetus 👨‍🍼','Ära võta öiste ärkamiste koormat täielikult enda kanda. Ärata oma partner; meeskonnaks olemine tähendab kohustuste võrdset jagamist.'),
('763e2885-6f82-4d6b-8ec4-680155ad7a5f'::uuid,'Энелердин баарлашуусу 💬','Баланын кыяңкечтиги менен күрөшүү кыйын болуп жатабы? Anacan коомчулугуна дароо кошулуп, башка энелердин колдоочу комментарийлерин окуп, сооронуч табыңыз.','Emad suhtlevad 💬','Kas sul on raskusi jonnihoogudega toimetulekul? Liitu kohe Anacan kogukonnaga, loe teiste emade toetavaid kommentaare ja leia lohutust.'),
('f47e2fcf-5030-43a8-a77b-79834cb3f95a'::uuid,'Кичинекей денедеги чоң сезимдер 🛑','Алар каалаганы болбой калганда полго жатып алып ыйлап жатышабы? Алардын деңгээлине түшүп, жай сүйлөшүп, бул кыяңкечтикти жеңүүгө жардам бериңиз.','Suured tunded, väike keha 🛑','Kas ta viskab end põrandale, kui ei saa oma tahtmist? Lasku tema tasemele, räägi rahulikult ja aita tal nende jonnihoogudega toime tulla.'),
('a0e7f0f6-1438-4f75-acb4-559e4df47974'::uuid,'Тынчтыкка болгон муктаждык 🤫','Үн өлчөгүчтүн (Sound Meter) жардамы менен бөлмөдөгү тынч атмосфераны сактаңыз. Түнкүсүн ойгонуу сиздин да, балаңыздын да эртең мененки маанайына терс таасирин тийгизиши мүмкүн.','Vaikuse vajadus 🤫','Hoia toas rahulikku õhkkonda, kasutades Helimõõtjat. Öised ärkamised võivad negatiivselt mõjutada nii beebi kui ka sinu enda hommikust meeleolu.'),
('dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95'::uuid,'Эне үчүн мейкиндик ☕','Үйдө отуруп чарчадыңызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн кафе тандап, эс алып, өзүңүзгө убакыт бөлүңүз.','Aeg emale ☕','Kas tunned end kodus olemisest kurnatuna? Vali meie emasõbralike kohtade seast kohvik, kus saad mugavalt lõõgastuda ja võtta aega iseendale.'),
('f34137b7-333a-47bb-8fab-66dd8be52bfb'::uuid,'Бий жана ритмдер 🎶','Телевизордон же телефонуңуздан ыргактуу үн угары менен бийлей башташабы? Алардын музыкалык кабыл алуусу толук иштеп жатат — кошулуп, чогуу бийлеңиз!','Tants ja rütmid 🎶','Kas ta hakkab tantsima kohe, kui kuuleb telerist või telefonist rütmilist heli? Tema muusikataju töötab täistuuridel – ühine lõbuga ja tantsi koos temaga!'),
('8a51b6b4-96e5-40da-8e4b-a3f74c147eb5'::uuid,'Уйку алдындагы жомоктордун сыйкыры 📖','Уктаар алдындагы кыска жомок элестетүүнү гана өстүрбөстөн, сиз менен балаңыздын ортосундагы эмоционалдык байланышты да бекемдейт.','Unejuttude võlu 📖','Lühike unejutt enne magamaminekut mitte ainult ei ärata kujutlusvõimet, vaid tugevdab ka emotsionaalset sidet sinu ja lapse vahel.'),
('b28c4699-a204-48ae-80c2-bef5008fdffd'::uuid,'Өз алдынча ойноо көндүмдөрү 🧩','Алардын кыска убакытка болсо да өз алдынча ойной алышы, көңүл буруу жөндөмүнүн өсүп жатканын көрсөтөт. Мындай учурларда аларды алыстан сүйүү менен карап туруңуз.','Iseseisva mängu oskused 🧩','Tema võime iseseisvalt mängida, isegi lühikest aega, näitab, et tema tähelepanuvõime areneb. Jälgi teda nendel hetkedel armastusega eemalt.'),
('e6b48652-88e0-49d8-b2cc-654a9f8eb626'::uuid,'Анын өсүшүнө көз салуу 📏','Балаңыздын кийимдери кичине болуп калдыбы? Жаңы өлчөмдөрүн Салмак трекери бөлүмүнө кошуп, алардын дени сак өсүп жатканын белгилеңиз.','Kasvu jälgimine 📏','Kas sinu laps hakkab oma riietest välja kasvama? Lisa tema uued mõõdud Kaalujälgija jaotisesse ja tähista tema tervet arengut.'),
('05e8d5ea-453b-4a35-a697-81e0b9ca911a'::uuid,'Чоңдорду тууроо 🧹','Сиз үстөлдү сүрткөндө, алар да чүпүрөк алып ошондой кылууга аракет кылышабы? Алар сиздин кичинекей күзгүңүз! Сиз жасаган нерсенин баарын кайталап жатышат.','Täiskasvanute matkimine 🧹','Kui sa pindu pühid, kas ta haarab lapi ja püüab sama teha? Ta on sinu väike peegel! Ta kopeerib kõike, mida sa teed.'),
('13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0'::uuid,'Паркпы же үйбү? ⛅','Сыртка чыккыңыз келип жатабы, бирок шамалбы? «Аба ырайы жана кийим тандоо» жардамчысы сизге эң ылайыктуу кийим айкалышын заматта сунуштайт.','Park või kodu? ⛅','Tahad õue minna, aga puhub tuul? Ilma- ja riietusassistent soovitab sulle kohe täiusliku kombinatsiooni.'),
('ecb2b9d1-a640-4303-b570-f3c7f463e0ab'::uuid,'Тынчсыз түндөр 🥱','Наристеңиз уйкуга каршылык көрсөтүп жатабы? Балким, анын күндүзгү уйкусун жана жалпы тартибин кайра карап чыгууга убакыт келгендир.','Rahutud ööd 🥱','Kas su pisike paneb uinumisele kõigest väest vastu? Võib-olla on aeg vaadata üle tema päevased uinakud ja üldine rutiin.'),
('9dd82a43-7f3a-4a5e-9d01-a99d7d738015'::uuid,'Өз алдынча кийинүү аракеттери 👕','Ал байпагын өзү чечип же кийүүгө аракет кылып жатабы? Анын бул жаңы жөндөмүн сабырдуулук менен колдоп коюңуз.','Iseseisvad riietumiskatsed 👕','Kas ta püüab juba ise sokke jalast võtta või jalga panna? Toeta kannatlikult neid tärkavaid peenmotoorika oskusi.'),
('ccf44d60-2dc0-447f-b1ea-dd06a80f0324'::uuid,'Суу ичүү абдан маанилүү 💧','Активдүү балдар бат суусашат. Наристеңизге күн бою, өзгөчө кечки тамактан кийин суу сунуп турууну унутпаңыз.','Vedeliku tarbimine on võtmetähtsusega 💧','Aktiivsed lapsed muutuvad kiiresti januseks. Ära unusta pakkuda oma pisikesele päeva jooksul vett, eriti pärast õhtusööki.'),
('10934358-ef97-4dab-87ad-73a62aee1231'::uuid,'Жыйнообу же эс алуубу? 🛋️','Бала уктап жатканда идиш жууганга шашылбаңыз. Диванга жатып, көзүңүздү жумуп, 15 мүнөт жөн гана терең дем алыңыз.','Koristada või puhata? 🛋️','Kui beebi magab, ära tõtta nõudepesumasina juurde. Heida diivanile, sulge silmad ja lihtsalt hinga 15 minutit.'),
('58866969-75c5-44cd-a308-210945d7a2af'::uuid,'Сыноо жана ката 🧱','Ал эки кубикти биринин үстүнө бирин коюуга аракет кылып, бирок алар кулап жатабы? Ал кайрадан аракет кылууда. Анын бул кичинекей «инженердик» аракетин үн катпай байкап туруңуз!','Katse ja eksituse meetod 🧱','Ta püüab kahte mänguklotsi üksteise otsa panna, aga need kukuvad muudkui ümber. Ta proovib ettevaatlikult uuesti. Jälgi vaikselt tema väikeseid insenerikatsetusi!'),
('94a9a306-04fb-42bb-9962-95b473b02f89'::uuid,'Эмоционалдык күндөлүк 📝','Өзүңүздү жалгыз сезгенде, сезимдериңизди Маанай күндөлүгүнө жазыңыз. Бардык энелер ушундай учурларды башынан өткөрүшөт; эсиңизде болсун, сиз күчтүүсүз.','Emotsioonide päevik 📝','Kui tunned end üksi, pane oma tunded kirja Meeleolupäevikusse. Kõik emad kogevad selliseid hetki; pea meeles, et oled tugev.'),
('8a5f3751-2bcd-4454-bfef-74c90f1c3f85'::uuid,'Күндүн аягы — эс алуу убактыңыз. 🛁','Бүгүн абдан чарчадыңызбы? Жылуу душка түшүп, эс алыңыз жана бүгүн жасаган бардык иштериңиз үчүн өзүңүзгө ыраазы болуңуз.','Päeva lõpp, aeg iseendale. 🛁','Tunned end täna täiesti kurnatuna? Käi sooja duši all, lõõgastu ja tunnusta end kõige eest, millega oled hakkama saanud.'),
('dcaa4b27-ca42-45e3-98f1-f11ad70e3dc8'::uuid,'Дене мүчөлөрүн үйрөнүү! 👃','«Мурунуң кайда?» деп сураганда, ал кичинекей манжасы менен көрсөтүп жатабы? Бул сүйкүмдүү ачылыштарды күзгү алдында кызыктуу оюнга айлантыңыз!','Õpime kehaosi! 👃','Kui küsid: „Kus on sinu nina?“, kas ta näitab seda oma väikese sõrmega? Muuda need armsad avastused lõbusaks mänguks peegli ees!'),
('e70adad3-3a0b-4d15-ab3c-9f286916a872'::uuid,'Пайдалуу шам-шум убактысы. 🍎','Чексиз энергиялуу балдар үчүн мөмө-жемиш кесимдери же жашылча таякчалары эң сонун тандоо. Аларды өз алдынча кармап жегенге үндөңүз.','Tervislik vahepala. 🍎','Piiramatu energiaga lastele on puuviljaviilud või köögiviljakangid suurepärane valik. Innusta teda toitu ise kätte võtma ja sööma.'),
('6b0a9309-594c-4f0a-a15f-6c0611c0d5c3'::uuid,'Кичинекей сүрөтчү иштеп жатат! 🖍','️ Аларга жоон карандаштарды же манжа менен боёочу боёкторду берип, кагазга эркин сүрөт тартууга уруксат бериңиз. Бул майда моториканы жана чыгармачылыкты өнүктүрүү үчүн абдан пайдалуу.','Väike kunstnik töös! 🖍','️ Paku talle jämedaid rasvakriite või näpuvärve ja lase tal paberile vabalt kritseldada. See on suurepärane peenmotoorika ja loovuse arendamiseks.'),
('ccb3a3d0-8dc5-450a-b184-37cf81a39c01'::uuid,'Экөөңүз үчүн тең таза аба. 🌳','«Энелер үчүн ыңгайлуу жайлар» картасын карап чыгып, балаңыз менен коляскада сейилдөөгө эң сонун жаңы сейил бакты табыңыз.','Värske õhk teile mõlemale. 🌳','Uuri meie „Emadesõbralike kohtade“ kaarti, et leida uus park, mis sobib ideaalselt mugavaks jalutuskäiguks vankriga.'),
('dd0a1e57-cbbc-4cc0-9c63-a03032174ab5'::uuid,'Уйку тартиби коопсуздук сезимин жаратат. 🌙','Ар кечинде кайталанган уйку алдындагы тартип (ванна, жомок, жарыкты өчүрүү) наристеңиздин тезирээк уктап кетишине жардам берет.','Unerutiin loob turvatunde. 🌙','Järjepidev õhtune rutiin (vann, jutt, hämardatud tuled) aitab su pisikesel kiiremini uinuda.'),
('12139491-dd07-42f8-b056-98645d9880be'::uuid,'Убакыттын бир ирмеми 📸','Ал күн сайын чоңоюп баратат. «Баланын сүрөт альбому» функциясын дароо ачып, бул табигый көз ирмемди түбөлүккө сактап калыңыз.','Hetk, mis on jäädvustatud 📸','Ta kasvab iga päevaga veidi rohkem. Ava kohe funktsioon „Beebi fotosessioon“ ja jäädvusta see ehe hetk igaveseks.'),
('302d3885-ce15-4277-a0cf-d95f95d7ed63'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктаардан бир саат мурун үйдөгү бардык жарыктарды жана экрандарды өчүрүңүз. Мелатонин гормону тынч жана жарым-жартылай караңгы чөйрөдө гана иштелип чыгат.','Hämarda tuled 🌙','Tund enne magamaminekut lülita välja kõik eredad tuled ja ekraanid. Melatoniin tekib vaid rahulikus ja hämara valgusega keskkonnas.'),
('78f8f713-17f3-46f4-83f8-9cdbfd0c9894'::uuid,'Өз алдынча ойноо убактысы 🧸','Наристеңиз эми оюнчуктары менен 10-15 мүнөт өз алдынча ойной алат! Аны алыстан көзөмөлдөп, бир аз тынч убакыттан ырахат алыңыз.','Iseseisev mänguaeg 🧸','Su pisike suudab end nüüd 10–15 minutit ise mänguasjadega lõbustada! Jälgi teda eemalt ja naudi neid paari vaikset hetket.'),
('a72fe5b0-0907-43fb-b4ef-fc4dd880fecd'::uuid,'Аба ырайын изилдөө ⛅','Сырттагы аба ырайы түшүнүксүзбү? «Аба ырайы жана кийим» куралы сизге шамалдын ылдамдыгын жана балаңыз үчүн эң ылайыктуу кийимди заматта айтып берет.','Ilma avastamine ⛅','Kas ilm on väljas ebakindel? Lase tööriistal „Ilm ja riietus“ sulle kohe öelda tuule kiirus ja soovitada su pisikesele täiuslikku riietust.'),
('bac8ff9b-6338-4b34-a5d6-84b7aefd251c'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкү уйкунун түйшүгүн жалгыз өзүңүз көтөрбөңүз. Жолдошуңузду ойготуңуз; команда болуу — бул жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi öövahetus 👨‍🍼','Ära võta öiseid ärkamisi täielikult enda kanda. Ärata oma partner; meeskonnaks olemine tähendab vastutuse võrdset jagamist.'),
('c1daed2c-e22f-4c5a-8534-4ff90b6b866e'::uuid,'Оюнчуктарымды өзүм табам! 🧸','Ал сиз жашырган оюнчукту таап жатабы? Демек, ал буюмдардын көзгө көрүнбөсө да бар экенин түшүнө баштады!','Leian oma mänguasjad ise! 🧸','Kas ta leiab üles mänguasja, mille sa tema silme alt ära peitsid? Ta hakkab mõistma objektide jäävust!'),
('04429520-36d1-489e-8ec7-309a2c08ae92'::uuid,'Биз бир командабыз! 💖','Оор күндөн кийин жолдошуңуз менен отуруп, сүйлөшүп алыңыз. Бири-бириңизди колдоо — жүктү эки эсе жеңилдетет.','Me oleme meeskond! 💖','Pärast keerulist päeva istu koos partneriga maha ja rääkige asjad selgeks. Üksteise toetamine poolitab koorma.'),
('05fff0e7-029c-401c-bfab-497bbc099997'::uuid,'Сөздөрдүн маанисин түшүнүү 🗣️','«Топту алып кел» десеңиз, ал чындап эле издеп жатабы? Анын сөз байлыгы тез өсүп жатат. Аны менен татаалыраак сүйлөмдөр менен сүйлөшүп көрүңүз.','Sõnade tähenduse mõistmine 🗣️','Kui ütled „Too pall“, kas ta lähebki seda otsima? Tema sõnavara kasvab kiiresti. Proovi temaga rääkida keerulisemate lausetega.'),
('ec4b2f26-3631-4fed-9578-c9539a35a5c0'::uuid,'Сиздин сатып алуулар тизмеңиз 🛒','Күндөлүк түйшүктө шампунь же памперс түгөнүп калдыбы? Баарын эсиңизде сактоого аракет кылбаңыз — аны «Соода тизмесине» кошуп, жолдошуңуз менен синхрондоштуруп алыңыз.','Sinu ostunimekiri 🛒','Kas igapäevases kaoses said šampoon või mähkmed otsa? Ära püüa kõike peas hoida – lisa need oma ostunimekirja ja jaga seda partneriga.'),
('663824a2-b8fe-471a-b981-3eb69f3a2c7f'::uuid,'Кичинекей денедеги чоң сезимдер. 🌪','️ Өзүн түшүндүрө албай калганда ыйлап, кыжырданышы — кадыресе көрүнүш. Анын деңгээлине чейин ийилип, жай үн менен аны түшүнүп жатканыңызды айтып сооротуңуз.','Suured tunded, väike keha. 🌪','️ On normaalne, et ta ärritub ja nutab, kui ei oska end väljendada. Lasku tema tasandile ja kinnita rahulikul häälel, et mõistad tema tundeid.'),
('8be96289-58a8-4a48-89ec-c4ba0488e973'::uuid,'Суу менен ойноо абдан тынчтандырат. 💧','Кичинекей идишке суу куюп, ичине пластик чөйчөктөрдү же идиштерди салып бериңиз. Суу менен ойноо балдарга энергиясын чыгарууга жана эс алууга жардам берет.','Veemängud võivad olla nii rahustavad. 💧','Täida väike kauss veega ja pane sinna mõned plasttopsid või karbid. Veega mängimine aitab lastel energiat maandada ja lõõgastuda.'),
('a70fb0ff-98b0-4735-ac10-846168dd5d60'::uuid,'Сурооңуз барбы? 🤖','«1 жаштагы бала менен кантип мамиле кылуу керек?» сыяктуу маанилүү суроолоруңуз барбы? Anacan AI жардамчыбыздан адис кеңешин сураңыз.','Kas sul on küsimus? 🤖','Kas sul on isegi hilisõhtul olulisi küsimusi, nagu „Kuidas tulla toime 1-aastase lapse etapiga?“? Küsi asjatundlikku nõu meie Anacan AI-assistendilt.'),
('2a991705-4255-4931-9ad5-cef8eb9bf0dd'::uuid,'Сиздин кичинекей жардамчыңыз! 🧹','Ал сизди туурап, чүпүрөк алып чаң сүртүүгө аракет кылып жатабы? Бул сүйкүмдүү жана тарбиялык көз ирмемдерди балаңыздын альбомуна видео катары кошуп коюңуз, келечекте эскерүү катары калат.','Sinu väike abiline! 🧹','Kas ta imiteerib sind, haarates lapi ja püüdes tolmu pühkida? Lisa need armsad ja õpetlikud hetked videona beebialbumisse, et neid tulevikus meenutada.'),
('813ebcca-fa4c-42de-926c-6ca1c1526de6'::uuid,'Музыка менен тынчтык. 🎶','Кечинде активдүү оюндардын ордуна, наристеңизди уйкуга даярдоо жана өзүңүздүн тынчтыгыңыз үчүн жай музыка коюңуз.','Rahu muusika saatel. 🎶','Õhtuti mängi aktiivsete mängude asemel rahustavat muusikat, et valmistada oma pisike ette uneks ja iseennast rahuks.'),
('ce071e13-068a-4c5a-8d4c-437e6f25658d'::uuid,'Тамакты тандап жегендик. 🍲','Эгер ал айрым тамактардан баш тартса, кабатыр болбоңуз. Аны башка күндөрү жана башка формада (мисалы, пюре эмес, өзү кармап жей турган кесимдер түрүндө) кайра сунуп көрүңүз.','Valiv sööja. 🍲','Kui ta keeldub teatud toitudest, ära muretse. Paku neid uuesti teistel päevadel ja erineval kujul (nt näputoiduna püreestamise asemel).'),
('502b8118-151f-47c7-9476-eb53fa55cfd0'::uuid,'Мунараларды куруу! 🧱','Балаңыз эми 3-4 кубикти биринин үстүнө коё алат! Көңүл бурууну жана кол-көз координациясын талап кылган бул оюнду мактоо жана колдоо менен кубаттаңыз.','Tornide ehitamine! 🧱','Sinu laps suudab nüüd 3–4 klotsi üksteise otsa panna! Innusta seda keskendumist ning käe ja silma koordinatsiooni nõudvat mängu oma kiituse ja toetusega.'),
('af470a51-532a-4658-877a-26e61845210a'::uuid,'Баарлашуу убактысы. 👶','Балаңыз сейил бакта башка балдарды кунт коюп карап жатабы? Алар чогуу ойнобосо да, «катарлаш ойноо» — бул социалдашуунун биринчи маанилүү кадамы.','Aeg suhelda. 👶','Kas su laps jälgib pargis tähelepanelikult teisi lapsi? Isegi kui nad veel koos ei mängi, on „paralleelmäng“ esimene oluline samm sotsialiseerumisel.'),
('ceb1c77d-c486-4755-b204-47ec200fcd34'::uuid,'Сиздин үнүңүздүн тонун түшүнөт 🗣️','«Болбойт» деп катуу айтканыңызда, наристеңиз токтоп, сизге карап жатабы? Ал эмоцияларды сезип жана чек араларды түшүнө баштады!','Mõistab sinu hääletooni 🗣️','Kui ütled kindlalt „ei“, kas su pisike peatub ja vaatab sulle otsa? Ta hakkab mõistma emotsioone ja piire!'),
('53cb1b60-78f0-41c1-a42e-b48a4324533b'::uuid,'400 күндүк керемет! 🌟','Эртең чоң дата: 400 күн! Бул 1 жыл жана 1 айдан ашык убакыт! Үйдө майрамдык маанай түзүп, жаңы сүрөттөр үчүн телефонуңуздун эс тутумун тазалап алыңыз!','400 päeva imesid! 🌟','Homme on suur tähis: 400 päeva! See on üle 1 aasta ja 1 kuu! Loo kodus väike pidulik meeleolu ja tee telefoni mälus ruumi uute fotode jaoks!'),
('9e145532-f5a6-48ed-a07c-a3e9fc574858'::uuid,'Укалоо убактысы 💆‍♂️','Бала уктагандан кийин, күндүн чарчоосун басуу үчүн жолдошуңуз менен бири-бириңизге ийин массажын жасаңыз. Сиздер командасыздар!','Massaaži aeg 💆‍♂️','Pärast seda, kui beebi magab, maanda päeva stressi õlamassaažiga koos partneriga. Te olete meeskond!'),
('fab52013-4ea8-458f-b397-01341fb91dad'::uuid,'Өзүңүздү кечире турган түн 📝','Бүгүн баарына кыжырданып жатасызбы? Бала уктагандан кийин сезимдериңизди «Маанай күндөлүгүнө» жазып коюңуз. Эртең жаңы жана жаркыраган күн болот.','Õhtu iseendale andestamiseks 📝','Kas täna häirib sind kõik? Kui laps magab, pane oma tunded kirja „Tujupäevikusse“. Homme on uus ja rõõmsam päev.'),
('165064a6-acf5-4848-b342-4a3782635921'::uuid,'Укмуштуудай 400 күн! 🎉','Куттуктайбыз! Сиздер бул укмуштуудай жолду чогуу басып өткөнүңүзгө туптуура 400 күн болду! Бул өзгөчө датаны сөзсүз белгилеңиз!','Imelised 400 päeva! 🎉','Palju õnne! Olete seda uskumatut teekonda koos läbinud täpselt 400 päeva! Tähistage seda erilist verstaposti kindlasti kohe!'),
('894151c3-97b8-419f-9602-aa08da619716'::uuid,'Өз алдынча тамактанууну улантыңыз! 🥄','Төгүп-чачып жатса да, өз кашыгы менен тамактанууга уруксат бериңиз. Бул анын өзүнө болгон ишенимин жана булчуң координациясын өнүктүрөт.','Jätka iseseisvat söömist! 🥄','Isegi kui ta mäkerdab, lase tal proovida oma lusikaga süüa. See aitab arendada enesekindlust ja lihaskoordinatsiooni.'),
('8c8e0b49-c38c-485a-b336-5facb1258a02'::uuid,'Сиз эң мыктысыз! ✨','Акыркы 400 күндө көрсөткөн эмгегиңиз баа жеткис. Эми терең дем алып, артка чалкалап, жай эс алыңыз.','Oled parim! ✨','Pühendumus, mida oled viimase 400 päeva jooksul üles näidanud, on hindamatu. Nüüd hinga sügavalt sisse, nõjatu seljatoele ja lõõgastu vaikselt.'),
('05dbf09b-2a49-4886-a4e4-6f85e7cbea42'::uuid,'Сыртка чыгып сейилдөө ⛅','Балаңыз үйдө тынчсызданып жатабы? Жаратылыш — эң мыкты даба. «Аба ырайы жана кийим» функциясын текшерип, туура кийинип, дароо сейил бакка жөнөңүз.','Seiklus õues ⛅','Kas su laps on kodus rahutu ja viril? Loodus on parim ravim. Vaata funktsiooni „Ilm ja riietus“, vali sobiv kombinatsioon ja suundu kohe parki.'),
('3cf4affc-53f5-4c77-84f1-006d5732e36a'::uuid,'Ата менен ойноо убактысы 👨‍👧','Күн бою балаңыздын артынан чуркап, буттарыңыз ооруп жаткандыр! Эми «Ата режими» келди. Полдо тоголонууну жана ат болуп ойноону атасына тапшырыңыз. Сиз эс алууга татыктуусуз.','Issi mänguaeg 👨‍👧','Pärast seda, kui oled terve päeva oma pisikese järel jooksnud, peavad su jalad küll valutama! Nüüd on aeg „Partneri režiimiks“. Lase isal põrandal rullida ja hobust mängida. Sina väärid puhkust.'),
('f1269e86-21d6-4d2f-83e1-31926957408a'::uuid,'Бөлмөдөн бөлмөгө укмуштуу окуялар 🏃‍♂️','Басуу эми аздык кылат; ал бөлмөдөн бөлмөгө чуркап жүрөт! Анын тең салмактуулугу толук калыптанып жатат. Бул чоң жетишкендикти өнүгүү күндөлүгүнө жазып коюуну унутпаңыз!','Toast-tuppa seiklused 🏃‍♂️','Kõndimisest enam ei piisa; ta tuhiseb nüüd ühest toast teise! Tema tasakaal on täielikult välja arenemas. Ära unusta seda suurt üldmotoorika saavutust arengujälgijasse kirja panna!'),
('7df527b0-7bf7-42d6-b9f4-0f231186e70c'::uuid,'Кичинекей меню диктатору 🥣','Кечээ жакшы көргөн тамагын бүгүн жебей жатабы? 1 жаштан кийин тандап жеген кадыресе көрүнүш. Кабатыр болбоңуз, «Дени сак рецепттер» бөлүмүнөн башка альтернативаларды издеңиз.','Väike menüüdiktatuur 🥣','Kas ta lükkab täna eemale eilse lemmiktoidu? Valiv söömine on pärast 1. eluaastat normaalne. Ära paanitse, uuri erinevaid alternatiive meie jaotisest „Tervislikud retseptid“.'),
('85bb394b-b9a2-4a30-a34a-98479663ff2d'::uuid,'"Бул эмне?" баскычы ☝️','Ал манжасы менен баарын көрсөтүп, өзгөчө үн чыгарып жатабы? Ал сизден дүйнөнү таанытууну суранып жатат! Ал көрсөткөн ар бир нерсенин атын сабырдуулук менен айтып бериңиз.','„Mis see on?“ faas ☝️','Ta näitab kõigele sõrmega ja teeb erilist häält. Ta palub sul oma maailmale nimesid anda! Ütle talle kannatlikult iga objekti nimi, millele ta osutab.'),
('f78a5d11-ba9f-41e9-8557-2840d12964be'::uuid,'Күнөөлүү сезимден арылыңыз 📝','Бүгүн аз окудум, экранды көп карады... Бул ойлорду кууп салыңыз! Сиз колуңуздан келгендин баарын жасап жатасыз. Маанай күндөлүгүңүзгө өзүңүзгө карата жылуу сөздөрдү жазыңыз.','Lase süütundest lahti 📝','Täna ma ei lugenud piisavalt, ta vaatas liiga palju ekraani... Vaigista need mõtted! Sa annad endast parima. Kirjuta endale oma tujupäevikusse üks südamlik märkus.'),
('1167974e-3206-4f0f-b4e8-4d14f35444b6'::uuid,'Өз алдынча уктоого өтүү 🥱','Эртең менен уктагысы келбей, тартипти бузуп жатабы? Бул өсүү белгиси! Балким, ал эки жолу уктоодон бир жолу уктоого өтүп жаткандыр. Жаңы ыргакты табуу үчүн тартипти акырындап өзгөртүңүз.','Üleminek omaette magamisele 🥱','Ei taha hommikul uinakut teha ja lööb kogu graafiku sassi? See on märk kasvust! Ta võib olla üle minemas kahelt uinakult ühele. Kohanda rutiini järk-järgult, et leida uus rütm.'),
('8017b10d-4bdb-4fe5-8a0b-20ae132c6ec2'::uuid,'Сыйкырдуу бөлмө 🪄','Акылдуу жомоктордо дүйнөнү изилдеген эр жүрөк баатыр жөнүндө өзгөчө окуя ойлоп табыңыз. Бул сүйкүмдүү жомок менен уйкуга өтүүнү жеңилдетиңиз.','Võlumaa 🪄','Loo nutikates muinasjuttudes eriline lugu vaprast kangelasest, kes avastab maailma. Muuda magamaminek selle armsa looga lihtsamaks.'),
('c7ad498c-1a79-4b6f-a5e5-0ac0b264682c'::uuid,'Өзүңүзгө убакыт бөлүңүз, апа ☕','Үйдүн дубалдарын карап тажадыңызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн балдар аянтчасы бар кафени табыңыз. Сиз кофеңизден ырахат алып отурганда, ал ойноп турсун.','Oma ruumi avastamine, emme ☕','Kas oled väsinud kodus samade seinte vaatamisest? Leia „Emadesõbralike kohtade“ alt mängunurgaga kohvik. Lase lapsel mängida, kuni sina kohvi naudid.'),
('d29d33a4-aed4-4635-9f37-3a7a39a378b0'::uuid,'Чек араларды текшерүү. 🛑','«Болбойт» деп айткандан кийин да, ал көзүңүзгө тике карап, тыюу салынган нерсеге колун сунуп жатабы? Бул баш ийбестик эмес, жөн гана чек араларды сынап көрүү. Сабырдуу жана туруктуу болуңуз.','Piiride katsetamine. 🛑','Isegi pärast seda, kui oled öelnud „ei“, kas ta vaatab sulle otse silma ja sirutab ikkagi käe keelatud eseme poole? See ei ole trots, vaid lihtsalt tema viis piire testida. Jää kannatlikuks ja järjepidevaks.'),
('f3355fe9-0c3b-41e2-9043-0a5cb8a61740'::uuid,'Түнкү ойгонуулар. 😴','Тиш жаруу же өсүү мезгили уйкуну бузушу мүмкүн. Зарыл болсо, уйку таймери аркылуу анын тартибиндеги өзгөрүүлөрдү көзөмөлдөп туруңуз.','Öised ärkamised. 😴','Hammaste tulek või kasvuspurt võivad und häirida. Vajadusel jälgi muutusi rutiinis, kasutades unetaimerit.'),
('2e0b0129-5a3d-466c-a35f-ef4707dea065'::uuid,'Атасынын мээрими 🫂','Түнкүсүн кезектешип туруңуз. Кээде караңгыда баланы атасынын ыргактуу сылоосу жана жыты гана заматта соорото алат.','Issi lohutab 🫂','Jagage kindlasti öiseid ärkamisi kordamööda. Mõnikord suudavad vaid isa rütmilised paitused ja lõhn beebit pimeduses kohe rahustada.'),
('812159bf-a0a9-4bf9-8e7b-97d82abbaa80'::uuid,'Кичинекей тууроочу: Чоңдорду тууроо 🧹','Тазалык кылып жатканда, ал чүпүрөк алып сизди туурап жатабы? Ал сиздин кичинекей көчүрмөңүз! Ага коопсуз, балдарга ылайыктуу буюм берип, үй жумуштарына «жардамдашууга» уруксат бериңиз.','Väike matkija: täiskasvanute järeleaimamine 🧹','Kui sa koristad, kas ta haarab lapi ja püüab sind imiteerida? Ta on sinu väike koopia! Anna talle ohutu, lapsesõbralik ese ja lase tal kodutöödes „aidata“.'),
('9510e83b-c10c-4166-b921-d1cd3c8f203c'::uuid,'Унутчаактык менен күрөшүү 🛒','Эсиңизден чыгып кеттиби? Үйдө түгөнүп бараткан ар бир майда-чүйдө нерсени дароо ''Соода тизмесине'' кошуп коюңуз, ошондо жубайыңыз жумуштан кайтып келе жатканда алып келе алат.','Võitlus unustamisega 🛒','Kas mälu vedas jälle alt? Lisa iga kodus otsa saav pisiasi kohe ostunimekirja, et elukaaslane saaks selle töölt tulles kaasa haarata.'),
('0a5f0553-0fcd-480d-a18f-a3ecfcfe950c'::uuid,'Логикалык табышмактар жана оюндар 🧩','Оюнчуктарды кутуга салып, кайра баарын чачып жатышабы? Алар ''ичинде жана сыртында'' деген түшүнүктү изилдеп жатышат! Бул кызыктуу жана кайталануучу эксперименттерди тынч байкап туруңуз.','Loogikamõistatused ja mängud 🧩','Kas ta paneb mänguasju kasti, et need siis jälle välja kallata? Ta avastab mõisteid "sees ja väljas"! Jälgi vaikselt neid põnevaid korduvaid katsetusi.'),
('302bafdb-c5ca-4389-a56e-16a2ddd6812b'::uuid,'Кечки тартиптин күчү 🛀','Жылуу ванна ар дайым кереметтерди жаратат. Кечки тартипти эч качан калтырбаңыз, анткени бул алардын мээсине уктоо убактысы келгенин так билдирет.','Õhtuse rutiini vägi 🛀','Soe vann teeb alati imesid. Ära kunagi jäta õhtust rutiini vahele, sest see annab lapse ajule selge signaali, et on aeg magama minna.'),
('309b39de-d5f5-4702-93e1-596dca9c9021'::uuid,'Энергияңызды калыбына келтириңиз 🥑','Эгер алар курсагын тойгузса, эми кезек сизде. Күнүмдүк шашылыш иштердин арасында түшкү тамакты шашып ичпеңиз. Биздин ''Дени сак рецепттерден'' энергия берүүчү тамак тандап алып, диванга жатып эс алыңыз.','Lae oma akusid 🥑','Kui lapsel on kõht täis, on sinu kord. Ära söö lõunat igapäevase kiirustamise käigus käigupealt. Vali meie tervislike retseptide seast energiat andev vahepala ja siruta end diivanil välja.'),
('66b4bd9b-8226-4190-94c7-9d50f8db6c34'::uuid,'Ичиңизди бошоткуңуз келеби? 💬','Сизди ''Эмне үчүн балам мындай кылып жатат?'' деген ойлор кыйнап жатабы? ''Anacan коомчулугуна'' кошулуңуз, башка энелердин окшош окуяларын окуп, көңүл жубатарлык кептерди табыңыз.','Tahad murest rääkida? 💬','Kas mõte "Miks mu laps seda teeb?" ei anna sulle rahu? Liitu Anacan kogukonnaga, loe teiste emade sarnaseid lugusid ja leia lohutust.'),
('80e6be85-6917-46a0-b283-acc653cca6c1'::uuid,'Кичинекей китепкөй: Барактарды оодаруу 📖','Алар китептердин барактарын оодарып, сүрөттөргө реакция кылып жатышабы? Алардын визуалдык эс тутуму өнүгүп жатат! Биргелешип түстүү жомок китептерин көп окууну унутпаңыз.','Väike raamatusõber: lehekülgede pööramine 📖','Kas ta lehitseb papist raamatuid ja reageerib piltidele? Tema nägemismälu areneb! Lugege kindlasti koos palju värvilisi juturaamatuid.'),
('df1f7c26-41ff-4081-9b25-dae8d38c75e8'::uuid,'Сиз менен өткөн убакыт сонун. ✨','Ар бир күн – бул ар башка укмуштуу окуя. Алар уктап жатканда, кичинекей колдорун карап, бүгүнкү күндөгү кичинекей жеңиштерине жылмайып коюңуз.','Aeg sinuga on imeline. ✨','Iga päev on isemoodi seiklus. Kui ta magab, vaata tema pisikesi käsi ja naerata tema tänastele väikestele võitudele.'),
('52e92eba-b885-4c30-891d-aa6e5379acf9'::uuid,'Өз алдынча тамактанууну талап кылуу 🥄','Алар өз алдынча тамактанууну каалап, кашыкты колуңуздан жулуп жатышабы? Баары чачылышы мүмкүн, бирок бул алардын майда моторикасын өнүктүрүү үчүн өтө маанилүү. Алардын өз алдынча болууга умтулуусун колдоңуз!','Iseseisva söömise nõudmine 🥄','Kas ta haarab sul lusika käest, olles õhinas end ise toita? See tekitab küll segadust, kuid on tema peenmotoorika arenguks ülioluline. Julgusta tema tärkavat iseseisvust!'),
('a26c1e0d-7872-4f7e-9268-2fba22c9203a'::uuid,'Сурооңуз барбы? 🤖','Эгерде 13-14 айлык балаңыздын жүрүм-туруму же өнүгүүсү боюнча суроолоруңуз болсо, Anacan AI жардамчыбыздан заматта кеңеш ала аласыз.','Kas sul on küsimus? 🤖','Kui sul on küsimusi oma 13-14-kuuse lapse käitumise või arengu kohta, saad kohest nõu meie Anacan AI assistendilt.'),
('eb8ab523-6225-489f-8a09-0f37ba40956a'::uuid,'Энергияны сарптаңыз! 🏃‍♂','️ Уктоо алдында аларды чарчатып, тынч уктоосуна жардам берүү үчүн активдүү оюндарды (мисалы, куушмай же топ ыргытуу) ойнотуңуз.','Kuluta veidi energiat! 🏃‍♂','️ Enne uinakut aita tal rahulikult magada, mängides aktiivseid mänge (nagu kull või palli viskamine), mis teda kergelt ära väsitavad.'),
('5d99a4ad-d33f-448d-9f7c-32943cbfa648'::uuid,'Азуу тиштер чыгып жатабы? 🦷','Тиштеринин бүйлөсү шишип, баарын кемирип жатышабы? Азуу тиштери чыгып жаткан болушу мүмкүн. Муздаткычка муздак тиш салгычтарды салып коюңуз!','Kas purihambad on tulemas? 🦷','Kas tema igemed on paistes ja ta närib kõike? Tal võivad tagumised hambad lõikuda. Pista mõned närimisrõngad sügavkülma!'),
('70d7d4ed-5c06-44bc-99e5-3871d07a9510'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктаардан бир саат мурун үйдөгү бардык жарыктарды жана экрандарды өчүрүңүз. Мелатонин гормону тынч жана жарым-жартылай караңгы чөйрөдө гана иштелип чыгат.','Hämarda tuled 🌙','Tund enne magamaminekut lülita välja kõik eredad tuled ja ekraanid. Melatoniin tekib vaid rahulikus ja hämara valgusega keskkonnas.'),
('aa9c9479-f8d5-4149-b7c4-99976958a17c'::uuid,'Кооптуу аймактарды изилдөө ⚡','Алар өсүп, мурда жете албаган текчелерге жете башташты. Телевизор тумбалары, курч бурчтар... Үйүңүздүн коопсуздугун тез арада кайра карап чыгууга убакыт келди!','Ohtlike tsoonide avastamine ⚡','Tal on olnud kasvuspurt ja ta ulatub nüüd riiuliteni, kuhu varem ei küündinud. Telerialused, teravad nurgad... On aeg oma kodu lapseohutus kiiresti üle vaadata!'),
('0872925d-e2d7-471e-ba13-22ee468f0a1f'::uuid,'Күтүүсүз ойгонуулар 😭','Түн ортосунда чыркырап ойгонуп, эч сооронбой жатабы? Көйгөйдүн себебин аныктоо үчүн «Ыйды анализдөө» функциясы аркылуу анын ыйын угуңуз.','Äkilised ärkamised 😭','Kas ta ärkab keset ööd karjudes ja teda ei saa rahustada? Kuula tema nuttu, kasutades nutuanalüüsi funktsiooni, et avastada probleemi põhjus.'),
('1fe0720b-91d5-4dc9-ad61-71e5ff522246'::uuid,'Өсүү секириктери. 📏','Алардын кийимдеринен эле канчалык тез өсүп жатканын сезе аласыз! Дени сак өсүшүн камсыз кылуу үчүн салмагын жана боюнун узундугун ''Трекерге'' жазып туруңуз.','Kasvuhüpped. 📏','Sa tunned juba riiete järgi, kui kiiresti ta kasvab! Märgi tema kaal ja pikkus jälgijasse, et tagada tema tervislik kasv.'),
('ca5a420a-5b8f-49ce-b884-6a219b8b71aa'::uuid,'Кичинекей денедеги чоң сезимдер 🛑','Алар каалаган нерсесин албай калганда жерге жатып алып ыйлап жатышабы? Наристелердин кыялкеч дүйнөсүнө кош келиңиз! Сабырдуу болуңуз, көз караштарыңызды бириктириңиз жана алардын жанында экениңизди сездириңиз.','Suured tunded, väike keha 🛑','Kas ta viskab end põrandale, kui ei saa oma tahtmist? Tere tulemast väikelaste jonnihoogude imelisse maailma! Jää rahulikuks, loo silmside ja anna talle teada, et oled tema jaoks olemas.'),
('005096a2-1549-4208-a331-7e39e1da9587'::uuid,'Жасалма интеллект педиатры 🤖','13,5 айлык кезиндеги өсүү секириктери сизди чарчатып жатабы? Өзүңүздү кыйнабаңыз! Anacan AI''дан педиатр тарабынан бекитилген так тизмени сураңыз.','AI-pediaater 🤖','Kas 13,5-kuuse lapse kasvuspurdid tunduvad kurnavad? Ära väsita end üle! Küsi Anacan AI-lt täpset, lastearstide poolt heaks kiidetud nimekirja.'),
('7de487db-11d1-4c22-8b8d-e58adb31344a'::uuid,'Жөнөкөй көрсөтмөлөрдү аткаруу 🧸','Сиз ''бут кийимиңди алып кел'' десеңиз, алар чын эле барып алып келишеби? Алардын сөз байлыгы жана түшүнүү жөндөмү өсүп жатат! Алар менен дагы көбүрөөк интерактивдүү оюндарды ойноңуз.','Lihtsate juhiste järgimine 🧸','Kui palud tal "tuua oma kingad", kas ta päriselt läheb ja toob need? Tema sõnavara ja arusaamisoskus arenevad mühinal! Kaasa teda veelgi enamatesse interaktiivsetesse mängudesse.'),
('9089b5ba-67c3-48ba-a5c3-8e428c87d9ec'::uuid,'Атасынын шайыр тарабы 🤡','Атасынын күлкүлүү үндөрүнө балага окшоп каткырып күлгөн эч нерсеге тең келбейт! Бүгүн кечинде бул кызыктуу көз ирмемдерди баалаңыз.','Issi mänguline pool 🤡','Miski ei pane beebit nii hästi kihistama kui issi tehtud naljakad hääled! Nautige neid lõbusaid ühiseid hetki täna õhtul.'),
('3170ad10-66c6-4ca0-bf72-80b0daf91373'::uuid,'Жакшы уйку үчүн кечки тартип. 🌙','Күн сайын бир убакта аткарылган кичинекей, туруктуу адаттар (тиш жуу жана жомок окуу сыяктуу) балаңыздын уйкуга өтүүсүн бир топ жеңилдетет.','Õhtune rutiin paremaks uneks. 🌙','Väikesed ja järjepidevad igapäevased harjumused (nagu hammaste pesemine ja unejutu lugemine) iga päev samal ajal võivad muuta sinu pisikese uinumise palju lihtsamaks.'),
('64832db8-28ac-41fb-8d33-21a72b48fa8c'::uuid,'Кызыктуу изилдөөчү! 🔍','Үйүңүздүн ар бир бурчу, ар бир шкафы алар үчүн жаңы дүйнө. Коопсуз чөйрө түзүп, аларга ар бир бурчун изилдөөгө эркиндик бериңиз!','Uudishimulik avastaja! 🔍','Iga nurk ja iga kapp sinu kodus on tema jaoks täiesti uus maailm. Loo turvaline keskkond ja anna talle vabadus avastada selle iga sentimeetrit!'),
('f283f219-7efa-4926-a360-3fb653057b9b'::uuid,'Таза аба, толук энергия! 🌳','Балдардын сыртта энергиясын сарпташы алардын күндүзгү уйкуга жеңил кетишине жардам берет. Паркка чогуу барыңыз.','Värske õhk, täis energiat! 🌳','Laste õues energia kulutamine aitab neil päevaunne palju kergemini jääda. Minge koos parki.'),
('aa01a859-3ad0-4c64-9ef3-4423ccf76d24'::uuid,'"Жок" деген сөздү жакшы көрөбү? 🛑','Алар сиздин ''жок'' деген сөзүңүздү туурап, өздөрү да баарына ''жок'' деп башташы мүмкүн! Бул этапта сабырдуу болуп, аларга кичинекей, алгылыктуу альтернативаларды сунуштоо маанилүү.','Kas sõna „ei“ on lemmik? 🛑','Ta võib hakata sinu "ei"-sid matkima ja ise kõigele "ei" ütlema! Selles etapis on oluline olla kannatlik ja pakkuda talle väikeseid, vastuvõetavaid alternatiive.'),
('b8b7257f-64c5-46a3-b958-ded901da8e8d'::uuid,'Суу ичүүнү кызыктуу кылыңыз! 💧','Балаңызга сууну дайыма кызыктуу, түстүү чөйчөк менен сунуштап туруңуз, өзгөчө активдүү оюндардан кийин суусуздануусуна жол бербеңиз.','Muuda vee joomine lõbusaks! 💧','Paku oma pisikesele regulaarselt vett lõbusast ja värvilisest joogitopsist, et ta püsiks hüdreeritud, eriti pärast aktiivset mängu.'),
('d2e6d5c6-90cf-4a42-ae18-383c2c592a7c'::uuid,'Атанын жомок айтып берүү убактысы. 👨‍🍼','Бүгүн кечинде жомок окуу жана уктатуу милдетин атасына өткөрүп бериңиз да, өзүңүзгө татыктуу эс алуу тартуулаңыз.','Issi unejutud. 👨‍🍼','Anna unejutu lugemine ja teki peale panemine täna õhtul issi hooleks ning luba endale üks igati väljateenitud väike puhkus.'),
('4484d3ee-8677-4454-8e65-371ba851a267'::uuid,'Ак ызы-чуунун (white noise) күчү. 🎶','Эгерде балаңыз активдүү күндөн кийин тынчтана албай жатса, ''Ак ызы-чуу'' (White Noise) функциясынан океандын же жамгырдын үнүн коюп, бөлмөдө тынч атмосфера түзүңүз.','Valge müra vägi. 🎶','Kui sinu pisike ei suuda pärast aktiivset päeva rahuneda, loo toas rahustav atmosfäär, mängides valge müra funktsioonist ookeani- või vihmahelisid.'),
('b03cef74-ad4c-4ee6-86e3-5d55fe15d1fd'::uuid,'Жылуу кучактоолор! 🤗','Алардын күтүлбөгөн жерден кучактап, өпкүлөөгө аракет кылышы – бул алардын сүйүүсүн билдирүүнүн таттуу жолу. Бул теңдешсиз көз ирмемдердин ар бирин баалаңыз!','Magusad kallistused! 🤗','Tema ootamatud kallistused ja katsed sulle musi anda on tema armas viis armastust avaldada. Naudi iga viimast kui üht neist võrreldamatutest hetkedest!'),
('fb1bbc34-c7a1-41dc-b4eb-e7444cbade21'::uuid,'Сүйлөөгө үндөңүз 🗣','️ Бөлмөдөгү нерселердин аттарын атап, балаңызды аларды кайталоого үндөңүз. Бул жөнөкөй жана кызыктуу оюндар аркылуу алардын сөз байлыгы өсөт!','Julgusta rääkima 🗣','️ Nimeta toas olevaid esemeid ja julgusta oma pisikest neid kordama. Tema sõnavara puhkeb nende lõbusate ja lihtsate mängude abil õitsele!'),
('35a5e175-d9f9-4d9a-9445-a523d64bc595'::uuid,'Өз алдынча тамактангысы келет 🥦','Бир аз чачылса да, кашыкты өздөрүнө карматыңыз! Бул алардын өз алдынчалык сезимин өстүрөт жана кол-көз координациясын өнүктүрөт.','Tahab iseseisvalt süüa 🥦','Isegi kui see tähendab väikest segadust, luba tal ise lusikat hoida! See julgustab tema iseseisvust ja arendab käe-silma koordinatsiooni.'),
('66beeaaa-0b78-4114-b41f-8d7e6f407c55'::uuid,'Сиз эс алууга татыктуусуз. 🛁','Сиз күнү бою бутуңузда жүрдүңүз. Балаңыз уктагандан кийин, өзүңүзгө жылуу чай демдеп, тынчтыктан ырахат алыңыз.','Sa väärid lõõgastust. 🛁','Oled terve päeva jalul olnud. Kui beebi on uinunud, tee endale tass sooja teed ja lihtsalt naudi vaikust.'),
('979d3d6f-0938-49ad-b47d-0cedcf8c1cf6'::uuid,'Ыкчам кадамдарды таштоодо! 🏃‍♂','️ Алар эми бөлмөлөрдүн ортосунда эркин жүрүшөт, ал тургай чуркоого аракет кылышууда! Алардын артынан жетишүү апалар үчүн олуттуу көнүгүүгө айланууда!','Kiired sammud! 🏃‍♂','️ Ta liigub nüüd vabalt tubade vahel ja proovib isegi joosta! Temaga sammu pidamine on emadele juba tõsise trenni eest!'),
('1008f62b-ef11-490d-886c-a80a06e64454'::uuid,'Көзүң кайда? 👀','''Дене мүчөлөрү'' оюну дагы деле алардын эң сүйүктүү оюндарынын бири! Аны күзгү алдында ойноп, дагы да кызыктуураак кылыңыз.','Kus on sinu silmad? 👀','Kehaosade mäng on endiselt üks tema suuri lemmikuid! Muuda see veelgi kaasahaaravamaks ja lõbusamaks, mängides seda peegli ees.'),
('2ca5e024-95be-449a-af7e-ee34228f8bca'::uuid,'Пландоо жан дүйнөгө тынчтык берет. 📝','Эртеңкиге пландарыңызды же тамак-аш тизмеңизди бир нече кыска жазуу менен даярдап алыңыз, анан эс алууга даяр болуп, тынч уктоого жатыңыз.','Planeerimine toob meelerahu. 📝','Valmista homne tegemiste nimekiri või toiduplaan mõttes paari väikese märkme abil ette, seejärel mine voodisse lõdvestunult ja puhkuseks valmis.'),
('efb1280f-e8f0-4ecf-bb77-385f667aff5d'::uuid,'Сооронуч издөө ☕','Кээде жөн гана сыртка чыгып, чөйрөнү өзгөртүү керек болот. Жакын жердеги балдарга ылайыктуу кафени табуу үчүн ''Апаларга ыңгайлуу жайлар'' функциябызды колдонуп, кофеңизден ырахат алыңыз.','Lohutuse otsimine ☕','Mõnikord on lihtsalt vaja välja saada ja keskkonnavahetust nautida. Kasuta meie emasõbralike kohtade funktsiooni, et leida lähedal asuv lapsesõbralik kohvik ja nautida oma kohvi.'),
('47368a03-c0f0-4e5c-a343-b4577d2ffa64'::uuid,'Түнкү бейпилдик 🛀','Жылуу ванна, жеңил массаж жана бөлмөнүн жарыгын өчүрүү. Уйкунун туруктуу тартибин сактоо – үзгүлтүксүз түндөрдүн негизги сыры.','Öine rahu 🛀','Soe vann, õrn massaaž ja toatulede hämardamine. Järjepideva unerutiini hoidmine on katkematute ööde peamine saladus.'),
('8edf71cc-a90b-4465-947f-070adc35b5f7'::uuid,'Музыкага бийлөө 🎶','Телевизордон ритмдүү музыка угары менен алар жамбаштарын булгалап башташат! Алардын музыкалык сезими өсүп жатат, андыктан аларга кошулуп бийлеңиз!','Muusika saatel tantsimine 🎶','Niipea kui ta kuuleb telerist rütmikat heli, hakkab ta tagumikku nõksutama! Tema muusikataju on puhkemas, nii et löö kampa ja tantsi koos temaga!'),
('1e376436-3f0d-4a14-a96b-e1c16c40c937'::uuid,'Уйкуга сезимталдык 🤫','Балаңыз уктап баратканда эле эң кичинекей үндөн чочуп кетеби? Бөлмөнүн акустикасын текшерип, терезеден келген үндөрдү басуу үчүн ак ызы-чуу (white noise) коюп көрүңүз.','Tundlikkus une suhtes 🤫','Kas sinu pisike võpatab vähimagi heli peale kohe, kui ta on uinunud? Kontrolli toa akustikat ja proovi mängida valget müra, et neutraliseerida aknast tulevaid helisid.'),
('b83f22c8-15c6-43cf-9689-94f8a790e4b9'::uuid,'Ымыркайдын алгачкы тамак татып көрүүсү','Кечээ эле сүйүнүп жеген тамагын бүгүн жебей жатышабы? Эгер тиш чыгуу көйгөйү жок болсо, бул жөн гана эркин сынап жатышы мүмкүн! Даамдуу жана түстүү ''жашыруун жашылчалуу'' котлет рецепттерибизди карап көрүңүз.','Beebi esimesed toidukatsed','Kas ta sülitab välja kõik, mida ta eile isuga sõi? Kui hammaste tulekuga probleeme pole, võib see olla lihtsalt tahtejõu proovilepanek! Vaata meie tervislikke retsepte, et leida maitsvaid ja värvilisi "peidetud köögiviljadega" kotlettide retsepte.'),
('fe01f44d-664a-4a34-8ce6-39e87f7fdab2'::uuid,'Беш мүнөттүк кыял ⏱️','Алар ''дагы 5 мүнөт карайын'' дешет, бирок алардын оюнда 5 мүнөт деген түшүнүк жок. Телефонуңузга таймер коюп, үн чыкканда бүтөрүн айтыңыз. Технология ''жаман'' болсун, сиз эмес.','Viieminutiline fantaasia ⏱️','Ta ütleb: "Ainult 5 minutit veel vaatan," aga tema peas pole 5 minutit olemas. Pane telefonis taimer käima ja anna talle teada, et aeg on läbi, kui heli kostab. Las tehnoloogia olla "paha poiss", mitte sina.'),
('0cd42656-20ce-4f47-aca2-4978ae93880d'::uuid,'Горшокко үйрөнүүдө артка кетүүбү? 🚽','Горшокко отурганды үйрөнүштү эле, эми кайра эле кырсыктар болуп жатабы? Бул абдан кадимки көрүнүш. Аларды кыйнабаңыз. Бул психологиялык тоскоолдукту стресссиз жеңүү жолдорун Anacan AI''дан сураңыз.','Tagasilöök potitreeningul? 🚽','Ta õppis potil käima, aga nüüd juhtub jälle äpardusi? See on täiesti normaalne tagasilöök. Ära avalda talle survet. Küsi Anacan AI-lt, kuidas ületada see psühholoogiline takistus ilma jonnihoogudeta.'),
('3164bc6c-fe7e-4273-94e8-6750bee50d0a'::uuid,'Блогдордон илхам алуу 📱','35 айга жакындап калган баладан кандай өнүгүү секириктерин күтсө болот? Кайсы көндүмдөрдү өздөштүрүшү керек? Тиркемедеги өнүгүү блогдорун окуп, балаңыздын жетишкендиктерине кубаныңыз!','Inspiratsiooni leidmine blogidest 📱','Milliseid arenguhüppeid võid oodata 35-kuuseks saavalt lapselt? Milliseid oskusi peaks ta omandama? Vaata äpi arengublogisid ja tunne rõõmu sellest, kui suuri edusamme sinu pisike teeb!'),
('4d45db57-1817-4fc6-ad71-f2aeb4cd1050'::uuid,'Жеңишиңизге даярдануу 💆‍♂️','Бала уктагандан кийин, эртеңки чоң күн үчүн бири-бириңиздерди куттуктап, ийиндериңизге жеңил массаж жасаңыз. Өзгөчө күнүңүзгө керектүү энергия үчүн экөөңүздөр тең эс алып, күч топтошуңуздар керек.','Valmistumine sinu võidukäiguks 💆‍♂️','Pärast lapse uinumist õnnitlege elukaaslasega teineteist homse suure verstaposti puhul ja tehke teineteisele väike õlamassaaž. Teie eriliseks päevaks vajaliku energia jaoks peate mõlemad puhkama ja akusid laadima.'),
('41e90866-d00f-459e-8936-e28d83f9d539'::uuid,'Уктоочу бөлмөдөгү тентектиктер 🏃‍♂️','Алар уктабай диванга секирип жатышабы? ''Суу ичем'' деген шылтоолор бүтпөй жатабы? Уйку таймерин иштетип, чек араңызды бекем сактаңыз.','Magamistoa seiklused 🏃‍♂️','Kas ta hüppab magamise asemel diivanil? Kas vabandused stiilis "ma tahan veel vett" on lõputud? Pane unetaimer käima ja hoia kindlalt oma piire.'),
('4f9eced2-7736-4f35-ad7d-6205edaad1e4'::uuid,'Ата менен ойноо убактысы! 👨‍👧','Эне болуу – бул чексиз марафон эмес. Бүгүн балаңыздын атасы менен паркта энергиясын сарптоосуна уруксат бериңиз, ал эми сиз диванда өзүңүзгө арналган баалуу убакыттан ырахат алыңыз.','Issi mänguaeg! 👨‍👧','Emadus ei ole lõputu maraton. Lase lapsel täna koos issiga pargis energiat kulutada, samal ajal kui sina naudid diivanil väärtuslikku aega iseendale.'),
('e18107ed-4459-4f40-b466-2d79ae0ff98c'::uuid,'Жайында кышкы баш кийим 🧢','Алар аба ырайына такыр туура келбеген кийимди кием деп өжөрлөнүп жатышабы? Өз алдынча болуу үчүн күрөштүн бул этабында аларга кичинекей, тандоого боло турган альтернативаларды сунуштаңыз.','Talvemütsid suvel 🧢','Kas ta nõuab kindlalt millegi sellise kandmist, mis ei sobi üldse ilmaga? Selles tärkavas iseseisvusvõitluses paku talle hoopis väikeseid ja jõukohaseid valikuid.'),
('37ca7eb9-999f-4245-9a90-94f0e28e6df4'::uuid,'Түгөнбөгөн суроолор','Башыңызда тынымсыз «Эмне үчүн?» жана «Кантип?» деген суроолор айланып жатабы? Anacan AI алардын кызыккан суроолоруна сабырдуулук жана логика менен жооп берүүгө кантип жардам берерин билип алыңыз. Сиздин сабырдуулугуңуз алардын өнүгүүсүнө чоң салым кошот.','Lõputud küsimused','Kas „Miks?“ ja „Kuidas?“ küsimused keerlevad sul pidevalt peas? Avasta, kuidas Anacan AI aitab sul nende uudishimulikele küsimustele kannatlikult ja loogiliselt vastata. Sinu kannatlikkus toetab tõeliselt nende arengut.'),
('70e9f70c-b53f-462f-9274-badc9beebd25'::uuid,'Жымжырттык күндөлүгү 📝','Үйдөгү кичинекей «бороон» акыры тынчыды. Эми телефонуңузду алып, бүгүнкү күндү аман-эсен өткөргөнүңүз үчүн Маанай күндөлүгүнө өзүңүзгө ыраазычылык кат жазыңыз. Сиз укмуштуудай иш жасап жатасыз!','Vaikuse päevik 📝','Väike kodune orkaan on lõpuks vaibunud. Nüüd haara telefon ja kirjuta meeleolupäevikusse tänusõnad iseendale, et tänase päeva üle elasid. Sa oled suurepärane!'),
('cac1efaa-10e1-4f19-b586-507cb8610102'::uuid,'Чек араларымды белгилөө 🛑','Балаңыз өзү боосун байлагысы келип, ал 10 мүнөткө созулуп жатабы? Шаштырбаңыз, убакыт бериңиз. Алардын аракеттери жана каталары келечектеги көйгөйлөрдү чечүү жөндөмүнүн пайдубалы болуп саналат.','Oma piiride seadmine 🛑','Sinu laps tahab ise paelu siduda ja see võtab 10 minutit? Ära kiirusta teda, anna talle aega. Tema katsed ja eksimused on tulevaste probleemilahendusoskuste vundament.'),
('078ff563-48f3-4bd6-81ac-93fc21a3bab7'::uuid,'Кофе жана медитация ☕','Бөлмө чачылып жатабы? Тазалоону бир азга унутуңуз. Балаңыз көңүлдүү ойноп жатканда, диванга отуруп, ысык кофеңизден ууртап, эс алуу үчүн 10 мүнөт дубалды карап отуруңуз.','Kohv ja meditatsioon ☕','Kas tuba on täielikus segaduses? Unusta koristamine hetkeks. Seni kuni laps on rõõmsalt ametis, istu diivanile, rüüpa kuuma kohvi ja vaata lihtsalt 10 minutit seina, et oma mõtteid värskendada.'),
('9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a'::uuid,'Көлөкө менен ойноо 🐰','Уктагысы келбей жатабы? Бөлмөнү толугу менен караңгылатып, колуңуз менен дубалга көлөкө театрын жасаңыз. Бул караңгылыктан коркууну жеңүүнүн эң кызыктуу жолу.','Varjuteatri lõbu 🐰','Ei taha magama minna? Tee tuba täiesti pimedaks ja loo kätega seinale varjuteater. See on kõige lõbusam viis pimedusehirmu ületamiseks.'),
('4ab501ea-956f-4adc-a27e-2e2bc99f59c6'::uuid,'Дене-арт укмуштуу окуялары 🖍️','Кээде бир нече секунддук тынчтык коркунучтуу болушу мүмкүн. Бөлмөгө кирип, балаңыз өзүнүн колуна маркер менен «татуировка» жасап жатканын көрдүңүзбү? Терең дем алыңыз. Алардын майда моторикасы өнүгүп жатат, ал эми теридеги боёк жуулат.','Kehakunsti seiklused 🖍️','Mõnesekundiline vaikus võib vahel ohtlik olla. Läksid tuppa ja leidsid nad endale vildikatega tätoveeringuid joonistamast? Hinga sügavalt sisse. Nende peenmotoorika areneb ja nahk saab niikuinii puhtaks.'),
('93712bd1-e114-4739-841f-9d8901785feb'::uuid,'Ата-өнөктөш 👨‍👧','Кечинде энергияңыз түгөнүп калабы? Өзүңүзгө: «Мен бул кырдаалдан чыгып жатам» деп айтыңыз да, кичинекейиңизди атасына өткөрүп бериңиз. Экөө чачып салган бөлмөнү жыйноо, бала менен жалгыз алышкандан алда канча оңой.','Partnerist issi 👨‍👧','Kas su energiavarud on õhtuks nullis? Ütle endale: „Ma tõmban end sellest olukorrast välja,“ ja anna väike põnn üle issile. Tuba, mille nad mõlemad sassi ajasid, on sageli lihtsam koristada kui lapsega üksi võidelda.'),
('9a4e49fa-28ce-4422-86d1-9b77699fd24c'::uuid,'Сизге керектүү клетчатка','Алар тынымсыз кыймылдап жүрүшөт, бирок суу ичүүнү көп унутушат. Горшоктогу жыйынтыгына көз салып туруңуз. Эгер ич катуу коркунучу болсо, рационуна сулу жана кара өрүк кошууну ойлонуп көрүңүз.','Sinu kiudainevajadus','Nad on pidevalt liikvel, kuid unustavad sageli vett juua. Jälgi nende potilkäimist. Kui on kõhukinnisuse oht, kaalu kaerahelveste ja ploomide lisamist menüüsse.'),
('2743b373-11c6-4a72-a371-988483c30fb4'::uuid,'Көлөкө коркунучтары 👻','Көчөдө же бөлмөдө күтүлбөгөн жерден ыйлап баштадыбы? Себеби алардын көлөкөсү артынан ээрчип жатканы болушу мүмкүн! 3 жаштарда элестетүү абдан күчөйт. Аларды кучактап, жылмаюу менен көлөкөсү менен тааныштырып коюңуз.','Varjukollid 👻','Hakkas äkki tänaval või toas nutma? Põhjus võib olla selles, et vari järgneb neile! Umbes 3-aastaselt muutub kujutlusvõime imeliselt elavaks. Kallista neid ja tutvusta neile naeratades nende varju.'),
('344cf14d-0511-4f06-86bb-38e1e79297c3'::uuid,'Кичинекей тамак изилдөөчү','Тамагын жебей, майда кесектерди же жашылчаларды кылдаттык менен бөлүп жатабы? Биздин тамактануу планыбызды карап чыгыңыз жана жашылчаларды пюре кылып, байкатпай кошуунун амалдарын үйрөнүңүз!','Väike toidumaadeavastaja','Nad ei söö toitu, vaid eraldavad kirurgilise täpsusega pisikesi tükke või rohelisi tükikesi? Sukeldu meie toitumiskavasse ja avasta nutikaid viise, kuidas köögivilju püreestades toidu sisse peita!'),
('85bf1b2b-8bd2-41a8-8e81-bd414469ff03'::uuid,'Эски оюнчуктар менен коштошуу 🧸','Уктаар алдында оюнчук машинеси, отургуч, атүгүл эшиктин туткасы менен коштошкусу келеби? Бул алардын жаңыдан калыптанган уктоо алдындагы ырым-жырымы, аларды шаштырбаңыз.','Hüvasti jätmine vanaga 🧸','Enne magamaminekut tahavad nad head ööd soovida mänguautole, toolile ja isegi ukselingile. See on üks nende uutest õhtustest rituaalidest, ära kiirusta neid.'),
('0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6'::uuid,'Жымжырттыктын баасы 🤫','Акыры укташты. Эми үйдөгү эң кичинекей дабыш да аларды ойготуп жиберчүдөй сезилет. Үн өлчөгүчтү (Sound Meter) колдонуп бөлмөдөгү ызы-чууну көзөмөлдөп жатканда, фондо бир калыптагы ак ызы-чууну (white noise) коюп коюңуз.','Vaikuse väärtus 🤫','Nad on lõpuks uinunud. Nüüd võib isegi vähim heli majas tunduda häirivana. Samal ajal kui kasutad helimõõdikut toa mürataseme jälgimiseks, mängi taustaks pidevat valget müra.'),
('bf9527d0-d7b0-4cb8-8523-c499e2e95693'::uuid,'Саноону баштоо','Кичинекейиңиз тепкичтен чыгып жатып же оюнчуктарын иретке келтирип жатып «бир, эки, үч» деп санаганга аракет кылып жатабы? Математикалык ой жүгүртүүнүн пайдубалы түптөлүп жатат! Бөлмөдөгү буюмдарды чогуу үн чыгарып санап машыгыңыз.','Loendama õppimine','Kas su väike laps üritab trepist üles ronides või mänguasju sorteerides lugeda „üks, kaks, kolm“? Matemaatilise mõtlemise alused on pandud! Harjutage koos esemete lugemist toas.'),
('ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5'::uuid,'Чарчоо менен күрөшүү 🔋','Баарына кыйкырып жибергиңиз келеби? Бул күйүп кетүү (burnout) белгиси болушу мүмкүн. Anacan коомчулугуна кошулуп, «Мен абдан чарчадым» деп жазыңыз. Ошол эле учурда миңдеген аялдар сизди түшүнүп жатканын көрөсүз.','Võitlus läbipõlemisega 🔋','Kas tunned, et tahaksid kõige peale karjuda? Võid kogeda läbipõlemist. Liitu Anacani kogukonnaga ja kirjuta „Olen nii väsinud“. Näed, et tuhanded naised tunnevad samal hetkel samamoodi.'),
('405360f8-7a97-471c-825c-355eafed365d'::uuid,'Күндүз уктоодон баш тартуу 🥱','Балаңыз күндүз уктоодон баш тартып, каршылык көрсөтүп жатабы? Кээ бир балдар 3 жашында күндүзгү уйкудан баш тартышат. Күндүзгү уйкуну «уйкусуз тынч убакыт» менен алмаштырып көрүңүз.','Keeldumine uinakust 🥱','Kas laps keeldub uinakust ja võitleb sellele pidevalt vastu? Mõned lapsed jätavad uinaku vahele umbes 3-aastaselt. Proovi uinak asendada „uinakuvaba vaikse ajaga“.'),
('c0c8236b-5e7c-45b1-a5c1-d45f005b603c'::uuid,'Эмоционалдык жеңилдик. 📝','Кээде баары ашыкча сезилиши мүмкүн. Сезимдериңизди жана чарчооңузду Маанай күндөлүгүнө жазып, күндүн стрессинен арылыңыз.','Emotsionaalne vabanemine. 📝','Mõnikord võib kõik tunduda liiga koormav. Vabane päeva stressist, kirjutades oma tunded ja kurnatuse meeleolupäevikusse.'),
('6740b19e-f070-42e2-9b6e-76434890c90f'::uuid,'Эскерүүлөр ойгонот','Балаңыз «Биз кечээ чоң апаныкына бардык» деп өткөн окуялар тууралуу сүйлөмдөрдү түзүп жатабы? Алардын убакытты түшүнүүсү жана узак мөөнөттүү эс тутуму өнүгүп жатат. Алардын эскерүүлөрүн чын дилден угуп, кызыктуу суроолорду бериңиз.','Mälestused ärkavad','Kas su laps moodustab lauseid minevikusündmustest, nagu „Käisime eile vanaema juures“? Nende ajataju ja pikaajaline mälu on tõeliselt õitsele puhkemas. Kuula nende mälestusi siira huviga ja esita kaasahaaravaid küsimusi.'),
('f0257b2e-d5f4-40d8-9701-488c186af81f'::uuid,'Уйкусунда ыйлап жатабы?','Аларды ойготпоңуз. «Ыйды талдоо» (Cry Analysis) функциясын колдонуп, бул жөн гана түнкү коркунуч экенин текшериңиз, анан акырын жанында болуңуз.','Kas nutab unes?','Ära proovi neid äratada. Kuula nende nuttu „Nutuanalüüsi“ funktsiooni abil, et veenduda, kas tegemist on öise hirmuhoo või muu põhjusega, ja jää siis vaikselt nende kõrvale.'),
('268f32e3-3ad0-45c0-aef4-aba7ce610179'::uuid,'Ашканадагы кырсыктар 🧑‍🍳','Тамак жасап жатканда, мештин жанында туз кошуп «жардам бергиси» келеби? Эгер уруксат берсеңиз, тамак бузулат; бербесеңиз, ыйлайт. Ага бош идиш менен бир аз суу берип, өзүнүн «шорпосун» бышырууну сураныңыз.','Köögikatastroofid 🧑‍🍳','Kas nad nõuavad süüa tehes pliidi ääres soola lisamisega „aitamist“? Kui lubad, läheb toit untsu; kui ei luba, hakkavad nad nutma. Anna neile tühi kauss ja veidi vett ning ütle, et nad „keedaksid“ oma suppi.'),
('1da71143-b8dd-434a-bf23-b7f16a2d4a80'::uuid,'Өз алдынча ичүү','Балаңыз сууну же сүттү өзү куюуга аракет кылып, натыйжада баары төгүлүп жатабы? Терең дем алыңыз! Бул «башаламандык» чындыгында алардын кол-көз координациясын жана өзүнө болгон ишенимин өнүктүрүү үчүн баа жеткис мүмкүнчүлүк. Ага чүпүрөк берип, экөөңүздөр чогуу акырын тазалап алыңыз.','Sõõm iseseisvust','Kas laps nõuab, et saaks ise vett või piima tassi valada, mille tulemuseks on suur lomp? Hinga sügavalt sisse! See „kaos“ on tegelikult hindamatu võimalus arendada käe-silma koordinatsiooni ja enesekindlust. Anna neile lapp ja koristage vaikselt koos.'),
('7f1b27a1-aff6-4522-ba4e-76bb08fa648e'::uuid,'Ызы-чуудан арылуу (детокс) 🎧','Кулагыңызда «Апа, апа, апа!» деген үн жаңырып жатабы? Өзүңүзгө кичине тыныгуу бериңиз. Балаңызды 15 мүнөткө коопсуз жана кызыктуу иш менен алек кылып, кофеңизди тынчтыкта ичип алыңыз. Сиздин да энергияңызды толуктоо керек.','Müradetoks 🎧','Kas „Emme, emme, emme!“ kõlab su peas? Anna endale väike paus. Jäta laps 15 minutiks ohutusse ja kaasahaaravasse tegevusse ning naudi kohvi täielikus vaikuses. Sinu aku vajab samuti laadimist.'),
('9ebeb631-4aa4-4310-b78e-47bee6920a4e'::uuid,'Чоюнууну кызыктуу кылуу 🛁','Ваннага киргиси келбей, жерде тоголонуп жатабы? «Сени жуунтуп алайын» дебей, «Кел, сүйүктүү машинелериңди (же куурчактарыңды) жуунтуп алалы» деп айтыңыз. Ар бир милдетти оюнга айландыруу – баланын эң алсыз жери.','Muuda vanniskäik lõbusaks 🛁','Ei taha vanni minna ja protestiks põrandal püherdada? Selle asemel, et öelda „Lase ma pesen sind“, ütle: „Lähme peseme su lemmikautosid (või nukke).“ Iga mänguks muudetud kohustus on lapse suurim nõrkus.'),
('5188ae48-9680-4372-a0c2-b6a14d87d513'::uuid,'Үйдөгү бут кийим драмасы','Кичинекейиңиз сырткы бут кийимин үйдүн ичинде кийгиси келип, чечпей жатабы? Бул үчүн урушууга арзыбайт! Таманын нымдуу чүпүрөк менен сүртүп, бир нече саат бою үйдө сыймыктануу менен басып жүрүүсүнө уруксат бериңиз. Кээде кичинекей «жеңилүү» – ата-эненин эң чоң жеңиши болушу мүмкүн.','Kodune kingadraama','Kas su väike laps nutab, sest tahab õuejalatseid toas kanda ja keeldub neid ära võtmast? See pole võitlust väärt! Pühi tallad niiske lapiga üle ja lase neil paar tundi uhkelt toas ringi marssida. Mõnikord on väikese lahingu teadlik „kaotamine“ lapsevanema suurim võit.'),
('a80b1c35-a6ce-48dc-a430-2268378d43f5'::uuid,'Атанын кезеги 👨‍🍼','Күнү бою «болбойт» деп айтып, эреже коюудан чарчадыңызбы? Бүгүн кечинде пижама кийгизүү жана тиш жуу милдетин атасына өткөрүп бериңиз. Уктоочу бөлмөнүн эшигин жаап, бүгүнкү сезимдериңизди «Маанай күндөлүгүнө» жазып, убакытты өзүңүзгө арнаңыз.','Nüüd on issi kord 👨‍🍼','Oled väsinud terve päeva „ei“ ütlemisest ja reeglite seadmisest? Anna täna õhtul pidžaama- ja hambapesulahing üle issile. Sulge magamistoa uks ja pühenda aega vaid endale, kirjutades tänased tunded oma „Meeleolupäevikusse“.'),
('f6d030df-f5ef-4ef7-84fc-04dd7126bef2'::uuid,'Жылмаюу аркылуу байланышуу 💬','Балаңыздын кыяңкечтиги бүгүн сизди абдан чарчаттыбы? Дароо Anacan коомчулугун ачып, башка энелердин үйлөрүндөгү окшош же андан да күлкүлүү окуяларды окуңуз. Окшош кырдаалдарды башыңыздан өткөрүп жатканыңызды жана жалгыз эмес экениңизди билүү – эң мыкты психологиялык колдоо.','Naeratuste kaudu ühendumine 💬','Kas lapse jonnihood kurnasid sind täna täielikult? Ava kohe Anacani kogukond ja loe teiste emade sarnaseid või veelgi naljakamaid kriisilugusid. Teadmine, et läbid sarnaseid kogemusi ja pole üksi, on parim psühholoogiline tugi.'),
('e612b840-bcec-4199-920b-e4d2f37aa7cb'::uuid,'Тизмеңизди текшерүү','Маараке күнү үчүн керектүү нерселердин баарын соода тизмеңизге коштуңузбу? Шарлар жана кичинекей белектер да тизмеде бар экенин текшериңиз! Өнөктөшүңүзгө акыркы эскертүүнү түздөн-түз колдонмо аркылуу жөнөтүңүз.','Oma nimekirja kontrollimine','Kas oled lisanud ostunimekirja kõik aastapäevaks vajaliku? Veendu, et õhupallid ja väikesed üllatused on ka kirjas! Saada partnerile viimane meeldetuletus otse äpist.'),
('eb50f918-4009-4323-94a0-e8fd1ccc9f1d'::uuid,'Уйку үчүн жарыкты көзөмөлдөө 🤫','Уктагандан кийинки биринчи жарым саат – мээ эң активдүү иштеген убакыт. Бөлмөнү жөнгө салуу үчүн үн өлчөгүчтү колдонуңуз. Терезеден келген үндөрдү басаңдатып, толугу менен тынч жана караңгы чөйрөнү түзүңүз.','Valguse jälgimine une jaoks 🤫','Esimene pooltund pärast uinumist on aeg, mil aju on kõige aktiivsem. Kasuta toa reguleerimiseks helimõõdikut. Neutraliseeri aknast tulevad helid ja loo täiesti vaikne ja pime keskkond.'),
('0cde3d33-fabc-43f7-bcba-b8c6c307e26e'::uuid,'Өз окуяңызды өзүңүз түзүңүз 🪄','Акылдуу жомокторду (Smart Stories) ачып, бүгүн кечинде сюжетти алар башкарсын. «Эми каарман кайда барышы керек?» деп сураңыз. Алар өздөрү жараткан укмуштуудай кызыктуу аягы менен уйкуга кетишсин.','Oma loo lavastamine 🪄','Ava Nutikad lood ja lase neil täna õhtul süžeed juhtida. Küsi: „Kuhu kangelane nüüd minema peaks?“ Lase neil uinuda nende endi loodud imeliselt absurdse lõpuga.'),
('0fa7eced-c60c-4055-8da1-5df4e54ec1ce'::uuid,'Мен сүйлөп жатам! 🗣️','«Ба-ба» же «ма-ма» сыяктуу муундарды айтып жатышабы? Өнүгүү трекерин ачып, тил өнүгүүсүндөгү бул маанилүү этапты жазып алыңыз жана алар менен сүйлөшүүнү улантыңыз!','Ma räägin! 🗣️','Kas nad lalisavad silpe nagu „ba-ba“ või „ma-ma“? Ava arengujälgija, märgi see oluline keeleline verstapost ja jätka nendega vestlemist!'),
('60a51ebc-ca29-4910-bc60-cd0880a0539a'::uuid,'Таң калыштуу көз жаш 🐶','Көчөдө көргөн ити аларды карабай койгону үчүн 15 мүнөт ыйлаштыбы? Логика издебеңиз. Алар үчүн бул чындыгында терең кайгы. «Билем, сен ал иттин сени карашын абдан каалагансың» деп, алардын сезимдерин кабыл алыңыз.','Segadust tekitavad pisarad 🐶','Kas nad nutsid 15 minutit, sest tänaval nähtud koer ei vaadanud nende poole? Ära otsi loogikat. Nende jaoks on see tõeliselt sügav kurbus. Kinnita nende tundeid, öeldes: „Ma tean, sa tahtsid väga, et see koer sind vaataks.“'),
('4c8a3a5d-e5df-48ed-823d-41dd50a6bc1d'::uuid,'Өбүү тартуулоо! 👋','Кичинекейиңиз адамдар кетип жатканда аң-сезимдүү түрдө кол булгалап, өбүү тартуулап жатабы? Бул сүйкүмдүү жана социалдык жаңсоолорду баалаңыз!','Õhusuudluste saatmine! 👋','Kas su väike laps lehvitab nüüd teadlikult „head aega“ ja saadab inimestele õhusuudlusi? Naudi neid imearmsaid ja sotsiaalseid žeste!'),
('e0a781fd-ff93-41bb-aced-df42a4ca9525'::uuid,'Үйдөгү башаламандыкты кабыл алуу','Бөлмө толугу менен оюнчуктарга толуп кеттиби? Кеп тазалыкта эмес, эң негизгиси – кичинекейиңиз менен өткөрүп жаткан бул бактылуу көз ирмемдер. Оюнчуктар эртең да ошол жерде болот, андыктан өзүңүздү чарчатпаңыз. Кээде башаламандыкка моюн сунуу – эс алуунун эң жакшы жолу.','Koduse kaose omaksvõtmine','Kas terve tuba on mänguasju täis? Asi pole korras; tõeliselt loevad need mängulised hetked, mida veedad oma lapsega. Mänguasjad on homme ka alles, nii et ära kurna end. Mõnikord on segadusele alistumine parim puhkuse vorm.'),
('3a84b553-313a-486c-95e8-2a799895283c'::uuid,'Ыйлаба, алтыным','Кичинекейиңиз сейил бакта ыйлап жаткан башка балага жакындап, аны сооротуп жатабы? Алардын боорукердик сезими расмий түрдө өнүгүп жатат! Бул сонун мээримдүүлүктү чоң сыймык менен байкаңыз.','Ära nuta, mu kallis','Kas su väike laps läheb pargis nutva teise lapse juurde ja lohutab teda õrnalt? Nende kaunis empaatiavõime on ametlikult õitsele puhkemas! Jälgi seda imelist kaastunnet suure uhkusega.'),
('77ff1ffc-86a7-418d-bad4-4d026f199772'::uuid,'Чоңдордун керебетине өтүү убактысы келдиби? 🛏️','Балаңыз бешигинен чыгууга аракеттенип жатабы? Балким, өзгөрүү жасоо убактысы келгендир. Anacan AI''дан коопсуздук эрежелери жана чоңдордун керебетине өтүү үчүн эң ыңгайлуу учур тууралуу сурап көрүңүз.','Kas on aeg suure lapse voodiks? 🛏️','Kas su laps üritab võrevoodist välja ronida? Võib-olla on aeg muudatusteks. Küsi Anacan AI-lt ohutusjuhiste ja suure lapse voodile ülemineku õige aja kohta.'),
('e176efcb-aafc-4480-93eb-e1978282a880'::uuid,'Атанын жомок айтып берүүсү 📖','Бүгүн кечинде үн байламталарыңызга эс бериңиз. Балаңыздын сүйүктүү китептерин ар кандай үндөр жана интонациялар менен окуп берүү милдетин атасына тапшырыңыз.','Issi unejutud 📖','Anna täna õhtul oma häälepaeltele puhkust. Lase isal lugeda lapse lemmikraamatuid erinevate häälte ja toonidega.'),
('2c139fbd-2360-47be-8201-67957bcf1684'::uuid,'Күзгүдөгү кичинекей режиссёр','Кичинекейиңиз күзгү алдында туруп, ар кандай бет кубулуштарын жасап, өзү менен өзү сүйлөшүп жатабы? Ал ар кандай ролдорду жана инсандык сапаттарды изилдеп жатат! Аны байкатпай байкап, бул жагымдуу жана көп учурда күлкүлүү көз ирмемдерден ырахат алыңыз.','Väike lavastaja peeglis','Kas su pisike seisab peegli ees, teeb nägusid ja räägib iseendaga? Ta avastab erinevaid rolle ja identiteete! Jälgi teda diskreetselt ja naudi neid armsaid, sageli koomilisi hetki.'),
('42026a5f-2788-45b9-acb9-1e97ccc1366b'::uuid,'Энергияны толуктоо убактысы 🍲','Тынымсыз шашуу сизди чарчатып койду. Дени сак тамактар бөлүмүнөн өзүңүзгө да, балаңызга да жага турган, темирге жана белокко бай башка бир тамакты тандаңыз.','Aeg energiat ammutada 🍲','Pidev rutt on sind ära väsitanud. Vali tervislike retseptide jaotisest uus raua- ja valgurikas lõunasöök, mis maitseb nii sulle kui ka lapsele.'),
('f413f7f2-f85e-4bd1-a054-6b9d46b4d341'::uuid,'Күнүмдүк маалыматтар 📝','Бала уктаары менен өнөктөшүңүз менен бирге ''Маанай күндөлүгүн'' ачыңыз. Бүгүн балаңыз жасаган эң күлкүлүү окуяны жазып, стресстен арылуу үчүн чогуу күлүңүз.','Igapäevased tarkused 📝','Niipea kui laps magab, ava koos partneriga „Tujupäevik“. Pane koos partneriga kirja kõige naljakam asi, mida laps täna tegi, ja naerge koos, et stressi leevendada.'),
('59d23d62-6dca-4962-aec7-eb093810797b'::uuid,'Уйкуга алып баруучу музыкалык жол 🎶','Кечки тартип оорлошуп баратабы? Жылуу сууга түшүп жатканда, фондо жагымдуу классикалык музыка коюңуз. Суу менен музыканын айкалышы эң тентек баланы да тынчтандыра алат.','Muusikaline tee uneni 🎶','Kas õhtune rutiin on muutumas keeruliseks? Mängi sooja vanni ajal taustaks rahustavat klassikalist muusikat. Vee ja muusika harmoonia võib rahustada ka kõige jonnakama lapse.'),
('605d2ada-99ba-4138-bd88-c091a6c53e2b'::uuid,'''Таптым!'' деген кубаныч','Жашынмак оюну балаңыздын эң сүйүктүү оюнуна айландыбы? Ал көшөгө артына жашынып, сиздин аны табышыңызды чыдамсыздык менен күтүп жатабы? Бул курактагы кызыктуу оюндар аркылуу объекттин туруктуулугу түшүнүгү чыңдалууда.','„Leidsin su üles!“ põnevus','Kas peitusemäng on nüüd su lapse absoluutne lemmik? Kas ta peidab end kardinate taha ja ootab põnevusega, et sa ta üles leiaksid? Selles vanuses kinnistub läbi selliste mängude arusaam asjade jäävusest.'),
('c0738cb9-5d1f-47d6-821c-55b543c58b28'::uuid,'Истериканы башкаруу 🛑','Дүкөндө же сейил бакта балаңыздын ыйлаганы сизди уялтабы? Эсиңизде болсун, башкалардын эмне ойлогону маанилүү эмес, ал учурда балаңыздын сезимдери маанилүү. Жөн гана аны кучактап, тынчтандырыңыз.','Jonnihoogude ohjeldamine 🛑','Kas jonnihood poes või pargis tekitavad piinlikkust? Pea meeles, et teiste arvamus pole oluline – olulised on lapse emotsioonid sel hetkel. Lihtsalt kallista teda vaikselt.'),
('65edab42-e5b4-4da3-8b99-8e271dd3fc16'::uuid,'Жеке чек араларды белгилөө','Балаңыз кимдир бирөө кучактап же өпкөнгө аракет кылганда тартынып же ''жок'' деп айтабы? Анын дене чек арасын ар дайым сыйлаңыз жана башкалардын да сыйлашын камсыз кылыңыз. Бул анын өзүнө болгон ишенимин калыптандыруудагы негизги кадам.','Isiklike piiride seadmine','Kas su laps tõmbub eemale või ütleb „ei“, kui keegi üritab teda kallistada või suudelda? Austa alati tema kehalisi piire ja taga, et ka teised seda teeksid. See on enesekindluse loomise alustala.'),
('c46434f8-d6b6-4038-89e7-8bc38a5332c2'::uuid,'Акылдуу жомоктордун сыйкыры 🪄','Классикалык жомоктордон тажадыңызбы? ''Акылдуу жомокторго'' өзгөчө тема бериңиз: Жашылча жегенди жакшы көргөн сыйкырдуу динозаврдын укмуштуу окуялары.','Nutikate lugude võlu 🪄','Väsinud klassikalistest muinasjuttudest? Anna „nutikatele lugudele“ eriline teema: köögivilju armastava võludinosauruse seiklused.'),
('d941dd67-309a-49cb-833c-78b38c4762e7'::uuid,'Кийинүү дипломатиясы 👗','Балаңыз кыштын ортосунда жайкы шорты кийгиси келеби? Дароо ''Аба ырайы жана кийим'' куралын ачып, экрандагы сүрөттөр аркылуу сыртта суук экенин логикалык жактан түшүндүрүңүз.','Riietumisdiplomaatia 👗','Kas laps tahab keset talve suviseid lühikesi pükse kanda? Ava kohe „Ilma ja riietuse“ tööriist ning selgita ekraanil olevate piltide abil loogiliselt, et väljas on külm.'),
('244e81e4-ef8a-4010-a428-229aabe2c4b0'::uuid,'Өнөктөшүңүздөн жардам сураңыз 🛒','Дүкөнгө барганга убактыңыз жокпу? Соода тизмесин ачып, үйдө эмне керек болсо белгилеңиз жана бир чыкылдатуу менен өнөктөшүңүзгө жөнөтүңүз. Үй-бүлөдө милдеттерди бөлүштүрүү абдан маанилүү.','Palu partneril appi tulla 🛒','Pole aega poes käia? Ava ostunimekiri, märgi üles kõik vajalik ja saada see ühe klõpsuga oma partnerile. Tööjaotus on hädavajalik.'),
('e5509d0f-428a-4a25-9b61-f825746504ad'::uuid,'Тынч окуу убактысы 📖','Бүгүн кечинде бөлмөдө китеп барактарынын шыбыры гана угулсун. Экөөңүздөр тең төшөккө жатып, ал сүрөттүү китебин карасын, сиз болсо унчукпай эс алыңыз.','Vaikne lugemisaeg 📖','Olgu täna õhtul toas ainsaks heliks raamatulehtede krabin. Lebage mõlemad voodis, lase lapsel vaadata pildiraamatut ja naudi ise vaikust.'),
('f568dd40-0374-40d2-8f34-9a863c9b7158'::uuid,'Тайманбас чыгуулар жана секирүүлөр','Кичинекейиңиз дивандан секирип түшүүгө аракеттенип жатабы? Ал кыймыл-аракет жөндөмдүүлүгүнүн өнүгүп жатканын көрсөтүүдө! Тыюу салуунун ордуна, полго жумшак жаздыктарды коюп, коопсуз ''секирүү аймагын'' түзүп бериңиз.','Julged ronimised ja hüpped','Kas su pisike üritab diivanilt alla hüpata? Ta näitab üles suurt enesekindlust oma arenevate motoorsete oskuste suhtes! Keelamise asemel loo talle turvaline „hüppetsoon“, asetades põrandale pehmed padjad.'),
('1222929d-ba35-40ba-92f4-2c3b29988e2e'::uuid,'Эрежелердин чегин сынап көрүү','Балаңыз сиз тыюу салган нерсени көзүңүзгө карап туруп жасайбы? Ал сизди ачуулантууну көздөбөйт, жөн гана сиз койгон чек аралардын бекемдигин сынап жатат. Эрежелериңизди ырааттуу сактоо өтө маанилүү.','Reeglite piiride katsetamine','Kas laps teeb täpselt seda, mida sa keelasid, vaadates sulle samal ajal otse silma? Ta ei ürita sind vihastada, vaid testib su piiride kindlust. Oluline on jääda oma reeglitele kindlaks.'),
('60d686a6-8001-479b-9d53-bcd85bcdffdb'::uuid,'Башаламандыкты кабыл алыңыз 🌪️','Күн сайын бир эле оюнчуктарды жыйнап чарчадыңызбы? Бүгүн аларды жыйнабаңыз! Үйдүн башаламан болушу дүйнөнүн акыры эмес, бирок эненин психологиялык абалы олуттуу маселе.','Lepi segadusega 🌪️','Kas oled väsinud iga päev samade mänguasjade koristamisest? Ära korista neid täna! Segamini kodu pole maailma lõpp, kuid ema vaimne heaolu on väga oluline.'),
('e7bfaacc-c0cc-4b36-8687-477371b3bc3d'::uuid,'Бүгүнкү акылдуу жомок 🪄',' ''Акылдуу жомокторго'' өзгөчө тема бериңиз: Оюнчуктарын жыйнаганды жакшы көргөн сыйкырдуу оюнчук аюу. Балким, бул жомок эртеңки тазалык иштеринде сизге жардам берер!','Tänane nutikas lugu 🪄','Anna „nutikatele lugudele“ eriline teema: võlukaru, kes armastab oma mänguasju koristada. Võib-olla aitab see lugu homsel koristamisel kaasa!'),
('895f4348-4fb2-4124-9532-acf7d07409f6'::uuid,'Атанын күнүмдүк тартиби 👨‍🍼','Балдардын аталары менен өздөрүнүн өзгөчө тартиптери болот. Бул кечинде уктоо процессин атасынын күлкүлүү эрежелерине тапшырып, бөлмөдөн тышкары жерде чай ичип, эс алыңыз.','Issi rutiinid 👨‍🍼','Lastel on isadega sageli oma erilised rutiinid. Sel õhtul usalda magamaminek isa naljakate reeglite hooleks ja naudi ise vaikselt teed teises toas.'),
('aca7ae85-535e-4175-ab27-d1ca390e78cb'::uuid,'Түстөр дүйнөсүн ачуу','Балаңыз түстөрдү туура топтоп, ''бул кызыл'', ''бул көк'' деп айтып жатабы? Бул анын таанып-билүү өнүгүүсүндөгү чоң секирик! Бул маалыматты ''Өнүгүү күндөлүгүнө'' сыймыктануу менен жазып коюңуз.','Värvide maailma avastamine','Kas su laps rühmitab värve õigesti, öeldes näiteks „see on punane“ või „see on sinine“? See on suur hüpe tema kognitiivses arengus! Märgi see detail kindlasti uhkusega tema arengu jälgijasse.'),
('b6ee83b4-0d5f-4791-8483-ed7d1d3aa649'::uuid,'Бирге тамак жасоонун кызыгы 🧑‍🍳','Балаңыз сизге жумуштарда жардам бергиси келеби? Дени сак тамактардан оңой торт рецептин тандап, ун же суу куюуга жардам берүүсүнө уруксат бериңиз. Башаламандык болсо да, көңүлдүү болору шексиз.','Koos kokkamine on lõbus 🧑‍🍳','Kas laps tahab sind toimetustes aidata? Vali tervislike retseptide hulgast lihtne koogiretsept ja lase tal aidata jahu või vett valada. Isegi kui see tekitab segadust, on lõbu garanteeritud.'),
('2009290a-99c2-4bf0-a2b6-174daa69d49d'::uuid,'Түнкү бейпилдик 🤫','Көчөдөгү ызы-чуу анын терең уйкуга кетишине тоскоол болуп жатабы? ''Үн өлчөгүч'' функциясы менен бөлмөнү талдап көрүңүз.','Öine rahu 🤫','Kas tänavamüra takistab lapsel sügavalt uinumast? Analüüsi tuba „Mürataseme mõõtja“ funktsiooniga.'),
('2a0f6e31-8cdc-436b-8432-73cf4dad5b5c'::uuid,'Кичинекей сүрөтчү иштеп жатат','Дубалдарыңыз жана эшиктериңиз кээде балаңыздын жеке сүрөт тартуучу жайына айланып жатабы? Капа болгондун ордуна, чоң картон кагазын таап, полго жайып, ага: ''Бул сенин сүрөт тарта турган атайын жериң!'' деп айтыңыз. Бул анын чыгармачылык каалоосун туура багытка бурууга жардам берет.','Väike kunstnik töös','Kas su seintest ja ustest saavad vahel lapse isiklikud lõuendid? Ärritumise asemel leia suur papitükk, laota see põrandale ja ütle: „See on sinu eriline koht joonistamiseks!“ See aitab suunata loovust positiivselt.'),
('7750d70c-df5b-48b0-9b2f-522c15391059'::uuid,'Сиздин AI суроо жардамчыңыз 🤖','3 жашка жакындаган баланын жүрүм-туруму тууралуу суроолоруңуз түгөнбөй жатабы? Anacan AI — сиздин 24/7 санарип педиатрыңыз жана психологуңуз. Сураңыз жана дароо жооп алыңыз.','Sinu AI-küsimuste assistent 🤖','Kas su küsimused lapse käitumise kohta 3. eluaasta lähenedes tunduvad lõputud? Anacan AI on su ööpäevaringne digitaalne lastearst ja psühholoog. Küsi ja saa kohe vastuseid.'),
('2859fc00-366b-44b7-ba24-815b9b659125'::uuid,'Сезимдериңизди билдирүү 📝','Өзүңүздү жалгыз жана түшүнүксүз сезип жатасызбы? Бул таптакыр табигый сезим. Сезимдериңизди ''Маанай күндөлүгүңүзгө'' чынчылдык менен жазыңыз.','Oma tunnete väljendamine 📝','Tunned end üksiku ja vääriti mõistetuna? See on täiesti loomulik tunne. Kirjuta oma tunnetest ausalt „Tujupäevikusse“.'),
('4f59cf22-ccfa-43b9-8a30-62365a911312'::uuid,'Өзүмдүн уникалдуулугумду ачуу','''Мен!'', ''Меники!'' деген сөздөр кичинекейиңиздин оозунан түшпөй жатабы? Бул эгоцентризмдин абдан көрүнүктүү мезгили! Анын өнүгүп жаткан инсандыгына сый менен мамиле кылыңыз; бул таптакыр нормалдуу жана маанилүү өнүгүү баскычы.','Oma unikaalse mina avastamine','Kas „Mina!“ ja „Minu!“ on su pisikese pidevad hüüded? See on väga ilmekas egotsentrismi periood! Suhtu tema arenevasse individuaalsusesse austusega; see on täiesti normaalne ja oluline arenguetapp.'),
('eddd6a67-3ce9-4446-ba23-dba7c167dca2'::uuid,'Жашоодогу өзгөрүүлөргө туруштук берүү ⛅','Сейилдөөгө чыккыңыз келеби, бирок сырттагы аба ырайы алдамчыбы? Аны ысытып жибербей, коргоп туруучу эң ылайыктуу кийимди тандоо үчүн ''Аба ырайы жана кийим'' куралын колдонуңуз.','Elumuutustega toimetulek ⛅','Tahad jalutama minna, aga ilm on petlik? Kasuta „Ilma ja riietuse“ tööriista, et leida täiuslik riietus, mis kaitseb last ilma teda üle kuumutamata.'),
('009a8d5c-9bba-4789-a6ee-e59d4c647832'::uuid,'Командалык сыймык 🥂','Сиз оор жуманы артта калтырдыңыз. Өнөктөшүңүз менен бетме-бет отуруп, бири-бириңизди: ''Биз бул баланы тарбиялоодо чындап эле сонун иш жасап жатабыз!'' деп дем бериңиз.','Meeskonna uhkus 🥂','Olete raske nädala seljatanud. Istuge partneriga vastamisi ja motiveerige üksteist, öeldes: „Me teeme selle lapse kasvatamisel tõesti suurepärast tööd!“'),
('19b9faef-1d59-42d5-bcb0-12290f627a1f'::uuid,'Тынчтык көз ирмеми ☕','Бөлмөдөгү башаламандык эч жакка качпайт. Кичинекейиңиз өз алдынча ойноп жатканда, кофеңизден ууртап, тынч көз ирмемдерден ырахат алыңыз.','Rahuhetk ☕','Segadus toas ei kao kuhugi. Sel ajal kui su pisike iseseisvalt mängib, rüüpa lihtsalt kohvi ja naudi vaikseid hetki.'),
('d0adf273-d83c-415a-88b8-6fa5f74c5f51'::uuid,'Бир сүйлөмдөн жомок айтып берүү','Балаңыз сүрөттүү китептерди карап, өзүнүн окуяларын ойлоп таап, уникалдуу сүйлөмдөрдү түзүп жатабы? Анын фантазиясы жана сүйлөө жөндөмү бир убакта өсүп жатат! Кунт коюп угуп, анын сонун чыгармачылыгын колдоп коюңуз.','Lugude jutustamine, lause haaval','Kas su laps vaatab pildiraamatuid ja mõtleb välja oma lugusid, luues unikaalseid lauseid? Tema kujutlusvõime ja kõne arenevad korraga tohutu kiirusega! Kuula tähelepanelikult ja kiida tema imelist loovust.'),
('9e41eb2a-f9ac-4f4c-8455-0ad7cfd405e3'::uuid,'Тынчтандыруучу ванна. 🛁','Жылуу сууга түшүү күндүн энергиясын чыгаруунун гана жолу эмес, ошондой эле булчуңдарды эс алдырып, аны уйкуга эң сонун даярдайт.','Rahustav vann. 🛁','Soe vann pole mitte ainult lõbus viis päevaenergia maandamiseks, vaid lõdvestab ka lihaseid, valmistades last suurepäraselt uneks ette.'),
('ff22b088-7f8b-4366-a32b-7bd8cd1aa92f'::uuid,'Энелер энелерди колдойт 💬','Горшокко үйрөтүү (дааратканага көндүрүү) сизди чарчатып жатабы? Дароо Anacan коомчулугуна кошулуңуз. Ал жердеги башка энелердин ийгиликтери жана кыйынчылыктары тууралуу окуялар сизге күч берет.','Emad toetavad emasid 💬','Kas potitreening tekitab masendust? Liitu kohe Anacan kogukonnaga. Teiste emade edulood ja mured annavad sulle jõudu.'),
('1c47434b-8f04-4342-a73a-e77c7a63eb48'::uuid,'Караңгыдан коркпоңуз 🌙','Караңгыдан коркобу? Төшөгүнүн жанына кичинекей түнкү чырак коюңуз, бирок бөлмө мелатонин өндүрүлүшү үчүн жетиштүү караңгы экенин текшериңиз.','Ära karda pimedust 🌙','Kardab pimedust? Pane voodi juurde väike öölamp, kuid veendu, et tuba oleks melatoniini tootmiseks piisavalt pime.'),
('77a1ab3f-8086-4334-93ed-03dab08fb152'::uuid,'Кийимимди өзүм тандоо','Балаңыз шкафты ачып, бири-бирине төп келбеген түстөрдү жана сезондук кийимдерди кийүүнү талап кылабы? Анын өз алдынчалыгын колдоңуз, бирок көзөмөлдү сактап калуу үчүн ага эки гана ылайыктуу вариантты сунуштаңыз.','Oma riiete valimine','Kas lapsele meeldib riidekappi avada ja nõuda sobimatute värvide ning hooajaväliste riiete kombineerimist? Toeta tema tärkavat iseseisvust, kuid kontrolli säilitamiseks paku talle vaid kahte sobivat valikut.'),
('b22d0c31-c528-4596-b176-4f64d3f5be5d'::uuid,'Кофе менен кубаттануу ☕','Күндүзгү уйку жок, күнү бою бир мүнөт да тынчтык жокпу? Аны 15 мүнөткө коопсуз иш менен алек кылып, өзүңүзгө керектүү кофе ичип алууну унутпаңыз.','Kohvipaus ☕','Lõunauinakuid enam ei toimu ja sa ei saa terve päeva jooksul hetkekski rahu? Lase lapsel 15 minutit turvaliselt tegutseda ja võta ise see hädavajalik kohvipaus.'),
('9787e3a9-8592-4bb2-8463-c4e695682c99'::uuid,'Оор жүк, чыдамкай жүрөк 🛒','Сейилдөөдөн кайтып келе жатканда эң оор буюмду же баштыкты сөзсүз өзү көтөргүсү келеби? Ордунан жылдыра албаса да, сиздин жардамыңызды кескин түрдө четке кагат. Коюңуз, бир аз аракет кылсын, күчүн сынасын.','Raske koorem, vastupidav süda 🛒','Kas ta tahab jalutuskäigult naastes kindlasti ise kõige raskemat eset või kotti kanda? Isegi kui ta ei jaksa seda liigutada, lükkab ta su abi järsult tagasi. Lase tal veidi proovida ja oma jõudu testida.'),
('290cd0a7-b2db-4a34-8b28-f8d9bbc37b62'::uuid,'Ичи менен жатуу убактысын узартуубу? 🐢','Анын булчуңдары күн сайын чыңдалууда. Бул процессти дагы да кызыктуу кылуу үчүн алдына түстүү оюнчуктарды коюп коюңуз!','Pikem kõhuli olemise aeg? 🐢','Tema lihased muutuvad iga päevaga tugevamaks. Muuda see protsess veelgi lõbusamaks, asetades tema ette värvilisi mänguasju!'),
('bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001'::uuid,'Кичинекей философ 🤔','Көзү илинип баратканда, күтүлбөгөн жерден: ''Апа, күн кайда уктаганы барат?'' деген сыяктуу философиялык суроо бердиби? Анын мээси уктап жаткан учурда да дүйнөнү талдайт. Тереңге кирбей, жомок сыяктуу кыска жооп бериңиз.','Väike filosoof 🤔','Just siis, kui ta silmad olid sulgumas, vaatas ta äkki üles ja küsis filosoofilise küsimuse: „Emme, kuhu päike magama läheb?“ Tema aju töötleb maailma isegi uinumise hetkel. Anna lühike muinasjutuline vastus, laskumata liigsetesse detailidesse.'),
('d452b163-e134-4c64-90b8-7e561b20c6f9'::uuid,'Сөздөрдү тууроо! 🗣','️ Сиз айткан сөздөрдү же жаныбарлардын үндөрүн тууроого аракеттенип жатабы? Анын өзүн көрсөтүү каалоосун өстүрүү үчүн бул аракеттерин кубануу менен колдоп коюңуз.','Sõnade järele kordamine! 🗣','️ Kas ta üritab jäljendada sinu öeldud sõnu või loomahääli? Julgusta neid katsetusi elavalt, et toetada tema soovi end väljendada.'),
('c2525bad-5158-49a7-81ce-247259a08d2e'::uuid,'Кичинекей кереметимдин каалоолору 🪄','Бүгүн эртең менен кесилген алманы кайра бириктирип коюшуңузду талап кылып ыйлап ойгондубу? Ооба, 3 жаш курагында алардын логикасы көп учурда физика мыйзамдарына каршы келет.','Minu väikese ime soovid 🪄','Ärkas täna hommikul karjudes ja nõudis, et paneksid viilutatud õuna uuesti kokku? Jah, umbes 3-aastaselt eirab nende loogika sageli füüsikaseadusi.'),
('1e3f3fa1-dbbc-4651-aa40-6590038f46b0'::uuid,'Жаныбарларды тууроо 🐶','Жөн эле үндөрдү чыгарбай, итче жөрмөлөп, мышыкча ырылдап жатабы? Дене тили менен элестетүү жөндөмү биригип жатат. Килем үстүндөгү бул оюнга аларга кошулуңуз!','Loomade matkimine 🐶','Ei tee enam lihtsalt hääli, vaid roomab nagu koer ja nurrub nagu kass? Kehakeel ja kujutlusvõime sulanduvad ühte. Ühine nendega vaibal toimuvas mängus!'),
('4ac97d09-8bce-44ef-922e-5286afc49815'::uuid,'Тандап тамак ичүү: Уландысы 🥣','Кечээ эле жакшы көргөн шорпосун бүгүн күтүүсүздөн ичпей койдубу? Мажбурлабаңыз. Жашылчаларды байкатпай кошууга боло турган альтернативдүү тамактарды табуу үчүн пайдалуу рецепттер бөлүмүн карап көрүңүз.','Valiv sööja: järg 🥣','Keeldub äkki supist, mida eile nii väga armastas? Ära sunni. Uuri tervislike retseptide sektsiooni, et leida alternatiivseid roogi, kuhu saad kavalalt köögivilju peita.'),
('d8f03ef9-1ea4-48a4-a43d-dc4f633f2d60'::uuid,'Сыйкырдуу уктаар алдындагы жомок 🪄','«Акылдуу жомоктор» бөлүмүндө үчүнчү туулган күнүнө даярданып жаткан эр жүрөк баатыр тууралуу жомок ойлоп табыңыз, бул аларга өсүп, күчтүү болуп жатканын сезүүгө жардам берет.','Maagiline unejutt 🪄','Loo „nutikate lugude“ abil jutustus vaprast kangelasest, kes valmistub oma kolmandaks sünnipäevaks – see paneb lapse tundma, et ta kasvab suuremaks ja tugevamaks.'),
('2a9575e0-ee4f-4f27-86a9-25def022748e'::uuid,'Кайдасың? «Ку-ку!» 👀','Бөлмөдөн чыгып кетээриңиз менен кайра ыйлай баштадыбы? Бөлүнүүдөн коркуу сезими кээде кайра кайтып келиши мүмкүн. Алыстан үнүңүз менен аларды тынчтандырыңыз, бирок ар бир секунд сайын көз алдында болуунун кажети жок экенин унутпаңыз.','Kus sa oled? Piilumismäng! 👀','Nutab jälle kohe, kui toast lahkud? Lahkumisärevus võib vahel uuesti esile kerkida. Rahusta teda eemalt oma häälega, kuid pea meeles – sa ei pea olema igal sekundil nähtaval.'),
('89de8241-ec59-4180-ba30-e03291e0f208'::uuid,'Жомокту аягына чейин айтып бериңиз 📖','Бүгүн кечинде жомок окуп жатканда, сүйлөмдөрдү бүтүрбөй токтотуп, аларды бүтүрүүгө мүмкүнчүлүк бериңиз! Бул укмуштуудай элестетүү жөндөмүн өнүктүрүүгө колдоо көрсөтүү үчүн Anacan AI''дан диалог боюнча кеңештерди сураңыз.','Lase tal lugu lõpuni kuulata 📖','Jäta täna õhtul lugu lugedes laused pooleli ja lase lapsel need lõpetada! Küsi Anacan AI-lt dialoogiideid, et toetada seda imelist kujutlusvõime arengut.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('ca321f21-1031-4b14-96c8-69fa4c4201da'::uuid,'Керектүү нерселердин тизмеси 🛒','Туулган күн үчүн керектүү буюмдар унутулбасын! Башыңызды оорутпаңыз, баарын дароо Соода тизмесине жазыңыз жана жолдошуңуз менен синхрондоштуруңуз.','Hädavajalik nimekiri 🛒','Ära unusta sünnipäevaks vajalikke asju! Ära vaeva oma pead, pane kõik kohe ostunimekirja ja sünkroniseeri see oma kaaslasega.'),
('16b69d4c-feb3-42d5-b458-329c2a13a823'::uuid,'Жаңы досторду табуу','Кичинекейиңиз сейил бакта теңтуштары менен чуркап, оюндарга кошулууга аракет кылып жатабы? Алардын социалдык өнүгүүсү расмий түрдө башталууда! Аларды кубаттап, башка балдар менен кантип учурашууну үйрөтүңүз.','Uute sõprade leidmine','Kas su väike põnn üritab pargis joosta ja teiste laste mängudega liituda? Tema sotsiaalne areng on ametlikult alanud! Julgusta teda ja õpeta, kuidas teisi lapsi tervitada.'),
('db813abc-1129-479f-a1e4-e6beaeb2ec95'::uuid,'Апалар үчүн жаратылыш терапиясы 🌳','Үйдүн дубалдары басып бараткандай сезилип жатабы? Балаңызды алып, жакынкы сейил бакка чуркаңыз. Таза аба балаңыз үчүн гана эмес, чарчаган нервдериңиз үчүн да эң мыкты массаж болот.','Loodusteraapia emale 🌳','Kas koduseinad hakkavad juba kitsaks jääma? Haara laps kaasa ja jookse lähimasse parki. Värske õhk pole hea mitte ainult lapsele, vaid on ka parim massaaž sinu väsinud närvidele.'),
('565fda98-0d2c-40b4-8230-13c64e585700'::uuid,'Байпактын тигиши менен болгон драма 🧦','Бүгүн эртең менен чоң кризис: байпагынын тигиши манжасына тийип жатыптыр! 3 жаш курагында эмоционалдык сезимталдык жогорку чегине жетет. Логика издебеңиз; жөн гана байпагын тескерисинен кийгизип коюңуз жана бул абсурддуу ыйдын 10 секундда кантип токтогонун көрүңүз.','Sokkide õmbluste draama 🧦','Ärkasid täna hommikul suure kriisi peale: sokkide õmblus puudutab varbaid! Umbes 3-aastaselt saavutab emotsionaalne tundlikkus haripunkti. Ära otsi loogikat; keera lihtsalt sokk pahupidi ja vaata, kuidas see absurdne jonnihoog 10 sekundiga lõpeb.'),
('acd26d8c-d24f-4082-9973-a1110aefb638'::uuid,'Көлдөчүк изилдөөчү 🌧️','Жамгырдан кийин сыртка чыкканыңыздарда, ал түз эле ылай көлчүккө секирип кеттиби? Кийимдери кир болду, бирок алардын көзүндөгү ачылыштын нурун караңыз. Аба ырайына жана кийимине жараша резина өтүктөрдү алдын ала пландап, балалыгын толук сезүүгө мүмкүнчүлүк бериңиз.','Lombijooksja 🌧️','Läksite pärast vihma õue ja ta hüppas otse porilompi? Riided on küll mustad, aga vaata seda avastamisrõõmu tema silmis. Planeeri ette kummikutega ja lase tal lapsepõlve täiel rinnal kogeda.'),
('b17158eb-f894-42c6-8d84-cab6d30d297a'::uuid,'Жакшы уктагыла, оюнчуктар 🧸','Уктоо убактысы келди, бирок кичинекейиңиз бөлмөдөгү ар бир машина жана оюнчук аюу менен коштошуп жатат. Бул уктоону кечеңдетүүнүн чыныгы чеберчилиги! Таймер коюп, эреже киргизиңиз: 3 мүнөттүн ичинде баары менен бир убакта коштошобуз.','Head ööd, mänguasjad 🧸','On uneaeg, aga su väike põnn jätab hüvasti iga toa auto ja kaisukaruga. See on tõeline meistriklass magamamineku edasilükkamises! Pane taimer ja tee reegel: jätame nendega kõigiga hüvasti 3 minuti jooksul.'),
('3b1d044a-5917-48bd-b4f3-847b5ba6d5db'::uuid,'Эң кызыктай буюм 🥄','Канчалаган кымбат оюнчуктарыңыз бар, бирок ал ашканадан чөмүч таап алып, кечке аны көтөрүп жүрүп, төшөгүнө жаткырып жатат. Баланын дүйнөсүнүн кызыктары чындап эле түшүнүксүз. Тоскоол болбоңуз; ал чөмүчкө сүйүүсүн төгө берсин!','Kõige veidram ese 🥄','Sul on nii palju kalleid mänguasju, aga ta leidis köögist kulbi ja kannab seda terve õhtu kaasas, pannes seda magama. Lapse mõttemaailma kiindumused on tõesti seletamatud. Ära sekku, lase tal seda kulpi armastusega üle külvata!'),
('498b3498-4fee-4a00-9b62-ebe43844ae53'::uuid,'Шорподогу кичинекей хирург 🥣','Тамагын жебей, майда пиязды же күрүчтү кылдаттык менен терип жатабы? Жашылчаларды пюре кылып, «көрүнбөс» кылып жасоо убактысы келди. Башка энелерден эң чыгармачыл, жашылча кошулган тамактарды табуу үчүн Anacan пайдалуу рецепттерин карап көрүңүз.','Väike kirurg supitaldrikus 🥣','Ta ei söö toitu, vaid nopib kirurgilise täpsusega välja pisikesed sibula- või riisitükid. On aeg köögiviljad püreestada ja need „nähtamatuks“ muuta. Vaata Anacani tervislike retseptide alt teiste emade kõige loomingulisemaid peidetud köögiviljadega roogi.'),
('a13e9959-a476-4e99-9da8-13f5bff68864'::uuid,'Өзүм ачам! (Шкаф изилдөөчү) 🚪','Бүгүн эртең менен шкафтын эшигин ачканыңыз үчүн ыйладыбы, анан өзү ачуу үчүн жаптырдыбы? Ооба, алар баарын өзү көзөмөлдөгүсү келет. Бул күнөөсүз «өзүм жасайм» аракеттерине жылмайып коюңуз; алар өз эркинин күчүн сынап жатышат.','Teen ise lahti! (Kapiuurija) 🚪','Kas ta nuttis täna hommikul sellepärast, et avasid kapiukse, sundides sind seda sulgema, et ta saaks ise uuesti avada? Jah, ta vajab täielikku kontrolli. Naerata nendele süütutele „mina ise“ katsetele; ta katsetab oma tahet.'),
('f7c61cc4-7a2d-48d0-bf89-ec947a89cd75'::uuid,'Атасынын милдеттери 👨‍🍼','Баарын өзүңүз жасоонун кажети жок. Бул кечинде тиш жуу жана пижама кийүү тартибин толугу менен атасына тапшырып, четтен байкап туруңуз.','Issi kohustused 👨‍🍼','Sa ei pea kõike ise tegema. Anna täna õhtul hammaste pesemise ja pidžaama selgapanemise rutiin isale ja jälgi toimuvat kõrvalt.'),
('0a4a5638-968e-4cce-9213-12c0072354c4'::uuid,'Тынчтыктын санарип таразасы 🤫','Акыры укташты! Үйдө орногон тынчтыкка ишене албай турасыз. Үн өлчөгүчүңүздү иштетип, экрандагы 0-10 децибелдик көрсөткүчтү карап, мээңиздин акырындап эс алып, кубаттанып жатканын сезиңиз.','Vaikuse digitaalne mõõdupuu 🤫','Ta on lõpuks ometi magama jäänud! Sa ei suuda uskuda majja saabunud vaikust. Aktiveeri helimõõtja ja vaata ekraanilt 0–10 detsibelli näitu, tundes, kuidas su aju aeglaselt lõõgastub ja laeb.'),
('b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a'::uuid,'«Жаман апа» деген күнөө сезими 💔','Конфет бербегениңиз үчүн сизге «сиз жамансыз» дедиби? Жүрөгүңүздү оорутпаңыз. Алар сезимдерин туура сөздөр менен билдирүүнү үйрөнүп жатышат; чындыгында алар «мен абдан капа болуп жатам» деп айткысы келет. Көз караштарыңызды бириктирип, алардын сезимин түшүнгөнүңүздү билдириңиз.','„Halva ema“ süütunne 💔','Kas ta ütles sulle „sa oled kuri“, sest sa ei andnud talle kommi? Ära lase sellel oma südant murda. Ta alles õpib oma tundeid õigete sõnadega väljendama; tegelikult mõtleb ta „ma olen nii pettunud“. Võta silmside ja tunnusta tema emotsiooni.'),
('fabd170d-dc89-4100-b9c1-3acf59e32a5c'::uuid,'Көрүнбөгөн достор менен маек 🐜','Балкондо же сейил бакта жердеги кумурсканын үстүнө эңкейип, аны менен өтө олуттуу сүйлөшүп жатабы? Элестетүү жана боор ооруу сезими бир убакта иштеп жатат. Бул керемет көз ирмемди балаңыздын сүрөтүнө тартып алып, архивиңиздин эң таттуу бурчуна сактап коюңуз.','Vestlused nähtamatute sõpradega 🐜','Kummardub rõdul või pargis maas oleva sipelga kohale ja räägib temaga väga tõsiselt? Kujutlusvõime ja empaatia töötavad samaaegselt. Jäädvusta see suurepärane hetk beebifotodega ja pane see oma albumi kõige armsamasse nurka.'),
('a860534c-7167-4781-b298-8321127fd089'::uuid,'Атанын «учак режими» ✈️','Кичинекейиңиздин энергиясы ашып-ташып, уктоодон баш тартып жатабы? Атасын жардамга чакырыңыз! Ал баланы көтөрүп, «самолёт сыяктуу учкузганда», бөлмөнү күлкү толтуруп, топтолгон физикалык чарчоо бир нече секундда жок болот.','Issi lennurežiim ✈️','Su väikesel põnnil on ikka veel liiga palju energiat ja ta tõrgub magamamineku vastu. Kutsu isa appi! Kui ta lapse üles tõstab ja laseb tal „nagu lennukiga lennata“, täitub tuba naeruga ja kogu kogunenud füüsiline pinge kaob sekunditega.'),
('e0e56f8d-3c51-4c46-90f2-dbfa90060519'::uuid,'Жерде оонап ойноо эркиндиги 🌪️','Супермаркеттин ортосунда жерге жатып алдыбы? Аны көтөрүүгө же айланадагыларга түшүндүрүүгө аракет кылбаңыз. Терең дем алыңыз. Anacan Коомчулугуна кошулганыңызда, миңдеген башка энелер да ушундай ыңгайсыз, бирок таптакыр кадимки учурларды башынан өткөрөрүн көрөсүз.','Vabadus põrandal püherdada 🌪️','Kas ta viskas end keset supermarketit põrandale pikali? Ära ürita teda üles tõsta ega kõrvalseisjatele selgitada. Hinga sügavalt sisse. Anacani kogukonnaga liitudes näed, et tuhanded teised emad kogevad samu piinlikke, kuid täiesti normaalseid hetki.'),
('431c0c7a-2968-4edd-9882-df9a926adf72'::uuid,'Олуттуу каалоолор пайда болдубу, апаке? 🤤','Кичинекейиңиздин жакасы көп учурда ным болуп жатабы? Бул тиш чыгуу мезгили болушу мүмкүн! Силикон тиш салгычты жаныңызда сактаңыз.','Tõsised isud, emme? 🤤','Kas su lapse krae on sageli märg? See võib olla hammaste tuleku aeg! Hoia silikoonist närimislelu alati käepärast.'),
('e9ba4911-0212-43aa-9a51-c6bf942facb9'::uuid,'«Мага караба!» фазасы 🙈','Жылмайганыңыз үчүн эле «мага караба!» деп ыйлап жатабы? Абсурддуу логиканын туу чокусу! Жүзүңүздү буруп, бул тамашалуу каприздин өтүп кетишин күтүңүз; кээде алар өздөрү да эмне каалап жатканын билишпейт.','„Ära vaata mind!“ faas 🙈','Ta nutab ja ütleb „ära vaata mind!“, lihtsalt sellepärast, et sa naeratasid talle? Absurdse loogika tipp! Pööra nägu ära ja oota, kuni see naljakas tuju möödub; vahel ei tea nad isegi, mida nad tahavad.'),
('07c7c2cb-58bb-47db-ac0e-f81bd01e602b'::uuid,'Эненин үнүнүн күчү 🎶','Бүгүн кечинде эч кандай гаджет колдонбоңуз. Жөн гана аларды кучагыңызга бекем кысып, кулагына эң жакшы көргөн бешик ырын шыбыраңыз. Сиздин үнүңүз алар үчүн эң коопсуз баш калкалоочу жай.','Ema hääle vägi 🎶','Ära kasuta täna õhtul ühtegi nutiseadet. Hoia teda lihtsalt tihedalt oma rinna vastas ja sosista talle kõrva tema lemmikhällilaulu. Sinu hääl on tema kõige turvalisem sadam.'),
('1acb826a-9b73-413f-b0af-4614a74084bd'::uuid,'Ыкчам педиатрдык колдоо 🤖','Балаңыз 3 жашка жакындаганда анын бою жана салмагы боюнча тынчсызданып жатасызбы? Интернеттен сааттап издебеңиз; педиатр тарабынан жактырылган так ченемдерди Anacan AI''дан дароо билип алыңыз.','Kiire lastearsti nõu 🤖','Kas oled mures oma lapse pikkuse ja kaalu pärast, kui ta läheneb 3. eluaastale? Ära kuluta tunde internetis otsimisele; uuri täpseid ja lastearstide poolt heaks kiidetud norme kohe Anacan AI-st.'),
('5bb344ff-e859-413b-93f7-4f25386f0835'::uuid,'Алардын атын жана жашын билүү','«Жашың канчада?» деп сураганда, балаңыз манжалары менен жашын көрсөтүүгө аракет кылып жатабы? Алардын өзүн-өзү таануу сезими сонун өнүгүп жатат! Бул интеллектуалдык секирикти Өнүгүү трекерине жазып коюуну унутпаңыз.','Nime ja vanuse teadmine','Kui küsid „kui vana sa oled?“, kas su laps üritab oma vanust sõrmedega näidata? Tema eneseteadvus õitseb kaunilt! Pane see intellektuaalne hüpe kindlasti arengupäevikusse kirja.'),
('3b9f5253-06a7-4aef-bfdf-bb0daf30818e'::uuid,'Жарыктын сыйкыры 🌙','Караңгыдан корко баштадыбы? Бөлмөнү толугу менен караңгылатып, кичинекей фонарик менен шыпта жарык оюндарын ойноңуз. Караңгыдан коркуу сезимин кызыктуу, уктоо алдындагы кичинекей изилдөөгө айлантыңыз.','Valguse maagia 🌙','Kas ta hakkab pimedust kartma? Tee tuba täiesti pimedaks ja mängi väikese taskulambiga laes valgusemänge. Muuda hirm pimeduse ees lõbusaks, väikeseks une-eelseks avastusretkeks.'),
('5d1a2a49-e134-453a-a974-f4cff4de0952'::uuid,'Пижама сүйүүсү 👗','Бүгүн эртең менен ойгонуп, кир пижамасын чечүүдөн такыр баш тартып жатабы? Эгер сыртка чыкпай турган болсоңуз, урушпаңыз. Кээде эненин жан дүйнөсүнүн тынчтыгы баланын тыкан көрүнгөнүнөн алда канча маанилүү.','Pidžaamaarmastus 👗','Ärkas täna hommikul ja keeldub kategooriliselt plekilist pidžaamat seljast võtmast. Kui te kodust välja ei lähe, jäta see võitlus pidamata. Mõnikord on ema meelerahu palju olulisem kui see, et laps näeks välja laitmatult puhas.'),
('c8ffca51-c2fa-4f5a-8090-6c144b596f9c'::uuid,'Чөнтөктөгү казыналар 🍁','Сейил бактан келгениңизде, чөнтөгүндө 3 таш, 1 кургак жалбырак жана бир бутак бар экен. Сиз үчүн бул таштанды, ал эми алар үчүн бул казына. Аларды үйгө чачып жиберүүнүн ордуна, тапкан нерселерин чогултуу үчүн атайын кутуча жасап бериңиз.','Taskuaarded 🍁','Tulite pargist tagasi ja tema taskus oli 3 kivi, 1 kuivanud leht ja oksaraag. Sinu jaoks on see prügi, tema jaoks aare. Selle asemel, et lasta tal neid mööda maja laiali loopida, loo talle kogumiskast, kuhu ta saab oma leide panna.'),
('176265d3-ef2f-4ec4-923c-4308870e611f'::uuid,'Эмоционалдык жүктү бошотуу 📝','Үйдө эч ким сиздин канчалык чарчаганыңызды көрбөгөндөй сезилип жатабы? Маанай күндөлүгүңүз сиздин эң ишенимдүү сырдашыңыз. Бүгүн сизди жинди кылган майда-чүйдө нерселердин баарын жазыңыз жана оюңуздун кантип жеңилдеп калганын байкаңыз.','Emotsionaalse koorma vabastamine 📝','Kas tundub, et keegi kodus ei näe, kui kurnatud sa oled? Sinu meeleolupäevik on su kõige vaiksem usaldusisik. Kirjuta üles kõik väikesed detailid, mis sind täna hulluks ajasid, ja vaata, kuidas su meel kergemaks muutub.'),
('94fce04c-73e9-47bd-8d9d-3bd3da19122a'::uuid,'Өзүм басам! 🚶‍♂️','Көчөдө өз алдынчалыгын көрсөтүп, колуңузду кармоодон баш тартып жатабы? Коопсуз жерлерде бул эркиндикти бериңиз. Аларды көзөмөлдөп туруңуз жана дүйнөнү өз темпи менен таанып-билүүсүнө мүмкүнчүлүк бериңиз.','Kõnnin ise! 🚶‍♂️','Tänaval keeldub ta kindlameelselt su käest kinni hoidmast, kuulutades oma iseseisvust. Anna talle seda vabadust turvalistes kohtades. Hoia tal silm peal ja lase tal maailma omas tempos avastada.'),
('b24a452c-9588-4b0c-923f-9c455be6d1e2'::uuid,'Ашканадагы кичинекей ашпозчум 🧑‍🍳','Сиз камыр жайып жатканда жаныңызга отургуч коюп, «жардам берүүгө» аракет кылып жатабы? Ага бир аз камыр бериңиз. Баары ун болуп калат, бирок алардын олуттуу, алек болгон жүзү тазалоо иштерине арзыйт.','Minu väike köögikokk 🧑‍🍳','Kas ta nõuab, et tõmbaks tooli sinu kõrvale ja „aitaks“, kui sa tainast rullid? Anna talle väike tükk tainast. Kõik saab küll jahuseks, aga tema tõsine ja tegus ilme on kogu koristamist väärt.'),
('09711673-d0fa-42b5-be98-012bd4b1ed8b'::uuid,'Экрансыз жашоо чакырыгы 📺','Бүгүн иштериңизден улам экран алдында көп отургузуп коюп, өзүңүздү күнөөлүү сезип жатасызбы? Өзүңүздү күнөөлөбөңүз. Ар күнү идеалдуу эне боло албайсыз. Кээде санариптик эмчи-домчу сизди психологиялык чарчоодон сактап калышы мүмкүн.','Ekraanivaba väljakutse 📺','Kas andsid talle täna oma toimetuste tõttu rohkem ekraaniaega ja tunned nüüd süümepiinu? Ära süüdista ennast. Sa ei saa olla iga päev täiuslik ema. Mõnikord võib digitaalne lapsehoidja päästa sind psühholoogilisest kokkuvarisemisest.'),
('8649e4ca-170c-4117-8af8-b0d7e819e84f'::uuid,'Менин кичинекей жаңырыгым 🎙️','Бүгүн эртең менен өнөктөшүңүз менен сүйлөшүп жатканда айткан кокустук сөздү оюнчугуна айтып жатабы? Алардын сөз байлыгы укмуштуудай тездик менен кеңейүүдө жана алар сизди толугу менен туурап жатышат. Сиз алар үчүн үлгү экениңизди унутпаңыз.','Minu väike kaja 🎙️','Täna hommikul ütleb ta juhuslikku sõna, mida sina eile oma kaaslasega rääkides kasutasid, aga oma mänguasjale! Tema sõnavara laieneb hämmastava kiirusega ja ta ahvib sind täielikult järele. Pea meeles, et oled talle eeskujuks.'),
('c0faa467-b596-4471-bbba-6d91e0e37db1'::uuid,'Шыбыроо девизи 🤫','Алар төшөктө өтө активдүү болуп, уктагысы келбей жатышат. Үнүңүздү көтөрүүнүн ордуна, күтүлбөгөн жерден үнүңүздү акырындатып, шыбырап сүйлөңүз. Балаңыз сизди угууга аракет кылып көңүлүн топтогондо, анын мээси автоматтык түрдө уйку режимине өтөт.','Sosistamise moto 🤫','Nad on voodis nii aktiivsed, et ei jää kuidagi magama. Selle asemel, et häält tõsta, langeta ootamatult tooni ja räägi sosinal. Kui laps keskendub sind kuulamisele, lülitub tema aju automaatselt unerežiimile.'),
('48263ed0-f236-440c-a83e-807da51bd86f'::uuid,'Таза абадан дем алуу ⛅','Төрт дубалдын ичинде отуруп чарчадыңыз, үйдө болсо ар кандай түшүнбөстүктөр чыгууда. Аба ырайын карап, ылайыктуу кийим тандаңыз. Сыртта чуркап жүрүү аларга энергиясын сарптоого жардам берет, ал эми сизге таза аба менен дем алууга мүмкүнчүлүк берет.','Sõõm värsket õhku ⛅','Neli seina on su aju tuimestanud ja kodus puhkevad kriisid. Kontrolli ilma ja vali õige riietus. Lihtsalt õues ringijooksmine aitab neil energiat kulutada ja annab sulle võimaluse värsket õhku hingata.'),
('8fed0a18-52ae-4688-8137-532b6b55726c'::uuid,'Жомоктун сыйкырдуу таягы 🪄','Экөөңүздөр тең кадимки жомоктордон тажадыңызбы? «Акылдуу жомокторду» ачыңыз – балаңызды башкы каарман кылып, анын бөлмөсүн тынч, өзгөчө жана кызыктуу уйку алдындагы укмуштуу окуянын ордосуна айлантыңыз.','Jutuvestmise võluvägi 🪄','Kas olete mõlemad klassikalistest unejuttudest väsinud? Ava mõni „nutikas muinasjutt“ – tee oma lapsest peategelane ja tema toast vaikse, ainulaadse ja spontaanse une-eelse seikluse toimumispaik.'),
('c7c388a1-a255-4a7c-a615-22236406e4e2'::uuid,'Авангарддык көркөм чыгармалар 🖍️','Бир нече секунддук тынчтык коркунучка айланды. Бөлмөгө кирсеңиз, алар колдоруна же курсагына маркер менен сүрөт тартып жатышат. Терең дем алыңыз. Алардын майда моторикасы өнүгүп жатат, ал эми теридеги боёктор баары бир жуулат.','Avangardistlikud kunstiteosed 🖍️','Mõni sekund vaikust muutus ohtlikuks. Läksid tuppa ja leidsid, et nad teevad endale markeriga tätoveeringuid kätele või kõhule. Hinga sügavalt sisse. Nende peenmotoorika areneb ja nahk läheb niikuinii puhtaks.'),
('15f19421-c415-4b7b-ad4d-54211e4ccb3a'::uuid,'Суу, бардык жерде суу! 💧','Алар чөйчөккө сууну өздөрү куюуну талап кылышты. Төгүп алышты, баары суу болду. Бирок чүпүрөктү алып, аны тазалоого аракет кылган кичинекей колдорун караңызчы. Алар каталары аркылуу жоопкерчиликтүү болууну үйрөнүп жатышат; капа болбоңуз.','Vett igal pool! 💧','Nad nõudsid kindlalt, et tahavad ise vett tassi valada. Ajasid maha, kõik sai märjaks. Aga vaata neid väikeseid käsi, mis püüavad lappi haarata ja koristada. Nad õpivad vigadest vastutust; ära pahanda.'),
('6d2f1d1e-d7d7-41c3-b906-1e286aab1a51'::uuid,'Атанын кезеги 👨‍👧','Эне болуу – бул чексиз марафон эмес. Бүгүн сейил бакка барууну атасына тапшырыңыз, ал эми өзүңүз диванда жалгыздыктан ырахат алыңыз.','Issi kord 👨‍👧','Emadus ei ole lõputu maraton. Lase issil tänane pargitiir ära teha, samal ajal kui sina naudid diivanil üksinduse hetke.'),
('0140116f-1e50-4656-93a0-277a1645b1ba'::uuid,'Сезимдерди сыртка чыгаруу 📝','Күн оор болдубу? «Маанай күндөлүгүн» ачып, бардык чарчооңузду жана сезимдериңизди чынчылдык менен жазып алыңыз.','Emotsionaalne vabastamine 📝','Kas oli raske päev? Ava oma meeleolupäevik ja kirjuta ausalt üles kogu oma väsimus ja tunded.'),
('cf9e0ee2-2f17-4a55-933b-735bc0754d7e'::uuid,'Биргелешкен массаж 💆‍♂️','Балаңыз уктагандан кийин, күндүн чарчоосун басуу үчүн өнөктөшүңүз экөөңүз бири-бириңизге ийинге массаж жасаңыз. Сиздер жөн гана ата-эне эмессиздер; сиздер бул үйдө бири-бириңиздердин эң чоң тирегиңиздерсиз.','Ühine massaaž 💆‍♂️','Pärast seda, kui laps on uinunud, tehke partneriga teineteisele õlamassaaži, et päeva pingetest vabaneda. Te ei ole ainult vanemad; te olete teineteise suurim toetaja selles kodus.'),
('72ba71ca-1652-48f5-bc29-c321459f659a'::uuid,'Ак ызы-чуунун күчү 🎶','Эгерде активдүү күндөн кийин алар уктабай кыйналып жатышса, бөлмөдө «Ак ызы-чуу» (White Noises) бөлүмүнөн океандын же жамгырдын үнүн коюп, тынчтандыруучу атмосфера түзүңүз.','Valge müra vägi 🎶','Kui neil on pärast aktiivset päeva raske uinuda, loo rahustav õhkkond, mängides toas White Noise''i abil ookeani- või vihmahelisid.'),
('2caa3c21-d2d3-4566-921a-e08cdbce1397'::uuid,'Мен чарчадым... 🔋','Баары сизден энергия күтөт, бирок сиздин кубатыңыз түгөнүп калды. Бүгүн тамак жасабаңыз; даяр тамакка заказ бериңиз же жөнөкөй макарон кайнатыңыз. «Супер эне» болуу – баарын жалгыз жасоо дегенди билдирбейт.','Olen väsinud... 🔋','Kõik ootavad sinult energiat, aga su aku on tühi. Ära täna süüa tee; telli midagi või keeda lihtsalt lihtsat pastat. Superema olemine ei tähenda, et pead kõike üksi tegema.'),
('48299b62-1108-44e9-af43-b48460ffdfa2'::uuid,'Ваннадагы тынчтык 🛀','Бүт күн «каалабайм» деген сөздөр менен өттү. Жылуу ванна жөн гана гигиена үчүн эмес; бул алардын ашыкча дүүлүккөн нерв системасын калыбына келтирүү үчүн керек. Суунун үнүн угуңуз, бөлмөдөгү атмосфера заматта өзгөрөт.','Rahu vannis 🛀','Terve päev oli täis „ma ei taha“. Soe vann pole ainult hügieeniks; see on nende ülestimuleeritud närvisüsteemi lähtestamiseks. Kuula vee häält ja õhkkond toas muutub silmapilkselt.'),
('ab5bd705-a57d-40d7-b0a0-86107e824b4d'::uuid,'Тепкичтерди жалгыз багындыруу 🧗','Тепкичтен колдоосуз чыгууга аракет кылып жатабы? Алардын кыймыл-аракет жөндөмү туу чокусунда! Четте туруп байкаңыз, кийлигишпеңиз. Бул көз карандысыз учурду балаңыздын сүрөт сессиясы менен түбөлүккө калтырыңыз.','Üksi trepist üles ronimine 🧗','Püüab ilma toeta trepist üles ronida? Nende motoorsed oskused on tipus! Jälgi kõrvalt, ära sekku. Jäädvusta see iseseisev hetk beebifotoseansiga.'),
('028ed2b5-737d-4edf-81c1-5a9151e5fbf0'::uuid,'Супермаркеттен шоколад сюрпризи 🛒','Базарга барардан мурун соода тизмеңизди ачтыңыз, ошол маалда алар артыңыздан келип, телефонуңуздун экранын таптап, бир нерселерди чиймелеп салышты. Ооба, алар сиздин санариптик жашооңузду да туурап жатышат!','Šokolaadiüllatus poes 🛒','Avasid enne turule minekut oma ostunimekirja ja siis tulid nad selja tagant, toksisid su telefoniekraani ja kritseldasid sinna midagi. Jah, nad kopeerivad ka sinu digitaalset elu!'),
('098cd94b-6989-48a8-9fdc-160a2f819cb0'::uuid,'Ойлоп табылган грамматикадан ырахат алуу 🗣️','Алар өздөрүнүн кызыктуу, бирок өтө таттуу сөз айкаштарын ойлоп табышты. Алардын сөз байлыгы бороондой өсүп жатат! Бул уникалдуу тилдик өнүгүүлөрдү алардын өсүү күндөлүгүнө архив катары жазып коюңуз.','Rõõm omaleiutatud keelest 🗣️','Nad on avastanud kummalised, kuid uskumatult armsad verbivormid. Nende sõnavara kasvab tormiliselt! Salvesta need ainulaadsed keelelised arengud nende kasvu jälgijasse kui arhiiv.'),
('50dce5d9-294a-44b8-b1c9-316b84d5df14'::uuid,'Керебеттин астында эмне бар? 👻','Алар караңгыда желмогуздар бар деп ишенишеби? Суу куюлган бөлгүчтү алып, аны «Желмогуз куугуч спрей» деп атап, бөлмөгө чачып, аларды тынчтандырыңыз. Элестетүүнү элестетүү менен жеңиңиз!','Mis on voodi all? 👻','Kas nad usuvad, et pimeduses on koletised? Haara tavalise veega täidetud pudel ja piserda seda tuppa kui „koletiste peletamise spreid“, et neid rahustada. Võida kujutlusvõime kujutlusvõimega!'),
('2cd29d0d-0cf1-403e-806d-35f84215b2df'::uuid,'Таңкы саат 5теги кече башталат! ⏰','Күн да чыга элек, бирок алар төшөктө секирип, күндү баштап жиберишти. Сиз дагы эле уйкулуу болсоңуз да, алар дүйнөнү багындырууга даяр. Аларга кошулуңуз; бул жинди энергия сизди да ойготсун.','Kell 5 hommikul algab pidu! ⏰','Päike pole veel tõusnudki, aga nad on juba alustanud päeva voodis hüppamisega. Isegi kui oled veel unine, on nemad valmis maailma vallutama. Ühine nendega; las see pöörane energia äratab ka sind.'),
('48550c10-c030-428e-9c25-ccd73ca09c55'::uuid,'Бала бакча издеп жатасызбы? 🏫','3 жаш чамасында бала бакчага берүү оюңузга келип, бирок чечим кабыл ала албай жатасызбы? Эгерде жалгыз ойлонуудан чарчасаңыз, Anacan коомчулугуна кошулуп, башка энелердин бала бакча тууралуу реалдуу тажрыйбаларын окуңуз.','Otsid lasteaeda? 🏫','Mõte lasteaiast umbes 3-aastaselt keerleb su peas, aga sa ei suuda otsustada? Kui oled väsinud üksi mõtlemisest, liitu Anacani kogukonnaga ja loe teiste emade tegelikke kogemusi lasteaiaga.'),
('df1cf1ea-2772-44a6-8cb7-33857989fedf'::uuid,'Сезимдериңизди белгилеп туруңуз 📝','"Күнү бою үйдөсүң, эмнеден чарчамак элең?" - деп кимдир бирөө айттыбы? Дароо маанай күндөлүгүңүздү ачып, бардык нааразычылыктарыңызды манжаларыңыз менен экранга төгүңүз. Чыныгы сезимдериңизди жазуу – бул жасалма жылмаюуга караганда алда канча жакшы терапия.','Oma emotsioonide kirjapanek 📝','Kas keegi ütles sulle: „Oled terve päeva kodus, millest sa küll väsinud oled?“ Ava kohe oma meeleolupäevik ja vala kogu oma frustratsioon sõrmeotstega ekraanile. Oma tõeliste tunnete kirjapanek on teraapia, palju parem kui võlts naeratus.'),
('33979ce6-ea09-4adc-ab85-0cf386a73156'::uuid,'Кутунун сыйкырдуу тартуусу 📦','Сиз ага кымбат, үн чыгарган оюнчук сатып алдыңыз, бирок ал бир сааттан бери оюнчуктун кутусу менен ойноп жатат. Баланын мээси даяр нерселерди жактыра бербейт; ал кыялданууну ойготкон жөнөкөй буюмдарды жакшы көрөт. Карап, үйрөнүңүз.','Kasti maagiline võlu 📦','Ostsid neile kalli ja lärmaka mänguasja, aga nad on tund aega mänginud mänguasja karbiga. Lapse aju ei eelista valmis struktuure; see armastab lihtsaid esemeid, mis sütitavad kujutlusvõimet. Vaata ja õpi.'),
('5b89452a-e411-4130-87b7-6e1e33b0701e'::uuid,'Табигый ак ызы-чуу (white noise) 🤫','Уйкуга кирип баратканда сезгичтик күчөйт. Көчөдөгү үндөрдү басуу үчүн, бөлмөдөгү үн өлчөгүчтүн "фондук ызы-чуу" функциясын иштетип, узакка созулган тынчтыкты орнотуңуз.','Looduslik valge müra 🤫','Tundlikkus suureneb, kui nad uinuvad. Tänavamüra neutraliseerimiseks aktiveeri toas helimõõtja „taustamüra“ funktsioon ja too kestev rahu.'),
('a09d0a7b-0632-4bcf-8833-28f5ef0f9d93'::uuid,'Жалган көз жаштын искусствосу 🎭','Чындап ыйлабай эле, каалаганына жетүү үчүн үнүн титиретип, жалган көз жаш төгүп жатабы? Ал сизди манипуляциялоону үйрөнүп жатат. Күлбөгөнгө аракет кылыңыз, бирок алдырбаңыз. Чек араларыңызды так сактаңыз.','Krokodillipisarate kunst 🎭','Teeb võltsnuttu, väriseva häälega, et saada seda, mida tahab, ilma et tegelikult nutaks? Nad õpivad sind manipuleerima. Püüa mitte naerda, aga ära järele anna. Hoia oma piirid selged.'),
('20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce'::uuid,'Күтүлбөгөн «Сени сүйөм!» сөздөрү 💖','Бөлмөнүн ортосунда ойноп жатып, күтүлбөгөн жерден сизге карап: "Мен сизди аяяябай жакшы көрөм" дедиби? Бул бардык уйкусуз түндөргө жана чарчоого татыйт! Бул көз ирмем тартуулаган терең, өзгөчө бейпилдиктен ырахат алыңыз.','Äkilised „Ma armastan sind!“ 💖','Kas nad vaatasid keset tuba mängides äkki sulle otsa ja ütlesid: „Ma armastan sind niiii väga“? See on väärt kõiki unetuid öid ja kurnatust! Naudi sügavat ja ainulaadset rahu, mida see hetk toob.'),
('22b5d836-6305-422c-8cf7-c30a523392f2'::uuid,'Атанын жинди бийи 🕺','Кечки чыр-чатакты атасы гана чече алат. Алар музыканы катуу коюп, бөлмөнү айланып, секирип, чимирилип чогуу бийлешсин. Ал эми сиз бул шайыр энергияны сырттан сыймыктануу менен карап турсаңыз болот.','Issi pöörane tants 🕺','Ainult issi suudab selle õhtuse jonnihoo lahendada. Lase neil muusika põhja keerata ja koos toas tantsida, hüpates ja keereldes. Sina aga saad seda rõõmsat energiat uhkusega kõrvalt vaadata.'),
('909bc50f-85b7-40ab-a524-0abbcb0fac9f'::uuid,'Сиз үчүн гана 10 мүнөт ☕','Ал мультфильмге алаксып жатканда, идиш жуугучту толтурууга шашпаңыз! Диванга жамбаштаңыз. Акыры, ошол кофени ысык кезинде ичип, 10 мүнөткө энелик ролуңуздан чыгып, жөн гана өзүңүз болуңуз.','10 minutit vaid sulle ☕','Samal ajal kui nad on sellesse multikasse süvenenud, ära kiirusta nõudepesumasinat täitma! Heida diivanile. Joo lõpuks see kohv, kuni see on kuum, ja astu 10 minutiks oma ema rollist välja ning ole lihtsalt sina ise.'),
('3deb7e49-2093-4c39-a51d-8dd6fd44d138'::uuid,'Жашылчалар менен күрөш уланууда 🥦','Шорподогу кичинекей сабизди кайра көрүп, тамактануудан баш тарттыбы? Жашылчаларды эзип пюре кылып, тамактануу планы аркылуу котлеттердин ичине жашыруу – эненин эң эски жана эң пайдалуу ыкмасы. Аны колдонуңуз!','Köögiviljasõda jätkub 🥦','Nägid nad jälle seda tillukest porganditükki supis ja keeldusid söömast? Köögiviljade püreestamine ja nende toiduplaani kaudu lihapallidesse peitmine on ema vanim ja kasulikum nipp. Kasuta seda!'),
('9dd6923c-7dc5-4341-8507-b21e0f3c9ee4'::uuid,'Менин кичинекей дарыгерим келди 🩺','Ал оюнчук стетоскобун алып, көкүрөгүңүзгө коюп: "Дем алыңыз" дейт. Сиз бейтапсыз, ал болсо башкы дарыгер. Оюнга кошулуңуз, жатыңыз жана 5 мүнөткө болсо да, көзүңүздү жумуп, бул "дарылануу" учурунда эс алыңыз.','Minu väike tohter on kohal 🩺','Nad võtavad oma mängustetoskoobi, asetavad selle su rinnale ja ütlevad: „Hinga sisse.“ Sina oled patsient ja nemad on peaarst. Mängi kaasa, heida pikali ja isegi kui see on vaid 5 minutit, sule silmad ja puhka selle „ravi“ ajal.'),
('ebf71c8a-d8a3-4875-8021-e3145bf8ae06'::uuid,'Үн чектөөлөрү 🌙','Алар акыры укташты. Эми үйдөгү эң кичинекей дабыш да сизди тынчсыздандырышы мүмкүн. Жарыкты өчүрүп, телевизорду токтотуп, караңгылыктын ичиндеги бул сейрек кездешүүчү тынчтыктын таттуу ырахатын сезиңиз.','Helipiirangud 🌙','Nad on lõpuks magama jäänud. Nüüd häirib sind majas isegi kõige pisem heli. Hämarda tuled, lülita teler välja ja naudi pimeduses selle vaikuse magusat ja haruldast naudingut.'),
('19419b9a-b627-43ae-9610-e43b875264b1'::uuid,'Максаттуу сойлоо жана чуркоо 🐢','Алар эми жөн эле басуу менен чектелбей, сизден жашынып чуркап, эшиктин артынан карап жатышат. Бөлмөдөгү тоскоолдуктарды алып салып, өзүңүз да чоң баланын энергиясы менен бул «куушмай» оюнуна кошулуңуз.','Sihipärane roomamine ja jooksmine 🐢','Nad ei lepi enam ainult kõndimisega; nad jooksevad kiiresti, et sinu eest peitu pugeda, piiludes uste tagant. Tee toas takistused vabaks ja liitu selle „kullimänguga“ suure lapse energiaga.'),
('20d0afb1-a487-43f5-b6f3-0f8cd2bca864'::uuid,'Жарыкты өчүрүп, таттуу уктаңыз 🌙','Балаңыздын тезирээк уктап кетиши үчүн бөлмөдөгү ашыкча жарыктарды жана көк экрандарды өчүрүңүз. Уйку гормону (мелатонин) караңгы жана технологиясыз чөйрөдө гана тез бөлүнүп чыгат.','Tuled kustu, head und 🌙','Et aidata neil kiiremini uinuda, lülita toas välja kõik lisatuled ja sinised ekraanid. Unehormoon (melatoniin) eritub kiiresti ainult pimedas ja tehnoloogiavabas keskkonnas.'),
('c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33'::uuid,'AI, реалдуу жооптор 🤖','Балаңызда кызыктай адат (мисалы, тырмак тиштөө) пайда болуп, интернет форумдары сизди чочуттубу? Токтоңуз. Педиатр тарабынан жактырылган чыныгы себебин билүү үчүн Anacan AI''дан сураңыз жана көңүлүңүздү тынчтандырыңыз.','AI, päris vastused 🤖','Sinu lapsel on tekkinud kummaline harjumus (nt küünte närimine) ja veebifoorumid on sind hirmutanud? Peatu. Küsi Anacan AI-lt pediaatri heakskiidetud tegelikku põhjust ja rahusta oma meelt.'),
('20794d75-b46f-481d-baa5-2b85b8516d4e'::uuid,'Парктагы эркиндик 🌳','Үйдө отуруп тажаштыбы? Аларды сейил бакка алып барыңыз, кум менен ойносун, чуркап жүрүп жыгылсын жана таш теришсин. Жаратылыштагы бул эркиндик алардын мээсинин өнүгүүсү үчүн эң чоң түрткү болот.','Vabadus pargis 🌳','Olete toas kinni ja nad muutuvad rahutuks? Vii nad parki, lase neil liivaga mängida, joostes kukkuda ja kive korjata. See vabadus looduses on nende aju arengule parim tõuge.'),
('3d4fe78e-9d18-4fa4-b11f-ee7836615ee7'::uuid,'Мелатонин фабрикасы 🌙','Балаңыздын тезирээк уктап кетиши үчүн бөлмөдөгү ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин тынч, жарыгы аз жана экрансыз чөйрөдө гана тез бөлүнүп чыгат.','Melatoniinitehas 🌙','Et aidata neil kiiremini uinuda, lülita toas välja kõik lisatuled ja tahvelarvuti ekraanid. Melatoniin eritub kiiresti ainult rahulikus, hämaras ja ekraanivabas keskkonnas.'),
('5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11'::uuid,'Элестеткен коноктор келишти! ☕','Балаңыз элестеткен достору менен сүйлөшүп, аларга чай куюп берип жатабы? Бул элестетүү жөндөмүнүн туу чокусу! Бул укмуштуудай жомокчуну сыймыктануу менен четтен байкаңыз; алар азыртадан эле өз ааламын жаратып жатышат.','Kujuteldavad külalised on kohal! ☕','Kas su laps räägib kujuteldavate sõpradega ja valab neile oma toas teed? See on kujutlusvõime arengu tipp! Jälgi seda imelist jutuvestjat uhkusega kõrvalt; nad loovad juba oma universumit.'),
('19c93357-3662-4a7d-bd13-a71d938dc00a'::uuid,'Түшүндүрүп берейин! ☝️','Кичинекейиңиз сизге өтө олуттуу жана билгичтик менен келип, өзүңүз билген нерсени түшүндүрүп жатабы? Алар өз билимдерин сынап жатышат! Жылмайууңузду басууга туура келсе да, аларды өтө олуттуулук менен угуңуз.','Lase mul selgitada! ☝️','Sinu väike tuleb sinu juurde väga tõsise ja teadliku ilmega, selgitades midagi, mida sa juba tead. Nad katsetavad oma teadmisi! Isegi kui pead naeratust tagasi hoidma, kuula neid ülima tõsidusega.'),
('6ab81ee1-daa9-4300-97cb-c7dad69d9baf'::uuid,'Маанай күндөлүгүңүзгө ичиңиздегини төгүңүз 📝','Телефонуңузду алыңыз. Социалдык тармактардан башкалардын жашоосун карап отурбай, «Маанай күндөлүгүңүздү» ачып, бүгүн алар жасаган эң күлкүлүү окуяны жазып коюңуз – бул келечек үчүн баалуу эстелик. Санариптик терапия чындап эле кереметтерди жаратат!','Vala oma tunded tuju-päevikusse 📝','Võta telefon kätte. Selle asemel, et sotsiaalmeedias teiste elusid kerida, ava oma meeleolupäevik ja pane kirja kõige naljakam hetk, mida nad täna tegid – väärtuslik mälestus tulevikuks. Digitaalne teraapia teeb tõesti imesid!'),
('ee467fcc-7c51-4e6a-ba68-1e6466be7d10'::uuid,'Уйку убактысына каршылык 🥱','Алар уктоодон таптакыр баш тартып жатышабы? Бул каршылык 3 жаш курагында көп кездешет. Аларды кыйнабаңыз же ыйлатпаңыз. Жарыкты өчүрүп, ''Тынч китеп окуу убактысы'' деп жарыялоо менен күнүмдүк тартипти өзгөртүңүз.','Uinakumäss 🥱','Nad keelduvad kategooriliselt magamaminekust? See vastupanu on 3-aastaste puhul klassika. Ära sunni neid ega aja nutma. Muuda rutiini: hämarda tuled ja kuuluta välja ''vaikse raamatu aeg''.'),
('1bbd92c6-a12a-4c26-a63f-0946e226b656'::uuid,'Өзүңүздү унутпаңыз! 🥗','Аларды тойгузуу үчүн 3 башка меню ойлоп таптыңыз, бирок өзүңүз дагы эле ачка калдыңызбы? Биздин пайдалуу рецепттерден 10 мүнөттө даярдалган, темирге жана кальцийге бай эртең мененки тамакты тандап, өзүңүздү баалаңыз.','Ära unusta iseennast! 🥗','Mõtlesid välja 3 erinevat menüüd, et neid toita, aga jäid ise ikkagi nälga? Vali meie tervislike retseptide hulgast 10 minutiga valmiv raua- ja kaltsiumirikas hommikusöök ning tunne end väärtustatuna.'),
('31e8c246-42c7-4bad-8ff1-c08af53874b1'::uuid,'Күтүлбөгөн кыжырдануу 💥','Ойноп жатып, алар күтүлбөгөн жерден ачууланып, оюнчуктарын ыргытып жибериштиби? Алар эмоцияларын башкара элек. Кыйкыруунун ордуна: ''Сенин капа болгонуңду көрүп турам, кел, чогуу терең дем алалы'' деп, эмпатияны өрчүтүңүз.','Äkiline jonnihoog 💥','Kas nad läksid mänguhoos äkki vihaseks ja viskasid mänguasju? Nad ei oska veel oma emotsioone valitseda. Selle asemel, et karjuda, ütle: ''Ma näen, et oled pahane, hingame koos sügavalt sisse'' ja arenda empaatiat.'),
('1f632261-0ec6-4f1f-be74-71aaaaf4c706'::uuid,'Керектүү буюмдар азайып калдыбы? 🛒','Жалаяктар же нымдуу аарчыгычтар түгөнүп баратабы? Аларды дароо Сатып алуулар тизмеңизге кошуңуз, ошондо жолдошуңуздун телефонуна да билдирүү барат.','Esmatarbekaubad hakkavad otsa saama? 🛒','Mähkmed või niisked salvrätikud hakkavad otsa saama? Lisa need kohe oma ostunimekirja ja teavitus võib minna ka partneri telefoni.'),
('96327d67-c216-46e6-b768-6cd8fce23852'::uuid,'Жубайлардын шампаны 🥂','Бала уктады. Эгер шампан жок болсо, стакандарга ысык чай куюп, жолдошуңуз менен кагыштырып: ''Биз бул оор күндү аман-эсен өткөрдүк!'' деп айтыңыз. Сиздер бул үйдүн эң күчтүү башчыларысыздар.','Paaride šampanja 🥂','Laps magab. Kui šampanjat pole, vala klaasidesse kuuma teed, kõlksuta partneriga ja ütle: ''Me saime selle raske päeva tervelt üle elatud!'' Olete selle kodu kõige tugevamad komandörid.'),
('b8850dac-f142-4e24-bc24-56bb7962ebf6'::uuid,'Атанын «учак режими» ✈️','Кичинекейиңиздин энергиясы дагы эле ашып-ташып, уктоого каршылык көрсөтүп жатабы. Атасын жардамга чакырыңыз! Ал аларды көтөрүп, ''учактай учурганда'', бөлмө күлкүгө толуп, бардык физикалык чыңалуу секунданын ичинде жок болот.','Issi lennurežiim ✈️','Su väikesel on ikka veel liiga palju energiat ja ta tõrgub magamamineku vastu. Kutsu issi appi! Kui ta lapse üles tõstab ja lennukina lennutab, täitub tuba naeruga ja kogu füüsiline pinge kaob sekunditega.'),
('ee7e813c-5a12-4710-b655-7b294f1ff478'::uuid,'Апанын эс алуу убактысы ☕','''Бөбөктөрдүн тилинде'' сүйлөөдөн чарчадыңызбы? Биздин Энелерге ыңгайлуу жерлерден балдар бурчу бар кафе таап, кофеңизден ырахат алыңыз жана башка энелер менен баарлашып эс алыңыз.','Emme puhkepaus ☕','Tüdinenud ''titekeeles'' rääkimisest? Leia meie ''Emadesõbralike kohtade'' hulgast mängunurgaga kohvik, naudi kohvi ja lõõgastu teiste emadega vesteldes.'),
('3a35865f-054d-413c-b3ad-81c68c171c47'::uuid,'Кайра эле бөлүнүү коркунучубу? 🥺','Бөлмөдөн бир секундага чыксаңыз да балаңыз ыйлайбы? Бөлүнүү тынчсыздануусу кээде үч жаш курагында кайра пайда болушу мүмкүн. Аларды алыстан коопсуз сездирүү үчүн: ''Мен ашканадамын, келе жатам!'' деп үн катып, жанында экениңизди билдириңиз.','Jälle lahusolekuärevus? 🥺','Kas laps nutab, kui toast lahkud, kasvõi sekundiks? Lahkumisärevus võib kolmeaastastel vahel uuesti tekkida. Rahusta teda hüüdes, et oled lähedal: ''Olen köögis, tulen kohe!'', et ta tunneks end distantsilt turvaliselt.'),
('96b4e611-59a4-4d8b-a157-87f9d477e265'::uuid,'🤫 Тынчтыктын ырахаты','Ызы-чуулуу күндөн кийин, кичинекейиңиз уктаганда, бөлмөнүн тынчтыгын үн өлчөгүч менен өлчөңүз. Бул сандардын нөлгө түшүп баратканын көрүү чарчаган эненин мээси үчүн эң сонун визуалдык массаж сыяктуу сезилет.','🤫 Vaikuse mugavus','Pärast tegusat päeva, kui väike on uinunud, mõõda toa vaikust helimõõtjaga. Nende numbrite nulli poole langemise vaatamine on kui ülim visuaalne massaaž väsinud ema ajule.'),
('c1d1539d-38e2-40da-9e66-eb22e0cbbd09'::uuid,'Кынтыксыз болуу кысымы 🛑','Башка балдар түстөрдү санап жатышат, бирок сиздики кызыкпай жатабы? Салыштырууну дароо токтотуңуз! Ар бир бала өз темпинде өнүгөт. Сиздин балаңыз өз ылдамдыгы менен өнүгүп жатат жана бул толугу менен кадыресе көрүнүш.','Täiuslikkuse surve 🛑','Teised lapsed loevad juba värve, aga sinu oma pole huvitatud? Lõpeta kohe võrdlemine! Iga laps areneb omas tempos. Sinu laps areneb oma kiirusega ja see on täiesti normaalne.'),
('2d61ffa4-9df3-4b29-acca-6b87ebc82745'::uuid,'Апалардын колдоо тобу 💬','Оор күн өткөрүп, бардыгы чарчатып жибердиби? Anacan Коомчулугундагы тажрыйбалуу энелердин кеңештери эч бир китептен табылбаган чыныгы жашоодогу чечимдерди сунуштайт. Илхамыңызды ошол жерден табыңыз.','Emade tugigrupp 💬','On raske päev ja kõik tundub üle jõu käiv? Anacani kogukonna kogenud emade nõuanded pakuvad elulisi lahendusi, mida ühestki raamatust ei leia. Leia sealt inspiratsiooni.'),
('58d0ef6e-2eed-490f-85f9-8fd8f899a9bd'::uuid,'Үйдөгү башаламандыкты кабыл алуу 🌪️','Бөлмө оюнчуктарга толуп кеттиби? Кеп тазалыкта эмес; алар менен бөлүшкөн бул оюн учурлары чындап маанилүү. Оюнчуктар эртең деле ошол жерде болот, өзүңүздү чарчатпаңыз. Кээде башаламандыкка багынып берүү — эс алуунун эң жакшы жолу.','Koduse kaose omaksvõtt 🌪️','Tuba on mänguasju täis? Asi pole korras, vaid nendes mänguhetkedes, mida te jagate. Mänguasjad on homme ka alles, ära kurna end. Mõnikord on segadusega leppimine parim puhkusevorm.'),
('d52a333c-1a4b-40fd-a11c-b3544628c6df'::uuid,'Атанын жашыруун тактикалары 👨‍🍼','Күндүзгү чарчооңуз жетиштүү болду! Бул кечте кичинекейиңизди уктоого даярдоо жана тишин жуудуруу сыяктуу оюн-күлкүлүү иштерди атасы аткарсын, ал эми сиз бир четте тынч эс алып, күч топтоңуз.','Issi salataktikad 👨‍🍼','Sul on päevasest kurnatusest kõrini! Las täna õhtul tegeleb issi lapse magamamineku ja hammaste pesuga, samal ajal kui sina vaikselt kõrval puhkad ja akusid laed.'),
('dbff772c-4b84-4bcd-8132-9e03a5a6d600'::uuid,'Өзгөчө жакын дос 🥄','Ушунча кымбат оюнчуктардын арасынан балаңыз ашканадан силикон калакчаны таап алып, аны күнү бою көтөрүп жүрүп, ал тургай уктатып жатабы? Баланын мээси укмуштуудай. Кийлигишпеңиз; алар калакчасын жакшы көрө беришсин!','Omapärane parim sõber 🥄','Kõigi nende kallite mänguasjade keskel leiab laps köögist silikoonist spaatli, kannab seda terve päeva kaasas ja paneb isegi magama? Lapse aju on uskumatu. Ära sekku, lase tal oma spaatlit armastada!'),
('5e23814c-ef4e-4708-8223-e1ab2ac7daa9'::uuid,'Шыбырап уктоо 🌙','Бөлмөнүн жарыгын толугу менен өчүрүңүз. Алардын жанына жатып, кулагына күндүн окуялары жөнүндө акырын шыбыраңыз. Шыбыроо — алардын мээсин уктоого даярдоонун эң табигый жана күчтүү жолу, ал күндүн ызы-чуусун акырын унуттурат.','Sosistatud uni 🌙','Hämarda toas tuled täielikult. Heida tema kõrvale ja sosista talle vaikselt kõrva sisse päeva sündmustest. Sosistamine on kõige loomulikum ja võimsam viis valmistada aju ette uneks, hajutades õrnalt päeva müra.'),
('e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c'::uuid,'Дүкөн тизмесинен сюрприз 🛒','Дүкөнгө барар алдында сатып алуулар тизмеңизди ачсаңыз, алардын акырын келип, телефондун экранын басып, ага шоколад кошуп койгонун көрдүңүз. Ооба, алар технологияны сизден жакшы билишет!','Üllatus ostunimekirjas 🛒','Avasid enne poodi minekut ostunimekirja ja nägid, kuidas ta hiilis ligi, toksas ekraani ja lisas sinna šokolaadi. Jah, nad tunnevad tehnoloogiat paremini kui sina!'),
('fc07a24b-5d02-4f37-9d95-b46ab5b5f190'::uuid,'Максаттуу башаламандык 🧱','Алар мунараны кылдаттык менен куруп, анан аны бир уруп кубануу менен кулатышат. Алар физиканы жана себеп-натыйжаны үйрөнүп жатышат! Капа болбоңуз; ал кулаган мунаралар — алардын мээсинде пайда болуп жаткан жаңы нейрондук байланыштар.','Sihipärane kaos 🧱','Nad ehitavad vaevaga torni, et see siis ühe hoobiga rõõmsalt ümber lükata. Nad õpivad füüsikat ja põhjus-tagajärg seoseid! Ära pahanda; need kokkukukkuvad tornid on uued närviühendused nende ajus.'),
('5242afc1-567f-496d-81cf-522c0271690e'::uuid,'Сыйкыр алардын колунда 🪄','Баягы эле эски классикалык уктоо алдындагы жомоктордон чарчадыңызбы? ''Smart Tales''ти ачып, балаңызды башкы каарманга, ал эми анын бөлмөсүн куткарыла турган сыйкырдуу жерге айлантыңыз. Өзгөчө, тынч жана укмуштуудай кыялдануу менен коштолгон уктоо сеансын жаратыңыз!','Maagia on nende kätes 🪄','Tüdinenud vanadest klassikalistest unejuttudest? Ava ''Nutikad lood'', tee oma lapsest peategelane ja tema toast paik, mida päästa. Loo erakordne, vaikne ja imeliselt fantaasiarikas unehetk!'),
('d5e65c0a-6f82-4fee-945e-ee1f72e84c4a'::uuid,'«Өзүм жасай алам!» фазасы 🛑','Алар бут кийиминин боосун өздөрү байлагысы келип, ага 10 мүнөт кетип жатабы? Аларды шаштырбаңыз, убакыт бериңиз. Алардын аракеттери жана каталары — келечектеги көйгөйлөрдү чечүү жөндөмдөрүнүн пайдубалы.','„Ma teen ise!“ faas 🛑','Nad tahavad ise paelu siduda ja see võtab 10 minutit? Ära kiirusta, anna neile aega. Nende katsed ja eksimused on vundament tulevastele probleemilahendusoskustele.'),
('aa798243-c44e-4178-957c-647030916048'::uuid,'Аба ырайы боюнча эскертүү ⛅','Сейилдөөгө чыгар алдында терезени карап эле алданып калбаңыз. Сырттагы чыныгы шамал жана температура үчүн эң сонун айкалышты аныктоо үчүн Аба ырайы жана кийим жардамчысын колдонуңуз жана үйдөн ыңгайлуу жана даяр болуп чыгыңыз.','Ilmateade ⛅','Ära lase end petta vaid aknast välja vaatamisest, kui oled jalutama minemas. Kasuta ''Ilma ja riietuse assistenti'', et määrata täiuslik kombinatsioon väljas valitseva tuule ja temperatuuri järgi ning lahku kodust mugavalt ja ettevalmistatult.'),
('b3ff48b4-aa5c-406e-999b-73655dca1c90'::uuid,'Мультфильм сынчысы 📺','Балаңыз жаңы эле көргөн мультфильми жөнүндө айтып, ким кайда барганын өзүнүн өзгөчө грамматикасы жана олуттуу ишеними менен түшүндүрүп жатат. Толугу менен таң калгандай кунт коюп угуңуз. Алар өздөрүн дүйнөдөгү эң акылдуу адам катары сезишсин.','Multikakriitik 📺','Su laps räägib sulle just vaadatud multikast, selgitades oma unikaalse grammatika ja tõsise veendumusega, kes kuhu läks. Kuula tähelepanelikult, justkui oleksid täiesti hämmastunud. Lase tal tunda end maailma kõige targema inimesena.'),
('c83099cc-b126-47d8-b334-d8faf9b45dde'::uuid,'🌙 Караңгылыктын күчү','Алардын тезирээк уктап калышына жардам берүү үчүн, бөлмөдөгү бардык ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин (уйку гормону) караңгы, технологиясыз чөйрөдө гана тез бөлүнүп чыгат.','🌙 Pimeduse vägi','Et aidata neil kiiremini uinuda, lülita toas välja kõik lisatuled ja tahvelarvutid. Melatoniin (unehormoon) eritub kiiresti vaid pimedas ja tehnoloogiavabas keskkonnas.'),
('9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b'::uuid,'Тандап жегендер 🥦','Алар кечээ эле жакшы көргөн тамагына ''жок'' деп жатышабы? 3 жашта тамакты ылгап жеш кадыресе көрүнүш. Алардын көңүлүн ача турган биздин пайдалуу рецепттерден түстүү жана кызыктуу жасалгаларды табыңыз.','Valivad sööjad 🥦','Nad ütlevad ''ei'' toidule, mida eile armastasid? Valiv söömine on 3-aastaselt normaalne. Leia meie tervislike retseptide hulgast värvilisi ja lõbusaid esitusviise, mis neid köidavad.'),
('b755d54c-d2cb-47a2-92bb-44a36d855874'::uuid,'Фантазиянын учушу 🚀','Алар эми жөн эле ойноп жаткан жок; алар сценарийлерди түзүп жатышат! Картон кутусу заматта космос кемесине айланат. Бул таанып-билүү секиригин өнүгүү трекериңизге сыймыктануу менен белгилеп, алардын кыялдануу оюнуна кошулуңуз.','Kujutlusvõime lendab 🚀','Nad ei mängi enam lihtsalt; nad loovad stsenaariume! Pappkast muutub hetkega kosmoselaevaks. Märgi see kognitiivne hüpe uhkusega oma arengupäevikusse ja liitu nende fantaasiamänguga.'),
('ef6fe3c1-b830-477f-93ee-842f8b450ab9'::uuid,'🌙 Күнүмдүк жыйынтык','Уктаар алдында жарыкты бүдөмүктөтүп, бүгүн сизди эмне көбүрөөк күлдүргөнү жөнүндө баарлашыңыз. Уктоо алдындагы бул кичинекей сүйлөшүүлөр алардын өз оюн билдирүү жөндөмүн өркүндөтүү үчүн эң сонун.','🌙 Päeva kokkuvõte','Enne und hämarda tuled ja vestle sellest, mis sind täna kõige rohkem naerma ajas. Need väikesed une-eelsed vestlused on suurepärased nende väljendusoskuse lihvimiseks.'),
('56159a04-f4fe-4e35-a3dd-8bcc4853f3c9'::uuid,'Атанын учак режими ✈️','Алар үйдү айланып чуркап, уктоодон баш тартып жатышат. Атасын жардамга чакырыңыз! Ал аларды ''учактай учуруу'' үчүн бийик көтөргөндө, бөлмө күлкүгө толуп, топтолуп калган бардык физикалык энергия бактылуу күлкү менен секунданын ичинде жок болот.','Issi lennurežiim ✈️','Nad jooksevad mööda maja ega taha voodisse minna. Kutsu issi appi! Kui ta tõstab nad ''lennukisõiduks'' kõrgele, täitub tuba naerupahvakutega ja kogu füüsiline energia kaob sekunditega rõõmsate kilgete saatel.'),
('69ac9098-fc9c-4474-aa9d-090c0c3f7cdf'::uuid,'Таңкы саат 6дагы режиссёр 🎬','Сиз дагы эле уктап жатасыз, бирок алар башыңызда турушат: ''Сиз аюу болуңуз, мен коён болом!'' Жарым уйкуда, арылдаган үндөрдү чыгарып, бул абсурддуу театрда өз ролуңузду ойноңуз. Энелик кээде эң мыкты актёрдук чеберчиликти талап кылат.','Kell 6 hommikul režissöör 🎬','Sina veel magad, aga nemad seisavad su pea kohal: ''Sina ole karu, mina olen jänku!'' Poolunes tee urisevaid hääli ja mängi oma rolli selles absurdses teatris. Emadus nõuab vahel parimaid näitlejaoskusi.'),
('aa6e4c45-6848-4e91-8836-f55617de9313'::uuid,'Коомчулук менен байланыш 💬','Сиз аябай чарчадыңыз жана эч кимге эч нерсе түшүндүргүңүз келбейт. Жөн гана Anacan Коомчулугуна окурман катары кошулуңуз. Башка энелердин да ушундай эле чарчоо менен бөлүшүп жатканын көрүү — ''мен жалгыз эмесмин'' деген сезимди жаратуучу эң мыкты терапия.','Kogukonnaga ühenduses 💬','Oled täiesti kurnatud ega taha kellelegi midagi selgitada. Liitu lihtsalt Anacani kogukonnaga lugejana. Teiste emade sarnase kurnatuse jagamise nägemine on parim teraapia, luues tunde ''ma pole üksi''.'),
('7b3c2751-f23f-4467-abdf-9463831a86cb'::uuid,'🤫 Санариптик тынчтыктын кубанычы','Алар акыры уктап калышты! Үйгө орногон тынчтык ушунчалык терең болгондуктан, кулагыңызга дээрлик жаңырып угулат. Үн өлчөгүчүңүздү иштетип, 0-10 децибел сандарын карап жатып, мээңиздин акырындык менен калыбына келип жатканын визуалдык түрдө сезиңиз.','🤫 Digitaalse vaikuse rõõm','Nad jäid lõpuks magama! Majja laskuv vaikus on nii sügav, et lausa kohiseb kõrvus. Aktiveeri helimõõtja ja koge visuaalselt, kuidas su aju aeglaselt taastub, vaadates neid 0-10 detsibelliseid numbreid.'),
('7d093b24-909b-4f92-b3df-fe627f2322c0'::uuid,'Арабаны мен түртөм! 🛒','Алар дүкөн арабасын сөзсүз өздөрү түрткүсү келип, акыры текчелерди сүзүп жатасызбы. Алардын көңүлүн калтырбоо үчүн, арабаны сиз менен чогуу түртүүсүнө уруксат бериңиз. Ал эми унутчаактыкка каршы, тиркемеде сатып алуулар тизмеңизди ачык кармаңыз.','Mina lükkan käru! 🛒','Nad nõuavad kindlalt, et tohivad ise ostukäru lükata, ja sina põrkad vastu riiuleid. Et nende indu mitte murda, lase neil käru koos sinuga lükata. Ja unustamise vastu hoia ostunimekirja äpis avatuna.'),
('803c4a83-8bb9-4a65-a6e0-a757e4e816cf'::uuid,'Сүйлөмдөрүмдү бүтүрүп кой 🗣️','Алар бир сөздү унутуп калганда, сиздин табышыңызды күтүп жаңсоолорду жасашабы? ''Аа, сен топту айтып жатасыңбы?'' дегениңиздеги алардын жеңилдеп калган учурун байкаңыз. Алардын сөз байлыгы кеңейип жатат, бирок кээде мээси тилинен тезирээк иштейт.','Lõpeta minu laused 🗣️','Kui nad sõna unustavad, kas nad teevad žeste, oodates, et sa ära arvaksid? Vaata seda kergenduse hetke, kui ütled: ''Ah, sa mõtled palli?'' Nende sõnavara laieneb, kuid vahel töötab aju keelest kiiremini.'),
('5625eb93-64b3-45e9-9346-29a2c6af885f'::uuid,'Жаратылыш менен детокс сөзсүз керек 🌳','Алар үйдө камалып калганда энергиясы агрессияга айланат. Аба ырайына же эмне кийип жүргөнүнө карабастан, алардын туура кийингенин текшерип, сыртка алып чыгыңыз. Жерге тийүү жана жалбырактарды чогултуу алардын нерв системасын заматта тынчтандырат.','Loodusdetoks on hädavajalik 🌳','Nende energia muutub siseruumidesse kinni jäädes agressiivsuseks. Sõltumata ilmast või riietusest, veendu, et nad on korralikult varustatud ja vii nad õue. Maa puudutamine ja lehtede korjamine rahustab nende närvisüsteemi hetkega.'),
('d33d70dc-19c8-4087-8ed8-270685911bfd'::uuid,'🌙 Шыбыроонун сыйкырдуу күчү','Үн байламталарыңыз жомок айтуудан чарчады. Бөлмөнүн жарыгын толугу менен өчүрүңүз. Анын жанына жатып, кулагына күндүз болгон окуяларды акырын шыбыраңыз. Шыбыроо — кичинекей мээни уйкуга даярдоонун эң тынчтандыруучу жолу.','🌙 Sosinate müstiline vägi','Sinu häälepaelad on jutustamisest väsinud. Kustuta toas tuled täielikult. Heida nende kõrvale pikali ja sosista vaikselt kõrva sisse lugusid sellest, kuidas päev möödus. Sosistamine on tõepoolest kõige rahustavam viis valmistada nende väike aju uneks ette.'),
('e578603f-02ec-4734-b19f-2d0ca949a8e2'::uuid,'Укмуштуудай жандык 🎈','Бул узак сапарда таң кала турган нерселер абдан көп. Мисалы, кечээ эле үйрөнгөн сөзүн бүгүн философиялык сүйлөмдө колдонушу! Бул күндөр кайра кайтып келбейт.','Imeline olend 🎈','Sellel pikal teekonnal on nii palju, mida imetleda. Näiteks see, kui nad kasutavad eile õpitud sõna täna täiesti filosoofilises lauses! Need päevad ei kordu enam kunagi.'),
('0cdb7f22-d990-414a-b36e-54d6d47e1b4f'::uuid,'Жашыруун шоколад тыныгуусу 🍫','Апасы, ашкана шкафынын артында жашыруун шоколад жеп жатасызбы — бул глюкоза Сиздики! Өзүңүздү күнөөлөбөңүз! Мындай чексиз энергияга туруштук берүү үчүн Сизге күч керек. Терең дем алып, таттууңуздан ырахат алыңыз.','Salajane šokolaadipaus 🍫','Emme, šokolaadi söömine köögikapi taga – see glükoos on sinu oma! Ära süüdista ennast! Pead end laadima, et selle hullumeelse energiaga sammu pidada. Hinga sügavalt sisse ja näksi edasi.'),
('62a2e4b7-b7ef-4d46-a134-22e1f4da5625'::uuid,'🪄 Акылдуу жомоктун башкы каарманы алар','Бүгүн кечинде «Smart Tales» бөлүмүндөгү жомоктун каарманына балаңыздын атын бериңиз. Тиш жуубаганына өкүнгөн каарман жөнүндө айтып берип, Сиз баалуу сабактарды кызыктуу жол менен үйрөтө аласыз.','🪄 Nad on nutika loo staarid','Täna õhtul pane „Nutikates muinasjuttudes“ kangelasele oma lapse nimi. Jutustades lugu, kus tegelane kahetseb hammaste pesemata jätmist, saad märkamatult ja lõbusalt edasi anda väärtuslikke õppetunde.'),
('ce8759a7-ff69-4b27-a788-668b48e71999'::uuid,'Даарат кагазынын инженери 🧻','Бир нече мүнөттүк жымжырттык... анан бөлмөгө кирсеңиз, даараткана кагаздарынын баары чечилип, үйгө чачылып калыптыр! Ачуулангандын ордуна, кагаздарды чогултуп, чогуу ак калаа жасаңыз. Башаламандыкты чыгармачылык менен жеңиңиз.','Tualettpaberi insener 🧻','Mõni minut vaikust... ja siis tuppa astudes leiad, et kogu tualettpaber on lahti rullitud ja mööda maja laiali! Selle asemel, et pahandada, korja paber kokku ja tehke koos lumememm. Võida kaos loovusega.'),
('1f94fede-7afb-4d0a-8e39-07ab7d2da0c4'::uuid,'Сиз бала болуңуз, мен апасы болоюн 👩‍👧','Ролдорду алмашуу оюну башталды! Эми балаңыз Сизге көрсөтмө берип жатат: «Бери кел, тамагыңды же!» Бул лидерлик тажрыйбаны кубаныч менен кабыл алып, анын баласынын ролун акырын аткарып бериңиз.','Ole sina laps, mina olen ema 👩‍👧','Rollide vahetamise mäng on alanud! Sinu laps jagab nüüd sulle korraldusi: „Tule siia, söö oma toitu!“ Võta seda juhtimiskogemust suure rõõmuga ja mängi vaikselt nende lapse rolli.'),
('77330b1b-94b4-4438-9dd4-9ea117490b54'::uuid,'Жашоо үчүн жасалма интеллект (AI) 🤖','Эмне үчүн 3 жашар бала күтүүсүздөн тырмагын тиштей баштайт? Интернеттеги коркунучтуу, травмалык макалаларды унутуңуз. Anacan AI''дан бул жөн гана убактылуу стресстик реакциябы же жокпу, сурап көрүңүз жана илимий жооп алыңыз.','AI päriselu lahendusteks 🤖','Miks peaks 3-aastane äkki küüsi närima hakkama? Unusta interneti hirmutavad ja traumaatilised artiklid. Küsi Anacan AI-lt, kas see on lihtsalt ajutine stressireaktsioon, ja saa teaduslik vastus.'),
('e7437e5e-38bf-45b1-8db0-74786f20b535'::uuid,'Жубайлар үчүн тыныгуу 🥂','Бала уктады. Эми телефондорду жана үй жумуштарын четке жыйыңыз. Түгөйүңүз менен бетме-бет отуруп, 20 мүнөт таптакыр башка нерселер жөнүндө сүйлөшүңүз — эсеп-кысаптан жана балдардан башкасынын баары. Эсиңизде болсун, Сиздер биринчи кезекте жубайсыздар!','Paaride puhkehetk 🥂','Laps magab. Nüüd pane telefonid ja kodutööd kõrvale. Istuge partneriga näost näkku ja rääkige 20 minutit millestki täiesti muust – millest iganes, aga mitte arvetest ja lastest. Pidage meeles, et olete ka paar!'),
('3a4c5cc8-5f54-4aef-b016-9394a079ec83'::uuid,'Чөнтөктөгү табылгалар 🪨','Шымын жууп жатып, чөнтөгүнөн үч башка көлөмдөгү таш жана каштандын кабыгын таптыңызбы? Алар үчүн бул дүйнөдөгү эң баалуу коллекция. Аларды ыргытып жибербей, кичинекей кутуга чогултуп, «кенч сандыгын» жасаңыз.','Taskusse mahtuvad leiud 🪨','Kas leidsid pükse pestes taskust kolm erinevas suuruses kivi ja kastanimuna? Nende jaoks on see maailma kõige väärtuslikum kollektsioon. Selle asemel, et need ära visata, pane need väikesesse karpi ja looge koos aardekirst.'),
('68c1a1ff-c119-4521-aae1-9a7a984caad7'::uuid,'Жарыкты өчүрүңүз, уйку келет 🌙','Тезирээк уктап калуусуна жардам берүү үчүн, уктоого кеминде бир саат калганда бөлмөдөгү бардык кошумча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин (уйку гормону) караңгы жана технологиясыз чөйрөдө гана тез бөлүнүп чыгат.','Tuled kustu, uni tuleb 🌙','Et nad kiiremini uinuksid, lülita vähemalt tund enne magamaminekut toas välja kõik lisatuled ja tahvelarvutite ekraanid. Melatoniin (unehormoon) eritub kiiresti vaid pimedas ja tehnoloogiavabas keskkonnas.'),
('9021ef15-5cf5-4f9d-8592-aab7e32c65a0'::uuid,'Чарчоо сезими 🔋','Баарына кыйкыргыңыз келип жатабы? Чуу мээңизди тешип бара жатабы? Бул — классикалык чарчоо. Баланы дароо коопсуз жерге калтырыңыз (же атасына бериңиз), бөлмөңүзгө кирип, бардык стрессиңизди «Маанай күндөлүгүнө» жазыңыз.','Läbipõlemise tunne 🔋','Kas tunned, et tahaksid kõige peale karjuda? Kas müra puurib su ajus? See on klassikaline läbipõlemine. Pane laps kohe turvalisse kohta (või anna isa kätte), mine oma tuppa ja kirjuta kogu oma filtreerimata stress meeleolupäevikusse.'),
('a5815a11-4b6f-4f3d-a6ff-4d587c286a65'::uuid,'Музыка менен ойгонуу 🎶','Күн чыга элек, бирок ал төшөктө секирип, ритмдүү үндөрдү чыгарып жатат. Бул дүйнөдөгү эң катуу, бирок эң сүйүктүү ойготкуч! Күнүңүздү анын чексиз энергиясына жылмайып баштаңыз.','Muusika saatel ärkamine 🎶','Päike pole veel korralikult tõusnudki, aga nemad juba hüppavad voodis ja teevad rütmilisi hääli. See on maailma kõige valjem, kuid samas kõige armsam äratuskell! Alusta oma päeva naeratades nende piiritule energiale.'),
('afb9fd4f-60e2-4547-87e2-d867963a1345'::uuid,'Сезимдериңизди белгилеп туруңуз 📝','Кичинекейиңиз уктагандан кийин, «Маанай күндөлүгүңүздү» ачыңыз. Анын бүгүн кылган эң күлкүлүү, таң калыштуу окуясын жазып коюңуз — бул баалуу эс тутум. Жылдар өткөндөн кийин аны окуу Сиздин көзүңүзгө жаш тегеретет.','Tunnete kirjapanek 📝','Kui su väike on uinunud, ava oma meeleolupäevik. Pane kirja kõige naljakam ja absurdsem hetk, mille nad täna tekitasid – mälestus, mida hoida. Aastate pärast seda lugedes tulevad sul kindlasti pisarad silma.'),
('db2d884d-1367-4ebc-a61b-9a450673d64d'::uuid,'Тынч убакыт практикасы','Күндүз уктагысы келбей жатабы, бирок көздөрү илинип баратабы? «3 жашар баланын уйкуга каршылыгы» — бул кадимки көрүнүш. Мажбурлабаңыз. Анын ордуна бөлмөнүн жарыгын азайтып, «тынч китеп окуу убактысын» жарыялап, жаңы тартип киргизиңиз.','Vaikusehetke praktika','Ei taha uinakut teha, aga silmad on unest rasked? „3-aastaste unevastupanu“ on klassika. Ära sunni. Selle asemel hämarda toas tuled ja tutvusta uut rutiini, kuulutades välja „vaikse raamatuaja“.'),
('0f647bd8-9749-4a55-969b-bfc85ddb7152'::uuid,'Атанын жашыруун куралы 🤡','Сиздин кадимки ыкмаларыңыз иштебей калганда, атасынын кызыктай үндөрү жана күлкүлүү жүздөрү абалды заматта сактап калат! Кечки ызы-чуу учурунда эстафетаны ага бериңиз жана четте тынчтанып, сыйкырдуу көз ирмемге күбө болуңуз.','Issi salarelv 🤡','Kui su tavalised nipid enam ei tööta, võivad isa rumalad hääled ja naljakad näod päeva hetkega päästa! Õhtuste jonnihoogude ajal anna teatepulk talle üle ja vaata kõrvalt, kuidas maagia sünnib, nautides ise hetke rahu.'),
('c30ee50d-9665-4368-af0d-6578c2cc302b'::uuid,'Денеңизди угуңуз','Себепсиз чарчап, ыйлагыңыз келип жатабы? «Этек кир календарын» ачыңыз. Денеңиз Сизге белги берип жатат. Биздин пайдалуу рецепттерден магнийге бай тамак тандап, өзүңүзгө кам көрүңүз.','Kuula oma keha','Tunned end seletamatult väsinuna ja nutusena? Ava oma tsüklikalender. Sinu keha saadab signaale. Ole enda vastu hea ja haara mõni magneesiumirikas suupiste meie tervislike retseptide hulgast.'),
('c49b057e-0774-42da-aec0-ee5fcc238471'::uuid,'Тандап жеген бала 🍝','Кичинекейиңиз 2-3 эле жакшы көргөн тамагын жеп жатабы? Кабатыр болбоңуз! Анын жумалык балансын көзөмөлдөө үчүн тамактануу трекерин колдонуңуз жана тамактануу учурунда басым жасабаңыз.','Valiv sööja 🍝','Kas su väike sööb vaid 2-3 lemmiktoitu? Ära muretse! Kasuta toitumispäevikut, et jälgida iganädalast tasakaalu ja vältida söögiaegset survet.'),
('462a51f8-d8f0-4c41-8551-81fbd18e8c62'::uuid,'Алар өз жомогун өздөрү жазышат 🪄','Кадимки китептерден тажадыңызбы? «Smart Tales» бөлүмүн ачып, бүгүн кечинде окуянын жүрүшүн балага багыттатыңыз! «Машина эми кайда барышы керек?» деп сураңыз жана ал ойлоп тапкан кызыктуу аяктоо менен уктап калуусуна мүмкүнчүлүк бериңиз.','Nad kirjutavad oma lõpu ise 🪄','Tüdinenud tavalistest raamatutest? Ava „Nutikad muinasjutud“ ja lase neil täna õhtul süžeed juhtida! Küsi: „Kuhu auto nüüd sõitma peaks?“ ja lase neil uinuda nende endi loodud imeliselt absurdse lõpuga.'),
('a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb'::uuid,'Кемчиликсиз эне мифи','Социалдык тармактардагы балдар ыр айтып жатышат, ал эми Сиздики дагы деле сөздөрдү алмаштырып жатабы? Салыштырууну токтотуңуз! Ар бир баланын өнүгүү темпи өзгөчө. Алар өз темпинде эң сонун өнүгүп жатышат.','Täiusliku ema müüt','Sotsiaalmeedias lapsed juba loevad luuletusi, aga sinu oma ajab veel sõnu sassi? Lõpeta kohe võrdlemine! Iga lapse arengutempo on unikaalne. Nad on täiuslikud omaenda tempos.'),
('fca7853a-0c3e-4553-8c15-c32fa7564774'::uuid,'Бут кийим кийүү олимпиадасы 👟','Оң бут кийимин сол бутуна кийип алып, чечүүдөн баш тартып жатабы? Мейли, кие берсин! «Өзүм кылдым» деген сыймыктануу жана эркиндик сезими туура кийгенден алда канча маанилүү. Бул анын келечектеги маселелерди чечүү жөндөмүнүн алгачкы кадамы.','Kingade jalgapanemise olümpiamängud 👟','Panid parema kinga vasakusse jalga ja keelduvad kategooriliselt seda ära võtmast? Las nad olla! Iseseisvustunne ja uhkus „ma sain ise hakkama“ on palju olulisem kui õigesti tegemine. See on ka vundament nende tulevastele probleemilahendusoskustele.'),
('344d14b0-cfc9-4ff3-af6f-44e0148ab198'::uuid,'Көрүнбөгөн башаламандык кырсыгы 🗑️','Алар өздөрү ыргытып жиберген (жана Сиз таштандыга салган) «керексиз» кагазды издеп ыйлап жатышабы? Бул — 3 жашар баланын логикасы. Аны кайтарып бере албагандыктан, көңүлүн дароо башка кызыктуу нерсеге буруңуз.','Nähtamatu segaduse katastroof 🗑️','Nad nutavad ja otsivad seda „kasutut“ paberitükki, mille nad ära viskasid (ja mille sina õigustatult prügikasti panid)! See on 3-aastase loogika täies hiilguses. Kuna sa seda tagasi tuua ei saa, siis hajuta nende tähelepanu millegi palju säravamaga.'),
('be71bad2-041d-4cb4-a658-89cb36e8a738'::uuid,'Апанын күч-кубат алуу убактысы','Ал 10 мүнөттөн бери баш катырма менен алек болуп жатат. Сиз бул убакытты үй жыйноого колдонгуңуз келеби? Жок! Диванга жатыңыз. Кечке чейин күчүңүз жетиши үчүн Сиздин да «батарейкаңызды» толтуруу керек.','Emme taastumisaeg','Nad on 10 minutit vaikselt puslega ametis. Tahad seda hetke kasutada koristamiseks? Ei! Heida diivanile pikali. Sinu akud vajavad samuti laadimist, et suudaksid õhtuni samas tempos jätkata.'),
('d2f93631-6ef4-4ba4-9cac-259dafd2fb22'::uuid,'Караңгылыкты кабыл алуу 🌙','Уктоочу бөлмөнүн жарыгы өчкөндө ал тынчсызданып жатабы? Бөлмөнүн бир бурчуна кичинекей, жылуу түстөгү (сары же кызгылт сары) түнкү чырак коюңуз. Терең уйку үчүн бөлмөнүн калган бөлүгү толугу менен караңгы болушу керек.','Pimeduse omaksvõtmine 🌙','Kas nad on magamistoas tulede kustudes ärevil? Pane toa nurka väike soojatooniline (kollane või oranž) öölamp. Ülejäänud tuba peaks sügavaks uneks jääma täiesti pimedaks.'),
('5407f02f-f40a-48e1-b4f8-80cd1fc9345c'::uuid,'Эртең мененки диктатор 👑','«Ал жерге отурбаңыз, менин мамалагым отурат!» Эртең мененки тамакта баарын ал башкарып жатат. Анын чечкиндүүлүгүн сындырбай, «Макул, мамалак тигил жерге отурсун, мен бул жерге отурам» деп тең салмактуулукту сактаңыз.','Hommikune diktaator 👑','Ära siia istu, mu kaisukaru istub siia! Nad juhivad hommikusöögilauas täielikult vägesid. Ilma nende enesekehtestamist maha surumata säilita tasakaal, öeldes: „Olgu, kaisukaru võib seal istuda ja mina istun siin.“'),
('a1a50d57-7314-4042-848d-a89f6c8fc209'::uuid,'Жаратылыш кучагына качуу','Төрт дубалдын ичинде экөөңүздөр тең тынчсызданып жатасызбы. Аба ырайын жана ылайыктуу кийимди текшерип, түз эле паркка жөнөңүз. Сыртта эркин чуркоо кичинекей баланын эң катуу ачуулануусун да бычак менен кескендей токтото алат.','Põgenemine loodusesse','Nelja seina vahel kinni olles muutute mõlemad rahutuks. Kontrolli ilma ja sobivat riietust ning suundu otse parki. Vabas õhus jooksmine ja vabadusetunne võivad lõigata läbi ka kõige intensiivsemad jonnihood nagu nuga.'),
('e61af62b-257c-41ec-8846-9d470f2646d9'::uuid,'Тынч түнкү ванналар 🛀','Күнү бою «каалабайм» деген сөздөр айтылдыбы. Жылуу ванна — бул жөн гана гигиена эмес; бул анын ашыкча иштеген нерв системасын калыбына келтирүү. Суунун үнү жана жылуулугу бардык өжөрлүктү жууп кетет.','Rahulikud õhtused vanniskäigud 🛀','Terve päev oli täis „ma ei taha“. Soe vann pole ainult hügieeniks; see on nende ülestimuleeritud närvisüsteemi lähtestamiseks. Vee heli ja soojus pesevad kogu jonni maha.'),
('8169372c-8d17-46fc-bfc3-eda3a929eaa6'::uuid,'Дүкөндөгү «энелик мээ»','Эс тутумуңузга ишенип дүкөнгө барып, жалаяк алганды унутуп калдыңызбы? Мындай болуп турат! Бардык муктаждыктарыңызды дароо «Соода тизмесине» кошууну адат кылыңыз; колдонмо Сиздин санариптик эс тутумуңуз болсун.','Emme aju toidupoes','Kas usaldasid oma mälu, läksid poodi ja tulid koju mähkmeid ostmata? Juhtub! Tee harjumuseks lisada kõik vajadused kohe ostunimekirja; las äpp olla sinu digitaalne mälu.'),
('a15765ea-b7ce-42a7-91ae-209256ee1beb'::uuid,'Апа, мага караңызчы! 👀','Сиз телефон карап же иштеп жатканда, ал келип колуңузду түртөт же алдыңызда туруп алат. Ал таптакыр туура кылат — ал Сиздин толук көңүл бурууңузду каалап жатат. Болгону 5 мүнөт көзүнө тике карап чогуу ойноо аны дароо тынчтандырат.','Emme, vaata mind! 👀','Kui vaatad telefoni või töötad, tulevad nad su kätt patsutama või seisavad otse su ees. Neil on täiesti õigus – nad janunevad sinu jagamatu tähelepanu järele. Vaid 5 minutit katkematut silmside-mängu rahustab nad kohe maha.'),
('de1347cd-769b-44d4-8aff-75ce2b7d2f0c'::uuid,'Жымжырттыктын күчү 🤫','Ызы-чуулуу күндөн кийин бала уктаганда, бөлмөнүн тынчтыгын текшерүү үчүн «Үн өлчөгүчтү» колдонуңуз. Ал сандардын нөлгө жакындаганын көрүү — эненин мээси үчүн эң сонун массаж сыяктуу таасир берет.','Vaikuse vägi 🤫','Pärast lärmakat päeva, kui laps magab, kasuta helimõõdikut, et kontrollida toa vaikust. Nende nulli lähenevate numbrite nägemine, see visuaalne rahu, mõjub ema ajule kui kõige imelisem massaaž.'),
('0ff315d9-2ad1-4c8c-9187-ea4c26042a66'::uuid,'Убакыт кандай тез өтөт!','Ал буга чейин эле өзүнүн эрки жана чечимдери бар кичинекей инсан. Бул күчтүү мүнөз келечекте Сизди сыймыкка бөлөйт. Бул баалуу күндөр түбөлүккө созулбайт, ошондуктан аны бүт сүйүүңүз менен кучактаңыз.','Kuidas aeg lendab!','Nad on juba väike inimene oma tugeva tahte ja otsustega. See võimas iseloom täidab sind tulevikus suure uhkusega. Need väärtuslikud päevad ei kesta igavesti, seega kallista neid kogu oma armastusega.'),
('e4430813-5ad7-446e-9502-6e658d83eddd'::uuid,'Жашылчалар менен тил табышуу','Шорподогу жашылчаларды микроскоп менен издегендей терип жатабы? Каршылашпаңыз. Биздин пайдалуу рецепттерден жашылчаларды пюре кылып, соустарга жашыруунун өзгөчө жана даамдуу жолдорун табыңыз.','Köögiviljade sosistaja','Kas nad korjavad supist köögivilju välja, nagu uuriksid neid mikroskoobiga? Ära võitle sellega. Avasta unikaalseid ja maitsvaid viise köögiviljade püreestamiseks ja peida need meie tervislike retseptide abil kastmetesse.'),
('e44cdd54-2858-49fa-8fd7-06dc369d29b6'::uuid,'Атанын жайландыруучу укалоосу 💆‍♂️','Күнү бою бутуңуздан тик туруп, анын артынан чуркап белиңиз ооруп калдыбы. Бала уктаары менен түгөйүңүздөн 10 мүнөттүк ийин массажын сураңыз. Сиз — үйүңүздүн тирегисиз, ал эми тиректер сөзсүз түрдө калыбына келиши керек.','Issi rahustav massaaž 💆‍♂️','Oled terve päeva jalgadel olnud ja selg valutab nende taga jooksmisest. Niipea kui laps magab, palu partnerilt 10-minutilist õlamassaaži. Sina oled oma kodu sammas ja sambad vajavad kindlasti taastamist.'),
('9c8523f0-548b-4581-bde4-2a8295db3639'::uuid,'Түнкү тынчтыкты тосуп алуу 🌙','Балаңыздын тез уктап кетишине жардам берүү үчүн бөлмөдөгү ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин караңгы жана технологиясыз чөйрөдө гана тез бөлүнүп чыгат, бул уйкуга өтүүнү жеңилдетет.','Öö tervitamine 🌙','Et aidata neil kiiremini uinuda, lülita toas välja kõik üleliigsed tuled ja tahvelarvutite ekraanid. Melatoniin eritub kiiresti vaid pimedas ja tehnoloogiavabas keskkonnas, muutes uinumise lihtsamaks.'),
('b7c3f40e-e406-412b-86a2-1c33a12692d8'::uuid,'Мектепке чейинки ой жүгүртүүлөр','Балаңызга көбүрөөк социалдашуу керек деп ойлойсузбу? Бала бакчага же мектепке чейинки билим берүү мекемесине барууга убакыт келдиби? Anacan коомчулугуна кошулуңуз жана башка энелердин реалдуу адаптация тажрыйбаларын окуп, чечим кабыл алууну жеңилдетиңиз.','Eelkooliealise mõtisklused','Kas tunned, et nad vajavad rohkem sotsialiseerumist? Kas on õige aeg lasteaiaks või eelkooliks? Liitu Anacani kogukonnaga ja loe teiste emade tõelisi kohanemiskogemusi, et oma otsust lihtsustada.'),
('d8d022ce-8e44-42aa-972f-aa293c4341c8'::uuid,'Мен жардам берейин! 🧽','Сиз идиш жууп жатканда, ал жаныңызга отургуч коюп, суу менен ойноону талап кылабы? Ал сизге жардам бергиси келбеши мүмкүн, бирок ал окуянын чордонунда болгусу келет. Ага кичинекей пластик идиш бериңиз, ал дагы сиз менен кошо самындап жуусун!','Luba ma aitan sind! 🧽','Kui nõusid pesed, kas nad nõuavad tingimata tooli toomist, et sinu kõrval veega mängida? Nad ei pruugi tahta aidata, vaid tahavad lihtsalt sündmuste keskel olla. Anna neile väike plastkauss ja lase neil ka seebiga pesta!'),
('63dc600c-4255-41f7-8695-78dd689a1998'::uuid,'Шыбырап айтылган жомоктор 🪄','Бөлмөдөгү жарыкты толугу менен өчүрүңүз. Жанына жатып, ''Акылдуу жомоктордон'' кыска бир жомокту кулагына акырын шыбырап айтып бериңиз. Шыбырап сүйлөө — мээни уйкуга даярдоонун эң табигый жана тынчтандыруучу ыкмасы.','Sosistatud unejutud 🪄','Lülita toas tuled täielikult välja. Heida nende kõrvale pikali ja sosista neile vaikselt kõrva mõni lühike lugu ''Nutikatest juttudest''. Sosistamine on kõige loomulikum ja rahustavam viis aju uneks ette valmistada.'),
('76d2443b-1074-45cd-a82d-59ba223792bb'::uuid,'Биздин кичинекей кайталагыч 🎙️','Кечээ телефондон досуңузга айткан ал эмоционалдуу же тамашакөй сөзүңүздү бүгүн балаңыз оюнчугуна айтып жатабы? Анын сөз байлыгы укмуштуудай тездик менен өсүп жатат жана ал сиздин ар бир кыймылыңызды туурап жатат. Мындан ары сөздөрүңүзгө өзгөчө көңүл бурушуңуз керек!','Meie väike kordaja 🎙️','See emotsionaalne või omapärane väljend, mida eile telefonis sõbrannale ütlesid? Täna ütlevad nad seda oma mänguasjale! Nende sõnavara laieneb uskumatult kiiresti ja nad ahvivad kõike, mida teed. Nüüdsest pead oma sõnadega eriti ettevaatlik olema!'),
('a624ef08-9c66-462b-82e4-a4aa90f5b17b'::uuid,'Өзүңүзгө артыкчылык бериңиз','Балаңызга тамак берүү үчүн жумуртканы 4 түрдүү ыкма менен бышырдыңыз, бирок өзүңүз эмне жедиңиз? Өзүңүздү биздин дени сак рецепттерибизден 5 мүнөттө даяр болгон, темирге жана кальцийге бай атайын тамак менен сыйлаңыз.','Enda esikohale seadmine','Valmistasid neile mune neljal erineval moel, aga mida *sina* sõid? Premeeri end meie tervislike retseptide hulgast mõne raua- ja kaltsiumirikka roaga, mis valmib vaid 5 minutiga.'),
('0f7458af-fb58-4fe6-9907-6a5b773bca96'::uuid,'Ак ызы-чуунун (white noise) жайландыруучу таасири 🤫','Бала уктап баратканда сезимталдыгы жогорулайт. Терезеден келген үндөрдү басуу үчүн бөлмөдөгү Үн өлчөгүчтүн фондук үн функциясын иштетиңиз, бул узакка созулган тынчтыкты камсыз кылат.','Valge müra lohutav mõju 🤫','Uinumise ajal tundlikkus suureneb. Akna tagant kostvate helide neutraliseerimiseks aktiveeri toas helitaseme mõõtja taustaheli funktsioon, mis toob kestva rahu.'),
('143f9431-42d8-41e6-9983-ce9dde347219'::uuid,'Жашоодогу кичинекей тактар','Пижамасы тамакка, кийимдери боёкко булгандыбы? Балдар таза өспөшү керек; алар изилдөө аркылуу кирдеши керек. Силикон алжапкычтарды колдонуңуз, калганын кир жуугуч машинага тапшырыңыз.','Elu väikesed plekid','Nende pidžaamad on toiduga koos, riided värviplekilised? Lapsed ei peaks kasvama puhtalt; nad peaksid uurides määrduma. Kasuta silikoonpõllesid ja jäta ülejäänu pesumasina hooleks.'),
('6aecb8fd-7228-4ba7-9f34-65a8f0cda801'::uuid,'Эмерекке чыгуу укмуштуу окуялары 🧗‍♂️','Ал диванга же креслого чыгууга аракет кылып жатабы? Анын тең салмактуулугу жана булчуң күчү чындап эле өнүгүп жатат! Коопсуздугун сактаңыз, бирок бул кичинекей альпинисттик аракеттерине жана физиканы изилдөөсүнө эч качан тоскоол болбоңуз.','Mööblil ronimise seiklused 🧗‍♂️','Kas nad üritavad diivanile või tugitoolile ronida? Nende tasakaal ja lihasjõud arenevad tõepoolest! Hoia neid, kuid ära mingil juhul takista neid väikeseid mägironimiskatseid ja füüsikaavastusi.'),
('0db41c26-c87d-4bd7-8650-e9fd07449904'::uuid,'Энелердин маеги жана колдоосу','Бул бала эч качан тынчтанбайт деген ой сизди чарчатып жатабы? Anacan коомчулугуна кошулуңуз; ар бир бала 3 жаш тегрегинде ушундай оор мезгилдерди башынан өткөрөрүн көрүп, жеңил дем аласыз.','Emmede jutuajamine ja tugi','Kas mõte, et see laps ei rahune kunagi, kurnab sind? Liitu Anacani kogukonnaga; näed, et iga laps läbib 3-aastasena need tormilised faasid, ja saad kergendatult hingata.'),
('448fd3b8-143f-4fee-a40b-1b20e42ebbba'::uuid,'Бир, эки, үч... он! 🔢','Ал манжаларын же оюнчуктарын санаганга аракет кылып жатабы? Анын математикалык акылы ойгонуп жатат! Укмуштуудай тездик менен өнүгүп жаткан бул алгачкы үйрөнүү аракеттерин өткөрүп жибербеңиз.','Üks, kaks, kolm... kümme! 🔢','Kas nad üritavad oma sõrmi või mänguasju lugeda? Nende matemaatiline mõtlemine ärkab! Ära maga maha neid hämmastavaid varajasi õppimiskatseid, mis arenevad uskumatult kiiresti.'),
('5a020277-4aac-4623-8f46-93168c2f54e5'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкү ойгонууларды жана уктоо тартибин жалгыз өзүңүз чечпеңиз. Өнөктөшүңүздү да ойготуңуз; команда болуу — жоопкерчиликти тең бөлүшүү дегенди билдирет. Бүгүн түнү аны уктатуу кезеги толугу менен анын мойнунда.','Issi öövahetus 👨‍🍼','Ära tegele öiste ärkamiste ja magamaminekurutiinidega üksi. Ärata ka oma partner; meeskonnana tegutsemine tähendab vastutuse võrdset jagamist. Täna on nende kord nad magama saada.'),
('026f00f3-6e56-4ac5-a91b-bd5bd82cd187'::uuid,'Тынч убакыт практикасы','Күндүз уктагысы келбей ыйлап жатабы? Мажбурлабаңыз. Бөлмөнүн жарыгын азайтып, экөөңүздөрдү тең тынчтандыра турган ''тынч китеп окуу убактысы'' деп жаңы тартип киргизиңиз.','Vaikusehetke praktika','Ei taha uinakut teha ja nutab? Ära sunni. Hämarusta toas tuled ja tutvusta uut rutiini, kuulutades välja ''vaikse raamatuaja'', mis rahustab teid mõlemaid.'),
('53b445aa-e1d7-4c46-9d5a-07132c91031c'::uuid,'Жылдыздар астында түш көрүү 🌌','Жарык өчкөндө бөлмөдөгү буюмдар желмогузга айланып жатабы? Ага ошол байыркы, кемчиликсиз коопсуздук сезимин кайра тартуулоо үчүн ''Ак ызы-чуулардан'' эненин курсагындагы үндү коюп бериңиз.','Unistamine tähtede all 🌌','Kas toas olevad esemed muutuvad tulede kustudes koletisteks? Pane ''Valgete helide'' alt mängima emakaheli, et anda neile taas see iidne ja täiuslik turvatunne.'),
('f4eb03a9-f74f-423a-ab2a-59d54da2db98'::uuid,'Логиканы издөө 🧩','Жөнөкөй оюнчуктар аны эми кызыктырбай калды; ал татаал оюндарды ойлоп табууда. ''Сунушталган өнүмдөр'' бөлүмүнөн анын интеллектин өстүрө турган жана логикалык ой жүгүртүүсүн өнүктүрө турган оюнчуктарды издеңиз.','Loogika otsingud 🧩','Lihtsad mänguasjad ei köida neid enam; nad mõtlevad juba välja keerukamaid mänge. Otsi ''Soovitatud toodete'' sektsioonist mänguasju, mis panevad nende intellekti proovile ja arendavad loogilist mõtlemist.'),
('00481a1e-da97-4621-84c5-0bde2c4df340'::uuid,'Көрүнбөгөн байкоочу 👻','Дубалдагы өз көлөкөсүнөн коркуп ыйлай баштадыбы? Көлөкө оюну — үч жаштагы балдар үчүн абдан кызыктуу классика! Жарыкты өчүрүп, фонарикти алыңыз жана көлөкөлөрдү бийлетиңиз, бул коркунучту кызыктуу жана сооротуучу уйку алдындагы ырымга айлантыңыз.','Nähtamatu jälgija 👻','Kas nad hakkasid nutma, kartes oma varju seinal? Varjuteater on kolmeaastaste seas klassika! Kustuta tuled, haara taskulamp ja pane varjud tantsima, muutes selle hirmu lõbusaks ja rahustavaks une-eelseks rituaaliks.'),
('135b57f3-06e7-4fc4-b590-bec1151ee33b'::uuid,'Жылуу ваннанын сыйкыры 🛀','Күнү бою «каалабайм» деген сөздөр айтылдыбы. Жылуу ванна — бул жөн гана гигиена эмес; бул анын ашыкча иштеген нерв системасын калыбына келтирүү. Суунун үнү жана жылуулугу бардык өжөрлүктү жууп кетет.','Sooja vanni võlu 🛀','Terve päev oli täis „ma ei taha“. Soe vann pole ainult hügieeniks; see on nende ülestimuleeritud närvisüsteemi lähtestamiseks. Vee heli ja soojus pesevad kogu jonni maha.'),
('57cfce2e-d64c-49cb-9f8b-295055620f21'::uuid,'Жаратылыш табышмагы','Үйдөгү зериктирүүчү атмосфера экөөңүздөрдү тең кыйнап жатат. Паркка барып, эң кызык формадагы ташты табуу тапшырмасын аткарыңыз. Жаратылыш — алар үчүн эң чоң лаборатория, бул сейилдөө бардык чыңалууну таратып жиберет.','Looduse pusle','Kodune tuim õhkkond lämmatab teid mõlemaid. Minge parki missiooniga leida kõige kummalisema kujuga kivi. Loodus on nende jaoks suurim labor ja see sulatab kogu pinge.'),
('682b0a2a-83c6-46cb-a100-02da150309f7'::uuid,'Жаныбарларды тууроо 🐶','Алар жөн эле үндөрдү чыгарбай, иттей сойлоп, мышыктай секирип жатышабы? Алардын дене тили менен элестетүүсү укмуштуудай айкалышууда! Килем үстүндөгү бул оюнга кошулуңуз, ошондо өзүңүздүн да стрессиңиз тараганын сезесиз.','Loomade matkimine 🐶','Kas nad ei tee ainult hääli, vaid roomavad nagu koer ja hüppavad nagu kass? Nende kehakeel ja kujutlusvõime põimuvad imeliselt! Liitu nendega vaibal ja lase oma stressil kaduda.'),
('01a8a883-66ea-4e90-9796-1cd4c7aa4386'::uuid,'Апанын офлайн сааты','Балаңыз өз дүйнөсүнө кирип ойноп жатканда, дароо эле үйдү тазалоого шашпаңыз. Өзүңүзгө бир чыны ысык чай куюп, телефонду четке коюп, 15 мүнөт эч нерсени ойлонбой отуруңуз.','Emme võrguvaba tund','Kui laps on süvenenud oma mängumaailma, ära torma kohe koristama. Vala endale tass kuuma teed, pane telefon kõrvale ja istu lihtsalt 15 minutit, puhastades oma mõtteid.'),
('7fc36514-28e6-4738-b9f6-f0c9cd9fa57d'::uuid,'Экөө үчүн бир көз ирмем 🥂','Бала уктады. Эми үй жумуштарын четке коюңуз. Өнөктөшүңүз менен кеминде 20 мүнөт бала же үй-бүлөлүк чыгымдардан башка темада сүйлөшүңүз. Сиздер да жубайларсыздар!','Hetk kahekesi 🥂','Laps magab. Nüüd pane kodutööd kõrvale. Räägi partneriga vähemalt 20 minutit millestki muust peale lapse või kulutuste. Te olete ka paar!'),
('8b2d61db-8be9-4916-a184-f14d02885b17'::uuid,'«Бул эмне?» машинасы ☝️','Алар кичинекей манжасы менен баарын көрсөтүп, «Бул эмне?» деп сурап жатышабы? Алар сизден дүйнөнү атап беришиңизди каалашат! Бул баарлашуудагы чоң кадам. Чарчап турсаңыз да, сабырдуулук менен ал нерселердин атын кайталай бериңиз.','Masin nimega „Mis see on?“ ☝️','Kas nad näitavad kõigele oma väikese sõrmega ja küsivad: Mis see on? Nad tahavad, et sa nimetaksid nende maailma! See on suur hüpe suhtlemises. Isegi kui oled väsinud, korda kannatlikult nende esemete nimesid.'),
('81f8ee8c-8ca4-4260-b2ea-e74f425fe201'::uuid,'Кир тоосунан жасалган чатыр ⛺','Жаңы эле бүктөлгөн кийимдериңизди чачып, чеп куруп алыштыбы? Капалануудан мурун, ал чептин ичине көз чаптырыңыз. Ал жердеги балаңыздын элестүү дүйнөсү жана кубанычы сиздин бүктөгөн эмгегиңизден алда канча баалуу.','Telk pesumäest ⛺','Kas nad ajasid su värskelt volditud pesuhunniku sassi, et ehitada kindlus? Enne kui pahandad, piilu kindlusesse. Sinu lapse kujutlusmaailm ja rõõm seal sees on palju väärtuslikumad kui sinu voltimisvaev.'),
('c4bb77ab-6874-45a4-8118-c089a7246538'::uuid,'Кийимдин этикеткасы менен болгон кризис 🏷️','«Тикенектейт!» Көйнөктүн артындагы кичинекей этикетка бүгүнкү эртең мененки эң чоң душман. Сезимталдык көбүнчө үч жаш курагында жогорулайт. Талашпаңыз; жөн гана этикетканы кесип салыңыз жана күндүн тынч башталышына мүмкүнчүлүк бериңиз.','Sildikriis 🏷️','''See torgib!'' See pisike silt särgi taga on hommikune suurim vaenlane. Sensoorne tundlikkus on kolmeaastastel sageli tipus. Ära vaidle; lõika silt lihtsalt ära ja anna päevale võimalus rahulikult alata.'),
('6716e6c0-2c87-4096-9dc2-661b570d83da'::uuid,'Муздаткычтагы пульт','Телевизордун пультун таппай жатасызбы? Муздаткычты же бут кийим текчесин текшериңиз. Алар дүйнөнү өздөрүнүн уникалдуу логикасы менен изилдеп жатышат. Капа болгондун ордуна, бул кызыктуу детективдик оюнга күлкү менен мамиле кылыңыз.','Pult külmkapis','Ei leia telekapulti? Vaata külmkappi või kingakappi. Nad avastavad maailma, paigutades esemeid oma unikaalse loogika järgi. Selle asemel, et ärrituda, lähene sellele absurdsele detektiivimängule naeruga.'),
('7e1b9939-5806-440f-9214-8ee42a76c83e'::uuid,'Ойдон чыгарылган жаракаттарды дарылоо 🩹','Ойгонуп эле денесинде көрүнбөгөн «жараат» бар экенин айтып, шашылыш түрдө пластырь талап кылышабы? Бул физикалык оору эмес, бул көңүл бурууга жана боорукердикке болгон муктаждык. Талашпаңыз — жөн гана кичинекей пластырь чаптап, өөп коюңуз, ошондо күнүңүз сакталат!','Kujuteldavate haavade ravimine 🩹','Nad ärkavad, avastavad kehal nähtamatu ''haava'' ja nõuavad paaniliselt plaastrit. See pole füüsiline valu, vaid puhas tähelepanu- ja kaastundevajadus. Ära vaidle – pane see pisike plaaster, anna musi ja päästa oma päev!'),
('ce6bc378-f040-49dc-a292-ef6ffa4a4247'::uuid,'Түнкү тамактануу каалоосу 🥱','Төшөккө жатарда ашканага чуркап барып, «Апа, курсагым ачты» дешет. Бул уйкуну кечиктирүүнүн эң сонун амалы! Кечки тамак планына уйкуну чакыруучу жеңил тамакты (мисалы, банан) кошуп, бул шылтоону алдын ала жокко чыгарыңыз.','Hilisõhtused isud 🥱','Just siis, kui voodisse sätid, tahavad nad kööki joosta, öeldes: Emme, mul on kõht tühi. See on meistriklass uinumise edasilükkamiseks! Vali nende toiduplaani väike und soodustav suupiste (näiteks banaan), et see vabandus ennetavalt neutraliseerida.'),
('7dcdfa61-d4a7-4888-bf22-0453312c6bae'::uuid,'Ойлоруңузду айтыңыз 💭','Төшөктө жатып, күндүзгү окуялар жөнүндө өзүнчө эле катуу сүйлөшүп жатышабы? Алар маалыматты жана эскерүүлөрдү ушундай иштетишет. Өнүгүү трекерин ачып, алардын окуяларды өз алдынча кураштыруу жөндөмү канчалык өскөнүн сыймыктануу менен белгилеп коюңуз.','Mõtete hääldamine 💭','Voodis lamades räägivad nad endamisi päeva sündmustest, aga valjult. Nii töötlevad nad infot ja mälestusi. Ava arengupäevik ja märgi uhkusega, kui teravalt on kasvanud nende võime spontaanselt lugusid luua.'),
('dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39'::uuid,'Килемдеги чыгармачылык 📏','Килемдин сызыктарын баспай басууга аракет кылып, сизден да ошондой кылууну суранып жатышабы? Алардын кыймыл-аракет координациясы жана көңүл буруусу эң сонун өнүгүүдө. Оюнду бузбаңыз — алар менен бирге ошол коопсуз сызыктын үстүнөн секирип өтүңүз.','Vaibakunst 📏','Nad üritavad kõndida nii, et ei astu vaiba triipudele, ja paluvad sul sama teha! Nende motoorika ja tähelepanu koordineeritus arenevad suurepäraselt. Ära riku mängu – hüppa nendega koos mööda sama ohutut joont.'),
('04cb5d8f-0591-4ccc-8e31-0cf6555eb83a'::uuid,'🛀 Ваннадагы кемелердин чөгүшү','Ваннада суу менен ойноп жатып, калкып жүргөн оюнчуктарды сууга чөктүрүүгө аракет кылып жатышабы? Алар физиканы изилдеп жатышат! Суу чачырасын; анын активдүү оюну күндүзгү топтолгон чыңалууну жууп кетет.','🛀 Uppuvad laevad vannis','Olete vannitoas veemängudes ja nad üritavad uputada mänguasju, mis ujuvad. Nad avastavad füüsikat! Lase veel pritsida; energiline mäng aitab maha pesta kogu päeva jooksul kogunenud vastupanu ja pinge.'),
('123c0368-cc37-47f7-bb36-f227dd4d9131'::uuid,'Ойдон чыгарылган үй жаныбары 🐕','Бөлмөдөгү көрүнбөгөн итке же мышыкка ат коюп, эркелетип жатышабы? Алардын элестетүүсү физикалык чектерден ашып кетти! Бөлмөнүн бир бурчуна көрүнбөгөн суу идишин коюп, бул таттуу оюнга кошулуңуз.','Kujuteldav lemmikloom 🐕','Kas nad paitavad toas kujuteldavat koera või kassi ja annavad talle nime? Nende kujutlusvõime on ületanud füüsilised piirid! Pane toa nurka nähtamatu veekausike ja ühine selle armsa illusiooniga.'),
('ecca6ba2-c00d-4fde-a20b-1268d23c90e0'::uuid,'Муз идишиндеги майрам 🧊','Эмне кылсаңыз да жашылча жебей жатышабы? Сунуштоо ыкмасын кескин өзгөртүңүз. Пайдалуу тамактарды муз катыруучу идиштин кичинекей бөлүкчөлөрүнө бөлүп салыңыз. Адаттан тыш көрүнүш ар дайым табитти ачат.','Jääkuubikute pidusöök 🧊','Ükskõik mida teed, nad ei söö köögivilju? Muuda drastiliselt serveerimist. Jaga tervislikud suupisted jääkuubikute vormi väikestesse sektsioonidesse. Ebatavaline serveerimine ergutab alati söögiisu.'),
('80fe5b22-0f4c-4f31-ac99-30418e5a6c6a'::uuid,'Дем алуу үчүн бир көз ирмем, апа','Үйдөгү баш аламандык башыңызды оорутуп жатабы? Аба ырайын карап, ылайыктуу кийинип, 15 мүнөткө сыртка чыгыңыз. Алар таш терип ойносун, ал эми сиз бетке тийген таза, муздак аба менен терең дем алыңыз.','Hetk hingetõmbeks, emme','Kodune kaos kumiseb kõrvus. Kontrolli ilma ja sobivat riietust, pane vajadusel soojalt riidesse ja mine lihtsalt 15 minutiks õue. Lase neil kive korjata ja hinga ise sügavalt sisse külma, värsket õhku.'),
('93c26bc0-b2a6-4580-91d3-d91792e077a2'::uuid,'Динозавр тили 🦖','Бүгүн эртең менен ал бала эмес, динозавр болуп ойгонду, бардык суроолоруңузга болгону ырылдоо менен жооп берип жатат! Ролдук оюндар — инсандык өнүгүү үчүн эң сонун курал. Бир азга жөн гана ата-эне эмес, өзүңүз да динозаврга айланып, алар менен өздөрүнүн өзгөчө тилинде сүйлөшүңүз.','Dinosauruse keel 🦖','Täna hommikul pole ta laps, vaid hoopis dinosaurusepoeg ja kõikidele su küsimustele vastab ta vaid ürgse möirgamisega! Rollimängud on suurepärane vahend isiksuse arendamiseks. Ole hetkeks mitte lihtsalt lapsevanem, vaid teine dinosaurus, ja suhtle temaga tema enda ainulaadses keeles.'),
('b992124a-a4ae-4e30-a81b-b79de4b95a68'::uuid,'Чарчоону моюнга алуу 📝','Эч ким сизди түшүнбөгөндөй жана аракеттериңиз байкалбай калгандай сезилип жатабы? Жасалма жылмаюуну бир четке коюңуз. Маанай күндөлүгүңүзгө бүгүн канчалык чарчаганыңызды чын дилиңизден жазыңыз. Экранга төгүлгөн ар бир сөз ийиниңиздеги оор жүктү жеңилдетет.','Kurnatuse tunnistamine 📝','Kas tunned, et keegi ei mõista sind ja su pingutused jäävad märkamata? Jäta liialdatud naeratused kõrvale. Kirjuta oma meeleolupäevikusse, kui kurnatud sa end täna tegelikult tunned. Iga ekraanile valatud sõna aitab su õlgadelt rasket koormat vähendada.'),
('075e0950-03bc-496b-a1a2-1172377fb523'::uuid,'AI жана ата-энелик кооптонуулар','Балаңыздын айрым тамгаларды айта албаганы сизди кооптондуруп жатабы? Кесипкөй эмес жана коркунучтуу интернет форумдарын жабыңыз. Anacan AI''дан 3 жаштагы балдардын сүйлөө нормалары тууралуу сурап, илимий жана ишенимдүү жооп алыңыз.','AI ja vanemlikud mured','Kas lapse suutmatus teatud tähti hääldada tekitas sinus äkki ärevust? Pane kinni need ebaprofessionaalsed ja hirmutavad foorumid. Küsi Anacan AI-lt 3-aastaste kõne arengunormide kohta ja saa teaduslikult põhjendatud ning rahustav vastus.'),
('9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9'::uuid,'Уктоо алдындагы цирк 🎪','Уктоо убактысы келгенде, төшөк заматта цирк аренасына айланат. Алар секирип, сойлоп, кыйкырышат. Үнүңүздү көтөрбөй, жарыкты өчүрүңүз. Алар акыркы энергиясын чыгарып жатышат. «Акылдуу жомоктордон» жай темптеги окуяны окуп, бул бороонду акырындап басаңдатыңыз.','Magamamineku tsirkus 🎪','Kui saabub uneaeg, muutub voodi hetkega tsirkuseareeniks. Nad hüppavad, roomavad ja karjuvad. Hämarda tuled ilma häält tõstmata. Nad vabanevad viimastest energiavarudest. Kustuta see torm järk-järgult rahuliku looga ''Nutikatest juttudest''.'),
('c4897803-48e7-46f1-aca1-db692fe7b9f1'::uuid,'«Меники» эшик туткасы 🚪','«Эшикти мен ачам!» деп, сизден озуп чуркашат. Эгер эшикти ачып койсоңуз, кайра жаптырып, өздөрү ачканга чейин ыйлашат. Бул куракта көзөмөл сезими баарынан маанилүү. Эшикти өздөрүнө ачтырыңыз — бул кичинекей жеңиштер алардын өзүнө болгон ишенимин бекемдейт.','„Minu oma“ ukselink 🚪','„Mina avan ukse!“ teatavad nad ja tormavad sinust ette. Kui sa juba ukse avasid, nutavad nad seni, kuni sa selle uuesti kinni paned, et nad saaksid seda ise teha. Kontrollitunne on selles vanuses kõik. Lase neil uks avada – need väikesed võidud toidavad nende tärkavat enesekindlust.'),
('2b40e6c9-46bc-4fb2-8d09-1e690e1a478c'::uuid,'Биздин колдоочу коомчулук 💬','Бүгүн ал абдан тентектик кылгандыктан, өзүңүздү жаман энедей сезип жатасызбы? Дароо Anacan коомчулугуна кириңиз. Башка энелердин балдарынын күнүмдүк тентектиктери жөнүндө окуганда, жалгыз эмес экениңизди жана чындыгында абдан жакшы эне экениңизди түшүнөсүз.','Meie toetav kogukond 💬','Täna olid nad nii trotslikud, et tunned end halva emana. Ava kohe Anacan Community. Kui loed teiste emade laste igapäevastest mässudest, mõistad, et sa pole üksi ja teed tegelikult suurepärast tööd.'),
('4f85a7f5-323c-4830-b901-61f69a9b8176'::uuid,'Жашыруун эки анжы болуу','Алар сизге «Мага суу бер, бирок бербе» деген сыяктуу карама-каршы сүйлөмдөр менен келишет. Алардын оюнда эки карама-каршы каалоо бир убакта жашайт. Көп ойлонбостон, сууну столго коюп коюңуз, алар өздөрүнүн ички талашын өздөрү чечип алышсын.','Varjatud vastakad tunded','Nad tulevad su juurde ja moodustavad täiesti paradoksaalseid lauseid, näiteks: „Anna mulle vett, aga ära anna mulle vett.“ Nende peas eksisteerivad korraga kaks vastandlikku soovi. Ära mõtle üle, pane lihtsalt vesi lauale ja lase neil oma sisemise vaidlusega ise toime tulla.'),
('ad8a8472-f316-41bd-82ab-7d5720d810ee'::uuid,'Күч топтоо убактысы, апа! 🔋','Күндүзгү түйшүк энергияңызды соруп алдыбы? Өзүңүздү унутуп, баланы тарбиялоо баатырдык эмес. Балаңызды коопсуз жерге отургузуп, 10 мүнөттүк кофе тыныгуусун жасаңыз.','Aeg akusid laadida, emme! 🔋','Kas päevane sagimine võttis sult energia? Lapse kasvatamine iseennast unustades pole kangelastegu. Pane oma väike laps turvalisse kohta ja võta 10-minutiline kohvipaus.'),
('fb64f95e-ceac-49e1-96ee-95e171273ead'::uuid,'Балка жана бурама менен ойноо 🛠️','Алар колуна тийген катуу оюнчуктар менен эмеректерди «оңдоп» жатышат. Чуусу сизди жинди кылса да, бул алардын себеп-натыйжа байланышын изилдөө ыкмасы! Аларга бош картон куту менен жыгач кашык бериңиз, ызы-чуулуу «оңдоо иштерин» ошол жерде улантышсын.','Haamri ja kruvikeeraja mäng 🛠️','Nad taovad mööblit iga kõva mänguasjaga, mis kätte satub, justkui „parandades“ seda. Isegi kui müra ajab sind hulluks, on see nende viis avastada põhjus-tagajärg seoseid! Anna neile tühi pappkarp ja puulusikas ning lase neil oma lärmakaid „remonditöid“ seal jätkata.'),
('0b8c858b-4b69-4199-b627-a7a497686efd'::uuid,'Башаламандыктан шедеврге чейин 🎨','Кичинекейиңиз бөлмөнүн ортосуна кагаздын үзүндүлөрү жана жиптер менен шедевр жаратып, аны ыргыттырбай жатабы? Тазалыкка болгон муктаждыгыңызды бир четке коюңуз. Алардын чыгармачыл башаламандыгын баалаңыз; тазалоо иштери эртең деле күтө турат.','Segadusest meistriteoseni 🎨','Sinu väike laps on keset tuba loonud meistriteose pisikestest paberitükkidest ja lõngajuppidest ega luba sul seda ära visata. Jäta oma korraarmastus kõrvale. Hinda nende loodud loomingulist kaost; koristamine võib alati homseni oodata.'),
('5f97fec7-d72f-4377-af18-4420a1663ca4'::uuid,'Тынч убакыт терапиясы 🤫','Үйдөгү тынымсыз ызы-чуу акыры токтоду. Алар уктап калышты. Үн өлчөгүчтү ачып, экрандагы сандардын 0 децибелге түшкөнүн караңыз. Бөлмөдөгү абсолюттук тынчтык мээңизди кандай эс алдырып жатканын сезиңиз.','Vaikusehetke teraapia 🤫','Lõputu müra kodus on lõpuks vaibunud. Nad magavad. Ava helimõõtja ja vaata, kuidas numbrid ekraanil langevad 0 detsibellini. Tunneta, kuidas täielik vaikus toas su aju visuaalselt masseerib.'),
('63b3f3e0-ceca-4b44-a2ea-ae171ce3413f'::uuid,'Күзгү театры 🎭','Эртең менен туруп эле күзгү алдында ыйлаган, күлгөн жана таң калган түрдүү бет түзүлүштөрүн жасап жатышат. Алар эмоцияларын билдирүүнү жана жүзүнүн кыймылын үйрөнүп жатышат! Бул укмуштуудай актёрдук чеберчиликти алыстан сыймыктануу менен караңыз.','Peegliteater 🎭','Kohe hommikul seisavad nad peegli ees ja harjutavad erinevaid nutvaid, naervaid ja üllatunud näoilmeid. Nad õpivad oma emotsioone väljendama ja seda, kuidas nende nägu neid kujundab! Jälgi seda suurepärast näitlemist eemalt uhkusega.'),
('14f4e22b-ebcd-4b44-af1e-7caf9bc49874'::uuid,'Атанын кучагы 🫂','Колуңуз көтөрө албай калганча чарчадыңыз, бирок ал дагы эле кучактанууну каалайт. Атасын чакырыңыз. Атасынын кучагында «учуу» баланын көңүл буруу муктаждыгын канааттандырат жана сиздин колдоруңуз менен белиңизге абдан керектүү эс алууну берет.','Issi lohutav kallistus 🫂','Su käed on terve päeva kandmisest väsinud, aga nad tahavad ikka kaisusse. Kutsu issi appi. Issi süles lendamine rahuldab lapse tähelepanuvajaduse ja annab su kätele ning seljale hädavajaliku puhkuse.'),
('8e97dc44-4076-463e-90aa-e9a38f43a406'::uuid,'Балдар логикасынын кызыктуу учуру 🧐','Эмне үчүн балыктар баспайт? Анын мээси эртең менен эле философиялык суроолор менен ойгонот. Суроолору сизди туңгуюкка кептесе да, талыкпай түшүндүрүүгө аракет кылыңыз. Сиздин үнүңүз — анын ааламды таанып-билүүсүндөгү эң коопсуз жана эң кооз жол.','Laste loogika kummaline juhtum 🧐','Miks kalad ei kõnni? Tema aju ärkab varahommikul filosoofiliste küsimustega. Isegi kui tema küsimused jätavad sind nõutuks, proovi väsimatult selgitada. Sinu hääl on tema jaoks kõige turvalisem ja ilusam viis universumit mõista.'),
('d78d5945-d2b9-4d6b-be69-c36a9e85a337'::uuid,'Дүкөн тизмесиндеги башаламандык 🛒','Супермаркеттин кассасында туруп, дагы бир маанилүү нерсени унутуп калганыңызды түшүндүңүз. Мээңиз миллиондогон нерселерди ойлоп жатат. Эсиңизге келери менен товарларды тиркемедеги «Соода тизмесине» кошууну адат кылыңыз — бул өзүңүзгө көрсөткөн кичинекей жардам!','Ostunimekirja kaos 🛒','Oled supermarketis kassas ja mõistad äkki, et unustasid jälle midagi olulist. Su aju žongleerib juba miljoni asjaga. Tee endale harjumuseks lisada tooted äpi ostunimekirja kohe, kui need meelde tulevad – see on väike abikäsi sulle endale!'),
('62d4901b-19ff-4b33-a0e0-89d727535d96'::uuid,'Тескери кийилген байпактын сыймыгы 🧦','Байпагынын такасы бутунун үстүндө турат, бирок ал өзү кийингени үчүн сыймыктануу менен басып жүрөт. Кийлигишпеңиз, атүгүл бир аз да болсо. Анын «Мен өзүм жасадым» деген сезими эстетикалык же туура кийингенден миллион эсе баалуу психологиялык пайдубал.','Uhkus pahupidi riiete üle 🧦','Soki kand on jala peal, aga ta kõnnib uhkelt, sest riietus ise. Ära sekku, isegi mitte natuke. Tema „ma tegin seda ise“ tunne on psühholoogiline vundament, mis on miljon korda väärtuslikum kui esteetiliselt või korrektselt riietumine.'),
('79c5f477-357d-4a5a-a226-aa71c2153c6a'::uuid,'Шыбырап айтылган түнкү жомоктор 🌙','Бүгүн үнүңүздү көп колдондуңуз, өпкөңүз чарчады. Жарыкты өчүрүп, жанына жатыңыз жана кулагына күндүн окуялары жөнүндө акырын шыбыраңыз. Шыбыроо алардын көңүлүн топтоп, мээсин терең уйкуга гипноздук түрдө даярдайт.','Sosistatud unejutud 🌙','Oled täna palju rääkinud ja su kopsud on väsinud. Kustuta tuled, heida nende kõrvale ja sosista lihtsalt päeva sündmustest neile kõrva. Sosistamine keskendub nende tähelepanule ja valmistab aju hüpnootiliselt ette sügavaks uneks.'),
('b3b80c54-4891-4e55-9e0b-d88a4a322bdd'::uuid,'Ашкана симфониясы 🥄','Кичинекейиңиз ашкананын ортосунда казан-аяктарды кагып, катуу концерт коюп жатабы? Башыңыз ооруп жатса да, бул алардын ритм сезими жана моторикасын өнүктүрүү үчүн сонун экенин унутпаңыз. Аларга «браво» деп кол чаап, концерттин тез бүтүшүн ичиңизден тилеңиз!','Köögisümfoonia 🥄','Sinu väike laps annab keset kööki valju kontserti, kolistades potte ja puulusikaid. Isegi kui su pea valutab, pea meeles, et see on suurepärane nende rütmitaju ja motoorika arenguks. Plaksuta neile ja looda vaikselt, et esinemine varsti lõppeb!'),
('26929739-4514-47f4-b2ff-3f79743e2a52'::uuid,'Алтын жымжырттыктын баасы 🤫','Үйдөгү башаламандык акыры бүтүп, алар уктап калышты. Идиш жууганга шашпаңыз! Үн өлчөгүчтү ачып, бөлмөдөгү абсолюттук тынчтыкты (0-10 децибел) байкоо менен мээңиздин 15 мүнөт бою кандай эс алаарын визуалдык түрдө сезиңиз.','Kuldse vaikuse väärtus 🤫','Kaos kodus on lõpuks lõppenud ja nad on uinunud. Ära kiirusta nõusid pesema! Ava helimõõtja ja koge visuaalselt, kuidas su aju 15 minutit lõõgastub, jälgides toas valitsevat täielikku vaikust (0-10 detsibelli).'),
('691e79df-4ad4-4dc1-80d2-9bb367dfc70e'::uuid,'Банан арчуу дастаны 🍌','Банандын кабыгын аарчып бергениңиз үчүн эртең мененки саат 8де бөлмөдө революция чыктыбы? Бул курактын алтын эрежеси: баарын ал чечиши керек. Банандын кабыгын кайра жабыштыра албайсыз, андыктан анын көңүлүн дароо башка нерсеге буруп, кризисти жөнгө салыңыз.','Banaani koorimise saaga 🍌','Kas kell 8 hommikul puhkes toas revolutsioon, sest koorisid tema banaani ära? Selle vanuse kuldreegel: tema peab kõike otsustama. Sa ei saa banaani tagasi koorida, seega suuna tema tähelepanu kohe teisele absurdsele asjale ja lahenda kriis.'),
('cfe53a47-5049-4180-8a26-333de41ec18f'::uuid,'Тандап угуу синдрому 🙉','Балаңыз оюнчуктарын жыйноону суранганда укмаксан болуп, бирок коңшу бөлмөдөн шоколаддын кагазынын шыбыраганын дароо угабы? Анын угуусунда эч кандай көйгөй жок, ал болгону өзүнө пайдалуу нерсени гана угат! Эрежелерди шыбырап айтып көрүңүз — балким, бул алардын кызыгуусун арттырар.','Valikulise kuulmise sündroom 🙉','Kas su laps ignoreerib sind, kui palud mänguasju koristada, aga kuuleb teisest toast kohe šokolaadipaberi krabinat? Tema kuulmisega pole midagi viga; nad kuulevad vaid seda, mis neile kasulik on! Proovi reegleid sosistada – see võib nende huvi äratada.'),
('46cb3019-8e96-4dd4-93b2-6c2a4bab0f53'::uuid,'Кенч толгон чөнтөк 🪨','Шымын жууп жатып чөнтөгүнөн эки таш, куураган жалбырак жана сынган бутак таптыңызбы? Сизге таштандыдай көрүнгөн бул нерселер, дүйнөнү изилдеп жаткан балаңыз үчүн баалуу коллекция. Аларды ыргытпай, кичинекей кенч кутусуна чогултуп коюңуз.','Taskud täis aardeid 🪨','Kas leidsid pükse pestes taskust kaks kivi, kuivanud lehe ja murtud oksarao? Need esemed, mis sulle võivad rämpsuna tunduda, on tema väärtuslik kollektsioon maailma avastamisel. Selle asemel, et need ära visata, kogu need väikesesse aardelaekasse.'),
('4c758b24-b5bb-4fba-9fae-76aff0e5119d'::uuid,'Брокколини жашыруу 🥦','Балаңыз шорпосундагы жашылчаларды хирургиялык тактык менен бөлүп жатабы? Тандап жеген учур эң жогорку чегинде! Жашылчаларды алардын тамак-аш планына жашырып, балким түстүү котлеттерге айландырып, жедирүүнүн өзгөчө жана акылдуу рецепттерин табуу убактысы келди.','Brokoli maskeering 🥦','Kas su laps eraldab supist kirurgilise täpsusega rohelisi köögivilju? Valiv söömine on haripunktis! On aeg avastada erilisi ja nutikaid retsepte, mis panevad köögiviljad nende toidulaual kaduma, muutes need näiteks värvilisteks kotlettideks.'),
('56a63f2b-c314-4614-a2a4-36e4a75775f5'::uuid,'Алар жомоктун режиссеру 🪄','Эски жомок китептеринен тажадыңызбы? «Акылдуу» жомок тиркемесин ачып, бүгүн кечинде сюжетти балаңызга башкартыңыз. «Ал учкан машина андан кийин кайда барышы керек?» деп сурап, алардын укмуштуудай фантазиялуу (жана балким күлкүлүү) аягы менен уктатыңыз.','Nemad on muinasjutu lavastajad 🪄','Tüdinenud vanadest raamatutest? Ava „nutikas“ jutuäpp ja lase lapsel täna õhtul süžeed juhtida. Küsi: „Kuhu see lendav auto peaks järgmisena minema?“ ja lase nende imeliselt fantaasiarikkal (ja võib-olla absurdsel) lõpul nad unne kussutada.'),
('4cbe2cb0-5188-4114-8447-b099245e7121'::uuid,'Атанын «учак режими» ✈️','Кичинекейиңиз энергияга толуп, уктоодон баш тартып жатабы? Жардамга атасын чакырыңыз! Атасы аны бийик көтөрүп, учакка айланганда, бөлмө күлкүгө толуп, топтолгон физикалык чыңалуу секунданын ичинде жок болот.','Issi lennurežiim ✈️','Kas su väike laps on energiat täis ja tõrjub uneaega? Kutsu appi abivägi – issi! Kui ta tõstab nad kõrgele ja muutub lennukiks, täitub tuba naerust ja kogu kogunenud füüsiline pinge kaob sekunditega.'),
('9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a'::uuid,'Өзүңүздүн чөйрөңүздү табыңыз 💬','Өзүңүздү абдан чарчаган жана дүйнөдөгү эң чыдамсыз энедей сезип жатасызбы? Дароо Anacan коомчулугун ачыңыз. Башка энелердин дал ушундай күлкүлүү кризистерди башынан өткөрүп жатканын окуу — эң чоң психологиялык колдоо.','Oma küla leidmine 💬','Tunned end täiesti kurnatuna ja maailma kõige kannatamatuma emana? Ava kohe Anacan Community. Teiste emade lugemine, kes kogevad täpselt samu absurdseid kriise, on suurim psühholoogiline tugi.'),
('bd33d5a6-7358-4409-91cf-48f9ce76cb44'::uuid,'Түгөнбөгөн «Эмне үчүн?» суроолору 🌪️','Эмне үчүн канаттуулар учат? Эмне үчүн суу нымдуу? Эмне үчүн «эмне үчүн» — «эмне үчүн»? Суроолордун агымы сизге карай тездик менен келе жатат. Чарчасаңыз да, ага логикалуу жана кыска жооп бериңиз. Ал ааламдын сырларын сиздин үнүңүздүн обонунан үйрөнөт.','Lõputu „Miks?“ ring 🌪️','Miks linnud lendavad? Miks vesi on märg? Miks „miks“ on „miks“? Küsimuste rong läheneb sulle kiiresti. Isegi kui väsid, anna talle loogilisi ja lühikesi vastuseid. Ta õpib universumi saladusi sinu hääletooni kaudu.'),
('5940af77-4cae-40d5-a543-2bf3a6668855'::uuid,'Жаратылыш кучагы ⛅','Төрт дубал сизди да, кичинекейиңизди да тажатып жибердиби? Үйдөгү башаламандыктан чарчадыңызбы? Аба ырайы жана кийим тандоо куралын текшерип, сейил бакка чуркаңыз! Таза абада эркин чуркоо балдардын эң катуу кыяңкечтигин да бычак менен кескендей токтото алат.','Põgenemine loodusesse ⛅','Neli seina muudavad nii sind kui ka su pisikest rahutuks. Oled kodusest kaosest väsinud? Kontrolli ilma ja riietumise tööriista ning tormake parki! Vabas õhus ringijooksmine võib lõigata läbi ka kõige ägedama väikelapse jonnihoo nagu nuga.'),
('7886ad64-9846-4990-9753-652093d6bac5'::uuid,'Туура эмес түстөгү кырсык 🔴','Ал көк чөйчөктөгү сууну кызыл чөйчөккө алмаштырганыңыз үчүн ыйлап жатабы? Бул тентектик эмес; ал жөн гана сиздин чек араңызды жана өз дүйнөсүн башкара алуу жөндөмүн сынап жатат. Урушпай эле чөйчөктү алмаштырыңыз да, өзүңүздүн энергияңызды үнөмдөп калыңыз.','Vale värvi katastroof 🔴','Kas jonnihoog tekkis seetõttu, et andsid talle vett sinises tassis punase asemel? See pole kapriissus; ta lihtsalt katsetab piire ja oma võimet maailma kontrollida. Vaheta tass ilma vaidlemata ja säästa oma energiat.'),
('449d1eaf-e90d-45bb-8ac5-83cc8e44397d'::uuid,'Күч топтоо убактысы! 🍎','Балаңыз уктап жатканда, сиз да көзүңүздү 20 мүнөткө жумуп алыңыз. Үй жумуштары түгөнбөйт, бирок сиздин энергияңыз түгөнүшү мүмкүн. Өзүңүздү аяңыз.','Aeg akusid laadida! 🍎','Kui laps magab, pane ka ise 20 minutiks silmad kinni. Majapidamistööd ei lõpe kunagi, aga sinu energia küll. Hoidu ennast.'),
('bfa1d504-f493-414c-a978-4ad885726ef7'::uuid,'Сезимдериңизди эркин коюңуз 📝','Үйдөгү чарчооңузду эч ким көрбөй жаткандай сезилеби? Маанай күндөлүгүңүз — сиздин эң ишенимдүү сырдашыңыз. Бүгүн сизди тажатып жиберген майда-чүйдө нерселердин баарын жазып коюңуз, ошондо ичиңиздеги оордук жеңилдеп калат.','Lase tunnetel voolata 📝','Tunned, et keegi ei näe, kui kurnatud sa kodus oled? Sinu meeleolupäevik on su kõige vaiksem usaldusisik. Pane kirja kõik pisiasjad, mis sind täna hulluks ajasid, ja tunne, kuidas vaimne koorem kergeneb.'),
('1800a436-63cf-4ef5-8469-ebb0dffa942d'::uuid,'AI, реалдуу чечимдер 🤖','Балаңызда кызыктай адат (мисалы, чачын буроо) пайда болуп, интернеттеги макалалар сизди тынчсыздандырып жатабы? Токтоңуз. Педиатрлар жактырган чыныгы себепти билүү үчүн Anacan AI''дан сураңыз жана ашыкча дүрбөлөңдөн өзүңүздү сактап калыңыз.','AI, päriselu lahendused 🤖','Kas su lapsel on tekkinud kummaline harjumus (näiteks juuste keerutamine) ja internetiartiklid on sind muretsema pannud? Peatu. Küsi Anacan AI-lt pediaatri heakskiidetud tõelist põhjust ja säästa end asjatust paanikast.'),
('3f147988-5fe0-4104-b53b-bcd1de9eb553'::uuid,'Катылгыч логикасы 🙈','Ал бөлмөнүн ортосунда көзүн жаап туруп, сизди издешиңизди күтүп жатат! Бул 3 жашар баланын логикасы: «Эгер мен сени көрө албасам, сен да мени көрө албайсың». Анын бул бейкүнөө оюнуна ишенгенсип, бөлмө ичинде ызы-чуу салып издеп баштаңыз.','Peitusemängu loogika 🙈','Ta seisab keset tuba, käed silmade ees, ja ootab, et sa ta üles leiaksid! See on 3-aastase loogika: kui mina sind ei näe, ei näe ka sina mind. Mängi kaasa ja otsi teda häälekalt mööda tuba taga.'),
('e71a10b9-dee7-4968-a1f7-387196804ef0'::uuid,'Жарыкты өчүрүңүз, уйку келсин 🌙','Балаңыздын тезирээк уктап кетишине жардам берүү үчүн, жатар алдында бир саат калганда бөлмөдөгү ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Уйку гормону болгон мелатонин караңгы жана технологиясыз чөйрөдө гана тез бөлүнүп чыгат.','Tuled kustu, uni tuleb 🌙','Et aidata lapsel kiiremini uinuda, lülita tund enne magamaminekut toas välja kõik lisavalgustid ja tahvelarvutite ekraanid. Melatoniin, unehormoon, eritub kiiresti vaid pimedas ja tehnoloogiavabas keskkonnas.'),
('2cc2d175-4d74-4e12-832a-3885acc3e55b'::uuid,'Санариптик эс тутум 🛒','Дүкөнгө барганда дайыма бир нерсени унутуп каласызбы? «Соода тизмеси» тиркемеде сизди күтүп жатат. Керектүү нерселерди дароо жазып коюңуз, ошондо жубайыңыз жумуштан кайтып келе жатып баарын так алып келет — башыңызды оорутпайсыз.','Digitaalne mälu 🛒','Kas unustad poes käies alati midagi ära? Sinu ostunimekiri ootab sind äpis. Pane vajalik kohe kirja, et su partner saaks töölt tulles täpselt kõik vajaliku kaasa haarata – pole vaja oma pead koormata.'),
('8949a363-0fca-4998-bc28-ec5b3f0fc9b2'::uuid,'«Мен өзүм жасай алам!» эрежеси 👟','Ал өзү бут кийиминин боосун байлагысы келип жатат, ал эми сиз үйдөн чыгууга 10 мүнөт кечигип жатасыз. Аны шаштырбаңыз. Анын өнүгүүсү үчүн бузулган графикке караганда, жабыркабаган өзүнө болгон ишеним алда канча маанилүү.','„Ma teen ise!“ reegel 👟','Ta tahab ise kingapaelu siduda ja sa oled juba 10 minutit hiljaks jäämas. Ära kiirusta teda. Terve ego on tema arengu jaoks palju olulisem kui sassi läinud ajakava.'),
('b6dabad1-9ff8-435e-b107-865df601701d'::uuid,'Шыбырап сүйлөөнүн сыйкырдуу күчү 🤫','Балаңыз төшөктө жатып уктабай, өтө активдүү болуп жатабы? Үнүңүздү көтөрүүнүн ордуна, күтүлбөгөн жерден акырын, шыбырап сүйлөй баштаңыз. Бала сизди угуш үчүн көңүлүн топтогондо, мээси автоматтык түрдө уйку режимине өтөт.','Sosistamise müstiline vägi 🤫','Kas laps on voodis liiga aktiivne, et rahuneda? Selle asemel, et häält tõsta, langeta ootamatult tooni ja räägi sosinal. Kui laps keskendub sind kuulma, lülitub tema aju automaatselt unerežiimile.'),
('222c5b3e-e10d-4be3-be74-5b7c060039a8'::uuid,'Түнкү бейпилдик 🛁','Бир күн бою чуркап жүрүп, сиз да, балаңыз да чарчадыңыздар. Ал жылуу сууга түшүп жатканда, фондо жаратылыштын тынчтандыруучу үндөрүн коюп бериңиз. Суунун гармониясы эң тентек баланы да терең уйкуга даярдайт.','Öine rahu 🛁','Pärast päevast ringijooksmist olete nii sina kui ka su pisike väsinud. Kui nad vannis käivad, mängi taustaks rahustavaid loodushelisid. Vee harmoonia valmistab ka kõige jonnakama lapse ette sügavaks uneks.'),
('658a0f7f-5501-4d36-97c8-25ebf4c2bf93'::uuid,'Чарчоо жана эмоционалдык ашыкча жүктөм 🔋','Күн бою үстүңүзгө чыгып, кучактап, чачыңыз менен ойноп жатышат. Сизге болгону бир аз жеке мейкиндик керек. «Тийүүдөн чарчоо» (touch fatigue) — бул реалдуу нерсе. Сиз бөлмөдө кеминде 15 мүнөт жалгыз калууга толук укуктуусуз.','Kurnatud puudutustest 🔋','Terve päeva ronivad nad su otsas, küsivad kaisutusi ja mängivad su juustega. Kõik, mida sa tahad, on natuke füüsilist ruumi. Puudutuste väsimus on päriselt olemas. Sa väärid täiesti vähemalt 15 minutit omaette toas.'),
('fd872988-ca1c-4392-86ef-3fa893d01f3e'::uuid,'Ваннадагы суу агызуучунун «жегичи» 🛀','Мурда сууга түшкөндү жакшы көргөн балаңыз, ваннанын түбүндөгү тешиктен коркуп ыйлай баштадыбы? Фантазия өскөн сайын, негизсиз коркуулар пайда болушу мүмкүн. Аны тынчтандыруу үчүн тешикти пластик оюнчук менен жаап коюңуз.','Vannikorgi koletis 🛀','Kas su laps, kes varem armastas vannis käia, hakkas äkki nutma, sest kardab vanni äravoolu? Kujutlusvõime arenedes võivad tekkida põhjendamatud hirmud. Kata äravool mänguasjaga, et teda rahustada.'),
('380c78ab-6c26-4edf-8c80-e7615f9b4b80'::uuid,'Экөөбүз үчүн кечки эс алуу 🥂','Бала уктады. Эми үй жумуштарын четке коюңуз. Кеминде 20 мүнөт жубайыңыз менен бала, көйгөйлөр же чыгашалар тууралуу эмес, башка нерселер жөнүндө сүйлөшүңүз. Сиздер ата-эне болгонго чейин жубайлар элеңиздер!','Kohtinguõhtu taaskäivitus 🥂','Laps magab. Nüüd pane majapidamistööd kõrvale. Veeda vähemalt 20 minutit partneriga rääkides millestki muust peale lapse, probleemide või kulutuste. Olite paar enne, kui saite vanemateks!'),
('752bc100-4fdb-4f78-84aa-dd9676151255'::uuid,'Жансыз буюмдар менен маек 🗣️','Ал сейил бакта таш менен сүйлөшүп же үйдө отургучту урушуп жатабы? Ал дүйнөнү символдук оюн аркылуу кабыл алып жатат. Бул өзгөчө учурларды анын өнүгүү күндөлүгүнө белгилеп коюуну унутпаңыз.','Vestlused elutute esemetega 🗣️','Kas ta räägib pargis tõsimeeli kiviga või sõitleb kodus tooli? Ta töötleb maailma läbi sümboolse mängu. Märgi need erilised hetked kindlasti lapse arengupäevikusse.'),
('7bfbea7d-ee3e-4b33-88e0-e90f78f2538d'::uuid,'Атанын укалоо сеансы 💆‍♂️','Бүгүн бутуңуз менен көп жүрдүңүз, балаңыздын артынан чуркап белиңиз ооруп жатат. Ал уктаары менен жубайыңыздан 10 мүнөттүк ийин массажын жасап берүүсүн сураныңыз. Сиз үйүңүздүн тирегисиз, ал эми тиректер сөзсүз түрдө калыбына келип турушу керек.','Issi massaažiseanss 💆‍♂️','Oled täna palju jalgadel olnud ja lapse tagaajamine tundub selga murdvat. Niipea kui nad magavad, palu partnerilt 10-minutilist õlamassaaži. Sina oled oma kodu tugisammas ja sambad vajavad kindlasti taastamist.'),
('14bae514-5bcb-45ca-923d-75a7333cefe5'::uuid,'Уйкуну кечиктирүү амалдары ⏱️','Балаңыз жатар убакыт болгондо эле суусап, дааратканага баргысы келип же дубал менен коштошуп жатабы? Таймер коюңуз. «Коңгуроо кагылганда баары укташат» эрежесин киргизип, бул чексиз коштошуулардан сабырдуулук менен кутулуңуз.','Uinumist edasilükkav taktika ⏱️','Kas lapsel tekib magamamineku ajal äkki janu, vajadus tualetti minna või soov seinaga hüvasti jätta? Pane taimer. Rakenda reeglit „kõik magavad, kui kell heliseb“ ja vabasta end kannatlikult nendest lõpututest hüvastijättudest.'),
('4ec63d29-5d5a-4c61-aeca-3683d2926fad'::uuid,'Өзүңүздү азыктандырыңыз, энеке 🥗','Аларды тойгузуу үчүн ар кандай менюларды ойлоп таптыңыз, бирок өзүңүз ачкасызбы? Биздин рецепттерден 10 мүнөттө даярдалуучу, темирге жана кальцийге бай пайдалуу түшкү тамакты тандап, өзүңүзгө кам көрүңүз.','Toitainerikas ema 🥗','Oled nende toitmiseks erinevaid menüüsid välja mõelnud, aga oled ise ikka näljane? Vali meie retseptide hulgast tervislik, raua- ja kaltsiumirikas lõuna, mille valmistamine võtab vaid 10 minutit, ja tunne end väärtustatuna.'),
('d6b3a2c2-7743-47f8-927a-59220b3461a1'::uuid,'Кир жуудагы кичинекей жардамчыбыз 🧺','Сиз кийимдерди тыкан бүктөп жатсаңыз, ал кайра чачып «жардам» берип жатабы? Ачууланбай, аны оюнга айлантыңыз: «Ким бул байпактарды себетке тезирээк ыргытат экен, көрөлүчү!»','Meie väike pesupesemise abiline 🧺','Sa voldid usinalt pesu ja tema „aitab“, ajades selle jälle üle toa laiali. Selle asemel, et vihastada, muuda see mänguks: „Vaatame, kes saab need sokid kõige kiiremini korvi!“'),
('95036444-eb4a-4cd7-a33d-678f3daaa180'::uuid,'Авангарддык модачы 👗','Ал кышкы свитердин үстүнөн жайкы шорты кийип, чечкиси келбей жатабы? Зыяны жок. Кийими дал келбеген бала — бул өз чечимин эрдик менен коргоп жаткан бала. Анын эркин сындырбаңыз.','Avangardne moeguru 👗','Ta kannab suviseid lühikesi pükse talvise kampsuni peal ja ei taha neid ära võtta? Pole hullu. Laps, kes läheb välja ebasobivates riietes, on tegelikult laps, kes kaitseb vapralt oma otsust. Ära murra tema tahet.'),
('98f4059e-feba-4e5c-88c8-f44ceadd630c'::uuid,'Түнкү коркунучтардын сырын чечүү 😭','Балаңыз түн ортосунда көзү жумулуу ыйлап ойгонуп, эч кимди укпай жатабы? Ыйды талдоо куралы менен текшериңиз; эгер бул түнкү коркуу болсо, аны ойготууга аракет кылбаңыз. Жөн гана жанында болуп, унчукпай сооротуңуз.','Öiste hirmuhoogude lahtimõtestamine 😭','Kas laps ärkas keset ööd nuttes, silmad kinni, ega tundu kedagi kuulvat? Kontrolli nutu analüüsi; kui see on öine hirmuhoog, ära proovi teda äratada. Ole lihtsalt kohal ja paku vaikselt lohutust.'),
('bfca2126-084c-4371-a225-6bbeaa8fe2d1'::uuid,'Аба ырайын текшерүү ⛅','Сейилдөөгө чыгарда терезеден карап эле алданбаңыз. Сырттагы шамалдын жана температуранын негизинде идеалдуу кийимди тандоо үчүн аба ырайы жана кийим жардамчысын колдонуңуз, ошондо үйүңүздөн ыңгайлуу жана даяр болуп чыгасыз.','Ilmateade ⛅','Ära lase end eksitada aknast välja vaatamisest, kui jalutama lähed. Kasuta ilma ja riietumise assistenti, et määrata täiuslik riietus vastavalt tegelikule tuulele ja temperatuurile, ning lahku kodust mugavalt ja ettevalmistatult.'),
('25567149-e2e9-4c4d-aaff-501c9547f638'::uuid,'Сиздин коомчулук, сиздин ишенимдүү досторуңуз 💬','Абдан чарчадыңыз жана эч кимге эч нерсе түшүндүргүңүз келбей жатабы? Жөн гана Anacan коомчулугуна кирип, окурмандардын катарында болуңуз. Башка энелердин да ушундай чарчоону бөлүшүп жатканын көрүү — эң жакшы терапия, бул «мен жалгыз эмесмин» деген сезимди тартуулайт.','Sinu kogukond, sinu usaldusisikud 💬','Oled täiesti kurnatud ega taha kellelegi midagi selgitada. Liitu lihtsalt Anacani kogukonnaga ja ole lugeja. Teiste emade sarnase väsimuse nägemine võib olla parim teraapia, luues tunde, et ma pole üksi.'),
('3df12920-0213-48db-ae96-b67ec62ae28a'::uuid,'Жандуу концерттер (жана кошуналар!) 🎤','Ал кашыкты алып, бөлмөнүн ортосунда туруп, бар үнү менен ырдап жатабы? Кошуналар эмне дейт деп кабатыр болбоңуз. Үйүңүздө жылдыз өсүп жатат; жөн гана кол чаап коюңуз.','Live-kontserdid (ja naabrid!) 🎤','Ta on võtnud lusika, seisab keset tuba ja laulab täiest kõrist. Ära muretse, mida naabrid arvavad. Sinu kodus kasvab täht; lihtsalt plaksuta.'),
('3f3676c6-cf62-4752-a389-70e0f348c529'::uuid,'Уйкуга алып баруучу музыкалык саякат 🎶','Кечки түшүнүксүз кыяңкечтикти жеңил классикалык музыка менен токтотуп көрүңүз. Көбүнчө, бул жөнөкөй, бирок эффективдүү ыкма үйдө кереметтерди жаратып, бөлмөгө тынчтык алып келет.','Muusikaline teekond unne 🎶','Proovi seletamatuid õhtuseid jonnihooge katkestada kerge klassikalise muusikaga. Tihti teeb see lihtne, kuid tõhus nipp kodus imesid ja toob tuppa kindla rahu.'),
('3e411b4b-9fe8-4f71-93e2-682182a18dba'::uuid,'Экран алдында өткөн убакыт үчүн күнөөлүү сезим 📺','Бүгүн иштериңиз көп болгондуктан, аларга экран алдында көп убакыт өткөрүүгө уруксат берип, азыр өзүңүздү күнөөлүү сезип жатасызбы? Өзүңүздү күнөөлөбөңүз. Кээде, санариптик эмчи — психологиялык чарчоодон сактап калуунун жалгыз жолу.','Süüdi ekraaniajas 📺','Kas andsid neile täna oma toimetuste tõttu rohkem ekraaniaega ja tunned nüüd süümepiinu? Ära süüdista ennast. Mõnikord on digitaalne lapsehoidja ainus viis päästa end psühholoogilisest kokkuvarisemisest.'),
('66770f83-ef83-4481-9f8c-e9788791f68a'::uuid,'Операция: Телефонду жашыруу 📱','Телефонуңузду таппай калып, бир аздан кийин оюнчуктардын арасынан таап алдыңызбы? Ал сиздин көңүлүңүздү телефон менен бөлүшкүсү келбейт. Аппаратты четке коюп, ага 15 мүнөт толук көңүл буруңуз.','Operatsioon: peida telefon 📱','Sa ei leia oma telefoni ja veidi aja pärast ilmub see mänguasjakasti. Ta ei taha jagada sinu tähelepanu telefoniga. Pane seade kõrvale ja kingi talle 15 minutit katkematut tähelepanu.'),
('b18d81af-044b-40e7-b55d-b23baee972a4'::uuid,'Жымжырттыктын санариптик өлчөмү 🤫','Акыры укташты! Үйдө орногон тынчтыкка ишене албай жатасыз. Үн өлчөгүчүңүздү иштетиңиз жана экрандагы 0-10 децибелдик көрсөткүчтү карап, мээңиздин акырындап эс алып жатканын сезиңиз.','Vaikuse digitaalne mõõdupuu 🤫','Nad on lõpuks magama jäänud! Sa ei suuda uskuda vaikust, mis on majja laskunud. Aktiveeri helimõõtja ja tunne visuaalselt, kuidas su aju aeglaselt lõdvestub, vaadates ekraanil 0-10 detsibelli näitu.'),
('09d17b10-a60b-4930-b773-b0f5bb7e0366'::uuid,'Меники! (Бул менин оюнчугум, сеники эмес!) 🧸','Сейил бакта ал слайдда же кумдуу аянтчада эч кимге кезегин бергиси келбей, оюнчуктарын бекем кармап жатабы? Бул өзүмчүлдүк эмес; бул чек араны белгилөө. Аны бөлүшүүгө мажбурлоонун ордуна, оюн аркылуу кезек менен ойноо системасын үйрөтүңүз.','Minu oma! (See on minu mänguasi, mitte sinu!) 🧸','Pargis ei taha ta kellelegi liumäel või liivakastis korda anda ja hoiab oma mänguasjadest kramplikult kinni. See pole isekus; see on piiride seadmine. Selle asemel, et sundida teda jagama, õpeta talle mängu kaudu kordamööda tegutsemist.'),
('0a13d571-0f47-4b38-ba09-6279a4e6c3b5'::uuid,'Караңгылыкка чакыруу 🌙','Балаңыз уктоочу бөлмөдө жарык өчкөндө тынчсызданабы? Бөлмөнүн бир бурчуна кичинекей, жылуу түстөгү түнкү чырак коюңуз. Терең уйку үчүн бөлмөнүн калган бөлүгү толугу менен караңгы болушу керек.','Kutse pimedusse 🌙','Kas laps muutub ärevaks, kui magamistoas tuled kustuvad? Pane toa ühte nurka väike soojatooniline öölamp. Ülejäänud tuba peaks sügavaks uneks jääma täiesti pimedaks.'),
('f1a7ace3-b71a-47a5-8150-e29d91b1d2f6'::uuid,'Энеге эс алуу керек болгондо 🛑','Сиз робот эмессиз. Эгер бүгүн тамак жасаганга күчүңүз жок болсо, даяр тамакка буйрутма бериңиз же жөн гана макарон кайнатыңыз. Мыкты эне болуу — баарын өзүң жасоо дегенди билдирбейт. Өзүңүзгө адам болууга уруксат бериңиз.','Kui emme vajab puhkust 🛑','Sa ei ole robot. Kui sul pole täna energiat süüa teha, telli toit või keeda lihtsalt pastat. Täiuslik ema olemine ei tähenda, et pead kõike ise tegema. Anna endale luba olla inimene.'),
('012a4a46-c01f-4202-b7ec-b6dfb922b323'::uuid,'Дүкөндөн күтүлбөгөн сатып алуулар 🛒','Базарга кетер алдында «Соода тизмеңизди» ачтыңыз, анан алардын артыңыздан келип, телефон экраныңызды таптап, бир нерселерди чиймелеп жатканын көрдүңүзбү? Ооба, алар да сиздин санариптик жашооңузду туурап жатышат!','Üllatused ostunimekirjas 🛒','Avasid enne poodi minekut oma ostunimekirja ja nägid siis neid selja tagant tulemas, su telefoniekraani toksimas ja sinna midagi kritseldamas. Jah, nad kopeerivad ka sinu digitaalset elu!'),
('1c68be5f-505e-4c46-be58-571a7196e98d'::uuid,'Окуяңыз менен бөлүшүңүз 💬','«Мындай сезимде болгон жалгыз менминби?» деп ойлонуп көрдүңүз беле? Anacan коомчулугуна кошулуңуз жана сиз башыңыздан өткөрүп жаткан нерселерди так түшүнгөн башка энелер менен байланышыңыз.','Jaga oma lugu 💬','Mõtled vahel: „Kas ma olen ainus, kes nii tunneb?“ Liitu Anacani kogukonnaga ja võta ühendust teiste emadega, kes mõistavad täpselt, mida sa läbi elad.'),
('0f7001d8-21ca-493f-95e3-7b29b5f52d2b'::uuid,'Маанай күндөлүгүндөгү моюнга алуулар 📝','Телефонуңузду колуңузга алыңыз. Социалдык тармактарда башкалардын жашоосун карап отурбай, «Маанай күндөлүгүн» ачыңыз да, балаңыздын бүгүнкү эң күлкүлүү окуясын келечек үчүн жазып коюңуз. Санариптик терапия чындап иштейт.','Ülestunnistused meeleolupäevikus 📝','Võta telefon kätte. Selle asemel, et sotsiaalmeedias teiste inimeste elu kerida, ava oma meeleolupäevik ja pane kirja lapse tänane kõige naljakam hetk tuleviku tarbeks. Digitaalne teraapia toimib.'),
('9c6e1121-6b3a-4988-b52a-daff7cb47017'::uuid,'Сиздин акылдуу жардамчыңыз 🤖','Балаңыздын табити эмнеге капысынан жоголду? Anacan AI жасалма интеллектинен көйгөйлүү суроолоруңузду бериңиз жана илимий жактан негизделген так жоопторду дароо алыңыз.','Sinu nutikas abiline 🤖','Miks lapsel isu kadus? Küsi Anacan AI-lt oma pakilisi küsimusi ja saa koheseid, teaduslikult põhjendatud vastuseid.'),
('507a4882-997e-48f9-8d0c-a6ff5f18c3ac'::uuid,'Кичинекей юристтей соодалашуу 🗣️','«Дагы 5 мүнөт ойнойюн, анан кийинем» дейби? Ал азыртадан эле кесипкөй адамдай сүйлөшүү жүргүзүүгө аракет кылып жатат. Анын тил өнүктүрүү жөндөмү абдан жакшы, бирок сүйүү менен чектерди жана эрежелерди сактоону унутпаңыз.','Kauplemine nagu väike advokaat 🗣️','Ta ütleb: „Veel 5 minutit mängu ja siis panen riidesse“? Ta proovib juba nagu proff läbi rääkida. Tema keeleline areng on suurepärane, kuid ära unusta armastavalt oma piire ja reegleid hoida.'),
('982b6e37-c6cb-46f9-bd93-9fafd76bcda8'::uuid,'Тынчтыктын бир көз ирмеми 🥱','Балаңыз уктагысы келбей ыйлап жатабы? Мажбурлабаңыз. Бөлмөдөгү жарыкты өчүрүп, «Тынч китеп окуу убактысын» жарыялаңыз. Бул экөөңүздөрдү тең эс алдыра турган жаңы адат болуп калат.','Hetk rahu 🥱','Laps ei taha uinakut teha ja nutab? Ära sunni. Hämarusta toas tuled ja kuuluta välja vaikse raamatu aeg, et luua uus rutiin, mis teid mõlemaid lõõgastab.'),
('dd274cad-cc38-4230-a074-0f529d065804'::uuid,'Бүгүн муну жебейм! 🥣','Кечээ кубанып жеген шорпосун бүгүн оозуна да албай жатабы? Эгер тиштери оорубаса, бул жөн гана сиздин чыдамыңызды сынап жатканы. Анын тамактануу планынан ошол эле витаминдерди камтыган башка рецепттерди издеп көрүңүз.','Seda ma täna ei söö! 🥣','Supp, mida ta eile rõõmuga sõi, ei taha ta täna isegi maitsta? Kui hambaprobleeme pole, on see lihtsalt tahtejõu proovilepanek. Otsi tema toitumiskavast alternatiivseid retsepte, mis pakuvad samu vitamiine.'),
('ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526'::uuid,'Атанын күлкүлүү үндөрү 🤡','Сиздин аракетиңиз натыйжа бербей калганда, атасынын күлкүлүү үндөрү жана жоруктары кырдаалды дароо сактап калышы мүмкүн. Кечки маанайы жок учурларда, топту дароо атасына өткөрүп бериңиз да, өзүңүз бир аз эс алып, четтен карап туруңуз.','Issi naljakad hääled 🤡','Kui sinu pingutused enam ei aita, võivad issi naljakad hääled ja grimassid päeva päästa. Õhtuste jonnihoogude ajal anna pall kohe talle üle ja vaata kõrvalt, samal ajal kui ise puhkad.'),
('805b4060-d925-4469-abb9-000b87b286a1'::uuid,'Жаратылыштын сырлары 🍁','Үйдөгү зериктирген атмосфера экөөңүздөрдү тең чарчаттыбы? Паркка барып, эң кызык формадагы ташты издөө миссиясын баштаңыз. Жаратылыш — алар үчүн эң чоң лаборатория, ал баланын бардык стрессин жок кылат.','Looduse saladused 🍁','Kodune tuim õhkkond väsitab teid mõlemaid. Suundu parki ja võta ette missioon leida kõige kummalisema kujuga kivi. Loodus on nende jaoks suurim labor ja sulatab kogu stressi.'),
('88ec7e91-36e6-4aab-9210-fc0f8e69cab3'::uuid,'Дасторкондогу элестүү коноктор ☕','Ал сизге бош чөйчөктү сунуп, «чай ич» деп, жок досу менен сүйлөшүп жатабы? Бул — элестетүү жөндөмүнүн шедеври. Бөлмөнүн бир бурчунда болуп жаткан бул оюнду үзбөңүз; сиз да ошол чайды ичип коюңуз.','Kujuteldavad külalised laua taga ☕','Ta ulatab sulle tühja tassi, ütleb „Joo teed“ ja räägib oma nähtamatu sõbraga? See on kujutlusvõime arengu meistriteos. Ära katkesta seda toanurgas toimuvat mängu; joo ka sina seda teed.'),
('9c237165-d4a6-41d4-ba0a-333830a89409'::uuid,'Акылдуу жомоктогу мен 🪄','Бардык классикалык китептерди жаттап бүттүңүзбү? «Акылдуу» жомок тиркемесин ачып, балаңызды башкы каарман кылыңыз жана анын бөлмөсүн багындырыла турган жер катары сүрөттөп, укмуштуудай түнкү жорукту жаратыңыз.','Mina nutikas muinasjutus 🪄','Oled kõik klassikalised raamatud pähe õppinud. Ava „nutikas“ jutuäpp, tee oma lapsest peategelane ja kujunda tema tuba vallutatavaks paigaks, luues erakordse une-eelse seikluse.'),
('62114884-cb2a-44c8-ab0b-33ab815b8e09'::uuid,'Ваннадагы тынчтык 🛀','Суу менен ойноо ушунчалык кызыктуу болгондуктан, манжалары бырышып кетсе да ваннадан чыккысы келбейт. Аларга 5 мүнөт калганын эскертип, таймер коюңуз. «Коңгуроо кагылганда чыгабыз» деген эреже көбүнчө кереметтерди жаратат.','Rahu vannis 🛀','Veega mängimine on nii lõbus, et nad ei taha vannist välja tulla isegi siis, kui sõrmed on kortsus. Anna 5-minutiline hoiatus ja pane taimer. Reegel „väljume, kui kell heliseb“ teeb sageli imesid.'),
('9f52c47e-5431-4d83-b54d-9c8d7cbf5228'::uuid,'«Колумду кармаба!» деген эркиндик 🚶‍♂️','Көчөдө колуңузду кармагысы келбей, эркин чуркагысы келип жатабы? Коопсуз жерлерде ага бул эркиндикти бериңиз. Аны көз жаздымда калтырбай, өз кадамдары менен дүйнөнү таанып-билүүсүнө жол бериңиз.','„Ära hoia mu käest!“ vabadus 🚶‍♂️','Ta keeldub tänaval kindlalt sinu käest kinni hoidmast ja tahab vabalt joosta? Anna talle see vabadus turvalistes kohtades. Hoia tal silm peal ja lase tal oma sammudega maailma vallutada.'),
('d319859d-6f77-4ec4-b4f9-90c9441fac9e'::uuid,'Өсүү этаптары 📈','3 жаштын тегерегинде алардын кыймыл-аракет жөндөмү, сөз байлыгы жана эмоционалдык интеллекти тез өзгөрөт. Кичинекей ачылыштарын эстеп калуу үчүн, үзгүлтүксүз жазып туруңуз жана «Өсүү трекеринде» архивдеп коюңуз.','Arenguetapid 📈','3. eluaasta paiku muutuvad nende motoorika, sõnavara ja emotsionaalne intelligentsus kiiresti. Et kõik väikesed avastused meeles püsiksid, tee regulaarselt märkmeid ja arhiveeri need arengupäevikusse.'),
('01326cb0-274c-49ad-8b92-7ce1373a0568'::uuid,'Кечирим сурап, кайра эле кайталоо 🧸','Бир нерсени уруп же сындырып алганы үчүн чын жүрөктөн кечирим сурайт, бирок 5 мүнөттөн кийин эле кайра кайталайбы? Ал азырынча өзүнүн импульстарын башкара албайт. Сабырдуулук менен эрежелерди кайра-кайра түшүндүрө бериңиз.','Palun vabandust, ja teen seda uuesti 🧸','Ta palub siiralt vabandust löömise või millegi lõhkumise pärast, kuid kordab 5 minutit hiljem täpselt sama tegevust? Ta ei suuda veel oma impulsse kontrollida. Selgita reegleid kannatlikult ikka ja jälle.'),
('1efb2536-bf55-4365-890d-581fbbac3193'::uuid,'Бөлүшүү жана байланышуу муктаждыгы 💬','Оор чечим кабыл алууга туура келип жатабы? (Бала бакча, горшокко үйрөтүү, уйку режими). Anacan коомчулугунда тажрыйбалуу энелер китептерден таба албай турган реалдуу чечимдерди бөлүшөт — бул күнүмдүк тарбиялоонун жүрөгүнөн чыккан практикалык кеңештер.','Vajadus jagada ja suhelda 💬','Seisad raske valiku ees? (Lasteaed, potitreening, unetreening). Anacani kogukonnas jagavad kogenud emad elulisi lahendusi, mida ühestki raamatust ei leia – praktilised nõuanded otse lapsevanemluse südamest.'),
('d2d2c46d-7705-4c59-b1ff-a6a3d0986863'::uuid,'Жомоктун аягын алар өздөрү жазсын 🪄','Экөөңүздөр тең классикалык китептерден чарчадыңыздарбы? «Акылдуу» жомоктор менен бул жолу аягын балаңыз өзү тандасын. «Бул каарманга ким жардам берди деп ойлойсуң?» деп сурап, уктаар алдында анын элестетүүсүнө канат бериңиз.','Lase neil kirjutada muinasjutu lõpp 🪄','Te mõlemad olete klassikalistest raamatutest väsinud. Lase „nutikate“ juttudega lapsel seekord lõpp valida. Küsi: „Kes sinu arvates seda kangelast aitas?“ ja lase tema kujutlusvõimel enne und lennata.'),
('37e65e72-e2dc-4492-b8ea-92aeab4db745'::uuid,'Дени сак эне, дени сак бала 🥑','Күнүмдүк шашылыш иштердин арасында түшкү тамакты шашып ичпеңиз. Отуруп, темирге жана кальцийге бай даамдуу салаттан ырахат алыңыз. Сиздин энергияңыз — бул үйдүн кыймылдаткычы, аны сактаңыз!','Terve ema, terve beebi 🥑','Ära söö lõunat kiirustades. Istu maha, naudi maitsvat salatit, mis on rikas raua ja kaltsiumi poolest. Sinu energia on selle kodu mootor – hoia seda!'),
('9a78401e-398c-45fd-a3a7-dae1cd59ed31'::uuid,'Жымжырттыктын ырастоосу 🤫','Ызы-чуулуу күндөн кийин, балаңыз уктагандан кийин, бөлмөдөгү тынчтыкты үн өлчөгүч менен ченеп көрүңүз. Ал сандардын нөлгө жакындаганын көрүү эле эненин мээси үчүн эң мыкты визуалдык массаж сыяктуу таасир этет.','Vaikuse jaatamine 🤫','Pärast lärmakat päeva, kui laps magab, mõõda toa vaikust helimõõtjaga. Juba ainuüksi nende numbrite nulli lähenemise nägemine toimib emale kui parim visuaalne massaaž.'),
('ba7f66f9-da13-4eea-9e4a-a968d14f269b'::uuid,'Ашканадагы укмуштуу окуялар 🧑‍🍳','Сиз камыр жууруп жатканда, алар сөзсүз түрдө отургучту сүйрөп келип «жардам берүүгө» аракет кылышат. Аларга өзүнүн кичинекей пластик идишине ун салып берүүгө уруксат бериңиз. Ашкана бир аз булганышы мүмкүн, бирок алардын бетиндеги олуттуу жана көңүл бурган көрүнүш тазалоого кеткен ар бир мүнөткө татыйт.','Köögiseiklused 🧑‍🍳','Kui sa tainast rullid, tõmbab laps kindlasti tooli ligi ja proovib „aidata“. Lase tal oma väikeses plastkausis jahu segada. Köök võib küll sassi minna, kuid see tõsine ja keskendunud ilme tema näol on iga koristusminutit väärt.'),
('06f0acb2-a541-42e5-8b33-ed2285d3285f'::uuid,'Бири-бирибизге ыраазычылык 🥂','Оор күндү артта калтырдыңыз. Балаңыз уктагандан кийин, өнөктөшүңүз менен бир чыны чай ичип, «Бул бороондуу күндө мага абдан жардам бердиң» деп ыраазычылык билдириңиз. Командалык дух ушинтип куралат.','Tänulikkus üksteise vastu 🥂','Raske päev on seljataga. Pärast lapse uinumist vala partneriga tass teed ja tänage üksteist: „Aitasid mind sel tormilisel päeval nii palju.“ Nii ehitatakse meeskonnavaimu.'),
('4217bad1-d028-470b-a2a2-ceacb5b15105'::uuid,'AI, реалдуу жооптор 🤖','3 жаштагы балдардын кыяңкечтигинин артында кандай илимий жана педиатрлар жактырган себептер бар? Интернеттеги коркунучтуу комментарийлерди окубай, балаңыздын психологиясы боюнча так жана кесипкөй талдоону түздөн-түз Anacan AI аркылуу алыңыз.','AI, päris vastused 🤖','Millised on teaduslikud ja pediaatrite poolt heaks kiidetud põhjused 3-aastaste jonnihoogude taga? Selle asemel, et lugeda hirmutavaid kommentaare, saa täpne ja professionaalne analüüs lapse psühholoogiast otse Anacan AI-lt.'),
('50050f6d-75e8-48b1-9632-bcebb31ce6fa'::uuid,'Сенсордук ашыкча жүктөм 🔋','Күн бою үстүңүзгө чыгып, чачыңызды тартып, тынбай ызы-чуу салдыбы? Нерв системаңыз кызыл сигнал берип жатат. «Тийүү чарчоосу» — бул реалдуу нерсе. Балаңызды өнөктөшүңүзгө берип, өзүңүз башка бөлмөгө чыгып, татыктуу эс алыңыз.','Sensoorne ülekoormus 🔋','Terve päeva on nad su otsas roninud, juukseid sikutanud ja lakkamatult lärmi teinud. Sinu närvisüsteem saadab punaseid hoiatusi. Puudutusväsimus on täiesti reaalne. Anna laps partnerile ja mine teise tuppa väljateenitud puhkusele.'),
('0efdad7b-f986-4a21-8e04-fc9cffca1b7d'::uuid,'Күлкүлүү айтылган сөздөр 🗣️','Алар сөздөрдү ушунчалык өзгөчө жана жагымдуу интонация менен айтышат, жылмайбай коюу мүмкүн эмес. Күлүп оңдобоңуз; тескерисинче, кунт коюп угуп, туура сүйлөмдү же айтылышты кайталап жооп бериңиз.','Naljakad hääldused 🗣️','Nad hääldavad sõnu nii ainulaadsete ja võluvate rõhkudega, et naeratamata on võimatu. Ära paranda neid naerdes; kuula hoopis tähelepanelikult ja vasta lihtsalt õiget lauset või hääldust korrates.'),
('6d1f309e-d64f-4916-a1e2-48f064024563'::uuid,'Супермаркеттеги «энелик мээ» 🛒','Эс тутумуңузга ишенип дүкөнгө барып, памперс албай үйгө кайттыңызбы? Мындай болуп турат! Бардык муктаждыктарыңызды дароо «Соода тизмесине» жазып алууну адат кылыңыз — санариптик эс тутумуңуз күнүңүздү сактап калсын.','Emme aju toidupoes 🛒','Usaldasid mälu, läksid poodi ja tulid mähkmeteta koju? Juhtub! Tee harjumuseks kirjutada kõik vajadused kohe ostunimekirja – las digitaalne mälu päästab päeva.'),
('b478188b-090e-49fa-8067-44d7985fc9d2'::uuid,'Сезимдериңизди кагазга төгүңүз 📝','Канчалык чарчаганыңызды эч ким көрбөй жаткандай сезилеби? «Маанай күндөлүгү» сизди угууга даяр. Бүгүн сизди жиниңизге тийгизген бардык майда-чүйдө нерселерди жазып, оюңузду тазалаңыз.','Vala oma tunded paberile 📝','Tundub, et keegi ei näe, kui kurnatud sa oled? Sinu meeleolupäevik on siin, et sind kuulata. Pane kirja kõik pisiasjad, mis sind täna hulluks ajasid, ja puhasta oma mõtteid.'),
('51755ad7-f4a2-46b5-9170-1977fdac0046'::uuid,'Уйку үчүн идеалдуу шарт түзүү 🌙','Кичинекейиңиздин тезирээк уктап кетишине жардам берүү үчүн, уктаардан бир саат мурун бөлмөдөгү ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Уйку гормону — мелатонин караңгы жана технологиясыз чөйрөдө эң жакшы иштелип чыгат.','Täiusliku uneõhkkonna loomine 🌙','Et aidata väikesel kiiremini uinuda, lülita tund enne und välja kõik lisatuled ja tahvelarvutid. Unehormoon melatoniin tekib kõige paremini pimedas ja tehnoloogiavabas keskkonnas.'),
('556d15ad-f396-4daf-9a38-c5bd773f19f0'::uuid,'Парктагы эркиндик 🌳','Төрт дубал аларды зериктириши мүмкүн. Сырттагы желге ылайыктуу кийимди тандоо үчүн «Аба ырайы жана кийим жардамчысын» колдонуңуз, анан паркка жөнөңүз. Кум менен ойноп, чуркап, жыгылсын. Эркиндик — алардын өнүгүүсү үчүн эң мыкты дары.','Vabadus pargis 🌳','Neli seina võivad lapse rahutuks teha. Kasuta ilmateate ja riietuse assistenti, et valida õue jaoks ideaalne riietus, ja suundu parki. Lase tal liivas mängida, joosta ja komistada. Vabadus on parim ravim arenguks.'),
('b2f0448e-4bda-4f45-8af5-d1f543150cda'::uuid,'Күтүлбөгөн кучактоолор 💖','Бөлмөнүн ортосунда ойноп жатып, капысынан сизге карап, чуркап келип, мойнуңузду бекем кучактап алдыбы? Бул бардык уйкусуз түндөргө, бардык чарчоого татыйт! Бул көз ирмем алып келген терең, өзгөчө тынчтыктан жана кубанычтан ырахат алыңыз.','Ootamatud kaisutused 💖','Toa keskel mängides vaatab ta äkki sulle otsa, jookseb ligi ja paneb käed tugevalt ümber su kaela. See on väärt kõiki unetuid öid ja kogu väsimust! Naudi sügavat, ainulaadset rahu ja rõõmu, mida see hetk toob.'),
('354da7a1-73e7-4191-ab3d-5f7d75ac4224'::uuid,'Убакыт түшүнүгүнүн калыптанышы ⏱️','Алар «эртең», «кечээ» же «кийин» деген сөздөрдү көп колдонушат, бирок кээде туура эмес контексттеби? Бул алардын убакытты түшүнүүсү активдүү өнүгүп жатканын билдирет! Алардын аракеттерин жылмаюу менен угуңуз.','Ajamõiste tekkimine ⏱️','Kas nad kasutavad sageli sõnu nagu „homme“, „eile“ või „hiljem“, kuid vahel vales kontekstis? See tähendab, et nende ajataju areneb aktiivselt! Kuula nende katsetusi õrna naeratusega.'),
('8b9fda41-95cb-4937-8a79-67166a02c4b7'::uuid,'Эне үчүн тыныгуу ☕','Балаңыз өз алдынча ойноп жатканда, дароо үй жумуштарына чуркабаңыз. Чачылган бөлмө күтө турат, бирок сиздин энергияңыз түгөнүп калышы мүмкүн. Отуруп, жылуу кофеңизден ырахат алыңыз.','Puhkepaus emmele ☕','Kui laps mängib iseseisvalt, ära torma kohe kodutöid tegema. sassis tuba võib oodata, aga sinu energia võib otsa saada. Istu maha ja naudi oma sooja kohvi.'),
('c1a7e066-6918-4641-ab6d-c5c20c553974'::uuid,'Уйкуга чейинки качуу стратегияңыз 🛌','Алар бешиктен же керебеттен чыгууга аракет кылып жатышабы? Бөлмөнүн коопсуздугун кайра текшериңиз. Балким, чоңдордун керебетине өтүү убагы келгендир.','Sinu magamamineku põgenemisplaan 🛌','Kas ta proovib võrevoodist välja ronida? Kontrolli tuba ohutuse seisukohalt. Võib-olla on aeg minna üle suure lapse voodile.'),
('46401ae3-aa9a-4ec9-afa2-b6cab38572ff'::uuid,'Элестүү сценарийлер 🧸','Алар оюнчуктарын тамактандырып же «ооруп» калганда аларга кам көрүп жатышабы? Символикалык оюн — бул боорукердикти өнүктүрүүнүн негизги кадамы. Бул когнитивдик секирикти алардын өнүгүү трекерине сыймыктануу менен белгилеп коюңуз!','Kujuteldavad stsenaariumid 🧸','Kas ta toidab oma mänguasju või teeskleb, et hoolitseb nende eest, kui nad on „haiged“? Sümboolne mäng on empaatia arengu alustala. Märgi see kognitiivne hüpe uhkusega oma arengupäevikusse!'),
('4b6ccde7-7cce-4142-8822-fa952592f465'::uuid,'Уйкунун белгилери 🥱','Алар көздөрүн ушалап же кулактарын тартып жатышабы? Уйкусу келип ыйлаганын күтпөңүз; дароо жарыкты өчүрүп, кечки режимиңизди баштаңыз.','Unemärgid 🥱','Kas ta hõõrub silmi või sikutab kõrvu? Ära oota täielikku uneväsimusest tingitud jonnihoogu; hämarusta kohe tuled ja alusta õhtuse rutiiniga.'),
('4cba464d-475d-46de-93c9-1a54b6d0a768'::uuid,'Сыйкырдуу түнкү атмосфера 🪄','Кичинекейиңиз уктабай жатабы? Тиш жууган аюу каарманы жөнүндө «Акылдуу жомок» түзүп көрүңүз, бул жаңы адаттарды кызыктуу жана жагымдуу кылат.','Maagiline öine keskkond 🪄','Kas su väikesel on raske uinuda? Proovi luua „nutikas jutt“ karust, kes peseb hambaid, et muuta uued harjumused lõbusaks ja kaasahaaravaks.'),
('7ef518fa-cecf-4467-bd34-eb7fb3a21761'::uuid,'Сейил бактагы баарлашуу 🌳','Балаңыз башка балдар менен түз ойнобой, жанында эле ойноп жатабы? Параллелдүү оюн бул курак үчүн абдан табигый нерсе. Аларды кысымга албай, социалдашуусун колдоңуз.','Ühendus pargis 🌳','Kas su laps mängib teiste laste kõrval, mitte nendega koos? Paralleelmäng on selles vanuses täiesti loomulik. Toeta nende sotsialiseerumist ilma surveta.'),
('85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff'::uuid,'Брокколи изилдөөчүсү 🥦','Балаңыз шорпосундагы жашыл жашылчаны таап алып, жебей койдубу? «Тамактануу планынан» жашылчаларды түстүү макарон менен аралаштырып, аларды алаксытып, пайдалуу азыктарды акылдуулук менен жашыруунун эң даамдуу жолдорун табыңыз.','Brokolidetektiiv 🥦','Kas laps avastab supist ühe rohelise köögivilja ja keeldub söömast? Avasta toitumiskavast maitsvaimad viisid köögiviljade segamiseks värvilise pastaga, et teda tähelepanu hajutada ja tervislikku toitu nutikalt peita.'),
('9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21'::uuid,'Сезимдериңизди кабыл алуу 📝','Күн бою баарына ''жок'' деп айтып чарчап, өзүңүздү күнөөлүү сезип жатасызбы? Маанай күндөлүгүңүздү ачыңыз. Бүгүн өзүңүзгө ''жалгыз калсам экен'' деген ички ойлоруңузду эркин билдирүүгө уруксат бериңиз. Өзүңүздү кыйнабаңыз; ар бир эне чарчайт жана кээде өзү менен өзү калууга муктаж болот.','Oma emotsioonide teadvustamine 📝','Tunned end süüdi, sest ütlesid terve päeva kõigele „ei“? Ava oma meeleolupäevik. Luba endal täna vabalt väljendada neid kõige tumedamaid „soovin, et oleksin üksi“ mõtteid. Ära ole enda vastu karm; iga ema väsib ja vajab vahel lihtsalt hetke iseendale.'),
('df69592f-4c0f-4591-8df6-51164eef4e12'::uuid,'Бул менин күнөөм эмес! 🤷‍♂️','Алар атайылап суу төгүп, анан столду күнөөлөп: ''Стол тайгаланып кетти!'' деп айтыштыбы? Бул калп эмес; бул балаңыздын жоопкерчиликтен качуу жана өзүн коргоо боюнча өнүгүп жаткан инстинкти. Талашпаңыз. Тескерисинче, ''Кел, столго жардам берип, экөөбүз чогуу сүртүп коёлу'' деп, жоопкерчиликти жумшак түрдө үйрөтүңүз.','See pole minu süü! 🤷‍♂️','Nad ajasid meelega vett maha, aga süüdistasid siis lauda, öeldes: „Laud libises!“ See ei ole valetamine; see on lapse arenev instinkt vältida vastutust ja end kaitsta. Ära vaidle. Selle asemel sisenda õrnalt vastutustunnet, öeldes: „Aitame lauda ja pühime koos ära.“'),
('7ac03452-73e8-4680-9a3a-f2917f96ee7f'::uuid,'Үйдө отуруп тажап кетүү психологиясы ⛅','Үйдө отуруп тажап, балаңыз да тынчсызданып жатабы? Аба ырайын жана кийимдерин текшерип, эң ыңгайлуу кийимин кийгизип, сейил бакка чуркаңыз! Таза аба жана кыймыл эркиндиги анын өнүгүп жаткан мээси үчүн да, сиздин чарчаган нервдериңиз үчүн да эң мыкты дары болот.','Toasistumise psühholoogia ⛅','Tunned end kodus lämmatatuna ja laps muutub rahutuks? Kontrolli ilma ja riietust, vali täiuslik komplekt ja tõtta parki! Värske õhk ja liikumisvabadus on parim detox nii lapse arenevale ajule kui ka sinu väsinud närvidele.'),
('ab102c70-f16b-4f7f-8521-b11e20c36d7a'::uuid,'Кир бүктөө экспедициясы 🧺','Таза кирлерди кылдаттык менен бүктөп койсоңуз, эки секундда эле алардын ичине кирип, баарын чачып салыштыбы? Бөлмөдө терең тынчтык орноду... Нервдериңиз чыңалып жатабы? Терең дем алыңыз. Чачылган кийимдердин үстүнө өзүңүздү таштап, күлкү менен бул башаламандыкка кошулуңуз.','Pesuvirna voltimise ekspeditsioon 🧺','Oled vaevaliselt kõik puhtad riided ära voltinud ja kahe sekundiga on nad sinna sisse sukeldunud ja kõik laiali pildunud. Tuba täidab suur vaikus... Kas närvid on läbi? Hinga sügavalt sisse. Viska end ise sassi aetud riidehunnikusse ja alistu naeruga kaosele.'),
('e3d6247b-8c6f-4322-9f82-93d3245cab38'::uuid,'Акылдуу окуянын режиссеру 🪄','Классикалык китептердеги эски каармандардан тажадыңызбы? ''Акылдуу жомокторду'' ачыңыз жана бүгүн кечинде балаңызга жомокчу болууга мүмкүнчүлүк бериңиз. ''Бул учуучу динозавр азыр кайда барышы керек?'' деп сураңыз жана анын өзүнүн кыялкеч дүйнөсүнө чөмүлүп, уктап калганын байкаңыз.','Nutika loo lavastaja 🪄','Tüdinenud klassikaliste raamatute vanadest tegelastest? Ava „Nutikad lood“ ja lase lapsel täna õhtul jutuvestja olla. Küsi: „Kuhu see lendav dinosaurus nüüd minema peaks?“ ja vaata, kuidas nad oma kujutlusmaailma eksinuna unne suikuvad.'),
('62178f50-5d62-4afb-bacf-33c6e7bf5732'::uuid,'Атанын көңүл топтоо режими ✈️','Энергиясын сарптай албай, уктоодон качуу үчүн миң шылтоо таап жатабы? Атасын чакырыңыз! Ал баланы көтөрүп ''самолёт'' оюнун ойногондо, бөлмөнү күлкүгө толтуруп, топтолгон энергиянын баары тарап кетет.','Issi fookusrežiim ✈️','Ei saa energiat välja ja leiutab tuhat vabandust, et vältida magamaminekut? Kutsu issi appi! Kui ta nad „lennukisõidule“ tõstab, täitub tuba naeruga ja kogu see kuhjunud energia hajub.'),
('7338bae4-7d68-4f02-8b9f-7e3603f62bb9'::uuid,'«Сен жаман энесиң!» деген сөздөн жүрөктүн оорушу 💔','Сиз каалаган оюнчукту алып бербегениңиз үчүн алар сизге карап: ''Сен жамансың!'' дедиби? Жүрөгүңүздү оорутпаңыз. Алар азырынча сезимдерин туура сөздөр менен билдире алышпайт; алар чындыгында: ''Мен абдан ачууланып жатам жана көңүлүм калды'' деп айткысы келет. Көздөрүнө карап, анын сезимин жөн гана кабыл алганыңызды билдириңиз.','„Sa oled halb ema!“ südamevalu 💔','Kas nad vaatasid sulle otsa ja ütlesid: „Sa oled kuri!“, sest sa ei ostnud soovitud mänguasja? Ära lase sel oma südant murda. Nad ei oska veel oma tundeid õigete sõnadega väljendada; tegelikult mõtlevad nad: „Olen väga vihane ja pettunud.“ Võta silmside ja lihtsalt tunnusta nende tunnet.'),
('c4d16b0b-f2b1-40f5-8462-8e7c3419883e'::uuid,'«Мен түртөм!» деген базардагы күрөш 🛒','Балаңыз соода арабасын өзү түрткүсү келип, текчелерди сүзүп, баарынын көңүлүн буруп жатабы? Сиз кийлигишкенде ыйлайбы? Аны менен чогуу ''айдаганга'' уруксат бериңиз. Унутчаактык менен күрөшүү үчүн, колдонмодогу Соода тизмесин активдүү кармаңыз, ошондо мээңиз бир аз эс алат.','„Mina lükkan!“ võitlus poes 🛒','Laps tahab ise ostukäru lükata, tõmmates riiulitesse põrkamisega kõigi tähelepanu. Ja kui sa sekkud, siis nad nutavad! Lase neil seda koos sinuga „juhtida“. Unustamise vastu hoia äpis ostunimekiri aktiivsena, et su aju saaks veidi puhata.'),
('159b5a7f-d190-47d4-8cda-ba692f07b0d0'::uuid,'Үн өлчөгүчтүн жымжырттыгы 🤫','Алар акыры уктап калышты! Үйдө орногон тынчтык ушунчалык терең болгондуктан, кулагыңыз жаңырышы мүмкүн. Үн өлчөгүчтү иштетип, 0-10 децибелдик көрсөткүчтү караңыз, акылыңыздын акырындап эс алып жатканын визуалдуу түрдө сезиңиз.','Helimõõtja vaikus 🤫','Nad on lõpuks uinunud! Majja laskuv vaikus on nii sügav, et kõrvus võib kohiseda. Aktiveeri helimõõtja ja jälgi 0–10 detsibelli näitu, kogedes visuaalselt, kuidas su meel aeglaselt lõõgastub.'),
('ece2fe16-c57e-4a1f-a594-5e39da1118d6'::uuid,'Коомчулуктагы ишенимдүү достор 💬','Өзүңүздү абдан чарчаган сезип, эч кимге эч нерсе түшүндүргүңүз келбей жатабы? Жөн гана Anacan Коомчулугуна кирип, унчукпай байкоочу болуңуз. Башка энелердин окшош кыйынчылыктарын жана балдардын күлкүлүү окуяларын көрүү — эң жакшы дары, ал сизди жалгыз эмес экениңизди сездирет.','Kogukonna usaldusisikud 💬','Tunned end täiesti kurnatuna ega taha kellelegi midagi selgitada? Liitu lihtsalt Anacani kogukonnaga ja ole vaikne vaatleja. Teiste emade sarnaste raskuste ja naljakate lastekriiside nägemine on parim palsam, mis paneb sind tundma, et sa pole üksi.'),
('fabbf657-c431-4c98-ba31-613ca3dc8a47'::uuid,'Кичинекей ашпозчу 🧑‍🍳','Камыр жууруп жатканыңызда, алар сөзсүз түрдө отургучту сүйрөп келип, жардам бергиси келет. Ага өзүнчө пластик идиш берип, ун бериңиз. Ашкана булганышы мүмкүн, бирок анын олуттуу, көңүл бурган жүзү жана ''мен да жасай алам!'' деген сезими тазалоонун ар бир мүнөтүнө татыктуу.','Väike köögikokk 🧑‍🍳','Kui sa tainast rullid, tõmbab laps vältimatult tooli ligi ja tahab osaleda. Anna talle oma plastkauss jahu jaoks. Köök võib küll sassi minna, kuid see tõsine, keskendunud ilme ja tunne „mina oskan ka!“ on väärt iga koristusminutit.'),
('7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3'::uuid,'Тескери кийилген кийим менен сыймыктануу 🧦','Байпагынын согончогу бутунун үстүндө турат, бирок ал өзү кийгендиги үчүн сыймыктанып басып жүрөт. Кичине да болсо кийлигишпеңиз. Анын ''мен өзүм жасадым!'' деген сезими эстетикалык кемчиликсиздиктен же туура кийинүүдөн миллион эсе баалуу психологиялык пайдубал болуп саналат. Күнүн ушундай өткөрүшүнө жол бериңиз.','Uhke pahupidi riietus 🧦','Soki kand on jala peal, aga nad kõnnivad uhkelt ringi, sest panid ise jalga. Ära sekku isegi mitte natuke. Nende „mina sain hakkama!“ tunne on miljon korda väärtuslikum psühholoogiline vundament kui esteetiline täiuslikkus või korrektne riietus. Lase neil päeva nautida.'),
('ca2fd133-6b0b-4852-a4b2-b830a12f0bc0'::uuid,'Эне үчүн интернетсиз көз ирмемдер ☕','Балаңыз тынч отуруп пазл чогултуп жатат, 10 мүнөттөн бери тынчтык. Бул учурду үйдү тазалоого колдонгуңуз келет. Жок! Диванга жатыңыз. Кечке чейин ушул темпти кармап туруу үчүн батареяңызды кубаттап алышыңыз керек.','Võrguvabad hetked emmele ☕','Laps paneb vaikselt puslet ja juba 10 minutit on vaikus. Tahad seda hetke kasutada koristamiseks. Ei! Mine leba diivanil. Sinu aku vajab laadimist, et suudaksid seda tempot õhtuni hoida.'),
('e264b682-e7a9-4579-80a1-6e47fe7bccb3'::uuid,'Караңгылык менен достошуу 🐰','Уктагысы келбей, көлөкөлөрдөн корком деп жатабы? Бөлмөнү толук караңгылатып, колуңуз менен дубалга куш же иттин көлөкөсүн жасаңыз. Караңгылык менен достошууга жардам бериңиз жана коркунучту кызыктуу оюнга айландырып, анын фантазиясын өстүрүңүз.','Pimedusega sõbraks saamine 🐰','Ei taha magada ja ütleb, et kardab varje? Pimenda tuba täielikult ja tee kätega seinale linnu- või koeravarje. Aita neil pimedusega sõbraks saada ja rakenda nende kujutlusvõimet, muutes hirmu mänguks.'),
('03f9e2c0-9e7a-47b1-892e-0261f73bfa13'::uuid,'Жасалма интеллект жана тынчсыздануулар 🤖','Балаңыздын кээ бир тамгаларды туура айта албаганы сизди тынчсыздандырып жатабы? Коркунучтуу онлайн форумдарды жабыңыз! Anacan AI-дан 38 айлык курактагы сүйлөө нормалары жөнүндө сурап, илимий жана реалдуу жооп алыңыз.','AI ja ärevus 🤖','Kas lapse suutmatus mõningaid tähti õigesti hääldada teeb sind ärevaks? Sulge need hirmutavad foorumid! Küsi Anacan AI-lt kõnearengu normide kohta 38 kuu vanuses ja saa teaduslik ning realistlik vastus.'),
('8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9'::uuid,'«Сен бала бол, мен эне болоюн» оюну 👩‍👧','Ролдорду алмаштыруу оюну башталды! Алар сизге буйрук берип жатышат: ''Бул жакка кел, тамагыңды же, ыйлаба!'' Бул лидерлик тажрыйбаны кубаныч менен кабыл алыңыз жана унчукпай анын баласынын ролун аткарыңыз; бул эмпатияны өнүктүрүүнүн негизги жолу.','Mängime „sina oled laps, mina olen emme“ 👩‍👧','Rollimäng on alanud! Nad annavad sulle juhiseid: „Tule siia, söö oma toitu, ära nuta!“ Võta seda juhtimiskogemust suure rõõmuga ja mängi vaikselt nende lapse rolli; see on empaatia arendamise alustala.'),
('b97073a4-f745-41b1-953a-0e776ded1591'::uuid,'Жарыкты өчүрүп, уйкуга чакыруу 🌙','Кичинекейиңиздин тезирээк уктап кетишине жардам берүү үчүн, уктоо убактысына бир саат калганда бөлмөдөгү бардык ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин караңгы жана технологиясыз чөйрөдө эң натыйжалуу иштелип чыгат.','Tuled kustu, uni kutsub 🌙','Et aidata väikesel kiiremini uinuda, lülita tund enne magamaminekut toas välja kõik lisatuled ja tahvelarvutite ekraanid. Melatoniin toodab end kõige tõhusamalt pimedas ja tehnoloogiavabas keskkonnas.'),
('66da20be-59e4-4c6a-b44a-168bd86bf8c2'::uuid,'Күзгү алдындагы кылыктар 🎭','Эртең менен турганда эле күзгү алдына туруп, ыйлоо, күлүү жана таң калуу үчүн ар кандай мимикаларды жасап жатабы? Алар өз сезимдерин кантип билдирүүнү жана жүзү кандай өзгөрөрүн изилдеп жатышат. Бул укмуштуудай актёрдук чеберчиликти алыстан жылмайып карап туруңуз.','Peegli ees keksimine 🎭','Hommikul vara seisavad nad peegli ees, harjutades erinevaid nutu-, naeru- ja üllatusilmeid. Nad avastavad, kuidas tundeid väljendada ja kuidas nende nägu muutub. Jälgi seda säravat näitlemist eemalt, naeratus huulil.'),
('69d26c82-f68d-4fca-acec-f2cabf4901f8'::uuid,'Атанын сыйкырдуу кучагы 🫂','Колуңуз менен күнү бою көтөрүп жүргөнүңүздөн колдоруңуз ооруп жатат, бирок ал дагы эле кучакташууну каалайт. Атасын чакырыңыз! Анын кучагындагы ''учуу'' балаңыздын көңүл буруу муктаждыгын канааттандырат жана өзүңүздүн колдоруңузга абдан керектүү эс алууну берет.','Issi maagiline kallistus 🫂','Käed valutavad terve päeva kandmisest, kuid nad tahavad ikka kaisutada. Kutsu issi appi! „Lend“ tema süles rahuldab lapse tähelepanuvajaduse ja annab sinu kätele hädavajaliku puhkuse.'),
('b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6'::uuid,'Таштанды эмес, искусство 🎨','Балаңыз бөлмөнүн ортосуна кагаздын майда бөлүктөрүнөн жана кесилген жиптерден укмуштуудай ''сүрөт'' жаратып, аны ыргытууга жол бербей жатабы? Тазалыкка болгон көз карандылыгыңызды бир четке коюңуз! Алардын жараткан башаламандыгын сыйлаңыз; тазалоо эртеңкиге чейин күтө турат.','Mitte prügi, vaid kunst 🎨','Laps on loonud toa keskele imelise „kunstiteose“ paberitükkidest ja lõngajuppidest ega luba seda ära visata. Jäta oma korraarmastus kõrvale! Austa nende loodud kaost; koristamine võib oodata homseni.'),
('3613ef28-90fe-4c93-a13a-cc4ded2b5ad4'::uuid,'«Өзүм жасай алам!» фазасы 🛑','Өзү боосун байлагысы келип жатат, ал эми сиз үйдөн чыгууга 10 мүнөт кечигип жатасыз. Аларды шаштырбаңыз. Жабыркабаган өзүн-өзү сыйлоо сезими, бир аз бузулган графикке караганда анын өнүгүүсү үчүн алда канча маанилүү. Аракет кылышына жол бериңиз.','„Ma teen ise!“ faas 🛑','Nad tahavad ise paelu siduda ja sa oled juba 10 minutit hiljaks jäämas. Ära kiirusta neid. Vigastamata ego on nende arenguks palju olulisem kui veidi nihkes ajakava. Lase neil proovida.'),
('67736a86-09e4-4211-ade6-1d5d48e8a05f'::uuid,'Шыбырап айтылган жомоктор 🌙','Үнүңүз бүгүн ашыкча иштеди, өпкөңүз чарчады. Жарыкты өчүрүп, жанына жатып, күндүн окуялары жөнүндө акырын шыбырап айтып бериңиз. Шыбыроо алардын көңүлүн бурат жана акылын терең, тынч уйкуга акырындап даярдайт.','Sosistatud lood 🌙','Sinu hääl on täna kõvasti tööd teinud ja kopsud on väsinud. Kustuta tuled, heida nende kõrvale pikali ja sosista vaikselt päeva sündmustest. Sosistamine köidab nende tähelepanu ja valmistab nende meeled õrnalt ette sügavaks ning rahulikuks uneks.'),
('8d9fad31-a8cd-481f-953a-35d411108040'::uuid,'Кемчиликсиз эне жөнүндөгү мифтер 🛑','Социалдык тармактардагы балдар англис тилинде түстөрдү жана сандарды санап жатышат, бирок сиздин балаңыз кызыкпай жатабы? Салыштырууну азыр токтотуңуз! Ар бир баланын өнүгүү темпи уникалдуу жана ар башка. Алар өз темпинде эң сонун.','Täiusliku ema müüdid 🛑','Sotsiaalmeedias lapsed juba loevad inglise keeles värve ja numbreid, aga sinu laps pole huvitatud? Lõpeta kohe võrdlemine! Iga lapse arengutempo on ainulaadne ja erinev. Nad on täiuslikud omaenda kiirusel.'),
('4c7e076f-90de-4c2c-ae58-d9d897931fd4'::uuid,'Күндүзгү уйку бүттүбү? ⏱️','Кичинекейиңиздин түнкүсүн уктап кетиши үчүн бир сааттан ашык убакыт кетеби? Уйку графигиңизди текшериңиз. ''Үч жашар'' фазасында күндүзгү уйкуну толугу менен алып салып, уктоо убактысын эртелетүү керек болушу мүмкүн.','Kas uinakuaeg on läbi? ⏱️','Kas väikesel uinumine võtab õhtul üle tunni? Kontrolli uneaegu. „Kolmeaastase“ faasis võib olla aeg päevased uinakud täielikult kaotada ja magamaminekut varasemaks nihutada.'),
('b52dda4e-86c5-4200-973f-b7fbeb8869cc'::uuid,'Түгөнбөгөн «Эмне үчүн?» суроолору 🌪️','''Эмне үчүн балыктар баспайт?'', ''Күн кайда кетти?'' Эртең менен турганда эле алардын мээси саатына 100 суроо менен философия издейт. Чарчап турсаңыз да, аларга логикалык жана кыска жооп бериңиз. Алар ааламдын сырларын сиздин үнүңүздүн обонунан үйрөнүп жатышат.','Lõputud „miks?“ küsimused 🌪️','„Miks kalad ei kõnni?“, „Kuhu päike läks?“ Hommikul vara otsib nende aju filosoofiat 100 küsimusega tunnis. Isegi kui oled väsinud, anna neile loogilisi ja lühikesi vastuseid. Nad õpivad maailma saladusi sinu hääletooni kaudu.'),
('c583d30d-5142-4b40-bcb3-399830284928'::uuid,'Булганууга толук уруксат 🏖️','Балаңыз ылай жана кум менен ойногонду каалайбы? Кирдешине жол бериңиз! Бул сенсордук өнүгүү иш-чаралары үчүн эң оңой тазалануучу каражаттарды Сунушталган өнүмдөрдөн таап, эркин изилдөөсүнө мүмкүнчүлүк бериңиз.','Täielik luba määrduda 🏖️','Laps tahab mudas ja liivas mängida? Lase neil määrduda! Leia soovitatud toodete hulgast kõige kergemini puhastatavad vahendid nende sensoorsete tegevuste jaoks ja lase neil vabalt avastada.'),
('0446eb50-5fac-4056-ad65-76a95baf67f3'::uuid,'Көлөкөлөр менен күрөшүү 👻','Дубалдагы көлөкөсүнөн коркуп, артыңызга жашынып жатабы? Фантазиянын чеги жок. Бөлмөнү караңгылатып, колуңуз жана фонарик менен дубалга көлөкө театрын жасаңыз.','Varjudega võitlemine 👻','Kas nad kardavad seinal olevat varju ja peidavad end sinu taha? Kujutlusvõimel pole piire. Pimenda tuba ja tee taskulambi ning kätega seinale varjuteater.'),
('b090e002-92d1-408a-8249-476d9566115b'::uuid,'Уйкуга өтүүчү музыкалык коштоо 🎶','Кечинде түшүнүксүз ыйлаган учурларын жай классикалык музыка менен тынчтандырууга аракет кылыңыз. Көбүнчө, бул жөнөкөй, бирок натыйжалуу ыкма кереметтерди жаратып, бөлмөгө абсолюттук тынчтык жана бейпилдик алып келет.','Muusikaline üleminek unne 🎶','Proovi seletamatuid õhtuseid jonnituure rahustada õrna klassikalise muusikaga. Tihti toimib see lihtne, kuid tõhus nipp imeliselt, tuues tuppa absoluutse rahu ja vaikuse.'),
('7b3662bc-d715-468b-a32f-326c023ef66e'::uuid,'Оодарылуу боюнча чемпион! 🤸‍♂️','Алар чалкасынан ичине, ичинен чалкасына оодарылууга аракет кылып жатышабы? Аларды эч качан кароосуз калтырбаңыз жана бул кызыктуу, активдүү фазадан ырахат алыңыз!','Veeremise tšempion! 🤸‍♂️','Kas nad üritavad seljalt kõhule ja kõhult seljale keerata? Ära jäta neid kunagi voodis järelevalveta ja naudi seda põnevat, aktiivset faasi!'),
('ba177a78-642c-483b-9a15-4d4a68a758af'::uuid,'Денеңиздин үнү 🩸','Түшүнүксүз кыжырдануу жана чарчоого алдырбаңыз. «Этек кир календарыңызды» текшериңиз – организмиңиз сизге белги берип жаткан болушу мүмкүн. Өзүңүздү күнөөлөөнүн ордуна, магнийге бай тамак жеп, эс алыңыз.','Sinu keha appikarje 🩸','Ära alistu seletamatule ärrituvusele ja väsimusele. Kontrolli oma tsüklikalendrit – su keha võib saata sulle signaale. Selle asemel, et end süüdistada, lõõgastu magneesiumirikka suupistega.'),
('dd84435f-c5e3-4339-9062-61f9c8648898'::uuid,'Жөнөкөй көрсөтмөлөрдү аткаруу 🧸','Сиз суранганда алар чын эле бут кийимин алып келеби? Алардын сөз байлыгы жана түшүнүү жөндөмү өсүп жатат! Алар менен көбүрөөк ойноңуз.','Lihtsate juhiste järgimine 🧸','Kas nad lähevadki ise kingi tooma, kui palud? Nende sõnavara ja arusaamisvõime on haripunktis! Kaasa neid rohkematesse mängudesse.'),
('1a2422fa-5d4e-4bbc-9f26-d69dd838496d'::uuid,'Сөздөрдү ойнотуп айтуу 🗣️','Алар «Машина» дебей, «Ма-шин» деп айтып, сиздин күлүүңүздү күтүп жатышабы? Алар тамашакөйлүгүн ачып жатышат! Кошо күлүңүз, бирок мээси туура жаттап калышы үчүн, ар дайым туура айтылышын жумшак белгилеп коюуну унутпаңыз.','Mänguline sõnadega keerutamine 🗣️','Kas nad nõuavad visalt, et ütleksid „Auto-mobiil“ asemel „Auto“ ja ootavad, et sa naeraksid? Nad avastavad oma huumorimeelt! Naera kaasa, kuid ära unusta iga kord õrnalt rõhutada õiget hääldust, et nende aju saaks õige vormi salvestada.'),
('21b5ead3-32a1-4d0e-96a9-1e38bf19fcec'::uuid,'Энеке, өзүңүздү азыктандырыңыз 🥗','Аларды тойгузуу үчүн жумуртканы 4 түрдүү ыкма менен бышырдыңыз, бирок *өзүңүз* эмне жедиңиз? Өзүңүздү «Дени сак рецепттер» бөлүмүнөн 5 мүнөттө даярдалуучу, темирге жана кальцийге бай өзгөчө тамак менен сыйлаңыз жана энергияңызды сактап калыңыз.','Emme, toida ennast 🥗','Valmistasid neile mune neljal erineval moel, aga mida sõid *sina*? Premeeri end meie tervislike retseptide hulgast ühe erilise, raua- ja kaltsiumirikka roaga, mille valmistamine võtab vaid 5 minutit, ja hoia oma energiat.'),
('cc6b3853-5963-47b7-b4f5-310bfd1919c2'::uuid,'Уйкуну кечиктирүү амалдары ⏱️','Уктоо убактысы жакындаганда алар күтүлбөгөн жерден суусап, дааратканага баргысы келип же бөлмөдөгү бардык нерсе менен коштошо баштайбы? Таймерди коюңуз. «Таймер чырылдаганда баары укташат» деген эрежени киргизип, бул чексиз коштошууларды сабырдуулук менен жеңип өтүңүз.','Uinumist edasilükkav taktika ⏱️','Kui uneaeg läheneb, kas nad muutuvad järsku januseks, vajavad potile minekut või hakkavad kõigega toas hüvasti jätma? Sea taimer. Kehtesta reegel „kui taimer heliseb, siis kõik magavad“, et nende lõputute hüvastijättudega rahulikult ja kannatlikult toime tulla.'),
('629ea652-62bd-4947-96b6-0e7f4cabb751'::uuid,'Оюнчуктарды чогултуу 🧸','Алар бардык оюнчук аюуларын жана унааларын тизип коюп, манжасы менен аларды бир нерсеге олуттуу түрдө үйрөтүп жатышабы? Бул лидерлик жана көңүл буруу жөндөмүнүн өнүгүүсү. Бөлмөнүн четинде унчукпай туруп, алардын фантазиялык чогулушун тоскоолдук кылбай байкаңыз.','Mänguasjade kokkupanek 🧸','Kas nad rivistavad kõik oma kaisukarud ja autod üles ning selgitavad neile siis väga tõsiselt midagi näpuga viidates? Nii arenevad juhtimisoskus ja keskendumisvõime. Seisa vaikselt toa nurgas ja jälgi nende kujuteldavat koosolekut neid segamata.'),
('8fdbd74e-0b03-4420-a816-6a0ea6ecdb73'::uuid,'Атанын күлкүлүү үндөрү 🤡','Сиздин адаттагы ыкмаларыңыз иштебей калганда, атасынын күлкүлүү жаныбарлардын үндөрүн чыгарганы жана кызыктай бет кубулуштары дароо жардамга келет. Кечки ыйлаган учурларда, «топту ага өткөрүп бериңиз» да, четте туруп алардын шаңдуу күлкүсүнөн ырахат алыңыз.','Issi naljakad hääled 🤡','Kui su tavalised nipid enam ei tööta, võivad issi naljakad loomahelid ja tobedad näod päeva hetkega päästa. Õhtuste jonnihoogude ajal „anna pall“ talle üle ja naudi rõõmsat naeru kõrvaltvaatajana.'),
('b32c30b6-11a0-4afc-aed3-bdfb0cc56622'::uuid,'Уйку убактысына каршылык 🥱','Алар уктагысы келбей ыйлап жатышабы? Мажбурлабаңыз. Бөлмөдөгү жарыкты өчүрүп, «Тынч окуу убактысын» жарыялаңыз. Бул экөөңүздөрдү тең эс алдырган жана тынчтык алып келген жаңы адат болуп калат.','Uinakumäss 🥱','Nad ei taha magama minna ja nutavad? Ära sunni. Hämarusta toas tuled ja kuuluta välja „vaikne lugemisaeg“, et luua uus rutiin, mis lõõgastab teid mõlemaid ja toob rahu nii sulle kui ka su pisikesele.'),
('07209316-984c-477d-a3c0-ff2c7202c5fa'::uuid,'Мектепке чейинки ой жүгүртүүлөр 🏫','Балаңызга көбүрөөк социалдашуу керек деп ойлойсузбу? Бала бакчага бара турган убакыт келдиби? Anacan коомчулугуна кошулуп, башка энелердин бала бакчага көнүү боюнча реалдуу тажрыйбаларын окуп, чечим кабыл алууну жеңилдетиңиз.','Eelkooliealise mõtisklused 🏫','Kas tunned, et su laps vajab rohkem sotsialiseerumist? Kas on õige aeg lasteaiaks? Tee otsustamine lihtsamaks, liitudes Anacani kogukonnaga ja lugedes teiste emade tõelisi kohanemiskogemusi.'),
('3f7992d5-c092-46f7-84f8-f10e51f36593'::uuid,'Күтүлбөгөн жерден ыйлоо 💥','Ойноп жатып күтүлбөгөн жерден ачууланып, оюнчуктарын ыргытып жибериштиби? Алар азырынча эмоцияларын башкара алышпайт. Урушуунун ордуна, боорукердик көрсөтүп: «Сенин ачууланып жатканыңды түшүнүп турам. Кел, экөөбүз терең дем алалы», – деп байланыш түзүңүз.','Äkiline jonnihoog 💥','Kas nad muutusid mänguhoos järsku vihaseks ja viskasid mänguasju? Nad ei oska veel oma emotsioone reguleerida. Selle asemel, et karjuda, näita üles empaatiat ja loo side, öeldes: „Ma näen, et oled vihane. Hingame koos sügavalt sisse.“'),
('a376f906-e66c-4618-827e-79f3b75ebd16'::uuid,'Караңгы бөлмө тынчсызданууну жаратабы? 🌙','Бөлмөнүн бир бурчуна кичинекей, жылуу жарык берүүчү түнкү чырак коюңуз. Ал эми бөлмөнүн калган бөлүгү терең жана тынч уйку үчүн караңгы болушу керек.','Kas pime magamistuba tekitab ärevust? 🌙','Aseta toa ühte nurka väike soojatooniline öölamp. Ülejäänud tuba peaks aga jääma täiesti pimedaks, et soodustada sügavat ja kosutavat und.'),
('171bedf4-3516-44a5-9404-c089661d5bbd'::uuid,'Жансыз буюмдар менен сүйлөшүү 🗣️','Паркта таш менен сүйлөшүп же үйдө отургучту олуттуу түрдө урушуп жатышабы? Символикалык оюн аркылуу алар дүйнөнү таанып жатышат. Бул өзгөчө учурларды алардын өнүгүү күндөлүгүнө жазып коюуну унутпаңыз!','Rääkimine elutute esemetega 🗣️','Kas nad räägivad pargis kiviga või sõimavad kodus täie tõsidusega tooli? Sümbolmängu kaudu töötlevad nad ümbritsevat maailma. Pane need erilised hetked kindlasti oma arengupäevikusse kirja!'),
('a74f3aea-565f-455f-bdbe-9ee44f6c7e35'::uuid,'Жылуу суунун сыйкыры 🛀','Кээде эч нерсе жардам бербей, баарына ыйлай беришет. Аларды көбүктүү жылуу сууга түшүрүңүз. Суунун тынчтандыруучу жана чыңалууну басуучу күчү бөлмөгө жана алардын нерв системасына дароо тынчтык алып келет.','Sooja vee võlu 🛀','Mõnikord ei tundu miski töötavat ja nad nutavad kõige pärast. Pane nad sooja vanni, kuhu on lisatud veidi vannivahtu. Vee rahustav ja pinget maandav jõud toob tuppa ja nende närvisüsteemi hetkega rahu.'),
('b4c6b7ac-81bd-476f-9816-9e8c14627206'::uuid,'Аба ырайы тууралуу маалымат ⛅','Сыртка чыгууну пландап жатканда терезеден карап алданбаңыз. «Аба ырайы жана кийим» жардамчысын колдонуп, сырттагы шамалдын жана температуранын чыныгы абалына жараша эң ылайыктуу кийимди тандаңыз. Ыңгайлуу жана даяр болуп чыгып, балаңызга таза абада энергиясын сарптоого мүмкүнчүлүк бериңиз.','Ilmateade ⛅','Ära lase aknast paistval vaatel end väljasõitu planeerides petta. Kasuta ilma- ja riietusabilist, et valida täiuslik riietus vastavalt tegelikule tuulele ja välistemperatuurile. Astu uksest välja mugavalt ja ettevalmistatult ning lase oma pisikesel õues energiat kulutada.'),
('2fc82c8d-f425-4306-866a-3f621177b592'::uuid,'Мультфильм сынчысы 📺','Кичинекейиңиз көргөн мультфильмин өзүнүн өзгөчө грамматикасы жана олуттуу ишеними менен ким кайда барганын айтып берип жатабы? Чындап таң калгандай болуп, кунт коюп угуңуз. Алар өздөрүн дүйнөдөгү эң акылдуу адамдай сезишсин.','Multikakriitik 📺','Su pisike jutustab vaadatud multikast, selgitades oma unikaalse grammatika ja tõsise veendumusega, kes kuhu läks. Kuula tähelepanelikult, justkui oleksid siiralt üllatunud. Lase neil tunda end maailma kõige targema inimesena.'),
('63daef22-cfd1-421f-8f7d-267873d17f9e'::uuid,'Эч ким идеалдуу эмес 🛑','Бүгүн эч нерсе пландагыдай болбой калдыбы? Өзүңүздү күнөөлөбөңүз. Сиз социалдык тармактардагы жасалма сүрөттөр эмес, чыныгы энесиз. Балаңызга болгону сиздин жылмаюуңуз жана кучагыңыз керек.','Keegi pole täiuslik 🛑','Kas täna ei läinud miski plaanipäraselt? Ära süüdista end. Oled päris ema, mitte sotsiaalmeedia filtreeritud illusioon. Su laps vajab lihtsalt su naeratust ja kallistust.'),
('e3cb9a40-b6ca-4e32-b4da-ab6d4899625b'::uuid,'Түнкү коркунучтардын сырын чечүү 😭','Түн ортосунда көзү жумулуу абалда ыйлап ойгонуштубу? Эгер бул түнкү коркунуч болсо, аларды ойготууга аракет кылбаңыз. Жөн гана жанында болуп, унчукпай сооротуңуз.','Öiste hirmuhoogude lahtimõtestamine 😭','Nad on keset ööd üles ärganud, nutavad kinniste silmadega ega tundu kedagi märkavat. Kui tegemist on öise hirmuhoo ehk ööterroriga, ära proovi neid äratada. Ole lihtsalt nende jaoks olemas ja paku vaikset, rahustavat tuge.'),
('10d94f4d-5823-4afc-963c-ff0397bf1a29'::uuid,'Жөн гана кучактоо 🫂','Бүгүн оюн, китеп же жомоктун кереги жок. Жөн гана аларды кучагыңызга бекем кысып, жытын жыттап, караңгыда алардын канчалык баалуу экенин шыбырап айтыңыз.','Lihtsalt üks kallistus 🫂','Täna pole vaja mänge, raamatuid ega lugusid. Lihtsalt hoia neid tihedalt vastu rinda, hinga sisse nende magusat lõhna ja sosista pimeduses, kui hindamatud nad on.'),
('3860d960-f463-4c1e-873a-4917b9b7c101'::uuid,'Кооптуу сөздөр 🤐','Каяктандыр угуп калган жаман сөздү кайталап, сиздин реакцияңызды күтүп жылмайып жатышабы? Сиздин эң жакшы куралыңыз – эч кандай реакция кылбоо. Күлбөңүз, ачууланбаңыз, жөн гана көңүл бурбаңыз. Алар ал сөздү бат эле унутуп калышат.','Ohtlikud sõnad 🤐','Kas nad kordasid just kuskilt kuuldud inetut sõna, naeratades kavalalt ja oodates su reaktsiooni? Sinu parim relv on mitte reageerida. Ära naera, ära vihasta, lihtsalt ignoreeri. Nad unustavad selle sõna peagi.'),
('fbd7d1b9-4e13-463d-80fa-fbbd34869d9e'::uuid,'Үйдөгү башаламандыкка уруксат 🌪️','Күн сайын бир эле оюнчуктарды жыйноодон тажадыңызбы? Бүгүн жыйнабаңыз! Үйүңүз музей эмес, бул жашоо кайнаган жай. Башаламандыкка көңүл бурбай, балаңыздын эркин изилдөөсүнөн ырахат алыңыз жана жөн гана эс алыңыз.','Luba sassis kodule 🌪️','Oled väsinud iga päev samu mänguasju koristamast? Ära täna vaeva näe! Su kodu pole muuseum; see on elav ruum, kus elu toimub. Lase segadusel olla, keskendu lapse vaba avastamisrõõmule ja lihtsalt lõõgastu.'),
('267500b1-a84b-4046-a247-9d2097325550'::uuid,'Төмөн караңызчы, алар эмнени изилдеп жатышат? 👣','Алар килемди же жердеги таштарды сезип, жылаңайлак басканды жакшы көрүшөт. Тамандын нервдерин стимулдаштыруу алардын тең салмактуулугу жана кыймыл-аракет жөндөмү үчүн өтө маанилүү. Байпаксыз жүрө беришсин!','Vaata alla, mida nad avastavad? 👣','Neile meeldib paljajalu käia, tundes vaipa või kive põranda all. Taldade närvilõpmete stimuleerimine on nende tasakaalu ja motoorika jaoks ülioluline. Lase neil sokkideta ringi joosta!'),
('2b6e6b05-f741-49ca-84e3-fa8deb8b2661'::uuid,'Жубайлар үчүн эс алуу 🥂','Кичинекейиңиз уктады! Эми үй жумуштарын четке коюңуз. Кеминде 20 мүнөт өнөктөшүңүз менен балдар же акча тууралуу эмес, башка нерселер жөнүндө сүйлөшүңүз. Эсиңизде болсун, сиздер да жубайсыздар!','Paaride puhkehetk 🥂','Pisike magab! Nüüd pane kodutööd kõrvale. Veeda vähemalt 20 minutit oma partneriga rääkides millestki muust peale laste või rahaasjade. Pea meeles, te olete ka paar!'),
('9d8da9d6-f615-4275-a01c-20687a161090'::uuid,'Азык-түлүк дүкөнүндөгү куткаруучу 🛒','Дүкөнгө баратканда эң керектүү нерсени унутуп кала бересизби? Соода тизмеңиз тиркемеде сизди күтүп жатат. Керектүү нерселерди жазып коюңуз, өнөктөшүңүз жумуштан кайтып келе жатканда аларды алып келип, мээңизди ашыкча түйшүктөн сактасын!','Päästja toidupoes 🛒','Kas unustad poodi minnes alati kõige tähtsama asja? Sinu ostunimekiri ootab sind äpis. Pane kirja, mida vajad, ja lase partneril need täpselt töölt tulles kaasa haarata – säästa oma aju stressist!'),
('2b451101-7b49-4ea1-a25f-f07ea36f7e85'::uuid,'Нааразычылыктарыңызды күндөлүккө жазыңыз 📝','Кимдир бирөө сизге: «Үйдө эле отурасың, эмнеден чарчайсың?» дедиби? Дароо «Маанай күндөлүгүңүздү» ачып, бардык нааразычылыгыңызды экранга төгүңүз. Чыныгы сезимдериңизди билдирүү – жасалма жылмаюудан алда канча жакшы терапия.','Kirjuta oma frustratsioon üles 📝','Kas keegi ütles sulle: „Oled ju kodus, millest sa küll väsinud oled?“ Ava kohe oma meeleolupäevik ja lase kõigil frustratsioonil ekraanile voolata. Oma tõeliste tunnete väljendamine on palju parem teraapia kui sundnaeratamine.'),
('5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5'::uuid,'Мага түшүндүрүп берүүгө уруксат этиңиз! ☝️','Алар сиз мурунтан эле билген нерсени абдан олуттуу жана акылдуу көрүнүш менен түшүндүрүүгө келиштиби? Алар өз билимдерин сынап жатышат! Күлкүңүздү тыюу үчүн тилиңизди тиштеп алсаңыз да, абдан олуттуу угуп, алардын ойлорун колдоп коюңуз.','Luba mul selgitada! ☝️','Nad tulevad sulle selgitama midagi, mida sa juba tead, väga tõsise ja intelligentse ilmega. Nad panevad oma teadmisi proovile! Isegi kui pead keelt hammustama, et mitte naerma puhkeda, kuula suure tõsidusega ja tunnusta nende mõtteid.'),
('62a5480b-e62d-48dc-a56f-7c512e104949'::uuid,'Тынчтыктын санариптик өлчөмү 🤫','Алар акыры укташты! Үйдөгү тынчтыкка ишене албай жатасызбы? Үн өлчөгүчүңүздү иштетип, экрандагы 0-10 децибелдик көрсөткүчтөрдү карап, акылыңыздын жайланышын сезиңиз.','Vaikuse digitaalne mõõdupuu 🤫','Nad jäid lõpuks magama! Sa ei suuda uskuda majja laskunud vaikust. Aktiveeri helimõõtja ja jälgi ekraanil 0–10 detsibelliseid näitusid, tundes, kuidas su mõtted aeglaselt rahunevad.'),
('523ef85e-fa2f-49a1-b3f9-34f2d35d22a1'::uuid,'Аба ырайын текшерүү ⛅','Сырттагы аба ырайы өзгөрүлмөлүүбү? «Аба ырайы жана кийим» куралы аркылуу терезеден көрүнбөгөн шамалдын ылдамдыгын дароо билип, эң ылайыктуу кийимдерди тандап алыңыз.','Ilmateade ⛅','Kas ilm väljas on veidi ettearvamatu? Lase ilma- ja riietustööriistal hetkega öelda tuulekiirus, mida sa aknast ei näe, ja soovitada täiuslikku riietuskomplekti.'),
('0aded6bb-b0fa-4cac-b297-4311bcd7f798'::uuid,'Баарын өзүңүз жасоого милдеттүү эмессиз 🌸','Сизге сүйүү менен караган балаңыз үчүн сиз бул дүйнөдөгү эң идеалдуу адамсыз.','Sa ei pea kõike ise tegema 🌸','Sinu beebi jaoks, kelle armastavad silmad on naelutatud sinu külge, oled sa maailma kõige täiuslikum inimene.'),
('5b3dc48b-525e-45b8-ba47-dd1abb851741'::uuid,'Өз алдынча бут кийимин чечүү 👟','Кийинүү күрөшкө айланып кеттиби? Алар байпактарын жана бут кийимдерин өздөрү чечип жатышат. Алардын майда моторикасынын өнүгүүсүнө суктаныңыз!','Oma kingade jalast võtmine 👟','Kas riietumisest on saanud maadlusmatš? Nad tõmbavad ise sokke ja kingi jalast. Imetle nende arenevat peenmotoorikat!'),
('cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8'::uuid,'Атанын колдоосу 🫂','Түнкүсүн ойгонгондо кезектешип туруңуз – бир жолу сиз, бир жолу өнөктөшүңүз. Жүктү команда катары толугу менен бөлүшүңүз.','Isa toetus 🫂','Öiste ärkamiste puhul tehke vahetust – üks kord lähed sina, teine kord partner. Jagage koormus meeskonnana täielikult ära.'),
('3522ca83-324c-49f9-ba7a-ffdc8c379ba2'::uuid,'Уйкуну бузган даараткана 🚽','Уктаар алдында эле: «Дааратканага барышым керек!» деп калыштыбы? Сиз алып барасыз, бирок эч нерсе болбойт. Бул уктоону кечеңдетүүнүн эң мыкты ыкмасы. Урушпаңыз. Чек араны так коюңуз: «Бул акыркы жолу, андан кийин дароо төшөккө кайтабыз».','Und segav tualetipaus 🚽','Just siis, kui nad on uinumas, ütlevad nad järsku: „Ma pean potile minema!“ Viid nad, aga midagi ei juhtu. See on magamamineku edasilükkamise kunsti ülim taktika. Ära karju. Sea selgelt piir: „See on viimane kord ja siis läheme kohe tagasi voodisse“.'),
('676880bc-91f2-426e-9b15-e2ce61b68fc4'::uuid,'Төшөктөгү изилдөөчү 🛏️','Түндү өз керебетинде баштап, таңга маал сиздин керебетиңизде буттарын бетиңизге коюп жатып калыштыбы? Бул «аймакты басып алууну» жылмаюу менен тосуп алыңыз. Сиздин жылуу жытыңыз алар үчүн эң чоң сооронуч.','Voodiuurija 🛏️','Nad alustavad ööd oma voodis, kuid ärkavad sinu omas, laiutades täielikult ja jalad su näos. Tervita seda territoriaalset vallutust naeratusega. Sinu soe lõhn on nende ülim turvatsoon.'),
('bf74dbb7-0eae-47bc-acea-2beeb831e679'::uuid,'Кутунун сыйкыры 📦','Кичинекейиңиз сиз сатып алган кымбат, ызы-чуу оюнчукту ыргытып салып, бир сааттан бери картон куту менен ойноп жатабы? Баланын мээси алдын ала программаланган сценарийлерге эмес, фантазияны ойготкон ачык нерселерге муктаж. Ал картон куту алар үчүн космостук кеме – алардын ойношуна жол бериңиз!','Kasti võlu 📦','Su pisike viskas kõrvale selle kalli ja lärmaka mänguasja, mille ostsid, ja on tund aega mänginud selle pappkastiga? Lapse aju areneb avatud mänguasjadest, mis sütitavad kujutlusvõimet, mitte etteprogrammeeritud stsenaariumidest. See pappkast on nende jaoks kosmoselaev – lase neil olla!'),
('42b797ef-b169-4515-ad62-c08b78bfdaca'::uuid,'Кышкысын жайкы козголоң ❄️','Сыртта шамал болуп жатса да, алар жайкы шорты кийем деп туруп алыштыбы? Түшүндүрүүгө убакыт кетирбеңиз. Аба ырайы жана кийим тандоо куралын ачып, экрандан жылуу кийинген баланын сүрөтчөсүн көрсөтүңүз. «Карачы, телефон деле бүгүн шым кийиш керек деп жатат!» деген амал кереметтей иштейт.','Suvine mäss talvel ❄️','Õues puhub tuul, aga nemad nõuavad suviseid lühikesi pükse. Selgitamine on ajaraisk. Ava ilma- ja riietustööriist ning näita neile ekraanilt soojalt riides lapse ikooni. Nipp „Vaata, isegi telefon ütleb, et täna peame püksid panema!” töötab imehästi.'),
('74bf7168-d7dc-468c-87a3-562a3bef9f2a'::uuid,'Элестетүүдөгү тиштегендер 🍏','Колунда эч нерсе жок болсо да, сизге келип, элестетилген алманы сунуштап: «Мына, тиштеп ал!» дешет. Ролдук оюндар инсандын өнүгүүсү үчүн өтө маанилүү. Ошол алманы чоң кылып тиштегенсип, анын дүйнөдөгү эң даамдуу алма экенин шыктануу менен тастыктап коюңуз!','Kujuteldavad ampsud 🍏','Neil pole midagi käes, aga nad tulevad su juurde, pakuvad kujuteldavat õuna ja ütlevad: „Palun, hammusta!” Rollimängud on isiksuse arenguks üliolulised. Tee sellest õunast üks suur, kujuteldav amps ja kinnita entusiastlikult, et see on maailma kõige maitsvam õun!'),
('d3d1367f-aa40-489c-9f91-b803403dff09'::uuid,'Терезедеги желмогуз 👻','Сырттагы желбиреген дарактын көлөкөсү бөлмөгө түшүп, алар коркуп, артыңызга жашынышат. Бөлмөнүн жарыгын күйгүзбөңүз. Тескерисинче, фонарикти алып, көлөкөнү көздөй жарык чачып: «Карачы, бул жөн гана дарактын бийи!» деп айтыңыз – коркунучту сыйкырдуу көз ирмемге айлантыңыз.','Koll aknal 👻','Õues kõikuva puu vari langeb tuppa ja nad ehmuvad, otsides sinu selja taga varju. Ära pane toas tuld põlema. Selle asemel haara taskulamp, valgusta varju ja ütle: „Vaata, see on lihtsalt puu, mis tantsib!” – muutes hirmu maagiliseks hetkeks.'),
('2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6'::uuid,'«Мага кара!» марафону 👀','Ойгонгондон кийин эле 40 жолу «Апа, мага карачы!» дештиби? Алар секирип, айланып, сиздин көңүлүңүздү каалап жатышат. Телефонуңузду четке коюп, 3 мүнөт бою аларга толук көңүл буруп, алардын укмуштуудай экенин айтыңыз. Бул бөлүнбөгөн көңүл буруу аларды канааттандырууга жетиштүү болот.','''Vaata mind!'' maraton 👀','Kas nad ütlesid kohe pärast ärkamist 40 korda „Emme, vaata mind!”? Nad hüppavad, keerlevad ja janunevad sinu heakskiidu järele. Pane telefon käest, vaata neid vaid 3 minutit täie tähelepanuga ja ütle, et nad on imelised. Sellest jagamatust tähelepanust piisab, et neid rahuldada.'),
('4e536027-0b7a-4ac3-acef-a7ba874bd609'::uuid,'Эненин жалкоо болууга укугу 🍕','Бүгүн баарына кыйкыргыңыз келип жатабы? Үй чачылып жатабы? Тазалоону унутуңуз; ашканага да кирбеңиз. Пицца же жөнөкөй бир нерсе заказ кылыңыз. Кемчиликсиз эне болуу иллюзиясынан баш тартыңыз – сиздин психологиялык абалыңыз үй тамагынан алда канча баалуу.','Ema õigus laiskusele 🍕','Kas tunned, et tahaksid täna kõige peale karjuda? Kas kodu on täielikus segaduses? Unusta koristamine; ära isegi astu kööki. Telli pitsat või midagi lihtsat. Lase lahti täiusliku ema illusioonist – sinu vaimne heaolu on palju väärtuslikum kui ükskõik milline kodutoit.'),
('c57f5d91-caec-47eb-964d-abcee011e0e2'::uuid,'Жубайлардын экран алдындагы уйкусу 📺','Бала уктады! Акыры өнөктөшүңүз менен кино көрүү үчүн диванга отурдуңуз, бирок 10 мүнөттөн кийин экөөңүз тең уктап калдыңыз. Бул сиздин чындыгыңыз. Бири-бирине жөлөнүп уктап калган ал чарчаңкы, бирок таттуу көрүнүш – бул өзү эле сүйүү.','Paaride ekraanikooma 📺','Laps magab! Istute lõpuks partneriga diivanile filmi vaatama, et vaid 10 minutit hiljem mõlemad magama jääda. See ongi sinu reaalsus. See väsinud, kuid armas stseen, kus te üksteise najal magama jääte, ongi armastus.'),
('658bd674-cc84-4d51-8a7e-822b9255b9d7'::uuid,'Жаңы жомокторду ачуу 📖','Бүгүн кечти өзгөчө кылалы! «Акылдуу жомоктор» бөлүмүндө суу астында сүзүп жүргөн суу периси жөнүндө жомок түзүп, бөлмөнү сыйкырга толтуруңуз.','Uute lugude avastamine 📖','Teeme tänase õhtu eriti eriliseks! Loo nutikates muinasjuttudes (Smart Tales) lugu veealust avastavast merineitsist ja täida tuba lummava maagiaga.'),
('2333a8bc-122b-4087-9603-3c895b2daf77'::uuid,'Тандап жегендердин логикасыздыгы 🥦','Кечээ кубанып жеген шорпосун бүгүн такыр карабай жатышабы? Биздин пайдалуу рецепттерди карап чыгып, түстүү макарон соустарына жашылча пюресин кантип жашырууну үйрөнүңүз. Кулинардык камуфляж өнөрүн өздөштүрүңүз!','Pirtsakate sööjate ebaloogilisus 🥦','Suppi, mida nad eile rõõmuga sõid, ei taha nad täna puutudagi? Tutvu meie tervislike retseptidega ja avasta, kuidas nutikalt püreestatud köögivilju värviliste pastakastmete sisse peita. Õpi selgeks kulinaarse kamuflaaži kunst!'),
('d14775e1-8a41-4689-87c3-351bcaa01c87'::uuid,'Ата менен ойноо убактысы 👨‍👧','Сабырыңыз түгөнүп баратабы? Эшикти жаап, кичинекей бала менен алек болууну атасына өткөрүп бериңиз. Бүгүн кечинде үй оюнунун башчысы ал болсун.','Issi mänguaeg 👨‍👧','Kannatus hakkab katkema? Sulge uks ja lase issil pisikesega tegeleda. Las tema olla täna õhtul koduse mängunurga boss.'),
('5e903417-88bd-42b5-bb8c-507e12e432bf'::uuid,'Суу астындагы падышалык 🛀','Чоюнуу убактысы эми жөн гана тазалануу эмес, бул суу астындагы кеме миссиясы! Сууну каалаганча чачыратыңыз. Суунун сыйкырдуу таасири алардын күн бою топтогон терс энергиясын жууп, агын сууга кошуп кетет.','Veealune kuningriik 🛀','Vanniskäik pole enam ammu lihtsalt pesemine, vaid allveelaeva missioon! Las vesi pritsib igale poole. Vee magnetiline toime peseb maha kogu selle kangekaelse negatiivse energia, mille nad päeva jooksul on kogunud, ja saadab selle kanalisatsiooni.'),
('185309c1-aba3-48ec-9411-535c92af4024'::uuid,'Санариптик тынчтык терапиясы 🤫','Бөлмөдө акыры абсолюттук тынчтык орноду. Идиш жуугучту бошотууга шашпаңыз. Үн өлчөгүчүңүздү иштетип, экрандагы сандардын 0 децибелге чейин түшкөнүн көрүп, чарчаган акылыңыздын тазаланып, сергигенин сезиңиз.','Digitaalse vaikuse teraapia 🤫','Tuppa on lõpuks saabunud täielik vaikus. Ära kiirusta nõudepesumasinat tühjendama. Aktiveeri helimõõtja ja vaata, kuidas numbrid ekraanil 0 detsibellini langevad, tundes, kuidas su väsinud meel puhastub ja värskeneb.'),
('4794fa88-36bd-4251-a4ea-871854d0d5ac'::uuid,'Сиздин кичинекей таштанды сүрөтчүңүз ✂️','Таза кагазды миңдеген майда бөлүктөргө айрып, бөлмөгө чачып жатышабы? Алардын майда моторикасы өнүгүп жатат! Капа болуп, шыпыргыга кол сунбаңыз. Тескерисинче, ал кагаз үзүндүлөрүн кутуга чогултуп, «кар жаады» оюнун ойноңуз.','Sinu väike prügikunstnik ✂️','Kas nad rebivad puhta paberi tuhandeks pisikeseks tükiks ja pillutavad need üle toa laiali? Nende peenmotoorika areneb! Ära mine närvi ja haara luuda. Selle asemel korja need väikesed tükid karpi ja mängige lumesajumängu.'),
('bcbae78a-e00a-4482-8778-25c54ab9a376'::uuid,'Күзгүдөгү атаандаш 🪞','Алар күзгү алдында туруп, кабагын түйүп, өздөрүнө ачууланган же кызыктай бет маскаларын жасап жатышат. Алар эмоциялардын бетте кантип чагылдырыларын сынап жатышат. Четте туруп, бул кичинекей театр актерунун машыгуусун кызыгуу менен байкаңыз.','Rivaal peeglis 🪞','Nad seisavad peegli ees, kortsutavad kulmu ja teevad endale vihaseid või imelikke nägusid. Nad katsetavad, kuidas emotsioonid näol välja näevad. Jälgi vaikselt kõrvalt seda miniatuurset näitlejat ja tema harjutusi huviga.'),
('9ecbc8da-836b-48fc-a294-6aaa4bafb6f3'::uuid,'Жалгыздыкка болгон сагыныч 🚪','Күнү бою сизден асылып, чырмалып жүргөн баладан чарчадыңызбы? Акыры дааратканага кирип, эшикти жаап, өзүңүзгө 5 мүнөт убакыт таптыңыз. «Маанай күндөлүгүн» дароо ачып, ичиңиздеги толуп турган сезимдерди экранга төгүп, бир аз тынчтык табыңыз.','Igatsus omaette olemise järele 🚪','Kas oled kurnatud lapsest, kes on terve päeva su otsas roninud ja rippunud? Läksid lõpuks vannituppa, panid ukse kinni ja said 5 minutit omaette olla. Ava kohe oma meeleolupäevik ja lase sel ülekoormustundel ekraanile voolata, leides hetke rahu.'),
('acb8e717-26b4-427c-9df9-4c6aeb16734c'::uuid,'Биздин окуянын режиссёру 🪄','Үнүңүз бүгүн чарчады. «Акылдуу жомокторду» ачыңыз. Балаңызга: «Бүгүн сен каармансың, ал эми фондо жамгыр жаап жатат» деп айтып, алардын тез уктап кетишине жардам бере турган өзгөчө, тынчтандыруучу жана жекелештирилген үн чөйрөсүн түзүңүз.','Meie loo lavastaja 🪄','Sinu hääl on täna õhtul väsinud. Ava „Nutikad lood”. Ütle lapsele: „Täna oled sina kangelane ja taustal sajab vihma,” luues erilise, rahustava ja isikupärase helikeskkonna, mis aitab neil unne suikuda.'),
('c58d19cd-28c0-452e-ab4b-85c75da1f2b0'::uuid,'Биринчи маанисиз тамаша 🤡','«Ит машинага түшүп, жарылып кетти!» деп кыйкырып, каткырып күлүп жатышат. Мында эч кандай логика жок, бирок алар юмор сезимин ачып жатышат. Маани издебеңиз; тескерисинче, алардын таза жана кубанычтуу күлкүсүнө өзүңүздүн катуу күлкүңүз менен кошулуңуз.','Esimene arusaamatu nali 🤡','„Koer läks autosse ja plahvatas!” hüüatavad nad ja puhkevad naerma. Selles pole mingit loogikat, aga nad alles avastavad oma huumorimeelt. Ära otsi tähendust; selle asemel ühine nende puhta ja rõõmsa naeruga valju itsitamisega.'),
('0a22f56d-c8f3-477d-a3c0-1cf48a52b75f'::uuid,'Эрежелердин тайгак жолу 🛝','Парктагы слайддын башында туруп, башка балдарды түшүрбөй жатышабы? Уялып же аларды катуу тартып албаңыз. Айланадагыларга көңүл бурбай, кезек менен түшүү керектигин акырын эскертиңиз. Алар бул жол менен болсо да, ээлик кылуу сезимин сынап жатышат.','Reeglite libe tee 🛝','Nad seisavad pargis liumäe tipus ega lase teisi lapsi alla. Ära tunne piinlikkust ega kisu neid jõuga ära. Tuleta neile õrnalt meelde kordamööda liuglemist, teisi pealtvaatajaid tähele panemata. Nad alles avastavad oma omanditunnet, isegi sellisel moel.'),
('2e61e71c-40b9-4acb-82fb-ac9b3ee6a222'::uuid,'Ал эми ымыркай эмес! 🌟','Алар өз алдынча чечимдери, кызыктуу суроолору жана чоң жүрөгү бар толук кандуу адамдар. Бул күчтүү мүнөздү сындырбай, тескерисинче, туура багыттап өстүргөнүңүз үчүн өзүңүзгө чоң рахмат айтыңыз. Сиз укмуштуудай иш жасап жатасыз.','Ta pole enam tita! 🌟','Nad on täisväärtuslikud inimesed oma otsuste, uudishimulike küsimuste ja suure südamega. Ütle endale suur aitäh, et kasvatad seda tugevat iseloomu nende vaimu murdmata, vaid neid suunates. Teed suurepärast tööd.'),
('a5162fa5-e190-42b6-b85c-5309ce76b381'::uuid,'Шампансыз жеңиш 🥂','Оор күндөн кийин экөөңүзгө ысык чай куюп алыңыз. Диванга бетме-бет отуруп, стакандарыңызды кагыштырып: «Биз бүгүнкү башаламандыкты да жеңип чыктык!» деп айтыңыз. Экөөңүз тең бул үйдүн командири жана командасысыздар.','Šampanjavaba võit 🥂','Pärast rasket päeva valage endale tass tavalist kuuma teed. Istuge partneriga diivanil vastamisi, kõlistage tasse ja öelge: „Me elasime ka tänase kaose üle!” Olete mõlemad selle kodu komandörid ja meeskond.'),
('450f109f-b886-4ee2-8c86-66186d74b732'::uuid,'Жарыктардын ыргагы 🌙','Алардын тез уктап кетиши үчүн, уктоо убактысына 1 саат калганда бөлмөдөгү бардык ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин караңгы жана технологиясыз чөйрөдө гана тез иштелип чыгат, бул сиздин ишиңизди жеңилдетет.','Tulede rütm 🌙','Et aidata neil kiiremini uinuda, lülita 1 tund enne magamaminekut toas välja kõik lisatuled ja tahvelarvutite ekraanid. Melatoniini toodetakse kiiresti vaid pimedas ja tehnoloogiavabas keskkonnas, mis teeb sinu töö lihtsamaks.'),
('b4a0c1d1-e187-401c-89d3-83448ef5f879'::uuid,'Динозаврдын эртең мененки тамагы 🦖','Эртең мененки тамакта алар кол колдонбой, оозун түз тарелкага тийгизип, динозавр сыяктуу тамактангысы келип жатышат. Адеп-ахлак боюнча лекция окубаңыз! 5 мүнөт динозавр болуп алышсын; алар баары бир оюнга тажап, кашыкты колдоруна алышат.','Dinosauruse hommikusöök 🦖','Hommikusöögi ajal tahavad nad süüa nagu dinosaurused, pannes suu otse taldrikule ilma käsi kasutamata. Ära pea loengut kommetest! Lase neil 5 minutit dinosaurust mängida; neil saab mängust küllalt ja nad võtavad nagunii lusika kätte.'),
('331d91d4-ea8d-4af5-be08-e82eb1b8836d'::uuid,'Өзүмдүн темпим 🐢','Үйдөн чыгышыңыз керек, бирок алар өздөрү бут кийим кийем деп 15 мүнөт бою жай кыймылдап жатышат. Эгер кийлигишсеңиз, 30 мүнөттүк ый менен беттешесиз. Убакыттын тардыгына эмес, алардын жаңыдан калыптанып жаткан «мен» сезимине көңүл буруп, жөн гана күтө туруңуз.','Minu oma tempo 🐢','Peate kodust lahkuma, aga nad nõuavad kindlalt, et panevad ise kingad jalga, mis võtab teosammul 15 minutit. Kui sekkud, ootab sind 30-minutiline nutuhoog. Ära keskendu ebakindlale ajagraafikule, vaid nende tärkava ego hoidmisele, ja lihtsalt oota.'),
('bd96c118-6b22-4005-829a-5d2036e47887'::uuid,'Жоголгон ачкычтардын сыры 🔑','Үйдүн ачкычын таппай жатасызбы? Муздаткычты же бут кийим текчесин текшериңиз! Кичинекейиңиз нерселерди жашырып, алардын бар экенин сынап жаткан болушу мүмкүн. Бул күлкүлүү кенч издөө оюнунда ачууланбай, күлүүнү тандаңыз.','Kadunud võtmete müsteerium 🔑','Ei leia koduvõtmeid? Kontrolli külmkappi või kingakappi! Sinu pisike katsetab tõenäoliselt objektide püsivust asju peites. Vali selle koomilise aardejahi ajal pahandamise asemel naer.'),
('c22e7a31-d31e-4595-845a-77f2550b33d1'::uuid,'Гипноздук шыбыр 🤫','Төшөктө жатып, буттарын абада серпип, уктагысы келбей жатышабы? Кыкырбай, күтүлбөгөн жерден үнүңүздү басаңдатып, шыбырап сүйлөңүз. Балаңыз сизди угуш үчүн кулак төшөгөндө, анын мээси автоматтык түрдө гипноздук, уйкуга даяр абалга өтөт.','Hüpnootiline sosin 🤫','Nad lamavad voodis, siputavad jalgadega ja keelduvad magamast. Karjumise asemel langeta järsku häält ja räägi nendega vaid sosinal. Kui laps pingutab, et sind kuulda, läheb tema aju automaatselt hüpnootilisse, uneks valmis olekusse.'),
('11c8bab9-c92e-47a2-b7c0-34d8c43e8735'::uuid,'Кучактоонун жылуулугу 🫂','Күнү бою көтөрүп, кучактап жүрүп денеңиз ооруп жатабы? Кечинде «топту» атасына өткөрүп бериңиз. Ал баланы аркасына мингизип ойногондо, баланын көңүл буруу муктаждыгы канааттандырылат, ал эми сиздин колдоруңуз эс алат.','Kallistuse lohutus 🫂','Pärast terve päeva kestnud ronimist ja kaisutuste vajadust valutab su keha. Õhtul „sööda pall” issile. Kui ta teeb lapsele kukil sõitu, saab nii lapse tähelepanuvajadus rahuldatud kui ka sinu käed hädavajaliku puhkuse.'),
('5ddf0bc2-3619-404d-a56d-27e47d73626e'::uuid,'Эртең мененки концерт 🎤','Күн толук чыга электе эле төшөктө секирип, сиз түшүнбөгөн тилде катуу ырдап жатышабы? Ооба, уйкуңуз келип жатат, бирок бөлмөнү толтурган бул чексиз энергия сиздин да маанайыңызды көтөрөт. Алардын кубанычтуу үндөрүнө карап жылмайып коюңуз.','Hommikune kontsert 🎤','Päike pole veel täielikult tõusnudki, aga nad hüppavad voodis ja laulavad valjult keeles, millest sa aru ei saa. Jah, oled unine, aga see piiritu energia, mis tuba täidab, tõstab ka sinu tuju. Lihtsalt naerata nende rõõmsatele häältele.'),
('c7c4ce1e-98e4-4beb-992c-e1f8c9783567'::uuid,'Сиздин AI куткаруучуңуз 🤖','«Апа, күн кайда уктаганы барат?» деген суроодон улам калдыңызбы? Түшүндүрүүнү татаалдаштырбаңыз. Бул суроону балаңыздын жашын белгилеп, Anacan AI''дан сураңыз жана 3 жашар баланын мээси оңой кабыл ала турган жомок сыяктуу жоопту алып, алар менен бөлүшүңүз.','Sinu tehisintellektist päästja 🤖','„Emme, kuhu päike magama läheb?” Kas küsimus ajas su segadusse? Ära selgitust üle keeruliseks aja. Esita see küsimus Anacan AI-le, täpsustades lapse vanust, ja saa see imeline, muinasjutuline vastus, millest 3-aastase aju kergesti aru saab, ning jaga seda nendega.'),
('0daa509c-a73b-47b1-a76d-b85764cf98f2'::uuid,'Унчукпай төгүлгөн көз жаш 💖','Алар күнү бою сизди абдан чарчатышты. Бирок азыр төшөктө бейкүнөө уктап жатканын көрүп, толкунданбай коё албай жатасыз, туурабы? Бул энеликтин эң чоң парадоксу. Көзүңүздөн аккан ал жалгыз тамчы жаш – алардын бар болгону үчүн сиздин ыраазычылыгыңыз.','Vaiksed pisarad 💖','Nad ajasid sind terve päeva täiesti hulluks. Aga nüüd, nähes neid voodis nii süütult magamas, ei saa sa jätta tundmata liigutust, eks? See on emaduse suurim paradoks. See üks pisar, mis su silmast langeb, on sinu tänulikkus nende olemasolu eest.'),
('2d96922a-7550-4150-a8ed-19cdd56a8801'::uuid,'Жашыруун тамак миссиялары 🥣','Кечээ эле жакшы көрүп жеген жумурткасын бүгүн жебей жатабы? Алардын каалоосу менен күрөшпөңүз. Акылдуулук менен жеңишке жетиңиз: биздин пайдалуу рецепттер бөлүмүнөн белокту ар кандай, түстүү жана кызыктуу формаларга айландырган тамактарды жасап көрүңүз!','Salajased toidumissioonid 🥣','Kas nad ei taha enam süüa muna, mida nad eile veel nii väga armastasid? Ära võitle nende tahtega. Ole kaval ja proovi meie tervislike retseptide sektsioonist suupisteid, mis muudavad valgud erinevateks, värvilisteks ja põnevateks kujunditeks!'),
('a6a15ff2-f8a6-4007-b1d8-974680e64a8d'::uuid,'Логиканын кыйрашы 🛑','Сууну кызыл чөйчөктөн ичем деп талап кылышат, сиз куюп берсеңиз, кайра эле «Эмнеге бул жакка куйдуң?!» деп ыйлашат. Мында эч кандай логика жок. Жөн гана алар чарчашты жана ичиндеги топтолгон эмоцияларын чыгарып алышы керек. Тынч күтө туруңуз; бороон өзүнөн-өзү басылат.','Loogika kokkuvarisemine 🛑','Nad nõuavad vett punases tassis, sina valadki selle punasesse tassi ja siis nad nutavad: „Miks sa selle siia valasid?!“ Selles pole mingit loogikat. Nad on lihtsalt väsinud ja peavad oma kuhjunud emotsioonid välja elama. Oota rahulikult; torm vaibub iseenesest.'),
('15c2879b-fa80-4ef3-b734-53366c8b7916'::uuid,'Күтүлбөгөн жерден келген сүйүү сезими 🥰','Оюндун ортосунда оюнчугун таштап, сизге чуркап келип, мойнуңузга асылып: «Мен сени жакшы көрөм» дешет. Бул чарчоонун жана уйкусуз түндөрдүн баарын унуттурган сыйкырдуу учур. Аларды бооруңузга бекем кысып, жытын искеңиз.','Äkiline armastusepuhang 🥰','Nad viskavad mänguhoos mänguasja käest, jooksevad sinu juurde, mässivad käed ümber su kaela ja ütlevad: „Ma armastan sind.“ See on see maagiline hetk, mis pühib minema kogu väsimuse ja unetud ööd. Hoia neid tugevalt oma rinna vastas ja hinga sisse nende magusat lõhna.'),
('c0446dd4-cfe7-4c72-9419-07304cef46d7'::uuid,'Атанын кызыктуу окуясы 📖','Бүгүн кечинде үнүңүз чарчаңкы чыгып жатабы? Жомок айтууну жолдошуңузга өткөрүп бериңиз. Ал китептегиден таптакыр башка, ойдон чыгарылган, күлкүлүү окуяны айтып берип, баланы каткыртып жиберет. Ал арада сиз чай ичип, бул көрүнүштөн ырахат алып отура аласыз.','Issi kummaline lugu 📖','Sinu hääl on täna õhtul väsinud. Anna unejutud üle issile. Ta räägib hoopis teistsuguse, väljamõeldud ja naljaka loo, mis paneb lapse naerust kilkama. Sina saad samal ajal teetassiga mugavalt istuda ja seda vaatepilti nautida.'),
('df2fef22-961b-4197-8f8b-a55345b6bbaa'::uuid,'Азык-түлүк дүкөнүндөгү башаламандык 🛒','Өздөрүнөн чоң болсо да, чоң арабаны өздөрү түртөм деп туруп алыштыбы. Коомдук жайда аларды ыйлатпай, колдорун арабанын четинде калтырып, өзүңүз байкатпай башкарып туруңуз.','Kaos toidupoes 🛒','Nad nõuavad, et tohiksid ise suurt ostukäru lükata, kuigi see on neist palju suurem. Selle asemel, et lasta neil avalikus kohas jonni ajada, lase neil käed käru serval hoida, samal ajal kui sina seda märkamatult suunad.'),
('1528a888-1cfa-4bf5-b2b7-c533244518f5'::uuid,'Тескери кийилген эркиндик 👗','Шымдарын тескери кийип алып, абдан чечкиндүү түрдө: «Мен өзүм кийиндим!» деп жатышат. Эстетиканы унутуңуз. Алардын өзүнө болгон ишеними жана көз карандысыздык сезими кийимди туура кийгенден алда канча маанилүү. Бул кичинекей козголоңчуңуз менен сыймыктаныңыз.','Tagurpidi vabadus 👗','Nad on pannud püksid tagurpidi jalga ja teatavad suure kindlustundega: „Ma panin ise riidesse!“ Unusta esteetika. Nende kasvav enesekindlus ja iseseisvustunne on palju olulisemad kui riiete õigetpidi kandmine. Ole selle väikese mässaja üle uhke.'),
('3b7890c9-fcdd-4513-a90d-c39e56fa7a0a'::uuid,'Башаламандыктын ортосундагы кофе ☕','Бөлмөнүн ортосуна оюнчуктарын чачып, укмуштуудай сепил куруп жатышат. Сиз ал башаламандыкты жыйнаарыңыз менен, алар кайра эле башкасын жасашат. Андыктан, күрөштү токтотуп, бөлмөнүн бир бурчуна отуруп, чай ичип, бул кооз башаламандыкты алыстан карап эс алыңыз.','Kohv keset kaost ☕','Nad on kõik mänguasjad keset tuba laiali puistanud, ehitades uhket lossi. Niipea kui sa selle segaduse ära koristad, teevad nad uue. Seega loobu võitlusest, mine toa nurka, naudi oma kohvi, kuni see veel soe on, ja lõõgastu, vaadeldes seda kaunist kaost eemalt.'),
('903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a'::uuid,'Бөлмөдөгү көлөкөлөр 🐰','Караңгыдан корко башташтыбы? Бөлмөнү толук караңгылатып, кичинекей фонарик менен шыпка жарык шоусун жана жаныбарлардын көлөкөсүн жасаңыз. Алар корккон караңгылыкты кызыктуу оюнга, уктаар алдындагы чогуу күлүп-жайнай турган кичинекей экспедицияга айлантыңыз.','Varjud toas 🐰','Kas nad hakkavad pimedust kartma? Tee tuba täiesti pimedaks ja kasuta väikest taskulampi, et luua laes valgusmänge ja looma-varjusid. Muuda hirmutav pimedus põnevaks mänguks, väikeseks une-eelseks ekspeditsiooniks, kus saate koos naerda.'),
('86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd'::uuid,'Үзгүлтүксүз уйкуга үмүт 🤞','Алар укташты, үйдө терең тынчтык орноду. Эң чоң тилегиңиз — бүгүн түнү ойгонбосо экен. Үн өлчөгүчтүн «токойдогу жайкы шыбыр» фонун акырын коюп, алардын терең уйку фазасында калышын камсыз кылыңыз.','Lootus katkematu une peale 🤞','Nad magavad ja majas valitseb sügav vaikus. Sinu suurim soov on, et nad täna öösel ei ärkaks. Veendu, et nad püsiksid sügavas unefaasis, mängides vaikselt helimõõtja taustaheli „õrn metsakohin“.'),
('906c34fb-a999-448f-8756-7ba4d8fc80cd'::uuid,'Жаратылыш лабораториясы 🍂','Үй ичи тумчугуп, балаңыз тынчсызданып жатабы? Аба ырайын жана кийимин текшерип, сөзсүз сыртка алып чыгыңыз. Кургак бутактарды жана жалбырактарды чогултуу сыяктуу жөнөкөй тапшырма менен алар энергиясын сарптап, сиз да төрт дубалдан чыгып, таза абадан дем аласыз.','Looduse laboratoorium 🍂','Kodu hakkab tunduma lämbe ja su väike laps on rahutu. Kontrolli ilma ja riietust ning mine kindlasti õue. Lihtsa ülesandega, nagu kuivanud okste ja lehtede korjamine, kulutavad nad energiat ja sina saad värsket õhku, pääsedes nelja seina vahelt välja.'),
('af0535a2-83d1-4838-8bfc-0cfb607ff2f5'::uuid,'Оюнчуктардын энеси 🧸','Бөлмөдөн үн чыкты. Кулак төшөсөңүз, алар сиздин үнүңүздү жана сөздөрүңүздү туурап, оюнчук аюусун урушуп жатышат! Алар сиздин эң жакшы көчүрмөңүз. Бул өзүңүздүн жүрүм-турумуңузду сырттан байкоо үчүн эң сонун мүмкүнчүлүк.','Mänguasjade ema 🧸','Toast kostab hääli. Kuulad tähelepanelikult ja seal nad ongi, noomides oma kaisukaru täpselt sinu hääletooni ja sinu fraasidega! Nad on sinu parim koopia. See on suurepärane võimalus vaadelda omaenda käitumist kõrvalt.'),
('0300b128-8698-433f-8d28-7ef165f88a96'::uuid,'Бөлүшүлбөс эртең мененки тамак 🍳','Өз тарелкасынан бир тиштем да бербейт, бирок сиздин тарелкаңыздагы жумуртканы жейм деп туруп алат. Балдар ар дайым ата-энесинин тандоосуна көбүрөөк ишенишет. Бул менен күрөшпөңүз; бул кичинекей сүйүктүүңүз менен тамагыңызды сүйүү менен бөлүшүңүз.','Jagamatud hommikusöögid 🍳','Nad ei anna sulle oma taldrikult suutäitki, aga nõuavad kindlalt muna sinu taldrikult. Lapsed usaldavad vanemate valikuid alati rohkem. Ära võitle sellega; jaga armastusega oma toitu selle väikese kullatükiga.'),
('334f9c8b-ef27-4cd7-845a-eb18706654fc'::uuid,'Соода тизмесиндеги кырсык 🛒','Эсиңизге ишенип үйгө келсеңиз, балаңыз үчүн эң керектүү болгон сүттү алганды унутуп калыптырсыз. Мээңиз ашыкча маалыматка толуп кетти! Керектүү нерселерди эсиңизге келери менен Anacan тиркемесиндеги «Соода тизмесине» кошууну адатка айлантыңыз жана ашыкча стресстен арылыңыз.','Sisseostunimekirja katastroof 🛒','Usaldasid oma mälu, tulid koju ja avastasid, et unustasid piima osta – beebi jaoks kõige olulisem asi. Su pea on niigi täis! Tee endale harjumuseks lisada asjad äpi ostunimekirja kohe, kui mõistad, et neid vajad, ja säästa end asjatust stressist.'),
('ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f'::uuid,'Ваннадагы океан 🌊','Чоюнуу убактысы эми жөн гана тазалануу эмес, бул толкун жасоо оюну! Сууну чачыратыңыз. Суунун сыйкырдуу таасири алардын күн бою топтогон терс энергиясын жууп кетип, уйкусун тереңдетет.','Vanniookean 🌊','Vanniskäik pole enam ammu ainult pesemine, vaid lainete tegemise mäng! Lase veel igale poole pritsida. Vee magnetiline mõju peseb maha kogu kangekaelse negatiivse energia, mida nad päeva jooksul kogunud on, saates selle äravoolust alla ja süvendades nende und.'),
('056e606b-664d-4a4e-94b5-81db6f2adf23'::uuid,'Сиз жетиштүүсүз 🛑','Социалдык тармактардагы балдары менен шедевр жаратып, үйүн жаркыратып жүргөн «идеалдуу» энелерди көргөндө өзүңүздү сындайсызбы? Ал фильтрлерге алданбаңыз. Сиздин башаламан, ызы-чуулуу, бирок чыныгы үйүңүз — балаңыз үчүн эң жылуу жана эң идеалдуу сүйүү уясы.','Sa oled piisav 🛑','Kas kritiseerid end, kui näed sotsiaalmeedias „täiuslikke“ emasid, kes loovad lastega meistriteoseid ja hoiavad kodud säravatena? Ära lange nende filtrite ohvriks. Sinu sassis, lärmakas ja ehtne kodu on lapsele kõige soojem ja täiuslikum armastuse pesa.'),
('156b6d8e-1bbe-4769-b258-c89d41a67564'::uuid,'Кичинекей юристтин аргументи 🗣️','«Мен чоңойдум, шоколад жесем болобу?» Алар буга чейин эле себеп-натыйжа байланыштарын түзүп, сиз менен соодалашууга аракет кылып жатышат! Алардын сүйлөө жөндөмү абдан жакшы өнүккөн. Аларды мактаңыз, бирок чектериңизди жана эрежелериңизди жумшактык менен сактаңыз.','Väikese advokaadi argument 🗣️','„Kas ma tohin šokolaadi süüa, sest olen nüüd suur?“ Nad üritavad juba sinuga läbi rääkida ja kaubelda, luues põhjus-tagajärg seoseid! Nende kõneareng on suurepärane. Kiida neid, kuid pea õrnalt kinni oma piiridest ja reeglitest.'),
('838e23dd-ecaf-4568-9687-59518e77bc77'::uuid,'Тынчтыктагы терапия 🤫','Алар акыры укташты! Үн өлчөгүчүңүздү иштетип, экрандагы сандардын 0 децибелге түшкөнүн караңыз. Чарчаган акылыңыздын тазаланып, бул визуалдык тынчтык сезимдериңизди эс алдырганын сезиңиз.','Teraapia vaikuses 🤫','Nad jäid lõpuks magama! Aktiveeri helimõõtja ja vaata, kuidas numbrid ekraanil 0 detsibellini langevad, tundes, kuidas väsinud meel selgineb ja see visuaalne vaikus su meeli masseerib.'),
('1645ac24-40c0-4cef-8645-e26caf67a799'::uuid,'Ашканадагы башаламандык 🧑‍🍳','Камыр жууруп жатсаңыз, балаңыз келип, колун унга салып, баарын ак кылып салды. Ооба, ашкана башаламан, сизде иш көбөйдү. Бирок ошол олуттуу, алек болгон кичинекей жүзүн тез арада сүрөткө тартып алыңыз. Башаламандык тазаланат, бирок ал эстелик түбөлүккө калат.','Köögikaos 🧑‍🍳','Sõtkud tainast ja laps tuleb, pistab käe jahusse, tehes kõik valgeks. Jah, köök on sassis ja sul on rohkem tööd. Aga jäädvusta kiiresti see tõsine ja tegus väike nägu beebifotoseeriaks. Segadus saab koristatud, aga see mälestus jääb igaveseks.'),
('b8b57297-f4b4-4473-87af-9acfeee74dd3'::uuid,'Ачка эмес, бирок эмнеге? 🧩','Эмне кылсаңыз да соорото албай жатасызбы? Божомолдоону токтотуңуз! Ыйдын анализин колдонуп, алардын эмне үчүн ыйлап жатканын дароо билип алыңыз.','Pole näljane, aga miks? 🧩','Ei suuda neid kuidagi rahustada? Lõpeta arvamine! Kasuta nutuanalüüsi, et kuulata nende nuttu ja avastada koheselt, mis neid vaevab.'),
('58f0130e-9824-44fe-9963-a1e86c3e18cc'::uuid,'Өзүңүз менен сыймыктаныңыз 🚀','Артка кылчайып карасаңыз, алардын кандай күчтүү мүнөзгө ээ болуп өскөнүн көрөсүз. Бүгүн аларды жакшылап карап, мындай сонун адамды тарбиялаганыңыз үчүн өзүңүз менен сыймыктаныңыз.','Ole enda üle uhke 🚀','Tagasi vaadates näed, kuidas neist on kasvanud tugeva iseloomuga inimesed. Täna vaata neid pikalt ja tunne uhkust enda üle, et oled kasvatanud nii imelise inimese.'),
('f9ac9f1e-0a4a-473c-909e-2a7e500a27b0'::uuid,'Тынчтандыруучу толкундар 🌊','Кызыктуу окуяларга толгон күндөн кийин уктабай жатасызбы? Бөлмөдө сыйкырдуу тынчтык орнотуу үчүн «Ак ызы-чуу» (White Noises) бөлүмүнөн деңиз толкундарынын үнүн тандаңыз.','Rahustavad lained 🌊','Kas uinumine on pärast põnevaid avastusi täis päeva raske? Vali valgete helide hulgast ookeanilainete heli, et luua tuppa maagiline rahu.'),
('f65305c4-c08d-4180-9df9-53864d7df4a9'::uuid,'Ыраазычылык командасы 🥂','Дагы бир оор жана түйшүктүү күндү артта калтырдыңыз. Бала уктагандан кийин жолдошуңуз менен чай ичип: «Бүгүн мага абдан жардам бердиң, рахмат» деп айтыңыз. Ата-эне болуу — бул жалгыз сапар эмес, ал күчтүү команда менен гана гүлдөйт.','Tänulikkuse tiim 🥂','Oled hakkama saanud järjekordse raske ja tormilise päevaga. Pärast lapse uinumist vala kaaslasega teed ja ütle: „Aitasid mind täna nii palju, aitäh.“ Lapsevanemaks olemine pole sooloretk; see õitseb tugevas meeskonnas.'),
('52fd1b46-da9f-4903-91e9-9855c04a5c68'::uuid,'Боорукерликтин жарк этиши','Балаңыз кулап калган оюнчукту акырын сооротуп: «Ыйлабачы» деп жатабы? Алардын боорукердик сезими сонун өнүгүп жатат! Бул таттуу ийгиликти «Өнүгүү күндөлүгүнө» жазып коюуну унутпаңыз.','Empaatia välgatused','Kas su laps lohutab õrnalt kukkunud mänguasja ja ütleb: „Ära nuta“? Nende empaatiavõime on kaunilt tärkamas! Logi see armas verstapost kindlasti arengupäevikusse.'),
('8cc847d7-8dbe-41eb-84d4-4cb88879af35'::uuid,'Тескери кийилген кийимдер 👗','Балаңыз көйнөгүн тескери кийип алдыбы? Күрөшпөңүз. Үйдө жүргөндө бир күн ошондой кийип жүрө берсин; алардын рухун сындырбаңыз.','Pahempidi riided 👗','Kas su laps nõuab särgi tagurpidi kandmist? Ära võitle sellega. Lase neil seda kodus päev otsa nii kanda; ära murra nende vaimu.'),
('8ec0eb18-27f1-4127-9c31-f0777f9a4904'::uuid,'Биз бир командабыз! 💖','Оор күндөн кийин жолдошуңуз менен отуруп, сүйлөшүп алыңыз. Бири-бириңизди колдоо жүктү чындап эле эки эсе жеңилдетет.','Me oleme meeskond! 💖','Pärast rasket päeva istu kaaslasega maha ja rääkige asjad läbi. Üksteise toetamine poolitab koorma tõeliselt.'),
('47e4625b-1969-49f3-9819-a17d4bddc0c8'::uuid,'Ордунан жасалган чептер 🛏️','Уктап баратканда эле капысынан ыйлап жиберишет: «Ордумдун чети бүктөлүп калды!». Алар үчүн жууркандын тегиздиги өтө маанилүү. Терең дем алып, жуурканды үтүктөп жаткандай тегиздеп, алардын бул таттуу кылдаттыгына жылмайып коюңуз.','Tekikindluse seiklused 🛏️','Just siis, kui nad on uinumas, puhkevad nad äkki nutma: teki nurk on kortsus! Nende jaoks on teki millimeetrise täpsusega siledus ülioluline. Hinga sügavalt sisse, silu tekk nii, nagu triigiksid seda, ja lihtsalt naerata sellele armsale pirtsakusele.'),
('743bf968-dea7-4d72-ac2d-22654230f0a2'::uuid,'Шектүү тынчтык 🤫','Үйдө капысынан терең тынчтык орноду. Үн өлчөгүч 0 децибелди көрсөтүп турат. Эгер балаңыз унчукпай жатса, демек, ал бир жерде чоң изилдөө жүргүзүп жатат. Бөлмөгө киргенде дубалдагы чиймелерди же айрылган кагаздарды көрүүгө даяр болуңуз.','Kahtlane vaikus 🤫','Majas valitseb äkiline sügav vaikus. Helimõõtja näitab 0 detsibelli. Kui laps on vait, tähendab see, et kuskil on käimas suur avastusretk. Valmistu vaimselt leidma tuppa sisenedes seintelt joonistusi või puruks rebitud paberit.'),
('9fa0703c-5759-4d65-aa22-1042aa7b5843'::uuid,'Талаш-тартышка аралашпаңыз 💼','«Бул боткону жебейм, анткени ал сары!» Алардын логикасы ушунчалык абсурддуу жана ишендиргич болгондуктан, өзүңүздү күнөөлүү сезип кетишиңиз мүмкүн. Талашпаңыз. «Туура айтасың, ал сары экен. Бирок ага бир аз кызыл мөмө кошсокчу?» деп, кичинекей талашкычыңызды жумшак багыттаңыз.','Ära lase end vaidlusse kiskuda 💼','„Ma ei söö seda putru, sest see on kollane!“ Nende loogika on nii veatult absurdne ja veenev, et võid peaaegu süüdlaslikult tunda. Ära vaidle. Ütle: „Sul on õigus, see on tõesti kollane. Aga mis siis, kui lisaksime punaseid marju?“ ja suuna oma väikest väitlejat õrnalt.'),
('454d0433-fa13-4bd5-95fe-c40365aff560'::uuid,'Үй-бүлөнүн башкы дарыгери 🩺','Оюнчук стетоскобун алып, көкүрөгүңүзгө коюп, кабагын бүркөп: «Дем ал!» дешет. Сиз тил алчаак бейтапсыз. Бул ролдук оюнду мүмкүнчүлүк катары колдонуңуз: көзүңүздү жумуп, 3 мүнөттүк «текшерүү» учурунда полдо жатып, белиңизди эс алдырыңыз.','Majapidamise peaarst 🩺','Nad võtavad mängustetoskoobi, panevad selle su rinnale, kortsutavad kulmu ja ütlevad: „Hinga sisse!“ Sina oled kuulekas patsient. Muuda see rollimäng võimaluseks: pane silmad kinni ja lihtsalt leba põrandal kogu 3-minutilise „läbivaatuse“ ajal, andes oma seljale puhkust.'),
('603f7d3e-e83f-41b9-ade3-bd0fa858fbaf'::uuid,'Атанын жомок айтуучу үнү 📖','Үнүңүз чарчап, тамагыңыз кургап турат. Жомок айтуу милдетин атасына өткөрүп бериңиз. Ал кичинекейиңизди китептеги сүрөттөрдөн таптакыр айырмаланган, күлкүлүү жана ойдон чыгарылган окуялар менен каткыртып күлдүрөт. Ал эми сиз бул жагымдуу көрүнүштү бир чыны жылуу чай менен алыстан карап отурсаңыз болот.','Issi jutuvestja hääl 📖','Sinu hääl on väsinud ja kurk kuiv. Anna unejutulugemine üle issile. Ta paneb su pisikese itsitama naljaka, väljamõeldud looga, mis on hoopis teistsugune kui raamatu piltidel. Sina saad samal ajal seda rõõmsat hetke eemalt sooja teetassi taga nautida.'),
('e4995ac6-5e09-45b3-8f40-851f3616a9f6'::uuid,'«Апа, карачы!» фазасы 👀','Алар дивандан секирип, бир эле кыймылды 50 жолу кайталап, «Апа, мага карачы!» деп кыйкырып жатышат. Телефонуңузду четке коюңуз. Алар муну жөн эле кыймыл үчүн эмес, сиздин көзүңүздөгү ыраазычылыктын учкунун көрүү үчүн жасап жатышат. Аларга беш мүнөт толук көңүл буруңуз; алар өздөрүн чындап баалуу сезишсин.','„Emme, vaata!“ faas 👀','Nad hüppavad diivanilt alla, kordavad sama tegevust 50 korda ja karjuvad: „Emme, vaata mind!“ Pane telefon käest. Nad ei tee seda tegevuse enda pärast, vaid selle sära pärast sinu silmis, mis kinnitab, et oled neid märganud. Kingi neile viis minutit segamatut tähelepanu; lase neil tunda, et nad on tõeliselt nähtud.'),
('41b57fa8-5ee9-47c4-bdaf-6650d5ddc287'::uuid,'Музыканын жумшак сыйкыры 🎶','Түшүнүксүз кечки ыйлоолор жана кыжырдануулар башталдыбы? Телевизорду өчүрүп, жарыкты басаңдатып, өтө жай классикалык музыка коюңуз. Музыканын терең добуштары атмосфераны сыйкырдуу түрдө өзгөртүп, бөлмөгө тынчтык алып келет.','Muusika õrn võlu 🎶','Seletamatud õhtused jonni- ja nutuhood on alanud. Pane teler kinni, hämarda tuled ja pane mängima väga rahulik klassikaline muusika. Muusika madalad sagedused muudavad atmosfääri võluväel ja toovad tuppa rahu.'),
('bfa22ff0-d771-4756-a950-034bebcc6d6a'::uuid,'Мультфильмдин сценаристи 📺','Алар жаңы эле көргөн мультфильмин ушунчалык өзгөчө жана ишенимдүү баяндап берет, сиз да дээрлик ишенип каласыз. Сиздин балаңыздын фантазиясы укмуштуудай өнүгүп жатат!','Multikate stsenarist 📺','Nad selgitavad just vaadatud multikat nii ainulaadse ja veenva süžeega, et hakkad seda peaaegu uskuma. Suurepärane kujutlusvõime on arenemas!'),
('d113ec32-8781-4153-b853-ad718dad74e9'::uuid,'Апанын өчүрүп-күйгүзүү баскычы 🚪','Ызы-чуу башыңызды оорутуп, баарына кыйкырып жибергиңиз келип жатабы? Маанай күндөлүгүңүздү ачыңыз. Ал жерге чарчаганыңызды эркин жазыңыз. Бул кыска санариптик терапия сизге кайрадан калыбына келүүгө жардам берет.','Emme lähtestusnupp 🚪','Müra puurib su ajusid ja tunned, et tahaksid kõige peale karjuda. Ava oma meeleolupäevik. Kirjuta sinna vabalt kogu oma väsimus. See lühike digitaalne teraapia aitab sul end nullida.'),
('15c2d5ec-3e4a-4b1d-b6d2-a891cc587847'::uuid,'Атанын сууга түшүүдөгү көңүл ачуусу! 🛁','Бүгүн кечинде жуунуу убактысы толугу менен атасынын көзөмөлүндө. Алар сууга түшүп ойноп жатышсын, ал эми сиз эшиктин артындагы жымжырттыктан ырахат алыңыз.','Issi pritsmetega vanniaeg! 🛁','Tänaõhtune vanniskäik on täielikult issi pärusmaa. Lase neil sulistada, samal ajal kui sina naudid ukse taga täielikku vaikust.'),
('2054a805-49e3-459b-8315-84f392392707'::uuid,'Кийим шкафындагы козголоң 🥽','Алар үйдүн ичинде сууда сүзүүчү көз айнек жана кышкы баш кийим менен жүргүсү келет. Алар өжөрлөнүп, чечпей жатышат. Коомдук нормаларды унутуңуз. Алардын чыгармачылыгын жана тандоо эркиндигин чектебеш үчүн, бир күн бою ушундай өзгөчө, күлкүлүү кийим менен жүрө беришсин.','Garderoobimäss 🥽','Nad tahavad majas ringi käia ujumisprillide ja talvemütsiga. Nad nõuavad seda ega võta neid peast. Unusta ühiskondlikud normid. Lase neil veeta päev selles ainulaadses ja naljakas riietuses, et mitte pärssida nende loovust ja valikuvabadust.'),
('5be61e62-9e95-417b-9db3-15386a93c72a'::uuid,'Азык-түлүк арабасындагы сюрприздер 🛒','Кассага жакындаганда, сиз албаган үч түрдүү шоколад жана бир кызыктай самын арабаңыздан сыйкырдуу түрдө пайда болдубу? Ал нерселерди кайра ордуна коюуга шашылыңыз. Унутчаактык менен күрөшүү үчүн, Соода тизмеңизди дайыма текшерип туруңуз.','Üllatused toidukärus 🛒','Kassasse jõudes ilmub su ostukorvi salapäraselt kolm erinevat šokolaadi ja üks kummalise kujuga seep, mida sa ei valinud. Manööverda kiiresti, et need asjad tagasi panna. Unustamise vältimiseks hoia oma ostunimekirjal silm peal, et püsida järjel.'),
('22ac2508-9b42-4e19-b15b-cc1dca8c750b'::uuid,'Тандап угуу режими күйгүзүлдү 🙉','Сиз «Оюнчуктарыңды жыйна» же «Кел, колуңду жуу» десеңиз, эч кандай реакция жокпу? Тандап угуу — 3 жашар балдардын сүйүктүү хоббиси! Кыйкыргандын ордуна, алардын жанына барып, кулагына акырын шыбыраңыз. Үнүңүздүн күтүүсүз өзгөрүшү дароо алардын көңүлүн бурат.','Selektiivse kuulmise režiim sees 🙉','Ütled: „Korja mänguasjad kokku“ või „Tule pese käed puhtaks“, aga reaktsiooni pole. Selektiivne kuulmine on 3-aastase lemmikhobi! Selle asemel, et karjuda, mine nende juurde ja sosista väga vaikselt kõrva. Äkiline tooni muutus tõmbab kohe nende tähelepanu.'),
('9ce62e84-5124-421b-bdd6-3fa7c590aa1a'::uuid,'Жаңы түстөр дүйнөсү! 👀','Алар эми түстөрдү ачык жана даана көрө башташты! Аларга контрасттуу түстөгү оюнчуктарды көрсөтүңүз.','Uute värvide maailm! 👀','Nad näevad nüüd värve erksamalt ja selgemalt! Näita neile suure kontrastsusega mänguasju.'),
('4bb7714f-90ea-44a6-8f84-3a989d3c428e'::uuid,'Ваннага түшүү боюнча соодалашуу 🛀','Кирип жатканда ыйлап, эми чыкпайм деп ыйлап жатышабы? Суунун сыйкырдуу күчү аларды толугу менен өзүнө тартып алды. Алдын ала 3 мүнөт калганын эскертип, таймер коюңуз. Коңгуроо кагылганда, оюн бүтөт деген эреже ар дайым жакшы иштейт.','Vanniaja kauplemine 🛀','Nad nutsid vanni minnes ja nüüd uluvad, et ei taha välja tulla! Vee võlu on nad täielikult endasse haaranud. Anna 3-minutiline hoiatus ette ja pane taimer. „Kui kell heliseb, on mänguaeg läbi“ rituaal teeb alati imesid.'),
('a6053646-98c9-47f9-ae28-32c8e38f416e'::uuid,'Кичинекей тамак сүрөтчүсү 🥦','Алар тарелкасындагы тамакты түсүнө жана формасына карап бөлүп, жашылдарын четке түртүп жатышабы? Тамактануу планына киришиңиз! Жашылчаларды байкалбаган пюреге айландырып, котлеттерге же соустарга кошуп жашыруу менен бул оюнду утуп алыңыз.','Väike toidukunstnik 🥦','Nad sorteerivad toitu taldrikul värvi ja kuju järgi, lükates rohelised tükid kõrvale. Süvene oma toitumiskavasse! Võida see mäng, avastades, kuidas muuta köögiviljad nähtamatuks püreeks ja peita need lihapallidesse või kastmetesse.'),
('0b46f253-2b1f-4b21-b471-54a500b94e42'::uuid,'Түн ичинде бийлөө 🌙','Алардын тезирээк уктап кетишине жардам берүү үчүн, уктоо убактысына бир саат калганда бөлмөдөгү бардык ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин (уйку гормону) караңгы жана технологиясыз чөйрөдө гана тез бөлүнүп чыгып, уйкуга өтүүнү жеңилдетет.','Tantsides läbi öö 🌙','Et aidata neil kiiremini uinuda, lülita tund enne magamaminekut toas välja kõik lisatuled ja tahvelarvutite ekraanid. Melatoniin (unehormoon) vabaneb kiiresti vaid pimedas ja tehnoloogiavabas keskkonnas, tagades sujuva uinumise.'),
('53f4b2ce-2dcb-457d-bccf-d9242c156c63'::uuid,'Көчөдөгү кенчтер 🍁','Балаңыз жерден тапкан кир бөтөлкөнүн капкагын же өзгөчө түстөгү ташты алтын сыяктуу кубанып көрсөтүп жатабы? «Ыргытып сал, ал кир» дебей, «Кандай кызыктуу түс! Кел, үйдөн жууп алалы» деп, алардын кызыгуусун колдоңуз.','Tänavate aarded 🍁','Sinu laps näitab sulle rõõmsalt määrdunud pudelikorki või maast leitud erivärvilist kivi, justkui oleks see kuld. Selle asemel, et öelda „Viska ära, see on must“, kiida nende uudishimu: „Milline huvitav värv! Peseme selle kodus puhtaks.“'),
('d8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f'::uuid,'Философия сааты, кайрадан башталды 🤔','«Шамал эмнеге согот? Жалбырактар эмнеге түшөт?» Эртең менен эле терең философиялык суроолор башыңызды оорутуп жатабы? Түшүндүрмөнү татаалдаштырбаңыз; жаратылышты алар түшүнө тургандай жомок түрүндө айтып бериңиз. Сиздин үнүңүздүн обону — алардын дүйнөнү таанып-билиши үчүн эң ишенимдүү жол.','Filosoofiatund, taastatud 🤔','„Miks tuul puhub? Miks lehed langevad?“ Sügavad filosoofilised küsimused põletavad su aju juba varahommikul. Ära muuda selgitust liiga keeruliseks; selgita loodust jutustavas vormis, millest nad aru saavad. Sinu hääletoon on neile kõige kindlam viis maailma mõista.'),
('4a8b061c-822f-4468-b267-6996ffaeb6d8'::uuid,'Ашкана концерти 🥄','Алар казан-аяктарды жана жыгач кашыктарды алып, ашкананын ортосунда концерт коюп жатышабы? Бул сиздин башыңызды оорутса да, алардын ритм сезиминин жана чыгармачылыгынын өнүгүүсү. Тоскоолдук кылууга шашпаңыз; бул жапайы энергиянын бир нече мүнөт бою бөлмөнү үн толкундары менен толтурушуна жол бериңиз.','Köögikontsert 🥄','Nad on välja tassinud potid ja puulusikad ning annavad keset kööki kontserti. Isegi kui see tekitab peavalu, on see nende rütmitaju ja loovuse areng. Ära kiirusta sekkuma; luba sellel metsikul energial mõne minuti jooksul tuba helilainetega täita.'),
('79b03a5c-cc04-4f7b-9361-f8120f787406'::uuid,'Коомчулуктан сооронуч табуу 💬','«Эмнеге балам мынча өжөр?» деген ой сизди жеп жатабы? Anacan коомчулугуна кошулуңуз. Башка энелердин үйлөрүндө болуп жаткан ушундай эле кызыктай кризистер жөнүндө окуганда, сиз жалгыз эмес экениңизди жана таптакыр кадимки, дени сак баланы тарбиялап жатканыңызды түшүнөсүз.','Kogukonnast lohutuse leidmine 💬','Kas mõte „Miks mu laps on nii kangekaelne?“ närib sind? Liitu Anacani kogukonnaga. Kui loed teiste emade kodudes toimuvatest sarnastest absurdsetest kriisidest, mõistad, et sa pole üksi ja kasvatad täiesti normaalset, tervet last.'),
('c0b67368-8315-449a-b685-71a8e309a2c6'::uuid,'Алардын деминин жылуулугу 💖','Алар күнү бою ыйлап, сизди чарчатышты. Бирок азыр төшөктө көкүрөгүңүзгө жабышып, алардын ритмдүү, жылуу деми бөлмөнү толтуруп жатат. Бул энеликтин эң чоң сыйлыгы. Аларды бекем кучактап, ар бир дем алуу менен чарчооңуздун тарап баратканын сезиңиз.','Nende hingamise soojus 💖','Nad ajasid sind terve päeva hulluks, nuttes kõige peale. Aga nüüd, voodis vastu su rinda surutuna, täidab tuba nende rütmiline, soe hingamine. See on emaduse suurim tasu. Hoia neid lähedal ja tunne, kuidas kogu su väsimus iga hingetõmbega hajub.'),
('1d548457-d3f9-490c-889a-735e0fede3a4'::uuid,'Төшөккө көчүп баруу 🛏️','Алар туура жатып уктап, эртең менен буттары жаздыкта, башы төшөктүн карама-каршы бурчунда ойгонуштубу? Алар уйкусунда да дүйнөнү таанып жатышат! Аларды ойготордон мурун, алардын күлкүлүү «төшөк миграциясын» жылмайып карап коюңуз.','Rändamine voodisse 🛏️','Nad läksid magama korralikus poosis, aga ärkavad hommikul jalad padjal ja pea voodi vastasnurgas. Nad avastavad maailma isegi unes! Vaata nende naljakat voodirännet muigega, enne kui nad üles äratad.'),
('9fa8e885-34cc-4a52-b9b9-6155faa47396'::uuid,'Түнкү философиялык ойлор 🦉','Төшөккө жатар алдында эле «Апа, жылдыздар эмнеге кулабайт?» деген сыяктуу терең суроолорду берип жатышабы? Максат — илим үйрөнүү эмес, уйкуну кечиктирүү. Кыска, таттуу, ойдон чыгарылган жоопторду бериңиз жана акылдуу аудио жомоктор менен уктоо убактысын тынчтандырыңыз.','Hilisõhtused filosoofilised mõtisklused 🦉','Just siis, kui nad voodisse sätivad, küsivad nad sügavaid küsimusi nagu: „Emme, miks tähed alla ei kuku?“ Eesmärk pole teadust õppida, vaid und edasi lükata. Anna lühikesi, armsaid, väljamõeldud vastuseid ja too kohe magamamineku rahu nutikate audiolugudega.'),
('b5e65866-a678-4ef1-91b0-5f12331c2cae'::uuid,'Даярдыктан өтүп жаткан супербаатыр 🦸‍♂️','Алар үйдүн ичинде кышкы өтүк же супер баатырдын маскасы менен жүрүүнү талап кылып жатышабы? Коомдук нормаларды жана эстетиканы унутуңуз. Бул алардын өзүн-өзү таануу сапары. Өз бөлмөсүндө болсо да, өтүгү менен баатыр сезилишине жол бериңиз.','Superkangelane väljaõppel 🦸‍♂️','Kas nad nõuavad majas ringi käimist talvesaabastes või superkangelase maskis? Unusta ühiskondlikud normid ja esteetika. See on nende eneseavastamise teekond. Lase neil tunda end kangelasena oma saabastes, isegi kui see on vaid nende toas.'),
('0497aa5e-024a-43eb-ba38-bda044dfec73'::uuid,'Динозаврдын тиштери 🦖','Алар тиш жуугучту ыргытып, өз алдынча тиш жуудан баш тартып жатышабы? Муну оюнга айлантыңыз! Аларга кошумча щетка берип: «Кел, алгач оюнчук динозаврыңдын тишин жууйлу» деңиз. Алар динозаврдын тишин жууп жатканда, сиз дагы алардын тишин чеберчилик менен жууп коюңуз.','Dinosauruse hambad 🦖','Nad keelduvad kategooriliselt ise hambaid pesemast, visates harja minema. Muuda see mänguks! Anna neile varuhari ja ütle: „Peseme kõigepealt su mängudinosauruse hambaid.“ Samal ajal kui nad dinosaurust pesevad, pese kavalalt ka nende hambaid.'),
('2824815e-ab93-4e74-b868-7dee6ae3bcac'::uuid,'Башаламан тамактануу 🥣','Алар йогуртту вилка менен жейм деп өжөрлөнүп, баарын булгап жатышабы? Тоскоолдук кылбаңыз жана тартып албаңыз. Төгүлгөн тамакты тазаласа болот, бирок «мен өзүм жасай алам» деген ишенимди кайра куруу кыйын. Силикон алжапкычты тагып, бул көрүнүштү сабырдуулук менен байкаңыз.','Sassis söömaajad 🥣','Nad nõuavad absoluutselt jogurti söömist kahvliga, tehes tohutu segaduse. Ära sekku ega võta seda ära. Mahavalgunud toidu saab ära koristada, aga seda „ma saan ise hakkama“ enesekindlust on raske uuesti üles ehitada. Pane neile silikoonpõll ette ja jälgi kannatlikult stseeni.'),
('33c034f1-168d-424b-b367-21b9eb4799c9'::uuid,'Апанын баалуу он мүнөтү 🚪','Туруктуу ызы-чуу мээңизди уютуп койдубу? Маанай күндөлүгүңүздү ачыңыз жана бүгүн сизди жинди кылган нерселердин баарын экранга эркин төгүп, ички «кайра баштоо» баскычыңызды басыңыз.','Emme väärtuslikud kümme minutit 🚪','Pidev müra on su aju tuimestanud. Ava oma meeleolupäevik ja vala ekraanile kõik, mis sind täna hulluks ajas, vajutades oma sisemist nullimisnuppu.'),
('1fc95e57-80a1-42af-8907-c939c12adef9'::uuid,'Таштанды челегинин сыйкыры 📦','Көптөгөн кымбат, жаркыраган оюнчуктар турганда, алар бош пластик бөтөлкө же картон куту менен сааттап ойноп жатышабы? Баланын фантазиясына даяр сценарийлердин кереги жок; ал чыгармачылыкты ойготкон жөнөкөй нерселерден өсөт. Байкаңыз жана үйрөнүңүз.','Prügikasti võlu 📦','Kuigi saadaval on nii palju kalleid ja säravaid mänguasju, mängivad nad tunde tühja plastpudeli või pappkastiga. Lapse kujutlusvõime ei vaja valmis stsenaariume; see õitseb avatud esemetega, mis sütitavad loovust. Vaatle ja õpi.'),
('61bc311a-ba5b-43dc-b36e-6a65967f1df0'::uuid,'Уйку революциясы ☁️','Эртең менен ойгонору менен алар сизге кабагын түйүп карап жатышабы? Себеби? Түшүндө сиз аларга каалаган оюнчугун бербей койгон экенсиз! Баланын мээси түш менен чындыкты али толук ажырата албайт. Олуттуу түрдө кечирим сураңыз жана бул күлкүлүү кырдаалга ичиңизден жылмайып коюңуз.','Une-revolutsioon ☁️','Sel hetkel, kui nad hommikul ärkavad, kortsutavad nad kulmu ja on sinu peale pahased. Põhjus? Unes ei andnud sa neile soovitud mänguasja! Lapse aju ei suuda veel täielikult eristada und ja reaalsust. Vabanda tõsiselt ja naerata salaja sellele absurdsele olukorrale.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('c193e688-7d18-417e-aa1d-53580a727596'::uuid,'Жымжырттыктын кубанычы 🥂','Бала акыры уктады. Сиз жана жолдошуңуз диванда жанаша отурасыздар, сүйлөшүүгө да алыңыз жок. Бири-бириңиздерди унчукпай карап, жылмайып коёсуздар. Ооба, бул унчукпаган көз караш — «Биз бул башаламандыкты чогуу жеңип жатабыз» деп айтуунун эң кооз жолу.','Vaiksed rõõmuhetked 🥂','Laps on lõpuks magama jäänud. Sina ja su partner istute diivanil kõrvuti, olles liiga väsinud, et isegi rääkida. Vaatate lihtsalt vaikuses teineteisele otsa ja naeratate. Jah, see vaikiv pilk on kõige ilusam viis öelda: „Me vallutame selle kaose koos.“'),
('98f98e2b-5170-4983-96d7-fe8b44837cdf'::uuid,'Көлөкө оюнундагы укмуштуу окуялар 🐰','Алар уктоо убактысынан качуу үчүн караңгылыктан коркууну шылтоо кылып жатышабы? Бөлмөдөгү жарыктарды өчүрүп, фонарикти күйгүзүп, колуңуз менен дубалга канаттуулардын жана иттердин көлөкөсүн жасаңыз. Алар корккон караңгылык бир нече секундда алар үчүн дүйнөдөгү эң коопсуз театрга айланат.','Varjuteatri seiklused 🐰','Nad kasutavad pimedusehirmu ettekäändena, et vältida magamaminekut. Lülita toas kõik tuled välja, lülita sisse taskulamp ja tee kätega seinale linnu- ja koeravarje. Pimedus, mida nad kartsid, muutub sekunditega nende jaoks maailma kõige turvalisemaks teatriks.'),
('bf60fea7-a806-46ec-a023-ae8a1e62e95a'::uuid,'Парктан чыгуунун амалдары 🌳','Парктан кете турган убакыт келди, ый башталдыбы? Аларды сүйрөп кетүүгө аракет кылбаңыз. Тескерисинче, чакырык таштаңыз: «Ким машинага тезирээк чуркап жетет экен, көрөлү!» Балдар жарышка жана жеңишке жетүү мүмкүнчүлүгүнө эч качан «жок» дешпейт.','Pargist lahkumise strateegiad 🌳','On aeg pargist lahkuda ja nutuhood on alanud. Ära proovi neid vägisi kaasa vedada. Selle asemel loo väljakutse: „Vaatame, kes jõuab kiiremini autoni!“ Lapsed ei ütle kunagi ära võiduajamisest ja võimalusest võita.'),
('e6013d08-4f44-4955-a2ce-c8556d1e2010'::uuid,'Көрүнбөгөн конок 👻','Эртең мененки тамакта алар сизден элестеткен досу үчүн да өзүнчө табак коюуну талап кылышат. Бул психологиялык көйгөй эмес, бул акыл-эстин өнүгүүсүндөгү чоң секирик! Ошол табакты коюп, коногуңузга элестеткен чайдан куюп бериңиз, бул кереметтүү оюндун бир бөлүгү болуңуз.','Nähtamatu külaline 👻','Hommikusöögi ajal nõuavad nad, et kataksid laua ka nende kujuteldavale sõbrale. See pole psühholoogiline tühimik, vaid hüpe intelligentsuses! Pane see taldrik lauale ja vala külalisele kujuteldavat teed, saades osaks sellest suurepärasest teatrist.'),
('07a807e7-5500-4214-ab98-d5372a84c109'::uuid,'Командалык ишке алкыш! 🥂','Дагы бир оор жана түйшүктүү күндү артта калтырдыңыз. Кичинекейиңиз уктагандан кийин, өнөктөшүңүз менен бир чыны чай ичип, бири-бириңизге: «Биз бүгүнкү башаламандыкты жеңдик; биз эң сонун командабыз!» деп айтыңыз. Ата-энелик милдетти жалгыз аткаруу үчүн эмес, колдоо менен бирге аткаруу үчүн жаралган.','Elagu meeskonnatöö! 🥂','Oled üle elanud järjekordse väljakutseid pakkuva ja tormilise päeva. Kui väike on uinunud, valage partneriga tass teed ja tõdage: „Me tulime sellest kaosest täna läbi; oleme suurepärane meeskond!“ Lapsevanemaks olemine ei ole mõeldud üksi tegemiseks; see õitseb toetuse najal.'),
('7715199a-4ef6-480d-9548-a833acc549dd'::uuid,'Өжөр бут кийим 👟','Алар бут кийимдерин тескери кийип алышса да, дүйнөнү багындыргандай сыймык менен басып жүрүшөт. Эгер сиз кийлигишип, аны оңдоого аракет кылсаңыз, баары бузулат. Алардын өзүнө болгон ишеними жана көз карандысыздыгы сырткы көрүнүштөн маанилүүрөөк. Бул кичинекей козголоңчунун сыймык менен басышына жол бериңиз.','Kangekaelne jalanõu 👟','Nad on pannud kingad valesse jalga, kuid kõnnivad sellise uhkusega, nagu oleksid vallutanud maailma. Kui sekkud ja proovid seda parandada, on kõik rikutud. Nende enesekindlus ja iseseisvus on tähtsamad kui esteetika. Lase sel väikesel mässajal uhkelt sammuda.'),
('b205ec5f-9776-4abd-8a5c-b967e050819e'::uuid,'Ашканадагы тентектиктер 🧑‍🍳','Сиз камыр жууруп жатканда, балаңыз келип, колун унга малып, айлананын баарын ак кылып салат. Ооба, ашкана башаламан болуп калды. Бирок ошол олуттуу, алек болгон кичинекей жүзүн дароо сүрөткө тартып алыңыз. Тазалоо иштери бүтөт, бирок ал күлкүлүү сүрөт түбөлүккө калат.','Köögikoomika 🧑‍🍳','Rullid tainast ja su laps tuleb ligi, pistab käe jahusse, tehes kõik valgeks. Jah, köök on sassis. Aga jäädvusta see tõsine ja tegus väike nägu kohe beebifotosessiooniga. Koristamine saab tehtud, kuid see naljakas hetkepilt jääb igaveseks.'),
('18bd2439-9788-43c4-81c5-8852d0241a0d'::uuid,'Тирүү күзгү 🦜','Алар оюнчугун урушуп жатканда, сиз ачууланганда жасаган бет түзүлүшүңүздү дал өзүндөй кайталашат. Өзүңүздү сырттан карап көрүңүз! Алар көргөн нерсенин баарын туурашат. Бул күлкүлүү, бирок ойлондурарлык көрүнүш — өз жүрүм-турумуңузга көбүрөөк көңүл буруу үчүн сонун күзгү.','Elav peegel 🦜','Nad riidlevad oma mänguasjaga, tehes täpselt samu näoilmeid, mida sina vihasena. Vaatle end kohe kõrvalt! Nad kopeerivad kõike, mida näevad. See naljakas, kuid mõtlemapanev stseen on sulle suurepärane peegel, et oma käitumisele rohkem tähelepanu pöörata.'),
('57b60f69-46b8-4792-b8f6-95c7ec477f5b'::uuid,'Бул сыйкырдуу окуядагы менин ролум 🪄','Бардык классикалык китептерди жаттап алып, аларды окуудан тажадыңызбы? Акылдуу аудио жомокторду ачыңыз. Балаңызды башкы каарман кылып, фондо токойдун тынчтандыруучу үндөрү менен уникалдуу жана жеңил уйку сессиясын түзүңүз.','Minu roll selles võluloos 🪄','Oled kõik klassikalised raamatud pähe õppinud ja oled nende lugemisest väsinud. Pane mängima nutikad audiolood. Kujunda ainulaadne ja pingevaba uneaeg, tehes oma lapsest peategelase, taustaks rahustavad metsahelid.'),
('8391ff6e-4225-4aa9-9011-6c07f64cfe8a'::uuid,'Таза абадагы көңүл ачуу ⛅','Аба ырайын жана алардын кийимин текшерип, сөзсүз түрдө сыртка алып чыгыңыз. Кургак бутактарды жана таштарды чогултуу сыяктуу жөнөкөй тапшырма менен сиз аларга энергиясын чыгарууга жардам бересиз, ал эми өзүңүз төрт дубалдан чыгып, терең дем аласыз.','Värske õhu rõõmud ⛅','Kontrolli ilma ja nende riietust, siis mine nendega kindlasti õue. Lihtsa ülesandega, nagu kuivanud okste ja kivide korjamine, aitad neil energiat vabastada ning pääsed nelja seina vahelt välja sügavalt hingama.'),
('267b7226-68df-4c3e-8db0-91462616e5aa'::uuid,'Жымжырттыктын өзүнүн тили бар 🤫','Алар акыры укташты! Бөлмөнү жыйноого шашпаңыз. Үн өлчөгүчүңүздү иштетип, экрандагы 0-10 децибелдик көрсөткүчтү караңыз. Үйдөгү абсолюттук тынчтыктын визуалдык тастыкталышы чарчаган мээңиз үчүн эң сонун массаж сыяктуу сезилет.','Vaikus ütleb nii mõndagi 🤫','Nad on lõpuks magama jäänud! Ära kiirusta tuba koristama. Aktiveeri helimõõtja ja vaata ekraanilt seda 0–10 detsibelli näitu. Visuaalne kinnitus täielikust vaikusest majas tundub kui kõige imelisem massaaž sinu väsinud ajule.'),
('9a9573ec-71e1-4545-84fd-a3a1f5b2af6b'::uuid,'Кичинекей философ 🧐','Алар «Апа, күн эмне үчүн ал жерде?» деп эмес, жөн гана «Күн эмне үчүн бар?» деп сурашат. Алардын суроолору барган сайын абстракттуу болуп баратат. Илимий түшүндүрмө берүү үчүн мээңизди чарчатпаңыз. «Анткени ал бизди жылытканды жакшы көрөт» деген сыяктуу кыска, жомок сымал жана жылуу жооп аларды толугу менен канааттандырат.','Väike filosoof 🧐','Nad ei küsi „Emme, miks päike seal on?“, vaid lihtsalt „Miks päike on?“. Nende küsimused muutuvad üha abstraktsemaks. Ära väsita oma aju tundidepikkuste teaduslike selgituste otsimisega. Lühike, muinasjutuline ja soe vastus, nagu „Sest talle meeldib meid soojas hoida“, rahuldab neid täielikult.'),
('c8cadde3-c829-4a73-89c2-d28ffc494046'::uuid,'Эс алуудагы буттар 🚶‍♂️','Балаңыз күтүлбөгөн жерден көчөнүн ортосуна отуруп алып, буту сынып калганын айтып, көтөрүп жүрүүнү талап кылат. Жок, алар чарчаган жок; алар жөн гана сиздин чыдамыңызды сынап жатышат! Драмага алдырбаңыз. Тескерисинче, аны оюнга айландырыңыз: «Кел, кичинекей пингвиндердей болуп машинага чейин басып баралы!»','Jalad puhkusel 🚶‍♂️','Su laps kukub äkki keset tänavat maha, väites, et jalad on katki ja nõudes süles kandmist. Ei, nad ei ole väsinud; nad lihtsalt katsetavad sinu piire! Ära draamale järele anna. Selle asemel muuda see mänguks: „Vagugem nagu väikesed pingviinid auto juurde!“'),
('d2c59147-ed1d-426c-a22f-74bab5a93a1b'::uuid,'Түстүү тамактарды жегиле 🥕','Бүгүн кичинекейиңиз бир гана кызгылт сары түстөгү тамактарды жейм деп чечип, калганын четке кагууда. Ооба, бөбөктөрдүн логикасы ушундай! Жашылчаларды пайдалуу тамактарга кантип жашыруун кошууну үйрөнүңүз. Ашкабак жана сабиз пюреси кошулган даамдуу тамактар менен бул тандалмалыкты жеңиңиз.','Söö vikerkaart 🥕','Täna on su väike otsustanud, et ainult oranžid toidud on vastuvõetavad, lükates kõik muu tagasi. Ah, väikelapse loogika oma parimas vormis! Avasta, kuidas köögivilju tervislikes retseptides nutikalt maskeerida. Võida see pirtsakus maitsvate roogadega, milles on kõrvitsa- ja porgandipüreed.'),
('d7d30904-6d53-4964-8b13-c4680a8d7346'::uuid,'Эртең мененки жалгыз аткаруучу 🎤','Эртең менен али таң ата электе, сиз көзүңүздү араң ачып жатканда, алар колуна оюнчук алып, бөлмөнүн ортосунда концерт берип жатышат. Аларды тынчтандырууга аракет кылбаңыз. Балдардын бул жапайы, чексиз энергиясы үйгө береке жана кубаныч алып келет. Аларды карап жылмайып гана коюңуз.','Hommikune solist 🎤','On alles varahommik ja kuigi vaevu silmi avad, annavad nad juba keset tuba mänguasjaga kontserti. Ära proovi neid vaigistada. See laste metsik ja piiritu energia toob tegelikult koju õnnistust ja rõõmu. Lihtsalt naerata, kui neid vaatad.'),
('e2fc49a4-e751-47d3-a247-fa5b6429b0ca'::uuid,'Сылоонун айыктыруучу күчү 💆‍♂️','Алар төшөктө жаткысы келбей жатышат. Жомокторду жана музыканы четке коюңуз. Алардын кичинекей буттарына же аркасына абдан жеңил, тынчтандыруучу массаж жасаңыз. Денеге тийүү сиздин да, алардын да денесиндеги кортизолду (стресс гормонун) дароо азайтып, уйкуну чакырат.','Puudutuse tervendav vägi 💆‍♂️','Nad lihtsalt ei jää voodis rahulikuks. Jäta lood ja muusika kõrvale. Tee neile väga kerge ja rahustav massaaž väikestele jalgadele või seljale. Füüsiline puudutus vähendab koheselt kortisooli (stressihormooni) nii nende kui ka sinu kehas, tuues une.'),
('297d6ab5-a5e9-4978-98b2-bd85528e89d5'::uuid,'Көрүнбөгөн башаламандык 🧹','Кичинекейиңиз кичинекей шыпыргы менен килемдеги көрүнбөгөн чаңдарды кылдаттык менен тазалап жатат, жүзүндө абдан олуттуу көрүнүш. Алар жөн гана сизди туурап жатышат! Бул сүйкүмдүү, жоопкерчиликтүү учурду сүрөткө тартып алыңыз – эң кичинекей жана эң таттуу жардамчыңыз иштеп жатат!','Nähtamatud segadused 🧹','Su väike puhastab vaibalt väga tõsise näoga nähtamatut tolmu väikese harjaga. Nad lihtsalt jäljendavad sind! Jäädvusta see armas ja vastutustundlik hetk beebifotosessiooniga – kõige väiksem ja armsam abilistest on tööl!'),
('79e7bb66-f1dd-4164-bbd9-7c802b073b10'::uuid,'Тынчтандыруучу үн терапиясы 🤫','Үйдөгү ал кичинекей бороон акыры уйкуга моюн сунду. Бөлмөдө идиш жуугучтун үнүнөн башка эч нерсе жок. Үн өлчөгүчүңүздү ачып, экрандагы минималдуу децибел сандарын карап, көзүңүздү жумуңуз. Бул визуалдык тынчтык мээңиз үчүн эң жакшы массаж.','Rahustav heliteraapia 🤫','See väike keeristorm majas on lõpuks unele alistunud. Toas pole muud kui nõudepesumasina heli. Ava oma helimõõtja, vaata ekraanil neid minimaalseid detsibellinumbreid ja sule silmad. See visuaalne vaikus on su ajule parim massaaž.'),
('fee25f48-2972-4bf2-9d26-d0fbea33a7f3'::uuid,'Мышыктын ойготуу чакырыгы 🐾','Бүгүн эртең менен кичинекейиңиз адам эмес! Алар төрт аяктап басып, бутуңузга сүйкөнүп, «мяу» деп гана сүйлөшүп жатышат. Бул алардын элестетүүсүнүн эң таттуу учуру. Эрежелерди коюунун ордуна, аларга элестеткен сүт идишин сунуштап, оюнга кошулуңуз.','Kassilik äratus 🐾','Täna hommikul pole su väike inimene! Nad kõnnivad neljakäpukil, hõõruvad vastu su säärt ja suhtlevad ainult näugudes. See on nende kujutlusvõime kõige armsam tipphetk. Selle asemel, et reegleid seada, ühine lõbuga, pakkudes neile kujuteldavat kausitäit piima.'),
('0d53c056-84aa-4820-a905-2f2e60542791'::uuid,'Коомчулуктун сырлары 💬','Бүгүн бардык нерсеге кыйкырып, дүйнөдөгү эң чыдамсыз энедей сезилип жатасызбы? Сиз жалгыз эмес экениңизди билиңиз. Anacan коомчулугуна кошулуп, башка энелердин да ушундай чарчаганын окуп, ичиңиздеги «жаман эне» деген күнөөнү басыңыз.','Kogukonna pihtimused 💬','Kas avastasid end täna kõige peale karjumast, tundes end maailma kõige kannatamatuma emana? Palun tea, et sa pole üksi. Liitu Anacani kogukonnaga ja loe, kuidas teised emad tunnevad end sama kurnatuna, vaigistades seda närivat ematunde süümepiina.'),
('844a3d1a-225d-46c7-945c-c5eaf88248c4'::uuid,'Атамдын кызыктуу жомоктору 📖','Бүгүн кечинде үнүңүз эс алсын. Жомок китебин атасына бериңиз жана ал жомокту атайылап тескери, күлкүлүү жана абсурддуу түрдө айтып берсин. Балаңыздын аны оңдоп жатканына жана атасына күлгөнүнө четтен карап ырахат алыңыз.','Issi pöörased ja naljakad lood 📖','Täna õhtul saab su hääl puhkust. Anna juturaamat issile ja lase tal lugu tahtlikult tagurpidi, naljakal ja absurdsel viisil jutustada. Vaata kõrvalt, kuidas su laps naudib tema parandamist ja issi üle itsitab.'),
('c862c51e-5b03-4e55-bd66-35165e58d3d8'::uuid,'Авангарддык архитектор 🥞','Эртең мененки тамакта алар куймактарды мунара кылып тизип, ортосуна тешик жасап, манжасын тыгып жатышат. Тамак менен ойноо алар үчүн жаңы инженердик долбоор. Башаламандыкка жол бериңиз; алар тамактын түзүлүшүн изилдеп жатышат!','Avangardistlik arhitekt 🥞','Hommikusöögi ajal laovad nad pannkookidest torni, torkavad keskele augu ja pistavad sõrme läbi selle. Toiduga mängimine on nende jaoks uus inseneriprojekt. Lase segadusel sündida; nad uurivad toidu tekstuuri!'),
('772055c7-02e3-4df1-ab25-b0a7ed011afe'::uuid,'Элестетүүдөгү оюн дүкөнү 🍅','Бөлмөнүн бир бурчунда алар оюнчуктарын тизип, сизге элестеткен помидорлорду элестеткен акчага сатып жатышат. Бул соода оюнунда абдан олуттуу болуңуз! Ошол элестеткен помидорду сатып алып жаткандай болуп, чоң ырахат менен жеңиз. Ролдук оюндар алардын социалдык интеллекти жана математикалык логикасы үчүн күчтүү негиз болуп саналат.','Kujuteldav toidupood 🍅','Toanurgas on nad üles seadnud oma mänguasjad ja müüvad sulle kujuteldava raha eest kujuteldavaid tomateid. Ole selles ärimängus väga tõsine! Tee nägu, et ostad selle kujuteldava tomati ja söö seda suure isuga. Rollimäng on võimas vundament nende sotsiaalsele intelligentsusele ja matemaatilisele loogikale.'),
('9c4fcd9f-eca4-4781-b7b6-58a379dc2126'::uuid,'Апанын жашыруун шоколады 🍫','Апа, ашкана шкафынын артында шоколад жеп жатасызбы – ал глюкоза сиздин толук укугуңуз! Күн бою чексиз энергия жана бүтпөгөн «эмне үчүн» деген суроолор менен күрөшүү үчүн сизге сөзсүз түрдө энергия топтоо керек. Терең дем алып, ар бир тиштегенден ырахат алыңыз.','Emme salajane šokolaad 🍫','Emme, šokolaaditüki näppamine köögikapi taga – see glükoos on sinu täielik õigus! Et tulla toime kogu selle piiritu energia ja lõputute „miks“-küsimustega päeva jooksul, pead sa end kindlasti laadima. Hinga sisse ja naudi iga suutäit.'),
('a0a70ea3-00c4-4338-848e-bcb45a1157ff'::uuid,'Түнкү коркунучтар 😭','Алар түн ортосунда көздөрү жумулуу, эч кимди тааныбай ыйлап ойгонушат. Ыйдын анализи менен текшериңиз; эгер бул түнкү коркуу болсо, аларды силкип же ойготууга аракет кылбаңыз. Жөн гана жанында унчукпай туруп, сооротуңуз, ал өтүп кетет.','Öised hirmuhood 😭','Nad ärkavad keset ööd nuttes, silmad ikka kinni, olles teistest justkui teadmatud. Kontrolli nutuanalüüsiga; kui see on öine hirmuhoog, ära raputa neid ega proovi äratada. Seisa lihtsalt vaikselt kõrval, pakkudes lohutust, ja see läheb mööda.'),
('2d19f095-845a-4bde-a575-de7451355856'::uuid,'Муздак логика 🥶','Алар муздаткычты ачып, муз идишин талап кылышат жана колдору тоңсо да коё беришпейт. Алар денеси менен ысык жана муздакты сезүүнү сынап жатышат. Бул ачылышты кичинекей илимий экспериментке айлантыңыз: бир идишке жылуу, экинчисине муздак суу куюңуз, ошондо алардын өжөрлүгү дароо жоголот.','Jääkülm loogika 🥶','Nad avavad külmkapi, nõuavad jääalust ega lase lahti, isegi kui käed külmetavad. Nad katsetavad oma kehaga kuuma ja külma tajumist. Muuda see avastus väikeseks teaduskatseks: pane ühte kaussi leiget vett ja teise jääkülma vett ning nende jonnakus sulab silmapilkselt.'),
('5b70990d-933c-46b2-be30-1407db2c7b1b'::uuid,'Жаратылышка маанилүү качуу ⛅','Үйдө камалып калганда, алардын энергиясы агрессияга айланып, ар бир сүйлөм «жок» деп башталышы мүмкүн. Аба ырайына карабай, аларды ылайыктуу кийинтип, сыртка алып чыгыңыз. Жерге тийүү алардын нерв системасын дароо калыбына келтирүүгө жардам берет.','Hädavajalik põgenemine loodusesse ⛅','Siseruumidesse suletuna võib nende energia muutuda agressiivsuseks ja iga lause algab sõnaga „ei“. Sõltumata ilmast, riieta nad sobivalt ja mine õue. Maa puudutamine aitab nende närvisüsteemi koheselt lähtestada.'),
('72b51261-3fd9-4ba4-a07e-a52ab32038d0'::uuid,'Түнкү чырак 🌙','Уктоочу бөлмөнүн жарыгы өчкөндө алар тынчсызданышабы? Бөлмөнүн бир бурчуна кичинекей, жылуу түстөгү (кызгылт сары же кызыл) түнкү чырак коюңуз. Бирок бөлмөнүн калган бөлүгү мелатонин өндүрүшүн жана терең уйкуну колдоо үчүн толугу менен караңгы бойдон калышы керек.','Öölamp 🌙','Kas nad muutuvad ärevaks, kui magamistoa tuled kustuvad? Pane toa ühte nurka väike soojatooniline (oranž või punane) öölamp. Ülejäänud tuba peaks aga jääma täiesti pimedaks, et toetada melatoniini tootmist ja sügavat und.'),
('0bee47e7-94df-4d8c-b500-e8adc690d1ff'::uuid,'Сиздин санариптик тизме жардамчыңыз 🛒','Дүкөндүн ортосунда туруп: «Мен бул жакка эмне үчүн келдим эле?» деп ойлонуп жатасызбы? Эненин мээси миллиондогон нерселерди бир убакта аткарып жатат! Тиркеменин «Соода тизмесине» керектүү нерселерди пайда болгон замат жазып коюуну адат кылыңыз жана акыл-эсиңиздеги жүктү жеңилдетиңиз.','Sinu digitaalne päästerõngas 🛒','Avastad end keset toidupoodi seismas ja mõtled: „Mida ma siia tegema tulin?“ Emme aju žongleerib juba miljoni asjaga! Tee harjumuseks kirjutada vajadused äpi ostunimekirja kohe, kui need tekivad, ja kergenda oma vaimset koormat.'),
('7574c80e-2022-481c-9e84-dd04a5dc3520'::uuid,'''Мен жардам берейин!'' деген кырсык 🧽','Идиш жууп жатканыңызда, балаңыз отургучту сүйрөп келип, суу менен ойногусу келеби? Чындыгында алар жардам бергиси келбейт, алар окуянын чордонунда болгусу келет. Ага кичинекей пластик идиш жана губка бериңиз. Ашкана бир аз чачылышы мүмкүн, бирок балаңыздын өзүнө болгон ишеними жана сыймыгы артат.','„Lase ma aitan!“ äpardus 🧽','Kui nõusid pesed, kas nad nõuavad tooli toomist ja veega mängimist? Tegelikult ei taha nad aidata, nad tahavad olla sündmuste keskpunktis. Anna neile väike plastkauss ja käsn. Köök võib küll segamini minna, aga nende eneseuhkus kasvab suureks.'),
('ed6ba029-b0b0-4d21-8825-996dcfdf7f9e'::uuid,'Музыканын сыйкырдуу жыштыгы 🎶','Кечинде себепсиз эле ыйлап, кыяшаланып жатабы? Жай классикалык музыка менен маанайды жумшартып көрүңүз. Көбүнчө бул жөнөкөй, бирок натыйжалуу ыкма бөлмөдөгү чыңалууну сыйкырдуу түрдө жок кылып, балаңызды терең тынчтыкка бөлөйт.','Muusika maagiline sagedus 🎶','Kas lapsel on seletamatud õhtused jonnihood ja nutukrambid? Proovi tormi vaigistada rahuliku klassikalise muusikaga. Tihti muudab see lihtne, kuid tõhus nipp ruumi pingelise õhkkonna maagiliselt rahulikuks, mähkides lapse sügavasse rahu.'),
('df056dc0-b341-46d5-89e8-51170248ba0c'::uuid,'Кийим шкафынын инженери 👗','Бүгүн ал ар башка түстөгү байпак жана тескери кийилген футболка менен сыртка чыккысы келип жатабы? Коомдун калыптанып калган эрежелерин унутуңуз. Өз тандоосун жасоо жана аны коргоо эркиндиги — түстөрдү дал келтирүүдөн алда канча маанилүү жашоо сабагы. Аларга уруксат бериңиз!','Garderoobiinsener 👗','Täna tahavad nad välja minna eri värvi sokkide ja pahupidi särgiga. Unusta ühiskonna normid. Vabadus teha oma valikuid ja neid kaitsta on palju suurem elutund kui värvide sobitamine. Lase neil seda teha!'),
('ed70e165-6613-45b8-9098-e5a1501e357a'::uuid,'Бейпилдик үчүн AI 🤖','Балаңыздын 3,5 жаш курагындагы катуу эмоционалдык өзгөрүүлөрү сизди тынчсыздандырып жатабы? Коркунучтуу, стресске салган интернет форумдарын жабыңыз! Бул курактык кризистер тууралуу илимий жана психологиялык жактан негизделген, тынчтандыруучу жоопторду Anacan AI аркылуу алыңыз.','AI meelerahu heaks 🤖','Kas lapse intensiivsed emotsionaalsed muutused umbes 3,5-aastaselt tekitavad sinus ärevust? Pane need hirmutavad ja traumeerivad internetifoorumid kinni! Küsi Anacan AI-lt teaduslikult ja psühholoogiliselt põhjendatud rahustavaid vastuseid nende eakohaste kriiside kohta.'),
('fd525f60-163f-4a76-b89b-734831b1ea09'::uuid,'Окуяны өздөрү жазсын 🪄','Күнүмдүк жомоктордон тажадыңызбы жана бөлмөдөгү маанай бир аз зериктирүүчү болуп жатабы? Бүгүн кечинде акылдуу жомокторду (импровизацияланган окуяларды) ачып, балаңызды сюжеттин режиссёру кылыңыз. «Учуучу машина андан кийин кайда барышы керек?» деп сураңыз жана алардын кыялында жаңы дүйнөлөрдү багындырып, уктап кетишине шарт түзүңүз.','Lase neil lugu kirjutada 🪄','Tüdinenud tavalistest unejuttudest ja tuba tundub igav? Ava täna õhtul oma nutikad lood (improviseeritud jutud) ja lase lapsel olla süžee lavastaja. Küsi: „Kuhu lendav auto järgmisena sõidab?“ ja lase neil uinuda, vallutades oma kujutlusvõimes uusi maailmu.'),
('cb4b4d68-2b36-4d3f-aa77-92d10314464f'::uuid,'Жаңы тамактар, жаңы заңдар 💩','Кечээ ал жаңы же аллергия бериши мүмкүн болгон тамак жедиби? Эртең менен жалаягын алмаштырып жатканда, заңына көз салыңыз жана абалын көзөмөлдөө үчүн түсүнүн же консистенциясынын өзгөрүшүн тиркемеде белгилеп туруңуз.','Uued toidud, uued mähkmed 💩','Kas nad sõid eile midagi uut või potentsiaalselt allergeenset? Hommikust mähet vahetades jälgi lapse väljaheidet ja märgi äppi kõik värvi või konsistentsi muutused, et tema seisundit jälgida.'),
('4cc9dfab-73bb-408b-8fd7-0cdb3ba02840'::uuid,'Шыбырдын гипнозу 🤫','Ал төшөктө бутун көккө көтөрүп, уктагысы келбей жатабы? Үнүңүздү көтөрүүнүн ордуна, күтүлбөгөн жерден акырын, шыбырап сүйлөй баштаңыз. Балаңыз сизди угуш үчүн кулак төшөгөндө, анын мээси автоматтык түрдө гипноздолуп, уйку режимине өтөт.','Sosinate hüpnoos 🤫','Nad lamavad voodis, jalad püsti, ja keelduvad kategooriliselt magamast. Selle asemel, et häält tõsta, langeta see äkitselt ja räägi vaid sosinal. Kui laps pingutab, et sind kuulda, muutub tema aju automaatselt hüpnotiseerituks ja lülitub unerežiimile.'),
('815c8c47-103f-4098-9702-cdb4705b486d'::uuid,'Апанын офлайн учуру 🛋️','Балаңыз мультфильмге же оюнчуктарына алаксып жатканда, идиш жуугучту бошотууга же кир жаюуга шашыласызбы? Токтоңуз! Ошол 10 мүнөттү диванга жатып, шыпты карап, эч нерсе жөнүндө ойлонбой өткөрүңүз. Сиз робот эмессиз.','Emme võrguvaba hetk 🛋️','Kas tormad nõudepesumasinat tühjendama või pesu riputama kohe, kui nad on multikatesse või mänguasjadesse süvenenud? Peatu! Veeda need 10 minutit lihtsalt diivanil lamades, lakke vaadates ja mitte millestki mõeldes. Sa ei ole robot.'),
('ac5c326d-30b1-4f87-8420-9236c8047849'::uuid,'Бүтпөгөн сүйлөмдөрдү толуктоо 🗣️','Ал сөздү унутуп калганда, колу менен ишарат кылып, кашын түйүп, сизден жооп күтөбү? Анын сөз байлыгы өсүп жатат, бирок мээси тилинен тезирээк иштеп жатат. Сүйлөмүн аягына чыгарганда, анын жүзүндөгү «аа, мен ушуну айткым келген!» деген жеңилдикти байкаңыз.','Poolikute lausete lõpetamine 🗣️','Kui nad sõna unustavad, žestikuleerivad nad kätega, kortsutavad kulmu ja ootavad, et sa selle ära arvaksid. Nende sõnavara kasvab, kuid aju töötab lihtsalt kiiremini kui keel. Jälgi seda kergendustunnet nende näol, kui nad lõpuks lause lõpetavad ja sa aru saad.'),
('7eaa01a6-6e1b-4778-9360-22935e0a6bcc'::uuid,'Тамактануу дизайнери 🥦','Балаңыз тамагын түсүнө жана формасына карап бөлүп, жашылчаларды четке түртүп жатабы? Биздин пайдалуу рецепттерибизди колдонуңуз! Жашылчаларды кантип байкалбаган пюреге айлантып, даамдуу соустарга жашырууну үйрөнүңүз жана тамактануу оюнунда жашыруун жеңишке жетиңиз.','Söömaaja disainer 🥦','Laps sorteerib taldrikul toitu värvi ja kuju järgi, lükates kõik rohelise kõrvale. Sukeldu meie tervislikesse retseptidesse! Avasta, kuidas nutikalt muuta köögiviljad nähtamatuteks püreedeks ja peita need maitsvatesse kastmetesse, võites salaja selle söömisvõitluse.'),
('91e22232-e032-41dd-a3bf-200483eec697'::uuid,'Атамдын ат болуп ойунтушу 🐴','Ал энергиясын толук сарптай албай, уктоодон баш тартып жатабы? Атасын жардамга чакырыңыз! Атасы аны аркасына мингизип же «ат чабыш» ойноп жатканда, бөлмөнү күлкүгө толтуруп, топтолгон физикалык стресс жана чексиз энергия секунданын ичинде жок болот да, ал кубаныч менен чарчап уктап калат.','Issi hobusesõit 🐴','Nad pole oma energiat täielikult välja elanud ja tõrguvad magamaminekuga? Kutsu issi appi! Kui ta teeb neile kukil sõitu või mängib „hobust“, täitub tuba naeruga ning kogu kogunenud füüsiline pinge ja piiritu energia kaovad sekunditega, kui nad end rõõmsalt väsitavad.'),
('f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5'::uuid,'Кооптуу сөздөр 🤐','Ал көчөдөн же телевизордон уккан жаман сөздү кайталап, сиздин реакцияңызды күтүп күлүп жатабы? Сиздин эң чоң куралыңыз — эч кандай реакция кылбоо. Күлбөңүз, ачууланбаңыз, жөн гана көңүл бурбаңыз. Ал көп өтпөй ал сөздү унутуп калат.','Ohtlikud sõnad 🤐','Nad naeravad, korrates seda halba sõna, mida kuulsid tänaval või telerist, oodates põnevusega sinu reaktsiooni. Sinu suurim relv on mitte reageerida. Ära naera, ära vihasta, lihtsalt ignoreeri. Nad unustavad selle sõna peagi.'),
('07324b19-8c8c-4d15-8c79-0b07b4d8c8cf'::uuid,'Ваннадагы океан 🌊','Чоюнуу убактысы эми жөн гана тазалануу эмес, толкун жаратуу оюну! Сууну чачыратууга уруксат бериңиз, ванна бөлмөсү бир аз суу болсо болсун. Суунун сыйкырдуу таасири күн бою топтолгон бардык терс энергияны жууп, агындыга агызып кетет.','Ookean vannis 🌊','Vanniskäik pole enam ainult pesemine, see on lainete tegemise mäng! Lase veel pritsida, lase vannitoal veidi märjaks saada. Vee magnetiline toime peseb maha kogu päeva jooksul kogunenud kangekaelse negatiivse energia, saates selle otse äravoolust alla.'),
('501e8f67-b2b7-4164-9b32-0326fabd781c'::uuid,'Эшик артындагы сырлар 🚪','Ал өз бөлмөсүнө кирип, эшикти жаап, жалгыз калгысы келеби? Бул анын жеке мейкиндигинин жана инсандыгынын калыптанышы. Коопсуздук чараларын көрүңүз жана ага бул кичинекей жеке укукту бериңиз. Ал чоңоюп жатат!','Uksetagused saladused 🚪','Kas nad tahavad minna oma tuppa, ukse enda järel sulgeda ja omaette olla? See on nende isikliku ruumi ja individuaalsuse taju tekkimine. Võta tarvitusele ohutusabinõud ja anna neile see väike privaatsuse õigus. Nad kasvavad suureks!'),
('9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7'::uuid,'Маанай күндөлүгүндөгү моюнга алуулар 📝','Телефонуңузду алыңыз. Социалдык тармактардагы идеалдуу жашоолорду карап отурбай, «Маанай күндөлүгүн» ачып, бүгүнкү күндөгү эң күлкүлүү учурду — сизди эң көп күлдүргөн окуяны жазып коюңуз. Муну жазуу — терапиянын эң таза түрү.','Ülestunnistused meeleolupäevikus 📝','Võta telefon kätte. Selle asemel, et kerida sotsiaalmeedias näiliselt täiuslikke elusid, ava oma meeleolupäevik ja pane kirja tänane kõige naljakam hetk – see, mis sind kõige rohkem naerma ajas. Kirjapanek on kõige puhtam teraapia vorm.'),
('4acc88e2-20b2-4215-8fcd-8a14393b92b9'::uuid,'Экөө үчүн тост 🥂','Бала уктады. Шампан ичүү мүмкүнчүлүгү болбосо да, жубайыңыз менен жылуу чай куюп, стакандарыңызды кагыштырып: «Биз дагы бир бороондуу күндү жеңдик!» деп айтыңыз. Экөөңүздөр тең бул үйдүн командири жана ажырагыс командасыздар.','Tervitus kahele 🥂','Laps magab. Isegi kui šampanja pole valik, valage endale sooja teed ja lööge partneriga klaase kokku, öeldes: „Me elasime veel ühe tormilise päeva üle!“ Olete mõlemad selle kodu komandörid ja vankumatu meeskond.'),
('4b9f4b0d-becb-4db4-85ec-0a0caae64162'::uuid,'Логикасыз көз жаш 🐶','Көчөдө көргөн ит ага карабай койгону үчүн же жалбырак жерге түшкөнү үчүн ыйлап жибердиби? Бул кырдаалдан логика издебеңиз. Ал үчүн бул чыныгы терең кайгы. Жөн гана анын сезимдерин колдоп: «Билем, сен ал иттин сага карашын абдан каалагансың» деп айтыңыз.','Ebaloogilised pisarad 🐶','Kas nad puhkesid nutma, sest tänaval nähtud koer ei vaadanud nende poole või leht kukkus maapinnale? Ära otsi siit loogikat. Nende jaoks on see tõeline sügav kurbus. Lihtsalt kinnita nende tundeid, öeldes: „Ma tean, sa tõesti tahtsid, et see koer sind vaataks.“'),
('9ae0817a-4137-49f1-8c45-fb16cc1d750b'::uuid,'Оюн аянтчасындагы дипломатия 🤝','Балаңыз слайдда өзү ойногусу келип, башка баланы түртүп жибердиби? Бөлүшүү — бул алар али толук өздөштүрө элек татаал түшүнүк. Уяткаруунун же жазалоонун ордуна, аянтчанын эрежелерин эскертип: «Азыр анын кезеги» деп айтыңыз.','Mänguväljaku diplomaatia 🤝','Kas laps lükkas liumäel teist last, tahtes ise minna? Jagamine on endiselt keeruline mõiste, mida nad pole veel päriselt omandanud. Selle asemel, et häbistada või karistada, tuleta neile lihtsalt mänguväljaku reegleid meelde: „Praegu on teise kord.“'),
('23303195-392c-42b3-a778-b5f932e7d2fb'::uuid,'Денеңиздин үнү 🩸','Себепсиз кыжырданууга жана чарчоого алдырбаңыз. «Этек кир календарын» текшериңиз — денеңиз бир нерседен кабар берип жаткан болушу мүмкүн! Өзүңүздү күнөөлөөнүн ордуна, магнийге бай тамак менен эс алыңыз.','Sinu keha appikarje 🩸','Ära alistu näiliselt põhjendamatule ärrituvusele ja väsimusele. Kontrolli oma tsüklikalendrit – su keha võib millestki märku anda! Selle asemel, et ennast süüdistada, lõõgastu magneesiumirikka suupistega.'),
('455a26dd-2714-4e7f-a8b0-c2319880fdbd'::uuid,'Көлөкө менен салгылашуу 👻','Ал дубалдагы өз көлөкөсүнөн коркуп, артыңызга жашынып жатабы? 3 жаш курагында элестетүү чексиз болот. Бөлмөнү караңгылатып, колуңуз жана фонарик менен дубалда көлөкө театрын түзүңүз. Алар корккон караңгылыкты көңүл ачуунун эң чоң булагына айлантыңыз.','Varjuvõitlus 👻','Kas nad kardavad oma varju seinal ja peidavad end sinu taha? Umbes 3-aastaselt ei tunne kujutlusvõime piire. Tee tuba pimedaks ja loo taskulambi ning käte abil seinale varjuteater. Muuda pimedus, mida nad kardavad, nende suurimaks lõbuallikaks.'),
('ca0412c4-f03e-412b-a720-1ce839d731c8'::uuid,'Жомоктордун сыйкыры 🪄','Бүгүн кечинде салттуу окуу стилинен баш тартыңыз. Акылдуу жомокторду ачып, шамалдын, кычыраган эшиктин же каармандын кадамдарынын үндөрүн оозуңуз менен чыгарып, бөлмөдө мини-үн театрын түзүңүз. Балаңыз бул аткарууга толугу менен суктанат.','Muinasjuttude võlu 🪄','Jäta täna õhtul tavapärane lugemisstiil kõrvale. Ava oma nutikad lood ja loo toas väike heliteater, tehes suuga tuule, kriuksuva ukse või kangelase sammude hääli. Laps on sellest etendusest täiesti lummatud.'),
('5ee7392d-5b0b-4213-bc93-84f42871cfbd'::uuid,'Уктоону кечеңдетүү амалдары ⏱️','Балаңыз уктаар маалда күтүлбөгөн жерден суусап, дааратканага баргысы келип же дубал менен коштошуп жатабы? Таймер коюңуз. «Коңгуроо кагылганда баары укташат» эрежесин киргизиңиз жана бул чексиз коштошуудан — бул чебер манипуляциядан сабырдуулук менен кутулуңуз.','Magamamineku edasilükkamise taktika ⏱️','Kas lapsel tekib magamamineku ajal äkki janu, vajadus tualetti minna või seinaga hüvasti jätta? Pane taimer. Rakenda reeglit „kõik magavad, kui kell heliseb“ ja põgene kannatlikult sellest lõputust hüvastijätust – sellest meistriklassi manipulatsioonist.'),
('8ed6ac5e-566a-43de-a26f-f6688bac7a5c'::uuid,'Оюнчуктардын энеси 🧸','Анын бөлмөсүнөн үн чыкты. Кунт коюп уксаңыз, ал өзүнүн оюнчук аюусун сиздин үнүңүз жана сөздөрүңүз менен урушуп жатат! Ал сиздин эң так көчүрмөңүз. Бул өзүңүздүн жүрүм-турумуңузду сырттан байкоо үчүн эң сонун мүмкүнчүлүк.','Mänguasjade ema 🧸','Nende toast kostab heli. Kuulad tähelepanelikult ja nad noomivad oma kaisukaru, kasutades täpselt sinu hääletooni ja fraase! Nad on sinu kõige täpsem koopia. See on suurepärane võimalus jälgida oma käitumist kõrvaltvaataja pilguga.'),
('fcc9b956-df18-4d44-8e28-2c6ce0162f8e'::uuid,'Аба ырайына көз салуу ⛅','Сырттагы аба ырайы түшүнүксүзбү — күн ачык, бирок шамалдуубу? Аба ырайы жана кийим куралы аркылуу шамалдын ылдамдыгын (терезеден көрө албаган!) жана кийимдердин эң сонун айкалышын заматта билип алыңыз. Эшиктин алдында ойлонуп убакыт коротпой, сейилдөөгө чыгыңыз.','Ilmaprognoos ⛅','Ilm väljas pole päris selge – päikseline, aga tuuline? Lase ilma- ja riietustööriistal kohe öelda tuule kiirus (mida sa aknast ei näe!) ja täiuslik riietuse kombinatsioon. Suundu jalutama, ilma et raiskaksid aega ukse ees kõhklemisele.'),
('542ab746-c3f8-40a2-81ae-c00828c5ed07'::uuid,'Атамдын жашыруун стратегиясы 👨‍🍼','Күндүзгү чарчоо жана ызы-чуу сизге жетиштүү. Кечинде уктоо тартибин — уктоого даярданууну, тиш жууну — атасынын тамашакөй маанайына өткөрүп бериңиз, ал эми өзүңүз башка бөлмөдө толук тынчтыкта эс алыңыз.','Issi salastrateegia 👨‍🍼','Päevane väsimus ja müra on sulle täiesti piisavad. Õhtul anna magamamineku rutiin – une ettevalmistus, hammaste pesu – issi mänguliste trikkide hooleks ja mine ise teises toas täielikus vaikuses lõõgastuma.'),
('843abd1b-ca68-4402-b6ea-b248f8954a8f'::uuid,'Апанын кубат берүүчү тамагы 🥑','Балаңызды тойгузуу үчүн төрт түрдүү меню даярдадыңыз, бирок өзүңүзчү? Биздин пайдалуу рецепттерибизден 5 мүнөттө даярдалуучу кальцийге бай атайын тамакты тандаңыз. Аны туруп жесеңиз да ырахаттанып жеңиз — сиз бул үйдү кыймылдаткан негизги күчсүз!','Emme kosutav vahepala 🥑','Oled lapse toitmiseks menüüsid neljal erineval moel ette valmistanud, aga kuidas on lood sinuga? Vali meie tervislike retseptide hulgast eriline kaltsiumirikas suupiste, mille valmistamine võtab vaid 5 minutit. Naudi seda, isegi kui seisad – sina oled mootor, mis seda majapidamist käimas hoiab!'),
('9b9022d6-2ceb-4fd3-b3c5-141395cf895c'::uuid,'Бөлүшүүгө болбой турган эртең мененки тамак 🍳','Ал өз табагындагысы менен бөлүшкүсү келбейт, бирок сиздин жумурткаңыздан же сырыңыздан бир тиштеп алууну талап кылабы? Балдар ар дайым ата-энесинин тандоосуна толук ишенишет. Буга каршы чыкпаңыз; сүйүү менен өзүңүздүн бир тиштемиңизди ага сунуңуз.','Jagamatu hommikusöök 🍳','Nad ei taha kuidagi oma taldrikul olevat jagada, aga nõuavad ampsu sinu munast või juustust. Lapsed usaldavad alati täielikult vanemate valikuid. Ära võitle selle vastu; anna neile armastusega oma amps.'),
('3a219301-d574-4311-87ab-5dc04ddcfd8f'::uuid,'Командалык массаж 💆‍♂️','Балаңыз уктагандан кийин, күндүн бардык физикалык жана психологиялык чарчоосун басуу үчүн өнөктөшүңүз экөөңүздөр бири-бириңиздерге ийинге массаж жасап бериңиздер. Сиздер жөн гана үй-бүлө курган ата-эне эмессиздер, сиздер бири-бириңиздерге таянган бекем командасыздар.','Meeskondlik massaaž 💆‍♂️','Kui laps magab, tehke partneriga teineteisele õlamassaaži, et vabastada kogu päeva füüsiline ja vaimne pinge. Te ei ole lihtsalt lapsevanemad, kes jagavad kodu; te olete murdmatu tugimeeskond.'),
('77e473a7-cc66-4af3-964b-ebd4e0ce22a0'::uuid,'''Бул менин күнөөм эмес!'' 🤷‍♂️','Алар атайылап полго суу төгүп жиберип, бирок күнөөнү столго оодарып: «Стол тайгаланып кетти!» деп айтышты. Бул калп эмес, бул өзүн коргоо инстинкти. Талашпаңыз. «Кел, столго жардам берип, экөөбүз чогуу сүртүп коёлу» деп, жоопкерчиликти жумшак жол менен үйрөтүңүз.','„See pole minu süü!“ 🤷‍♂️','Nad ajasid meelega vett põrandale, kuid süüdistasid siis lauda, öeldes: „Laud libises!“ See pole vale, vaid enesealalhoiuinstinkt. Ära vaidle. Õpeta õrnalt vastutustunnet, öeldes: „Aitame lauda ja pühime koos ära.“'),
('a43b3c7f-b8b9-440c-abc6-6650d2627176'::uuid,'Коомчулуктун колдоосу 💬','«Мен эч качан мурдагыдай эркин боло албайм го» деген ой сизди каптап жатабы? Бул убактылуу, бирок өтө оор сезимди Anacan коомчулугундагы башка энелер менен бөлүшүңүз. Ошол эле жолду басып өткөн адамдардан сооронуч жана колдоо табасыз.','Kogukonna tugi 💬','Kas mõte, et sa ei saa enam kunagi oma endiseks, vabaks minaks, tabab sind ootamatult? Jaga seda ajutist, kuid äärmiselt rasket tunnet teiste emadega Anacani kogukonnas. Leiad lohutust ja tuge neilt, kes on sama teed käinud.'),
('3cde3483-1ec6-4721-b8a3-2803d38e22f1'::uuid,'Жаңы сөздөрдү ачуу 🗣️','Алар буюмдарга өздөрү ойлоп тапкан, эч бир тилде жок жаңы аттарды коюп жатышат. Жана сизден да ошол аттарды колдонууну талап кылышат! Өнүгүү күндөлүгүңүздү ачып, бул күлкүлүү сөздөрдү жазып коюңуз, келечекте окуп алып бирге күлөсүздөр.','Uued sõnavaraavastused 🗣️','Nad annavad esemetele täiesti uusi, ise väljamõeldud nimesid, mida üheski keeles ei eksisteeri. Ja nad nõuavad, et ka sina neid kasutaksid! Ava oma arengupäevik ja pane need naljakad sõnad kindlasti kirja, et saaksid neid tulevikus vaadates naerda.'),
('50316f93-f1fa-4052-831d-66931b46940d'::uuid,'Үйдөгү катылган кенчтер 🔑','Үй ачкычыңызды же пультту таба албай жатасызбы? Оюнчук мештин ичин же керебеттин астын карап көрүңүз. Алар буюмдарды катып, дүйнөнү сынап жатышат. Бул күлкүлүү кенч издөө оюнунда ачууланбай, терең дем алып, күлгөндү тандаңыз.','Kodused peidetud aarded 🔑','Ei leia majavõtmeid või pulti? Kontrolli mängu-ahju seest või voodi alt. Nad katsetavad universumit esemeid peites. Vali selles koomilises aardejahis frustratsiooni asemel naer ja hinga sügavalt sisse.'),
('e6c3f535-9f72-4297-8076-fd7145c977da'::uuid,'Чоюлуу убактысынын парадоксу 🛀','Ваннага киргиси келбей ыйлашкан, эми болсо чыккысы келбей ыйлап жатышат! Суунун сыйкырдуу, тынчтандыруучу таасири аларды өзүнө тартып алды. Суудан чыгууну драма кылбаш үчүн, сүлгүнү «жылуу кучактоо» деп атап, ага ороп алып чыгыңыз.','Vannitamise paradoks 🛀','Nad nutsid, sest ei tahtnud vanni minna, ja nüüd uluvad, et ei taha välja tulla! Vee maagiline, rahustav mõju on nad võlunud. Et vältida veest väljumise dramatiseerimist, nimeta rätikut soojaks kallistuseks, mässi nad sellesse ja tõsta välja.'),
('1eb146d3-b624-4eb5-88ee-21bab3e1a546'::uuid,'Жөн гана кучактаңыз 🫂','Бүгүн кечинде оюндардын, ызы-чуулуу китептердин же узун жомоктордун кереги жок. Жөн гана аларды көкүрөгүңүзгө кысып, алардын таза жытын терең дем менен жыттап, караңгыда алардын канчалык баалуу экенин жана аларды канчалык жакшы көрөрүңүздү шыбырап айтыңыз.','Lihtsalt kallista 🫂','Täna pole vaja mänge, lärmakaid raamatuid ega keerulisi lugusid. Lihtsalt hoia neid tihedalt vastu rinda, hinga sügavalt sisse nende puhast lõhna ja sosista vaikuses, kui väärtuslikud nad on ja kui väga sa neid armastad.'),
('39c13cd6-54ea-4fd8-a9da-7ceece969e6d'::uuid,'''Мен арабаны түрткүм келет!'' деген өжөрлүк 🛒','Алар соода арабасын өздөрү түрткүсү келип, текчелерди сүзүп башаламандык жаратып жатышат. Эл алдында ыйлатпаш үчүн, колдорун арабанын четинде калтырып, өзүңүз акырын башкарып туруңуз. Ал эми унутуп калган нерселериңизди кийинчерээк тизмеңизден текшерип аласыз!','„Ma tahan ise käru lükata!“ nõudmine 🛒','Nad tahavad ise ostukäru lükata, tekitades riiulitesse põrgates kaost. Selle asemel, et panna neid avalikult nutma, lase nende kätel jääda käru servale ja juhi seda märkamatult ise. Mis puutub unustatud asjadesse, siis märgi need hiljem ostunimekirja!'),
('dcf51c40-2de5-47dc-a87f-c99740f37d0f'::uuid,'Оюнчуктар бороону 🌪️','Күн сайын бир эле оюнчуктарды жыйнап чарчадыңызбы? Бүгүн жыйнабаңыз! Үйүңүз музей эмес, бул кичинекей изилдөөчү өсүп жаткан жашоого толгон жылуу мейкиндик. Башаламандыкка эмес, балаңыздын эркин изилдөөсүнөн алган кубанычына көңүл буруңуз жана өзүңүзгө эс алуу бериңиз.','Mänguasjatornaado 🌪️','Oled väsinud iga päev samu mänguasju korjamast? Ära korja neid täna! Sinu kodu pole muuseum; see on elust pulbitsev soe ruum, kus kasvab väike avastaja. Keskendu lapse vaba avastamise rõõmule, mitte segadusele, ja anna endale puhkust.'),
('7f0898f3-4281-4b25-877c-f3060088913f'::uuid,'Төмөн кароо: кандай ачылыштар? 👣','Алар жылаңайлак басып, килемди, таштарды же муздак плитканы сезгенди жакшы көрүшөт. Тамандын нерв учтарын стимулдаштыруу алардын тең салмактуулугу жана неврологиялык өнүгүүсү үчүн өтө маанилүү, андыктан бут кийимсиз жүрүүсүнө тыюу салбаңыз.','Allavaatamine: millised avastused? 👣','Nad armastavad paljajalu käia, tundes vaipa, kive või külmi plaate jalataldade all. Jalataldade närvilõpmete stimuleerimine on ülioluline nende tasakaalu ja neuroloogilise arengu jaoks, nii et ära kindlasti keela neil paljajalu olla.'),
('a17ad881-1738-43fa-b18c-dd0c7b263be1'::uuid,'AI: Чыныгы чечимдер 🤖','Балаңыздын баарына кескин реакция кылганы сизди коркутуп жатабы? Интернеттеги үрөй учурган макалаларды унутуңуз. Anacan AI''дан бул жөн гана убактылуу стресс реакциясыбы деп сураңыз жана педиатрлар тарабынан жактырылган илимий жооп менен тынчтаныңыз.','AI: tõelised lahendused 🤖','Kas lapse teravad reaktsioonid kõigele hirmutasid sind? Unusta need traumeerivad internetiartiklid. Küsi Anacan AI-lt, kas see on lihtsalt ajutine stressireaktsioon, ja leia meelerahu teadusliku, lastearsti heakskiidetud vastusega.'),
('602df0e4-a84c-493f-a594-485626339a2a'::uuid,'Жарыкты өчүрүп, уктагыла! 🌙','Алардын тезирээк уктап кетишине жардам берүү үчүн, уктаардан бир саат мурун бөлмөдөгү бардык ашыкча жарыктарды жана планшет экрандарын өчүрүңүз. Мелатонин (уйку гормону) караңгы жана технологиясыз чөйрөдө гана тез бөлүнүп чыгып, уйкуга өтүүнү жеңилдетет.','Tuled kustu, uni tuleb! 🌙','Et aidata neil kiiremini uinuda, lülita tund enne magamaminekut toas välja kõik lisatuled ja tahvelarvutite ekraanid. Melatoniin (unehormoon) eritub kiiresti vaid pimedas, tehnoloogiavabas keskkonnas, tagades sujuva uinumise.'),
('871e1c8b-981d-456b-8f8e-49b3f9df1255'::uuid,'Блогдон илхам алуу 📱','40-айдын тегерегиндеги өнүгүү секириктери кандай болот? Балаңыз кандай көндүмдөрдү өздөштүрүшү керек? Тиркемедеги өнүгүү блогдорун карап чыгыңыз жана кичинекейиңиздин таанып-билүү жана логика жагынан канчалык алдыга кеткенин көрүп, ичиңизден кубаныңыз!','Blogi inspiratsioon 📱','Millised on tüüpilised arenguhüpped 40. kuu paiku? Milliseid oskusi peaks laps valdama? Vaata äpi arengublogisid ja rõõmusta salaja, nähes, kui kaugele on su väike laps jõudnud tunnetuses ja loogikas!'),
('dc309f01-53dd-4d8e-b0a5-566a9cb979d1'::uuid,'Сүйлөмдөрдү толуктоо 🗣️','Сөз унутуп калганда, алар колдору менен ишарат кылып, кабагын бүркөп, сиздин табышыңызды күтүшөт. Алар сүйлөмүн сабырдуулук менен аяктаганда, жүзүндөгү «аа, мен ушуну айткым келген!» деген жеңилдикти байкаңыз. Сиз алардын жалгыз котормочусусуз.','Lausete lõpetamine 🗣️','Kui nad sõna unustavad, žestikuleerivad nad kätega, kortsutavad kulmu ja ootavad, et sa selle ära arvaksid. Jälgi seda „ahhaa, seda ma mõtlesingi!“ kergendust nende näol, kui nad kannatlikult oma lause lõpetavad. Sina oled nende ainus tõlk.'),
('35170eca-5526-4a79-8f60-bb6c6204b11e'::uuid,'Капыстан келген ачкалык 🥱','Төшөккө жатаарда эле: «Апа, ачка болдум!» деп ашканага чуркагысы келет. Бул уйкуну кечиктирүүнүн классикалык ыкмасы! Кечки тамак планына уйкуну чакыруучу кичинекей тамакты кошуу менен бул шылтоону алдын ала жок кылыңыз.','Äkiline näljatunne 🥱','Just siis, kui nad voodisse sätivad, väidavad nad: „Emme, mul on kõht tühi!“ ja tahavad kööki tormata. See on klassikaline meistriteos une edasilükkamiseks! Neutraliseeri see vabandus ennetavalt, lisades õhtusöögiplaani väikese, und soodustava suupiste.'),
('a52300ac-c13a-4b61-bfa8-c7cb27b41cfa'::uuid,'''Бутум чарчады'' деген шылтоо 🚶‍♂️','Көчөдө басып баратканда эле «бутум сынып калды, көтөрүп алчы!» деп кулап түшөбү? Бул физикалык чарчоо эмес, бул апасын манипуляциялоо. Муну оюнга айлантыңыз: «Кел, ким коёндой болуп үйгө тезирээк секирип жетет экен!»','„Mu jalad on väsinud“ kavalus 🚶‍♂️','Kas jalutate tänaval, kui nad äkki kokku vajuvad ja ütlevad: „Mu jalad on katki, kanna mind!“? See pole füüsiline väsimus; see on puhas emaga manipuleerimine. Muuda see mänguks: „Vaatame, kes meist hüppab kiiremini koju nagu jänku!“'),
('ed5f6008-15d7-44f7-a33c-21fd4bedec89'::uuid,'Апанын өчүрүп-күйгүзүү баскычы 🚪','Ызы-чуу мээңизди оорутуп, баарына кыйкыргыңыз келип жатабы? Маанай күндөлүгүңүздү ачыңыз. Бардык чарчооңузду ошол жерге төгүп салыңыз. Бул кыска санариптик терапия сизге кайрадан «баштоо» баскычын басууга жардам берет.','Emme lähtestusnupp 🚪','Müra puurib su ajju, pannes sind kõige peale karjuma. Ava oma meeleolupäevik. Vala kogu oma kurnatus sinna vabalt välja. See lühike digitaalne teraapia aitab sul vajutada „lähtesta“ nuppu.'),
('0d31e21b-368c-475e-b2bc-811f2bd6c64c'::uuid,'''Меники!'' фазасы 🧸','Алар үйдөгү каалаган буюмду кучактап алып: «Бул меники!» деп эч кимге бербей жатышабы? Алар менчик укугунун чектерин изилдеп жатышат. Аларды ачкөздүк үчүн күнөөлөбөңүз; жөн гана ал буюм ошол учурда алардыкы болуп турсун.','„Minu oma!“ faas 🧸','Nad kallistavad suvalist majapidamisesemet, karjudes: „See on minu oma!“ ega luba kellelgi teisel seda puutuda. Nad avastavad omandi piire. Ära süüdista neid isekuses; lase sel esemel hetkeks nende oma olla.'),
('81e2b129-a3fd-4f20-b3aa-69e3df1d9014'::uuid,'Алардын үнүнүн обону 🌙','Алар китептеги окуянын сюжетине эмес, үнүңүздүн обонуна кулак салып жатышат. Бүгүн сюжетти унутуңуз. Жомокту жай, жагымдуу бешик ырындай акырын үн менен окуңуз, бул алардын нерв системасына түздөн-түз уйку сигналын жөнөтөт.','Nende hääle meloodia 🌙','Nad ei kuula raamatu loo sisu, vaid sinu hääletooni. Unusta täna süžee. Loe lugu aeglaselt, madala ja meloodilise häälega nagu õrna hällilaulu, saates otse lapse närvisüsteemile uinumissignaali.'),
('92e01489-6842-4c96-9e36-b31b3377a1e1'::uuid,'Социалдык тармактардын иллюзиясы 📱','Интернеттеги «кемчиликсиз» энелерди көрүп, үйүңүздүн башаламандыгы үчүн өзүңүздү күнөөлөп жатасызбы? Токтотуңуз. Ал 15 секунддук фильтрленген видеолорго ишенбеңиз.','Sotsiaalmeedia illusioon 📱','Kas näed veebis „täiuslikke“ emasid ja süüdistad end segamini kodu pärast? Peatu. Ära usu neid 15-sekundilisi filtreeritud videoid.'),
('045a4c72-4a86-41d2-b03b-ae2eaef10270'::uuid,'Атамдын жомогу 📖','Эгер бүгүн үнүңүз чарчап турса, жомок айтууну атасына өткөрүп бериңиз. Ал таптакыр башка, кызыктуу жана күлкүлүү жомок айтып берип, балаңызды каткыртып күлдүрөт. Ал ортодо сиз чай ичип эс алып, бул жагымдуу көрүнүштөн ырахат алыңыз.','Issi unejutt 📖','Kui su hääl on täna väsinud, anna unejutu lugemine üle issile. Ta räägib hoopis teistsuguse, fantaasiarohke ja naljaka loo, pannes lapse naerust rõkkama. Sina saad samal ajal teetassi taga lõõgastuda ja seda armsat vaatepilti nautida.'),
('4f62a7a1-3c14-48ad-8798-069c557ed2c1'::uuid,'Кир жууганга жардамчы 🧺','Сиз кийимдерди тыкан бүктөп жатсаңыз, алар баарын кайра чачып «жардам берип» жатышабы? Капа болбой, муну оюнга айлантыңыз: «Кел, ким байпактарды себетке тезирээк жана так ыргытат экен!»','Väike pesupesemise abiline 🧺','Sa voldid usinalt pesu ja nemad teatavad, et „aitavad“, ajades kõik uuesti mööda tuba laiali. Selle asemel, et pahandada, muuda see mänguks: „Vaatame, kes suudab need sokid kõige kiiremini ja täpsemalt korvi visata!“'),
('b2fc2b4c-64df-4f47-be2c-e630a4d24c5c'::uuid,'Жаратылышка маанилүү качуу ⛅','Төрт дубалдын ичинде камалган энергия агрессияга айланып, ар бир сүйлөмү «жок» деп башталып жатабы? Аба ырайына же кийимине карабай, ылайыктуу кийиндирип, сөзсүз сыртка алып чыгыңыз. Жаратылыш менен байланышуу алардын нерв системасын заматта калыбына келтирет.','Hädavajalik põgenemine loodusesse ⛅','Nende energia, mis on nelja seina vahele lõksu jäänud, muutub agressiooniks ja iga lause algab sõnaga „ei“. Sõltumata ilmast või sellest, mis neil seljas on, riieta nad sobivalt ja vii kindlasti õue. Maaga ühendumine lähtestab nende närvisüsteemi hetkega.'),
('20cf0e7c-3293-4269-b577-f8012d7d5117'::uuid,'Логиканын кыйрашы 🔴','Сууну кызыл чөйчөккө сурап ыйлашат, сиз кызылына куюп берсеңиз, кайра: «Эмнеге буга куйдуң?!» деп ыйлашат. Мында логика жок. Алар жөн гана чарчашты жана ыйлап алуу керек. Сабырдуулук менен күтө туруңуз; бороон өзүнөн-өзү басылат.','Loogika kokkuvarisemine 🔴','Nad karjuvad vett punases tassis, sina valad selle punasesse, ja siis nad nutavad: „Miks sa sellesse valasid?!“ Siin pole loogikat. Nad on lihtsalt väsinud ja vajavad tühjendavat nuttu. Oota kannatlikult; torm vaibub ise.'),
('3d467b3e-4418-42f9-965d-e11c13d74805'::uuid,'Чөнтөктөгү кенчтер 🪨','Шымдарын жууп жатып чөнтөгүнөн 2 таш, куураган жалбырак жана жарымы желинген бутак таптыңызбы? Сизге таштандыдай көрүнгөн нерселер алар үчүн дүйнөнү изилдөөдөн чогулткан баалуу кенч. Аларды ыргытып салбай, кичинекей кутучага чогултуп коюңуз.','Taskuaarded 🪨','Kas leidsid pükse pestes taskust 2 kivi, kuivanud lehe ja pooliku oksa? See, mis sulle rämpsuna tundub, on nende väärtuslik kollektsioon maailma avastamisest. Selle asemel, et need ära visata, kogu need väikesesse aardelaekasse.'),
('78fd11f7-de1e-4540-906f-51f08156be41'::uuid,'Менин акылдуу жомок укмуштуу окуям 🪄','Бардык классикалык китептерди жаттап бүттүңүзбү? Акылдуу жомокторуңузду (өзүңүз ойлоп тапкан) ачыңыз жана балаңыз башкы каарман болгон, ал эми өз бөлмөсү изилдене турган же багындырыла турган сыйкырдуу өлкө болгон өзгөчө, жеңил уйку сеансын түзүңүз.','Minu nutikas seiklusjutt 🪄','Oled kõik klassikalised raamatud pähe õppinud. Ava oma nutikad muinasjutud (improviseeritud lood) ja loo erakordne, pingevaba une-audio, kus laps on peategelane ja tema oma tuba on maagiline maa, mida avastada või vallutada.'),
('5294e5b4-881b-4e55-b798-fa4dd914d649'::uuid,'''Таштандыдан'' искусствого чейин 🎨','Алар бөлмөнүн ортосуна майда кагаз жана жиптерден чоң «арт-объект» жасап, ыргыттырбай жатышабы? Тазалыкка болгон каалооңузду бир азга токтотуңуз. Алардын жараткан кооз башаламандыгын сыйлаңыз; тазалоо иштери эртеңкиге чейин күтө турат.','„Rämpsust“ kunstiks 🎨','Nad on teinud toa keskele väikestest paberitükkidest ja lõngajuppidest suure „kunstiteose“ ega luba sul seda ära visata. Jäta kõrvale oma korraarmastus. Austa nende loodud kaunist kaost; koristamine võib oodata homseni.'),
('b303b530-f33d-4aed-9563-288f674e5686'::uuid,'Колдоо сураган ыйды түшүнүү 😭','Түн ортосунда көзү жабык бойдон ыйлап ойгонуштубу? Ыйдын анализи менен текшериңиз; эгер бул түнкү коркунуч болсо, аларды ойготпоңуз. Жөн гана жанында унчукпай туруңуз, бир нече мүнөттөн кийин алар кайра уктап кетишет.','Toetust otsiva nutu mõistmine 😭','Nad ärkavad keset ööd nuttes, silmad endiselt kinni, olles ümbritsevast justkui teadmatud. Kontrolli nutu analüüsiga; kui tegemist on öise hirmuhoo ehk ööterroriga, ära proovi neid äratada. Seisa lihtsalt vaikselt kõrval ja nad vajuvad mõne minuti pärast uuesti unne.'),
('d0b48160-e2df-4f83-a2aa-8dad8ce91b39'::uuid,'Буюмдар менен маектешүү 🗣️','Балаңыз сейил бактагы таш же үйдөгү отургуч менен олуттуу сүйлөшүп, ал тургай аларды урушуп жатабы! Мындай символдук оюндар аркылуу ал дүйнөнү таанып, анын эрежелерин түшүнүүдө. Бул өзгөчө оюн сценарийлерин өнүгүү күндөлүгүңүзгө жазып коюуну унутпаңыз.','Vestlused esemetega 🗣️','Sinu laps peab pargis kiviga või kodus tooliga tõsist vestlust, vahel isegi riidleb nendega! Nende sümboolsete mängude kaudu töötleb laps maailma ja õpib tundma selle reegleid. Pane need ainulaadsed mängusituatsioonid kindlasti oma arengupäevikusse kirja.'),
('3486268f-4b63-480f-87b2-0334f163c85e'::uuid,'Ваннадагы көңүл ачуу 🌊','Чоюнуу убактысы эми жөн гана тазалануу эмес, толкун жаратуу оюну! Сууну чачыратууга уруксат бериңиз, ванна бөлмөсү бир аз суу болсо болсун. Суунун сыйкырдуу таасири күн бою топтолгон бардык терс энергияны жууп, агындыга агызып кетет.','Vannirõõmud 🌊','Vanniskäik pole enam ainult pesemine, see on lainete tegemise mäng! Lase veel pritsida, lase vannitoal veidi märjaks saada. Vee magnetiline toime peseb maha kogu päeva jooksul kogunenud kangekaelse negatiivse energia, saates selle otse äravoolust alla.'),
('c30e7d23-adbf-430f-894c-89ab12e4b61e'::uuid,'Атайылап талкалоо 🧱','Кичинекейиңиз мунараны абдан аракеттенип курат, бирок анан аны кубаныч менен кулатып салат! Ал физиканы жана себеп-натыйжа байланышын үйрөнүп жатат. Капа болбоңуз – ал кулаган мунаралар мээсинде жаңы нейрондук байланыштарды түзүүгө жардам берет. Аны кайра курууга үндөңүз!','Tahtlik lammutamine 🧱','Sinu väike põnn ehitab suure vaevaga torni, et see siis rõõmsalt ümber lükata! Ta õpib füüsikat ja põhjus-tagajärg seoseid. Ära pahanda – need kokkukukkuvad tornid aitavad tegelikult luua uusi närviühendusi tema ajus. Julgusta teda uuesti ehitama!'),
('f4280214-1e8a-4015-949d-34ae67c41790'::uuid,'Уйку убактысындагы башаламандык 🥱','Уктагысы келбей ыйлап жатабы? Мажбурлабаңыз. Бөлмөдөгү жарыкты өчүрүп, ''Тынч китеп окуу убактысы'' деп жарыялаңыз. Бул экөөңүздөрдү тең эс алдырган жана башкача маанайда тынчтанууга шарт түзгөн жаңы адат болуп калат.','Uinakuaegne kaos 🥱','Laps ei taha magama minna ja nutab? Ära sunni teda. Hämarda toas tuled ja kuuluta välja „vaikse raamatu aeg“ – see loob uue rutiini, mis lõõgastab teid mõlemaid ja aitab päeva teistmoodi selja taha jätta.'),
('b2543089-e56e-4e5f-b7a7-8528d7fea1b5'::uuid,'Эртең мененки башчы келди! 👑','''Ал жерге отурба, ал жерге менин оюнчук аюум отурат!'' Балаңыз эртең мененки тамактануучу столду ээлеп алды. Анын кыялын түздөн-түз өчүрбөстөн, тынчтыкты жана тең салмактуулукту сактоо үчүн: ''Макул, аюу ошол жерде отурсун, мен болсо бул жерге отурам'' деп айтып көрүңүз. Бул анын оюнун сыйлоо менен бирге, чек араларды жумшак белгилөөгө жардам берет.','Hommikune ülemus on kohal! 👑','„Ära siia istu, mu kaisukaru istub siia!“ Sinu laps on hommikusöögilaua üle võtnud. Ilma tema kujutlusvõimet otseselt maha surumata püüa säilitada rahu ja tasakaalu, öeldes: „Olgu, kaisukaru võib siia istuda ja mina istun siia.“ See austab lapse mängu, seades samas õrnalt piire.'),
('c7639a79-f169-46c8-bd32-85e01fd08685'::uuid,'Шамдын жарыгында чай ичүү 🕯️','Балаңыз акыры уктады. Жарыкты өчүрүп, столго бир шам жагыңыз. Бул романтика үчүн эмес, жөн гана экрандардан жана ызы-чуудан чарчаган нервдериңизди жана көзүңүздү эс алдыруу үчүн.','Tee küünlavalgel 🕯️','Beebi on lõpuks uinunud. Kustuta tuled ja süüta laual üks küünal. See pole romantika jaoks, vaid lihtsalt selleks, et rahustada oma kurnatud närve ja väsinud silmi, mis on terve päeva ekraanide ja müra käes vaevelnud.'),
('c83edf54-e27c-4125-b28b-f2d18dfa66d3'::uuid,'Тийүүдөн чарчоо 🔋','Алар күнү бою үстүңүзгө чыгып, кучактап, чачыңыз менен ойноп жатышат. ''Тийүүдөн чарчоо'' (touch fatigue) – бул реалдуу нерсе. Сиздин жок дегенде 15 мүнөткө өзүнчө бөлмөгө кирип, денеңизге ээлик кылууга укугуңуз бар.','Puuteväsimus 🔋','Laps ronib su otsas, nõuab kaisutusi ja mängib terve päeva su juustega. Puudutusväsimus on täiesti reaalne. Sul on õigus tõmbuda vähemalt 15 minutiks üksi tuppa, kus su keha kuulub ainult sulle.'),
('01e96341-0baa-4735-9565-edc8b43ed916'::uuid,'Атасы менен ат чапмай 🐴','Алардын энергиясы ашып-ташып, уктоодон баш тартып жатышабы? Атасын чакырыңыз! Атасы аларды аркасына отургузуп ''ат чаптырып'' ойногондо, бөлмөнү күлкүгө толтурат. Ошол топтолгон физикалык стресс жана чексиз энергия бир заматта жок болуп, алар уйкуга даяр болуп калышат.','Issiga hobusemäng 🐴','Lapsel on ikka veel liiga palju energiat ja ta tõrgub magamamineku vastu. Kutsu isa appi! Kui isa võtab ta selga „hobusesõidule“, täitub tuba naeruga ning kogu kogunenud füüsiline pinge ja lõputu energia hajuvad sekunditega, jättes lapse uneks valmis.'),
('384ff620-f71d-4bc9-9283-5e83ec033e38'::uuid,'Коомчулуктун сырлары 💬','Бүгүн баарына кыйкырып, өзүңүздү дүйнөдөгү эң чыдамсыз энедей сезип жатасызбы? Сиз жалгыз эмес экениңизди билиңиз. Anacan коомчулугуна кошулуңуз жана башка энелер да бүгүн сиздей чарчаганын окуп, көңүлүңүзгө жубатуу табыңыз.','Kogukonna pihtimused 💬','Kas karjusid täna kõige peale ja tunned end maailma kõige kannatamatuma emana? Tea, et sa pole üksi. Liitu Anacani kogukonnaga ja leia lohutust lugedes, et teised emad on täna sama kurnatud.'),
('da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9'::uuid,'Күзгүдөгү атаандаш 🪞','Күзгү алдында турган балаңыз кабагын түйүп, ачуулуу жана кызыктай бет маскарапоздуктарды жасап жатат. Ал ар кандай эмоциялар бетте кандай көрүнөрүн эксперимент кылып жатат. Бул кичинекей актёрдун репетициясын тынч жана суктануу менен байкап туруңуз.','Peegli rivaal 🪞','Peegli ees seistes kortsutab laps kulmu ning teeb vihaseid ja veidraid nägusid. Ta katsetab, kuidas erinevad emotsioonid näol välja näevad. Jälgi vaikselt ja huviga selle pisikese näitleja proovi.'),
('4a5979ea-637a-48c3-a6a9-1af57b3d55c4'::uuid,'Элестетүү дүкөнү 🍅','Бөлмөнүн бир бурчунда балаңыз дүкөн ачып, сизге элестүү помидорлорду элестүү акчага сатып жатат. Бул оюнду абдан олуттуу кабыл алыңыз! Ал элестүү помидорду ''сатып алып'', ырахаттанып ''жеңиз''. Ролдук оюндар алардын социалдык интеллектинин күчтүү пайдубалы болуп саналат.','Kujuteldav pood 🍅','Toanurgas on laps avanud poe ja müüb sulle kujuteldavaid tomateid kujuteldava raha eest. Võta seda poemängu täie tõsidusega! „Osta“ see kujuteldav tomat ja „söö“ seda suure isuga. Rollimäng on lapse sotsiaalse intelligentsuse võimas vundament.'),
('58c30ae3-2599-434d-af6b-bb25c9a1766d'::uuid,'Музыкалык гипноз 🎶','Кечки тынчсыздануу жана ыйлоо башталдыбы? Телевизорду өчүрүп, жарыкты азайтып, өтө жай классикалык музыка коюңуз. Музыканын терең, тынчтандыруучу жыштыктары атмосфераны сыйкырдуу түрдө өзгөртөт.','Muusikaline hüpnoos 🎶','Õhtune rahutus ja nutuhood on alanud. Lülita teler välja, hämarda tuled ja pane mängima väga vaikne klassikaline muusika. Muusika sügavad ja rahustavad sagedused muudavad atmosfääri maagiliselt.'),
('d8b0e257-5429-4bf7-b2a7-1bb116658651'::uuid,'Кемчиликсиздик — бул жомок 🛑','Бүгүн чыдамыңыз түгөндүбү? Өзүңүздү күнөөлөбөңүз. Интернеттеги идеалдуу энелердин элесинен алыстаңыз. Сиз чыныгы энесиз; эмоцияларды жана чарчоону сезүүгө сизге уруксат.','Täiuslikkus on müüt 🛑','Kas su kannatus katkes täna? Ära tunne end halvasti. Astu eemale interneti täiuslike emade illusioonidest. Oled päris ema; sul on lubatud tunda oma emotsioone ja väsimust.'),
('4673a3e6-d285-4515-9173-039b8bcbc1e0'::uuid,'Азык-түлүк дүкөнүндөгү куткаруучу 🛒','Базарга барганда дайыма эң керектүү нерсени унутуп каласызбы? Соода тизмеңиз тиркемеде сизди күтүп жатат. Керектүү нерселерди ошол жерге жазып коюңуз, жубайыңыз жумуштан кайтып келе жатып аларды так алып келет, ал эми сиз өзүңүзгө эс алуу тартуулаңыз.','Toidupoe päästerõngas 🛒','Kas unustad poes alati kõige olulisema asja? Sinu ostunimekiri ootab sind äpis. Pane vajalikud asjad sinna kirja, lase partneril need töölt tulles täpselt üles korjata ja anna oma mõtetele puhkust.'),
('dd38c03c-a89e-4942-af31-f459dbf71386'::uuid,'«Апа, мага карачы!» фазасы 👀','Кичинекейиңиз дивандан секирип, элүү жолу катары менен ''Апа, мага карачы!'' деп кыйкырып жатабы? Телефонуңузду четке коюңуз. Ал жөн эле көңүл ачуу үчүн эмес, сиздин көзүңүздөгү ыраазычылыктын жаркыраганын көрүү үчүн секирип жатат. Ага беш мүнөт толук көңүл буруңуз – ал баалуу мүнөттөрдөн ырахат алсын.','„Emme, vaata mind!“ faas 👀','Sinu väike põnn hüppab diivanilt ja karjub viiskümmend korda järjest: „Emme, vaata mind!“ Pane telefon käest. Ta ei hüppa ainult põnevusest, vaid selleks, et näha sinu silmis heakskiidusära. Kingi talle viis minutit katkematut tähelepanu – lase tal seda väärtuslikku aega nautida.'),
('effd03a1-4f68-42a7-8c25-eabba9947bc3'::uuid,'Шыбырап айтылган жомоктор 🌙','Кичинекейиңиз бүгүн абдан көп сүйлөдү, ал кичинекей өпкөлөрү чарчады. Жарыкты өчүрүп, жанына жатып, күндүн окуялары жөнүндө акырын шыбырап айтып бериңиз. Шыбырап сүйлөө ага көңүл топтоого жардам берет жана акылын терең, тынч уйкуга акырындык менен даярдайт.','Sosistatud lood 🌙','Sinu väikesel on olnud väga jutukas päev ja need pisikesed kopsud on väsinud. Kustuta tuled, heida tema kõrvale ja sosista vaikselt päeva sündmustest. Sosistamine aitab lapsel keskenduda ja valmistab tema meeled õrnalt ette sügavaks ja kosutavaks uneks.'),
('2c31302d-18e1-44cd-8719-76e1444cd735'::uuid,'Тамактандыруу боюнча жашыруун операция 🥣','Кечээ жумуртканы жакшы көрчү, бүгүн жебей койдубу? Анын каалоосу менен күрөшпөңүз. Биздин дени сак рецепттер бөлүмүндөгү акылдуу тамактарды колдонуп, белокторду ар кандай, түстүү жана кызыктуу формаларга айландырып, жеңишке жетиңиз.','Salajane toitmise operatsioon 🥣','Eile ta armastas mune, täna ei saa sa teda neid sööma. Ära võitle tema tahtega. Ole nutikam, kasutades meie tervislike retseptide sektsiooni, mis muudavad valgud erinevateks, värvilisteks ja huvitavateks vormideks.'),
('723d3b58-0a46-493d-ba9b-9e4d8c6656ee'::uuid,'Жымжырттыктын бейпилдиги 🤫','Ызы-чуулуу күндөн кийин, балаңыз уктагандан кийин, бөлмөнүн тынчтыгын өлчөө үчүн үн өлчөгүчтү колдонуңуз. Ошол сандардын нөлгө жакындаганын көрүү, визуалдык тынчтык, чарчаган эненин акылы үчүн эң сонун массаж сыяктуу.','Vaikuse mugavus 🤫','Pärast lärmakat päeva, kui laps magab, kasuta helimõõturit, et mõõta toa vaikust. Nende numbrite langemine nulli lähedale ja visuaalne rahu on kui kõige kaunim massaaž väsinud ema meeltele.'),
('f226f50f-54a9-4f4e-ad02-b0959087d7d6'::uuid,'Күтүлбөгөн «Сизди жакшы көрөм» 💖','Бөлмөнүн ортосунда ойноп жатып, балаңыз күтүлбөгөн жерден сизге карап, чуркап келип, мойнуңузду кучактап алды. Бул көз ирмем ар бир уйкусуз түнгө, ар бир чарчоого татыктуу! Ал алып келген терең, өзгөчө тынчтык жана кубаныч сезиминен ырахат алыңыз.','Äkiline „Ma armastan sind“ 💖','Keset tuba mängides vaatab laps äkki sulle otsa, jookseb juurde ja paneb käed ümber su kaela. See hetk on väärt iga uneta ööd ja iga grammi väsimust! Naudi seda sügavat, ainulaadset rahu ja rõõmu, mida see toob.'),
('3517ce10-8615-407d-be3b-394eda1c9fa6'::uuid,'Жарыкты өчүрөбүз, уктоо убактысы 🌙','Алардын тезирээк уктап кетишине жардам берүү үчүн, уктоо убактысына бир саат калганда бөлмөдөгү бардык кошумча жарыктарды жана планшет экрандарын өчүрүңүз. Уйку гормону болгон мелатонин караңгы, технологиясыз чөйрөдө эң натыйжалуу иштелип чыгат.','Tuled kustu, aeg magama minna 🌙','Et aidata lapsel kiiremini uinuda, lülita vähemalt tund enne magamaminekut toas välja kõik lisatuled ja tahvelarvutite ekraanid. Melatoniin, unehormoon, toodetakse kõige tõhusamalt pimedas ja tehnoloogiavabas keskkonnas.'),
('7daa2d64-db1d-42ea-8cec-a0101d304bbf'::uuid,'Клетчаткага болгон муктаждык 💩','Алар көп чуркашат, бирок суу ичүүнү унутуп калышат. Горшоктогу жыйынтыгын көзөмөлдөңүз. Эгерде ич катуу коркунучу болсо, аны тиркемеге жазып, Nutrition Tracker куралын колдонуп, менюсуна дароо сулу жана кара өрүк кошуңуз.','Kiudainete vajaduse katmine 💩','Nad jooksevad palju ringi, kuid unustavad vett juua. Jälgi lapse potilkäimist. Kui on kõhukinnisuse oht, märgi see äppi ja lisa toitumispäeviku tööriista abil menüüsse kohe kaerahelbed ja ploomid.'),
('e079d221-e081-498b-8457-7e4dc4555c89'::uuid,'Кооптуу сөздөр 🤐','Балаңыз көчөдөн же телевизордон уккан ''жаман сөздү'' кайталап, күлүп, сиздин реакцияңызды күтүп жатабы? Бул жердеги эң күчтүү куралыңыз – реакция кылбоо. Күлбөңүз, ачууланбаңыз – жөн гана көңүл бурбаңыз. Эгерде ал сөз сизден реакция албаса, бала аны тез эле унутуп калат.','Ohtlikud sõnad 🤐','Sinu laps kordab „halba sõna“, mida kuulis tänaval või telerist, naerdes ja oodates põnevusega sinu reaktsiooni. Sinu tugevaim tööriist on siinkohal reaktsiooni puudumine. Ära naera, ära pahanda – lihtsalt ignoreeri seda. Laps unustab sõna kiiresti, kui see ei tekita sinus mingit vastukaja.'),
('2b47e995-a54a-442e-b303-43e9894db748'::uuid,'Окуянын аягын өздөрү жазсын 🪄','Классикалык жомоктордон экөөңөр тең чарчадыңар. Акылдуу жомоктордо бул жолу окуянын аягын балаңызга тандатыңыз. ''Сенин оюңча, ал каарманга ким жардам берди?'' деп сурап, уктаар алдында анын фантазиясын эркин кое бериңиз.','Lase neil loo lõpp kirjutada 🪄','Olete mõlemad klassikalistest raamatutest väsinud. Nutikates muinasjuttudes lase sel korral lapsel loo lõpp valida. „Kes sinu arvates kangelast aitas?“ küsides lased tema kujutlusvõimel enne und vabalt lennata.'),
('e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a'::uuid,'Муздак логика 🥶','Балаңыз муздаткычты ачып, муз салгычты талап кылып, колу тоңуп жатса да бербей жатабы! Ал ысык жана муздак түшүнүктөрүн физикалык жактан изилдеп жатат. Бул ачылышты кызыктуу илимий экспериментке айлантыңыз: ага бир идишке жылуу суу, экинчисине муздак суу берип, изилдөөсүнө шарт түзүңүз.','Jääkülm loogika 🥶','Laps avab külmkapi, nõuab jääalust ja ei lase sellest lahti, kuigi käed külmetavad! Ta uurib füüsiliselt kuuma ja külma mõisteid. Muuda see avastus lõbusaks teaduskatseks: anna talle üks kauss sooja veega ja teine jääveega, et ta saaks neid uurida.'),
('fd41f13f-2abd-4cce-ba8e-06a55c0b506f'::uuid,'Атанын сейил бактагы укмуштуу окуясы 👨‍👧','Энелик – бул 24/7 иштөөчү нөөмөт эмес. Өнөктөш функциясын иштетиңиз! Бүгүн атасы сейил бакта ал чексиз энергияны сарптасын, ал эми сиз үйдөгү тынчтыктан толук ырахат алыңыз.','Issi pargiseiklus 👨‍👧','Emadus ei ole 24/7 vahetus. Aktiveeri partneri funktsioon! Lase isal täna pargis see lõputu energia välja elada, samal ajal kui sina naudid kodus täielikku vaikust.'),
('587f6b4e-5494-4f6a-8efa-28e0cb53f529'::uuid,'Ашкана концерти 🥄','Кичинекейиңиз казан-аяктарды жана жыгач кашыктарды алып чыгып, ашкананын ортосунда концерт берип жатабы! Бул сиздин башыңызды оорутса да, анын ритм сезимин жана чыгармачылыгын өнүктүрүү үчүн эң сонун жол. Кийлигишүүгө шашпаңыз; бир нече мүнөткө ал кубанычтуу, жапайы энергия бөлмөнү үнгө толтурсун.','Köögikontsert 🥄','Sinu väike põnn võtab välja potid ja puulusikad, korraldades keset kööki tõelise kontserdi! Isegi kui see tekitab peavalu, on see suurepärane viis arendada rütmitunnet ja loovust. Ära kiirusta sekkuma; lase sel rõõmsal, metsikul energial mõne minuti jooksul tuba helidega täita.'),
('a36ee256-d6c9-4345-a732-3a052e7dd260'::uuid,'Аба ырайына көз салуу ⛅','Сырттагы аба ырайы так эмес – күн да бар, бирок шамал да барбы? Аба ырайы жана Кийим куралы аркылуу шамалдын ылдамдыгын (терезеден көрө албайсыз) жана туура кийим айкалышын дароо билип алыңыз, ошондо эшиктин алдында убакыт коротпостон сейилдөөгө чыга аласыз.','Ilmaprognoos ⛅','Ilm väljas pole päris selge – on päikest, aga ka tuult? Lase ilmateate ja riietuse tööriistal kohe öelda tuule kiirus (mida sa aknast ei näe) ja õige riietuse kombinatsioon, et saaksid kõhklusteta ja ukse taga aega raiskamata jalutama minna.'),
('c95b298d-8316-46aa-ace1-1fc1956a0fda'::uuid,'Биргелешкен массаж 💆‍♂️','Балдар уктагандан кийин, күндүн стрессинен арылуу үчүн бири-бириңизге ийин массажын жасаңыз. Эсиңизде болсун, сиздер жөн гана бир үйдө жашаган ата-эне эмессиздер; сиздер бузулгус колдоо командасысыздар.','Meeskonnatöö massaaž 💆‍♂️','Pärast laste uinumist vabanege päeva stressist, tehes üksteisele õlamassaaži. Pea meeles, et te pole lihtsalt kodu jagavad vanemad, vaid murdmatu tugimeeskond.'),
('7a91d538-17ac-47d6-a73e-975aed76abb5'::uuid,'Кичинекей ишкер 🍅','Бөлмөнүн бир бурчунда балаңыз дүкөн ачып, сизге элестүү помидорлорду элестүү акчага сатып жатат. Бул оюнду абдан олуттуу кабыл алыңыз! Ал элестүү помидорду ''сатып алып'', ырахаттанып ''жеңиз''. Ролдук оюндар алардын социалдык интеллектинин жана алгачкы математикалык логикасынын күчтүү пайдубалы болуп саналат.','Väike ettevõtja 🍅','Toanurgas on laps avanud poe ja müüb sulle kujuteldavaid tomateid kujuteldava raha eest. Võta seda poemängu täie tõsidusega! „Osta“ see kujuteldav tomat ja „söö“ seda suure isuga. Rollimäng on võimas vundament nii lapse sotsiaalsele intelligentsusele kui ka varajasele matemaatilisele loogikale.'),
('87c32869-7e9b-4faa-bbbe-1c640a3da5bb'::uuid,'Кальций: сөөктөрүңүздүн коргоочусу 🦴','Кальций тез өсүп жаткан сөөктөр үчүн абдан маанилүү. Сүт ичпей жатабы? Анда бүгүн "Тамактанууну көзөмөлдөө" куралы аркылуу анын сыр, йогурт же брокколиден алган өлчөмүн эсептеп чыгыңыз.','Kaltsium: Sinu luude kaitsekilp 🦴','Kaltsium on kiiresti kasvavatele luudele hädavajalik. Kas laps ei joo piima? Veendu täna toitumispäeviku tööriista abil, et ta saaks piisavalt kaltsiumi juustust, jogurtist või brokolist.'),
('dca4203c-2783-4935-8d52-5e2abbd31c77'::uuid,'Уктоочу бөлмөдөн качуу 🏃‍♂️','«Суу ичем», «Оюнчугумду таап бер!» — 3 жашар баланын уктаар алдындагы шылтоолору бүтпөйт. Уктоо таймерин колдонуңуз жана чек араларды бекем сактаңыз.','Põgenemine magamamineku ajal 🏃‍♂️','„Ma tahan juua“, „Leia mu mänguasi!“ – 3-aastase vabandused magamamineku ajal ei lõpe kunagi. Kasuta unetaimerit ja hoia kindlalt piiridest kinni.'),
('b42e7a75-4fab-45bd-89fe-f334b8181757'::uuid,'Өзүңүзгө кам көрүүнү унутпаңыз 🍲','Балаңыз тамактангандан кийин, кезек Сизде! Биздин пайдалуу рецепттердин ичинен 10 мүнөттө даярдала турган, сизге күч-кубат берүүчү жеңил тамакты тандап, өзүңүзгө кам көрүңүз.','Ära unusta enda eest hoolitseda 🍲','Kui laps on söönud, on sinu kord! Vali meie tervislike retseptide hulgast energiat andev vahepala, mille valmistamine võtab vaid 10 minutit, ja toida ka ennast.'),
('cf65b961-f3be-4509-9af3-0b6c17f757e7'::uuid,'Атам экөөбүздүн убактыбыз 🫂','Аталар да бала менен «териден териге» байланышынан ырахат алышы керек. Кечинде аларга чогуу убакыт өткөрүүгө мүмкүнчүлүк бериңиз; бул алардын ортосундагы байланышты бекемдейт, ал эми Сиз бир аз эс алып аласыз.','Issi ja minu aeg 🫂','Ka isad peaksid lapsega nahk-naha kontakti nautima. Luba neil õhtuti lapsega kahekesi aega veeta; see tugevdab nende sidet ja annab sulle hädavajaliku puhkuse.'),
('0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605'::uuid,'Оор жүктү көтөрүү 🎒','Алар Сиздин оор баштыгыңызды же чоң кол чатырыңызды өздөрү көтөрүп, сүйрөп барууну каалашат жана эч кандай жардамды кабыл алышпайт. Күчүн сынап көрүшүнө жол бериңиз; алар үйдөгү эң күчтүү баатыр сезилгиси келет. Алардын көз карандысыздыгына тоскоол болбоңуз.','Raske koorma kandmine 🎒','Nad nõuavad, et tohiksid ise sinu raskeid kotte või suurt vihmavarju tassida, lohistades neid järel, kuid keelduvad järsult igast abist. Lase neil oma jõudu proovida; nad tahavad tunda end kui maja tugevaim kangelane. Ära takista nende iseseisvust.'),
('13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf'::uuid,'Жаңы образ 🕷️','Балаңыз бүгүн эртең менен ойгонуп: «Мен бала эмесмин, мен жөргөмүшмүн!» — деп олуттуу жарыялайт. 40 айлык куракта алардын фантазиясынын чеги жок. Талашпаңыз — муну кабыл алыңыз! Ага «эртең мененки тамагын ичип жаткан жөргөмүштүн» ролун берип, анын кызыктуу оюнуна кошулуңуз.','Uus isiksus 🕷️','Sinu laps ärkab täna hommikul ja teatab väga tõsiselt: „Ma ei ole laps, ma olen ämblik!“ Umbes 40-kuuselt ei tunne nende fantaasia piire. Ära vaidle – võta see omaks! Anna talle hommikusööki sööva ämbliku roll ja ühine nende veetleva, absurdse teatrietendusega.'),
('b2a11f30-5597-4b15-9f01-835c2894a09b'::uuid,'Түгөнбөгөн шылтоолор 🦶','Уктап бара жатып, алар «Бутумдун бармагы кычышып жатат!» деген сыяктуу шылтоолор менен төшөктөн турууга аракет кылышат. Алар уктоону кечиктирүү өнөрүн өздөштүрүп алышкан. Бекем болуңуз: бутун бир аз кашып койгон болуп, анан чечкиндүү түрдө жарыкты өчүрүңүз. Чек араны Сиз белгилейсиз.','Lõputud vabandused 🦶','Just siis, kui nad on uinumas, üritavad nad voodist välja saada vabandusega: „Mu varvas sügeleb!“ Nad on meisterlikult selgeks õppinud une edasilükkamise kunsti. Ole kindel: süga korraks jalga, justkui teeksid seda päriselt, ja kustuta siis otsustavalt tuled. Sina sead piirid.'),
('272c7bb7-edd9-4323-8db9-05fe3c752757'::uuid,'Маанайдын кескин өзгөрүшү 🤖','3,5 жаштагы балаңыздын маанайынын кескин өзгөрүшү Сизди тынчсыздандырып жатабы? Коркунучтуу жана травмалык онлайн форумдарды жабыңыз. Бул курактык кризистер тууралуу илимий жана психологиялык жактан негизделген, ишенимдүү жоопту Anacan AI''дан алыңыз.','Äkilised meeleolumuutused 🤖','Kas lapse intensiivsed tujumuutused 3,5-aastaselt teevad sulle muret? Sulge need hirmutavad ja traumeerivad veebifoorumid. Küsi Anacan AI-lt teaduslikult ja psühholoogiliselt põhjendatud ning rahustavaid vastuseid nende eakohaste kriiside kohta.'),
('53a9bbe1-a99a-4438-963b-9b63a44c8eb3'::uuid,'Жылуу ваннанын сыйкыры 🛀','Кээде эч нерсе жардам бербей, алар баардык нерсеге эле ыйлай беришет. Аларды акырын жылуу сууга, көбүктөр менен жуунтуңуз. Суунун чыңалууну басуучу касиети бөлмөгө тынчтык алып келип, баланын нерв системасын калыбына келтирет.','Sooja vanni võlu 🛀','Mõnikord ei tundu miski töötavat ja nad lihtsalt nutavad kõige pärast. Pane nad õrnalt sooja vanni, kus on veidi vahtu. Vee müstiline, pinget maandav jõud toob hetkega rahu nii tuppa kui ka nende väikesesse närvisüsteemi.'),
('b49dbabf-98b6-4f35-8748-de30793c2722'::uuid,'Гардероб инженери 👗','Бүгүн балаңыз ар башка байпак кийип же көйнөгүн тескери кийип сыртка чыгууну каалап жатат. Коомдун калыптанган эрежелерин унутуңуз! Өз алдынча чечим чыгаруу жана аны коргой билүү эркиндиги — түстөрдү айкалыштыруудан алда канча баалуу сабак. Ага уруксат бериңиз.','Garderoobiinsener 👗','Täna nõuab su laps, et läheksime välja eri värvi sokkide ja tagurpidi särgiga. Unusta ühiskonna normid! Vabadus teha oma valikuid ja nende eest seista on palju väärtuslikum elutund kui lihtsalt värvide sobitamine. Lase neil seda teha.'),
('00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5'::uuid,'Кичинекей кайталагыч 🎙️','Бүгүн эртең менен балаңыз Сиздин кечээ жолдошуңуз менен сүйлөшүп жатканда айткан кокустук сөзүңүздү оюнчугуна кайталап жатат. Алар Сиздин тирүү күзгүңүз. Алардын жанында колдонгон сөздөрүңүзгө жана эмоцияларыңызга өзгөчө көңүл буруңуз; алар баарын көчүрүп алышат.','Väike kordaja 🎙️','Täna hommikul kordab su laps suvalist, võib-olla tarbetut sõna, mida sa eile partneriga rääkides kasutasid – ja ütleb seda oma mänguasjale! Nad on tõepoolest sinu elav peegel. Pööra erilist tähelepanu emotsioonidele ja sõnadele, mida sa nende juuresolekul kasutad; nad kopeerivad kõike.'),
('885b2dd9-966f-46c2-bbae-00f0fd65a479'::uuid,'Атанын кызыктуу жомок айтып берүүсү 📖','Бүгүн кечинде жомокту башка бирөө айтып берсин! Жомок китебин атасына бериңиз жана окуяны тескерисинен же күлкүлүү кылып айтып берүүсүн сураныңыз. Балаңыздын аны оңдоп, каткырып жатканына сырттан байкоо салыңыз.','Issi lõbus unejutuaeg 📖','Täna õhtul las keegi teine olla jutuvestja! Anna muinasjuturaamat isale ja julgusta teda lugu tagurpidi või naeruväärselt absurdsel viisil ette lugema. Jälgi kõrvalt, kuidas laps naudib tema parandamist ja puhkeb naerma.'),
('fdf68496-5c5f-493c-aaed-7e9ab140b9c8'::uuid,'Коомчулуктун күчү 💬','«Эмне үчүн балам мынчалык өжөр?» деген ой Сизди кыйнап жатабы? Anacan Коомчулугуна кошулуңуз. Башка энелердин үйлөрүндө да ушундай эле кызыктай кризистер болуп жатканын окуганда, Сиз жалгыз эмес экениңизди жана туура жолдо баратканыңызды түшүнөсүз.','Kogukonna jõud 💬','Kas mõte „Miks mu laps on nii kangekaelne?“ närib su hinge? Liitu Anacan Communityga. Kui loed teiste emade kodudes toimuvatest sarnastest absurdsetest kriisidest, näed, et sa pole üksi ja oled täiesti õigel teel.'),
('489a0197-f1e2-44a5-bece-55d85fa323ae'::uuid,'Аба ырайына көз салуу ⛅','Күн тийип турса да, алар кышкы пальто кийүүнү талап кылышат. Талашпаңыз. Аба ырайы жана кийим тандоо куралын ачып, экрандагы жеңил кийинген баланын сүрөтүн көрсөтүңүз. «Карачы, телефон бүгүн күн жылуу деп жатат!» — бул ыкма ар дайым жакшы жардам берет.','Ilmaprognoos ⛅','Päike paistab, aga nad nõuavad talvemantli kandmist. Ära vaidle. Ava ilma- ja riietumistööriist, näita neile ekraanil kergelt riides lapse ikooni. „Vaata, telefon ütleb, et täna on soe!“ – see nipp töötab alati imeliselt.'),
('0ed5ca13-9d93-489b-99e3-a198862dd467'::uuid,'Уйкунун бузулушубу? 🤖','Түн ичинде ойгонуулар күтүүсүз көбөйдүбү? Бул өнүгүүдөгү секирик болушу мүмкүн. 4-5 айлык курактагы уйкунун регрессиясы тууралуу Anacan AI''дан кененирээк маалымат алыңыз.','Une regressioon? 🤖','Kas öised ärkamised on järsku sagenenud? See võib olla arenguhüpe. Küsi Anacan AI-lt lisateavet 4–5-kuuste uneregressiooni kohta.'),
('64df174c-9f28-403f-83be-8452dd687caf'::uuid,'Сценарий алардын колунда 🪄','Классикалык жомоктор аларды кызыктырбай калдыбы? Интерактивдүү окуяны ачып: «Бул сыйкырдуу поезд эми кайда барышы керек?» — деп сураңыз. Алар өздөрү ойлоп тапкан кызыктай жана күлкүлүү аяктоо менен таттуу уйкуга кетсин.','Stsenaarium on nende kätes 🪄','Klassikalised muinasjutud ei köida enam nende tähelepanu? Ava interaktiivne lugu ja küsi neilt: „Kuhu see võlurong nüüd sõitma peaks?“ Lase neil uinuda, olles eksinud nende endi loodud kummalisse ja täiesti absurdsesse lõppu.'),
('9a0a29d7-d513-4158-b204-99c831639c23'::uuid,'Бирге, бирок өзүнчө 👶','Алар паркта башка балдар менен ойнобой, жөн гана байкоо салып жатышабы? Бул — параллелдүү оюн! Социалдашуунун бул баскычы тууралуу кызыктуу фактыларды Anacan AI''дан сураңыз.','Koos, kuid eraldi 👶','Kas nad jälgivad pargis teisi lapsi, selle asemel et otse mängida? See on paralleelmäng! Küsi Anacan AI-lt huvitavaid fakte selle sotsialiseerumise etapi kohta.'),
('e9ba59d9-6287-434c-823d-456c6d21f0ef'::uuid,'Тиш доктурга баруу 🦷','Балаңыз тиш щеткасын алып, Сиздин тиштериңизди абдан олуттуу түрдө текшергиси келип жатат. Оозуңузду ачып, бул сүйкүмдүү «дарыгерге» өз ишин кылууга мүмкүнчүлүк бериңиз! Ролдук оюндар — инсанды калыптандыруунун жана коркунучтарды жеңүүнүн эң натыйжалуу жана кызыктуу жолдорунун бири.','Hambaarsti visiit 🦷','Su laps on haaranud hambaharja ja tahab väga tõsiselt sinu hambaid uurida. Ava suu ja lase sel armsal väikesel „arstil“ oma tööd teha! Rollimäng on üks tõhusamaid ja nauditavamaid viise arendada isiksust ja ületada hirme.'),
('cafa10cc-4494-418e-834e-6ddf05c49140'::uuid,'Таштанды эмес, казына 🍬','Сиз бир нече күндөн бери кармап жүргөн эски момпосуйдун кагазын ыргытып жибергениңиз үчүн «шоколад кагазы кризиси» башталдыбы? Сиз үчүн таштанды болгон нерсе, алар үчүн баалуу кенч же коллекция болушу мүмкүн. Алардын көз жашын токтотуу үчүн тезинен башка кызыктуу нерсе менен алаксытыңыз.','Pole prügi, vaid aare 🍬','Kas puhkes „šokolaadipaberi kriis“, sest viskasid ära selle vana kommipaberi, mida nad olid päevi käes hoidnud? See, mis on sinu jaoks prügi, võib neile olla kallis aare või väärtuslik kollektsioon. Pisarate peatamiseks hajuta nende tähelepanu kohe mõne veelgi köitvama esemega.'),
('d9ad6664-d013-4d53-b45b-e81b7aa6c58c'::uuid,'Шампансыз жеңиш 🥂','Балдар укташты! Колуңузда шампан жок болсо да, ысык чай куюп, жолдошуңуз менен чөйчөк кагыштырып: «Бүгүнкү башаламандыкты да жеңдик!» — деп айтыңыз. Унутпаңыз, Сиз бул үйдүн сынбас жана чарчабас командасысыз.','Võit ilma šampanjata 🥂','Lapsed magavad! Isegi kui šampanjat käepärast pole, vala tass kuuma teed, kõlksuta partneriga klaase ja ütle: „Me alistasime ka täna selle kaootilise tormi!“ Pea meeles, et olete selle majapidamise murdmatu ja väsimatu meeskond.'),
('e8db8e88-207e-4ac3-9421-9b1c49bdfd27'::uuid,'Брокколи изилдөөчүсү 🥦','Алар шорподогу жалгыз жашылчаны көрүп калып, ичүүдөн баш тартып жатышабы? Тамактануу планынан жашылчаларды түстүү макарон менен аралаштыруу же пюре кылып жашыруу сыяктуу эксперттик ыкмаларды билип алыңыз.','Brokolidetektiiv 🥦','Kas nad märkavad supis seda ühte rohelist köögivilja ja keelduvad söömast? Avasta toitumiskavast asjatundlikud nipid, kuidas neid hajutada, segades köögivilju värvilise pastaga või peites need nutikalt püreesse.'),
('417acfcf-4492-4093-aa86-48285ecc470a'::uuid,'Атанын баш кийим чакырыгы 🧢','Кичинекейиңиз атасынын кышкы калпак кийип уктоосун талап кылып жатабы? Кийсин! Атасы калпакты кийип, кызыктуу үндөрдү чыгарсын. Бул күлкүлүү кечки ырым-жырым уктаар алдында экөөңүздөрдү тең күлдүрүп гана койбостон, ар кандай өжөрлүктү заматта жок кылат.','Issi mütsiväljakutse 🧢','Sinu väike nõuab, et isa kannaks voodis talvemütsi? Las ta kannab! Las isa paneb mütsi pähe ja teeb naljakaid hääli. See imeliselt absurdne õhtune rituaal ei pane teid mõlemaid enne und naerma, vaid sulatab hetkega ka igasuguse kangekaelsuse.'),
('7516076d-1a63-4620-b73e-63a31b706bac'::uuid,'Физикага каршы келген өжөрлүк 💧','Алар «кургак суу» сурап ыйлап жатышабы? Баланын мээси мүмкүн эмес нерсени сураганда, алар көбүнчө Сиздин чек араңызды жана чыдамыңызды сынап жатышат. Аларга түшүндүрүүгө аракет кылбаңыз; жөн гана башка түстүү буюм менен көңүлүн дароо башка жакка буруңуз.','Füüsikaseadusi eirav jonnakus 💧','Kas nad nuuksuvad ja nõuavad „kuiva vett“? Kui lapse aju nõuab võimatut, panevad nad sageli proovile sinu piire ja kannatust. Ära ürita nendega vaielda; suuna nende tähelepanu lihtsalt mõne muu värvilise esemega mujale.'),
('b726a724-b8d0-4de2-92f7-30636fde8d1a'::uuid,'Шкафтан тынчтык табуу 🚪','Үйгө күтүүсүз тынчтык орноп, Сиз аларды шкафтын ичинде жашынып алып, өз алдынча ойноп жаткан жеринен таптыңыз. Бул — алардын жеке мейкиндик издөөсү. Аларды дароо чыгарып албаңыз; алар да ызы-чуудан качып, жалгыз калып, мээсин эс алдыргысы келет.','Rahu leidmine kapis 🚪','Majas valitses äkiline vaikus ja leidsid nad kapist peidus, omaette mängimas. See on nende viis otsida isiklikku ruumi. Ära tõmba neid kohe välja; nad tahavad samuti mürast pääseda, olla omaette ja oma mõtteid vaigistada.'),
('4b514d29-e0d8-49a4-850f-900d0c46bffa'::uuid,'Ичтеги жашыруун ачуу 😤','Алар каалаганы болбой калганда ыйлабай, колдорун кайчылаштырып, дубалды карап Сизге таарынып жатышат. Бул — эмоционалдык жөнгө салуудагы жаңы жана абдан маанилүү кадам. Аларды кыйнабаңыз; 3 мүнөттөн кийин эч нерсе болбогондой кайра эле күлүп калышат.','Vaikne raev 😤','Selle asemel, et nutta, kui nad oma tahtmist ei saa, ristavad nad käed, vaatavad seina ja solvuvad. See on uus ja väga oluline samm emotsioonide reguleerimisel. Ära survesta neid; 3 minuti pärast naeratavad nad jälle, nagu poleks midagi juhtunud.'),
('4b721431-3565-4047-8fb3-144c9d3a8f8b'::uuid,'Алтын жымжырттыктын баасы 🤫','Үйдөгү тынымсыз ызы-чуудан кулагыңыз чыңылдап кетти. Алар уктаганда, үн өлчөгүчтү иштетиңиз. Экрандагы сандардын нөлгө жакындаганын, санариптик тынчтыктын визуалдык көрүнүшүн көрүү — чарчаган эненин мээси үчүн эң сонун массаж.','Kuldse vaikuse väärtus 🤫','Pidev müra kodus paneb kõrvad kumisema. Kui nad lõpuks uinuvad, lülita sisse helimõõtja. Nende ekraanil nulli poole liikuvate numbrite jälgimine, see digitaalse vaikuse visuaalne esitus, on tõeliselt kauneim visuaalne massaaž väsinud ema ajule.'),
('450e1ee4-0ee2-4568-acc9-22677b87903d'::uuid,'Алар сизди карап жатышат! 📸','Бөлмөнүн кайсы жеринде болсоңуз да, ал кичинекей көздөр Сиздин ар бир кыймылыңызды байкап турат.','Nad jälgivad sind! 📸','Ükskõik kus sa toas ka ei viibiks, need väikesed silmad jälgivad alati iga sinu liigutust.'),
('696eaa28-30b3-4a02-87e3-0cd00d185f07'::uuid,'Болгону 10 мүнөт 🛀','Наристе уктап, акыры тынчтык орноду. Идиш жуугучту иреттегендин ордуна, жылуу душка кирип, 10 мүнөткө суунун үнү менен эс алыңыз.','Vaid 10 minutit 🛀','Laps magab ja lõpuks on saabunud vaikus. Selle asemel, et nõudepesumasinaga tegeleda, hüppa sooja duši alla ja lase vee rahustaval kohinal end 10 minutit hellitada.'),
('8ad462c4-33b5-4c76-be29-aa192feb14a1'::uuid,'Бут кийим тар болуп жатабы? 📏','Кичинекейиңиз акыркы убакта чуркап баратып бат-баттан мүдүрүлүп жатабы? Бул өсүү секириги болушу мүмкүн! Анын физикалык өнүгүүсүн көзөмөлдөө үчүн учурдагы боюнун узундугун жана өлчөмдөрүн «Өсүү календарына» киргизиңиз.','Kingad tunduvad kitsad? 📏','Kas su väike komistab viimasel ajal joostes sagedamini? Neil võib olla kasvuspurt! Sisesta nende praegune pikkus ja mõõdud kasvupäevikusse, et hoida silm peal nende füüsilisel arengul.'),
('6fcf10ba-99bd-4b23-bbff-0487161fbfe4'::uuid,'Жаңы тилди үйрөнүү 🗣️','Балаңыз «учуп-чуркоо» же «ысык-муздак» сыяктуу өзүнүн татаал жана кызыктай сөздөрүн ойлоп таба баштадыбы? Анын сөз байлыгы укмуштуудай тездик менен өсүүдө. Бул кызыктуу, өзү ойлоп тапкан сөздөрдү өнүгүү календарына алгачкы тилинин унутулгус архиви катары жазып коюңуз.','Uue keele avastamine 🗣️','Sinu laps on hakanud leiutama keerulisi ja omapäraseid sõnu, nagu „lenda-jookse“ või „kuum-külm“! Nende sõnavara laieneb uskumatult kiiresti. Salvesta need lõbusad, ise loodud väljendid kindlasti oma arengupäevikusse kui unustamatu arhiiv nende varajasest keelest.'),
('2c413ba6-81fc-4861-95ac-e87a4f29055d'::uuid,'Менин кызыктай шеригим 🥄','Паркка бара жатканда балаңыз оюнчук машиналарынын ордуна ашкана чөмүчүн алууну талап кылып жатат. Каршы болбоңуз! Ал чөмүч бүгүн кум казуу үчүн анын эң өзгөчө, бирок абдан пайдалуу оюнчугу болору шексиз.','Minu veider kaaslane 🥄','Teel parki nõuab su laps autode asemel köögikulpide kaasa võtmist. Ära seisa neil teel! See kulp on täna kahtlemata nende kõige ebatavalisem, kuid uskumatult funktsionaalne mänguasi liivas kaevamiseks.'),
('b865240d-5ee4-4c57-917c-6139d1ce4039'::uuid,'Мышыктар суудан коркушат 🐈','Жуунуудан качуу үчүн алар: «Мен мышыкмын, ал эми мышыктар жуунбайт!» — деп жарыялашат. Аларга кошулуп ойноңуз! «Ошондойбу? Бирок бул кичинекей мышык самын көбүктөрү менен ойногусу келеби?» — деп жооп бериңиз. Каршылыктарды жеңүү үчүн алардын фантазиясын колдонуңуз.','Kassid kardavad vett 🐈','Vanniskäigust hoidumiseks teatavad nad: ''Ma olen kass ja kassid ei käi vannis!'' Mängi kaasa! Vasta: ''Ah nii? Aga kas see väike kassike tahab seebimullidega mängida?'' Kasuta nende kujutlusvõimet, et vastuseisust üle saada.'),
('f573b98e-335c-4b92-b5f7-06c122ba5b12'::uuid,'Азык-түлүк сатып алуу боюнча эксперт 🛒','Дүкөндө таттуу сурап ыйлагандын ордуна, алар: «Егер муну сатып алсак, мен шорпомду ичем», — деп соодалаша башташат. Куттуктайбыз, кичинекей сүйлөшүүчүңүз чоңоюп жатат! Унутуп калбаш үчүн соода тизмеңизди жаныңызда кармаңыз, ошондо алар менен талашып жатканда оюңуз чар тарапка чачырабайт.','Nutikas toidupoe külastus 🛒','Selle asemel, et poes kommi nõuda, hakkavad nad kauplema: ''Kui me selle ostame, siis ma söön oma supi ära.'' Palju õnne, sinu väike läbirääkija on suureks kasvamas! Hoia ostunimekiri käepärast, et unustamine sind ei kimbutaks ja mõtted nendega vaieldes uitama ei läheks.'),
('605e9c74-a673-4f1f-9b27-383f6a4810eb'::uuid,'«Мага карачы!» фазасы 👀','Балаңыз дивандан секирип, бир эле кыймылды элүү жолу кайталап, сиздин мактооңузду күтүп жатат. Телефонуңузду четке коюңуз. Алар жөн эле секирип жаткан жок, алар сиздин көзүңүздөгү мээримдүү колдоону көрүү үчүн аракет кылып жатышат.','„Vaata mind!“ faas 👀','Sinu laps hüppab diivanilt alla, kordab sama tegevust viiskümmend korda ja ootab sinu heakskiitu. Pane telefon käest. Nad ei hüppa lihtsalt hüppamise pärast, vaid selle armastava ja tunnustava sära pärast sinu silmis.'),
('61cf1118-2d1d-4e42-9dac-f7a6ca616e71'::uuid,'Менин үнсүз сырдашым 📝','Сизди эч ким түшүнбөгөндөй сезилип, үй тиричилигинен аябай чарчадыңызбы? Жасалма жылмаюуну бир азга четке коюңуз. Маанай күндөлүгүңүзгө бүгүн өзүңүздү канчалык алсыз сезип жатканыңызды жазыңыз. Экранга төгүлгөн ар бир сөзүңүз ийиниңиздеги оор жүктү жеңилдетет.','Minu vaikne usaldusisik 📝','Tunned, et keegi ei mõista sind ja oled kodustest toimetustest täiesti kurnatud? Jäta sundnaeratus hetkeks kõrvale. Kirjuta oma meeleolupäevikusse, kui väsinud sa end täna tegelikult tunned. Iga sõna, mille ekraanile valad, kergendab su koormat.'),
('a2f88e5e-134a-4514-9134-a36d1a155887'::uuid,'Полдо уктоо 🥱','Алар уктоодон баш тартып, каршылык көрсөтүштү, бирок кийин килемдин үстүндө оюнчуктарынын арасында бүрүшүп уктап калышты. Аларды төшөккө көтөрүп барып ойготуп албаңыз; бөлмөнүн ортосундагы ошол бейпилдиктен ырахат алышсын, ал эми сиз дагы бир саат эс алып алыңыз.','Põrandauinakud 🥱','Nad keeldusid uinakust ja panid vastu, kuid keerasid end siis vaibal mänguasjade keskel kerra ja jäid magama. Ära kanna neid voodisse ja ärata üles; lase neil nautida seda süütust keset tuba ja võta ka ise tund aega puhkust.'),
('52a1e30d-f365-493c-8480-78b508714eb6'::uuid,'Караңгыдан коркосузбу? 👻','3,5 жаштын тегерегинде көбүнчө караңгыдан коркуу сезими пайда болот. Бөлмөгө кичинекей түнкү чырак коюп, Smart Tales аркылуу кайраттуу баатырлар жөнүндө окуяларды ойлоп табыңыз.','Kas kardad pimedat? 👻','Umbes 3,5-aastaselt tekib sageli hirm pimeduse ees. Pane tuppa väike öölamp ja loo Smart Talesi abil julgeid kangelaslugusid.'),
('cbfa1fac-401d-41c2-974d-c9424b7436ce'::uuid,'Апалардын маеги 💬','Балаңыз эмне үчүн горшокко көнө элек деп чарчап жатасызбы? Anacan Коомчулугуна кошулуңуз, ошондо ар бир баланын өзүнүн өзгөчө өнүгүү темпи бар экенин көрөсүз.','Emmede jutuajamine 💬','Oled kurnatud mõttest, miks su laps pole veel potitreeningut täielikult selgeks saanud? Liitu Anacani kogukonnaga ja näed, et igal lapsel on oma ainulaadne tempo.'),
('cde5f67f-33e9-4a06-9155-b70a56cb6c73'::uuid,'Сөздөр менен ойноо 🗣️','Алар атайылап кээ бир тамгаларды өзгөртүп, кызыктуу үндөрдү чыгарып, буга өздөрү күлүп жатышабы? Алар тилдин ийкемдүүлүгүн ачып жатышат! Аларга кошулуп, сөз оюндарын ойноңуз.','Sõnadega mängimine? 🗣️','Kas nad muudavad meelega tähti, teevad naljakaid hääli ja naeravad selle üle? Nad avastavad keele paindlikkust! Liitu nendega ja mängige koos sõnamänge.'),
('57748696-ab80-425d-85cf-6283ca454879'::uuid,'Жаңы достошуулар 👫','Алар эми паркта башка балдар менен бирге (жөн эле жанында эмес, чогуу) ойноого аракет кылып жатышабы? Социалдашуу расмий түрдө башталды! Бул учурга бир аз алыстан байкоо салыңыз, эгер керек болсо жардамга келүүгө даяр болуңуз.','Tärkav sõprus 👫','Kas nad üritavad nüüd pargis teiste lastega *koos* mängida (mitte ainult nende kõrval)? Sotsialiseerumine on ametlikult alanud! Jälgi seda hetke veidi eemalt, olles valmis vajadusel sekkuma.'),
('9fedc843-d647-418d-b31f-ad9bf956e849'::uuid,'Сиздин чөнтөк тизмеңиз 🛒','Күнүмдүк убаракерчиликте шампунь же нымдуу салфетка түгөнүп калдыбы? Баарын эстеп калууга аракет кылбаңыз. Аны дароо Соода тизмесине кошуп, өмүрлүк жолдошуңуз менен шайкештештириңиз.','Sinu taskunimekiri 🛒','Kas igapäevases saginas said šampoon või niisked salvrätid otsa? Ära ürita kõike meeles pidada. Lisa see kohe ostunimekirja ja sünkrooni oma partneriga.'),
('ac1c42c5-b375-4935-bfbe-c3b0f8da74a1'::uuid,'Тынч убакытка болгон муктаждык 🤫','Уктап калгандан кийинки алгачкы жарым саат — эң сезимтал убакыт. Бөлмөдөгү ызы-чуунун деңгээлин үн өлчөгүч менен текшерип, чектеш бөлмөдөгү сыналгынын үнүн басаңдатыңыз.','Vajadus vaikuse järele 🤫','Esimene pooltund pärast uinumist on kõige tundlikum aeg. Kontrolli toa mürataset helimõõtjaga ja piira teleri helitugevust kõrvaltoas.'),
('2e15df12-458b-434c-ac05-d42b6b0a04b3'::uuid,'Алардын деминин жылуулугу 💖','Алар күнү бою сизди чарчатып, бардык нерсеге өжөрлүк менен каршылык көрсөтүштү. Бирок азыр төшөктө көкүрөгүңүзгө башын коюп, бир калыпта дем алганы бөлмөнү толтуруп турат. Бул — энеликтин эң чоң сыйлыгы. Аларды кучактап, бардык чарчооңузду унутуңуз.','Nende hingamise soojus 💖','Nad ajasid sind terve päeva marru, trotsides kõike. Aga nüüd, voodis vastu sinu rinda surutuna, täidab tuba nende rütmiline hingamine. See on emaduse suurim tasu. Hoia neid lähedal ja lase kogu väsimusel haihtuda.'),
('b9503491-2c22-4639-94ac-cc1a79aea888'::uuid,'Сыймык менен кийилген ар түрдүү бут кийимдер 👟','Алар бут кийимдерин тескери кийип алышты, бирок дүйнөнү багындыргандай сыймыктануу менен басып жүрүшөт. Кийлигишпеңиз же оңдоого аракет кылбаңыз. Балаңыздын өзүнө болгон ишеними жана көз карандысыздыгы анын кийиминин кемчиликсиз көрүнүшүнөн миллион эсе маанилүү.','Uhked eripaari kingad 👟','Nad panid kingad valesse jalga, kuid kõnnivad ringi sellise uhkusega, nagu oleksid maailma vallutanud. Ära sekku ega ürita seda parandada. Sinu lapse enesekindlus ja iseseisvus on miljon korda tähtsamad kui täiuslik välimus.'),
('cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4'::uuid,'Боорукерликтин туу чокусу 🩹','Алар оюнчук аюунун колуна «ооруп жатат» деп пластырь чаптап, өөп жатышабы? Бул чоң, боорукер жүрөккө суктаныңыз! Бул терең боорукердик сезимин Өнүгүү трекерине сонун мүнөз катары сыймыктануу менен жазып коюңуз.','Empaatia tipphetk 🩹','Kas nad panevad oma mängukaru käpale plaastri ja suudlevad seda, sest ''see valutab''? Imetle seda suurt ja kaastundlikku südant! Märgi see sügav empaatiavõime uhkusega oma arengupäevikusse kui kaunis iseloomuomadus.'),
('1f4d8560-3286-4e95-8474-fcafd793fada'::uuid,'Атанын кичинекей аянтчасы 👨‍👧','Сабырыңыз түгөнүп баратканын сезип жатасызбы? Уктоочу бөлмөнүн эшигин жаап, кичинекейиңизди атасы менен калтырыңыз. Бүгүн кечинде оюнду ал башкарсын, ал эми сиз татыктуу эс алыңыз.','Issi väike mänguväljak 👨‍👧','Tunned, et kannatus hakkab katkema? Sulge magamistoa uks ja jäta väike põnn isaga kahekesi. Las tema olla täna õhtul mänguaja juht, samal ajal kui sina võtad väljateenitud puhkuse.'),
('af913905-7dd6-4f3e-bf26-424dee34a1c5'::uuid,'Мен эмне кыла аларымды карачы! 🤸‍♂️','Алар сиздин көңүлүңүздү буруу үчүн бир буттап турууга же секирүүгө аракет кылып жатышабы? Алар сиздин мактооңузду күтүп жатышат! Бул физикалык тең салмактуулукту Өнүгүү трекерине белгилеп, аларды катуу кубаттаңыз.','Vaata, mida ma suudan! 🤸‍♂️','Kas nad üritavad ühe jala peal seista või hüpata, et sinu tähelepanu saada? Nad otsivad sinu heakskiitu! Märgi see füüsiline tasakaal arengupäevikusse ja kiida neid kõvasti.'),
('cd8e0cdd-1b7c-42e3-856f-3b4914ee1697'::uuid,'Жашылча согуштары 🥦','Алар тарелкасындагы жашыл жашылчаларды четке түртүп жатышабы? Урушпаңыз. Пайдалуу рецепттер бөлүмүнөн жашылчаларды кекстердин же котлеттердин ичине жашыруунун акылдуу жолдорун табыңыз.','Köögiviljasõjad 🥦','Kas nad lükkavad taldrikul rohelised köögiviljad kõrvale? Ära võitle sellega. Leia tervislike retseptide sektsioonist nutikaid nippe, kuidas köögivilju muffinite või lihapallide sisse peita.'),
('465bfed4-fe0b-4cbe-96cc-61ab753a7ff8'::uuid,'Денедеги искусство 🖍️','Күтүүсүз жымжырттык сизди шекшитип, алардын колдоруна маркер менен «шедевр» жаратып жатканын көрдүңүз. Капа болбоңуз. Алар өздөрүнүн майда моторикасын изилдеп жатышат, ал эми теридеги боёк суу менен оңой эле жуулат. Терең дем алып, бул кызыктуу учурду эстеп калыңыз.','Kunst kehal 🖍️','See ootamatu vaikus tegi sind kahtlustavaks ja leidsid nad vildikatega oma kätele meistriteoseid joonistamas. Ära pahanda. Nad avastavad oma peenmotoorikat ja nahk saab veega puhtaks. Hinga sügavalt sisse ja jäädvusta see naljakas hetk.'),
('5f1b9ed1-3342-457d-874b-d33366fcceaf'::uuid,'Гипноздук шыбырлар 🤫','Алар төшөктө ушунчалык активдүү болгондуктан, такыр уктабай жатышат. Үнүңүздү көтөрүүнүн ордуна, аны кескин түрдө басаңдатып көрүңүз. Шыбырап гана сүйлөңүз. Балаңыз сизди угууга аракет кылганда, анын мээси табигый түрдө уйку режимине өтөт.','Hüpnootilised sosinad 🤫','Nad on voodis nii aktiivsed, et ei jää kuidagi magama. Selle asemel, et häält tõsta, proovi seda dramaatiliselt madaldada. Räägi ainult sosinal. Kui laps pingutab, et sind kuulda, lülitub tema aju loomulikult unerežiimile.'),
('6ac2df5a-944c-4a22-9450-7bfad30550c4'::uuid,'Биздин апалар коомчулугунун күчү 💬','Бул бала эч качан тынчыбайт деген ойдон чарчадыңызбы? Anacan Коомчулугуна кошулуңуз. Ал жерден башка энелердин өжөрлүк жөнүндөгү ушуга окшош, атүгүл андан да кызыктуу окуяларын окуу сиздин жалгыз эмес экениңизди түшүнүүгө жана жеңил дем алууга жардам берет.','Meie emade kogukonna vägi 💬','Oled kurnatud mõttest, et see laps ei rahune kunagi maha? Liitu Anacani kogukonnaga. Teiste emade sarnaste või veelgi naljakamate lugude lugemine aitab sul mõista, et sa pole üksi, ja kergendatult hingata.'),
('7b051600-3f87-4940-baec-461cd64e5af1'::uuid,'Кичинекей философ 🤔','Эмне үчүн шамалды көрө албайбыз? Эмне үчүн жалбырактар түшөт? Ушул сыяктуу терең суроолор эртең менен эле мээңизди чарчатышы мүмкүн. Сааттап илимий түшүндүрмө берүүгө аракет кылбаңыз. «Дарактар кийимдерин алмаштырып жатышат» деген сыяктуу таттуу, фантазиялуу жооптор бул курактагы балдарды толугу менен канааттандырат.','Väike filosoof 🤔','Miks me ei näe tuult? Miks lehed langevad? Sellised sügavad küsimused võivad su pead vaevata juba varahommikul. Ära ürita tunde teaduslikult selgitada. Armsad ja fantaasiarikkad vastused, nagu ''puud vahetavad riideid'', rahuldavad neid selles vanuses suurepäraselt.'),
('7bab0bc1-e2b8-4588-8d81-ecc8ddbde523'::uuid,'Көлөкө театры 🐰','Алар караңгыдан коркууну шылтоо кылып, уктоодон качып жатышат. Бөлмөнүн бардык жарыгын өчүрүп, кол чыракты алыңыз жана дубалга колдоруңуз менен канаттуулар, иттер сыяктуу кызыктуу көлөкө куурчактарын жасаңыз. Алар корккон караңгылык бир нече секунддун ичинде сыйкырдуу театрга айланат.','Varjuteater 🐰','Nad põgenevad magamamineku eest, kasutades ettekäändena hirmu pimeduse ees. Kustuta toas tuled, haara taskulamp ja tee kätega seinale lõbusaid varjuteatreid – linde, koeri. Nende kardetud pimedus muutub sekunditega maagiliseks teatriks.'),
('d0ef94fa-1acc-4932-b3b2-947791c88119'::uuid,'Жасалма интеллект жардамга келет 🤖','Балаңыздын суроолоруна же адаттан тыш жүрүм-турумуна жооп таба албай жатасызбы? Anacan AI менен кеңешиңиз. Ал 3 жаштан ашкан балдардын акылы кандай иштээрин педиатр сыяктуу ишенимдүү жана кыска түрдө түшүндүрүп берет.','Tehisintellekt appi 🤖','Ei leia vastuseid lapse küsimustele või ebatavalisele käitumisele? Konsulteeri Anacan AI-ga. See selgitab rahustavalt ja lühidalt, kuidas üle 3-aastaste laste mõttemaailm töötab, täpselt nagu lastearst.'),
('6701933c-47e8-4c97-996b-a27409d87c3c'::uuid,'Табышмактар жана логика 🧩','Алар 5-6 бөлүктөн турган пазлдарды чогултууга аракет кылып жатышабы? Алар геометрияны жана логиканы үйрөнүп жатышат! Бул кайталануучу, бирок билим берүүчү аракеттерге тоскоол болбоңуз.','Mõistatused ja loogika 🧩','Kas nad üritavad kokku panna 5-6-osalisi puslesid? Nad õpivad geomeetriat ja loogikat! Ära katkesta neid korduvaid, kuid harivaid tegevusi.'),
('a0d7169c-229c-430c-a926-4c31eef15e2c'::uuid,'Атанын колдоосу 🫂','Түн ичинде ойгонгондо сөзсүз кезектешип туруңуз. Кээде караңгыда атасынын ыргактуу эркелетүүсү жана жыты гана баланы заматта тынчтандырат.','Issi toetus 🫂','Vahetage öiste ärkamiste ajal kindlasti rolle. Mõnikord suudab vaid isa rütmiline silitus ja lõhn pimeduses lapse hetkega rahustada.'),
('55bba77e-306b-49e8-94ad-180de8387a8b'::uuid,'Көк алма талабы 🍏','Алар ойгонуп, көк алма сурап кыйкырып жатышат. Табиятта мындай нерсе жок экенин түшүндүрүп, физика же биология сабагын баштабаңыз. Анын ордуна, алардын логикасына: «Көк алмалар дагы эле уктап жатышат, кел, андан көрө кызыл алманы ойготолу!» — деген сыяктуу тамашалуу, бирок натыйжалуу жооп бериңиз.','Nõudmine sinise õuna järele 🍏','Nad ärkavad ja karjuvad sinise õuna järele. Ära hakka pidama füüsika- või bioloogiatundi selgitamaks, et looduses sellist asja ei eksisteeri. Selle asemel vasta nende absurdsele loogikale sama absurdse, kuid tõhusa vastusega: ''Sinised õunad veel magavad, äratame hoopis ühe punase!'''),
('5d5d4766-5ced-4cf7-8ea9-3acdffe118cf'::uuid,'Журп сүйүү 🛏️','Алар уктаар алдында күтүүсүз: «Жууркан сол бутума тийип жатат!» — деп кыйкырып жиберишет. 3,5 жаштагы баланын уктоо убактысын кечиктирүү үчүн ойлоп тапкан бул жаңы адатына ичиңизден жылмайып коюңуз. Унчукпастан жуурканды түздөп, бөлмөнүн жарыгын толугу менен өчүрүңүз.','Tekikaisutus 🛏️','Just siis, kui nad on uinumas, hüüavad nad äkki: ''Tekk puudutab mu vasakut jalga!'' Naerata sisemiselt sellele uuele kinnisideele, mille 3,5-aastane on välja mõelnud magamamineku edasilükkamiseks. Sõnagi lausumata kohenda tekki ja lülita toas tuled kindlalt välja.'),
('710f54a9-baa0-4889-a361-f7615894b552'::uuid,'Кесиптерди ролдоштуруп ойноо','Балаңыз оюнчук аюусун «дарылап» же оюнчук машиналарын «оңдоп» жатабы? Алардын ролдук оюндары чындап өнүгүп жатат!','Rollimängud ja ametid','Kas su laps ''ravib'' oma mängukaru või ''remondib'' mänguautosid? Nende sümboolne mäng (rollimäng) on tõeliselt hoogu võtmas!'),
('8bcf9de1-187f-451e-8f68-1235d768b6ad'::uuid,'Шектүү жымжырттыктын баасы 💄','Үйдөгү күтүүсүз 10 мүнөттүк жымжырттыктын аягы: Сиз бөлмөгө кирсеңиз, алар сиздин эң жакшы көргөн помадаңыз менен бетин да, күзгүнү да боёп алышыптыр. Эми ачуулануу кеч!','Kahtlase vaikuse hind 💄','Ootamatu 10-minutilise vaikuse lõpp kodus: astud tuppa ja nad on kasutanud sinu lemmikhuulepulka, et värvida nii oma nägu kui ka peeglit. Pahandamiseks on nüüd juba liiga hilja!'),
('42ac5c0d-b412-4999-8839-ddf0e44a9d4b'::uuid,'Атанын сыйкырдуу учак колдору ✈️','Күнү бою көтөрүп жүрүп колдоруңуз ооруп жатат, бирок алар дагы эле энергияга толуп, уктоого каршылык көрсөтүп жатышат. Атаны жардамга чакырыңыз! Ал баланы учак сыяктуу өйдө көтөргөндө, бөлмө күлкүгө толуп, топтолгон чексиз энергия заматта жок болот.','Issi võluvad lennukikäed ✈️','Sinu käed valutavad terve päeva kandmisest, kuid nad on ikka energilised ja tõrguvad magama minemast. Kutsu isa appi! Kui tema lapse õhku tõstab ja lennukit mängib, täitub tuba itsitamisega ja kogu see lõputu kogunenud energia on hetkega nullitud.'),
('fd37073a-86b1-4420-9d46-293b17c2e64b'::uuid,'Көрүнбөгөн ит менен сейилдөө 🐕','Алар бөлмөнүн ортосунда эңкейип, көрүнбөгөн итти эркелетип, аны менен сүйлөшүп жатышат. Бул — фантазиянын эң таза учуру. Алардан: «Иттин аты ким?» — деп сураңыз, андан кийин бөлмөнүн бурчуна элестүү суу идиш коюп, бул кереметтүү оюндун катышуучусу болуңуз.','Jalutuskäik nähtamatu koeraga 🐕','Nad kükitavad keset tuba, silitavad nähtamatut koera ja räägivad temaga. See on kujutlusvõime kõige süütum faas. Küsi neilt: ''Mis koera nimi on?'' ja hakka selles suurepärases mängus teisejärguliseks näitlejaks, asetades kujuteldava veekausi toa nurka.'),
('29371981-c485-4102-9d09-323cae4a8b4c'::uuid,'Гардероб козголоңу 🕶️','Алар эртең мененки тамакка күндөн коргоочу көз айнек жана кышкы баш кийим кийип чыгышты, аны чечүүдөн такыр баш тартышты. Эстетиканы жана «эл эмне дейт» дегенди унутуңуз. Өз алдынча чечим кабыл алуу жана анын артында туруу эркиндиги — кийимдин ылайыктуулугуна караганда алда канча маанилүү психологиялык пайдубал.','Garderoobimäss 🕶️','Nad tulid hommikusöögile päikeseprillide ja talvemütsiga ning keelduvad kategooriliselt neid ära võtmast. Unusta esteetika ja see, mida „teised arvavad“. Vabadus teha ise otsuseid ja nende eest seista on palju tugevam psühholoogiline vundament kui riietuse sobivus.'),
('51cdbeb9-6ab2-41f5-bfe2-9e148aedb489'::uuid,'Жымжырттыктын санариптик тарабы 🤫','Үйдөгү ызы-чуудан кулагыңыз тунарат. Алар акыры уктап калганда, «Үн ченегичти» (Sound Meter) иштетиңиз. Экрандагы санариптик тынчтыктын 0-10 децибелге чейин түшкөнүн көрүү — чарчаган эненин мээси үчүн эң кооз жана визуалдык жактан жагымдуу эс алуу.','Vaikuse digitaalne pool 🤫','Kodu lärm paneb kõrvus kohisema. Kui nad lõpuks uinuvad, lülita sisse oma helimõõtja. Selle digitaalse vaikuse jälgimine ekraanil 0–10 detsibellini on väsinud ema meelele kõige kaunim ja visuaalselt rahustavam massaaž.'),
('fca5f016-a334-4b48-86a0-e10c617f28f2'::uuid,'Кумурсканы куткаруучу 🐜','Паркта жердеги кумурсканы басып албаш үчүн ыйлап, жолуңузду тосуп калыштыбы? Алардын чексиз, боорукер мээримине суктаныңыз.','Sipelgate päästja 🐜','Kas nad puhkesid pargis nutma ja tõkestasid su tee, et kaitsta maas olevat sipelgat mahatallamise eest? Imetle nende tohutut ja kaastundlikku empaatiavõimet.'),
('02c49204-da15-4fa6-aab8-953dbda0aa33'::uuid,'Акылдуу жомоктогу мен 🪄','Классикалык китептерди окуудан үнүңүз чарчадыбы? «Акылдуу жомокторду» (Smart Tales) ачыңыз. Балаңызды токойдун тынчтандыруучу үндөрү коштогон жомоктун башкы каарманы кылып, өзгөчө, жеңил жана уйкуну чакыруучу сеанс түзүңүз.','Mina nutikas loos 🪄','Sinu häälepaelad on klassikaliste raamatute lugemisest väsinud. Ava Smart Tales. Kujunda oma laps peategelaseks, taustaks rahustavad metsahelid, luues erakordse, vaevatu ja hüpnootilise uneaja.'),
('b5cdd715-cb24-4a73-93b6-d40eb1d78c2e'::uuid,'Коомчулуктун үнсүз колдоосу 💬','«Мен эч качан мурдагыдай эркин, камсыз болбой каламбы?» деген ой сизди каптап жатабы? Anacan коомчулугуна кошулуңуз. Башка энелер да ушундай татаал, бирок абдан табигый сезимдерди башынан өткөрөрүн окуп, сооронуч табыңыз — бул энеликтин бир этабы гана.','Kogukonna vaikne lohutus 💬','Kas sind valdab äkiline mõte, et sa ei saa enam kunagi oma vana, vaba ja muretu mina juurde tagasi? Liitu Anacani kogukonnaga. Leia lohutust lugedes, et ka teised emad kogevad neid keerulisi, kuid väga loomulikke tundeid – see on emaduse üks etapp.'),
('dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c'::uuid,'Сөз ремикси 🗣️','Алар «суу» жана «сүт» деген сөздөрдү бириктирип, «сүтсуу» сыяктуу ойдон чыгарылган сөздөрдү айтып күлүп жатышабы? Алар сөз байлыгын жаңылап жатышат! Алардын тил оюнуна чын жүрөктөн күлүп кошулуңуз; баланын мээси тилдин чектерин ушинтип изилдейт.','Sõnademäng 🗣️','Kas nad kombineerivad sõnu nagu „vesi“ ja „piim“, luues täiesti uusi sõnu nagu „piimavesi“ ja naeravad? Nad teevad oma sõnavaraga remiksi! Liitu nende keelemängudega südamest naerdes; just nii uurib nende aju keele piire.'),
('4d3c3b0d-80ec-45f4-815f-fb2e6cc34948'::uuid,'Күтүлбөгөн сүйүү сезими 🫂','Бүгүн эртең менен сизге «кетчи» деген бала, уктаар алдында мойнуңузду кучактап: «Мен сени айга чейин сүйөм» деп жатабы? Бул энеликтин парадоксу! Ошол жылуу демди ичиңизге тартып, күндүн бардык чарчоосун унутуңуз.','Äkiline armastusepuhang 🫂','Laps, kes käskis sul täna hommikul „ära minna“, mässib nüüd magamamineku ajal oma käed tihedalt ümber su kaela ja ütleb: „Ma armastan sind kuuni ja tagasi.“ See on emaduse paradoks! Hinga sisse seda sooja väikest hingeõhku ja lase kogu päeva väsimusel hajuda.'),
('50186ca0-d65c-4eb2-80df-487222e57b43'::uuid,'Кетчи, апа! 💔','Алар каалаганы болбой калганда сизге карап: «Сен мага керек эмессиң, кетчи!» деп айтышабы? Капа болбоңуз. Алар азырынча ачуусун башкарууну билишпейт. Муну жеке кабыл албаңыз; жөн гана: «Мен бул жердемин, тынчтанганыңда сүйлөшөбүз» деп, аларга сезимдерин басып алуу үчүн мейкиндик бериңиз.','Mine ära, emme! 💔','Kui nad ei saa oma tahtmist, kas nad vaatavad sulle otsa ja ütlevad: „Ma ei taha sind, mine ära!“? Ära lase südamel murduda. Nad ei oska veel oma vihaga toime tulla. Ära võta seda isiklikult; ütle lihtsalt: „Ma olen siin ja me saame rääkida, kui oled rahunenud,“ andes neile ruumi oma emotsioone kogeda.'),
('ee0e20bd-35e2-417c-adfc-d1000ee7da40'::uuid,'Сиздин соода боюнча жардамчыңыз 🛒','Дүкөндөн таттуу үчүн ыйлабай, «эгер муну алсак, үйдө шорпомду ичем» деп соодалашып жатышабы? Куттуктайбыз, кичинекей юристиңиз чоңоюп жатат! Унутчаактыкка жол бербөө үчүн «Соода тизмеңизди» жаныңызда кармаңыз, ошондо соодалашуу учурунда негизги максатыңыздан адашпайсыз.','Sinu ostuadvokaat 🛒','Selle asemel, et poes kommi pärast jonnida, nad kauplevad: „Kui me selle saame, siis söön kodus oma supi ära.“ Õnnitlused, su väike advokaat on suureks kasvamas! Unustamise vältimiseks hoia oma ostunimekiri käepärast, et sa ei kaotaks läbirääkimiste käigus silmist oma peamist eesmärki.'),
('2ee42120-6dce-4972-a1f5-41636027a46e'::uuid,'Ваннадагы цунами 🌊','Чоюнуу убактысы эми тазалануу эмес, кичинекей цунами жаратуу оюнуна айланды. Сууну чачыратыңыз! Суунун энергияны сиңирүүчү сыйкырдуу таасири күн бою топтолгон терс энергияны жууп, агызып кетет.','Vannitsunami 🌊','Vanniskäik ei tähenda enam puhtaks saamist, vaid minitsunami loomist. Lase veel igale poole pritsida! Vee müstiline, energiat neelav magnetiline toime peseb maha kogu selle kangekaelse negatiivse energia, mis on päeva jooksul kogunenud, ja saadab selle kanalisatsiooni.'),
('3a758cd5-028f-4ac8-be02-5dda6a95b453'::uuid,'Апанын жалкоо болуу укугу 🍕','Бүгүн баарына кыйкыргыңыз келип жатабы? Үй чачыкпы? Тазалоону унутуңуз, тамак жасоодон стресс болбоңуз. Пицца же даяр тамак заказ кылыңыз. «Кемчиликсиз эне» болуу иллюзиясынан арылыңыз; сиздин психологиялык абалыңыз үй тамагынан алда канча баалуу.','Emme õigus olla laisk 🍕','Kas tunned täna, et tahaksid kõige peale karjuda? Kas maja on sassis? Unusta koristamine, ära muretse söögitegemise pärast. Telli pitsat või mida iganes on väljastpoolt kõige lihtsam saada. Vabane täiusliku ema illusioonist; sinu psühholoogiline heaolu on palju väärtuslikum kui kodus valmistatud eine.'),
('d683b351-38a0-49ed-a8b1-b2fe98cd3d08'::uuid,'Өзүм жасайм! 💧','Алар чоң кумурадагы сууну кичинекей чөйчөккө өздөрү куюуга аракет кылышат. Суу столго, анан полго төгүлөт. Бирок алардын чүпүрөктү алып, аны тазалоого аракет кылган кичинекей колдорун караңызчы. Алар ката кетирүү аркылуу жоопкерчиликти үйрөнүп жатышат; бул башаламандык — өнүгүүнүн өзү.','Teen ise! 💧','Nad nõuavad, et saaksid ise suurest kannust väikesesse tassi vett valada. Vesi voolab lauale, siis põrandale. Aga vaata nende pisikesi käsi, mis üritavad lappi haarata ja seda koristada. Nad õpivad vastutust läbi vigade tegemise; see kaos ongi arengu olemus.'),
('746ce0d9-945c-4d05-9518-1097d9f22fcd'::uuid,'Кайчыны колдонууну үйрөнүү ✂️','Алар кагазды балдар үчүн коопсуз пластик кайчы менен кесүүгө аракет кылып жатышабы? Бул майда моториканы өнүктүрүү үчүн эң сонун көнүгүү! Муну өнүгүү күндөлүгүнө жазып коюңуз.','Kääridega lõikama õppimine ✂️','Kas nad üritavad lastele mõeldud plastkääridega paberit lõigata? See on suurepärane peenmotoorika harjutus! Veendu, et logid selle nende arengupäevikusse.'),
('d01a4de6-1799-4ace-b8f9-b22ea720b143'::uuid,'«Мага карачы!» талабы 👀','Сиз телефон карап же башка иш менен алек болгондо, алар келип жүзүңүздү өздөрүнө бурушабы? Алар сиздин толук көңүлүңүздү каалашат. Угуп жатканыңызды билдирүү үчүн көз карашыңызды алардын көзүнө буруңуз.','„Vaata mind!“ nõudlikkus 👀','Kui vaatad telefoni või teed midagi muud, kas nad tulevad ja pööravad su näo enda poole? Nad tahavad su täielikku tähelepanu. Võta silmside, et näidata, et kuulad neid.'),
('ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c'::uuid,'Атасынын кезеги 👨‍🍼','Түнкү уйкунун түйшүгүн жалгыз өзүңүз тартпаңыз. Өнөктөшүңүздү да ойготуңуз; команда болуу — жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi kord 👨‍🍼','Ära kanna öiste ärkamiste koormat üksi. Ärata ka oma partner; meeskonnaks olemine tähendab kohustuste võrdset jagamist.'),
('4e5540da-110f-46b1-a6fe-0833314d27a6'::uuid,'Кечки тамакка эмне болот дилеммасы 🍲','Кошумча тамактандыруу менюсу үчүн идеялар түгөнүп жатабы? Интернеттен адашпаңыз; «Дени сак рецепттер» бөлүмүнөн жаңы даамдарды табыңыз.','Õhtusöögidilemma 🍲','Kas ideed lisatoidu menüü jaoks hakkavad otsa saama? Ära eksle internetis; avasta uusi maitseelamusi jaotises Tervislikud retseptid.'),
('7d3efca9-83bd-4ef7-a064-007baae56a2f'::uuid,'Жеке жомок 🪄','«Акылдуу жомоктордо» балаңыз башкы каарман болгон өзгөчө жомок түзүңүз: «Сыйкырдуу кайчы менен дүйнөнү боёгон эр жүрөк наристе».','Isiklik muinasjutt 🪄','Loo „Nutikates lugudes“ eriline muinasjutt, kus su laps on kangelane: „Vapper väike tegelane, kes värvib maailma võlukääridega“.'),
('fa3aa9fa-1390-45bd-833a-86ce9790410b'::uuid,'Жардам берейин! 🧹','Кир жууп жатканда кийимдерди колуңуздан жулуп жатышабы? Алар өздөрүн чоң жардамчы сезип жатышат! Аларга кичинекей сүлгү берип, жардам берүүсүнө уруксат бериңиз.','Luba, ma aitan! 🧹','Kas nad üritavad pesu voltides su käte vahelt riideid haarata? Nad tunnevad end juba suure abilisena! Anna neile väike rätik ja lase neil aidata.'),
('9049cae3-8dbb-4e95-8c21-0965664d904f'::uuid,'Сизге бир сыр айтып берейин 🤫','Уктаар алдында көздөрү жумулуп баратканда, «Апа, сизге бир сырым бар!» деп уйкудан качууга аракет кылышабы? Алар уктаар убакытты кечиктирүү искусствосу боюнча докторлук даражасын алып жатышат. Жылмайып, жарыкты өчүрүп: «Сырыңды түшүңдө айтып бер» деп коюңуз.','Räägin sulle ühe saladuse 🤫','Just siis, kui nad on voodisse pandud ja silmad hakkavad sulguma, üritavad nad und edasi lükata, öeldes: „Emme, mul on sulle saladus!“ Nad on praktiliselt omandamas doktorikraadi magamamineku edasilükkamise kunstis. Naerata ja lülita tuled kindlalt välja, öeldes: „Räägi mulle oma saladus unes.“'),
('27873a53-69de-4c27-a20c-c15256739b9a'::uuid,'Биз бир командабыз! 🌟','Түнкү ойгонуулардан чарчадыңызбы? Өнөктөшүңүздү ойготуудан тартынбаңыз. Команда болуу — бул жүктү бөлүшүү жана бири-бириңизди сүйүү менен колдоо.','Oleme meeskond! 🌟','Kas oled öistest ärkamistest kurnatud? Ära kõhkle oma partnerit äratamast. Meeskonnaks olemine tähendab koorma jagamist ja üksteise toetamist armastusega.'),
('a097a156-cfb7-4bbb-a187-0b6a9ba7dade'::uuid,'Печеньенин даамдуу ичи 🍪','Алар печеньенин ортосундагы кремди жалап, кургак бөлүктөрүн столдун четине тизип коюштубу? Куттуктайбыз, сиз 3,5 жашар баланын тамак философиясы менен расмий тааныштыңыз. Алардын көңүлүн бура турган, кызыктуу жана пайдалуу тамактарды «Дени сак рецепттерден» табыңыз.','Küpsise kreemine sisu 🍪','Kas nad lakkusid ümmarguste küpsiste keskelt kreemi ära ja sättisid kuivad osad laua servale? Õnnitlused, oled ametlikult tutvunud 3,5-aastase toidufilosoofiaga. Avasta Tervislike retseptide hulgast mõistlikumaid, kuid lõbusaid suupisteid, mis nende tähelepanu köidavad.'),
('bf046ede-b62a-43aa-8a59-9305494237e5'::uuid,'Ырдоого болбойт! 🛑','Фондо ойноп жаткан балдар ырына кошулуп ырдасаңыз, алар дароо: «Ырдаба!» деп кыйкырыштыбы? Бөлмөдөгү жалгыз солист — алар, сиздин вокалдык аракеттериңиз алардын сахнасын ээлеп жатат. Таарынбаңыз; сахнаны бул кичинекей дивага калтырыңыз.','Laulmine keelatud! 🛑','Sa ümisesid taustal mängiva lastelaulu kaasa ja nad karjusid kohe: „Ära laula!“ Nad on toas ainus solist ja sinu vokaalsed katsed trügivad nende lavale. Ära solvu; jäta tähelepanu keskpunkt sellele väikesele diivale.'),
('6b819068-b681-48a9-82bf-6d4801827c9e'::uuid,'Апанын дубалды тиктеп отуруусу 🛋️','Бөлмөдө ызы-чуу, алар оюнчуктарын уруп жатышат, ал эми сиз дубалды тиктеп, эч нерсени сезбей отурасызбы? Бул мээңиздин коргоо механизми. Өзүңүзгө ошол 5 мүнөттүк тыныгууну бергениңиз үчүн өкүнбөңүз; жашоого кайтып келүү үчүн бул сизге керек.','Emme võiduvaatamine seinaga 🛋️','Toas on lärm, nad taovad mänguasju kokku ja sina lihtsalt vaatad tühja pilguga seina, olles täiesti omas maailmas. See on su aju kaitsemehhanism. Ära keela endale seda 5-minutilist tardumust; vajad seda, et eluga edasi minna.'),
('6b9b4528-1015-4f69-940f-0bb0951b3bab'::uuid,'Эл алдындагы ыңгайсыз суроолор 😳','Автобуста же супермаркетте: «Эмне үчүн тиги аялдын мурду чоң?» деп катуу сураштыбы? Жер жарылып кирип кетсе экен деген учур! Аларды унчукпай кой деп уят кылбай, дароо көңүлүн башка түстүү нерсеге буруп, кырдаалдан дипломатиялык жол менен чыгып кетиңиз.','Piinlikud küsimused avalikus kohas 😳','Kas nad küsisid bussis või supermarketis valjult: „Miks sellel tädil nii suur nina on?“ See hetk, mil soovisid, et maa sind neelaks! Selle asemel, et neid vaigistada ja häbi tunda, päästa end olukorrast diplomaatiliselt, suunates nende tähelepanu kohe mõnele teisele värvilisele objektile.'),
('8d369fcb-2b04-4658-a824-5b34c817cbfd'::uuid,'Атанын кызыктуу эрежелери 🎲','Түнкүсүн пижама кийбеш үчүн үйдө чуркап жүрүшөбү? Атасы: «Кел, көзүңдү жумуп кийинип көрчү!» деген кызыктай оюн ойлоп табат. Жана болду! Бала байкабай эле кийинип калат. Аталардын бул логикасыз, бирок эффективдүү оюндары кол чабууларга гана татыктуу.','Issi mängulised reeglid 🎲','Öösel jooksevad nad mööda maja, et vältida pidžaama selgapanemist. Nende isa mõtleb välja absurdse mängu: „Vaatame, kas suudad selle pidžaama kinnisilmi selga panna!“ Ja pauk! Lapsel on see seljas, ilma et ta arugi saaks. Need ebaloogilised, kuid tõhusad mängud, mida isad mängivad, väärivad vaid aplausi kõrvaltvaatajatelt.'),
('5eac5298-1552-4198-9ef8-4a16006b3701'::uuid,'Мен кайрадан наристемин! 🍼','Бир маалда сойлоп, ыйлап: «Мен наристемин, мени кучактачы» деп калыштыбы? Чоңоюу кээде алар үчүн коркунучтуу болушу мүмкүн, ошондуктан алар наристелик коопсуз күндөрүнө кайткысы келет. Мурдагыдай эле бир нече мүнөт кучактап, сооротуп коюңуз.','Olen jälle tita! 🍼','Kas nad hakkasid äkki roomama, nutma ja ütlema: „Ma olen beebi, kallista mind“? Suureks kasvamine võib nende jaoks vahel hirmutav olla ja nad tahavad naasta imikuea vanadesse turvalistesse päevadesse. Hoia ja lohuta neid mõni minut, täpselt nagu tegid neil varasematel aegadel.'),
('bb01fed8-0d6f-4127-8a47-f959e37b46e4'::uuid,'Баткактан жасалган шорпо 🍲','Паркта суу менен топуракты аралаштырып, сизге: «Апа, мен сизге шорпо жасадым!» деп сунушташтыбы? Жийиркенүүгө болбойт! Ал шорпо дүйнөдөгү эң даамдуу тамак деп элестетиңиз.','Mudasupp 🍲','Pargis segavad nad vett ja mulda, ulatades sulle siis selle porimöksi sõnadega: „Emme, tegin sulle suppi!“ Vastikustunne on keelatud! Kujuta ette, et see supp on kõige maitsvam eine, mida oled kunagi söönud.'),
('c5e8c723-3ce3-424f-8294-5aece5936ca5'::uuid,'Санариптик тынчтыктын таттуулугу 🤫','Үйдөгү башаламандык аяктап, алар уктап калышты. «Үн ченегичти» (Sound Meter) ачып, бөлмөдөгү тынчтыктын деңгээлин (0-10 децибел) экрандан көрүңүз. Сандардын нөлгө жакындаганын көрүү — чарчаган эненин мээси үчүн дүйнөдөгү эң кымбат спа-сеанс сыяктуу.','Digitaalse vaikuse magusus 🤫','Kodu kaos on lõpuks lõppenud ja nad on uinunud. Ava helimõõtja ja vaata ekraanilt ruumi vaikuse taset (0–10 detsibelli). Nende numbrite nullilähedaseks muutumise jälgimine tundub väsinud ema meelele kui maailma kõige luksuslikum spaaprotseduur.'),
('204c6838-b697-4616-9592-52e0162c6a92'::uuid,'Банандын белгиси 🍌','Балаңыз бананды аарчып, кичинекей такты көрүп: «Бул бузулуп калыптыр!» деп ыйлап жатабы? Алардын визуалдык кемчиликсиздикке умтулуусу жаңы деңгээлде. Жөн гана бычак менен ошол кичинекей жерди кесип алып: «Мен аны сактап калдым!» деп айтыңыз, ошондо бул кичинекей драма токтойт.','Banaani plekk 🍌','Su laps koorib banaani, märkab pisikest millimeetrist plekki ja hüüatab: „See on rikutud!“ Nende visuaalse täiuslikkuse taotlus on täiesti uuel tasemel. Lõika lihtsalt noaga see pisike tükk ära ja kuuluta: „Päästsin selle!“ et teha sellele minidraamale lõpp.'),
('49d8e195-1371-46c6-a98a-c6f38e78e098'::uuid,'Эшикти кулпулоо миссиясы 🚪','Алар үйдөгү бардык эшиктерди жаап, Сизди сыртта калтыруудан өзгөчө ырахат алышабы? Алардын жеке мейкиндик жөнүндөгү түшүнүгү өзгөрүп жатат! Кичинекей манжаларын коргоо үчүн алдын ала чараларды көрүңүз, бирок алардын өз аймагын ээлөө оюнуна олуттуу тоскоол болбоңуз.','Ukse lukustamise missioon 🚪','Kas neile pakub erilist naudingut kõikide maja uste sulgemine ja sinu väljapoole jätmine? Nende arusaam isiklikust ruumist on revolutsiooniline! Võta tarvitusele ettevaatusabinõud, et kaitsta nende väikeseid sõrmi, kuid ära seda oma territooriumi hõivamise mängu liialt takista.'),
('524b4634-31bf-4fa3-860b-d29e08cc3c10'::uuid,'Жомок айтып жаткандагы ар кандай үндөр 🪄','Бүгүн кечинде Smart Tales бөлүмүн ачыңыз, бирок текстти башкача окуңуз. Аюунун үнүн жоон, ал эми канаттуунун үнүн ичке кылып, бөлмөдө кичинекей театр уюштуруңуз. Бул бир түрдүүлүктү бузуп, баланын көңүлүн дароо жомокко бурат, ал эми андан ары уйкуга жетелейт.','Erinevad hääled unejutu ajal 🪄','Ava täna õhtul Smart Tales, kuid loe teksti teistmoodi. Loo toas väike teater, tehes karu hääle sügavaks ja linnu hääle kõrgeks. See lõhub monotoonsuse ja tõmbab lapse tähelepanu hetkega loosse ning sealt edasi juba unne.'),
('603225e8-0807-426b-b793-892dfeb9e281'::uuid,'Караңгыда шыбырашып ачылган сырлар 🌙','Бөлмөнүн жарыгын толугу менен өчүрүңүз. Анын жанына жатып, күндүз эмне болгонун же анын мүнөзүндөгү Сизге жаккан өзгөчөлүктү кулагына акырын шыбыраңыз. Шыбыроо — мээни уйкуга даярдоонун жана ызы-чууну унуттуруунун эң сыйкырдуу ыкмасы.','Sosistatud avastused pimeduses 🌙','Kustuta toas tuled täielikult. Heida nende kõrvale ja sosista vaikselt kõrva, mis päeva jooksul juhtus või mis on sinu lemmikdetail nende iseloomu juures. Sosistamine on kõige müstilisem meetod aju uneks ettevalmistamiseks ja müra unustama panemiseks.'),
('60fcf611-529f-4586-9532-af738483766f'::uuid,'Үйдүн ичинде кол чатыр ачуу ☂️','Сыртта күн тийип турса да, ал үйдүн ичинде кол чатыр менен жүрүүнү каалайт. Анын фантазиясы физикалык чөйрө менен чектелбейт. Эгер орун жетиштүү болсо, ошол кол чатырдын астында кичинекей лагерь курууга уруксат бериңиз. Баланын логикасын коомдук нормалар менен чектебеңиз.','Vihmavari toas ☂️','Väljas paistab päike, aga nemad tahavad avatud vihmavarjuga mööda maja ringi käia. Nende kujutlusvõimet ei piira füüsiline keskkond. Kui ruumi on piisavalt, lase neil selle vihmavarju all väike telk ehitada. Ära lämmata lapse loogikat ühiskondlike normidega.'),
('831decae-1343-4bbb-bf11-1f398cc1bc2d'::uuid,'Дүкөндөгү «жок» деп айтуу сыноосу 🛒','Балаңыз супермаркеттин ортосунда момпосуй сурап, Сиз "жок" дегениңизде ыйлай баштадыбы? Башкалардын караганына карабай, чечимиңизде бекем турдуңуз. Сиз эң сонун энесиз! Унутуп калбоо жана тезирээк чыгып кетүү үчүн көзүңүздү соода тизмесинен албаңыз.','„Ei“-katse toidupoes 🛒','Sinu laps nõudis supermarketis kommi, sina ütlesid ei ja tema hakkas nutma. Jäid oma otsusele kindlaks, hoolimata hukkamõistvatest pilkudest. Oled suurepärane ema! Unustamise vältimiseks ja kiireks lahkumiseks hoia silm peal oma ostunimekirjal.'),
('1d613098-d421-410e-ae85-8cfd9552b432'::uuid,'Эмнеге менин атымды атадыңыз? 😤','Сиз жөн гана "Кел, тамак даяр" дедиңиз, ал болсо "Эмнеге менин атымды айттың?" деп ачууланып ыйлап кирди. Бул куракта сезимдер ушунчалык аралашып кеткендиктен, кээде алар жок жерден капа болушу мүмкүн. Эч нерсени түшүндүрүүгө аракет кылбаңыз; эки мүнөттөн кийин ал өзү эле тамак ичүүгө чуркап келет.','Miks sa mu nime hüüdsid? 😤','Ütlesid lihtsalt: „Tule, toit on valmis,“ ja tema sai pahaseks, karjudes: „Miks sa ütlesid minu nime?“ Selles vanuses on emotsioonid nii sassis, et nad võivad vahel tühjast kohast ärrituda. Ära proovi midagi selgitada; kahe minuti pärast jookseb ta tõenäoliselt ise sööma.'),
('ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02'::uuid,'Жасалма интеллект жана кызыктай фобиялар 🤖','Ал дайыма ойноп жүргөн кызыл машинадан күтүүсүздөн корко баштадыбы? Эгерде ушундай түшүнүксүз коркунучтар Сизди тынчсыздандырса, кооптонууну жараткан онлайн форумдардан алыс болуңуз. 3,5 жаштагы баланын фантазиясынын кызыктуу өзгөчөлүктөрү тууралуу Anacan AI''дан илимий жана тынчтандыруучу жооп алыңыз.','AI ja omapärased foobiad 🤖','Kas nad kardavad äkki punast autot, millega on alati mänginud? Kui need seletamatud hirmud sind muretsema panevad, hoia eemale ärevust tekitavatest veebifoorumitest. Küsi Anacan AI-lt teaduslikku ja rahustavat vastust 3,5-aastase lapse kujutlusvõime põnevate iseärasuste kohta.'),
('cacabcad-105f-4eff-bcae-aa81bf6e1cbd'::uuid,'Экөөбүз үчүн кино кечеси... 🎬','Бала уктады! Сиз акыры жолдошуңуз менен кино көрүү үчүн диванга жайгаштыңыз, бирок 10-мүнөттө экөөңүз тең уктап калдыңыз. Бул Сиздин реалдуулугуңуз. Бири-бириңизге жөлөнүп уктап калган ошол чарчаган көрүнүш — командалык иштин чыныгы көрүнүшү.','Filmiõhtu kahekesi... 🎬','Laps magab! Jõudsid lõpuks diivanile partneriga filmi vaatama, kuid 10. minutiks olite mõlemad sügavas unes. See ongi sinu reaalsus. See väsinud stseen, kus üksteise najal magatakse, on tõeline meeskonnatöö väljendus.'),
('45baf1a1-9599-41ad-8361-b1f8a05e79a2'::uuid,'Төшөктөгү күкүмдөр 🍞','Эртең менен көзүңүздү ачсаңыз, төшөк печеньенин күкүмдөрүнө толуп калыптыр. Көрсө, ал эрте туруп, өзүнө эртең мененки тамакты уюштуруп алган экен! Урушкандын ордуна, бул өз алдынча маселе чечүү жөндөмүн Өнүгүү трекерине кызыктуу эс тутум катары жазып коюңуз.','Puru voodis 🍞','Hommikul silmi avades leiad voodi täis küpsisepuru. Tuleb välja, et nad korraldasid varakult omaenda hommikusöögi! Selle asemel, et karjuda, märgi see iseseisev probleemilahendusoskus naljaka mälestusena oma arengupäevikusse.'),
('5b590891-270c-48fa-a5d7-d69f319ed48e'::uuid,'Атанын ийинди укалоосу 💆‍♂️','Бүгүн Сиз күнү бою бутуңуздан тик турдуңуз; баланын артынан чуркап, оюнчуктарды жыйнап, белиңиз үзүлүп кете жаздады. Бала уктаар замат, жолдошуңуздан 10 мүнөттүк ийин массажын сураңыз. Сиз үйүңүздүн тирегисиз, ал эми тиректер сөзсүз түрдө эс алууга жана калыбына келүүгө муктаж.','Issi õlamassaaž 💆‍♂️','Oled täna terve päeva jalgadel olnud; selg valutab neile järele jooksmisest ja mänguasjade korjamisest. Niipea kui laps uinub, palu partnerilt 10-minutilist õlamassaaži. Oled oma kodu tugisammas ja sambad vajavad hädasti puhkust ja taastumist.'),
('5ff3402c-285a-4d58-a123-bc33ce162448'::uuid,'Өзүм эле жасайм! 🛑','Ал бут кийиминин боосун өзү байлайм деп өжөрлөнүп, колунан келбей ачууланып, Сиздин жардамыңыздан кескин баш тартып жатабы? Терең дем алыңыз. Анын келечеги үчүн бир аз кечигүүгө караганда, өзүнө болгон ишениминин жабыркабаганы алда канча маанилүү. Жөн гана күтө туруңуз.','Teen ise! 🛑','Nad nõuavad, et saaksid ise paelu siduda, ei saa hakkama, muutuvad frustreerituks ja tõrjuvad agressiivselt sinu abi. Hinga sügavalt sisse. Kriimustamata ego on nende tuleviku jaoks palju olulisem kui veidi nihkunud ajakava. Lihtsalt oota see hetk ära.'),
('8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346'::uuid,'«Мага карашты!» деген кырсык 👀','Паркта башка бир бала карап койгону үчүн эле балаңыз ыйлап жибердиби? Социалдык чек араларды жаңыдан таанып жаткан кичинекей бала үчүн башка бирөөнүн караганы да кийлигишүү сыяктуу сезилиши мүмкүн. Аны кучактап, "Ал сенин сонун көйнөгүңдү эле карап жатат" деп айтыңыз жана көңүлүн акырын башка жакка буруңуз.','„Nad vaatasid mind!“ katastroof 👀','Kas su laps puhkes pargis nutma lihtsalt sellepärast, et teine laps teda vaatas? Väikesele lapsele, kes alles avastab sotsiaalseid piire, võib isegi võõras pilk tunduda sissetungina. Kallista teda, ütle: „Ta lihtsalt vaatas su lahedat särki,“ ja juhi tähelepanu õrnalt kõrvale.'),
('b272e283-3b37-4825-9917-d8f7f4f54d69'::uuid,'Кызыктуу жомоктор менен тынчтануу 🪄','Ал бөлмөдө чуркап жүрүп, төшөккө жатуудан баш тартып жатабы? Жарыкты басаңдатыңыз. Smart Tales бөлүмүнөн кызыктуу окуяны таап, окуп бериңиз.','Rahu läbi nutikate lugude 🪄','Nad jooksevad toas ringi ja keelduvad voodisse minemast. Hämarusta tuled. Loo ja loe kaasahaarav lugu Smart Talesist.'),
('ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc'::uuid,'Оюнчуктарды катар тизүү 🚗','Кичинекейиңиз бөлмөнүн бир четинен экинчи четине чейин бардык машиналарын тизип, бирин да жылдырууга уруксат бербей жатабы? Бул анын визуалдык тартипке болгон умтулуусу. Бул кичинекей архитектордун эмгегине алыстан суктаныңыз жана анын шедеврине тоскоол болбоңуз.','Mänguasjade ritta seadmine 🚗','Sinu väike laps rivistab kõik oma autod hoolikalt ühest toa otsast teise ega luba ühtegi liigutada. See on nende püüd visuaalse korra poole. Imetle vaikselt eemalt selle pisikese arhitekti tööd ja ära nende meistriteost häiri.'),
('0136ed32-a803-4c48-aa0d-ab3379945e1c'::uuid,'Эл арасында жашыруун байкоочу болуу 💬','Сиз аябай чарчадыңыз жана эч нерсени түшүндүргүңүз же эч кимге ичиңизди төккүңүз келбей жатабы? Anacan Коомчулугуна кошулуп, жөн гана байкоочу болуңуз. Башка энелердин ушундай эле кызыктай кризистерди кантип жеңип жатканын көрүү — эң күчтүү үнсүз терапия.','Salajane vaatleja avalikus kohas 💬','Oled täiesti kurnatud ega taha midagi selgitada ega kellelegi kurta. Liitu Anacan Communityga ja ole lihtsalt vaikne vaatleja. Nägemine, kuidas teised emad sarnaste absurdsete kriisidega toime tulevad, on kõige võimsam vaikne teraapia.'),
('b9bc7eed-7b9f-4aa8-8301-118abf554ade'::uuid,'Кашыктын көлөмү боюнча драма 🥄','Сиз шорпону чоң кашык менен бергениңиз үчүн чоң нааразычылык башталдыбы! "Мен кичинекей кашыкты каалагам!" деп өжөрлөнүп жатабы? Тамак бир эле болсо да, анын логикасы боюнча, кашыктын көлөмү тамактын даамын өзгөртөт. Талашпаңыз; жөн гана кашыкты алмаштырып, күчүңүздү үнөмдөңүз.','Lusika suuruse draama 🥄','Puhkes täiemahuline protest, sest pakkusid suppi suure lusikaga! „Tahtsin väikest lusikat!“ nõudsid nad. Isegi kui toit on sama, muudab lusika suurus nende loogika järgi toidu maitset. Ära vaidle; vaheta lihtsalt lusikas ja säästa oma energiat.'),
('c2cb9b1d-61a5-43c0-97ec-813152f9cfe1'::uuid,'«Мени жаап кой!» деген адат 🛏️','Ал уктаар алдында күтүүсүздөн: "Жууркандын бурчу ачылып калды, мени жап!" деп кыйкырат. Жууркандын четтери түз болушу ал үчүн өтө маанилүү. Жуурканды үтүктөлгөндөй кылып түздөңүз жана бул кызыктуу уйку алдындагы ырым-жырымдарга ичиңизден жылмайып коюңуз.','„Kata mind kinni!“ kinnisidee 🛏️','Just siis, kui nad on uinumas, hüüavad nad äkki: „Tekinurk läks lahti, kata mind!“ Nende jaoks on eluliselt tähtis, et tekiääred oleksid täiesti sirged. Sirgenda tekki, nagu oleks see triigitud, ja naerata sisemiselt nendele lõbusatele magamaminekurituaalidele.'),
('4aca275a-17a5-44c6-88b5-fa54de701839'::uuid,'Пластырга болгон кумар 🩹','Кичинекейиңиз денесинен көрүнбөгөн "жараат" таап алып, пластырь чаптоону талап кылып жатабы? Бул физикалык оору эмес, жөн гана Сиздин көңүлүңүзгө жана мээримиңизге болгон муктаждык. Жөн гана ошол кичинекей пластырды чаптап, өөп коюңуз – ишениңиз, бул Сиздин күнүңүздү сактап калат.','Plaastrisõltuvus 🩹','Sinu väike laps on leidnud oma kehal nähtamatu haava ja nõuab, et paneksid plaastri peale. See ei ole seotud füüsilise valuga; see on puhas vajadus sinu tähelepanu ja kiindumuse järele. Pane see pisike plaaster peale ja anna suudlus – usu meid, see päästab su päeva.'),
('6549682b-784d-4e30-b184-53c2ea51b45f'::uuid,'Тынчтыктын визуалдык ырахаты 🤫','Үйдөгү баш аламандык акыры бүтүп, ал уктады. Идиш жууганга шашпаңыз! Үн өлчөгүчтү күйгүзүп, 15 мүнөт бою абсолюттук тынчтыкты (0-10 децибел) байкаңыз. Зээниңиз кантип эс алып, бул визуалдык бейпилдик Сизди айыктырып жатканын сезиңиз.','Vaikuse visuaalne õndsus 🤫','Majas valitsev kaos on lõpuks läbi ja nad magavad. Ära kiirusta nõusid pesema! Lülita sisse helimõõtja ja naudi 15 minutit täielikku vaikust (0-10 detsibelli). Tunneta, kuidas su meel lõdvestub ja see visuaalne rahu sind tervendab.'),
('c51feab8-8101-47a7-82b7-0a8e946ff974'::uuid,'Кумдан сепил куруу архитектурасы 🏰','Ал парктагы кумдукта казына издегенсип, терең казып жатабы? Башынан аягына чейин баткакка батты. Бирок бул баалуу ачылыш учурун үзгүлтүккө учуратпаңыз. Алдын ала аба ырайына ылайыктуу жана кир болсо өкүнбөй турган кийимдерди тандап алуу менен, Сиз бул көрүнүштү стрессиз эле карап тура аласыз.','Liivalosside arhitektuur 🏰','Nad kaevavad pargis liivakastis nii sügavalt, nagu otsiksid aaret. Nad on pealaest jalatallani mudased. Kuid ära katkesta seda väärtuslikku avastamishetke. Valides eelnevalt ilmastikule vastavad ja määrdumist kannatavad riided, saad seda stseeni stressivabalt jälgida.'),
('95e37724-7f25-4dc6-a06e-d194ca45d333'::uuid,'Кечки көнүгүү: Атанын үстүндө секирүү! 🤸‍♂️','Кичинекейиңиздин энергиясы ашып-ташып, уктагысы келбей жатабы? Атасын диванга жаткырып, балаңызга анын үстүнө секирүүгө уруксат бериңиз. Атасынын чыгарган кызыктуу үндөрү бөлмөнү күлкүгө толтуруп, ашыкча энергия бир нече секундда жок болот.','Õhtune trenn: issi peal hüppamine! 🤸‍♂️','Sinu väike laps ei saa energiast lahti ega taha magama minna? Pane issi diivanile pikali ja lase lapsel tema peal hüpata. Issi tehtud naljakad hääled täidavad toa naeruga ja kogu liigne energia on sekunditega kadunud.'),
('9680e706-6c53-46d8-b37d-e2b2ed358ee7'::uuid,'Апалар үчүн өзүнө кам көрүү 🥗','Кичинекейиңизди тамактандыруу үчүн үч башка меню ойлоп таптыңыз, бирок өзүңүз дагы эле ач калдыңызбы? Тамактануу планы бөлүмүнө өтүп, 10 мүнөттө даяр боло турган, темирге жана кальцийге бай, энергия берүүчү түшкү тамакты тандаңыз – бул бир гана балдар үчүн эмес, энелер үчүн да – жана өзүңүздү чындап баалуу сезиңиз.','Enesehoolitsus emmedele 🥗','Mõtlesid välja kolm erinevat menüüd, et oma last toita, aga jäid ise jälle nälga? Suundu Nutrition Plan sektsiooni ja vali energiat andev, raua- ja kaltsiumirikas lõunasöök, mille valmistamine võtab vaid 10 minutit – mitte ainult lastele, vaid ka emadele – ja tunne end tõeliselt väärtustatuna.'),
('c0f71481-4d8f-40e3-87af-c4432426cfab'::uuid,'«Сен кимсиң?» оюну 🎭','Бүгүн эртең менен кичинекейиңиз Сизди олуттуу карап: "Сиз кимсиз? Менин апам кайда?" деп сурадыбы? Бул анын фантазиясынын өнүгүүсүнүн туу чокусу! Оюнга кошулуңуз: үнүңүздү өзгөртүп, "Мен кошуна эжемин, апаң азыр келет!" деп айтыңыз жана бул кереметтүү театралдаштатылган оюнду улантыңыз.','„Kes sa oled?“ mäng 🎭','Täna hommikul vaatab väike laps sind väga tõsise ilmega ja küsib: „Kes sa oled? Kus mu emme on?“ See on nende kujutlusvõime arengu tipp! Mängi kaasa: muuda häält ja ütle: „Olen tädi Naaber, su emme tuleb kohe!“ ning jätka seda suurepärast teatrietendust.'),
('17737c7f-74cb-4797-867c-90a8c03b4bfe'::uuid,'Даарат кагазынан жасалган искусство 🧻','Бир нече мүнөттүк тынчтык... бөлмөгө кирсеңиз, бардык даараткана кагазы жайылып, үйгө чачылып калыптыр! Капа болгондун ордуна, кагаздарды чогултуп, чогуу ак кар киши же топ жасаңыз. Баш аламандыкты кыйкырык менен эмес, чыгармачылык менен жеңиңиз.','Tualettpaberi kunst 🧻','Mõni minut vaikust... ja tuppa sisenedes näed, et kogu tualettpaber on lahti rullitud ja mööda maja laiali pillutud! Selle asemel, et pahandada, korja paber kokku ja meisterdage koos lumememm või pall. Alista kaos loovusega, mitte karjumisega.'),
('300e5d4c-57c8-45bf-bdcd-829a6024697a'::uuid,'Жумшак сөздөрдү шыбырашуу 💖','Ал күнү бою Сизди чарчатып, бардык нерсеге өжөрлөндү. Бирок азыр төшөктө ушунчалык күнөөсүз уктап жатат... Жанына жатып, аны кандай жакшы көрөрүңүздү, бүгүн кылган жакшы иштерин кулагына шыбыраңыз. Балдар уктап жатканда да эненин мээримдүү үнүн сезишет.','Armsad sosistused 💖','Ta ajas sind terve päeva hulluks ja oli kõigele vastu. Aga nüüd magab ta voodis nii süütult... Heida tema kõrvale ja sosista talle kõrva, kui väga sa teda armastad ja mis häid asju ta täna tegi. Lapsed tunnevad ema armastavat häält isegi unes.'),
('42d87f04-8d19-4c11-b1e4-703ee34de8db'::uuid,'Кир жуугуч машинаны ачуу 🧺','Балаңыз кир жуугуч машинанын алдында отуруп, айланып жаткан кийимдерге мультфильм көрүп жаткандай суктанып жатабы? Бул толугу менен акысыз жана зээнди тынчтандыруучу оюн. Анын тынчын албаңыз; өзүңүз эс алуу үчүн бул баалуу учурду пайдаланыңыз.','Pesumasina avastamine 🧺','Sinu laps istub pesumasina ees, olles pöörlevatest riietest nii lummatud, nagu vaataks multikat. See on täiesti tasuta ja vaimselt rahustav meelelahutus. Ära sega neid; kasuta seda väärtuslikku hetke, et ise puhata.'),
('56f07d8f-4184-4cda-b356-e566ad65a81d'::uuid,'Жомок убагынан качуу аракеттери 🏃‍♂️','Сиз жомок окуп жатканда, алар төшөктөн секирип түшүп, башка оюнчук алып келүүгө чуркап жатышабы? Алар жөн гана уйкуга моюн сунгүсү келбейт. Күтүүсүздөн үнүңүздү акырындатып, жомокту шыбырап айта баштаңыз. Сизди угуу үчүн алар төшөккө кайтып келип, кунт коюуга мажбур болушат жана тез эле уйкуга кетишет.','Katsed unejutust põgeneda 🏃‍♂️','Samal ajal kui sa unejuttu loed, hüppavad nad voodist välja ja jooksevad uut mänguasja otsima. Nad lihtsalt ei taha unega leppida. Langeta järsku häält ja hakka juttu sosistama. Nad on sunnitud voodisse tagasi tulema ja keskenduma, et sind kuulda, ning peagi vajuvad nad unne.'),
('6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8'::uuid,'Мен чоңойдум, кофе ичем! ☕','Кичинекейиңиз чөйчөгүңүзгө кол сунуп: «Мен чоңойдум, мен да кофе ичем!» — деп ишенимдүү айтат. Алар жөн гана сиздин дүйнөңүздүн бир бөлүгү болгусу келет. Алардын кичинекей чөйчөгүнө бир аз сүт менен какао куюп: «Карачы, бул сенин балалык кофең!» — деп, алар менен чөйчөк кагыштырып коюңуз.','Olen suur inimene, joon kohvi! ☕','Sinu väike põngerjas sirutab käe sinu tassi järele ja teatab kindlalt: „Olen suur, tahan ka kohvi!“ Nad tahavad lihtsalt sinu maailma osa olla. Vala nende väikesesse tassi veidi piima ja kakaod, ütle: „Vaata, see on sinu lastekohv!“ ja kõlksuta nendega tasse.'),
('7a51f55e-c494-489a-927c-6f2193813549'::uuid,'Аба ырайы жана катмарлап кийинүү өнөрү ⛅','Жаз жакындаган сайын аба ырайы туруксуз болот: эртең менен суук, түштөн кийин жылуу. «Аба ырайы жана кийим» куралы сизге аларды катмарлап кийинтүүнү («пияз эффекти») эскертет. Паркта алар ысып кеткенде, тердетпөө жана өзүңүздүн тынчсызданууңузду алдын алуу үчүн бир катмарын чечип коюңуз.','Ilm ja riietumise kunst ⛅','Kevade lähenedes on ilm heitlik: hommikul külm, pärastlõunal soe. Tööriist „Ilm ja riietus“ tuletab meelde, et riietaksid nad kihiliselt (sibulameetod). Kui nad pargis soojaks lähevad, eemalda lihtsalt üks kiht, et vältida nii higistamist kui ka enda stressi.'),
('063d0e5f-8a19-45c6-b301-96c01e527e0a'::uuid,'«Мурунуңду жулуп алдым» оюну 👃','Сиз баш бармагыңызды көрсөтүп: «Мурунуңду кармап алдым!» — десеңиз, алар буга чындап ишенип, ыйлай башташат. 3,5 жашта фантазия кээде чындык менен элести айырмалай албайт. Дароо: «Аха, ордуна койдум!» — деп мурунунан өөп коюңуз, ошондо бул кичинекей капачылык жылмаюуга айланат.','„Sain su nina kätte!“ mäng 👃','Ütled: „Sain su nina kätte!“ ja näitad pöialt, ning nad usuvadki seda ja hakkavad nutma! 3,5-aastasena ei suuda kujutlusvõime vahel reaalsust ja illusiooni eristada. Ütle kohe: „Ahah, panin tagasi!“ ja suudle nende nina, muutes selle väikese pahameele naeratuseks.'),
('31689193-e8a3-408a-bec9-cc30d1fc08c4'::uuid,'Өнөктөшүңүз менен үнсүз көз караш алмашуу 🥂','Бала акыры уктады. Сиз жана түгөйүңүз диванда катарлашып, сүйлөшүүгө да алыңыз жок отурасыз. Бири-бириңизди карап, унчукпай жылмаясыз. Бул бейпил көз караш: «Биз бул башаламандыкты эң сонун жеңип жатабыз», — деп айтуунун эң кооз жолу.','Vaikiv pilk kaaslasega 🥂','Laps on lõpuks magama jäänud. Istute partneriga diivanil kõrvuti, olles liiga väsinud, et isegi rääkida. Vaatate lihtsalt teineteisele otsa ja naeratate vaikuses. See vaikne pilk on kõige ilusam viis öelda: „Me tuleme selle kaosega suurepäraselt toime.“'),
('7834ecb1-6218-4b7b-a3ed-c138894407b9'::uuid,'Жасалма интеллект жана күтүлбөгөн өжөрлүк 🤖','Кечээ эле козудай жоош болгон бала бүгүн баарына агрессивдүү мамиле кылып жатабы? Интернеттен коркунучтуу себептерди издебеңиз. Anacan AI''дан бул өнүгүү секиригинин (менталдык секирик) психологиялык себептери жөнүндө сураңыз жана педиатр тарабынан тастыкталган жооп тынчсызданууңузду бассын.','AI ja äkiline kangekaelsus 🤖','Laps, kes oli eile kui talleke, reageerib täna kõigele agressiivselt? Ära otsi internetist hirmutavaid põhjuseid. Küsi Anacan AI-lt selle arenguhüppe (vaimse hüppe) psühholoogiliste põhjuste kohta ja lase lastearsti heakskiidetud vastusel oma mured hajutada.'),
('9dcc2901-fb6b-4d84-a478-46c76064f671'::uuid,'Муну мен таптым - ээлик кылуучу наристе 🔑','Алар полдон пультту же атасынын ачкычтарын алып: «Муну таптым, бул меники!» — деп жарыялашат. Алар үчүн табуу — ээлик кылуу дегенди билдирет. Күч менен жулуп албаңыз. Анын ордуна: «Таап бергениң үчүн рахмат!» — деп, буюмду кайтарып алуу үчүн алардын көңүлүн башка оюнчукка буруңуз.','Leidsin selle – omandihimuline väikelaps 🔑','Nad võtavad põrandalt puldi või issi võtmed ja teatavad: „Leidsin selle, see on minu oma!“ Nende jaoks tähendab leidmine omamist. Ära kisu seda jõuga käest. Selle asemel ütle: „Aitäh, et selle minu jaoks leidsid!“ ja suuna nende tähelepanu eseme kättesaamiseks mõnele teisele mänguasjale.'),
('c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec'::uuid,'Ваннадагы чакан спа 🛀','Бүгүн кечинде аларды эле эмес, өзүңүздү да сууга салыңыз. Бала уктагандан кийин, жылуу суу толтуруп, көбүк кошуп, ваннада бир шам жагыңыз. Эшикти бекитип, болгону 15 мүнөткө «апа» ролунан чыгып, кайрадан өзүңүз болуңуз.','Vannitoa minispaa 🛀','Täna õhtul ära pane ainult neid vanni, mine ise ka. Pärast lapse uinumist lase vann täis, lisa vahtu ja süüta vannitoas üks küünal. Lukusta uks ja astu vaid 15 minutiks oma „ema“ rollist välja ning ole lihtsalt jälle sina ise.'),
('cfb02ba9-2584-45e0-a1c3-ce6672adabe6'::uuid,'Өз алдынча чач кыркуу аракети ✂️','Бөлмөгө кирип, алардын куурчагынын чачын кайчы менен кесип жатканын көрөсүз. Бул учурду баштан кечирүү — ар бир апанын коркунучтуу түшү. Капаланбастан, кайчыны акырын алып коюңуз жана бул «чач тарачтык аракетти» келечектеги балалык сүрөттөр үчүн күлкүлүү архив катары сактап коюңуз.','Ise tehtud soengukatsetus ✂️','Astud tuppa ja näed, kuidas nad üritavad kääridega nuku juukseid lõigata. Selle hetke kogemine on iga ema suurim õudusunenägu. Ära pahanda, võta õrnalt käärid ja hoia see „juuksurikatsetus“ kui koomiline mälestus tulevaste beebifotode jaoks.'),
('175e4578-dab7-4e75-8a87-dd96baf6d2c6'::uuid,'Дагы бир жолу ойногула! 🎶','Алар радиодон жаңы эле жаңырган ырдын кайра коюлушун каалашат. Сиз бул түз эфир экенин жана ал бүткөнүн түшүндүрөсүз, бирок алар: «Кайра кой!» — деп ыйлашат. Баланын мээси түз эфирдин логикасын түшүнбөйт. Алардын көңүлүн алаксытуу үчүн, ырды өзүңүз ар кандай күлкүлүү үндөр менен ырдап бериңиз.','Mängi seda uuesti! 🎶','Nad tahavad, et raadiost just kõlanud laul hakkaks uuesti mängima. Selgitad, et see oli otseülekanne ja läbi, aga nad nutavad: „Too tagasi!“ Lapse aju ei hooma otseülekande loogikat. Nende tähelepanu hajutamiseks hakka ise seda laulu erinevate naljakate häältega laulma.'),
('a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7'::uuid,'Соода тизмесиндеги керексиз буюмдар 🛒','Дүкөнгө барар алдында соода тизмеңизди ачтыңыз, күтүүсүздөн кичинекейиңиз арттан келип экранды басып, түшүнүксүз тамгаларды жана «шоколад» деген сөздү кошуп койду. Ооба, алар санариптик дүйнөнү абдан тез өздөштүрүп жатышат!','Ebavajalikud asjad ostunimekirjas 🛒','Avasid enne poodi minekut ostunimekirja ja järsku vajutab su väike põngerjas selja tagant ekraanile, lisades sinna arusaamatu tähejada ja „šokolaadi“. Jah, nad avastavad digimaailma uskumatult kiiresti!'),
('f9e8851b-f40e-4ed9-a246-2e1405232755'::uuid,'Жан дүйнө тынчтыгында ичилген чай ☕','Алар бөлмөнүн ортосунда жалгыз ойноп, оюнчуктарын тизип жатышат. Сураныч, бул баалуу көз ирмемди үй шыпырууга коротпоңуз! Диванга отуруп, бир чөйчөк жылуу кофе же чай ичип, 10 мүнөт эч нерсе ойлобостон бейпилдиктен ырахат алыңыз.','Tee nautimine õndsas vaikuses ☕','Nad mängivad keset tuba üksi, rivistades oma mänguasju. Palun ära kasuta seda väärtuslikku hetke koristamiseks! Istu diivanile, naudi sooja kohvi või teed ja naudi 10 minutit lihtsalt vaikust, ilma et mõtleksid millelegi muule.'),
('92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e'::uuid,'Уйку таймеринин ыкмалары ⏱️','Балаңыз уктоо маалында күтүүсүздөн суусап, дааратканага баргысы келип же дубал менен коштошкусу келеби? Таймер коюңуз. Бул чексиз коштошуудан жана чебер манипуляциядан урушсуз кутулуу үчүн «таймер шыңгыраганда баары уктайт» деген эрежени киргизиңиз.','Unetaimeri taktika ⏱️','Kas lapsel on magamamineku ajal järsku janu, vaja tualetti minna või tahab ta seinaga hüvasti jätta? Pane taimer. Rakenda reeglit „kui taimer heliseb, siis kõik magavad“, et pääseda sellest lõputust hüvastijätust ja meistriklassi manipulatsioonist ilma vaidluseta.'),
('9d39f5c1-6418-4ab4-8bba-64b21fccd4ac'::uuid,'Чыныгы сүрөтчү дубалды тандайт 🖍️','Бир нече секунддук жымжырттык кооптуулукка алып келди! Бөлмөгө кирип, алардын маркер менен дубалга «искусство чыгармасын» жаратып жатканын көрөсүз. Терең дем алыңыз. Алардын майда моторикасы өнүгүп жатат, ал эми дубалды баары бир тазаласа болот. Келечекте күлүп эстеш үчүн бул шедеврди сүрөткө тартып алууну унутпаңыз.','Tõeline kunstnik valib seina 🖍️','Mõni sekund vaikust on viinud ohuolukorrani! Astud tuppa ja leiad nad markeriga seinale kunstiteost loomas. Hinga sügavalt sisse. Nende peenmotoorika areneb ja seina saab niikuinii puhastada. Tee sellest meistriteosest kindlasti foto, et saaksid hiljem naerda.'),
('dda9eb22-cebb-4f1b-962b-3223d17b83eb'::uuid,'Anacan коомчулугунун күчү 💬','«Эмне үчүн балам мынчалык өжөр?» деген ой сизди кыйнап жатабы? Anacan Коомчулугуна кошулуңуз. Башка апалардын үйүндө болуп жаткан ушундай эле кызыктай кризистерди окуганда, сиз жалгыз эмес экениңизди жана туура жолдо экениңизди көрөсүз.','Anacani kogukonna vägi 💬','Mõte „Miks mu laps on nii kangekaelne?“ vaevab su meelt. Liitu Anacan kogukonnaga. Kui loed sarnastest absurdsetest kriisidest, mida teised emad kodus läbi elavad, näed, et sa pole üksi ja oled täiesti õigel teel.'),
('1c56259d-5943-4110-9eaf-5c1870b222b1'::uuid,'Эртең мененки жашынмак 🙈','Сиз жумушка же бала бакчага кечигип жатасыз, ал эми кичинекейиңиз көшөгөнүн артына жашынып: «Мени тап!» — деп жатат. Нервиңиз жукарып турса да, кыйкыруу процессти гана узартат. Оюнга эки мүнөткө кошулуп: «Менин татынакай балам кайда?» — деп сурап, аны акырын сыртка чыгарып алыңыз.','Hommikune peitusemäng 🙈','Oled tööle või lasteaeda hiljaks jäämas ja su väike põngerjas peidab end kardina taha, öeldes: „Leia mind!“ Isegi kui su närvid on pingul, teeb karjumine protsessi vaid pikemaks. Liitu mänguga kaheks minutiks, küsides: „Kus mu ilus beebi on?“ ja meelita nad õrnalt välja.'),
('7b148d61-8829-4863-ab9e-6d4a0bb51f81'::uuid,'Тамак-ашты түсүнө карап сорттоо 🍅','Алар тарелкадагы тамактарды түсү жана формасы боюнча бөлүп, жашылчалардын баарын четке түртүп жатышабы? Тамактануу планына баш багыңыз. Ал жашылчаларды кантип байкатпай пюреге айлантып, даамдуу соустарга жашырууну үйрөнүңүз, ошондо бул тамактануу оюнунда сиз жеңүүчү болосуз.','Toidu sorteerimine värvi järgi 🍅','Nad sorteerivad taldrikul toitu värvi ja kuju järgi, lükates kõik rohelise kõrvale? Suundu toitumiskavasse. Avasta, kuidas need köögiviljad märkamatult nähtamatuteks püreedeks muuta ja maitsvatesse kastmetesse peita, et saaksid seda söögiaja mängu salaja võita.'),
('b42730c5-7949-4ebf-93b6-63b027cfa615'::uuid,'Атанын кызыктуу жомоктору 📖','Бүгүн кечинде жомокту сиз айтпаңыз. Жомок китебин атасына бериңиз, ал окуяны атайлап тескерисинче, күлкүлүү жана маанисиз кылып айтып берсин. Балаңыздын аны оңдоп, атасы менен бирге каткырып жатканына четтен байкоо салыңыз.','Issi fantaasiarikkad lood 📖','Täna õhtul ei ole sinu hääl see, mis lugu jutustab. Anna juturaamat issile ja lase tal meelega lugu tagurpidi, koomiliselt ja absurdselt rääkida. Vaata kõrvalt, kui väga lapsele meeldib teda parandada ja koos issiga naerust rõkata.'),
('4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5'::uuid,'Маанай күндөлүгүңүздөгү ачууну билдирүү 📝','Үйдө сиздин канчалык чарчаганыңызды эч ким көрбөгөндөй сезилеби? Маанай журналы — сиздин эң ишенимдүү сырдашыңыз. Бүгүн сизди жиниңизге тийгизген бардык майда-чүйдө нерселерди жазыңыз жана экраныңыздан оюңуздун жеңилдеп, тынчсызданууларыңыздын жок болуп жатканын байкаңыз.','Viha väljendamine meeleolupäevikus 📝','Kas tundub, et keegi ei näe, kui väsinud sa kodus oled? Meeleolupäevik on su kõige vaiksem usaldusisik. Pane kirja kõik detailid, mis sind täna hulluks ajasid, ja vaata ekraanilt, kuidas su meel kergemaks muutub ja mured lihtsalt hajuvad.'),
('5c983784-bca8-4998-adca-b16664e5be99'::uuid,'Үйдүн ичинде баш кийим кийип жүрүү 🧢','Алар үйдө кышкы калпагын кийгиси келип, аны чечүүдөн баш тартып жатышабы? Коомдук нормаларды бир азга унутуңуз. Алардын чыгармачылыгын жана эркиндигин чектебөө үчүн, эгер бөлмө температурасы нормалдуу болсо, аларга бул өзгөчө, күлкүлүү кийим менен күн өткөрүүгө уруксат бериңиз.','Mütsi kandmine toas 🧢','Nad tahavad kanda talvemütsi toas, nõudes seda ja keeldudes ära võtmast. Unusta hetkeks ühiskondlikud normid. Et mitte lämmatada nende loovust ja iseseisvust, lase neil veeta päev oma ainulaadses naljakas riietuses – kui toatemperatuur on normaalne, las nad naudivad seda.'),
('77e7ae70-0ff1-4b56-a2eb-2e4ed43e460c'::uuid,'Аба ырайынан кичинекей сюрприз! ⛅','Сейилдөөгө чыкканда, алдамчы аба ырайынан кичинекейиңизге суук тийгизип албаңыз. Сырткы шарттарга ылайыктуу кийимди оңой тандоо үчүн аба ырайы жана кийим жардамчысын колдонуңуз.','Väike üllatus ilmataadilt! ⛅','Jalutama minnes ära lase eksitaval ilmal oma lapsel külmetuda. Kasuta ilma ja riietuse abimeest, et valida õues valitsevate olude jaoks hõlpsasti parim riietus.'),
('9d6dd60c-7863-4418-b9e4-e9cffd903339'::uuid,'«Сен мени укпай жатасың!» деп кыйкыруу 😠','Сиз телефонуңузду карап же тамак аралаштырып жатканыңызда, алар келип, жүзүңүздү өздөрүнө буруп: «Мени карачы!» — деп талап кылышат. Жана алардыкы туура. Алар сиздин жөн гана жанында болушуңузду эмес, толук көңүл бурууңузду каалашат. Жасап жаткан ишиңизди токтотуп, болгону 3 мүнөткө аларды көзүнө тике карап, кунт коюп угуңуз.','„Sa ei kuula mind!“ puhang 😠','Kui vaatad telefoni või segad toitu, tulevad nad juurde ja pööravad su näo enda poole, nõudes: „Vaata mind!“ Ja neil on õigus. Nad ei taha ainult sinu füüsilist kohalolu; nad tahavad sinu jagamatut tähelepanu. Jäta pooleli see, mida teed, ja kuula neid tõeliselt, hoides vaid 3 minutit täielikku silmsidet.'),
('8665ce13-4bbc-4643-86cd-402909af004b'::uuid,'Темирге болгон муктаждыкты толуктоо 🥩','Активдүү булчуңдарды азыктандырыңыз! Бүгүн алар жетиштүү темир алып жатканын текшерүү үчүн Тамактануу трекерин колдонуңуз жана менюну тууралаңыз.','Rauavajaduse katmine 🥩','Turguta neid aktiivseid lihaseid! Kasuta toitumisjälgijat, et kontrollida, kas nad saavad täna piisavalt rauda, ja kohanda nende menüüd.'),
('45e62ed0-8906-4bfa-998b-97725faac7dc'::uuid,'Сейил бакта жаңы таанышуулар 🤝','Алар паркта бейтааныш балага барып: «Менин атым...» — деп өздөрүн тааныштырышат! Социалдык көндүмдөр таң калыштуу ылдамдыкта өнүгүүдө. Өнүгүү трекерине бул кайраттуу баарлашуу аракеттерин алардын инсандык өнүгүүсүндөгү сыймыктуу учур катары жазып коюңуз.','Tutvuste loomine pargis 🤝','Nad kõnnivad pargis võõra lapse juurde ja tutvustavad end: „Minu nimi on...“! Sotsiaalsed oskused arenevad hämmastava kiirusega. Salvesta arengujälgijasse need julged suhtlemiskatsed kui uhke verstapost nende isiksuse arengus.'),
('6538fe5a-5021-49de-8c05-b4294e3a7259'::uuid,'«Жок» деп айтуу мезгили 🛑','Суу ичесиңби? «Жок!» Бирок 5 секунддан кийин суу сурап ыйлап жатышат. Бул — өз чечимдеринин кесепеттерин текшерүү фазасы. Алар көбүнчө өздөрү каалаган нерселерге «жок» деп айтышат. Сууну жөн гана столдун үстүнө коюп коюңуз, мажбурлабаңыз; алар ички талашын бүтүрүп, өздөрү ичишет.','„Ei“-faas 🛑','Kas tahad vett? „Ei!“ Aga siis, 5 sekundit hiljem, nutavad nad vee järele. See on nende otsuste tagajärgede katsetamise faas. Nad ütlevad sageli „ei“ asjadele, mida nad tegelikult soovivad. Pane lihtsalt vesi lauale, ära sunni; nad lõpetavad oma sisemise vaidluse ja joovad ära.'),
('c5259254-085d-4cab-81d7-de92adaaa126'::uuid,'Тынч уктоо үчүн сыйкырдуу жомоктор 🪄','Сиз бардык классикалык китептерди жаттап алдыңыз. Акылдуу жомокторду ачыңыз, башкы каарманды балаңыз катары, ал эми багындыра турган жерди анын бөлмөсү катары белгилеп, өзгөчө жана оңой аудио-уйку сеансын түзүңүз. Жана өзүңүз да эс алыңыз!','Maagilised unejutud kergemaks uinumiseks 🪄','Oled kõik klassikalised raamatud pähe õppinud. Ava nutikad lood, kujunda peategelaseks oma laps ja vallutatavaks kohaks nende tuba, luues erakordse ja vaevatu auditi uneaja. Ja puhka ise ka!'),
('3267eb25-4eba-48a9-b86e-272c45f62299'::uuid,'Караңгыдагы көлөкө театры 🐰','Алар караңгыдан коркконун төшөктөн турууга шылтоо катары колдонуп жатышат. Бөлмөдөгү бардык жарыкты өчүрүп, кол чыракты күйгүзүңүз жана дубалга колуңуз менен куштун же иттин көлөкөсүн жасаңыз. Алар корккон караңгылык заматта алар үчүн театрга айланат.','Varjuteater pimedas 🐰','Nad kasutavad oma pimedusehirmu ettekäändena, et voodist välja saada. Kustuta toas kõik tuled, lülita sisse taskulamp ja tee kätega seinale linnu- või koeravarje. Nende kardetud pimedus muutub silmapilkselt nende isiklikuks teatrilavaks.'),
('4ac972f2-0058-41fe-9a63-593036a6aa46'::uuid,'Үн монитору менен тынчтыкты сактоо 🤫','Үйдөгү ызы-чуу кулагыңызды тундуруп жатат. Алар акыры уктап калганда, Үн өлчөгүчтү (Sound Meter) иштетиңиз. Экрандагы сандардын дээрлик нөлгө түшкөнүн көрүү, ошол санариптик жымжырттыкты сезүү — чарчаган эненин мээси үчүн эң сонун визуалдык массаж.','Vaikuse hoidmine beebimonitoriga 🤫','Kodune müra paneb su kõrvad kumisema. Kui nad lõpuks uinuvad, lülita sisse helimõõtja. Nende numbrite ekraanil nulli lähedale langemise jälgimine ja selle digitaalse vaikuse kogemine on väsinud ema ajule kõige kaunim visuaalne massaaž.'),
('b4510edb-beed-40b8-b0ad-884291f78f89'::uuid,'«Ал жерге отурба!» деген диктатура 🪑','Сиз диванга отургуңуз келет, бирок алар чуркап келип: «Бул жерде менин мамалагым отурат, сиз тик туруңуз!» — дешет. Алар үйдө өз бийлигин орнотууга аракет кылып жатышат. Алардын эркин одоно сындырбай: «Мамалак бул жерде отура берсин, мен анын жанына отурам», — деп, бөлмөдөгү тең салмактуулукту жана тынчтыкты сактаңыз.','„Siin ei tohi istuda!“ diktatuur 🪑','Tahad diivanile istuda, aga nad jooksevad kohale ja ütlevad: „Minu kaisukaru istub siin, sina seisa!“ Nad üritavad kodus võimu kehtestada. Ilma nende tahet jõuliselt murdmata ütle: „Karu võib siin istuda ja mina istun kohe tema kõrvale,“ säilitades nii toas tasakaalu ja rahu.'),
('a33e5975-6dcb-4e61-93db-f52a429ffcb8'::uuid,'Anacan AI: Балдар эмне үчүн калп айтышат? 🤥','Алар: «Сууну мен эмес, оюнчук төгүп койду!» — деп ишендирип жатышат. Алар калп айтып жатышабы же фантазиясы ушунчалык күчтүүбү? Интернеттен кооптуу жоопторду издебеңиз. Anacan AI аркылуу 3,5 жаштагы баладагы мындай элестетүүлөр өнүгүүнүн толук нормалдуу баскычы экенин билип, жөн гана тынчтаныңыз.','Anacan AI: Miks lapsed valetavad? 🤥','Nad väitsid: „Mina ei ajanud vett ümber, mänguasi tegi seda!“ Kas nad valetavad või on nende kujutlusvõime lihtsalt valla pääsenud? Ära otsi internetist ärevust tekitavaid vastuseid. Õpi Anacan AI-lt, et sellised illusioonid 3,5-aastase puhul on täiesti normaalne arenguetapp, ja lihtsalt lõõgastu.'),
('f03a726a-5a9c-4eda-ab04-4d6b21a432cd'::uuid,'Өнөктөшүңүз менен биргелешкен күлкү 🥂','Бала акыры уктады. Күн ичинде сизди жиниңизди келтирген ошол акылга сыйбаган окуяны түгөйүңүзгө айтып берип жатып, күтүүсүздөн экөөңүз тең каткырып күлүп каласыз. Ооба, бул күлкү — ата-энеликтин эң жагымдуу сыйлыгы.','Ühine naer koos partneriga 🥂','Laps on lõpuks uinunud. Kui räägid partnerile sellest absurdseks muutunud olukorrast, mis sind päeval hulluks ajas, puhkevad mõlemad äkki naerma. Jah, see naer on lapsevanemaks olemise kõige toredam tasu.'),
('fce85c76-de6a-416c-a8d9-e7fd462bd967'::uuid,'Оюнчуктарды ваннага алып кирүү 🛀','Алар жуунгусу келбейт, бирок ваннаны бардык машиналары жана пластик мамалактары менен толтургандан кийин сууга түшүүгө макул болушат. Тоскоол болбоңуз. Ваннадагы ошол оюнчуктар — балага суунун тынчтандыруучу таасирине моюн сунууга жардам берген эң мыкты ортомчулар.','Mänguasjade vannitamisretk 🛀','Nad ei taha vannis käia, aga pärast vanni täitmist kõigi nende autode ja plastkarudega nõustuvad nad vette minema. Ära sekku. Need mänguasjad vannis on parimad vahendajad, mis aitavad neil vee rahustavale mõjule alistuda.'),
('383239b8-7f85-4507-9f51-cdc8a13d1e8f'::uuid,'Макаронду сүйүү 🍝','Кечээ этти жакшы көрүшсө, бүгүн андан баш тартып, күнү бою макарон гана жегиси келип жатат. Алардын эрки менен күрөшпөңүз. Белок менен жашылчаларды даамдуу макарон соустарына байкатпай кошууну үйрөткөн пайдалуу рецепттерди табыңыз жана тамактануу убагындагы бул салгылашта акырын жеңишке жетиңиз.','Pastaarmastus 🍝','Eile nad armastasid liha, aga täna keelduvad sellest ja tahavad terve päeva ainult pastat. Ära võitle nende tahtega. Avasta tervislikke retsepte, mis õpetavad, kuidas märkamatult lisada valke ja köögivilju maitsvatesse pastakastmetesse, ning võida see söögiaja lahing vaikselt.'),
('6fb57a61-aa7b-441f-afc3-ed5b09208ed5'::uuid,'Күзгү алдындагы бий 🪞','Алар күзгүнүн алдында туруп, ырдап жана ар кандай бий кыймылдарын жасап жатышат. Алар өз денесинин ыргагын жана кандай көрүнөрүн сынап жатышат! Бул денени сезүү жана ыргак сезимин алардын өнүгүү трекерине кубаныч менен жазып коюңуз.','Peeglitantsud 🪞','Nad seisavad peegli ees, laulavad ja proovivad erinevaid tantsuliigutusi. Nad katsetavad oma keha rütmi ja seda, kuidas nad välja näevad! Salvesta see kehatunnetus ja rütmitaju rõõmuga nende arengupäevikusse.'),
('86182307-b484-4518-a023-a22ef5f8216d'::uuid,'Шыбырап айтылган уйку алдындагы дуэт 🌙','Алар төшөктө ушунчалык активдүү болгондуктан, уктай албай жатышат. Үнүңүздү көтөрүүнүн ордуна, күтүүсүздөн үнүңүздү акырындатып, жакшы көргөн ырын шыбырап баштаңыз. Балаңыз сизди угуу үчүн көңүл бурганда, анын мээси автоматтык түрдө гипноздолуп, уйку режимине өтөт.','Sosistatud une-duett 🌙','Nad on voodis nii aktiivsed, et ei jää magama. Selle asemel, et häält tõsta, langeta ootamatult tooni ja hakka nende lemmiklaulu sosistama. Kui laps keskendub sind kuulamisele, hüpnotiseerub tema aju automaatselt ja lülitub unerežiimile.'),
('4cd431fe-3e79-44d3-a7ca-53965a307626'::uuid,'Чач тарашуудагы күрөш 🪮','Таракты көрөрү менен алар кыйкырып, бөлмөдөн качып чыгышат. Күрөштү токтотуңуз. Алгач таракты алардын колуна берип, сиздин чачыңызды же куурчагынын чачын таратууга уруксат бериңиз. Алар башкарууну сезгенден кийин, кезек сизге келгенине макул болушат.','Juukseharjamise lahing 🪮','Niipea kui nad kammi näevad, karjuvad nad ja jooksevad toast välja. Lõpeta võitlus. Anna kamm esmalt neile ja lase neil kammida oma juukseid või nuku juukseid. Kui nad tunnevad, et kontroll on nende käes, lubavad nad ka sinul seda teha.'),
('7de027d7-5609-44f6-aeb7-25a62639a344'::uuid,'Anacan коомчулугундагы колдоо 💬','«Мен эч качан мурункудай эркин болбойм» деген ой сизди күтүүсүздөн каптап жатабы? Бул терең, бирок убактылуу сезимди Anacan коомчулугундагы башка энелер менен бөлүшүңүз жана ушул эле жолду басып өткөндөрдөн сооронуч жана колдоо табыңыз.','Tugi Anacani kogukonnas 💬','Kas mõte „Ma ei saa enam kunagi oma endiseks, vabaks minaks“ vallutab sind ootamatult? Jaga seda sügavat, kuid ajutist tunnet teiste emadega Anacani kogukonnas ning leia lohutust ja tuge neilt, kes on sama teed käinud.'),
('f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0'::uuid,'Суу терапиясы 🌊','Кээде эч нерсе жардам бербейт; алар жөн гана бардык нерсеге ыйлай беришет. Аларды жылуу ваннага салып, бир аз көбүк кошуңуз. Суунун сыйкырдуу, чыңалууну басуучу магниттик таасири заматта бүт бөлмөгө жана алардын нерв системасына тынчтык алып келет.','Veeteraapia 🌊','Mõnikord ei aita miski; nad lihtsalt nutavad kõige pärast. Pane nad sooja vanni, lisa veidi vannivahtu. Vee müstiline, pinget maandav magnetiline mõju toob silmapilkselt rahu nii kogu tuppa kui ka nende närvisüsteemi.'),
('11b4acb5-0c50-4711-bda6-86d12a2c254b'::uuid,'Ата менен массаж убактысы 💆‍♂️','Сиз күнү бою бутуңуздан тик туруп, алардын артынан чуркап, оюнчуктарды жыйнап, белиңиз үзүлүп кетейин деди. Бала уктаар замат, түгөйүңүздөн 10 мүнөттүк ийин массажын сураңыз. Сиз — үйдүн тирегисиз, ал эми тиректер эс алып, калыбына келиши керек.','Massaažiaeg issiga 💆‍♂️','Oled terve päeva jalgadel olnud, neil järel jooksnud ja mänguasju korjanud, ning su selg on valus. Niipea kui laps magab, palu partnerilt 10-minutilist õlamassaaži. Sina oled kodu tugisammas ja sambad peavad puhkama ning taastuma.'),
('48e0f071-5110-45a7-a007-23be77bbd305'::uuid,'Тескери кийилген көйнөктүн «менменсинуусу» 👕','Алар көйнөгүн тескери кийип алышып, дүйнөнү багындыргандай сыймыктануу менен көрсөтүп жатышат. Кийимди тескери кийип сыртка чыккан бала — өз чечимин коргогон бала. Буга такыр кийлигишпеңиз; тескерисинче, алардын өзүнө болгон ишенимине суктаныңыз.','Pahempidi särgi ego 👕','Nad on pannud särgi pahupidi selga ja näitavad seda uhkusega, nagu oleksid maailma vallutanud. Laps, kes astub välja pahupidi riietes, on laps, kes kaitseb oma otsust. Ära sekku isegi mitte natuke; selle asemel imetle nende enesekindlust.'),
('b20bcc48-1ecb-4706-9d32-0f8329c7cd46'::uuid,'Дүкөндөгү укмуштуу окуялар 🛒','Кассага жакындаганда, арабадан сиз такыр албаган үч башка шоколадды таап аласыз. Алар сиздин чектериңизди сынап жатышат! Ыкчам аракет менен ал буюмдарды байкатпай кайра ордуна коюңуз. Ал эми унутуп калбоо үчүн, колдонмодогу Соода тизмесин (Shopping List) дайыма көзөмөлдөп туруңуз.','Seiklused toidupoes 🛒','Kassasse jõudes avastad kärust kolm erinevat šokolaadi, mida sa kindlasti ei valinud. Nad katsetavad su piire! Kiire manöövriga pane need esemed diskreetselt tagasi. Ja unustamise vastu pea alati silma peal rakenduse ostunimekirjal.'),
('229bf8d4-9bef-44e1-90de-84a850188af4'::uuid,'Муздак кофе чындыгы ☕','Кофе куюп алып, үч сааттан кийин анын муздап калганын көрүү — энеликтин жазылбаган мыйзамы сыяктуу. Бирок бүгүн өзгөртүү киргизиңиз! Сиз кофени ысык ичип жатканда, алар жакшы көргөн мультфильмин көрө турушсун. Сиз робот эмессиз; сиз бир аз эс алууга татыктуусуз.','Jahtunud kohvi reaalsus ☕','Kohvi valamine ja selle kolm tundi hiljem jääkülmalt joomine on emaduse puhul praktiliselt kirjutamata reegel. Aga tee täna muudatus! Lase neil vaadata oma lemmikmultikat, samal ajal kui sina naudid kuuma kohvi. Sa ei ole robot; sa väärid hetke puhkust.'),
('78ebbc01-68e9-48f1-b518-6ad7212482ec'::uuid,'Үн өлчөгүчтүн санариптик тынчтыгы 🤫','Алар акыры укташты! Үйгө орногон жымжырттыкка ишенбей турасыз. Үн өлчөгүчүңүздү иштетиңиз жана экрандагы 0-10 децибелдик көрсөткүчтү карап, мээңиздин кантип акырындап калыбына келип жатканын визуалдык түрдө сезиңиз.','Müramõõtja digitaalne vaikus 🤫','Nad on lõpuks uinunud! Sa ei suuda uskuda vaikust, mis on majja laskunud. Lülita sisse oma helimõõtja ja tunneta visuaalselt, kuidas su aju aeglaselt taastub, vaadates ekraanil seda 0–10 detsibelli näitu.'),
('83129caa-97cc-414e-93e5-8bffa69fcbb9'::uuid,'Бирок мен сенин апаңмын да! 👩‍👧','Ролдорду алмашуу оюну башталды! Алар сизге көрсөтмө берип жатышат: «Бул жакка кел, төшөккө жат, ыйлаба!» Бул лидерлик тажрыйбаны чоң кубаныч менен кабыл алыңыз жана алардын баласынын ролун унчукпай ойноңуз; бул — иш жүзүндөгү эмпатия.','Aga mina olen ju sinu emme! 👩‍👧','Rollimäng on alanud! Nad annavad sulle juhiseid: „Tule siia, mine voodisse, ära nuta!“ Võta seda juhtimiskogemust suure rõõmuga vastu ja mängi vaikselt nende lapse rolli; see on empaatia tegevuses.'),
('257a6a67-1139-417f-a422-373f16be4a85'::uuid,'Операция: Жашыруун пайдалуу тамак 🥣','Кечээ жакшы көргөн тамагын бүгүн колу менен да кармабайт. Алардын эрки менен күрөшпөңүз! Белокторду ар кандай, түстүү жана кызыктуу формаларга айландырган пайдалуу жеңил тамактардын рецепттерин изилдеп, жеңүүчү болуңуз.','Operatsioon: Peidetud tervislikkus 🥣','Toidu, mida nad eile armastasid, ei puutu nad täna üldse. Ära võitle nende tahtega! Ole võitja, avastades tervislikke suupisteretsepte, mis muudavad valgud erinevateks, värvilisteks ja lõbusateks kujunditeks.'),
('e8a36b6d-250c-4114-bd67-1068cf626c68'::uuid,'Менин оюнчугум ооруп калды 🩺','Алар оюнчук стетоскобун алып, мамалагын олуттуу түрдө текшерип, атүгүл ага пластырь чаптап жатышат. Символикалык оюн аркылуу алар боорукердикти жана курчап турган дүйнөнү таанып жатышат. Алардын ооруканасында бейтаптын ролун аткарып, оюнга кошулуңуз.','Minu mänguasi on haige 🩺','Nad on võtnud oma mängustetoskoobi ja uurivad tõsiselt oma kaisukaru, pannes sellele isegi plaastri peale. Sümboolse mängu kaudu töötlevad nad kaastunnet ja ümbritsevat maailma. Liitu mänguga, võttes nende haiglas patsiendi rolli.'),
('fc4c9174-8969-47bc-b1ba-7be545e849f3'::uuid,'Акылдуу жомоктор менен сыйкырдуу түштөр 🪄','Сиз бардык классикалык китептерди жаттап алдыңыз. Акылдуу окуяларды ачып, башкы каарманды балаңыз катары, ал эми багындыра турган жерди анын бөлмөсү катары белгилеңиз жана өзгөртүүсүз, күч жумшабай турган аудио уйку сеансын түзүңүз.','Maagilised unenäod nutikate lugudega 🪄','Oled kõik klassikalised raamatud pähe õppinud. Ava nutikad lood, kujunda peategelaseks oma laps ja vallutatavaks kohaks nende tuba, luues erakordse ja pingevaba unejutu seansi.'),
('3bc4e55a-369a-4bca-8a42-e2a95a607168'::uuid,'Маанай күндөлүгүңүздөгү сырлар 📝','Үйдө сиздин канчалык чарчаганыңызды эч ким көрбөгөндөй сезилеби? Маанай журналы — сиздин эң ишенимдүү сырдашыңыз. Бүгүн сизди жиниңизге тийгизген бардык майда-чүйдө нерселерди жазыңыз жана экраныңыздан оюңуздун жеңилдеп, тынчсызданууларыңыздын жок болуп жатканын байкаңыз.','Pihtimused meeleolupäevikus 📝','Kas tundub, et keegi ei näe, kui väsinud sa kodus oled? Meeleolupäevik on su kõige vaiksem usaldusisik. Pane kirja kõik detailid, mis sind täna hulluks ajasid, ja vaata ekraanilt, kuidas su meel kergemaks muutub ja mured lihtsalt hajuvad.'),
('be5cb204-e61d-452b-9a0e-bb977bd6249c'::uuid,'Себепсиз төгүлгөн көз жаш ☀️','Алар «күн мени карап жатат» деп ыйлап жибериштиби? Бөлмөдөн логика издебеңиз. Бул алар үчүн чындап эле терең капалануу; алар дүйнөнү башкара албаганына нааразы болуп жатышат. Жөн гана: «Мен көшөгөнү жаап, күндү жашырып койдум», — деп, алардын сезимдерин түшүнгөнүңүздү билдириңиз.','Seletamatud pisarad ☀️','Kas nad puhkesid nutma, väites, et päike jõllitab neid? Ära otsi toast loogikat. See on nende jaoks siiralt sügav pahameel; nad on frustreeritud oma suutmatusest maailma kontrollida. Lihtsalt kinnita nende tundeid, öeldes: „Tõmbasin kardina ette ja panin päikese peitu.“'),
('05028726-3b26-4576-b76c-968926aa3c37'::uuid,'Жалгыздыкка болгон сагыныч 🚪','Ызы-чуу мээңизди тешип, бардык нерсеге кыйкыргыңыз келип жатабы? Аларды коопсуз жерге калтырып, ваннага кирип, эшикти жабыңыз. 5 мүнөт бою эч нерсе кылбай, жөн гана дубалды карап туруңуз. Бул кыска тыныгуу сизге күчүңүздү калыбына келтирүүгө жана энелик ролуңузга кайрадан киришүүгө жардам берет.','Igatsus omaette olemise järele 🚪','Kas müra puurib su ajju, pannes sind tahtma kõige peale karjuda? Pane nad turvalisse kohta, mine vannituppa ja sulge uks. Lihtsalt vaata 5 minutit seina, tegemata mitte midagi. See lühike paus aitab sul end nullida ja oma emarolli naasta.'),
('3d57cc08-81bc-4a6c-804c-4488f1dababe'::uuid,'Жалаң аяк жүрүү эрежеси 👣','Алар жылаңайлак басканды, килемди, муздак плитканы же атүгүл майда таштарды сезгенди жакшы көрүшөт. Буттун таманындагы нервдердин стимуляциясы алардын тең салмактуулугу жана неврологиялык өнүгүүсү үчүн абдан маанилүү. Эгер алар үшүбөй эле жатышса, байпаксыз изилдөөсүнө сөзсүз уруксат бериңиз.','Paljajalu reegel 👣','Nad armastavad paljajalu käia, tundes vaipa, jahedaid plaate või isegi kivikesi. Taldade närvilõpmete stimuleerimine on nende tasakaalu ja neuroloogilise arengu jaoks ülioluline. Kuni neil külm ei hakka, lase neil kindlasti ilma sokkideta avastada.'),
('903639ea-1976-4233-a451-64887050fd95'::uuid,'Атанын күлкүлүү үндөрү 🤡','Сиздин кадимки ыкмаларыңыз иштебей калганда, атасынын кызыктай жаныбарлардын үндөрү жана күлкүлүү жүздөрү заматта кырдаалды сактап калат. Кечки ызы-чуу учурунда топту дароо ага өткөрүп бериңиз жана четте туруп, тынчтыктан ырахат алыңыз.','Issi naljakad hääled 🤡','Kui su tavalised nipid enam ei tööta, päästavad isa imelikud loomahelid ja naljakad näod päeva. Õhtuste jonnihoogude ajal anna pall kohe talle üle ja vaata kõrvalt, nautides oma rahu.'),
('4cb1e963-5e79-4f65-b536-3c251c29e851'::uuid,'Бүгүн ашпозчу менмин! 🧑‍🍳','Сиз камыр жайып жатканда, алар сөзсүз түрдө отургучту сүйрөп келип, аралашууну талап кылышабы? Алар сөзсүз эле «жардам берүүнү» эмес, окуянын так борборунда болууну каалашат. Аларга кичинекей камыр бериңиз. Ашкана булганышы мүмкүн, бирок алардын өзүн-өзү баалоо сезими жана чыгармачылыгы гүлдөйт.','Täna olen mina kokk! 🧑‍🍳','Kui sa tainast rullid, kas nad nõuavad tingimata tooli toomist ja osalemist? Nad ei taha tingimata „aidata“, vaid pigem olla tegevuse keskel. Anna neile väike tükk tainast. Köök võib küll segaseks minna, aga nende eneseväärikus ja loovus õitsevad.'),
('7f5013df-f5cb-4869-9600-c6ec01184189'::uuid,'Ымыркайдын алгачкы сөздөрүн белгилөө 📈','Алар буюмдарга эч бир тилде жок, ойдон чыгарылган аттарды коюп, сизден да ошол сөздөрдү колдонууну талап кылып жатышат! Өнүгүү трекерин (Growth Tracker) ачып, бул күлкүлүү сөздөрдү келечекте окуп күлүү үчүн сөзсүз архивдеп коюңуз.','Beebi esimeste sõnade jälgimine 📈','Nad annavad esemetele täiesti väljamõeldud nimesid, mida üheski keeles ei eksisteeri, ja nõuavad tungivalt, et ka sina kasutaksid neid sõnu! Ava arengupäevik ja salvesta need naljakad sõnad kindlasti, et saaksid neid tulevikus lugeda ja naerda.'),
('df048442-7c05-4ccf-850d-802c3f348e55'::uuid,'Караңгылыкты кабыл алуу 🌙','Кичинекейиңиз тезирээк уктап калышы үчүн, жатардан бир саат мурун бөлмөдөгү бардык кошумча жарыктарды жана планшеттердин экрандарын өчүрүңүз. Мелатонин караңгы жана технологиясыз чөйрөдө эң натыйжалуу бөлүнүп чыгат, бул уйкуга тынч өтүүнү камсыз кылат.','Pimeduse omaksvõtmine 🌙','Et aidata oma väikesel kiiremini uinuda, veendu, et tund enne magamaminekut oleksid toas kõik üleliigsed tuled ja tahvelarvutite ekraanid välja lülitatud. Melatoniin vabaneb kõige tõhusamalt pimedas ja tehnoloogiavabas keskkonnas, tagades rahuliku ülemineku unne.'),
('18eabc56-86a4-4978-a5a6-151a3c410b3b'::uuid,'Жарыкты өчүрүп, тынчтыкка бөлөнүңүз 🤫','Акыры алар укташты. Эми үйдөгү эң кичинекей добуш да тоскоолдуктай сезилет. Жарыкты азайтып, телевизорду өчүрүңүз жана караңгыдагы баалуу, таттуу жымжырттыктан чындап ырахат алыңыз. Күндүн чарчоосу ушундайча тарайт.','Hämarda tuled, naudi vaikust 🤫','Nad on lõpuks ometi uinunud. Nüüd tundub isegi kõige pisem heli majas häirivana. Hämarda tuled, lülita teler välja ja naudi tõeliselt seda väärtuslikku, magusat vaikust pimeduses. Nii sulab päeva väsimus tasapisi ära.'),
('90892878-829c-442e-a1ef-747f03a0affd'::uuid,'Түшүнүксүз капалануу 😤','Сиз жөн гана: «Кел, тамак даяр», — дедиңиз, ал эми алар колдорун кайчылаштырып, дубалды тиктеп, Сиз менен сүйлөшпөй калышты. Бул куракта эмоциялар ушунчалык татаал болгондуктан, алар эч нерсеге арзыбаган нерсеге капа болушу мүмкүн. Түшүндүрүүгө аракет кылбаңыз; эки мүнөттөн кийин алар кайра эле столго чуркап келишет.','Seletamatu jonn 😤','Ütlesid lihtsalt: „Tule, õhtusöök on valmis,“ ja nad ristasid käed, jõllitasid seina ja hakkasid sind ignoreerima. Selles vanuses on emotsioonid nii keerulised, et nad võivad ärrituda tühjast-tähjast. Ära püüa selgitada; kahe minuti pärast jooksevad nad tõenäoliselt ise laua juurde.'),
('e85911c9-eb5a-4470-b9d6-9a1a5872b746'::uuid,'Anacan AI: Баланын коркуу сезимдерин түшүнүү 🤖','Алар күтүүсүздөн дайыма ойноп жүргөн кызыл машинадан корко башташтыбы? Эгер түшүнүксүз коркунучтар Сизди тынчсыздандырып жатса, ал коркунучтуу онлайн форумдарды жабыңыз. 3,5 жаштагы баланын фантазиясынын кызыктуу өзгөчөлүктөрү жөнүндө илимий жана ишенимдүү жоопторду Anacan AI''дан алыңыз.','Anacan AI: Lapse hirmude mõistmine 🤖','Kas nad on äkki hakanud kartma punast autot, millega nad alati mängisid? Kui seletamatud hirmud sind muretsema panevad, sulge need traumeerivad veebifoorumid. Hangi Anacan AI-lt teaduslikke ja rahustavaid vastuseid 3,5-aastase lapse fantaasiamaailma põnevate iseärasuste kohta.'),
('037f6c5f-0014-4a61-89cc-f6268f8f792a'::uuid,'Сыйкырдуу шыбырлар 🌙','Алар төшөктө ары-бери оодарылып, буттарын өйдө көтөрүп, такыр уктабай жатышат. Үнүңүздү көтөрүүнүн ордуна, аны күтүүсүздөн басаңдатып, шыбырап гана сүйлөп көрүңүз. Балаңыз Сизди угуу үчүн кунт коюп көңүл бурганда, анын мээси автоматтык түрдө тынч, дээрлик гипноздук абалга өтүп, акырындык менен уйкуга батат.','Hüpnootilised sosinad 🌙','Nad vähkrevad voodis, jalad püsti, ja keelduvad kategooriliselt uinumast. Selle asemel, et häält tõsta, proovi äkki häält madaldada ja rääkida vaid sosinal. Kui laps keskendub pingutatult sind kuulama, läheb tema aju automaatselt rahulikku, peaaegu hüpnootilisse seisundisse, mis aitab neil õrnalt uinuda.'),
('b0b14a33-4ccb-42a3-a0a7-0359199a066c'::uuid,'Anacan коомчулугунан колдоо табуу 💬','Сиз аябай чарчап, эч кимге эч нерсе түшүндүргүңүз келбей жатабы? Anacan Community бөлүмүнө кирип, жөн гана окурман болуңуз. Башка энелердин да ушундай чарчоону башынан кечирип жатканын көрүү — эң жакшы терапия, бул «мен жалгыз эмесмин» деген жубатарлык сезимди жаратат.','Anacani kogukonnast lohutuse leidmine 💬','Oled täiesti kurnatud ega taha kellelegi midagi selgitada? Sisene Anacani kogukonda ja ole lihtsalt lugeja. Teiste emade sarnase väsimuse kogemine on parim teraapia, mis tekitab lohutava tunde: „Ma ei ole üksi.“'),
('b51e5eaf-9b52-4501-9631-0ad7c9e7aebd'::uuid,'«Эмне үчүн?» бороону 🌪️','«Эмне үчүн балыктар баспайт?», «Күн кайда кетти?» Таң эрте алардын мээси философиялык изденүүдө болуп, саатына жүздөгөн суроолорду жаадырат. Чарчап турсаңыз да, кыска жана так жооп бериңиз. Алар ааламдын сырларын Сиздин сөздөрүңүздөн гана эмес, үнүңүздүн тонунан да үйрөнүшөт.','„Miks“-torm 🌪️','„Miks kalad ei kõnni?“, „Kuhu päike läks?“ Kohe hommikul on nende aju filosoofilisel rännakul, tulistades sada küsimust tunnis. Isegi kui oled väsinud, paku lühikesi ja selgeid vastuseid. Nad õpivad universumi saladusi mitte ainult sinu sõnadest, vaid ka sinu hääletoonist.'),
('56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f'::uuid,'Бул меники! - Менчикчилдик курагы 🧸','Алар үйдөгү каалаган буюмду кучактап: «Бул меники!» — деп, башка эч кимге тийгизбей коюшат. Алар менчик жана чек ара түшүнүктөрүн изилдеп жатышат. Аларды өзүмчүл деп атабаңыз; буюмду кайтарып алуу үчүн алардын көңүлүн башка кызыктуу ишке акырын буруңуз.','See on minu oma! – Omandihimu iga 🧸','Nad kallistavad suvalist majapidamisesemet, kuulutavad: „See on minu!“ ja keelduvad laskmast kellelgi teisel seda puudutada. Nad avastavad omandi ja piiride mõistet. Ära sildista neid isekaks; suuna nende tähelepanu õrnalt mõnele teisele kaasahaaravale tegevusele, et ese tagasi saada.'),
('77d341ac-ecee-44bc-a34c-b8046e7ebe38'::uuid,'Апамдын өз табагы 🥗','Сиз аларды тамактандыруу үчүн үч башка меню ойлоп таптыңыз, бирок өзүңүз дагы эле ачкасызбы? Тамактануу планы бөлүмүнө өтүп, даярдоого болгону 10 мүнөт кеткен, темирге жана кальцийге бай, энергия берүүчү эртең мененки тамакты тандаңыз — бул балдар үчүн гана эмес, энелер үчүн да — жана өзүңүздү баалуу сезүүнү унутпаңыз.','Emme oma taldrik 🥗','Oled mõelnud välja kolm erinevat menüüd, et neid toita, aga oled ise ikka näljane? Suundu toitumiskava sektsiooni ja vali energiat andev, raua- ja kaltsiumirikas hommikusöök, mille valmistamine võtab vaid 10 minutit – mitte ainult lastele, vaid ka emadele – ja ära unusta tunda, et oled väärtuslik.'),
('97e76dee-bae4-4d8b-bffd-646b99d0b6bc'::uuid,'Экөөбүз үчүн майрам 🥂','Оор күндөн кийин өзүңүзгө жылуу чай куюп алыңыз. Диванда өнөктөшүңүздүн маңдайына отуруп, чыныларды кагыштырып: «Биз бүгүнкү башаламандыктан да аман-эсен өттүк!» — деп айтыңыз. Сиздер бул үйдүн багыт берүүчү лидерлери жана бекем командасысыздар.','Šampanja kahele 🥂','Pärast rasket päeva valage endale tassike lohutavat kuuma teed. Istuge partneriga diivanil vastamisi, kõlistage tasse ja öelge: „Me isegi elasime selle tänase kaose üle!“ Olete mõlemad selle kodu juhid ja kindel meeskond.'),
('0dc18b7e-e572-47af-8c7b-0d7785728f82'::uuid,'«Өзүм куям» фазасы 💧','Алар чоң кумурадан кичинекей стаканга сууну өздөрү куюуга аракет кылышат. Суу столго, андан кийин полго чачырайт. Бирок алардын өчүргүчү менен тазалоого аракет кылган кичинекей колдорун караңызчы. Алар каталар аркылуу жоопкерчиликти үйрөнүп жатышат; ачууланбоого аракет кылыңыз.','„Valan ise“ faas 💧','Nad nõuavad, et saaksid ise suurest kannust väikesesse klaasi vett valada. Vesi pritsib lauale, siis põrandale. Aga vaata nende pisikesi käsi, mis püüavad seda kustutuskummiga puhastada. Nad õpivad vastutust katse-eksituse meetodil; püüa mitte ärrituda.'),
('4f75092c-a7ba-4a8b-9f64-4af1718f2cab'::uuid,'Ваннадагы океан 🌊','Жуунуу убактысы эми жөн гана тазалануу эмес, толкундарды жараткан кызыктуу оюнга айланды. Суу чачырасын! Суунун ошол сыйкырдуу, тазалоочу таасири балаңыздын күн бою топтогон бардык терс энергиясын жууп, суу менен кошо агызып кетет.','Ookean vannis 🌊','Vanniskäik pole enam ammu lihtsalt pesemine; see on vahva lainete tekitamise mäng. Lase veel pritsida! Vee magnetiline ja puhastav toime peseb maha kogu selle kangekaelse negatiivse energia, mille laps päeva jooksul kogus, saates selle otse äravoolust alla.'),
('d4d0d422-f5f6-490e-8c72-e88ef36a1315'::uuid,'Соода тизмеси: Унутулуп калган маанилүү нерселер 🛒','Дүкөнгө барганда дайыма эң маанилүү нерсени унутуп каласызбы? Тиркемеде Сизди Соода тизмеси күтөт! Керектөөлөрүңүздү ошол жерге белгилеңиз, ошондо өнөктөшүңүз жумуштан үйгө келе жатып аларды так сатып келе алат, бул Сиздин мээңизди ашыкча түйшүктөн бошотот.','Ostunimekiri: Unustatud esmatarbed 🛒','Kas unustad turule minnes alati kõige tähtsama asja? Ostunimekiri ootab sind äpis! Märgi oma vajadused sinna ja partner saab need töölt tulles täpselt kaasa osta, vabastades su mõtted tarbetust koormast.'),
('418c1711-4059-4957-81d3-edd1c0d2c899'::uuid,'Сейил бактагы ачылыштар: Архитектуралык кереметтер 🏰','Алар сейил бактагы кумда кенч издеп жаткандай терең казып, баткакка батып калышты. Бирок бул ачылыш учурун үзгүлтүккө учуратпаңыз! Эгер Сиз Аба ырайы жана кийим куралын колдонуп, тактарга туруктуу кийимдерди алдын ала тандап алган болсоңуз, бул көрүнүштү стрессиз көрүүгө мүмкүнчүлүк аласыз.','Pargiavastused: Arhitektuuriimed 🏰','Nad kaevavad pargi liivakastis nii sügavalt, nagu otsiksid aaret, ja on mudaga koos. Aga ära katkesta seda avastamishetke! Kui oled ilmastiku ja riietuse tööriista abil eelnevalt valinud plekkidele vastupidavad riided, saad seda stseeni muretult jälgida.'),
('4690cd10-6ebf-45be-8b49-fc76a078e4f1'::uuid,'Буюмдар менен өзгөчө достук 🗣️','Сейил бакта алар таш менен терең баарлашып жатышы мүмкүн же үйдө отургучту катуу урушуп жатышы мүмкүн. Символдук оюн аркылуу алар дүйнөнү кабыл алып, түшүнүп жатышат. Бул фантазиялык сценарийлерди алардын өнүгүү трекерине белгилеп коюуну унутпаңыз.','Ebatavalised sõprussuhted esemetega 🗣️','Pargis võivad nad olla süvenenud vestlusesse kiviga või kodus rangelt tooli noomida. Sümboolse mängu kaudu töötlevad nad maailma ja mõtestavad seda lahti. Veendu, et märgid need fantaasiarikkad stsenaariumid nende arengupäevikusse.'),
('a43560ca-6c77-420e-beaa-23a6e7c51732'::uuid,'Сыйкырдуу жомоктогу мен 🪄','Бүгүн кечинде «Акылдуу жомоктордо» башкы каарманга балаңыздын атын бериңиз. Каарман да бөлмөсүн жыйнап, анан таттуу уктаган окуяны айтып берүү менен, Сиз жөн гана буйрук бербей, жакшы адаттарды жана эрежелерди кыйыр түрдө акырын үйрөтө аласыз.','Mina võluloo kangelasena 🪄','Täna õhtul pane „Nutikates lugudes“ peategelasele oma lapse nimi. Jutustades lugu, kus tegelane samuti koristab oma toa ja magab seejärel rahulikult, saad õrnalt ja kaudselt sisendada häid harjumusi ja reegleid, selle asemel et lihtsalt käske jagada.'),
('9e327ded-a5c0-48ad-901c-52606eb80762'::uuid,'Маанай күндөлүгү: Жеңилдик учуру 📝','Телефонуңузду колуңузга алыңыз. Социалдык тармактарда башкалардын жашоосун карап отурбай, Маанай күндөлүгүн ачып, келечек үчүн алардын бүгүнкү эң кызыктуу учурун жазып коюңуз. Буй санариптик терапия Сизди да эс алдырат.','Tujupäevik: Hetk vabastuseks 📝','Võta telefon kätte. Selle asemel, et sotsiaalmeedias teiste elusid kerida, ava meeleolupäevik ja salvesta tuleviku jaoks kõige naljakam hetk, mille nad täna lõid. See digitaalne teraapia lõdvestab ka sind.'),
('a7cb2140-287a-4406-a2b5-5d7c82c31a2d'::uuid,'Атамдын аркасындагы ат чабыш 🐴','Алардын энергиясы дагы эле ашып-ташып, уктоого такыр каршы болуп жатышат. Атаны жардамга чакырыңыз! Ал аларды «ат» кылып жонуна көтөрүп ойноткондо, бөлмө күлкүгө толуп, топтолгон физикалык стресс жана чексиз энергия бир заматта жок болот, ал эми алар таттуу чарчоо менен уктап калышат.','Issi ratsahobune 🐴','Neil on veel energiat üle ja nad keelduvad kategooriliselt magamaminekust. Kutsu isa appi! Kui ta teeb neile lõbusa „hobusesõidu“ seljas, täitub tuba naeruga ning kogu see kuhjunud füüsiline pinge ja piiritu energia kaob hetkega, jättes nad õndsalt väsinuks.'),
('e21478c9-e278-43bf-8cfc-ce997f28ab6d'::uuid,'«Мага карачы!» фазасы 👀','Алар дивандан секирип, бир эле кыймылды 50 жолу кайталап: «Апа, мени караңызчы!» — деп кыйкырып жатышат. Телефонуңузду коюңуз. Алар жөн эле секирбей, Сиздин көзүңүздөгү ошол колдоо учкунун көрүү үчүн секирип жатышат. Аларга беш мүнөт убакыт бөлүңүз; алар муну чындап сезишсин.','„Vaata mind!“ faas 👀','Nad hüppavad diivanilt, korrates sama liigutust 50 korda ja karjudes: „Emme, vaata mind!“ Pane telefon käest. Nad ei hüppa lihtsalt hüppamise pärast, vaid selle heakskiidusädeme pärast, mida nad sinu silmis näevad. Anna neile viis katkematut minutit; lase neil seda tõeliselt nautida.'),
('4a32ef42-8519-4a15-ae15-b2e86c604165'::uuid,'0 децибелге жетүү 🤫','Акыры алар укташты! Үйгө орногон терең жымжырттыкка ишенүү кыйын. Үн өлчөгүч тиркемесин ачып, экрандагы 0-10 децибелдик көрсөткүчтү караңыз. Мээңиздин акырындык менен эс алып жатканын сезиңиз, бул «визуалдык жымжырттык» Сиздин акылыңызга кандайча эс алуу тартуулап жатканын байкаңыз.','0 detsibelli saavutamine 🤫','Nad on lõpuks uinunud! Vaevalt usud seda sügavat vaikust, mis on majja laskunud. Ava oma helitaseme mõõtmise äpp ja vaata ekraanil seda 0–10 detsibelli näitu. Tunneta, kuidas su aju aeglaselt lõdvestub, kogedes, kuidas see „visuaalne vaikus“ su meelt tõeliselt masseerib.'),
('5db98ad2-4a41-4a94-8924-de68639a6a28'::uuid,'Күтүүсүз бий 🎶','Алар жарнамалык обон болобу же унаанын сигналыбы, биринчи уккан ритмге бийлей башташат. Жашоого алар сыяктуу кубаныч менен караңыз! Аларга кошулуп бөлмөдө бир нече мүнөт бийлеңиз, ошондо бардык стрессиңиз тарап кеткенин көрөсүз.','Spontaanne tants 🎶','Nad hakkavad tantsima esimese rütmi peale, mida kuulevad, olgu see reklaamimeloodia või auto signaal. Vaata elu sama rõõmuga nagu nemad! Ühine nendega mõneks minutiks pööraseks tantsuks toas ja vaata, kuidas kogu su stress hajub.'),
('8095b6da-2b93-462b-bce2-881fa1732924'::uuid,'Өсүү трекери: Энелик сыймык 📈','Алар эми наристе эмес! Алар өз алдынча чечим чыгарган, кызыктуу суроолору жана чоң жүрөгү бар кичинекей инсан. Ал эми Сиз, апаке, сонун иш жасап жатасыз!','Kasvujälgija: Ema uhkus 📈','Nad ei ole enam beebid! Nad on täielikud väikesed inimesed oma otsuste, uudishimulike küsimuste ja suure südamega. Ja sina, emme, teed suurepärast tööd!'),
('064149bc-eacb-463c-b371-3ee4af7db167'::uuid,'Килемдеги чек аралар: Элестетүү дүйнөсү 🗺️','Алар жаңы эреже ойлоп табышты: бөлмөдөн ашканага килемдин кызыл сызыктарын гана басып баруу керек. Бул чоң моториканы көңүл буруу жана кунт коюу менен айкалыштырат. Бул логикасыз көрүнгөн эрежени бузбаңыз; алар менен бирге сызыктар боюнча бийлеп, муну эртең мененки көнүгүүңүзгө айлантыңыз.','Vaibapiirid: Kujuteldavad maailmad 🗺️','Nad on teinud uue reegli: toast kööki saab minna ainult vaiba punastel joontel astudes. See ühendab motoorika keskendumise ja tähelepanuga. Ära riku seda näiliselt ebaloogilist reeglit; liitu nendega joonel tantsides ja tee sellest oma hommikune võimlemine.'),
('60b3ac1d-dc8e-4802-b644-6bc09bfcea1f'::uuid,'Тамактануудагы талаш-тартыштар артта калды ⏱️','Алар кашыгын четке түртүп жатышабы? Тамактандыруу таймерин токтотуңуз — кичинекейиңиз тойду. Табит графигин талдоо менен, Сиз мажбурлап тамактандыруудан качып, тамак-аш менен дени сак мамилени түзө аласыз.','Söögiaja lahingud on läbi ⏱️','Kas nad viskavad lusika kõrvale? Peata toitmise taimer – su väike on kõhu täis söönud. Söögiisu graafikut analüüsides saad vältida sundtoitmist ja kujundada tervislikku suhet toiduga.'),
('2980ee34-de75-4617-8093-160c3c2da3a0'::uuid,'Жаздык астындагы театр 🎪','Алар төшөктө, бирок баштары жаздыктын астында, өзүнчө акырын сүйлөнүп жатышат. Бөлмөнү толугу менен караңгылатыңыз. Ошол караңгы, коопсуз жайда өздөрүнүн кичинекей окуяларын жаратып, акырындык менен уйку дүйнөсүнө батышсын. Кийлигишүү каалоосуна каршы туруңуз.','Teater padja all 🎪','Nad on voodis, aga pea on padja all ja nad pomisevad vaikselt omaette. Pimenda tuba täielikult. Lase neil luua oma väikesi lugusid selles pimedas ja turvalises kohas ning vajuda aeglaselt unemaailma. Hoidu kiusatusest sekkuda.'),
('af38ac43-154c-4c60-9f01-51c84d74b264'::uuid,'Чөнтөктөгү макарон көйгөйү 🍝','Кир жуучу жайга таштаган шымдын чөнтөгүнөн кургатылган макарон таап алдыңызбы? Сиз үчүн бул таштанды, ал эми алар үчүн бул жолдо ачка калганда жей турган «өзгөчө кырдаал» тамагы болушу мүмкүн! Аларды күнөөлөбөңүз; «пландоо жөндөмүнүн» бул алгачкы учкундарын Өнүгүү трекерине кызыктуу эс тутум катары жазып коюңуз.','Taskupasta dilemma 🍝','Kas leidsid pesukorvi visatud pükste taskust kuivanud makaroni? Sinu jaoks on see prügi; nende jaoks oli see ehk hädaabisuupiste juhuks, kui nälg teel olles tabab! Ära süüdista neid; salvesta need esimesed „planeerimisvõime“ sähvatused naljaka mälestusena arengupäevikusse.'),
('881d0866-6df6-4dec-801b-67b99df853c5'::uuid,'«Сууну кургат!» талабы 💧','Стакандын ичиндеги сууну ичүүнүн ордуна, «Бул өтө нымдуу экен! Кургатып бер!» деп кыйкырып жатышат. 3,5 жаштагы балдардын кызыктуу жана күлкүлүү дүйнөсүнө кош келиңиз. Түшүндүрүүгө аракет кылуу сиздин энергияңызды гана коротот. Жөн гана: «Макул, азыр сага башка, кургак суу алып келем», - деп, ошол эле сууну башка түстөгү чөйчөккө куюп бериңиз.','Nõudmine „Kuivata vesi ära!“ 💧','Selle asemel, et juua klaasis olevat vett, karjuvad nad: „See on liiga märg! Tee see kuivaks!“ Tere tulemast 3,5-aastaste veetlevasse absurdi. Selgitamine vaid kurnab su energiat. Ütle lihtsalt: „Olgu, toon sulle nüüd teistsugust, kuiva vett,“ ja anna neile sama vett teist värvi tassis.'),
('d2f34bfd-32c7-43f7-89fd-d8226236a390'::uuid,'Атамдын жашыруун даамдуу тамагы 🤫','Тиш жуугусу келбей жатышат. Атасы акырын жакындап: «Эгер тишиңди жуусаң, чөнтөгүмдөгү сыйкырдуу ташты көрсөтөм!» деп шыбырайт. Кээде аталардын мындай тапкыч жана тез таасир этүүчү оюн түрүндөгү амалдары менен кадимки тарбия эрежелерин бир аз ийкемдүү кылууга туура келет.','Issi salajane maiuspala 🤫','Nad keelduvad hambaid pesemast. Isa kummardub salaja ligi ja sosistab: „Kui hambad ära pesed, näitan sulle oma taskus olevat võlukivi!“ Mõnikord tuleb tavalisi kasvatusreegleid veidi painutada nende nutikate, kuid koheselt toimivate isade mänguliste nippidega.'),
('f968f309-08cf-46ae-901b-44ed8420ced0'::uuid,'Балкондон көрүнүш: Дүйнөнү байкоо 👀','Алар балкондо өтүп бараткандардын баарына кубануу менен кол булгалап, кыйкырып жатышат, ал эми жооп болбогондо капа болушат. Алардын социалдык байланышка болгон муктаждыгы туу чокусунда! Аларды ичкери сүйрөбөңүз; «Алар абдан алыс экен, балким сени угушпай калгандыр» деп түшүндүрүп, алардын боорукердик сезимин коргоңуз.','Vaade rõdult: maailma uudistamine 👀','Nad on rõdul, lehvitavad entusiastlikult ja hõikavad kõigile möödujatele, ning muutuvad siis kurvaks, kui vastust ei saa. Nende vajadus sotsiaalse kontakti järele on tipus! Ära tiri neid tuppa; kaitse nende tärkavat empaatiat, selgitades: „Nad on väga kaugel, võib-olla nad ei kuulnud sind.“'),
('01eb4758-ff80-4ee6-b2d8-884207fd7862'::uuid,'Тынч окуу сессиясы 📖','Бүгүн кечинде сүйлөшпөй эле коёлу. «Акылдуу жомокторду» ачыңыз, текстти үн чыгарып окуунун ордуна, жөн гана сүрөттөрүн карап, жаратылыштын жагымдуу үндөрүн угуңуз. Мындай визуалдык көңүл буруу аларды чарчатып, уйкуга табигый түрдө жетелейт.','Vaikne lugemistund 📖','Täna õhtul ei räägi me midagi. Ava „Nutikad lood“ ja selle asemel, et teksti ette lugeda, vaadake lihtsalt vaikselt pilte, mida saadavad seadmest kostvad õrnad loodushelid. See visuaalne tegevus väsitab nad ära ja juhatab nad automaatselt unne.'),
('fae36977-58eb-48b1-8551-438307ad854b'::uuid,'Жумуртканын «туура эмес» тарабы 🍳','Бышырылган жумурткасын экиге бөлүп койгонуңуз үчүн эле чоң ызы-чуу чыкты. «Мен аны бүтүн каалагам!» Тамактын көрүнүшү көбүнчө балдар үчүн эң сезимтал нерсе. Тамакты кызыктуу формада жана жагымдуу жолдор менен сунууну үйрөнүү үчүн пайдалуу рецепттерди карап көрүңүз.','Muna „vale“ pool 🍳','Suur jonnihoog tekib seetõttu, et julgesid nende keedumuna pooleks lõigata. „Tahtsin seda tervelt!“ Toidu esitlus on sageli nende kõige tundlikum koht. Uuri tervislikke retsepte, et õppida, kuidas toitu lõbusate kujundite ja kaasahaaraval viisil serveerida.'),
('fed4ec8b-badd-4ae2-b8cd-74446e67eee7'::uuid,'Кичинекей жаратылыш изилдөөчүсү 🔍','Алар сейил бакта 20 мүнөт кыймылдабай, кумурсканын ийинин карап отурушту. Аларды шаштырбаңыз! Эгерде сиз «Аба ырайы жана кийим» жардамчысынын жардамы менен аларды алдын ала жылуу жана ылайыктуу кийиндирген болсоңуз, бул кичинекей биологго дүйнөнү өз каалоосундай изилдөөгө мүмкүнчүлүк бериңиз.','Väike looduseuurija 🔍','Nad istusid pargis 20 minutit liikumatult, jälgides lihtsalt sipelgapesa. Ära kiirusta neid! Kui oled nad eelnevalt Ilma ja riietuse assistendi abil ilmale vastavalt soojalt riidesse pannud, lase sel väikesel bioloogil maailma oma südame järgi avastada.'),
('82b46290-c3d6-4ad5-8d94-600e0311ba33'::uuid,'Жөн гана кучакташууну каалайсызбы? 🛋️','Колуңуздан түшкүсү келбей жатабы? Бул эркелетүү эмес; алар жөн гана сиздин жытыңыздын жылуулугуна муктаж. Аларды кучагыңызга бекем кысыңыз – бул баалуу күндөр көз ачып-жумгуча өтүп кетет.','Tahad ainult kaisutada? 🛋️','Ei taha su sülest lahkuda? See pole ärahellitamine; nad vajavad lihtsalt su lõhna pakutavat turvatunnet. Hoia neid lähedal – need väärtuslikud päevad mööduvad kiiresti.'),
('0601b05e-a2e4-4730-b08b-f661e0e89b2a'::uuid,'Ваннадагы кичи лаборатория 🛀','Алар сууга ар түрдүү түстөгү самындарды аралаштырып, сыйкырдуу дары жасап жатышат. Ооба, ванна бөлмөсү бир аз чачылып кетиши мүмкүн! Бирок алар эриткичтер жана заттардын айкалышуусу жөнүндө үйрөнүп жатышат. Мындай илимий изилдөө кечки чарчоону басуунун жана аларды тынч уйкуга акырындык менен даярдоонун эң сонун жолу.','Vannitoa minilabor 🛀','Nad segavad vees erinevat värvi seepe, luues võlujooki. Jah, vannituba võib veidi sassi minna! Kuid nad õpivad lahustite ja ainete segunemise kohta. Selline teaduslik avastamine on suurepärane viis õhtuse väsimuse leevendamiseks ja nende õrnaks une-eelseks ettevalmistamiseks.'),
('19a9511e-358f-41a2-bbf2-d966afa6ffa9'::uuid,'Күнүмдүк тартипти талдап көрөлү ⏱️','Наристеңиздин кечки ойгоо убактысы өтө узарып баратабы? Уйку таймерин иштетип, графикти көзөмөлдөңүз. Балким, алардын күндүзгү уйкусун 15 мүнөткө кыскартуунун дал убагыдыр.','Analüüsime rutiini ⏱️','Kas su pisikese õhtune ärkvelolekuaeg venib liiga pikaks? Käivita unetaimer ja jälgi graafikut. Võib-olla on ideaalne aeg lühendada nende päevaund 15 minuti võrra.'),
('15d2ba80-4fad-4f86-8e70-6261ae666ebc'::uuid,'Шкафтагы жашынуучу жай: Жалгыздык издөө 🚪','Үйдүн ичинде күтүлбөгөн жерден жымжырттык орноду. Сиз аларды караңгыда, шкафтын ичинде жалгыз ойноп жатканын таптыңыз. Бул депрессиянын белгиси эмес; бул жөн гана эмоционалдык жактан эс алуу учуру. Эшикти акырын жаап, аларга жеке мейкиндиктин бул ырахатын тартуулаңыз.','Peidupaik kapis: omaette olemine 🚪','Äkiline vaikus keset maja. Leidsid nad pimedas üksi riidekapis mängimas. See pole depressiooni märk; see on lihtsalt hetk emotsionaalseks taastumiseks. Sulge vaikselt uks ja luba neile seda isikliku ruumi luksust.'),
('869bedae-ce51-4c50-8799-4b322d523e09'::uuid,'Тийүүнүн күчү 🔋','Күн бою үстүңүзгө чыгып, чачыңызды тарткан баладан улам физикалык жактан чарчадыңызбы? Аларды дароо коопсуз жерге отургузуп, башка бөлмөгө чыгып кетиңиз. Бул «ашыкча тийишүү» синдромунун психологиялык жүгүн жеңилдетүү үчүн «Маанай күндөлүгүңүзгө» «Менин денем меники эмес» деп жазып коюңуз.','Puudutuse vägi 🔋','Oled füüsiliselt kurnatud lapsest, kes on terve päeva su otsas roninud ja juukseid kiskunud. Pane nad kohe turvalisse kohta ja mine teise tuppa. Kirjuta oma meeleolupäevikusse „Minu keha pole minu oma“, et vabastada end sellest „puudutustest üleküllastumise“ psühholoogilisest koormast.'),
('5817fca0-3cbb-4276-a47d-9383c042597d'::uuid,'Үндү көзөмөлдөө 🤫','Ар бир чыккан үндөн улам уктап жаткан балаңыз ойгонуп кетеби деп тынчсызданып, дайыма чочулап жүрөсүзбү? Үн мониторун иштетиңиз жана алардын баалуу уйкусун коргоого жардам берүү үчүн бөлмөнүн акустикасын текшериңиз.','Helikontroll 🤫','Kas oled pidevalt ärevil, muretsedes, et iga heli võib su magava beebi üles äratada? Aktiveeri helimonitor ja kontrolli ruumi akustikat, et aidata kaitsta nende väärtuslikku und.'),
('4a91e0c3-a4cb-4e5c-b68a-474b7d153369'::uuid,'Жоолуктарды саноону уланткыла! 🧷','Балаңыздын күнүмдүк жалаяк алмаштыруусун Anacan тиркемесине белгилеп туруу менен анын жакшы тамактанып жатканын камсыз кылыңыз.','Jätka mähkmete lugemist! 🧷','Veendu, et su beebi sööb hästi, logides nende igapäevase mähkmete arvu Anacanis.'),
('18c831a2-2a8d-41b4-aec0-3fc3423e4549'::uuid,'Үн өлчөгүч менен ички тынчтык 🤫','Акыры укташты. Бирок кулагыңыздагы «шыңгыр» басылбай койду. Колдонмодогу Үн өлчөгүчтү (Sound Meter) ачыңыз. Экрандагы «0 децибелди» карап жатып, бөлмөдөгү терең тынчтыктын акылыңызга сиңип, сизди айыктырып жана калыбына келтирип жатканын сезиңиз.','Sisemine rahu helimõõtjaga 🤫','Nad on lõpuks uinunud. Kuid „helin“ su kõrvus ei taha vaibuda. Ava rakenduses helimõõtja. Kui vaatad ekraanil „0 detsibelli“, tunne, kuidas ruumi sügav vaikus imbub su mõtetesse, tervendades ja taastades sind.'),
('64255b01-33d4-405e-b645-f0ff22d8defe'::uuid,'Кичинекей телефон уурусу 📱','Чай куюп жатып телефонуңуз жок экенин байкайсыз, анан дивандын артынан ал сиздей болуп «Салам» деп жатканын угасыз. Алар сиздин санариптик адаттарыңызды байкап жатышат! Аппаратты алганыңызда, тамашалап: «Менин телефонум да сени менен сүйлөшкүсү келиптир!» деп айтып, кайра алыңыз.','Väike telefonivaras 📱','Teed endale teed valades märkad, et telefon on kadunud, ja siis kuuled seda diivani tagant täpselt nagu sina ütlemas „Hallo“. Nad skaneerivad su digitaalseid harjumusi! Kui seadme kätte saad, ütle mänguliselt: „Mu telefon tahtis ka sinuga rääkida!“ ja võta see tagasi.'),
('d0533c80-d46b-4d9f-9654-8ce50e72523b'::uuid,'«Өзүң кийин!» саясаты 👖','Алар буттарын асманга көтөрүп: «Мен наристемин, мени кийиндир!» деп жарыялашат. Алар дайыма көз карандысыздык менен көз карандылыктын ортосунда жүрүшөт. Аларды кийинүүгө мажбурлабаңыз. Тескерисинче, кийимдерди жанына коюп, тамашалап: «Бул супер баатырдын шымы өзүнүн сонун ээсин күтүп жатат!» деп сунуштаңыз.','Poliitika „Pane ise riidesse!“ 👖','Nad tõstavad jalad taeva poole, kuulutades: „Olen beebi, riieta mind!“ Nad navigeerivad pidevalt iseseisvuse ja sõltuvuse vahel. Ära sunni neid riidesse panema. Selle asemel aseta riided lähedale ja soovita mänguliselt: „Need superkangelase püksid ootavad lihtsalt oma ägedat omanikku!“'),
('5d82c548-2228-430b-916c-6c21c900e5fe'::uuid,'Шыбырдын сыйкырдуу күчү 🌙','Алар уктоо убактысын өткөрүп жиберүү үчүн ар кандай шылтоолорду ойлоп табышууда. Үнүңүздү таптакыр басаңдатып, шыбырап гана сүйлөңүз. Алар сизди түшүнүү үчүн физикалык жактан топтолууга аргасыз болушат, бул катуу көңүл буруу алардын мээсин акырын гипноздоп, уйкуга тартат.','Sosina müstiline vägi 🌙','Nad mõtlevad välja igasuguseid vabandusi, et vältida magamaminekut. Langeta oma hääl täielikult ja räägi ainult sosinal. Nad peavad füüsiliselt keskenduma, et sinust aru saada, ja see intensiivne fookus hüpnotiseerib nende aju, uinutades nad õrnalt unne.'),
('e401c834-583c-49ec-8d04-289b6b62d99b'::uuid,'Anacan коомчулугунан сооронуч табуу 💬','«Мен эч качан идеалдуу болбойм» деген сезим сизди кыйнап жатабы? «Инстаграмдагы эне» деген элести өчүрүңүз! Anacan коомчулугуна кирип, үйү чачылган жана балдары дубалга сүрөт тарткан энелердин чынчыл моюнга алууларын окуп, өзүңүзгө: «Мен таптакыр кадимки эле энемин» деп ишенич бериңиз.','Rahu leidmine Anacani kogukonnast 💬','Kas tunne „Ma ei saa kunagi täiuslikuks“ matab su enda alla? Kustuta see „Instagrami ema“ illusioon! Sisene Anacani kogukonda ja loe ausaid ülestunnistusi emadelt, kelle kodud on sassis ja kelle lapsed on seintele joonistanud, ning kinnita endale: „Olen täiesti normaalne.“'),
('fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6'::uuid,'Динозавр логикасы 🦖','Эртең менен алар суроолорго жооп бербей, бир гана ырылдашат. Бүгүн алар Ти-Рекс. Ти-Рекстер ботко жейби? Алардын ойдон чыгарган образына ыңгайлашып, эртең мененки жөрөлгөнү көз жашсыз бүтүрүңүз.','Dinosauruste loogika 🦖','Hommikul nad küsimustele ei vasta, ainult möirgavad. Täna on nad T-Rex. Kas T-Rexid söövad putru? Kohane nende väljamõeldud karakteriga ja vii hommikune rituaal läbi ilma pisarateta.'),
('5a7d778f-6e03-4003-a60c-0214c0dc5a0b'::uuid,'Атамдын ойдон чыгарылган баатырлары 🦸‍♂️','Бүгүн кечинде салттуу китеп жомокторун унутуңуз. Атасы балаңыз башкы каарман болгон ойдон чыгарылган фантастикалык жомок айтып берсин. «Ал өзүнүн кудуреттүү кылычын сууруп чыкты... анан тишин жууду!» деген сыяктуу сүйлөмдөр балаңызды каткыртып, уйкуга акырын даярдайт.','Issi kujuteldavad kangelased 🦸‍♂️','Unusta täna õhtul traditsioonilised raamatulood. Las isa räägib väljamõeldud ja fantastilise loo, kus su laps on peategelane. Laused nagu „Ja ta tõmbas oma vägeva mõõga... ja siis pesi ta hambad!“ panevad su lapse naerma ja valmistavad nad õrnalt uneks ette.'),
('732719f9-46cf-4097-a068-781df2eeaf00'::uuid,'Өз сүрөттөрүн сыноо 🖍️','Алар сизге кара чиймелерин көрсөтүп, «Бул сенсиң, бирок бул жаман» деп жарыялап, аны айрып салышат. Алардын өзүн-өзү сыноо жөндөмү өнүгүп жатат! Алардын сезимдерин баалабай койбоңуз; тескерисинче, «Кийинки сүрөтүңө кызыл түстү колдонуп көрсөңчү?» деп сунуштап, алардын өнүгүүсүн колдоңуз.','Oma kunsti kritiseerimine 🖍️','Nad näitavad sulle oma musta kritseldust, kuulutavad „See olid sina, aga see on paha“ ja rebivad selle siis katki. Nende enesekriitika võime on tärkamas! Ära alahinda nende tundeid; toeta hoopis nende arengut, soovitades: „Ehk proovid järgmisel joonistusel punast värvi?“'),
('aa506c93-122a-43f1-8742-2605113c516c'::uuid,'Базардан тапкан олжом! 🛒','Кассага жакындаганыңызда, арабада сиз салбаган бир пакет печенье сыйкырдуу түрдө пайда болот. Кичинекей изилдөөчүңүз иштеп жатат! Соода тизмеңизди ачып: «Карачы, бул биздин тизмеде жок экен. Кийинки жолу кошуп коёбуз!» деп айтыңыз. Ушундай кылуу менен, сиз тизменин санариптик бийлигине эрежени сактоого мүмкүнчүлүк берип жатасыз.','Minu avastus turult! 🛒','Kassasse jõudes ilmub kärusse salapäraselt pakk küpsiseid – selline, mida sina sinna ei pannud. Su väike avastaja on olnud tegus! Ava oma ostunimekiri ja ütle: „Vaata, seda pole meie nimekirjas. Lisame selle järgmiseks korraks!“ Nii lased nimekirja digitaalsel autoriteedil reeglit jõustada.'),
('d3d2b281-0b44-4f04-8791-8ceca32ccdb3'::uuid,'Гениалдуу ойлоп табуучу 👟','Алар бут кийимди кулагына кармап, олуттуу түрдө «Алло?» деп жатышат. Алар буюмдардын жаңы функцияларын ойлоп табууда! Бул абсурддуу, бирок укмуштуудай учурду өткөрүп жибербеңиз. Бул күлкүлүү ойлоп табуучуну мини-фотосессия менен тартып алып, архивдериңиздин эң жаркыраган жерине сактап коюңуз.','Geniaalne leiutaja 👟','Nad hoiavad kinga kõrva ääres, räägivad tõsiselt ja ütlevad „Hallo“? Nad leiutavad esemetele uusi funktsioone! Ära maga maha seda absurdset, kuid geniaalset hetke. Jäädvusta see naljakas leiutaja miniseansiga ja pane see oma arhiivi kõige eredamasse kohta.'),
('0b6916b1-4773-417f-aed4-71c7ff7f85e9'::uuid,'Жекече чай ичүү убактысы 🥂','Оор күндөн кийин өзүңүзгө жылуу чай куюп ичиңиз. Диванда өнөктөшүңүздүн маңдайында отуруп, стакандарды кагыштырып: «Биз бүгүнкү башаламандыкты да жеңип чыктык, биз кандай сонун командабыз!» деп айтыңыз. Сиздер бул үйдүн бузулгус пайдубалысыздар.','Teeõhtu kahekesi 🥂','Pärast rasket päeva valage endale lohutavat kuuma teed. Istuge partneriga diivanil vastamisi, kõlistage klaase ja öelge: „Me isegi elasime selle kaose täna üle, oleme nii suurepärane meeskond!“ Te olete selle kodu purunematu vundament.'),
('8bce8353-bf73-417b-8a15-56b41142ba18'::uuid,'Жашыруун жашылчалар операциясы 🥦','Балаңыз шорпосундагы бир даана күрүчтү же кичинекей сабизди байкап калып: «Мен муну жебейм!» деп жарыялайт. «Тамактануу планына» өтүңүз. Белокторду жана жашылчаларды түстүү кекс формасында кантип жашыруун кошууну үйрөнүп, тамак тандаган кичинекей балаңызды алдап кетиңиз!','Operatsioon: Peidetud köögiviljad 🥦','Su laps märkab supis seda ühte riisiterakest või tillukest porgandit ja kuulutab: „Mina seda ei söö!“ Suundu „Toitumiskava“ juurde. Avasta, kuidas nutikalt peita valke ja köögivilju värvilistesse muffinitesse, tehes oma väikesele pirtsutajale ära!'),
('ef39807d-1235-46a3-9ca8-a0f70bb2fa23'::uuid,'Эмерекке чыгуу боюнча олимпиада 🧗‍♂️','Алар дивандын чети менен терезени көздөй сойлоп баратат. Сиз үчүн үй коркунучтуу жерлерге толгон, ал эми алар үчүн бул жеке гимнастикалык зал. «Этият бол, кулап кетесиң!» деп дүрбөлөңгө түшүп кыйкыруунун ордуна, бул кыймыл муктаждыгын: «Колуңду тигил жерге кой» деп сабырдуулук менен багыттаңыз.','Mööblironimise olümpiamängud 🧗‍♂️','Nad ronivad mööda diivani äärt akna poole. Sinu jaoks on maja täis võimalikke ohte; nende jaoks on see isiklik võimla. Selle asemel, et paanitseda ja karjuda „Ole ettevaatlik, sa kukud!“, suuna seda liikumisvajadust, öeldes rahulikult: „Pane käsi siia.“'),
('000abcf3-b4c9-4928-8d58-c7a8f138f07f'::uuid,'AI жана бейпилдик 🤖','Балаңыздын күтүлбөгөн жерден кекечтениши же каприз болушу сизди интернеттен коркунучтуу ооруларды издөөгө мажбурладыбы? Токтоңуз! Anacan AI''дан бул 3 жаштагы өнүгүү секиригиби деп сураңыз жана педиатр тарабынан жактырылган, ишенимдүү жооп алыңыз.','Tehisintellekt ja meelerahu 🤖','Kas su lapse äkiline kogelemine või ootamatud jonnihood on sind interneti otsingutesse viinud, otsides hirmutavaid haigusi? Peatu kohe! Küsi Anacani AI-lt, kas tegemist on 3-aastase arenguhüppega, ja saa pediaatri heakskiidetud rahustav vastus.'),
('ac974535-4db4-4ecb-aa90-d75a7dabe40a'::uuid,'Бөлмөдөгү үн эффекттери 🪄','«Акылдуу жомокторду» ачыңыз. Жомокту окуп жатып, эшиктин кычыраганын, жумшак шамалды же шыбырды туурап, бөлмөдө жагымдуу добуштук чөйрө түзүңүз. Мындай өзгөчө добуштар баланын көңүлүн дароо жомокко буруп, андан ары терең уйкуга жетелейт.','Heliefektid toas 🪄','Ava ''Nutikad lood''. Lugu lugedes loo toas õrn helitaust, matkides kriuksuvat ust, pehmet tuuleiili või sosinat. Need peened ja ebatavalised helid köidavad lapse tähelepanu ning aitavad tal sujuvalt sügavasse unne vajuda.'),
('e9945ad4-3802-48f8-b0bf-d94527c3999b'::uuid,'Көлөкөлөрдөн качуу 👻','Көчөдө баратып, балаңыз күтүүсүздөн өз көлөкөсүнөн коркуп, Сиздин артыңызга жашынып калышы мүмкүн. Бул жерден логика издебеңиз; бул болгону 3,5 жашар баланын бай фантазиясынын натыйжасы. «Кел, көлөкөнү тебелейли!» деп, анын коркуусун дароо кызыктуу оюнга айлантыңыз.','Varjude eest põgenemine 👻','Tänaval kõndides võib laps äkki oma varju karta ja sinu taha peituda. Ära otsi siit loogikat – nii töötab 3,5-aastase elav kujutlusvõime. Muuda hirmutav objekt hetkega lõbusaks mänguks, öeldes: ''Hüppame varju peale!'''),
('06d21315-e90d-4d7c-a84d-b0f3acd86dc9'::uuid,'Атамдын ийинге массажы 💆‍♂️','Сиз күнү бою бутуңуздан тик турдуңуз; балаңыздын артынан чуркап, оюнчуктарды жыйнап белиңиз ооруп калды. Балаңыз уктаар замат, өмүрлүк жолдошуңуздан 10 мүнөттүк ийин массажын сураңыз. Сиз бул үйдүн кыймылдаткычысыз, ал эми кыймылдаткычка сөзсүз түрдө эс алуу жана күч-кубат алуу керек.','Issi õlamassaaž 💆‍♂️','Oled terve päeva jalgadel olnud; selg valutab mänguasjade korjamisest ja lapse tagaajamisest. Niipea kui laps uinub, palu partnerilt 10-minutilist õlamassaaži. Sina oled selle kodu mootor ja mootor vajab puhkust ning tankimist.'),
('3d278e8d-5fc9-46fa-ad40-bcef90b99e90'::uuid,'Кимдир бирөө сизди «жаман эне» дедиби? 💔','Сиз ал каалаган оюнчук машинаны алып бербегениңиз үчүн ал ушундай сөздөрдү айтты жана Сиздин жүрөгүңүз ооруп кетти. Бирок эсиңизде болсун, ал өз сезимдерин азырынча так айтып бере албайт; чындыгында ал «Мен капа болдум» деп айткысы келип жатат. Жөн гана аны кучактап, сезимдерин түшүнгөнүңүздү билдириңиз.','Kas keegi nimetas sind „halvaks emaks“? 💔','Ta ütles *seda*, sest sa ei ostnud talle soovitud mänguautot, ja su süda vajus saapasäärde. Kuid pea meeles, et ta ei oska veel oma tundeid sõnadesse panna; tegelikult tahab ta öelda: ''Olen pettunud.'' Lihtsalt kallista teda ja tunnusta tema tundeid.'),
('d54e4e25-89e6-430d-b9c4-307312ee2246'::uuid,'Стиль сезими 👗','Кичинекейиңиз сейил бакка бара жатканда кышкы байпактын сыртынан жайкы сандал кийип алам деп өжөрлөнүп, чечпей жатабы? Коомдук нормаларды бир азга унутуңуз. Анын чыгармачылыгын өстүрүү үчүн, ошол өзгөчө жана кызыктуу көрүнүш менен жүрө берүүсүнө уруксат бериңиз – ал өзүн көрсөтүүнү үйрөнүп жатат!','Stiilitunnetus 👗','Sinu väike põngerjas nõuab parki minnes suvesandaale koos talvesokkidega ega taha neid jalast võtta. Unusta hetkeks ühiskondlikud normid. Loovuse toetamiseks lase tal seda unikaalset ja naljakat välimust nautida – ta õpib ennast väljendama!'),
('9fab66ef-18f3-4cdb-8e01-0a4f9485cffe'::uuid,'Күзгүдөгү ким? 🪞','Алар күзгүнүн алдында кабагын бүркөп, тынчсызданган жана кызыктай мимикаларды жасап жатышат. Алар сезимдердин жүздө кандай көрүнөрүн байкап көрүшүүдө. Бул кичинекей театр актёрунун репетициясын четтен унчукпай жана кубаныч менен байкаңыз.','Kes see seal peeglis on? 🪞','Ta seisab peegli ees, kortsutab kulmu ja teeb veidraid nägusid. Ta katsetab, kuidas emotsioonid näol välja näevad. Jälgi seda pisikest teatrinäitlejat eemalt vaikselt ja naudinguga.'),
('61d69ed1-ecb9-44fd-ac6a-cb922359921f'::uuid,'Сиздин кичинекей сүрөтчүңүз иштеп жатат! 📸','Кичинекей сүрөтчүңүз өзүн жана дубалды «кооздоп» салдыбы? Капа болбостон, бул кызыктуу учурду сүрөткө тартып, «Бөбөк фотосессияларындагы» шайыр стикерлер менен кооздоп, баалуу эскерүү катары альбомго жүктөңүз.','Sinu väike kunstnik tegutseb! 📸','Kas sinu väike kunstnik kaunistas nii iseennast KUI ka seina? Selle asemel, et pahandada, jäädvusta see naljakas sodimishetk, kaunista see ''Beebifotode'' rõõmsate kleebistega ja laadi albumisse kui armas mälestus.'),
('df219eb3-fe33-48d7-81df-3e2d39df4620'::uuid,'Колуңуздан эмнелер келерин караңыз! 💖','Күзгүдөн чарчаган көздөрүңүздү карап, жылмайыңыз. Сиз эч кандай нускамасы жок эле кереметти тарбиялап жатасыз – Сиз баарын сонун аткарып жатасыз!','Vaata vaid, milleks sa võimeline oled! 💖','Vaata peeglist oma väsinud silmi ja naerata. Kasvatad imet ilma kasutusjuhendita – teed suurepärast tööd!'),
('e70841e8-9af5-471e-9ff6-b28774448a7f'::uuid,'Сураныч, тоскоол болбоңуз 🧦','Байпагынын согончогу өйдө карап турат, бирок ал өзү кийгени үчүн дүйнөдөгү эң сыймыктанган адамдай басып жүрөт. Такыр кийлигишпеңиз! Ийгиликке жетүү жана көз карандысыздык сезими байпакты туура кийгенден алда канча маанилүү.','Palun ära sekku 🧦','Soki kand on pealpool, aga ta kõnnib ringi nagu maailma uhkeim inimene, sest pani sokid ise jalga. Ära sekku! Saavutustunne ja iseseisvus on palju tähtsamad kui täiuslikult jalas olevad sokid.'),
('b8be3052-4ca5-4460-8506-d2c5926555b2'::uuid,'Апамдын эс алуучу жайы 🚪','Ызы-чуу мээңизди жеп, баарына кыйкыргыңыз келип жатабы? Кичинекейиңизди коопсуз жерге калтырып, дааратканага кирип, эшикти жабыңыз. «Маанай күндөлүгүн» ачыңыз. Бардык чарчооңузду ошол жерге эркин төгүңүз. Бул кыска терапия Сиздин калыбына келишиңизге жардам берет.','Ema oma aja pelgupaik 🚪','Müra puurib su ajus ja tunned, et tahaksid kõige peale karjuda. Pane laps turvalisse kohta, mine vannituppa ja sulge uks. Ava oma ''Tujupäevik''. Vala kogu oma väsimus sinna. See lühike teraapia aitab sul end nullida.'),
('cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6'::uuid,'Караңгылыкты кабыл алуу 🐰','Алар уктоодон качуу үчүн караңгыдан коркууну шылтоо кылып жатышат. Бөлмөнүн бардык жарыгын өчүрүп, кол чыракты алыңыз жана дубалга куштардын же иттердин көлөкөсүн түшүрүңүз. Алар мурда корккон караңгылык бир нече секунддун ичинде сыйкырдуу көлөкө театрына айланат.','Pimedusega sõbrunemine 🐰','Ta kasutab pimedusehirmu ettekäändena, et voodisse minekut vältida. Kustuta tuled, võta taskulamp ja tee seinale lindude või koerte varjukujusid. Hirmutav pimedus muutub sekunditega maagiliseks varjuteatriks.'),
('217250d8-e2a0-42ca-ac61-232ced171632'::uuid,'Аба ырайын байкоо стратегиябыз ⛅','Күн тийип турат, бирок ошол эле учурда алдамчы шамал да бар. Терезеден бир карап эле алданбаңыз! «Аба ырайы жана кийим тандоо» куралы Сизге «сезилген температураны» жана эң туура кийинүү айкалышын дароо айтып берет. Ошентип, эшиктин алдында убакыт коротпостон, ден соолукка пайдалуу сейилдөөгө чыга аласыз.','Meie ilmaluure strateegia ⛅','Päike paistab, aga tuul on salakaval. Ära lase end aknast piiludes petta! Kasuta ''Ilma ja riietuse tööriista'', et teada saada tegelikku tunnetuslikku temperatuuri ja parimat riietuskihti. Nii saate tervislikule jalutuskäigule minna ilma ukse ees kõhklemisele aega raiskamata.'),
('4a193a83-4450-45ef-8b03-b9487c79d984'::uuid,'Бул менин күнөөм эмес! 🤷‍♂️','Алар атайлап жерге суу төгүп, анан «Ал мени түртүп жиберди!» деп оюнчугун күнөөлөштү. Бул калп эмес; бул баланын мээсинин коргонуу механизми. Талашпаңыз. Анын ордуна: «Кел, бул оюнчукка кантип жыйноо керектигин үйрөтөлү!» деп, анын көңүлүн оюнга буруңуз.','See pole minu süü! 🤷‍♂️','Ta ajas meelega vett põrandale, aga süüdistas siis mänguasja: ''See lükkas mind!'' See pole valetamine, vaid lapse aju kaitsemehhanism. Ära vaidle. Selle asemel ''triki'' teda mänguliselt: ''Õpetame mänguasjale, kuidas koristada!'''),
('c170e0aa-73e3-4e36-8c66-e8887556d5ab'::uuid,'Ваннадагы океан бороону 🌊','Жуунуу убактысы эми жөн гана тазалануу эмес, бул кичи-цунами түзүү оюну! Суунун ар тарапка чачырашына уруксат бериңиз. Суунун ошол сыйкырдуу, энергияны тазалоочу касиети балаңыздын күн бою топтогон бардык терс энергиясын жууп кетет.','Ookeanitorm vannis 🌊','Vanniskäik pole enam ainult pesemine, vaid mini-tsunami loomise mäng! Lase veel pritsida. Vee müstiline ja energiat puhastav toime peseb maha kogu päeva jooksul kogunenud kangekaelse negatiivse energia, saates selle otse äravoolust alla.'),
('28383f04-88e3-44f0-b462-99283a8b08f3'::uuid,'Денеңиздин SOS сигналы 🩸','Түшүнүксүз ачууланууга жана чарчоого алдырбаңыз. «Цикл календарын» текшериңиз — денеңиз Сизге белги берип жатат! Өзүңүздү күнөөлөөнүн ордуна, «Дени сак рецепттерден» магнийге бай тамак тандап, эс алыңыз. Бул гормоналдык өзгөрүүлөрдүн таасири болушу мүмкүн.','Sinu keha SOS-signaal 🩸','Ära alistu lihtsalt seletamatule ärritusele ja väsimusele. Kontrolli oma ''Tsüklikalendrit'' – su keha saadab sulle signaale! Selle asemel, et end süüdistada, lõõgastu ''Tervislike retseptide'' magneesiumirikka suupistega. Tõenäoliselt on mängus hormonaalsed muutused.'),
('4c7f9f66-bdd5-4db6-8e78-8af325982d85'::uuid,'Эртең мененки ойлор 🤔','«Эмне үчүн канаттуулар кулап кетпейт?», «Эмне үчүн дарак жашыл?» Таң эрте илимий конференция расмий түрдө ачылды! Эгер так жооп берүүдөн чарчасаңыз, суроону өзүнө кайтарып: «Сен кандай деп ойлойсуң?» деп сураңыз жана анын фантазияга бай жоопторун ырахат менен угуңуз.','Hommikused mõtisklused 🤔','''Miks linnud alla ei kuku?'', ''Miks puu on roheline?'' Hommik on ametlikult avanud teaduskonverentsi! Kui oled väsinud täpseid selgitusi andmast, küsi küsimus neilt tagasi: ''Mida sina arvad?'' ja naudi nende imelisi, fantaasiarikkaid vastuseid.'),
('132a3a1b-1001-4fec-a775-7883117a6988'::uuid,'Күнүмдүк тартип кандай жүрүп жатат? 📈','Тамактандыруу календарын жана Уйку таймерин текшерип, акыркы статистикаңызды карап чыгыңыз.','Kuidas rutiin edeneb? 📈','Vaata oma hiljutist statistikat ''Toitmise jälgija'' ja ''Une taimeri'' kaudu.'),
('ab1d1514-de05-4637-8009-2407cc320f46'::uuid,'Уйку таймери боюнча макулдашуу ⏱️','Уктоо убактысы жакындаганда, алар күтүүсүздөн суусап, дааратканага баргысы келип же бөлмөдөгү ар бир буюм менен коштошууну чечишет. Таймерди коюңуз. Бул чексиз коштошууларды жана убакытты созуу ыкмаларын жөнгө салуу үчүн «коңгуроо кагылганда жарык өчөт» деген эрежени киргизиңиз.','Unetaimeri kokkulepe ⏱️','Magamamineku eel tekib lapsel äkki janu, vajadus tualetti minna või soov öelda head ööd igale toas olevale esemele. Pane taimer käima. Kehtesta reegel ''tuled kustu, kui kell heliseb'', et nende lõputute hüvastijättude ja viivitamistaktikatega kindlalt toime tulla.'),
('310065f1-7769-41dc-b05f-15aba7ca4982'::uuid,'Супермаркеттеги каприз 🛒','Балаңыз кассада таттуу сурап кыйкырып жатабы? Айланадагылардын сын көз караштарына такыр көңүл бурбаңыз. Түз карап, эрежени түшүндүрүңүз жана бекем туруңуз. Эгер ал тизмеде жок болсо, аны үйгө алып кетпейбиз.','Jonnituur supermarketis 🛒','Kas laps karjub kassas maiustuste järele? Eira täielikult kõrvalseisjate hukkamõistvaid pilke. Võta rahulikult silmside, selgita reeglit ja jää endale kindlaks. Kui seda pole nimekirjas, siis see meiega koju ei tule.'),
('d64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e'::uuid,'«Сен кимсиң?» оюну 🎭','Алар Сизди абдан олуттуу карап: «Сиз кимсиз? Менин апам кайда?» деп сурашат. Алар Сиз менен актёрдук оюн ойноп жатышат! Үнүңүздү өзгөртүп: «Мен сенин кошуна досуңмун, апаң азыр келет» деп, бул сонун театрлаштырылган оюнду улантыңыз.','„Kes sa oled?“ mäng 🎭','Ta vaatab sind väga tõsise näoga ja küsib: ''Kes sa oled? Kus mu emme on?'' Ta mängib sinuga näitlemismängu! Muuda häält ja ütle: ''Olen su naabri-sõber, emme tuleb kohe tagasi,'' ja jätka seda toredat teatrietendust.'),
('f9b49a33-7a6d-4463-b26d-b51d28283257'::uuid,'Күтүүсүз «Мен сени сүйөм» 💖','Алар бөлмөнүн ортосунда ойноп жатып, күтүүсүздөн Сизди карап, чуркап келип, мойнуңуздан кучактап калышат. Мындай учурлар уйкусуз түндөрдүн жана ар бир чарчоонун акыбетин кайтарат! Бул терең, өзгөчө кубанычты сезиңиз, ошондо бардык башаламандыкты дароо унутасыз.','Spontaanne „ma armastan sind“ 💖','Ta mängib toas rõõmsalt, jookseb siis äkki sinu juurde ja paneb käed ümber su kaela. Just sellised hetked muudavad iga unetu öö ja väsimuse väärtuslikuks! Naudi seda sügavat ja ainulaadset rõõmu ning unustad hetkega kogu kaose.'),
('3674bd2e-5c13-4e77-8d3d-732d072d4226'::uuid,'Башаламандыктан шедеврге чейин 🎨','Бөлмөнүн ортосунда алар кагаздын калдыктарынан жана кесилген жиптерден «шедевр» жаратышты жана аны ыргытууга такыр уруксат беришпейт. Жыйноо каалооңузду четке коюңуз. Алардын чыгармачыл башаламандыгын сыйлаңыз — жыйноо иши эртеңкиге чейин күтө турат.','Segadusest meistriteoseni 🎨','Ta on keset tuba loonud suurepärase ''meistriteose'' paberitükkidest ja lõngajuppidest ning ei luba seda mingil juhul ära visata. Jäta koristamissoov kõrvale. Austa tema loodud loomingulist kaost – koristada jõuab ka homme.'),
('f14df610-5f47-47f4-b085-7728f03a38c4'::uuid,'Сүйлөмдөрдү толуктаңыз 🗣️','Сөздү унутуп калганда, алар жаңсоолорду жасап, кабагын бүркөп, Сиздин табышыңызды күтүшөт. Алардын сөз байлыгы кеңейүүдө, бирок кээде мээси тилине караганда тезирээк иштейт. Сүйлөмүн аяктаганда анын жүзүндөгү «Аха, мен ушуну айткым келген!» деген жеңилдөөнү чыдамдуулук менен байкаңыз.','Lõpeta laused 🗣️','Kui ta sõna unustab, teeb ta žeste, kortsutab kulmu ja ootab, et sa ära arvaksid. Tema sõnavara laieneb, kuid vahel töötab aju kiiremini kui keel. Jälgi kannatlikult, kuidas ''Ah, seda ma mõtlesingi!'' kergendus tema näole levib, kui ta lõpuks lause lõpetab.'),
('489e6dea-7ed3-426f-a373-fa7b11cafdff'::uuid,'Атамдын аркасында пони болуп ойноо 🐴','Дагы эле күчкө толуп, уктоодон баш тартып жатабы? Атаны жардамга чакырыңыз! Ал баланы «ат» кылып ойноткондо, бөлмө күлкүгө толуп, топтолгон физикалык чыңалуу жана чексиз энергия бир нече мүнөттө тер менен кошо чыгып кетет.','Hobusemäng issi seljas 🐴','Kas laps on ikka täis energiat ja keeldub magama minemast? Kutsu issi appi! Kui ta teeb lapsele lõbusat ''hobusesõitu'', täitub tuba naeruga ning kogu füüsiline pinge ja piiritu energia hajuvad hetkega koos väikese higiga.'),
('654f0e0a-2920-4fe5-8cf5-be2fa96fa926'::uuid,'Апамдын энергиясын көтөрүү 🥑','Сиз ага тамак жедириш үчүн төрт башка меню даярдадыңыз, ал эми өзүңүз жөнүндөчү? Сиз бул үй-бүлөнүн кыймылдаткычысыз жана Сизге күч-кубат алуу керек! «Дени сак рецепттерден» 5 мүнөттө даяр боло турган, кальцийге бай өзгөчө тамак тандап, бутуңузда туруп жесеңиз да, анын даамын татыңыз.','Ema energialaks 🥑','Oled valmistanud neli erinevat menüüd, et laps sööks, aga mis saab *sinust*? Sina oled selle majapidamise mootor ja vajad laadimist! Vali ''Tervislike retseptide'' hulgast spetsiaalne kaltsiumirikas suupiste, mis valmib 5 minutiga, ja naudi seda, isegi kui sööd jalgadel olles.'),
('f72407e2-133f-448d-813f-15315e00fa30'::uuid,'Мышыктай болуп ойгонуу 🐾','Бүгүн эртең менен ал адам эмес. Ал төрт аяктап басып, бутуңузга сүйкөнүп, «мияулоо» менен гана сүйлөшүп жатат. Бул алардын фантазиясынын эң таттуу учуру. Эреже коюунун ордуна, ага элестетилген бир табак сүт сунуштап, бул кызыктуу оюнга кошулуңуз.','Ärkamine nagu kass 🐾','Täna hommikul pole ta inimene. Ta kõnnib neljakäpukil, hõõrub vastu su säärt ja suhtleb ainult ''mjäu''-des. See on tema kujutlusvõime kõige armsam tipphetk. Selle asemel, et reegleid seada, ühine mänguga, pakkudes talle kujuteldavat kausitäit piima, ja naudi seda toredat mängu.'),
('784cb32f-466a-4d9b-9df3-23fb3c0de764'::uuid,'Музыкалык гипноз 🎶','Кечки «сыйкырдуу саат» келди, ал өзү менен кошо себепсиз каприздерди жана ыйлоолорду ала келди. Телевизорду өчүрүп, жарыкты басаңдатып, бөлмөгө жай классикалык музыка коюңуз. Музыканын терең жыштыктары атмосфераны сыйкырдуу түрдө өзгөртүп, тынчтык жана бейпилдик тартуулайт.','Meloodiline hüpnoos 🎶','Kätte on jõudnud õhtune „nõiatund“, mis toob kaasa põhjuseta jonni ja nutuhood. Lülita teler välja, hämarda tuled ja pane mängima vaikne klassikaline muusika. Muusika sügavad sagedused muudavad atmosfääri võluväel, tuues tuppa rahu ja vaikuse.'),
('791a6f93-24a4-4445-acfb-0bee156d7b20'::uuid,'Менин бөлүшпөй турган эртең мененки тамагым 🍳','Өз табагындагысын бөлүшпөйт, бирок сиздин табагыңыздагы жумуртканы жегиси келет. Балдар ата-энесинин тандоосуна ар дайым толук ишенишет. Буга каршы чыкпаңыз; сүйүү менен бир тиштем бөлүшүп, жылмайып коюңуз.','Minu hommikusöök, mida ma ei jaga 🍳','Nad ei taha jagada midagi oma taldrikult, kuid nõuavad tungivalt muna sinu omalt. Lapsed usaldavad alati täielikult oma vanemate valikuid. Ära võitle selle vastu; jaga armastusega oma suutäit ja naerata.'),
('840bd918-95f6-4c59-bcb3-4b0f4eaea73b'::uuid,'Баары менен сүйлөшүү 🗣️','Парктагы таш же үйдөгү отургуч менен олуттуу сүйлөшүп, атүгүл аларды урушуп жатышат! Символикалык оюн аркылуу балаңыз айлана-чөйрөнү активдүү таанып жатат. Бул өзгөчө учурларды «Өнүгүү күндөлүгүнө» белгилеп коюңуз — бул жогорку чыгармачылыктын белгиси!','Kõigega rääkimine 🗣️','Nad peavad pargis kiviga või kodus tooliga täiesti tõsist vestlust, lausa riidlevad nendega! Sümboolse mängu kaudu töötleb su laps aktiivselt ümbritsevat maailma. Märgi need erilised hetked kindlasti „Arengupäevikusse“ – see on märk suurest loovusest!'),
('11214951-0661-40fc-a2c7-d7aedff5cf90'::uuid,'Маанай күндөлүгүмдөн сырлар 📝','Телефонуңузду алыңыз. Социалдык тармактардагы башкалардын «идеалдуу жашоосун» чексиз карагандын ордуна, «Маанай күндөлүгүңүздү» ачыңыз. Бүгүн алар жараткан эң күлкүлүү, эң таасирдүү учурду жазып алыңыз — бул эскерүүнү өмүр бою сактайсыз. Аны кагазга түшүрүү — эң таза терапия.','Pihtimused minu tujupäevikust 📝','Võta telefon kätte. Selle asemel, et lõputult sotsiaalmeedias teiste „täiuslikke elusid“ kerida, ava oma „Tujupäevik“. Pane kirja kõige naljakam ja südamlikum hetk, mille nad täna lõid – see on mälestus, mida hoiad igavesti. Selle kirjapanek on puhtaim teraapia.'),
('1219c5e2-02af-4f74-a734-ea08c3018209'::uuid,'Ырдоого болбойт! 🛑','Фондо ойноп жаткан балдар ырына кошулуп ырдасаңыз, алар дароо: «Ырдаба!» деп кыйкырышты. Бөлмөдөгү жалгыз солист — алар; сиздин вокалдык аракеттериңиз алардын сахнасын кичирейтип жатат. Буга таарынбаңыз; сахнаны бул сүйкүмдүү кичинекей эгоистке калтырыңыз.','Laulmine keelatud! 🛑','Sa ümisesid taustal mängiva lastelaulu kaasa ja nad karjusid kohe: „Ära laula!“ Nad on toa ainus solist; sinu vokaalsed katsed kahandavad nende lava. Ära võta seda isiklikult; jäta lava sellele armsale väikesele egoistile.'),
('9dfdb936-66eb-43a1-b7d1-6fccd5198f88'::uuid,'Сыйкырдуу жомоктогу мен 🪄','Бүгүн кечинде «Акылдуу жомок» айтып жатканда, башкы каарманга балаңыздын атын коюңуз. Каарман уктаар алдында бөлмөсүн кантип жыйнаганын баяндап берүү менен, сиз урушпай же кыйкырбай эле, эрежелерди жана жакшы адаттарды акырындык менен сиңире аласыз.','Mina võluloo kangelasena 🪄','Pane täna õhtul „Nutikas loos“ peategelasele oma lapse nimi. Jutustades, kuidas tegelane enne rahulikku uinumist oma toa koristab, saad kaudselt ja õrnalt reegleid ning häid harjumusi juurutada, selle asemel et näägutada või karjuda.'),
('28d0f55b-6b15-4788-8b02-4740d679f342'::uuid,'Тартип бузулуп жатабы? ⏱️','Уктаар убакыт өтө эле созулуп жатабы? Уйку графигиңизди карап чыгыңыз. Балким, күндүзгү уйкуну толугу менен алып салып, кечки уйкуну эртелетүүгө убакыт келгендир.','Kas rutiin hakkab käest libisema? ⏱️','Kas magamaminek venib liiga pikaks? Vaata üle oma uneaja graafik. Võib-olla on ideaalne aeg päevane uinak täielikult ära jätta ja magamamineku aega varasemaks nihutada.'),
('2c32efa0-ce45-4ee9-9fb5-78b505fc81dc'::uuid,'Менин кичинекей мультфильм сынчым 📺','Алар өздөрүнүн уникалдуу грамматикасы менен көргөн мультфильми жөнүндө айтып, ким кайда барганын кызыгуу менен түшүндүрүп жатышат. Абдан таң калгандай болуп, кунт коюп угуңуз. Алардын фантазиясынын канат жайышына жол бериңиз жана өздөрүн дүйнөдөгү эң акылдуу адамдай сезишине шарт түзүңүз.','Minu väike multifilmikriitik 📺','Nad räägivad sulle multikast, mida vaatasid, kasutades oma ainulaadset grammatikat ja selgitades tõsimeeli, kes kuhu läks. Kuula tähelepanelikult, justkui oleksid vaimustuses. Lase nende kujutlusvõimel lennata ja lase neil tunda end maailma kõige targema inimesena.'),
('bc152191-c6d9-4a5e-b03a-d59aaa89994d'::uuid,'Коомчулуктун тынч колдоосу 💬','Сиз абдан чарчадыңыз жана эч нерсени түшүндүрүүгө же кимдир бирөө менен бөлүшүүгө күчүңүз жок. Жөн гана «Anacan коомчулугуна» кирип, унчукпай окуңуз. Башка энелердин да ушундай эле кыйынчылыктарды кантип жеңип жатканын көрүү — көп учурда эң күчтүү, үнсүз колдоо болуп саналат.','Kogukonna vaikne toetus 💬','Oled täiesti kurnatud ja sul pole energiat midagi selgitada ega kellelegi kurta. Liitu lihtsalt „Anacani kogukonnaga“ ja ole vaikne lugeja. Nägemine, kuidas teised emad samade absurdsete kriisidega toime tulevad, on sageli kõige võimsam, sõnatu lohutus.'),
('487012f7-5a3f-49e2-9f9d-2533c14f18c9'::uuid,'Уктоо убактысындагы чоң качуу 🏃‍♂️','Суу ичем, оюнчугумду тап... Үч жашар баланын уктаар алдындагы шылтоолору чексиз. Уйку таймерин иштетиңиз, чек араларды бекем сактаңыз жана бөлмөнү «Ак ызы-чуу» (White Noise) менен тынчтандырыңыз.','Suur põgenemine uneajal 🏃‍♂️','Palun vett, leia mu mänguasi... Kolmeaastase vabandused magamamineku ajal on lõputud. Aktiveeri unetaimer, hoia kindlalt piire ja rahusta tuba valge müra abil.'),
('543ac832-5997-4074-94fa-e27c0915dc20'::uuid,'Менин кичинекей жомокчум 🗣️','Алар ойдон чыгарылган окуяларды жана фантастикалык сценарийлерди түзүү үчүн сөздөрдү бириктирип жатышабы? Бул укмуштуудай тилдик жарылууну өткөрүп жибербеңиз; дароо үн жазуу катары сактап, аны «Баланын альбомуна» түбөлүккө калтырыңыз.','Minu väike jutuvestja 🗣️','Kas nad kombineerivad juba sõnu, et mõelda välja kujuteldavaid lugusid ja fantastilisi stsenaariume? Ära maga maha seda suurepärast keelelist plahvatust; salvesta see kohe häälsõnumina ja jäädvusta nende beebialbumisse.'),
('75d14b5e-1909-445c-9146-d6cc02f1b594'::uuid,'Сиздин кальций калканыңыз 🦴','Кальций өсүп жаткан сөөктөр үчүн абдан маанилүү. Сүт ичпейби? Бүгүн алар жеген сыр, йогурт же брокколинин өлчөмүн эсепке алуу үчүн «Тамактанууну көзөмөлдөө» куралын колдонуңуз.','Sinu kaltsiumikilp 🦴','Kaltsium on kasvuspurtide ajal kiiresti kasvavatele luudele hädavajalik. Kas nad ei joo piima? Kasuta „Toitumise jälgimise tööriista“, et veenduda, kas oled täna arvestanud nende juustu-, jogurti- või brokolikogusega.'),
('5be6af82-89c1-4468-a900-9f899a3717f7'::uuid,'''Меники!'' фазасы 🧸','Оюнчугун башка эч кимге бергиси келбей жатабы? Бул өзүмчүлдүк эмес, кадимки өнүгүү баскычы. «Бөлүшүүгө» мажбурлоонун ордуна, «кезеги менен ойноо» түшүнүгүн үйрөтүү боюнча биздин блогдорду окуп, аны иш жүзүндө колдонуп көрүңүз.','„Minu oma!“ faas 🧸','Ei luba kellelgi teisel oma mänguasjaga mängida? See ei ole isekus, vaid normaalne arenguetapp. Selle asemel, et sundida neid „jagama“, loe meie blogipostitusi „kordamööda tegutsemise“ õpetamisest ja rakenda seda praktikas.'),
('6c5b3273-7cbb-4026-9d69-cd0596d59019'::uuid,'Эртең мененки козголоң 🛑','Кечээ жакшы көргөн тамагын бүгүн жегиси келбей жатабы? Бул тандалмалык эмес, жөн гана көзөмөлдү өз колуна алуу аракети. Мындай учурларда сабырдуу болуу үчүн Anacan AI''дан кеңеш сураңыз, терең дем алыңыз жана эч качан дасторкон үстүндө «согуш» ачпаңыз.','Hommikune mäss 🛑','Toit, mida nad eile armastasid, lükatakse täna vastikustundega tagasi? See ei ole pirtsakus; see on lihtsalt katse kontrolli haarata. Kui selliste hetkedega silmitsi seisad, küsi Anacan AI-lt nõu, kuidas rahulikuks jääda, hinga sügavalt sisse ja ära kunagi alusta söögilauas sõda.'),
('4b47f634-fca5-4f0e-a391-d61c2ad9b71e'::uuid,'Апамдын кофе ичүү тыныгуусу ☕','Балаңыз менен тынымсыз сүйлөшүү жана чексиз суроолорго жооп берүү чарчатышы мүмкүн. «Ата-энелер үчүн ыңгайлуу жайлар» тизмесинен балдарга ылайыктуу кафе таап, ысык кофеңизди ичип, башка энелер менен баарлашыңыз. Бул дем алуунун жана байланышуунун эң сонун жолу.','Ema kohvipaus ☕','Lapsega pidev rääkimine ja lõpututele küsimustele vastamine võib olla kurnav. Leia „Lapsesõbralike kohtade“ hulgast kohvik, rüüpa kuuma kohvi ja vestle teiste emadega. See on suurepärane viis hinge tõmmata ja suhelda.'),
('4e86cfa1-9302-4174-a4b5-457a860c75dd'::uuid,'Жомок окуу кезеги атада 📚','Бүгүн кечинде уктатуу милдети толугу менен атасында. Ал жомок окуп жатканда, сиз эшиктин артындагы толук тынчтыктан ырахат алыңыз.','Issi kord muinasjuttu lugeda 📚','Täna õhtul on magamamineku rutiin täielikult issi vastutusel. Lase temal lugu lugeda, samal ajal kui sina naudid ukse taga täielikku vaikust.'),
('ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7'::uuid,'Өзүм эле жасайм! 🛑','Баарына кийлигишип, кийинип жаткан процессти үч эсе узартып жатышабы? Башаламандыкка көңүл бурбаңыз; алардын өсүп жаткан өзүнө болгон ишенимин көрүңүз. Сабырыңыз түгөнгөндө, бул учурларды оюн аркылуу чечүү боюнча биздин блогдорду окуп, терең дем алыңыз.','Teen ise! 🛑','Kas nad segavad kõike ja pikendavad riietumisprotsessi kolmekordselt? Ära keskendu segadusele; märka nende kasvavat enesekindlust. Kui kannatus katkeb, loe meie blogist ideid, kuidas neid hetki mängu kaudu lahendada, ja hinga sügavalt sisse.'),
('086dfc4e-9fb2-412e-ade9-cb121424e290'::uuid,'Жылуу чай жана тынчтык 🍵','Таймер токтоду, балаңыз уктады. Үй жумуштарын унутуңуз; алардын баары күтө турат. Биздин пайдалуу рецепттерден даамдуу суусундук даярдап, өзүңүз үчүн бөлүнгөн бул баалуу убакыттан ырахат алыңыз.','Soe tee ja vaikus 🍵','Taimer peatus, su laps magab. Unusta majapidamistööd; need võivad oodata. Valmista meie tervislike retseptide järgi maitsev jook ja naudi seda väärtuslikku aega iseendale.'),
('577db9f8-8f80-4ad0-9e5c-4fd106adca75'::uuid,'Эртең мененки жашынмак 🙈','Жумушка же бала бакчага кечигип жатасыз, ал болсо көшөгөнүн артына жашынып алып: «Мени тап!» деп кыйкырып жатат. Нервиңиз чыңалып турса да, кыйкыруу процессти гана узартат. Анын ордуна: «Ой, менин сулуу балам кайда экен?» деп эки мүнөт оюнга кошулуп, аны «таап» алыңыз.','Hommikune peitusemäng 🙈','Oled tööle või lasteaeda hilinemas ja nad peidavad end kardina taha, karjudes: „Leia mind!“ Isegi kui su närvid on pingul, pikendab karjumine protsessi vaid veelgi. Selle asemel liitu mänguga kaheks minutiks, öeldes: „Oh, huvitav, kus mu ilus laps on?“ ja „leia“ nad üles.'),
('61996b98-7da4-41e9-be9f-afe630090cfe'::uuid,'Түсүнө карап тамактануу 🍅','Табагындагы тамакты түсүнө жана формасына карап кылдаттык менен сорттоп, жашыл бөлүктөрүн четке түртүп жатышабы? «Тамактануу планына» өтүңүз. Жашылчаларды кантип көрүнбөгөн пюреге айлантып, даамдуу соустарга кошуп, бул тамактануу оюнун жашыруун түрдө кантип утуп алууну билип алыңыз!','Värvide järgi söömine 🍅','Nad sorteerivad oma taldrikul toitu hoolikalt värvi ja kuju järgi, lükates kõik rohelised tükid kõrvale. Suundu „Toitumiskava“ juurde. Avasta, kuidas muuta need köögiviljad nähtamatuteks püreedeks ja peita need maitsvatesse kastmetesse, võites salaja selle söögiaja mängu!'),
('01916001-64ad-41ab-8fea-1c1101a3ae1c'::uuid,'Тынчтыкка болгон муктаждык 🤫','Алар акыры укташты! Үйдө орногон тынчтыкка ишене албай турасыз. Үн өлчөгүчүңүздү иштетип, 0-10 децибелдик көрсөткүчтү караңыз. Бул тынчтыктын визуалдык көрүнүшү жан дүйнөңүзгө массаж жасагандай болуп, акылыңыздын акырындап эс алып жатканын сезиңиз.','Vajadus vaikuse järele 🤫','Nad magavad lõpuks! Sa ei suuda uskuda seda vaikust, mis on majja laskunud. Aktiveeri helimõõtja ja jälgi seda rahulikku 0–10 detsibelli näitu. Tunneta, kuidas su meel aeglaselt lõdvestub, justkui oleks see vaikuse visuaalne esitus su hingele õrn massaaž.'),
('95ce868b-b982-4c4e-baa7-7ca7cd3520b4'::uuid,'Чөнтөктөгү кенчтер! 🪨','Шымын жууп жатып, чөнтөгүнөн эки таш, куураган жалбырак жана бир бутактын сыныгы түшүп калдыбы? Сизге таштандыдай көрүнгөн нерсе — алардын дүйнөнү таанып-билүү учурунда чогулткан баалуу коллекциясы. Аларды ыргытпай, кичинекей «казына кутучасына» сактап коюңуз.','Taskuaarded! 🪨','Pesed nende pükse ja taskust kukub välja kaks kivi, kuivanud leht ja pool oksaraagu? See, mis sulle prügina tundub, on nende väärtuslik kollektsioon, mis on kogutud maailma avastades. Selle asemel, et see ära visata, pane need väikesesse „aardelaekasse“.'),
('97aa3207-a7a2-42a1-9e74-01d2388db3b1'::uuid,'Эшикти кулпулоо миссиясы 🚪','Алар бөлмөнүн эшиктерин жаап, сизди сыртта калтыруудан өзгөчө ырахат алышат. Алардын жеке мейкиндик жөнүндөгү түшүнүгү өзгөрүп жатат! Манжалары кысылып калбашы үчүн сактык чараларын көрүңүз, бирок алардын өз аймагын жарыялоо оюнуна олуттуу кийлигишпеңиз.','Ukse lukustamise missioon 🚪','Nad tunnevad erilist rõõmu kõigi tubade uste sulgemisest enda järel, jättes sind välja. Nende arusaam isiklikust ruumist on tegemas revolutsiooni! Võta tarvitusele ettevaatusabinõud, et vältida sõrmede vahelejäämist, kuid ära nende oma territooriumi kuulutamise mängu tõsiselt sekku.'),
('a910e33f-005d-4ed1-a228-647503e47993'::uuid,'Жымжырттыктын бейпилдиги 🤫','Алар акыры укташты! Үйдө орногон тынчтыкка ишене албай турасыз. Үн өлчөгүчүңүздү иштетип, 0-10 децибелдик көрсөткүчтү караңыз. Бул тынчтыктын визуалдык көрүнүшү жан дүйнөңүзгө массаж жасагандай болуп, акылыңыздын акырындап эс алып жатканын сезиңиз.','Vaikuse rahu 🤫','Nad magavad lõpuks! Sa ei suuda uskuda seda vaikust, mis on majja laskunud. Aktiveeri helimõõtja ja jälgi seda rahulikku 0–10 detsibelli näitu. Tunneta, kuidas su meel aeglaselt lõdvestub, justkui oleks see vaikuse visuaalne esitus su hingele õrn massaaž.'),
('2f583ff5-e2c4-4fbb-acdc-470ccf241970'::uuid,'Даарат кагазынан жасалган искусство 🧻','Бир нече мүнөттүк тынчтык... Бөлмөгө кирсеңиз, даараткана кагазы бүт үйгө жайылып жатат! Ачуулангандын ордуна, кагазды чогултуп, чогуу кар киши же топ жасаңыз. Башаламандыкты кыйкырык менен эмес, чыгармачылык менен жеңиңиз.','Tualettpaberi kunst 🧻','Mõni minut vaikust... Ja kui tuppa astud, leiad kogu tualettpaberi lahti rullituna ja üle kogu maja laiali! Selle asemel, et vihastada, korja paber kokku ja tehke koos lumememm või pall. Võida kaos mitte karjumise, vaid loovusega.'),
('6ae9e7b9-b61e-4945-82bd-3ceb19652949'::uuid,'Кир жуугуч машинадагы табылга 🧺','Кир жуугуч машинанын алдында отуруп, айланып жаткан кийимдерди сүйүктүү мультфильмин көргөндөй таң калуу менен карап жатышат. Бул — таптакыр бекер, психиканы тынчтандыруучу көңүл ачуу. Аларды токтотпоңуз! Бул баалуу мүмкүнчүлүктү пайдаланып, өзүңүз да эс алып алыңыз — башаламандык бир азга токтоду.','Pesumasina avastus 🧺','Nad istuvad pesumasina ees, olles lummatud pöörlevatest riietest, justkui oleks see nende lemmikmultikas. See on täiesti tasuta ja vaimselt rahustav meelelahutus. Ära sega neid! Kasuta seda väärtuslikku võimalust ise puhata – kaos on hetkeks peatunud.'),
('c8193b18-f83a-473a-bda3-5d573d734271'::uuid,'Сүйүүнүн шыбыр сөздөрү 💖','Күн бою сиздин сабырыңызды сынап, айтканыңыздын баарына каршы чыгышкандыр. Бирок азыр, алардын төшөктө бейкүнөө уктап жатканын көрүп... Жанына жатып, аларды канчалык жакшы көрөрүңүздү жана бүгүн жасаган бардык сонун иштерин шыбырап айтыңыз. Балдар энесинин мээримдүү үнүн уйкусунда да сезишет.','Sosistatud armusõnad 💖','Nad võisid terve päeva su kannatust proovile panna, kõigele vastu vaieldes. Aga nüüd, nähes neid nii süütult voodis magamas... Heida nende kõrvale ja sosista, kui väga sa neid armastad ja kui palju imelisi asju nad täna tegid. Lapsed tunnevad ema armastavat häält isegi unes.'),
('8f4abc30-5451-459c-a1af-55ec249af8b0'::uuid,'Сиз мени укпай жатасыз! 😠','Телефонуңузду карап же тамак аралаштырып жатканда, алар келип: «Мага карачы!» деп жүзүңүздү өздөрүнө бурушат. Алар туура айтышат. Аларга сиздин физикалык жактан жаныңызда болушуңуз эмес, толук көңүл бурууңуз керек. Жасап жаткан ишиңизди токтотуп, 3 мүнөт бою көз карашыңызды алардан албай угуңуз.','Sa ei kuula mind! 😠','Kui vaatad telefoni või segad toitu, tulevad nad ja pööravad su näo enda poole, öeldes: „Vaata mind!“ Neil on õigus. Nad ei taha su füüsilist kohalolu, vaid su jagamatut tähelepanu. Jäta pooleli see, mida teed, ja kuula neid 3 minutit täieliku silmside abil.'),
('9069176c-b719-421b-bb4f-85cd101945a6'::uuid,'Жомок айтып жатканда качып кетүү аракеттери 🏃‍♂️','Жомок окуп жатканда, оюнчук алышым керек деп төшөктөн секирип кете беришет. Алар жөн гана уйкуга моюн сунгулары келбейт. Күтүлбөгөн жерден үнүңүздү өтө акырын шыбырга чейин басаңдатыңыз. Сизди угуу үчүн алар төшөккө кайтып келип, кунт коюп угууга аргасыз болушат.','Põgenemiskatsed unejutust 🏃‍♂️','Lugu lugedes hüppavad nad pidevalt voodist välja, väites, et peavad mänguasja tooma. Nad lihtsalt ei taha unele alla vanduda. Proovi järsku oma hääl väga vaikseks sosinaks muuta. Et sind kuulda, peavad nad voodisse tagasi ronima ja tähelepanelikult kuulama.'),
('e4d134d2-7f4f-4894-b6f3-6051d4c2f528'::uuid,'Ар кандай аба ырайына ылайык кийинүү ⛅','Жаз жакындаган сайын аба ырайы кубулмалуу болуп калат — эртең менен суук, түштөн кийин жылуу. «Аба ырайы жана кийим куралы» Сизге катмарлап кийинүүнү же «пияз ыкмасын» эскертет. Паркта алар жылына баштаганда, тердеп ыңгайсыз болбошу үчүн жана Сиздин тынчсызданууңузду алдын алуу үчүн бир катмарын чечип коюңуз!','Kihiline riietus iga ilmaga ⛅','Kevade lähenedes võib ilm olla väga heitlik – hommikul külm, pärastlõunal soe. „Ilma ja riietuse tööriist“ tuletab meelde, et riietuksid kihiliselt ehk kasutaksid „sibulameetodit“. Kui nad pargis soojaks lähevad, võta üks kiht vähemaks, et vältida nii higistamisest tingitud ebamugavust kui ka enda stressi!'),
('918e0a4a-7932-41e0-b1cb-29b726120c0e'::uuid,'Жасалма интеллект жана күтүлбөгөн өжөрлүк 🤖','Балаңыз кечээ тынч эле, бирок бүгүн баарына агрессивдүү мамиле кылып жатабы? Интернеттен коркунучтуу себептерди издебеңиз. Anacan AI''дан бул «менталдык секириктин» психологиялык себептери жөнүндө сураңыз жана педиатр тарабынан тастыкталган жооп менен тынчсызданууңузду басыңыз.','AI ja äkiline kangekaelsus 🤖','Kas su laps oli eile rahulik, aga täna reageerib kõigele agressiivselt? Ära otsi internetist hirmutavaid põhjuseid. Küsi Anacan AI-lt selle „vaimse hüppe“ psühholoogiliste põhjuste kohta ja leevenda oma muresid pediaatri heakskiidetud vastusega.'),
('b03065aa-7764-4054-8d16-b42a880815cc'::uuid,'Мурунуңду жулуп алдым! 👃','Сиз «мурдуңду кармап алдым!» деп бармагыңызды көрсөтсөңүз, алар буга чын эле ишенип, ыйлай башташат! 3,5 жашта фантазия кээде чындык менен элестин ортосундагы чекти бүдөмүктөтүп коёт. Тезинен «Аха, ордуна койдум!» деп, мурдунан өөп коюңуз, бул кичинекей кайгылуу көз ирмемди жылмаюуга айлантыңыз.','Sain su nina kätte! 👃','Ütled „Sain su nina kätte!“ ja näitad pöialt, ning laps usub seda siiralt ja hakkab nutma! 3,5-aastaselt hägustub kujutlusvõimes piir reaalsuse ja illusiooni vahel. Ütle kohe: „Ahah, panin selle tagasi!“ ja suudle tema nina, muutes selle väikese ärevushetke naeratuseks.'),
('f9660fac-3163-450f-a18c-f1ac86faf296'::uuid,'Жубайыңыз менен тынч отуруп тиктешүү 🥂','Ваш балаңыз акыры уктады. Сиз жана өмүрлүк жолдошуңуз диванда сүйлөшүүгө да алыңыз жок, катарлашып отурасыз. Сиздер жөн гана бири-бириңиздерди унчукпай карап, жылмаясыздар. Бул сөзсүз түшүнүшүү — «Биз бул башаламандыкты эң сонун жеңип жатабыз» дегенди билдирген эң сонун көз ирмем.','Vaikne pilk kaaslasega 🥂','Su laps on lõpuks uinunud. Istute partneriga diivanil kõrvuti, olles liiga väsinud, et isegi rääkida. Vaatate lihtsalt vaikuses teineteisele otsa ja naeratate. See sõnatu hetk on kõige ilusam viis tõdeda: „Me saame selle kaosega suurepäraselt hakkama.“'),
('48be6a74-039a-47b4-b2e6-38a02b369aa1'::uuid,'Бул меники! - Менчикчил бөбөк 🔑','Балаңыз полдон сыналгынын пультун же атасынын ачкычын алып: «Мен муну таптым, бул меники!» дейт. Алар үчүн табуу — ээлик кылуу дегенди билдирет. Күч менен тартып албаңыз. Анын ордуна: «Мага таап бергениң үчүн рахмат!» деп айтыңыз жана аны кайтарып алуу үчүн көңүлүн башка оюнчукка акырын буруңуз.','See on minu oma! – Omandihimuline väikelaps 🔑','Su laps võtab põrandalt telekapuldi või issi võtmed ja teatab: „Leidsin selle, see on minu oma!“ Tema jaoks tähendab leidmine omamist. Ära võta seda jõuga. Ütle hoopis: „Aitäh, et selle minu jaoks üles leidsid!“ ja suuna tema tähelepanu õrnalt teisele mänguasjale, et ese tagasi saada.'),
('53233246-1c9c-44d8-aa89-08a12ab1932c'::uuid,'Ашкана концерти 🥄','Алар казан-аяктарды, жыгач кашыктарды алып чыгып, ашкананын ортосунда концерт берип жатышат. Бул Сиздин башыңызды оорутса да, алардын ритм сезимин жана чыгармачылыгын өстүрөт. Кийлигишүүгө шашпаңыз; ошол жалындуу энергия бир нече мүнөткө бөлмөнү үн толкундарына толтурсун.','Köögikontsert 🥄','Nad on välja otsinud potid ja puulusikad ning annavad keset kööki kontserti. Isegi kui see tekitab peavalu, arendab see nende rütmitaju ja loovust. Ära kiirusta sekkuma; luba sellel metsikul energial mõne minuti jooksul tuba helilainetega täita.'),
('54609407-cfb4-47a1-8f37-28a152cd5950'::uuid,'Ваннадагы кичинекей спа 🛀','Бүгүн кечинде балаңызды эле эмес, өзүңүздү да эркелетиңиз. Ал уктагандан кийин, жылуу ванна даярдап, көбүк кошуп, бир шам жагыңыз. Эшикти бекитип, болгону 15 мүнөткө «апа» ролунан чыгып, өзүңүзгө убакыт бөлүңүз. Сиз буга татыктуусуз.','Minispaa vannitoas 🛀','Täna õhtul ära vannita ainult last; hellita ka ennast. Pärast seda, kui ta on uinunud, lase vanni soe vesi, lisa vahtu ja süüta üks küünal. Lukusta uks ja astu vaid 15 minutiks oma „ema“ rollist välja, et võtta hetk iseendale. Sa väärid seda igati.'),
('370a629d-a585-41ae-ad7c-85bbfe349f3d'::uuid,'Маанай күндөлүгүнөн бир сыр','Телефонуңузду колуңузга алыңыз. Социалдык тармактарда башкалардын жашоосун карап отурбастан, «Маанай күндөлүгүн» ачып, келечекте эстеп жүрүү үчүн балаңыздын бүгүнкү эң кызыктуу көз ирмемин жазып коюңуз. Бул «санариптик терапия» Сизди да эс алдырат; экранды карап отуруп, тынчсызданууларыңыздын тараганын байкаңыз.','Ülestunnistus meeleolupäevikust','Võta telefon kätte. Selle asemel, et sotsiaalmeedias teiste inimeste elusid kerida, ava oma „Meeleolupäevik“ ja pane tuleviku tarbeks kirja kõige naljakam hetk, mille su laps täna tekitas. See „digitaalne teraapia“ lõõgastab ka sind; vaata, kuidas mured kaovad, kui ekraani silmitsed.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('8353b398-30f5-4594-98bd-74c894cfb243'::uuid,'Ырымды кайтарып бер! 🎶','Алар радиодон жаңы эле жаңырган ырды кайра уккусу келип жатат. Сиз бул түз эфир экенин жана ал бүткөнүн түшүндүрөсүз, бирок алар «Кайра кой!» деп ыйлашат. Баланын мээси түз эфирдин логикасын түшүнбөйт. Алардын көңүлүн алаксытуу үчүн, ырды өзүңүз башкача, кызыктуу үн менен ырдап баштаңыз.','Too mu laul tagasi! 🎶','Nad tahavad uuesti kuulda laulu, mis just raadiost kõlas. Selgitad, et see oli otseülekanne ja see on läbi, aga laps nutab: „Pane uuesti!“ Lapse aju ei hooma otseülekande loogikat. Tähelepanu hajutamiseks hakka ise seda laulu teise, naljaka häälega laulma.'),
('f3893094-7182-4330-982a-7ccd3eced333'::uuid,'Тынчтыкта ичилген чай ☕','Алар бөлмөнүн ортосунда оюнчуктарын тизип, жалгыз тынч ойноп жатышат. Сураныч, бул баалуу көз ирмемди үй жыйноо менен коротпоңуз! Диванга жайгашып, ысык кофе же чай ичиңиз жана болгону 10 мүнөткө эч нерсе ойлобостон, бул сейрек кездешүүчү жымжырттыктан ырахат алыңыз.','Tee vaikses üksinduses ☕','Nad mängivad keset tuba vaikselt omaette, rivistades mänguasju üles. Palun ära raiska seda väärtuslikku hetke koristamisele! Sea end diivanil sisse, rüüpa kuuma kohvi või teed ja naudi lihtsalt 10 minutit seda haruldast vaikust ilma ühegi mõtteta.'),
('52d5f808-8d3e-4769-9814-0abc72834d43'::uuid,'Уйку таймеринин стратегиясы ⏱️','Уктоо маалы жакындаганда, алар капысынан суусап, дааратканага баргысы келип же бөлмөдөгү ар бир буюм менен коштошууну чечишеби? Таймер коюңуз. Бул чексиз коштошуулардан жана чеберчилик менен убакытты созуудан талашсыз кутулуу үчүн «коңгуроо кагылганда баары төшөккө» деген катуу эрежени киргизиңиз.','Unetaimeri strateegia ⏱️','Kas uneaja lähenedes tekib lapsel äkki janu, vajadus tualetti minna või otsustab ta kõigile toas olevatele esemetele head ööd soovida? Pane taimer. Kehtesta kindel reegel „kui kell heliseb, lähevad kõik magama“, et pääseda nendest lõpututest hüvastijätmistest ja meisterlikest viivitamistaktikatest ilma vaidlusteta.'),
('7cbac7ca-9f74-4319-bb84-ce56d77a4832'::uuid,'Anacan коомчулугунун күчү 💬','«Эмне үчүн менин балам мынчалык өжөр?» деген ой Сизди кыйнап жатабы? Anacan Коомчулугуна кошулуңуз. Башка энелердин үйлөрүндө да ушундай эле түшүнүксүз ачуулануулар болуп жатканын окуганда, Сиз жалгыз эмес экениңизди жана туура жолдо баратканыңызды түшүнөсүз.','Anacani kogukonna vägi 💬','Kas mõte „Miks mu laps nii kangekaelne on?“ vaevab su meeli? Liitu Anacan Communityga. Kui loed sarnastest absurdsetest jonnihoogudest teiste emade kodudes, mõistad, et sa pole üksi ja oled täiesti õigel teel.'),
('c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b'::uuid,'Дубалдар — менин сүрөт тартуучу кагазым! 🖍️','Ошол коркунучтуу жымжырттык... Кирсеңиз, дубалга маркер менен тартылган «шедеврди» көрөсүз. Терең дем алыңыз. Алардын майда моторикасы өнүгүп жатат, ал эми дубалдарды дайыма тазалап алса болот. Келечекте күлүп эстеш үчүн бул шедеврди сөзсүз сүрөткө тартып алыңыз.','Seinad on minu lõuend! 🖍️','See kardetud vaikus… astud tuppa ja avastad seinale markeriga joonistatud meistriteose. Hinga sügavalt sisse. Nende peenmotoorika areneb ja seinu saab alati puhastada. Tee sellest meistriteosest kindlasti tuleviku naerupahvakute jaoks foto.'),
('017dd4ef-6a6d-470c-a536-c9d8157780f2'::uuid,'Караңгылыкка чакыруу 🌙','Уктоочу бөлмөдө жарык өчкөндө алар тынчсызданабы? Бөлмөнүн бир бурчуна кичинекей, жылуу түстөгү (кызгылт сары же кызыл) түнкү чырак коюңуз. Мелатониндин иштелип чыгышын камсыз кылуу жана терең, калыбына келтирүүчү уйку үчүн бөлмөнүн калган бөлүгү толугу менен караңгы болушу керек.','Kutse pimedusse 🌙','Kas laps muutub ärevaks, kui magamistoas tuled kustutatakse? Pane toa ühte nurka väike soojatooniline (oranž või punane) öölamp. Ülejäänud ruum peaks jääma täiesti pimedaks, et toetada melatoniini tootmist ja tagada sügav, taastav uni.'),
('0cf9c44c-98af-4034-b557-39b1dbb9f133'::uuid,'Кичинекей чач тарачтын биринчи аракети ✂️','Бөлмөгө кирсеңиз, алар куурчагынын чачын кайчы менен кыркууга аракет кылып жатышат. Ар бир ата-эненин коркунучтуу түшү, туурабы? Ачууланбастан, кайчыны акырын алып, бул «чач тарачтын» алгачкы аракетин келечектеги балалык сүрөт альбому үчүн кызыктуу эскерүү катары сактап коюңуз.','Väikese juuksuri esimene katse ✂️','Astud tuppa ja avastad, et nad üritavad kääridega nukule soengut teha. Iga lapsevanema õudusunenägu, eks? Ilma pahandamata võta õrnalt käärid ja salvesta see juuksuritöö esimene katse naljaka mälestusena tuleviku beebialbumisse.'),
('86c98bc5-4f00-463f-9722-124e19e389a1'::uuid,'Табият койнуна өтө зарыл болгон качуу ⛅','Үйдө камалып, алардын энергиясы агрессияга айланып, ар бир сүйлөмү «жок» менен башталып жатабы? Аба ырайына же эмне кийип жүргөнүнө карабай, аларды тиешелүү түрдө кийинтип, сыртка алып чыгыңыз. Жерге тийүү алардын нерв системасын заматта калыбына келтирет.','Väga vajalik põgenemine loodusesse ⛅','Siseruumidesse lõksu jäänuna muutub nende energia agressiivsuseks ja iga lause algab sõnaga „ei“? Sõltumata ilmast või sellest, mis neil seljas on, riieta nad sobivalt ja mine õue. Maa puudutamine lähtestab nende närvisüsteemi silmapilkselt.'),
('04ffb755-8100-4999-9284-739b81b180be'::uuid,'Меники! Баары меники! - Менчикчилдик мезгили 🧸','Алар үйдөгү туш келди бир буюмду кучактап, «Меники!» деп кыйкырып, бербей жатышат. Алар жөн гана ээлик кылуу жана чек ара түшүнүктөрүн изилдеп жатышат. Аларды өзүмчүл деп атабаңыз; анын ордуна, буюмду кайтарып алуу үчүн көңүлүн башка кызыктуу ишке акырын буруңуз.','Minu oma! Kõik minu oma! – Omandihimuline faas 🧸','Nad kallistavad suvalist majapidamiseset, karjuvad „Minu oma!“ ja keelduvad seda käest andmast. Nad alles avastavad omandi ja piiride mõistet. Ära sildista neid isekaks; suuna nende tähelepanu eseme tagasisaamiseks õrnalt mõnele teisele kaasahaaravale tegevusele.'),
('1f9e9c23-d051-49a3-8538-a3275546e6a3'::uuid,'Бул таштанды эмес, бул искусство! 🎨','Алар бөлмөнүн ортосунда кагаздын калдыктарынан жана кесилген жиптерден чоң «көркөм шедевр» жаратышты жана аны ыргытууга уруксат беришпейт. Тазалыкка болгон муктаждыгыңызды четке коюңуз. Алар жараткан бул башаламандыкты сыйлаңыз; жыйноо эртеңкиге чейин күтө турат.','See pole prügi, see on kunst! 🎨','Nad on loonud keset tuba pisikestest paberitükkidest ja lõigatud nöörijuppidest suure kunstiteose ega luba sul seda ära visata. Jäta oma korraarmastus kõrvale. Austa nende loodud kaost; koristamine võib oodata homseni.'),
('55f7cd1c-adbb-4e6a-bcc0-5847c157d42a'::uuid,'Атанын аркасында пони менен сейилдөө 🐴','Дагы эле күчкө толуп, уктоодон баш тартып жатабы? Атаны жардамга чакырыңыз! Ал баланы «ат» кылып ойноткондо, бөлмө күлкүгө толуп, топтолгон физикалык чыңалуу жана чексиз энергия бир нече мүнөттө тер менен кошо чыгып кетет.','Poni-sõidud issi seljas 🐴','Kas laps on ikka täis energiat ja keeldub magama minemast? Kutsu issi appi! Kui ta teeb lapsele lõbusat ''hobusesõitu'', täitub tuba naeruga ning kogu füüsiline pinge ja piiritu energia hajuvad hetkega koos väikese higiga.'),
('11adcff5-957f-4e30-8ecc-96f09d1482fe'::uuid,'Жомоктор дүйнөсү 🪄','Классикалык жомокторду четке коюңуз. Акылдуу окуяларды ачыңыз. Өзүңүздүн өзгөчө жомогуңузду жаратыңыз.','Muinasjuttude maailm 🪄','Pane klassikalised muinasjutud kõrvale. Ava nutikad lood. Loo omaenda eriline muinasjutt.'),
('4418649d-d556-4a03-af91-b1d0242b6324'::uuid,'Коомчулуктун колдоосу 💬','Сиз аябай чарчадыңыз жана эч нерсени түшүндүргүңүз же эч кимге ишенгиңиз келбейт. Жөн гана Anacan Коомчулугуна кошулуп, унчукпай байкоочу болуңуз. Башка энелердин ушундай эле түшүнүксүз ачууланууларды кантип жеңип жатканын көрүү — эң күчтүү үнсүз сооронуч.','Kogukonna tugi 💬','Oled täiesti kurnatud ega taha midagi selgitada ega kellelegi kurta. Liitu lihtsalt Anacan Communityga ja ole vaikne vaatleja. Nähes, kuidas teised emad samade absurdsete jonnihoogudega toime tulevad, on kõige võimsam vaikne lohutus.'),
('6e6ecb59-b07b-44ae-b10f-31d088fcccf0'::uuid,'Эртең мененки диктатор иште 👑','«Ал жерге отура албайсыз, ал жерде Тедди отурат!» Алар эртең мененки тамактануу үстөлүн толугу менен башкарууга аракет кылып жатышат. Алардын эркине түздөн-түз каршы чыкпастан: «Макул, Тедди ошол жерге отурсун, а мен бул жерге отурам» деп көрүңүз. Ошентип, Сиз бөлмөдө тең салмактуулукту жана тынчтыкты сактайсыз.','Hommikune diktaator on tööl 👑','„Sa ei saa siin istuda, Mõmmi istub siin!“ Nad üritavad kogu hommikusöögilauda valitseda. Selle asemel, et nende tahtele otse vastu astuda, proovi: „Olgu, Mõmmi võib seal istuda ja mina istun siin.“ Nii säilitad toas tasakaalu ja rahu.'),
('1b1ca975-b7c1-4e57-9e31-3f5e83031e0f'::uuid,'Уйку убактысына каршылык 🥱','Алар төшөккө жаткысы келбей, ыйлап жатышабы? Мажбурлабаңыз. Бөлмөдөгү жарыкты өчүрүп, «Тынч окуу убактысын» жарыялаңыз, бул экөөңүздү тең эс алдыра турган жаңы тартипти түзүп, Сизге да, аларга да башкача жол менен эс алууга мүмкүндүк берет.','Uinakumäss 🥱','Nad ei taha magama minna ja nutavad? Ära sunni neid. Hämarusta toas tuled ja kuuluta välja vaikne lugemisaeg, luues uue rutiini, mis lõõgastab teid mõlemaid ja võimaldab nii sul kui ka lapsel teistmoodi maha rahuneda.'),
('8ca291c9-dcd2-4396-9580-b58e8c48c73a'::uuid,'Окуяны өздөрү жазсын 🪄','Экөөңүздөр тең эски китептерден тажап, бөлмөдө зериктирүүчү маанай өкүм сүрүп жатабы? Акылдуу окуяларды ачып, балаңызга бүгүнкү сюжетти башкарууга мүмкүнчүлүк бериңиз. «Ал учкан унаа эми кайда барышы керек?» деп сураңыз жана алардын фантазиясында жаңы дүйнөлөрдү багындырып, уйкуга кетүүсүнө жол бериңиз.','Lase neil lugu kirjutada 🪄','Mõlemad väsinud samadest vanadest raamatutest ja toas valitseb tuim õhkkond? Ava nutikad lood ja lase lapsel tänase õhtu süžeed juhtida. Küsi: „Kuhu see lendav auto nüüd peaks minema?“ ja lase neil uinuda, vallutades oma kujutlusvõimes uusi maailmu.'),
('bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83'::uuid,'Күзгүдөгү атаандаш 🪞','Алар күзгүнүн алдында кабагын түйүп, ар кандай кызыктуу, экспрессивдүү жүздөрдү жасап жатышат. Алар жөн гана ар кандай эмоциялар алардын жүзүндө кандай көрүнөрүн байкап көрүшүүдө. Бул кичинекей актердун жеке репетициясын унчукпай жана ырахат менен байкаңыз.','Rivaal peeglis 🪞','Nad seisavad peegli ees, kortsutavad kulmu ja teevad igasuguseid naljakaid, ilmekaid nägusid. Nad lihtsalt katsetavad, kuidas erinevad emotsioonid nende näol välja näevad. Jälgi vaikselt ja rõõmuga selle väikese näitleja privaatset proovi.'),
('c78f6742-28ba-40d4-8884-94cee25316f0'::uuid,'Дубалга сырларды шыбыроо 🤫','Төшөккө жатып, дубалга карап, кимдир бирөөгө сырларын шыбырап жатышабы? Кандай гана сүйкүмдүү! Жарыкты өчүрүп, жөн гана эс алыңыз, ошол таттуу шыбырлардын акырын уйкуга айланганын угуңуз.','Saladuste sosistamine seinale 🤫','Läksid voodisse, keerasid selja ja nüüd sosistavad kellelegi saladusi? Kui armas! Kustuta tuled ja lihtsalt lõõgasta, kuulates, kuidas need armsad sosinad vaikselt uneks hajuvad.'),
('ca5cea03-5260-4977-bf88-cfe3ed937e38'::uuid,'''Туура эмес чөйчөк'' үчүн күрөш? 🥤','Сууну сары чөйчөккө бергениңиз үчүн эле ызы-чуу түшүп жатабы? Бул тууралуу көп ойлонбоңуз; алар бүгүн эртең менен жөн гана чек араларды сынап жатышат. Сууну тез эле көк чөйчөккө куюп, бөлмөдөгү тынчтыкты калыбына келтириңиз жана энергияңызды күндүн калган бөлүгүнө сактаңыз.','„Vale tassi“ lahing? 🥤','Kas maailm on kokku kukkumas, sest andsid neile vett kollases tassis? Ära mõtle üle; nad lihtsalt katsetavad täna hommikul piire. Vala vesi kiiresti sinisesse tassi, taasta toas rahu ja hoia oma energiat ülejäänud päevaks.'),
('f8e8bb79-94ba-4264-b58d-e4f81f8007f5'::uuid,'Чаң соргуч менен болгон атаандаштык 🌪️','Сиз үй жыйнап жатканда, алар «менин чаңымды шыпырба» деп ыйлап, жолуңузду тосуп жатышабы? Алардын ээлик кылуу сезими акылга сыйбаган деңгээлге жетти. Чаң соргучту өчүрүп, 5 мүнөттүк «кош бол, чаң» аземин өткөрүңүз. Ишенип коюңуз, бул башаламандыкты алда канча тезирээк токтотот.','Tolmuimeja kui vaenlane 🌪️','Kas nad nutavad ja blokeerivad su teed, nõudes koristamise ajal „Ära pühi minu tolmu ära“? Nende omanditunne on jõudnud absurdsele tasemele. Lülita tolmuimeja välja ja korralda 5-minutiline „hüvasti, tolm“ tseremoonia. Usu meid, see lõpetab kaose palju kiiremini.'),
('0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9'::uuid,'Кийимдер дагы аралашып кетти 🧥','Сыртка чыкканы жатасыздар, бирок ал резина өтүк менен кыска жеңдүү көйнөк кием деп туруп алдыбы? Талашпаңыз. Телефонуңуздагы аба ырайы тиркемесин ачып, ага бул кийим ылайыксыз экенин көрсөтүңүз. «Санарип экран» эрежени аткарсын; сиз четке чыгыңыз, ал өзү эле үн катпай башка кийим кийип алат.','Riided on jälle sassis 🧥','Lähete õue, aga laps nõuab kummikuid ja lühikeste varrukatega särki? Ära vaidle. Ava telefonis ilmarakendus ja näita talle, et selline riietus ei sobi. Las ''digitaalne ekraan'' kehtestab reegli; sina astu samm kõrvale ja ta paneb särgi vaikselt selga.'),
('310c5e1a-58e7-49ee-a785-62a8445bbaba'::uuid,'Чай ичүү кыялы ☕','Балдар ойноп жатканда ашканага кирип, эшикти жаап, жашырынып калгыдай чарчадыңызбы? Бул толугу менен табигый нерсе. Маанай күндөлүгүңүздү ачып, эки эле сөз жазыңыз: «Мен чыдадым». Кээде энеге ошол баалуу 5 мүнөттүк тыныгуу гана керек болот.','Unistus teeajast ☕','Oled nii kurnatud, et hiilisid salaja kööki ja panid ukse kinni, kuni laps mängis? Sul on selleks täielik õigus. Ava oma meeleolupäevik ja kirjuta üles vaid kaks sõna: Elasin üle. Mõnikord on emal vaja just seda väärtuslikku 5-minutilist põgenemist.'),
('a80cc41d-cd81-475f-9ddf-075470e2ad74'::uuid,'Булутту карма, качырып жибербе! ☁️','Булут терезеден алыстап кетти деп ыйлап жатышабы? Шамалдын агымын илимий түшүндүрүүгө убакыт коротпоңуз. Жөн гана: «Ал башка балдар менен учурашканы кетти!» деп коюңуз. Алардын кыялкеч дүйнөсүнө бир аз тамаша жана жомок кошуп, кырдаалды оңдоп алыңыз.','Püüa pilv kinni, ära lase lahti! ☁️','Kas laps nutab, sest pilv liikus aknast eemale? Ära raiska aega tuulehoovuste teaduslikule selgitamisele. Ütle lihtsalt: „Oh, see läks teistele lastele tere ütlema!“ Võta omaks tema fantaasiarikas maailmavaade, lisa veidi huumorit ja väikeseid väljamõeldud lugusid, et olukord päästa.'),
('154abe48-3205-47d2-a68c-a06bfd4856c5'::uuid,'Ата менен диванда күрөшүү 🤼‍♂️','Уктоо убактысы келгенде качып жашындыбы? Топту атасына өткөрүп бериңиз. Атасы менен жакшылап ойноп алсын. Ал ызы-чуулуу, тердетип ойногон оюн алардын акыркы энергиясын сарптап, тынч уйкуга багынып берүүсүнө шарт түзөт.','Diivanimaadlus issiga 🤼‍♂️','Jooksis magamamineku ajal peitu? Sööda pall isale. Las nad möllavad ja müravad korralikult. See lärmakas ja higistama ajav isa-lapse mäng kulutab lapse viimasegi kangekaelse energia, sundides teda rahulikule unele alistuma.'),
('1d80be38-a3ec-4e4f-a266-479942a81b0f'::uuid,'Интернеттеги энелерден тажадыңызбы? 📵','Instagram''ды ачканда эле баарынын идеалдуу балдарын көрүп көңүлүңүз чөкпөсүн! Ал тиркемени жаап, Anacan коомчулугуна кириңиз. Башкалардын үйү да сиздики сыяктуу эле чачык, балдары да сиздики сыяктуу эле ызы-чуу экенин көрөсүз. Терең дем алыңыз – сиз жалгыз эмессиз!','Tüdinenud veebiemmedest? 📵','Ära lase end heidutada, kui näed Instagrami avades kõigi teiste täiuslikke lapsi! Sulge see rakendus ja sisene Anacani kogukonda. Näed, et ka teiste kodud on sama segamini ja lapsed sama lärmakad kui sinu omad. Hinga sügavalt sisse – sa pole üksi!'),
('f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37'::uuid,'Муну мен бышырам! 🍳','Жумуртканы өзүм чагам деп туруп алып, жарымы столго төгүлдүбү? Анын «ашпозчу» катары сыймыктануусуна мүмкүнчүлүк бериңиз. Ашкана баары бир тазаланат, бирок анын өз алдынчалыкка болгон умтулуусун жана ишенимин өчүрбөңүз.','Mina teen süüa! 🍳','Laps nõudis, et tohib ise mune kloppida, ja pool sellest sattus lauale? Lase tal nautida seda uhket kokahetke. Köök saab niikuinii puhtaks, aga ära pärsi tema arenevat ego ja iseseisvustunnet.'),
('1325aee8-211f-49a3-af39-fd0cef6023c0'::uuid,'Сиздин чөнтөк педиатрыңыз 🤖','Балаңыздын уйку режими күтүлбөгөн жерден өзгөрдүбү? Кабатырлануудан мурун, Anacan AI''дан 5 айлык баланын уйкусунун өзгөрүшү боюнча кеңеш сураңыз.','Sinu taskupediaater 🤖','Kas beebi unerežiim on ootamatult muutunud? Enne kui muretsema hakkad, küsi Anacan AI-lt nõu ja nippe 5-kuuse uneregressiooni kohta.'),
('66d60d54-4a5d-4de0-a372-047beaa63d3c'::uuid,'Жашыруун макарон камдоо 🍝','Кир жууп жатып чөнтөгүнөн кургак макарон таап алдыңызбы? Бул ачкөздүк эмес, бул балалык пландаштыруу! Кабагыңызды чытпай, аны таштандыга ыргытыңыз, бирок ичиңизден бул кичинекей изилдөөчүгө жылмайып коюңуз. Алар чоңоюп жатышат!','Salajane pastavaru 🍝','Leidsid pesu pestes lapse taskust kuivanud makaroni? See pole ahnus, see on lapsepõlve planeerimine! Viska see ilmetu näoga prügikasti, aga naerata sisemiselt sellele väikesele avastajale ja varujale. Ta kasvab suureks!'),
('d2eca751-d4a9-42ee-89e8-a1b216e785bc'::uuid,'Экрандагы жымжырттыктын үнү 🤫','Акыры укташты. Үйдө кулак тундурган тынчтык орноп калдыбы? Тиркемедеги «Үн өлчөгүчтү» (Sound Meter) ачыңыз. 0 децибелди көрүү чарчаган мээңиз үчүн эң сонун эс алуу болот.','Vaikuse heli ekraanil 🤫','Laps on lõpuks uinunud. Kas majas valitseb nii sügav vaikus, et kõrvus kohiseb? Ava rakenduses helimõõtja. 0-detsibellise näidu nägemine on ülim visuaalne massaaž sinu väsinud ja mürast tüdinud ajule.'),
('d6eb2191-63cd-4b2d-9410-9f12b1424bea'::uuid,'Көйнөктүн этикеткасы мени жинди кылып жатат! 🏷️','Артындагы кичинекей белги ийнедей сайылып жатат деп кийинүүдөн баш тартыштыбы? 3,5 жаштагы балдардын сезимталдыгы кээде тажатма болот. Талашпаңыз; кайчыны алып, аны кесип салыңыз да, бул кичинекей көйгөйдү секунданын ичинде чечиңиз.','See sildiots ajab mind hulluks! 🏷️','Laps keeldub riietumast, sest see pisike silt seljal tundub nagu nõel? Sensoorne tundlikkus 3,5-aastaselt võib olla hullutav. Ära vaidle; haara käärid, lõika silt ära ja lahenda see pisikriis sekunditega.'),
('772e1eef-c912-4a17-abaa-b5296c686fe3'::uuid,'Ал таш меники болчу! 🪨','Парктан алып келген кир ташты ыргытып жибергениңиз үчүн ыйлап жатышабы? Көрсө, ал анын эң жакын досу экен! Тез эле башка жалтырак нерсени таап: «Карачы, таш сага белек жибериптир!» деп, кичинекей жомок менен кырдаалды чеберчилик менен сактап калыңыз.','See kivi oli minu oma! 🪨','Kas laps röögib, sest viskasid ära selle määrdunud kivi, mille ta pargist kaasa tõi? Ilmselt oli see tema parim sõber! Leia kiiresti mõni teine läikiv ese, ütle: „Vaata, kivi saatis sulle selle suveniiriks!“ ja päästa olukord meisterlikult väikese väljamõeldud looga.'),
('8d7ffafe-9007-449d-a1c5-50fafa6a8a92'::uuid,'Менин окуям, менин эрежелерим 📖','Жомок окуп жатып бир сөздү туура эмес айтсаңыз, дароо оңдоп койдубу? Алар баарын жаттап алышыптыр! Китепти жаап: «Жакшы, бүгүн сен мага окуп бер» деңиз. Алардын фантазиясына жол бериңиз, сиз болсо жатып алып, алардын үнүнөн ырахат алыңыз.','Minu lugu, minu reeglid 📖','Lugesid unejuttu ja ütlesid ühe sõna valesti, mille peale laps sind kohe parandas? Ta on selle pähe õppinud! Pane raamat kinni ja ütle: „Olgu, täna loed sina mulle.“ Lase tema fantaasial juhtida ja sina lihtsalt leba ning naudi tema hääle kuulamist.'),
('ba68f77d-f963-479b-bdc5-453510fe2fd8'::uuid,'Шорпо детективи иште 🥕','Шорподон пияздын бир бөлүгүн таап, четке алып койдубу? Бул зергердей тактык! Эртеңден баштап жашылчаларды соуска кантип майдалап кошууну үйрөнүү үчүн «Дени сак рецепттерди» карап чыгыңыз жана бул «согушта» жашыруун жеңишке жетиңиз.','Supidetektiiv tööl 🥕','Laps pistis lusika supi sisse, leidis ühe sibulatüki ja tõstis selle kõrvale? See on juveliiri täpsus! Vaata kohe jaotisest „Tervislikud retseptid“, kuidas need köögiviljad alates homsest püreeks segada, ja võida see lahing salaja.'),
('3f320efd-46d8-4e41-85e8-a584506068f1'::uuid,'Экөөбүз үчүн тынч көз ирмемдер 🥂','Бала уктады, үй жыйналды. Өнөктөшүңүз менен диванда жанаша отуруңуз, телевизорду да күйгүзбөңүз. Жөн гана бири-бириңизди карап: «Биз дагы бир күндү жеңдик, биз чыдадык!» деп коюңуз. Ишениңиз, бул ата-энелик жашоодогу эң романтикалуу жана чыныгы көз ирмем.','Vaiksed hetked kahekesi 🥂','Pisike magab, kodu on korras. Istu koos partneriga diivanil, ära isegi telerit pane. Vahetage lihtsalt pilk, mis ütleb: „Me saime veel ühe päevaga hakkama, me jäime ellu!“ Usu meid, see on lapsevanemaks olemise kõige romantilisem ja ehedam hetk.'),
('5c1ffe1c-132b-41ee-89f2-40908e4efd15'::uuid,'Супермаркеттеги коркунучтуу ''Алып бер!'' 🛒','Кассанын алдында шоколад алып бер деп кыйкырып жатышабы? Артыңыздагылардын караганына карабай, көнбөңүз. Соода тизмеңизди ачып: «Бул тизмеде жок экен, кассадан өтпөйт» деп айтыңыз. Тышкы бийлик аларга ар дайым ишенимдүүрөөк сезилет.','Kardetud „Ma tahan!“ poes 🛒','Kas laps karjub kassas šokolaadi järele? Hoolimata teiste pilkudest ära järele anna. Ava oma ostunimekiri ja ütle talle: „Seda pole siin kirjas, kassapidaja ei saa seda läbi lüüa.“ Väline autoriteet tundub neile alati veenvam.'),
('68fe0739-89b9-4724-85e1-174aecc17d9d'::uuid,'Эмне үчүн МЕН менен сүйлөштүң? 😤','«Кутман таң» дегениңиз үчүн эле капа болуштубу? Себепсиз таарынуу мезгили башталды. Өжөрлөнбөңүз; чайыңызды куюп ичиңиз. Эки мүнөттөн кийин эле тизеңизди кучактап келерине ишениңиз. Алардын эмоциялары азыр ушундай татаал мезгилде!','Miks sa MINUGA rääkisid? 😤','Kas laps sai pahaseks lihtsalt sellepärast, et ütlesid „Tere hommikust“? Näiliselt põhjuseta mossitamise ajastu on täies hoos. Ära suru peale; vala teed ja rüüpa. Ole rahulik, kahe minuti pärast kallistab ta juba su põlve. Tema emotsioonid on praegu lihtsalt nii imeliselt sassis!'),
('5a73dbf6-a948-449b-bd9f-bd6acec175f3'::uuid,'Төрт буттуу бала 🐾','Бүгүн эртең менен адам сыяктуу эмес, күчүк сыяктуу сойлоп турдубу? Капа болуп, эреже үйрөтпөңүз. Жөн гана: «Азаматсың, менин акылдуу күчүгүм!» деп, тамагын сунуштаңыз. Алардын оюнуна кошулуу каршылык көрсөткөнгө караганда алда канча көп энергияны үнөмдөйт.','Neljajalgne laps 🐾','Kas laps ronis täna hommikul voodist välja nagu kutsikas, selle asemel et ärgata nagu inimene? Ära pahanda ega loe moraali. Ütle lihtsalt: „Tubli, minu tark väike kutsikas!“ ja paku talle hommikusööki. Rollimänguga kaasa minemine säästab palju rohkem energiat kui vastupunnimine.'),
('b5299007-402e-4c46-9a86-5fb45df938df'::uuid,'Түнкүсүн күтүүсүз ыйлоо 😭','Түнкүсүн көзү жабык бойдон ыйлап ойгонуп, сизди укпай жатабы? Бул түнкү коркуу сезими. Аны ойготпогонго аракет кылыңыз; жанында туруп, колунан кармап, акырын сылаңыз. Алар көбүнчө өзүнөн-өзү тынчтанып, кайра терең уйкуга кетишет.','Äkiline kesköine nutt 😭','Ärkas öösel nuttes, silmad kinni, ja tundub, et ei kuule sind? See on öine hirmuhoog. Püüa teda mitte äratada; seisa lihtsalt lähedal, hoia käest ja silitage õrnalt. Tavaliselt rahuneb ta ise ja vajub tagasi sügavasse unne.'),
('cd19d080-ed21-40f3-b449-164e996aed41'::uuid,'Денем өзүмдүкү эместей 🔋','Күнү бою бутуңузга жармашып, кучактанууну каалап жатышабы? Сиз физикалык жактан чарчадыңыз. Сиз «сенсордук чарчоо» (touched out) синдромун баштан кечирип жатасыз. Аларды оюнчуктары менен калтырып, 5 мүнөткө ваннага кирип, жалгыздыктан ырахат алыңыз. Сиз буга татыктуусуз.','Mu keha polegi minu oma 🔋','Laps on terve päeva su jala küljes kinni ja tahab kaisutusi? Oled füüsiliselt kurnatud. Koged „puudutustest väsimise“ sündroomi. Jäta ta tuppa mänguasjadega ja põgene 5 minutiks vannituppa, et tunda veidigi omaette olemist. Sa väärid seda.'),
('3c2e2a41-c838-4dd0-b137-24862355a226'::uuid,'Эшикти өзүм ачам! 🚪','Үйдөн чыгып баратканда эшикти ачып койгонуңуз үчүн ыйлап, кайра жаптырдыбы? Бул куракта көзөмөл сезими алардын эң чоң психологиялык муктаждыктарынын бири. 30 мүнөттүк ызы-чуунун алдын алуу үчүн бир мүнөт убактыңызды бериңиз, бул алардын өзүнө болгон ишенимин өстүрөт.','Ma avan ukse ise! 🚪','Kas laps nuttis ja sundis sind ust uuesti kinni panema, sest *sina* avasid selle majast lahkudes? Kontrollivajadus on selles vanuses üks lapse suurimaid psühholoogilisi vajadusi. Lase tal kaotada minut oma ajast, et vältida 30-minutilist avalikku jonnihoogu ja toetada tema enesekindlust.'),
('93ebf06c-8a17-42ec-bbd4-671ae644ffaa'::uuid,'Ваннадагы цунами 🌊','Ваннада жуунуу алар үчүн океан жаратып, толкундар менен ойноо үчүн шылтоо болуп жатабы? Коё бериңиз, ойносун! Суунун ызы-чуусу алардын чексиз, өжөр энергиясын жууп кетет. Кечинде эч кандай каршылыксыз эле укташат.','Vannituba kui hiidlaine 🌊','Kas vanniaeg on talle vaid ettekääne ookeani tekitamiseks ja lainetega mängimiseks? Lase tal möllata! Vee pladistamine ja müra pesevad maha kogu selle lõputu, kangekaelse energia. Õhtuks on ta valmis voodisse minema ilma ühegi protestita.'),
('ed5a44fd-8133-4d4a-859e-893fc179d90d'::uuid,'Кызыктай суроолорго жасалма интеллекттин жооптору 🤖','Апа, көлөкөм түнкүсүн кайда кетет? Бул суроо сизди токтотуп койдубу? Ойдон чыгарып айтпаңыз. Anacan AI''ды ачып, 3,5 жаштагы бала үчүн эң кызыктуу, илимий жоопту алыңыз жана окуп бериңиз. Өзүңүздү улуу философ жана баарын билген эне катары сезиңиз.','AI vastused veidratele küsimustele 🤖','Emme, kuhu mu vari öösel kaob? Kas see küsimus pani sind tarduma? Ära mõtle midagi välja. Ava Anacan AI, saa 3,5-aastasele lapsele kõige lummavam ja armsam teaduslik vastus ning loe see talle ette. Tunne end suure filosoofi ja emana, kes teab kõike.'),
('14c25fd3-e3ee-49fb-8520-527d8c11b191'::uuid,'Сыймыгымды ичинен сыртка кийип 👕','Көйнөгүн тескери кийип алып, оңдотпой жатабы? Коё бериңиз! Анын көзүндөгү «Мен өзүм жасадым!» деген сыймык туура кийингенден алда канча маанилүү. Бүгүн күн бою ошондой сыймыктануу менен жүрсүн; бул анын тандоосу.','Uhke särk pahupidi seljas 👕','Ta pani särgi pahupidi selga ja keeldub kategooriliselt laskmast sul seda parandada? Lase tal! Enesekindlus tema silmis, mis ütleb „Mina tegin!“, on palju tähtsam kui korrektselt riides olemine. Las ta jalutab uhkelt terve päeva nii ringi; see on tema valik.'),
('4ffcb0aa-a9e4-48df-8c7b-2bcf41163980'::uuid,'Аларды шыбырап уктатуу 🤫','Төшөктөн туруп алып, уктабай чуркап жатабы? Кыйкырбаңыз. Тескерисинче, күтүлбөгөн жерден өтө жай, шыбырап сүйлөй баштаңыз. Сизди түшүнүү үчүн алар ушунчалык катуу көңүл бурушу керек болот, натыйжада мээси чарчап, автоматтык түрдө уйку режимине өтөт. Байкап көрүңүз!','Sosistades neid magama 🤫','Voodist väljas ja jookseb toas ringi, keeldudes magamast? Ära karju. Selle asemel hakka äkki rääkima väga aeglaselt, peaaegu sosinal. Ta peab sinust aru saamiseks nii intensiivselt keskenduma, et tema aju väsib ja lülitub automaatselt unerežiimile. Proovi järele!'),
('5dd3ffc3-a306-476f-91ee-6cb8332ca500'::uuid,'Эң сонун тынч көз ирмем 🛋️','Пазл менен ушунчалык берилип ойноп жаткандыктан, үйдө күтүлбөгөн тынчтык орнодубу? Шектенбеңиз; дароо өзүңүзгө кофе куюп алыңыз. Ал алтын мүнөттөрдү тазалоого эмес, өзүңүздүн жан дүйнөңүздү жашартууга жумшаңыз. Сиз робот эмессиз.','Täiuslik vaikne hetk 🛋️','Laps mängib pusledega nii süvenenult, et majas on äkki vaikus? Ära ole kahtlustav; vala endale kohe kohvi. Kuluta need haruldased ja kuldsed minutid mitte koristamisele või pesupesemisele, vaid oma hinge turgutamisele. Sa ei ole robot.'),
('3481c7e9-17f1-45e8-b5ca-16ba68fd1628'::uuid,'Ваннадагы кичи лаборатория 🛀','Сууга ар түрдүү түстөгү самындарды аралаштырып, «дары» жасап жатышабы? Ооба, ванна бир аз кирдеши мүмкүн. Бирок алар эритмелерди жана заттардын айкалышуусун үйрөнүп жатышат! Бул кичинекей илимий изилдөө кечки энергиясын сарптоого жана тынч уйкуга даярданууга жардам берет.','Vannitoa minilabor 🛀','Segab vees erinevaid seepe, et luua jooke? Jah, vannituba võib veidi segaseks saada. Aga ta õpib lahustite ja ainete segunemise kohta! See väike teaduslik avastus aitab tema õhtust energiat hajutada, valmistades teda suurepäraselt ette rahulikuks ööuneks.'),
('628064ef-a8e4-4e1f-b2f9-27acab4d05cf'::uuid,'Тийүү революциясы 🔋','Күнү бою үстүңүзгө чыгып, чачыңызды тарткан баладан физикалык жактан чарчадыңызбы? Аларды дароо коопсуз жерге отургузуп, башка бөлмөгө өтүңүз. Маанай күндөлүгүңүзгө «Денем өзүмдүкү эмес» деп жазып, бул «сенсордук чарчоо» синдромунун психологиялык жүгүнөн арылыңыз.','Puudutuste revolutsioon 🔋','Oled füüsiliselt kurnatud lapsest, kes ronib terve päeva su otsas ja kisub juustest. Pane ta kohe turvalisse kohta ja liigu teise tuppa. Kirjutades oma meeleolupäevikusse „Minu keha ei kuulu mulle“, vabastad end selle „puudutustest väsimise“ sündroomi psühholoogilisest koormast.'),
('6dfd2aa0-4f21-483a-bbab-d26de61eb620'::uuid,'Шкафтагы социалдык изоляция 🚪','Үй ичи күтүлбөгөн жерден тынчып калды. Аларды караңгы шкафтын ичинде жалгыз ойноп жатканын көрөсүз. Бул депрессия эмес; бул жөн гана эмоциялык жактан эс алуу учуру. Эшикти акырын жаап, аларга бул жеке мейкиндиктин ырахатын тартуулаңыз.','Sotsiaalne isolatsioon kapis 🚪','Majas jäi äkki vaikseks. Leiad nad üksi pimedas riidekapis mängimas. See pole depressioon, vaid lihtsalt hetkeline emotsionaalne taaskäivitus. Sulge vaikselt uks ja kingi neile see privaatse ruumi luksus.'),
('8d6625c2-a9b5-42f5-804d-da69978a47f8'::uuid,'Телефон уурусу 📱','Чай ичип отуруп, телефонуңузду таппай каласыз, анан дивандын артынан сизди туурап: «Алло?» деп жаткан үнүн угасыз. Алар сиздин санариптик адаттарыңызды байкап жатышат!','Telefonivaras 📱','Valad endale teed ja avastad, et telefon on kadunud, kuni kuuled diivani tagant enda häält matkivat ''Halloo?''. Nad skaneerivad su digitaalseid harjumusi!'),
('e750fc50-e44a-47b8-b631-5ac89b90275d'::uuid,'''Өзүң кийин!'' саясаты 👖','Алар буттарын асманга көтөрүп жатып: «Мен бөбөкмүн, мени кийиндир!» деп жатышат. Алар дайыма көз карандысыздык менен көз карандылыктын ортосунда жүрүшөт. Аларды кийинүүгө мажбурлабаңыз. Тескерисинче, кийимдерин жанына коюп: «Бул супер баатырдын шымы өзүнүн укмуштуудай ээсин күтүп жатат!» деп кырдаалды башкарыңыз.','„Riietu ise!“ poliitika 👖','Nad lamavad jalad püsti ja ütlevad: ''Olen tita, riieta mind!'' Nad kõiguvad pidevalt iseseisvuse ja sõltuvuse vahel. Ära sunni neid riidesse panema. Selle asemel aseta riided lähedale ja manipuleeri olukorraga, öeldes: ''Need superkangelase püksid ootavad oma ägedat omanikku!'''),
('fa66784d-c126-46e1-ac35-502bd4ad5f50'::uuid,'Үн өлчөгүч менен ички тынчтык 🤫','Алар акыры укташты. Ал эми кулагыңыздагы шыңгыроо дагы деле токтобой жатабы? Колдонмодогу «Үн өлчөгүчтү» (Sound Meter) ачыңыз. Экрандагы 0 децибелдик көрсөткүчтү карап жатып, бөлмөдөгү тынчтыктын акылыңызды кантип тазалап жатканын, чыныгы дары сыяктуу сезиңиз.','Sisemine rahu helimõõtjaga 🤫','Nad lõpuks magavad. Ja see kohin su kõrvus ei taha ikka vaibuda? Ava äpis helimõõtja. Jälgides ekraanil 0 detsibelli näitu, tunneta visuaalselt, kuidas ruumi vaikus su meelt puhastab – see on tõeline palsam hingele.'),
('61c7ca48-5a19-4998-8086-07edd1d4d938'::uuid,'Anacan коомчулугундагы сооронуч 💬','Эч качан идеалдуу боло албайм деген сезим сизди муунтуп жатабы? Instagram''дагы энелердин элесин унутуңуз. Anacan коомчулугуна кошулуңуз, үйү чачылган, дубалга сүрөт тарткан балдары бар энелердин чын жүрөктөн чыккан окуяларын окуп, өзүңүзгө: «Мен таптакыр кадимкидей энемин» деп айтыңыз.','Mugavus Anacani kogukonnas 💬','Kas tunne, et sa ei saa kunagi olema täiuslik, lämmatab sind? Kustuta Instagrami emade illusioon. Liitu Anacani kogukonnaga, loe südamlikke pihtimusi emadelt, kelle kodud on sassis ja lapsed joonistavad seintele, ning ütle endale: ''Olen täiesti normaalne.'''),
('7a600dc5-32dc-4b11-81f6-fb429bfb7588'::uuid,'Шыбырдын сыйкырдуу күчү 🌙','Уктоо убактысы келгенде шылтоо издеп жатышабы? Үнүңүздү акырын шыбырга чейин түшүрүңүз. Алар сизди түшүнүү үчүн физикалык жактан көңүл бурууга аргасыз болушат, ал эми бул катуу концентрация алардын мээсин гипноздоп, тез уктап кетишине жардам берет.','Sosina müstiline vägi 🌙','Leiutavad vabandusi, et vältida magamaminekut? Langeta hääl sosinani. Nad peavad keskenduma füüsiliselt, et sinust aru saada, ja see intensiivne keskendumine hüpnotiseerib nende aju, uinutades nad kiiresti.'),
('fbad87dc-8f76-4644-9e49-49107be8118b'::uuid,'Динозавр логикасы 🦖','Эртең менен алар эч кандай суроого жооп бербей, жөн гана ырылдашат. Бүгүн алар — Ти-Рекс. Ти-Рекстер сулу боткосун жейби? Эртең мененки тартипти көз жашсыз бүтүрүү үчүн алардын ойдон чыгарган образына ылайыкташыңыз.','Dinosauruste loogika 🦖','Hommikul keelduvad nad vastamast ja ainult möirgavad. Täna on nad T-Rex. Kas T-Rexid söövad putru? Kohane nende väljamõeldud rolliga, et hommikune rutiin pisarateta läbida.'),
('401f5436-2de1-44e1-911f-f31af21dfae8'::uuid,'Атамдын ойдон чыгарылган баатырлары 🦸‍♂️','Бүгүн кечинде китептеги окуяларды унутуңуз. Атасы балаңыз башкы каарман болгон фантастикалык, ойдон чыгарылган жомок айтып берсин. «Ал кылычын сууруп чыкты... жана тишин жууду!» сыяктуу сүйлөмдөр аларды күлкүгө бөлөп, уктоо үчүн эң сонун маанай түзөт.','Issi kujuteldavad kangelased 🦸‍♂️','Unusta täna õhtul raamatulood. Lase issil jutustada fantastiline lugu, kus su laps on peategelane. Laused nagu: ''Ja ta tõmbas mõõga... ning pesi hambaid!'' ajavad nad naerma, luues ideaalse meeleolu uneks.'),
('cc1183e6-40b5-4a08-b574-b47668387f44'::uuid,'Өзүмдүн шедевримди сындап 🖍️','Алар сизге кара чийме көрсөтүп: «Бул сенсиң, бирок бул жаман!» деп айтып, аны айрып салышат. Алардын өзүн-өзү сыноо жөндөмү өнүгүп жатат! Алардын сезимдерин баалабай койбоңуз. Тескерисинче, өнүгүүсүн колдоо үчүн: «Балким, кийинки сүрөтүңдө кызыл түстү колдонуп көрөсүңбү?» деп сунуштаңыз.','Oma meistriteose kritiseerimine 🖍️','Nad näitavad sulle musta kritseldust ja teatavad: ''See olid sina, aga see on paha!'' ning rebivad selle puruks. Nende enesekriitika tärkab! Ära pisenda nende tundeid. Toeta nende arengut, soovitades: ''Ehk proovid järgmisel joonistusel punast värvi?'''),
('faf3013a-4d98-4178-82f0-b76954e80a74'::uuid,'Дүкөндөн тапкан олжом 🛒','Кассага жакындаганда, арабадан сиз салбаган печенье пакети чыгат. Кичинекейиңиз унчукпай изилдөө жүргүзүптүр! Соода тизмеңизди ачып, аны көрсөтүп: «Карачы, бул биздин тизмеде жок экен. Кийинки жолу кошуп коёбуз» деп, «айыпты» санариптик эрежеге оодарыңыз.','Minu leid toidupoest 🛒','Kassasse jõudes ilmub kärust pakk küpsiseid, mida sa sinna ei pannud. Sinu väike uurija on tegutsenud! Ava ostunimekiri, osuta sellele ja ütle: ''Vaata, seda pole meie nimekirjas. Lisame selle järgmine kord,'' veeretades ''süü'' digitaalse autoriteedi kaela.'),
('064802a6-44a3-418a-af04-e8b21366e4d7'::uuid,'Эмерекке чыгуу боюнча олимпиада 🧗‍♂️','Алар дивандын чети менен терезени көздөй сойлоп баратат. Сиз үчүн үйүңүз коркунучтарга толгондой сезилет, бирок алар үчүн бул чоң спорт зал! «Этият бол, кулап кетесиң!» деп дүрбөлөңгө түшүп кыйкыргандын ордуна, алардын физикалык кыймылын акырын багыттап: «Колуңду мына бул жерге кой» деп айтыңыз.','Mööblironimise olümpiamängud 🧗‍♂️','Nad ronivad mööda diivani serva akna poole. Sinu jaoks on kodu täis ohte, aga nende jaoks on see hiiglaslik jõusaal! Selle asemel, et paanitseda ja karjuda ''Ettevaatust, kukud!'', suuna nende füüsilist energiat õrnalt: ''Pane käsi täpselt siia.'''),
('1c07d667-ff98-498d-8a14-c5dc48ceda8c'::uuid,'Жашыруун жашылчалар операциясы 🥦','Балаңыз шорпосундагы жалгыз буурчакты же сабизди көрүп: «Мен муну жебейм!» деп жарыялайт. Тамактануу планына кайрылыңыз. Белокторду жана жашылчаларды түстүү кекс формасына кантип айландырууну үйрөнүп, бул тандалма жегичти акыл менен жеңиңиз!','Operatsioon: Peidetud köögiviljad 🥦','Laps märkab supis seda ühte hernest või porgandit ja teatab: ''Mina seda ei söö!'' Sukeldu oma toitumiskavasse. Õpi, kuidas muuta valgud ja köögiviljad värvilisteks muffiniteks ja kavaldada üle see valiv sööja!'),
('7ce3cc61-1a21-499e-a7c2-d24e3693336c'::uuid,'Жубайлардын чай ичүү убактысы 🥂','Оор күндөн кийин өзүңүзгө ысык чай куюп ичиңиз. Диванга өнөктөшүңүздүн маңдайына отуруп, чөйчөктөрүңүздү кагыштырып: «Биз бүгүнкү башаламандыкты да жеңдик; биз укмуштуудай командабыз!» деп айтыңыз. Эсиңизде болсун, сиз үйүңүздүн бекем тирегисиз.','Paaride teehetk 🥂','Pärast rasket päeva valage endale tass teed. Istuge diivanil vastamisi, kõlistage tasse ja öelge: ''Me elasime ka selle kaose üle; oleme suurepärane meeskond!'' Pea meeles, et sina oled oma kodu vankumatu vundament.'),
('1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2'::uuid,'Өз көлөкөмдөн коркуп 👻','Көчөдө басып баратканда, алар күтүлбөгөн жерден өз көлөкөсүнөн коркуп, артыңызга жашынышат. Логика издебеңиз; 3,5 жаштагы баланын элестетүүсү ушундай иштейт! Коркунучтуу нерсени дароо физикалык оюнга айландырып: «Кел, көлөкөнүн үстүнө секирели!» деп айтыңыз.','Oma varju kartmine 👻','Tänaval kõndides ehmuvad nad äkki oma varjust ja peidavad end su selja taha. Ära otsi loogikat; nii töötab 3,5-aastase kujutlusvõime! Muuda hirmutav objekt kohe füüsiliseks mänguks: ''Hüppame varjule peale!'''),
('9cee1c64-59c7-411a-9cc4-1d823dfe8c01'::uuid,'Жасалма интеллект жана бейпилдик 🤖','Балаңыздын күтүлбөгөн жерден кекечтениши же каприз кылышы сизди Google''дан коркунучтуу ооруларды издөөгө түртүп жатабы? Токтоңуз! Anacan AI''дан бул 3 жаштагы баланын өнүгүү этабыбы деп сураңыз жана педиатр тарабынан тастыкталган, ишенимдүү жооп алыңыз.','AI ja meelerahu 🤖','Kas lapse äkiline kogelemine või ootamatud jonnihood ajavad sind Google''is hirmutavate haiguste otsingule? Peatu! Küsi Anacan AI-lt, kas see on tüüpiline 3-aastaste arenguhüpe, ja saa pediaatri heakskiidetud rahustav vastus.'),
('d8c70945-12ad-4739-98a0-3d98184c5d44'::uuid,'Бөлмөдөгү сыйкырдуу үндөр 🪄','Акылдуу жомокторду ачыңыз. Окуп жатканда, эшиктин кычыраган үнүн, шамалдын ышкырыгын жана шыбырларды колдонуп, бөлмөдө үн театрын түзүңүз. Бул адаттан тыш үндөр алардын көңүлүн дароо жомокко буруп, акырындык менен терең уйкуга кетишине жардам берет.','Maagilised heliefektid toas 🪄','Ava nutikad lood. Lugemise ajal loo toas heliteater: kriuksuvad uksed, tuuleiilid ja sosinad. Need ebatavalised helid tõmbavad nende tähelepanu kohe loole ja sealt edasi uinutad nad õrnalt sügavasse unne.'),
('a4d74500-c7bc-4a1a-a200-c6bae74eb5ce'::uuid,'Нандын ортосу меники! 🍞','Кичинекейиңиз нандын жумшак жерин гана жеп, катуу четин сизге берип жатабы? Чети үчүн талашпаңыз. Эртеңден баштап нанды кызыктуу жаныбар формасындагы калыптар менен кесиңиз. Бир аз чыгармачыл сунуштоо бул тамак-аш дилеммасын дароо чечет.','Leiva sisu on minu oma! 🍞','Kas su väike sööja sööb ainult saia pehmet sisu ja ulatab sulle koorikud? Ära vaidle koorikute üle. Lõika homsest saia lõbusate loomakujuliste vormidega. Väike loov esitlus võib selle toidufilosoofilise dilemma kohe lahendada.'),
('e1513af5-17e8-478e-acc0-67084e546889'::uuid,'Алардын таттуу жытын жыттап эле дем ал 🫂','Бүгүн алар сизди чындап эле чарчатып, энергияңызды түгөтүштүбү? Бирок, алар төшөктө ушунчалык бейкүнөө уктап жатышат... Жарыкты өчүрүп, жомокту токтотуңуз. Жөн гана жанына жатып, алардын таза, жагымдуу жытын терең дем алып, бүгүнкү күн үчүн ыраазы болуңуз.','Lihtsalt hinga sisse nende magusat lõhna 🫂','Kas nad ajasid sind täna tõesti hulluks, kurnates su energia täielikult? Ja ometi nad magavad seal nii süütult... Kustuta tuled, jäta lugu vahele. Lihtsalt heida nende kõrvale, hinga sügavalt sisse seda puhast, magusat beebilõhna ja ole tänulik tänase päeva eest.'),
('f1d4800f-e749-493d-9ba5-56a7cf6edfa0'::uuid,'''Сыртка чыккым келбейт'' маанайы ⛅','Төрт дубал сизди кысып, кичинекейиңиз диванга отуруп алып, сыртка чыкпай ыйлап жатабы? Аба ырайын текшерип, туура кийимди тандаңыз, анан кыйын болсо дагы сейил бакка алып барыңыз. Таза аба бетине тийээри менен, бардык агрессиясы тарап кетет. Биз сизге ишенебиз!','„Ei taha välja minna“ masendus ⛅','Kas seinad suruvad peale ja laps nutab diivanil, keeldudes õue minemast? Kontrolli ilma, vali õige riietus ja vii ta parki, isegi kui see nõuab pingutust. Niipea kui värske õhk talle näkku puhub, sulab kogu agressioon. Me usume sinusse!'),
('3a198cfb-0f8d-4bb9-b96b-0ead690adcbf'::uuid,'''Тамакка тийбе'' эрежеси 🚫','Эртең мененки тамакта помидор бадыраңга тийип калганы үчүн революция башталдыбы? 3,5 жаштагы баланын расмий тамак-аш философиясына кош келиңиз! Логика издебеңиз. Биздин «Дени сак рецепттер» менен алардын тарелкасында кызыктуу, өзүнчө зоналарды түзүүнү үйрөнүңүз жана бул абсурддуу кризисти тынчтык жолу менен чечиңиз.','„Toidu mittepuutumise“ reegel 🚫','Kas hommikusöögil puhkes revolutsioon, sest tomat puutus kokku kurgiga? Tere tulemast 3,5-aastase ametlikku toidufilosoofiasse! Ära otsi loogikat. Õpi meie tervislike retseptide abil looma taldrikule lõbusaid eraldatud tsoone ja lahenda see absurdne kriis rahulikult.'),
('9f8b4dfd-dfd3-4045-969a-2d6b122add47'::uuid,'Уктоо убактысы боюнча дипломатиялык соодалашуу 🤝','Алар уктоо убактысын кечеңдетүү үчүн сиз менен расмий сүйлөшүүлөрдү жүргүзүп жатышабы: «Эки эле ууртам суу, бир кучактоо, анан уктайм»? Бул чебер манипуляцияга жылмайып коюңуз. Алардын шарттарына макул болуп, анан жарыкты бекем өчүрүп, келишимди дароо аткарыңыз.','Diplomaatiline kauplemine magamaminekust 🤝','Kas nad peavad sinuga magamamineku üle ametlikke läbirääkimisi: ''Ainult kaks lonksu vett, üks kallistus, siis magan''? Naerata sellele meisterlikule manipulatsioonile. Nõustu tingimustega, seejärel kustuta kindlalt tuled, lüües tehingu lukku.'),
('d547337a-f6dc-44bb-a0b7-19904928148b'::uuid,'Пол — бул лава оюну! 🌋','Пол — лава, диванга чык! Алардын элестетүүсү үйдү джунглиге айландырды. Иштериңизди четке коюп, эки мүнөткө болсо да «лавадан» качып, алардын дүйнөсүнө кириңиз. Кээде баланын эрежелери менен ойноо — стресстен арылуунун эң жакшы жолу.','Põrand on laava! 🌋','Põrand on laava, roni diivanile! Nende kujutlusvõime on muutnud kodu džungliks. Pane toimetused kõrvale ja isegi kui vaid kaheks minutiks, põgene ''laava'' eest ja sisene nende maailma. Mõnikord on lapse reeglite järgi mängimine parim stressimaandaja.'),
('6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba'::uuid,'Таштанды челегинен чыккан сырлар 🗑️','Балаңыз жаңы оюнчугу менен ойноонун ордуна, күнү бою оюнчук оролгон көбүкчөлүү пленканы кучактап жүрөбү? Баланын мээси алдын ала түзүлгөн сценарийлерди эмес, эркиндикти сүйөт. Бул уникалдуу чыгармачылык учурларды «Өсүү трекерине» сыймыктануу менен жазып коюңуз.','Saladused prügikastist 🗑️','Kas su laps veedab terve päeva uue mänguasja mullikilet kallistades, selle asemel et mänguasjaga mängida? Lapse aju ei armasta etteantud stsenaariume; see õitseb vabaduses. Salvesta need ainulaadsed loovuse hetked uhkusega kasvu jälgijasse.'),
('7fe2513f-2da9-40be-8ba2-3f77c91758aa'::uuid,'Тынч кечки көз ирмемдер 🛀','Мээңиз күнү бою «эмне үчүн» деген суроолордон чарчадыбы? Аларды жылуу ваннага отургузуп, бир аз көбүк кошуңуз, анан жанында отуруп, суунун тынчтандыруучу үнүнө көңүл буруңуз. Суунун сыйкырдуу таасири балаңыздын өжөрлүгүн жууп, өзүңүздүн чарчаган нервдериңизди тынчтандырат.','Rahulikud õhtuhetked 🛀','Kas su aju on ''miksidest'' üle ujutatud? Pane nad sooja vanni, lisa veidi vannivahtu ja istu lihtsalt lähedal, keskendudes vee rahustavale helile. Vee magnetiline mõju peseb lapse jonni ja rahustab su enda närve.'),
('e5f2539f-4aa6-4c0d-ad49-b97d6f90a867'::uuid,'Сиз мени укпай жатасыз! 😤','Кичинекейиңиз «Мага кулак сал!» деп, колу менен жүзүңүздү өзүнө буруп жатабы? Алар жөн гана физикалык катышууңузду эмес, 100% көңүлүңүздү талап кылып жатышат. Телефонуңузду же колуңуздагы ишти 3 мүнөткө таштап, көз карашыңызды аларга толук буруңуз. Бул кийинки сааттардагы каприздердин алдын алат.','Sa ei kuula mind! 😤','Kas su väike laps ütleb ''Kuula mind!'' ja keerab su näo kätega enda poole? Nad ei palu ainult füüsilist kohalolu, vaid 100% su tähelepanu. Pane telefon või muu tegevus vaid 3 minutiks kõrvale ja pööra neile täielik silmside. See võib ära hoida tunde kestva jonnimise.'),
('0da92da6-227b-4bc4-8733-939d83f883ad'::uuid,'Түнкү ойлор 🦉','Уктаар алдында кичинекейиңиз: «Апа, булуттар эмне үчүн кулап түшпөйт?» деген сыяктуу терең суроолорду берип жатабы? Алардын максаты илим үйрөнүү эмес, сизди алаксытып, уктоо убактысын кечеңдетүү. Аларга кыска, элестетүүгө бай жооп бериңиз, мисалы: «Анткени алар ал жакта уктап жатышат!». Андан кийин, тынч уйкуга багыттоо үчүн «Акылдуу жомоктордон» жагымдуу обон коюңуз.','Kesköised mõtisklused 🦉','Just siis, kui nad on uinumas, küsib laps sügavaid küsimusi nagu: ''Emme, miks pilved alla ei kuku?'' Nende eesmärk pole teadust õppida, vaid sind kaasata ja und edasi lükata. Anna kiire, fantaasiarikas vastus: ''Sest nad magavad seal üleval!'' Seejärel mängi ''Nutikatest lugudest'' rahustavat meloodiat, et juhatada nad kindlalt unemaale.'),
('1b4bdd7d-042a-4be6-a59f-82892d67ff8d'::uuid,'Дүкөндөгү укмуштуудай суроо 😳','Кассада кезекте турганда балаңыз катуу үн менен: «Эмне үчүн тигил айымдын чачы мындай?» деп сурап калса, аны уятпаңыз же «үнүңдү өчүр» дебеңиз. Дароо көңүлүн тиркемедеги соода тизмесине буруп: «Кел, алма алдыкпы, текшерип көрөлүчү!» деп, кырдаалды дипломатиялык жол менен чечиңиз.','Uskumatu küsimus poes 😳','Seistes kassajärjekorras, küsib laps valjult: „Miks selle tädi juuksed sellised on?“ Ära tunne piinlikkust ega vaigista teda. Suuna tema tähelepanu kohe äpis olevale ostunimekirjale, öeldes: „Vaatame, kas saime õunad kätte!“ ja lahenda olukord diplomaatiliselt.'),
('62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e'::uuid,'Эмне үчүн менин сүйүктүү көйнөгүмдү жууп салдың?! 👕','Сүйүктүү, бирок эскирген көйнөгүн жууп койгонуңуз үчүн үйүңүздө «аза күтүү күнү» жарыяландыбы? Балдардын буюмдарга болгон байланышы кээде логикага сыйбайт. Талашпаңыз! Дароо «Ымыркайдын фотосессиясы» функциясын ачып, анын капа болгон жүзүн тартып алыңыз да, аны тамашага айлантыңыз. «Экрандан өзүңдүн канчалык каардуу экениңди карачы!» деген ыкма анын көңүлүн заматта бурат – байкап көрүңүз!','Miks mu lemmiksärk ära pesti?! 👕','Kas kodus on kuulutatud välja „leinapäev“, sest panid selle armsa, pleekinud särgi pesumasinasse? Laste kiindumus esemetesse eirab vahel igasugust loogikat. Ära vaidle! Ava kohe funktsioon „Beebi fotosessioon“, jäädvusta tema pahur nägu ja muuda see naeruks. „Vaatame, kui vihane sa ekraanil välja näed!“ on nipp, mis juhib tähelepanu hetkega kõrvale – proovi järele!'),
('4e937fd6-67f9-496a-b0c5-be8bf0840c6d'::uuid,'Жарыкты өчүр, көлөкө оюнун башта! 🐰','Ал караңгыдан коркуп жатабы же жалгыз коридорго чыккысы келбей жатабы? Бөлмөдөгү жарыктарды өчүрүп, кичинекей фонарикти күйгүзүңүз. Колуңуз менен дубалга иттин же куштун көлөкөсүн жасап, коркунучтуу караңгылыкты кызыктуу оюн аянтчасына айлантыңыз. Ал бат эле уктап калат.','Tuled kustu, varjuteater algab! 🐰','Kas laps kardab pimedust või ei taha üksi koridori minna? Kustuta toas tuled ja lülita sisse väike taskulamp. Tee kätega seinale koera- või linnuvarjusid, muutes hirmutava pimeduse mängumaaks. Nad uinuvad hetkega.'),
('6d8c96e4-6f09-4805-a4a8-4acf034ab6c9'::uuid,'Сизге эс алуу убактысы келди ☕','Балаңыз өз бөлмөсүндө оюнчуктары менен алек болуп, үйдө күтүлбөгөн жерден тынчтык орнодубу? Сураныч, ал учурду үй жыйноого же кир жууганга жумшабаңыз! Диванга жатып, «Маанай күндөлүгүңүзгө» 5 мүнөттүк тынчтыкты жазып, кофеңизди жылуу кезинде ичип алыңыз. Сиз да бул үй-бүлөнүн бир бөлүгүсүз.','On aeg end välja lülitada ☕','Kas laps on oma toas mänguasjadega nii süvenenult ametis, et majas valitseb äkiline vaikus? Palun ära kasuta seda hetke koristamiseks või pesu voltimiseks! Mine diivanile, kirjuta oma meeleolupäevikusse 5 minutit rahu ja rüüpa kohvi, kuni see on veel soe. Sina oled ka osa sellest perest.'),
('f30558ce-2e74-4368-ad59-ff72d43fefc7'::uuid,'Мен кылган жокмун, оюнчук аюум кылды! 🧸','Ал атайылап суу төгүп, анан күнөөнү оюнчугуна оодардыбы? Ал калп айтып жаткан жок; ал жөн гана 3,5 жашар баланын коргонуу механизмин ачты. Каршылашпаңыз! «Кел, кичинекей айыбызга (оюнчук/досу) аны кантип тазалоону үйрөтөлү» деп, колуна чүпүрөк бериңиз. Ал жоопкерчиликти үйрөнөт, анын «мен» деген сезими да жабыркабайт.','Mina ei teinud seda, kaisukaru tegi! 🧸','Kas ta ajas meelega vett maha ja süüdistas siis oma mänguasja? Ta ei valeta, ta on lihtsalt avastanud 3,5-aastase kaitsemehhanismi. Ära hakka vastu! Ütle: „Õpetame oma väikesele kuule (mänguasjale/sõbrale), kuidas seda koristada,“ ja anna talle lapp. Ta õpib vastutust ja tema ego jääb terveks.'),
('1633765a-e691-4a02-b657-169e03223f3f'::uuid,'Эненин тамак-аш күйүүчү майы 🥗','Балаңызды тойгузуу үчүн ар кандай менюларды ойлоп таптыңыз, бирок өзүңүз дагы эле кургак нерсе жеп, бутуңуз менен туруп жүрөсүзбү? Дени сак рецепттер бөлүмүнөн даярдалышына 10 мүнөт гана кеткен, темирге жана кальцийге бай, энергия берүүчү эртең мененки тамакты табыңыз – бул балдар үчүн гана эмес, өзүңүз үчүн да керек. Өзүңүздү баалаңыз!','Emme toidukütus 🥗','Oled nuputanud lapsele erinevaid menüüsid, aga kas oled ise jälle midagi kuiva püstijalu söönud? Leia tervislike retseptide sektsioonist energiat andev, raua- ja kaltsiumirikas hommikusöök, mille valmistamine võtab vaid 10 minutit – mitte ainult lastele, vaid ka sulle endale. Väärtusta ennast!'),
('2d30d5d5-9abc-4c5e-847a-462fa693fbda'::uuid,'''Оюнчугум ооруп калды'' күрөшү 🩺','Балаңыз оюнчук стетоскоп менен аюусун олуттуу текшерип, ага бинт таңып жатабы? Символикалык оюн аркылуу ал боорукерликти жана камкордукту үйрөнүп жатат. 5 мүнөткө бейтап болуп жатып берип, ага кошулуңуз, ал сизди тынч «текшерип» алсын.','„Mu mänguasi on haige“ lahing 🩺','Kas laps uurib tõsiselt oma mängukaru mängustetoskoobiga ja paneb sellele plaastrit? Sümboolse mängu kaudu töötleb ta empaatiat ja hoolivust. Liitu temaga, heida pikali ja mängi 5 minutit patsienti, lastes tal end vaikselt „läbi vaadata“.'),
('37ed4aaf-5c8b-418c-8274-802f79f0bf41'::uuid,'Тез уктоо үчүн акылдуу жомоктор 🪄','Бардык классикалык жомокторду жаттап алдыңызбы? «Акылдуу жомокторду» ачып, балаңызды башкы каарман кылып, анын бөлмөсүн жомоктогу изилдене турган кызыктуу жайга айлантып, укмуштуудай жана жеңил уктоо сеансын түзүңүз.','Nutikad lood kergemaks uinumiseks 🪄','Oled kõik klassikalised unejutud pähe õppinud. Ava „Nutikad muinasjutud“ ja loo erakordne, pingevaba uneaeg, tehes oma lapsest loo peategelase ja tema toast põneva paiga, mida avastada.'),
('72e4a373-da8e-4cf7-b36b-25d3d3a13b6e'::uuid,'Жөн гана кучактоо 🫂','Бүгүн оюндарды, китептерди же жомокторду унутуңуз. Жөн гана аны көкүрөгүңүзгө кысып, анын жагымдуу, өзгөчө жытын жыттап, караңгыда анын канчалык баалуу экенин жана аны канчалык терең сүйөрүңүздү шыбырап айтыңыз.','Lihtsalt üks kallistus 🫂','Unusta täna mängud, raamatud ja unejutud. Lihtsalt hoia teda tihedalt oma rinna vastas, hinga sisse tema magusat, ainulaadset lõhna ja sosista pimeduses, kui väärtuslik ta on ja kui sügavalt sa teda armastad.'),
('8d0e8d79-2ed2-4d47-9d71-055f26b53574'::uuid,'Буюмдар менен сүйлөшүү 🗣️','Балаңыз сейил бакта таш менен олуттуу сүйлөшүп жатабы же үйдө отургучту урушуп жатабы? Символикалык оюн аркылуу ал өзүн курчап турган дүйнөнү түшүнүүгө аракет кылып жатат.','Vestlused asjadega 🗣️','Sinu laps peab pargis kiviga täiesti tõsist vestlust või riidleb kodus tooliga. Sümboolse mängu kaudu töötleb ta ümbritsevat maailma.'),
('b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9'::uuid,'Эртең мененки жашынмак 🙈','Жумушка же бала бакчага кечигип жатасыз, ал эми балаңыз парданын артына жашынып алып: «Мени тап!» деп кыйкырып жатабы? Нервиңиз жукарып турса да, кыйкыруу процессти гана узартат. «Менин сулуу бөбөгүм кайда экен?» деп сурап, 2 мүнөт оюнга кошулуңуз, аны «таап», анан акырын жетелеп чыгыңыз.','Hommikune peitusemäng 🙈','Kas oled tööle või lasteaeda hilinemas ja laps peidab end kardina taha, hüüdes: „Leia mind!“? Isegi kui närvid on pingul, pikendab karjumine vaid protsessi. Liitu mänguga 2 minutiks, küsides: „Kus mu kaunis väike laps küll olla võiks?“ ja „leia“ ta üles, seejärel juhi ta õrnalt välja.'),
('9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e'::uuid,'Физикага баш ийбеген өжөрлүк 💧','Ал столго суу төгүп алып, эми аны кайра чөйчөккө куюп беришиңизди ыйлап талап кылып жатабы? Ооба, бул жерде логика жок, болгону оңолгус катанын айынан келип чыккан капалануу бар. Түшүндүрүүгө аракет кылбаңыз. Колуна чүпүрөк берип: «Кел, бул сууну жоготуп жиберели!» деп, аны оюнга айлантыңыз.','Füüsikaseadusi eirav jonnakus 💧','Kas ta ajas lauale vett ja nõuab nüüd nuttes, et paneksid selle tagasi tassi? Jah, toas pole loogikat, vaid pöördumatu vea tekitatud frustratsioon. Ära püüa selgitada. Anna talle lapp ja ütle: „Paneme selle vee kaduma!“ muutes selle mänguks.'),
('aff11dbf-a5df-4f87-ba8b-797021b1bfe4'::uuid,'Эненин оффлайн режиминдеги качуусу 🚪','Ызы-чуудан кулагыңыз жаңырдыбы? Балаңызды коопсуз жерге калтырыңыз (же атасына бериңиз), анан ваннага кирип, эшикти жаап алыңыз. Беш мүнөт эч нерсе кылбай, дубалды карап отуруңуз, жадакалса телефонуңузду да ачпаңыз. Бул кыска тынчтык – сизди энелик абалыңызга кайтара турган эң күчтүү курал.','Emme võrguväline põgenemine 🚪','Kas müra paneb kõrvus kumisema? Vii laps turvalisse kohta (või anna ta issi hoolde), siis lipsa vannituppa ja sulge uks. Lihtsalt vaata viis minutit seina, ära tee midagi, ära isegi ava telefoni. See lühike vaikus on kõige võimsam vahend, et tuua sind tagasi oma emalikku olemusse.'),
('f965edcf-2124-46c3-82a9-e8d418ee755a'::uuid,'Атанын учак режими ✈️','Ал энергиясын толук сарптай албай, уктоодон баш тартып жатабы? Атасын диванга чакырыңыз! Ал балаңызды учактай көтөргөндө, бөлмө күлкүгө толуп, топтолгон физикалык стресс заматта жок болот. Бул атанын өзүн көрсөтө турган учуру!','Issi lennukirežiim ✈️','Nad pole kogu energiat välja elanud ja keelduvad magamaminekust. Kutsu issi diivanile! Kui ta tõstab lapse lennukina õhku, täitub tuba naeruga, sulatades kogu kogunenud füüsilise pinge sekunditega. See on issi hetk särada!'),
('535821ef-9689-4454-87b8-1d43fe500b62'::uuid,'Жаңы тил ойлоп табуу 🗣️','Бөбөгүңүз «Оюнчугум капа болуп жатат» же «Асман ыйлады» деп, нерселерге сезимдерди ыйгарып, элестүү, поэтикалык сүйлөмдөрдү түзүп жатабы? Анын сөз байлыгы жана эмоционалдык интеллекти чагылгандай тездик менен өнүгүп жатат! Анын бул таттуу философиясын дароо архивдөө үчүн «Ымыркайдын фотосессиясынын» видео режимин колдонуңуз.','Uue keele leiutamine 🗣️','Kas su väike laps loob kujutlusvõimelisi, poeetilisi lauseid, omistades esemetele tundeid, nagu „Minu mänguasi on kurb“ või „Taevas nuttis“? Tema sõnavara ja emotsionaalne intelligentsus arenevad välkkiirelt! Kasuta „Beebi fotosessiooni“ videorežiimi, et see armas filosoofia kohe arhiveerida.'),
('baf0af3c-984e-45f1-a68f-93e13e9f1cef'::uuid,'Башкы ашпозчу иште! 🧑‍🍳','Сиз торт бышырып жатканда, ал сөзсүз түрдө отургучту сүйрөп келип, ундун өзү төгүшүн талап кылат. Эгер уруксат берсеңиз, ашканаңыз заматта унга толот! Анын ордуна, ага бош идиш, бир аз суу жана бир аз ун берип: «Сен өзүңдүн камырыңды жууруп ал!» деңиз. Башаламандык болушу мүмкүн, бирок анын кичинекей «мен» деген сезими толугу менен канааттандырылат.','Peakokk on tööl! 🧑‍🍳','Kui küpsetad muffineid, tõmbab laps kindlasti tooli ligi ja nõuab, et saaks ise jahu valada. Kui lubad, on köök hetkega jahu täis! Selle asemel anna talle tühi kauss, veidi vett ja natuke jahu, öeldes: „Saad oma koogitainast ise sõtkuda!“ Kaos võib tulla, aga tema väike ego on täielikult rahuldatud.'),
('cba9ff3e-e38f-40b7-b48d-13e030f8993a'::uuid,'''Өзүм жасайм!'' тамактануу козголоңу 🥣','Өзү тамак жей алса да, сизден жедиришиңизди талап кылып, анан кашыкты түртүп жиберип ыйлап жатабы? Бул карама-каршылыктардын этабы. Мажбурлап тамактандырууга аракет кылбаңыз жана ачка калат деп кабатыр болбоңуз. Тарелканы алдына коюп: «Ачка болгондо жейсиң» деп, столдон алыстап кетиңиз. Ал даяр болгондо сөзсүз жейт.','„Ma teen ise!“ söögiaja mäss 🥣','Kuigi ta oskab ise süüa, nõuab ta kangekaelselt, et sina teda toidaksid, lükkab siis lusika eemale ja nutab. See on vastuolude faas. Ära püüa sundida ja ära muretse, et ta nälga jääb. Pane taldrik tema ette, ütle: „Sööd siis, kui kõht on tühi,“ ja lahku lauast. Ta sööb, kui on valmis.'),
('5672be3d-87ec-469d-a4b7-fca0b00ec9ac'::uuid,'Аянтчадагы саясат 🤝','Балаңыз слайддан түшүүнү каалап, башка баланы түртүп жибердиби? Бөлүшүү – бул алар үчүн али толук түшүнүктүү боло элек татаал түшүнүк. Уятпай же жазалабай эле, «Азыр анын кезеги» деп, эрежени жөн гана эскертип коюңуз.','Mänguväljaku poliitika 🤝','Kas su laps lükkab teist last liumäelt, sest tahab ise järgmisena minna? Jagamine on veel keeruline mõiste, mis pole tema jaoks päriselt kohale jõudnud. Häbistamise või karistamise asemel tuleta talle lihtsalt reeglit meelde, öeldes: „Nüüd on tema kord.“'),
('7b9a42e6-44aa-4528-9036-fbb93f662348'::uuid,'Эмне үчүн күн мага карап турат?! ☀️','Балаңыз «Эмне үчүн күн менин көзүмө карап жатат?» деп ыйлап ойгондубу? Логика издебеңиз же жаратылыш кубулуштарын түшүндүрүүгө аракет кылбаңыз; ал дүйнөнү башкара албаганына капа болуп жатат. Парданы жаап: «Мен күндү сенин гана көзүңдөн жашырып койдум!» деңиз — бул абсурддуу көйгөйдү заматта чечет.','Miks päike mind vaatab?! ☀️','Kas laps ärkab hüsteeriliselt nuttes ja küsib: „Miks päike mulle otse silma vaatab?“ Ära püüa leida loogikat ega selgitada loodusnähtusi; ta on lihtsalt vihane, et ei saa maailma kontrollida. Tõmba kardin ette ja ütle: „Peitsin päikese just sinu jaoks ära!“ – lahendades selle absurdse probleemi hetkega.'),
('bf33243a-24ca-4b24-a11a-d703c038cdcf'::uuid,'Менин кичинекей кыймылдаткычым дагы деле иштеп жатат! 🚗','Ал уктоодон качуу үчүн «Менин машинам уйкусураган жок!» деп туруп алдыбы? Балдар көбүнчө өздөрүнүн уйкусу келбегенин жана каршылыгын оюнчуктарына оодарышат. Талашпаңыз; анын ордуна «Акылдуу жомокторду» ачып, уктап жаткан машиналар жөнүндө жомок түзүңүз. Машина уктап калары менен, ал да өзүнөн өзү көзүн жумат. Байкап көрүңүз!','Mu väike mootor töötab ikka veel! 🚗','Kas ta nõuab magamamineku vältimiseks: „Minu auto ei ole unine!“? Lapsed projitseerivad sageli oma unetust ja vastupanu mänguasjadele. Ära vaidle; ava hoopis „Nutikad muinasjutud“ ja loo lugu magama minevatest autodest. Niipea kui auto uinub, vajuvad ka temal silmad kinni. Proovi ja vaata!'),
('5c063277-1aff-4166-9dbe-d6ab5866cdbd'::uuid,'Нандын четин кесип салыңыз! 🍞','Бөбөгүңүз нандын жумшак жерин гана жеп, катыган четин кескин түрдө четке кагып жатабы? Бул курактын өзүнүн өзгөчө визуалдык эстетикасы бар. Нанды сүйкүмдүү жаныбарлардын формасында кескенди үйрөнүңүз. Кичинекей дизайн бул күрөштү заматта токтотот.','Lõika koorikud ära! 🍞','Kas su väike laps sööb röstsaiast ainult pehmet osa ja lükkab koorikud kindlalt tagasi? Selles vanuses on oma unikaalne visuaalne esteetika. Õpi lõikama leivaviile armsate loomakujulistena. Väike disain võib selle võitluse hetkega lõpetada.'),
('e0613a64-c64f-491d-8c87-72276f72849e'::uuid,'Тактарды кабыл алыңыз 👗','Кошумча тамакка өтүү – бул тамактын чачылышы дегенди билдирет! Бул үчүн стресс болбоңуз; силикон алжапкычтарды колдонуңуз жана бул башаламан, күлкүлүү көз ирмемдерден ырахат алыңыз.','Lepi plekkidega 👗','Tahke toiduga alustamine tähendab sageli toitu kõikjal! Ära lase sel end stressata; kasuta silikoonpõllesid ja naudi neid segaseid, naljakaid hetki.'),
('a42141c6-7a93-4719-be36-e495b333ffee'::uuid,'Унчукпай карап отуруунун ырахаты 🥂','Бала уктады, үй жыйналды. Өнөктөшүңүз менен диванга жанаша отуруңуз; телевизорду да күйгүзбөңүз. Жөн гана «Биз дагы бир күндү аман-эсен өткөрдүк!» дегенди билдирген көз караш менен алмашыңыз. Бизге ишениңиз, бул чарчаган ата-энелик жашоодогу эң романтикалуу жана нукура көз ирмем.','Vaikse vaatamise rõõm 🥂','Laps magab, kodu on korras. Istuge partneriga diivanil kõrvuti; ärge isegi telerit sisse lülitage. Vahetage lihtsalt see teadlik pilk, mis ütleb: „Me elasime veel ühe päeva üle!“ Uskuge meid, see on väsinud lapsevanemaks olemise kõige romantilisem ja ehedam hetk.'),
('fbd48b54-2407-4752-a5b5-4e335233ace4'::uuid,'Көрүнбөгөн тактар кырсыгы 👕','Балаңыз микроскоп менен гана көрүнө турган кичинекей такты таап алып, көйнөк кийүүдөн баш тарттыбы? Нымдуу салфетка менен такты сүрткөн болуп: «Абракадабра! Мен аны сыйкыр менен жок кылдым!» деп айтыңыз. Баланын акылы ар дайым эненин сыйкырына ишенет – байкап көрүңүз.','Nähtamatu pleki katastroof 👕','Kas laps keeldus särki kandmast, sest leidis pisikese pleki, mida on näha vaid mikroskoobi all? Tee nägu, et pühid pleki niiske salvrätiga ära ja kuuluta: „Presto! Panin selle võluväel kaduma!“ Lapse mõistus usub alati ema võluväesse – proovi järele!'),
('081fe93d-51fc-4e73-b956-ea2d06dcec72'::uuid,'Мага сууну башка чөйчөккө куюп бериңиз! 🥤','Сары чөйчөккө суу куюп бергениңиз үчүн эле үйдө ызы-чуу чыктыбы? Кабатыр болбоңуз, бул жөн гана чектерди сынап көрүү. Бир мүнөттөн кийин сууну алар каалаган чөйчөккө куюп бериңиз, үйдө тынчтык орнойт, ал эми өзүңүздүн күчүңүздү күндүн калган бөлүгүнө сактап калыңыз.','Anna mulle vesi teises tassis! 🥤','Kas tuba läks täiesti segi, sest andsid neile vett kollases tassis? Ära mõtle üle; nad lihtsalt katsetavad piire. Vala vesi hetkega nende eelistatud tassi, taasta toas rahu ja hoia oma energiat päeva ülejäänud osaks.'),
('12e39cd9-ad30-497d-8902-0c8e0d1a5c56'::uuid,'Парктан чыгып кетүү өнөрү 🌳','Сейил бактан кете турган убакыт келди, ал эми балаңыз ыйлап баштадыбы? Аны сүйрөп кетүүнүн кереги жок. Тескерисинче, көңүлүн дароо кызыктуу оюнга буруңуз: «Ким пингвин болуп басып, машинага биринчи жетет?» Ал сөзсүз түрдө жеңишке жетүүнү каалайт!','Pargist lahkumise kunst 🌳','On aeg pargist lahkuda ja nutune jonn on alanud. Lohistamine ei aita. Selle asemel suuna nende tähelepanu kohe lõbusale väljakutsele: kes suudab kõige kiiremini pingviini kombel autoni vantsida? Nad tahavad kindlasti võita!'),
('ec5e51b0-e017-4226-9363-9dfff1dce391'::uuid,'Атасы менен диванда күрөшүү 🤼‍♂️','Уктоо убактысы келгенде качып жашынып алдыбы? Топту атасына бериңиз! Дубалдын жанында бир аз күрөшүп ойношсун. Ал ызы-чуулуу, тердеткен оюн алардын өжөрлүгүн басып, тез эле уйкуга кетишине жардам берет.','Diivanimaadlus issiga 🤼‍♂️','Kas nad jooksid magamamineku eest peitu? Anna pall üle issile! Las nad teevad seina ääres ühe mängulise maadlusmatši. See lärmakas ja higistama ajav mäng kurnab nende kangekaelse energia viimseni, aidates neil kergemini uinuda.'),
('01fb525b-af8a-41d4-8fd1-724d4fd01667'::uuid,'Музыканын сыйкырдуу таасири 🎶','Кечки маалдагы түшүнүксүз ыйды классикалык музыка менен басууга аракет кылыңыз. Телевизорду өчүрүңүз. Көбүнчө ушул жөнөкөй ыкма ар кандай тынчсызданууну басып, үйгө сыйкырдуу тынчтык алып келет.','Muusika hüpnootiline mõju 🎶','Proovi õhtuseid seletamatuid jonnituure leevendada kerge klassikalise muusikaga. Pane teler kinni. Tihti summutab see lihtne nipp igasuguse sügava rahulolematuse ja toob tuppa imelise rahu.'),
('d8b40eb7-3665-4514-839c-874f3d30ec40'::uuid,'Ойдон чыгарылган сөздөр 🗣️','Балаңыз «Асман ыйлады» же «Машина ачууланды» деген сыяктуу кызык сүйлөмдөрдү айтып жатабы? Алардын сөз байлыгы тездик менен өсүп жатат, алар сөздөр менен ойноп жатышат! Өнүгүү күндөлүгүн ачып, алардын бул таттуу, поэтикалык ойлорун жазып коюңуз — бир нече жылдан кийин окуп алып, өзүңүз да каткырасыз.','Väljamõeldud sõnad 🗣️','Kas su laps loob omapäraseid lauseid nagu ''Taevas nuttis'' või ''Auto sai pahaseks''? Nende sõnavara kasvab tormiliselt ja nad mängivad sõnadega! Ava arengupäevik ja pane kirja nende armsad, poeetilised mõtted – aastaid hiljem naerad neid lugedes südamest.'),
('f96cc98d-a4e0-44e3-9617-a284b205c20e'::uuid,'Экрансыз убакыттын дилеммасы 📺','Бүгүн көп жумушуңуз болгондуктан, балаңыз телевизор алдында көп отуруп калдыбы? Өзүңүздү күнөөлүү сезип жатасызбы? Ар дайым идеалдуу боло албайсыз. Кээде экрандар бизди чоң башаламандыктан сактап калган эң күнөөсүз «бала багуучу» болуп берет. Өзүңүзгө өтө катуу талап койбоңуз.','Ekraanivaba pausi dilemma 📺','Kas laps veetis täna liiga palju aega teleri ees, sest sul oli palju tegemist? Kas süütunne närib sind? Sa ei saa olla iga päev täiuslik. Mõnikord on ekraanid kõige süütumad lapsehoidjad, päästes meid suuremast kaosest. Ära ole enda vastu nii karm.'),
('246edaf3-5d30-44d2-bda4-13ec5fbf5f36'::uuid,'Караңгы бөлмөдөгү көлөкө театры 🐰','Караңгыдан коркуп, уктоодон баш тартып жатабы? Бөлмөдөгү жарыкты өчүрүп, кичинекей фонарикти күйгүзүңүз. Колдоруңуз менен дубалга иттин же канаттуунун сөлөкөтүн жасаңыз. Коркунучтуу караңгылыкты кызыктуу оюн аянтчасына айландырыңыз, ошондо алар тез эле уктап калышат.','Varjuteater pimedas toas 🐰','Kardab pimedust ja keeldub voodisse minemast? Kustuta toas kõik tuled ja lülita sisse väike taskulamp. Tee kätega seinale koera- ja linnuvarjusid. Muuda hirmutav pimedus nende jaoks mängumaaks ja nad uinuvad hetkega.'),
('d3b4180b-5723-4f72-a6c8-b4229f2e876c'::uuid,'Динозаврлар сулу боткосун жебейт! 🦖','Балаңыз эртең менен суроолорго жооп берүүнүн ордуна эле ырылдап жатабы? Бүгүн ал Ти-Рекс экен! Анын ролуна ылайыкташып: «Ти-Рекстер эртең мененки тамакты ичеби?» деп сураңыз, ошондо ал ыйлабай эле столго отурат.','Dinosaurused ei söö putru! 🦖','Kas su laps möirgab hommikul küsimustele vastamise asemel? Nad on täna türannosaurus! Kohane nende väljamõeldud rolliga, küsides: ''Kas türannosaurused söövad hommikusööki?'' ja taga, et nad istuksid ilma pisarateta laua taha.'),
('e089800c-6f76-4909-bafd-021551368a5f'::uuid,'Бүгүн мен чарчадым 🛑','Баары үйүлүп келип, үнүңүздү көтөрүп жибердиңиз. Эми өзүңүздү күнөөлүү сезип жатасыз. Сиз робот эмессиз. Маанай күндөлүгүңүздү ачып: «Мен бүгүн чындап чарчадым» деп жазыңыз. Бул чынчыл моюнга алуу жасалма жылмайуудан көрө сизге көбүрөөк жардам берет.','Täna on mu piir käes 🛑','Kõik kuhjus ja sa tõstsid häält. Nüüd tunned süüd. Sa ei ole robot. Ava oma meeleolupäevik ja kirjuta: ''Olen täna tõeliselt väsinud.'' See aus ülestunnistus aitab sind rohkem kui võltsnaeratuse sundimine.'),
('e67730b8-4981-4bba-b868-fe6cf9b7e3da'::uuid,'Керектүү нерселер түгөнүп жатабы? 🛒','Пюре үчүн жаңы жашылчалар керекпи? Аларды соода тизмеңизге кошуп коюңуз, ошондо жубайыңыз жумуштан келе жатып жаңы азыктарды алып келет.','Varud hakkavad otsa saama? 🛒','Vajad püreedeks uusi köögivilju? Lisa need ostunimekirja, et su kaaslane saaks koju tulles värsket kraami kaasa haarata.'),
('a8aeb934-2767-4365-a584-e2b99fc16215'::uuid,'«Сен кимсиң?» оюну 🎭','Балаңыз бүгүн эртең менен сизди тааныбай: «Сиз кимсиз? Апам кайда?» деп сурадыбы? Бул жаңы ролдук оюн! «Мен кошуна эжекемин, апаң азыр келет» деп айтыңыз. Үйдү күлкүгө толтуруңуз; бул каршылашканга караганда алда канча аз күч талап кылат.','„Kes sa oled?“ mäng 🎭','Kas su laps vaatas sind täna hommikul nagu võõrast ja küsis: ''Kes sa oled? Kus mu emme on?'' See on uus rollimäng! Ütle: ''Olen tädi Naaber ja emme tuleb varsti.'' Las tuba täitub hommikul naeruga; see säästab palju rohkem energiat kui vastupunnimine.'),
('cf7b3532-560e-4c59-af5f-4a64a8510605'::uuid,'Жомоксуз уйкуга кетүү 🪄','Бүгүн кечинде жомок окуп берүүгө күчүңүз жокпу? «Акылдуу жомокторду» ачып, фонго токойдун шыбыры менен шамалдын үнүн коюп коюңуз. Караңгыда бул жаратылыш үндөрү экөөңүздөрдү тең күндүн ызы-чуусунан арылтып, тынчтандырат. Чарчооңуз заматта тарап кетет.','Unejuttudeta magamaminek 🪄','Pole täna õhtul jõudu unejuttu lugeda? Ava ''Nutikad muinasjutud'' ja sea taustaks sosistav mets ja tuulehelid. Pimedas lase neil loodushäältel teid mõlemaid päeva mürast rahustada. See visuaalne väsimus kaob hetkega.'),
('f8301d61-e90d-4d1c-b4e2-7f1feb3be70d'::uuid,'Кир жуучу күнүмдүн «казыналары» 🍝','Кир жууп жатып балаңыздын чөнтөгүнөн кургап калган макарон же таш таап алдыңызбы? Бул таштанды эмес, баланын дүйнөнү таанып-билүүсү! Олуттуу жүз менен аны таштандыга ыргытыңыз, бирок ичиңизден кичинекей коллекционериңизге жылмайып коюңуз. Бул күлкүлүү учурду Өсүү күндөлүгүнө жазып коюңуз.','Minu pesupäeva „aarded“ 🍝','Kas leidsid pesu pestes lapse taskust kuivanud makaroni või kivi? See pole kogumine, see on lapsepõlve avastusretk! Viska see tõsise näoga prügikasti, kuid naerata salaja oma väikesele kollektsionäärile. Pane see naljakas hetk kirja nende arengupäevikusse.'),
('3f11dc71-3a89-4499-8bac-19038f6fdeb4'::uuid,'Кызыктай коркуулар башталганда 🤖','Балаңыз күтүлбөгөн жерден ваннадагы суу агуучу тешиктен коркуп баштадыбы? Интернеттен оору издебеңиз. Anacan AI''дан сураңыз, бул куракка мүнөздүү эле фантазиядан улам келип чыккан убактылуу коркуу экенин билип, тынчтаныңыз.','Kui tekivad kummalised hirmud 🤖','Kas su lapsel on äkki tekkinud hirm vannitoa äravoolu ees? Ära otsi internetist haigusi. Küsi Anacan AI-lt ja saa teada, et see on täiesti normaalne ja mööduv foobia, mis tuleneb nende eakohasest kujutlusvõimest, ja vabane oma paanikast.'),
('51e9982e-8a0e-4e2c-9ee7-749ec67f6283'::uuid,'Өзүм жегим келет! 🥣','Балаңыз өзү жей алса да, сизден тамактандырууну талап кылып, анан кашыкты түртүп ыйлап жатабы? Алар өздөрү эмне каалап жатканын билишпейт! Тарелканы алдына коюп: «Ачка болгондо жейсиң» деп айтыңыз да, столдон алыстаңыз. Чындап ачка болгондо сөзсүз жейт.','Ma tahan ise süüa! 🥣','Kas su laps nõuab, et sina teda toidaksid, kuigi ta oskab ise süüa, ja siis lükkab lusika eemale ning nutab, kui proovid? Nad ei teagi ise, mida tahavad! Pane taldrik nende ette, ütle: ''Võid süüa, kui oled näljane,'' ja astu lauast eemale. Nad söövad, kui on tõeliselt näljased.'),
('cc8c59da-7b2e-4da4-87ec-e11a59ea5011'::uuid,'Өзүңүзгө бир аз убакыт бөлүңүз 💆‍♂️','Бала уктагандан кийин, жубайыңыздан 10 мүнөт ийиниңизди укалап коюусун сураныңыз. Күнү бою чуркап жүрүп моюнуңуз катып калгандыр! Сиздер жөн гана бир үйдө жашаган ата-эне эмес, бири-бириңиздердин эң жакын психологиялык тирегиңиздерсиз.','Võta aega iseendale 💆‍♂️','Pärast lapse uinumist palu kaaslaselt 10-minutilist õlamassaaži. Sinu kael peab terve päeva ringijooksmisest kange olema! Te ei ole lihtsalt vanemad, kes jagavad sama kodu; te olete üksteise lähim psühholoogiline tugi.'),
('68be8da2-a2bd-442f-bb8b-f854ddbaa84b'::uuid,'Instagram энелери жана реалдуулук 📱','Instagram''ды ачканда эле баарынын идеалдуу балдарын көрүп көңүлүңүз чөкпөсүн! Ал тиркемени жаап, Anacan коомчулугуна кириңиз. Башкалардын үйү да сиздики сыяктуу эле башаламан, балдары да ызы-чуу экенин көргөндө, сиздин кадимки эле эне экениңизди түшүнөсүз!','Instagrami emad vs. tegelikkus 📱','Ära lase end heidutada, kui näed Instagrami avades kõigi teiste täiuslikke lapsi! Pane see äpp kinni ja hüppa Anacani kogukonda. Kui näed, et ka teiste kodu on sama sassis kui sinu oma ja lapsed sama lärmakad, mõistad, et oled täiesti normaalne!'),
('9d186c69-6a80-405e-9b2f-01d72d720233'::uuid,'Саат боюнча уктоо ⏱️','Уктоо убактысы суу ичүү, дааратканага баруу жана дубалдар менен коштошуу өтүнүчтөрү менен созулуп жатабы? Телефонуңузга таймер коюп, эреже киргизиңиз: коңгуроо кагылганда баары жарыкты өчүрөт. Бул үндү укканда, алар эч кандай каршылыксыз эле төшөккө жатышат.','Magamaminek kella järgi ⏱️','Kas magamaminek venib lõputult vee, tualetipauside ja seintele head-ööd-ütlemistega? Pane telefonis taimer ja kehtesta reegel: kui kell heliseb, kustutavad kõik tuled. Kui nad seda heli kuulevad, lähevad nad voodisse ilma ühegi protestita.'),
('e4247830-a48b-4a17-9555-7ca391f03a7d'::uuid,'Төрт буттуу кичинекей дос 🐾','Балаңыз бүгүн эртең менен адам эмес, ит болуп сойлоп чыктыбы? Урушпаңыз же капа болбоңуз. «Азаматсың, менин акылдуу күчүгүм!» деп айтып, тамак бериңиз. Алардын ролдук оюндарына кошулуу талашып-тартышкандан алда канча аз күч талап кылат.','Neljajalgne väike sõber 🐾','Kas su laps roomas täna hommikul voodist välja nagu koer, mitte nagu laps? Ära tee märkusi ega pahanda. Ütle: ''Tubli, mu tark väike kutsikas!'' ja anna talle hommikusööki. Nende rollimängudega kaasa minemine säästab palju rohkem energiat kui vaidlemine.'),
('051e4221-4f19-4e4b-a097-d797006e0813'::uuid,'Тынчтыктын эң сонун көз ирмеми 🛋️','Балаңыз пазлдары менен алек болуп, үйдө күтүлбөгөн жерден тынчтык орнодубу? Шектенбеңиз, дароо өзүңүзгө кофе куюп алыңыз. Ал сейрек кездешүүчү алтын мүнөттөрдү тазалоого же кир жууганга эмес, жаныңызды эс алдырууга, жада калса жөн гана шыпты карап жатууга жумшаңыз. Сиз робот эмессиз.','Täiuslik vaikusehetk 🛋️','Kas su laps on nii süvenenud oma pusledesse, et majas valitseb äkiline vaikus? Ära ole kahtlustav, vala endale kohe kohvi. Veeda need haruldased kuldsed hetked mitte koristades või pesu pestes, vaid oma hinge puhates, isegi kui see tähendab lihtsalt lakke vahtimist. Sa ei ole robot.'),
('87efef38-8bd8-470c-82a9-956ee26f1fa2'::uuid,'Бул көйнөктүн этикеткасы кычыштырып жатат! 🏷️','Балаңыз кийиминин артындагы кичинекей белги ийнедей сайылып жатат деп кийүүдөн баш тартып жатабы? Бул курактагы сезгичтик адамды жинди кылышы мүмкүн! Талашпаңыз; кайчыны алып, аны кесип салыңыз, ошондо бул кичинекей көйгөй заматта чечилет.','See särgi silt sügeleb! 🏷️','Kas su laps keeldub midagi kandmast, sest see pisike silt seljal tundub nagu nõel? Sensoorne tundlikkus võib selles vanuses hulluks ajada! Ära isegi vaidle; haara käärid, lõika see maha ja lahenda see minikriis hetkega.'),
('a134dfa9-2e73-4246-a281-0577e4411534'::uuid,'Тамак менен ойноого уруксат бериңиз! 🥦','Тамагын кармалап, эзип, изилдеп көрүүсүнө уруксат бериңиз! Бул таттуу жана башаламан учурларды «Баланын сүрөт сессиясы» функциясы менен тартып алып, эстелик катары сактап калыңыз!','Lase neil toiduga mängida! 🥦','Lase neil toitu katsuda, muljuda ja avastada! Jäädvusta need armsad ja sassis hetked beebifotode funktsiooniga ja hoia need kallite mälestustena alles!'),
('d321475d-a2ef-4c95-8a95-ccdb6522c470'::uuid,'Таттуу түштөрдү шыбыроо 🤫','Төшөктөн чыгып, бөлмөдө чуркап, уктоодон баш тартып жатышабы? Кыйкырбаңыз. Тескерисинче, күтүлбөгөн жерден өтө жай, дээрлик шыбырап сүйлөп баштаңыз. Сизди түшүнүү үчүн алар аябай көңүл бурушу керек болот, ошондо мээси чарчап, автоматтык түрдө уйку режимине өтөт. Байкап көрүңүз!','Sosistades magusaid unenägusid 🤫','Kas nad ronivad voodist välja, jooksevad toas ringi ja keelduvad magamast? Ära karju. Selle asemel hakka äkki rääkima väga aeglaselt, peaaegu sosinal. Nad peavad sinust aru saamiseks nii palju keskenduma, et nende aju väsib ja lülitub automaatselt unerežiimile. Proovi järele!'),
('7e80987d-061d-4fcd-8171-45d84324b66e'::uuid,'«Муну оюнчук сындырды!» деген калп 🤷‍♂️','Атайылап суу төгүп жиберип, анан оюнчук машинасын көрсөтүп: «Бул мени түрттү!» деп жатабы? Бул калп эмес, бул табигый коргонуу механизми. Мээсин башка жакка буруу үчүн: «Кел, машинага кантип тазалоону үйрөтөлү!» деп сунуштаңыз.','Valetamine: „Minu mänguasi tegi katki!“ 🤷‍♂️','Kas nad ajasid tahtlikult vett maha, näitasid siis mänguauto peale ja väitsid: ''See lükkas mind!''? See pole valetamine; see on loomulik toimetulekumehhanism. Suuna nende aju osavalt ümber, pakkudes: ''Õpetame autole, kuidas koristada!'''),
('a3c5807d-b2c4-4369-a70a-3e8219c1c3ef'::uuid,'Экрандагы тынчтыктын көрсөткүчү 🤫','Акыры укташты! Үйдө кулак тундурган тынчтык орнодубу? Тиркемедеги «Үн өлчөгүчтү» ачыңыз. 0 децибелди көрүү чарчаган мээңиз үчүн эң мыкты визуалдык эс алуу болот.','Vaikuse skoor ekraanil 🤫','Nad on lõpuks magama jäänud! Kas majas on nii sügav vaikus, et kõrvus kumiseb? Ava äpis ''Mürataseme mõõtja''. Selle 0-detsibellise näidu jälgimine on parim visuaalne massaaž sinu väsinud ja mürast kurnatud ajule.'),
('c034d9ff-ba06-4346-b3af-4ee27df0fc64'::uuid,'Көрүнбөгөн жашылча миссиясы 🥦','Шорпосунан сабизди таап алып: «Мен муну жебейм!» деп жатабы? Тааныш көрүнүшпү? Жашылчаларды пюре кылып, соустарга кошуп жибериңиз; эми таап көрсүнчү! Тамак тандаган балаңызды ушундай жол менен алдап коюңуз.','Nähtamatu köögivilja missioon 🥦','Kas nad leidsid supist selle ühe porganditüki ja teatasid: ''Ma ei söö seda!''? Tuleb tuttav ette? Püreesta köögiviljad ja peida need kastmetesse; vaatame, kas nad suudavad need nüüd üles leida! Ole pirtsakast sööjast nutikam.'),
('3b221a5a-9106-4d1d-8e8e-3de653008273'::uuid,'Менин денем, бирок өзүмдүкү эместей 🔋','Кичинекейиңиз күнү бою бутуңузга жармашып, кучактап алууну суранып жатабы? Сиз физикалык жактан чарчадыңыз, «тийүүдөн чарчоо» (touch fatigue) сезими пайда болду. Аларды оюнчуктары менен бөлмөдө калтырып, ваннага 5 мүнөткө кирип, эшикти жаап алыңыз. Жалгыздыктын ошол көз ирмеминен ырахат алыңыз.','Minu keha, mitte päris minu oma 🔋','Kas su väike põnn ripub terve päeva su jala küljes ja nõuab pidevalt kaisutusi? Oled füüsiliselt kurnatud ja koged ''puudutusväsimust''. Jäta nad tuppa mänguasjadega, jookse 5 minutiks vannituppa ja pane uks kinni. Lihtsalt naudi seda üksinduse hetke.'),
('633ad245-30eb-4956-9f39-7177c312745a'::uuid,'Түн ичиндеги күтүүсүз ый 😭','Түн ортосунда көзү жабык бойдон ыйлап ойгонуп, сизди укпай жатабы? Бул түнкү коркунуч (night terror) болушу мүмкүн. Аны ойготпогонго аракет кылыңыз; жөн гана жанында туруп, колунан кармап, акырын сылап коюңуз. Алар өздөрү эле тынчтанып, терең уйкуга кетишет.','Äkiline kesköine nutt 😭','Kas nad ärkasid keset ööd nuttes, silmad kinni, ja tundus, et nad ei kuule sind? Analüüsi nuttu: see kõlab nagu öine hirmuhoog. Ära proovi neid äratada; seisa lihtsalt kõrval, hoia nende käest ja silitage seda õrnalt. Nad rahunevad ise ja vajuvad tagasi sügavasse unne.'),
('8febb55a-81bd-4c4c-969e-a2b64ee79f90'::uuid,'Ашканадагы жардамчынын кырсыгы 🧑‍🍳','Камыр жууруп жатсаңыз, балаңыз отургучту сүйрөп келип, унду өзү чачкысы келип жатабы? Жол бербесеңиз, ыйлайт. Ага кичинекей желим идиш жана бир аз ун бериңиз. Ашкана бир аз чачылышы мүмкүн, бирок ал олуттуу кичинекей ашпозчунун жүзүн көрүү тазалоо түйшүгүнө толугу менен арзыйт.','Köögis abistamise katastroof 🧑‍🍳','Kas rullisid tainast, kui laps tooli ligi vedas ja nõudis, et saaks ise jahu lisada? Kui sa ei luba, hakkab ta nutma. Anna talle väike plastkauss ja natuke jahu. Köök võib küll segamini minna, aga see tõsine väikese koka ilme on koristamist igati väärt.'),
('026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b'::uuid,'Эшикти мен ачам! 🚪','Үйдөн чыгып баратканда эшикти ачсаңыз, балаңыз ыйлап, кайра жаптырып, өзү ачкысы келдиби? Бул курактагы балдар үчүн көзөмөл кылуу – негизги психологиялык муктаждык. Убактыңыздын бир мүнөтүн «коромжу» кылууга жол бериңиз; бул сыртта 30 мүнөткө созулган ыйдын алдын алат.','Mina avan ukse! 🚪','Kas laps nuttis, kui sa ukse avasid, et välja minna, ja sundis sind uuesti kinni panema, et ta saaks ise avada? Kontrollivajadus on selles vanuses suur psühholoogiline vajadus. Luba tal oma aega minut ''raisata''; see hoiab ära 30-minutilise jonnihoo õues.'),
('9e3821dd-5beb-4da8-ba9b-4369b4836b0a'::uuid,'Дүкөндөгү текченин алдында катып калуу 🛒','Супермаркеттин ортосунда туруп, «Мен эмне үчүн келдим эле?» деп ойлонуп көрдүңүз беле? «Энелик мээ» – бул чындык, ал абдан алек! Тиркемедеги «Соода тизмесин» ачып, санариптик эс тутумга таянуу сизди ар дайым мындай башаламандыктан сактап калат.','Külmunud poe vahekäigus 🛒','Oled sa kunagi keset supermarketit seisnud ja mõelnud: mida ma siia üldse ostma tulin? Emme-aju on päriselt olemas ja see on täis! Rakenduse ostunimekirja avamine ja sellele digitaalsele mälule toetumine päästab sind alati sellest kaosest.'),
('c3a12f76-8197-4f4b-b339-db8bd083cf0a'::uuid,'Ваннадагы суу ташкыны! 🌊','Чоюнуу убактысы жөн гана шылтоо болуп, алар ваннада океан жаратып, толкундар менен ойноп жатышабы? Коё бериңиз! Суунун үнү жана чачырашы алардын чексиз, өжөр энергиясын жууп кетет. Кечинде алар эч каршылыксыз эле төшөккө жатышат.','Vannitoa uputus! 🌊','Kas vanniaeg on vaid ettekääne, tegelikult loob ta vannis ookeani ja mängib lainetega? Luba seda! Vee helid ja sulin pesevad maha kogu selle lõputu, kangekaelse energia. Õhtuks heidab ta voodisse ilma igasuguse vastupanuta.'),
('006ab58d-d1e7-4e1c-a78e-139ada266050'::uuid,'Тескери кийилген кийим менен сыймыктануу 👕','Көйнөгүн тескери кийип алып, оңдогонго такыр көнбөй жатышабы? Коё бериңиз! Алардын «Мен өзүм жасадым!» деген көз карашындагы өзүнө болгон ишеним туура кийингенден алда канча маанилүү. Бүт күн бою сыймыктануу менен ошентип жүрө берсин; бул алардын көз карандысыз тандоосу.','Uhke pahempidi särk 👕','Kas ta kannab särki pahupidi ja keeldub kategooriliselt seda parandamast? Luba seda! Enesekindlus, mis tema ''ma tegin ise!'' silmadest kiirgab, on palju tähtsam kui õigetpidi särk. Las ta jalutab uhkelt terve päeva nii ringi; see on tema iseseisev valik.'),
('a6797020-6e00-4e51-85e1-ce4c1dc47785'::uuid,'Апасынын үнү жетпей калганда, атасы жардамга келет! 🤡','Сиздин сөзүңүздү укпай, өжөрлөнүп жатышабы? Бирок атасы кирип келип, жаныбарлардын үнүн чыгарып, кызыктай бет маскарапоздуктарды жасаганда, алар дароо каткырып жиберишет. Кээде эркектердин логикасыз тамашалары чындап эле жардамга келет. Жөн гана четтен карап туруңуз.','Kui emme häälest ei piisa, on issi olemas! 🤡','Kas ta ignoreerib kõike, mida ütled, ja ajab jonni? Aga siis tuleb isa, teeb imelikke loomahelisid ja naljakaid nägusid ning laps puhkeb kohe naerma? Mõnikord päästab meeste ebaloogiline huumor tõesti päeva. Lihtsalt vaata kõrvalt.'),
('bf79338f-3f38-4811-b226-50574547225b'::uuid,'Кызыктай суроолорго жасалма интеллекттин жооптору 🤖','«Апа, түнкүсүн менин көлөкөм кайда кетет?» деп сураганда эмне дээриңизди билбей калдыңызбы? Ойдон чыгаруунун кажети жок. Anacan AI''ды ачып, алардын курагына ылайыктуу эң сыйкырдуу жана таттуу илимий жоопту алып, окуп бериңиз. Өзүңүздү улуу философтой сезесиз!','AI vastused kummalistele küsimustele 🤖','Kas jäid kangeks, kui küsiti: ''Emme, kuhu mu vari öösel kaob?'' Pole vaja midagi välja mõelda. Ava Anacan AI, saa lapse vanusele vastav kõige maagilisem ja armsam teaduslik vastus ning loe see talle ette. Tunned end kui suur filosoof!'),
('50a90b1b-61b0-4de1-8146-038e23b46eb9'::uuid,'Ачуумду жазуу менен чыгаруу 📝','Үйдөгү чарчаганыңызды эч ким байкабаганы сизди кыжырдантабы? Маанай күндөлүгүңүздү ачыңыз. Бүгүн сизди эмне кыжырдантып жатса, баарын жазыңыз. Эмоцияңызды кабыл алып, жазып коюу жасалма жылмайгандан көрө сизге көбүрөөк жардам берет.','Oma viha välja kirjutamine 📝','Kas ajab närvi, et keegi ei paista märkavat, kui kurnatud sa kodus oled? Ava oma meeleolupäevik. Kirjuta üles kõik, mis sind täna marru ajab. Emotsioonide aktsepteerimine ja kirjapanek aitab sind rohkem kui teeseldud naeratus.'),
('86283ea0-922f-4b91-8fed-55bf6231330d'::uuid,'Жансыз нерселер менен узак маектешүү 🗣️','Алар парктагы таш же үйдөгү отургуч менен олуттуу сүйлөшүп жатышабы? Алар элестетүү оюну аркылуу дүйнөнү жана эрежелерди үйрөнүп жатышат.','Pikad vestlused elutute esemetega 🗣️','Kas ta räägib tõsimeeli pargis kiviga või kodus tooliga? Ta õpib kujutlusmängu kaudu maailma ja reegleid tundma.'),
('b3273f0d-ec07-48f9-82e7-89e57daaf623'::uuid,'Бүгүн кечинде кучакташып эле жаталы 🫂','Бүгүн кечинде оюндардын же ызы-чуулуу китептердин кереги жок. Жөн гана аларды кучагыңызга кысып, ымыркайдын таза, жагымдуу жытын терең дем алып, караңгыда алардын канчалык баалуу экенин шыбырап айтыңыз. Экөөңүзгө тең ушул жетиштүү.','Täna õhtul lihtsalt kaisutame 🫂','Täna pole mänge ega lärmakaid raamatuid vaja. Lihtsalt hoia teda tihedalt vastu rinda, hinga sügavalt sisse seda puhast, magusat beebilõhna ja sosista pimeduses, kui uskumatult kallis ta on. See on kõik, mida te mõlemad vajate.'),
('113aa528-0657-4840-905d-63eec2aa048b'::uuid,'Мен билем, сага да үйрөтөм! ☝️','Алар сиз билген нерсени өтө олуттуу жана акылдуу түрдө түшүндүрүп жатышабы? Алар өз интеллектин сынап жатышат! Күлүп жибербөө үчүн эриниңизди тиштеп, бирок кунт коюп угуп, «Чын элеби? Чоң рахмат!» деп жооп бериңиз.','Ma tean ja õpetan sind ka! ☝️','Kas ta seletab sulle väga tõsise ja aruka ilmega midagi, mida sa juba tead? Ta katsetab oma intellekti! Hammusta huulde, et naeru tagasi hoida, aga kuula tähelepanelikult ja vasta: ''Tõesti? Suur aitäh sulle!'''),
('70129896-2f43-4370-bbff-f84bbbb58845'::uuid,'Атасынын жомокту чаташтырышы 📖','Бүгүн кечинде үнүңүз эс алсын. Жомок китебин атасына бериңиз. Ал жомокту атайылап тескери айтып, кызыктуу жана күлкүлүү кылсын. Анан балаңыздын аны оңдоп, каткырып жатканын кубануу менен четтен карап туруңуз.','Issi sassis unejutt 📖','Täna on su hääl vaba. Anna juturaamat isale. Las ta räägib lugu meelega tagurpidi, tehes seda naljakaks ja absurdseks. Seejärel vaata rõõmuga kõrvalt, kuidas laps naudib tema parandamist ja puhkeb naerma.'),
('e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a'::uuid,'Алгач оюн, анан тазалык 🎨','Алар бөлмөнүн ортосуна күкүмдөрдөн шедевр жаратып, тазалатпай жатышабы? «Тазалыкка болгон талабыңызды» бир четке коюңуз. Алардын жараткан кооз башаламандыгына тийбеңиз; тазалоо эртеңге чейин күтө турат. Үйүңүз музей эмес.','Esmalt mäng, siis koristus 🎨','Kas ta tegi keset tuba purudest meistriteose ja ei luba sul seda koristada? Pane oma ''koristusmaania'' kõrvale. Ära puutu seda kaunist kaost; koristamine võib oodata homseni. Sinu kodu pole muuseum.'),
('4501063e-24e5-4f32-a723-396adeab0d2a'::uuid,'Мультфильмди сага кайра айтып берүү 📺','Алар көргөн мультфильмин таптакыр башка логика менен айтып берип, ким кайда барганын олуттуу түшүндүрүп жатышабы? Ар бир сөзүнө ишенгендей болуп кунт коюп угуңуз. Алар өздөрүн дүйнөдөгү эң акылдуу жана күчтүү адамдай сезишсин.','Multika ümberjutustamine sulle 📺','Kas ta jutustab multikat, mida vaatas, täiesti teistsuguse loogikaga, seletades tõsiselt, kes kuhu läks? Kuula tähelepanelikult, nagu usuksid iga sõna. Lase tal tunda end maailma kõige targema ja tugevama inimesena.'),
('68a8ce66-c86f-4596-b8d3-b0d44f55a37d'::uuid,'Дүкөндөгү коркунучтуу «Алып бер!» талабы 🛒','Кассанын алдында шоколад деп кыйкырып жатышабы? Артыңыздагылардын караганына карабай, көнбөңүз. Соода тизмеңизди ачып: «Бул жерде жок экен, сканер окубай жатат» деп айтыңыз. Тышкы бийлик өкүлү аларга ар дайым ишенимдүүрөөк сезилет.','Kardetud „Ma tahan seda!“ poes 🛒','Kas ta karjub kassas šokolaadi järele? Ära anna järele, hoolimata seljatagustest pilkudest. Ava oma ostunimekiri ja ütle: ''Seda siin pole, skanner ei loe seda.'' Väline autoriteet tundub neile alati veenvam.'),
('7a348b09-00b7-46e1-8565-808daca1314c'::uuid,'Күндүн чарчоосун жууп салуу 🛀','Кээде эч нерсе жардам бербейт, алар баарына ыйлай беришет. Аларды жылуу сууга түшүрүңүз. Суунун чыңалууну басуучу сыйкырдуу күчү бөлмөгө жана алардын нерв системасына дароо терең тынчтык алып келет. Байкап көрүңүз.','Päevaväsimuse mahapesemine 🛀','Mõnikord ei aita miski ja ta nutab kõige pärast. Pane ta sooja vanni. Vee müstiline, pinget maandav jõud toob hetkega sügava rahu nii tuppa kui ka lapse närvisüsteemi. Proovi järele.'),
('1d8c6250-cd7d-4c49-8588-80172d7ce7fd'::uuid,'Терезеден аба ырайын болжолдоо ⛅','Күн ачык, бирок катуу шамал болуп жатабы? Эгерде аба ырайы жана кийим тандоо куралы катмарлап кийиниңиз десе, ага ишениңиз. Эшиктин алдында экиленип, нааразы болгондун ордуна, туура кийимди тандап, ыңгайлуу чыгып кетиңиз.','Ilma ennustamine aknast ⛅','Päike paistab, aga tuul on tugev? Kui ilma ja riietuse tööriist soovitab kihiti riietuda, usalda seda. Selle asemel, et uksel kõhelda ja nuriseda, vali õige riietus ja suundu mugavalt välja.'),
('78e7980c-5a72-49e5-bf40-4486d421427a'::uuid,'Алар тамагын бөлүшпөйт 🍳','Өз табагынан бөлүшпөй, сиздикинен жегиси келип жатабы? Балдар ар дайым ата-энесинин тандоосуна ишенишет. Буга каршы чыкпаңыз; сүйүү менен бир тиштем берип, алардын бул таттуу эгоцентризмине жылмайып коюңуз.','Nad ei taha oma toitu jagada 🍳','Ta ei taha oma taldrikult jagada, aga nõuab, et saaks süüa sinu omalt? Lapsed usaldavad alati pimesi vanemate valikuid. Ära võitle sellega; anna talle armastusega amps ja naerata sellele armsale egotsentrismile.'),
('bdc2de1f-725b-4742-942a-3e8bf91a38f3'::uuid,'Менин окуям, менин эрежелерим 📖','Жомок окуп жатып ката кетирсеңиз, алар дароо оңдоштубу? Демек, алар аны жаттап алышыптыр! Китепти жаап: «Бүгүн сен мага окуп бер» деңиз. Сиз жөн гана жатып, алардын таттуу үнүн угуп жатканда, алардын фантазиясы канат жайсын.','Minu lugu, minu reeglid 📖','Kas tegid lugedes vea ja ta parandas sind kohe? See tähendab, et ta on loo pähe õppinud! Pane raamat kinni ja ütle: ''Täna loed sina mulle.'' Lase tema kujutlusvõimel lennata, samal ajal kui sina lihtsalt lamad ja kuulad tema armsat häält.'),
('02c28ca2-9054-4fe0-ba4f-902da3aebfad'::uuid,'Мунараны куруп, кайра кулатуу 🧱','Алар кубиктерден мунараны кыйналып куруп, анан кубаныч менен кулатып салыштыбы? Сиз аракеттерине бооруңуз оорушу мүмкүн, бирок алар физиканы жана себеп-натыйжа байланышын үйрөнүп жатышат. Бул «кыйроолор» мээсинде жаңы байланыштарды түзүүдө, андыктан капа болбоңуз.','Ehita torn ja lükka see ümber 🧱','Kas ta ehitas vaevaliselt klotsidest torni, et see siis rõõmsalt ümber lükata? Kuigi sul võib vaevast kahju olla, õpib ta tegelikult füüsikat ja põhjus-tagajärg seoseid. Need ''hävitustööd'' on uued ühendused tema ajus, nii et ära pahanda.'),
('380dd8d0-d6f8-457c-b025-9b12f69938f2'::uuid,'Түшкү тамагым кайда? 🥗','Балаңызга жашылчага бай атайын табак даярдап жатып, өзүңүз кургак нан жеп жатасызбы? Токтотуңуз! Тамактануу планындагы апалар үчүн 5 мүнөттүк жеңил салатты жасаңыз жана акыры, бул үй-бүлөнүн негизги кыймылдаткычын (өзүңүздү!) кубаттоону унутпаңыз. Сиз маанилүүсүз.','Kus on mu lõunasöök? 🥗','Kas valmistad lapsele erilist köögiviljataldrikut, samal ajal kui ise näksid kuiva leiba? Peatu! Tee toitumiskavast see lihtne 5-minutiline salat emadele ja ära unusta lõpuks selle majapidamise peamootorit (ennast!) laadida. Sina oled tähtis.'),
('44db284c-e980-4095-8376-f1dcb5c24c8a'::uuid,'Жарыкты өчүрөбүз, уктоо убактысы 🌙','Уктаардан бир саат мурун бөлмөдөгү бардык жарыкты жана телевизорду өчүрүңүз. Бөлмө караңгылаганда, алар автоматтык түрдө эстей башташат. Ушундай жол менен сиз мелатонинди (уйку гормонун) табигый түрдө иштетип, өз ишиңизди жеңилдетесиз.','Tuled kustu, aeg magama minna 🌙','Tund enne magamaminekut lülita toas välja kõik eredad tuled ja teler. Kui tuba hämardub, hakkab ta automaatselt haigutama. Nii käivitad märkamatult ja loomulikult melatoniini (unehormooni) tootmise, mis teeb su töö palju lihtsamaks.'),
('63fa1eaa-e73f-4258-a342-669de7f7f892'::uuid,'Тартылуу күчү жеңди: Кечки тамак полдо 🍝','Алар атайылап тамакты жерге ыргытып, анан карап туруштубу? Кыйкырбаңыз; алар сизди тажаткысы келген жок, тескерисинче, тартылуу күчүн сынап жатышат. Табакты тынч алып коюңуз; сабакты кийинчерээк үйрөтөсүз.','Gravitatsioon võitis: õhtusöök põrandal 🍝','Kas ta viskas meelega toitu põrandale ja jälgis seda? Ära karju; ta ei ürita sind ärritada, vaid katsetab gravitatsiooni. Võta taldrik rahulikult ära; õppetunni saad anda hiljem.'),
('6e8cabf6-04bc-4e0f-a26d-cdeb494389a5'::uuid,'Мени Бэтмен деп атагыла! 🦇','Ойгонуп алып, өз атын тааныбай, башка ат менен чакырууну талап кылыштыбы? Кошулуңуз! 5 мүнөттүн ичинде бөлмөдөгү чыңалууну: «Мына, Бэтмен, боткоңду же!» деп тамашага айлантыңыз.','Kutsu mind Batmaniks! 🦇','Ta ärkas ja keeldus oma nimest, nõudes, et teda kutsutaks teisiti? Mängi kaasa! Muuda 5 minutiga toa pinge komöödiaks, öeldes: ''Palun väga, Batman, söö oma putru!'''),
('b81a0aff-ac53-43cf-bdca-b8bf4192300e'::uuid,'Пижаманын резинкасы менен болгон көйгөйлөр 👖','Пижамасы тар болуп жатат деп кыйкырып жатышабы (чындыгында алар чоң болсо да!)? Алардын сезгичтиги ойноп жатат. «Күтө тур, чоюлуп кетиши үчүн сыйкырдуу сөз айтайын» деп, пижаманы тартып көрүңүз. Алар ишенишет!','Püksikummide mured 👖','Ta karjub, et pidžaama on liiga kitsas (kuigi see on peaaegu seljast kukkumas!). Tema sensoorne tundlikkus on mängus. Ütle: ''Oota, ma loen võlusõnad, et see veniks,'' ja tee nägu, nagu venitaksid pidžaamat. Ta usub seda!'),
('070422be-d317-4a23-a559-6432c6ae63ed'::uuid,'Көзүмдү жумсам, жок болуп кетем 👀','Көзүн ирмебей, көзүнөн жаш чыкканча туруштук берип жатышабы? Баланын мээси түшүнүксүз коркууларды ойлоп табат. Бул коркууну: «Карачы, мен көзүмдү жумуп койдум, бирок дагы эле ушул жердемин!» деп оюнга айлантыңыз.','Kui ma silmad kinni panen, siis ma kadusin 👀','Kas ta üritab mitte pilgutada ja punnib, kuni silmad vett jooksevad? Lapse aju mõtleb välja seletamatuid hirme. Muuda see absurdne hirm mänguks, öeldes: ''Vaata, ma panin silmad kinni ja olen ikka siin!'''),
('652ec194-fa0e-4ca8-ab49-626452c474ad'::uuid,'Мага тийбе, ысып кеттим 🛑','Күтүлбөгөн жерден кучактаганыңыздан баш тартыштыбы? Таарынбаңыз! Алар жеке чек араларын сынап, денеси бир гана өзүнө таандык экенин үйрөнүп жатышат. Бул көз карандысыздыктын белгиси; аларды алыстан сыймыктануу менен карап туруңуз.','Ära puutu mind, mul on liiga palav 🛑','Kas ta keeldus äkki su kallistusest? Ära solvu! Ta katsetab oma isiklikke piire ja õpib, et tema keha kuulub ainult talle. See on iseseisvuse märk; vaata teda eemalt uhkusega.'),
('c7f18643-0c26-48a6-bc85-4480566ce781'::uuid,'Креслонун астында уктоо 🛋️','Төшөгүнөн баш тартып, креслонун астына кирип уктап калыштыбы? Аларды мажбурлап чыгарбаңыз же ойготпоңуз! Өзүнүн уникалдуу, корголгон мейкиндигинде уктоонун ырахатын алышсын, сиз болсо эс алыңыз.','Uinak tugitooli all 🛋️','Kas ta hülgas oma voodi ja keeras magama tugitooli alla? Ära sunni teda välja ega ärata! Luba tal nautida mugavust magada oma ainulaadses, kaitstud kohas, ja sina saad puhata.'),
('f998fac0-0a6b-42d2-b200-7a956f147c9a'::uuid,'Атасынын кезеги 👨‍🍼','Бүгүн кечинде баланы жуунтуп, уктоого даярдоо атасынын милдети.','Issi kord 👨‍🍼','Täna on isa kord beebit vannitada ja magamaminekuks valmis seada.'),
('9b33bb20-6873-451a-abe7-084cc34eff93'::uuid,'Сиздер чыныгы командасыздар! 🌟','Ар бир ишенимдүү кадам – бул өнөктөшүңүз экөөңүздүн биргелешкен аракетиңиздин натыйжасы.','Te olete tõeline meeskond! 🌟','Iga enesekindel samm on teie ja partneri ühiste jõupingutuste tulemus.'),
('1fe87964-746d-4cf2-a7f3-21730045a9ae'::uuid,'Эмне үчүн ботком ысык? 🥣','Жылуу болбосо жебейм деп, анан жылуу болсо ыйлап жатышабы? Жеңишсиз кырдаал! Ага атайылап түстүү муз кесегин таштаңыз; ал дароо алардын көңүлүн буруп, тынчтандырат.','Miks mu puder on kuum? 🥣','Ta ei söö, kui pole piisavalt soe, aga nüüd nutab, sest ON soe? Olukord, kus võita pole võimalik! Viska sinna meelega värviline jääkuubik; see köidab kohe tema tähelepanu ja rahustab ta maha.'),
('8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93'::uuid,'Жабык эшиктин артында ыйлоо 🚪','Эшикти жаап алып, бөлмөсүндө жалгыз ыйлап жатышабы? Аларды кучактоого мажбурлабаңыз. Кээде балдарга өз сезимдери менен жалгыз калуу керек болот. Аларга убакыт жана мейкиндик бериңиз.','Nutmine suletud uste taga 🚪','Kas nad panid ukse kinni ja nutavad oma toas üksi, ega taha sind sinna? Ära sunni neid kallistama. Mõnikord peavad lapsed oma emotsioone üksi läbi elama. Anna neile aega ja ruumi.'),
('f52f2ceb-159e-4eff-95c6-70eae6ed7217'::uuid,'Китеп желмогузуна таарынуу 🐺','Китептеги желмогузду муштап, урушуп жатышабы? Алардын фантазиясы укмуш! Чындыгын бузбастан, ''Сен мени коргодуң, кандай эр жүрөксүң!'' деп мактап, ишенимин арттырыңыз.','Vihane raamatukoletise peale 🐺','Kas nad löövad ja sõimavad raamatus olevat koletist? Nende kujutlusvõime on imeline! Ilma nende reaalsust lõhkumata tõsta nende enesekindlust, öeldes: ''Sa kaitsesid mind, sa oled nii julge!'''),
('3c299611-0f24-405d-b774-857cf09c273e'::uuid,'Байпагымды кийгизбе! Өзүм кийем! 🧦','Кылган ишиңиздин баарына каршы чыгып жатышабы? Эң сонун! Кийимдерин диванга коюп: ''Ким биринчи кийинет экен?'' деп таймашыңыз. Алар секунданын ичинде даяр болушат.','Ära pane mulle sokke jalga! Ma saan ise! 🧦','Kas nad keelduvad resoluutselt kõigest, mida sa teed? Ideaalne! Pane riided diivanile ja esita neile väljakutse: ''Kes saab enne riidesse?'' Nad on sekunditega valmis.'),
('3d738e03-bc77-4be0-b44b-95ecf5e6cdb0'::uuid,'Стол астындагы философия 🤔','Балаңыз столдун астына кирип алып, жомок ойлоп таап, ал жерден сиз менен сүйлөшүп жатабы? Ал кичинекей философту өзүнүн кыялкеч дүйнөсүндө калтырыңыз, ал эми бул убакытты өзүңүз эс алууга жумшаңыз.','Laua-alune filosoofia 🤔','Kas su laps on laua all, mõtleb lugusid välja ja räägib sealt sinuga? Lase sel väikesel filosoofil oma kujutlusmaailmas püsida ja kasuta seda aega iseenda lõõgastamiseks.'),
('b5d5bf11-5ce6-464a-892e-f00915b62103'::uuid,'Журкулдаган жууркан 🛌','Журкулдаган жууркандын айынан уктай албай жатышабы? Шылтоолору чегине жетти. Аларды жеңил жууркан менен жаап коюңуз; сиз баарына чечим таба аларыңызды көрүп, уйкуга моюн сунушат.','Tekikoti sahin 🛌','Nad ei saa magada, sest tekk krabiseb! Kummalised vabandused on haripunktis. Kata nad kerge tekiga; nad näevad, et oled kõigele lahenduse leidnud ja alistuvad unele.'),
('553ac831-9d91-4727-b2a6-83bd86e98633'::uuid,'Жаздыгым такыр туура эмес! 🛏️','Жаздыгын миллиметрге чейин тууралашыңыз керек деп ыйлап жатышабы? Бул алардын идеалга умтулуусу! Алардын айтканына көнүп, жаздыкты сызгыч менен ченегендей кылып тууралап, анан жарыкты өчүрүңүз.','Mu padi on täiesti vale! 🛏️','Kas nad nutavad, sest padi vajab millimeetri täpsusega kohendamist? See on nende täiuslikkuse otsing! Mine vooluga kaasa, kohenda patja nagu joonlauaga mõõtes ja kustuta siis kindlalt tuled.'),
('895f4c44-bb71-4d9f-917c-8dc75b779cc8'::uuid,'Үйдөгү жымжырттыктан чочулоо 🚪','Үйдө күтүлбөгөн жерден жымжырттык орнодубу? Издөөгө чыгыңыз, балким алар эшиктин артында кыялданып отурушкандыр. Кабатыр болбоңуз; алар ызы-чуудан алыстап, эс алып жатышат. Бул убакытты аларга бериңиз.','Vaikuse paanika kodus 🚪','Kas majas läks äkki liiga vaikseks? Mine otsima ja tõenäoliselt leiad nad ukse taga unistamast. Ära muretse; nad lihtsalt tõmbuvad mürast eemale, et end taastada. Anna neile see aeg.'),
('fceb9d37-669a-42ac-ae17-36b46f1fa546'::uuid,'Сынган печенье драмасы 🍪','Печенье экиге бөлүнүп калганы үчүн трагедия болуп жатабы? Аны кайра чаптай албайсыз. Тескерисинче, аларды математикага жана бөлүшүүгө тартыңыз: ''Карачы, эми экөөбүздө тең бар! Бири мага, бири сага!''','Katkise küpsise draama 🍪','Küpsis murdus pooleks ja see on katastroof? Sa ei saa seda tagasi kleepida. Selle asemel kaasa nad matemaatikasse ja jagamisse, öeldes: ''Vaata, nüüd on meil kaks! Üks mulle, üks sulle!'''),
('7871e777-44f4-425d-a10e-dda0547ccfc1'::uuid,'Балмуздак «уктап калды» (эрип кетти) 🍦','Түшүндө балмуздак жеп жатып, ойготуп койгонуңуз үчүн сизге капа болуп жатышабы? Кичинекейлер үчүн түш менен чындык көп учурда аралашып кетет. Ал капа болгон бетти кучактап, күлүп коюңуз; эки мүнөттөн кийин чындыкка кайтып келишет.','Jäätis jäi magama (sulas ära) 🍦','Kas nad sõid unes jäätist ja said su peale pahaseks, et sa nad üles äratasid? Unenäod ja reaalsus segunevad väikelastel sageli. Kallista seda pahurat nägu ja naera; nad naasevad reaalsusesse kahe minutiga.'),
('94d22bcb-5e09-49a0-bea6-432b56a92308'::uuid,'Суу бөтөлкөсүнүн түсү боюнча талаш 🚰','Түнкүсүн суу ичкиси келип, бирок кызыл чөйчөктөн ичпей жатышабы? Түн ортосунда логика издеп же акыл үйрөтпөңүз. Жөн гана чөйчөктү дароо алмаштырып, күчүңүздү эртеңкиге жана тынчтыкка сактап калыңыз.','Veepudeli värvi vaidlus 🚰','Nad tahavad öösel vett, aga mitte punasest tassist? Ära proovi keset ööd loogikat otsida ega neile loengut pidada. Vaheta lihtsalt tass kohe ära ja hoia oma energiat hommikuks ja rahuks.'),
('c160b0b4-c39a-4e5d-bbc5-111f29e33385'::uuid,'«Бут кийимдеги таш» сезими 👟','Бут кийиминде таш барбы деп он жолу чечтирип, бирок эч нерсе таппай жатасызбы? Тааныш көрүнүшпү? Кара так бар экен деп, ''Карачы, таптым, эми баары жакшы!'' деп алдап коюп, сейилдөөнү улантыңыз.','„Kivi kingas“ tunne 👟','Kas nad panevad sind kümme korda kinga jalast võtma, et kivi kontrollida, ainult et ei leia midagi? Tundub tuttav? Tee nägu, et leidsid pisikese musta täpi, ütle ''Vaata, leidsin üles, nüüd oleme ohutus!'' ja jätka jalutuskäiku.'),
('56bcf6ad-42a4-41b4-a775-ca5dbc61f766'::uuid,'Ваннадагы козголоң 🛀','Сууга түшкүсү келбей жатабы? Ар түрдүү түстөгү чөйчөктөрдү, ал тургай ашканадагы пластик буюмдарды сууга ыргытыңыз. Суу коркунучтуу жерден кызыктуу оюн аянтчасына айланат.','Vanniskäigu mäss 🛀','Ei taha vette minna? Viska sisse erinevat värvi topse, isegi plastist kööginõusid. Vesi muutub hirmutavast kohast äkki lõbusaks tegevuskeskuseks.'),
('7f7bb774-fd67-46a5-93fe-c0a784ba9885'::uuid,'Мен ата болдум! 👔','Бүгүн эртең менен атасынын чоң бут кийимин кийип ишке баргысы келип жатабы? Аларды шаштырбаңыз! Эшикке чейин узатыңыз; лифтти көргөн замат күлүп кайра келишет.','Ma olen issi! 👔','Kas nad tahavad täna hommikul issi suurte kingadega tööle minna? Ära kiirusta neid! Saada nad ukseni; nad pööravad tõenäoliselt itsitades tagasi, niipea kui lifti märkavad.'),
('dbd02f3e-2d56-4baa-bc3c-93886c747027'::uuid,'0 децибелди издөө 🤫','Акыры укташты! Тиркемедеги Үн өлчөгүчтү (Sound Meter) ачып, экрандын түбүнө түшкөн абсолюттук жымжырттыкты байкаңыз. Бул визуалдык тынчтык чарчаган мээңизди чыныгы спа сыяктуу эс алдырат.','0 detsibelli jaht 🤫','Nad on lõpuks magama jäänud! Ava rakenduses Helimõõtja ja vaata, kuidas see täielik vaikus ekraani põhja vajub. See visuaalne vaikus masseerib su väsinud aju nagu tõeline spaa.'),
('1c6686dd-4008-4750-acaf-4155c3330cdd'::uuid,'Дарак жалбырактарын төккөндө 🍂','Жердеги жалбырак үчүн даракка капа болуп, аны урушуп жатышабы? Алардын жаратылыш менен болгон байланышы ушунчалык таза жана күлкүлүү!','Kui puu ajab lehti 🍂','Kas nad on puu peale pahased ja sõimavad seda maas oleva lehe pärast? Nende side loodusega on nii puhas ja imeliselt koomiline!'),
('806ceb98-90c4-4de6-a42b-37c72e8d03ae'::uuid,'Менин көлөкөм алдымда жүрөт 👻','Көлөкөсү алдыда болуп калганы үчүн көчөдө ыйлап жатышабы? Аларды көтөрүп алып: ''Карачы, көлөкөлөрүбүз эми чогуу!'' деңиз. Физиканы түшүндүрүүнүн ордуна, аларга мээрим жана коопсуздук сезимин бериңиз.','Minu vari käib minu ees 👻','Nutavad tänaval, sest nende vari on neist eespool? Võta nad sülle ja ütle: ''Vaata, meie varjud on nüüd koos!'' Füüsika selgitamise asemel paku neile lihtsalt lohutust ja turvatunnet.'),
('a0789257-db81-493e-9643-abeb1d193c59'::uuid,'Атамдын тамашалары 🤡','Атасы күлдүрүп, уктаар алдында ойготуп койсо, ачууланбаңыз. Ал шаңдуу күлкү балаңыздын күн бою топтогон стрессин толугу менен жок кылат. Шумдуктуу болушса да, мейли!','Issi naljakad naljad 🤡','Ära saa pahaseks, kui issi neid naerutab ja magamamineku ajal üles ajab. Need rõõmsad itsitamised nullivad täielikult kogu stressi, mida su laps on päeva jooksul kogunud. Lase neil lärmata!'),
('0879e029-e767-44f9-917b-506cde86d1a1'::uuid,'Жумуртканы ыйлатпайлы 🍳','Жумуртканы чакканыңызда ага боору ооруп, жебей жатышабы? Алардын боорукердиги чексиз! ''Эми ал сенин булчуңдарыңда жашап, сени күчтүү кылат!'' деген сыяктуу таттуу калптар менен кырдаалды сактап калыңыз.','Ärme pane muna nutma 🍳','Kas neil on kahju munast, kui sa selle katki lööd, ja nad keelduvad seda söömast? Nende empaatiavõime on piiritu! Päästa olukord armsate väikeste valedega, nagu ''Nüüd elab see su lihastes ja teeb sind tugevaks!'''),
('7338df78-5f1a-4db5-ae07-ccfc779e153a'::uuid,'Шыбырашуу оюну 🤫','Уктагысы келбей чуркап жатышабы? Үнүңүздү кескин басаңдатып, өтө акырын шыбыраңыз. Сизди угуу үчүн жакындашат, мээси чарчап, 5 мүнөттүн ичинде уйкуга моюн сунат.','Sosistamismäng 🤫','Ei taha magada ja jooksevad ringi? Langeta järsult häält ja sosista väga vaikselt. Nad kummarduvad lähemale, et sind kuulda, ja nende aju väsib ning alistub unele vaid 5 minutiga.'),
('b9a9483f-7511-4f19-847b-4d0786991104'::uuid,'Дененин шашылыш чакырыгы 🩸','Түшүнүксүз кыжырдануу жана чарчоого алдырбаңыз. Цикл календарыңызды текшериңиз; денеңиз сизге белги берип жаткан болушу мүмкүн. Өзүңүздү күнөөлөөнүн ордуна, ''Дени сак рецепттер'' бөлүмүнөн магнийге бай тамак менен эс алыңыз.','Keha kiire kutse 🩸','Ära alistu seletamatule ärrituvusele ja väsimusele. Kontrolli oma tsüklikalendrit; su keha võib sulle signaale saata. Selle asemel, et end süüdistada, lõõgastu magneesiumirikka suupistega jaotisest Tervislikud retseptid.'),
('1bf9463f-7457-4983-af0a-2e62627ce701'::uuid,'Кызыл түстөгү тамактар фазасы 🍅','Бүгүн ''кызыл'' күн! Балаңыз баары кызыл болушун каалап жатабы? Тамактануу планыңызды карап, бүгүн кызыл помидор же кулпунай сунуштаңыз. Бул сүйкүмдүү кылыкка жол бериңиз, ага каршы күрөшүүнүн кереги жок.','Punase toidu faas 🍅','On ''punane'' päev! Kas su väike laps küsib ainult punaseid asju? Kontrolli oma toitumiskava, paku täna punaseid tomateid või maasikaid. Lase sel armsal veidrusel olla, pole vaja selle vastu võidelda.'),
('73d3b07e-eaa0-4423-b3b3-a6fb8656c01c'::uuid,'Оюнчугум ооруп калды 🩺','Аюу оюнчугун ооруканага жаткырып коюштубу? Сиз да ооруңуз! Диванга жатып алып, 10 мүнөт сизге ''кароо'' жүргүзүүсүнө уруксат бериңиз; бул белиңизди эс алдыруу үчүн эң сонун шылтоо.','Minu mänguasi on haige 🩺','Kas nad panid oma kaisukaru haiglasse? Ole sina ka haige! Heida diivanile ja lase neil end 10 minutit ''uurida''; see on suurepärane vabandus, et su selg saaks puhata.'),
('ea408c5e-c419-4258-9053-eba96cea541e'::uuid,'«Мени менен укта» өтүнүчү 🫂','Жаныңызда уктоону талап кылып жатышабы? Бир түнгө эрежелерди бузуп, алардын жытын терең дем алып, жанында уктаңыз. Бул экөөңүздөр үчүн тең сүйүү терапиясы.','„Maga minuga“ palve 🫂','Kas nad nõuavad, et magaksid nende kõrval? Riku üheks ööks reegleid, hinga sügavalt sisse nende lõhna ja maga ka ise nende kõrval. See on armastusteraapia teile mõlemale.'),
('7d8bddb7-9260-4872-8287-e9bfde4a91d7'::uuid,'AI, мага жардам бер! 🤖','Балаңыздын тынбай берген ''эмне үчүн'' деген суроолору сизди чарчатып жатабы? Жөн гана Anacan AI''дан сураңыз! Ал 4 жашар бала үчүн эң илимий, сабырдуу жана таттуу жоопторду заматта түзүп, сизди жеңилдетет.','AI, aita mind! 🤖','Kas su lapse lõputu ''miks''-küsimuste voog väsitab sind? Küsi lihtsalt Anacan AI-lt! See suudab 4-aastasele hetkega koostada kõige teaduslikumad, kannatlikumad ja armsamad vastused, võttes sinult pinge maha.'),
('9135dd5f-177c-4a9d-97a6-1658abd0da9a'::uuid,'Күзгүдөн өзүмдү тааныбай калдым 🪞','Күзгүгө каранып, бет түзүлүшүн өзгөртүп, өзүнө ачууланып жатышабы? Алардын инсандыгы жана сезимдери калыптанып жатат. Алардын бул драмалык оюнун четтен тынч байкаңыз.','Ma ei tundnud end peeglist ära 🪞','Kas nad vaatavad peeglisse, muudavad näoilmeid ja saavad enda peale pahaseks? Nende identiteet ja emotsioonid arenevad. Jälgi vaikselt kõrvalt nende dramaatilist etteastet.'),
('a579865a-399f-44c5-a9b0-e44cc032ce14'::uuid,'Мен жомоктун бир бөлүгүмүн! 🪄','Уктаар алдындагы жомоктордо каармандын атын түз эле балаңыздын атына алмаштырыңыз. Жомоктогу каарман тез жана тил алчаак уктагандай эле, балаңыз да ошондой кылууга шыктанат.','Olen osa loost! 🪄','Nutikates unejuttudes asenda kangelase nimi otse oma lapse nimega. Kuna kangelane jääb loos kiiresti ja kuulekalt magama, tekib ka lapsel motivatsioon sama teha.'),
('2d3b049d-536d-441d-a015-9e7326fee52e'::uuid,'Дүкөндөгү ыйлоо 🛒','Дүкөнгө кирип, эмне алыш керек экенин унутуп калдыңызбы? Башаламандыктын ичинде соода тизмеңизди санарип сактабасаңыз, баарын унутуп каласыз. Ар дайым санарип эсиңизге ишениңиз!','Toidupoe jonnihoog 🛒','Astusid toidupoodi ja unustasid, mida vaja oli? Keset seda kaost, kui sa oma ostunimekirja digitaalselt ei pea, unustad kindlasti kõik. Usalda alati oma digitaalset mälu!'),
('47345c36-90d7-4e89-b816-0332dc1932ef'::uuid,'Түнкүсүн жылдыз саноо 🌟','Уктоочу бөлмөнүн шыбын карап, элестетилген жылдыздарды санап жатышабы? Санай беришсин. Алар онго жетпей эле терең уйкуга кетишет.','Tähtede lugemine öösel 🌟','Kas nad vaatavad magamistoa lakke ja loevad kujuteldavaid tähti? Lase neil lugeda. Nad on juba sügavasse unne vajunud, enne kui nad nende väljamõeldud tähtedega kümneni jõuavad.'),
('924a98d3-0af0-4add-81f0-0d94e1af83c6'::uuid,'Колум бутума айланып кетти! 🤸‍♂️','Колу менен басууга аракет кылып, оодарылып жатышабы? Чыгармачыл кыймыл-аракет жөндөмдөрү өнүгүп жатат! Үйдүн коопсуз жеринде аларга кичинекей тоскоолдуктар курсун түзүп бериңиз, энергиясын сарптасын.','Mu käed muutusid jalgadeks! 🤸‍♂️','Üritavad kätel kõndida ja kukuvad ümber? Loov motoorika areng on täies hoos! Sea neile maja turvalises kohas üles väike takistusrada, et nad saaksid selle energia välja elada.'),
('50f1584c-32c1-44e9-9ef5-89a70a2afc5e'::uuid,'Атамдын акырын кириши 👨‍🍼','Жомок окуп чарчап турган учурда, атасы акырын кирип, аларды сылап, сизге эс алууга белги бергени – бул ата-энеликтеги эң сонун командалык иш.','Issi vaikne sisenemine 👨‍🍼','Hetkel, kui oled unejutu lugemisest kurnatud, siseneb issi vaikselt tuppa, patsutab neid õrnalt ja annab sulle märku, et mine puhka. See on lapsevanemaks olemise ülim meeskonnatöö hetk.'),
('6694bf7a-8c8c-47c1-8991-2a84701c94f1'::uuid,'Бананды туура эмес аарчыдың! 🍌','Шылтоолордун падышасы! Бананды СИЗ аарчып койгонуңуз үчүн трагедия болдубу? Аларга жаңы банан бериңиз жана ортосунан сынса да, каалагандай аарчууга уруксат бериңиз, ошондо алардын өз алдынчалыгы бузулбайт.','Sa koorisid banaani valesti! 🍌','Vabanduste kuningas! See on katastroof, sest SINA koorisid banaani. Anna neile uus banaan ja lase neil seda koorida nii, nagu nad tahavad, isegi kui see tähendab selle keskelt murdmist, et nende iseseisvus ei kannataks.'),
('9aaf0e76-e78b-442f-afe1-7bb02c660da6'::uuid,'«Абдан ысык» козголоңу 🧥','Балаңыз көчөдө курткасын чечип, тоңуп калабы деп тынчсызданып жатасызбы? Каршы болбоңуз! Чындап суук болгондо, өздөрү сурашат. Табигый кесепеттерди сезүүгө мүмкүнчүлүк бериңиз.','„Liiga palav“ mäss 🧥','Kas su laps võtab keset tänavat jope seljast, jättes sind muretsema, et ta külmetub? Ära võitle sellega! Kui neil hakkab päriselt külm, küsivad nad seda ise. Lase neil kogeda loomulikke tagajärgi.'),
('02ff52cb-13af-47d3-83d9-4e3e21f04d45'::uuid,'Мен отургучмун! 🪑','Бир нерсени туурап, кыймылдабай туруп калыштыбы? Тамашалап үстүнө оюнчук коюп: ''Кандай сонун отургуч!'' деңиз. Алар бул кызыктуу ролду жактырып, тынч отурушат.','Ma olen tool! 🪑','Kas nad teesklevad, et on mingi ese, seistes täiesti liikumatult? Pane mänguliselt nende peale mänguasi ja ütle: ''Milline armas tool!'' Nad armastavad seda veidrat rolli ja püsivad vaikselt.'),
('50fd969e-9bd4-4e5e-8927-9b3b9067a4be'::uuid,'Коом мага эмне дейт 💬','Баарын туура эмес кылып жаткандай сезилип жатабы? Anacan Коомчулугуна кирип, башка энелердин тентек жана укмуштуу балдары жөнүндө окуяларды окуп, терең дем алыңыз, балким өз балаңыз үчүн ыраазы болосуз!','Mida ühiskond minult ootab 💬','Tunned, et teed kõike valesti? Hüppa Anacani kogukonda, loe lugusid teiste emade metsikutest ja imelistest lastest, hinga sügavalt sisse ja võib-olla leiad end omaenda väikese lapse eest tänulikuna!'),
('8d85cb27-805f-4ca6-a6a0-16122a07af20'::uuid,'Бөлмөнү караңгылатуу 🌙','Коридордон түшкөн жарыктан улам уктай албай жатышабы? Алар идеалдуулукту издеп жатышат. Эшикти бекем жаап, бөлмөнү толугу менен караңгылатыңыз, мелатонин өз ишин жасап, аларды уйкуга тартат.','Toa täielik pimendamine 🌙','Ei saa magada, sest esikust imbub valgust? Nad otsivad täiuslikkust. Sulge uks tihedalt, pimenda tuba täielikult ja lase melatoniinil teha oma loomulikku tööd, et nad unne suigutada.'),
('6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd'::uuid,'Көрүнбөгөн тактар менен күрөш 👕','Балаңыз шымдарындагы такты эч нерсе жок болсо да, тынчсызданып издеп жатабы? Оо, ал визуалдык кумарлар! Жөн гана нымдуу салфетка менен сүртүп, «баары кетип калды!» деп айтыңыз. Баланын акылы кичинекей эле иллюзияга ишенүүгө абдан даяр болот.','Nähtamatu pleki needus 👕','Kas su laps otsib meeleheitlikult pükstelt plekki, kuigi seal pole midagi? Ah, need visuaalsed kinnisideed! Tee lihtsalt nägu, et pühid seda niiske salvrätiga ja kuuluta: ''Kõik läinud!'' Lapse arukas meel usub imeliselt kergesti väikestesse illusioonidesse.'),
('7da643f9-a304-476b-9165-6028a945c141'::uuid,'Сиз сыртта калыңыз! 🛑','Ал сизден жанында эмес, эшиктин жанында, алыс отурууну талап кылып жатабы? Таарынбаңыз! Бул анын өз алдынча болууга жасаган чоң кадамы, андыктан ичиңизден кубанышыңыз керек.','Sina jääd välja! 🛑','Kas ta nõuab, et istuksid voodi kõrval asemel hoopis ukse juures? Ära solvu! See on suur samm iseseisvuse suunas ja peaksid selle üle salaja rõõmustama.'),
('b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba'::uuid,'Ал куш МЕНИКИ! 🐦','Балаңыз короодогу кушту үйгө алып киргиси келип ыйлап жатабы? Анын жаратылышка болгон сүйүүсү ашып-ташып жатат! Куштун апасы аны үйдө күтүп жатканы жөнүндө жомок ойлоп тапсаңыз, ал кризис дароо тынчтыкка айланат.','See lind on MINU oma! 🐦','Kas su väike põnn nutab, sest tahab õuest linnu tuppa tuua? Tema armastus looduse vastu on piiritu! Mõtle välja lugu sellest, kuidas linnu emme teda kodus ootab, ja see kriis laheneb silmapilkselt.'),
('544fb1ce-862b-49f6-8e2e-6b2192929ac3'::uuid,'Түнкү коркуу сезимдери башталды 👻','Ал керебеттин астындагы желмогуздан коркуп жатабы? Бош чачыраткыч бөтөлкөгө суу куюп, бөлмөгө «желмогузду куучу сыйкырдуу суу» катары чачыңыз. Ал коркуу бир нече секундда жоголот.','Õhtused hirmud algavad 👻','Kas ta kardab voodialust koletist? Täida tühi pihustipudel veega ja piserda seda tuppa kui ''maagilist koletisepeletajat''. Hirm kaob sekunditega.'),
('b51cc09c-00f6-4b63-945d-9cfceecedfb2'::uuid,'Тишимди манжам менен тазалайм! 🪥','Тиш щеткасынан баш тартып, сөөмөйү менен тазалагысы келип жатабы? Каршы болбоңуз! Бир аз тиш пастасы сүйкөлгөн таза сөөмөй да ишти бүтүрөт; чоң көйгөй жаратуунун кажети жок.','Harjan hambaid sõrmega! 🪥','Keeldub hambaharjast ja nõuab sõrmega pesemist? Ära vaidle! Puhas sõrm ja tilk hambapastat ajavad asja ära; pole vaja suurt tüli tekitada.'),
('e403fe31-012f-4f6b-80cb-45dd719c9f06'::uuid,'Менин жашыруун шоколад ырахатым 🍫','Балаңыз телевизорго алаксып жатканда, ашканада жашыруун шоколад жеп жатасызбы? Ар бир тиштеминен ырахат алыңыз! Күнүмдүк «кризистерден» кийин бул сиз үчүн табигый энергия булагы. Өзүңүздү күнөөлүү сезбеңиз!','Minu salajane šokolaadihetk 🍫','Kas näksid salaja köögis šokolaadi, samal ajal kui laps on telerisse süvenenud? Naudi iga suutäit! Pärast kõiki neid päevaseid ''kriise'' on see sinu loomulik energiaallikas. Ära tunne end süüdi!'),
('2d98107a-3331-4f7f-8930-8f762e325d02'::uuid,'Көйнөгүмдү тескери кийип алдым! 👕','Балаңыз көйнөгүн тескери кийип сыймыктанып жүрөбү? Түзөтпөңүз! Анын өзүнө болгон ишеними абдан жогору, жөн гана алыстан карап, бул эркин ой жүгүрткөн келечектеги лидер менен сыймыктаныңыз.','Särk on pahupidi seljas! 👕','Kas su laps kõnnib uhkelt ringi, särk pahupidi seljas? Ära paranda teda! Tema enesekindlus on nii kõrge – vaata teda eemalt ja tunne uhkust selle vaba vaimuga tulevase liidri üle.'),
('c5aa519b-baae-498e-a13b-bdf83115f0c9'::uuid,'Биздин унчукпай тиктешүүбүз 🥂','Бала уктап калды, сиз жана жолдошуңуз диванда бири-бириңизди унчукпай карап отурасыз. Сөздүн кереги жок. Бул жымжырттык — «Биз муну жасадык, дагы бир күндү аман-эсен өткөрдүк» деп айтуунун эң романтикалуу жолу.','Meie vaikne pilk 🥂','Beebi magab ja te partneriga vaatate diivanil vaikides teineteisele otsa. Sõnu pole vaja. See vaikus on kõige romantilisem viis öelda: ''Me saime hakkama, elasime veel ühe päeva üle.'''),
('eaade7fe-4846-47fa-9bc5-4c49360a0a4a'::uuid,'Мени шамал түрттү! 💨','Балаңыз сырттагы шамалга ачууланып, аны «ургулап» жатабы? Эгер аба ырайын жана кийим тандоо куралын алдын ала текшергениңизде, балким, сыртка чыкпайт белеңиз! Азырынча бул кичинекей комедияга күлүп, тез үйгө кирип кетиңиз.','Tuul lükkas mind! 💨','Kas su laps on väljas puhuva tuule peale maruvihane ja üritab seda ''lüüa''? Kui oleksid ilmaprognoosi ja riietumise tööriista varem vaadanud, poleks te võib-olla üldse välja läinud! Praegu aga naera selle väikese komöödia üle ja tee kiire spurt koju.'),
('77606aaa-e2aa-442d-992d-f4dce779d9e5'::uuid,'Полдогу көркөм өнөр шедеври 🎨','Ал бөлмөнүн ортосунда кургак макарондон шедевр жаратып, сизге сыймыктануу менен карап жатабы? Башаламандыкты унутуп, анын чыгармачылыгына жылмайып жооп бериңиз.','Põrandakunsti meistriteos 🎨','Kas ta tegi keset tuba kuivast pastast meistriteose ja vaatab sind nüüd tohutu uhkusega? Unusta hetkeks segadus ja naerata vastu tema loovusele.'),
('92c59586-e756-4176-87f0-6ee0836bd1f7'::uuid,'Атамдын жомок айтып берүүсү 📖','Үнүңүз чарчадыбы? Дагы бир жолу жомок окуп бергиңиз келбей жатабы? Кезекти атасына бериңиз! Анын өзгөчө, жоон үнү жана ойлоп тапкан кызыктуу деталдары балаңызды дароо арбап алат.','Issi unejutt 📖','Hääl väsinud? Ei jaksa enam unejuttu lugeda? Anna teatepulk üle issile! Tema eriline, sügav hääl ja kõik need fantaasiarikkad detailid, mida ta välja mõtleb, võluvad su väikese põnni hetkega.'),
('dc97d51e-f4af-4633-84e4-fbe0fbe9e15a'::uuid,'Чачым ооруп жатат! 🪮','Чач тараш чоң согушка айланып жатабы? Чачына бир аз суу чачып, күзгүдөн кызыктуу бет маскарапоздуктарды жасап алаксытыңыз. Көңүлү башка жакка бурулганда, тез тарап бүтүрүңүз.','Juuksed valutavad! 🪮','Kas juuste kammimine on eepiline lahing? Piserda juustele veidi vett ja hajuta tähelepanu, tehes peegli ees naljakaid nägusid. Kui tähelepanu on mujal, kammi kiirelt ja saa asjaga ühele poole.'),
('1752e8bc-24e4-4f1b-97e5-c557a4522bda'::uuid,'Асман кайда кетти? ☁️','Тумандуу аба ырайы тууралуу күтүүсүз суроосу сизди жоопсуз калтырдыбы? Ага булуттар суук болбосун деп жаап жатат деп айтыңыз. Анын мээси илимий түшүндүрмөгө даяр эмес, ал жөн гана жомок уккусу келет.','Kuhu taevas kadus? ☁️','Kas tema ootamatu filosoofiline küsimus uduse ilma kohta jättis su sõnatuks? Ütle talle, et pilved katavad ilma, et sellel külm ei hakkaks. Tema aju pole veel teaduslikuks selgituseks valmis; ta tahab lihtsalt lugu.'),
('2d5bfd88-008f-4b96-a72a-390cdfe7c90d'::uuid,'Дүкөн аралап тентип жүрүү','Кассада күтүүсүз чуркап кетип, текчелердин артына жашынып калдыбы? Соода тизмеңизди санарип сактаңыз, ошондо мындай дүрбөлөң учурунда эмне керек экенин унутуп, үйгө куру кол кайтпайсыз.','Seiklused poes','Jookseb kassas ootamatult minema ja peidab end riiulite taha? Hoia ostunimekirja digitaalsena, et sellises paanikas ei unustaks, mida vaja oli, ja koju tühjade kätega ei naaseks.'),
('5c94e9c6-00cb-4c58-b265-f248e6c3e544'::uuid,'Шыбырашуу оюну 🤫','Чуркап жүрүп, уктоодон баш тартып жатабы? Күтүүсүз жерден үнүңүздү дээрлик угулгус шыбырга чейин басаңдатыңыз. Сизди угуу үчүн ал кунт коюп тыңшашы керек болот, бул аны тез эле уйкуга тартат.','Sosistamismäng 🤫','Jookseb ringi ja võitleb uneajaga? Langeta järsku hääl peaaegu kuuldamatu sosinani. Ta peab sind kuulmiseks väga keskenduma, mis teeb ta kiiresti uniseks.'),
('22c6ff37-5069-489b-9d49-2a97d14d2e2e'::uuid,'Кемчиликсиз болбосо да болот 🛑','Бүгүн баары тескери кетип, кыйкырып жибердиңизби? Өзүңүздү жемелебеңиз. Жөн гана маанай күндөлүгүңүзгө: «Бүгүн оор болду, бирок мен жакшы энемин жана эртең дагы аракет кылам» деп жазып коюңуз.','Pole hullu, kui sa pole täiuslik 🛑','Kas täna läks kõik viltu ja sa karjusid? Ära piitsuta end. Kirjuta lihtsalt oma meeleolupäevikusse: ''Täna oli raske, aga olen hea ema ja proovin homme uuesti.'''),
('39a82edc-fce3-4cb5-8ef7-be6b2f9a1122'::uuid,'Жамгыр үнү коштогон жомок 🌧️','Үнүңүз чыкпай калдыбы? Жомок окууга чарчадыңызбы? Биздин акылдуу жомок функциябыздан жамгырдын жана токойдун жагымдуу үндөрүн коюп бериңиз. Жаратылыштын тынчтандыруучу үнү аны каалаган жомоктон да тез уктатышы мүмкүн.','Vihmahelide lugu 🌧️','Hääl kadunud? Liiga väsinud jutu lugemiseks? Meie nutikas jutuvestmise funktsioonis mängi taustaks õrna vihma- ja metsaheli. Looduse rahustav vaikus võib nad uinutada kiiremini kui ükski muinasjutt.'),
('69d7d720-ce5e-441e-ac6e-b3151e6557c4'::uuid,'Колумду кармаба! 🚶‍♂️','Ал колуңузду коё берип, көчөдө өз алдынча баскысы келеби? Эгер коопсуз жер болсо, анын өз алдынчалыгын сынап көрүүсүнө уруксат бериңиз. Жөн гана эки кадам артынан сыймыктануу менен ээрчип жүрүңүз.','Ära hoia mu käest kinni! 🚶‍♂️','Kas ta tahab su käest lahti lasta ja tänaval iseseisvalt kõndida? Kui piirkond on ohutu, lase tal oma iseseisvust katsetada. Käi lihtsalt kaks sammu tagapool ja sära uhkusest.'),
('1b495b8d-2c5f-47f5-aeda-e199006766ac'::uuid,'Денем эми меники эместей 🔋','Күнү бою балаңыз үстүңүзгө чыгып, денеңиз талып калдыбы? 5 мүнөткө балаңызды бөлмөсүндө коопсуз калтырып, эшикти жаап, көзүңүздү жумуп, терең дем алыңыз. Сизге сөзсүз түрдө эс алуу керек.','Mu keha pole enam minu oma 🔋','Kas su keha on kogu sellest otsas ronimisest kange ja väsinud? Jäta väike põnn 5 minutiks turvaliselt oma tuppa, pane uks kinni, sule silmad ja hinga sügavalt. Sa pead end laadima.'),
('81591bb3-d8f2-475d-b7fc-1bd47693b91f'::uuid,'Мени наристе деп атаба! 😤','Ал бөлмөдө эрежелерди орнотуп, «Мен чоңойдум!» деп жатабы? Ал өзүнүн жетилгенин далилдегиси келет. Анын өз алдынча болуу каалоосун «Макул, жаш айым/мырза» деп таанып, анын сый-урматына ээ болуңуз.','Ära kutsu mind beebiks! 😤','Kas ta kehtestab toas reegleid ja kuulutab: ''Olen nüüd suur inimene!''? Ta üritab tõestada, et on küpsenud. Tunnusta tema iseseisvussoovi, kutsudes teda ''Olgu, noor daam/härra'', ja võida tema austus.'),
('a65f1e7a-ca07-4462-bac0-1293b0e5896c'::uuid,'Менин санариптик тынч жайым 🤫','Үйдө тынчтык, бирок оюңуз дагы эле чарчап жатабы? Колдонмодогу үн өлчөгүчтү ачыңыз. Экрандагы «0 децибел» көрсөткүчүн карап отуруу сизге терапиядан да көбүрөөк жардам бериши мүмкүн. Байкап көрүңүз!','Minu vaikne digitaalne põgenemine 🤫','Majas on vaikne, aga mõtted ikka sumisevad? Ava äpis helimõõtja. Selle ''0 detsibelli'' näidu vaatamine ekraanil võib sind rahustada rohkem kui teraapiaseanss. Proovi järele!'),
('25ef7ba4-1698-4dbc-9412-9bb568472d80'::uuid,'Оюнчуктарын төшөгүнө жаткыруу 🧸','Балаңыз уктабай, оюнчуктарын кылдаттык менен жаткырып жатабы? Бул элестетүү оюну — анын уйкуга психикалык жактан даярдануусунун акылдуу жолу. Тоскоол болбоңуз, бул жакшы белги!','Mänguasjade voodisse panemine 🧸','Kas su väike põnn ei maga, vaid sätib usinalt mänguasju magama? See rollimäng on tegelikult nutikas viis end vaimselt uneks ette valmistada. Lase tal olla, see on hea märk!'),
('7626d265-88f4-40f1-a79c-e9d0f1238d73'::uuid,'Бирок эшикти мен ачкым келген! 🚪','Сиз ачкан эшикти кайра жаптырып, өзү ачкысы келип ыйлап жатабы? Бир мүнөт убакыт кетирсин, бул үйдөгү 20 мүнөттүк ыйды жана кыйкырыкты тынчтык жолу менен алдын алат.','Aga mina tahtsin ust avada! 🚪','Kas ta nutab ja sunnib sind ust uuesti sulgema vaid seetõttu, et *sina* selle avasid, nõudes, et ta teeks seda ise? Lase tal see minut võtta, see hoiab ära 20-minutilise jonnihoo ja karjumise.'),
('a5284401-af40-43a4-aa11-663792a88d21'::uuid,'Жашыл тамактар мезгили! 🥦','Ал тарелкасынан бир гана жашыл нерселерди издеп жатабы? Тамактануу планыңызды текшериңиз! Ар кандай чөптөрдөн жашыл жашылча топторун жасоону үйрөнүп, анын бул «жашыл» кумарын оюн түрүндө канааттандырыңыз.','Rohelise toidu faas! 🥦','Kas ta otsib taldrikult ainult rohelisi asju? Kontrolli toitumiskava! Õpi valmistama armsatest rohelistest köögiviljadest palle ja rahulda mänguliselt seda ''rohelist'' kinnisideed.'),
('27e63f29-b167-40b2-aa6b-8ed0d0329ca3'::uuid,'Нандын чети — душман! 🍞','Ал нандын ортосун гана жеп, четин таштап жатабы? Четтери үчүн урушпаңыз. Жаныбар формасындагы калыптарды колдонуп, чети жок фигураларды жасаңыз жана ал сиздин кулинардык дизайныңыздан ырахат алсын.','Koorikud on vaenlased! 🍞','Kas ta sööb ainult sisu ja viskab koorikud ära? Ära võitle äärte pärast. Kasuta loomakujulisi vorme, et teha koorikuvabu kujundeid, ja lase tal nautida sinu kulinaarset disaini.'),
('7c97a838-1745-4335-a86c-2bf011bb9f3b'::uuid,'Үйдөн чыгуудан баш тартуу ⛅','Төрт дубалдын арасында калып, балаңыз ыйлап, сыртка чыкпай жатабы? Аба ырайы жана кийим тандоо куралына ишенип, аны акырын сыртка чыгууга көндүрүңүз. Таза абаны жутканда эле, анын үйдөгү бардык капалыгы заматта тарап кетет!','Keeldumine kodust lahkuda ⛅','Kas seinad suruvad peale, aga laps nutab ja keeldub õue minemast? Usalda ilma ja riietumise tööriista ning meelita ta õrnalt välja, isegi kui see tundub sunnitud. Värsket õhku hingates kaob toas tekkinud tusatuju hetkega!'),
('f3fa598e-4bec-4396-a5cb-220c0c856d23'::uuid,'Атам менен пижамачан күрөшүү 🤼‍♂️','Уктоодон баш тартып жатабы? Атасы менен «дубал менен күрөшүү» оюнун ойнотуңуз, анда атасы «жеңилип» калсын. Балаңыз калган энергиясынын баарын сарптап, төшөккө чуркап барууга даяр болот.','Issiga pidžaamamaadlus 🤼‍♂️','Keeldub magamast? Lase issil temaga mängida ''seinamaadlust'', kus issi dramaatiliselt ''kaotab''. Su väike põnn kulutab kogu allesjäänud energia ja on valmis otse voodisse jooksma.'),
('2ab3a16c-8538-4df6-b8df-c031bc53d6c7'::uuid,'Коомчулуктан күч табуу 💬','Сабырыңыз түгөнүп баратканда, Anacan коомчулугуна кириңиз. Дал ушундай кооз башаламандыкты башынан кечирип жаткан башка энелерди көрүү сизге чоң жеңилдик жана «мен жалгыз эмесмин» деген сооронуч тартуулайт.','Jõu leidmine kogukonnast 💬','Kui kannatus on katkemas, sukeldu Anacani kogukonda. Teiste emade nägemine, kes navigeerivad samas kaunis kaoses, toob tohutu kergendustunde ja lohutava teadmise: ''Ma pole üksi.'''),
('5a8f1d52-e3d3-4c7e-b491-d2552a236831'::uuid,'Биз муну жасадык! 🚀','Үйдө акыры тынчтык орноду. Кийинки айда кандай башаламандык болбосун, сиз даярсыз — сиз бул иште адис болуп калдыңыз! Жарыкты өчүрүп, бүгүн жасаган кичинекей кереметтериңиз үчүн өзүңүзгө ыраазычылык билдириңиз.','Me saime hakkama! 🚀','Majas on lõpuks vaikne. Oled valmis igaks uueks kaoseks, mida järgmine kuu toob – oled selles proff! Kustuta tuled ja täna end kõigi nende väikeste imede eest, mida täna korda saatsid.'),
('83732257-57c8-43f0-99f6-cb1c1583874a'::uuid,'Ал көлөкө меники! 👻','Ал өзүнүн көлөкөсү менен сүйлөшүп, ага буйрук берип жатабы? Анын элестетүүсү чындап эле чексиз.','See vari on minu oma! 👻','Kas ta võtab oma varju omaks, räägib sellega ja annab juhiseid? Tema kujutlusvõimel pole tõesti piire.'),
('37af8066-a97d-4233-891d-9eb3a99e296b'::uuid,'Соода тизмесин бузуу 🛒','Азык-түлүк дүкөнүнө барардан мурун, колдонмодогу соода тизмеңизди ачып, «5 шоколад» сырдуу түрдө кошулганын көрдүңүзбү? Ооба, ал санариптик инфильтрациянын жана сиздин виртуалдык дүйнөңүздү көчүрүүнүн чебери болуп калган!','Ostunimekirja saboteerimine 🛒','Kas avasid enne poodi minekut äpis ostunimekirja ja avastasid, et sinna on salapäraselt lisatud ''5 šokolaadi''? Oh jah, ta on selgelt omandanud digitaalse imbumise ja sinu virtuaalmaailma kopeerimise kunsti!'),
('709311bc-b001-46b6-bc4d-6ad222fa6ef4'::uuid,'Бүтүн алма драмасы 🍏','Алманы кескенде бөлмөдө ый чыктыбы? «Мен аны бүтүн каалагам!» деп ыйлап жатабы? Логика издебеңиз. Жөн гана кесимдерди кайра бириктирип: «Карачы, мен оңдоп койдум!» деп айтыңыз — жана бул маанисиз драмадан дипломатиялык жол менен качыңыз.','Terve õuna draama 🍏','Kas toas puhkes nutt, sest lõikasid õuna? Kas ta nutab: ''Tahtsin tervet!''? Ära otsi loogikat. Pane viilud lihtsalt kokku ja ütle: ''Vaata, parandasin ära!'' — ja põgene diplomaatiliselt sellest mõttetust draamast.'),
('8b61be71-cfc2-42cd-ad4f-a58585ff674e'::uuid,'Атам ойлоп тапкан баатыр 🦸‍♂️','Үнүңүз чыкпай калдыбы? Окууга демиңиз жетпей жатабы? Кезекти атасына бериңиз! Ал балаңыз башкы каарман болгон кызыктуу жомок айтып берсин. Сиз болсо диванга жатып, бөлмөдөн чыккан күлкүдөн ырахат алыңыз.','Issi väljamõeldud kangelane 🦸‍♂️','Hääl kadunud? Juttu lugeda ei jaksa? Viska pall issile! Lase tal vesta pöörane fantaasialugu, kus su laps on peategelane. Sina lihtsalt leba diivanil ja naudi toast kostvat itsitamist.'),
('167cc8b8-5aaf-4f2a-8be0-934651da76be'::uuid,'Тескери кийилген байпакка каршылык 🧦','Балдарыңыз байпагын тескери кийип алып, аны оңдоого такыр көнбөй жатабы? Коё бериңиз. Алардын «мен өзүм кийдим!» деп сыймыктануусу, байпактын туура кийилгенинен миллион эсе баалуу.','Sokkide pahupidi protest 🧦','Kas nad kannavad sokke nii, et kand on jalalaba peal, ja keelduvad kategooriliselt laskmast sul seda parandada? Las olla. Nende uhkus öelda „Ma tegin ise!“ on miljon korda väärtuslikum kui sokkide õigesti kandmine.'),
('4081d285-b739-4c34-a223-ae2922366de7'::uuid,'«Дагы бир ууртам» шылтоосу 💧','Уктаар алдында эле «суу ичким келип жатат!» деп калышабы? Кеп сууда эмес, кеп сиз менен дагы бир аз убакыт өткөрүүдө. Мындай адатты алдын алуу үчүн, төшөгүнүн жанына төгүлбөй турган суу бөтөлкөсүн коюп коюңуз.','„Veel üks lonks“ vabandus 💧','Kas nad teatavad äkki „Mul on NII janu!“, just kui nad on uinumas? Asi pole vees; asi on selles, et nad tahavad sinuga veidi rohkem aega veeta. Enneta seda tavapärast magamamineku venitust, asetades lekkimiskindla veepudeli otse voodi kõrvale.'),
('aff9ba8d-8d8a-4d80-9363-09474c73609e'::uuid,'Кичинекей изилдөөчү 👣','Алар буттарын таап алышып, ооздоруна салууга аракет кылып жатышат!','Väike avastaja 👣','Nad on avastanud oma varbad ja üritavad neid suhu pista!'),
('7b85f446-78f0-4be5-9cc1-c336a25ea658'::uuid,'Чарчадым, бирок айтпайм 📝','Бүгүн сиздин канчалык чарчаганыңызды эч ким байкабай жаткандай сезилип, баарына жылмайып коюу өтө оор болуп жатабы? Маанай күндөлүгүңүздү ачыңыз. Ичиңиздеги бардык терс эмоцияларды экранга төгүп салыңыз. Бул санариптик «ич бошотуу» кээде психологдун кабыл алуусунан да эффективдүү болот!','Olen väsinud, aga ei ütle seda 📝','Kas tundub, et keegi ei näe, kui suures stressis sa täna oled, ja kõigi ees naeratamine on lämmatav? Ava oma meeleolupäevik. Vala kogu see kogunenud frustratsioon ja „mürgised“ emotsioonid ekraanile. See digitaalne „väljaelamine“ võib mõnikord olla terapeutilisem kui teraapiaseanss!'),
('4c512e27-6d0e-434b-b3b6-e7db7541662c'::uuid,'Тротуардагы чийиндер — мыйзам 🛣️','Алар тротуардагы сызыктарды баспай өтүүгө аракет кылып, кызыктай басып жатышабы? Бул чоң моториканы жана көңүл бурууну өнүктүрүү үчүн эң сонун көнүгүү! Аларды шаштырбаңыз; колунан кармап, ал тургай сызыктардан чогуу секирип өтүңүз.','Kõnnitee kriimud on seadus 🛣️','Kas nad teevad kõndides kummalisi liigutusi, püüdes vältida kõnnitee pragude vahel olevatele joontele astumist? See on suurepärane harjutus nii üldmotoorika kui ka keskendumisvõime arendamiseks! Ära kiirusta neid; hoia neil käest ja hüppa koos nendega üle nende joonte.'),
('685cde5b-1133-4e8c-aa85-09d262ad4afb'::uuid,'Ваннанын агындысынан коркуу 🛁','Ваннадагы суу агып кеткенде, алар агынды түтүктөн коркуп жатышабы? Алардын элестетүүсү өтө күчтүү! Агынды түтүктүн үстүнө кичинекей оюнчук кайыкты коюп: «Карачы, бул биздин кичинекей сакчыбыз, ал эч нерсени агызып жибербейт» деп айтыңыз. Коркуу сезими дароо кызыгууга айланат.','Hirm vannitoa äravoolu ees 🛁','Kas nad kardavad äravoolu, kui vannivesi ära voolab? Nende kujutlusvõime võib valla pääseda! Aseta äravoolu kohale väike mängupaat ja ütle neile: „Vaata, see on meie väike kaitsja, see ei lase millelgi hirmutaval ära kaduda.“ Nende hirm muutub hetkega mänguliseks uudishimuks.'),
('e7c8a731-9f6f-40fe-bb36-efba9869846f'::uuid,'Таңкы саат 6дагы концерт 🎤','Ойгонору менен эле катуу үн менен ырдай башташабы? «Шыбырап сүйлө, кошуналар ойгонуп кетет!» деп алардын кубанычын өчүрбөңүз! Кошулуп ырдаңыз! Эртең менен ыр менен ойгонгон бала күн бою азыраак агрессивдүү болот.','Kell kuus hommikul algav kontsert 🎤','Kas nad ärkavad ja hakkavad kohe täiest kõrist väljamõeldud laulu laulma? Ära sumbuta seda rõõmsat energiat ütlusega „Ššš, naabrid ärkavad!“. Ühine nendega! Laps, kes alustab oma hommikut lauluga, kipub olema päeva jooksul vähem agressiivne.'),
('7dbcfeb4-6b0f-40e0-a421-e16781d15f4a'::uuid,'0 децибелдик унчукпоо бийи 🤫','Акыры бөлмө караңгыланып, алар укташты. Үйдөгү жымжырттык кулак тундурат. Тиркемедеги Үн өлчөгүчтү (Sound Meter) ачыңыз. Экранда «0 децибел» деген жазууну көрүү — ызы-чуудан чарчаган мээңиз үчүн эң сонун эс алуу.','0-detsibelline vaikuse tants 🤫','Lõpuks on tuba pime ja nad magavad. Majas on nii vaikne, et see tundub kõrvulukustav. Ava rakenduses helimõõtja. Selle „0 detsibelli“ näidu ilmumine ekraanile on nagu rahustav digitaalne massaaž sinu mürast väsinud meelele.'),
('80129e61-cd59-4c54-9d5e-e6507c3811da'::uuid,'Оюнчугум сага таарынып калды 🧸','Кичинекейиңиз келип: «Сен кыйкырганың үчүн аюу оюнчугум сага таарынып жатат» дедиби? Балким, ал өзүнүн сезимдерин сүйүктүү оюнчугуна өткөрүп жаткандыр. Аюудан өтө олуттуу түрдө кечирим сурап, аны кучактап коюңуз. Балаңыздын канчалык тез тынчтанаарына таң каласыз.','Mu mänguasi on sinu peale pahane 🧸','Kas su väike laps tuli sinu juurde ja ütles: „Mu kaisukaru on sinu peale pahane, sest sa karjusid“? Tõenäoliselt projitseerivad nad oma tundeid oma armastatud mänguasjale, et suhelda. Palu kaisukarult väga tõsiselt vabandust ja anna talle siis suur kalli. Sa üllatud, kui kiiresti su laps lõõgastub.'),
('e7d3487a-45d4-44a3-bf97-c34082190904'::uuid,'Чай эмнеге бууланып жатат? ☕','Балаңыз чөйчөктөн чыккан бууга карап, ал эмне экенин сурап же коркуп жатабы? Илимий түшүндүрмө бере албай жатасызбы? Anacan AI''дан 4 жашар бала үчүн философиялык жана таттуу жооп алыңыз: «Ал булуттарга кошулуу үчүн учуп баратат!»','Miks tee aurab? ☕','Kas su laps vaatab tassist tõusvat auru ja palub sul seda selgitada või lausa kardab? Ei oska teaduslikku selgitust anda? Küsi Anacan AI-lt 4-aastasele sobivat filosoofilist ja armsat selgitust: „See lendab üles pilvedega ühinema!“'),
('1bdc66c1-4583-42f2-a981-0ba814be491d'::uuid,'Сырт кийим үчүн күрөш 🧥','Сыртта күн тийип турат, бирок балаңыз куртка кийбей жатабы? Терезеден карап эле чечим чыгарбаңыз! Аба ырайы жана кийим тандоо куралынан чыныгы температураны көрсөтүңүз, балким, катмарлап кийинген баланын сүрөтүн көрсөтүңүз. Бүгүнкү күндүн эрежесин тиркеме аныктасын!','Mantli-lahing 🧥','Väljas paistab päike, aga su väike laps keeldub jopet selga panemast? Ära lase end vaid ühest aknast piilumisest kõigutada! Näita talle tegelikku temperatuuri rakenduse Ilm ja riietus tööriistas ning võib-olla pilti kihiliselt riietatud lapsest. Las rakendus olla tänane reeglite seadja!'),
('8b4c98d1-27b9-49ae-b0a2-f93f650bdd45'::uuid,'Куш эмнеге мага караган жок? 🐦','Паркта кептер учуп кеткени үчүн алар токтобой ыйлап жатышабы? Логика издебеңиз. Алар үчүн бул чоң жоготуу. «Оо, ал сени абдан сагынат!» деп алардын сезимдерин сыйлаңыз.','Miks lind mulle otsa ei vaadanud? 🐦','Kas nad nutsid kontrollimatult, sest tuvi lendas pargis minema? Ära otsi siit loogikat. Nende jaoks on see tõeliselt suur pettumus. Kinnita õrnalt nende tundeid, öeldes: „Oh, ta hakkab sind väga igatsema!“'),
('cbcac766-bab8-4183-80ab-82267106b24d'::uuid,'Менин атым жазылган жомок 🪄','Кадимки жомок каармандарынан тажадыңызбы? Биздин акылдуу жомокторубузда каармандын атын балаңыздын атына алмаштырыңыз. Өзүнүн эрдиктери жөнүндө угуу ага эч кандай каршылыксыз уктоого жардам берет.','Lugu, kus on minu nimi 🪄','Tüdinenud tavalistest muinasjutukangelastest? Meie nutikates lugudes saad asendada kangelase nime oma lapse nimega. Kuuldes omaenda vapratest seiklustest, uinuvad nad ilma ühegi protestita.'),
('83683b1a-77a6-45bf-bf9e-6b7ae022a7e3'::uuid,'Бүгүн мен машинемин! 🚗','Эртең менен сизге: «Мен бала эмесмин, мен машинамын!» дешсе, талашпаңыз. Тескерисинче: «Анда багыңды (ботко менен) толтуралы, тез айдашың үчүн!» деңиз. Мындай тамашалуу ролдук оюндар кыйкырыктан алда канча натыйжалуу.','Olen täna auto! 🚗','Kas nad ütlevad sulle hommikul: „Ma ei ole laps, ma olen auto!“? Ära vaidle. Ütle hoopis: „Siis täidame su paagi (pudruga), et saaksid kiiresti sõita!“ Neid naljakaid rollimänge on palju lihtsam mängida kui karjuda.'),
('87824b1c-6e01-4ebd-84b1-4bb784a464e0'::uuid,'Кумдан жасалган торт 🏖️','Паркта суу менен топуракты аралаштырып, сизге «торт» бышырам деп кир болуп жатышабы? Кир болгонуна карабаңыз! Бул майда моториканын өнүгүүсү жана чыгармачылыктын гүлдөшү.','Liivalossist kook 🏖️','Kas nad segasid pargis vett ja mulda, muutudes täiesti poriseks, et sulle kooki „küpsetada“? Unusta segadus! See on puhas peenmotoorika areng ja loovuse õitsemine.'),
('bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99'::uuid,'Көз тиктешүү оюну 👀','Уктабай, көздөрүн чоң ачып карап жатышабы? «Ким биринчи көзүн ирмесе, ошол утулат» деген оюн ойноңуз. Көздөрү табигый түрдө чарчап, бир нече мүнөттө уктап калышат. Байкап көрүңүз!','Kes keda jõllitab 👁️','Keelduvad magamast ja vahivad sind meelega suurte silmadega? Kutsu nad mängima mängu „kes esimesena pilgutab, see kaotab“. Nende silmad muutuvad loomulikult vesiseks ja väsinuks ning nad uinuvad mõne minutiga. Proovi järele!'),
('20b06f39-a2df-4c97-aab5-39753c3a8a8f'::uuid,'Жашырылган оюнчуктар 🧸','Төшөккө жатканда астынан үч катуу оюнчук машина таап алдыңызбы? Алар уктап жатканда да аларды «кайтарып» жатышат. Кабатыр болбоңуз, терең уйкуга кеткенден 10 мүнөт өткөндөн кийин, аларды акырын алып коюп, балаңыздын ыңгайлуу уктоосун камсыздай аласыз.','Voodisse peidetud mänguasjad 🧸','Kas avastasid voodisse minnes nende alt kolm kõva mänguautot? Nad „valvavad“ neid isegi unes. Ära muretse, vaid 10 minutit pärast seda, kui nad on sügavalt uinunud, saad need esemed vaikselt ära võtta ja neile tõeliselt mugava une tagada.'),
('29e9913a-41eb-42ab-96c8-cc6c3af590fd'::uuid,'Эл көзүндөгү жашыруун тынчтык 💬','Абдан чарчап, эч кимге сырыңызды айткыңыз келбей жатабы? Anacan коомчулугуна кирип, жөн гана байкоочу болуңуз. Башка энелердин да дал ушундай «кризистерди» башынан өткөрүп жатканын көрүү — сөзсүз түрдө эң чоң сооронуч болот.','Salajane lohutus avalikus kohas 💬','Oled täiesti kurnatud ega taha kellelegi südant puistata? Astu lihtsalt Anacan Communitysse ja ole vaikne vaatleja. Teiste emade nägemine samasugustes absurdsetes „kriisides“ on kõige võimsam, sõnatu lohutus, mida võid soovida.'),
('bab27593-bee1-487c-a8d8-1d9f5c333dc2'::uuid,'«Туура эмес кашык» кризиси 🥄','Чоң кашык менен шорпо бергениңиз үчүн эле «козголоң» чыктыбы? 4 жаш тегрегинде, тамак бирдей болсо да, идиштин көлөмү алардын логикасында даамды өзгөртөт. Талашпаңыз; кашыкты дароо алмаштырып, өзүңүздүн энергияңызды сактап калыңыз.','„Vale lusika“ kriis 🥄','Kas puhkes peaaegu mäss, sest andsid neile supi suure lusikaga? Umbes 4-aastaselt, isegi kui toit on sama, muudab söögiriista füüsiline suurus nende loogikas toidu maitset. Ära vaidle; vaheta kiiresti lusikas ja säästa oma energiat.'),
('6072f87e-09eb-4773-9647-75d90ac37029'::uuid,'Дивандагы жагымдуу эс алуу 🥂','Бала уктады, үй таза. Өнөктөшүңүз менен диванда отуруңуз, телевизорду да күйгүзбөңүз. Жөн гана бири-бириңизди карап: «Биз муну кылдык, дагы бир күндү жеңдик» деген көз караш менен алмашыңыз. Ишениңиз, бул ата-энелик жашоодогу эң романтикалуу жана чын жүрөктөн чыккан көз ирмемдердин бири.','Meie vaikne diivanil vedelemine 🥂','Beebi magab, maja on korras. Istu elukaaslase kõrvale diivanile, ära isegi pane telerit tööle. Vahetage lihtsalt see teadlik pilk, mis ütleb: „Me tegime ära, me elasime veel ühe päeva üle.“ Usu meid, see on üks lapsevanemaks olemise kõige romantilisemaid ja ehedamaid hetki.'),
('a980ec72-f146-48fe-a3b4-28ba8f8a9398'::uuid,'Көк чөптөргө болгон сүйүү 🥦','Кичинекейиңиз тарелкадагы жашыл нерселерди гана алып, башка түстөгүлөрдү түртүп жатабы? Биздин пайдалуу рецепттерибизди карап чыгып, жашылчалардан кантип даамдуу жана жагымдуу топторду жасоону үйрөнүңүз.','Armastus rohelise vastu 🥦','Kas su väike laps sirutab taldrikul käe vaid roheliste asjade järele ja lükkab teised värvid eemale? Sirvi meie tervislikke retsepte ja avasta, kuidas teha lehtköögiviljadest imearmsaid rohelisi köögiviljapalle.'),
('e2f4da77-db67-4ed8-9acb-d0a907894c73'::uuid,'Бирок мен эшикти өзүм жапкым келген! 🚪','Үйдөн чыгып баратканда эшикти *сиз* жапканыңыз үчүн ыйлап жатышабы? Алардын эң чоң муктаждыгы — көзөмөлдөө сезими. Азыр бир мүнөтүңүздү коротуп, көчөдө 30 мүнөттүк ыйдан сактанып калыңыз.','Aga mina tahtsin ust kinni panna! 🚪','Kas nad tegid jonnihoo ja panid sind ust uuesti avama, sest *sina* sulgesid selle majast lahkudes? Nende suurim vajadus on kontrollitunne. Las see maksab sulle praegu ühe minuti ja hoiab ära 30-minutilise nutukriisi tänaval.'),
('2feec242-97b8-4207-9200-a80856e8121d'::uuid,'Күзгүдөгү ал бала ким? 🪞','Алар күзгү алдында каштарын түйүп, кызыктай бет маскаларын жасап жатышабы? Алар эмоциялардын бетте кантип чагылдырылаарын изилдеп жатышат. Бул кичинекей актёрдун репетициясын алыстан суктануу менен карап туруңуз.','Kes see laps peeglis on? 🪞','Kas nad seisavad peegli ees, kortsutavad kulmu ja teevad vihaseid ning kummalisi nägusid? Nad avastavad, kuidas emotsioonid nende näol välja näevad. Jälgi vaikselt ja rõõmuga selle miniatuurse teatrietenduse proovi eemalt.'),
('70b38ef9-bf37-4439-be26-d9a4e96ca1a7'::uuid,'Жарыкты өчүрүп, көлөкө издейбиз 🔦','Караңгыдан коркуп, уктоодон баш тартып жатышабы? Жарыкты өчүрүп, кичинекей фонарик алыңыз да, дубалга көлөкө оюндарын жасаңыз — ит, куш! Коркунучтуу караңгылыкты сыйкырдуу театрга айландырыңыз, ошондо уктоо алда канча жеңил болот.','Tuled kustu, varjujahile 🔦','Kas nad kardavad pimedust ja tõrguvad magama minemast? Kustuta peatuled, võta väike taskulamp ja loo seinale lõbusaid varjuteatreid – koer, lind! Muuda hirmutav pimedus maagiliseks teatriks ja magamaminek muutub palju lihtsamaks.'),
('d5008830-7d32-4abc-8ae0-128b13041be3'::uuid,'Дубалдагы көркөм чыгармалар 🖍️','Бир аз тынчтыктан кийин дубалга маркер менен «шедевр» тартып жатканын көрдүңүзбү? Терең дем алыңыз. Алардын майда моторикасы өнүгүп жатат! Дубалды болсо тазалап койсо болот. Сүрөтүн тартып алууну унутпаңыз!','Seinakunsti meistriteosed 🖍️','Leidsid nad pärast mõnesekundilist vaikust markeritega seinale meistriteost loomas? Hinga sügavalt sisse. Nende peenmotoorika areneb! Ja seina saab alati puhastada. Lihtsalt tee sellest „kunstiteosest“ foto, enne kui selle maha pühid.'),
('56af6282-7207-49e4-b888-b735c8e4f791'::uuid,'Атамдын ийининдеги саякат 🐴','Балаңыздын энергиясы ашып-ташып, уктабай жатабы? Атасын чакырыңыз! Ал баласын «ат кылып» көтөргөндө, бөлмө күлкүгө толуп, бардык топтолгон энергиясы тарап кетет.','Issi õlgadel ratsutamine 🐴','Kas su väikesel on ikka veel energiat ja ta tõrgub magama minemast? Kutsu issi appi! Kui ta nad „hobusesõidule“ võtab, täitub tuba naeruga ja kogu see kogunenud füüsiline energia hajub itsitamise ja higistamise saatel.'),
('65ce993d-a029-4b05-8c87-ec0d7b807a64'::uuid,'Дааратканадагы ыйык 5 мүнөттүк эс алуу 🚪','Ызы-чуудан башыңыз ооруп, баарына кыйкыргыңыз келип жатабы? Балаңызды коопсуз жерге калтырып, ваннага кирип, эшикти жабыңыз. 5 мүнөт эч нерсе кылбай, дубалды карап отуруңуз. Бул кыска тынчтык сизге кайрадан кадимки адамдай сезилүүгө жардам берет.','Püha 5-minutiline vannitoapaus 🚪','Kas müra puurib su ajus ja paneb sind tahtma kõige peale karjuda? Pane laps turvalisse kohta, astu vannituppa ja sulge uks. Lihtsalt vaata 5 minutit seina, tegemata mitte midagi. See lühike vaikus aitab sul end jälle normaalse inimesena tunda.'),
('856b771b-5997-4eed-bc26-8b35541184c6'::uuid,'Аба ырайы тууралуу маалымат ⛅','Сырттагы аба ырайы өзгөрүлмөлүүбү? Биздин аба ырайы жана кийим тандоо куралыбыз шамалдын ылдамдыгын (терезеден көрүнбөсө да!) жана эң ылайыктуу кийимди дароо айтып берет, андыктан эч ойлонбой сейилдөөгө чыга аласыз.','Ilmateade ⛅','Kas ilm väljas on veidi ettearvamatu? Meie ilmateate ja riietuse tööriist annab sulle kohe teada tuule kiiruse (isegi kui sa seda aknast ei näe!) ja täiusliku riietuse, nii et saad muretult jalutama minna.'),
('a5a3dc3f-2634-4d40-9509-dbe4066d8a5a'::uuid,'Ботком өтө тегерек болуп калды! 🥣','Тамактын формасына нааразы болуп, жебей жатышабы? Логика издебей эле, боткону кашык менен аралаштырып: «Карачы, мен оңдоп койдум!» деңиз. Иллюзия өнөрү энелик жашоодо ар дайым керек болот.','Mu puder on liiga ümmargune! 🥣','Kas nad vihastavad toidu kuju peale ja keelduvad söömast? Otsimata loogikat, sega lihtsalt putru lusikaga ja ütle: „Vaata, ma parandasin selle ära!“ Illusioonikunst on emaduses alati kasulik.'),
('9272ca67-0e34-4d81-b7cc-a00d43d2c52b'::uuid,'Түшүнүксүз көз жаштар 😭','Сейил бактан кайтып келе жатканда ташты тепкилей албай калганы үчүн эле ызы-чуу салдыбы? Мында логика жок, ал жөн гана чарчаган. Талашпаңыз, кучагыңызга алып, сезимин түшүнгөнүңүздү билдирип, көңүлүн башка жакка буруңуз.','Need seletamatud pisarad 😭','Kas parkist tulles tekkis maailmalõpp, sest ta ei saanud teel olevat kivi jalaga lüüa? Siin pole loogikat, ta on lihtsalt väsinud. Ära vaidle, võta ta sülle, tunnusta tema tundeid ja suuna tähelepanu mujale.'),
('bf4ef479-e79f-4536-adc8-2a33fe4bb476'::uuid,'Уктаар алдындагы шыбырашуулар 🤫','Уктоо убактысы келгенде ар кандай шылтоолорду айтып жатабы? Үнүңүздү акырын шыбырга чейин басаңдатыңыз. Сизди угуу үчүн алар кунт коюп тыңшашы керек болот, бул болсо мээсин тез эле уйкуга багындырат.','Sosistatud uneaja saladused 🤫','Leiutab iga ettekäände, et vältida magamaminekut? Langeta oma hääl sosinani. Ta peab sind mõistmiseks pingutama ja keskenduma, mis uinutab tema aju kiiresti unne.'),
('dd593bef-61fd-4b06-ae2c-84f70da4ad5c'::uuid,'Эмнеге менин музыкамы өчүрдүң? 🎶','Фондо ойноп жаткан балдар ырына кошулуп ырдасаңыз, дароо эле «Ырдаба!» деп кыйкырдыбы? Бөлмөдөгү жалгыз солист — ал, сиздин ырдооңуз анын сахнасын кичирейтип жаткандай сезилет. Буга таарынбаңыз, бул кичинекей эгоистке өзүнүн «жылдыздуу» көз ирмеминен ырахат алууга мүмкүнчүлүк бериңиз.','Miks sa mu muusika kinni panid? 🎶','Ümisesid taustal mängiva lastelaulu kaasa ja ta karjus kohe: „Ära laula!“ Tema on toas ainus solist; sinu vokaalsed katsed kahandavad tema lava. Ära võta seda isiklikult, lase sel väikesel egoistil oma tähetundi nautida.'),
('0e5c772e-ad3b-4b0c-99e1-704d879eb64e'::uuid,'Өз кийимин өзү тандаганда 👗','Кызыл шым, кроссовка жана кышкы баш кийим... ушундай кийинип сейил бакка барам деп өжөрлөнүп жатабы? Башкалар эмне дейт деп ойлонбоңуз. Каалагандай кийинип чыксын; азыр алар үчүн өзүн көрсөтүү эркиндиги сырткы көрүнүштөн алда канча маанилүү.','Kui nad valivad ise oma riided 👗','Punased püksid, tossud ja talvemüts... ja ta nõuab, et läheb nii parki? Unusta, mida ühiskond arvab. Lase tal minna oma valitud riietuses; see eneseväljendusvabadus on talle praegu tähtsam kui esteetika.'),
('1c02e319-6351-4dbf-93b0-072c9cbcabab'::uuid,'Уктоо убактысы боюнча келишим ⏱️','Бананды *сиз* аарчып койгонуңуз үчүн эле бөлмөдө «революция» башталдыбы? Бул курактын алтын эрежеси: Баарын алар чечиши керек. Аарчылган бананды кайра калыбына келтире албайсыз, андыктан жаңысын бериңиз жана алар каалагандай аарчысын, бул алардын өз алдынчалык сезимин сактап калат.','Uneaja taimeri kokkulepe ⏱️','Kas magamamineku ajal tekib tal äkki janu või vajadus öelda head ööd igale toas olevale esemele? Pane taimer! Kehtesta reegel: „Kui taimer heliseb, lähevad kõik magama.“ Lapsed täidavad välist ja neutraalset autoriteeti sageli kergemini.'),
('42320a1e-019f-4b03-8860-b2a7ebec874e'::uuid,'Ай эмнеге дагы эле көрүнүп турат? 🌙','Эртең мененки асмандан айды көрүп: «Эмнеге ай уктабайт?» деп сурадыбы? Анын кичинекей башын илимий терминдер менен чаташтырбаңыз. Anacan AI тиркемесин ачып, анын курагына ылайыктуу кызыктуу астрономиялык жомокту таап, окуп берип, кызыгуусун канааттандырыңыз.','Miks kuu on ikka veel väljas? 🌙','Ta nägi hommikutaevas kuud ja küsis: „Miks kuu ei maga?“ Ära koorma tema väikest pead teaduslike terminitega. Ava Anacan AI, leia tema vanusele sobiv armas astronoomiline lugu, loe see talle ette ja rahulda tema uudishimu.'),
('37e1f058-26f3-4681-8381-3414a60ed5c9'::uuid,'Нандын чети гана даамдуу! 🍞','Нандын четин гана жеп, ортосун таштап коюшабы? Тамакка карата мындай өжөрлүк сизге тааныш көрүнүш. Нандын чети үчүн урушпаңыз. Тамактануу планыбыздагы калыптарды колдонуп, нанды ар кандай формада кесип, ага кызыктуу четин жаратууну үйрөнүңүз.','Ainult koorik on hea! 🍞','Kas ta sööb ainult leivakoorikut ja viskab sisu ära? Kangekaelsed toitumiseelistused on sulle tuttav teema. Ära võitle koorikute pärast. Õpi oma toitumiskavas leiba vormidega lõikama, et luua talle erinevaid koorikuid.'),
('d40bcca0-d355-4520-b51b-bece0b2b8663'::uuid,'Мелатонин үчүн караңгылыкты кабыл алыңыз 🌌','Балаңыздын тез уктап кетишине жардам берүү үчүн, уктоо убактысына бир саат калганда бөлмөдөгү бардык сыналгы жана телефон экрандарын өчүрүңүз. Уйку гормону — мелатонин караңгы чөйрөдө эң жакшы иштелип чыгат, андыктан бул табигый процесске ишениңиз.','Melatoniini jaoks pimedus appi 🌌','Et aidata lapsel kiiremini uinuda, lülita vähemalt tund enne magamaminekut toas välja kõik telerid ja telefoniekraanid. Melatoniin, unehormoon, tekib kõige tõhusamalt pimedas keskkonnas, seega usalda seda loomulikku protsessi.'),
('eb8ec98b-d143-483a-b14c-964f86bd6a10'::uuid,'Оюнчуктар эмнеге уктабайт? 🧸','Өзү уктабай, бардык оюнчуктарын бирден төшөккө жаткырып жатабы? Бул ролдук оюн аларды психологиялык жактан өзүнүн уйкусуна акырындык менен даярдап жатат. Бул процесске тоскоолдук кылбаңыз.','Miks mänguasjad ei taha magada? 🧸','Ta ei maga ise, aga paneb kõiki oma mänguasju ükshaaval magama ja teeb neile pai? See rollimäng valmistab teda tegelikult psühholoogiliselt õrnalt ette tema enda uneks. Ära sega seda.'),
('22a3d2df-ec5e-47c6-9766-7dc689ce8423'::uuid,'Жөн гана алардын жытын искеңиз 🫂','Бүгүнкү күн күчүңүздү алып, чыдамыңызды сынадыбы? Бирок азыр алардын тынч жана бейкүнөө уктап жатканын караңыз... Жарыкты өчүрүңүз. Жанына жатып, анын таттуу жытын терең дем алып жыттап, караңгылыкта аларды канчалык жакшы көрөрүңүздү акырын шыбырап айтыңыз.','Lihtsalt nuusuta nende lõhna 🫂','Kas tänane päev kurnas su energiat ja pani kannatuse proovile? Aga vaata teda nüüd, magab nii rahulikult ja süütult... Kustuta tuled. Heida tema kõrvale, hinga sisse seda magusat beebilõhna ja sosista vaikuses, kui väga sa teda armastad.'),
('48b463cd-d776-4db6-a471-4507d498dd54'::uuid,'Дүкөндөгү ыйлаган учур 🛒','Дүкөнгө кирип, эмне алыш керек экенин унутуп калдыңызбы? Эгерде санариптик соода тизмесин колдонбосоңуз, башаламандыкта баарын унутуп каласыз. Үйгө куру кол кайтпаш үчүн ар дайым тиркеменин санариптик эс тутумуна таяныңыз.','Toidupoe jonnihoog 🛒','Läksid poodi ja unustasid täielikult, mida vaja oli? Kui sa ei pea digitaalset ostunimekirja, unustad kaoses kõik. Kasuta alati äpi digitaalset mälu, et sa ei peaks tühjade kätega koju naasma.'),
('9dc02f00-56a0-48da-87a7-8f742a42c374'::uuid,'Сиз мени менен ойнобой жатасыз! 😤','Тамак аралаштырып жатканда келип, колу менен жүзүңүздү өзүнө буруп: «Мага кара!» дейби? Алар туура айтат. Аларга сиздин физикалык жактан жаныңызда болушуңуз эмес, толук көңүл бурууңуз керек. Колуңуздагы ишти таштап, 2 мүнөт бою көзүнө тике карап, аларды угуңуз.','Sa ei mängi minuga! 😤','Segad toitu, kui ta tuleb ja keerab su näo kätega enda poole, öeldes: „Vaata mind!“ Tal on õigus. Ta ei taha su füüsilist kohalolu, ta tahab su jagamatut tähelepanu. Pane tegemised kõrvale ja kuula teda 2 minutit, hoides silmsidet.'),
('a00b84e6-561e-4101-8d5d-a0f8a705abed'::uuid,'Жамгыр үнү коштогон бөлмө 🌧️','Үнүңүз чыкпай калдыбы же жомок окуп берүүгө өтө чарчадыңызбы? «Акылдуу жомоктор» функциябыздан жамгырдын же токойдун үнүн фон катары коюп көрүңүз. Жаратылыштын бул тынчтандыруучу, бир калыптагы үнү кээде каалаган жомоктон да сыйкырдуу жана тынчтандыруучу таасир берет.','Tuba täis vihmahelisid 🌧️','Kaotasid hääle või oled lihtsalt liiga väsinud unejutu lugemiseks? Proovi mängida meie „Nutikate lugude“ funktsioonist taustaks vihma- või metsahelisid. See rahustav ja monotoonne looduse vaikus võib mõnikord olla lummavam ja rahustavam kui ükski jutt.'),
('a4fa9d13-3510-4b51-9dcb-583bfd5c19ad'::uuid,'Мени ойдон чыгарылган атым менен атаңыз! 🦇','Бүгүн эртең менен ойгонуп, өз атынан баш тартып: «Мени Бэтмен деп ата!» дедиби? Ыңгайлашыңыз! 5 мүнөт бою: «Марш, Бэтмен, боткоңду жеп ал», — деп айтып, бөлмөдөгү чыңалууну дароо тамашага айлантыңыз.','Kutsu mind minu väljamõeldud nimega! 🦇','Ta ärkas täna hommikul, hülgas oma nime ja nõudis: „Kutsu mind Batmaniks!“ Kohane! Ütle 5 minutit: „Palun, Batman, söö oma putru,“ ja muuda toa pinge hetkega komöödiaks.'),
('e5dd03b1-7179-4527-8c52-f0958fe208e9'::uuid,'Инстаграмдагы энелердин чарчоосу 📱','Instagram''ды ачарыңыз менен баарынын «кемчиликсиз» балдарын көрүп капа болбоңуз! Тиркемени жаап, Anacan коомчулугуна кириңиз. Башкалардын үйүндө да сиздики сыяктуу эле башаламандык болуп жатканын көргөндө, терең дем алыңыз — сиз жалгыз эмессиз.','Instagrami-emme väsimus 📱','Ära lase end heidutada, kui näed Instagrami avades kõigi teiste „täiuslikke“ lapsi! Sulge äpp ja sukeldu Anacani kogukonda. Hinga sügavalt sisse, kui näed, et ka teiste kodudes valitseb samasugune kaos – sa pole üksi.'),
('17e2ffec-fd31-4ab8-8917-684e3ceaaff9'::uuid,'Суу стрессиңизди жууп кетсин 🛀','Кээде эч нерсе жардам бербей, баарына ыйлай береби? Жылуу ваннага түшүрүп көрүңүз. Суунун тынчтандыруучу, дээрлик сыйкырдуу таасири алардын нерв системасын дароо жайгарып, бүт бөлмөгө тынчтык алып келет.','Lase veel oma stress minema uhtuda 🛀','Vahel tundub, et miski ei aita ja laps nutab kõige peale. Proovi sooja vanni. Vee rahustav, peaaegu maagiline toime võib hetkega nende närvisüsteemi maha rahustada ja tuua kogu tuppa rahu.'),
('d1311034-b416-403f-a981-34577f22c978'::uuid,'Кетчи, сени каалабайм! 💔','Каалоосун аткарбаганыңыз үчүн: «Сен жаман апасың, кет!» дедиби? Жүрөгүңүз ооруп кетти. Бирок алар ачуусун азырынча сөз менен айта алышпайт; алар чындыгында: «Мен капа болдум» деп жатышат. Таарынбаңыз, жөн гана сүйүү менен кучактап коюңуз.','Mine ära, ma ei taha sind! 💔','Kas nad ütlesid sulle: „Sa oled halb ema, mine ära!“, sest sa keelasid neil midagi teha? Su süda vajus saapasäärde. Kuid nad ei oska oma viha veel sõnadesse panna; tegelikult tahavad nad öelda: „Olen pettunud.“ Ära võta seda isiklikult, lihtsalt kallista neid armastusega.'),
('e3289711-a700-447f-9c8d-d0e1b469b80e'::uuid,'Элестеткен достор менен чай ичүү 🫖','Бөлмөнүн бурчунда эч ким жок жерге чай куюп, өзүнчө күлүп жатабы? Анын элестеткен досу менен болгон мезгили өнүгүп жатат!','Teepidu kujuteldavate sõpradega 🫖','Kas nad valavad tühja õhku teed ja itsitavad toa nurgas? Nende kujuteldavate sõprade faas on arenemas!'),
('05726924-8563-423e-bd0f-f5be06f1d806'::uuid,'Атам окуган жомоктогу каталар 📖','Бүгүн кечинде жомок китебин атасына бериңиз. Ал жомокту атайылап тескери же күлкүлүү, акылга сыйбаган жол менен айтып берсин. Балаңыздын аны оңдоп, каткырып күлгөнүн кубануу менен караңыз.','Issi valesti loetud muinasjutt 📖','Täna õhtul anna raamat isale. Las ta loeb lugu meelega tagurpidi või naljakal, absurdsel moel. Vaata rõõmuga, kuidas laps naudib tema parandamist ja puhkeb naerma.'),
('1b87ed18-3cf6-4e93-88b1-58f24b42513f'::uuid,'Эртең мененки кууп жетүү оюну! 🏃‍♂️','Эртең мененки саат 7де диванда секирип жатышабы? Кыйкырбаңыз. Колуңуздагы ишти 2 мүнөткө таштап, аларга кошулуп секириңиз. Балаңыздын кыялкеч дүйнөсүнө кирүү — бул сиз үчүн стресстен арылуунун кызыктай, бирок сонун жолу.','Varahommikune tagaajamine! 🏃‍♂️','Kas nad jooksevad kell 7 hommikul mööda diivaneid? Ära karju. Jäta oma tegemised 2 minutiks pooleli ja hüppa nendega koos. Lapse kujutlusmaailma sisenemine on tegelikult kummaline, kuid suurepärane viis stressi maandamiseks.'),
('9c4135ea-bc1e-4450-aea1-64dfec877859'::uuid,'Күтүлбөгөн жерден кекечтенип калуу кооптонуусу 🤖','Балаңыздын күтүлбөгөн жерден кекечтенип калганы сизди интернеттен оору издеп, дүрбөлөңгө салдыбы? Токтоңуз! Anacan AI бул көбүнчө 4 жаштагы балдардын өнүгүүсүндөгү кадимки көрүнүш экенин айтып, сизди тынчтандырсын. Дүрбөлөңдү токтотуңуз.','Äkiline mure kokutamise pärast 🤖','Kas lapse äkiline kogelemine on pannud sind internetist haigusi otsima? Peatu! Lase Anacan AI-l sind rahustada – see on sageli normaalne 4-aastaste arenguhüpe. Lülita paanika välja.'),
('15bb2b6b-7a84-4331-86dd-6aee2aba5539'::uuid,'Тынчтыктын көрсөткүчү 📉','Акыры укташты. Үйдө кулак тундурган тынчтык орнодубу? Тиркемебиздеги «Үн өлчөгүчтү» (Sound Meter) ачыңыз. «0 децибел» деген жазууну көрүү чарчаган, ызы-чуудан тажаган мээңиз үчүн эң сонун визуалдык эс алуу болот.','Vaikuse näitaja 📉','Nad on lõpuks magama jäänud. Kas majas valitseb nii sügav vaikus, et kõrvus kohiseb? Ava meie äpis helimõõtja. Selle „0 detsibelli“ näidu jälgimine on ülim visuaalne massaaž sinu väsinud ja mürast küllastunud ajule.'),
('21cfa5ea-471d-459d-a626-6d4be6cf6e4c'::uuid,'«Бананымды аарчып койдуң» кризиси 🍌','Бананды *сиз* аарчып койгонуңуз үчүн бөлмөдө «революция» болуп кеттиби? Бул курактын алтын эрежеси: баарына өздөрү чечим чыгарышы керек. Аарчылган бананды кайра калыбына келтире албайсыз, андыктан аларга жаңысын бериңиз да, өздөрү каалагандай аарчыганга уруксат бериңиз. Бул алардын өз алдынчалык сезимин өстүрүүгө жардам берет.','„Sa koorisid mu banaani“ kriis 🍌','Kas toas puhkes revolutsioon, sest *sina* koorisid banaani? Selle vanuse kuldreegel: nemad peavad kõike otsustama. Banaani ei saa tagasi koorida, seega anna neile uus ja lase neil seda ise koorida nii, nagu nad soovivad – see kaitseb nende iseseisvust.'),
('e6cc1e43-997c-46d7-a69b-a71076271387'::uuid,'Тротуардын четинде тең салмактуулук сактоо 🧱','Сейил бакка бара жатканда түз жол менен эмес, тротуардын эң тар чети менен басам деп өжөрлөнүп жатабы? Коопсуздугу үчүн колунан кармап, бул кичинекей «чокуну» багындыруусуна жол бериңиз. Алардын тең салмактуулугу жана өзүнө болгон ишеними ушул учурда эң сонун өнүгөт.','Kõnnitee äärel tasakaalustamine 🧱','Kas nad nõuavad pargi poole minnes otsetee asemel kõnnitee kõige kitsamal serval kõndimist? Hoia ohutuse mõttes nende käest kinni ja lase neil see väike „mäetipp“ vallutada. Nende tasakaal ja enesekindlus arenevad samal ajal suurepäraselt.'),
('6daea202-5e39-49bd-9344-4fdbc59064e5'::uuid,'Өзүңө кам көрүү — бул өзүмчүлдүк эмес 🥗','Аларга ар кандай меню даярдадыңыз, бирок өзүңүз эмне жедиңиз? Дени сак рецепттерибизден энелер үчүн 5 мүнөттүк жеңил салат жасап алыңыз. Акыры өзүңүздү да кубаттандырууну унутпаңыз.','Enese eest hoolitsemine pole isekas 🥗','Oled neile erinevaid menüüsid koostanud, aga mida sina sõid? Valmista meie tervislike retseptide hulgast see lihtne 5-minuti salat emadele. Ära unusta end lõpuks laadida.'),
('744c45ec-e43d-4be3-95b9-700cd56edef4'::uuid,'Бирге унчукпай тиктешүү 🥂','Бала уктады. Сиз жана жолдошуңуз диванда унчукпай отуруп, бири-бириңизди карап жатасыз. Бул унчукпастык — «Биз дагы бир күндү жеңдик, биз эң сонун командабыз» деп айтуунун эң романтикалуу жана чын жүрөктөн чыккан жолу.','Vaikne pilk koos 🥂','Laps magab. Istute partneriga vaikselt diivanil ja lihtsalt vaatate üksteist, sõnu pole vaja. See vaikus on tegelikult kõige romantilisem ja südamlikum viis öelda: „Me saime jälle hakkama, oleme suurepärane meeskond.“'),
('9632825c-5c1a-41f6-900b-2b6b7e88d644'::uuid,'Күрмө кийүүдөн баш тартуу 🧥','Күн ачык болгону үчүн кышкы курткасын кийгиси келбей жатабы? Аба ырайы жана кийим тиркемеңизди ачып, телефонуңуздан кышка кийинген баланын сүрөтүн көрсөтүңүз. Эрежени санариптик экранга жүктөп, анан акырын четтеңиз; алар эч талашсыз эле кийинип алышат.','Jopega võitlemine 🧥','Nad ei taha talvejopet selga panna, sest päike paistab? Ava oma ilma- ja riietumisäpp, näita neile telefonist pilti talveriietes lapsest. Lae reegel digitaalsele ekraanile ja astu vaikselt eemale; nad riietuvad ilma jonnimata.'),
('6f53d579-a4b1-4e03-8f30-fcdd7a9084bf'::uuid,'Караңгыдагы сырдуу шыбырлар 🌙','Жарыкты толугу менен өчүрүңүз. Жанына жатып, кулагына күндүз эмне болгонун акырын шыбырап айтып бериңиз же анын мүнөзүндөгү сизге жаккан өзгөчөлүктү мактаңыз. Шыбырап сүйлөө — мээни уйкуга даярдоонун жумшак, дээрлик сыйкырдуу жолу.','Intiimsed sosinad pimeduses 🌙','Kustuta tuled täielikult. Heida nende kõrvale pikali ja sosista neile vaikselt kõrva, kuidas su päev möödus, või räägi mõni armas seik nende iseloomu kohta. Sosistamine on õrn ja peaaegu maagiline viis valmistada lapse aju uneks ette.'),
('ba2db9df-7097-4890-b7eb-8938c592806f'::uuid,'«Менин күнөөм эмес» деген калп 🤥','Полго атайылап суу төгүп жиберип, анан оюнчук машинасын көрсөтүп: «Бул түрттү» дедиби? Бул калп эмес, бул коргонуу механизми. Акылдуулук менен: «Кел, машинага полду тазалаганды үйрөтөлү!» деп, анын оюн башка жакка буруңуз.','Valetamine stiilis „see pole minu süü“ 🤥','Nad valasid meelega vett põrandale, aga näitasid siis sõrmega mänguautole ja ütlesid: „See lükkas“? See pole valetamine, vaid kaitsemehhanism. Trikita nutikalt ja ütle: „Õpetame sellele autole, kuidas koristada!“'),
('ce02bfea-edc6-42ad-80fd-37f3c322993b'::uuid,'Аянтчадагы слайд саясаты 🤝','Биринчи болом деп башка баланы түртүп жибердиби? Уялбаңыз же урушпаңыз. Жумшак, бирок чечкиндүү түрдө эрежени эскертиңиз: «Азыр анын кезеги, андан кийин сеники». Социалдык адеп-ахлакты алар ушинтип үйрөнүшөт.','Mänguväljaku liumäe-poliitika 🤝','Kas nad lükkasid liumäel teist last, et ise esimesena minna? Ära tunne piinlikkust ega löö neid. Tuleta neile õrnalt, kuid kindlalt meelde reeglit: „Nüüd on teise kord, siis on sinu kord.“ Nii õpivad nad sotsiaalset etiketti.'),
('2128fd31-18d2-4020-9903-1e4bdb06a192'::uuid,'Жумуртка «ыйлабашы» үчүн кам көрүү 🍳','Жумуртканы чакканыңызда ага боору ооруп, эми аны жебей койдубу? Алардын боорукердигинин чеги жок. Кырдаалды дароо оңдоо үчүн: «Ал азыр сенин булчуңдарыңа кирип, сени абдан күчтүү кылат!» деген сыяктуу таттуу калптарды колдонуңуз.','Veendumine, et muna ei „nutaks“ 🍳','Kas neil hakkas munast kahju, kui sa selle katki lõid ja nüüd nad ei taha seda süüa? Nende empaatiavõimel pole piire. Päästa olukord kiiresti armsate väljamõeldistega, nagu: "See läheb nüüd sinu lihastesse ja teeb sind ülitugevaks!"'),
('2fbf236d-dcf9-462e-911e-87f8e16831b1'::uuid,'Жаздыктарды жайгаштыруу боюнча колдонмо 🛏️','Жаздыкты миллиметрлеп оңдоо үчүн ыйлап жатабы? Уйкуга байланыштуу өзгөчө талаптары пайда болду. Эрежелерди сактаңыз, жаздыкты сызгыч менен ченегендей кылып түзөп, жарыкты чечкиндүү түрдө өчүрүп, ага ишеним бериңиз.','Patjade sättimise juhend 🛏️','Kas ta nutab, sest padi pole millimeetri pealt õigesti? Tekkinud on une-obsessioonid. Allu reeglitele, sätita padi nagu joonlauaga mõõdetult ja kinnita talle kindlalt, et kõik on korras, lülitades tuled otsustavalt välja.'),
('3b18406f-7fbc-4193-88c1-aa910648f2b5'::uuid,'Менин «казынамды» кайтарып бер! 🗑️','Алар сактап жүргөн эски шоколаддын кагазын ыргытып жибергениңиз үчүн дүйнө кыйрагандай болдубу? Сиз үчүн таштанды болгон нерсе, алар үчүн казына болушу мүмкүн. Аларды башка жалтырак оюнчук менен алаксытып коюңуз.','Anna mu „aare“ tagasi! 🗑️','Kas maailm sai otsa, sest viskasid ära selle vana šokolaadipaberi, mida ta hoidis? See, mis on sinu jaoks prügi, on tema jaoks aare. Hajuta tema tähelepanu õrnalt mõne teise särava mänguasjaga.'),
('3d6e1c1c-6a73-4824-ae1e-d09852574023'::uuid,'Дасторкон башындагы кичинекей диктатор 👑','Эртең мененки тамактануу учурунда «бул жерге отур, тигил жерге эмес» деп баарын башкаргысы келип жатабы? Алардын эркин сындырбай, бөлмөдөгү тең салмактуулукту жана тынчтыкты сактоо үчүн жылмайып: «Макул, сенин айтканыңдай болсун» деп коюңуз.','Väike diktaator söögilaua taga 👑','Kas ta üritab hommikusöögilauda kontrollida, öeldes: "Istu siia, mitte sinna"? Ilma tema tahet jõhkralt murdmata säilita toas tasakaal ja rahu väikese naeratusega: "Olgu, teeme nii, nagu sina tahad."'),
('51ca75c5-97b8-4826-b323-ca25f125a567'::uuid,'Сиз эч кимге түшүндүрмө берүүгө милдеттүү эмессиз 📝','Үйдөгү чарчаганыңызды эч ким көрбөгөндөй сезилип, жарылып кетчүдөй болуп жатасызбы? Маанай күндөлүгүңүздү ачыңыз. Бүгүн сизди жиниңизге тийгизген нерселердин баарын жазып чыгыңыз. Сезимдериңизди таанып, кагазга түшүрүү сизге абдан жардам берет.','Sa ei pea kellelegi aru andma 📝','Kas tundub, et keegi ei näe, kui kurnatud sa kodus oled, ja see ajab sind plahvatama? Ava oma meeleolupäevik. Kirjuta üles kõik, mis sind täna hulluks ajab. Oma emotsioonide teadvustamine ja väljakirjutamine aitab sind tohutult.'),
('989e82d9-dbab-4ad4-8fb4-42a6025e0511'::uuid,'Тынч окуу убактысы 📖','Бүгүн китеп окуу жок. Жөн гана биздин «Акылдуу жомоктор» бөлүмүнөн жагымдуу музыканы коюп, сүрөттөрдү чогуу унчукпай карап отуруңуз. Алардын мээси визуалдык жактан чарчап, сиз бир ооз сөз айтпастан эле уйкуга кетишет.','Vaikne lugemisaeg 📖','Täna õhtul lugemist ei toimu. Pane lihtsalt mängima rahustav taustamuusika meie ''Nutikatest lugudest'' ja vaadake vaikides koos pilte. Tema aju väsib visuaalselt ja ta uinub, ilma et peaksid ühtegi sõna ütlema.'),
('6f490476-47fe-4d7a-adc6-bf02e33e53bc'::uuid,'Кассадагы кезектин сыноосу 🛒','Кассанын алдында шоколад деп кыйкырып жатышабы? Артыңыздагылардын караганына карабай, бербеңиз. Соода тизмеңизди ачып: «Бул тизмеде жок, касса аны сканерлебейт» деп айтыңыз. Эгерде чечкиндүү болсоңуз, алар акыры токтошот.','Kassajärjekorra väljakutse 🛒','Kas ta karjub kassas šokolaadi järele? Ära anna järele, hoolimata järjekorras olijate pilkudest. Ava oma ostunimekiri ja ütle talle: "Seda pole nimekirjas ja kassapidaja ei saa seda läbi lüüa." Kui oled kindlameelne, annab ta lõpuks järele.'),
('851d1060-8f2e-4d29-b181-eb135eec18ca'::uuid,'Кол менен эмес, ооз менен тамактануу 🐶','Тарелкадан кол колдонбой, мышыктай болуп жегиси келип жатабы? Тыюу салбаңыз. Ашкана баары бир булганат, 5 мүнөт мышык болуп ойносун. Бул кызыктуу оюн табиттин жоктугун жеңүүнүн эң шаңдуу жолу.','Söömine suuga, mitte kätega 🐶','Kas ta tahab süüa nagu kass taldrikult, käsi kasutamata? Ära keela seda. Köök läheb niikuinii mustaks; lase tal 5 minutit kass olla. See naljakas rollimäng on kõige rõõmsam viis isutuse ületamiseks.'),
('9555c57b-eea5-4d41-a55f-827af2218674'::uuid,'Атанын ийиндерин укалоо 💆‍♂️','Күн бою алардын артынан чуркап, оюнчуктарды жыйнап, бутуңуз жана белиңиз ооруп жаткандыр. Балаңыз уктаары менен өнөктөшүңүздөн 10 мүнөт ийинге массаж жасоону сураныңыз. Сиз бул үйдүн кыймылдаткычысыз, өзүңүздү калыбына келтирүү үчүн убакыт табуу абдан маанилүү.','Issi õlamassaaž 💆‍♂️','Oled terve päeva jalgadel olnud, neil järel jooksnud ja mänguasju korjanud – su selg peab kindlasti valutama. Niipea kui laps magab, palu partnerilt 10-minutilist õlamassaaži. Sina oled selle kodu mootor; on hädavajalik, et saaksid aega akude laadimiseks.'),
('ac3ac13e-8fa6-42b2-ace2-92fa2336b5eb'::uuid,'Бөлмөнү толук караңгылатуу 🌌','Коридордон түшкөн жарыктын шооласынан улам уктабай жатышабы? Алар идеалдуулукту издеп жатышат. Эшикти бекем жаап, бөлмөнү толук караңгылатыңыз, мелатонин өз ишин жасап, аларды тез эле уйкуга киргизет.','Täielik pimedus toas 🌌','Kas ta ei saa magada koridorist tuleva valguskiire tõttu? Ta otsib täiuslikkust. Sulge uks tihedalt, pimenda tuba täielikult ja lase melatoniinil oma loomulikku tööd teha, uinutades ta kiiresti.'),
('e268e86b-b622-447e-800e-69d444728521'::uuid,'«Бул меники!» фазасы 🧸','Үйдө пультту кучактап алып: «Бул меники!» деп жатышабы? Алар ээлик кылуу чегин сынап жатышат. Аларды ач көз деп атабаңыз. Тескерисинче: «Мага таап бергениң үчүн рахмат!» деп, көңүлүн башка оюнга буруп, пультту кайтарып алыңыз.','„See on minu!“ faas 🧸','Kas ta hoiab kodus pulti ja hüüab: "See on minu oma!"? Ta katsetab omandiõiguse piire. Ära nimeta teda isekaks. Ütle hoopis: "Aitäh, et sa selle minu jaoks leidsid!" ja suuna tema tähelepanu õrnalt teisele mängule, et see tagasi saada.'),
('e71d30e6-0cdb-4938-b907-fc93e194b4d5'::uuid,'Чала сүйлөгөн сүйлөмдөрүн чечмелөө 🗣️','Унутуп калган сөзүн табууңузду күтүп, колу менен ишарат кылып жатышабы? Акыры сөзүн бүтүргөндө, алардын жүзүндөгү жеңилдикти сабырдуулук менен байкаңыз. Алар сиздин колдооңуз менен сөз байлыгын жана өзүнө болгон ишенимди бекемдеп жатышат.','Poolikute lausete dešifreerimine 🗣️','Kas ta teeb kätega žeste, oodates, et leiaksid sõna, mille ta on unustanud? Jälgi kannatlikult kergendust tema näol, kui ta lõpuks lause lõpetab. Ta arendab oma sõnavara ja enesekindlust just tänu sinu toetusele.'),
('0a86e24e-bf60-4b61-ae36-925c5211691c'::uuid,'Сууну «кургатуу» талабы 💧','Чөйчөктөгү сууну ичкендин ордуна: «Бул өтө нымдуу экен, кургатып бер!» деп кыйкырып жатышабы? Логика издебеңиз; сууну башка түстөгү чөйчөккө куюп: «Мен сага кургак суу алып келдим!» деп айтыңыз. Иллюзия өнөрү — энеликтеги эң чоң куралыңыз.','Nõudmine teha vesi „kuivaks“ 💧','Kas ta keeldub tassist vett joomast ja karjub: "See on liiga märg, tee kuivaks!"? Ära otsi loogikat; kalla vesi lihtsalt teist värvi tassi ja ütle: "Tõin sulle kuiva vett!" Illusioonikunst on sinu suurim relv emaduses.'),
('b27687ec-9619-4dbe-be9c-054706708b62'::uuid,'Жаратылышка качып чыгуунун маанилүүлүгү ⛅','Төрт дубалдын ичинде алардын энергиясы агрессияга айланып, ар бир сүйлөмү «жок» деп башталып жатабы? Аба ырайына жана кийимине ишенип, сөзсүз түрдө сыртка алып чыгыңыз. Жерге тийүү алардын нерв системасын дароо калыбына келтирет.','Hädavajalik põgenemine loodusesse ⛅','Kas tema energia muutub nelja seina vahel agressiivseks ja iga lause algab sõnaga ''ei''? Usalda ilma ja tema riietust ning vii ta kindlasti õue. Maa puudutamine lähtestab tema närvisüsteemi hetkega.'),
('eeca2adc-6712-4238-9603-30877865ed81'::uuid,'Автоматтык уйку үчүн коңгуроо ⏱️','Балаңыз уктоо маалы келгенде эле күтүүсүздөн дааратканага баргысы келип калабы? Таймер коюңуз. Таймер шыңгыраганда бардык жарыктар өчөт деген бекем эреже киргизип, бул бүтпөгөн "дагы бир нерсе" деген шылтоолорго жана чебер манипуляцияга ашыкча талаш-тартышсыз чекит коюңуз.','Kellahelin automaatseks uneks ⏱️','Kas lapsel on äkki vaja tualetti minna just siis, kui on magamaminekuaeg? Pane taimer. Kehtesta kindel reegel, et kui taimer heliseb, kustuvad kõik tuled, ja tee lõpp sellele lõputule ''veel üks asi'' mangumisele ja meisterlikule manipuleerimisele.'),
('4e140178-6301-4406-9f9f-fe623cbcfff7'::uuid,'Эшиктин артында катылып ойноо 🙈','Бала бакчага кечигип жатасыз, бирок ал "Мени тап!" деп парданын артына жашынып алдыбы? Урушуу процессти узартат гана. "Менин кичинекейим кайда экен?" деп, 2 мүнөт оюнга кошулуңуз да, аны күлдүрүп ээрчитип чыгыңыз.','Peitusemäng ukse taga 🙈','Olete lasteaeda hiljaks jäämas, aga tema peidab end kardina taha ja ütleb: "Leia mind!" Karjumine ainult pikendab protsessi. Ütle: "Kus mu väike lapsuke küll on?" Liitu mänguga 2 minutiks ja meelita ta itsitades välja.'),
('7964aed1-1770-40a2-a565-23bfdc9aea21'::uuid,'Акылдуу жомоктордогу ар түрдүү үн эффекттери 🪄','''Акылдуу жомокту'' ачыңыз. Жомокту окуп жатканда эшиктин кычыраганы, шамалдын үнү жана шыбыроо сыяктуу эффекттерди кошуп, бөлмөдө "үн театрын" түзүңүз. Бул өзгөчө үндөр алардын кыялдануусун дароо өзүнө тартып, жомоктун ичине тереңирээк сүңгүтөт.','Mitmekesised heliefektid nutikates lugudes 🪄','Ava ''Nutikad lood''. Lugu lugedes loo toas ''heliteater'', lisades efekte nagu kriuksuv uks, tuuleiilid ja sosinad. Need ebatavalised helimaastikud haaravad ta kujutlusvõime ja tõmbavad ta sügavamale loosse.'),
('c87486c1-f5de-473b-8cd5-b9e2e2bd31c1'::uuid,'Экрансыз эс алуу дилеммасы 📺','Сиздин жумушуңуз көп болгондуктан, ал бүгүн сыналгынын алдында өтө көп убакыт өткөрдүбү? Өзүңүздү күнөөлүү сезип жатасызбы? Күн сайын идеалдуу болуу мүмкүн эмес. Кээде экрандар бизди толук башаламандыктан куткарган эң зыянсыз бала багуучу болуп саналат. Эс алыңыз.','Ekraanivaba pausi dilemma 📺','Kas ta veetis täna liiga palju aega teleri ees, sest sul oli palju tegemist? Kas süütunne närib sind? Sa ei saa olla iga päev täiuslik. Mõnikord on ekraanid kõige süütumad lapsehoidjad, mis päästavad meid täielikust kaosest. Lõõgastu.'),
('0c893825-691b-4509-9849-6369336b84d4'::uuid,'Өз эмгегин өзү талкалаган сүрөтчү 🖍️','Тарткан сызыгы жакпай калып, "Бул жаман болду!" деп сүрөтүн жыртып салдыбы? Өзүн-өзү сыноо жана перфекционизм сезими ойгонуп жатат! "Кийинкисинде башка түстү колдонуп көрөлү!" деп, анын нааразычылыгын жаңы ачылышка айлантыңыз.','Kunstnik, kes hävitab oma teose 🖍️','Kas ta rebis oma joonistuse katki, öeldes ''See on kole!'', sest talle ei meeldinud tõmmatud joon? Enesekriitika ja täiuslikkuseiha on tärkamas! Pööra tema pettumus avastuseks, öeldes: "Proovime järgmine kord teist värvi!"'),
('bcac5731-4815-4adc-beb4-861e3ff078b1'::uuid,'Мышыктай болуп эркелеп сүйкүнүү 🐾','Бул таңда ал төрт аяктап жөрмөлөп, бутуңузга сүйкөнүп, жөн эле мыёолоп жатабы? Аны токтотуп акыл үйрөтүүнүн ордуна, сүт куюлган идишти сунмуш этиңиз. Урушканга караганда ойноо ар дайым оңой жана кызыктуураак.','Hõõrumine helluse märgiks, nagu kassil 🐾','Ta roomab täna hommikul neljakäpukil, hõõrub end vastu su säärt ja lihtsalt näub? Selle asemel, et teda manitseda, ulatas talle mängult kausitäis piima. Mängimine on alati lihtsam ja lõbusam kui keelamine.'),
('c6026760-e985-429a-b39f-d4d1786df630'::uuid,'Ваннадагы кичи лаборатория 🛀','Сууга ар кандай түстөгү самындарды аралаштырып, "сыйкырдуу суусундуктарды" жасап жатабы? Ооба, жуунуучу бөлмө бир аз кирдеши мүмкүн, бирок ал эриткичтер жана реакциялар жөнүндө үйрөнүп жатат! Бул кичинекей илимий изилдөө – күндүн чарчоосун жууп, аны тынч уйкуга акырын даярдоонун эң сонун жолу.','Vannitoa minilabor 🛀','Kas ta segab vees erinevaid seepe, luues ''võlujooke''? Jah, vannituba võib veidi sassi minna, aga ta õpib lahustite ja reaktsioonide kohta! See väike teaduslik uurimus on suurepärane viis päeva väsimuse mahapesemiseks ja rahulikuks uneks valmistumiseks.'),
('40e041b4-2484-475f-93b5-25cda3ee362e'::uuid,'«Сен кимсиң?» оюну 🎭','Сизди чоочун адамдай карап, "Сиз кимсиз? Менин апам кайда?" деп сурап жатабы? Бул жаңы ролдук оюн. "Мен Доктор эжекемин, сенин жүрөгүңдү укканы келдим" деп, аны кытыгылаңыз. Бөлмө таңкы күлкүгө бөлөнсүн.','Mäng „Kes sa oled?“ 🎭','Kas ta vaatab sind nagu võõrast ja küsib: "Kes sa oled? Kus mu emme on?" See on uus rollimäng. Ütle: "Olen tädi Doktor ja tulin su südant kuulama," ja kõdita teda. Las tuba täitub hommikuse naeruga.'),
('417e0bcc-cf3b-4a96-95e9-58a2f51764f6'::uuid,'Даарат кагазынан жасалган искусство 🧻','Бөлмөгө кирип, даараткана кагазынын баары түрмөктөн чечилип, үйгө чачылып калганын көрдүңүзбү? Ачуулануунун ордуна, ал кагаздарды чогултуп, чогуу топ жасаңыздар. Башаламандыкты кыйкырык менен эмес, чыгармачылык жана күлкү менен жеңиңиз.','Tualettpaberi kunst 🧻','Kõndisid tuppa ja leidsid kogu tualettpaberi lahti rullituna üle terve maja? Selle asemel, et pahandada, korja paberid kokku ja tehke koos pall. Alista kaos mitte karjumise, vaid loovuse ja naeruga.'),
('4a1de341-603c-4aae-ab4d-439d7bb05d7c'::uuid,'Жымжырттыктын ырахаты 🤫','Акыры укташты. Үйдө кулак тундурган тынчтык орнодубу? Тиркемебиздеги «Үн өлчөгүчтү» (Sound Meter) ачыңыз. «0 децибел» деген жазууну көрүү чарчаган, ызы-чуудан тажаган мээңиз үчүн эң сонун визуалдык эс алуу болот.','Vaikuse nauding 🤫','Nad on lõpuks magama jäänud. Kas majas valitseb nii sügav vaikus, et kõrvus kohiseb? Ava meie äpis helimõõtja. Selle „0 detsibelli“ näidu jälgimine on ülim visuaalne massaaž sinu väsinud ja mürast küllastunud ajule.'),
('3d9dcc3e-1698-4fca-951e-a58aed0724d2'::uuid,'«Туура эмес чөйчөк» үчүн ыйлоо 🥤','Сууну сары чөйчөккө куюп бергениңиз үчүн бөлмөдө кыямат кайым болдубу? Ашыкча ойлонбоңуз; ал жөн гана ушул таңда чектерди сынап жатат. Сууну дароо көк чөйчөккө куюп берип, бөлмөдөгү тынчтыкты калыбына келтирүү менен энергияңызды сактап калыңыз.','„Vale värvi tassi“ kokkuvarisemine 🥤','Kas toas läks põrgu lahti, sest andsid talle vett kollases tassis? Ära mõtle üle; ta lihtsalt katsetab täna hommikul piire. Kalla vesi kiiresti sinisesse tassi ja hoia oma energiat, taastades toas rahu.'),
('522145b2-4826-4821-80c0-e0e180045415'::uuid,'Жөн гана кучактап туруу 🫂','Бүгүнкү күн чындап эле энергияңызды соруп, сабырыңызды сынадыбы? Бирок азыр анын ушунчалык бейпил жана бейкүнөө уктап жатканын караңызчы... Жарыкты өчүрүп, жомокту бир азга кое туруңуз. Анын жанына жатып, наристенин таттуу жытын терең жыттап, ушул тынч мүнөт үчүн жөн гана ыраазы болуңуз.','Lihtsalt lähedal hoidmine 🫂','Kas tänane päev kurnas su energia ja pani kannatuse proovile? Aga vaata teda nüüd, magab nii rahulikult ja süütult... Kustuta tuled, jäta lugu korraks vahele. Heida tema kõrvale, hinga sisse seda magusat beebilõhna ja tunne lihtsalt tänulikkust selle vaikse hetke eest.'),
('792e3525-032e-4662-ba49-1276a3b3ef78'::uuid,'Башка энелердин окуялары 💬','Инстаграмдан ар кимдин "идеалдуу" баласын көрүп көңүлүңүздү чөгөрбөңүз! Ал тиркемени жаап, Anacan Коомчулугуна кириңиз. Башкалардын да үйү сиздикиндей эле чачык экенин түшүнгөндө, терең дем алып эс алыңыз.','Teiste emade lood 💬','Ära lase end heidutada, nähes Instagramis kõigi ''täiuslikke'' lapsi! Sulge see äpp ja sisene Anacani kogukonda. Hinga sügavalt sisse, kui mõistad, et kõigi kodud on sama sassis kui sinu oma.'),
('3e4bbd84-ef8f-45a2-b630-5aeadd95390e'::uuid,'«Колумду кармаба!» деген көз карандысыздык декларациясы 🚶‍♂️','Колуңузду кое берип, жолдо эркин баскысы келип жатабы? Эгер ал коопсуз аймак болсо, ага өз алдынчалыгын сыноого мүмкүнчүлүк бериңиз. Жөн гана эки кадам артта ээрчип, бул кичинекей, эркин рухтуу козголоңчуну сыймыктануу менен карап туруңуз.','„Ära hoia mu käest kinni!“ iseseisvusdeklaratsioon 🚶‍♂️','Kas ta tahab su käest lahti lasta ja teel vabalt kõndida? Kui see on ohutu tsoon, lase tal oma iseseisvust katsetada. Lihtsalt kõnni kaks sammu tagapool ja vaata uhkusega seda väikest vabameelset mässajat.'),
('6dda8fe5-3765-4d3c-bdfe-6519fcf2d0a0'::uuid,'Ашканадагы жардамчынын кырсыгы 🧑‍🍳','Сиз камыр жайып жатканда, ал отургучту сүйрөп келип, унду сөзсүз өзүм куям деп туруп алдыбы? Эгер уруксат бербесеңиз, көз жаш төгүлөт. Ага кичинекей желим идиш жана бир аз ун бериңиз. Ашкана чачылышы мүмкүн, бирок анын жетишкендик сезими көкөлөйт.','Köögis abistamise katastroof 🧑‍🍳','Kas rullisid tainast, kui ta tõi tooli ja nõudis, et saaks ise jahu puistata? Kui sa ei luba, järgnevad pisarad. Anna talle väike plastkauss ja natuke jahu. Köök võib küll sassi minna, aga tema saavutustunne kasvab taevani.'),
('776040ef-af05-4430-a752-3b380b194dba'::uuid,'Ай бизди кууп келе жатат 🌕','Кечинде үйгө баратканда терезени карап, "Ай бизди ээрчип келе жатат!" деп таң калып жатабы? Ал чындап эле аалам анын айланасында айланат деп ишенет. Анын таттуу кыялын бузуунун ордуна, "Кызык, ал биз менен кайда саякаттап баратат болду экен?" деп сурап, бул сыйкырга кошулуңуз.','Kuu ajab meid taga 🌕','Kas ta vaatab õhtul koju sõites aknast välja ja hüüab: "Kuu käib meiega kaasas!"? Ta usub siiralt, et universum tiirleb tema ümber. Selle asemel, et tema armsat kujutlusvõimet purustada, ühine maagiaga, küsides: "Huvitav, kuhu ta koos meiega reisib?"'),
('58e2fe84-f6c5-40ff-93ab-26ea06ad9f14'::uuid,'Кир көйнөктүн бейпилдиги 👕','Үч күн катары менен бир эле көйнөктү кийип, аны жуудурбай жатабы? Бул куракта кээ бир буюмдар аларга коопсуздук сезимин тартуулайт. Талашпаңыз. Тескерисинче, көйнөктү кир жуугуч машинага сыйкырдуу саякатка жөнөткөнүңүздү жана ал кайра күчтүү болуп кайтып келерин айтып, оюн катары колунан алыңыз. Алар бул жомокко ишенишет.','Musta särgi lohutav mõju 👕','Kannab kolm päeva järjest sama särki ja keeldub laskmast seda pesta? Selles vanuses pakuvad mõned esemed neile turvatunnet. Ära vaidle. Selle asemel ütle, et saatsid särgi pesumasinasse maagilisele seiklusele ja see tuleb sealt tugevamana tagasi – võta see mängleva kergusega nende käest. Nad usuvad seda illusiooni.'),
('b740d6be-007b-4aa6-9c46-6ffbce8b157e'::uuid,'Кумурсканы акыркы сапарга узатуу 🐜','Паркта жерден кумурсканы көрүп, ал адашып калды деп ыйлап, ордунан жылбай жатабы? Алардын боорукердиги чексиз! Апасы жакында келип, аны үйүнө алып кетерин айтыңыз.','Sipelga matused 🐜','Nägid pargis maas sipelgat ja ei taha edasi liikuda, nuttes, et ta on ära eksinud? Nende empaatiavõimel pole piire! Ütle neile, et sipelga emme tuleb talle varsti järele ja viib ta koju.'),
('fcc60573-09e9-4a7c-8399-55df532828cd'::uuid,'Саздуу жердин ак ызы-чуусу 🌊','Тынчтануунун ордуна бөлмө ичинде секирип жатышабы? Sound Meter''дин фондук жөндөөлөрүнөн океан толкундарынын же ак ызы-чуунун үнүн коюңуз. Ал жагымдуу, бир калыптагы жыштык алардын ашыкча энергиясын басып, 10 мүнөттүн ичинде көздөрү жумула баштайт.','Soolalauka valge müra 🌊','Kas nad ei jää rahulikuks, vaid hüppavad mööda tuba ringi? Pane mängima võimsad ookeanilained või valge müra helimõõturi taustavalikutest. See rahustav, monotoonne sagedus aitab nende liigset energiat hajutada ja silmad vajuvad tõenäoliselt 10 minuti jooksul kinni.'),
('73abbd29-9b2f-4f48-8461-6482853b741f'::uuid,'Шыпыргы менен жардам берүүнүн тескери натыйжасы 🧹','Үйдү жыйнап жатканда «Мен жардам берем!» деп келип, тескерисинче чачып жатышабы? Эгер тыюу салсаңыз, ыйлап чыгышы мүмкүн. Аларга нымдуу салфетка берип: «Сен столдун ушул бурчуна жооптуусуң» деп айтыңыз. Ошентип, сиз ишиңизди бүтүрөсүз, алардын да өзүнө болгон ишеними артат.','Luua abilise äpardus 🧹','Kui sa koristad, kas nad tulevad ütlema „Mina teen!“ ja ajavad segaduse hoopis suuremaks? Kui sa neid ei luba, tuleb suur nutuhoog. Anna neile niiske lapp ja ütle: „Sinu vastutada on ainult see lauanurk.“ Nii saad sina oma asjad tehtud ja nende väike ego saab tublisti kosutust.'),
('eacaec53-45d2-4b70-9f52-8b48878bd78c'::uuid,'Бош дубалды тиктеп отуруу убактысы 🛋️','Балаңыз бөлмөдө өз алдынча тынч ойноп жатабы? Сураныч, бул баалуу учурду идиш жууп өткөрүп жибербеңиз! Диванга отуруп, чайыңызды алып, дубалды карап эле отуруңуз. Ооба, эч нерсени ойлонбой. Маанай күндөлүгүңүзгө «5 мүнөттүк таза тынчтык» деп белгилеп коюңуз. Сиз буга татыктуусуз.','Tühja seina vahtimise aeg 🛋️','Kas su laps mängib toas vaikselt omaette? Palun ära raiska seda väärtuslikku hetke nõude pesemisele! Mine diivanile, võta teetass ja lihtsalt vaata seina. Jah, mõtlemata mitte millelegi. Märgi oma tujupäevikusse „5 minutit puhast rahu“. Sa oled seda tõesti väärt.'),
('f172b5bc-02ec-44a8-9df7-fcc0cfb0c0e3'::uuid,'«Чачым сынып калды!» драмасы 🪮','Таракты көрөрү менен чачы ооруп жатканын айтып качып жатабы? Сенсордук сезимталдык аны коркутат. Көңүлүн алаксытыңыз. Колуна күзгү берип, «Кел, ким күзгүдө күлкүлүү тил чыгарат экен?» деп, ал алаксып жатканда чачын тез эле тарап бүтүрүңүз.','„Mu juuksed läksid katki!“ draama 🪮','Kas laps jookseb minema kohe, kui näeb kammi, väites, et juuste kammimine on valus? Sensoorne tundlikkus teeb teda ärevaks. Hajuta ta tähelepanu. Anna talle kätte peegel ja küsi: „Vaatame, kes teeb peeglis naljakama näo?“ Samal ajal kui ta on ametis, saad juuksed sekunditega ära kammida.'),
('2127b5f4-7e9a-438e-9094-bd9d7f0d5237'::uuid,'Азык-түлүк тизмеси менен шантаж 🛒','Кассада күтүлбөгөн жерден момпосуй талап кылып жатабы? Ата-энелик тарбияңызга карата айланадагылардын сындаган көз караштарына көңүл бурбаңыз. Соода тизмеңизди ачып: «Бул тизмеде жок, кассир бизге сатпайт» деп бекем туруңуз.','Toidupoe nimekirja väljapressimine 🛒','Kas nad nõudsid kassajärjekorras ootamatult kommi? Ignoreeri täielikult teiste hukkamõistvaid pilke oma kasvatusmeetodite kohta. Ava oma ostunimekiri, teata: „Seda nimekirjas pole, müüja ei müü seda meile,“ ja jää endale kindlaks.'),
('73af2e7a-1bb5-4576-8888-801050bfada3'::uuid,'Дубалдагы карандаш сүрөттөрү! 🖍️','Бөлмөгө кирип, дубалга тартылган жаңы «сүрөттү» көрдүңүзбү? Терең дем алыңыз. Алар кагаздын чегинен чыгып, өзүнүн моторикасын чоң масштабда изилдеп жатышат. Тазалоодон мурун, бул шедеврди сүрөткө тартып алыңыз, келечекте ага көрсөтүп чогуу күлөсүз.','Rasvakriidid seintel! 🖍️','Astud tuppa ja avastad seinalt uue seinamaalingu? Hinga sügavalt sisse. Nad avastavad oma motoorseid oskusi suures plaanis, ületades paberi piire. Enne kui selle ära puhastad, tee sellest meistriteosest kindlasti foto, et saaksid seda neile tulevikus näidata ja koos naerda.'),
('f6ed5025-5dc3-4f4a-8ce2-d48478e2666f'::uuid,'Экранда тынчтык орноду 📉','Алар акыры укташты. Бирок кулагыңызда дагы эле элес ыйлар угулуп жатабы? Sound Meter''ди ачыңыз. Бөлмөдөгү үн 0 децибелге түшкөнүн көрүү чарчаган мээңиз үчүн эң сонун эс алуу болот.','Ekraanil kinnitatud vaikus 📉','Nad on lõpuks magama jäänud. Aga kas su kõrvus kumiseb ikka veel fantoomkisa? Ava helimõõtur. Selle joone langemine toas 0 detsibellini on kõige ilusam visuaalne massaaž su väsinud ja sumisevale ajule.'),
('48318bc7-c4f3-4717-9848-18bd10967e29'::uuid,'Атанын ойдон чыгарган жомогу 🦸‍♂️','Сүйлөөгө алыңыз жокпу, китеп окугуңуз келбей жатабы? Жомок айтууну атасына тапшырыңыз. Ал балаңыз башкы каарман болгон күлкүлүү, ойдон чыгарылган окуяны айтып берсин. Диванга жатып, балаңыздын атасы менен кошо каткырып жатканын карап эс алыңыз.','Issi improviseeritud unejutt 🦸‍♂️','Oled rääkimiseks liiga väsinud ega taha raamatut lugeda? Anna unejutu lugemine üle issile. Las ta räägib ühe tobeda, väljamõeldud loo, kus su laps on peategelane. Lõõgastu diivanil ja vaata, kuidas laps issi juttude peale naerust rõkkab.'),
('4ac93f87-372d-4d1a-a449-a2da763a8227'::uuid,'«Туура эмес формадагы» тамак дилеммасы 🥒','Бадыраңды тегерек эмес, узун туураганыңыз үчүн тарелкасын түртүп жатабы? Алардын тамак-аш эстетикасы өнүгүп жатат! Ошол эле жашылчаларды кызыктуу формада «жашырууну» үйрөнүңүз. Бул дизайн оюнунда сиз жеңесиз.','„Vale kujuga“ toidu dilemma 🥒','Kas nad lükkasid taldriku eemale, sest lõikasid kurgi pikkadeks ribadeks, mitte ringideks? Nende toiduesteetika on täies hoos arenemas! Õpi samu köögivilju lõbusate kujunditena „maskeerima“. Võidad selle disainimängu kindlasti.'),
('61167ef0-dce7-4186-9b36-5aa8a00936ff'::uuid,'Жалгыз калуу үчүн ваннага качуу 🛀','Күнү бою бутуңузга жармашып, тынымсыз тийүүдөн чарчадыңызбы? «Сенсордук чарчоо» — бул реалдуу нерсе. Аларды бөлмөдө коопсуз калтырып, ваннага кирип, эшикти жаап, 5 мүнөт жөн гана дем алыңыз. Сизге кайрадан күч топтоо керек.','Põgenemine vannituppa omaette olemiseks 🛀','Nad on terve päeva su jala küljes rippunud ja tunned pidevast puudutusest tuimust? „Puudutustest üleküllastumine“ on päris asi. Jäta nad turvaliselt tuppa, lipsa 5 minutiks vannituppa, pane uks kinni ja lihtsalt hinga. Vajad akude laadimist.'),
('4c96a8e1-971d-4b98-9e5c-faff2c2726a9'::uuid,'Күтүлбөгөн жерден келген философиялык ойлор 🤔','Күтүлбөгөн жерден «Океандын түбү эмне үчүн караңгы?» деген сыяктуу илимий суроо берип жатабы? Кабатыр болбоңуз! Anacan AI''ды ачыңыз, педиатрлар жана психологдор тарабынан жактырылган, алардын курагына ылайыктуу жомок сыяктуу жоопту алып, окуп бериңиз. Сиз дайыма баарын билген эң мыкты апасыз!','Äkiline filosoofiahoog 🤔','Nad esitasid äkki teadusliku küsimuse, näiteks: „Miks on ookeanipõhi pime?“ Ära muretse! Ava Anacan AI, saa kõige armsam, lastearsti ja psühholoogi heakskiidetud, muinasjutuline ja nende vanusele sobiv vastus ning loe see neile ette. Oled alati ema, kes teab kõike!'),
('9f289ae7-fe30-4b1a-8ebd-63874521363d'::uuid,'Караңгы бөлмөдөгү жашынмак 🔦','Уйку убактысы келсе да, алар дагы эле энергияга толуп турабы? Бөлмөдөгү бардык жарыкты өчүрүңүз. Кичинекей фонарикти алып, «дубалдагы жарык кимге тиет?» оюнун ойноңуз. Караңгыда ойноо мелатониндин иштелип чыгышын жогорулатат жана аларга тынчтанып, уктоого жардам берет.','Peitusemäng pimedas toas 🔦','On aeg magama minna, aga nad on ikka veel energiat täis? Kustuta toas kõik tuled. Võta väike taskulamp ja mängige „keda valgus seinal tabab?“. Pimedas mängimine soodustab melatoniini tootmist ja aitab neil rahuneda.'),
('d28d5d46-d2a6-4daa-b454-adbdf6be3f63'::uuid,'Көрүнбөгөн жаракаттын азабы 🩹','Бармагында эч нерсе жок болсо да, канап жатат деп ыйлап, пластырь сурап жатабы? Бул физикалык оору эмес, аларга сиздин мээримиңиз жана көңүл бурууңуз керек. Пластырь чаптап, өөп коюңуз да, сыйкырдуу өбүү менен айыктырганыңызды айтыңыз. Күнүңүз сакталды!','Nähtamatu haiget saamise piin 🩹','Sõrmel pole midagi viga, aga nad nutavad, väidavad, et see veritseb ja küsivad plaastrit? Siin pole küsimus füüsilises valus; nad vajavad sinult lohutust ja empaatiat. Pane plaaster peale, anna musi ja ütle, et ravisid selle maagilise suudlusega terveks. Sinu päev on päästetud!'),
('19ac1700-7f02-47aa-b9e8-f8064c7e18d0'::uuid,'Эшикти жабуу: Жеке мейкиндик 🚪','Бөлмөсүнө кирип, эшикти жаап, «Кирбе!» деп айттыбы? Бул нерсени жеке кабыл албаңыз. Алар ызы-чуудан жана башаламандыктан алыстап, тынчтык тапкысы келип жатышат. Эгер баары коопсуз болсо, аларга ошол жеке мейкиндиктен ырахат алууга мүмкүнчүлүк бериңиз. Алар чоңоюп жатышат!','Ukse sulgemine: isiklik ruum 🚪','Kas nad läksid oma tuppa, panid ukse kinni ja ütlesid: „Ära tule sisse“? Ära võta seda isiklikult. Nad tahavad lihtsalt mürast ja kaosest eralduda, et leida veidi rahu. Kui kõik on turvaline, lase neil seda isiklikku ruumi nautida. Nad kasvavad suureks!'),
('2cb51eab-cbdc-48ba-8569-e245d61ad27e'::uuid,'Түнкүсүн айтылган чексиз шылтоолор 🚰','Көздөрү жумулуп баратканда, күтүлбөгөн жерден «Бутум кычышып жатат!» же «Суусадым!» деп тура калышабы? Алар уктоо убактысын созуунун чеберлери. Таймер коюңуз. Телефон шыңгыраганда: «Бардык шылтоолор бүттү» деп айтыңыз. Телефонду авторитет катары колдонуп, өзүңүз бөлмөдөн чыгып кетиңиз.','Öised lõputud vabandused 🚰','Silmad vajuvad kinni, aga äkki kargavad nad püsti: „Jalg sügeleb!“ või „Mul on janu!“? Nad on uneaja edasilükkamise meistrid. Pane taimer. Kui telefon heliseb, ütle neile: „Kõik vabandused on nüüd otsas.“ Las telefon olla autoriteet ja sina saad lahkuda.'),
('9240add5-52c7-45dc-8ae0-15dd7dadfa88'::uuid,'Жок, бул менин атым эмес! 📛','Өзүн Спайдерменмин деп, аты менен чакырбагыла деп жатабы? Бул алардын инсандыгын изилдөө жолу. Оюнга кошулуңуз! Эртең мененки тамагын сунуштап: «Марк Спайдермен, мына тамагыңыз» деп айтыңыз. Бөлмөдөгү ар кандай чыңалууну бир нече секундда күлкүгө айландыруу сиздин колуңузда.','Ei, see pole minu nimi! 📛','Kas nad keelavad end oma nimega kutsuda, sest nad on Ämblikmees? See on nende viis identiteeti uurida. Mängi kaasa! Paku hommikusööki öeldes: „Palun väga, härra Ämblikmees.“ Sinu kätes on muuta igasugune pinge toas sekunditega komöödiaks.'),
('a897741a-cd22-4371-a712-b1ae3911676e'::uuid,'Өзүм ойлоп тапкан обондор 🎤','Күн да чыга электе секирип, катуу ырдап жатышабы? Аларга кыйкырып, тынчтан деп айтпаңыз. Эртең менен ыр менен баштаган бала энергиясын чыгарып жатат. Бир мүнөт болсо да ошол энергияга кошулуңуз, уйкуңуз дароо тарап кетет!','Minu enda väljamõeldud meloodiad 🎤','Päike pole veel tõusnudki, aga nad hüppavad ja laulavad valjult arusaamatuid sõnu? Ära karju ja käsi neil vait olla. Laps, kes alustab hommikut lauluga, vabastab oma energiat. Ühine selle metsiku energiaga kasvõi üheks minutiks ja su unine olek kaob hetkega!'),
('ad4460c3-33b8-4fdc-85b5-ca63eae32f6e'::uuid,'Инстаграмдагы «кемчиликсиз» энелер 📱','Instagram''ды ачып, баарынын үйү таптаза, балдары өтө акылдуу экенин көрүп көңүлүңүз чөктүбү? Ал тиркемени өчүрүңүз! Anacan коомчулугуна кириңиз. Үйү сиздики сыяктуу эле чачык, балдары сиздики сыяктуу эле өжөр болгон реалдуу энелердин окуяларын окуп, жеңилдеп калыңыз.','Instagrami „täiuslikud“ emad 📱','Kas avasid Instagrami ja tundsid end masendunult, nähes kõigi teiste täiuslikult korras kodusid ja uskumatult tarku lapsi? Kustuta see äpp! Tule Anacan kogukonda. Loe lugusid päris emadelt, kelle kodud on sama segased kui sinu oma ja kelle lapsed on sama kangekaelsed, ning tunne kergendust.'),
('38581365-03a6-48aa-a7b4-923dde40764d'::uuid,'Тепкичтердин азгырыгы 🧗‍♂️','Эгер үйдө тепкичтер же бийик жерлер болсо, алар сөзсүз изилдөөгө аракет кылышат. Коопсуздук тосмолорун орнотуунун убагы келди.','Trepi ahvatlus 🧗‍♂️','Kui kodus on treppe või kõrgemaid tasapindu, tahavad nad neid kindlasti uurida. On tõesti aeg paigaldada turvaväravad.'),
('b2cba04d-e6f3-4afd-a54a-7b8bbbf1f6e4'::uuid,'Уйку шыбыр менен келет 🤫','Төшөктөн качып, секирип жатышабы? Күтүлбөгөн жерден үнүңүздү акырын шыбырап сүйлөөгө өткөрүңүз. Сизди угуу үчүн алар физикалык жактан көңүл бурууга аргасыз болушат, мээси чарчап, 5 мүнөттүн ичинде уйку режимине өтөт. Байкап көрүңүз!','Uni saabub sosinal 🤫','Kas nad põgenevad voodist ja hüppavad igal pool? Langeta äkki oma hääl sosinani. Nad peavad sind mõistmiseks füüsiliselt keskenduma, nende aju väsib ja lülitub 5 minutiga unerežiimile. Proovi järele!'),
('1dcf070f-1d18-4228-b248-9ed1c6174aff'::uuid,'Сюрприз! Муздаткычтагы оюнчук 🧊','Муздаткычты ачып, ичинен оюнчук машина таап алдыңызбы? Бул эс тутумду өнүктүрүү жана буюмдарды ар кандай мейкиндикте сынап көрүү оюну. Ачууланбаңыз; бул көрүнүш алардын өнүгүүсүнүн бир бөлүгү.','Üllatus! Mänguasi külmkapis 🧊','Avad külmkapi ja leiad sealt mänguauto? See on mälu ja esemete erinevates kohtades katsetamise mäng. Ära vihasta; see näiliselt absurdne käitumine on osa nende arengust.'),
('ba708130-cef9-4b08-8a17-7c16cb66de0a'::uuid,'Үйдөн чыгуудан баш тартуу ⛅','Үй чачык, алар диванга отуруп алып ыйлап, чыкпай жатышабы? Аба ырайын текшерип, ылайыктуу кийиндирип, каршылык көрсөтсө да парка алып барыңыз. Таза аба бетине тийээри менен, ичиндеги бардык терс эмоциялар тарап кетет.','Keeldumine kodust lahkuda ⛅','Kodu on sassis ja nad nutavad diivanil, keeldudes lahkumast? Kontrolli ilma ja temperatuuri, riieta nad sobivalt ja isegi kui see on võitlus, vii nad parki. Niipea kui värske õhk neile näkku puhub, sulab kogu see kogunenud frustratsioon.'),
('c3fe5fd9-dde9-47f5-b95c-98d26881d393'::uuid,'Жомоктун каарманына айлануу 🪄','Акылдуу жомокторду ачыңыз. Каармандын атын балаңыздын атына алмаштырыңыз. Жомок бою ал каармандын канчалык эр жүрөк жана тил алчаак болуп уктаганын окуп бериңиз. Өзүн жомоктон укканда, алар эч каршылыксыз көздөрүн жумушат.','Loo kangelaseks saamine 🪄','Ava nutikad lood. Asenda kangelase nimi otse oma lapse nimega. Loe kogu loo vältel, kui vapralt ja kuulekalt see kangelane magas. Kui nad kuulevad loos iseennast, panevad nad silmad kinni ilma igasuguse protestita.'),
('139226ae-9370-42b4-954a-012623528599'::uuid,'Түнкүсүн себепсиз ыйлоолор 😭','Түн ортосунда көзү жумулуу бойдон ыйлап ойгонуп, сизди укпай жатабы? Ыйды талдоо функциясын колдонуңуз; бул чочуп ойгонуу (night terror) болушу мүмкүн. Аларды ойготпоого аракет кылыңыз, жанында туруп, колунан кармаңыз. Алар тынчтанып, кайра өз алдынча уктап кетишет.','Seletamatu kesköine nutt 😭','Kas nad ärkasid keset ööd nuttes, silmad kinni, ega kuule sind? Kontrolli nutuanalüüsiga; see on tõenäoliselt öine hirmuhoog. Ära proovi neid äratada, seisa lihtsalt nende kõrval, hoia käest. Nad rahunevad ja jäävad ise uuesti magama.'),
('a18289d8-27fc-49de-ad3f-5cb7e1e5a6a1'::uuid,'Апанын жашыруун шоколад убактысы 🍫','Шкафтын артында жашынып, алардан жашыруун шоколад жеп жатасызбы? Ырахаттанып жеңиз! Ал кичинекей глюкоза — чексиз «эмне үчүн?» деген суроолорго жана каприздерге чыдоо, энергияңызды калыбына келтирүү үчүн сиздин табигый укугуңуз. Бул үчүн эч качан өзүңүздү күнөөлүү сезбеңиз.','Emme salajane šokolaaditund 🍫','Kas sööd salaja kapi taga šokolaadi, peites end nende eest? Naudi seda! See väike glükoosilaeng on su loomulik õigus taluda neid lõputuid „miks-e“ ja jonnituure ning taastada oma energiat. Ära tunne selle pärast kunagi süüd.'),
('a4aa4ea2-4391-40e9-ab29-3d2dca2ff6fe'::uuid,'Көлөкө куумай: кызыктуу оюн! 🏃‍♂️','Көчөдө басып баратып, күтүлбөгөн жерден өз көлөкөсүн кармагысы келип чуркап кетиштиби? Алардын кыялы логикасынан ашып түшүүдө. Аларды токтотпоңуз; көчөнүн ортосунда өзүңүз да көлөкөңүздү кармоого аракет кылып, бул шайыр жана кызыктуу оюнга кошулуңуз. Жашоо өтө кыска, андыктан баарын олуттуу кабыл алуунун кажети жок!','Varjude tagaajamine: lõbus mäng! 🏃‍♂️','Kas nad jooksevad tänaval äkki minema, püüdes omaenda varju tabada? Nende kujutlusvõime on loogikast üle. Ära peata neid; ühine selle metsiku ja rõõmsa mänguga keset tänavat, püüdes ka ise oma varju tabada. Elu on liiga lühike, et seda nii tõsiselt võtta!'),
('4d4b704f-57d5-4f72-9df3-13398bb1f2e3'::uuid,'Бут кийимди тескери кийүү мезгили 👟','Оң бутундагы бут кийимди солго, солдукун оңго кийип алып, оңдоп коюуңузга жол бербей жатышабы? Жөн эле коюңуз! Алардын «муну өзүм жасадым» деген сыймыгы жана өз алдынчалык сезими эң сонун кийилген бут кийимден миллион эсе баалуу.','„Kingad vales jalas“ faas 👟','Kas nad panid parema kinga vasakusse jalga ja vasaku paremasse ning keelduvad laskmast sul seda parandada? Lihtsalt lase sel olla! Nende uhkus öelda „ma tegin ise“ ja nende iseseisvustunne on miljon korda väärtuslikum kui ideaalselt jalas olevad kingad.'),
('95ee8df4-a59a-42f4-b252-bf062304f70b'::uuid,'Ачуумду санариптик жол менен чыгаруу 📝','Бүгүн канчалык чарчаганыңызды эч ким байкабай жаткандай сезилип, жылмаюу сизге оор болуп жатабы? Күндөлүгүңүздү ачыңыз. Бардык чарчооңузду жана нааразычылыгыңызды экранга төгүңүз. «Мен аябай чарчадым» деп жазуу баары жакшы деп жалган жылмайгандан көрө тезирээк жеңилдетет.','Oma viha digitaalne väljendamine 📝','Kas tundub, et keegi ei näe, kui kurnatud sa täna oled, ja naeratamine tundub lämmatav? Ava oma meeleolupäevik. Vala kogu see frustratsioon ja väsimus ekraanile. Kirjutamine „Olen kurnatud“ aitab sul kiiremini taastuda kui teesklus, et kõik on täiuslik.'),
('ec907054-781c-4e3c-be06-6c97119a4864'::uuid,'Атанын жайлуу ийин массажы 💆‍♂️','Күнү бою бут үстүндө жүрүп, балдардын артынан чуркап, оюнчуктарды жыйнап, белиңиз ооруп жатабы? Бала уктаары менен өнөктөшүңүздөн 10 мүнөт ийиндериңизди укалап коюусун сураныңыз. Сиз бул үйдүн кыймылдаткычысыз, ал эми кыймылдаткычка сөзсүз түрдө эс алуу жана калыбына келүү керек.','Issi rahustav õlamassaaž 💆‍♂️','Oled terve päeva jalul olnud, selg valutab neile järele jooksmisest ja mänguasjade korjamisest. Niipea kui laps uinub, palu partnerilt 10-minutilist õlamassaaži. Sina oled selle kodu mootor ja mootor vajab hädasti puhkust ja taastumist.'),
('486ad622-5eff-484f-8ea8-ea64a245ed91'::uuid,'Бирок бананды *мен* аарчыгым келген! 🍌','Бананды *сиз* аарчып койгонуңуз үчүн бөлмөдө төңкөрүш болдубу? Бул курактагы алтын эреже: баарына алар чечим чыгарышы керек. Аарчылган бананды кайра калыбына келтире албайсыз, андыктан дароо жаңысын берип, өздөрү каалагандай аарчыганга уруксат бериңиз. Талаш-тартыш убактыңызды гана текке кетирет.','Aga *mina* tahtsin banaani koorida! 🍌','Kas toas puhkes revolutsioon, sest *sina* koorisid banaani? Kuldreegel selles vanuses: nemad peavad kõike otsustama. Banaani ei saa enam kokku panna, seega anna neile kohe uus ja lase neil seda koorida nii, nagu nad tahavad. Vaidlemine raiskab vaid sinu aega.'),
('b59a06d3-66eb-4eef-8c37-b58f8b3331ca'::uuid,'Экөөбүз үчүн тынч көз ирмем 🥂','Бала уктады, үй жыйналды. Өнөктөшүңүз менен диванда жанаша отуруңуз, телевизорду да күйгүзбөңүз. Жөн гана бири-бириңизди карап: «Биз муну да жеңдик, биз кылдык» деген көз караш менен алмашыңыз. Бул ата-энелик жашоодогу эң романтикалуу жана чыныгы командалык учур.','Rahulik hetk kahekesi 🥂','Laps magab, kodu on korras. Istu partneriga diivanil kõrvuti, ära isegi pane telerit tööle. Vahetage lihtsalt pilk, mis ütleb: „Me elasime ka selle üle, me saime hakkama.“ See on lapsevanemaks olemise kõige romantilisem ja ehedam tiimihetk.'),
('c8f0d464-17b3-4dc7-a4f5-c03c96c8a18b'::uuid,'Стол астындагы кичинекей үй ⛺','Алар ашкана үстөлүнүн астына кирип, кичинекей үй куруп, эми ошол жерде түшкү тамак ичкиси келип жатабы? Эрежелерди бир аз жумшартыңыз. Шорпону ошол жайлуу, караңгы жерге алып барыңыз. Айлана-чөйрөнүн өзгөрүшү эң тандамал жеген баланы да укмуштуу окуяга жетелейт!','Väike maja laua all ⛺','Kas nad ronisid söögilaua alla, ehitasid väikese maja ja tahavad nüüd seal lõunat süüa? Painuta reegleid veidi. Serveeri supp sellesse hubasesse hämarasse ruumi. Keskkonnavahetus võib isegi kõige pirtsakama sööja seiklusjanuga täita!'),
('1f9be131-7868-4433-adc0-efe09d70723d'::uuid,'Сиз мени менен ойнобой жатасыз! 😠','Сиз телефон карап жатканда, алар келип, колу менен жүзүңүздү өздөрүнө буруп: «Мага кара!» деп талап кылыштыбы? Алар туура айтышат. Алар сиздин жөн гана жаныңызда болушуңузду эмес, толук көңүл бурууңузду каалашат. Телефонуңузду четке коюп, 3 мүнөт көзүнө тике караңыз, ошондо алар заматта тынчтанышат.','Sa ei mängi minuga! 😠','Samal ajal kui sa telefoni vaatasid, tulid nad ja keerasid su näo kätega enda poole, nõudes: „Vaata mind!“ Neil on õigus. Nad ei taha ainult sinu füüsilist kohalolu; nad tahavad sinu jagamatut tähelepanu. Pane telefon ära, loo 3 minutiks täielik silmside ja nad rahunevad silmapilkselt.'),
('86f2c2e9-f758-416c-a78d-b431eb3db53a'::uuid,'Тротуардын четинде аркан менен баскандай тең салмактуулук 🧱','Сейил бакка баратканда, түз жол менен эмес, тротуардын эң тар чети менен басам деп өжөрлөнүп жатышабы? Колунан бекем кармап, бул кичинекей «чокуну» багындыруусуна жол бериңиз. Алардын тең салмактуулугу жана өзүнө болгон ишеними бир убакта өнүгүп жатат, андыктан аларды токтотпоңуз.','Kõnnitee äärekivil tasakaalustamine 🧱','Parki minnes nõuavad nad kõndimist mööda kõnnitee kõige kitsamat äärt, mitte otse mööda teed? Hoia neist kinni ja lase neil see väike „tipp“ vallutada. Nende tasakaal ja enesekindlus arenevad samal ajal suurepäraselt, nii et ära hoia neid tagasi.'),
('963db29c-a2ad-4233-bbc2-364a68692feb'::uuid,'Бөлмөдөгү сыйкырдуу үн эффекттери 🪄','Бүгүн кечинде окууга чарчадыңызбы? Акылдуу жомокторду ачыңыз. Жомокту окуп жатып, бөлмөдө эшиктин кычыраганы, шамалдын үнү жана шыбырлар менен «үн театрын» түзүңүз. Бул адаттан тыш үн толкундары алардын көңүлүн заматта жомокко бурат.','Toa maagilised heliefektid 🪄','Oled täna õhtul lugemiseks liiga väsinud? Ava nutikad lood. Lugu lugedes loo toas „heliteater“ vaid kriuksuvate uste, tuulehelide ja sosinatega. Need ebatavalised helilained tõmbavad nende tähelepanu kohe loole.'),
('2d56a8b7-4b19-4fb3-95e9-798ee0cfa5d6'::uuid,'Парктан кетүү үчүн атаандаштык тактикасы 🌳','Сейил бактан кете турган убакыт келди, ыйлап-сыктоо башталдыбы? Аларды сүйрөө эч кандай натыйжа бербейт. Тескерисинче: «Ким коёндой болуп машинага тезирээк секирип жетет экен?» деп көрүңүз. Алардын көңүлүн дароо кызыктуу мелдешке буруңуз; алар сөзсүз түрдө кошулушат.','Võistluslikud taktikad pargist lahkumiseks 🌳','On aeg pargist lahkuda ja nutuhood on alanud. Lohistamine ei aita. Proovi hoopis öelda: „Vaatame, kes suudab kiiremini autoni jänese kombel hüpata?“ Suuna nende tähelepanu kohe lõbusale võistlusele; nad tahavad kindlasti kaasa lüüa.'),
('42b47472-82e3-49e8-bb91-8de4938efbde'::uuid,'Жөн гана алардын жагымдуу жытын искеңиз 🫂','Бүгүн алар сизди чындап эле чарчатып, энергияңызды түгөтүштүбү? Бирок азыр төшөктө ушунчалык бейкүнөө уктап жатышат... Жарыкты өчүрүңүз. Жанына жатып, алардын таза бала жытын терең дем алып, кулагына алар сиз үчүн канчалык баалуу экенин шыбырап коюңуз.','Lihtsalt hinga sisse nende magusat lõhna 🫂','Kas nad ajasid sind täna tõesti hulluks, kurnates su energia täielikult? Aga nüüd magavad nad voodis nii süütult... Kustuta tuled. Heida nende kõrvale, hinga sügavalt sisse seda puhast beebilõhna ja sosista, kui väärtuslikud nad sulle on.'),
('67931668-7ad8-456d-8077-31b1756abd2c'::uuid,'Бул *башка* чөйчөктө болушу керек! 🥤','Сары чөйчөккө суу куюп бергениңиз үчүн бөлмөдө башаламандык башталдыбы? «Мен көгүн каалагам!» деп ыйлап жатышабы? Терең ойлонбоңуз; алар жөн гана чек араларын сынап жатышат. Сууну заматта көк чөйчөккө куюп, бөлмөдө тынчтыкты орнотуп, өз энергияңызды сактап калыңыз.','See peab olema *teises* tassis! 🥤','Kas toas läks mölluks, sest andsid neile vett kollases tassis? „Ma tahtsin sinist!“ hüüavad nad. Ära süvene; nad lihtsalt katsetavad piire. Vala vesi sekunditega sinisesse tassi, taasta toas rahu ja hoia oma energiat.'),
('047715fd-ae66-4d00-8341-50e230c2b688'::uuid,'Динозаврлар ботко жебейт! 🦖','Эртең менен эч кандай суроого жооп бербей, элес-булас болуп жатышабы? Бүгүн алар Ти-Рекс! «Ти-Рекстер эртең мененки тамакты ичеби?» деп сураңыз. Алардын ойдон чыгарган образына кошулуп, ыйлабай эле столго отурушун тынчтык менен камсыз кылыңыз.','Dinosaurused ei söö putru! 🦖','Hommikul ei vasta nad ühelegi küsimusele, vaid möirgavad? Nad on täna T-Rex! Küsi: „Kas T-Rexid söövad hommikusööki?“ Mängi nende väljamõeldud tegelaskujuga kaasa ja taga rahulikult, et nad istuksid ilma pisarateta laua taha.'),
('2da52e9b-b72c-461f-8480-276d6d5e47df'::uuid,'Дүкөндөгү ыйлоо 🛒','Дүкөнгө кирип эле, эмне алыш керек экенин унутуп калдыңызбы? «Энелик мээ» чындыгында эле ашып-ташып жатат! Тиркемедеги «Сатып алуулар тизмесин» ачып, санариптик эс тутумга ишениңиз; ал Сизди үйгө куру кол кайтуудан дайыма сактап калат.','Toidupoe jonnihoog 🛒','Kas kõndisid toidupoodi ja unustasid kohe, mida vaja oli? „Emme aju“ on tõesti ülekoormatud! Ava äpis ostunimekiri ja usalda seda digitaalset mälu; see päästab sind alati tühjade kätega koju naasmisest.'),
('020f5f2c-bba3-4441-b9a0-518ce0263ac5'::uuid,'Бул таштанды эмес, бул искусство! 🎨','Алар бөлмөнүн ортосунда кургак макарон жана кагаз сыныктарынан укмуштуудай көркөм чыгарма жаратыштыбы? Тазалыкка болгон ашыкча умтулууңузду бир азга четке коюңуз. Бул — «Өнүгүү трекери» үчүн эң сонун болгон ири моториканын өнүгүүсүнүн эң сонун көрүнүшү. Эсиңизде болсун, Сиздин үйүңүз музей эмес.','See pole prügi, see on kunst! 🎨','Kas nad tegid keset tuba suurepärase kunstiteose kuivast pastast ja paberitükkidest? Jäta oma puhtusemaania hetkeks kõrvale. See on suurepärane peenmotoorika arengu näide, mis sobib ideaalselt arengupäevikusse. Pea meeles, et su kodu ei ole muuseum.'),
('7231bd75-47cb-4255-ae64-144dcd8d314f'::uuid,'Тынчтык өкүм сүргөн сааттар 📉','Алар акыры укташты. Үйдө кулак тунган тынчтык орнодубу? Тиркемедеги «Үн өлчөгүчтү» ачыңыз. Ошол 0 децибелдик көрсөткүчтү көрүү — Сиздин чарчаган, ызы-чуудан шишиген мээңиз үчүн эң жакшы визуалдык массаж болот.','Kuvatud vaiksed tunnid 📉','Nad on lõpuks magama jäänud. Kas majas on nii vaikne, et kõrvus kumiseb? Ava äpis helimõõtja. Selle 0-detsibellise näidu vaatamine on parim visuaalne massaaž sinu väsinud ja mürast kurnatud ajule.'),
('d3223299-be6e-4dfc-bfb7-c168e33bb866'::uuid,'Бүтпөгөн сүйлөмдөрдү аягына чыгаруу 🗣️','Сөздү унутуп калганда, колдору менен жаңсап, Сиздин таап алышыңызды күтүшөбү? Алардын сөз байлыгы өсүп жатат, бирок мээси тилине караганда тезирээк иштеп жатат. Сүйлөмүн аягына чыгарышын чыдамдуулук менен күтүңүз, анан «Ооба, мен так ушуну айткым келген!» деп түшүнгөндөгү алардын жүзүндөгү жеңилдөөнү байкаңыз.','Poolikute lausete lõpetamine 🗣️','Kui nad sõna unustavad, kas nad kasutavad žeste ja ootavad, et sa ära arvaksid? Nende sõnavara kasvab, kuid aju töötab kiiremini kui keel. Oota kannatlikult, kuni nad lause lõpetavad, ja vaata kergendust nende näol, kui nad mõistavad: „Jah, just seda ma mõtlesingi!“'),
('3f9c24cf-68b9-4b5b-9e40-a3652b7d443e'::uuid,'Ата менен диванда күрөшүү 🤼‍♂️','Уктоо убактысынан качуу үчүн чуркап барып жашынып калыштыбы? Топту атасына ыргытыңыз. Алар полдо бир аз алышып ойношсун. Ошол ызы-чуулуу, тердеткен ата-бала оюну балаңыздын акыркы өжөр энергиясын сарптап, аны оңой эле уйкуга багындырат.','Issiga diivanil maadlemine 🤼‍♂️','Kas nad jooksid ja peitsid end, et vältida magamaminekut? Viska pall issile. Lase neil põrandal naljatledes maadelda. See lärmakas ja higine isa-lapse mäng kurnab lapse viimasegi jonni ja nad alistuvad kergesti unele.'),
('4d053e9f-b091-45c7-9c6a-66e7f1ab590e'::uuid,'Жашылчаларды жашыруу өнөрү 🥦','Шорпосунан ошол кичинекей сабизди таап алып: «Мен муну жебейм!» дедиби? Ал жашылчаларды пюре кылып, соустарга байкатпай кошуп коюңуз; кана, эми таап көрүшсүн! Тамак тандаган табитти акылдуулук менен алдап коюңуз.','Köögiviljade peitmise kunst 🥦','Kas nad leidsid supist selle ühe pisikese porganditüki ja teatasid: „Ma ei söö seda!“? Püreesta köögiviljad ja peida need kastmetesse; vaatame, kas nad leiavad need nüüd üles! Nutikas viis pirtsaka maitsemeele üle kavaldamiseks.'),
('db42b564-536c-485c-afff-dce099e8c451'::uuid,'Мен учкум келет! 🕊️','Алар дивандан секирип, колдорун күүлөп, уча албаганы үчүн Сизге ачууланып жатышабы? Физика мыйзамдарын үйрөтүүгө али эрте. Аларга: «Канаттарың дагы эле өсүп жаткандыктан, азырынча уча албайсың!» деп айтыңыз жана көңүлүн жумшак жерге секирүүгө буруңуз.','Ma tahan lennata! 🕊️','Kas nad hüppavad diivanilt, lehvitavad kätega ja on sinu peale vihased, sest nad ei saa lennata? Füüsikaseaduste õpetamiseks on veel vara. Ütle neile: „Sa ei lenda veel, sest su tiivad alles kasvavad!“ ja suuna tähelepanu pehmel pinnal hüppamisele.'),
('76fc525d-97d8-486f-adde-6d0bdc417bbe'::uuid,'«Бул меники!» деп талашуу 🧸','Үйдө пультту кучактап алып, «Бул меники!» деп жатабы? Алар ээлик кылуу чек арасын сынап жатышат. Аларды «ачкөз» деп атабаңыз. Тескерисинче, «Мага таап бергениңе рахмат!» деп, көңүлүн башка оюнга буруу менен акырын алып коюңуз.','„See on MINU!“ vastasseis 🧸','Kas nad kallistavad kodus pulti, kuulutades: „See on minu oma!“? Nad katsetavad omandiõiguse piire. Ära nimeta neid isekaks. Ütle hoopis: „Aitäh, et leidsid selle minu jaoks!“ ja võta see õrnalt tagasi, suunates nende tähelepanu teisele mängule.'),
('ca5fc44a-790c-4b6a-b1b9-dcd31a3b298b'::uuid,'Саат боюнча уктоо ⏱️','Уктоо убактысы созулуп жатабы? Суу, даараткана, дубал менен коштошуу... Телефонуңузга таймер коюңуз. Ойготкуч чырылдаганда баары жарыкты өчүрөт деген эреже киргизиңиз. Балдарга сырткы эрежеге баш ийүү дайыма жеңилирээк болот.','Magamine kella järgi ⏱️','Kas magamaminek venib ja venib? Vesi, tualett, seinale head-aega ütlemine... Pane telefonis taimer. Kehtesta reegel, et kui alarm heliseb, kustutavad kõik tuled. Välisele autoriteedile allumine on neile alati lihtsam.'),
('f24ccc35-5845-4b4b-803c-db7a68218026'::uuid,'Сиз эч кимге түшүндүрмө берүүгө милдеттүү эмессиз 🛑','Бүгүн чыдамыңыз кетип, үнүңүздү көтөрүп жибердиңизби? Өзүңүздү жазалабаңыз. Маанай күндөлүгүңүзгө «Мен жакшы энемин, бүгүн жөн гана абдан чарчадым» деп жазып коюңуз. Өзүңүзгө боорукер болуңуз; эч ким сизден кемчиликсиз болууну талап кылбайт.','Sa ei pea kellelegi aru andma 🛑','Kas su kannatus katkes ja hääl tõusis täna? Ära ennast karista. Kirjuta oma meeleolupäevikusse: „Olen hea ema, olin täna lihtsalt väga väsinud.“ Ole enda vastu lahke; keegi ei oota sinult täiuslikkust.'),
('3fdd99bb-9e81-4b54-a9b9-28997c15bd09'::uuid,'Апанын энергиясын калыбына келтирүү 🥗','Балдарды тойгузуу үчүн ар кандай меню даярдадыңыз, бирок өзүңүз эмне жедиңиз? Дени сак тамактар бөлүмүнөн энелер үчүн тез даярдалуучу 5 мүнөттүк салатты жасап алыңыз.','Emme energiaallikas 🥗','Oled valmistanud neile erinevaid toite, aga mida *sina* oled söönud? Valmista tervislike retseptide sektsioonist see lihtne 5-minutiline salat emadele.'),
('8e09c446-7bb4-4213-903b-ca0d9d539235'::uuid,'Ысык чай жана тынч ой жүгүртүү ☕','Бала акыры уктады. Бөлмөнүн ортосунда чачылган оюнчуктарга карап, терең дем алыңыз. Аларды азыр жыйнабаңыз! Өзүңүзгө жылуу чай куюп, диванга отуруңуз да, ушул тынчтыктын ырахатын сезиңиз.','Kuum tee ja vaikne mõtisklus ☕','Laps on lõpuks magama jäänud. Vaata keset tuba laiali pillutud mänguasju ja hinga sügavalt sisse. Ära korista neid praegu! Vala endale soe tee, istu diivanile ja naudi lihtsalt rahu, mida see vaikus sulle toob.'),
('b85f6433-c512-4f2e-a5d4-b9023f0eb544'::uuid,'Жансыз достор менен терең маек 🗣️','Парктагы таш же үйдөгү отургуч менен олуттуу сүйлөшүп жатышабы? Алар эрежелерди сиңирип, дүйнөнү оюн аркылуу таанып жатышат.','Sügavad vestlused elutute sõpradega 🗣️','Kas nad räägivad pargis täiesti tõsiselt kiviga või kodus tooliga? Nad internaliseerivad reegleid ja mõistavad maailma mängu kaudu.'),
('294ce10a-4fac-4bfb-8007-e2e3fea714ad'::uuid,'Кичинекей сүрөтчүнүн өз ишин сындашы 🖍️','Тартылган сүрөтү жакпай калып, «Бул жаман!» деп кагазды айрып салыштыбы? Бул алардын өзүнө сын көз менен карай баштаганын жана жеткилеңдикке умтулуусун билдирет! Алардын капа болгонун колдоочу ачылышка айлантыңыз: «Кел, кийинки жолу башка түс менен тартып көрөлү!» деп сунуштаңыз.','Väikese kunstniku enesekriitika 🖍️','Kas neile ei meeldinud joonistatud joon ja nad rebisid paberi katki, öeldes: „See on halb!“? See näitab nende tärkavat enesekriitikat ja perfektsionismi! Muuda nende frustratsioon toetavaks avastuseks, soovitades: „Proovime järgmine kord teist värvi!“'),
('76df67fe-b947-400d-8825-c8fd1637478f'::uuid,'Коомчулуктагы жашыруун колдоо 💬','Өзүңүздү абдан чарчаңкы сезип, эч ким менен сүйлөшкүңүз келбей жатабы? Anacan коомчулугуна кошулуңуз жана жөн гана окурман болуңуз. Башка энелер ушундай эле кыйынчылыктарды кантип жеңип жатканын көрүү – эң күчтүү, үнсүз колдоо болот.','Varjatud lohutus kogukonnas 💬','Oled täiesti kurnatud ja ei taha kellegagi rääkida? Liitu Anacani kogukonnaga ja ole lihtsalt lugeja. Nähes, kuidas teised emad samade absurdsete väljakutsetega toime tulevad, on kõige võimsam vaikne lohutus.'),
('882a14e7-4dd7-4a8b-8fa7-7bd5afe17ad2'::uuid,'Ваннадагы океан укмуштуу окуясы 🌊','Ваннада жуунуу жөн гана шылтоо болуп, алар чындыгында океан жаратып, толкундар менен ойноп жатышабы? Ойношсун. Суунун үнү жана чачырашы алардын чексиз, өжөр энергиясын жууп кетет. Бүгүн кечинде алар эч каршылыксыз эле төшөккө жатышат.','Vanniskäigu ookeaniseiklus 🌊','Kas vanniaeg on vaid ettekääne, et tegelikult ookean luua ja vannis lainetega mängida? Lase neil mängida. Vee kohin ja pladistamine pesevad maha kogu selle lõputu, kangekaelse energia. Nad heidavad täna õhtul voodisse ilma igasuguse vastupanuta.'),
('3e4c8054-2b97-4968-a10f-267dccb5b8c0'::uuid,'Эртең мененки философиялык маектер 🤔','Алар күтүлбөгөн жерден «Эмне үчүн биз шамалды көрө албайбыз?» деген сыяктуу илимий суроо бериштиби? Кабатыр болбоңуз! Anacan AI ачыңыз, педиатрлар жана психологдор жактырган, алардын курагына ылайыктуу жомок сыяктуу жоопту алыңыз жана окуп бериңиз. Сиз ар дайым баарын билген энесиз!','Hommikused filosoofiaistungid 🤔','Kas nad esitasid äkki teadusliku küsimuse, näiteks: „Miks me tuult ei näe?“ Ära muretse! Ava Anacan AI, saa kõige armsam, lastearsti ja psühholoogi heakskiidetud muinasjutuline vastus, mida nende vanuses mõistetakse, ja loe see neile ette. Oled alati ema, kes kõike teab!'),
('b7b7faa9-f807-43f1-bf54-6d7f963c5e32'::uuid,'Жөн гана тынч эс алуу 🛋️','Алар тынч гана пазл чогултуп жатышабы жана үйдө күтүлбөгөн жерден жымжырттык орнодубу? Сураныч, ал учурда пол шыпырууга чуркабаңыз! Диванга жатыңыз. Сиздин да энергияңыз толукталышы керек, ошондо гана кечке чейин алардын темпине туруштук бере аласыз. Сөзсүз эс алыңыз.','Lihtsalt rahulikult puhkamine 🛋️','Kas nad panevad vaikselt puslet kokku ja majas on äkki vaikus? Palun ära kuluta seda hetke põrandate pühkimisele! Heida diivanile pikali. Sinu akud vajavad samuti laadimist, et suudaksid õhtuni seda tempot hoida. Puhka kindlasti.'),
('ccae9470-c321-4925-94c0-7408317b4c14'::uuid,'Чөнтөктөгү казыналар 🪨','Шымдарын жууп жатып чөнтөгүнөн кургап калган жалбырак же таш таптыңызбы? Бул таштанды эмес, бул баланын изилдөөсү. Аны билдирбей ыргытып салыңыз, бирок ичиңизден бул кичинекей коллекционерге жылмайып коюңуз – алар дүйнөнү таанып жатышат.','Taskuaarded 🪨','Leidsid pükse pestes taskust kuivanud lehe või kivi? See pole kogumine, see on lapsepõlve avastusretk. Viska see ilmetu näoga ära, aga naerata sisemiselt sellele väikesele kollektsionäärile – nad avastavad maailma.'),
('039b7451-67d0-43b6-9ed0-d4ec9bf47752'::uuid,'Куртка кийүү үчүн күрөш 🧥','Күн ачык болгону үчүн кышкы курткасын кийгиси келбей жатышабы? Терезеден карап эле алданбаңыз. Аба ырайы жана кийим тандоо тиркемесин ачып, кышкы кийимчен баланын сүрөтчөсүн көрсөтүңүз. Санарип экран эрежени бекемдесин, ал эми сиз четте тура бериңиз.','Jopega võitlemine 🧥','Nad ei taha talvejopet selga panna, sest päike paistab? Ära lase end aknast välja vaadates petta. Ava ilma- ja riietusrakendus, näita neile talveriietes lapse ikooni. Las digitaalne ekraan kinnitab reeglit ja sina saad sammu tagasi astuda.'),
('1d2e4dc8-5a7a-4aed-ab26-9b7c8dd5179c'::uuid,'Керебеттин астында жашынмак ойноо 🛏️','Алар төшөктө эмес, сөзсүз түрдө керебеттин астында уктагысы келип жатабы? Мындай жабык, кичинекей мейкиндиктер аларга эненин курсагындагыдай коопсуздук сезимин берет. Уруксат бериңиз; алар уктап калганда акырын көтөрүп төшөккө салып койсоңуз болот. Энергияңызды үнөмдөңүз.','Peitus voodi all 🛏️','Kas nad tahavad tingimata magada voodi all, mitte voodis? Need suletud väikesed ruumid annavad neile turvatunde, nagu oleksid nad emakas. Luba seda; kui nad on uinunud, saad nad õrnalt voodisse tagasi tõsta. Säästa oma energiat.'),
('73a43849-8300-493d-9040-f05eaf01e5b6'::uuid,'Күтүлбөгөн түшүнүксүз учурлар 🥶','Балаңыз ысык чайды үйлөп муздатуунун ордуна, ага муз салам деп жатабы? Алар ысык менен муздактын айырмасын үйрөнүп жатышат. Музду бериңиз жана эрип жатканын байкоого мүмкүнчүлүк бериңиз. Эртең мененки тамак кечигип калса да, алар кызыктуу илимий ачылыш жасашат.','Ootamatud segadusehetked 🥶','Kas su laps nõuab kuuma tee sisse jääkuubikuid, selle asemel et seda jahutamiseks puhuda? Nad õpivad kuuma ja külma kontrasti. Anna neile jää ja lase neil sulamisprotsessi jälgida. Isegi kui hommikusöök viibib, on nad teinud põneva teadusliku avastuse.'),
('1171703b-c644-4ad0-8298-a24063264467'::uuid,'Жамгырдын үнү менен жомок угуу 🌧️','Сүйлөшүүгө да, жомок окуп берүүгө да чарчап калдыңызбы? Акылдуу жомоктордогу жамгырдын же токойдун үнүн фон катары коюп коюңуз. Жаратылыштын бул бир калыптагы тынчтыгы кээде аларды эң кызыктуу жомоктон да тезирээк уктатып коёт.','Unejutud vihmahelide saatel 🌧️','Oled liiga väsinud rääkimiseks, pole energiat lugu lugeda? Pane nutikates lugudes taustaks mängima vihma- ja metsahelid. See looduse monotoonne rahu hüpnotiseerib nad mõnikord kiiremini unne kui kõige põnevam lugu.'),
('43e7fbfe-64bc-4627-85d6-4ddae59c6985'::uuid,'Күзгүдөгү өзүн көрүп кыжыры келүү 🪞','Алар күзгү алдында туруп, ар кандай кызыктуу үндөрдү чыгарып, беттерин ар түрдүү кылып жатышабы? Бул алардын өзүн-өзү таанып-билүүсүнүн өнүгүп жатканынын сонун белгиси. Алар өз денеси жана эмоциялары башкаларга кандай көрүнөрүн изилдеп жатышат. Жөн гана алыстан тынч байкап туруңуз.','Pettumus oma peegelpildi ees 🪞','Kas nad seisavad peegli ees, teevad naljakaid hääli ja erinevaid nägusid? See on imeline märk nende arenevast eneseteadvusest. Nad uurivad, kuidas nende keha ja emotsioonid teistele paistavad. Jälgi lihtsalt vaikselt eemalt.'),
('5b1cbac6-ecf8-4886-b2f1-c0e88c8559b5'::uuid,'Тийүүнүн күчү 🔋','Алар күнү бою бутуңузга жармашып, көтөрүп жүрүүнү талап кылып жатышабы? Сиз физикалык жактан чарчадыңыз. Сизде «тийишүүдөн чарчоо» (touch fatigue) болуп жатат. Аларды оюнчуктары менен бөлмөдө калтырып, 5 мүнөткө ваннага кирип, эшикти жаап алыңыз. Жөн гана ошол жалгыздыктан ырахат алыңыз.','Puudutuse vägi 🔋','Kas nad ripuvad pidevalt su jala küljes ja tahavad terve päeva süles olla? Oled füüsiliselt kurnatud. Tunned puudutustest väsimust. Jäta nad tuppa mänguasjadega ja torma 5 minutiks vannituppa, sulge uks. Tunneta lihtsalt seda üksindust.'),
('14317db1-b6eb-40d2-8404-59bcea4acdf7'::uuid,'Атамдын жомогу 📖','Үнүңүз чарчап, жомок айтууга күчүңүз жокпу? Кезепти атасына бериңиз! Анын башкача, жоон үнү жана ойлоп тапкан кызыктуу деталдары балаңыздын мээсин арбап, сиздин үнүңүзгө караганда тезирээк уктатып коёт.','Issi unejutt 📖','Su hääl on väsinud ja sul pole energiat unejutuks? Anna pall üle issile! Tema teistsugune, sügavam hääl ja kõik need rumalad detailid, mida ta välja mõtleb, lummavad su lapse aju ja uinutavad nad kiiremini kui sinu tavapärane hääl.'),
('5d28c236-3ed8-4900-b875-c6d0d9b2aa20'::uuid,'«Сен кимсиң?» оюну 🎭','Бүгүн эртең менен сизди бейтааныш адамдай карап: «Сиз кимсиз? Менин апам кайда?» деп сураштыбы? Бул жөн гана жаңы ролдук оюн! Аларга: «Мен эжекеңизмин [же башка бир оюн каарманы], апаң азыр келет!» деп айтыңыз. Бөлмө эртең менен күлкүгө толсун; бул өжөрлүк менен талашып-тартышкандан көрө энергияңызды алда канча көп үнөмдөйт.','Mäng „Kes sa oled?“ 🎭','Kas nad vaatasid sind täna hommikul nagu võõrast ja küsisid: „Kes sa oled? Kus mu emme on?“ See on lihtsalt uus rollimäng! Ütle neile: „Mina olen tädi [või mänguline tegelane] ja emme on kohe siin!“ Las tuba täitub täna hommikul naeruga; see säästab palju rohkem energiat kui kangekaelne vaidlus.'),
('8758179c-cc13-42d7-b2c1-4900aea35e3a'::uuid,'Тамагын бөлүшкүсү келбейт 🍳','Өз тарелкасынан бөлүшкүсү келбейт, бирок Сиздикинен жегиси келеби? Балдар ата-энесинин тандоосуна ар дайым толук ишенишет. Каршылык көрсөтпөңүз; мээрим менен бир тиштем берип, бул күлкүлүү өзүмчүлдүккө жөн гана жылмайып коюңуз.','Ta ei taha toitu jagada 🍳','Nad ei taha oma taldrikult jagada, aga nõuavad söömist sinu omast? Lapsed usaldavad alati täielikult vanemate valikuid. Ära võitle selle vastu; anna neile armastusega suutäis ja naerata selle koomilise isekuse peale.'),
('12a06ab8-bcee-4772-8e2b-6f509250a594'::uuid,'Мен учкум келет! 🕊️','Дивандан секирип, колдорун кагып, уча албай жатканына ачууланып жатабы? Физика мыйзамдарын үйрөтүүгө али эрте! Ага: "Канаттарың али өсүп жаткандыктан уча албай жатасың", - деп айтыңыз да, андан соң көңүлүн жумшак нерсенин үстүнө секирүүгө акырын буруңуз.','Ma tahan lennata! 🕊️','Kas nad hüppavad diivanilt, lehvitavad kätega ja vihastavad, et ei saa lennata? Füüsikaseaduste õpetamiseks on veel vara! Ütle neile: „Sa ei lenda, sest su tiivad alles kasvavad,“ ja suuna nende tähelepanu õrnalt pehmele pinnale hüppamisele.'),
('e80a8c85-c67a-45b2-8209-90553a33fb5f'::uuid,'Телефон уурусу 📱','Өзүңүзгө чай куюп жатып, телефонуңуз жок экенин жана ал дивандын артынан Сиз сыяктуу эле "Ало" деп жатканын байкадыңызбы? Алар Сиздин санариптик адаттарыңызды кайталап жатышат. Түзмөктү алганда: "Менин телефонум да сени менен сүйлөшкүсү келип жатат!" - деп айтып, жылмаюу менен анын колунан тамашалап алып коюңуз.','Telefonivaras 📱','Teed endale teed ja märkad, et telefon on kadunud ning see „ütleb“ diivani tagant „Tere“, täpselt nagu sina? Nad kopeerivad su digitaalseid harjumusi. Kui seadme kätte saad, ütle: „Mu telefon tahab sinuga ka rääkida!“ ja võta see naeratades mänguliselt nende käest.'),
('ebb45c07-d4c6-4504-ac39-3e83655d3e00'::uuid,'Экөөбүз үчүн тынч көз ирмемдер 🥂','Бала уктады, үй ичи иреттелди. Жубайыңыздын жанына диванга отуруңуз, атүгүл сыналгыны да күйгүзбөңүз. Жөн гана "биз муну жасадык, дагы бир күндү өткөрдүк" деген көз караш менен бөлүшүңүз. Ишенип коюңуз, бул чарчаган ата-энеликтеги эң чыныгы командалык учур.','Vaiksed hetked kahekesi 🥂','Laps magab, maja on korras. Istu partneri kõrvale diivanile, ära isegi telerit pane. Jagage lihtsalt seda pilku „me saime hakkama, elasime veel ühe päeva üle“. Usu mind, see on kurnatud lapsevanemaks olemise kõige ehedam meeskonnatöö hetk.'),
('2a662eb4-1c17-46f1-ad5d-c566286402e8'::uuid,'Парктан чыгуудагы кыйынчылыктар 🤝','Тайгаланмадан өзү биринчи түшөм деп башка баланы түртүп жибердиби? Баары Сизди карап турушат. Ыңгайсыз болуп, балаңызды урбаңыз. Ага: "Азыр анын кезеги, андан кийин биздин кезек келет", - деп эрежени акырын, бирок чектүү эскертиңиз. Тартип ушундай иштейт.','Võitlus pargist lahkumisel 🤝','Kas nad lükkasid liumäel teist last, tahtes ise järgmisena minna? Kõik vaatavad sind. Ära tunne piinlikkust ega löö oma last. Tuleta neile õrnalt, kuid kindlalt meelde reeglit: „Nüüd on nende kord, siis on meie kord.“ Nii see süsteem toimib.'),
('c0dcbfbe-b91a-462c-890d-a8770be19cf3'::uuid,'Эртең мененки чуркап ойноо 🏃‍♂️','Балаңыз эртең мененки саат 7де дивандарда чуркап, секирип жатабы? Кыйкырбаңыз. Жасап жаткан ишиңизди эки мүнөткө токтотуп, оюнга кошулуңуз. Балаңыздын кыял дүйнөсүнө кирүү бир аз кызыктай сезилиши мүмкүн, бирок бул Сиз үчүн да стресстен арылуунун эң сонун жолу!','Hommikune mänguhoos tormamine 🏃‍♂️','Kas su laps jookseb ja hüppab kell 7 hommikul diivanitel? Ära karju. Jäta oma tegemised kaheks minutiks pooleli ja ühine lõbuga. Lapse fantaasiamaailma astumine võib tunduda veidi kummaline, aga see on tegelikult ka sulle suurepärane stressimaandaja!'),
('e41be904-7cb3-4dd6-8966-ea3b375783f6'::uuid,'Түнкү коркунучтарды жеңүү: Илимий ыкма 🔦','Кичинекейиңиз уктоочу бөлмөдөгү көлөкөлөрдөн коркуп жатабы? Бөлмөнү тарс караңгы кылбаңыз; анын ордуна кичинекей, жылуу түстөгү түнкү чыракты колдонуп көрүңүз. Бул мелатониндин иштелип чыгышына тоскоол болбойт жана визуалдык ыңгайлуулукту камсыз кылып, анын коркуусун басат.','Öiste hirmuhoogude lahendamine: teaduslik lähenemine 🔦','Kas su väike laps kardab magamistoas varje? Ära tee tuba kottpimedaks; proovi hoopis väikest sooja tooniga öölampi. See ei sega melatoniini tootmist ja pakub visuaalset mugavust, leevendades nende hirme.'),
('b5588608-ef71-4787-b05e-09f4f4f2492a'::uuid,'Күтүүсүз «Мен сени сүйөм!» 💖','Алар бөлмөнүн ортосунда ойноп жатып, күтүүсүздөн Сизди карап, чуркап келип, мойнуңуздан бекем кучакташат. Ар бир уйкусуз түн, ар бир чарчаган көз ирмем – мунун баары ушуга татыктуу! Бул көз ирмем тартуулаган терең, өзгөчө тынчтыктан ырахат алыңыз жана бардык башаламандыкты унутуңуз.','Spontaanne „Ma armastan sind!“ 💖','Nad mängivad keset tuba, vaatavad siis äkki sulle otsa, jooksevad ligi ja kallistavad tugevalt ümber kaela. Iga unetu öö, iga kurnatuse hetk – see on seda väärt! Naudi sügavat, ainulaadset rahu, mida see hetk toob, ja unusta kogu kaos.'),
('e2ac4132-1e14-42d5-a828-9c40ffb00179'::uuid,'Шыбырдын сыйкырдуу күчү 🤫','Балаңыз керебеттен секирип түшүп, ары-бери чуркап жатабы? Үнүңүздү болушунча басаңдатып, шыбырап сүйлөп көрүңүз. Сизди түшүнүү үчүн алар бүт көңүлүн бурууга мажбур болушат, натыйжада мээси чарчап, 5 мүнөттүн ичинде уйку режимине өтөт. Байкап көрүңүз!','Sosistamise maagiline vägi 🤫','Kas su laps hüppab voodist välja ja jookseb ringi? Proovi oma häält täiesti madaldada ja hakata sosistama. Nad peavad sind mõistmiseks füüsiliselt keskenduma ning nende aju väsib ja lülitub 5 minuti jooksul unerežiimile. Proovi järele!'),
('f5be8b0c-0a17-4790-b9b1-73d205d64a76'::uuid,'Instagram энелеринин элеси 📱','Инстаграмды ачып, баарынын иреттүү үйлөрүн жана тил алчаак балдарын көрүп, көңүлүңүз чөктүбү? Ал тиркемени өчүрүп салыңыз! Anacan коомчулугуна кошулуңуз. Үйлөрү Сиздикиндей иретсиз, ал эми балдары Сиздикиндей эле өжөр болгон чыныгы энелердин окуяларын окуңуз.','Instagrami-ema illusioon 📱','Kas avasid Instagrami ja tundsid end masendununa, nähes kõigi teiste korras kodusid ja ideaalselt käituvaid lapsi? Kustuta see rakendus! Liitu Anacani kogukonnaga. Loe lugusid päris emadelt, kelle kodud on sama segased kui sinu oma ja kelle lapsed on sama kangekaelsed.'),
('add15a56-d6d1-4819-af57-b57688cec0f4'::uuid,'Китепсиз эле түнкү сыйкыр 🪄','Бүгүн кечинде жомок окуп берүүгө дартыңыз жокпу? Тынчтандыруучу аудио жомокторду байкап көрүңүз. Тек жай катары токойдун шыбырын жана шамалдын үнүн коюп коюңуз. Караңгыда жаратылыштын бул үндөрүн угуу экөөңүздүн тең күндүзгү ызы-чуудан арылып, эс алууңузга жардам берет. Көздүн чарчоосу заматта жоголот.','Uneaja maagia ilma raamatuta 🪄','Pole täna õhtul energiat lugu lugeda? Proovi rahustavaid audiolugusid. Pane taustaks sosistav mets ja tuulehelid. Pimedas nende loodushelide kuulamine aitab teil mõlemal päeva mürast lõõgastuda. Visuaalne väsimus kaob hetkega.'),
('b000be1e-116f-4403-b926-fe4428d04231'::uuid,'Ичимдегилерди күндөлүккө жазуу 📝','Үйдө канчалык чарчаганыңызды эч ким көрбөгөндөй сезилип, ичиңизден жарылып кете жаздап жатасызбы? Маанай күндөлүгүңүздү ачыңыз. Бүгүн Сизди жиниңизге тийгизген нерселердин баарын жазыңыз. Сезимдериңизди кабыл алып, аларды кагазга түшүрүү, жасалма жылмаюуга караганда көбүрөөк жардам берет.','Oma pettumuste kirjapanek 📝','Kas tundub, et keegi ei näe, kui kurnatud sa kodus oled, ja see paneb sind plahvatama? Ava oma meeleolupäevik. Kirjuta üles kõik, mis sind täna hulluks ajas. Oma emotsioonide aktsepteerimine ja kirjapanemine aitab sind rohkem kui võltsnaeratuse sundimine.'),
('f9e06d3b-098b-4aa8-b407-0f31bbbcfcf8'::uuid,'Билем, азыр көрсөтөм! ☝️','Алар Сизге келип, Сиз ансыз деле билген нерсени абдан олуттуу жана акылдуу түрдө түшүндүрүп жатышабы? Алар өз акылын сынап жатышат! Күлкүңүздү тыйып, бирок абдан олуттуу угуп: «Чын элеби? Чоң рахмат!» — деп айтыңыз. Алардын кичинекей аброюн көтөрүп коюу абдан сонун.','Ma tean, lase ma näitan! ☝️','Kas nad tulevad su juurde ja selgitavad väga tõsise ja intelligentse ilmega midagi, mida sa juba tead? Nad katsetavad oma nutikust! Hammusta huulde, et mitte naerma puhkeda, aga kuula väga tõsiselt ja ütle: „Tõesti? Suur tänu!“ On imeline nende väikest ego turgutada.'),
('5b3e259a-f085-41f9-b9ba-e7ff8789e89c'::uuid,'Сууга түшүүдөгү шаңдуу оюндар! 🌊','Сууга түшүү убактысы алар үчүн океан жасап, толкундар менен ойноо үчүн жөн гана шылтоо болуп жатабы? Мейли, ойной беришсин! Суунун чачыраганы жана ызы-чуусу алардын чексиз, өжөр энергиясын жууп кетет. Бүгүн кечинде алар эч кандай каршылыксыз укташат.','Vanniskäigu sulistamisrõõm! 🌊','Kas vanniaeg on neile vaid ettekääne ookeani loomiseks ja lainetega mängimiseks? Lase neil! Vee pladistamine ja müra pesevad maha kogu selle lõputu, kangekaelse energia. Täna õhtul lähevad nad voodisse ilma igasuguse vastupanuta.'),
('7c552cb2-0d81-4027-8eba-e235f8359b1d'::uuid,'Ашканада жардам берүү 🧑‍🍳','Камыр жууруп жатсаңыз, жаныңызга келип, отургучту сүйрөп келип, унду өздөрү чачкысы келип жатабы? Эгер уруксат бербесеңиз, ый сөзсүз болот! Аларга кичинекей пластик идиш жана бир аз ун бериңиз. Ашкана бир аз чачылышы мүмкүн, бирок алардын олуттуу ашпозчудай болгон жүзүн көргөндө, баарын тазалоого арзый турганын түшүнөсүз.','Köögis abistamine 🧑‍🍳','Kas rullisid tainast ja nad tulid kohale, vedasid tooli ligi ja nõudsid, et saaksid ise jahu puistata? Kui sa ei luba, järgneb kindlasti nutt! Anna neile väike plastkauss ja natuke jahu. Köök võib küll sassi minna, aga nende tõsine väike koka-ilme on koristamist väärt.'),
('86e3829d-08da-4b37-867c-0faf0ab2fa1c'::uuid,'Дүкөндөгү текченин алдында катып калуу 🛒','Супермаркеттин ортосунда туруп, «Мен эмне сатып алганы келдим эле?» деп ойлонуп жатасызбы? Энелик мээ чындап эле ашыкча жүктөлгөн. Тиркемедеги «Соода тизмесин» ачыңыз, санариптик эс тутум сизди бул башаламандыктан дайыма куткарат.','Külmunud poe vahekäigus 🛒','Seisad keset supermarketit ja mõtled: „Mida ma siia ostma tulin?“ Emme-aju on tõesti ülekoormatud. Ava rakenduses ostunimekiri ja usalda, et digitaalne mälu päästab sind alati sellest kaosest.'),
('202773be-9378-4cfa-915c-7cbc9e98cdc2'::uuid,'Кийимдин саймалуу белгиси сайып жатабы? 🏷️','Кийимдин артындагы кичинекей белги ийнедей сайылып жаткандыктан кийингиси келбей жатабы? Бул курактагы сезгичтик адамды бир аз жинди кылышы мүмкүн. Талашпаңыз дагы; кайчыны алып, аны кесип салыңыз, ошондо бул кичинекей кризис секунданын ичинде чечилет.','See sügelev riidesilt! 🏷️','Nad ei taha riidesse panna, sest see pisike silt selja taga tundub nagu nõelatorge? Sensoorne tundlikkus võib selles vanuses tõesti natuke hulluks ajada. Ära isegi vaidle; haara käärid, lõika see lihtsalt ära ja lõpeta see minikriis sekunditega.'),
('65b5e1a3-f9ad-4e00-a2af-7ae096f9121d'::uuid,'Тынчтыктын эң сонун көз ирмеми 🛋️','Алар пазлдар менен ушунчалык берилип ойноп жаткандыктан, үйдө күтүлбөгөн жерден жымжырттык орнодубу? Шектенбеңиз; дароо өзүңүзгө кофе куюп алыңыз. Ал сейрек кездешүүчү алтын мүнөттөрдү үй жыйноого же кир жууганга эмес, жаныңызды эс алдырууга арнаңыз, атүгүл шыпты карап жатсаңыз дагы. Сиз робот эмессиз.','Täiuslik vaikusehetk 🛋️','Nad mängivad nii süvenenult oma pusledega, et majas valitseb äkki vaikus? Ära ole kahtlustav; vala endale kohe tass kohvi. Veeda need haruldased ja kuldsed minutid mitte koristades või pesu pestes, vaid oma hinge turgutades, kasvõi lihtsalt lakke vaadates. Sa ei ole robot.'),
('a86a31ee-9e29-4f41-aa7c-1edc94992d88'::uuid,'Түнкүсүн күтүүсүз ыйлоо 😭','Балаңыз көзү жумулуу абалда ыйлап ойгонуп, сизди укпай жатабы? Бул түнкү коркунучтуу түш сыяктуу. Аны ойготпогонго аракет кылыңыз; жөн гана жанында туруп, колунан кармап, акырын сылаңыз. Ал өзү эле тынчтанып, кайра терең уйкуга кетет.','Äkiline kesköine nutt 😭','Kas su laps ärkas nuttes, silmad kinni, ega kuule sind? See kõlab nagu öine hirmuhoog. Püüa teda mitte äratada; lihtsalt ole lähedal, hoia ta käest ja silitage õrnalt. Ta rahuneb ise ja uinub uuesti sügavasse unne.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('2e1371fa-bf2b-4fc1-b3c0-c7f4619346f4'::uuid,'Жарыкты өчүрүп, уктоо убактысы 🌙','Тез уктап кетиши үчүн, уктоодон 1 саат мурун бөлмөдөгү бардык сыналгы жана телефон экрандарын өчүрүңүз. Караңгы чөйрөдө мелатонин тез иштелип чыгат, андыктан табигый процесс сиздин пайдаңызга иштесин.','Tuled kustu, uni tuleb 🌙','Et aidata neil kiiremini uinuda, lülita 1 tund enne magamaminekut toas välja kõik teleri- ja telefoniekraanid. Melatoniin tekib pimedas keskkonnas kiiresti, nii et lase loomulikul protsessil enda heaks töötada.'),
('e85b3357-f072-4120-8d16-ffdc101f5e86'::uuid,'Атасы менен аянтчада ойноо 👨‍👧','Эне болуу — бул эс алуусу жок 24/7 нөөмөт эмес. «Өнөктөш функциясын» иштетиңиз! Атасы бүгүн ал чексиз энергияны сейил бакка алып кетсин, ал эми сиз үйдө татыктуу тынчтыктан жана жайлуулуктан ырахат алыңыз.','Issi mänguväljakuaeg 👨‍👧','Emadus ei ole 24/7 vahetus ilma pausideta. Aktiveeri „Partneri funktsioon“! Lase issil see lõputu energia täna parki viia, samal ajal kui sina naudid kodus täiel rinnal väljateenitud rahu ja vaikust.'),
('dffa4555-16c2-4705-a09e-e04f9ae6d25d'::uuid,'Үй иштери күтө турат. Чын эле. 🌪️','Өнөктөшүңүздөн бүгүнкү үй жумуштарын өзүнө алуусун сураныңыз. Сиз эс алууга татыктуусуз!','Kodutööd võivad oodata. Päriselt. 🌪️','Palu partneril tänased kodutööd üle võtta. Sa väärid puhkust!'),
('1d119442-bc5b-4f46-a607-68533220e425'::uuid,'Сурооңуз барбы? 🤖','Эгерде өнүгүү боюнча кандайдыр бир деталдар сизди түнкүсүн да тынчсыздандырса, Anacan AI жардамчыбыздан эксперттик колдоо сураңыз.','Kas sul on küsimusi? 🤖','Kui mõni arengudetail sind muretsema paneb, kasvõi hilisõhtul, küsi nõu meie Anacan AI-assistendilt.'),
('e83a5069-7214-47ea-9051-6406495d5723'::uuid,'«Оюнчугумду бер!» фазасы! 🧸','Колундагы нерсени алганыңызда, алар катуу реакция кылып ыйлайбы? Алардын ээлик кылуу сезими толук калыптанып жатат. Тыюу салуунун ордуна, көңүлүн башка жакка бурууга аракет кылыңыз.','„Anna mu mänguasi tagasi!“ faas 🧸','Kui võtad neil midagi käest, kas nad reageerivad tugevalt ja nutavad? Nende omanditunne on täielikult arenemas. Keelamise asemel proovi nende tähelepanu mujale juhtida.'),
('ae6d1371-ca56-433f-b6db-9c70c59094fb'::uuid,'Маанайдын өзгөрүшү 🛑','Полго жатып алуу сыяктуу жаңы тентектиктер башталып жатабы? Алар сезимдерин башкара албай жатышат. Алардын деңгээлине түшүп, бул кыйынчылыктарды сабырдуулук менен түшүндүрүп сүйлөшүңүз.','Tuju muutub 🛑','Kas algamas on uued jonnihood, nagu põrandale viskumine? Nad ei oska oma tunnetega toime tulla. Mine nende tasemele ja räägi nendega need puhangud rahulikult läbi.'),
('5f3d97d0-e211-488f-bb05-dd9ccce213a3'::uuid,'Биз бир командабыз! 💖','Оор күндөн кийин өнөктөшүңүз менен отуруп, баарын талкуулаңыз. Бири-бириңизди колдоо жүктү чындап эле эки эсе жеңилдетет.','Me oleme meeskond! 💖','Pärast rasket päeva istu partneriga maha ja rääkige asjad läbi. Üksteise toetamine poolitab tõesti koorma.'),
('92cb503c-c013-47cb-ab12-416c047b2693'::uuid,'Өнүгүүсүн текшерүү 🤖','12 айлык балаңыздын кыймыл-аракет жөндөмдүүлүгү тууралуу маалымат керекпи? Anacan AI''дан педиатрлар жактырган кыска жана так тизмени сураңыз.','Arengukontroll 🤖','Vajad infot oma 12-kuuse lapse motoorika kohta? Küsi Anacan AI-lt lühikest, täpset ja lastearsti heakskiidetud nimekirja.'),
('63bf2d84-bd96-49e0-9c51-b1f59bd85995'::uuid,'Мөмө-жемиш жей турган убакыт! 🍎','Энергияңызды толуктоо үчүн сезондук мөмө-жемиштерден турган түстүү жана жагымдуу тарелка даярдаңыз.','Puuviljaaeg! 🍎','Valmista värviline ja ahvatlev taldrik hooajaliste puuviljadega, et oma energiavarusid täiendada.'),
('d4a01ba0-4f2b-45a3-8cb0-3f2fa493585d'::uuid,'Жаңы оюнчук керекпи? 🛒
','Эгерде сиз курагына ылайыктуу жана акыл-эсин өстүрүүчү билим берүүчү оюнчуктарды издеп жатсаңыз, биздин «Сунушталган өнүмдөр» тизмебизди карап көрүңүз.','Vaja uut mänguasja? 🛒
','Kui otsid arendavaid mänguasju, mis on eakohased ja stimuleerivad nende mõtlemist, vaata meie soovitatud toodete nimekirja.'),
('5b41e7e4-7a14-41e6-a7a1-c4a7838db66b'::uuid,'Бирге китеп окуу. 📖','Алар азыр барактарды өздөрү барактаганга абдан кызыгышат. Картон китептер жана аудио жомоктор бул өнүгүү баскычы үчүн эң сонун.','Lugege koos raamatut. 📖','Nad on nüüd innukad ise lehti keerama. Papraamatud ja audiolood on selleks arenguetapiks ideaalsed.'),
('7cc24719-4bcf-403b-9178-3f6a80317c26'::uuid,'500 сонун күндү белгилөө! 🎉','Ишенесизби?! Кичинекейиңиз төрөлгөндөн бери 500 күн өттү!','Tähistame 500 imelist päeva! 🎉','Kas suudad uskuda?! Sinu pisikese sünnist on möödas juba 500 päeva!'),
('d3ed901e-4f05-435d-a1d6-02b2847be818'::uuid,'Сыйкырдуу түнкү маанай. 🪄','Уктай албай жатасызбы? Дарыянын үнү сыяктуу тынчтандыруучу ак ызы-чуу (white noise) фонун колдонуп көрүңүз.','Maagiline öine atmosfäär. 🪄','Kas uinumisega on raskusi? Proovi rahustavat valge müra tausta, kus on vaid jõe kohin.'),
('917ef6a5-ae0d-4133-b145-53d60f762945'::uuid,'Топту алып кел! 🧠','Балаңыз азыр жөнөкөй тапшырмаларды абдан жакшы түшүнөт. Сиз суранган нерсени алып келгендеги алардын кубанычы акыл-эси канчалык тез өнүгүп жатканын көрсөтөт.','Too pall! 🧠','Sinu laps mõistab nüüd lihtsaid juhiseid väga hästi. Nende rõõm, kui nad toovad sulle midagi, mida palusid, näitab, kui kiiresti nende intelligentsus areneb.'),
('35d30a24-8966-43d1-afce-6f79d49ebcec'::uuid,'Адистин колдоосу 🤖','«Балам тиштеп жатат, кантип реакция кылышым керек?» сыяктуу тынчсыздандырган жүрүм-турумдар боюнча жаңы суроолоруңуз барбы? Anacan AI жардамчыбыздан кеңеш сураңыз.','Ekspertide tugi 🤖','Kas sul on uusi küsimusi murettekitava käitumise kohta, näiteks „Mu laps hammustab, kuidas peaksin reageerima?“ Küsi juhiseid meie Anacan AI-assistendilt.'),
('a9e6c327-e70b-4cd7-9bed-cb9d250622ba'::uuid,'Тынчтандыруучу үндөр 🎶','Эгерде кичинекейиңиз активдүү изилдөө менен өткөн күндөн кийин тынчтана албай жатса, «Ак ызы-чуу» (White Noise) бөлүмүнөн жамгырдын үнүн коюп, бөлмөдө тынч атмосфера түзүңүз.','Rahustavad helid 🎶','Kui su pisikesel on pärast aktiivset avastamispäeva raske rahuneda, loo toas rahulik õhkkond, mängides valge müra alt vihmahelisid.'),
('714f8ced-9ccc-40ff-a807-9428279f86d4'::uuid,'Уйкуга жайлуу өтүү. 🌙','Күндүзгү активдүүлүктөн кийин, бөлмөдөгү жарыкты басаңдатып, балаңыз терең уйкуга кетиши үчүн ага акырын үн менен бешик ырын ырдап бериңиз.','Sujuv üleminek unele. 🌙','Pärast aktiivset päeva hämarda toas tuled ja laula vaikse häälega hällilaulu, et aidata neil sügavasse unne vajuda.'),
('bf80d71f-c8bb-4983-b046-1ee91c367f20'::uuid,'Адистин колдоосу 🤖','«Сөздөрдү түшүнөт, бирок эмнеге аз сүйлөйт?» деген сыяктуу суроолоруңуз болсо, Anacan AI жардамчыбыздан сурап, көңүлүңүзгө тынчтык табыңыз.','Ekspertide tugi 🤖','Kui sul on küsimusi, mis panevad sind imestama, näiteks „Nad mõistavad sõnu, aga miks nad nii vähe räägivad?“, küsi meie Anacan AI-assistendilt ja leia meelerahu.'),
('fb70ef32-f9e7-42c7-9f54-302457a506bf'::uuid,'Сөзсүз эле түшүнүү. 🫂','Бүгүн абдан чарчадыңыз. Балаңыз уктагандан кийин, жолдошуңуз менен диванга чогуу отуруп, сүйлөшүүнүн зарылдыгы жок эле тынчтыктан ырахат алыңыз.','Mõistmine ilma sõnadeta. 🫂','Oled täna väga väsinud. Pärast seda, kui beebi magab, istu lihtsalt partneriga diivanil kõrvuti ja naudi vaikust, ilma et peaksid rääkima.'),
('5a50a7bc-7ff1-421e-abac-beffc69e1480'::uuid,'Тротуардын четинде басуу сыноосу 🧱','Паркка баратканда, алар кадимки жол менен эмес, аркан үстүндө баскан адамдай болуп, бордюрдун эң ичке жана бийик чети менен басууну талап кылышат. Бул алардын ири моторикасы жана тең салмактуулугу өнүгүп жатканын билдирет! Коопсуздугу үчүн колунан кармап туруңуз жана бул кичинекей, бирок абдан маанилүү чокуну багындыруусуна мүмкүнчүлүк бериңиз.','Kõnnitee äärekivi väljakutse 🧱','Teel parki nõuavad nad, et ei kõnniks tavalisel teel, vaid äärekivi kõige kitsamal ja kõrgemal serval, nagu köielkõndijad. Üldmotoorika ja tasakaal arenevad! Hoia nende käest, et nad oleksid kaitstud, ja lase neil vallutada see väike, kuid väga tähtis tipp.'),
('15793f9f-2b07-4de4-817b-a555822e7e8e'::uuid,'Бүгүнкү кичинекей керемет. 🖼️','520-күн үчүн өзгөчө көз ирмем! Эң баалуу жана күлкүлүү сүрөттөрүңүздү «Ымыркай альбомуна» жүктөп, ал эстеликтерди жылдар бою жылмаюу менен эскерип жүрүңүз.','Tänane väike ime. 🖼️','Eriline hetk 520. päeval! Laadi oma kõige kallimad ja naljakamad fotod beebialbumisse ja naudi neid mälestusi naeratusega veel aastaid.'),
('5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b'::uuid,'Түштөн кийинки табит 🥣','Бүгүн жетиштүү өлчөмдө белок алдыбы? Алардын тамак-ашын тамактануу трекерине киргизип, күнүмдүк нормасын аткарганын текшериңиз.','Pärastlõunane isu 🥣','Kas nad said täna piisavalt valku? Sisesta nende toidukorrad toitumisjälgijasse ja veendu, et nad on oma päevased vajadused täitnud.'),
('8fab2e02-e35e-45f0-a10f-554adfe7c2c6'::uuid,'Үйдөгү башаламандык бүттү','Терезеден келген ызы-чууну басуу үчүн, lofi музыкасын коюп, жаныңызды эс алдырыңыз.','Kodune kaos on läbi','Et akna tagant kostvaid helisid summutada, pane mängima lofi-muusika ja lase hingel puhata.'),
('a242b14e-b434-493a-ab87-b2064aedfc9e'::uuid,'Менин кичинекей саякатчым 📸','Алар ойноп же чуркап жүргөндө тартып алган эң күлкүлүү сүрөтүңүздү «Ымыркай альбомуна» кошуп, аны баалуу эстеликке айлантыңыз.','Minu väike seikleja 📸','Muuda see kõige naljakam foto, mille jäädvustasid ronimise või kullimängu ajal, kalliks mälestuseks, lisades selle beebialbumisse.'),
('0671a41f-8a24-4dff-87f0-008aa3abfc3d'::uuid,'Сиңирүү процесси кандай? 💩','Жоолугун алмаштырып жатканда, заңдын абалы тууралуу белгилерди тиркемеге кошууну унутпаңыз. Бул клетчаткага бай азыктар балаңыздын сиңирүү процессине күн бою кандай таасир этерин оңой көзөмөлдөөгө жардам берет.','Kuidas seedimine on? 💩','Mähkmeid vahetades ära unusta rakendusse märkmeid teha. Nii on lihtne jälgida, kuidas kiudainerikkad toidud beebi seedimist päeva jooksul mõjutavad.'),
('fbbb1355-d1ac-4efe-b9c7-1746b97b1656'::uuid,'Бөлүшкүсү келбей жатабы? 🤖','Кичинекейиңиз оюнчугун бөлүшпөй, паркта ыйлап жатабы? Мындай татаал кырдаалдарды чечүү үчүн Anacan AI сунуштаган стратегияларды үйрөнүп, колдонуп көрүңүз.','Ei taha jagada? 🤖','Kas su pisike keeldub mänguasja jagamast ja teeb pargis jonnihoo? Õpi ja rakenda Anacan AI strateegiaid, et nende keeruliste olukordadega toime tulla.'),
('f0fc96ac-776c-4e66-bacf-461eff128cbc'::uuid,'Түстүү тарелкалар 🥦','Жашылчаларды жегиси келбей жатабы? Кошумча тамакка өтүп жаткан ымыркайлар үчүн кызыктуу жана чыгармачыл рецепттерди изилдеп, «Тамактануу трекери» аркылуу алардын керектүү азыктарды алуусун камсыз кылыңыз.','Värvilised taldrikud 🥦','Kas köögiviljadega on raskusi? Avasta lõbusaid ja loomingulisi retsepte lisatoiduga alustavatele beebidele ning saavuta mänguliselt nende toitumiseesmärgid toitumisjälgija abil.'),
('6bb4b5b9-3f8e-4a1c-a637-e0752d1d87ee'::uuid,'Кичинекей мода дизайнериңиз иштеп жатат! 👗','Түстөрү бири-бирине төп келбесе да, кийимдерин өздөрү тандап кийгиси келеби? Бул күлкүлүү көрүнүштү «Ымыркай фотосессиясы» функциясындагы шаңдуу стикерлер менен кооздоп, альбомуңуздагы эң кызыктуу сүрөткө айлантыңыз.','Sinu väike moedisainer töös! 👗','Kas nad tahavad ise riideid valida, isegi kui värvid ei sobi? Kaunista see naljakas kombo beebifotoseansi funktsiooni rõõmsate kleebistega ja muuda see albumi kõige naljakamaks pildiks.'),
('f8565841-4602-47d5-af45-99f7dea5b129'::uuid,'Сол колбу же оң колбу? 🤚','Кашыкты кайсы колу менен кармайт? Доминанттуу колдун качан жана кантип калыптанаары тууралуу «Блогдор» бөлүмүндөгү жаңы илимий макалабызды сөзсүз окуп чыгыңыз.','Vasakukäeline või paremakäeline? 🤚','Kumba kätt nad lusika hoidmiseks kasutavad? Vaata kindlasti meie uut teaduslikku artiklit blogide sektsioonis selle kohta, kuidas ja millal kujuneb välja domineeriv käsi.'),
('daa6a0d6-25d4-401e-ba81-8a8ca5108695'::uuid,'Жаныбарлардын алгачкы үндөрү 🐮','Кичинекейиңиз ит же мышыкты көргөндө алардын үнүн туураганга аракет кылабы? Бул сонун когнитивдик өнүгүүнү «Ымыркай альбомуна» кыска видео катары тартып алып, эстелик катары сактап калыңыз.','Esimesed loomahääled 🐮','Kas su pisike püüab koera või kassi hääli järele teha, kui neid näeb? Jäädvusta see imeline kognitiivne areng lühivideona beebialbumisse ja hoia mälestust.'),
('cc01349a-6eef-4c61-aa08-b3f505c2eb5f'::uuid,'«Өзүм жейм!» күрөшү 🥣','Эгер уруксат берсеңиз, тамак чачылат; бербесеңиз, ыйлайт. Тамактануу маалындагы бул башаламандыкты стресс жок башкарууну Anacan AI психологиялык кеңештери аркылуу азыр үйрөнүңүз.','„Söön ise!“ lahing 🥣','Kui lubad neil, läheb toit igale poole; kui ei luba, siis nad karjuvad. Õpi, kuidas seda söögiaja hullust stressivabalt hallata, kasutades Anacan AI psühholoogilisi nõuandeid.'),
('deb6cbd4-3a89-4915-9bdf-626d87829918'::uuid,'Сууну жана ылайды жакшы көрөт! 💦','Алардын кир болуп калышынан коркпоңуз! «Энелер үчүн ыңгайлуу жайлар» тизмебизден сырттагы аянтчаларды таап, сезүү органдарын өнүктүрүү үчүн аларды жаратылыш менен байланыштырыңыз.','Armastab vett ja muda! 💦','Ära karda lasta neil määrduda! Leia meie emmesõbralike asukohtade hulgast väliala ja lase neil loodusega suhelda, et turgutada nende sensoorset arengut.'),
('49af58d4-c188-43d7-a0b2-43f4cd255337'::uuid,'Эртең мененки кофе жетишсиз! ☕','Күндү ач карын кофе ичүү менен баштоо энергияңызды тез эле түгөтүп коёт. Анын ордуна, аялдар үчүн дени сак рецепттерибизден 5 мүнөттө даяр болчу энергия берүүчү сулу кексин тандаңыз.','Hommikukohvist ei piisa! ☕','Päeva alustamine tühja kõhuga kohviga võib su energia kiiresti ammendada. Vali hoopis energiat andev kaerakukkel meie naiste tervislike retseptide hulgast, mis valmib vaid 5 minutiga.'),
('869af623-de96-421f-808b-d64172a8f765'::uuid,'Сиз баарын туура жасап жатасыз! 👏','Үй бүгүн бир аз башаламан болуп калдыбы? Бул үчүн такыр кабатыр болбоңуз! Балаңыз менен чогуу өткөргөн күлкүлүү көз ирмемдер алда канча баалуу. «Маанай күндөлүгүңүздө» өзүңүздү мактоону унутпаңыз.','Sa saad suurepäraselt hakkama! 👏','Kas maja jäi täna natuke sassi? Ära üldse muretse! Naeru täis hetked, mida oma lapsega jagad, on palju väärtuslikumad. Ära unusta end meeleolupäevikus kiita.'),
('348430a9-4730-49e1-90ac-91076b5c5d7c'::uuid,'Түстөрдү үйрөнөлү! 🔴🔵','Кызыл оюнчуктар бир жакта, көктөрү экинчи жакта. 19,5 айлык балдардын көңүл буруусун жана логикасын өстүрүүчү үй оюндарын «Блог» бөлүмүнөн окуп, сынап көрүңүз.','Õpime värve! 🔴🔵','Punased mänguasjad ühel pool, sinised teisel. Loe ja proovi blogisektsioonist koduseid mänge, mis arendavad 19,5-kuuste tähelepanu ja loogikat.'),
('a3aeb0cd-d49a-4a1a-a82c-e3dc837e022c'::uuid,'Кечинде суюктук ичүү 🚰','Эгер эртең мененки жалаягы өтө оор болсо, кечкисин ичкен суусун көзөмөлдөө керек болушу мүмкүн. Муну «Жалаяк трекерине» белгилеп, күнүмдүк статистиканы карап туруңуз.','Öine vedeliku tarbimine 🚰','Kui nende hommikune mähe on väga raske, pead võib-olla kohandama õhtust veetarbimist. Logi see mähkmejälgijasse ja vaata üle päevastatistika.'),
('8ae66558-ee37-4cd1-9102-46bab1a97b21'::uuid,'5 мүнөттүк ырахат! 🥗','Шашылыш тамактанууга туура келип жатабы? Аялдар үчүн дени сак рецепттерибизден авокадо тостун жасап алыңыз, ал сизди ток жана энергиялуу кармайт!','5-minutiline nauding! 🥗','Haarata kiire amps teel olles? Tee meie naiste tervislike retseptide hulgast avokaado-võileib, mis hoiab sind täis ja energilisena!'),
('53a89401-1ea0-43b5-9469-65a0d422f72c'::uuid,'Тамак ичүүдөгү түгөнбөгөн оюн 🥣','Тамак менен ойноп, жерге чачып, бирок жебей жатабы? Тамактануу таймерин иштетиңиз жана тиркемедеги график аркылуу алардын табитинин өнүгүүсүн так талдап көрүңүз.','Lõputu söömisetendus 🥣','Mängib toiduga, loobib seda põrandale, aga ei söö? Käivita toitmise taimer ja analüüsi täpselt lapse isu arengut rakenduse graafiku abil.'),
('31a9cc16-de41-4012-b357-b74232182120'::uuid,'Сиз бүгүнкү күндүн каарманысыз 🌟','Алардын ар бир жаңы үйрөнгөн жөндөмү — сиздин эмгегиңиздин үзүрү. Маанай күндөлүгүңүздү ачып, бүгүн өзүңүзгө сыймыктануу сезимин тартуулай турган бир нерсе жазып коюңуз!','Oled tänane kangelane 🌟','Iga uus oskus, mille laps omandab, on tõestus sinu suurest tööst. Ava oma meeleolupäevik ja kirjuta täna üles midagi sellist, mis paneb sind endale aplodeerima!'),
('3f5ef83a-d114-41da-8dd2-6bd3c11c45e8'::uuid,'5 мүнөттүк энергия булагы ⚡','Эртең мененки жумуштарга шашпаңыз. Денеңизди кубаттандыруу үчүн биздин пайдалуу рецепттер жыйнагыбыздан антиоксидантка бай мөмө-жемиш кошулган сулу боткосун жасап ичиңиз.','5-minutiline energialaeng ⚡','Ära kiirusta hommikuste toimetustega. Turguta oma keha antioksüdantiderikka marja-kaerahelbepudruga meie tervislike retseptide kogust.'),
('622216cc-100d-4e85-95dc-7d70e41c5761'::uuid,'Өз алдынча тамактангысы келет 🥣','Наристеңиз кашыкты бербей жатабы? Тамактануу таймерин иштетип, бул сүйкүмдүү «эгемендүүлүк сынагы» канчага созуларын байкаңыз. Жөн гана жылмайып, бул башаламандыкты кабыл алыңыз!','Tahab iseseisvalt süüa 🥣','Kas su väike põngerjas keeldub lusikat käest andmast? Käivita toitmise taimer ja vaata, kui kaua see armas „iseseisvuse test“ kestab. Lihtsalt naerata ja lepi segadusega!'),
('057bf87f-0bbd-415e-a240-9562e85f263d'::uuid,'Кийинүү учурундагы кыйынчылыктар! 👗','Эртең менен кийинүү чоң күрөшкө айланып жатабы? Аларга тандоо үчүн эки башка көйнөк сунуштап, өз алдынча чечим кабыл алуусуна мүмкүнчүлүк бериңиз.','Riietumisega seotud raskused! 👗','Kas hommikune riietumine on suur võitlus? Anna lapsele valikuvabadus, pakkudes talle valida kahe erineva särgi vahel.'),
('f52268ca-f991-4824-88f4-73fcbe961356'::uuid,'Ич катуу маселесиби? 💩','Эртең менен жалаягын алмаштырып жатканда, ичинин иштешин байкаңыз. Эгер ичи катып жатса, аны тиркемеге жазып коюңуз жана Тамактануу трекери аркылуу менюсуна клетчаткага бай азыктарды кошууну унутпаңыз.','Kõhukinnisuse mured? 💩','Hommikust mähkmevahetust tehes jälgi lapse seedimist. Kui esineb kõhukinnisust, märgi see rakendusse ja lisa toitumisjälgija abil menüüsse kiudainerikkaid toite.'),
('8fc02957-0717-4600-94a0-03ec95b3ecc9'::uuid,'Горшокко үйрөтүүгө даярбы? 🚽','Эртең менен жалаягы кургакпы? Бул горшокко үйрөтүүнү баштоо үчүн эң ыңгайлуу учур болушу мүмкүн. Муну жалаяк трекерине жазып, тиркемедеги даярдык боюнча макалаларыбызды окуп чыгыңыз.','Kas pottitreeninguks valmis? 🚽','Kas hommikune mähe on täiesti kuiv? See võib olla ideaalne aeg potitreeninguga alustamiseks. Märgi see mähkmejälgijasse ja tutvu meie rakenduses olevate potitreeningu artiklitega.'),
('1ecb40c2-379b-4b51-a326-4d93bf0ac050'::uuid,'Эртең мененки энергияңызды сактаңыз ⚡','Күнүңүздү ачка баштабаңыз! 5 мүнөттө даяр боло турган, аялдар үчүн пайдалуу рецепттерибизден даамдуу жана ток кармоочу сулу боткосунан жасалган кексти тандап, өзүңүзгө кам көрүңүз.','Hoia oma hommikust energiat ⚡','Ära alusta päeva tühja kõhuga! Hoolitse enda eest ja vali tervislik, toitev ja maitsev kaerahelbemuffin meie naistele mõeldud tervislike retseptide hulgast – valmib vaid 5 minutiga.'),
('69fe7fde-913c-4ff4-8fe2-fcbdad210e16'::uuid,'Энелерге да достор керек! 👯‍♀️','Жалгызсырап, бир гана наристеңиз менен сүйлөшүп жаткандай сезилип жатабы? Башка энелер менен баарлашып, тажрыйба бөлүшүү үчүн «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн оюн топтору бар борборлорду табыңыз.','Emad vajavad ka sõpru! 👯‍♀️','Tunned end üksildasena, rääkides vaid oma pisikesega? Avasta meie „Emadele sõbralikud kohad“ rubriigist mängugruppidega keskusi, et teiste emadega suhelda ja kogemusi jagada.'),
('f7991ada-b885-400f-9f72-4df6d1f9477e'::uuid,'Күндүзгү уйку кыскарып баратабы? ⏱️','Кечээ кечинде уктап калуусу көп убакытты алдыбы? Уйку таймерин иштетип, графигин көзөмөлдөңүз. Балким, күндүзгү уйкусун 15-20 мүнөткө кыскартуу керек чыгар.','Kas päevased uinakud jäävad lühemaks? ⏱️','Kas uinumine võttis eile õhtul kaua aega? Käivita unetaimer ja jälgi graafikut. Võib-olla on aeg lühendada päevast und 15–20 minuti võrra.'),
('9c87f5af-e2e2-4310-ab2c-98ff6d5521d4'::uuid,'Тынчтык режимине өтүү 🤫','Алар уйкуга кирип баратканда өтө сезимтал болуп калышат. Сураныч, тынчтыкты сактаңыз.','Vaikuserežiimile lülitumine 🤫','Uinumise ajal muutuvad nad tundlikumaks. Palun hoia toas vaikust.'),
('41e1758f-79bb-43e3-8304-d4d74fa983b0'::uuid,'Аба ырайынын өзгөрүшү үйдө калууга мажбурлап жатабы? 🌧️','Биздин аба ырайы жана кийим тандоо куралыбыз сизге шамалдын ылдамдыгын жана эң ылайыктуу кийимди заматта айтып берет, андыктан сейил бакка ишенимдүү аттана берсеңиз болот!','Kas imelik ilm hoiab sind kodus? 🌧️','Lase meie ilma- ja riietustööriistal koheselt öelda tuule kiirus ja sobivaim riietus, et saaksid enesekindlalt parki jalutama minna!'),
('d816b4dc-5206-4a90-9e61-8c02ef8f5c68'::uuid,'Дасторкон үстүндөгү сабырдуулук 🥣','Балаңыз тамак менен ойноп, башаламандык жаратып жатабы? Тамактануу таймерин иштетиңиз, андан кийин процесс канча убакытка созулганын так көзөмөлдөө үчүн график аркылуу алардын табитинин өнүгүүсүн талдаңыз.','Kannatlikkus söögilauas 🥣','Kas su laps mängib toiduga ja teeb segadust? Käivita toitmise taimer ja analüüsi graafiku abil lapse isu, et täpselt jälgida, kui kaua söömine aega võtab.'),
('842a46f0-f832-4901-8e08-572103acff74'::uuid,'Бүгүн оор күн болдубу? 💆‍♀️','Үзгүлтүксүз ый жана кыйкырыктарды угуп жатасызбы? Терең дем алыңыз, өзүңүздү күнөөлөөнү токтотуңуз — сиз эң сонун энесиз!','Kas täna oli raske päev? 💆‍♀️','Kuuled pidevat nuttu ja karjumist? Hinga sügavalt sisse, lõpeta enda süüdistamine – teed suurepärast tööd!'),
('1681892e-80a4-445a-827d-19733c9c6b73'::uuid,'Коомчулуктун күчү 💬','«Эмне үчүн балам мынчалык өжөр?» деген ой сизди түйшөлтүп жатабы? Anacan коомчулугуна кошулуңуз. Башка энелердин үйлөрүндө болуп жаткан ушундай эле күлкүлүү кырдаалдарды окуганда, сиз жалгыз эмес экениңизди жана бул кадимки эле тарбиялоо процесси экенин түшүнөсүз.','Kogukonna jõud 💬','Kas mõte „Miks mu laps on nii kangekaelne?“ vaevab su meelt? Liitu Anacani kogukonnaga. Kui loed teiste emade kodudes toimuvatest sarnastest absurdsetest jonnihoogudest, mõistad, et sa pole üksi ja oled täiesti tavalisel lapsevanemaks olemise teekonnal.'),
('37bdad79-de07-4752-a75a-2761546b1523'::uuid,'Бөлүшүү кыйын 🧸','Балаңыз сейил бакта бир тууганына же башка балдарга орой мамиле кылып жатабы? Бөлүшүү алар үчүн азырынча түшүнүксүз түшүнүк. Жазалабаңыз, тескерисинче, алардын сезимдерин түшүнөрүңүздү көрсөтүңүз.','Jagamine on raske 🧸','Kas su laps käitub pargis õe-venna või teiste lastega karmilt? Jagamine on nende jaoks veel abstraktne mõiste. Ära karista, vaid näita talle, et mõistad tema tundeid.'),
('70cc8a60-04a1-4e4e-b5c3-986f74563498'::uuid,'20 мүнөттүк сейилдөө 👟','Балаңыз өзү бут кийимин кийем деп, жолго чыгууну кечеңдетип жатабы? Сабырыңызды жоготпоңуз.','20-minutiline väljasõit 👟','Laps tahab ise kingi jalga panna ja viivitab väljaminekuga? Ära kaota kannatust.'),
('e0d7037f-df25-46a9-8fd2-5b2b39c1432d'::uuid,'Эмеректерге чыгуу 🧗‍♂️','Наристеңиз диван же отургуч сыяктуу эмеректерге чыгууга аракет кылып жатабы? Алардын бут булчуңдары ар кандай бийиктикти сынап жатат. Коопсуздугун камсыз кылыңыз, бирок бул кичинекей тоого чыгуу укмуштуу окуяларына тоскоол болбоңуз.','Mööblile ronimine 🧗‍♂️','Kas su väike põngerjas üritab mööblile, näiteks diivanitele ja toolidele ronida? Tema jalalihased katsetavad erinevaid kõrgusi. Hoia teda, kuid ära takista neid väikeseid ronimisseiklusi.'),
('6007d88c-cdbb-46d0-9b99-4e7bdd857418'::uuid,'Түнкү бешик ыры 🎶','Эч кандай тиркеме же үн эненин бешик ырынын ордун баса албайт. Бүгүн кечинде наристеңизди кучагыңызга кысып, алардын эң жакшы көргөн, тынчтандыруучу бешик ырын акырын ырдап бериңиз.','Öine hällilaul 🎶','Ükski rakendus ega heli ei asenda ema hällilaulu. Täna lihtsalt hoia oma beebit tihedalt vastu rinda ja laula talle vaikselt tema lemmikut, kõige rahustavamat hällilaulu.'),
('ade78fe2-3290-467b-9d4f-4aa0e7d81802'::uuid,'Горшокко отуруудагы алгачкы ийгилик! 🚽','Балаңыз горшокко өз алдынча баргысы келеби? Бул 2,5 жашар бала үчүн чоң жетишкендик! Бул ийгиликти Жалаяк/Горшок трекерине жазып коюңуз жана бул өткөөл мезгилди жеңилдетүү үчүн биздин блогдорду окуп чыгыңыз.','Esimene potivõit! 🚽','Kas su laps tahab ise potil käia? See on 2,5-aastase jaoks suur verstapost! Märgi see saavutus mähkme-/potijälgijasse ja loe meie blogisid, et õppida, kuidas üleminekut veelgi sujuvamaks muuta.'),
('8f7c6b2d-87b3-4688-9ad1-78064dda6eb8'::uuid,'Апалардын маеги 💬','Өзүңүздү жетишсиз сезип жатасызбы? Anacan коомчулугу менен байланышыңыз! Башка энелердин колдоо көрсөткөн билдирүүлөрүн окуу сизге чоң сооронуч тартуулайт.','Emmede jutuajamine 💬','Tunned, et sa ei ole piisavalt hea? Võta ühendust Anacani kogukonnaga! Teiste emade toetavate kommentaaride lugemine võib pakkuda suurt lohutust.'),
('4a0eb59e-113c-42ab-af5f-e0f64f837b44'::uuid,'Жаңы жерлерди ачыңыз ☕','Күнүмдүк турмуштан чарчадыңызбы? Жакын жердеги коляска менен кирүүгө ыңгайлуу кафени табуу үчүн биздин тиркемени колдонуңуз жана өзүңүзгө кофе ичип эс алууну тартуулаңыз!','Avasta uusi kohti ☕','Tunned väsimust igapäevarutiinist? Kasuta meie rakendust, et leida läheduses asuv lapsevankrisõbralik kohvik ja lubada endale üks hädavajalik kohvipaus!'),
('4c4da832-707f-472e-a209-374acff11d94'::uuid,'Үй иштерине жардам берүү! 🧹','Наристеңиз чаң сүртүүчү чүпүрөктү кармаганга же шыпыргы менен ойногонго аракет кылып жатабы? Бул тууроо — алардын өнүгүүсүнүн эң сонун белгиси.','Kodutöödes abistamine! 🧹','Kas su väike põngerjas üritab haarata lappi, et tolmu pühkida, või mängib luuaga? See matkimine on imeline märk tema arengust.'),
('ca45e311-dc2b-43fe-aa24-08a197d26f0a'::uuid,'Балаңыздын өнүгүүсү боюнча суроолоруңуз барбы? 🤖','13-14 айлык мезгил боюнча кандайдыр бир тынчсызданууларыңыз болсо, жада калса түн ортосунда да биздин Anacan AI жардамчыбызга жазуудан тартынбаңыз.','Küsimused beebi arengu kohta? 🤖','Kui sul on 13–14 kuu vanuse perioodi kohta muresid, ära kõhkle kirjutamast meie Anacani AI-abilisele, isegi hilisõhtul.'),
('2064ec2b-0483-4d3b-9453-106b6b9f32f8'::uuid,'Алгачкы сүрөт тартуулар! 🖍','️ Аларга балдар үчүн коопсуз жоон карандаштарды же боёкторду берип, кагазга чиймелеп жатканын мээрим менен карап туруңуз. Ким билет, балким, көз алдыңызда болочок сүрөтчү чоңоюп жаткандыр!','Esimesed kriidijoonistused! 🖍','️ Paku talle lapsele ohutuid pakse kriite või värve ja vaata armastusega, kuidas ta paberile kritseldab. Kes teab, võib-olla kasvab su silme all tulevane kunstnik!'),
('7f86b541-f24f-46cc-bf72-a538c8e62fa0'::uuid,'Өз алдынча ойноо убактысы 🧩','Ал тургай, кыска убакытка өз алдынча ойноо да өзүн-өзү камсыздоого карай чоң кадам болуп саналат. Аларды алыстан байкап, айлана-чөйрөнү изилдөөсүнө мүмкүнчүлүк бериңиз!','Iseseisev mänguaeg 🧩','Isegi lühikesed iseseisva mängu hetked on suur samm iseseisvuse suunas. Jälgi teda eemalt ja lase tal avastada!'),
('f945146d-2bbb-40d9-95f6-29bdc7f3be6d'::uuid,'Чоңоюп жатат! 📏','Наристеңиздин кийимдери кичирейип баратат! Анын жаңы боюн жана салмагын Өсүү трекери бөлүмүнө кошуп, өнүгүүсүнө көз салып туруңуз.','Kasvab jõudsalt! 📏','Sinu pisikese riided jäävad väikeseks! Lisa tema uus pikkus ja kaal kasvu jälgimise sektsiooni ja hoia tema arengul silm peal.'),
('241a81f3-8158-4d3c-a8b2-640a1b060696'::uuid,'Тандап тамактанган бала менен иштөө 🍲','Айрым күндөрү наристеңиз жакшы көргөн тамагынан баш тартышы мүмкүн. Аны кыстабаңыз; жөн гана башка пайдалуу альтернативаларды сунуштаңыз.','Valiva sööjaga toimetulek 🍲','Mõnel päeval võib su väike põngerjas lemmiktoidust keelduda. Ära sunni teda; paku lihtsalt erinevaid tervislikke alternatiive.'),
('4716a93b-966d-4c69-b174-c2a48e9a09fa'::uuid,'Кечки жуунуу. 🛁','Жылуу ванна – күндүн кирин кетирүүнүн кызыктуу жолу гана эмес, наристеңизди эң сонун эс алдырып, уйкуга даярдайт.','Õhtune vann. 🛁','Soe vann ei ole mitte ainult lõbus viis päeva mustusest vabaneda, vaid see lõdvestab ka suurepäraselt su pisikest, valmistades teda ette uneks.'),
('dbbcb16c-cf48-47f7-92ab-992ed2fab247'::uuid,'Дене мүчөлөрүн үйрөнүү! 👃','"Мурунуң кана?" же "Кулагың кана?" деп ойноңуз. Алар туура көрсөткөндө, кол чаап, мактап кубаттаңыз!','Õpime kehaosi! 👃','Mängige „Kus on nina?“ või „Kus on kõrv?“. Kui ta õigesti näitab, julgusta teda plaksutamise ja kiitusega!'),
('0ffbde04-3193-4b21-aa17-136db5de3c72'::uuid,'Эмоционалдык күндөлүк 📝','Өзүңүздү жалгыз сезгенде, сезимдериңизди Маанай күндөлүгүнө жазыңыз. Эсиңизде болсун, бардык аялдар бул жолду басып өтүшөт жана Сиз абдан күчтүүсүз.','Emotsioonide päevik 📝','Kui tunned end üksinda, väljenda oma tundeid meeleolupäevikus. Pea meeles, et kõik naised läbivad neid teekondi ja sa oled uskumatult tugev.'),
('7cdfa7f4-2c92-497d-9290-43caf53d8a56'::uuid,'Тынчтыкка болгон муктаждык 🤫','Үн мониторунун жардамы менен бөлмөдөгү тынчтыкты сактаңыз. Түнкүсүн уйкунун бузулушу наристеңиздин да, Сиздин да эртең мененки маанайыңызга таасир этет.','Vaikuse vajadus 🤫','Hoia toas rahu helimonitori abil. Katkestatud ööuni mõjutab nii beebi kui ka sinu enda hommikust tuju.'),
('f39f5c34-c612-4758-a438-ed52b2d49ba8'::uuid,'«Кош бол!» деп айтуу! 👋','Кимдир бирөө кетип жатканда, наристеңиз өз демилгеси менен кол булгап коштошот! Бул сонун социалдык жетишкендик. Ар бир мүмкүнчүлүк болгон сайын аларды кубаттап туруңуз!','„Head aega!“ ütlemine 👋','Kui keegi lahkub, lehvitab su väike põngerjas omal algatusel head aega! See on kaunis sotsiaalne verstapost. Julgusta teda igal võimalusel!'),
('0dcb1657-4eeb-47c5-a193-84ed106d43bc'::uuid,'Суроо берүүдөн тартынбаңыз 🤖','Анын уйку тартибинде бир нерсени туура эмес кылып жатамбы деп кабатырланып жатасызбы? Кандайдыр бир шектенүүлөрүңүз болсо, дароо Anacan AI жардамчысынан сурап, көңүлүңүздү тынчтандырыңыз.','Ära häbene küsida 🤖','Muretsed, et teed lapse unerežiimiga midagi valesti? Küsi Anacani AI-lt koheselt kõigi oma kahtluste kohta ja leia meelerahu.'),
('10d800e4-c6bd-4325-b22e-385edaca8f7f'::uuid,'Түнкүсүн дагы эле ойгонуп жатабы? 😴','Эгерде акыркы учурда наристеңиздин уйкусу кайрадан бузулуп жатса, анын графигин талдоо жана тартибиндеги кемчиликтерди аныктоо үчүн Anacan уйку таймерин колдонуңуз.','Kas öised ärkamised jätkuvad? 😴','Kui su pisikese uni on viimasel ajal jälle häiritud olnud, kasuta Anacani unetaimerit, et analüüsida tema graafikut ja tuvastada rutiinis lüngad.'),
('0cc0cda4-4fef-4e92-9af2-cd065cfee008'::uuid,'Сиз эң мыктысыз! 💖','Бала тарбиялоо марафонго чуркаганга окшош. Бул кечте өзүңүзгө бир аз убакыт бөлүңүз, сүйүктүү тасмаңызды көрүңүз же жөн гана тынчтыкта эс алыңыз.','Oled parim! 💖','Lapse kasvatamine on nagu maratonijooks. Võta täna õhtul aega iseendale, vaata lemmikfilmi või lihtsalt lõõgastu rahus.'),
('781ac9f7-7fd3-4466-9d70-0b41dd1e954a'::uuid,'Оюнчуктарды сүйрөп жүрүү! 🧸','Сүйрөмө оюнчуктар же кичинекей түртмө арабалар эми алардын сүйүктүү эрмеги. Бул тең салмактуулукту жана координацияны өнүктүрүү үчүн эң сонун көнүгүү!','Mänguasjade vedamine! 🧸','Nööriga järelveetavad mänguasjad või väikesed lükkamiskärud on nüüd nende lemmiktegevus. See on suurepärane harjutus tasakaalu ja koordinatsiooni arendamiseks!'),
('7dec83e1-5089-42b4-a2b5-f3d997eb1138'::uuid,'Өзүңүздүн да тамактанууңузга көңүл буруңуз 🥗','Энергияга бай баланын артынан жетишүү кыйын болушу мүмкүн! Күчүңүздү калыбына келтирүүгө жардам берүү үчүн аялдар үчүн пайдалуу рецепттерибизден даамдуу жана витаминдүү тамак даярдаңыз.','Toida ka iseennast 🥗','Energilise lapsega sammu pidamine võib olla raske! Valmista meie naistele mõeldud tervislike retseptide hulgast maitsev ja vitamiinirikas eine, mis aitab su energiat taastada.'),
('6942d3e7-d39d-4aee-b8a0-ef2313920693'::uuid,'«Өзүм жасайм!» мезгили. 🧦','Эгерде наристеңиз байпагын өзү кийүүгө же өз алдынча тамактанууга аракет кылса, ага тоскоол болбоңуз. Алардын өз алдынчалык сезими дал ушул кичинекей аракеттер аркылуу өсөт.','„Teen ise!“ faas 🧦','Kui su väike põngerjas üritab ise sokke jalga panna või iseseisvalt süüa, ära takista teda. Tema iseseisvustunne kasvab just nende väikeste katsetuste kaudu.'),
('e1f2089f-f46e-44ca-b5b5-5564bd6ee8fb'::uuid,'Таза абадагы укмуштуу окуялар 🌳','Паркта жалбырактарды кармап, таштарды чогултуу алардын сенсордук өнүгүүсүн стимулдайт. Кийинки сейилдөөңүз үчүн жаңы сейил бакты тандоого аракет кылыңыз!','Seiklused värskes õhus 🌳','Lehtede puudutamine ja kivide korjamine pargis stimuleerib lapse sensoorset arengut. Proovi järgmiseks jalutuskäiguks valida uus park!'),
('96b02483-42a2-4868-a751-d817b0144951'::uuid,'Суу ичүүнү унутпаңыз! 💧','Экөөңүздөр тең! Энергияны талап кылган оюндардан кийин жана тамактануунун ортосунда денедеги суунун балансын сактоо үчүн жетиштүү суу ичүүнү унутпаңыздар.','Ära unusta juua! 💧','Mõlemad! Pärast energilist mängimist ja söögikordade vahel veendu, et jooksid piisavalt vett, et püsida hästi hüdreeritud.'),
('d89100dc-a7f8-49dd-8358-e3c63248fa5d'::uuid,'Сиздин кичинекей жардамчыңыз! 🧹','Балаңыз чаң сүртүү үчүн чүпүрөк алып же шыпыргы менен ойноп Сизди туурап жатабы? Балдар байкоо жүргүзүү аркылуу эң жакшы үйрөнүшөт!','Sinu väike abiline töös! 🧹','Kas su laps matkib sind, haarates lappi, et tolmu pühkida, või mängib luuaga? Lapsed õpivad kõige paremini jälgides!'),
('eea0806e-a72b-42f1-b1c3-b7a791619a96'::uuid,'Уйку режиминдеги өзгөрүүлөр? 😴','Эгерде күндүзгү уйку бир убакытка бириге баштаса, бул өткөөл мезгилде түнкү уйку көбөйүшү мүмкүн. Уйку таймери менен акыркы уйку режимдерин көзөмөлдөңүз.','Muutused uneharjumustes? 😴','Kui päevased uinakud hakkavad üheks pikemaks uneks koonduma, võib öine uni sellel üleminekuperioodil suureneda. Jälgi hiljutisi uneharjumusi unetaimeriga.'),
('15bfc39a-e833-4e38-b7fc-bc13ef473b00'::uuid,'Өз алдынча ойноо убактысы! 🧸','Наристеңиз эми 10-15 мүнөт бою оюнчуктар менен өзүн алаксыта алат! Бул көңүл буруу узактыгынын кеңейип жатканынын сонун белгиси. Тынч мүнөттөрдөн ырахат алыңыз!','Iseseisva mängu aeg! 🧸','Sinu väike põngerjas suudab nüüd end 10–15 minutit mänguasjadega tegevuses hoida! See on suurepärane märk kasvavast tähelepanuvõimest. Naudi vaikseid hetki!'),
('99045f34-6450-4abd-856c-64fd61405e7b'::uuid,'Сиздин үнүңүздү түшүнөт 🗣️','Сиз катуу "жок" дегенде, алар катып калып, Сизди карашабы? Бул алардын эмоцияларды жана чектерди түшүнө баштаганын көрсөтөт!','Mõistab sinu tooni 🗣️','Kui ütled kindlalt „ei“, kas ta tardub ja vaatab sulle otsa? See näitab, et ta hakkab emotsioone ja piire mõistma!'),
('dc953aca-0624-4e7e-a96b-11f2b35b9a14'::uuid,'Музыканын күчү 🎶','Кечки түшүнүксүз чыргоолонууларды жагымдуу классикалык музыка менен тынчтандырууга аракет кылыңыз. Көбүнчө бул жөнөкөй ыкма сонун натыйжа берет.','Muusika vägi 🎶','Proovi neid seletamatuid õhtuseid rahutusi leevendada õrna klassikalise muusikaga. Tihti teeb see lihtne nipp imesid.'),
('1eee6b26-c3fa-460c-8e48-030eb1e5a77c'::uuid,'Түстүү чиймелер! 🖍','️ Балдар үчүн коопсуз жоон карандаштар же боёктор жана чоң кагаз менен ыңгайлуу бурч даярдаңыз. Алардын алгачкы шедеврлерин Наристе альбомуңузда түбөлүккө калтырууну унутпаңыз!','Värvilised kritseldused! 🖍','️ Sea sisse hubane nurgake lapsele ohutute paksude kriitide või värvide ja suure paberiga. Ära unusta jäädvustada tema esimesi meistriteoseid oma beebialbumisse!'),
('3ed02c3f-6c13-412d-9e4b-93ad1bd1da69'::uuid,'Адистин жардамы керекпи? 🤖','Түнкүсүн да болсо, Anacan AI жардамчыбыздан «14 айлык баламдын сүйлөө жөндөмүн кантип өстүрсөм болот?» сыяктуу суроолорду сурасаңыз болот.','Vajad asjatundja abi? 🤖','Küsi ka hilisõhtul meie Anacan AI-assistendilt küsimusi, näiteks: „Kuidas toetada oma 14-kuuse lapse kõne arengut?“'),
('f1854aec-f168-4789-a191-8a1fa96c3cd8'::uuid,'Коопсуздукту жаңыртуу керек. 🛡','️ Балаңыз эркин басып, шкафтарды ача баштаганда, кооптуу жагдайлар көбөйөт. Эмеректерге бекиткичтерди орнотуу үчүн биздин «Сунушталган товарлар» тизмебизди карап чыгыңыз.','Turvakontroll vajab uuendamist. 🛡','️ Kui laps hakkab vabalt kõndima ja kappe avama, suurenevad ka võimalikud ohud. Vaata kindlasti meie „Soovitatud toodete“ nimekirjast lapsekindlaid kappe ja lukke.'),
('02d67440-3e37-4d1c-99f8-cbfa7aadda52'::uuid,'Пайдалуу тамактануу убактысы! 🍎','Энергиясы ташып турган балдар үчүн мөмө-жемиш кесимдери же жашылча таякчалары эң сонун тамак болот. Аларга өз алдынча кармап жегенге мүмкүнчүлүк бериңиз!','Tervislik vahepala! 🍎','Lõputu energiaga lastele on puuviljaviilud või köögiviljapulgad suurepärased vahepalad. Lase neil harjutada ise söömist, hoides ja süües ise!'),
('4a197291-3001-4afb-9a70-d4320bd260b2'::uuid,'«Бул эмне?» баскычы. ☝','️ Кичинекейиңиз баарын көрсөтүп, аттарын сурап жатабы? Ар бир нерсенин атын сабырдуулук менен айтып бериңиз; бул алардын сөз байлыгын тез арада өстүрөт!','„Mis see on?“ faas. ☝','️ Sinu väike põnn näitab kõigele näpuga ja küsib nimesid. Ütle kannatlikult iga eseme nimi; see arendab kiiresti lapse sõnavara!'),
('8938f1b0-220a-48ac-b5f5-33db3613995c'::uuid,'Атанын жомок айтып берүү убактысы. 👨‍🍼','Бүгүн кечинде жомок окуу жана уктатуу милдетин атасына өткөрүп бериңиз да, өзүңүзгө татыктуу эс алуу тартуулаңыз.','Issi unejutud. 👨‍🍼','Anna unejutu lugemine ja teki peale panemine täna õhtul issi hooleks ning luba endale üks igati väljateenitud väike puhkus.'),
('47ea2f2a-adf0-473a-a6a2-47218a354bbd'::uuid,'Маймыл сыяктуу тырмышып чыгуу! 🧗‍♂','️ Балаңыз диванга же жапыз эмеректерге өз алдынча чыгууга аракет кылып жатабы? Айлананы коопсуз кылып, алардын бул жаңы кыймыл-аракеттерин сиздин көзөмөлүңүз астында коопсуз сынап көрүүсүнө шарт түзүңүз.','Ronib nagu ahvike! 🧗‍♂','️ Kas su väike laps üritab iseseisvalt diivanile või madalale mööblile ronida? Muuda ümbrus lapsekindlaks ja lase tal oma uusi põnevaid motoorseid oskusi sinu valvsa pilgu all ohutult katsetada.'),
('ea4bc86f-6869-478f-98a6-52bb8dc4c40f'::uuid,'Уктоо убактысын жеңилдетүү. 🌙','Кечинде бирдей тартипти сактоо (сууга түшүрүү, жомок окуп берүү, жарыкты өчүрүү) балаңыздын тынч уктоосуна жардам берет.','Magamamineku lihtsustamine. 🌙','Igal õhtul samade tegevuste kordamine (vann, unejutt, tulede hämardamine) aitab su lapsel rahulikumalt uinuda.'),
('9052004a-46e9-4652-8de2-61f2a8f774d7'::uuid,'Чарчоо жана сыймыктануу 💖','Бул 14 айдын чарчоосу менен сыймыгын бүгүн кечинде жубайыңыз менен бөлүшүңүз. Сиздер эң сонун командасыздар!','Väsimus ja uhkus 💖','Tähistage täna õhtul koos partneriga seda 14 kuud kestnud väsimust ja uhkust. Olete suurepärane meeskond!'),
('dde3a118-6b4b-4b86-b077-744218b7fcd7'::uuid,'Наристеңиздин канчалык өскөнүн караңыз! 📈','Алгачкы күндөрдөгү коркуу сезимдери артта калып, азыр энелик ишенимге ээ болдуңуз. Өзүңүз менен сыймыктаныңыз!','Vaata, kui kaugele su väike ime on jõudnud! 📈','Algusaegade hirmud on asendunud tugeva emaliku enesekindlusega. Ole enda üle uhke!'),
('33a2089a-67cc-4441-bb79-483ad77a1a42'::uuid,'Өзүңүзгө убакыт бөлүңүз. 🛁','Бүгүн күн бою бутуңузда жүрдүңүз. Чарчооңузду басуу үчүн аны «Маанай күндөлүгүнө» белгилеп, бир чыны жылуу чай менен эс алыңыз.','Võta aega iseendale. 🛁','Oled terve päeva jalgadel olnud. Leevenda väsimust, märkides selle oma meeleolupäevikusse, ja lõõgastu sooja teetassiga.'),
('625bdfef-2359-4843-aaac-6c8411b1963b'::uuid,'Нерселерди ыргытуу өнөрү! 🎾','Оюнчуктарды же тамакты жерге ыргытып, алардын кулашын карап туруу — бул тентектик эмес, тартылуу күчүн изилдөө. Сабырдуу болуңуз жана ага сынбай турган нерселер менен ойноого уруксат бериңиз.','Viskamiskunsti meistriklass! 🎾','Mänguasjade või toidu põrandale viskamine ja nende kukkumise jälgimine pole pahatahtlikkus, vaid gravitatsiooni uurimine. Ole kannatlik ja lase tal purunematute esemetega mängida.'),
('ee0ba9ab-4b88-462e-aae9-f9a207218204'::uuid,'Чаян сыяктуу басуу! 🦀','Балаңыз эми алдыга гана эмес, артка жана капталга да басууну сынап жатат. Бул тең салмактуулукту сактоо жана кыймыл-аракетти өнүктүрүү үчүн эң сонун көнүгүү!','Kõnnib nagu krabi! 🦀','Sinu väike laps ei kõnni enam ainult edasi, vaid katsetab ka tagurpidi ja külgsuunas liikumist. See on suurepärane harjutus tasakaalu ja motoorsete oskuste arendamiseks!'),
('21478892-353c-43fd-ba31-59c9aeb8255d'::uuid,'Энелер үчүн энергия булагы! 🥗','Активдүү балдар энелерден эки эсе көп энергия талап кылат! Биздин пайдалуу рецепттерибизден даамдуу тамак тандап, өзүңүздү сыйлаңыз.','Energiasüst emmedele! 🥗','Aktiivsed lapsed nõuavad emadelt topeltenergiat! Premeeri end, valides ja valmistades maitsva roa meie tervislike retseptide hulgast.'),
('530feb7f-e42b-4ca3-88fe-a9c205c1ef1e'::uuid,'Телефон менен сүйлөшүп жаткандай түр көрсөтүү! 📱','Балаңыз пультту же телефонду кулагына кармап, сиздей болуп сүйлөөгө аракет кылып жатабы? Бул сүйкүмдүү тууроо учурларын өткөрүп жибербеңиз!','Teeskleb telefoniga rääkimist! 📱','Kas su väike laps hoiab pulti või telefoni kõrva ääres, püüdes rääkida täpselt nagu sina? Ära maga maha neid imearmsaid järeleaimamise hetki!'),
('ab819835-a2e1-481b-91b5-5391eb6051e8'::uuid,'Уйку режимин түшүнүү. ⏱️','Күндүзгү уйку бир маалга кыскардыбы? Балаңыз уктаганда уйку таймерин иштетип, жаңы тартипке көнүү үчүн графикти текшериңиз.','Mõista uneharjumusi. ⏱️','Kas päevased uinakud on vähenenud ühele korrale? Kui laps magab, käivita unetaimer ja kontrolli graafikut, et uue rutiiniga kohaneda.'),
('44b33bc4-3602-4265-9fe5-30b5609015de'::uuid,'Аталар менен биргеликте тарбиялоо. 👨‍🍼','Кечки оюн убагы абдан активдүү болушу мүмкүн. Бүгүн кечинде балаңыз менен атасы ойноп, уктатуу тартибин аткарып жатканда, сиз бир аз эс алып алыңыз.','Kooskasvatamise hetked issidega. 👨‍🍼','Õhtune mänguaeg võib olla väga energiline. Las täna õhtul tegeleb issi mürgeldamise ja magamamineku rutiiniga, samal ajal kui sina võtad aega lõõgastumiseks.'),
('b2803eb7-9fa9-49b3-a014-d7a2eabb5c95'::uuid,'Боорукердик сезими ойгонууда! 💖','Кимдир бирөө ыйласа же капа болсо, балаңыз жанына келип сооротууга аракет кылып жатабы? Балаңыздын эмоционалдык интеллекти сонун өнүгүп жатат!','Empaatia tärkab! 💖','Kui keegi nutab või on kurb, kas su laps tuleb ligi ja püüab teda lohutada? Sinu lapse emotsionaalne intelligentsus areneb imeliselt!'),
('e569bdf3-a845-44dc-852b-5318a0cf6a72'::uuid,'Сырттагы токтоосуз энергия! 🌳','Кичинекей изилдөөчүңүздүн энергиясын сарптоо үчүн, биздин «Энелер үчүн ыңгайлуу жайлар» функциясын колдонуп, коопсуз жана жаңы сейил бактарды табыңыз.','Peatamatu energia õues! 🌳','Et aidata oma väikesel avastajal energiat kulutada, leia turvalisi ja uusi parke, kuhu saad mugavalt minna, kasutades meie funktsiooni „Emadele sobivad asukohad“.'),
('381afc75-3dbd-4716-b5ea-3af987c642dc'::uuid,'Күндүзгү уйкудан баш тартуу. 😴','Ойноо уктоодон да кызыктуу! Уктоо убактысына жарым саат калганда активдүү оюндарды токтотуп, тынч оюндарга өтүңүз.','Uinakutele vastu hakkamine. 😴','Mängimine on alati huvitavam kui magamine! Pool tundi enne magamaminekut vaheta aktiivsed mängud vaiksemate tegevuste vastu.'),
('3ed2bd45-e711-4e56-bdc9-29b31e605069'::uuid,'Сурооңуз барбы? 🤖','«Эмне үчүн балам кээ бир күндөрү тамак жебей жатат?» сыяктуу маанилүү суроолор боюнча түнкүсүн да болсо Anacan AI жардамчыбыздан колдоо алыңыз.','Tekkis küsimus? 🤖','Oluliste küsimuste korral, nagu „Miks mu laps mõnel päeval ei söö?“, saad tuge meie Anacan AI-assistendilt, isegi hilisõhtul.'),
('718ac202-3ddd-463e-90fd-d1367161e2b5'::uuid,'Тандап жеген бала менен иштөө. 🍲','Кээде балаңыз сүйүктүү тамагынан баш тартышы мүмкүн. Мажбурлабаңыз; анын ордуна тиркемебиздеги башка рецепттерди сунуштап көрүңүз.','Kuidas toime tulla valiva sööjaga. 🍲','Mõnel päeval võib laps oma lemmiktoidust keelduda. Ära sunni teda; proovi selle asemel erinevaid alternatiivseid retsepte, mis on meie äpis saadaval.'),
('9693a098-adc4-4d19-ab73-4c5cc195a25e'::uuid,'Өзү сүртүүгө аракет кылуу! 🧽','Сиз столду сүртүп жатканда, балаңыз да чүпүрөк сурап жатабы? Кичинекей жардамчыңызга коопсуз жана жөнөкөй тапшырма бериңиз. Бул анын өзүнө болгон ишенимин абдан жогорулатат!','Nõuab, et tohiks ise pühkida! 🧽','Kui sa lauda pühid, kas su laps tahab ka lappi? Anna oma väikesele abilisele ohutu ja lihtne ülesanne. See tõstab uskumatult tema enesekindlust!'),
('98ba1e51-63c6-4c73-891d-99f1b14f3495'::uuid,'Ак ызы-чуунун (white noise) күчү. 🎶','Эгерде активдүү күн же тиш жаруудан улам уктабай жатса, «Ак ызы-чуу» (White Noises) бөлүмүнөн жамгырдын үнүн коюп, бөлмөдө тынч атмосфера түзүңүз.','Valge müra vägi. 🎶','Kui lapsel on aktiivse päeva või hammaste tuleku tõttu raske uinuda, loo toas rahulik õhkkond, mängides „Valge müra“ alt vihmasadu.'),
('f5a87b81-5f64-4d75-abaf-6fd718e53fc5'::uuid,'Пайдалуу тамактар. 🍎','Мөмө-жемиш кесимдери же йогурт бул курак үчүн эң сонун тамак. Тиркемедеги балдар үчүн рецепттерден уникалдуу жана даамдуу идеяларды табыңыз.','Tervislikud vahepalad. 🍎','Puuviljaviilud või jogurt on selles vanuses suurepärased vahepalad. Avasta äpist meie lasteretseptide hulgast unikaalseid ja maitsvaid ideid.'),
('0b365564-8d23-4572-9881-7a4b9e2159bf'::uuid,'Наристенин алгачкы шедеврлери! 🖍','️ Балаңыз кагазга жоон боёктор менен чийме тартууну жакшы көрөт. Алардын алгачкы шедеврлерин келечек үчүн «Баланын сүрөт сессиясы» бөлүмүндө сактап коюңуз.','Pisikese esimesed meistriteosed! 🖍','️ Sinu väike laps armastab paberile paksude värvidega kritseldada. Salvesta tema esimesed meistriteosed tulevikuks jaotisesse „Beebi fotosessioon“.'),
('c0638659-03fe-4ca5-b078-76057498811f'::uuid,'Апасына жабышып алуу! 🥰','Дааратканага кирсеңиз да, балаңыз эшиктин артында ыйлап күтүп жатабы? Бөлүнүү коркунучу эң жогорку чегинде болушу мүмкүн. Ар бир жолу аны сооротуп, жанында экениңизди сездириңиз.','Emme küljes rippumine! 🥰','Isegi kui lähed tualetti, ootab su laps ukse taga nuttes. Lahkumisärevus on tõenäoliselt haripunktis. Rahusta teda iga kord.'),
('f2ba1614-ef41-4060-97ee-0fe66e58b884'::uuid,'Суу ичүү абдан маанилүү. 💧','Алар канчалык активдүү болсо, ошончолук суусашат. Оюндар учурунда жана тамактан кийин аларга суу сунууну унутпаңыз.','Vedeliku tarbimine on võti. 💧','Mida aktiivsem laps on, seda janusem ta on. Ära unusta talle mängu ajal ja pärast sööki vett pakkuda.'),
('356f85b5-b941-4e2e-8218-18498e652ff8'::uuid,'Кубиктерден сепил куруу 🧱','Кичинекейиңиз эки-үч оюнчук кубикти биринин үстүнө бирин коюуга аракет кылып жатат. Анын бул сүйкүмдүү «инженердик» аракеттерин тынч байкап көрүңүз.','Klotsidest lossi ehitamine 🧱','Sinu väike laps proovib kahte või kolme klotsi üksteise peale laduda. Jälgi vaikselt neid imearmsaid „insenerikatsetusi“.'),
('b22af5a1-54b4-4af4-afbf-f4de46dc6ba3'::uuid,'Ак ызы-чуунун (white noise) күчү. 🎶','Эгерде активдүү күн же тиш жаруудан улам уктабай жатса, «Ак ызы-чуу» (White Noises) бөлүмүнөн жамгырдын үнүн коюп, бөлмөдө тынч атмосфера түзүңүз.','Valge müra vägi. 🎶','Kui lapsel on aktiivse päeva või hammaste tuleku tõttu raske uinuda, loo toas rahulik õhkkond, mängides „Valge müra“ alt vihmasadu.'),
('f73e2678-7057-466b-a01a-218bff7ab963'::uuid,'Тиш жууганды кызыктуу кылуу! 🪥','Балаңыз өзү тиш жуугуч щетканы кармагысы келеби? Анын бул адатын колдоңуз: күзгү алдында чогуу туруп, ага ылайыктуу жумшак щетка менен тишиңизди жууп көрсөтүңүз.','Muudame hammaste pesemise lõbusaks! 🪥','Kas su laps tahab ise hambaharja hoida? Julgusta seda harjumust, pestes koos peegli ees hambaid pehmete, neile sobivate harjadega.'),
('58b586ed-1396-42c6-81f5-29f087488332'::uuid,'Уйкуга жайлуу өтүү. 🌙','Активдүү күндөн кийин жарыкты өчүрүп, үнүңүздү басаңдатып, жомок окуп берүү менен аны уйкуга даярдаңыз.','Sujuv magamaminek. 🌙','Pärast aktiivset päeva hämarda tuled, räägi vaiksemalt ja valmista teda uneks ette, lugedes pehme häälega unejuttu.'),
('82b39d0a-8bac-4430-a17f-2937f0af35e1'::uuid,'Энергияңыздын түгөнүшүнө жол бербеңиз! 🥗','Өзүңүздү абдан чарчаңкы сезип жатасызбы? Аялдар үчүн ден соолукка пайдалуу рецепттерибизден витаминге бай смузи даярдап ичиңиз, ал сизге дароо күч-кубат берет.','Ära lase oma energial otsa saada! 🥗','Tunned end väga väsinuna? Valmista meie naiste tervislike retseptide hulgast vitamiinirikas smuuti, mis taastab hetkega energia, ja premeeri end.'),
('1bf6a974-24ed-47b3-8587-a38235ea120e'::uuid,'Ашканадагы укмуштуу окуялар! 🍳','Казан-аяктар, кашыктар жана пластик идиштер анын сүйүктүү оюнчуктарына айланды. Ага коопсуз шкафтарды ачып, жаңы «казыналарды» изилдөөгө мүмкүнчүлүк бериңиз!','Köögiseiklused! 🍳','Potid, lusikad ja plastkarbid on muutunud tema lemmikmänguasjadeks. Luba tal ohutult ligipääsetavaid kappe uurida ja uusi „aardeid“ avastada!'),
('88b4c840-5c20-4f9f-8b89-4530da60297b'::uuid,'Коопсуздукту текшерүү эскертүүсү! 🛡','️ Кичинекейиңиз шкафтарды ачып, изилдеп баштаганда коркунучтар да көбөйөт. Балдар үчүн коопсуздук кулпуларын жана бурч коргоочуларды табуу үчүн биздин «Сунушталган товарлар» тизмебизди карап чыгыңыз.','Meeldetuletus turvakontrolliks! 🛡','️ Kui su väike laps uurib ja avab kappe, suurenevad ohud. Vaata kindlasti meie „Soovitatud toodete“ nimekirjast lapsekindlaid lukke ja nurgakaitsmeid.'),
('409e6b49-8ccb-4975-92b1-c12021092540'::uuid,'Уктаар алдындагы жомоктордун сыйкыры. 📖','Уктаар алдындагы кыска жомок элестетүү жөндөмүн өстүрбөстөн, ортоңуздагы эмоционалдык байланышты да бекемдейт.','Unejutud on maagilised. 📖','Lühike unejutt enne magamaminekut mitte ainult ei arenda kujutlusvõimet, vaid tugevdab ka teievahelist emotsionaalset sidet.'),
('6b7d6637-7328-44aa-b6c8-47c73df3a6f3'::uuid,'Өсүү темпи абдан тез! 📏','Балаңыздын кийимдери кайрадан кичирейип баштады! Анын жаңы боюнун жана салмагынын өлчөмдөрүн «Өсүү трекери» бөлүмүнө киргизип, ден соолугунун чың өсүп жатканына кубаныңыз.','Kasvuspurt käib kiiresti! 📏','Lapse riided hakkavad jälle väikeseks jääma! Lisa tema uued pikkuse ja kaalu mõõdud jaotisesse „Kasvujälgija“ ja tähista tema tervislikku arengut.'),
('807127b9-417f-43a0-9bca-9ef33fbdadb8'::uuid,'Дене тили аркылуу баарлашуу 🗣️','«Барабызбы?» деп сураганыңызда, ал колун көтөрөт же башын чайкап «жок» дейт. Анын түшүнүү жөндөмү укмуштуудай өстү!','Kehakeele kaudu suhtlemine 🗣️','Kui küsid „Kas läheme?“, tõstab ta käed või raputab pead „Ei“. Tema arusaamisoskus on uskumatult kasvanud!'),
('2cca6125-c540-4b9b-9a06-6121b60507e5'::uuid,'Сырттагы укмуштуу окуя! 🌳','Балаңыз үйдүн ичинде энергиясын сарптай албай жатабы? Коляска менен ыңгайлуу басып жүрө турган жана таза абадан чогуу ырахат ала турган коопсуз сейил бакты тандаңыз.','Õueseiklus! 🌳','Kas laps ei saa toas energiat kulutatud? Vali turvaline park, kuhu saad mugavalt vankriga minna, ja nautige koos värsket õhku.'),
('73b001a8-93ab-4798-bca3-094a519e468a'::uuid,'Сезимдериңизди билдириңиз. 📝','Ар бир күн оңой боло бербейт; кээде баары оор сезилиши мүмкүн. Күнүмдүк стресстен арылуу үчүн сезимдериңизди «Маанай күндөлүгүнө» жазып туруңуз.','Väljenda oma tundeid. 📝','Iga päev pole kerge; mõnikord võib kõik tunduda üle jõu käivana. Vabane päeva stressist, kirjutades oma tunded meeleolupäevikusse.'),
('80913e3b-4640-4efe-ae49-ce789db16fd1'::uuid,'Күнүңүздүн эң сонун аягы. ✨','Бүгүн сиз эне катары колуңуздан келгендин баарын жасадыңыз. Көзүңүздү жумуп, өзүңүз менен сыймыктанып, тынч уйкуга кетиңиз.','Sinu päeva täiuslik lõpp. ✨','Täna tegid sa taas kõik, mida üks ema teha saab. Sule silmad ja uinu rahulikult, olles enda üle uhke.'),
('8e332da4-937a-4f7f-af67-edbe9e325d0e'::uuid,'Ишенимдүү кадамдар! 🏃‍♂','️ Азыр ал үйдү эркин изилдеп, кээде чуркаганга да аракет кылып жатат! Бул жаңы эр жүрөк кыймылдар сизди сыймыктандырат, бирок ошол эле учурда дайыма сак болууга да мажбурлайт!','Kõnnib enesekindlalt! 🏃‍♂','️ Ta uurib nüüd vabalt maja ja üritab vahel isegi joosta! Need vaprad uued liigutused teevad sind uhkeks, kuid hoiavad sind ka pidevalt valvel!'),
('b5982bde-910f-4d42-bc5f-8e5e9b2e683f'::uuid,'Аллергия боюнча кооптонуулар 🤖','Жаңы тамак берип, анын бетинде кызарууну байкадыңызбы? Дүрбөлөңгө түшөрдөн мурун, алгачкы кадамдарды Anacan AI''ден билип алыңыз.','Mured allergiate pärast 🤖','Kas oled tutvustanud uut toitu ja märganud põskedel punetust? Enne paanitsemist uuri esimesi samme Anacan AI-lt.'),
('0deab7a8-9a3b-4827-969f-f24303c70419'::uuid,'Тиш жаруудагы ыңгайсыздык. 🦷','Бүйлөлөрү кызарып, шилекейи кайрадан тынымсыз агып жатабы? Муздак тиш кашыгычтарды даярдаңыз.','Hammaste tulekust tingitud ebamugavus. 🦷','Kas igemed on jälle punased ja ila voolab lakkamatult? Pane külmad närimisrõngad valmis.'),
('46166e0f-606a-46ff-86d4-07304bc93180'::uuid,'Суу ичүүнү адат кылуу! 💧','Активдүү кыймылдаган сайын, анын чаңкоосу күчөйт. Оюн учурунда жана тамактан кийин ага суу сунуштоону унутпаңыз.','Muudame joomise harjumuseks! 💧','Aktiivselt liikudes janu suureneb. Ära unusta talle mängu ajal ja pärast sööki vett pakkuda.'),
('9e232723-1401-4819-8b29-1e4636b3edc3'::uuid,'Алгачкы көркөм чыгармалар! 🖍','️ Кичинекейиңиз калың боёктор менен кагазга сүрөт тартканды жакшы көрөт! Анын алгачкы искусство чыгармаларын келечек үчүн «Бөбөктүн сүрөт альбому» бөлүмүндө сактап коюңуз.','Esimesed kunstiteosed! 🖍','️ Sinu väike laps armastab paberile paksude värvidega kritseldada! Säilita tema esimesed kunstiteosed tulevikuks jaotises „Beebi fotoalbum“.'),
('2423bd81-d7d2-4b3e-b97a-32a10186bc3d'::uuid,'Элестетүү оюну башталды! 🧸','Балаңыз оюнчук аюусуна тамак же суу берүүгө аракет кылып жатабы? Бул анын сизди канчалык кунт коюп байкап, туурап жатканынын эң таттуу далили!','Kujutlusmängud algavad! 🧸','Kas su laps üritab oma kaisukaru toita või talle juua anda? See on armsaim tõestus sellest, kui tähelepanelikult ta sind jälgib ja järele aimab!'),
('a589cdee-fd82-4fde-b44b-6b88fbe8e1cc'::uuid,'Сурооңуз барбы? 🤖','Сизди түйшөлткөн «Баламдын тамак тандаганы нормалдуубу?» сыяктуу суроолорду, атүгүл түн бир оокумда да биздин Anacan AI жардамчыбызга бериңиз.','Tekkis küsimus? 🤖','Kõigi sind huvitavate küsimuste korral, nagu „Kas minu lapse valiv söömine on normaalne?“, küsi meie Anacan AI-assistendilt, isegi hilisõhtul.'),
('d4f6586e-25f9-4dd3-9a6b-1408627d49eb'::uuid,'Күндүзгү уйкудан баш тартуу. 😴','Уктаганга караганда ойногон ар дайым кызыктуураак. Эгер балаңыздын уктоосу кыйын болуп жатса, анын акыркы графигин көзөмөлдөө жана режимин жөнгө салуу үчүн Anacan''дын уйку таймерин колдонуңуз.','Uinakutele vastu hakkamine. 😴','Mängimine on alati ahvatlevam kui magamine. Kui lapsel on raske uinuda, kasuta Anacani unetaimerit, et jälgida tema hiljutist graafikut ja rutiini kohandada.'),
('13b16a71-31e8-44cf-bbf4-b97f55c8f45e'::uuid,'Сырттагы аба ырайы ыңгайсыз болсочу? ⛅','Аба ырайы жана кийим куралы терезеңизден көрүнбөгөн шамалдын ылдамдыгын сизге заматта айтып берсин.','Kui ilm õues ei ole just kõige parem? ⛅','Lase ilma- ja riietustööriistal endale kohe öelda tuulekiirus, mida aknast ei näe.'),
('807a2e9f-2fb3-4378-94cf-0ad756854f25'::uuid,'Өзгөчө жомок убактысы. 🪄','Smart Tales бөлүмүндө балаңыз башкы каарман болгон өзгөчө жомокту жаратыңыз: Жылдыздарга жеткен эр жүрөк бала.','Eriline unejutu aeg. 🪄','Loo „Nutikate juttude“ (Smart Tales) abil eriline lugu, kus peategelaseks on sinu laps: „Vapper laps, kes ronis tähtede juurde“.'),
('25f37869-be99-4918-83ae-dd5fecd2f5ce'::uuid,'Ашканада чогуу! 🥦','Тамак жасап жатканда, ага сынбаган желим идиш жана жыгач кашык бериңиз; ал дагы өз тамагын «жасасын».','Koos köögis! 🥦','Toidu valmistamisel anna talle purunematu plastkauss ja puulusikas; las ta „valmistab“ ka oma toitu.'),
('c0b75b28-86cb-44ea-8bc4-de62c31fae30'::uuid,'Пландоо жан дүйнөгө тынчтык берет. 📝','Эртеңки аткарылчу иштердин тизмесине же тамактануу планына оюңузда кичинекей белгилерди жасап, акыл-эсиңизди даярдаңыз, андан соң эс алган абалда уктаганы жатыңыз.','Planeerimine toob meelerahu. 📝','Valmista end vaimselt ette homseteks toimetusteks või toiduplaaniks väikeste märkmetega oma peas, seejärel suundu puhanuna magama.'),
('e47ea433-71bf-4c11-8e6e-6edbaec03292'::uuid,'Баарын көрсөтүп жатат! ☝','️ Бул «Бул эмне?» дегендин үнсүз версиясы. Анын кызыгуусун сактап калуу үчүн, ал көрсөткөн ар бир нерсенин атын сабырдуулук менен кайталаңыз.','Näitab kõigele näpuga! ☝','️ See on küsimuse „Mis see on?“ vaikne versioon. Et hoida lapse uudishimu elus, korda kannatlikult iga asja nime, millele ta näpuga näitab.'),
('09564db7-642f-496e-b113-4fd15ad5aefe'::uuid,'Атанын түнкү нөөмөтү. 👨‍🍼','Түнкүсүн ойгонуу түйшүгүн жалгыз өзүңүз тартпаңыз. Жолдошуңузду да ойготуңуз; команда болуу – бул жоопкерчиликти тең бөлүшүү дегенди билдирет.','Issi öövahetus. 👨‍🍼','Ära kanna öiseid ärkamisi üksi. Ärata ka oma partner; meeskonnana tegutsemine tähendab kohustuste võrdset jagamist.'),
('30d6fd90-986c-491d-9a4a-39c6c9f48f69'::uuid,'Өнүгүүнү текшерүү 🤖','15 айлык наристенин өнүгүү секириктери тууралуу маалымат керекпи? Wonder Weeks календарын карап көрүңүз.','Arengukontroll 🤖','Vajad teavet 15-kuuste arenguhüpete kohta? Vaata Wonder Weeksi kalendrit.'),
('661b0ef0-cce8-4702-8d5a-2f90901198ad'::uuid,'Китепке болгон сүйүүнү калыптандыруу! 📖','Сүрөттүү китептердин барактарын оодарып, сиздин окуганыңызды угуу – алардын сөз байлыгын өстүрүүнүн эң сонун жолу. Күн сайын кеминде 10 мүнөт чогуу окууга аракет кылыңыз.','Raamatute armastuse tärkamine! 📖','Pildiraamatute lehitsemine ja sinu ettelugemise kuulamine on suurepärane viis sõnavara arendamiseks. Püüdke koos lugeda vähemalt 10 minutit iga päev.'),
('3d8cb5fe-0f15-4006-98f6-4f4232e5efb2'::uuid,'Сиздин үнүңүздү түшүнүү! 🗣️','«Болбойт» деп олуттуу айтканыңызда, алар токтоп, сизге карап калабы? Демек, алар эмоцияларды жана чек араларды түшүнө башташты!','Mõistab sinu tooni! 🗣️','Kas laps jääb seisma ja vaatab sulle otsa, kui ütled tõsisel toonil „ei“? Ta hakkab mõistma emotsioone ja piire!'),
('553f302d-8ba0-44d9-9d9d-e356d494f003'::uuid,'Уйку алдындагы тартип. 😴','Жылуу ванна жана таза пижама аларды тынчтандырып, уйкуга эң сонун даярдайт.','Magamamineku rutiin. 😴','Soe vann ja puhtad pidžaamad rahustavad last ja valmistavad ta suurepäraselt uneks ette.'),
('ed9814d4-d919-40b0-833b-d118d90c1727'::uuid,'Эгемендүүлүк издөөдө. 🥣','Өз алдынча чөйчөгүн же кашыгын кармагысы келсе, мүмкүнчүлүк бериңиз. Башаламандык – бул үйрөнүүнүн эң кооз бөлүгү.','Iseseisvuse otsingul. 🥣','Kui laps soovib ise oma kaussi või lusikat hoida, anna talle see võimalus. Segadus on õppimise kõige ilusam osa.'),
('4e2f3772-b7ad-4946-a8a3-70f3ebef0c4e'::uuid,'Сизге да энергия керек! 🥗','Күн бою бутуңуздасыз. Күчүңүздү калыбына келтирүү үчүн аялдар үчүн пайдалуу рецепттерибизден даамдуу тамак даярдап алыңыз.','Ka sina vajad energiat! 🥗','Oled terve päeva jalgadel. Valmista meie tervislike retseptide hulgast üks maitsev vahepala, mis taastab sinu energia.'),
('6df61827-7605-47d2-aeef-a4e811b4d8c8'::uuid,'Тез ачылыштарды жасоо! 🏃‍♂','️ Кичинекейиңиз эми бөлмөлөрдүн ортосунда ишенимдүү басып, баарына тийгиси келет! Үйүңүздүн коопсуздугун камсыздап, бул активдүү мезгилден ырахат алыңыз.','Kiired avastused! 🏃‍♂','️ Sinu väike ime liigub nüüd enesekindlalt tubade vahel ja tahab kõike katsuda! Veendu, et kodu oleks lapsekindel, ja naudi seda aktiivset faasi.'),
('c9b2a6a2-258b-4f8c-96f9-86282d8d8145'::uuid,'Эмоционалдык жеңилдик. 📝','Чарчаңкы күндөн кийин, сезимдериңизди Маанай күндөлүгүнө жазып, стресстен арылыңыз. Сиз укмуштуудай энесиз!','Emotsionaalne vabanemine. 📝','Pärast kurnavat päeva vabane pingest, kirjutades oma tunded üles meeleolupäevikusse. Oled suurepärane ema!'),
('14e2b559-f6b1-4ffb-ba5f-0e5d6eeca267'::uuid,'Сиз чыныгы баатырсыз! ✨','Акыркы 450 күн ичинде көрсөткөн сүйүүңүз менен камкордугуңуздун орду толгус. Эми, бул сонун күндөн кийин эс алып, тынч уктаңыз.','Sa oled kangelane! ✨','Armastus ja hool, mida oled viimase 450 päeva jooksul jaganud, on asendamatud. Nüüd lõõgastu ja uinu pärast seda kaunist päeva rahulikult.'),
('157a98b7-1825-4699-b38d-85781cd21cf3'::uuid,'Ар бир бөлмөнү изилдөө! 🏃‍♂️','Алар эми жөн эле баспай, дээрлик чуркап калышты! Тең салмактуулугу күн сайын жакшырууда. Бул активдүү этапты Өсүү трекерине сыймыктануу менен белгилеп коюңуз.','Avastab igat tuba! 🏃‍♂️','Ta ei kõnni enam lihtsalt, vaid peaaegu jookseb! Tema tasakaal paraneb iga päevaga. Märgi see aktiivne faas uhkusega oma arengupäevikusse.'),
('47ea1c98-c71a-45d9-b06c-d95aa3da437b'::uuid,'Ата менен көңүлдүү оюн 👨‍👧','Күнү бою алардын артынан чуркоо чарчатышы мүмкүн. Бүгүн кечинде атасынын кезеги! Полдо тоголонуп ойноо жана кууп ойноолорду ага тапшырыңыз.','Issi mänguaeg 👨‍👧','Nendega terve päeva jooksmine võib olla kurnav. Täna on issi kord! Lase temal tegeleda põrandal püherdamise ja tagaajamisega.'),
('9b3b08e6-de82-413f-9e4b-6da904b304a3'::uuid,'Бүгүн үйдүн башаламандыгына кабатыр болбоңуз.','Балдар үйдүн тазалыгын эмес, бактылуу энесин эстешет. Өзүңүзгө кофе куюп, эс алыңыз.','Ära muretse täna segamini kodu pärast.','Lapsed mäletavad õnnelikke emasid, mitte korras kodusid. Vala endale tass kohvi ja lõõgastu.'),
('67b35eea-eab9-41c5-88b7-f31e283eddd9'::uuid,'Балаңыз үйдө тынчсызданып жатабы? ⛅','Жаратылыш – эң мыкты тынчтандыруучу каражат. Аба ырайын карап, ылайыктуу кийим тандап, түз эле сейил бакка жөнөңүз!','Kas su laps on toas rahutu ja viril? ⛅','Loodus on parim rahustaja. Vaata ilma, vali sobiv riietus ja suundu otse parki!'),
('b9cf7b0e-6913-455f-8740-fcf7cc3d09d9'::uuid,'«Бул эмне?» баскычы! ☝️','Алар манжасы менен баарын көрсөтүп, өзгөчө үндөрдү чыгарышат. Алар дүйнөнүн аталыштарын сизден сурап жатышат! Сабырдуулук менен көрсөткөн ар бир нерсенин атын айтып бериңиз.','„Mis see on?“ faas! ☝️','Laps näitab näpuga kõigele ja teeb erilist häält. Ta palub, et nimetaksid maailma tema jaoks! Nimeta kannatlikult iga eset, millele ta osutab.'),
('d4a833e4-9676-4c95-baa2-923b9117c325'::uuid,'Тынчтык көз ирмеми 🤫','Уктап кеткенден кийинки алгачкы жарым саат – эң сезимтал учур. Бөлмөдөгү ызы-чуунун деңгээлин үн өлчөгүч менен текшерип, күтүүсүз үндөрдөн сак болуңуз.','Vaikusehetk 🤫','Esimene pooltund pärast uinumist on kõige tundlikum aeg. Kontrolli toa mürataset helimõõtjaga ja väldi äkilisi helisid.'),
('088ce5b1-9a8e-4d7d-8f55-017e0cc63605'::uuid,'Сурооңуз барбы? 🤖','15 айлык наристеңиздин өнүгүүсү боюнча тынчсызданып жатасызбы? Интернеттен издеп убара болбой, илимий негизделген жооп алуу үчүн түздөн-түз Anacan AI''дан сураңыз.','Kas sul on küsimusi? 🤖','Muretsed 15-kuuse lapse arengu pärast? Ära eksi interneti otsingutesse; küsi teaduspõhist vastust otse Anacan AI-lt.'),
('b6c6ae0a-2aaa-45b3-b8de-d4785923503c'::uuid,'Сыйкырдуу жомок убактысы 🪄','Алар үчүн дүйнөнү акылдуу жомоктор аркылуу тааныган эр жүрөк баатыр жөнүндө өзгөчө окуя ойлоп табыңыз. Уйкуга кетүүсүн жеңилдетиңиз.','Maagiline unejutu aeg 🪄','Loo talle eriline lugu vaprast kangelasest, kes avastab maailma nutikate juttude kaudu. Muuda uinumine magusamaks.'),
('c4cd946e-4029-4937-a10b-6f87983c2067'::uuid,'Өз алдынча уктоо 🥱','Эртең мененки уйкуга жаткыңыз келбей, графикти бузуп жатабы? Алар чоңоюп жатышат! Эки маал уктоодон бир маал уктоого өтүү ушул мезгилде башталат. Режимин акырындап жөнгө салыңыз.','Iseseisev uinumine 🥱','Ei taha hommikusele uinakule minna ja ajab graafiku sassi? Ta kasvab! Üleminek kahelt uinakult ühele algab sageli just sel ajal. Kohanda rutiini järk-järgult.'),
('2517046a-f369-483a-b1e2-38f6320720ad'::uuid,'Жайлуу жылуу ванна 🛁','Суу менен ойноо алардын күндүзгү чаңын жана чарчоосун жууп кетүүгө жардам берет, бул көңүлдүү жана уйкуга эң сонун даярдык.','Soe ja rahustav vann 🛁','Veega mängimine aitab päeva tolmu ja väsimuse maha pesta, muutes selle lõbusaks ja valmistades lapse suurepäraselt uneks ette.'),
('258818a7-034e-4b93-86ea-97e8e01d3126'::uuid,'Кыяшалык кылып жатабы? 🌪','️ Өзүн көрсөтө албай калганда, алар капаланып ыйлашы мүмкүн. Эгер бул боюнча колдоо керек болсо, эң туура ыкманы билүү үчүн Anacan AI менен кеңешиңиз.','Jonnihood? 🌪','️ Kui laps ei suuda end väljendada, võib ta muutuda frustreerituks ja nutta. Kui vajad selles osas tuge, konsulteeri Anacan AI-ga, et leida parim lähenemisviis.'),
('ca5a1958-0c22-4c62-874b-c3b801f70118'::uuid,'Жаңы сөздөрдү өздөштүрүү! 🧠','Сураганда бут кийимин таап алып келеби? Бул алардын интеллектинин канчалык тез өнүгүп жатканын көрсөтөт. Аларды мактап коюңуз!','Uute sõnade omandamine! 🧠','Kas laps leiab ja toob sulle kingad, kui palud? See näitab, kui kiiresti tema intelligentsus areneb. Kiida teda ohtralt!'),
('9cae6c34-b21b-425c-bdc8-0f1f07e9d0ea'::uuid,'Сиздин кичинекей меню диктаторуңуз! 🥣','Кечээ жакшы көргөн тамагын бүгүн жебей жатабы? Бул куракта тамак тандап жеш кадимки көрүнүш. Дүрбөлөңгө түшпөстөн, «Пайдалуу рецепттер» бөлүмүнөн башка альтернативаларды издеңиз.','Sinu väike menüüdikteerija! 🥣','Kas ta lükkab tagasi toidu, mida eile veel armastas? Selles vanuses pirtsutamine on normaalne. Ära paanitse, vaid otsi tervislike retseptide sektsioonist alternatiive.'),
('54788c72-cfe2-4f75-82f0-ba29d942e404'::uuid,'Жаныбарлардын үнүн тууроо! 🐱','«Мышык кандай үн чыгарат?» оюнун ойноңуз. Мындай жөнөкөй жана кызыктуу тууроолор алардын сүйлөп баштоосуна эң сонун негиз болуп берет.','Loomahäälte järeleaimamine! 🐱','Mängige mängu „Kuidas kass teeb?“. Need lihtsad ja lõbusad matkimised on suurepärane vundament rääkima hakkamiseks.'),
('b6e52bfa-dc31-4ddf-8f05-2d6b4e9ec2fa'::uuid,'Энергияңызды толуктаңыз 🥑','Эгер алар курсагын тойгузса, эми сиздин кезегиңиз! Күнүмдүк түйшүктүн арасында тик туруп тамактанбаңыз. Пайдалуу рецепттерибизден күч бере турган тамак тандап, диванга жатып эс алыңыз.','Taasta oma energia 🥑','Kui laps on söönud, on sinu kord! Ära söö lõunat igapäevases saginas püsti seistes. Vali meie tervislike retseptide hulgast energiat andev vahepala ja viska diivanile pikali.'),
('f3a87482-9f2e-4700-94d8-d413093ea00a'::uuid,'Кечки тартиптин күчү 🛀','Жылуу ванна ар дайым жардам берет. Кечки тартибин эч качан бузбаңыз, анткени бул анын мээсине уйку убактысы келгени тууралуу белги берет.','Õhtuse rutiini vägi 🛀','Soe vann aitab alati. Ära kunagi riku õhtust rutiini, sest see annab lapse ajule märku, et on aeg magama minna.'),
('1b9c01dc-4c8d-4f96-bbe5-d06d1d460981'::uuid,'Күндүн таттуу көз ирмемдери 📸','Бул баалуу көз ирмемдерди түбөлүккө калтыруу үчүн, бүгүнкү кызыктуу жоруктарын же жаңы үйрөнгөн жөндөмдөрүн «Ымыркайдын фотосессиясы» аркылуу сүрөткө тартып алыңыз.','Päeva armsad hetked 📸','Jäädvusta tänased naljakad grimassid või uued oskused beebifotode funktsiooniga, et need väärtuslikud hetked igaveseks talletada.'),
('21100889-9857-4170-a0a6-59c3dec113f8'::uuid,'Чек араны сынап көрүү. 🛑','«Жок» дегениңизге карабай, дагы эле ошол буюмга умтулуп жатабы? Бул каршылык көрсөтүү эмес, болгону эрежелерди үйрөнүү үчүн жасалган сыноо. Сабырдуу болуңуз.','Piiride katsetamine. 🛑','Kas laps sirutab käe keelatud eseme järele, kuigi ütlesid „ei“? See pole trots, vaid lihtsalt reeglite katsetamine. Ole kannatlik.'),
('66da2b8a-fe86-40dc-b027-d36d46f5091a'::uuid,'Кичинекей китеп сүйүүчү! 📖','Калың барактуу китептердин барактарын барактап, сүрөттөргө реакция кылып жатабы? Анын көрүү эс тутуму өнүгүүдө! Ага көптөгөн түстүү жомок китептерин окуп бериңиз.','Tärkav raamatusõber! 📖','Kas laps keerab raamatulehti ja reageerib piltidele? Tema visuaalne mälu areneb! Loe talle palju värvilisi juturaamatuid.'),
('5991e165-7b36-40d5-be3a-c6729cd8e924'::uuid,'Тазалоо же эс алуу? 🛋️','Балаңыз уктап жатканда идиш жууганга шашпаңыз. Диванга жатып, көзүңүздү жумуп, 15 мүнөт жөн гана дем алыңыз. Сиз роботсузбу? Жок.','Koristada või puhata? 🛋️','Kui laps magab, ära torma nõudepesumasina juurde. Heida diivanile, pane silmad kinni ja lihtsalt hinga 15 minutit. Kas sa oled robot? Ei ole.'),
('67273a71-3d6d-40e2-b209-34b098335818'::uuid,'Күн сайын өсүүдө 📸','Бул баалуу көз ирмемди эстеп калуу жана сактап коюу үчүн дароо «Ымыркайдын фотосессиясы» функциясын ачыңыз.','Kasvab iga päevaga 📸','Ava kohe beebifotode funktsioon, et see kaunis hetk jäädvustada ja mällu söövitada.'),
('d17f36fc-9cb8-4df2-a29e-60891f565b13'::uuid,'Өз алдынча тамактануу укмуштуу окуясы 🥄','Кичинекейиңиз кашыкты кармап, өз алдынча тамактангысы келип жатат! Бир аз булганышы мүмкүн, бирок бул анын өсүп жаткан моторикасы үчүн абдан маанилүү. Анын өз алдынчалыгын колдоңуз.','Ise söömise seiklused 🥄','Sinu väike ime tahab lusikat haarata ja ise süüa! See võib küll veidi segadust tekitada, kuid on lapse motoorika arenguks ülioluline. Julgusta tema iseseisvust.'),
('145c55e0-770c-4adc-a15b-4bd94389378f'::uuid,'Коркунучтуу аймактарга кирүү ⚡','Ал бою өсүп, мурда колу жетпеген текчелерге жете баштады! Сыналгы койгучтар, курч бурчтар... Үйдүн коопсуздугун тез арада кайра текшерип чыгууга убакыт келди.','Juurdepääs ohtlikesse tsoonidesse ⚡','Laps on kasvanud ja ulatub nüüd riiuliteni, kuhu varem ei küündinud! Telerialused, teravad nurgad... On aeg kodu turvalisus uuesti üle kontrollida.'),
('b6ac32de-f983-4a93-89fc-cb209586570b'::uuid,'Тиш жарылып жатабы? 🦷','Бүйлөлөрү шишип, колун оозуна салып жатабы? Арткы тиштери чыгып жаткан болушу мүмкүн! «Тиш чыгууну көзөмөлдөөчү» бөлүмүн текшерип, муздак тиш салгычтарды бериңиз.','Kas hambad tulevad? 🦷','Kas igemed on turses ja laps topib käsi suhu? Võib-olla tulevad tagahambad! Kontrolli hammaste tuleku jälgijat ja paku külma närimisrõngast.'),
('d2fd7757-cdd9-4cc6-b45c-347ada81b748'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктоого бир саат калганда үйдөгү бардык ачык жарыктарды жана экрандарды өчүрүңүз. Мелатонин тынч жана күңүрт чөйрөдө гана бөлүнүп чыгат.','Hämarda tuled 🌙','Lülita tund enne magamaminekut kodus välja kõik eredad tuled ja ekraanid. Melatoniin eritub vaid rahulikus ja hämaras keskkonnas.'),
('4139adbd-6ed1-4e3e-a4dc-01c65b9d8182'::uuid,'Күтүүсүз ойгонуулар 😭','Түн ортосунда кыйкырып ойгонуп, токтобой жатабы? Бул түнкү коркунучпу же оорубу экенин аныктоо үчүн «Ыйды анализдөө» функциясын колдонуп, анын ыйын угуп көрүңүз.','Äkilised ärkamised 😭','Kas laps ärkab keset ööd nuttes ega jää vait? Kuula tema nuttu nutianalüüsi funktsiooniga, et teha kindlaks, kas tegemist on öise hirmuhoo või valuga.'),
('cfd3d5f1-834e-412c-9e3a-a69a0413fbc1'::uuid,'Кичинекей дене, чоң сезимдер 🛑','Алар каалаган нерсесин албай калганда жерге жатып алып ыйлап жатышабы? Наристелердин кыялкеч дүйнөсүнө кош келиңиз! Сабырдуу болуңуз, көз караштарыңызды бириктириңиз жана алардын жанында экениңизди сездириңиз.','Väike keha, suured tunded 🛑','Kas ta viskab end põrandale, kui ei saa oma tahtmist? Tere tulemast väikelaste jonnihoogude imelisse maailma! Jää rahulikuks, loo silmside ja anna talle teada, et oled tema jaoks olemas.'),
('d33491b0-9722-4db2-ae48-c019740b7411'::uuid,'Биримдик руху 🥂','Түгөйүңүз менен өткөргөн алгачкы күндөрдү, уйкусуз түндөрдү эстеп, күлүп алыңыз. Сиз бул чекке оңой менен жеткен жоксуз! Бул — биргелешкен иштин жеңиши.','Ühtekuuluvustunne 🥂','Meenuta neid esimesi päevi partneriga, neid unetuid öid ja naera koos. Te ei jõudnud siia lihtsalt! See on meeskonnatöö võit.'),
('138aeaf3-e845-4d03-b6db-2a04410076a7'::uuid,'Тандап жеген адат дагы эле уланып жатабы? 🥦','Эгерде балаңыз айрым тамактардан баш тартса, кабатыр болбоңуз. «Кошумча тамактандыруу» бөлүмүндөгү рецепттерибизден ар түрдүү жана кызыктуу тамактарды жасап көрүңүз.','Valiv söömine jätkub? 🥦','Kui laps keeldub teatud toitudest, ära muretse. Proovi erinevaid ja lõbusaid serveerimisviise meie lisatoidu retseptide jaotisest.'),
('2f302f24-3142-4182-84a0-2782c5ce8394'::uuid,'Сезимдерди сыртка чыгаруу 📝','Күнүңүз чарчаңкы өттүбү? Балаңыз уктагандан кийин, күндүн стрессинен арылуу үчүн сезимдериңизди «Маанай күндөлүгүнө» жазып коюңуз.','Emotsionaalne vabastamine 📝','Kas päev oli kurnav? Pärast lapse uinumist pane oma tunded kirja meeleolupäevikusse, et päeva stressist vabaneda.'),
('8b269aa5-a26e-4c52-b247-14a7194a3d35'::uuid,'Үйдөгү марафон! 🏃‍♂','Жөн эле басуу эми аздык кылат; алар дээрлик чуркоого аракет кылып жатышат! Кичинекей буттарынын татынакай дүкүлдөгөнүнөн ырахат алыңыз, бирок аларды көз жаздымда калтырбаңыз – алар абдан шамдагай!','Maraton toas! 🏃‍♂','Kõndimisest jääb väheks; ta üritab juba joosta! Naudi pisikeste jalgade armsat paterdamist, aga hoia tal silm peal – ta on kiire!'),
('8ee97257-b3d6-4144-ad9a-91e2e54c967a'::uuid,'Сырттагы көңүлдүү оюндар. 🌳','Үйдө энергиясын сарптай албай жатышабы? Таза абада сейилдөө үчүн сыртка чыгыңыз, сейил бакта чарчаганча эркин чуркап ойношсун.','Õuemängud ja lõbu. 🌳','Kas lapsel on toas liiga palju energiat? Minge koos õue värske õhu kätte ja laske tal pargis vabalt joosta, kuni ta on mõnusalt väsinud.'),
('e84402f2-45d4-40ce-ae96-610f12a3e06b'::uuid,'Менин кичинекей жардамчым! 🧹','Чүпүрөк алып чаң сүрткүсү келеби же шыпыргы менен «ойногонго» кызыгабы? Сизди тууроого болгон каалоосу – алардын өнүгүү процессиндеги эң таттуу жана маанилүү учур.','Minu väike abiline tööl! 🧹','Kas ta tahab innukalt lappi haarata ja tolmu pühkida või luuaga „mängida“? Soov sind jäljendada on tema õppimisprotsessi kõige armsam ja olulisem osa.'),
('ed63e2e3-10b5-4bd6-9b06-a81622e913eb'::uuid,'Уйку тартиби бейпилдик берет 🌙','Ар кечинде бирдей аракеттерди жасоо (ванна, жомок, жарыкты өчүрүү) алардын тез уктап кетишине жардам берет.','Unerutiin toob rahu 🌙','Igal õhtul samade tegevuste kordamine (vann, unejutt, tulede hämardamine) aitab lapsel kergemini uinuda.'),
('ae5acd1f-b8cf-43ad-b265-37b9e76b0c35'::uuid,'Сөздөрдү түшүнүү өнөрү 🧠','«Бут кийимди алып кел» десеңиз, аны таап алып келеби? Бул алардын акыл-эси тез өнүгүп жатканын көрсөтөт! Аларды мактап, дем берип туруңуз.','Sõnade mõistmise meistriklass 🧠','Kui palud tal „tuua kinga“, kas ta leiab selle ja toob sulle? See näitab, et tema intelligentsus areneb kiiresti! Kiida ja julgusta teda palju.'),
('ce1fc21a-8f96-4c92-b928-5126f2240b1d'::uuid,'Сизге да энергия керек. 🥗','Күн бою бут үстүндөсүз. Өзүңүз үчүн аш болумдуу жана даамдуу тамак даярдоону унутпаңыз.','Ka sina vajad energiat. 🥗','Oled terve päeva jalgadel. Ära unusta ka endale tervislikku ja maitsvat vahepala valmistada.'),
('d8cf1dda-3655-48e8-9316-6481b7ea82ba'::uuid,'Кыяшалык менен күрөшүү? 🌪','Өзүн түшүндүрө албай калганда, алар капаланып ыйлашы мүмкүн. Эгер бул боюнча колдоо керек болсо, туура мамилени үйрөнүү үчүн Anacan AI менен кеңешиңиз.','Jonnihood kimbutavad? 🌪','Kui laps ei oska end väljendada, võib ta muutuda frustreerituks ja nutma hakata. Kui vajad selles osas tuge, küsi nõu Anacan AI-lt.'),
('2b9c6af1-1706-4704-b2ce-29e57d4866f4'::uuid,'Атасынын кезеги 👨‍🍼','Бүгүн кечинде жомок окуп, баланы уктоочу жайга жаткыруу милдетин атасына тапшырып, өзүңүзгө бир аз эс алыңыз.','Issi kord 👨‍🍼','Anna täna õhtul unejutu lugemine ja lapse voodisse panemine issi hooleks ning võta endale väike puhkepaus.'),
('8db205c2-0561-48d8-8b6c-61fc68065e2a'::uuid,'Мунара куруу өнөрү 🧱','3-4 кубикти тизип, анан кубаныч менен кулатуу – алардын сүйүктүү оюну! Бул оюн кол менен көздүн координациясын тез өнүктүрөт.','Tornide ehitamise kunst 🧱','3-4 klotsi virna ladumine ja nende rõõmuga ümber lükkamine on lemmiktegevus! See mäng arendab kiiresti silma ja käe koostööd.'),
('e513a042-7558-4dae-8bc5-5e2b5e5d74fa'::uuid,'Үйдөн сырткары ыңгайлуулук. ☕','Күндөлүк турмуштан тажадыңызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн коляска менен кирүүгө ыңгайлуу кафе таап, кофе ичип эс алыңыз.','Mugavus kodust eemal. ☕','Tunned igapäevarutiinist tüdimust? Leia meie „Emadele sobivad kohad“ jaotisest vankrisõbralik kohvik ja naudi kohvipausi.'),
('6537418f-2c88-443b-b40f-e07f0ccd5801'::uuid,'Ак ызы-чуунун күчү 🎶','Эгерде активдүү күндөн кийин алар уктабай кыйналып жатышса, бөлмөдө «Ак ызы-чуу» (White Noises) бөлүмүнөн океандын же жамгырдын үнүн коюп, тынчтандыруучу атмосфера түзүңүз.','Valge müra vägi 🎶','Kui neil on pärast aktiivset päeva raske uinuda, loo rahustav õhkkond, mängides toas White Noise''i abil ookeani- või vihmahelisid.'),
('c45968e1-c58f-48dd-a705-2dc4c22325e0'::uuid,'Өсүү секириги. 📏','Кийимдери кайрадан кичирейип калдыбы! Бою менен салмагынын жаңы көрсөткүчтөрүн «Өсүү трекерине» киргизип, алардын ден соолугунун өнүгүү графигин жаңыртыңыз.','Kasvuhüpe. 📏','Riided jäävad jälle väikeseks! Lisa uued pikkuse ja kaalu mõõdud kasvu jälgijasse ja uuenda lapse tervisliku arengu graafikut.'),
('f13027ff-0446-4962-9c51-398d40234b5a'::uuid,'Алгачкы шедеврлер! 🖍','️ Алар калың карандаштар же коюу боёктор менен кагазга чиймелегенди жакшы көрүшөт! Алардын алгачкы шедеврлеринин жаралышын чексиз кубаныч менен байкаңыз.','Esimesed meistriteosed! 🖍','️ Nad armastavad paberile kritseldada jämedate kriitide või paksude värvidega! Jälgi nende esimesi meistriteoseid suure rõõmuga.'),
('3b86e3a2-b53e-4603-a4b1-a57fc531000c'::uuid,'Өз алдынча тамактангысы келет! 🥄','Төгүп-чачып жатышса да, кашыкты өздөрүнө карматтырыңыз. Бул алардын булчуңдарынын координациясы жана өз алдынчалыгы үчүн өтө маанилүү.','Tahab ise süüa! 🥄','Isegi kui nad teevad soterdades segadust, lase neil lusikat ise käes hoida. See on ülioluline nende lihaste koordinatsiooni ja iseseisvuse arenguks.'),
('ce4d24a9-fdbd-44df-93c0-058cf5d834aa'::uuid,'Таттуу кучакташуулар! 🤗','Алардын күтүүсүз кучактап, өпкүлөөгө аракет кылышы – бул сүйүүнүн эң сонун тили. Бул баа жеткис көз ирмемдерди баалаңыз жана аларды ''Ымыркайдын фотосессиясы'' бөлүмүндө түбөлүккө калтырыңыз.','Magusad kaisutused! 🤗','Nende ootamatud kallistused ja suudluskatsetused on kaunis armastuse keel. Hinda neid hindamatuid hetki ja jäädvusta need ''Beebifotosessioonil''.'),
('fd4e2dc2-dbda-49c0-bcfc-b6880fe0e4a7'::uuid,'Китепке болгон сүйүүнү калыптандыруу 📖','Сүрөттүү китептердин барактарын өздөрүнө оодартыңыз. Сиздин үнүңүз менен жомок угуу алардын сөз байлыгын өстүрүүгө жардам берет.','Raamatuarmastuse kasvatamine 📖','Lase neil ise pildiraamatute lehti keerata. Sinu häälega lugude kuulamine aitab nende sõnavara laiendada.'),
('1cb9115d-9cf4-466e-adbe-8fa808d6b45c'::uuid,'Уйку тартибине көз салуу ⏱️','Эгерде күндүзгү уйкусунун тартиби өзгөрсө, алар кечинде эртерээк чарчап калышы мүмкүн. Уйкуга жаткыруу убактысын бир аз эртерээк жылдырып көрүңүз.','Une rütmi jälgimine ⏱️','Kui nende päevase une rütm on muutunud, võivad nad õhtul varem väsida. Võid proovida nende uneaega veidi varasemaks nihutada.'),
('42c60ff7-6aed-4b88-96d2-512be311f08c'::uuid,'Суу ичүүнү унутпаңыз. 💧','Алар активдүү болуп бараткан сайын, суусаганы да артат. Оюндан кийин жана тамактангандан кийин дайыма суу сунуп туруңуз.','Ära unusta juua vett. 💧','Aktiivsemaks muutudes suureneb ka nende janu. Paku neile mängu ajal ja pärast sööki regulaarselt vett.'),
('9a860f2e-97a8-4151-9a68-ed86235ecd75'::uuid,'«Бул эмне?» деген курак ☝','️ Алар баарына манжасы менен көрсөтүп, атын сурашат. Ар бир нерсенин атын чыдамкайлык менен айтып бериңиз; бул алардын айлана-чөйрөнү таанып-билүүсүнүн эң сонун жолу.','„Mis see on?“ etapp ☝','️ Nad näitavad kõigele näpuga ja küsivad sinult, mis see on. Ütle kannatlikult, mis asi on; see on nende imeline viis ümbritsevat maailma avastada.'),
('09bd2033-24ed-4376-ba68-6795f9e6d0fa'::uuid,'Музыкага бийлөө! 🎶','Ритмдүү музыка укса эле термелип, бийлей башташабы? Бул шайыр көз ирмемдерди видеого тартып, ''Ымыркайдын альбомуна'' жүктөп коюңуз!','Muusika saatel tantsimine! 🎶','Kas nad hakkavad rütmilise muusika saatel õõtsuma ja tantsima? Laadi need energilised hetked videotena üles nende ''Beebialbumisse''!'),
('899ab05b-717c-4e03-b941-aadf4ad85007'::uuid,'Өз алдынча ойноо көндүмдөрү. 🧩','Эгерде алар аз убакыт болсо да өз алдынча ойной алса, бул алардын көңүл буруу жөндөмү өсүп жатканын билдирет. Мындай учурларда аларды алыстан сүйүү менен байкап туруңуз.','Iseseisva mängu oskused. 🧩','Kui nad suudavad kasvõi lühikest aega iseseisvalt mängida, näitab see, et nende keskendumisvõime areneb. Jälgi neid nendel hetkedel eemalt armastusega.'),
('98938324-49d8-43fc-bdde-202849487b20'::uuid,'Жайлуу жылуу ванна 🛁','Суу менен ойноо алардын күндүзгү чаңын жана чарчоосун жууп кетүүгө жардам берет, бул көңүлдүү жана уйкуга эң сонун даярдык.','Soe ja rahustav vann 🛁','Veega mängimine aitab päeva tolmu ja väsimuse maha pesta, muutes selle lõbusaks ja valmistades lapse suurepäraselt uneks ette.'),
('67d07afb-a906-4267-ae07-195da32a67d1'::uuid,'Чек араларды текшерүү 🛑','Сиз ''болбойт'' десеңиз да, ошол нерсеге кайра эле умтулуп жатышабы? Бул тентектик эмес, бул алардын чек араны сынап, эрежелерди үйрөнүп жатканы. Сабырдуу жана ырааттуу болуңуз.','Piiride katsetamine 🛑','Kas nad sirutavad käe selle eseme järele ka pärast seda, kui oled öelnud ''ei''? See ei ole jonnakus, vaid piiride katsetamine ja reeglite õppimine. Ole järjepidev ja kannatlik.'),
('71f533be-645b-4990-ac46-86ad77f1a038'::uuid,'Мөмө-жемиш убактысы! 🍎','Күч-кубатын калыбына келтирүү үчүн мезгилдүү жемиштерден турган түстүү жана табит ачаар тарелка даярдаңыз.','Puuviljaaeg! 🍎','Energia taastamiseks valmista neile värviline ja ahvatlev taldrikutäis hooajalisi puuvilju.'),
('cbf7129c-f3df-44ab-928f-9f74910675e9'::uuid,'Өзүңүздү унутпаңыз! 💖','Балаңыз уктагандан кийинки биринчи саат сиздики болсун. Үй жумуштарын токтотуп, жөн гана эс алыңыз жана өзүңүзгө жаккан нерсе менен алектениңиз.','Ära unusta iseennast! 💖','Esimene tund pärast lapse uinumist peaks kuuluma vaid sulle. Ära tee kodutöid; lihtsalt lõõgastu ja tegele millegagi, mida armastad.'),
('6f0da037-da86-424d-bd6d-1e6d3aefe4db'::uuid,'Суроо берүүдөн тартынбаңыз! 🤖','Уйку тартиби боюнча бир нерсени туура эмес кылып жатамбы деп тынчсызданасызбы? Дароо Anacan AI''дан сурап, көңүлүңүздү тынчтандырыңыз.','Küsi julgelt! 🤖','Muretsed, et teed lapse une rutiiniga midagi valesti? Küsi kohe Anacan AI-lt kõike, milles sa kindel pole, ja rahusta oma meelt.'),
('b0d45a27-101a-4c13-b494-715c8c48dda4'::uuid,'Чарчоону четке кагыңыз 🥂','Бүгүн кечинде бөбөгүңүз уктагандан кийин, өнөктөшүңүз менен биргеликте жетишкендиктериңизди белгилегенди унутпаңыз!','Jäta väsimus selja taha 🥂','Pärast seda, kui väike põngerjas on täna õhtul uinunud, ära unusta koos partneriga tähistada oma meeskonna võitu!'),
('8878ea41-701a-4729-9437-858b0e0448ae'::uuid,'Топ ойнойлу! ⚽','Алар эми топту жөн эле тоголотпостон, колдорун көтөрүп сизге ыргытууга аракет кылып жатышат! Бул спорттук аракеттерди дароо видеого тартып, Ымыркайдын альбомуна кошуп коюңуз.','Mängime palli! ⚽','Nad ei veereta enam lihtsalt palli, vaid üritavad seda käed üleval sulle visata! Jäädvusta need sportlikud katsed kohe, lisades need videona beebialbumisse.'),
('d2eace3f-d381-45ba-bfbb-2db61f670769'::uuid,'Үй-бүлөлүк альбомдо кимдер бар? 🖼','️ Сүрөттөрдү карап жатып ''Чоң эне кайда?'' деп сурасаңыз, бөбөгүңүз дароо аны көрсөтөбү? Алардын эс тутуму жана жүздөрдү таануу жөндөмү тез өнүгүп жатат.','Kes on perealbumis? 🖼','️ Kui vaatate pilte ja küsid ''Kus vanaema on?'', kas su väike laps näitab otse tema peale? Nende mälu ja nägude äratundmise oskus areneb kiiresti.'),
('f2055f25-61d4-4680-83b3-954a3f1a9671'::uuid,'Инженердик аракеттер 🧱','Алар эки оюнчук кубикти бири-биринин үстүнө коюуга аракет кылып, бирок кулатып алышууда. Алар кайрадан кылдаттык менен аракет кылышууда. Алардын бул өжөрлүгүн унчукпай байкап, баалаңыз.','Ehituskatsetused 🧱','Nad üritavad kahte klotsi üksteise peale laduda, kuid need kukuvad ümber. Nad proovivad ettevaatlikult uuesti. Jälgi vaikselt ja hinda nende püsivaid pingutusi.'),
('458a103b-d07a-4e59-ac24-1d9dafc323f0'::uuid,'Эне үчүн гана мейкиндик ☕','Үйдө отуруп чарчадыңызбы? ''Энелерге ыңгайлуу жайлар'' бөлүмүнөн эс ала турган жайлуу кафени тандап, өзүңүзгө убакыт бөлүңүз.','Koht ainult emmele ☕','Tunned end kodus olemisest kurnatuna? Vali meie ''Emadele sobivate kohtade'' hulgast hubane kohvik, kus saad lõõgastuda ja endale veidi ''oma aega'' lubada.'),
('d9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e'::uuid,'Чыргоолуктун туу чокусу ☁️','Эч нерсе жакпай, баарына ыйлап жатышабы? Балким, алардын арткы азуу тиштери чыгып жаткандыр! Бул процессти ''Тиш чыгууну көзөмөлдөө'' бөлүмүнө жазып коюңуз.','Jonni tipphetk ☁️','Miski ei tundu neile meeldivat ja nad nutavad kõige pärast? Võib-olla tulevad neil tagumised purihambad! Märgi see protsess ''Hammaste tuleku jälgijasse''.'),
('ed11b132-51fc-4e86-99e0-021b6675020e'::uuid,'Түнкү бешик ыры 🎶','Эненин үнүндөй эч нерсе сооротпойт. Бүгүн кечинде бөбөгүңүздү кучагыңызга бекем кысып, акырын бешик ырын ырдап бериңиз.','Õhtune hällilaul 🎶','Ükski heli pole nii lohutav kui ema hääl. Täna õhtul hoia oma väikest lihtsalt tihedalt vastu rinda ja laula talle vaikselt hällilaulu.'),
('07f52bf7-1174-455b-9c35-8391687a69fe'::uuid,'Өнүгүүсүн текшерүү 🤖','16 айлык кезиндеги өсүү жана өнүгүү этаптары тууралуу маалымат керекпи? Anacan AI''дан педиатр тарабынан жактырылган кыска жана так тизмени сураңыз.','Arengukontroll 🤖','Vajad teavet 16-kuuste kasvuhoogude ja arenguetappide kohta? Küsi Anacan AI-lt lühikest, täpset ja pediaatri heakskiidetud nimekirja.'),
('d94026ce-ef2a-4e93-b559-9f926c9f245d'::uuid,'Тынчтандыруучу үндөр 🎶','Эгерде кичинекейиңиз активдүү изилдөө менен өткөн күндөн кийин тынчтана албай жатса, «Ак ызы-чуу» (White Noise) бөлүмүнөн жамгырдын үнүн коюп, бөлмөдө тынч атмосфера түзүңүз.','Rahustavad helid 🎶','Kui su pisikesel on pärast aktiivset avastamispäeva raske rahuneda, loo toas rahulik õhkkond, mängides valge müra alt vihmahelisid.'),
('523911e7-6ac9-424d-9f11-0729711fb179'::uuid,'Сенсордук оюндар үчүн идеялар. 🌾','Чоң идишке күрүч же макарон салып, ичине оюнчуктарды катып коюңуз. Алар колдору менен издеп таап, сезүү жөндөмүн өстүрүшсүн.','Ideid sensoorseks mänguks. 🌾','Vala suurde kaussi riisi või pastat ja peida mänguasjad nende sisse. Lase neil kätega kompides mänguasju otsida, arendades nii nende puutetundlikkust.'),
('9d72a4f6-eac7-46c3-b9e9-ae6e482ce533'::uuid,'Өз алдынча ойноо убактысы 🧸','Алар эми 10-15 мүнөт өз алдынча оюнчуктары менен ойной алышат! Бул алардын көңүл буруу убактысы узарганын билдирет. Бул тынч көз ирмемдерден ырахат алыңыз.','Iseseisev mänguaeg 🧸','Nad suudavad nüüd 10–15 minutit mänguasjadega ise tegeleda! See on märk sellest, et nende keskendumisvõime pikeneb. Naudi neid vaikseid hetki.'),
('adb7bf26-343c-4ba5-8233-149cdef6b1f2'::uuid,'Музыканын күчү 🎶','Эгерде кечинде себепсиз ыйлап жатышса, жай классикалык музыка коюп көрүңүз. Бул жөнөкөй ыкма көп учурда жакшы жардам берет.','Muusika vägi 🎶','Kui sul on tegemist seletamatute õhtuste jonnihoogudega, proovi neid leevendada õrna klassikalise muusikaga. See lihtne nipp toimib sageli imeliselt.'),
('8bf81bea-dee2-4f82-9f28-f1e6a128a812'::uuid,'Сабыр түгөнгөндө. 📝','Кээде наристеңиздин энергиясы сизди аябай чарчатышы мүмкүн. Маанай күндөлүгүн ачып, бүгүн сизди эмне көбүрөөк алсыратып жатканын эркин жазып калтырыңыз.','Kui kannatus katkeb. 📝','Mõnikord võib lapse energia olla täiesti kurnav. Ava oma ''Meeleolupäevik'' ja kirjuta vabalt üles, mis sind täna kõige rohkem väsitab.'),
('977f5267-192c-40d2-9215-420a5a54d255'::uuid,'Айры колдонууну үйрөнүү. 🍴','Алар тамакты айры менен сайып жегенге аракет кылып жатышат! "Кошумча тамакка өткөн наристелер үчүн рецепттер" бөлүмүнөн колго кармап жегенге ыңгайлуу тамактарды даярдаңыз.','Kahvli kasutamise õppimine. 🍴','Nad üritavad juba kahvliga toitu torgata! Valmista kergesti käsitsetavaid näputoite meie ''Tahke toiduga alustavate beebide retseptide'' hulgast.'),
('c22aaf03-7bb2-467b-9c9d-ca82637af893'::uuid,'Бут кийимин чечүү 👟','Кийинүү күрөшкө айландыбы? Алар эми байпактарын жана бут кийимдерин өздөрү чечип жатышат! Алардын өнүгүп жаткан моторикасына суктаныңыз.','Kingade jalast võtmine 👟','Kas riietumine on muutunud maadlusmatšiks? Nad tõmbavad nüüd ise sokke ja kingi jalast! Imesta nende arenevate motoorsete oskuste üle.'),
('3f154cd8-81d2-425b-aa71-ec2864247772'::uuid,'Меники! 🧸','Колунан бир нерсени алганда нааразы болуп, ыйлап жатышабы? Алардын менчик сезими күчөп жатат! Бул алардын мүнөзүнүн калыптанышынын маанилүү бөлүгү.','Minu oma! 🧸','Kas nad protesteerivad ja nutavad, kui sa neil midagi käest võtad? Nende omanditunne tugevneb! See on oluline osa nende iseloomu arengust.'),
('7a8e2bea-1a47-4839-9ded-36d3fa6fbd27'::uuid,'Киринтүү кезеги атасында. 👨‍🍼','Бул кечте атасы сууга түшүрүү жана уктатуу милдетин өзүнө алып, суу менен кызыктуу оюндарды ойнотсун, ал эми сиз татыктуу эс алыңыз.','Issi kord vannitada. 👨‍🍼','Täna õhtul lase issil vannitamise ja magamamineku rutiin üle võtta, samal ajal kui sina teed väljateenitud pausi.'),
('b60defb6-6a44-41ab-8087-7dec23cd3f5c'::uuid,'Бүгүн эмне тамак жасасак? 🍲','Кошумча тамак менюсу үчүн идеяларыңыз түгөнүп жатабы? Интернеттен издеп убара болбоңуз! "Пайдалуу рецепттер" бөлүмүнөн жаңы даамдуу рецепттерди табыңыз.','Mida täna süüa teha? 🍲','Ideed tahke toidu menüüdeks otsas? Pole vaja internetis ekselda! Avasta maitsvaid uusi retsepte meie ''Tervislike retseptide'' sektsioonist.'),
('5c715c5a-b613-43a0-9f22-5f59af3ae1fc'::uuid,'Чечинүү өнөрү 🧦','Аларды кийинтүү кыйын болушу мүмкүн, бирок чечинүү алар үчүн абдан кызыктуу! Аларга баш кийимин, байпактарын же бут кийимдерин өздөрү чечкенге мүмкүнчүлүк бериңиз.','Riietest vabanemise kunst 🧦','Riietamine võib olla väljakutse, aga riidest lahtisaamine on nende jaoks nii lõbus! Lase neil proovida ise mütsi, sokke või kingi ära võtta.'),
('d3844bde-9596-474d-adfe-9c81a7e0ff26'::uuid,'Чоңдордун буюмдарына кызыгуу. 👜','Сиздин сумкаңызды аңтаруу же атасынын бут кийимин кийип көрүү – алардын эң жакшы көргөн эрмеги! Аларга коопсуз буюмдарыңызды изилдөөгө уруксат бериңиз – бул алардын кызыктуу саякатынын бир бөлүгү.','Uudishimu täiskasvanute asjade vastu. 👜','Koti läbi tuhnimine või issi kingade proovimine on nende lemmiktegevus! Luba neil oma ohutuid esemeid uurida – see on osa nende uudishimulikust teekonnast.'),
('17b19954-1449-474d-a0b9-d199021947cc'::uuid,'Ден соолугу чың апа, ден соолугу чың бала 🥑','Сиздин темир жана кальций деңгээлиңиз төмөндөп кетиши мүмкүн. Өзүңүздү сергек сезүү үчүн "Пайдалуу рецепттер" бөлүмүнөн тез жана күч берүүчү салат жасап жеңиз.','Terve ema, terve laps 🥑','Sinu raua- ja kaltsiumivarud võivad olla ammendunud. Valmista kiire ja taastav salat meie ''Tervislike retseptide'' sektsioonist, et tunda end energilisena.'),
('68c3e726-41d6-481a-91d7-a89fa5795172'::uuid,'Чиймелөө өнөрү! 🖍️','Карандаш берсеңиз, кагазга чиймелегенге аракет кылып жатышабы? Бул алардын майда моторикасы үчүн эң сонун көнүгүү. Болгону карандаштар алар үчүн коопсуз экенин текшериңиз.','Sodimise kunst! 🖍️','Kas nad üritavad paberile kritseldada, kui annad neile kriidi? See on suurepärane harjutus nende peenmotoorikale. Veendu vaid, et kriidid oleksid neile ohutud.'),
('ab2f1bd1-caf0-41b5-b8ae-89ec60663539'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкүсүн ойгонууну жалгыз өзүңүз мойнуңузга албаңыз. Жолдошуңузду да ойготуңуз; бир команда болуу – бул жоопкерчиликти бөлүшүү дегенди билдирет.','Issi öövahetus 👨‍🍼','Ära kanna öiste ärkamiste koormat üksi. Ärata ka oma partner; meeskonnana tegutsemine tähendab vastutuse jagamist.'),
('24b47242-9a10-48f7-a928-0a19449b984a'::uuid,'Жарыкты басаңдатыңыз 🌙','Уктаарга бир саат калганда үйдөгү бардык жарыктарды жана экрандарды өчүрүңүз. Мелатонин тынч чөйрөдө гана бөлүнүп чыгат.','Hämarda tuled 🌙','Lülita tund enne magamaminekut majas välja kõik eredad tuled ja ekraanid. Melatoniin vabaneb ainult rahulikus keskkonnas.'),
('2d66c314-cb67-48c8-93d1-be3249bad125'::uuid,'Жаратылыштан кенч издөө. 🍂','Паркта сейилдеп жүргөндө ар кандай жалбырактарды же тобурчактарды чогултуңуз. "Энелерге ыңгайлуу жерлер" бөлүмүнөн өзгөчө жаратылышы бар жаңы парктарды табыңыз.','Looduse otsimismäng. 🍂','Pargis jalutades korja erinevaid lehti või käbisid. Avasta uusi unikaalsete loodusmaastikega parke meie ''Emadele sobivate kohtade'' sektsioonist.'),
('98db8b9f-36cd-4968-86c5-ed66999457de'::uuid,'Жаныбарлардын үнүн тууроо! 🐶','Алар мышыкты көргөндө "мяу", же итти көргөндө "ав-ав" дегенге аракет кылып жатышабы? Алардын сөз байлыгы көбүнчө жаныбарлардын үндөрүнөн башталат. Алар менен бул кызыктуу оюнду ойноңуз!','Loomahäälte tegemine! 🐶','Kas nad üritavad öelda ''mjäu'', kui näevad kassi, või ''auh-auh'', kui näevad koera? Nende sõnavara algab sageli loomahelidega. Mängi nendega seda lõbusat mängu!'),
('8e91be33-56a9-43aa-bf49-8aa525510abf'::uuid,'Жаратылыштан кенч издөө. 🍂','Паркта сейилдеп жүргөндө ар кандай жалбырактарды же тобурчактарды чогултуңуз. "Энелерге ыңгайлуу жерлер" бөлүмүнөн өзгөчө жаратылышы бар жаңы парктарды табыңыз.','Looduse otsimismäng. 🍂','Pargis jalutades korja erinevaid lehti või käbisid. Avasta uusi unikaalsete loodusmaastikega parke meie ''Emadele sobivate kohtade'' sektsioonist.'),
('e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8'::uuid,'Толтуруу жана бошотуу баскычы! 📦','Оюнчуктарды чоң кутуга чогултуп, анан баарын бир заматта төгүп салуу! Бул себеп-натыйжа оюну алардын логикасын өнүктүрүүгө жардам берет.','„Täitmise ja tühjendamise“ faas! 📦','Mänguasjade suurde kasti kogumine ja siis korraga välja kallamine! See põhjus-tagajärg mäng aitab neil arendada loogilist mõtlemist.'),
('1ba81e06-af3c-43ed-b2c1-9d0d1b231a26'::uuid,'Сүйлөшүп алуу керек 💬','"Мен эч качан мурункудай болбойм" деген ойдон кыйналып жатасызбы? Бул убактылуу сезимди Anacan коомчулугундагы башка энелер менен бөлүшүңүз – сиз жалгыз эмессиз.','Vaja on rääkida 💬','Tunned end ülekoormatuna mõttest ''ma ei saa enam kunagi endiseks''? Jaga seda ajutist tunnet teiste emadega Anacani kogukonnas – sa pole üksi.'),
('5d958416-87e8-44f2-8b6e-cde98e63822d'::uuid,'Бүгүнкү сыйкырдуу жомоктор 🪄','Кызыктуу жомоктордогу эр жүрөк жана сүйкүмдүү жаныбарлар жөнүндө окуя ойлоп табыңыз жана бөлмөнү сыйкырдуу дүйнөгө айландырыңыз.','Tänased võlujutud 🪄','Loo kaasahaaravates muinasjuttudes lugu vapratest ja armsatest loomadest ning muuda tuba maagiliseks paigaks.'),
('679e2936-6a93-4a92-9069-b372c4d3f661'::uuid,'Уктаар алдындагы жомоктордун сыйкыры. 📖','Алар эми китептеги сүрөттөрдү сизге көрсөтүп жатышат. Уктаар алдында чогуу кыскача жомок окуу ортоңуздардагы байланышты укмуштуудай бекемдейт.','Une-eelse jutu võlu. 📖','Nad näitavad nüüd sulle raamatutes piltidele. Lühikese loo koos lugemine enne und võib teie sidet uskumatult tugevdada.'),
('fbb768fe-d41f-4451-8978-b683840f7855'::uuid,'Толтуруу жана бошотуу кубанычы! 📦','Бардык оюнчуктарды чоң кутуга чогултуп, анан баарын кубануу менен жерге төгүп салуу! Бул себеп-натыйжа оюну алардын логикасын өнүктүрүүнүн эң сонун жолу.','Täitmise ja tühjendamise rõõm! 📦','Kõigi mänguasjade suurde kasti kogumine ja siis rõõmsalt põrandale kallamine! See põhjus-tagajärg mäng on fantastiline viis nende loogika arendamiseks.'),
('cd9fb3be-79a5-4ecd-980a-171e6fa00ed4'::uuid,'Ага тандоо мүмкүнчүлүгүн бериңиз. 👕','"Кызыл көйнөгүңдү киесиңби же көк көйнөгүңдүбү?" – Ушундай кичинекей тандоолорду сунуштоо алардын өжөрлүгүн азайтып, өзүн-өзү баалоо сезимин жогорулатат.','Anna talle valikuvõimalus. 👕','''Kas paneme selga punase või sinise särgi?'' – Selliste väikeste valikute pakkumine võib vähendada jonnakust ja tõsta nende eneseteadvust.'),
('d25d87b5-6fc8-47d3-a3b2-ce74b55cbbfe'::uuid,'Татаалдаштырылган жашынмак! 🙈','Оюнчугун эки башка жууркандын астына жашырып койсоңуз да, алар аны оңой эле таап жатышабы? Алардын буюмдардын туруктуулугун түшүнүүсү толук калыптанды!','Edasijõudnute peitusemäng! 🙈','Kas nad leiavad oma mänguasja hõlpsasti üles ka siis, kui peidad selle kahe erineva teki alla? Nende arusaam esemete püsivusest on täielikult välja kujunenud!'),
('373a30b7-4c10-4d16-b029-a2c123ab28b9'::uuid,'Чуркоо башталсын! 🏃‍♂️','️ Ал тез кадамдар эми кичинекей чуркоолорго айланып баратат! Алардын тизелерин коргоо кыйыныраак болушу мүмкүн, бирок алардын кубанычын жана эркиндигин көрүү буга татыктуу!','Las jooks algab! 🏃‍♂️','️ Need kiired sammud muutuvad nüüd väikesteks jooksudeks! Kuigi põlvede kaitsmine võib muutuda väljakutseks, on nende rõõmu ja vabaduse jälgimine seda väärt!'),
('5a23341a-91f5-4bdf-a760-e7b99f610283'::uuid,'Жаңы текстураларды таанып-билүү. 🥦','Тамактарынын түстөрүн жана формаларын өзгөртүү менен алардын табитин ачыңыз. "Кошумча тамакка өткөн наристелер үчүн рецепттер" бөлүмүнөн илхам жана идеяларды табыңыз.','Uute tekstuuride avastamine. 🥦','Tõsta nende söögiisu, varieerides toitude värve ja kujusid. Leia inspiratsiooni ja ideid meie ''Tahke toiduga alustavate beebide retseptide'' sektsioonist.'),
('6581c209-98c5-4f79-adf1-c7b985567899'::uuid,'Сиз чыныгы баатырсыз. 🛁','Күнү бою тынымсыз наристеңиздин артынан чуркадыңыз. Эми өзүңүзгө бир чыны жылуу чай куюп, ойлоруңузду эркин коё берип, жөн гана эс алыңыз.','Oled tõeline kangelane. 🛁','Oled terve päeva tegusa pisipõnni järel jooksnud. Nüüd vala endale tass sooja teed ja lihtsalt lõõgastu, lastes mõtetel rändama minna.'),
('1705b7a5-fb30-4cc3-974a-91a4210ec2a2'::uuid,'Өзүңүзгө гана арналган убакыт. 🛁','Алар уктап жатышат, үй тыптынч. Эми телефонуңузду четке коюп, сүйүктүү тасмаңызды коюп, тынчтыктан ырахат алыңыз.','Aeg ainult sulle. 🛁','Nad magavad, majas on vaikne. Nüüd pane telefon ära, pane käima lemmikfilm ja lihtsalt naudi rahu ja vaikust.'),
('60fa7d8e-7d2e-4789-b844-5bdd9d35a5eb'::uuid,'Артка жана капталга жылуу! 🦀','Алар азыр тең салмактуулугун текшерип, алдыга гана эмес, артка же капталга да кадам таштап жатышат. Бул кызыктуу көз ирмемдерди сүрөткө тартып алууну унутпаңыз!','Liikumine tagurpidi ja küljele! 🦀','Nad katsetavad nüüd oma tasakaalu, astudes samme mitte ainult ettepoole, vaid ka tagurpidi või küljele. Jäädvusta need lõbusad hetked kindlasti fotole!'),
('f05a8717-d544-48fb-a529-17361118fee2'::uuid,'Боюнун тез өсүшү! 📏','Наристеңиздин өсүү мезгили келгенин сезип жатасызбы? Анын акыркы өлчөмдөрүн Салмакка көз салуу бөлүмүнө киргизип, өсүү графигиндеги ийгиликтерине көз салыңыз!','Kasvuhüpe! 📏','Kas tunned, et su väikesel on käsil kasvuspurt? Sisesta tema uusimad mõõdud kaalu jälgijasse ja vaata, kuidas ta kasvugraafikul mühinal edeneb!'),
('75798a4e-e59c-4911-827e-b1622b37ae33'::uuid,'Чачты жана тишти тазалоо! 🪥','Ал чачын тарап же щетканы оозуна алып барып, сизди туурап жатабы? Бул оюн аркылуу өзүнө кам көрүү көндүмдөрүн калыптандыруу үчүн эң сонун учур.','Juuste ja hammaste pesemine! 🪥','Kas ta imiteerib sind, kammides oma juukseid või viies harja suhu? See on ideaalne aeg mängu kaudu enesehooldusharjumusi kujundada.'),
('784b1d1b-2c53-42bf-a43b-d6b6e3121aba'::uuid,'Үй-бүлөлүк кечки тамак убактысы. 🍲','Бүгүн кечинде тамак жасагыңыз келбей жатабы? Биздин тиркемедеги картаны колдонуп, балдар менюсу бар жана наристеңиз үчүн атайын отургучтары бар ресторандарды табыңыз.','Pere õhtusöögi aeg. 🍲','Ei taha täna kodus süüa teha? Kasuta meie äpi kaarti, et leida restorane, kus on lastele mõeldud menüüd ja söögitoolid.'),
('b328273f-0602-46a6-a82b-54d47ec1b77d'::uuid,'Терең дем алыңыз. ✨','Ар бир күн пландалгандай боло бербейт, кээде үй ичи бир аз башаламан болушу мүмкүн. Сиз идеалдуу болууга милдеттүү эмессиз; алар үчүн сиз эң мыктысыз.','Hinga sügavalt sisse. ✨','Kõik päevad ei lähe plaanipäraselt ja vahel võib kodus veidi segamini olla. Sa ei pea olema täiuslik; tema jaoks oled sa parim.'),
('755229fb-26a0-4a27-af2c-49bb6a367386'::uuid,'Тынчтандыруучу көнүмүш адат. 🌙','Уктаар алдында бөлмөдөгү жарыкты азайтып, акырын сүйлөө анын кыймыл-аракетин жайлатып, уйкуга даярданууга жардам берет.','Rahustav rutiin. 🌙','Enne magamaminekut aitab tulede hämardamine ja vaikse häälega rääkimine tal tempot maha võtta ja uneks valmistuda.'),
('ae949749-3a87-49dc-a4ae-057b9e3594b1'::uuid,'Чиймелерден максаттуу сызыктарга чейин! 🖍','️ Карандашты кармаганда, ал жөн гана чекит койбостон, узун сызыктарды тартууга аракет кылып жатат. Бул кичинекей шедеврди сүрөткө тартып, дароо Баланын альбомуна кошуп коюңуз!','Sodimisest sihipäraste joonteni! 🖍','️ Kui ta hoiab käes värvipliiatsit, püüab ta joonistada pikki jooni, mitte ainult täppe. Tee sellest väikesest meistriteosest foto ja lisa see kohe beebialbumisse!'),
('f1cd31cb-c9bf-40c8-b2e0-ab0c8e5c21b9'::uuid,'Жаратылыштан кенч издөө. 🍂','Короодо же сейил бакта жалбырактарды же майда таштарды чогултуп, аларды изилдөө анын сезүү органдарынын өнүгүүсү үчүн сонун көнүгүү.','Looduse otsimismäng. 🍂','Lehtede või väikeste kivide kogumine ja uurimine õues või pargis on suurepärane tegevus tema sensoorseks arenguks.'),
('1b65f6b1-f423-43f5-bc48-5ffb574c7c74'::uuid,'Суу менен ойноо аркылуу эс алуу. 🛁','Жылуу ваннада сууга ыргыткан оюнчуктары менен ойноо абдан кызыктуу гана эмес, ошондой эле күндүн чарчоосун басуунун эң сонун жолу.','Lõõgastus veemängude abil. 🛁','Soojas vannis vette visatud mänguasjadega mängimine pole mitte ainult lõbus, vaid ka suurepärane viis päevastressi maandamiseks.'),
('bc0b7dcc-fdc0-4664-bff5-56183ea22258'::uuid,'Эки баскычтуу буйруктарды түшүнүү! 🧠','Сиз: «Бут кийимиңди ал да, мага бер» дегенде, ал эки аракетти тең ырааттуу аткарабы? Бул анын интеллектинин укмуштуудай өсүп жатканынын белгиси!','Kaheastmeliste käskluste mõistmine! 🧠','Kas ta teeb mõlemad tegevused järjest, kui ütled: „Võta oma king ja anna see mulle“? See on märk tema intelligentsuse suurest hüppest!'),
('c18b2eee-ba78-43cc-89fd-423a464819d2'::uuid,'Апанын энергиясы маанилүү. 🥗','Дайыма чуркап жүрүп чарчадыңызбы? Биздин «Аялдар үчүн пайдалуу тамактар» бөлүмүнөн өзүңүз үчүн даамдуу жана аш болумдуу тамак даярдап алыңыз.','Emme energia on oluline. 🥗','Tunned end pidevast ringijooksmisest väsinuna? Valmista endale midagi maitsvat ja toitvat meie naiste tervislike retseptide jaotisest.'),
('cd0e822c-b843-41fa-9a3e-f4b682a848ae'::uuid,'Өз алдынча кашык менен тамактануу. 🥄','Ал кашыкты оозуна алып барганда азыраак төгүп жатат! Бул өнүгүп жаткан майда моториканы колдоп, анын өз алдынчалыгын өстүрүүгө дем бериңиз.','Iseseisev lusikaga söömine. 🥄','Ta ajab lusikat suhu viies vähem toitu maha! Kiida seda arenevat peenmotoorikat ja julgusta tema kasvavat iseseisvust.'),
('d6374c1a-94a0-4de3-855d-6a8d4e9a29af'::uuid,'Оюнчуктар менен боор ооруу. 🧸','Ал оюнчук аюусун сылап, тамактандырып же жаткырып жатабы? Бул таттуу ролдук оюндар анын эмоционалдык интеллекти канчалык сонун өнүгүп жатканын көрсөтөт.','Empaatia mänguasjade vastu. 🧸','Kas ta silitab oma kaisukaru, toidab seda või sätib magama? Need armsad rollimängud näitavad, kui kaunilt areneb tema emotsionaalne intelligentsus.'),
('299405ea-50dc-48c1-ba2a-233941bf627c'::uuid,'Атанын жомок айтып берүү убактысы. 👨‍🍼','Бүгүн кечинде жомок окуп берүүнү жана баланы уктоочу жайга жаткырууну атасына тапшырып, өзүңүзгө бир аз эс алуу тартуулаңыз.','Issi jutuvestmise aeg. 👨‍🍼','Lase täna õhtul issil õhtujutt lugeda ja laps magama panna, ning võta endale väike puhkepaus.'),
('7ad6ef35-e677-498c-8bc2-cc3e84535415'::uuid,'Коопсуздукту текшерүү убактысы! 🛡️','Шкафтарды жана тартмаларды ачуу анын сүйүктүү машыгуусуна айланды! Балдардын коопсуздугу үчүн зарыл болгон кулпуларды биздин «Сунушталган товарлар» тизмесинен текшерип көрүңүз.','Aeg ohutuskontrolliks! 🛡️','Kappide ja sahtlite avamisest on saanud tema lemmiktegevus! Vaata kindlasti meie soovitatud toodete nimekirja, et leida vajalikud lapsekindlad lukud.'),
('ec2361c8-31f7-458e-ad6e-506355b447a5'::uuid,'Жаңы бийиктиктерди багындыруу! 🧗‍♂️','️ Ал азыр бийик жерлерге жетип, эмеректерге оңой эле чыга алат. Үйүңүздөгү коопсуздук чараларын дагы бир жолу карап чыгууга убакыт келди.','Uute kõrguste vallutamine! 🧗‍♂️','️ Ta ulatub nüüd kõrgemale ja ronib kergemini mööblile. On aeg oma kodune ohutus taas üle vaadata.'),
('21888245-7cf1-48e4-a08b-53389aa39131'::uuid,'Суу ичүүнү кызыктуу кылыңыз! 💧','Активдүү чуркоо жана ойноо аны суусатышы мүмкүн. Түстүү чөйчөгү менен бат-баттан суу сунуп, суу балансын сактап туруңуз.','Muuda veejoomine lõbusaks! 💧','Aktiivne jooksmine ja mängimine võib teha ta januseks. Hoia teda hüdreerituna, pakkudes sageli vett värvilisest nokaga tassist.'),
('4595ac68-2033-4a66-a4d9-1146030382ed'::uuid,'Күнүмдүк отчет. ✨','Сиз ар күнү идеалдуу болууга милдеттүү эмессиз. Эгер бүгүн баарын бүтүрө албай калсаңыз, бул эч нерсе эмес. Сиз наристеңиз үчүн эң мыктысыз.','Päeva kokkuvõte. ✨','Sa ei pea olema iga päev täiuslik. Kui sa ei jõudnud täna kõike tehtud, on see täiesti okei. Sa oled oma lapse jaoks parim.'),
('9a00f6ae-31b9-432b-a4a4-3a97caf3bc85'::uuid,'Ритм сезими күчөдү! 🎶','Ал сүйүктүү ырынын алгачкы секунддары угулары менен кыймылдап, жылмайып баштайбы? Бул энергиялуу көз ирмемдерди баланын фотосессиясы менен тартып алып, үй-бүлөлүк тобуңузга жөнөтүңүз!','Rütmitaju tugevneb! 🎶','Kas ta hakkab liikuma ja naeratama kohe, kui kuuleb oma lemmiklaulu esimesi sekundeid? Jäädvusta need energilised hetked beebifotodega ja saada need oma peregrupile!'),
('33b8d80d-5434-483c-b198-c7b20c73321d'::uuid,'Дене мүчөлөрүн кененирээк таануу. 👂','«Ичиң кайда?» же «Кулагың кайда?» сыяктуу жаңы суроолорго туура жооп берүү жөндөмү анын канчалык тез үйрөнүп жатканын көрсөтөт.','Kehaosade täpsem tundmine. 👂','Tema võime õigesti vastata uutele küsimustele, nagu „Kus on su kõht?“ või „Kus on su kõrvad?“, näitab, kui kiiresti ta õpib.'),
('87029bf7-0808-4eac-a180-0abfa62f0b48'::uuid,'Бирге китеп окуу. 📖','Китептин барактарын жөн эле оодарбастан, наристеңиз азыр китептеги жаныбарларды же буюмдарды көрсөтүп, алардын аттарын сизден чыдамсыздык менен күтөт.','Lugege koos raamatut. 📖','Lisaks lehekülgede keeramisele näitab su väike nüüd raamatutes loomadele või esemetele, oodates põnevusega, et sa neile nimed annaksid.'),
('cc468aff-f9d2-4961-b955-bf2eaa13f7ef'::uuid,'Өсүү жолу кандай бара жатат? 📏','Кийимдери кайрадан кыскарып калдыбы? Анын жаңы өлчөмдөрүн «Өсүүгө көз салуу» бөлүмүнө киргизип, өнүгүү графигинин өсүшүнө көз салыңыз!','Kuidas kasvamine edeneb? 📏','Kas ta riided jäävad jälle lühikeseks? Sisesta uued mõõdud kasvu jälgijasse ja vaata, kuidas arengugraafik tõuseb!'),
('308b629a-7190-416d-8240-7f61a2fe4d68'::uuid,'Кежирлик: Сөздөр жетпей калганда. 🌪','Наристеңиз каалаган нерсесин ала албай калганда же өзүн түшүндүрө албай жатканда капаланып, ыйлашы — кадыресе көрүнүш. Анын деңгээлине чейин ийилип, сезимдерин түшүнөрүңүздү билдирип коюңуз.','Jonn: kui sõnadest ei piisa. 🌪','On normaalne, et su väike muutub frustreerituks ja nutab, kui ta ei saa seda, mida tahab, või ei suuda end väljendada. Mine tema tasemele ja anna talle teada, et mõistad tema tundeid.'),
('78541e65-2128-40ff-8cb4-1e0d54454519'::uuid,'Сезимдериңизди билдириңиз. 📝','Чарчаңкы күн болдубу? Балаңыз уктагандан кийин, сезимдериңизди «Маанай күндөлүгүнө» жазып, күндүн стрессинен арылыңыз.','Väljenda oma tundeid. 📝','Oli kurnav päev? Pärast lapse uinumist vabane päevastressist, kirjutades oma tunded üles meeleolupäevikusse.'),
('7ea95622-1f8d-4996-8638-aeeafe28a802'::uuid,'Жаңы жерлерди изилдеңиз! ☕','Күнүмдүк тиричиликтен чарчадыңызбы? Наристеңиз менен чогуу эс ала турган, балдар менюсу бар кафелерди биздин "Энелерге ыңгайлуу жайлар" бөлүмүнөн табыңыз.','Avasta uusi kohti! ☕','Tunned väsimust igapäevarutiinist? Leia meie emadele sõbralike kohtade jaotisest lastesõbralikke kohvikuid, kus saad koos lapsega lõõgastuda.'),
('58ff14f8-978e-4eec-8b86-a777de1b33ba'::uuid,'Жыйноону кызыктуу кылыңыз! 🧺','Наристеңиз оюнчуктарды кутудан төккөндү жакшы көрөт, эми алардын айрымдарын кайра салганды да үйрөнүп жатат! Чогуу оюнчук жыйноо ырын ырдап, бул жараянды кызыктуу оюнга айлантыңыз.','Muuda koristamine lõbusaks! 🧺','Sinu lapsele meeldib mänguasju kastist välja kallata ja nüüd õpib ta ka mõnda tagasi panema! Muuda koristamine lõbusaks mänguks, lauldes koos koristuslaulu.'),
('b54bf6d9-a27d-4cd5-bc2b-21d160aa5b81'::uuid,'Уйку режими өзгөрүп жатабы? ⏱️','Эгерде күндүзгү уйку толугу менен калыптанса, түнкү уйкуга өтүү бир аз өзгөрүшү мүмкүн. Жаңы тартипке көнүү үчүн бүгүнкү графикти Anacan уйку таймери менен көзөмөлдөңүз.','Kas une rütm on muutumas? ⏱️','Kui päevased uinakud on täielikult paigas, võib üleminek ööunele veidi muutuda. Jälgi tänast ajakava Anacani unetaimeriga, et uue rutiiniga kohaneda.'),
('e71126af-730c-4cca-8daa-1682609e21a1'::uuid,'Формаларды сорттоо (Пазлдар). 🧩','Ал тегеректи тегерек көзөнөккө, ал эми чарчыны чарчы көзөнөккө салууга аракет кылып жатат. Формаларды сорттоочу мындай оюндар анын сабырдуулугун жана көңүл буруусун арттырат.','Kujundite sorteerimine (pusled). 🧩','Ta proovib sobitada ringi ringikujulisse avasse ja ruutu ruudukujulisse. Need kujundite sorteerimise mängud arendavad tema kannatlikkust ja tähelepanuvõimet.'),
('069cc383-0002-41b5-ba19-4172c6d6b10f'::uuid,'Уктоо кыйындап баратабы? 😴','Активдүү изилдөө кээде балаңызды ашыкча толкундандырышы мүмкүн. Уйку таймерин коюп, бөлмөнүн жарыгын азайтып, уктаар алдында жомок окуп бериңиз.','Kas uinumine on muutunud raskemaks? 😴','Aktiivne avastamine võib last vahel erutada. Pane unetaimer, hämarda toas tuled ja loe enne und üks unejutt.'),
('1beeca23-44cf-48f8-9b07-fc08412e7809'::uuid,'Адептүүлүк маанилүү: Суранам жана Рахмат. 🙏','Бир нерсе берип же алып жатканда, наристеңиз эми башын ийкеп же өзүнүн өзгөчө ыкмасы менен ыраазычылыгын билдирет. Бул коомдук адеп-ахлакты үйрөтүүнү баштоо үчүн эң сонун убакыт!','Kombed loevad: palun ja aitäh. 🙏','Midagi andes või vastu võttes noogutab su väike nüüd või väljendab tänu omal erilisel moel. See on ideaalne aeg hakata õpetama sotsiaalseid kombeid!'),
('eb807359-495c-4338-a628-e4dd3e405226'::uuid,'Бойдун жана салмактын өсүшүн көзөмөлдөө. 📏','Кийимдери кайрадан кичирейип калдыбы? Анын жаңы өлчөмдөрүн "Өсүү трекери" бөлүмүндө жаңыртып, 500-күнгө чейинки өнүгүүсүн белгилеңиз.','Pikkuse ja kaalu jälgimine. 📏','Kas ta riided jäävad jälle väikeseks? Uuenda tema uued mõõdud kasvu jälgijasse ja kaardista tema areng kuni 500. päevani.'),
('158d01ac-e4e7-4be6-959c-37e93007ee0b'::uuid,'Китептердеги жаныбар досторду таануу. 🐶','"Ит кайда?" деп сураганыңызда наристеңиз сөөмөйү менен көрсөтөбү? Анын сөз байлыгын арттыруу үчүн китептериндеги нерселердин түстөрүн да атай баштаңыз.','Loomasõprade tundmine raamatutes. 🐶','Kas su väike näitab näpuga, kui küsid „Kus on koer?“ Sõnavara rikastamiseks hakka nimetama ka raamatutes olevate esemete värve.'),
('9e266e10-1251-4668-af5f-a58fe3b3f537'::uuid,'Коопсуздукту текшерүү! 🛡️','Эми ал бийигирээк жерлерге жете алат! Дасторкондорду жана учтуу бурчтарды кайра текшерип чыгыңыз. Керек болсо, балдардын коопсуздугун камсыздоо чечимдери үчүн биздин "Сунушталган өнүмдөр" бөлүмүн карап чыгыңыз.','Ohutuskontroll! 🛡️','Ta ulatub nüüd kõrgemale! Kontrolli üle laudlinad ja teravad nurgad. Vajadusel vaata meie soovitatud tooteid lapsekindlate lahenduste leidmiseks.'),
('ca40c713-93a7-4e51-9b1b-8465a3151e1f'::uuid,'Атанын оюн убактысы. 👨‍🍼','Кечтин энергиялуу бөлүгүн атасына тапшырыңыз. Алардын күлкүгө толгон оюндары ортодогу байланышты бекемдеп, сизге эс алууга мүмкүнчүлүк берет.','Issi mängutund. 👨‍🍼','Lase issil tegeleda õhtuse energilisema osaga. Nende naeru täis mängud tugevdavad sidet ja annavad sulle võimaluse puhata.'),
('17791a06-d7d3-466d-acee-c2689fa82589'::uuid,'Сенсордук оюн. 🌾','Чоң идишке күрүч же кум салып, ичине оюнчуктарды жашырыңыз. Аларды колдору менен издөө майда моториканы өнүктүрүү үчүн баа жеткис ыкма.','Sensoorne mäng. 🌾','Vala suurde kaussi riisi või liiva ja peida mänguasjad sisse. Nende kätega otsimine on hindamatu väärtusega peenmotoorika arendamiseks.'),
('85ff80d1-72d4-4dd2-9fa5-45e283e54bc3'::uuid,'Өз кийимин өзү тандоо. 👕','Көк көйнөктү кийгиң келеби же жашылдыбы? Эки тандоо сунуштоо анын өз алдынчалыгын арттырып, өжөрлүгүн азайтууга жардам берет.','Oma riiete valimine. 👕','Kas soovid kanda sinist või rohelist särki? Kahe valiku pakkumine suurendab tema enesetunnetust ja võib aidata vähendada jonnakust.'),
('e6632c98-233d-431d-adc3-c5f78c1c7a37'::uuid,'Суу менен ойноп эс алыңыз. 🛁','Жылуу ванна жана суунун чачыраган үнү күндүн бардык чарчоосун жууп кетет. Көлөм түшүнүгүн үйрөтүү үчүн сууга ар кандай өлчөмдөгү идиштерди салыңыз.','Lõõgastu veemängudega. 🛁','Soe vann ja sulistamise heli pesevad maha kogu päeva väsimuse. Pane vette erineva suurusega anumaid, et õpetada mahu mõistet.'),
('148de716-5fb6-4776-96cc-81e2d00b53b8'::uuid,'Сезимдериңиз менен бөлүшүңүз. ✨','Кээде жумуштун баары үйүлүп калышы мүмкүн. Күндүн аягында жан дүйнөңүздүн тынчтыгын табуу үчүн сүйүктүү хоббиңиз менен алектениңиз.','Jaga oma tundeid. ✨','Vahel võib kõike liiga palju saada. Päeva lõpus tegele oma lemmikhobiga, et leida sisemine rahu.'),
('b3ddea65-cbd9-4fdd-900d-8914e021db1f'::uuid,'Топ менен бутага тийгизүү! ⚽','Ал эми топту тоголотуп эле тим болбостон, аны белгилүү бир багытка ыргытууга аракет кылып жатат! Бул кол-көз координациясынын өнүгүп жатканынын ачык белгиси.','Palli sihtmärki viskamine! ⚽','Ta ei veereta enam ainult palli; ta proovib seda kindlas suunas visata! See on selge märk arenevast käe-silma koordinatsioonist.'),
('cbf9b73e-6e0b-4cbc-8731-ad9674e6dca3'::uuid,'Суу ичүүнү кызыктуу кылыңыз! 💧 А','Активдүү балдар тез суусайт. Суу балансын сактоо үчүн ага түстүү жана кызыктуу суу ичүүчү чөйчөк менен үзгүлтүксүз суу берип туруңуз.','Muuda veejoomine lõbusaks! 💧 A','Aktiivsed lapsed muutuvad kiiresti januseks. Paku talle regulaarselt vett värvilisest ja põnevast nokaga tassist, et ta oleks hästi hüdreeritud.'),
('2f67b26a-192a-4bd5-87f9-5f376ff164e3'::uuid,'Эки баскычтуу буйруктар. 🧠','"Оюнчукту алып, кутуга сал." Анын мындай көп баскычтуу буйруктарды аткара алуусу кабыл алуу жөндөмүнүн өнүккөнүн көрсөтөт.','Kaheastmelised käsklused. 🧠','„Võta mänguasi ja pane see kasti.“ Tema võime järgida neid mitmeetapilisi käsklusi näitab arenenud mõistmist.'),
('bf0e882a-2f6d-4439-b170-c9adaeed59cd'::uuid,'Өз ыргагында бийлөө. 🎶','Наристеңиз эми жөн эле термелип тим болбойт; ал музыканын ыргагына жараша кол чаап же тегеренип бийлеп жатат!','Tantsimine oma rütmis. 🎶','Sinu väike ei kõigu enam ainult, vaid plaksutab või keerleb muusikarütmis!'),
('c522fcf6-60fc-463a-b943-7933f5ac5c70'::uuid,'Уктаар алдындагы жомоктор сыйкырдуу. 📖','Балаңызга сүрөттөрдү карап, окуяны өз сөзү менен айтып берүүсүнө мүмкүнчүлүк бериңиз. Бул келечектеги китеп окуу адатына негиз салат.','Une-eelsed jutud on võluvad. 📖','Lase lapsel pilte vaadates lugu oma sõnadega jutustada. See loob vundamendi tulevastele lugemisharjumustele.'),
('19e05272-ac3b-430f-bbad-b5c770118fd3'::uuid,'Туулган күн майрамы! 🎈','Бул күндү кичинекей торт же анын сүйүктүү жемиши менен белгилеңиз. Анын канчалык тез чоңоюп жатканын көрүү — сиздин эң чоң сыйлыгыңыз.','Sünnipäeva tähistamine! 🎈','Tähista seda päeva väikese koogi või tema lemmikpuuviljaga. Näha, kui kiiresti ta kasvab, on sinu suurim tasu.'),
('52e84dda-8f2e-4dce-9b8e-b095190c1816'::uuid,'Өзүңүзгө ишениңиз. ✨','500 күндүк мээримиңиз, сүйүүңүз жана сабырдуулугуңуз үчүн өзүңүзгө ыраазычылык билдириңиз. Эми жакшылап уктап эс алыңыз; эртең жаңы барак ачылат!','Ole enda üle uhke. ✨','Tänan ennast 500 päeva pühendumise, armastuse ja kannatlikkuse eest. Nüüd maga hästi; homme algab uus peatükk!'),
('dcf8f474-5360-4c6f-ac54-ecde70444961'::uuid,'Ылдамдык кошуу! 🏃‍♂️','Наристеңиз эми басып эле тим болбостон – ал дээрлик чуркап калды! Ага жетишүү барган сайын кыйын болуп баратат. Бул жаңы ылдамдык жетишкендигин өнүгүү трекерине жазып, үйдөгү тоскоолдуктарды алып салууну унутпаңыз.','Kiiruse kogumine! 🏃‍♂️','Sinu väike ei kõnni enam ainult – ta peaaegu jookseb! Temaga sammu pidamine muutub keerulisemaks. Salvesta see uus kiiruse verstapost arengu jälgijasse ja veendu, et kodus poleks takistusi.'),
('19f5918f-33f2-423f-ba32-d0be2a6bca2a'::uuid,'Денеңиздин муктаждыктарын угуңуз. 🥑','Колуңуз жана белиңиз ооруп жатабы? Наристеңиз эми оорлошуп калды! Булчуңдарыңызды колдоо үчүн биздин пайдалуу рецепттерден кальций жана протеинге бай жеңил түшкү тамакты тандаңыз.','Kuula oma keha vajadusi. 🥑','Kas käed ja selg valutavad? Sinu väike on nüüd raskem! Toeta oma lihaseid, valides meie tervislike retseptide hulgast kerge, kaltsiumi- ja valgurikka lõunasöögi.'),
('3ddcf967-26bf-4c82-a9be-ef2d0c28d637'::uuid,'Оюн башталсын! 🧸','Балаңыз оюнчук аюусун тамактандырууга же уктатууга аракет кылып жатабы? Анын кыялдануусу чындап өнүгүп жатат! Эмпатияга болгон бул сонун аракеттерди сыймыктануу менен байкаңыз.','Las rollimängud algavad! 🧸','Kas su laps proovib oma kaisukaru toita või magama panna? Tema kujutlusvõime tõesti õitseb! Jälgi uhkusega neid imelisi empaatia katseid.'),
('c178ee13-258d-408c-8a70-3133436f4f3b'::uuid,'Атанын оюн убактысы. 👨‍👧','Алыңыз куруп, чарчадыңызбы? Бул кечте полдо оонап, кытыгылашып ойногонду атасына тапшырыңыз.','Issi mänguaeg. 👨‍👧','Kas oled omadega läbi? Lase issil täna põrandal püherdamise ja kõdistamismängudega tegeleda.'),
('05b16636-3744-4ea1-b6f2-f3824e51cd2d'::uuid,'Ашканадагы укмуштуу окуялар! 🍎','Мөмө-жемиштерди жууганга жардам берүүсүнө жол бериңиз. Суунун үнү жана жемиштердин ачык түстөрү алардын көңүлүн буруп, кызыгуусун арттырат.','Köögiseiklused! 🍎','Lase neil end aidata puuviljade pesemisel. Vee sulin ja puuviljade erksad värvid hoiavad neid tegevuses ja uudishimulikena.'),
('3fd7287e-bc6f-49d6-a94b-292122e10559'::uuid,'Сүйлөмдөрдү курап жатат! 🗣','️ Алар "Апа, бер" же "Ата, кара" сыяктуу эки сөздү бириктирүүгө аракет кылып жатабы? Бул алардын сүйлөө жөндөмүнүн өнүгүүсүндөгү укмуштуудай секирик!','Harjutame lauseid! 🗣','️ Kas nad proovivad juba kahte sõna ühendada, nagu „Emme, anna“ või „Issi, vaata“? See on suurepärane hüpe nende kõne arengus!'),
('9884e1c4-18cf-4fce-b89d-ae4f4603110b'::uuid,'Кичинекей сүрөтчүңүз иштеп жатат! 🖍️','Карандаш бергениңизде кагазга (же дубалга!) чиймелеп жатабы? Алардын майда моторикасы тез өнүгүүдө. Жуула турган карандаштарды же маркерлерди алуунун убактысы келди!','Sinu väike kunstnik on ametis! 🖍️','Kas nad kritseldavad paberile (või seinale!), kui neile värvipliiatsi annad? Nende peenmotoorika areneb kiiresti. On aeg muretseda pestavad värvipliiatsid või vildikad!'),
('cbbf4112-6812-4999-b3bd-fe378d632205'::uuid,'Атанын жомок айтып берүү убактысы. 👨‍🍼','Кечки эң акыркы кыймылдуу оюндарды атасына өткөрүп бериңиз. Алардын чогуу күлгөнү сиздин эс алууңуз үчүн эң сонун фон болот.','Issi unejutud. 👨‍🍼','Anna õhtu viimased energilised mängud issi hooleks. Nende ühine naer on kõige ilusam taust sinu puhkusele.'),
('fcd25c40-af67-4335-a70a-9d6c3e016480'::uuid,'Аба ырайын изилдөө! ⛅','Сыртта шамал болуп жатабы же бир аз эле салкынбы? Терезеден бир карап коюуга эле ишенбеңиз. Биздин "Аба ырайы жана Кийим" куралыбыз сизге эң сонун айкалышты секунданын ичинде айтып берсин.','Ilma avastamas! ⛅','Kas väljas on tuuline või lihtsalt veidi jahe? Ära piirdu vaid kiire pilguga aknast. Meie ilmateate ja riietuse tööriist ütleb sulle sekunditega, mida selga panna.'),
('1cec3e77-df8d-4fe0-9a15-4d7f7ee66785'::uuid,'Тажрыйбаңыз менен бөлүшүңүз! 💬','"Менин балам да ушундайбы?" деген ой санааңызды ээлеп алдыбы? Anacan коомчулугуна кошулуп, 16 айлык балдардын башка энелеринин баяндарын окуп, терең дем алыңыз.','Jaga oma kogemusi! 💬','Kas mõte „Kas mu laps on ka selline?“ ei anna sulle rahu? Liitu Anacani kogukonnaga, loe teiste 16-kuuste laste emade lugusid ja hinga sügavalt sisse.'),
('61b42915-8f61-46a7-b887-07cc8998e71f'::uuid,'Тынчтандыруучу ванна убактысы. 🛁','Уктаар алдында жылуу суу менен ойноо күндүн бардык чарчоосун жууп кетет. Тынч атмосфераны түзүү үчүн сууга бир нече тамчы эфир майын кошуңуз.','Rahustav vanniaeg. 🛁','Sooja veega mängimine enne und aitab päeva pingeid maha pesta. Lisa vette paar tilka eeterlikku õli, et luua rahulik õhkkond.'),
('f5e358ba-f868-4a50-851c-6980fa2b0075'::uuid,'Тепкичтерди алгачкы жолу өз алдынча чыгуу! 🪜','Эми алар сиздин колуңуздан кармап, ишенимдүүрөөк туруп жатышат. Бут булчуңдарын чыңдоосуна тоскоол болбоңуз, болгону алардын коопсуздугун камсыз кылыңыз.','Esimesed iseseisvad trepironimised! 🪜','Nad tõusevad nüüd sinu käest kinni hoides kindlamalt püsti. Ära takista neil jalalihaste tugevdamist, lihtsalt taga nende ohutus.'),
('bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6'::uuid,'Соода тизмеңиз дайыма жаныңызда! 🛒','Күнүмдүк түйшүктө шампунь же нымдуу салфетка түгөнүп калдыбы? Аны оюңузда сактабай, "Соода тизмесине" кошуп, жолдошуңуз менен синхрондоштуруңуз.','Sinu ostunimekiri on alati kaasas! 🛒','Kas igapäevases saginas said šampoon või niisked salvrätikud otsa? Ära hoia seda peas, lisa need ostunimekirja ja sünkrooni partneriga.'),
('c131d78d-b239-4de3-9bc9-c0c8fe25a6f7'::uuid,'Сурооңуз барбы? 🤖','"Эмне үчүн түнкүсүн ойгонуу көбөйдү?" деген сыяктуу суроолорго биздин Anacan AI жардамчыбыз түн ортосунда дароо жооп бере алат.','Kas sul on küsimusi? 🤖','Küsimustele nagu „Miks öised ärkamised on sagenenud?“ vastab meie Anacani AI-assistent silmapilkselt, isegi keset ööd.'),
('c67019a7-8ef8-4eef-bcc7-41d6f859382f'::uuid,'Ку-ку! Мен сени таптым! 🙈','Алар көздөрүн жаап, "ку-ку" ойноп жатышабы? Алардын нерселердин туруктуулугун түшүнүүсү сонун өнүгүп жатат!','Kuku-kuu! Leidsin su üles! 🙈','Kas nad katavad silmi ja mängivad peitust? Nende arusaam objektide püsivusest areneb imeliselt!'),
('45bc547e-6211-4178-aad6-4266015ca9cf'::uuid,'Биз бир командабыз! 💖','Оор күндөн кийин жолдошуңуз менен бетме-бет отуруп, сүйлөшүңүз. Бири-бириңизди колдоо физикалык жана эмоционалдык жүктү толугу менен эки эсеге азайтат.','Oleme meeskond! 💖','Pärast rasket päeva istuge partneriga näost näkku ja rääkige asjad läbi. Teineteise toetamine poolitab füüsilise ja emotsionaalse koormuse.'),
('89373578-8a41-4cd9-bcef-3a5786b1f576'::uuid,'Педиатриялык суроолоруңуз барбы? 🤖','16-18 айлык өнүгүүдө эмнени күтүү керек деп ойлонуп жатасызбы? Интернеттен коркунучтуу жаңылыктарды окугандын ордуна, Anacan AIден так эксперттик корутунду сураңыз.','Mured lapse tervisega? 🤖','Huvitab, mida oodata 16–18 kuu arengus? Selle asemel, et lugeda internetist hirmutavaid uudiseid, küsi Anacani AI-lt täpne ja asjatundlik kokkuvõte.'),
('daea63ca-66de-40da-bafb-c740af314d06'::uuid,'Китепке болгон сүйүү 📖','Алар китептин барактарын эркин барактап, сүрөттөрдү көрсөтүп жатышабы? Китеп окууга болгон сүйүү дал ушундай башталат! Сүрөттөрдөгү нерселердин аталыштарын чогуу атагыла.','Armastus raamatute vastu 📖','Kas nad keeravad juba vabalt raamatulehti ja näitavad piltidele? Nii algab armastus lugemise vastu! Nimetage koos piltidel olevaid objekte.'),
('1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d'::uuid,'Наристеңиз күтүлбөгөн жерден ыйлап ойгондубу?','Бул түнкү коркуу болушу мүмкүн. Үндү угуп, көйгөйдүн физикалык же психологиялык экенин аныктоо үчүн "Ыйды анализдөө" функциясын колдонуңуз.','Kas su laps ärkas äkki karjudes?','See võib olla öine hirmuhoog. Kasuta nutianalüüsi, et kuulata häält ja teha kindlaks, kas probleem on füüsiline või psühholoogiline.'),
('e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c'::uuid,'Үй жумуштары күтө турат! 🛑','Пол жуулбай калдыбы? Мейли, кала берсин. Чачылган үйдү жыйнаса болот, бирок эненин чарчоосунан арылуу көбүрөөк убакытты талап кылат. Диванга жатып, жөн гана тынчтыкты угуңуз.','Kodutööd võivad oodata! 🛑','Kas põrand on pesemata? Las olla. Segamini kodu saab korda teha, aga ema kurnatusest taastumine võtab kauem aega. Heida diivanile ja lihtsalt kuula vaikust.'),
('fba2093e-fbf1-4663-b05f-7071650fd43f'::uuid,'Логикалык жөндөмдөрдү өнүктүрүү 🧱','Алар мунара куруу үчүн 3-4 кубикти үстү-үстүнө коюп жатышабы? Бул моторикалык жетишкендикти "Өсүү трекерине" сөзсүз жазып коюңуз! Алардын кичинекей инженердик аракеттерине кол чабыңыз.','Loogikaoskuste arendamine 🧱','Kas nad laovad juba 3–4 klotsi torniks? Ära unusta seda motoorika verstaposti kasvupäevikusse märkida! Plaksuta nende väikestele inseneritöödele.'),
('0fea9ae7-0132-47ff-9282-adcf39bd128b'::uuid,'Уйкуга даярдануу. 🌙','Бөлмөнүн жарыгын бүдөмүктөтүп, акырын шыбырап сүйлөңүз. Бул алардын нерв системасына эс алуу убактысы келгенин билдирет.','Uinumise lihtsustamine. 🌙','Hämarda toas tuled ja räägi vaikselt sosinal. See annab nende närvisüsteemile märku, et on aeg puhata.'),
('eb955e5b-023a-4e67-ac53-d6ab712c507e'::uuid,'Кичинекей жардамчыңыз 🧺','Оюнчуктарды кутуга чогултуп жатканыңызда, алар дагы бирөөнү алып келип кошушабы? Бул кичинекей жардам берүү аракеттерин сөзсүз мактап, аларга ыраазычылык билдириңиз!','Sinu väike abiline 🧺','Kui korjad mänguasju kasti, kas nad toovad ühe juurde? Kiida kindlasti neid väikeseid abivalmiduse märke ja tänage neid!'),
('49fd2511-4696-40ce-a9eb-8140a6570163'::uuid,'Кызыктуу жомоктун сыйкыры. 🪄','''Smart Tales'' бөлүмүндө балаңыз башкы каарман болгон өзгөчө жомок жаратыңыз: ''Сыйкырдуу токойдо сейилдеген эр жүрөк бөбөк''.','Huvitava loo võlu. 🪄','Loo „Nutikates juttudes“ eriline lugu, kus sinu laps on kangelane: „Väike vapper rändur võlumetsas“.'),
('f03e45ee-5599-42df-9ad9-5c86e351f328'::uuid,'Апанын өзүнө арнаган убактысы! 🎧','Балаңыз уктаар замат ашканага шашпаңыз. Кулакчыныңызды тагынып, сүйүктүү ырыңызды коюп, 15 мүнөт жөн гана "өзүңүз" болуңуз.','Emme oma aeg! 🎧','Ära torma kööki kohe, kui laps uinub. Pane kõrvaklapid pähe, mängi oma lemmiklugu ja ole lihtsalt 15 minutit iseendaga.'),
('ff37a7ef-9322-44bc-9dbd-322f32bc0ec9'::uuid,'Өз алдынча тамактанууга аракет кылуу 🥄','Эгерде алар колуңуздан кашыкты алууга аракет кылып жатса, тоскоол болбоңуз! Айланасы булганса дагы, өз алдынча тамактануу – бул алардын көз карандысыздыгына карай чоң кадам.','Nõuab ise söömist 🥄','Kui nad proovivad lusikat su käest võtta, ära takista neid! Isegi kui tekib segadus, on iseseisev söömine suur samm iseseisvuse poole.'),
('59f57b09-3fb4-490e-8cae-41edccebdd18'::uuid,'Таттуу уйку 🌙','Күнүңүз узак болду, туурабы? Наристеңиз уктап жатканда, биздин "Ак ызы-чуу" функциябыздан океан толкундарынын үнүн коюңуз. Экөөңүз тең тынчтык таап, эс алыңыз.','Magusaid unenägusid 🌙','Sul on olnud pikk päev, eks? Kui su väike ime magab, pane meie valge müra funktsioonist mängima ookeanilained. Leidke mõlemad rahu ja puhake.'),
('69941885-7481-4f3d-83b9-75392ac8bf14'::uuid,'Түшкү тамак убактысы ⏱️','Тамактануу убактысын көзөмөлдөө эми оңой! Бөбөгүңүздүн күнүмдүк тамактануусун кылдат байкоо үчүн тамактануу таймерин колдонуңуз.','Lõunasöögi taimer ⏱️','Söötmisaegade jälgimine muutus just lihtsamaks! Kasuta toitmise taimerit, et hoida oma beebi igapäevasel toidukogusel silm peal.'),
('76342fb8-c3b7-4c1b-a6cb-70ae7ab72954'::uuid,'Даяр, баштадык, ЧУРКА! 🏃‍♀️','17 айлык изилдөөчүңүз үйдө шаңдуу ызы-чуу салып жатабы? Алардын энергиясын сарптоо үчүн ''Энелерге ыңгайлуу жайлар'' бөлүмүнөн жакынкы сейил бакты табыңыз!','Valmis, tähelepanu, JOOKSE! 🏃‍♀️','Kas su 17-kuune avastaja teeb kodus rõõmsat lärmi? Leia meie „Emadele sobivate kohtade“ rubriigist uus lähedalasuv park, kus ta saab energiat kulutada!'),
('310b35fd-56c2-4e43-bf45-49c975449bf2'::uuid,'Даамдуу жана өзгөчө! 🥦','Бүгүн бөбөгүңүзгө кандай жаңы тамак жасасам деп ойлонуп жатасызбы? Кошумча тамакка өтүп жаткан бөбөктөр үчүн ''Рецепттер'' бөлүмүнөн даамдуу идеяларды табыңыз.','Maitsev ja teistmoodi! 🥦','Mõtled, mida täna oma pisikesele süüa teha? Leia maitsvaid ideid retseptide sektsioonist, mis on mõeldud lisatoiduga alustavatele beebidele.'),
('9477e55c-8f99-4ea9-8c87-38780aa67baa'::uuid,'Сезимдериңизди күндөлүккө жазыңыз 📝','Эне болуу кээде чарчатат, бул табигый көрүнүш. Бүгүн сизди эмне көбүрөөк чарчатты, ''Маанай күндөлүгүнө'' жазып коюңуз да, өзүңүзгө эс алууга уруксат бериңиз.','Pane oma tunded kirja 📝','Emadus võib vahel kurnav olla ja see on täiesti normaalne. Pane oma meeleolupäevikusse kirja, mis sind täna kõige rohkem väsitas, ja luba endal puhata.'),
('bd556eab-5192-450f-94ce-a80cdc85557b'::uuid,'Эртең мененки жалаяк сюрпризи! 💩','Күндүн биринчи жалаягын алмаштырдыңызбы? Гигиеналык тартипти оңой көзөмөлдөө үчүн аны тиркеменин ''Жалаякка көз салуу'' бөлүмүнө каттап коюуну унутпаңыз!','See hommikune mähkmeüllatus! 💩','Vahetasid päeva esimese mähkme? Ära unusta seda rakenduse mähkmejälgijasse märkida, et saaksid hõlpsalt hügieenirutiinil silma peal hoida!'),
('09e40e6a-1b4a-402d-88ca-e9d2b030ae96'::uuid,'Мага кара! ☝️','Ал сиздин көңүлүңүздү буруу үчүн үндөрдү чыгарып, кызыккан нерселерин көрсөтүп жатабы? ''Ооба, бул топ!'' деп тастыктап, анын ачылыштарына кошулуңуз.','Vaata mind! ☝️','Kas ta teeb tähelepanu saamiseks hääli ja osutab huvipakkuvatele esemetele? Ühine tema avastustega ja kinnita: „Jah, see on pall!“'),
('c5a0bf61-8c64-48fe-98e1-446f7f35fcb3'::uuid,'Тамактануу учурундагы кашык менен күрөш 🥄','Бөбөгүңүз өзү тамактанууга аракеттенип, жарымын төгүп жатабы? Төгүлгөнүнө кабатыр болбоңуз! Бул алгачкы күндөр алардын өз алдынча тамактануу көндүмдөрүнүн пайдубалын түптөөдө.','Söömisaja lusikalahingud 🥄','Kas su pisike üritab ise süüa ja ajab poole toidust maha? Ära muretse segaduse pärast! Need esimesed päevad panevad aluse tema iseseisvatele söömisharjumustele.'),
('c62d64af-c28e-4bfc-82ce-a73c5d55fd91'::uuid,'Күнүмдүк отчет. 📝','Өзүңүздү жетишсиз сезгенде, күн ичиндеги кичинекей жетишкендиктериңизди ''Маанай күндөлүгүнө'' жазыңыз. (Мисалы: ''Мен аны күлдүрдүм'', ''Мен аны тойгуздум''). Сиз укмуштуудай энесиз!','Päevaaruanne. 📝','Kui tunned end ebakindlalt, kirjuta oma meeleolupäevikusse üles päeva väikesed saavutused. (Näiteks: „Panin ta naerma“, „Hoidsin ta kõhu täis“). Sa oled suurepärane!'),
('14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22'::uuid,'Маектешүү тереңдейт 🗣️','Ал сиз менен түшүнүксүз сөздөр менен ''сүйлөшүп'', жада калса кол жаңсоолорун колдонуп жатабы? Аны менен олуттуу түрдө диалог куруңуз; бул тил өнүктүрүү үчүн өтө маанилүү.','Vestlused muutuvad sügavamaks 🗣️','Kas ta „räägib“ sinuga arusaamatute sõnadega ja kasutab isegi žeste? Suhtle temaga sama tõsiselt; see on keelelise arengu jaoks ülioluline.'),
('1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c'::uuid,'Таза абанын күчү 🌙','Бөбөгүңүз уктагысы келбей жатабы? Терезени ачып, бөлмөнү желдетиңиз. Салкын, таза аба ага тез уктоого дайыма жардам берет.','Värske õhu vägi 🌙','Kas su pisike võitleb unega? Ava aken ja värskenda tuba. Jahe ja värske õhk aitab tal alati kergemini uinuda.'),
('66766839-1404-43e5-8e4f-02d3ea6ce97c'::uuid,'Аллергиядан шектенесизби? 🤖','Жаңы жемиш берип, аллергиялык бүдүр байкадыңызбы? Дүрбөлөңгө түшөрдөн мурун, Anacan AI менен балдардагы тамак-аш аллергиясынын алгачкы белгилери тууралуу билип алыңыз.','Kahtlustad allergiat? 🤖','Tutvustasid uut puuvilja ja märkasid löövet? Enne kui satud paanikasse, uuri Anacan AI abil toiduallergiate esimesi märke lastel.'),
('86fd1056-7ec6-4295-9ae9-cce90735b8fe'::uuid,'Уйку убактысы! 😴','Уйку таймерин иштетиңиз! Кечки уйкунун так планын түзүү үчүн 17 айлык бөбөгүңүздүн күндүзгү уйкусунун узактыгын талдап чыгыңыз.','Uinakuaeg! 😴','Aktiveeri une taimer! Analüüsi oma 17-kuuse lapse uinakute kestust, et luua täpsem õhtune magamaminekuplaan.'),
('88975ce2-bde2-4036-a81f-ecfc994e6ec7'::uuid,'Сооронуч табуу 🍼','Алардын өз алдынчалыгын өстүрүү үчүн төгүлбөй турган эң мыкты чөйчөктү издеп жатасызбы? Биздин ''Сунушталган товарлар'' бөлүмүнөн башка энелердин жогорку баа берген тандоолорун карап чыгыңыз.','Mugavuse leidmine 🍼','Otsid parimat lekkekindlat nokktassi, et toetada lapse iseseisvumist? Sirvi meie soovitatud toodete sektsioonis teiste emade poolt kõrgelt hinnatud valikuid.'),
('b24e422c-33a1-4394-8c5a-e6048392180c'::uuid,'Өзүңүзгө кам көрүңүз, апа! ☕','Сиздин энергияңыз бөбөгүңүздүн бакубаттыгы үчүн өтө маанилүү! Биздин пайдалуу рецепттерден өзүңүзгө даамдуу жана күч бере турган смузи жасап ичиңиз.','Sea ennast esikohale, emme! ☕','Sinu energia on beebi heaolu jaoks ülioluline! Valmista meie tervislike retseptide abil endale maitsev ja energiat andev smuuti.'),
('6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d'::uuid,'Блог жана кофе тыныгуусу 📖','Бөбөгүңүз уктады, эми сиздин убактыңыз! Биздин жаңы блогду окуп, активдүү балдардын психологиясы тууралуу кызыктуу маалыматтарды билип алыңыз.','Blogi ja kohvipaus 📖','Beebi magab, nüüd on sinu aeg! Loe meie uut blogipostitust ja avasta põnevaid teadmisi aktiivsete laste psühholoogia kohta.'),
('92227c75-1f64-4b68-adfc-1f2f5187c456'::uuid,'Жайбаракат сейилдөө 👟','Сейил бакта бөбөгүңүздүн артынан чуркоо үчүн өзүңүзгө жана ага ыңгайлуу бут кийим издеп жатасызбы? ''Сунушталган товарлар'' бөлүмүнөн эң мыкты варианттарды караңыз.','Lõõgastavad jalutuskäigud 👟','Vajad mugavaid jalanõusid nii endale kui ka oma pisikesele, et temaga pargis ringi joosta? Sirvi parimaid valikuid soovitatud toodete sektsioonis.'),
('ee92e380-b93d-467f-ae59-b65756c20e29'::uuid,'Суроолоруңуз барбы? 🤔','Балаңыздын өжөрлүгүн кантип жөнгө салууну билбей жатасызбы? Anacan AI сизге дароо эксперттик кеңеш берүүгө даяр!','On küsimusi? 🤔','Mõtled, kuidas toime tulla lapse kasvava jonnakusega? Anacan AI on valmis andma kohest asjatundlikku nõu!'),
('5124c8a0-ed5f-4aa8-8203-12fc951409c5'::uuid,'Тамак сиңирүү системасын текшерүү. ⏱️','Күнүмдүк жалаяктын санын көзөмөлдөө бөбөгүңүздүн тамактануу сапатынын жакшы көрсөткүчү боло алат. Бүгүнкү өзгөрүүлөрдү биздин тиркемеге каттадыңызбы?','Seedimise kontroll. ⏱️','Igapäevane mähkmete jälgimine võib olla hea näitaja beebi toitmise kvaliteedi kohta. Kas oled tänased vahetused meie rakendusse märkinud?'),
('9c188bf4-4509-4c22-a2b7-a1a25cc28562'::uuid,'Үй-бүлөлүк тамактануу 🍲','Бүгүн кечки тамакка эмне бар? Биздин кошумча тамак рецепттерибиз бүт үй-бүлө сүйүп жей турган пайдалуу жана даамдуу тамак идеяларын сунуштайт.','Pere ühine söögiaeg 🍲','Mida täna õhtuks süüa teha? Meie lisatoidu retseptid pakuvad tervislikke ja maitsvaid ideid, mida kogu pere naudib.'),
('dab8f6cb-2ef5-454d-85b6-120c0f7644eb'::uuid,'Энелик жолуңуз 📝','Ар бир эненин окуясы уникалдуу. Биздин блогдордон башка энелердин реалдуу тажрыйбаларын жана окуяларын окуп, шыктаныңыз.','Sinu emaduse teekond 📝','Iga ema lugu on ainulaadne. Loe meie blogidest teiste emade tõelisi kogemusi ja lugusid ning leia inspiratsiooni.'),
('2522685d-511e-40e4-ab2a-4b34a238936c'::uuid,'Паркта чуркоо 👟','Алгачкы кадамдардан кийин чуркоо башталат! ''Сунушталган товарлар'' бөлүмүнөн биринчи бут кийим үчүн пайдалуу моделдерди карап көрүңүз.','Jooks tiigis või pargis 👟','Pärast esimesi samme algab jooksmine! Vaata soovitatud toodete sektsioonist tervislikke mudeleid esimesteks jalanõudeks.'),
('4b619580-dcf5-4c3a-a584-37bd74dfbaba'::uuid,'Тынч чөйрө түзүү 🌊','Бүгүн уктоо кыйын болуп жатабы? Нерв системаңызды тынчтандырып, уйкуга кирүү үчүн ''Ак ызы-чуу'' (White Noise) функциясынан океан толкундарынын үнүн коюңуз.','Rahuliku keskkonna loomine 🌊','Kas uinumine on täna raske? Pane mängima meie valge müra funktsiooni ookeanilained, et rahustada oma närvisüsteemi ja uinuda.'),
('7ae22b42-7e16-455e-8d98-b410c2cd5c7a'::uuid,'Белокту жетиштүү кабыл алып жатасызбы? 🍗','Белок балаңыздын өсүшү үчүн өтө маанилүү! Алардын күнүмдүк тамактануусун көзөмөлдөө жана керектүү азыктарды алып жатканын текшерүү үчүн ''Тамактануу трекерин'' колдонуңуз.','Kuidas on lood sinu valgu tarbimisega? 🍗','Valk on lapse kasvuks hädavajalik! Kasuta toitumise jälgijat, et jälgida tema igapäevast toidutarbimist ja veenduda, et ta saab kõik vajalikud toitained.'),
('2c591870-5eb2-4029-b209-ea812c8276ab'::uuid,'Уйку таймери иштеп жатабы? ⏳','Уктоого даярданып жатасызбы? Таймерди иштетип, уктоого канча убакыт кетерин талдап, андан соң бөбөгүңүздүн уйку тартибин кантип жакшыртууну үйрөнүңүз.','Kas unetaimer on aktiivne? ⏳','Valmistud magamaminekuks? Käivita taimer ja analüüsi, kui kaua uinumine aega võtab, ning õpi, kuidas oma pisikese rutiini täiustada.'),
('fb78ab52-3c7a-4706-adfa-55485f38dc6d'::uuid,'Күч топтоо убактысы! 🔋','Күндүн түйшүгүнө даярсызбы? Аялдар үчүн пайдалуу рецепттерден өзүңүзгө даамдуу жана витаминге бай эртең мененки тамакты тандаңыз.','Aeg akusid laadida! 🔋','Oled valmis päevaseks saginaks? Vali endale meie naistele mõeldud tervislike retseptide hulgast maitsev ja vitamiinidest pakatav hommikusöök.'),
('543206e3-a734-4c0f-89e0-a5bb0b8f6100'::uuid,'Сооронууну издеп. 🍼','Бөбөгүңүздүн өз алдынча ичишине көмөктөшө турган эң ыңгайлуу чөйчөктү издеп жатасызбы? Энелер тарабынан жогору бааланган варианттарды биздин ''Сунушталган товарлар'' бөлүмүнөн карап көрүңүз.','Mugavuse otsimine. 🍼','Otsid parimat lekkekindlat nokaga tassi, et toetada lapse iseseisvumist? Vaata emade poolt kõrgelt hinnatud valikuid meie jaotisest „Soovitatud tooted“.'),
('70ce55d5-f110-4637-a672-3efae4b7e852'::uuid,'Сиз муну сөзсүз жасай аласыз! 💪','Күнүңүз оор өттүбү? Маанай күндөлүгүнө ички сезимдериңизди жазып, жеңилдеп алыңыз. Эсиңизде болсун, бул жөн гана жаман күн, жаман жашоо эмес.','Sa saad hakkama! 💪','Oli keeruline päev? Kuula oma sisemisi mõtteid meeleolupäevikus. Pea meeles, see on vaid halb päev, mitte halb elu.'),
('787e9318-ea30-497d-9a1a-d3de64060a9d'::uuid,'Тамактануу боюнча отчет 📊','Балаңыздын күнүмдүк тамактануусун ''Тамактануу трекерине'' киргизиңиз. Бүгүн ал керектүү витаминдердин баарын алдыбы, текшерип көрөлү!','Söötmise aruanne 📊','Sisesta lapse tänane toitumine toitumisjälgijasse. Vaatame, kas ta sai täna kõik vajalikud vitamiinid kätte!'),
('0d93db4a-8b6f-404c-af2e-d97c0d79adf5'::uuid,'Терең дем алыңыз ✨','Баары идеалдуу болбосо да эч нерсе эмес. Сиз буга чейин эле эң сонун энесиз! Күндүн чарчоосун Маанай күндөлүгүнө калтырып, жан дүйнөңүзгө тынчтык табыңыз.','Hinga sügavalt sisse ✨','Pole hullu, kui kõik pole täiuslik. Sa teed juba niigi suurepärast tööd, emme! Lase päeva stress meeleolupäevikusse ja leia rahu.'),
('c34d441d-5c3c-48a4-9477-974b42412b6e'::uuid,'Бул өсүү мезгилиби? 🦒','Кийимдери кичинекей болуп калдыбы? Жаңы өлчөмдөрүн ''Өсүү трекерине'' киргизиңиз жана балаңыздын өсүү графиги кандай өзгөргөнүн көрүңүз!','Kas see on kasvuhüpe? 🦒','Kas riided hakkavad kitsaks jääma? Sisesta uued mõõdud kasvu jälgijasse ja vaata, kuidas kasvukõver tõuseb!'),
('d37162b5-bdeb-4abc-8206-52d2382cc6de'::uuid,'Тамактануу боюнча көрсөтмөлөр 🥣','Бөбөгүңүз бүгүн жетиштүү өлчөмдө белок алдыбы? ''Тамактануу трекери'' аркылуу балаңыздын күнүмдүк менюсун талдап, жетишсиздиктерди толуктаңыз.','Söötmise juhised 🥣','Kas su beebi sai täna piisavalt valku? Analüüsi beebi päevamenüüd toitumisjälgijaga ja täida võimalikud lüngad toitumises.'),
('06c24f98-8519-42a4-86d5-14e6b430bf94'::uuid,'Тынчтандыруучу үндөр 🌧️','Күндүн таасиринен улам уйкуңуз келбей жатабы? Балаңыздын нерв системасын табигый жол менен тынчтандыруу үчүн ''Ак ызы-чуу'' (White Noise) функциясынан жамгырдын үнүн тандаңыз.','Rahustavad helid 🌧️','Kas päeva erutusest on raske uinuda? Vali meie valge müra funktsioonist vihmaheli, et aidata lapse närvisüsteemi loomulikult rahustada.'),
('8fe0e4be-15b3-4472-a10c-0dbbc28c48cc'::uuid,'Бүгүнкү күндү өзгөчө кылыңыз! 🌟','Үйдөгү күнүмдүк турмуштан чарчадыңызбы? ''Энелер үчүн ыңгайлуу жайлар'' картасын ачып, бөбөгүңүз менен эс ала турган жаңы кафе табыңыз.','Muuda tänane päev eriliseks! 🌟','Kas kodune rutiin tundub veidi kurnav? Ava meie „Emadesõbralike kohtade“ kaart ja avasta uus kohvik, kus saad beebiga mugavalt lõõgastuda.'),
('ea228eca-a9dc-4d32-bfab-5af38c95cc81'::uuid,'Кичинекей жылдызым! 📸','Анын таттуу жылмаюусу баа жеткис! ''Бөбөк фотосессиясы'' функциясындагы ар кандай алкактарды колдонуп, бул күндү түбөлүккө сактап калыңыз.','Väike staar! 📸','Nende armas naeratus on hindamatu! Jäädvusta see päev, kasutades beebi pildistamise funktsioonis erinevaid raame.'),
('58bde9b3-f42d-49ca-ae5b-48563d307555'::uuid,'Өсүү мезгили жакындап калдыбы? 📈','Бөбөгүңүз көп ыйлап же уйкусу бузулуп жатабы? Бул 17 айлык өсүү мезгили же ''секирик жумасы'' экенин билүү үчүн Anacan AI менен кеңешиңиз.','Kasvuhüpe tulemas? 📈','Kas su väike laps nutab palju või on uni häiritud? Konsulteeri Anacan AI-ga, et teha kindlaks, kas tegemist võib olla 17-kuuse kasvuhüppe või arenguhüppega.'),
('7771d800-de2f-41eb-8bd6-431add8986fe'::uuid,'Тынчтандыруучу тартип 🌙','Кереметтүү күндүн аягы. Уйку таймерин иштетип, ''Ак ызы-чуу'' коллекциясынан бешик ырын тандап, күнүңүздү тынчтык менен жыйынтыктаңыз.','Lõõgastav rutiin 🌙','Kauni päeva lõpp. Pane käima unetaimer, vali meie valge müra kogust hällilaul ja naudi rahulikult päeva lõppu.'),
('b9d3a084-eae2-4a4a-af8c-e99d02752f66'::uuid,'Таза абага сейилдөө 🌳','Үйдө зеригип жатасызбы? ''Энелер үчүн ыңгайлуу жайлар'' картасын ачып, бөбөгүңүз менен жайбаракат сейилдей турган жаңы сейил бак табыңыз.','Värske õhu kätte 🌳','Igav kodus? Ava meie emadesõbralike kohtade kaart ja avasta uus park, kus saad beebiga mugavalt jalutada.'),
('c7d9bc7f-54a9-4f50-9876-80c78adff647'::uuid,'Уктоо убактысы ⏱️','Балаңызды уктатууга даярданып жатасызбы? Уйку таймерин иштетип, уйку режимин сактоо канчалык ийгиликтүү болуп жатканын көзөмөлдөңүз.','Aeg magama minna ⏱️','Valmistud uinakuks või ööuneks? Käivita unetaimer ja jälgi, kui hästi rutiinist kinni pead, et analüüsida lapse uneharjumusi.'),
('e064d0bf-455a-4252-9305-e3585f5b88ac'::uuid,'Эртең мененки табитиңиз кандай? 🥣','Күндү дени сак баштоо абдан маанилүү! Бүгүнкү витамин муктаждыгын эсептөө жана менюну пландаштыруу үчүн ''Тамактануу трекерин'' колдонуңуз.','Kuidas on lood hommikuse isuga? 🥣','Tervislik päeva algus on võtmetähtsusega! Kasuta toitumisjälgijat, et arvutada tänane vitamiinivajadus ja planeerida menüü.'),
('256bddeb-107b-434f-9688-0c6670394bc8'::uuid,'Кийимдери тар болуп баштадыбы? 📏','Балаңыздын тез өсүп жатканын байкадыңызбы? Жаңы көрсөткүчтөрдү ''Салмак трекерине'' киргизип, анын дени сак өсүү графигин текшериңиз.','Riided hakkavad kitsaks jääma? 📏','Märkasid lapsel äkilist kasvuhüpet? Sisesta uued numbrid kaalu jälgijasse ja kontrolli tema tervislikku kasvukõverat.'),
('ac852fa3-348f-43fe-9321-7b4e3e9f3af1'::uuid,'Тамактануу таймери ⏱️','Тамактануу канча убакытка созулуп жатат? Тамактандыруу таймерин иштетип, сиңирүү процесси туура жүрүшү үчүн режимди көзөмөлдөңүз.','Söötmise taimer ⏱️','Kui kaua söömine aega võtab? Käivita toitmise taimer ja jälgi rutiini, et tagada korralik seedimine.'),
('f78fdccc-68a3-4827-b309-2accfb39bff1'::uuid,'Пайдалуу макалалар 📖','Бөбөгүңүз уктап жатканда эмне кылып жатасыз? Энелик сапарыңызды байытуу үчүн ''Блогдор'' бөлүмүндөгү акыркы макалаларды окуп чыгыңыз.','Kasulikku lugemist 📖','Beebi magab, millega sina tegeled? Loe uusimaid artikleid meie blogide jaotisest, et rikastada oma emaduse teekonda.'),
('0a2bf8ce-6e82-41df-9345-19718f7bde4c'::uuid,'Эң ыңгайлуу чөйчөктү тандоо 🥤','Төгүлбөй турган жана ыңгайлуу чөйчөк издеп жатасызбы? ''Сунушталган товарлар'' бөлүмүнөн энелер тарабынан сыналган эң мыкты товарларды карап чыгыңыз.','Ideaalse nokaga tassi leidmine 🥤','Otsid lekkekindlat ja mugavat nokaga tassi? Sirvi emade poolt järeleproovitud tooteid jaotises „Soovitatud tooted“.'),
('12fa87ff-96f2-48c2-a70c-da7757524f9b'::uuid,'Кофе ичүү тыныгуусу ☕','Бүгүн сыртка чыккыңыз келип жатабы? ''Энелер үчүн ыңгайлуу жайлар'' бөлүмүнөн балдар аянтчасы бар кафени таап, өзүңүзгө бир аз убакыт бөлүңүз.','Kohvipaus ☕','Tahaksid täna kodust välja saada? Leia meie emadesõbralike kohtade jaotisest mängunurgaga kohvik ja võta endale veidi aega.'),
('5bd8188b-93fc-435a-8a33-b488c4ecc902'::uuid,'Сезимдерди сыртка чыгаруу 📝','Бүгүнкү күн пландагыдай болбой калдыбы? Өзүңүздү өтө катуу сындабаңыз. Ички тынчсызданууларыңызды Маанай күндөлүгүнө жазып, жеңилдеп алыңыз.','Emotsionaalne vabastamine 📝','Kas täna ei läinud kõik plaanipäraselt? Ära ole enda vastu liiga karm. Vala oma sisemised mured meeleolupäevikusse.'),
('0d268555-6803-4b45-adab-7558434a3d7b'::uuid,'Эртең мененки ичеги-карын абалын текшерүү 💩','Бүгүнкү биринчи жалаяк алмаштыруу болдубу? Заңдын түсү жана консистенциясы ичеги-карындын ден соолугунан кабар берет. Аны дароо жалаяк трекерине белгилеңиз!','Hommikune kaka kontroll 💩','Kas vahetasid päeva esimese mähkme? Väljaheite värv ja konsistents võivad viidata soolestiku tervisele. Märgi see kohe mähkmete jälgijasse!'),
('7d0a17bf-475f-48d2-9838-14918053b021'::uuid,'Энелер үчүн энергия 🥗','Баланын артынан чуркоо чарчатат. Өзүңүздү унутпаңыз! Аялдар үчүн дени сак рецепттерибизден даамдуу жана энергия бере турган салат даярдаңыз.','Energiat emmedele 🥗','Nendega jooksmine on väsitav. Ära unusta iseennast! Valmista meie naiste tervislike retseptide järgi maitsev ja energiat andev salat.'),
('b2894838-9e87-4d9f-80b1-63a311667ac3'::uuid,'Ак ызы-чуунун сыйкыры 🌧️','Абдан активдүү күн болдубу? Бөлмөдө ''Ак ызы-чуу'' функциясынан жамгырдын үнүн коюңуз. Бөбөгүңүз оңой уктап кетсин, ал эми сиз акыры терең дем алып эс алыңыз.','Valge müra võlu 🌧️','Oli väga aktiivne päev? Pane toas mängima meie valge müra funktsiooni vihmaheli. Lase beebil kergelt uinuda ja saad lõpuks ise rahulikult hingata.'),
('0b41a1b3-ce5c-4804-b352-c95cc9725120'::uuid,'Күндүн эң таттуу көз ирмеми 📸','Бөбөгүңүз бүгүн өзгөчө жана күлкүлүү нерсе жасадыбы? Ал баалуу көз ирмемди ''Бөбөк фотосессиясы'' функциясындагы кызыктуу алкактар менен түбөлүккө сактап калыңыз.','Päeva armsaim hetk 📸','Kas su väike laps tegi täna midagi ainulaadset ja naljakat? Jäädvusta see väärtuslik hetk meie beebi pildistamise funktsiooni lõbusate raamidega ja muuda see eluaegseks mälestuseks.'),
('136efb64-ddf1-465d-be06-c1f4f0ca13f2'::uuid,'Өз алдынча тамактанууга даяр! 🥦','Өз алдынчалыкка умтуласызбы? Кошумча тамакка өтүп жаткан бөбөктөр үчүн даамдуу, кармоого оңой жана чачылбай турган рецепттерди тандаңыз.','Valmis ise sööma! 🥦','Soovid iseseisvust? Vali maitsvad, kergesti käes hoitavad ja vähem määrivad portsjonid meie lisatoiduga alustavate beebide retseptidest.'),
('37e233ca-794d-4595-8c1d-115d93279302'::uuid,'Кырсылдак мүнөз менен иштөө 🤖','Бөбөгүңүз баарына ''жок'' деп жатабы? Эгерде ''эки жашарлардын кыяңкечтигин'' кантип башкарууну билбей жатсаңыз, дароо Anacan AI менен кеңешиңиз.','Kuidas toime tulla jonnihoogudega 🤖','Kas su väike põnn ütleb kõigele ei? Kui sa ei tea, kuidas ''jonniiga'' või tujudega sel perioodil toime tulla, pea nõu Anacan AI-ga.'),
('30a82706-c2b4-4804-8bf8-50b827b59af2'::uuid,'Уйкуга болгон муктаждыкты түшүнүү 😴','Түнү кандай уктады? Балаңыз күнүмдүк уйку нормасын аткарганын талдоо үчүн уйку таймеринин журналдарын текшериңиз.','Unevajaduse mõistmine 😴','Kuidas nad öösel magasid? Kontrolli unetaimeri logisid, et analüüsida, kas su beebi sai oma soovitusliku ööpäevase unekoguse kätte.'),
('63599f1b-cfac-43fe-af30-fa096e5c9039'::uuid,'Оюңузда эмне бар? 🤖','Балаңыздын өнүгүүсү боюнча суроолоруңуз барбы? Илимий негизделген жоопторду алуу жана тынчтануу үчүн биздин Anacan AI эксперттик жардамчыбыз менен баарлашыңыз.','Mis sul mõttes on? 🤖','Kas sul on küsimusi või muresid lapse arengu kohta? Vestle meie Anacan AI eksperdist assistendiga, et saada teaduspõhiseid vastuseid ja meelerahu.'),
('c29b8ee7-5a3e-484e-b3fb-fba482038bb2'::uuid,'Ар бир тамак сайын жаңы даамдар 🍲','''Бүгүн эмне тамак жасасам?'' деген суроо эми жок! Кошумча тамакка өтүп жаткан бөбөктөр үчүн рецепттер бөлүмүндө сиз үчүн түстүү жана пайдалуу менюлар бар.','Uued maitsed igal toidukorral 🍲','Dilemma ''mida täna süüa teha?'' on läbi! Jaotises ''Lisatoidu retseptid'' on värvilised ja tervislikud menüüd just sulle.'),
('0c8639eb-e97c-4e44-a8d2-900ea16527d9'::uuid,'Күнүмдүк ичеги-карын отчету 💩','Эртең мененки жалаяк алмаштырууну белгилегенди унутпаңыз! Күн бою жалаяк алмаштырууну көзөмөлдөө балаңыздын жетиштүү суюктук ичип жатканын билдирет.','Igapäevane kakaaruanne 💩','Ära unusta hommikust mähkmevahetust kirja panna! Mähkmevahetuste jälgimine päeva jooksul näitab, kas su laps saab piisavalt vedelikku.'),
('c9a5ad78-ffcc-4191-a0f2-0e290d6c0364'::uuid,'Өзүңүздүн да ден соолугуңузга кам көрүңүз! 🥗','Энергияңыз азайып жатабы? Аялдар үчүн дени сак рецепттерибизден витаминге бай смузи даярдаңыз. Сизге күчтүү болуу керек!','Toitu ka ise tervislikult! 🥗','Tunned, et energiat on vähe? Valmista vitamiinirikas smuuti meie naistele mõeldud tervislike retseptide järgi. Pead tugev püsima!'),
('d0842140-92ca-41c9-be61-ea76700b043c'::uuid,'Унутулгус көз ирмемдер 🖼️','Анын эң таттуу сүрөттөрүн ''Бөбөк альбомуна'' жүктөңүз жана аларды коопсуз сактаңыз, ошондо жылдар өткөндөн кийин бул баалуу көз ирмемдерди жылмаюу менен эстей аласыз.','Unustamatud mälestused 🖼️','Laadi beebialbumisse üles nende kõige armsamad fotod ja hoia need alles, et saaksid aastate pärast nendele väärtuslikele hetkedele naeratusega tagasi vaadata.'),
('4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e'::uuid,'Бүгүн өзүңүздү кандай сездиңиз? 💖','Эң чарчаган күндөрү да бөбөгүңүздүн бир жыты баарын унуттурат эмеспи? Бүгүнкү сезимдериңизди Маанай күндөлүгүнө жазып, эс алууга бир мүнөт бөлүңүз.','Kuidas sa end täna tundsid? 💖','Isegi kõige väsitavamatel päevadel paneb üks nuusutus su pisikesest kõik muu ununema, eks? Pane oma tänased tunded meeleolupäevikusse kirja ja leia hetk lõõgastumiseks.'),
('965bee4a-5d90-4c53-aa89-40a47df609d3'::uuid,'Убакыт менен тамактануу ⏱️','Тамактануу узарып жатабы? Тамактандыруу таймерин иштетип, убакытты башкарыңыз, балаңыздын тоюшун камсыз кылыңыз жана тамак тандап жеген адатын алдын алыңыз.','Toidukordade ajastamine ⏱️','Kas söögiaeg venib pikaks? Aktiveeri toitmistaimer, et hallata kestust, tagada piisav toidukogus ja aidata vältida pirtsutamist.'),
('ff2d08b5-7a14-4db2-985e-1998a959811b'::uuid,'Эртең мененки оюн убактысы 🧩','Келгиле, чогуу үйрөнөлү! 17,5 айлык балдардын таанып-билүү жөндөмүн өстүрүүчү оюндар тууралуу ''Блогдор'' бөлүмүндөгү макалабызды сөзсүз окуңуз.','Hommikune mänguaeg 🧩','Õpime koos! Loe kindlasti meie blogipostitust jaotisest ''Blogid'' mängude kohta, mis toetavad 17,5-kuuste laste kognitiivset arengut.'),
('276fc8e9-ee3f-4392-a41a-de859475f6f7'::uuid,'Сизди сүйөм кучагы 🫂','Бөбөгүңүз күтүлбөгөн жерден мойнуңузду кучактап же бетиңизден сылап жатабы? Ал эми сезимдерин физикалык түрдө көрсөтө баштады. Бул көз ирмемди баалаңыз.','Armastuse kallistused 🫂','Kas su pisike kallistab äkki su kaela või paitab su nägu? Nad näitavad nüüd oma kiindumust füüsiliselt. Naudi seda hetke.'),
('6d6ea5dd-3811-42ae-a92c-4f0473fafb88'::uuid,'Атасынын мээрими 🫂','Түнкүсүн ойгонгондо, жубайыңыз менен кезектешип туруңуз. Жүктү тең бөлүшүп, команда катары аракет кылыңыз.','Issi lohutab 🫂','Öiste ärkamiste ajal vahetage partneriga korda. Jagage koormust võrdselt nagu üks meeskond.'),
('87b2db95-d589-400c-8cce-c78da82f0fee'::uuid,'Аллергия боюнча кооптонуулар 🤖','Жаңы тамак берип, бети кызарганын байкадыңызбы? Кабатырлануудан мурун, биринчи кадамдарды Anacan AI аркылуу билип алыңыз.','Mured allergiate pärast 🤖','Tutvustasid uut toitu ja märkasid põskedel punetust? Enne kui muretsema hakkad, uuri esimesi samme Anacan AI-lt.'),
('85d64887-6099-4720-8a44-11c6766f10bb'::uuid,'Үйдө отуруп тажадыңызбы? ☕','''Энелер үчүн ыңгайлуу жайлар'' картасынан эс ала турган, ал эми бөбөгүңүз ойной турган жакынкы кафени табыңыз.','Tunned end kodus kinni? ☕','Avasta lähim kohvik meie ''Lapsesõbralike kohtade'' hulgast, kus saad ise hinge tõmmata ja su pisike saab mängida.'),
('aa709e76-dc89-4447-b36a-69ce62fbdfe6'::uuid,'Сиздин үнүңүздүн тонун түшүнөт 🗣️','Олуттуу түрдө ''жок'' дегенде, ал токтоп сизди карап жатабы? Ал эми эмоцияларды жана чек араларды толук түшүнүп калды. Ошол чектерди сактаңыз.','Mõistab sinu hääletooni 🗣️','Kas nad peatuvad ja vaatavad sulle otsa, kui ütled tõsisel toonil ''ei''? Nad mõistavad nüüd täielikult emotsioone ja piire. Jää nende piiride juurde.'),
('d09c606d-f7bf-4df1-900d-b7cc38d34313'::uuid,'Жарыкты басаңдатыңыз 🌙','Уйкуга 1 саат калганда үйдөгү бардык жарыктарды жана экрандарды өчүрүңүз. Мелатонин тынч чөйрөдө гана иштелип чыгат.','Hämarda tuled 🌙','Tund enne und lülitage kodus kõik eredad tuled ja ekraanid välja. Melatoniin eritub vaid rahulikus keskkonnas.'),
('7c968d48-84d9-4e6e-9f71-708f424d13fc'::uuid,'Уйку графиги ⏱️','Уктоо убактысы келди! Уйку таймерин иштетиңиз. Балаңыз күнүмдүк уйку нормасын алып жатканын текшерүү үчүн графикти талдаңыз.','Uneplaan ⏱️','On uneaeg! Aktiveeri unetaimer. Analüüsi graafikut, et veenduda, kas su pisike saab soovitusliku ööpäevase une kätte.'),
('83a23b90-6573-48f0-bd8e-9924821c611c'::uuid,'Өзүңүзгө кам көрүңүз 🥗','Бөбөгүңүздүн артынан чуркоодон чарчадыңызбы? Аялдар үчүн дени сак рецепттерибизден даамдуу жана энергия бере турган салат даярдаңыз.','Hoolitse enda eest 🥗','Oled väsinud oma pisikese tagaajamisest? Avasta maitsev ja koheselt energiat andev salatiretsept meie naistele mõeldud tervislike retseptide hulgast.'),
('e949f663-9f46-4fb4-8e24-07f0556f19ea'::uuid,'Эртең мененки тазалык 🧻','Бүгүнкү биринчи жалаяк алмаштыруу кандай өттү? Заң тууралуу маалыматты тиркемеге киргизип, балаңыздын ичеги-карын системасын оңой көзөмөлдөңүз.','Hommikune koristamine 🧻','Kuidas läks päeva esimene mähkmevahetus? Logi väljaheite info äppi ja jälgi hõlpsalt oma beebi seedesüsteemi tööd.'),
('317a6a9f-9ea0-4356-ac6b-713b806d7195'::uuid,'Таттуу эскерүүлөр 📸','Бөбөгүңүздүн бүгүн жасаган эң күлкүлүү жоругун ''Бөбөк альбомуна'' кошуңуз. Жылдар өткөндөн кийин бул көз ирмемдерди карап, абдан күлөсүз.','Magusad mälestused 📸','Lisa beebialbumisse kõige naljakam asi, mida su beebi täna tegi. Aastate pärast vaatad nendele hetkedele tagasi ja naerad südamest.'),
('c56a5aef-ad55-4a58-b85d-04ee040e2457'::uuid,'Төгүлбөй турган чөйчөк 🥤','Бөбөгүңүз жолдо суу ичкенди жакшы көрөбү, бирок дайыма кийимин суу кылып коёбу? ''Сунушталган товарлар'' бөлүмүнөн энелер тандаган эң ыңгайлуу чөйчөктөрдү карап көрүңүз.','Lekkekindel nokaga tass 🥤','Kas su pisikesele meeldib liikvel olles vett juua, aga ta teeb alati oma riided märjaks? Vaata emade poolt valitud kõige mugavamaid nokaga tasse meie ''Soovitatud toodete'' jaotises.'),
('e0699b25-a664-453e-b3a5-a31644bae458'::uuid,'Кийимдери кичирейип калды! 📏','Бөбөгүңүздүн кийимдери кайрадан кичинекей болуп калдыбы? Жаңы өлчөмдөрдү ''Салмак трекерине'' киргизип, анын боюнун жана салмагынын өсүү графигин сыймыктануу менен текшериңиз.','Riided jäävad väikeseks! 📏','Kas su pisikese riided on jälle lühikeseks jäänud? Sisesta uued mõõdud kaalujälgijasse ja vaata uhkusega nende pikkuse ja kaalu kasvu kasvukõveral.'),
('281783cf-f4b1-478b-9c23-4859307143e4'::uuid,'Өз алдынча ойноо убактысы 🧸','Ал эми оюнчуктар менен 10-15 мүнөт өз алдынча ойной алат. Бул анын көңүл буруу жөндөмүнүн өсүшү. Тынчтыктан ырахат алыңыз!','Iseseisev mänguaeg 🧸','Nad suudavad nüüd end 10-15 minutit mänguasjadega üksi tegevuses hoida. See on nende tähelepanuvõime pikenemine. Naudi vaikust!'),
('64f775c3-f09d-4993-a954-437681ccf730'::uuid,'Сыртта асман бүркөкпү? ⛅','''Аба ырайы жана кийим'' куралы аркылуу шамалдын ылдамдыгын дароо билип (терезеден көрүнбөсө да) жана эң ылайыктуу кийим тандоону сунуштайбыз.','Kas väljas on hall taevas? ⛅','Lase ilma ja riietuse tööriistal koheselt öelda tuule kiirus (isegi kui sa seda aknast ei näe) ja soovitada täiuslikku riietuse kombinatsiooni.'),
('6ca7a3a7-3202-4bdf-87de-b43d04388374'::uuid,'Укалоо убактысы 💆‍♂️','Бөбөк уктагандан кийин, күндүн чарчоосун басуу үчүн жубайыңыз экөөңүздөр бири-бириңиздерге ийинге массаж жасаңыздар. Сиздер бир командасыздар!','Massaaži aeg 💆‍♂️','Pärast seda, kui beebi on uinunud, tehke partneriga üksteisele õlamassaaži, et päeva pingetest vabaneda. Olete meeskond!'),
('23c1e329-cee4-4d43-89e7-04f3883f2a24'::uuid,'Витаминдик кошумча 🥦','Тамактанууну көзөмөлдөөчү курал аркылуу бүгүнкү менюну текшериңиз. Витаминдерди толуктоо керекпи? Биздин «Бөбөктөр үчүн рецепттер» бөлүмүндө сизди түстүү жана ар түрдүү тамактар күтөт!','Vitamiinilaks 🥦','Vaata tänast menüüd toitumispäeviku abil. Vajad vitamiinilisa? Meie beebiretseptide jaotisest leiad värvilisi ja mitmekesiseid toiduportsjoneid!'),
('2450b85b-f956-4dd3-b9ad-11b269818238'::uuid,'Наристеңиз кырсылдакпы? 🤖','Ал дайыма эле «жок» деп жатабы? 17,5 айлык бөбөгүңүздүн кыяңкечтигин жөнгө салуу үчүн Anacan AI жардамчыбыздан илимий негизделген психологиялык кеңештерди алыңыз.','Kas su väike laps on jonnakas? 🤖','Kas laps ütleb pidevalt „ei“? Küsi Anacan AI-lt teaduspõhist nõu, kuidas 17,5-kuuse lapse jonnihoogudega toime tulla.'),
('91b9e4eb-ca6a-4a90-94bc-2abf486852f9'::uuid,'Тынч кеч 🌊','Бөлмөдө тынч атмосфера түзүүчү убакыт келди. Бөбөгүңүздүн нерв системасы терең уйкуга өтүшү үчүн «Ак ызы-чуу» (White Noise) бөлүмүнөн деңиз толкундарынын үнүн коюңуз.','Rahulik õhtupoolik 🌊','On aeg luua toas rahustav õhkkond. Pane mängima „Valge müra“ ookeanilained, et aidata lapsel sügavasse unne suikuda.'),
('60f75637-7bb2-4f09-8e04-1616cc3f6b3a'::uuid,'Тамактануу убактысын изилдөө ⏱️','Тамактануу убактысы узарып баратабы? Тамактануу таймерин иштетип, ден соолукка пайдалуу чектен чыкпаңыз жана табиттин жоголушунун себептерин талдап көрүңүз.','Söömisaja avastamine ⏱️','Kas söögiaeg venib pikaks? Lülita sisse toitmise taimer, et püsida tervislikes piirides ja analüüsida võimalikke isutuse põhjuseid.'),
('8773c2dd-9938-4a61-a038-72940b1c0339'::uuid,'Күнүмдүк терапия 📝','Эне болуу кээде эмоционалдык сезимдердин куюну сыяктуу. «Маанай күндөлүгүн» ачып, бүгүн ичиңиздеги чарчоону кагазга төгүп, жеңилдеп алыңыз.','Igapäevane teraapia 📝','Emadus võib vahel tunduda emotsionaalse ameerika mägedena. Ava oma meeleolupäevik, kirjuta oma väsimus üles ja leia kergendus.'),
('da198266-6b56-4801-ac35-87e201ed0cda'::uuid,'Кофе ичүү убактысы! ☕','Төрт дубалдын ичинде отуруп тажадыңызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн балаңыз менен чогуу эс алууга боло турган кафени таап, маанайыңызды көтөрүңүз.','Kohviaeg! ☕','Tunned end nelja seina vahel kinni? Leia meie „Emadega sobivad kohad“ jaotisest kohvik, kuhu saad lapsega mugavalt minna ja tuju tõsta.'),
('0c27441c-12ef-47a7-9dc7-2b5ead6dd4a7'::uuid,'Үндү жөнгө салуу 🤫','Уйкунун алгачкы жарым сааты эң сезимтал учур. Үн өлчөгүч аркылуу чөйрөнү текшерип, күтүлбөгөн ызы-чуулардан сак болуңуз.','Helide haldamine 🤫','Esimene pooltund und on kõige tundlikum aeg. Kontrolli helitaseme mõõtjaga ümbrust ja väldi äkilisi helisid.'),
('cee8912e-bf87-4d52-b0d0-309e7583f3e5'::uuid,'Педиатрдан тез кеңеш 🤖','18 айлык бөбөгүңүздүн тил өнүктүрүүсү тынчсыздандырып жатабы? Анын курагына ылайыктуу сөздөрдү билүү үчүн Anacan AI жардамчысынан сураңыз.','Kiired lastearsti nõuanded 🤖','Muretsed oma 18-kuuse lapse keelelise arengu pärast? Küsi Anacan AI-lt, millised sõnad on selles vanuses tavapärased.'),
('52450380-67b2-4414-9193-af2b18f7264a'::uuid,'Өзүңүздү кубантыңыз 👏','Башаламан бөлмөгө эмес, анын бүгүнкү кубанычына көңүл буруңуз. Сиз эч бир китеп үйрөтө албаган укмуштуудай энесиз.','Tähista ennast 👏','Ära keskendu segadusele toas, vaid sellele, kui õnnelik laps täna on. Oled imeline ema viisil, mida ükski raamat õpetada ei suuda.'),
('c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d'::uuid,'Таймер менен уйкуну көзөмөлдөө ⏱️','Күндүзгү уйкусу кыскарып баратабы? Уйку таймерин иштетип, ушул аптадагы тартипти талдап, анын жатар убактысын кайра карап чыгыңыз.','Une jälgimine taimeriga ⏱️','Kas päevane uni jääb lühemaks? Käivita unetaimer, analüüsi nädala graafikut ja kohanda lapse uneaega.'),
('fda065c2-2893-4c1e-858b-19c095a29529'::uuid,'Бири-бириңиздерди колдоңуздар! 💖','Оор күндөн кийин жолдошуңуз менен отуруп, сүйлөшүп алыңыз. Бири-бириңизди колдоо — жүктү эки эсе жеңилдетет.','Toetage üksteist! 💖','Pärast keerulist päeva istu koos partneriga maha ja rääkige asjad selgeks. Üksteise toetamine poolitab koorma.'),
('815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b'::uuid,'Акыл-эс өнүгүүсү 🧠','Бөбөгүңүздүн мээсинде эмне болуп жатат? 17-18 айлык балдардын таанып-билүү жөндөмүнүн өнүгүүсү тууралуу «Блогдор» бөлүмүндөгү акыркы макаланы окуңуз.','Arenguhüpe 🧠','Mis toimub sinu beebi ajus? Loe „Blogide“ jaotisest uusimat artiklit 17–18-kuuste laste kognitiivse arengu kohta.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('87dc449d-a56d-419b-bdab-000fd5ed38fd'::uuid,'Уйку графиги ⏱️','Ойгонуу убактысы өзгөрдүбү? Уйку таймеринин статистикасын текшерип, күндүзгү жана түнкү уйкунун ортосундагы эң сонун тең салмактуулукту талдаңыз.','Uneplaan ⏱️','Kas lapse ärkamisajad on muutunud? Analüüsi päevase ja öise une tasakaalu, kontrollides unetaimeri statistikat.'),
('4c6d197d-5cde-42e9-b88b-05a62b37e397'::uuid,'Эртең мененки ичегинин иштеши тууралуу отчет 💩','Тамак сиңирүү системасы — ден соолуктун биринчи көрсөткүчү. Жоолук алмаштырганда, тиркемеге заңдоосу тууралуу белгилеп, күн ичиндеги өзгөрүүлөргө көз салып туруңуз.','Hommikune potiraport 💩','Seedimine on esimene tervise näitaja. Lisa mähkmeid vahetades rakendusse märkmeid väljaheite kohta ja jälgi muutusi päeva jooksul.'),
('e59af63b-a407-459e-a6f1-a0263d9f74f5'::uuid,'Кичинекей жылдызча 🌟','Ал таттуу жылмаюуну өткөрүп жибербеңиз! «Бөбөктөрдү сүрөткө тартуу» куралындагы кызыктуу темалар менен бүгүнкү маанайды түбөлүккө сактап калыңыз.','Väike täheke 🌟','Ära maga maha seda armsat naeratust! Jäädvusta tänane meeleolu lõbusate teemadega „Beebi fotosessiooni“ tööriistas.'),
('f71b2bf0-976d-4844-8538-db17781ce999'::uuid,'Өзүңүзгө убакыт бөлүңүз 🍵','Бөбөгүңүз уктап жатканда, өз денеңизди калыбына келтирүү кезеги сиздики. Пайдалуу рецепттерден тынчтандыруучу чөп чайын демдеп ичиңиз.','Leia aega endale 🍵','Beebi magab, nüüd on sinu kord end kosutada. Valmista tervislike retseptide järgi üks rahustav taimetee.'),
('91d67474-6689-4302-b69e-a9b260aedef7'::uuid,'Туура оюнчукту тандоо 🧩','Таанып-билүү жөндөмүн өстүрүүчү оюнчуктарды издеп жатасызбы? «Сунушталган товарлар» бөлүмүнөн курагына ылайыктуу жана пайдалуу пазлдарды табыңыз.','Õige mänguasja valimine 🧩','Otsid mänguasju kognitiivse arengu toetamiseks? Avasta „Soovitatud toodete“ jaotisest eakohaseid ja kasulikke puslesid.'),
('c5a6eac8-e59c-4b94-98cf-eb7be52db9a2'::uuid,'Уйку алдындагы тартип 🌙','Бөбөгүңүздү күн сайын бир убакта уктатуу жакшы адатты калыптандырат. Уйку таймерин колдонуп, анын тартибин текшерип, тынч уйкудан ырахат алыңыз.','Uinumisrutiin 🌙','Lapse igapäevane samal ajal magamapanek loob hea harjumuse. Kasuta unetaimerit, kontrolli rutiini ja naudi rahulikku und.'),
('e8b020dc-c4fe-4f5b-946a-28ae84382a39'::uuid,'Дени сак жана күчтүү өсүү 📈','Дээрлик 18 ай! «Салмакты көзөмөлдөө» куралы аркылуу анын өсүү темпин талдап, бою менен салмагы нормада экенин текшериңиз.','Kasvades tugevaks ja terveks 📈','Peaaegu 18 kuud! Analüüsi lapse kasvutempot kaalujälgija abil ja kontrolli, kas pikkus ja kaal on eakohased.'),
('ab02b4ce-b2c3-41bc-a1aa-f97787c0ba17'::uuid,'Күндүн эң сонун аягы 🖼️','Бул өзгөчө күндү (540 күн!) бирге түшкөн эң бактылуу жана жылуу сүрөтүңүздү «Бөбөк альбомуна» кошуп, түбөлүккө сактаңыз.','Päeva täiuslik lõpp 🖼️','Jäädvusta see eriline päev (540 päeva!) ja lisa beebialbumisse teie kõige õnnelikum ja soojem ühine foto.'),
('c1dc4453-41a2-40e6-812c-73fb934ccc70'::uuid,'Сиз чыныгы баатырсыз! ✨','Энелик сапарыңыздын 540-күнү! Күнүмдүк жетишкендигиңиз менен Anacan AI менен бөлүшүңүз, ал сизге күнүңүздү жаркыратуу үчүн өзгөчө дем берет.','Oled kangelane! ✨','Sinu emadusteekonna 540. päev! Jaga oma igapäevaseid saavutusi Anacan AI-ga ja lase sel end motiveerida.'),
('fa1d5820-5e14-435d-81d1-df116bd7de6f'::uuid,'Үй-бүлөлүк тамактануу 🍲','Ал эми сиз жеген тамактарды жей алат! «Тамактанууну көзөмөлдөөчү» курал менен биргелешкен тамактарыңыздын азыктык баалуулугун оңой эсептеңиз.','Pere ühine söögiaeg 🍲','Laps saab nüüd süüa sama toitu mis sina! Arvuta toitumispäeviku abil hõlpsalt ühiste toidukordade toiteväärtus.'),
('4f770f32-235d-4481-acc9-8a3353f11910'::uuid,'Эмнелер ойлондуруп жатат? 🤔','Тамактан баш тартып жатабы? Каалаган сурооңузду Anacan AI жардамчысына берип, дароо так жана эксперттик жооп алыңыз.','Mis sul mõttes on? 🤔','Keeldub äkki söömisest? Esita Anacan AI-le mis tahes lapsevanemaks olemisega seotud küsimus ja saa koheseid asjatundlikke vastuseid.'),
('996b9423-cc50-4ec2-bbf6-02866083bb10'::uuid,'Уйкуга жеңил өтүү 🎶','Активдүү ачылыштарга толгон күндөн кийин уктата албай жатасызбы? «Ак ызы-чуу» бөлүмүнөн бешик ырын тандап, бөлмөдө сыйкырдуу тынчтык орнотуңуз.','Lihtne uinumine 🎶','Ei saa pärast aktiivset avastamist täis päeva magama jääda? Vali „Valgest mürast“ hällilaul ja loo tuppa maagiline rahu.'),
('9d8ea18e-9c4f-4f0b-9883-a708f0ed884b'::uuid,'Жаратылышты таанып-билүү 🍂','Таза аба экөөңүзгө тең пайдалуу. «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн жаңы сейил бак таап, бөбөгүңүзгө чуркап, энергиясын чыгарууга мүмкүнчүлүк бериңиз.','Looduse avastamine 🍂','Värske õhk tuleb teile mõlemale kasuks. Leia meie „Lapsesõbralike asukohtade“ kaardilt uus park ja lase lapsel vabalt ringi joosta ning energiat kulutada.'),
('19f1aa58-50a6-4acf-b375-1d03850cfcb6'::uuid,'Ички үнүңүз 💖','Сиз идеалдуу эне болууга милдеттүү эмессиз; сиз балаңыз үчүн эң мыктысыз. Бүгүн «Маанай күндөлүгүнө» сезимдериңизди жазып, жеңилдеп алыңыз.','Sinu sisemine hääl 💖','Sa ei pea olema täiuslik ema; oled oma lapse jaoks parim. Pane oma tunded täna meeleolupäevikusse kirja ja leia veidi kergendust.'),
('6cc2d53f-bf34-4dcd-9edd-bf3d05a35b98'::uuid,'Өз алдынча тамактануу таймери ⏱️','Өзү тамактанууга аракет кылып жатабы? Башаламандыктан коркпоңуз! Тамактануу таймерин иштетип, бул көз карандысыздыкка канча убакыт кетерин талдаңыз.','Ise söömise ajastamine ⏱️','Kas laps proovib ise süüa? Lepi segadusega! Käivita söötmise taimer ja analüüsi, kui kaua see iseseisvumine aega võtab.'),
('f869363f-52a1-4240-a759-b2b999d347e4'::uuid,'Пайдалуу таттуулар 🍪','Дүкөндөн алынган таттуулардын кереги жок. Биздин «Рецепттер» бөлүмүнөн кошумча тамакка өтүп жаткан бөбөктөр үчүн шекерсиз, даамдуу печеньелерди даярдаңыз.','Tervislikud suupisted 🍪','Poest ostetud maiustusi pole vaja. Valmista meie retseptide järgi lihtsaid, suhkruvabu ja maitsvaid küpsiseid, mis sobivad suurepäraselt tahke toiduga alustavale lapsele.'),
('ae531928-8e01-4e71-961a-63a517eaee5a'::uuid,'Терең уйкуга өтүү 🌙','Уйку таймерин иштетиңиз. Эгер түнкүсүн ойгонуу көбөйсө, «Ак ызы-чуу» бөлүмүнөн деңиз толкундарынын үнү менен анын нерв системасын тынчтандырыңыз.','Sügava une faas 🌙','Aktiveeri unetaimer. Kui öised ärkamised sagenevad, rahusta lapse närvisüsteemi „Valge müra“ ookeanilainetega.'),
('bacdcc71-8211-4dd5-b3af-c5af34fb468a'::uuid,'Эртең мененки сюрприз 💩','Бөбөгүңүздүн күн ичиндеги биринчи жоолук алмаштыруусун белгилегенди унутпаңыз! Бул анын өсүп жаткан организминин тамак сиңирүүсүнө жана суу балансына көз салуунун эң сонун жолу.','Hommikune üllatus 💩','Ära unusta märkida lapse päeva esimest mähkmevahetust! See on suurepärane viis jälgida oma kasvava lapse seedimist ja vedeliku tarbimist.'),
('e207d666-c361-4203-8076-7ba835d4f015'::uuid,'Кашык менен тамактанууну үйрөнүүдөбү? 🥄','Тамактануу таймерин иштетиңиз. Өз алдынча тамактануу аракеттери канча убакыт алаарын талдап, күнүмдүк тамактануу боюнча сунуштарды карап чыгыңыз.','Kas lusikas on juba käpas? 🥄','Lülita sisse söötmise taimer. Analüüsi, kui kaua iseseisvad söömiskatsed aega võtavad, ja vaata üle igapäevased toitumissoovitused.'),
('35587de2-b62b-435c-aca4-01e72314423a'::uuid,'Сезимдериңизди билдириңиз 📝','Ар бир күн идеалдуу болбойт, бул кадыресе көрүнүш. Бүгүн «Маанай күндөлүгүнө» сезимдериңизди жазып, стресстен арылыңыз жана тынч эс алыңыз.','Väljenda oma tundeid 📝','Iga päev ei pea olema täiuslik ja see on täiesti normaalne. Kirjuta oma tunded täna meeleolupäevikusse, vabane stressist ja puhka rahulikult.'),
('da88924f-9b7a-4cc5-9b9e-429e9d903edd'::uuid,'Өзүңүздү сыйлаңыз ☕','18 айлык бөбөктүн энеси болуу оңой эмес! «Энелер үчүн ыңгайлуу жайлар» картасынан жайлуу кафе таап, өзүңүзгө жылуу кофе менен сый көрсөтүңүз.','Hellita ennast ☕','18-kuuse lapse emaks olemine pole kerge! Leia meie „Lapsesõbralike asukohtade“ kaardilt hubane kohvik ja premeeri end sooja kohviga.'),
('6b77a02d-8882-4aed-be91-5f8ce3841671'::uuid,'Аракетке даярсызбы? 👟','Биринчи ишенимдүү кадамдар үчүн туура бут кийим абдан маанилүү! «Сунушталган товарлар» бөлүмүнөн энелер эң жакшы көргөн ортопедиялык моделдерди табыңыз.','Valmis tegutsema? 👟','Õiged jalanõud on esimeste kindlate sammude jaoks üliolulised! Avasta emade poolt enim armastatud ortopeedilised mudelid jaotises „Soovitatud tooted“.'),
('d6d681fb-3d1d-40b8-84c0-e3cd64921f6e'::uuid,'Таттуу көз ирмемдер 📸','Чуркап баратып жыгылып, анан күлүп жатабы? Бул сүйкүмдүү учурду дароо «Бөбөк альбомуна» кошуп, келечек үчүн түстүү жана өмүр бою эсте кала турган эскерүүгө айлантыңыз.','Armsad hetked 📸','Kukkusid jooksmise ajal ja hakkasid naerma? Lisa see armas hetk kohe beebialbumisse ja muuda see värviliseks, elukestvaks mälestuseks.'),
('e2aefd08-9263-41a3-87d4-c2d0378c7526'::uuid,'Темирдин деңгээли кандай? 🥩','Бөбөгүңүз бүгүн жетиштүү темир алдыбы, «Тамактанууну көзөмөлдөөчү» курал аркылуу текшериңиз. Эгер жетишсиз болсо, «Бөбөктөр үчүн рецепттер» бөлүмүнөн темирге бай варианттарды караңыз.','Kuidas on lood sinu rauavarudega? 🥩','Kasuta toitumisjälgijat, et näha, kas su väike laps on täna piisavalt rauda saanud. Kui esineb puudujääke, uuri meie beebiretsepte, mis on rauast rikkad.'),
('48983c78-1769-4320-a7cf-ba470eef1415'::uuid,'Сиздин өзгөчө окуяңыз 🪄','«Акылдуу жомоктор» бөлүмүндө балаңыз башкы каарман болгон өзгөчө окуяны түзүңүз: «1,5 жашар изилдөөчүнүн укмуштуу окуялары».','Sinu eriline lugu 🪄','Loo nutikate lugude (Smart Tales) abil eriline lugu, kus sinu laps on kangelane: „1,5-aastase avastaja seiklused“.'),
('9815225a-8bb2-4fd7-93dd-34bcbbda8ac0'::uuid,'Чың ден соолукта өсө бериңиз! 🌟','Бөбөгүңүз эми 18 айдан ашты! Өз алдынча баскан, сезимдерин билдирген, кээде кыяңкеч, бирок чексиз сүйүүгө толгон бала менен жаңы доор башталат!','Kasva ikka edasi! 🌟','Sinu väike laps on nüüd üle 18 kuu vana! Algab uus ajastu lapsega, kes kõnnib iseseisvalt, väljendab emotsioone, võib olla kangekaelne, kuid on uskumatult armastav!'),
('cdca9fee-71e1-4e46-aea7-41734d6fa68a'::uuid,'18 айлыктагы уйкунун бузулушубу? 🥱','Уйкуга каршылык көрсөтүп же түнкүсүн ойгонуп жатабы? Бул белгилүү «уйку регрессиясы» болушу мүмкүн. Бул биологиялык процесс тууралуу Anacan AI жардамчысынан илимий маалымат алыңыз.','18. kuu unehäired? 🥱','Kas laps võitleb une vastu või ärkab öösel? See võib olla tuntud uneregressioon. Hangi Anacan AI-lt teaduslikke teadmisi selle bioloogilise protsessi kohta.'),
('be8b4ec7-a61e-4f60-ae12-bdc8b7beda03'::uuid,'«Өзүм жасайм!» баскычы 🛑','Бөбөгүңүз баарын, атүгүл кооптуу буюмдарды да кармагысы келет. Эгер тартып алсаңыз, бороон-чапкынга даяр болуңуз! «Жок» дебей, анын көңүлүн кызыктуураак нерсеге бурууга аракет кылыңыз.','„Teen ise!“ faas 🛑','Sinu väike laps tahab kõike haarata, isegi ohtlikke esemeid. Valmistu tormiks, kui proovid seda ära võtta! Selle asemel, et öelda „ei“, proovi suunata tema tähelepanu millelegi köitvamale.'),
('d6508b29-e914-4995-93c3-58c73e271159'::uuid,'Массаж жана тынчтык 💆‍♀️','Күнү бою бөбөгүңүздүн артынан чуркап, белиңиз ооруп жатабы? Бала уктагандан кийин жолдошуңуздан 10 мүнөттүк ийин массажын сураңыз. Сиз буга татыктуусуз!','Massaaž ja vaikus 💆‍♀️','Kas selg on terve päeva lapse tagaajamisest valus? Palu partneril teha 10-minutiline õlamassaaž pärast seda, kui laps on uinunud. Sa väärid seda!'),
('dd068a2e-5d54-49f1-be6d-02db7c690974'::uuid,'Сиз дайыма кыймылдасыз! 🏃‍♂️','Ал бөлмөдөн бөлмөгө чексиз энергия менен чуркап жүрөбү? Бул күндөрү анын тең салмактуулугу тез өнүгүүдө. Үйүңүздү коопсуз кылып, бул энергиялуу көз ирмемдерди жөн гана карап ырахат алыңыз.','Oled hoos! 🏃‍♂️','Kas ta kihutab lõputu energiaga toast tuppa? Tema tasakaal areneb nendel päevadel kiiresti. Veendu, et kodu oleks lapsekindel, ja naudi lihtsalt nende energiliste hetkede vaatamist.'),
('e1121d1f-a680-4fb9-9a1f-6792cb16e172'::uuid,'Мөмө-жемиштер менен болгон мамиле 🍎','Кечээ жакшы көргөн алма бүгүн полдогу жасалгага айландыбы? Тамак тандап жеш — бул курактагы кадимки көрүнүш. Интернеттен чексиз издөөлөрдү токтотуп, биздин тиркемеден жемиштерди кызыктуу сунуштоо жолдорун жана пайдалуу рецепттерди табыңыз.','Puuviljade põlgus 🍎','Eilne lemmikõun on täna põrandakaunistus? Valiv söömine on selles vanuses klassikaline väljakutse. Jäta lõputud veebiotsingud ja leia meie äpist lõbusad puuviljade serveerimisviisid ning tervislikud retseptid.'),
('ef76ecee-5471-407a-a72c-9593be1406af'::uuid,'Сүйлөшүүлөр узарып баратат 🗣️','Ойгонору менен өзүнүн тилинде сайрап жатабы? Анын тил борбору өнүгүүнүн туу чокусунда. Кунт коюп угуп, «Чын элеби?» же «Анан эмне болду?» сыяктуу кызыктуу суроолор менен жооп бериңиз.','Vestlused muutuvad pikemaks 🗣️','Kas ta lobiseb kohe ärgates oma ainulaadses keeles? Tema keelekeskus läbib arenguplahvatust. Kuula tähelepanelikult ja vasta kaasahaaravate küsimustega, nagu „Päriselt?“ või „Mis edasi sai?“'),
('1bf2c33f-3711-4208-8da6-0a931502b566'::uuid,'Толук караңгылык 🌙','Бөбөгүңүз уйкуга каршылык көрсөтүп жатабы? Кичинекей жарык да алаксытышы мүмкүн. Мелатониндин иштелип чыгышын жогорулатуу үчүн бардык экрандарды өчүрүп, бөлмөнү толугу менен караңгылатыңыз.','Täielik pimedus 🌙','Kas su väike laps võitleb une vastu? Isegi väike valgus võib segada. Lülita kõik ekraanid välja ja tee tuba täiesti pimedaks, et soodustada melatoniini tootmist.'),
('7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f'::uuid,'Жымжырттыктан чочулоо','Ал бөлмөдө сүрөттөрдү тынч карап отурат, үйдө терең жымжырттык. Бирок сиз бул тынчтыктан шек санап, ар дайым кырсык күтөсүз. Эс алыңыз. Кээде алар да жалгыз калгысы келет. Артка чалкалап отуруп, бул сейрек кездешүүчү тынч көз ирмемден ырахат алыңыз.','Vaikusepaanika','Ta vaatab vaikselt toas pilte ja majas valitseb sügav vaikus. Kuid sa kahtlustad seda vaikust ja ootad igal hetkel katastroofi. Lõõgastu. Mõnikord tahab temagi omaette olla. Toetu seljaga vastu tooli ja naudi seda haruldast hetke omaette.'),
('5f000b16-6031-438b-92a6-3ea1d69ae68b'::uuid,'Энелик унутчаактык кайра келдиби? 🛒','Жоолук же йогурт түгөнүп калдыбы? Башыңызды оорутпаңыз! Аны дароо «Соода тизмесине» кошуп коюңуз, ошондо жолдошуңуз үйгө келе жатып алып келе алат.','Emme aju streigib jälle? 🛒','Mähkmed või jogurt said otsa? Ära vaeva oma pead! Lisa see kohe ostunimekirja, et partner saaks selle kojutulekul kaasa osta.'),
('561010fd-17de-4698-b582-1c91bc73389a'::uuid,'Жөн гана кучактап коюңуз 🫂','Эч кандай кымбат гаджеттердин, китептердин же жомоктордун кереги жок. Бүгүн кечинде аны көкүрөгүңүзгө кысып, таттуу жытын жыттап, караңгылыкта ага болгон сүйүүңүздү шыбырап айтыңыз.','Lihtsalt kallista 🫂','Pole vaja mingeid uhkeid vidinaid, raamatuid ega muinasjutte. Täna õhtul lihtsalt hoia teda tihedalt oma rinna vastas, hinga sisse tema magusat lõhna ja sosista talle vaikuses oma armastust.'),
('8593e3b3-5794-49a0-a5ef-d04af1bd53a7'::uuid,'Китептердеги майда-чүйдөлөр 📖','Кичинекейиңиз китептерди барактап, сүрөттөрдөгү эң майда деталдарды (мисалы, кичинекей кушту) көрсөтүп жатабы? Бул таанып-билүү жөндөмүн «Өсүү трекерине» жазып коюңуз. Анын визуалдык эс тутуму укмуштуудай иштеп жатат!','Detailid raamatutes 📖','Kas su pisike sirvib raamatuid ja näitab piltidel isegi kõige pisematele detailidele (nagu väike lind)? Märgi see kognitiivse arengu verstapost kasvu jälgijasse. Tema visuaalne mälu teeb imesid!'),
('5df90283-8938-4f2c-bc5d-95fad0d0249f'::uuid,'Уйку графигин текшерели ⏱️','Уйкуга жаткыруу кыйын болуп жатабы? Анын уйку графигин карап чыгыңыз. Балким, күндүзгү уйкусун бир аз кыскартуу жетиштүү болор.','Kontrollime uneaega ⏱️','On magamaminekuga raskusi? Vaata üle tema uneplaan. Võib-olla piisab vaid veidi lühemast päevauinakust.'),
('eb685812-a20b-4dfa-8dcd-a8c0865f1a25'::uuid,'Эненин энергиясы 🔋','Өзүңүздү да унутпаңыз, апа! «Рецепттер» бөлүмүнөн тез даярдалуучу, даамдуу жана белокко бай эртең мененки тамакты тандаңыз.','Emme energia 🔋','Ära unusta iseennast, emme! Vali meie retseptide sektsioonist kiire ja maitsev valgurikas hommikusöök.'),
('f80fa225-e7f6-4b7d-a7da-b651f5688ba0'::uuid,'«Жок!» баскычы 🛑','Кичинекейиңиз баарына каршы чыгып жатабы? 1,5 жаштагы балдардын «кыйын мезгилин» (же наристелердин өжөрлүгүн) жеңүү боюнча психологиялык колдоо жана чечимдер үчүн Anacan AI жардамчыбызга кайрылыңыз.','„Ei!“ faas 🛑','Kas su väike põngerjas protestib kõige vastu? Konsulteeri meie Anacan AI-assistendiga, et saada psühholoogilist tuge ja lahendusi 1,5-aastaste nn trotsiea (või väikelapse jonni) ületamiseks.'),
('bd224607-0812-4b81-8b5d-af59d7d7cc10'::uuid,'Витаминдик заряд 🥗','Апанын энергиясы эч качан түгөнбөшү керек! Аялдар үчүн атайын иштелип чыккан пайдалуу рецепттерибизден заматта энергия бере турган даамдуу смузи жасап ичиңиз.','Vitamiinilaks 🥗','Emme energia ei tohiks kunagi otsa saada! Valmista kiirelt energiat andev ja maitsev smuuti meie naistele mõeldud tervislike retseptide järgi.'),
('c9435c7a-e56d-449f-9eb8-fae0dc263176'::uuid,'Уйку алдындагы ырым-жырым 🌙','Уйку таймерин иштетип, бөлмөнүн жарыгын басаңдатыңыз. Ар күнү кечинде уйкунун туруктуу тартибин оңой орнотуу үчүн графикке талдоо жүргүзүңүз.','Uinumisrituaal 🌙','Lülita sisse unetaimer ja hämarda tuba. Analüüsi ajakava, et luua igal õhtul vaevata järjepidev magamaminekurutiin.'),
('ffe1377d-426e-4c3f-a06d-3551b2ee446b'::uuid,'Билим берүүчү оюнчуктар 🧩','18 ай — логикалык оюндар үчүн эң сонун курак. Акыл-эсин өстүрүү үчүн «Сунушталган товарлар» бөлүмүнөн куракка ылайыктуу пазлдарды жана кубиктерди карап көрүңүз.','Õpetlikud mänguasjad 🧩','18 kuud on ideaalne vanus loogikamängudeks. Uuri soovitatud toodete alt eakohaseid puslesid ja klotse, et tema mõtlemist teritada.'),
('10d89b1a-052c-42d7-9604-a8aa080e3159'::uuid,'Үй-бүлөлүк тамактануунун кубанычы 🍲','Кичинекейиңиз эми сиз менен чогуу дасторконго отура алат! Кошумча тамакка өтүүчү балдар үчүн рецепттерибизди карап чыгып, бүт үй-бүлө үчүн пайдалуу тамакты тандаңыз.','Perega koos söömise rõõm 🍲','Sinu väike ime saab nüüd täielikult sinuga õhtusöögilauas liituda! Tutvu meie tahkest toidust alustavate beebide retseptidega ja vali ühine tervislik eine kogu perele.'),
('25077620-39e7-49c9-abd7-7ee3d4c9f4a5'::uuid,'Ичегинин саламаттыгын текшерүү ⏱️','«Жоолук (подгузник) трекерине» күнүмдүк өзгөрүүлөрдү киргизүү менен, балаңыз жетиштүү суюктук жана клетчатка алып жатканын оңой эле байкай аласыз.','Seedimise kontroll ⏱️','Märkides igapäevaseid muutusi mähkmete jälgijasse, saad hõlpsalt analüüsida, kas beebi saab piisavalt vedelikku ja kiudaineid.'),
('94fb4891-ca2e-4e41-b663-ea23a832df89'::uuid,'Жамгырдын тынчтандыруучу үнү 🌧️','Чарчаңкы күн кичинекей балдардын мээсин ашыкча чарчатышы мүмкүн. Бөлмөдө уйкуну чакыруучу жагымдуу маанай түзүү үчүн «Ак ызы-чуу» (White Noises) бөлүмүнөн жамгырдын жумшак добушун иштетиңиз.','Rahustav vihmasabin 🌧️','Tihe päev võib pisikesi ajusid üle stimuleerida. Pane mängima valge müra alt õrn vihmasabin, et luua tuppa täiuslikult rahustav ja und soodustav atmosfäär.'),
('02d8aef9-6d63-4748-9f41-c063ee842eb2'::uuid,'Сиз муну жасай аласыз! 💖','Өзүңүздү чарчаңкы сезип жатасызбы? «Маанай күндөлүгүн» ачыңыз. Жөн гана «Мен муну жеңе алам» деп жазып, өзүңүзгө эс алууга уруксат бериңиз.','Sa saad hakkama! 💖','Tunned end kurnatuna? Ava oma meeleolupäevik. Kirjuta lihtsalt „Ma saan hakkama“ ja luba endal lõõgastuda.'),
('04fca8dd-97bb-4af2-93b5-030f318cd3da'::uuid,'Жаратылышты изилдөө 🌳','Үйүңүздүн дубалдары кичинекей изилдөөчүңүзгө тардык кылып жатабы? Ал энергиясын сарпташы үчүн «Апалар үчүн ыңгайлуу жайлар» бөлүмүнөн кенен жана коопсуз сейил бактарды табыңыз.','Looduses avastamas 🌳','Kas kodu seinad tunduvad sinu väikesele avastajale juba veidi kitsaks jäävat? Leia meie emmesõbralike kohtade hulgast avar ja turvaline park, kus ta saab energiat kulutada.'),
('7306940e-101e-4de4-af72-da4ab6736ad8'::uuid,'Тамактануу таймери ⏱️','Балаңыз тамак жегенден көрө аны менен ойногонду жакшы көрөбү? Ал дасторкондо канча убакыт отурганын көзөмөлдөө жана табит үлгүлөрүн талдоо үчүн «Тамактануу таймерин» колдонуңуз.','Söömisaja taimer ⏱️','Kas su laps mängib toiduga rohkem kui sööb? Kasuta söötmise taimerit, et jälgida laua taga veedetud aega ja analüüsida tema söögiisu mustreid.'),
('07b5d33a-c674-4dcc-a023-81e3746cb054'::uuid,'Логикалык оюндар 🧱','Ал мунара куруу үчүн 4-5 кубикти бири-биринин үстүнө тизип жатабы? Бул майда моторикадагы ийгиликти «Өнүгүү трекерине» жазып коюңуз! Анын кичинекей инженердик аракетин мактоону унутпаңыз.','Loogikamängud 🧱','Kas ta virnastab juba 4-5 klotsi, et torni ehitada? Salvesta see peenmotoorika võit arengu jälgijasse! Ära unusta tema väikeseid inseneripüüdlusi kiita.'),
('be5acfb3-03f0-4bea-9e14-40b38bca8262'::uuid,'Атанын түнкү нөөмөтү 👨‍🍼','Түнкүсүн ойгонуу менен жалгыз күрөшпөңүз. Өнөктөшүңүздү да ойготуңуз — команда болуу жоопкерчиликти бөлүшүүнү билдирет. Бүгүн түнү аны сооротуу ишин өнөктөшүңүзгө тапшырыңыз.','Issi öövahetus 👨‍🍼','Ära tegele öiste ärkamistega üksi. Ärata ka oma partner – meeskonnatöö tähendab vastutuse jagamist. Las täna rahustab tema.'),
('fa9c7680-afc6-4095-9ec3-d56ad432d989'::uuid,'Бүгүн сейил бакка барасызбы же үйдөсүзбү? ⛅','Сыртка чыккыңыз келеби, бирок аба ырайы өзгөрүлмөлүүбү? Биздин «Аба ырайы жана кийим тандоо жардамчыбыз» сизге температураны гана эмес, кичинекейиңизди шамалдан коргой турган кийимдерди да сунуштайт.','Parki või koju täna? ⛅','Tahad välja minna, aga ilm on heitlik? Lase meie ilma- ja riietumisassistendil öelda mitte ainult temperatuuri, vaid ka seda, milliseid tuulekindlaid riideid oma pisikesele selga panna.'),
('22efa7bf-186e-41c7-b46c-b75ce17b0a09'::uuid,'Эртең мененки сергектик 💧','Күндүн биринчи жоолугун алмаштырдыңызбы? Балаңыздын суюктук ичүүсү жетиштүү экенин көзөмөлдөө үчүн бөлүп чыгаруу маалыматтарын тиркемеге жазып туруңуз.','Hommikune värskus 💧','Vahetasid päeva esimese mähkme? Salvesta eritusandmed äppi, et hõlpsalt jälgida, kas vedeliku tarbimine on piisav.'),
('37e7b0b1-141f-488d-99c8-a87bde73955f'::uuid,'Тамактануу учурундагы кежирликтер 🥣','Тамак жебей жатабы? Мажбурлоонун ордуна, тарелкасына түстүү жашылчаларды кооздоп коюп, анын кызыгуусун ойготуп көрүңүз. Пайдалуу рецепттерибизден жаңы идеяларды табыңыз.','Söömisaja jonnihood 🥣','Keeldub söömast? Sundimise asemel proovi äratada tema huvi, sättides taldrikule värvilisi köögivilju. Leia värskeid ideid meie tervislikest retseptidest.'),
('5ae1647c-ec81-4db7-838c-66f57619dd06'::uuid,'Үндү башкаруу 🤫','Уйкуга даярданып жатканда, «Добуш өлчөгүч» менен бөлмөдөгү ызы-чуунун деңгээлин көзөмөлдөңүз. Түнкүсүн уйкунун үзгүлтүккө учурашы анын өнүгүүсүнө да, эртеси эртең мененки маанайыңызга да терс таасирин тийгизиши мүмкүн.','Helide haldamine 🤫','Magamaminekuks valmistudes hoia helitaseme mõõdikuga silm peal toa müratasemel. Öine katkendlik uni võib pärssida nii lapse arengut kui ka sinu järgmise hommiku tuju.'),
('2e177a88-e995-4df3-ae19-8a1044979006'::uuid,'Музыкалык кечелер 🎶','Кечки маанайсыздыкты басуунун эң оңой жолу — анын сүйүктүү ырын коюп, кучактап, бийлөө.','Muusikalised õhtud 🎶','Kõige lihtsam viis õhtust jonnimist rahustada on panna mängima tema lemmiklugu, hoida teda lähedal ja tantsida.'),
('82b5cb21-ea7e-4957-9166-81471c0b098a'::uuid,'Эмне үчүн алар мындай кылып жатышат? 🤖','Ал «кыйын мезгилдеги» өжөрлүгүн эрте көрсөтө баштадыбы? Эксперттик психологиялык ыкмаларды жана күрөшүү стратегияларын үйрөнүү үчүн дароо Anacan AI жардамчысына кайрылыңыз.','Miks nad nii teevad? 🤖','Kas need „kohutavad kaheaastased“ jonnihoogud algavad varem? Konsulteeri kohe Anacan AI-ga, et õppida asjatundlikke psühholoogilisi lähenemisi ja toimetulekustrateegiaid.'),
('8aa141ab-420e-4a45-9eba-7dddd2430cb1'::uuid,'Кантсыз энергия 🍌','Түштөн кийин таттуу жегиңиз келип жатабы? Балдар үчүн рецепттерибиздеги банан жана сулу кошулган пайдалуу тамактар менен туура тамактанууну сактаңыз.','Suhkruvaba energia 🍌','Tekkis isu pärastlõunase maiuse järele? Hoia toitumine kontrolli all meie beebiretseptide hulgast pärit tervislike banaani- ja kaerahelbesnäkkidega.'),
('2d802010-e9c4-4370-b595-862f19214f3d'::uuid,'Кальций булагы 🧀','Кальций тиштердин жана сөөктөрдүн бекем болушу үчүн өтө маанилүү. Күнүмдүк сүт азыктарын жетиштүү өлчөмдө ичип-жегениңизди текшерүү үчүн «Тамактанууну көзөмөлдөө» куралын колдонуңуз.','Kaltsiumipomm 🧀','Kaltsium on ülioluline tugevate hammaste ja luude jaoks. Kasuta toitumise jälgimise tööriista, et kontrollida, kas oled oma päevase piimatoodete koguse kätte saanud.'),
('739069ab-a4c7-4cc9-ae84-572e67836bd2'::uuid,'Күндүн эң таттуу көз ирмеми 🖼️','Бүгүн ал жасаган, сизди каткыртып күлдүргөн ошол сүйкүмдүү жоругун эстеңизчи? Аны дароо «Баланын альбомуна» жүктөп коюңуз жана жылдар бою эстеп жүрүңүз.','Päeva kõige armsam hetk 🖼️','Pea meeles seda armsat asja, mida ta täna tegi ja mis sind naerma ajas? Laadi see kohe beebialbumisse ja hoia mälestust aastaid.'),
('faac9718-e68e-455d-90e4-e34b7b38a24e'::uuid,'Мээнин өнүгүүсү 🧠','1,5 жаштагы балдардын мээсинде болуп жаткан укмуштуудай процесстер тууралуу «Блогдор» бөлүмүндөгү жаңы макалабыздан окуп билиңиз.','Aju areng 🧠','Avasta meie uuest blogipostitusest uskumatud protsessid, mis toimuvad 1,5-aastaste laste ajus.'),
('2155f722-dd8c-49ec-a515-ecee85476474'::uuid,'Эртең мененки даараткана балансы 🧻','Күндүн биринчи жалаягын тиркемеге белгиледиңизби? Заңдын түсү жана коюулугу баланын жетиштүү суюктук ичип жатканын так көрсөтөт.','Hommikune potitasakaal 🧻','Kas märkisid päeva esimese mähkmevahetuse äppi? Väljaheite värvus ja konsistents annavad täpse ülevaate sellest, kas laps saab piisavalt vedelikku.'),
('67ef78f2-7b35-47be-a6f4-6368c3a37a84'::uuid,'Тамактануудагы кыйынчылыктар ⏱️','Балаңызга үйдүн дубалдары тардык кылып жатабы? Анын чексиз энергиясын сарптоо үчүн «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн кенен жана коопсуз сейил бактарды табыңыз.','Söömisaja väljakutsed ⏱️','Kas su laps istub kaua laua taga ja mängib toiduga? Aktiveeri söötmistaimer, et analüüsida võimalikke põhjuseid, miks isu on vähenenud.'),
('d9b69a33-09da-4d7d-98e9-ac3acd553715'::uuid,'Уйкунун бузулушубу? 🤖','Түнкүсүн көп ойгонуп жатасызбы? Anacan AI адисине жазып, бул өсүү мезгили (growth spurt) экендигин дароо билип алыңыз.','Unefaasi muutus? 🤖','Kas laps ärkab öösiti tihti? Uuri Anacan AI eksperdilt kohe, kas tegemist võib olla kasvuhüppega.'),
('283507fe-ca12-4764-a828-61d9a9f30424'::uuid,'Сиз чыныгы баатырсыз! 💖','Сиз идеалдуу болууга милдеттүү эмессиз. Маанай күндөлүгүңүзгө жөн гана «Мен муну жеңе алам» деп жазыңыз жана өзүңүзгө эс алууга мүмкүнчүлүк бериңиз.','Oled kangelane! 💖','Sa ei pea olema täiuslik. Kirjuta lihtsalt oma meeleolupäevikusse „Saan hakkama“ ja luba endale puhkust.'),
('290e0f59-3a24-4f74-9a01-c478f55efce5'::uuid,'Сырттагы укмуштуу окуялар 🌳','Кичинекей изилдөөчүңүз үчүн үйүңүз тар болуп жатабы? Анын чексиз энергиясын сарптоо үчүн «Энелерге ыңгайлуу жайлар» бөлүмүнөн кенен жана коопсуз сейил бактарды табыңыз.','Seiklused õues 🌳','Kas kodu seinad tunduvad väikesele avastajale kitsaks jäävat? Leia meie emmesõbralike kohtade nimekirjast avar ja turvaline park, kus ta saab oma piiritut energiat maandada.'),
('d9528425-30f7-4a4a-ac0d-053206658d00'::uuid,'Энергияңызды сактаңыз 🔋','Чарчап-чаалыгып калдыңызбы? Аялдар үчүн атайын даярдалган пайдалуу рецепттерибизден даамдуу жана тез күч бере турган эртең мененки тамакты тандаңыз.','Hoia energiat 🔋','Kas oled tegusast päevast täiesti kurnatud? Vali meie naistele mõeldud tervislike retseptide hulgast maitsev ja kiirelt energiat andev hommikusöök.'),
('0867f1c5-1a97-47ac-ba01-ac80c4c73f6b'::uuid,'Күндүзгү уйку ⏱️','Уйку таймерин иштетиңиз! Уйку убактысын так белгилөө менен, балаңыздын тынч түнкү уйкуга өтүүсүн оңой жөнгө сала аласыз.','Päevased uinakud ⏱️','Aktiveeri unetaimer! Uinakute täpse logimisega saad hõlpsalt reguleerida lapse üleminekut rahulikule ööunele.'),
('1b9ea296-6f6b-4447-9f45-4c6548d5e543'::uuid,'Үй-бүлөлүк тамактануу 🍲','Балаңыз эми сиз менен бирге тамактана алат! «Тамактанууну көзөмөлдөө» куралы менен үй-бүлөлүк тамактардын азыктык баалуулугун оңой эсептеңиз.','Pere ühine söögiaeg 🍲','Sinu laps saab nüüd süüa sama toitu mis sina! Arvuta meie toitumisjälgija abil mugavalt ühiste peretoitude toiteväärtust.'),
('b62665c0-5b12-4c5d-adfa-7b34000204cf'::uuid,'Күлкү үндөрү 📸','Бүгүн сизди эң көп күлдүргөн ошол таттуу көз ирмемди эстедиңизби? Аны сөзсүз түрдө «Баланын альбомуна» кыска видео же сүрөт катары кошуп коюңуз.','Naeruhelid 📸','Kas mäletad seda armsat hetke, mis sind täna kõige rohkem naerma ajas? Lisa see kindlasti lühivideo või fotona beebialbumisse.'),
('e16b58bb-af8f-43a3-bf1f-c1d132a221a5'::uuid,'Дүрбөлөңгө түшпөңүз! 🤖','Балаңыздын жүрүм-турумунан өзгөчөлүктү байкадыңызбы? Түнү менен тынчсызданбай, суроолоруңузга жооп алуу үчүн дароо Anacan AI менен байланышыңыз.','Ära paanitse! 🤖','Märkasid lapsel ebatavalist käitumist? Ära muretse öö läbi – pöördu kohe Anacan AI poole, et oma muredele vastused saada.'),
('ec3f1a4d-28dd-4a4a-9b91-b595f96327d4'::uuid,'Кальцийге болгон муктаждык 🦷','Балаңыз бүгүн канча кальций алганын эсептөө үчүн «Тамактанууну көзөмөлдөө» куралын колдонуңуз. Сөөктөр жана тиштер бекем болушу үчүн сунушталган сүт азыктарынын өлчөмүнө көңүл буруңуз.','Kaltsiumivajadus 🦷','Kasuta toitumisjälgijat, et arvutada, kui palju kaltsiumi su laps täna sai. Pööra tähelepanu soovituslikule piimatoodete kogusele, et tagada tugevad luud ja hambad.'),
('284e490f-ef18-407e-b320-432395edf56f'::uuid,'Түгөнбөгөн соода тизмеси 🛒','Шампунь, жалаяк же сулу жармасы түгөнүп баратабы? Баарын эстеп калууга аракет кылбаңыз – аларды «Соода тизмесине» кошуп, өнөктөшүңүз менен дароо синхрондоштуруңуз.','Lõputu ostunimekiri 🛒','Šampoon, mähkmed või kaerahelbed hakkavad otsa saama? Ära proovi kõike meeles pidada – lisa need ostunimekirja ja sünkrooni kohe oma partneriga.'),
('72bb2391-6fc4-4ef8-9352-3ae963d61f5b'::uuid,'Эми сиздин кезегиңиз! 🥗','Балаңыз уктап жатабы? Ашканага барыңыз! Аялдар үчүн атайын иштелип чыккан пайдалуу рецепттерибизден тез күч бере турган, белоктон бай салатты табыңыз.','Nüüd on sinu kord! 🥗','Laps magab? Suundu kööki! Avasta meie naistele mõeldud tervislike retseptide hulgast kiirelt valmiv ja valgurikas salat.'),
('91cfb4b2-1e2c-4e02-8b77-867d550b9fcd'::uuid,'Сыртка чыгууга убакыт келди ☕','Күнүмдүк тартиптен чарчадыңызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн балдар менен барууга ыңгайлуу кафе таап, жылуу кофеден ырахат алыңыз.','Aeg õue minna ☕','Oled rutiinist väsinud? Leia meie emmesõbralike kohtade hulgast lastesõbralik kohvik ja naudi tassikest sooja kohvi.'),
('7c893844-8335-47b4-baf7-b21329be4554'::uuid,'Ичиңиздегини төгүп салыңыз 📝','Оор күн болдубу? Сезимдериңизди Маанай күндөлүгүнө жазып коюу психикалык жүктү жеңилдетүүгө жардам берет.','Vala oma süda välja 📝','Kas päev oli kurnav? Tunnete kirjapanemine meeleolupäevikusse aitab vaimset koormust vähendada.'),
('ee049a04-c690-49d6-a1c7-d2c603be49d5'::uuid,'Уйку алдындагы жомок 🪄','Smart Tales бөлүмүндө атайын жекелештирилген жомок түзүңүз. Аны балаңызга үн чыгарып окуп бериңиз.','Une-eelne jutuaeg 🪄','Loo nutikate lugude (Smart Tales) abil eriline isikupärastatud muinasjutt. Loe see oma lapsele ette.'),
('fa6aaf54-9d2b-4b0c-a7b0-543d93bdc90a'::uuid,'Кийимдер кичине болуп калдыбы? 📏','18 айдан кийин өсүү мезгили күтүлөт. Салмак өлчөө куралына жаңы көрсөткүчтөрдү киргизип, өсүү графигинен анын ийгиликтерин сыймыктануу менен карап туруңуз.','Kas riided jäid jälle väikseks? 📏','Pärast 18. elukuud on oodata kasvuhüpet. Märgi uued mõõdud kaalujälgijasse ja vaata uhkusega lapse arengut kasvukõveral.'),
('46fbf80f-0604-494d-b68e-60f85488090d'::uuid,'Өз алдынча тамактануу! 🥣','Колунан кашыкты алдыра албай жатасызбы? Тамактануунун узактыгын жана көлөмүн көзөмөлдөө үчүн тамактануу таймерин иштетиңиз.','Sööb juba täitsa ise! 🥣','Kas lusikas ei taha kuidagi käest ära tulla? Käivita söötmistaimer, et jälgida nii söömise kestust kui ka kogust.'),
('5174db8a-22d1-41db-af86-5a575522337a'::uuid,'Биринчи шедеврлер 🖍️','Чиймелөө мезгили башталдыбы? «Сунушталган өнүмдөр» бөлүмүнөн уулуу эмес, жуула турган боёктордун эң жакшы варианттарын карап чыгыңыз.','Esimesed meistriteosed 🖍️','Kas kritseldamisperiood on alanud? Sirvi meie soovitatud toodete sektsiooni, et leida parimad mittetoksilised ja pestavad värvid.'),
('5e9337e9-36e0-44d6-9ecf-c3265d3eca6b'::uuid,'Менин кичинекей сүрөтчүм 📸','Боёкко булганып калдыбы? Стресс болбой, бул күлкүлүү көз ирмемди «Баланын фотосессиясынан» кызыктуу жээкчелер менен түбөлүккө калтырыңыз.','Minu väike kunstnik 📸','Värviga koos? Selle asemel et stressata, jäädvusta see naljakas hetk beebifotoseansi mänguliste raamidega.'),
('d414aad6-2d3e-4a62-a555-9241874e68b3'::uuid,'Уйку графиги ⏱️','Уктоо убактысы келди! Уйку таймерин иштетип, балаңыздын күнүмдүк уйку талаптарын аткарып жатканын текшерүү үчүн анын тартибин талдаңыз.','Uneplaan ⏱️','On uneaeg! Pane unetaimer tööle ja analüüsi lapse rutiini, et tagada tema ööpäevane unevajadus.'),
('7616cbf9-cf9d-45e8-86a1-eb74cb13ae1e'::uuid,'Эртең мененки даараткана сюрпризи 💩','Күндүн биринчи жалаягын алмаштырдыңызбы? Балаңыздын тамак сиңирүү системасын жана суюктук ичүүсүн көзөмөлдөө үчүн заңдын чоо-жайын тиркемеге белгилеп коюңуз.','Hommikune potiüllatus 💩','Vahetasid päeva esimese mähkme? Märgi väljaheite andmed äppi, et hoida beebi seedimisel ja vedelikutarbimisel silm peal.'),
('b32e8863-be99-483a-aff4-94fc82f554bc'::uuid,'Уйку таймери иштетилди! ⏱️','Кечки тартип башталды. Таймерди иштетип, бош эмес күндүн уйкуга өтүүгө кандай таасир этерин оңой талдап алыңыз.','Unetaimer aktiveeritud! ⏱️','Õhtune rutiin algab. Käivita taimer ja analüüsi hõlpsalt, kuidas tegus päev mõjutab uinumist.'),
('4673b81e-675b-4232-a5ca-c06aa26d504d'::uuid,'Эненин энергиясы 🔋','Балаңыздын артынан чуркап, чарчап калдыңызбы? Өзүңүздү азыктандырууну унутпаңыз! Пайдалуу рецепттерибизден тез күч бере турган белоктуу смузи жасап ичиңиз.','Emme energia 🔋','Kas oled lapse järel jooksmisest täiesti läbi? Ära unusta ka enda eest hoolitseda! Valmista meie tervislike retseptide järgi kiire ja energiat andev valgukokteil.'),
('7a2ab463-526e-46c6-a246-3494b6c46fa9'::uuid,'Оор эртең мененки убакытпы? 🌪️','Баланын кыяңкечтиги чарчатышы мүмкүн! Терең дем алыңыз жана бул кырдаалды кантип чечүү керектиги боюнча Anacan AI адисинен дароо кеңеш сураңыз.','Raske hommik? 🌪️','Jonnihood võivad olla kurnavad! Hinga sügavalt sisse ja küsi kohe Anacan AI-lt nõu, kuidas olukorda kõige paremini lahendada.'),
('c995af30-30f9-4eaf-a66c-3d0d65fc825b'::uuid,'Ички үнүңүзгө ишениңиз 📝','Балаңыз уктады. Эми «Маанай күндөлүгүн» ачып, бүгүнкү сезимдериңизди эч ким окубай турган барактарга төгүп, ичиңизди бошотуп, жеңилдеп алыңыз.','Usalda oma sisetunnet 📝','Beebi magab. Ava nüüd oma meeleolupäevik ja kergenda oma koormat, kirjutades tänased tunded lehekülgedele, mida keegi teine ei loe.'),
('0aa2cefc-f18c-4c10-98d6-e4dfda22198e'::uuid,'Тынчтандыруучу үндөр 🌧️','Жаңы ачылыштарга толгон күндөн кийин уктай албай жатабы? «Ак ызы-чуулар» бөлүмүнөн жамгырдын үнүн коюп, анын нерв системасын табигый жол менен тынчтандырыңыз.','Rahustavad helid 🌧️','Ei saa pärast uusi avastusi täis päeva magama jääda? Rahusta lapse närvisüsteemi loomulikul viisil, mängides valge müra alt vihmasadu.'),
('a57c041d-751b-4413-a98e-ee1564a86127'::uuid,'Таза аба, көбүрөөк энергия 🌳','Үйдө отуруп зериктиңизби? «Энелерге ыңгайлуу жайлар» бөлүмүнөн кызыктуу оюн аянтчалары бар жаңы паркты таап, кичинекейиңиздин ашыкча энергиясын чыгарууга жардам бериңиз!','Värske õhk, rohkem energiat 🌳','Tunned end kodus kinni? Avasta uusi põnevate mänguväljakutega parke jaotises „Emadele sobivad kohad“ ja aita oma väikesel kogu see energia välja elada!'),
('f3737052-fe7e-4f0c-9b36-7d082f7dbdfc'::uuid,'Акыл-эс өнүгүүсү 🧠','18,5 айлык балаңыздын мээсинде эмнелер болуп жатканы кызыкпы? Биздин «Блог» бөлүмүндөгү акыркы макаланы окуп, анын укмуштуудай өнүгүү процесстери менен таанышыңыз.','Arenguhüpe 🧠','Huvitab, mis toimub sinu 18,5-kuuse lapse ajus? Avasta tema uskumatud arenguprotsessid, lugedes meie blogi uusimat artiklit.'),
('108adc32-ab84-4dcd-be8c-e7597e84aa99'::uuid,'Көп отурасызбы? ⏱️','Тамактануу убактысы оюнга айланып баратабы? Тамактануу узактыгын талдоо жана тамак тандаган адаттардын алдын алуу үчүн «Тамактандыруу таймерин» иштетиңиз.','Istud liiga palju? ⏱️','Kas söögiaeg muutub mänguajaks? Aktiveeri toitmise taimer, et analüüsida söömise kestust ja aidata vältida valiva söömise harjumusi.'),
('36ae8436-7cda-46ec-b16d-44295bf2f7bc'::uuid,'Кийимдери кичирейип калдыбы? 📏','Балаңыздын бою күтүүсүздөн өсүп кеткендей сезилип жатабы? Жаңы өлчөмдөрдү «Өсүү көрсөткүчү» бөлүмүнө киргизип, анын өсүү графигин сыймыктануу менен байкаңыз.','Kas riided jäävad juba väikseks? 📏','Tundub äkki, et lapsel on „kasvuspurt“? Sisesta uued mõõdud kasvujälgijasse ja vaata uhkusega, kuidas tema arengugraafik tõuseb.'),
('909b1a9f-36d9-4ba3-a481-ae0e711ea145'::uuid,'Жагымдуу көз ирмемдер 📸','Кичинекейиңиз секирип же бийлегенге аракет кылып жатабы? Бул кубанычтуу көз ирмемди тартып алыңыз! Аны «Баланын сүрөт альбомундагы» кызыктуу жээкчелер менен кооздоп, өмүр бою сактала турган эстелик жаратыңыз.','Armsaimad hetked 📸','Kas su väike laps üritab hüpata või tantsida? Jäädvusta see rõõmus hetk! Kaunista see beebialbumi lõbusate raamidega ja loo eluaegne mälestus.'),
('049ab226-ff27-4f2f-a64f-85d2b588c035'::uuid,'Тиши ооруп жатабы? 🤖','Кичинекейиңиздин табити себепсиз жоголуп же көп ыйлап жатабы? Тиш чыгуунун, өзгөчө азуу тиштердин белгилери боюнча Anacan AI жардамчысынан адистин кеңешин сураңыз.','Kas see võib olla hambavalu? 🤖','Kas su lapsel on seletamatu isutus või nutab ta liiga palju? Küsi Anacan AI-lt asjatundlikku nõu hammaste tuleku, eriti purihammaste kohta.'),
('0e73fb38-1702-4d44-8a47-bf821e795ce5'::uuid,'Коопсуз кадамдар 👟','Кичинекейиңиз барган сайын ылдам чуркап жатабы? Алгачкы ишенимдүү кадамдар үчүн «Сунушталган товарлар» бөлүмүнөн эң мыкты ортопедиялык бут кийим моделдерин карап көрүңүз.','Kindlad sammud 👟','Kas su lapse jooksusamm muutub kiiremaks? Esimeste kindlate sammude jaoks vaata meie soovitatud toodete jaotisest parimaid ortopeedilisi jalatseid.'),
('2606521b-da76-4e40-8b9b-74eaed8f4900'::uuid,'Келечек үчүн мурас 🖼️','Бүгүн сизди эң көп күлдүргөн көз ирмемди «Баланын альбомуна» коштуңузбу? Телефонуңуздун эс тутуму толсо да, бул жерде сиздин элестериңиз ар дайым коопсуз сакталат.','Pärand tulevikuks 🖼️','Kas lisasid täna beebialbumisse selle hetke, mis sind kõige rohkem naerma ajas? Isegi kui telefoni mälu saab täis, on su mälestused siin alati kaitstud.'),
('1e433a5c-ee68-4089-bf86-5ce74fde7136'::uuid,'Пазл оюндары 🧩','18,5 айлык курак — логикалык оюндар үчүн эң сонун убакыт! «Сунушталган товарлар» бөлүмүнөн курагына ылайыктуу пазлдарды жана кубиктерди издеп көрүңүз.','Pusled ja nuputamismängud 🧩','Umbes 18,5 kuud on ideaalne aeg loogikamängudeks! Avasta meie soovitatud toodete jaotisest eakohased pusled ja klotsid.'),
('9d69d283-cfae-47a2-a874-8fabcc20a7f1'::uuid,'Өсүү мезгили 📈','«Өсүү көрсөткүчү» куралы аркылуу балаңыздын өсүү темпин талдаңыз. Анын бою менен салмагы өсүү графигиндеги дени сак нормада экенине ынануу үчүн көзөмөлдөп туруңуз.','Kasvuspurt 📈','Analüüsi lapse kasvutempot kasvujälgija abil. Jälgi tema pikkust ja kaalu, et veenduda, kas need jäävad kasvukõvera tervislikesse piiridesse.'),
('58a79bee-96dd-429b-a570-14dc6d97d91a'::uuid,'Тынчтандыруучу толкундар 🌊','Ашыкча чарчаган мээ эс алууга муктаж. Бөлмөгө «Ак ызы-чуулар» бөлүмүнөн океан толкундарынын үнүн коюп, аны тынчтандырыңыз.','Rahustavad lained 🌊','Üleergutatud aju vajab puhkust. Rahusta teda, mängides toas valge müra alt ookeanilainete heli.'),
('cf7f3cf6-5b3a-46ef-aef0-f4f77d4245e1'::uuid,'«Бул эмне?» фазасы 🤖','Балаңыздын чексиз суроолоруна жана кызыгуусуна таң калып жатасызбы? Бул таанып-билүү өсүшү жөнүндө биздин Anacan AI жардамчыбыздан көбүрөөк билип алыңыз.','„Mis see on?“ faas 🤖','Kas oled hämmastunud lapse lõpututest küsimustest ja lakkamatust uudishimust? Loe selle kognitiivse kasvuspurtide kohta lähemalt meie Anacan AI assistendilt.'),
('f8ad5a51-f4c3-4fc4-8170-0775df79fe84'::uuid,'Өзү тамактангысы келет 🥣','Кашыкты колунан алдырбай жатабы? Тамактануу убактысын көзөмөлдөө үчүн тамактандыруу таймерин иштетиңиз жана «Бала үчүн рецепттер» бөлүмүнөн кармаганга оңой тамактарды тандаңыз.','Tahab ise süüa 🥣','Ei saa lusikat tema käest kätte? Lülita sisse toitmise taimer, et jälgida söömise kestust, ja vali meie beebiretseptide hulgast kergesti haaratavaid toite.'),
('995604f6-97b2-4fe5-91ea-98f2248c1b28'::uuid,'Белоктун күчү 🥚','Белок жигердүү кичинекейиңиздин өсүп жаткан булчуңдары үчүн абдан маанилүү! Күнүмдүк тамактануу балансын көзөмөлдөө жана бардык керектүү азыктарды алып жатканына ынануу үчүн «Тамактанууну көзөмөлдөө» бөлүмүн колдонуңуз.','Valguvägi 🥚','Valk on sinu aktiivse lapse arenevate lihaste jaoks ülioluline! Kasuta toitumisjälgijat, et jälgida tema igapäevast toidulauda ja tagada kõigi vajalike toitainete kättesaamine.'),
('ec6ff433-9523-4a66-a427-b2548807345b'::uuid,'Көңүл буруу жана эс тутум 🧠','Балаңыз кантип үйрөнөт? Колдонмонун «Блог» бөлүмүнөн 1,5 жаштан кийинки курактагы көңүл буруунун жана эс тутумдун өнүгүшү тууралуу макаланы окуңуз.','Tähelepanu ja mälu 🧠','Kuidas su laps õpib? Loe meie rakenduse blogist artiklit tähelepanu ja mälu arengu kohta pärast 1,5-aastaseks saamist.'),
('ef4e2662-a0c2-4758-a2d7-d0ebe8f23855'::uuid,'Күндүн аягы 🌙','Уктоо убактысы келди! Уйку таймерин иштетиңиз, күнүмдүк уйку нормасын сактап жатканына ынануу үчүн анын тартибин жазыңыз жана өзүңүз да эс алыңыз.','Päeva lõpp 🌙','On uneaeg! Käivita unetaimer, märgi üles tema rutiin, et veenduda soovitusliku unevajaduse täitumises, ja lõõgastu.'),
('309ac2aa-7e4c-4fba-a6ae-8ce53ca7a9f7'::uuid,'Уйкунун бузулушубу? ⏱️','Түн ичинде бат-баттан ойгонуп жатабы? Уйку таймеринин графигин текшериңиз. Эгерде күндүзгү уйкусу өтө узун болсо, аны бир аз кыскартууга убакыт келгендир.','Une regressioon? ⏱️','Kas laps ärkab öösel sageli? Kontrolli unetaimeri graafikut. Kui päevased uinakud on liiga pikad, võib olla aeg neid veidi lühendada.'),
('6cc3ddd9-74b8-4e89-bf39-abc72a3548c9'::uuid,'Кальцийдин булагы 🧀','Кальций тиштердин жана сөөктөрдүн бекем болушу үчүн зарыл! Бүгүнкү сунушталган сүт азыктарынын нормасын толтурганыңызды текшерүү үчүн тамактанууну көзөмөлдөө бөлүмүн колдонуңуз.','Kaltsiumilaks 🧀','Kaltsium on tugevate hammaste ja luude jaoks hädavajalik! Kasuta toitumisjälgijat, et kinnitada tänase soovitusliku piimatoodete koguse täitumine.'),
('ec0d2d5d-31ad-48a9-8c47-f6c4eeeace11'::uuid,'Күнүмдүк баланс 💧','Күн бою жалаяк алмаштырууну белгилеп турууну унутпаңыз! Суюктуктун жетиштүүлүгү жана тамак сиңирүү ден соолугу тууралуу маалыматты жалаяктын канчалык бат булганышынан билсе болот, бул өзгөчө бала жигердүү болгондо маанилүү.','Igapäevane tasakaal 💧','Ära unusta mähkmevahetusi päeva jooksul kirja panna! Märgade mähkmete ja soolestiku tegevuse sagedus annab aimu lapse vedelikutasakaalust ja seedimisest, eriti suurenenud aktiivsuse korral.'),
('44008632-a96c-4f5e-a936-9b65273a2264'::uuid,'Эми сиздин кезегиңиз 🥗','Кичинекейиңиз акыры уктадыбы? Ашканага жөнөңүз! «Аялдар үчүн рецепттер» бөлүмүнөн даамдуу жана пайдалуу тамак жасап, өзүңүздү кубантыңыз.','Nüüd on sinu kord 🥗','Kas su väike laps teeb lõpuks uinakut? Suundu kööki! Premeeri end maitsva ja tervisliku suupistega meie naistele mõeldud retseptide hulgast.'),
('868f8ace-292a-4cf1-9abe-4b2da08aca3f'::uuid,'Кофе ичүү тыныгуусу ☕','Үй тиричилигинен жана күнүмдүк түйшүктөрдөн чарчадыңызбы? ''Энелер үчүн ыңгайлуу жайлар'' бөлүмүнөн балдар аянтчасы бар, үй-бүлө менен барууга ылайыктуу кафе табыңыз. Сиз эс алып, жылуу кофе ичүүгө толук татыктуусуз!','Kohvipaus ☕','Oled kodutöödest ja igapäevarutiinist väsinud? Leia meie „Emadesõbralike kohtade“ alt perega külastamiseks sobiv kohvik, kus on eraldi mängunurk. Sa väärid igati üht lõõgastavat kuuma kohvi!'),
('f7b08a7d-5067-40df-81d3-421be952c00e'::uuid,'Кемчиликсиз эне болбойт 💖','Эгер бүгүн баары пландалгандай болбой калса, өзүңүздү күнөөлөбөңүз. Маанай күндөлүгүнө тынчсызданууларыңызды жазып, жеңилдеп алыңыз.','Ükski ema pole täiuslik 💖','Kui kõik ei läinud täna plaanipäraselt, ära ennast süüdista. Pane oma mured kirja meeleolupäevikusse ja hinga kergendatult.'),
('913b583d-e8e0-426f-a7cd-75ab8b1bc0b4'::uuid,'Күлкү үндөрү 📸','Балаңыздын чуркап же тырмышып жүргөн учурунда тартылган эң күлкүлүү сүрөтүн ''Ымыркай альбомуна'' кошуңуз, бул бүгүнкү чарчооңузду жылмаюуга айлантат.','Naeruhelid 📸','Lisa beebialbumisse see kõige naljakam foto, mille tegid siis, kui ta parasjagu ronis või ringi jooksis – las see muudab tänase väsimuse naeratuseks.'),
('ccbbf1c0-789d-4a84-96bd-cdb04c618d13'::uuid,'Өсүүсүн көзөмөлдөйлү 📈','Алардын физикалык активдүүлүгү артты, бирок салмак кошуусу нормадабы? Өсүү темпин талдоо жана тынчсызданууларды азайтуу үчүн ''Салмакка көз салуу'' куралын колдонуңуз.','Jälgime kasvu 📈','Tema füüsiline aktiivsus on kasvanud, aga kas kaalutõus on ikka eakohane? Kasuta kaalujälgimise tööriista, et analüüsida tema kasvutempot ja hajutada muresid.'),
('44418a3d-932e-44e2-832c-c9fdeea34df1'::uuid,'Уруп жана тиштеп жатабы? 🛑','Айтылбай калган сезимдер кээде агрессия катары көрүнүшү мүмкүн. Өнүгүүнүн бул баскычында тиштөө жана уруу сыяктуу жүрүм-турумдарды кантип жөнгө салуу керектиги боюнча Anacan AI''дан кеңеш сураңыз.','Lööb ja hammustab? 🛑','Väljendamata tunded võivad vahel avalduda agressiivsusena. Küsi Anacan AI-lt nõu, kuidas selles arenguetapis hammustamise ja löömisega toime tulla.'),
('4a287257-0f36-49cd-93f7-28a1154386a6'::uuid,'Китепке болгон сүйүүнү кантип ойготуу керек? 📖','Уктаар алдында китеп окуйсузбу? Биздин блог бөлүмүнөн балдарды китепке кызыктыруунун жана алардын көңүлүн барактарда кармап туруунун алтын эрежелерин окуңуз.','Kuidas tekitada armastust raamatute vastu 📖','Kas loete enne magamaminekut? Loe meie blogist kuldreegleid, kuidas panna lapsed raamatuid armastama ja hoida nende tähelepanu lehekülgedel.'),
('f9f77164-bd35-4d6c-83ca-1991fcf7701a'::uuid,'Жаңы ачылыштар, жаңы коркунучтар ⚠️','Кичинекей изилдөөчүңүз ар жерге тырмышып жатабы? Үйдүн коопсуздугун жогорулатуу үчүн ''Сунушталган товарлар'' бөлүмүнөн эмеректердин бурчтарына тагылуучу жумшак коргоочуларды карап көрүңүз.','Uued avastused, uued ohud ⚠️','Sinu väike avastaja ronib kõikjal! Muuda kodu turvalisemaks ja vaata meie „Soovitatud toodete“ sektsioonist pehmeid nurgakaitsmeid mööblile.'),
('66297752-072e-4e90-afa0-bfdfc587176c'::uuid,'Темирдин деңгээли кандай? 🥩','Энергиялуу бөбөгүңүз аз кандуулуктан алыс болуп, сергек жүрүшү үчүн, тамактануу трекери аркылуу бүгүнкү темирдин өлчөмүн текшерип, жетишпеген бөлүгүн толуктаңыз.','Kuidas on lood rauatasemega? 🥩','Et su energiline väikelaps väldiks aneemiat ja oleks täis elujõudu, kontrolli toitumisjälgija abil tänast rauatarbimist ja vajadusel täienda menüüd.'),
('802d0f46-e525-43d0-8f5c-440b82228035'::uuid,'Кум жана жалбырак терапиясы 🍂','Төрт дубалдан чыгыңыз! ''Энелер үчүн ыңгайлуу жайлар'' бөлүмүнөн кумдуу аянтчасы же кенен жашыл аймагы бар сейил бактарды издеп, балаңыздын сезүү органдарынын өнүгүүсүнө колдоо көрсөтүңүз.','Liiva- ja leheteraapia 🍂','Pääse nelja seina vahelt välja! Uuri „Emadesõbralikke kohti“, et leida liivakasti või suurte rohealadega park ning toeta lapse sensoorset arengut.'),
('ee6e42f5-c128-4ecd-8cea-dcd4ee6be618'::uuid,'Кемчиликсиз болууну көздөөнү токтотуңуз ✨','Бүгүн балаңызга үнүңүздү көтөрүп жибердиңизби? Өзүңүздү күнөөлүү сезбеңиз. Ичиңиздеги толкундоолорду Маанай күндөлүгүнө жазып, өзүңүздү кечириңиз жана эртеңки жаңы күнгө даярданыңыз.','Loobu täiuslikkuse tagaajamisest ✨','Kas tõstsid täna lapse peale häält? Ära tunne süüd. Kirjuta oma sisemine segadus meeleolupäevikusse, anna endale andeks ja valmistu homseks uueks alguseks.'),
('0bcc42e9-f88e-427d-8d6d-562c3e7e7138'::uuid,'Брокколи операциясы! 🥦','Бөбөгүңүз жашылча жебей жатабы? Капа болбоңуз! Биздин рецепттер менен брокколини даамдуу куймактын ичине кантип чеберчилик менен жашырууну үйрөнүңүз.','Operatsioon „Brokkoli“! 🥦','Kas su väike põnn keeldub köögiviljadest? Ära muretse! Avasta meie beebiretseptide abil, kuidas nutikalt brokolit maitsvatesse pannkookidesse peita.'),
('2e502c2f-240e-4506-a102-a80013f7742b'::uuid,'Өзүңүзгө чынчыл болуңуз 🛋️','Бүгүн абдан чарчап, баарынан баш тарткыңыз келип жатабы? Бул кадыресе көрүнүш! Маанай күндөлүгүн ачып, ''Мага эс алуу керек'' деп жазыңыз да, бул кечти өзүңүзгө гана арнаңыз.','Ole enda vastu aus 🛋️','Oled täna täiesti kurnatud ja tahaksid lihtsalt alla anda? See on normaalne! Ava oma meeleolupäevik, kirjuta „Vajan puhkust“ ja pühenda see õhtu vaid iseendale.'),
('530196ff-adb2-4ae9-a06d-67bb4bfd998f'::uuid,'Кургак жалаяктар көбөйүп жатабы? 🧻','Эртең мененки жалаякты текшериңиз. Эгер ал 2 сааттан ашык кургак болсо, бул горшокко үйрөтүүнүн алгачкы белгиси болушу мүмкүн! Байкоолоруңузду жалаяк трекерине киргизип, статистиканы караңыз.','Kas kuivi mähkmeid jääb vähemaks? 🧻','Kontrolli hommikust mähet. Kui see püsib kuivana üle 2 tunni, võib see olla varajane märk potitreeninguks! Märgi oma tähelepanekud mähkmejälgijasse ja vaata statistikat.'),
('057998e1-6566-4f75-aa40-70a38d334aee'::uuid,'Эненин суу балансы 💧','Балаңыздын артынан чуркап, суусузданып калдыңызбы? Баш оорууңуз ошонун белгиси болушу мүмкүн! Дени сак рецепттерибизден сергитүүчү детокс суусундуктарын жасап, энергияңызды калыбына келтириңиз.','Ema vedelikutasakaal 💧','Kas tunned lapse järel jooksmisest vedelikupuudust? See peavalu võib olla märk! Taasta oma energia, valmistades meie tervislike retseptide järgi värskendavaid detoks-vett.'),
('29452fba-ed37-4bde-8e72-45e1f9c46d4d'::uuid,'Уктоого 10 мүнөт калды... ⏱️','Уйку таймерин иштетип, жарыкты өчүрүңүз. ''Ак ызы-чуу'' (White Noises) бөлүмүнөн токой шамалынын үнүн коюп, уйкуга кетүү процессин өзүңүз жана балаңыз үчүн сыйкырдуу кылыңыз.','10 minutit uinumiseni... ⏱️','Pane käima unetaimer ja hämarda tuled. Mängi valge müra alt metsatuka kohinat, muutes uinumise maagiliseks nii talle kui ka sulle.'),
('fa637a9e-0a58-4301-a5dd-89fb27cdb46b'::uuid,'Макарон сүйүүчү! 🍝','Балаңыз өзү тамактанып жатып, чачына чейин тамакка боёлуп калдыбы? Бул күлкүлүү учурду өткөрүп жибербеңиз! ''Ымыркай альбомундагы'' кызыктуу жээкчелер менен кооздоп, аны альбомуна кошуп коюңуз.','Pastakoletis! 🍝','Kas su väike põnn on ise süües toiduga koos, juuksed kaasa arvatud? Ära jäta seda naljakat hetke jäädvustamata! Kaunista see beebialbumi lõbusate raamidega ja lisa albumisse.'),
('031932e3-d91b-494c-9f35-dc03d53026b4'::uuid,'Бут кийими тар болуп калган жокпу? 👟','Балаңыз акыркы убакта көп чалынып жатабы? Балким, ал тез өсүп жаткандыр! Өнүгүүсүн талдоо үчүн анын жаңы бут кийим өлчөмүн жана боюнун узундугун ''Өсүү трекерине'' киргизиңиз.','Kas kingad on liiga kitsad? 👟','Kas su laps komistab viimasel ajal sagedamini? Võib-olla on tal kasvuspurt! Sisesta kasvujälgijasse tema uued kinga- ja pikkusemõõdud, et analüüsida arengut.'),
('db0a30ff-e18a-4830-abdc-881dc8827a75'::uuid,'Мээ үчүн азык: Омега-3 🐟','Балык мээнин өнүгүүсү үчүн абдан маанилүү. Кошумча тамакка өтүп жаткан бөбөктөр үчүн биздин Рецепттер бөлүмүнөн духовкада бышырылган, сөөксүз даамдуу балык котлетин жасап көрүңүз.','Ajutoit: Omega-3 🐟','Kala on aju arengu toetamiseks ülioluline. Tahke toiduga alustavatele beebidele proovi meie retseptide sektsioonist maitsvat luudeta ahjus küpsetatud kalakotletti.'),
('eb71840a-d8fc-43f9-897d-715c008b72b7'::uuid,'Эс алуу убактысы! 🌙','Активдүү күндүн аягы. Уйку таймерин иштетип, чуркап жүргөн оюндардан тынч иш-аракеттерге (мисалы, табышмактарды чечүү) өтүңүз.','Aeg maha võtta! 🌙','Aktiivse päeva lõpp. Aktiveeri unetaimer ja liigu ringijooksmiselt üle rahustavatele tegevustele (näiteks puslede lahendamine).'),
('36d9b82f-d63f-40d9-bafa-df3b3dc844b9'::uuid,'5 мүнөттүк ырахат! 🥗','Жолдо баратып эле тез тамактанып жатасызбы? Аялдар үчүн дени сак рецепттерибизден авокадо жана жумуртка кошулган тост жасап көрүңүз – ал ток кармайт жана энергияңызды жогорулатат!','5-minutiline nauding! 🥗','Kas haarad kiiruga snäkke? Proovi meie naiste tervislike retseptide hulgast avokaado-muna röstsaia – see on toitev ja hoiab su energiataseme kõrgel!'),
('5db92d40-f36e-4671-8f65-a3cb3f1c91ed'::uuid,'Чоюнуу учурундагы физикалык ачылыштар 🛁','Бир пластик чөйчөктөн экинчисине суу куюп жаткандагы анын олуттуу жана көңүл бурган келбетин ''Ымыркай альбомуна'' кошуңуз – мындай кичинекей ачылыштар унутулгус!','Vannitoa füüsikaavastused 🛁','Lisa beebialbumisse see tõsine ja keskendunud ilme, mis tal oli vee ühest plasttopsist teise valamisel – need väikesed avastushetked on unustamatud!'),
('e18f3a19-4a7e-44e4-9703-5c88f6dda037'::uuid,'Экран алдында көп отуруп жатабы? 📱','Телефонду алганда балаңыз катуу ыйлайбы? Anacan AI''дын кеңештери менен экран убактысын стресс жок чектөөнү жана дени сак чектерди коюуну үйрөнүңүз.','Liiga palju ekraaniaega? 📱','Kas telefoni käestvõtmine tekitab suure jonnituuri? Õpi Anacan AI nõuannete abil, kuidas piirata ekraaniaega stressivabalt ja seada tervislikud piirid.'),
('2c1e9be8-ccf0-412a-a942-30cea5075e5b'::uuid,'Башкалар менен баарлашуу убактысы! 👶','Кичинекейиңиз башка балдар менен баарлашууну каалап жатабы? ''Энелер үчүн ыңгайлуу жайлар'' бөлүмүнөн атайын оюн борбору бар, балдар үчүн ыңгайлуу жайды табыңыз жана анын кубанычына күбө болуңуз!','Aeg suhelda! 👶','Kas su väike põnn igatseb teiste lastega suhtlemist? Avasta „Emadesõbralike kohtade“ alt mängukeskusega paik ja vaata, kuidas ta silmad särama löövad!'),
('fec1f9db-8b95-410a-b753-aded5a7dc606'::uuid,'Караңгыдан коркобу? 🌌','Бөлмөдө жарыкты өчүргөндө ыйлап же тынчсызданабы? Аларга тааныш, жылуу коопсуздук сезимин тартуулоо үчүн "Ак ызы-чуулар" бөлүмүнөн эненин жатынындагы үндү (жүрөктүн кагышын) коюп бериңиз.','Kas kardab pimedust? 🌌','Kas laps nutab või muutub ärevaks, kui tuled kustutad? Pane „Valge müra“ alt mängima emaüsas kostuv südamelöökide heli, et pakkuda talle tuttavat ja turvalist soojustunnet.'),
('5c635a69-e5ff-42eb-9277-29e39d9986fa'::uuid,'Тиш жууган кызыктуу! 🪥','Кичинекейиңиздин тишин жуудуруу кыйын болуп жатабы? "Сунушталган товарлар" бөлүмүнөн манжага кийилүүчү же жарык күйгөн, музыкалык тиш щеткаларын карап чыгып, ооз көңдөйүнүн гигиенасын кызыктуу оюнга айлантыңыз.','Hammaste pesemine on lõbus! 🪥','Kas hambapesu on paras katsumus? Muuda suuhügieen lõbusaks mänguks, uurides „Soovitatud toodete“ alt sõrmehambaharju või helendavaid ja muusikalisi mudeleid.'),
('f2a19104-ece3-4a8f-9966-8cad392a68af'::uuid,'Кечки бейпилдик 🍵','Бөбөк уктады, таймер токтоду. Эми шашпай, эс алууга убакыт келди. Биздин пайдалуу рецепттерден ромашка чайын демдеп, тынчтыктан ырахат алыңыз.','Õhtune rahu 🍵','Beebi magab ja taimer on peatatud. Nüüd on aeg puhata, mitte kiirustada. Valmista meie tervislike retseptide järgi kummeliteed ja naudi tõeliselt seda rahu.'),
('f524b282-4173-4386-b8dd-255261b77d1d'::uuid,'«Өзүм кийинем!» фазасы 👕','Эртең менен кийинүү убактысы чоң күрөшкө айланып жатабы? "Блогдор" бөлүмүнөн балага тандоо мүмкүнчүлүгүн берүү менен кийинүүдөгү чыр-чатактарды чечүүнүн практикалык жолдорун окуп чыгыңыз.','„Ma riietun ise!“ faas 👕','Kas hommikud muutuvad riietumise ajal suureks lahinguks? Loe blogist praktilisi nippe, kuidas riietumistega seotud jonnihooge lahendada, pakkudes lapsele valikuvõimalusi.'),
('46919051-4727-4a43-8ba3-d5a1f5451c16'::uuid,'Дүкөндө ыйлап жатабы? 🛒','Коомдук жайда каалаганы болбой калды деп өзүн жерге уруп жатабы? Айланадагылардын көз карашына маани бербеңиз, ошол учурда тынчтыкты сактоо үчүн Anacan AI менен сырдашып, колдоо алыңыз.','Poes jonnimine? 🛒','Kas laps viskab end poes pikali, kui ta ei saa oma tahtmist? Ära pööra tähelepanu teiste pilkudele – vestle sel hetkel Anacan AI-ga, et end rahustada ja tuge saada.'),
('874df706-e26e-4b72-a02c-7f8309fc95d5'::uuid,'Эки сөздөн турган сүйлөмдөр! 🗣️','Бүгүн "Апа кел" же "Топту ыргыт" сыяктуу жаңы сөз айкаштарын түздүбү? Тилдин мындай сонун өнүгүүсүн дароо "Бөбөктүн альбомуна" аудио-видео клип катары сактап коюңуз.','Kahesõnalised laused! 🗣️','Kas ta ütles täna uue sõnapaari, näiteks „Emme tule“ või „Viska palli“? Salvesta see imeline keeleline areng kohe video- või heliklipina beebialbumisse.'),
('af368cd3-f751-4611-9e47-9c8fda037ebd'::uuid,'Майда моторика иштеп жатат! 🧩','Буурчак, жүгөрү же тууралган жемиштерди өз алдынча жешине уруксат бериңиз. Бул майда моториканы өнүктүрүүгө жардам берет. "Тамактануу трекери" аркылуу порциялардын өлчөмүнө көз салып туруңуз.','Peenmotoorika areneb! 🧩','Lase tal ise süüa herneid, maisi või tükeldatud puuvilju. See arendab peenmotoorikat. Jälgi toiduportsjonite suurust toitumispäeviku abil.'),
('1f770df3-c7ef-4bf3-8564-f5ddd0b6a323'::uuid,'Иммунитетти көтөрөбүз! 🍊','Мезгилдин алмашуусу сезилип жатабы? "Тамактануу трекерин" колдонуп, бүгүнкү С витамининин көлөмүн эсептеңиз жана менюга цитрус жемиштерин, киви же түстүү болгар калемпирин кошуу менен иммунитетти көтөрүңүз.','Turguta immuunsust! 🍊','Tunned aastaaegade vahetumist? Arvuta toitumispäevikus tänane C-vitamiini kogus ja turguta immuunsust, lisades menüüsse tsitruselisi, kiivit või värvilist paprikat.'),
('28cf8172-0a76-4afd-b2de-765879c7939a'::uuid,'Өзүңүздү баалай билиңиз! 💖','Сиз ушунчалык камкор жана сонун энесиз! "Маанай күндөлүгүн" ачып, бүгүн балаңыз үчүн кылган эң кичинекей жакшылыгыңызды да жазып, өзүңүз менен сыймыктаныңыз.','Kiida ennast! 💖','Oled nii pühendunud ja imeline ema! Ava oma meeleolupäevik, pane kirja ka kõige väiksem hea tegu, mida täna lapse heaks tegid, ja tunne enda üle uhkust.'),
('f00a5e44-ed12-4c77-9249-e4246b2b108d'::uuid,'Горшокко үйрөтүү 🚽','Дагы деле эрте болсо да, дааратканада горшок кармоо визуалдык тааныштыкты жаратат. Алардын көңүлүн бура турган ыңгайлуу жана кызыктуу моделдерди "Сунушталган товарлар" бөлүмүнөн карап чыгыңыз.','Potitreeningu algus 🚽','Isegi kui on veel vara, aitab poti vannituppa panemine sellega harjuda. Vaata meie „Soovitatud toodete“ alt mugavaid ja põnevaid mudeleid, mis lapse tähelepanu köidavad.'),
('f830cd97-a8bb-4789-bdc5-7806bcd89cfe'::uuid,'Ашыкча чарчоо 🎇','Кичинекейиңиздин мээси күндүз өтө активдүү болуп, түнкүсүн тынчтана албай жатабы? "Ак ызы-чуулар" функциясынан фендин же желдеткичтин үнүн коюп, бир калыптагы ритм аларды кантип тынчтандырарын көрүңүз.','Üleärritus 🎇','Kas su pisipõnni aju on päeval liiga aktiivne, et õhtul uinuda? Pane „Valge müra“ alt mängima fööni või ventilaatori heli ja vaata, kuidas ühtlane rütm teda rahustab.'),
('1915583e-53f5-46af-8212-835dfd587e22'::uuid,'Чачыңыз дагы эле түшүп жатабы? 💇‍♀️','Сиздин организмиңиз дагы деле калыбына келүүдө. Аялдар үчүн пайдалуу рецепттерибизден цинк жана биотинге бай эртең мененки тамак менюсун тандап, бүгүн өзүңүзгө кам көрүңүз.','Kas juuksed langevad ikka välja? 💇‍♀️','Sinu keha alles taastub. Hoolitse täna enda eest ja vali meie naiste tervislike retseptide hulgast tsink- ja biotiinirikas hommikusöök.'),
('cfbeabf3-def0-4cbe-a106-fd34987dd776'::uuid,'Музыкалык аспаптар менен көңүл ачуу! 🥁','Жыгач кашыктар менен казандарды ургулаганды жакшы көрөбү? "Сунушталган товарлар" бөлүмүнөн балдар үчүн коопсуз үн деңгээли бар ксилофондорду жана барабандарды карап чыгыңыз.','Muusikariistadega mängimine! 🥁','Kas talle meeldib puulusikatega pottide peal trummeldada? Vaata meie „Soovitatud toodete“ alt ksülofone ja trumme, mille helitugevus on lapsele ohutu.'),
('2ed7fd17-90ba-451d-9c88-a1f94a180fe0'::uuid,'Табити төмөндөдү, салмагы кандай? 📉','Бул айларда тамак тандап жегендик көп кездешет. Учурдагы көрсөткүчтөрдү "Салмак трекерине" киргизиңиз жана алардын өнүгүүсү толугу менен нормада экенин көргөндө дароо жеңилдеп каласыз.','Söögiisu vähenenud, kuidas on kaaluga? 📉','Söömise valivus võib nendel kuudel suureneda. Sisesta kaaluandmed kaalujälgijasse ja tunne kergendust, nähes, et areng on täpselt graafikus.'),
('50209dd4-d2d7-4719-bf4e-21df8c72686a'::uuid,'Уктоо алдындагы тартип 🧸','Ар бир кечтеги бирдей тынчтандыруучу тартип! Уйку таймерин баштаңыз, сүйүктүү оюнчук аюусуна бейпил түн каалатыңыз жана бул туруктуу ырым-жырым алардын уйкуга өтүүсүн канчалык жеңилдетерине байкоо салыңыз.','Magamamineku rutiinid 🧸','Igaõhtune rahustav rutiin! Käivita unetaimer, lase lapsel oma lemmikmänguasjale head ööd soovida ja märka, kuidas see järjepidev rituaal uinumist lihtsustab.'),
('3abde512-ebd4-4cf1-986e-fb1953695f78'::uuid,'Иммунитет үчүн түстүү калкан 🛡️','"Тамактануу трекери" аркылуу бүгүн жетиштүү С витаминин алганын текшериңиз. Кызгылт сары жана кызыл жашылчалар кошулган идеяларды "Бөбөктөр үчүн рецепттер" бөлүмүнөн караңыз.','Värviline kilp immuunsusele 🛡️','Kontrolli toitumispäeviku abil, kas ta on täna piisavalt C-vitamiini saanud. Vaata beebiretseptide alt ideid oranžide ja punaste köögiviljadega.'),
('56129e04-2f90-42b1-b51e-b835940e284e'::uuid,'Психологиялык жүгүңүздү жеңилдетиңиз 🧘‍♀️','Муну кылыш керек, тигини бышырыш керек – оюңуз тынымсыз ушулар менен алекпи? Бардык пландарыңызды жана тынчсызданууларыңызды "Маанай күндөлүгүнө" жазып алыңыз. Аларды жөн гана тизмелеп коюу стрессти дароо азайтууга жардам берет.','Kergenda oma vaimset koormat 🧘‍♀️','Peab seda tegema, peab toda kokkama – kas mõtted aina tiirlevad? Pane kõik plaanid ja mured meeleolupäevikusse kirja. Juba ainuüksi nende üleskirjutamine aitab stressi vähendada.'),
('1576f605-27d8-4159-b3bd-3dd9e63c91dd'::uuid,'Тамак сиңирүү үчүн көп суюктук ичиңиз 💧','Катуу тамак-ашка толук өтүү кээде тамак сиңирүүнү кыйындатышы мүмкүн. "Жалаяк трекерине" белгилеп туруу менен, аларга сууну көбүрөөк ичүү керекпи же жокпу, оңой эле аныктай аласыз.','Rohkelt vedelikku sujuvaks seedimiseks 💧','Üleminek tahkele toidule võib vahel seedimist mõjutada. Märkmeid tehes saad mähkmetäitja abil hõlpsasti kindlaks teha, kas laps vajab rohkem vett.'),
('93141c59-a17f-414d-9f6c-c865a0650eeb'::uuid,'Көлөкө оюну башталды! 🐰','Жарыкты өчүрүп, кол чырак менен дубалга көлөкө фигураларын жасаңыз. Бул сыйкырдуу көз ирмемди көрүп жаткандагы алардын жүзүндөгү таттуу, таң калган көрүнүштү "Бөбөктүн альбому" үчүн сөзсүз тартып алыңыз.','Varjuteatri aeg! 🐰','Kustuta tuled ja tee taskulambiga seinale varjupilte. Jäädvusta kindlasti see armas ja üllatunud ilme lapse näol, kui ta seda maagilist hetke beebialbumi jaoks vaatab.'),
('a14c30d1-ff1f-46da-8b1e-98116e38ee0d'::uuid,'Барактарды айрып жатабы? 📖','Китептерди окугандын ордуна айрып салганды жакшы көрөбү? Бул курактагы калың барактуу жана тактилдик китептердин маанилүүлүгү жөнүндө "Блогдор" бөлүмүндөгү жаңы кеңештерибизди окуп чыгыңыз.','Kas rebis lehti? 📖','Kas ta eelistab raamatuid pigem rebida kui lugeda? Loe meie uusi nõuandeid blogist selle kohta, miks on selles vanuses olulised papist ja kombatavad raamatud.'),
('8e7d531f-d445-43eb-a4d5-05ffff377c4f'::uuid,'Үнсүз дүйнөдөн музыкага 🎶','Телевизордун же оюнчуктардын үнүнөн кийинки кескин жымжырттык кээде балдарды чочутуп коюшу мүмкүн. "Ак ызы-чуулар" функциясынан поезддин үнүн коюп, алардын уйку чөйрөсүнө акырындык менен өтүүсүн камсыздаңыз.','Helist vaikuseni 🎶','Järsk üleminek teleri või mänguasjade helidelt täielikule vaikusele võib lapsi ehmatada. Loo rahulik üleminek unekeskkonda, mängides „Valge müra“ alt rongisõidu heli.'),
('c6f920b8-00cf-46b0-a823-bf8cf1fd5ecf'::uuid,'Кыйынчылыктар менен бөлүшүү 🧸','Балаңыз паркта башка балдардын оюнчуктарын көздөй чуркап, бирок өзүнүкү менен бөлүшүүдөн баш тартабы? 1,5 жаштагы балдарга кезек күтүү түшүнүгүн кантип үйрөтүү керектигин Anacan AI''дан сураңыз.','Murede jagamine 🧸','Kas su laps jookseb pargis teiste laste mänguasjade juurde, aga keeldub enda omi jagamast? Küsi Anacan AI-lt, kuidas õpetada 1,5-aastasele kordamööda tegutsemist.'),
('ca671510-91c4-4377-9f69-b4bd47b292a2'::uuid,'Сиз үчүн кичинекей тыныгуу ☕','Энергияңыз кандай болуп жатат? Үй жумуштарын токтотуңуз. "Аялдар үчүн пайдалуу рецепттер" бөлүмүнөн кубат берүүчү жержаңгак майы кошулган кекс даярдап, кофеңиздин кайнап жаткан жагымдуу үнүн угуп отуруңуз.','Väike paus sulle ☕','Kuidas su akud on? Jäta kodutööd pooleli. Valmista naiste tervislike retseptide sektsioonist energiat andev maapähklivõikook ja lihtsalt kuula kohvimasina rahustavat kohinat.'),
('38141003-a43c-4589-a477-21da541a08db'::uuid,'Кинетикалык кумдун сыйкыры! 🏖️','Үйдө кичинекей пляж жасоого кандай карайсыз? Манжа булчуңдарын бекемдеген жана оңой тазаланган кинетикалык кум топтомдорун "Сунушталган товарлар" бөлүмүнөн карап чыгыңыз.','Kineetilise liiva võlu! 🏖️','Kuidas oleks väikese ranna loomisega kodus? Vaata meie „Soovitatud toodete“ alt kineetilise liiva komplekte, mis tugevdavad sõrmelihaseid ja mida on lihtne koristada.'),
('75f9f2e1-a04a-4711-9125-3d8c610326d9'::uuid,'Өз денесин таанып билүү! 👃','"Мурдуң кана?" деп сураганыңызда, сыймыктануу менен көрсөтөбү? Бөлмөсүндө эле мини фотосессия уюштуруп, бөбөктүн альбому үчүн ошол сүйкүмдүү позаны тартып алыңыз!','Oma keha avastamine! 👃','Kui küsid „Kus su nina on?“, kas ta näitab uhkelt sellele? Korralda toas väike fotosessioon ja jäädvusta see armas poos beebialbumisse!'),
('ae036003-f237-47e6-8031-7feeb47126cc'::uuid,'Баланын тоюп калганын кантип билсе болот? ⏱️','Эгерде алар тамакты ыргытып же түкүрүп баштаса, бул алардын "Мен тойдум" дегени. Тамактандыруу таймерин токтотуп, муктаждыктары канааттандырылганын белгилеңиз жана табитин анализдеңиз.','Kuidas teada, et beebi on kõhu täis söönud? ⏱️','Kui ta hakkab toitu loopima või välja sülitama, on see tema viis öelda: „Olen kõhu täis söönud.“ Peata toitmistaimer, märgi vajaduste rahuldamine ja analüüsi tema isu.'),
('05bc3cfd-c566-4963-b6b2-87889d369e27'::uuid,'Сизге да колдоо керек 💬','Башка энелер менен баарлашуу сизге да пайдалуу болот! "Энелерге ыңгайлуу жайлар" бөлүмүнөн оюн топтору бар борборду тандап, экөөңүздөргө тең социалдашуу мүмкүнчүлүгүн белек кылыңыз.','Ka sina vajad oma toetavat võrgustikku 💬','Teiste emadega suhtlemine tuleb ka sulle kasuks! Vali meie „Emasõbralike asukohtade“ hulgast mängugrupiga keskus ja kingi teile mõlemale sotsialiseerumisvõimalus.'),
('5b6366a9-6eb4-4593-8335-c41fd3447da1'::uuid,'Бүгүнкү жетишкендигиңиз эмне болду? 🏆','Аларды чыр-чатаксыз уктаттыңызбы? Же бир идиш тамакты толук ичип бүтүүгө көндүрдүңүзбү? Сиздин эң кичинекей жеңиштериңиз да баалоого татыктуу! Аларды "Маанай күндөлүгүнө" жазып, өзүңүзгө кол чабыңыз.','Mis oli sinu tänane võit? 🏆','Kas said ta ilma suurema vaevata magama? Või veensid teda terve kausitäie sööma? Isegi kõige väiksemad võidud väärivad tunnustust! Pane need meeleolupäevikusse kirja ja kiida ennast.'),
('98a39354-24f3-4f3c-9cfb-1e084764a56b'::uuid,'Өсүү мезгили жана жаңы бут кийим 📏','Эгерде алар бут кийимин кийүүдөн баш тартып жатса, балким, ал кичинекей болуп калгандыр! "Салмак трекери" куралындагы өлчөмдөр таблицасын текшерип, алардын физикалык өнүгүүсүнө көз салып туруңуз.','Kasvuspurt ja uued kingad 📏','Kui ta keeldub kingi kandmast, on need ehk väikeseks jäänud? Kontrolli kaalujälgija suurustabelit ja hoia silm peal lapse füüsilisel arengul.'),
('5bcd3758-fc71-4b21-a0a4-008b6ec5eec1'::uuid,'Чачтын жана теринин ден соолугу үчүн 🥑','Күнүмдүк түйшүктөн чарчаган денеңизге кам көрүңүз. "Аялдар үчүн пайдалуу рецепттер" бөлүмүнөн антиоксиданттарга бай авокадо жана жаңгак кошулган "жаштык салатын" даярдаңыз.','Tervete juuste ja naha heaks 🥑','Hoolitse oma igapäevatoimetustest väsinud keha eest. Valmista naiste tervislike retseptide hulgast antioksüdantiderikas avokaado-kreeka pähkli „noorusesalat“.'),
('a832a387-bccf-4a1a-823c-3930e73e4c07'::uuid,'Баланын алгачкы сөздөрү: «Суу, апа!» 🗣️','Алар эки сөздү бириктирип, кичинекей сүйлөмдөрдү түзүүгө аракет кылып жатабы? Тилдин өнүгүүсүндөгү кандай сонун секирик! Алардын аракеттерин дайыма колдоп, сүйлөөгө шыктандырыңыз.','Beebi esimesed sõnad: „Vesi, emme!“ 🗣️','Kas ta proovib juba kahest sõnast lauseid moodustada? Milline fantastiline hüpe keelelises arengus! Kinnita pidevalt tema katsetusi ja julgusta teda rääkima.'),
('d1f9f7f1-6831-4583-9dbd-fab805703b8d'::uuid,'Чексиз энергия 🔋','Чуркагандан эч тажабайбы? Уйку таймерин баштап, жарыкты бүдөмүктөтүп, "Ак ызы-чуулар" бөлүмүнөн токойдун шуулдаган жагымдуу үнү менен аларды акырындык менен уйку режимине өткөрүңүз.','Piiritu energia 🔋','Ei väsi jooksmast? Käivita unetaimer, hämarda tuled ja aita ta „Valge müra“ alt kostva metsakohina saatel õrnalt unerežiimile.'),
('34104368-1e25-46df-8c68-910d16cd40b1'::uuid,'Тамак сиңирүүсү кандай? 🚽','Кичинекейиңиз ич катуудан кыйналып жатабы? Эртең мененки жалаягын алмаштырып жатканда белгилеп коюңуз жана "Тамактануу трекери" аркылуу менюсуна клетчаткага бай азыктарды (алмурут жана сулу боткосу сыяктуу) сөзсүз кошуңуз.','Kuidas seedimisega lood on? 🚽','Kas su pisikesel on kõhukinnisus? Tee hommikust mähet vahetades märge ja lisa toitumispäeviku abil menüüsse kiudainerikkaid toite (nagu pirnid ja kaerahelbed).'),
('79b083b6-1c72-4250-a120-ca8846206ce5'::uuid,'Өзүңүздү кандай сезип жатасыз? 🧘‍♀️','Өзүңүздүн "Бүгүн эмес!" деп айтканыңызды байкадыңызбы? Өзүңүздү күнөөлүү сезбеңиз. Чыныгы сезимдериңизди "Маанай күндөлүгүнө" төгүп, эне катары канчалык жан аябас экениңизди өзүңүзгө эскертиңиз.','Kuidas sa end tunned? 🧘‍♀️','Kas tabasid end mõttelt „Täna mitte!“? Ära tunne süüd. Vala oma tõelised tunded meeleolupäevikusse ja tuleta endale meelde, kui ennastsalgav ema sa oled.'),
('bfb35c45-0163-48f3-be24-eff4697cb9e8'::uuid,'Кичинекей жаратылыш сүрөтчүлөрү 🍂','Жалбырактар, таштар жана бутактар – эң мыкты оюнчуктар! "Энелерге ыңгайлуу жайлар" бөлүмүнөн жапжашыл паркты таап, сырттагы чыныгы изилдөөгө аттаныңыз.','Väikesed looduse kunstnikud 🍂','Lehed, kivid ja oksad on parimad mänguasjad! Leia meie „Emasõbralike asukohtade“ hulgast lopsakas roheline park ja suundu tõelisele loodusavastusretkele.'),
('01861a89-1cc1-4443-8c58-c79d90402305'::uuid,'Дүкөндөгү каприздер 🛒','Дүкөндөн каалаганын алып бербегениңиз үчүн чыр чыгардыбы? Паникага алдырбаңыз. Башкалардын көз карашына көңүл бурбай, акырын алардын көз деңгээлине чейин эңкейиңиз.','Jonnimine supermarketis 🛒','Kas ta sai poes jonnihoo, sest sa ei ostnud seda, mida ta tahtis? Ära paanitse. Ignoreeri teiste pilke ja lasku rahulikult lapse silmade kõrgusele.'),
('32e724db-ca0f-4d6b-9d07-716443a9dcdd'::uuid,'Эмоционалдык жүгүңүздү бошотуңуз 📝','Оор күн болдубу? Бүгүнкү стрессти "Маанай күндөлүгүнө" жазып, жеңилдеп алыңыз. Ар бир эне ушундай учурларды башынан өткөрөт – сиз жалгыз эмессиз.','Vabasta oma emotsionaalne koorem 📝','Oli raske päev? Kergenda südant, kirjutades tänane stress meeleolupäevikusse. Iga ema kogeb selliseid hetki – sa ei ole üksi.'),
('a0570819-b575-49b5-bbf4-bc21cf5fc939'::uuid,'Эки буттап секирүүнү өздөштүрүү! 🦘','Туруп туруп, эки буту менен тең секирүүгө аракет кылып жатабы? Бул абдан күлкүлүү көрүнөт, туурабы? Бул көз ирмемди "Бөбөктүн фотосессиясы" менен сөзсүз түбөлүккө калтырыңыз.','Kahe jalaga hüppamine! 🦘','Kas ta proovib seistes mõlema jalaga korraga hüpata? See näeb nii naljakas välja, eks? Jäädvusta see hetk kindlasti beebifotosessiooniga.'),
('1eeadb7c-f8e9-45ae-bbde-edff2903cb9d'::uuid,'Уктоодон баш тартуубу? 🥱','Күндүзгү уйкуга каршылык көрсөтүп жатабы? 20 айлык балдардын уйку терезелери боюнча так маалыматты жана графикти Anacan AI''дан сураңыз.','Keeldub magamast? 🥱','Kas ta võitleb päevaste uinakute vastu? Küsi Anacan AI-lt täpset infot ja ajakava 20-kuuse lapse unevajaduse kohta.'),
('2edb626b-eafe-49c0-a743-e6dae9f9eddd'::uuid,'Музыкалык бейпилдик 🎶','Кечки чыр-чатакты басуунун эң оңой жолу – алардын сүйүктүү обонун коюп, жылуу кучактап, акырын бийлөө.','Muusikaline rahu 🎶','Lihtsaim viis õhtust rahutust leevendada on panna mängima tema lemmikmeloodia, teha talle soe kallistus ja õrnalt tantsida.'),
('b174df30-8e63-488e-ae9b-4d227f3136f1'::uuid,'Апа үчүн даамдуу тамак 🥑','Алардын курсагы ток болушу үчүн баарын жасайсыз. А өзүңүзчү? "Пайдалуу рецепттер" бөлүмүнөн сизге энергия бере турган, темирге бай түшкү тамакты тандап, шашпай отуруп тамактаныңыз.','Pidu emmele 🥑','Teed kõik, et laps oleks söönud. Aga sina ise? Vali tervislike retseptide hulgast rauarikas lõunasöök, mis annab sulle energiat, ning istu rahulikult ja söö.'),
('5d951093-5ada-49f6-9750-d303bcf8d918'::uuid,'Азуу тиштери чыгып жатабы? 🦷','Баарынын бетин кемирип, себепсиз эле ыйлап жатабы? Балким, арткы азуу тиштери чыгып жаткандыр! Тиш чыгууну көзөмөлдөөчү куралда (Teething Tracker) бул процессти белгилеп коюңуз жана муздак тиш салгычтарды даярдап алыңыз.','Kas purihambad on tulemas? 🦷','Närib kõike ja nutab ilma nähtava põhjuseta? Võib-olla on tulemas tagumised purihambad! Märgi hammaste tulek hammaste kasvu jälgijasse ja hoia külmad närimisrõngad käepärast.'),
('9fe66081-4fad-49c8-891d-2ca85484f87d'::uuid,'Жомоктун каарманы 🪄','Бүгүн кечинде «Акылдуу жомоктор» (Smart Tales) бөлүмүндө балаңыз башкы каарман болгон өзгөчө жомок ойлоп табыңыз: «Тиш жууганды жакшы көргөн эр жүрөк бөбөк».','Muinasjutu kangelane 🪄','Loo täna õhtul Smart Talesis eriline lugu, kus sinu laps on kangelane: „Vapper väike tegelane, kes armastab hambaid pesta.“'),
('c638741f-2af1-4bf3-a4de-09ffcb406144'::uuid,'Таза абага чыгуу ⛅','Аба ырайына байланыштуу үйдө отурасызбы? «Аба ырайы жана кийим» куралы аркылуу шамалдын ылдамдыгын (терезеден көрүнбөгөн) жана эң ылайыктуу кийим тандоону заматта билип, сейилдөөгө ишенимдүү аттаныңыз.','Õues seiklemine ⛅','Kas jääte koju, sest ilm tundub „kahtlane“? Lase ilma ja riietuse tööriistal kohe öelda tuule kiirus (mida aknast ei näe) ja ideaalne riietuskomplekt, ning suundu siis enesekindlalt parki.'),
('3d75b744-8440-4e62-83c6-4a08b865c0f7'::uuid,'Йогурттан беткап! 🥣','Тамакты бети-башына сүйкөп алдыбы? Капа болбой, бул тамашалуу учурду баалуу эскерүүгө айлантыңыз! Аны «Бөбөк альбомуна» кошуп, кызыктуу стикерлер менен кооздоп, ошол көз ирмемди сактап калыңыз.','Jogurtimask! 🥣','Kas ta määris just toidu üle näo ja juuste? Selle asemel, et pahandada, muuda see meistriteos hinnaliseks mälestuseks! Lisa see beebialbumisse, kaunista lõbusate kleebistega ja naudi seda hetke.'),
('69c1e419-f8f2-4b2f-90e3-9b51e78ff197'::uuid,'Таймер өчтү, эс алуу убактысы 🍵','Уйку таймерин коюп, бөлмөдөн чыктыңыз. Эми үй жумуштарын токтотуңуз! Өзүңүзгө жыпар жыттуу ромашка чайын демдеп, жылуу буусу менен күндүн чарчоосун таратыңыз.','Taimer helises, aeg puhata 🍵','Panid unetaimeri tööle ja lahkusid toast. Nüüd jäta kodutööd sinnapaika! Valmista endale tassike rahustavat kummeliteed ja lase päeva väsimusel koos sooja auruga hajuda.'),
('934796d5-42af-4c49-9cb9-67f18b657e36'::uuid,'Тиштери кычышып жатабы? 🦷','Акыркы азуу тиштери чыгып жаткан болушу мүмкүн. Кычышкан тиштерин басуу үчүн «Бөбөк рецепттери» бөлүмүнөн шекерсиз, пайдалуу жана муздак жемиш балмуздактарын даярдап бериңиз.','Kas igemed sügelevad? 🦷','Viimased purihambad võivad olla teel. Sügelevate igemete rahustamiseks valmista beebiretseptide sektsioonist jahedaid, suhkruvabu ja tervislikke puuviljapulgajäätiseid.'),
('06d75280-127a-43d4-a7f0-42d2871b24c5'::uuid,'Көз карандысыз ашпозчу! 👨‍🍳','Кашыкты бергиси келбей жатабы? Биздин рецепттерден колго кармаганга ыңгайлуу тамактарды жасап көрүңүз. Өз алдынча тамактанууну көзөмөлдөө үчүн «Тамактануу таймерин» колдонуп, анын табитине көз салыңыз.','Iseseisev kokk! 👨‍🍳','Ei taha lusikat käest anda? Proovi valmistada meie beebiretseptide järgi kergesti haaratavaid näputoite. Kasuta söötmise taimerit, et jälgida iseseisvaid söögikordi ja kontrollida lapse isu.'),
('2102feb2-22f3-4c41-8de6-6f3e115e2d56'::uuid,'Жомоктогудай аягы 🪄','Кадимки жомоктор тажатма болушу мүмкүн. Бул жолу «Интерактивдүү жомоктор» менен балаңызга жомоктун аягын өзү тандоого мүмкүнчүлүк бериңиз. «Кичинекей аюуга ким жардам берди деп ойлойсуң?» деп сурап, анын фантазиясын өстүрүңүз.','Muinasjutuline lõpp 🪄','Klassikalised muinasjutud võivad tüütuks muutuda. Seekord lase lapsel interaktiivsete lugude abil ise lõpplahendus valida. Erguta tema kujutlusvõimet küsimusega: „Kes sinu arvates väikesel karul appi tuli?“'),
('458c2efd-1859-4a36-bc6c-218987ce42a4'::uuid,'Тарелкадагы искусство 🥦','Бөбөгүңүз тамак ичпей жатабы? Кээде маселе даамда эмес, тамактын көрүнүшүндө болот. Жашылчалардан кызыктуу жана түстүү беттерди жасап, анын табитин ачыңыз!','Kunst sinu taldrikul 🥦','Kas su väike laps keeldub söömast? Mõnikord pole probleem maitses, vaid toidu välimuses. Proovi isu äratada, luues erksavärvilistest köögiviljadest lõbusaid ja värvilisi nägusid!'),
('1e03f3e4-2305-4ae5-883c-39581f248697'::uuid,'Сандар менен таанышуу 🔢','Тепкичтен чыгып жатканда же оюнчуктарды тизип жатканда «бир, эки, үч» деп санаганга аракет кылып жатабы? Анын бул математикалык өнүгүүсүн колдоп, чогуу санаңыз.','Numbrite avastamine 🔢','Kas ta üritab trepist ronides või klotse ladudes lugeda „üks, kaks, kolm“? Toeta seda matemaatilist kognitiivse arengu etappi ja loe koos temaga.'),
('2e1f0716-93b5-4be3-9000-fdb28349534d'::uuid,'Атанын жашыруун куралы 🤡','Кадимки ыкмаларыңыз иштебей калганда, атасынын тамашалуу үндөрү жана кызыктуу бет маанайы дароо жардамга келет. Кечки маанайы чөккөн учурда, бул ишти атасына ишенип тапшырыңыз!','Issi salarelv 🤡','Kui tavapärased nipid enam ei aita, võivad issi naljakad hääled ja näod päeva päästa. Õhtuste jonnihoogude ajal ära kõhkle palli talle söötmast!'),
('a57ba6d4-a9da-4163-8ddf-e60b3ee296c5'::uuid,'Энелердин жашыруун тобу 💬','Оор чечим кабыл алуу керекпи? (Мисалы, бала бакча тандоо). Anacan коомчулугундагы тажрыйбалуу энелердин кеңештери эч бир китепте жок реалдуу жана далилденген чечимдерди сунуштайт.','Salajane emmede grupp 💬','Seisad raske valiku ees? (Näiteks lasteaia valimine). Anacani kogukonna kogenud emade nõuanded pakuvad kõige realistlikumaid ja läbiproovitud lahendusi, mida ükski raamat ei suuda anda.'),
('7da1ffab-3792-4ba0-b3b7-ce279478fa15'::uuid,'Аба ырайынын өзгөрүшү жана күтүүсүз бурулуштар ⛅','Сырттагы аба ырайы түшүнүксүзбү – күн ачык, бирок шамалбы? «Аба ырайы жана кийим» куралы аркылуу шамалдын ылдамдыгын билип, эң ылайыктуу кийимди тандаңыз. Ошентип, эшиктин алдында убакыт коротпой, сейилдөөгө ишенимдүү чыгыңыз.','Ilma tujud ja äkilised muutused ⛅','Ilm väljas pole päris selge – päikseline, aga ka tuuline? Lase ilma ja riietuse tööriistal kohe öelda tuule kiirus (mida aknast ei näe) ja soovitada ideaalset riietust. Nii saad kõhklemata ja ukse taga aega raiskamata jalutama minna.'),
('be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e'::uuid,'Жымжырттыктын санариптик өлчөмү 🤫','Акыры уктады! Үйдөгү тынчтыкка ишене албай жатасыз. Үн өлчөгүч тиркемени иштетип, экрандагы 0-10 децибелдик көрсөткүчтү карап, мээңиздин эс алып жатканын сезиңиз.','Vaikuse digitaalne mõõdupuu 🤫','Ta jäi lõpuks magama! Sa ei suuda uskuda majja laskunud vaikust. Aktiveeri helitaseme mõõtja ja tunne visuaalselt, kuidas su aju aeglaselt puhkab, kui vaatad ekraanil 0–10 detsibellist näitu.'),
('4b7fd5a1-3084-40d7-9f2d-e7fb4777d2eb'::uuid,'Күлкүлүү бет маанайлар! 🤪','Алар күзгү алдында кызыктуу бет кубулуштарын жасап жатышабы? Бул шаңдуу көз ирмемди өткөрүп жибербеңиз! Аны «Ымыркайдын фотосессиясы» функциясындагы кызыктуу стикерлер менен кооздоп, альбомуңуздагы эң шайыр сүрөткө айлантыңыз.','Naljakad näod! 🤪','Kas ta teeb peegli ees naljakaid nägusid? Ära lase seda lõbusat hetke käest! Kaunista see beebifotode funktsiooni lõbusate kleebistega ja tee sellest albumi rõõmsaim pilt.'),
('739af07d-8466-4c3f-a164-5e408385ca93'::uuid,'Баарына тырмышып жатабы? 🧗‍♀️','Диван, стол, шкаф... Ал чыныгы кичинекей альпинист! Үйдөгү бул кооптуу, бирок маанилүү кыймыл-аракет жөндөмүн кантип коопсуз өнүктүрүү керектигин «Блогдор» бөлүмүнөн окуңуз.','Ronib igale poole? 🧗‍♀️','Diivan, laud, kapp... Ta on tõeline väike ronija! Loe blogide sektsioonist, kuidas seda riskantset, kuid hädavajalikku motoorset vajadust kodus ohutult rahuldada.'),
('602f2986-8e86-421e-ab71-94038d048ccf'::uuid,'Юристтей сүйлөө 🗣️','Ал силер менен сөз аркылуу соодалашып, «дагы бир аз ойнойюн, анан уктайм» деп жатабы? Анын сүйлөө жөндөмү абдан жакшы өнүгүптүр, бирок өзүңүздүн чек араңызды сактоону унутпаңыз!','Räägib nagu advokaat 🗣️','Kas ta üritab juba sinuga sõnadega kaubelda, öeldes näiteks: „Veel natuke mängida, siis magan“? Tema kõneareng on suurepärane, kuid ära unusta piire hoida!'),
('8ac7016a-7613-48aa-a952-59cc5f8a6354'::uuid,'Шымдары кичинекей болуп калдыбы? 👖','Боюнун өсүү мезгили башталды! Анын учурдагы бою менен салмагын «Өсүү трекерине» киргизип, өнүгүү графигинин жогорулашына сыймыктаныңыз.','Püksid juba väikesed? 👖','Kasvuspurt on täies hoos! Sisesta tema praegune pikkus ja kaal kasvu jälgijasse ja vaata uhkusega, kuidas arengugraafik tõuseb.'),
('db467018-0ec9-41a9-a3a3-3ef1c48cda53'::uuid,'Өнүктүрүүчү оюнчуктарды издөө 🧩','Сизге жөн гана ызы-чуу эмес, ой жүгүртүүнү өстүрүүчү оюнчуктар керек. «Сунушталган товарлар» бөлүмүнөн логикалык жана формаларды үйрөтүүчү табышмактарды (1.5 жаштан жогору) сөзсүз карап көрүңүз.','Otsid arendavaid mänguasju 🧩','Vajad mänguasju, mis pole lihtsalt lärmakad, vaid stimuleerivad ka mõtlemist. Vaata kindlasti meie soovitatud toodete alt loogika- ja kujundimänge (alates 1,5. eluaastast).'),
('df8f7402-1277-45bd-a743-5c24bdaf48e1'::uuid,'Тиш жаруудагы кыйынчылыктар? 🦖','Ачууланганда тиштеп же уруп жатабы? Бул анын сөз менен айта албаган чоң сезимдери болушу мүмкүн. Бул жүрүм-турумду Anacan AI менен кантип жумшак жолго салууну үйрөнүңүз.','Hammaste tuleku mured? 🦖','Kas ta lööb või hammustab, kui on endast väljas? Need on sageli suured tunded, mida ta veel sõnadega väljendada ei oska. Õpi Anacan AI abil seda käitumist õrnalt suunama.'),
('907f2a4d-a45c-43e1-8024-d6c91a18d072'::uuid,'Супермаркеттеги ыйлаактык? 🛒','Коомдук жайда ыйлап, жерге жатып алдыбы? Башкалардын караганына көңүл бурбаңыз. Мындай кризистик кырдаалдарды кантип тынч чечүү керектигин Anacan AI менен талкуулаңыз.','Poes jonnituur? 🛒','Kas tal oli avalikus kohas jonnihoog, nuttis ja viskas end põrandale? Unusta teiste pilgud. Vestle Anacan AI-ga, et õppida meetodeid nende kriiside rahulikult lahendamiseks.'),
('e6ec7f70-00dc-438b-af17-5f764a9d8216'::uuid,'Күндүзгү уйку кыскарып баратабы? ⏱️','Бөбөгүңүз күндүзгү уйкуга каршылык көрсөтүп жатабы? Уйку таймеринин статистикасына көз салыңыз. Балким, бир жолу узак уктоого жана кечирээк жатууга өтүүчү убакыт келгендир.','Uinakud jäävad lühemaks? ⏱️','Kas su väike laps tõrgub uinakute vastu? Hoia silm peal unetaimeri statistikal. Võib-olla on aeg minna üle ühele pikemale uinakule ja varasemale magamaminekuajale.'),
('46ef9700-c667-4312-ac63-98bd03625249'::uuid,'Бут кийим менен болгон күрөш! 👟','Жайында сыртка чыгарда кышкы өтүк кийем деп жатабы? Кээде ага өз алдынча тандоо жасоого уруксат берүү анын эркин жана көз карандысыздыгын бекемдейт.','Kingalahing! 👟','Kas su väike laps nõuab suvel õue minnes talvesaapaid? Mõnikord võib oma valikute tegemine tugevdada tema tahet ja iseseisvust.'),
('5541587a-ad73-4e1d-9174-d4fe1c028c3e'::uuid,'Уктоодон баш тартуубу? 🛌','Оюнга берилип, уктагысы келбей жатабы? Уйку таймерин иштетип, «Ак ызы-чуу» (White Noise) бөлүмүндөгү деңиз толкундарынын үнү менен анын тынчтанышына жардам бериңиз.','Vastu võitleb magamaminekule? 🛌','Liiga hõivatud mängimisega, et magama minna? Käivita unetaimer ja rahusta tema meeli valge müra ookeanilainetega.'),
('c2f59a7d-198f-4c77-831a-cca0b1b7e5e6'::uuid,'Горшокко үйрөтүүгө кызыгуу барбы? 🚽','Балаңыз дааратканага сиз менен кошо кирүүнү талап кылып жатабы? Бул анын даярдыгынын эң сонун белгиси! «Блогдор» бөлүмүнөн горшокко үйрөтүүнү качан жана кантип баштоо керектигин окуп, даяр болуңуз.','Huvi potitreeningu vastu? 🚽','Kas su laps nõuab, et tuleksid temaga tualetti kaasa? See on suurepärane märk visuaalsest valmisolekust! Loe meie blogidest, millal ja kuidas potitreeninguga alustada, ning ole valmis.'),
('45af46ac-18bf-499b-a5c7-56bbe71e4564'::uuid,'Тынчтыкка өтүү 🎶','Күн бою чуркаган кичинекей буттар эс ала турган убакыт келди. «Ак ызы-чуу» бөлүмүндөгү унаанын бир калыптагы тынчтандыруучу үнү менен уйку үчүн эң сонун шарт түзүңүз.','Rahunemise aeg 🎶','On aeg puhata neil väikestel tegusatel jalgadel, mis on terve päeva ringi jooksnud. Loo ideaalne uneõhkkond valge müra autosisemüra rahustava ja monotoonse üminaga.'),
('47b68bdb-a1fd-4da7-9316-dcca5fdae94f'::uuid,'Сизге да досторуңуз керек! 👯‍♀️','Балаңыз паркта ойноп жатканда башка энелер менен баарлашкыңыз келеби? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн оюн топтору бар борборлорду таап, таанышыңыз.','Sina vajad ka oma sõpru! 👯‍♀️','Kas soovid teiste emadega vestelda, kuni laps pargis mängib? Avasta meie „Emadele sobivate asukohtade“ alt mängugruppidega keskused ja suhtle.'),
('aaf473f6-79bc-44cf-97f4-687dfa4eb293'::uuid,'Сууну жактырбайбы? 💧','Эртең мененки жалаягы кургакпы? Балким, суюктукту көбүрөөк ичирүү керек. Муну «Жалаяк трекерине» белгилеп, тиркемедеги жемиш кошулган суу рецепттерин жана чөйчөктөрдүн түрлөрүн карап көрүңүз.','Ei meeldi vesi? 💧','Kas hommikune mähe oli liiga kuiv? Võib-olla on aeg vedeliku tarbimist suurendada. Märgi see mähkmete jälgijasse ja vaata rakendusest puuviljadega maitsestatud vee retsepte ning erinevaid nokaga tasse.'),
('ff614b36-4091-473e-b7fa-91411bd4e2a9'::uuid,'Бекем сөөктөр! 🦴','Бүгүн кальций менен D витаминин жетиштүү алдыбы, «Тамактануу трекери» аркылуу эсептеп көрүңүз. Бул эки элемент физикалык өнүгүү үчүн абдан маанилүү.','Tugevamad luud! 🦴','Kasuta toitumise jälgijat, et arvutada, kas ta on täna saanud piisavalt kaltsiumi ja D-vitamiini. Need kaks elementi on kiireks füüsiliseks arenguks hädavajalikud.'),
('6d72635f-ba12-4c8b-b7ef-f626dd634dce'::uuid,'Эртең мененки энергия башкача! ⚡','Бөбөгүңүз сулу боткосун жебей жатабы? «Бөбөк рецепттеринен» жемиш жана жержаңгак майы кошулган смузини таап, «Тамактануу трекери» аркылуу анын калориясын оңой толуктаңыз.','Hommikune energia on teistsugune! ⚡','Kas su väike laps keeldub kaerahelbepudrust? Avasta meie beebiretseptide alt puuviljane maapähklivõi-smuuti ja saavuta toitumise jälgija abil hõlpsalt tema kalorivajadus.'),
('0a81bd63-014b-4d25-b347-1808455aea49'::uuid,'Сыртка чыгып жатасыздарбы? 🏃‍♀️','Үйдөгү чексиз энергияны кантип сарптоону билбей жатасызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн балаңыз эркин чуркап ойноп жатканда, сиз кофе ичип эс ала турган коопсуз оюн борборлорун табыңыз.','Käite palju väljas? 🏃‍♀️','Kas kodus on raske seda piiritut energiat ära kulutada? Avasta „Emadele sobivate asukohtade“ alt turvaline mängukeskus, kus saad nautida kohvi, kuni laps vabalt jookseb ja mängib.'),
('657f4585-c7bb-41c0-9574-51e8f943398b'::uuid,'Чачылган, бирок өз алдынча! 🥣','Өзү тамактанганга аракет кылып жатабы? «Тамактануу таймерин» иштетип, процесстин узактыгын көзөмөлдөңүз жана бул көз карандысыздык анын майда моторикасына кандай таасир этерин белгилеп коюңуз.','Sassis, aga iseseisev! 🥣','Nõuab ise söömist? Käivita söötmise taimer, jälgi protsessi kestust ja märgi üles, kuidas see iseseisvus tema peenmotoorikat arendab.'),
('7feaa5c7-f1f9-4df2-a08a-b9cef56c0ce4'::uuid,'Түнкүсүн ойгонуулар кайра башталдыбы? ⏱️','20 айлык кезиндеги уйкунун бузулушу болушу мүмкүн. Уйку таймеринин графигин текшерип, күндүзгү уйкусун 15 мүнөткө кыскартуу керекпи же жокпу, карап көрүңүз.','Kas öised ärkamised on tagasi? ⏱️','Võib-olla on käimas 20-kuuse une-regressioon. Kontrolli unetaimeri graafikut ja vaata, kas on aeg uinakut 15 minuti võrra lühendada.'),
('385a8205-8e28-4c23-94fa-a2a8fe32e28c'::uuid,'Өзүңүздү күнөөлөбөңүз 📝','Бүгүн үнүңүз бир аз катуу чыгып кеттиби? Өзүңүздү күнөөлөбөңүз. Ичиңиздеги тынчсызданууну «Маанай күндөлүгүнө» жазып, сиздин эң сонун эне экениңизди унутпаңыз.','Ära tunne süüd 📝','Kas su hääl läks täna natuke valjemaks? Ära ennast süüdista. Vala oma sisemised mured meeleolupäevikusse ja pea meeles, et teed suurepärast tööd.'),
('49b18c8f-b30b-4368-9445-6af88b1d8115'::uuid,'Эки сөздөн турган сүйлөмдөр! 🗣️','«Апа, кел! Топ бер!» – Анын сөз байлыгы тез өсүп жатат! Сүйлөөгө болгон бул таттуу аракеттерин үн же видео катары «Бөбөк альбомуна» дароо кошуп, өмүр бою сакталуучу эскерүүгө айлантыңыз.','Kahesõnalised laused! 🗣️','„Emme, tule! Anna pall!“ – Tema sõnavara kasvab kiiresti! Lisa need armsad kõnekatsetused kohe hääl- või videosalvestistena beebialbumisse ja muuda need elukestvateks mälestusteks.'),
('5d516faa-7c77-4db9-b201-49bff969e3d8'::uuid,'Бекем сөөктөр үчүн кальций 🦴','Дайыма кыймылда болгон бөбөк үчүн сөөктөр бекем болушу керек! «Тамактануу трекери» аркылуу бүгүн кальцийди (сыр, йогурт сыяктуу) жетиштүү алганын текшерип, норманы сактаңыз.','Kaltsium tugevate luude jaoks 🦴','Alati liikuva väikese lapse jaoks on tugevad luud hädavajalikud! Kasuta toitumise jälgijat, et kontrollida tänast kaltsiumitarbimist (nt juustust ja jogurtist) ja veenduda, et ta saab soovitatud koguse.'),
('3b603489-95c3-4a32-b0e0-5191fc844b75'::uuid,'''Өзүм кийинем'' деген күрөш 👕','«Бул көйнөктү кийбейм!» – Өжөрлүк башталдыбы? Эртең мененки кийинүү талаштарын азайтуу жана ага тандоо укугун берүү жолдорун Anacan AIдан сураңыз.','„Tahan ise riidesse panna“ lahing 👕','„Ma ei taha seda särki!“ Kas jonnakus on alanud? Küsi Anacan AI-lt nippe hommikuste riietumisvõitluste vähendamiseks ja anna talle valikuõigus.'),
('89933e6a-484e-4f2e-bf20-8262f6a74c72'::uuid,'Омега-3 запасы 🐟','Мээнин өнүгүүсү эч качан токтобойт! Бул жумада балык же жаңгак жетиштүү берилгенин «Тамактануу трекери» аркылуу текшерип, жетишсиздик болсо белгилеп коюңуз.','Omega-3 varud 🐟','Aju areng ei peatu kunagi! Kontrolli toitumise jälgija abil, kas ta on sel nädalal saanud piisavalt kala või kreeka pähkleid, ja märgi kindlasti üles kõik puudujäägid.'),
('fa46cf0a-85f0-484c-8aa5-b60eb52b320b'::uuid,'Үйдө энергияны сарптап жатабы? 🏃‍♂️','Үйдө отуруп калдыңызбы? Анын энергиясын сарптоого жардам бериңиз! «Сунушталган товарлар» бөлүмүнөн үйдө колдонууга ылайыктуу мини-батуттарды же слайддарды карап көрүңүз.','Kulutad kodus energiat? 🏃‍♂️','Oled toas kinni? Aita tal energiat kulutada! Vaata meie soovitatud toodete alt siseruumidesse mõeldud minitrampliine või liumägesid.'),
('00691751-d785-4fc6-8036-d313adccdad6'::uuid,'Эртең мененки жалаякты текшерүү! 🧻','Жоолуктардын кургак болушу тез-тезден болуп жатабы же ичеги-карындын иштеши жайлап баратабы? Ымыркайдын суюктукка жана клетчаткага болгон муктаждыгын дароо талдоо үчүн «Жоолуктарды көзөмөлдөө» бөлүмүнө эртең мененки алмаштырууну белгилеп коюңуз.','Hommikune mähkmete kontroll! 🧻','Kas kuivad mähkmed muutuvad sagedasemaks või on seedimine aeglustumas? Märgi hommikune mähkmevahetus mähkmejälgijasse, et analüüsida koheselt oma pisikese vedeliku- ja kiudainevajadust.'),
('0bde6683-6d18-4d98-bc39-b122396c0b17'::uuid,'Эс алып, жайланышуу убактысы 🍵','Чуркоо-секирүү бүттү! Биздин пайдалуу рецепттерден суусундук даярдап алыңыз, анан диванга жатып, жөн гана тынчтыктан ырахат алыңыз.','Aeg lõõgastuda ja puhata 🍵','Ringijooksmine on läbi! Valmista meie tervislike retseptide järgi jook, heida diivanile ja naudi lihtsalt vaikust.'),
('0eecf770-9ba2-463c-9b39-bbe24d01b4e1'::uuid,'''Меники!'' фазасыбы? 🧸','Сиздин бөбөгүңүз сейил бакта башка балдардын оюнчуктарын тартып алабы? Anacan AI аркылуу бул «меники!» деген учурларды жөнгө салуунун эң натыйжалуу психологиялык ыкмаларын үйрөнүңүз.','„Minu oma!“ faas? 🧸','Kas su pisike napsab pargis teistelt lastelt mänguasju? Õpi Anacan AI abil kõige tõhusamaid psühholoogilisi strateegiaid nende „minu oma!“ hetkede haldamiseks.'),
('9867089b-80a4-4895-985d-1e1d5fa3df95'::uuid,'Уйкуңуз келип жатабы? 😴','Бөбөгүңүз уктаганда, сиз да жатып эс алыңыз. Эгер уйкуңуз келбесе, «Аялдар үчүн пайдалуу рецепттер» бөлүмүнөн антиоксидантка бай көк чай ичип, сергип алыңыз.','Tunned end unisena? 😴','Kui beebi magab, heida ka ise pikali. Kui sa ei saa magada, värskenda end antioksüdantiderikka rohelise teega jaotisest „Tervislikud retseptid naistele“.'),
('a5fedf21-2dca-46ed-9476-0b415ced68a5'::uuid,'Уктоодон баш тартуубу? 🛌','19-ай «уйкунун артка кетиши» менен белгилүү. Уйку таймерин иштетип, графикти текшериңиз; балким, күндүзгү уйкуну кыскартуунун дал убагы келгендир!','Vastu võitleb magamaminekule? 🛌','19. elukuu on tuntud „une regressioonide“ poolest. Käivita unetaimer ja kontrolli graafikut; võib-olla on õige aeg päevaseid uinakuid lühendada!'),
('39db43fc-07a0-417e-90da-c0bbbd5f14a4'::uuid,'Ичи ооруп жатат деп ойлойсузбу? 💩','Эртең мененки жоолугун алмаштырып жатканда, заңын байкап көрүңүз. Эгер ич катуу коркунучу болсо, Anacan AI''дан дароо табигый каражаттарды жана массаж ыкмаларын сураңыз.','Kahtlustad kõhuvalu? 💩','Märgi hommikust mähkmevahetust tehes lapse väljaheite vaatlused üles. Kui on kõhukinnisuse oht, küsi Anacan AI-lt koheseid looduslikke vahendeid ja massaaživõtteid.'),
('613cd9e2-958a-41bd-b191-0de3ff8ec07f'::uuid,'Бүгүн канча жолу ''жок'' деди? 🙉','Тартипке көнбөгөн бөбөк менен иштөө чоң сабырдуулукту талап кылат. Ички чыңалууңузду «Маанай күндөлүгүнө» жазып, сезимдериңизди эч кимге айыпталбай чыгарып алыңыз.','Mitu „ei“-d täna tuli? 🙉','Väljakutseid pakkuva lapsega toimetulek nõuab tohutut kannatlikkust. Pane oma sisemine pinge kirja meeleolupäevikusse ja vabasta oma tunded ilma hinnanguteta.'),
('68ef19de-c144-4be9-8878-9cc1b34a6483'::uuid,'Уктап калуу үчүн канча убакыт кетет? ⏱️','Төшөктө оодарылып жатасызбы? Уйку таймерин иштетип, анын уктап калышына канча убакыт кеткенин жазып алыңыз. Балким, кечки оюн убактысын эрте бүтүрүү керек чыгар.','Kui kaua uinumine aega võtab? ⏱️','Vähkred voodis? Aktiveeri unetaimer ja märgi üles, kui kaua neil uinumine aega võtab. Võib-olla peaks õhtused mänguajad varem lõpetama.'),
('70a3e410-6335-466b-99bc-28ac0c3d913f'::uuid,'Эмнеге күтүүсүз ыйлап жатат? 🤖','Түнкүсүн ыйлап ойгонуп, соороно албай жатабы? Түнкү коркунучтар боюнча тынчсызданууларыңыз менен дароо Anacan AI адисине кайрылыңыз жана туура кадамдарды үйрөнүңүз.','Miks need äkilised pisarad? 🤖','Kas laps ärkab öösel karjudes ega lase end lohutada? Pöördu kohe Anacan AI eksperdi poole oma muredega öiste hirmuhoogude pärast ja saa teada, milliseid samme astuda.'),
('80e71246-05ae-4bc6-857d-5ce3af704b5e'::uuid,'Апанын энергия булагы? 🥗','Бөбөгүңүздүн артынан чуркап, чарчап бүттүңүзбү? Таттууларды таштап, белокко өтүңүз! «Аялдар үчүн пайдалуу рецепттерден» энергия берүүчү жержаңгак смузисин даярдап ичиңиз.','Emme energiaallikas? 🥗','Kas tunned end pisikese järel jooksmisest täiesti kurnatuna? Jäta maiustused vahele ja vali valk! Valmista meie „Tervislike retseptide naistele“ abil kiire energiat andev maapähklivõi smuuti.'),
('145211fa-74d2-4e28-8a64-c14921db5185'::uuid,'Өзүңүзгө баа бериңиз! 🌟','Бүгүн аны ыйлатпай тамактандыра алдыңызбы? Эң кичинекей ийгилигиңизди да «Маанай күндөлүгүнө» жазып, өзүңүздүн укмуштуудай энелик жөндөмүңүз үчүн өзүңүздү мактап коюңуз.','Ole enda üle uhke! 🌟','Kas õnnestus neid täna ilma pisarateta toita? Kirjuta isegi oma väikseim õnnestumine meeleolupäevikusse ja kiida end oma suurepäraste vanemlike oskuste eest.'),
('4f60f5e8-df5e-4892-aa2e-dcffda8f877b'::uuid,'Суу ичүү абдан маанилүү 💧','Активдүү оюн суусузданууга алып келиши мүмкүн. «Жоолуктарды көзөмөлдөө» бөлүмүнө эртең мененки белгини коюп, «Сунушталган товарлар» бөлүмүнөн балдар оңой ача турган спорттук суу бөтөлкөлөрүн карап көрүңүз.','Vedeliku tarbimine on võtmetähtsusega 💧','Aktiivne mäng võib põhjustada dehüdratsiooni. Tee hommikul märge mähkmejälgijasse ja vaata jaotist „Soovitatavad tooted“, et leida spordijoogipudeleid, mida nad ise kergesti avada saavad.'),
('edd993f1-ac76-4300-8ed0-6009d7897f2b'::uuid,'Башка апалар менен баарлашуу? ☕','Бир гана балаңыз менен сүйлөшүүдөн тажадыңызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн энелер чогулган балдарга ылайыктуу кафелерди таап, өзүңүзгө социалдык баарлашуу белегин тартуулаңыз.','Suhtled teiste emadega? ☕','Kas oled väsinud sellest, et vestled ainult oma lapsega? Leia laste-sõbralikke kohvikuid meie jaotisest „Emadele sobivad kohad“, kus emad kokku saavad, ja kingi endale sotsiaalne ühendus.'),
('e893b0aa-e3fc-4f78-a970-b681a0ed0450'::uuid,'Тырмышуу боюнча чемпион! 🧗','Үйдөгү эмеректер анын тырмалап чыгуусуна аздык кылып жатабы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн жумшак тосмолору бар балдар оюн борборун таап, анын изилдөө каалоосун коопсуз канааттандырыңыз.','Ronimise meister! 🧗','Kas kodumööbel ei ole nende ronimisseiklusteks piisav? Leia meie „Emadele sobivate kohtade“ hulgast pehmete barjääridega siseruumides asuv mängukeskus ja rahulda ohutult nende uurimisvajadust.'),
('6f516c4d-5db5-4d3e-8fca-8c461e614752'::uuid,'Темирдин деңгээли жетиштүүбү? 🥩','Активдүү бөбөгүңүздө темир жетишсиздиги болбошу үчүн, бүгүнкү темирдин өлчөмүн (эт, буурчак өсүмдүктөрү) «Тамактанууну көзөмөлдөө» бөлүмүнөн текшерип, менюсун ошого жараша тууралаңыз.','Kas su rauavarud on piisavad? 🥩','Et su aktiivsel pisikesel ei tekiks rauapuudust, kontrolli tänast rauatarbimist (liha, kaunviljad) toitumisjälgijas ja kohanda nende menüüd vastavalt.'),
('b003834c-8ce3-4da4-a17e-0b837c04f7f7'::uuid,'Кальций запасын текшерип жатасызбы? 🧀','Тез өсүп жаткан сөөктөр көп кальцийди талап кылат! Бүгүнкү жеген сыр жана йогурттун өлчөмүн текшерүү үчүн «Тамактанууну көзөмөлдөө» бөлүмүн колдонуңуз жана жетишсиздикти толуктаңыз.','Kontrollime kaltsiumivarusid? 🧀','Kiiresti kasvavad luud vajavad palju kaltsiumi! Kasuta toitumisjälgijat, et vaadata üle tänane juustu ja jogurti tarbimine ning veenduda, et kõik vajadused on rahuldatud.'),
('b5cae897-2c37-4223-8c5a-201bd9d0229a'::uuid,'Сырдуу токой үндөрү 🍃','Бүгүн өтө ызы-чуулуу жана стресске толгон күн болдубу? Экөөңүздөрдүн тең нерв системаңызды тынчтандыруу үчүн «Ак ызы-чуу» (White Noise) бөлүмүнөн жалбырактардын шыбыраган үнүн коюңуз.','Salapärased metsahelid 🍃','Kas oli väga lärmakas ja stressirohke päev? Pane „Valgest mürast“ mängima lehtede sahin, et rahustada mõlema närvisüsteemi.'),
('20cf6725-2fdc-45bb-965b-09069424fe0a'::uuid,'Шекерсиз таттуулар 🍪','Дүкөндөн печенье сатып алуунун кажети жок! Биздин балдар рецепттеринен 10 мүнөттө даяр боло турган курма жана сулу кошулган пайдалуу таттууларды табыңыз.','Suhkruvabad vahepalad 🍪','Poeküpsiseid pole vaja! Avasta meie beebiretseptide hulgast tervislikud kodused datli- ja kaerahelbemaitselised maiused, mis valmivad vaid 10 minutiga.'),
('f527de5c-afa8-4884-a173-da37070a2826'::uuid,'Үйдөгү кичинекей жардамчыңызбы? 🧹','Тазалык кылып жатканда, кичинекей жардамчыңыз столду чүпүрөк менен сүрткөнгө аракет кылып жатабы? Бул жоопкерчиликтүү учурду «Бөбөк альбомуна» сүрөткө тартып, сыймыктануу менен сактап коюңуз!','Sinu väike abiline kodus? 🧹','Kas su väike abiline püüab koristades lapiga lauda pühkida? Jäädvusta see armas tärkava vastutustunde hetk ja tee sellest uhke sissekanne oma beebialbumisse!'),
('18518788-d8e2-4971-93f7-6fbf0592ca33'::uuid,'Урганда же түрткөндө... 🛑','Балаңыз капа болгондо күтүлбөгөн жерден агрессия көрсөтүп жатабы? 20 айлык курактагы бул жүрүм-турумду оюн түрүндөгү өз ара аракеттенүү жана стратегиялар менен кантип чечүү керектигин билүү үчүн Anacan AI менен кеңешиңиз.','Kui ta lööb või tõukab... 🛑','Kas su laps muutub frustreerituna äkki agressiivseks? Konsulteeri Anacan AI-ga, et õppida, kuidas seda 20-kuuse lapse käitumist mänguliste suhtlusviiside ja strateegiatega lahendada.'),
('a6200253-33e2-4142-a4a9-811aa67d4feb'::uuid,'Сиз бүгүнкү күндүн баатырысыз 🧘‍♀️','Бөбөк уктады. Үй жумуштарынын баарын токтотуңуз. Маанай күндөлүгүнө сезимдериңизди жазыңыз, жагымдуу музыка коюп, бул кечти өзүңүзгө арнаңыз.','Oled tänane kangelane 🧘‍♀️','Laps magab. Jäta kõik kodutööd pooleli. Kirjuta oma tunded meeleolupäevikusse, pane mängima rahustav muusika ja pühenda see õhtu vaid iseendale.'),
('eefd67fd-3835-4f65-abf3-9ced6b705e30'::uuid,'Тамактануу учурундагы сабырдуулук сынагы ⏱️','Бир кашык тамакты 5 мүнөт жеп жатабы? «Тамактануу таймерин» иштетип, сабырдуу болуңуз жана колдонмодогу отчет аркылуу анын табитинин өнүгүүсүн так талдаңыз.','Söömise kannatlikkuse proovikivi ⏱️','Kas neil kulub ühe lusikatäie söömiseks 5 minutit? Käivita söötmistaimer, harjuta kannatlikkust ja analüüsi rakendusesisese aruande abil täpselt nende söögiisu arengut.'),
('070b2f75-0440-4e85-b828-292900301f9e'::uuid,'Фантазиялык оюндар башталды! 🧸','Балаңыз оюнчук аюусуна суу берип жатабы же сиздин «жараатыңызды» дарылап жатабы? Эмпатиянын өнүгүп жаткан бул баалуу учурларын «Бөбөк альбомуна» видео түрүндө сактап, келечекте эстеп жүрүңүз.','Fantaasiamängud lendavad! 🧸','Kas su laps annab oma mängukarule vett või „ravib“ sinu haiget kohta? Säilita need väärtuslikud empaatia arengu hetked, lisades need video ja heliga oma beebialbumisse tuleviku tarbeks.'),
('388f83f4-0bb5-4306-abf6-b75f9dc65017'::uuid,'Темирдин деңгээлин текшерүү 🥩','Активдүү булчуңдар жана дени сак өнүгүү үчүн темир жетишсиздигине жол бербөө керек. Бүгүнкү темирдин өлчөмүн (эт, буурчак өсүмдүктөрү) текшерүү үчүн «Тамактанууну көзөмөлдөө» бөлүмүн колдонуңуз жана жетишсиздикти дароо толуктаңыз.','Rauataseme kontroll 🥩','Aktiivsete lihaste ja tervisliku arengu jaoks tuleb vältida rauapuudust. Kasuta toitumisjälgijat, et kontrollida tänast rauatarbimist (liha, kaunviljad) ja kompenseerida koheselt kõik puudujäägid.'),
('9cb7efe6-c6c0-4032-89de-12eeec5119ee'::uuid,'Ызы-чуудан тынчтыкка өтүү 🎶','Телевизор жана оюнчуктардын үнүнөн кийинки күтүлбөгөн тынчтык тынчсыздандырышы мүмкүн. Бөлмөгө «Ак ызы-чуу» бөлүмүнөн чач кургаткычтын үнүн коюп, бул бир калыптагы үн анын уйку чөйрөсүнө кандай таасир этерин байкаңыз.','Üleminek helidelt vaikusele 🎶','Äkiline vaikus pärast teleri- ja mänguasjade helisid võib olla häiriv. Pane toas mängima föönimüra „Valgest mürast“ ja vaata, kuidas see monotoonne heli nende unekeskkonda positiivselt mõjutab.'),
('847e9a71-981a-4920-b6be-a1986674dd92'::uuid,'Бүтпөгөн тамактануу шоусу ⏱️','Тамак менен ойноп, жерге чачып, бирок жебей жатабы? Тамактануу таймерин иштетип, сабырдуу болуңуз жана бул көз карандысыз этапта анын табитинин өнүгүүсүн колдонмодогу график аркылуу кылдат талдаңыз.','Lõputu söömisetendus ⏱️','Kas nad mängivad toiduga, viskavad selle põrandale, aga ei söö? Käivita söötmistaimer, ole kannatlik ja analüüsi rakendusesisese graafiku abil hoolikalt nende söögiisu arengut sellel iseseisvumise perioodil.'),
('890ee8d7-3315-4b7a-994a-c41900d8c960'::uuid,'Эң сонун өнүктүрүүчү оюнчукту табуу? 🧩','Балаңыз фигураларды тешиктерине тууралап салууну үйрөндүбү? Анын акылын дагы да курчутуу үчүн «Сунушталган товарлар» бөлүмүнөн курагына ылайыктуу пазлдарды табыңыз.','Otsid täiuslikku arendavat mänguasja? 🧩','Kas su laps on omandanud kujundite aukudesse sobitamise? Avasta meie „Soovitatavate toodete“ jaotisest eakohaseid puslesid, et nende mõtlemist veelgi arendada ja teravdada.'),
('2e662854-2d0b-4e0d-be84-f71f33b1ed5b'::uuid,'Эмнеге күтүүсүз ыйлап жатат? 🤖','Бир мүнөт кубанып ойноп жатып, кийинки мүнөттө ыйлап жибердиби? Бул эмоционалдык өйдө-ылдыйлардын себебин түшүнүү үчүн Anacan AI эксперттик жардамчыбыздан сураңыз.','Miks need äkilised pisarad? 🤖','Kas nad mängisid ühel hetkel rõõmsalt ja puhkesid järgmisel hetkel nutma? Küsi meie Anacan AI eksperdilt, et mõista nende emotsionaalsete tõusude ja mõõnade põhjuseid.'),
('b30cbe06-794a-4924-bc78-63ebe289b716'::uuid,'Мээнин өнүгүүсү эч качан токтобойт 🧠','Ал баарын сорттогонду жакшы көрөт! 20-21 айлык балдар үчүн түстөрдү жана формаларды кабыл алууну өркүндөтүүчү үй оюндары тууралуу «Блогдор» бөлүмүндөгү макаланы сөзсүз окуңуз.','Aju areng ei peatu kunagi 🧠','Nad armastavad kõike sorteerida! Loe kindlasti blogide jaotisest artiklit koduste mängude kohta, mis parandavad 20–21-kuuste laste värvi- ja kujunditaju.'),
('dcfe0150-6b59-46be-be17-cba289272768'::uuid,'5 мүнөттүк энергия заряды? 🔋','Ачкарын кофе ичүү түштөн кийин энергиянын кескин төмөндөшүнө алып келет. Анын ордуна «Пайдалуу рецепттерден» даамдуу, тез даярдалуучу жана ток кармоочу сулу кексин тандаңыз!','5-minutiline energialaeng? 🔋','Tühja kõhuga kohvi joomine võib põhjustada pärastlõunase energiakriisi. Vali selle asemel meie tervislike retseptide hulgast maitsev, kiiresti valmiv ja kõhtu täitev kaerakukkel!'),
('41523bc6-ac22-4b48-a7b5-8663ed9c74c3'::uuid,'Кум менен ойноо кызыктуу! 🏖️','Анын бир аз кир болушунан коркпоңуз! «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн кумдуу аянтчасы бар жерди табыңыз. Кумга тийүү сезими өнүгүү үчүн кымбат оюнчуктардан да пайдалуу.','Liivakastimängud! 🏖️','Ära karda lasta neil veidi määrduda! Leia meie „Emadele sobivate kohtade“ hulgast liivakastiga koht. Liiva puudutamise sensoorne kogemus on arengule kasulikum kui kallid mänguasjad.'),
('863859ae-c920-41fe-b876-915ee50bba17'::uuid,'Кичинекей сүрөтчү иштеп жатат! 📸','Ал өзүн жана дубалды боёп салдыбы? Капа болгондун ордуна, бул күлкүлүү чийме учурун «Бөбөк альбомуна» жүктөп, ага кызыктуу стикерлерди кошуп коюңуз.','Väike kunstnik töös! 📸','Kas nad värvisid ennast ja seina? Selle asemel, et pahandada, laadi see lõbus kritseldamise hetk beebialbumisse ja lisa sellele vahvaid kleebiseid.'),
('af623bf2-6a45-452d-a9c0-bd16d67bf74d'::uuid,'Блинчик жегич 🥞','Бөбөгүңүз эртең мененки тамактан баш тартып жатабы? «Бөбөк рецепттериндеги» шекерсиз банан куймагынын рецептин карап көрүңүз. Ал өзү жегенди жакшы көрөт, балким, бул анын табитин ачат!','Pannkoogikoletis 🥞','Kas su pisike keeldub hommikusöögist? Vaata meie beebiretseptide hulgast suhkruvaba banaanipannkoogi retsepti. Neile meeldib ise süüa ja see võib nende söögiisu äratada!'),
('a7786d73-a362-4a32-a77f-3c09e4ab2ffb'::uuid,'Суу менен ойноо физикасы! 🛁','Балаңыз ваннада сууну бир чөйчөктөн экинчисине талыкпай куюп жатабы? Бул изилдөөсүнө дем берүүчү кызыктуу жана тынчтандыруучу суу оюнчуктарын «Сунушталган товарлар» бөлүмүнөн карап көрүңүз.','Veemängude füüsika! 🛁','Kas su laps valab vannis väsimatult vett ühest tassist teise? Vaata meie „Soovitatavaid tooteid“, et leida lõbusaid ja rahustavaid veemänguasju, mis seda avastamist soodustavad.'),
('ccc521b5-a8ef-4b74-a8d7-bf2ba2f22793'::uuid,'Кальций калканы 🦴','Кальций тиштердин жана сөөктөрдүн бекемдиги үчүн өтө маанилүү. Бөбөгүңүздүн бүгүн йогурт жана сыр аркылуу күнүмдүк нормасын алганын текшерүү үчүн «Тамактанууну көзөмөлдөө» бөлүмүн колдонуңуз.','Kaltsiumikilp 🦴','Kaltsium on ülioluline tugevate hammaste ja luude jaoks. Kasuta toitumisjälgijat, et kinnitada, kas su pisike sai täna kätte oma päevase jogurti- ja juustukoguse.'),
('e8d46282-de1c-4981-9242-f0dff7014b1d'::uuid,'Күн тартибин талдап көрөлү ⏱️','Кечки уйкуга чейинки ойгоо убактысы өтө узарып баратабы? Уйку таймерин иштетип, графикти көзөмөлдөңүз. Балким, күндүзгү уйкусун 15 мүнөткө кыскартуунун убагы келгендир.','Analüüsime rutiini ⏱️','Kas nende õhtune ärkvelolekuaeg muutub liiga pikaks? Käivita unetaimer ja jälgi graafikut. Võib-olla on aeg nende uinakut 15 minuti võrra lühendada.'),
('527e5a17-444d-47c4-8578-4ebb1ee870b1'::uuid,'Таттуу уйкубу же уйку үчүн күрөшпү? 🛌','Эгер уктатуу чоң кризиске айланса, 21 айлык балдар үчүн уйкуга өтүү ырым-жырымдары жана психологиялык амалдар боюнча дароо Anacan AI''дан сураңыз.','Magus uni või unelahing? 🛌','Kui magamaminekust on saanud suur kriis, küsi kohe Anacan AI-lt 21-kuustele lastele sobivaid unerituaale ja psühholoogilisi nippe.'),
('9c6e3d93-ba09-4cda-8c01-9c820b1e3ed6'::uuid,'Түнүңүз кандай өттү? 🌙','Эгер эртең мененки жоолугу өтө оор болсо, уктаар алдында ичкен суюктугун азайтуу керек болушу мүмкүн. Муну «Жоолуктарды көзөмөлдөө» бөлүмүнө белгилеп, анын күнүмдүк суу балансын текшериңиз.','Kuidas öö möödus? 🌙','Kui nende hommikune mähe on väga raske, pead võib-olla enne magamaminekut nende vedelikutarbimist kohandama. Märgi see mähkmejälgijasse ja kontrolli nende üldist päevast vedelikutarbimist.'),
('ac8ebb1f-1fc4-47f7-86d8-2eb0fa26e0a4'::uuid,'Майда моторика 🧩','Бөбөгүңүз фигураларды бири-бирине тууралап салуунун чебери болуп баратат! Анын таанып-билүү жөндөмүн өстүрүү үчүн курагына эң ылайыктуу пазлдарды «Сунушталган товарлар» бөлүмүнөн табыңыз.','Peenmotoorika 🧩','Su pisike on muutumas kujundite sobitamise meistriks! Avasta „Soovitatavate toodete“ jaotisest nende vanusele ideaalselt sobivaid puslesid, et nende kognitiivset arengut veelgi turgutada.'),
('b322d3bf-6cd3-46c1-9a5f-bb9f3a106c60'::uuid,'Эс алуу убактысы 🎶','Чарчаңкы күн акыл-эсти чарчатышы мүмкүн. «Ак ызы-чуу» бөлүмүнөн токойдун шыбыраган үнүн коюп, бөлмөдө уйкуну чакыруучу тынч атмосфера түзүңүз.','Rahunemise aeg 🎶','Tihe päev võib olla vaimselt kurnav. Loo toas täiuslikult rahustav, und soodustav õhkkond, mängides „Valgest mürast“ metsa sahinat.'),
('d93eedfc-78de-4d26-810d-89c2b8c71690'::uuid,'Өзүңүзгө кофе менен сый көрсөтүңүз ☕','Күн бою чуркап чарчадыңызбы? Өзүңүзгө татыктуу эс алуу тартуулаңыз! «Энелер үчүн ыңгайлуу жайлар» картасы аркылуу балдар аянтчасы бар кафени табыңыз.','Premeeri end kohviga ☕','Kas tunned end kogu päeva ringijooksmisest kurnatuna? Kingi endale väljateenitud paus! Leia „Emadele sobivate kohtade“ kaardilt laste mängunurgaga kohvik.'),
('a1bb5dc0-7875-44dc-a4df-f9fa8c0a427f'::uuid,'Тамак сиңирүү белгилери 💩','Катуу тамак-ашка толук өтүү кээде сиңирүү процессин бир аз кыйындатышы мүмкүн. Эртең мененки жалаяк алмаштырууну «Жалаякка көз салуу» бөлүмүнө белгилеп, алардын суюктук жана клетчаткага болгон муктаждыгын жөнгө салуу керекпи же жокпу, оңой байкап туруңуз.','Seedimise märgid 💩','Täielik üleminek tahkele toidule võib vahel seedimise veidi keeruliseks muuta. Märgi hommikune mähkmevahetus mähkmejälgijasse, et näha, kas pead lapse vedeliku- ja kiudainete tarbimist kohandama.'),
('c4d895de-4842-4a9b-ae46-1557c6e3d2cc'::uuid,'Табигый тынчтандыруучу каражаттар 🍃','Бүгүн өтө ызы-чуулуу жана стресске толгон күн болдубу? Экөөңүздөрдүн тең нерв системаңызды тынчтандыруу үчүн «Ак ызы-чуу» (White Noise) бөлүмүнөн жалбырактардын шыбыраган үнүн коюңуз.','Looduslikud rahustid 🍃','Kas oli väga lärmakas ja stressirohke päev? Pane „Valgest mürast“ mängima lehtede sahin, et rahustada mõlema närvisüsteemi.'),
('f1307d3d-156d-45b5-82ac-2f5c2abfa1a3'::uuid,'Күнүмдүк кийинүү күрөшүбү? 👗','«Мен бул көйнөктү кийбейм!» Алардын өжөрлүгү түгөнбөй жатабы? Эртең менен кийинүүдөгү талаш-тартыштарды жеңилдетүү үчүн, кийинүү процессин кызыктуу оюнга айландырыңыз: аларга «бөбөктөрдүн фотосессиясына» даярданып жатканыңызды айтыңыз!','Igapäevane riietumislahing? 👗','„Ma ei taha seda särki!“ Kas jonnituju ei lõpegi? Hommikuste riietumisvõitluste leevendamiseks muuda riietumine lõbusaks mänguks, öeldes lapsele, et valmistute „beebide fotosessiooniks“!'),
('0daafb47-5c27-4a37-935b-b3612abf5506'::uuid,'Бүгүнкү күндүн баатыры 🌟','Ар бир жаңы үйрөнгөн жөндөмү – бул сиздин эмгегиңиздин үзүрү. «Маанай күндөлүгүн» ачып, бүгүн алар үчүн жасаган эң кичинекей жакшылыгыңызды да жазып коюңуз, анан өзүңүз менен сыймыктаныңыз!','Tänane kangelane 🌟','Iga uus oskus, mida laps iga päev õpib, on sinu suure töö vili. Ava meeleolupäevik ja pane kirja ka kõige väiksem heategu, mida sa täna tema heaks tegid, ning tunne enda üle uhkust!'),
('3b1eb831-8b25-40be-89a6-b50384eeb49b'::uuid,'Сүйлөшкүсү келет, бирок... 🗣️','Сиздин бөбөгүңүз айта алганынан көбүрөөк сөздү түшүнөбү? Сөздөрдү так айта албаса да, тил өнүктүрүүдөгү бул укмуштуудай секирикти кантип колдоо керектигин биздин «Блогдор» бөлүмүнөн билип алыңыз.','Tahab rääkida, aga... 🗣️','Kas su väike laps mõistab rohkem sõnu, kui ta öelda suudab? Isegi kui ta ei häälda sõnu veel täiuslikult, loe meie blogist, kuidas seda imelist keelelist arenguhüpet toetada.'),
('a4477b67-ebfc-489b-b2e5-165c0ebb273f'::uuid,'Өз алдынчалыкка умтулуу 🥣','Бөбөгүңүз кашыкты бербей жатабы? Тамактануу таймерин иштетип, бул көз карандысыздык сынагы канчага созуларын байкаңыз. Ал эми төгүлгөн тамакка келсек, жөн гана жылмайып, бул көз ирмемден ырахат алыңыз!','Iseseisvuse otsingud 🥣','Kas su väike laps keeldub lusikat andmast? Käivita söötmistaimer ja vaata, kui kaua see iseseisvuse proovilepanek kestab. Mis puutub mahapudisenud toitu, siis lihtsalt naerata ja naudi hetke!'),
('4dbfd2fe-196e-4f4f-9fd6-89ab8dff4f94'::uuid,'Өсүү мезгили! 📏','Бөбөгүңүздүн капысынан тез өсүп жатканын байкадыңызбы? Алардын жаңы өлчөмдөрүн «Өсүү трекерине» киргизип, дени сак өнүгүүсүнө сыймыктануу менен көз салыңыз.','Kasvuspurt! 📏','Märkasid, et lapsel on äkiline kasvuspurt? Sisesta uued mõõdud kasvu jälgijasse ja jälgi uhkusega tema tervislikku arengut.'),
('9167bebc-9c9c-4cbb-8cf3-b64e9ea99677'::uuid,'Энергия топтоо убактысы 🔋','Апа, өзүңүздү унутпаңыз! «Дени сак рецепттер» бөлүмүнөн эртең мененки тамак үчүн тез даярдалуучу, белокко бай даамдуу смузи менен күч-кубат алыңыз.','Aeg akusid laadida 🔋','Emme, ära unusta iseennast! Taastu kiire ja maitsva valgurikka smuutiga, mille retsepti leiad meie tervislike retseptide sektsioonist.'),
('e61cda6e-e7ca-46f3-a40c-42185a9f8216'::uuid,'5 мүнөттүк энергия жарылуусу ⚡','Бөбөгүңүз түштөн кийин уктап жатканда, үй жумуштарына шашылбаңыз. Анын ордуна, «Дени сак рецепттерден» антиоксидантка бай смузи жасап, организмиңизди сергитиңиз.','5-minutiline energiasüst ⚡','Kui laps pärastlõunal magab, ära kiirusta kodutöödega. Selle asemel valmista meie tervislike retseptide järgi antioksüdantidest pakatav smuuti ja turguta oma keha.'),
('733a062a-9528-4b89-8399-8894cdcd37ab'::uuid,'Бирге китеп окуу 📖','Балаңыз китептин барактарын өзү барактаганга кызыгып жатабы? Бул куракта окууга болгон сүйүүнү кантип оюн түрүндө калыптандыруу керектиги тууралуу «Блогдор» бөлүмүндөгү сонун макалабызды окуп чыгыңыз.','Loeme koos raamatuid 📖','Kas su laps soovib juba ise raamatulehti keerata? Vaata meie suurepärast artiklit blogis, kuidas selles vanuses mänguliselt lugemishuvi äratada.'),
('840a48c0-60b0-4169-a7a4-bfd97c049d9d'::uuid,'Жаратылышты изилдөө 🌳','Бөбөгүңүз үйдө отуруп тажадыбы? «Апаларга ыңгайлуу жайлар» бөлүмүнөн кенен жана коопсуз сейил бактарды таап, таза абада энергиясын сарптоого жардам бериңиз!','Looduse avastamine 🌳','Kas lapsel on toas igav? Leia avar ja turvaline park, kasutades „Emmesõbralike kohtade“ funktsiooni, ja aita tal õues energiat kulutada!'),
('fc70b034-70d7-48ac-b093-b541c3d08e54'::uuid,'Эртең мененки тазалык жана текшерүү 💧','Күндүн биринчи жалаягын алмаштырдыңызбы? Алардын суюктук ичиши жана сиңирүүсү жетиштүү экендигин оңой көзөмөлдөө үчүн маалыматтарды тиркемеге киргизиңиз.','Hommikune koristus ja kontroll 💧','Vahetasid just päeva esimese mähkme? Märgi detailid rakendusse, et hõlpsalt jälgida, kas lapse vedelikutarbimine ja seedimine on piisavad.'),
('8139b24d-f8c3-4b60-b4f1-38bd25e609a6'::uuid,'Кашык менен тамактанууну үйрөнүүдөбү? 🥄','Тамактануу таймерин иштетиңиз! Алардын өз алдынча тамактануу аракеттери канча убакытка созуларын талдап, күнүмдүк азыктануусун тиркеме аркылуу текшерип туруңуз.','Kas lusikas on juba käpas? 🥄','Käivita söötmistaimer! Analüüsi, kui kaua iseseisev söömine aega võtab, ja kontrolli rakenduses lapse igapäevast toitumist.'),
('9cda88a3-f6c1-4cc3-92c3-5cb54bd45a91'::uuid,'Кум терапиясы 🏖️','Бир аз кир болуудан коркпоңуз! Кинетикалык кум жана сезүү органдарын өнүктүрүүчү оюндар үчүн эң мыкты куралдарды «Сунушталган товарлар» бөлүмүнөн азыр табыңыз.','Liivateraapia 🏖️','Ära karda natuke määrduda! Avasta parimad vahendid kineetilise liiva ja sensoorseks mänguks meie soovitatud toodete sektsioonist.'),
('f71cc78c-d1eb-4694-b94a-1843f80e2db1'::uuid,'Тынчтандыруучу толкундар 🌊','Кызыктуу окуяларга толгон күндөн кийин тынчтана албай жатабы? «Ак ызы-чуу» (White Noise) бөлүмүнөн «океан толкундарын» тандап, бөлмөдө сыйкырдуу тынч атмосфера түзүп, уйкуга кетишине жардам бериңиз.','Rahustavad lained 🌊','Kas lapsel on pärast põnevat päeva raske uinuda? Vali valge müra alt „ookeanilained“ ja loo tuppa maagiliselt rahulik atmosfäär, et laps saaks uinuda.'),
('3787f491-d618-4351-acd6-86ff87689c17'::uuid,'Уруу жана түртүү 🛑','Ачууланганда капысынан уруп же тиштеп жатабы? 21 айлык курактагы мындай жүрүм-турумду сүйүү менен кантип оңдоо керектигин Anacan AI''дан сураңыз.','Löömine ja tõukamine 🛑','Kas laps lööb või hammustab, kui ta on vihane? Küsi Anacan AI-lt, kuidas nendele 21-kuustele omastele käitumismustritele armastavalt läheneda.'),
('e29e6044-f61d-47fa-b1d7-8e16d2c4b2ce'::uuid,'Белокту жетиштүү кабыл алып жатасызбы? 🍗','Белок – дени сак өсүү үчүн абдан маанилүү! Балаңыздын күнүмдүк тамактануу балансын өлчөө жана жетишпеген жерлерин толуктоо үчүн тамактануу трекерин колдонуңуз.','Kuidas on lood valkudega? 🍗','Valk on tervislikuks kasvuks hädavajalik! Kasuta toitumisjälgijat, et mõõta lapse igapäevast toidulauda ja täita võimalikud lüngad.'),
('e90a6ec1-ff62-4f86-8635-bb93512c7c35'::uuid,'Уйкуну талдоо таймери ⏱️','Уктоо убактысы келди! Уйку таймерин иштетиңиз, алардын графигин талдап, сунушталган уйку убактысын камсыз кылыңыз, анан өзүңүз да эс алыңыз.','Une analüüsi taimer ⏱️','On uneaeg! Käivita unetaimer, analüüsi lapse rutiini, et veenduda soovitusliku uneaja täitumises, ja seejärel puhka ka ise.'),
('ad033330-a436-4b30-84e7-2df370198c16'::uuid,'Эң сонун өнүктүрүүчү оюнчукту табуу? 🧩','Балаңыз формаларды тешиктерге салууну жакшы көрөбү? Алардын өнүгүп жаткан акылын курчутуу үчүн «Сунушталган товарлар» бөлүмүнөн куракка ылайыктуу жыгач пазлдарды табыңыз.','Otsid täiuslikku arendavat mänguasja? 🧩','Kas su laps armastab kujundeid aukudesse sobitada? Avasta meie soovitatud toodete sektsioonist eakohased puidust pusled, mis arendavad lapse mõtlemist.'),
('0ac93f21-93e2-449d-b93b-ae00befc33f7'::uuid,'Караңгыдан коркобу? 🌌','Бөлмөдө жарык өчкөндө бөбөгүңүз тынчсызданып жатабы? «Ак ызы-чуу» бөлүмүнөн «эненин курсагындагы үндөрдү» (жүрөктүн согушу) коюп, аларга коопсуздук сезимин тартуулаңыз.','Kas kardab pimedust? 🌌','Kas laps muutub rahutuks, kui tuled kustuvad? Paku talle turvatunnet, mängides valge müra alt „emakahelisid“ (südamelöögid).'),
('5831d6e0-9735-485f-be90-56915bc7047f'::uuid,'Сиз үчүн убакыт! 🥗','Бөбөгүңүз уктадыбы? Ашканага барыңыз! «Аялдар үчүн дени сак рецепттер» бөлүмүнөн белокко бай салаттарды же сергитүүчү детокс суусундуктарын табыңыз.','Aeg sulle! 🥗','Beebi magab? Suundu kööki! Avasta meie naiste tervislike retseptide sektsioonist energiat andvad valgurikkad salatid või värskendavad detoks-veed.'),
('5c1e8139-b38e-4666-8558-f6706af826d7'::uuid,'Кичинекей сүрөтчү иштеп жатат 🖍️','Алар чиймелегенди жакшы көрөбү? Боёкко боёлуп калса, кабатыр болбоңуз! Бул чыгармачыл көз ирмемди «Бөбөктүн альбомуна» кошуп, өмүр бою эстелик катары сактап калыңыз.','Väike kunstnik töös 🖍️','Kas talle meeldib kritseldada? Ära muretse, kui ta on värviga koos! Jäädvusta see loominguline hetk ja lisa see beebialbumisse.'),
('04f3e5a5-25b9-471b-9c8e-e6c96050313b'::uuid,'Түстүү иммунитет калканы 🛡️','Тамактануу трекерин колдонуп, бөбөгүңүз бүгүн жетиштүү С витаминин алдыбы, текшериңиз. Түстүү жашылча идеялары үчүн «Бөбөктөр үчүн тамак рецепттерин» карап көрүңүз!','Värviline immuunsuskilp 🛡️','Kontrolli toitumisjälgijast, kas laps sai täna piisavalt C-vitamiini. Värviliste köögiviljaroogade ideid leiad meie beebitoitude retseptidest!'),
('41231bd2-e2dd-4432-bc31-3952982f012e'::uuid,'Тиш жууп жатабызбы? 🪥','Бөбөгүңүз тиш щеткасын көргөндө качып жатабы? Бул гигиеналык көнүгүүнү кызыктуу оюнга айландыруу үчүн «Сунушталган товарлар» бөлүмүнөн музыкалык же манжага кийилүүчү щеткаларды издеңиз.','Kas peseme hambaid? 🪥','Kas su laps jookseb hambaharja nähes minema? Avasta soovitatud toodete sektsioonist muusikalised või sõrmeotsaharjad, et muuta hügieenirutiin lõbusaks mänguks.'),
('9603c325-693c-472c-b02b-2c75bd255571'::uuid,'Сиз бүгүнкү күндүн баатырысыз! 🌟','Бардык кыйынчылыктарга жана чарчоого карабастан, сиз укмуштуудай иш жасап жатасыз! «Маанай күндөлүгүңүздү» ачып, бүгүнкү аракетиңизди белгилеген жазуу калтырыңыз – сиз алкышка татыктуусуз!','Oled tänane kangelane! 🌟','Vaatamata kõigile väljakutsetele ja väsimusele teed sa suurepärast tööd! Ava meeleolupäevik ja kirjuta üles midagi, mis tähistab sinu tänaseid pingutusi – oled kiitust väärt!'),
('d22a5573-d857-4918-90d2-9def6a084f6f'::uuid,'Акылды тынчтандыруу өнөрү 🎶','Бөбөгүңүз ашыкча толкунданып, уктабай жатабы? Бөлмөнү караңгылатып, «Ак ызы-чуудан» океан толкундарын коюп, терең уйкуга даярдаңыз.','Meele rahustamise kunst 🎶','Kas laps on üleväsinud ja tal on raske uinuda? Tee tuba pimedaks ja mängi valge müra alt ookeanilaineid, et aidata tal sügavasse unne suikuda.'),
('fb035079-cf24-4146-9049-8d721e68f53f'::uuid,'Боёкко боёлгон кичинекей сүрөтчү! 🎨','Чиймелеп жатып боёкко толугу менен боёлуп калдыбы? Капа болгондун ордуна, бул күлкүлүү көз ирмемди «Бөбөктүн фотосессиясы» бөлүмүндөгү шаңдуу чаптамалар менен кооздоп, альбомго жүктөп коюңуз.','Väike kunstnik, värviga koos! 🎨','Kas ta sai kritseldades värviga kokku? Selle asemel, et pahandada, kaunista see naljakas hetk beebide fotosessiooni sektsiooni rõõmsate kleebistega ja laadi albumisse.'),
('0b2c56b1-a7a8-4553-8880-13254eeb155b'::uuid,'Кийимдери кичинекей болуп калдыбы? 📏','Шымдарынын балагы кыскарып баратса, демек, бул өсүү мезгили! Учурдагы өлчөмдөрүн «Салмак трекерине» киргизип, өсүү графигинин жогорулаганын сыймыктануу менен байкаңыз.','Riided jäävad väikeseks? 📏','Kui püksisääred jäävad lühikeseks, on see kasvuspurt! Sisesta praegused mõõdud kaalujälgijasse ja vaata uhkusega, kuidas kasvukõver tõuseb.'),
('03d03133-0370-4630-9d2e-153f9459d86d'::uuid,'Чыңырып ойгонуп жатабы?','Бөлмөнүн жарыгын күйгүзбөстөн, «Ак ызы-чуудан» «эненин курсагындагы үндөрдү» коюп, алардын коопсуз сезип, кайра тынч уктап кетишине жардам бериңиз.','Ärkab karjudes?','Tuld põlema panemata mängi valge müra alt „emakahelisid“, et aidata lapsel end turvaliselt tunda ja uuesti uinuda.'),
('8ed6f8ef-f210-4aaa-96f8-4667b80d657e'::uuid,'Жок деп айтууну үйрөнүңүз! 🛑','Бөбөгүңүз бардык сунуштарыңызга каршы чыгып жатабы? Каршылык көрсөтүү менен күрөшүүнүн ордуна, аларга туура тандоону кантип сунуштоо керектигин Anacan AI''дан сураңыз!','Õpi ütlema ei! 🛑','Kas su laps vaidlustab kõik su ettepanekud? Selle asemel, et jonni vastu võidelda, küsi Anacan AI-lt, kuidas talle õigeid valikuid pakkuda!'),
('0b3896bc-de1d-4dd2-b68d-bd0aa3890750'::uuid,'Күндүзгү уйку узарып баратабы? ⏱️','Бөбөгүңүз кечинде уктоодон баш тартып жатабы? Уйку таймерин иштетип, графигин текшериңиз. Балким, алар күндүзгү уйкудан өтө кеч ойгонуп жаткандыр?','Kas päevased uinakud pikenevad? ⏱️','Kas laps tõrgub õhtul magamaminekust? Käivita unetaimer ja kontrolli graafikut. Äkki ärkas ta päevaunest liiga hilja?'),
('7c7fefdb-4a4d-41d2-bca8-742c9430dc8d'::uuid,'Кальций жана сөөктөр 🦴','Тез физикалык өнүгүү кальцийди талап кылат. «Тамактануу трекерин» колдонуп, алардын сыр жана йогурт муктаждыгын эсептеп чыгыңыз, эгер жетишсиз болсо, «Бөбөктөр үчүн тамак рецепттерин» карап көрүңүз.','Kaltsium ja luude tervis 🦴','Kiire füüsiline areng nõuab kaltsiumi. Kasuta toitumisjälgijat, et arvutada lapse juustu- ja jogurtivajadus, ning kui sellest jääb puudu, uuri ideid meie beebiretseptidest.'),
('c7f42861-81dc-4ed2-b93f-7c30709d92ed'::uuid,'Чарчап турганыңызды сезип жатасызбы? 🔋','Күчтөн тайдыңызбы? Таттууга кол сунбаңыз! «Аялдар үчүн дени сак рецепттерден» кантсыз, энергия берүүчү тамактарды жасап, күч-кубатыңызды калыбына келтириңиз.','Tunned end kurnatuna? 🔋','Aku tühi? Ära haara maiustuste järele! Lae oma akusid, valmistades meie naiste tervislike retseptide järgi suhkruvabu energiapalle.'),
('9f2ceaa6-0d99-46a0-884c-3460db78351b'::uuid,'Баары түшүнүктүү, бирок али сүйлөй элекпи? 🧠','Пассивдүү сөз байлыгы активдүү сөз байлыгына караганда тезирээк өнүгөт. 20 айлык бөбөктөрдүн сүйлөө жөндөмүн тездетүүчү үй оюндары тууралуу «Блог» бөлүмүндөгү макаланы сөзсүз окуңуз.','Saab aru, aga veel ei räägi? 🧠','Passiivne sõnavara areneb kiiremini kui aktiivne. Loe blogist artiklit koduste mängude kohta, mis kiirendavad 20-kuuse lapse kõnearengut.'),
('f641f443-9a8d-4060-a2b5-fe5d5562fa9d'::uuid,'Жашыруун витамин миссиясы 🥕','Бөбөгүңүз жашылчаларды жегиси келбей жатабы? «Бөбөктөр үчүн тамак рецепттериндеги» даамдуу куймактардын же оладьилердин ичине шпинат менен сабизди кантип чеберчилик менен жашырууну үйрөнүңүз.','Peidetud vitamiinide missioon 🥕','Kas su laps lükkab rohelise ja köögiviljad eemale? Õpi, kuidas peita spinatit ja porgandit maitsvatesse pannkookidesse või kotlettidesse meie beebiretseptide abil.'),
('2ecfbac7-2e44-4661-8705-95fe2f59e9a9'::uuid,'Кемчиликсиз болууну көздөөнү токтотуңуз 🧘‍♀️','Үй бир аз башаламан болуп жатабы? Кабатыр болбоңуз! Сезимдериңизди «Маанай күндөлүгүңүзгө» жазыңыз. Эсиңизде болсун, бактылуу апа – тыкан үйгө караганда алда канча маанилүү.','Loobu täiuslikkuse tagaajamisest 🧘‍♀️','Kas kodus on veidi segamini? Ära muretse! Pane oma tunded meeleolupäevikusse kirja. Pea meeles, et õnnelik emme on palju tähtsam kui ideaalselt korras kodu.'),
('31e46f9b-eb74-4b8a-8369-6c0eb709b2d1'::uuid,'Сизге да эс алуу керек ☕','Сыртка чыгып, бир аз эс алыңыз! «Апаларга ыңгайлуу жайлар» бөлүмүнөн балдар бурчу бар жакын жердеги кафени таап, ысык кофеңизден ырахат алыңыз.','Ka sina vajad puhkust ☕','Mine välja ja hinga värsket õhku! Leia lähedal asuv lastenurgaga kohvik, kasutades „Emmesõbralike kohtade“ funktsiooni, ja naudi oma kuuma kohvi.'),
('f9b61a4f-eba1-4cee-bf4a-958278a9300c'::uuid,'Биздин кичинекей ашпозчубуз 👩‍🍳','Алар ашканада сизге жардам берип, казан аралаштырганды жакшы көрүшөбү? Бул сүйкүмдүү, ун болгон көз ирмемди «Бөбөктүн фотосессиясындагы» ашпозчу чаптамалары менен кооздоңуз!','Meie väike kokk 👩‍🍳','Kas talle meeldib köögis potte segada? Kaunista see armas, jahuga kaetud hetk beebide fotosessiooni sektsiooni koka-kleebistega!'),
('2c0cd78a-df37-49ab-8eae-44063551c7d9'::uuid,'Пазл чебери 🧩','Алар формаларды туура коюуну үйрөнүп жатышабы? «Сунушталган товарлар» бөлүмүнөн 21 айлык бөбөктөр үчүн иштелип чыккан геометриялык пазлдарды таап, алардын интеллектин өстүрүңүз.','Puslemeister 🧩','Kas ta on kujundite sobitamises juba osav? Arenda tema intelligentsust, avastades soovitatud toodete sektsioonist 21-kuustele mõeldud geomeetrilised pusled.'),
('eeefba30-2a67-4d29-87df-2dbd7f03271f'::uuid,'Китептерди айрууга болгон каалоо 📖','Балаңыз китеп окугандын ордуна барактарын жыртып жатабы? Муну окууга болгон сүйүүсүн өчүрбөстөн кантип оңдоо керектиги тууралуу «Блогдор» бөлүмүндөгү макалабызды дароо окуп чыгыңыз.','Kihk raamatuid rebida 📖','Kas su laps rebib lugemise asemel lehti? Loe kohe meie blogiartiklit selle kohta, kuidas sellele reageerida, ilma et tapaksid temas lugemishuvi.'),
('f7f548f7-29ae-4098-8eb1-12f16f94c4b9'::uuid,'Тамак менен ойноо этабы 🥣','Бөбөгүңүз кашыкты ыргытып, тамакты колу менен изилдеп жатабы? Алардын табитине көз салуу үчүн тамактануу таймерин колдонуңуз жана бул сезүү өнүгүүсүнө сабырдуулук менен мамиле кылыңыз.','Toiduga mängimise etapp 🥣','Kas su laps loobib lusikat ja uurib toitu kätega? Kasuta söötmistaimerit, et jälgida tema söögiisu, ja suhtu sellesse sensoorsesse arengusse kannatlikult.'),
('3512adbc-96b2-42e9-8a54-b673dc404876'::uuid,'Кечки күлкү 📸','Уктаар алдында жасаган ал күлкүлүү кыймылын өткөрүп жибербеңиз! Дароо видеого тартып, «Бөбөктүн альбомуна» кошуу менен күндүн чарчоосун жылмаюуга айлантыңыз.','Õhtune itsitamine 📸','Ära maga maha seda naljakat liigutust enne uinumist! Tee kiiresti video, lisa see beebialbumisse ja muuda päeva väsimus naeratuseks.'),
('42cda594-bd4d-4a45-a1f6-1f894ad11fe7'::uuid,'Жаңы сөздөр келе жатат! 🗣️','Бөбөгүңүз көп үндөрдү чыгарып жатат, бирок али толук сөздөрдү айта элекпи? Пассивдүү сөз байлыгын активдештирүүгө жардам бере турган эң натыйжалуу үй оюндарын жана көнүгүүлөрдү табуу үчүн Anacan AI''дан сураңыз.','Uued sõnad on tulemas! 🗣️','Kas su laps teeb palju hääli, aga ei räägi veel täislauseid? Küsi Anacan AI-lt kõige tõhusamaid koduseid mänge ja silbiharjutusi, mis aitavad passiivset sõnavara aktiveerida.'),
('ad6e0b2f-1d5f-4db6-82ee-93ed492c1c54'::uuid,'Бут кийими тар болуп калдыбы? 👟','Акыркы убакта чуркап жатып көп чалынып жатабы? Балким, бут кийиминин өлчөмүн чоңойтуу керек чыгар! Алардын өсүүсүнө көз салуу үчүн учурдагы өлчөмдөрүн «Өсүү трекерине» киргизиңиз.','Kas kingad hakkavad kitsaks jääma? 👟','Kas ta komistab jooksmisel tihti? Võib-olla on aeg osta suuremad jalanõud! Sisesta praegused mõõdud kasvu jälgijasse, et tema arengul silm peal hoida.'),
('a3eb6f02-e9da-422e-a243-1f395cf4661e'::uuid,'Уктоо убактысы өзгөрүп жатабы? ⏱️','Кечинде ойгоо убактысы узарып баратабы? Уйку таймерин иштетип, алардын уйку графигин кайра карап чыгуу үчүн талдап көрүңүз.','Kas uneaeg nihkub? ⏱️','Kas lapse ärkveloleku aeg õhtuti venib pikemaks? Käivita unetaimer ja analüüsi graafikut, et tema unerežiim uuesti üle vaadata.'),
('aac102d8-edd5-4708-bab2-8cf3fcc9802c'::uuid,'Ич катуу маселеси барбы? 🚽','Эртең мененки жалаяк алмаштырууда балаңыздын ичегисинин иштешине көз салыңыз. Эгер ичи катып жатканын байкасаңыз, аны тиркемеге белгилеп коюңуз жана менюсуна клетчаткага бай азыктарды (мисалы, алмурут жана сулу) кошууну унутпаңыз.','Mured kõhukinnisusega? 🚽','Jälgi hommikusel mähkmevahetusel beebi seedimist. Kui märkad kõhukinnisust, märgi see äppi ja lisa menüüsse kiudainerikkaid toite (näiteks pirni ja kaerahelbeid).'),
('4bdcd931-fb36-41ca-9759-7a92226d97f9'::uuid,'Баланын тойгонун кантип билсе болот? ⏱️','Эгер ал тамакты ыргытып же түкүрө баштаса, бул көбүнчө анын тоюп калганын билдирет. Тамактануу таймерин токтотуп, баланын тоюп калганын жазып алыңыз жана анын табитине баа бериңиз.','Kuidas teada, et beebi on kõhu täis söönud? ⏱️','Kui laps hakkab toitu välja sülitama või loopima, tähendab see sageli, et kõht on täis. Peata söötmise taimer, märgi üles, et laps on söönud, ja hinda tema isu.'),
('be36c558-6f81-4ee5-9a59-f79497bbff2d'::uuid,'Тиш жуудагы күрөш! 🪥','Балаңыз тиш щеткасын көргөндө качып кетеби? Бул маанилүү гигиеналык көнүгүүнү кызыктуу оюнга айландырыңыз, ал үчүн «Сунушталган товарлар» бөлүмүнөн музыкалык же манжага кийилүүчү тиш щеткаларын карап көрүңүз.','Hammaste pesemise lahing! 🪥','Kas su laps jookseb hambaharja nähes minema? Muuda see oluline hügieenitoiming lõbusaks mänguks, vaadates soovitatud toodete alt muusikalisi või sõrmeotsa-hambaharju.'),
('cd9296b3-74e7-4229-8871-9f5ee4fe977a'::uuid,'Эненин суу балансы 💧','Башыңыз ооруп жатабы? Кичинекейиңиздин артынан чуркап жүрүп, организмиңиз суусузданган болушу мүмкүн. «Аялдар үчүн пайдалуу рецепттер» бөлүмүнөн детокс суусундуктарын даярдап, күчүңүздү калыбына келтириңиз.','Ema vedelikutasakaal 💧','Kas pea valutab? Tõenäoliselt oled väikelapse järel jooksmisest vedelikupuuduses. Turguta oma keha, valmistades meie naiste tervislike retseptide järgi detoks-vett.'),
('2fbfd933-5095-452a-808e-4209aab75b80'::uuid,'Сизге да социалдык чөйрө керек 👯‍♀️','Бир гана балаңыз менен сүйлөшүп, өзүңүздү жалгыз сезип жатасызбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн оюн топтору бар борборлорду таап, башка энелер менен таанышыңыз.','Ka sina vajad sotsiaalset aega 👯‍♀️','Tunned end üksildasena, rääkides vaid oma pisikesega? Leia mängugruppidega keskusi jaotises „Emadele sobivad kohad“ ja loo kontakte teiste emadega.'),
('a7d068ee-6f98-437e-b7f3-f2284f8fbdbc'::uuid,'Сизди туураган кичинекей жардамчыңыз 📱','Кичинекейиңиз сизди туурап, телефон менен сүйлөшүп жатабы? Балдар чындап эле биздин күзгүбүз!','Sinu väike järeleahvija 📱','Kas su pisike lobiseb telefonis täpselt nagu sina ja matkib su žeste? Lapsed on tõesti meie suurimad peegeldajad!'),
('bf157f3f-185f-45b5-aae0-091b2cf00653'::uuid,'Бирге, бирок өзүнчө 👶','Ал сейил бакта башка балдар менен кошулуп ойногондон көрө, аларды карап отурганды жактырабы? Бул — параллелдүү оюн! Социалдашуунун бул баскычы тууралуу кызыктуу фактыларды «Блогдор» бөлүмүнөн окуңуз.','Koos, kuid eraldi 👶','Kas ta eelistab pargis teiste laste mängimist vaadata, selle asemel et ise liituda? See on paralleelmäng! Avasta põnevaid fakte selle sotsialiseerumisetapi kohta blogide jaotisest.'),
('205f33e0-59b6-4cce-bdf2-72feb1805167'::uuid,'Пайдалуу таттууларды издөө 🍪','Кантсыз, бирок даамдуу таттууну каалап жатасызбы? «Балдар тамактарынын рецепттери» бөлүмүнөн 10 мүнөттө даяр болчу банан жана курма кошулган печеньелерди табыңыз!','Tervislike suupistete otsingul 🍪','Isu millegi suhkruvaba, kuid maitsva järele? Avasta meie beebitoitude retseptide hulgast kiired ja lihtsad banaani-datliküpsised, mis valmivad vaid 10 minutiga!'),
('db60a4c8-3ab7-4727-9545-2ff3fea13946'::uuid,'Өжөр ''жок!'' 🛑','Ал баарына каршы чыгып, ыйлап жатабы? 21 айлык балдардын өжөрлүгү тууралуу Anacan AI жардамчыбыздан кеңеш сурап, мындай эмоционалдык абалдарды кантип жөнгө салууну үйрөнүңүз.','Kangekaelne „ei!“ 🛑','Kas laps protestib kõige vastu ja karjub? Konsulteeri meie Anacan AI-ga 21-kuuste trotsi teemal ja õpi, kuidas emotsionaalsete puhangutega toime tulla.'),
('ec464aff-d0a0-4b3d-ac5c-7d32cf5dcf36'::uuid,'Уйку режимин текшерип көрөлү ⏱️','Кичинекейиңиз түнкүсүн көп ойгонуп жатабы? Уйку трекериңиздеги графикти текшериңиз. Балким, күндүзгү уйкусун бир аз өзгөртүү кечинде анын чарчап, жакшы уктоосуна жардам берет.','Vaatame uneharjumused üle ⏱️','Kas su pisike ärkab öösiti tihti? Kontrolli unepäeviku graafikut. Võib-olla aitaks päevase uneaja väike korrigeerimine tal õhtuks väsinum olla.'),
('87662f03-ab51-47a9-bb0d-dc1172cdf859'::uuid,'Витаминдердин булагы 🥗','Күнүмдүк витамин муктаждыгыңызды эсептөө жана менюңузду пландаштыруу үчүн тамактануу трекерин колдонуңуз. Омега-3 жана D витамининин балансын текшерүүнү унутпаңыз!','Vitamiinipomm 🥗','Kasuta toitumisjälgijat, et arvutada oma päevane vitamiinivajadus ja planeerida menüüd. Ära unusta kontrollida oma Omega-3 ja D-vitamiini taset!'),
('a1ffdcb1-2aeb-4842-a0b3-6bc2096bceb7'::uuid,'Пазл жана логикалык оюнчуктар 🧩','Бул курак логикалык оюндар үчүн эң сонун! Балаңыздын акыл-эсин өстүрүү үчүн «Сунушталган товарлар» бөлүмүнөн куракка ылайыктуу пазлдарды жана формаларды сорттоочу оюнчуктарды табыңыз.','Pusled ja loogikamängud 🧩','See vanus on ideaalne loogikamängudeks! Avasta arendavaid puslesid ja kujundite sorteerimise mänguasju soovitatud toodete alt, et teritada lapse arenevat mõistust.'),
('b4b68202-2497-420c-9cf0-d0f43130a249'::uuid,'Ойлоруңузду күндөлүккө жазыңыз 📝','Ар бир күн идеалдуу боло бербейт, бул кадыресе көрүнүш. Бүгүн «Маанай күндөлүгүнө» сезимдериңизди жана ички толкундоолоруңузду жазып, стресстен арылып, тынч эс алыңыз.','Pane oma mõtted kirja 📝','Iga päev ei pea olema täiuslik ja see on täiesti normaalne. Pane oma tunded ja sisemised mured täna meeleolupäevikusse kirja, vabane stressist ja lõõgastu rahulikult.'),
('6b045729-7aac-44f1-99aa-a2dbeb7985f2'::uuid,'Соода тизмеси жашоону жеңилдетет 🛒','Эс тутумуңуз дагы эле пандеңизби? Үйдө түгөнүп калган ар бир майда-чүйдө нерсени эстеп калууга аракет кылбаңыз. Аларды дароо «Соода тизмесине» кошуп коюңуз, калганын өнөктөшүңүз чечсин!','Ostunimekirjad päästavad päeva 🛒','Mälu veab jälle alt? Ära püüa meeles pidada iga pisiasja, mis kodus otsa saab. Lisa see kohe ostunimekirja ja lase partneril ülejäänu eest hoolitseda!'),
('7abb85ab-0b3c-4464-a5f4-15bfe391f1ba'::uuid,'Топту тебүү! ⚽','Ал жердеги топту тебүүгө аракет кылып жатабы? Анын тең салмактуулугу жана бут координациясы жакшырып жатат! Аны менен бирге топ ойноп бериңиз.','Palli löömine! ⚽','Kas ta proovib maas palli lüüa? Tema tasakaal ja jalgade koordinatsioon paranevad! Mängi temaga veidi söötmismängu.'),
('eec0d21f-e4e1-482b-ae4c-9c9f182e42a1'::uuid,'Сыйкырдуу түнкү атмосфера 🪄','Уктай албай жатасызбы? «Акылдуу жомоктор» бөлүмүнөн оригиналдуу жомок түзүп, окуп бериңиз.','Maagiline öine atmosfäär 🪄','Kas uinumine on raske? Loo ja loe originaalmuinasjuttu, kasutades nutikaid lugusid.'),
('51155148-f9ec-40a7-99a1-3f09cffe59c1'::uuid,'Атанын оюн аянты 👨‍👧','Өзүңүздү чарчаңкы сезип жатасызбы? Эшикти жаап, балаңызды атасына тапшырыңыз. Бүгүн кечинде үй ичиндеги оюн аянтчасына ал жооптуу!','Issi mängunurk 👨‍👧','Tunned end kurnatuna? Pane uks kinni ja lase issil üle võtta. Täna vastutab tema koduse mänguväljaku eest!'),
('81f2ea67-6d6b-45a8-9d3f-bdbc71d94739'::uuid,'Кийим тандоо боюнча талаш 👗','Ал жайында калың свитер, кышында жайкы көйнөк кийүүнү каалап жатабы? Анын эрктүүлүгү өсүп жатат! Эки ылайыктуу кийимди сунуштап, «Кайсынысын кийгиң келет?» деп сурап, өзүнө чечим кабыл алдырыңыз.','Riietumisega seotud võitlus 👗','Kas ta tahab suvel kanda paksu kampsunit või talvel suvesärki? Tema tahtejõud areneb! Paku kahte sobivat riidevalikut ja lase tal otsustada, küsides: „Kumba sa tahad?“'),
('c6ce4007-ba3b-4772-8fba-7c4797ad17dd'::uuid,'Таза аба — эң мыкты дары 🌳','Кичинекейиңиз үйдө тынч отура албай жатабы? Аба ырайын жана кийимин текшерип, түз эле сейил бакка жөнөңүз. Табият — балдар үчүн эң тез тынчтандыруучу каражат!','Värske õhk on parim rohi 🌳','Kas su pisike on rahutu ja toas raske rahuneda? Kontrolli ilma ja riietust ning suundu otse parki. Loodus on lastele sageli kõige kiirem rahustav vahend!'),
('5bf406ee-d6c9-4691-8b5e-2df617ed2939'::uuid,'Жаратылышты изилдөө 🌳','Кичинекейиңиз үйдө отуруп тажадыбы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн кумдуу аянтчасы жана селкинчектери бар коопсуз сейил бакты таап, таза абада сейилдеңиз!','Looduse avastamine 🌳','Kas su pisike tunneb end toas kinni olevana? Leia „Emadele sobivate kohtade“ kaudu turvaline park, kus on suur liivakast ja kiiged, ning minge värsket õhku hingama!'),
('ad873c49-3118-429c-a9cf-3328699e514f'::uuid,'Макарон менен ойноо убактысы! 🍝','Кичинекейиңиз тамактануучу столдо отургусу келбей жатабы? «Балдар рецепттери» бөлүмүнөн жашылчаларга бай, түстүү макарон идеяларын карап чыгып, анын көңүлүн буруңуз.','Pastaga mängimise aeg! 🍝','Kas su pisike keeldub söögilaua taha istumast? Püüa tema tähelepanu tagasi, avastades beebitoitude retseptide jaotisest värvilisi ja köögiviljarikkaid pastaroogi.'),
('dca5184f-26ea-4b5e-b78d-2f4c36c6bf42'::uuid,'Бир түрдүүлүктүн күчү 🌬️','Жымжырттык аны тынчсыздандырып жатабы? Уктоочу бөлмөдө «Ак ызы-чуу» (White Noise) бөлүмүнөн чач кургаткычтын же желдеткичтин үнүн коюп, анын уйкусу үчүн коопсуз чөйрө түзүңүз.','Monotoonsuse vägi 🌬️','Kas vaikus teeb ta rahutuks? Mängi toas valge müra alt fööni või ventilaatori heli ja vaata, kuidas see loob unekeskkonnas turvatunde.'),
('04ea5cc7-5f44-4fc9-ad82-59f8e294f0a5'::uuid,'Өзүңүздү мактаңыз! 🌟','Бүгүн аны ыйлатпай кийинте алдыңызбы? Эң кичинекей жеңиштериңизди да «Маанай күндөлүгүнө» жазып, энелик жөндөмүңүз үчүн өзүңүздү мактап коюңуз.','Kiida ennast! 🌟','Kas said ta täna ilma pisarateta riidesse? Pane isegi oma väikseimad võidud meeleolupäevikusse kirja ja kiida end oma uskumatu vanemliku oskuse eest.'),
('5d85dda7-f62e-4490-8b4e-2ca037fd60ac'::uuid,'Иммунитетти көтөрүү! 🛡️','Мезгил алмашууга даярданып жатасызбы? Бүгүн балаңыз жетиштүү С витаминин алып жатканын текшерүү үчүн «Тамактануу трекерин» колдонуңуз жана менюсун ошого жараша жаңыртыңыз.','Turguta immuunsust! 🛡️','Valmistud aastaaja vahetuseks? Kasuta toitumisjälgijat, et tagada talle täna piisav C-vitamiini kogus, ja uuenda vastavalt menüüd.'),
('680f971c-231a-40e8-a772-413975915698'::uuid,'Уруу жана түртүү 🛑','Ал капысынан ачууланып, уруп же түртүп жатабы? 21,5 айлык кезиндеги бул татаал жүрүм-турумду кантип оюн түрүндө жөнгө салуу керектигин Anacan AI жардамчысынан сураңыз.','Löömine ja tõukamine 🛑','Kas ta lööb või tõukab, kui on äkki vihane? Küsi Anacan AI-lt, kuidas seda keerulist käitumist 21,5-kuuselt mänguliselt lahendada.'),
('9faf82e4-78ff-4782-a4bb-0d745a808c97'::uuid,'Жашылчаларга каршылык 🥦','Кичинекейиңиз жашылча жегиси келбей жатабы? «Кошумча тамак баштоочу балдар үчүн рецепттер» бөлүмүнөн аларды даамдуу куймак же блинчиктердин ичине кантип жашырууну үйрөнүңүз!','Rohelise toidu protest 🥦','Kas su pisike kirtsutab köögiviljade peale nina? Avasta meie lisatoidu retseptide hulgast, kuidas neid nutikalt maitsvatesse pliinidesse või pannkookidesse peita!'),
('c2142ff9-9553-4737-9602-95ee907b4599'::uuid,'Чарчоого алдырбаңыз 🛋️','Бүгүн баарынан баш тарткыңыз келдиби? Бул кадыресе көрүнүш! «Маанай күндөлүгүн» ачып, ичиңиздеги толкундоолорду жазыңыз жана бул кечти өзүңүзгө арнаңыз.','Ära anna väsimusele järele 🛋️','Kas tundsid täna, et tahaksid alla anda? See on täiesti normaalne! Ava meeleolupäevik, pane kirja oma sisemine segadus ja pühenda see õhtu vaid iseendale.'),
('cc7b1b1f-1c7c-4424-996a-a223a00c890e'::uuid,'Кургак жүрүү узарып баратабы? 🧻','Эртең мененки текшерүү! Эгер жалаягы узак убакыт бою кургак болсо, горшокко үйрөтүү убактысы жакындап калган болушу мүмкүн. Аны «Жалаяк трекерине» белгилеп, статистикасын карап көрүңүз.','Püsib kauem kuivana? 🧻','Hommikune kontroll! Kui mähe püsib kauem kuivana, võib potitreeningu aeg läheneda. Märgi see mähkmejälgijasse ja vaata statistikat.'),
('86da0f7a-f021-4c65-aed2-e8e15433a92d'::uuid,'Айлануунун кубанычы! 🌀','Ал тынымсыз дөңгөлөктөрдү же бөтөлкөнүн капкактарын айлантып жатабы? Бул кыймыл-аракет муктаждыгы жана анын таанып-билүү өнүгүүсүндөгү ролу тууралуу «Блогдордон» окуңуз.','Pöörlemise rõõm! 🌀','Kas ta keerutab pidevalt rattaid või pudelikorke? Loe blogidest selle spetsiifilise motoorse vajaduse ja selle rolli kohta kognitiivses arengus.'),
('9ea6bc21-5003-4afe-8fca-e2eebb549250'::uuid,'Кум менен ойноо пайдасы 🏖️','Бир аз кир болуудан коркпоңуз! «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн кумдуу аянтчасы бар жерди табыңыз. Кум менен ойноо сезимдердин өнүгүүсү үчүн абдан пайдалуу!','Liivakastimängu kasulikkus 🏖️','Ära karda veidi määrduda! Avasta liivakastiga koht meie „Emadele sobivate kohtade“ jaotises. Liivaga mängimine on suurepärane sensoorseks arenguks!'),
('081299bb-b5c9-4af5-8361-9fa39bbdf0bf'::uuid,'Ич катуу менен күрөшүүбү? 🚽','Эртең мененки жалаяк алмаштырууда балаңыздын ичегисинин иштешине көз салыңыз. Эгер ичи катып жатканын байкасаңыз, аны тиркемеге белгилеп, «Кошумча тамак баштоочу балдар үчүн рецепттер» бөлүмүнөн клетчаткага бай азыктарды (мисалы, алмурут жана сулу) тандаңыз.','Kimpus kõhukinnisusega? 🚽','Jälgi hommikusel mähkmevahetusel beebi seedimist. Kui märkad kõhukinnisust, märgi see äppi ja vali lisatoidu retseptide hulgast kiudainerikkaid toite (nagu pirn ja kaerahelbed).'),
('a11b2562-1cd1-41dc-ac6f-d1a7d36b53bb'::uuid,'Сиздин кичинекей сүрөтчүңүз иштеп жатат 🎨','Кичинекейиңиз өзүнүн шедеврлерин жаратып жатып, боёлуп жатабы? Коопсуз жана оңой жуула турган боёкторду «Сунушталган товарлар» бөлүмүнөн башка энелердин сунуштары аркылуу табыңыз.','Sinu väike kunstnik töös 🎨','Kas su pisike värvib end meistriteoseid luues ära? Ohutute ja pestavate värvide leidmiseks uuri teiste emade poolt kõrgelt hinnatud tooteid meie „Soovitatud toodete“ jaotises.'),
('3e9ffaf8-f631-4e99-946e-651b683eab7f'::uuid,'Биринчи сөздөр жана сөз айкаштары! 🗣️','Кичинекейиңиз эки сөздү бириктирип сүйлөм түзүүгө аракет кылып жатабы? Бул тил өнүгүүсүндөгү чоң кадам! Анын алгачкы сүйлөмдөрүн «Өнүгүү трекерине» эстелик катары жазып коюңуз.','Esimesed sõnad ja fraasid! 🗣️','Kas su pisike proovib juba kahest sõnast lauset moodustada? Milline suur hüpe keelelises arengus! Salvesta tema esimesed lausekesed arengupäevikusse kui kallis mälestus.'),
('473def83-9d3b-4698-becd-a16f81aed11d'::uuid,'Дүкөндөгү ыйлоо көйгөйлөрү 🛒','Балаңыз дүкөндө өзү каалаган нерсени албай калганда ыйлап жатабы? Дүрбөлөңгө түшпөңүз! Башкалардын караганына көңүл бурбай, анын көз деңгээлине чейин эңкейип, сабырдуулук менен сүйлөшүңүз.','Jonnihood toidupoes 🛒','Kas laps tegi poes jonnituuri, sest ei saanud oma tahtmist? Ära paanitse! Lasku rahulikult tema silmade kõrgusele, ignoreerides teiste uudishimulikke pilke.'),
('fdbb311e-3b42-4723-986f-c65a632fb53e'::uuid,'Эмоционалдык жүктү бошотуңуз 📝','Оор күн болдубу? Стрессиңизди «Маанай күндөлүгүнө» төгүп, жеңилдеп алыңыз. Бардык энелер ушундай кыйынчылыктарды башынан өткөрүшөт; сиз жалгыз эмессиз.','Vabasta emotsionaalne koorem 📝','Oli raske päev? Vala oma stress meeleolupäevikusse ja lase see välja. Kõik emad kogevad neid tavalisi väljakutseid; sa pole üksi.'),
('34d9fbb9-7747-4964-9067-399afa7f0a7c'::uuid,'Жаратылыштын тынчтыгы 🍃','Балаңыз уктады. Үй жумуштарын унутуңуз! Аялдар үчүн пайдалуу рецепттерден лимон чөбүнөн чай демдеп, диванга жатып, жымжырттыктан ырахат алыңыз.','Looduse rahu 🍃','Beebi magab. Unusta majapidamistööd! Keeda meie naiste tervislike retseptide järgi melissiteed, heida diivanile ja naudi lihtsalt vaikust.'),
('e79393de-a250-4c25-b9a8-93a1bc3692aa'::uuid,'С витамининин калканы 🍊','Иммунитеттин бекем болушу маанилүү. Балаңыз бүгүн жетиштүү С витаминин алганын билүү үчүн «Тамактануу трекерин» колдонуңуз жана анын менюсун чыгармачылык менен байытыңыз!','C-vitamiini kilp 🍊','Tugev immuunsüsteem on hädavajalik. Kasuta toitumisjälgijat, et näha, kas laps on täna saanud piisavalt C-vitamiini, ja ole menüüga loov!'),
('f29d2f2b-6e38-44f2-9d6b-467c0c3431e7'::uuid,'Кийинип жаткандагы талаш-тартыштар 👗','«Бул көйнөктү кийбейм!» Өжөрлүк башталдыбы? Эртең мененки кийинүү кризисин азайтуу жана ага өз алдынча тандоо мүмкүнчүлүгүн берүү жолдорун Anacan AI жардамчысынан үйрөнүңүз.','Riietumise vaidlused 👗','„Ma ei taha seda särki!“ Kas jonniperiood on alanud? Õpi Anacan AI-lt viise, kuidas vähendada hommikuseid riietumiskriise ja anda lapsele vaba valiku võimalus.'),
('2a640acf-5bf6-44d4-b56f-00e902c2ddd2'::uuid,'Эгемендүүлүккө умтулуу 🥣','Наристеңиз кашыкты бербей жатабы? Тамактануу таймерин иштетип, бул сүйкүмдүү «эгемендүүлүк сынагы» канчага созуларын байкаңыз. Жөн гана жылмайып, бул башаламандыкты кабыл алыңыз!','Iseseisvuse otsingul 🥣','Kas su väike põngerjas keeldub lusikat käest andmast? Käivita toitmise taimer ja vaata, kui kaua see armas „iseseisvuse test“ kestab. Lihtsalt naerata ja lepi segadusega!'),
('cb94164a-0ea2-471c-9c17-a09778ea707c'::uuid,'Бөлүнүүдөн коркуу сезимиби? 🌌','Кичинекейиңиз сиз бөлмөдөн чыгып кеткенде ыйлайбы? Ага тааныш жана сооротуучу сезим тартуулоо үчүн «Ак ызы-чуу» бөлүмүнөн эненин курсагындагы үндү (жүрөктүн согушу) коюп бериңиз.','Lahkumisärevus? 🌌','Kas su pisike nutab, kui toast lahkud? Mängi valge müra alt emakaheli (südamelööke), et pakkuda talle seda tuttavat ja rahustavat turvatunnet.'),
('d3ae908a-552f-4504-a171-436173eaeceb'::uuid,'Тиш жуудагы күрөш! 🪥','Ал тиш щеткасын көргөндө оозун бекем жаап жатабы? Бул гигиеналык көнүгүүнү кызыктуу оюнга айландырыңыз, ал үчүн «Сунушталган товарлар» бөлүмүнөн музыкалык же манжага кийилүүчү тиш щеткаларын карап көрүңүз.','Hammaste pesemise lahing! 🪥','Kas ta surub hambaharja nähes suu kinni? Muuda see hügieenitoiming lõbusaks mänguks, vaadates soovitatud toodete alt muusikalisi või sõrmeotsa-hambaharju.'),
('4932b8a8-d024-498c-ba06-d790b59bc198'::uuid,'Өзүңүзгө ырайымдуу болуңуз 🧘‍♀️','Бүгүн баары тескери кеттиби? Сезимдериңизди «Маанай күндөлүгүнө» жазыңыз, өзүңүздү кечириңиз, терең дем алыңыз жана эс алыңыз.','Ole enda vastu leebe 🧘‍♀️','Kas täna läks kõik viltu? Pane oma tunded meeleolupäevikusse kirja, anna endale andeks, hinga sügavalt sisse ja lõõgastu.'),
('ed014436-2469-48a6-b579-7bce93de1ae7'::uuid,'Сөздүк корун кеңейтүү! 🗣️','Эки сөздөн турган сүйлөмдөр көбөйүп жатабы? Бул укмуштуудай тил өнүгүүсүн колдоо жана баарлашууну өркүндөтүү үчүн эмне кылуу керектигин Anacan AI жардамчысынан сураңыз.','Sõnavara laieneb! 🗣️','Kas kahesõnalised laused muutuvad sagedasemaks? Küsi kohe Anacan AI-lt, kuidas seda imelist keelelist arengut kõige paremini toetada ja vestlust soodustada.'),
('ed579060-f78c-4890-b8e4-2bb0c7729792'::uuid,'Баланын заңынын түсү эмнени билдирет 💩','Жалаяк алмаштыруу учурунда көңүл буруңуз! Ич катуунун алдын алуу үчүн анын суюктук жана клетчатка ичүүсүн көзөмөлдөө үчүн «Тамактануу трекерин» колдонуңуз.','Mida beebi kaka värvus tähendab 💩','Mähkmevahetuse ajal ole tähelepanelik! Kasuta toitumisjälgijat, et jälgida lapse vedeliku- ja kiudainete tarbimist, aidates vältida kõhukinnisust.'),
('15f9bb81-a16f-4753-a3f5-a2b604b16a46'::uuid,'Баланын таза абада уктоосу 🌳','Кичинекейиңиз үйдө уктабай жатабы? «Энелер үчүн ыңгайлуу жайлар» бөлүмүнөн тынч, бак-дарактуу сейил бакты табыңыз. Таза аба табитти да, уйкуну да жакшыртат!','Beebi uinakud õues 🌳','Kas su pisikesel on toas raske magama jääda? Leia „Emadele sobivate kohtade“ jaotises rahulik ja roheline park. Värske õhk teeb imesid nii isule kui ka unele!'),
('1e63b6e0-14e2-4999-89f7-2f0db3539031'::uuid,'Түнкү ойгонуулар ⏱️','Уйку таймерин иштетиңиз! Таймердин статистикалык диаграммасы аркылуу бул түнкү коркунучтуу түштөрбү же уйкунун артка кетишиби, дароо талдап көрүңүз.','Öised ärkamised ⏱️','Pane unetaimer tööle! Analüüsi kohe taimeri statistika põhjal, kas tegemist on öiste hirmuhoogude või une regressiooniga.'),
('2097babe-f9a8-45d7-927c-24d3ef08f38a'::uuid,'Күлкү жана жылмаюу! 📸','Кичинекейиңиз сизге карап бетин тырыштырып же күлүп жатабы? Бул таттуу көз ирмемди «Ымыркайдын фотосессиясы» бөлүмүндөгү чаптамалар менен кооздоп, түбөлүк эстелик катары альбомго кошуп коюңуз.','Naerupahvakud ja itsitamine! 📸','Kas su väike ime kirtsutab nina või itsitab, kui ta sulle otsa vaatab? Kaunista see armas hetk beebifotosessiooni kleebistega ja lisa see ajatu mälestusena albumisse.'),
('3d45eb72-a379-4b0c-95b5-43a9f90cd232'::uuid,'Тынчтандыруучу ыргактардын күчү 🎶','Ызы-чуу күндөн кийинки күтүүсүз тынчтык аны чочутабы? Уйку чөйрөсүндө коопсуздук сезимин жаратуу үчүн «Ак ызы-чуу» (White Noises) бөлүмүнөн чач кургаткычтын үнүн коюп бериңиз.','Rahustavate rütmide vägi 🎶','Kas äkiline vaikus pärast lärmakat päeva ehmatab teda? Pane ''Valge müra'' alt mängima föönihääl, et luua tema unekeskkonnas turvatunne.'),
('af588f6b-bdb1-4b34-b380-81bc42d5db3f'::uuid,'Апанын энергиясы 🔋','Өзүңүздү абдан чарчаңкы сезип жатасызбы? Таттуу тамактардан баш тартыңыз! Анын ордуна, аялдар үчүн дени сак рецепттерибизден энергия берүүчү, протеинге бай жержаңгак майы кошулган смузи жасап ичиңиз.','Emme aku 🔋','Tunned end täiesti kurnatuna? Jäta suhkrused näksid vahele! Selle asemel valmista endale meie tervislike retseptide hulgast kiire energiat andev ja valgurohke maapähklivõi smuuti.'),
('3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248'::uuid,'Өсүү секириги жакындап калдыбы? 📏','Анын бою тез өсүп жатат! Учурдагы бою менен бут кийиминин өлчөмүн «Өнүгүү трекерине» киргизип, өсүү графигинин жогорулаганын сыймыктануу менен байкаңыз.','Kasvuhüpe tulekul? 📏','Tal on käimas füüsiline kasvuspurt! Sisesta tema praegune pikkus ja jalanumber arengujälgijasse ning vaata uhkusega, kuidas kasvukõver tõuseb.'),
('5bace5b1-8b66-491f-869e-157ff26e9bbf'::uuid,'Логиканы издөө 🧩','Ал эски оюнчуктарынан тажадыбы? Акыл-эсин курчутуп, көңүлүн бура турган куракка ылайыктуу жана коопсуз табышмактарды «Сунушталган өнүмдөр» бөлүмүнөн изилдеп көрүңүз!','Loogika otsingul 🧩','Kas tal on vanad mänguasjad igavaks muutunud? Uuri meie ''Soovitatud toodete'' sektsioonist eakohaseid ja ohutuid puslesid, mis teritavad tema mõistust ja pakuvad põnevat tegevust!'),
('e03c5d95-be6c-414b-b518-86431da64323'::uuid,'Уруу жана тиштөө этаптары 🦖','Балаңыз ачууланганда агрессивдүү болуп жатабы? Anacan AI менен бул жүрүм-турумду оюнга айландырып, акырындык менен оңдоону үйрөнүңүз.','Löömise ja hammustamise faas 🦖','Kas su laps muutub vihastades agressiivseks? Õpi Anacan AI abil, kuidas seda käitumist õrnalt mänguks muutes suunata.'),
('53335520-c239-4dc6-bb98-8950aeac052d'::uuid,'Жашыруун жашылчалар менен көңүл ачуу! 🥕','Ал сабиз менен шпинатты жебей жатабы? «Ымыркайлар үчүн рецепттер» бөлүмүнөн бул витаминдерди даамдуу куймактардын ичине кантип чеберчилик менен жашырууну үйрөнүңүз.','Peidetud köögiviljade rõõm! 🥕','Kas ta keeldub porgandist ja spinatist? Avasta, kuidas need vitamiinid nutikalt maitsvate pannkookide sisse peita – vaata beebiretseptide sektsiooni.'),
('9cc1439a-0d58-4e5e-94b1-3125467bf825'::uuid,'Өзүңүздү күнөөлөөнүн кереги жок 💖','Бүгүн үнүңүздү көтөрүп жибердиңизби? Өзүңүздү күнөөлөбөңүз. Сезимдериңизди «Маанай күндөлүгүнө» жазып коюңуз; сиз дагы деле ал үчүн эң мыкты энесиз.','Süüdistustele pole ruumi 💖','Kas tõstsid täna häält? Ära ennast süüdista. Pane oma tunded meeleolupäevikusse kirja; oled talle ikkagi maailma parim ema.'),
('bd4e1f9a-2949-4f64-b861-47344e3cdbfc'::uuid,'Түгөнбөгөн тамактануу шоусу ⏱️','Балаңыз тамагы менен ойноп, бирок жебей жатабы? Тамактануу таймерин иштетип, тамак ичүү убактысын көзөмөлдөңүз жана анын табитинин өзгөрүшүн так талдаңыз.','Lõputu söötmis-show ⏱️','Kas su laps mängib toiduga, aga tegelikult ei söö? Aktiveeri söötmistaimer, jälgi söögikorra kestust ja analüüsi täpselt tema isu arengut.'),
('39267d40-2480-48f4-9716-e425031ba3b3'::uuid,'Эгемендүү, бирок байланышта 👶','Кичинекейиңиз сейил бакта башка балдар менен ойнобой, жөн гана байкап турабы? Бул — параллелдүү оюн! Социалдашуунун бул дени сак баскычы тууралуу «Блогдор» бөлүмүнөн кененирээк окуңуз.','Iseseisev, kuid lähedane 👶','Kas su väike ime ei mängi pargis teiste lastega, vaid pigem jälgib neid? See on paralleelmäng! Loe lähemalt selle tervisliku sotsialiseerumisetapi kohta blogide sektsioonist.'),
('7ae07c2d-565f-4b45-bebf-b9e3ab799a99'::uuid,'Кантсыз тамактануу 🍪','Дүкөндөн алынган печеньелерди унутуңуз! «Ымыркайлар үчүн рецепттер» бөлүмүнөн үйдө 10 мүнөттө эле даярдай турган курма жана алма кошулган пайдалуу таттууларды табыңыз.','Suhkruvabad suupisted 🍪','Jäta poeküpsised riiulisse! Avasta meie beebiretseptide sektsioonist tervislikud datli- ja õunamaiused, mida saad kodus vaid 10 minutiga valmis teha.'),
('02902252-366d-405a-a62b-9c6f129b4a84'::uuid,'Акыл кантип өсөт 🧠','21,5 айлык балдардын түс жана форманы кабыл алуусун жакшыртуучу жана мээсин стимулдаштыруучу үй оюндары тууралуу «Блогдор» бөлүмүндөгү макаланы сөзсүз окуңуз.','Kuidas intelligentsus areneb 🧠','Loe kindlasti blogide sektsioonist artiklit koduste mängude kohta, mis arendavad 21,5-kuuse lapse värvi- ja kujutaju ning stimuleerivad aju.'),
('08bbbba1-9e53-4379-a09e-82d1079f7df6'::uuid,'Темирдин деңгээлин текшерүү 🥩','Булчуңдардын активдүү болушу үчүн темирдин жетишсиздигине (анемияга) жол бербеш керек. Бүгүнкү темирдин өлчөмүн текшерүү үчүн «Тамактануу трекерин» колдонуңуз жана жетишсиздикти дароо толуктаңыз!','Rauataseme kontroll 🥩','Aktiivsete lihaste jaoks on rauavaegus (aneemia) välistatud. Kasuta toitumisjälgijat, et kontrollida tänast rauatarbimist ja tegeleda puudujääkidega kohe!'),
('4c3b97db-69e0-4349-8a8d-b599fed49f3d'::uuid,'Түнкүсүн памперс толуп кетеби? 🧻','Эртең мененки өтө оор жалаяк түнкү уйкуну бузушу мүмкүн. Жалаяк трекерине нымдуулукту жазып, кечки суюктук ичүү режимин жөнгө салуу үчүн статистиканы талдаңыз.','Kas mähkmed lekivad öösel? 🧻','Väga raske mähe hommikul võib öist und segada. Märgi mähkmejälgijasse niiskus ja analüüsi statistikat, et õhtust vedelikutarbimist kohandada.'),
('c15f640c-d99c-497d-be3f-c7f256e90fd8'::uuid,'Ашкана изилдөөчүсү 🥦','Кичинекейиңиз ашканада сизге жардам бергиси келеби? «Кошумча тамакка өтүүчү ымыркайлар үчүн рецепттер» бөлүмүнөн чогуу даярдай турган жашылчага бай, даамдуу маффин рецепттерин изилдеңиз.','Köögis avastamas 🥦','Kas su väike ime tahab köögis kampa lüüa? Uuri meie ''Lisatoidu retseptide'' sektsioonist lihtsaid, köögiviljarohkeid ja maitsvaid muffini retsepte, mida saate koos valmistada.'),
('e02612f3-415f-450d-9411-e60c3bd32d09'::uuid,'Тынчтыктын үнү 🌧️','Өтө активдүү күндөн кийин акыл-эсти тынчтандыруу абдан маанилүү. Уйку чөйрөсүн табигый түрдө тынчтандыруу үчүн «Ак ызы-чуу» бөлүмүнөн жамгырдын үнүн коюп бериңиз.','Vaikuse hääl 🌧️','Pärast liiga aktiivset päeva on oluline meelt rahustada. Pane toas mängima ''Valge müra'' vihmaheli, et luua loomulikult rahustav unekeskkond.'),
('3dca59c4-0add-4ccb-919d-3806c0dfdbf4'::uuid,'Жаратылыштын тынчтыгы 🍃','Бүгүн өтө баш аламан жана ызы-чуулуу күн болдубу? Кичинекейиңиздин да, өзүңүздүн да нерв системаңызды тынчтандыруу үчүн «Ак ызы-чуу» бөлүмүнөн жалбырактардын шыбыраган үнүн коюңуз.','Looduse rahu 🍃','Kas päev oli väga kaootiline ja lärmakas? Pane mängima ''Valge müra'' lehtede kahina heli, et rahustada nii oma lapse kui ka enda närvisüsteemi.'),
('e5117ef0-d242-45f1-b114-50b3bfca72d9'::uuid,'Сизге да өз коомчулугуңуз керек ☕','Күнү бою кичинекейиңиз менен гана сүйлөшүп чарчадыңызбы? Башка энелер чогулган, балдарга ыңгайлуу кафелерди табуу үчүн «Энелер үчүн ыңгайлуу жайлар» бөлүмүнө кирип, чоңдор менен баарлашуудан ырахат алыңыз!','Ka sina vajad oma kogukonda ☕','Tunned end väsinuna, sest oled terve päeva rääkinud vaid oma lapsega? Uuri meie ''Emadele sobivaid kohti'', et leida lastesõbralikke kohvikuid, kus teised emad käivad, ja naudi vajalikku täiskasvanute vestlust!'),
('cd9b8bec-56d4-42a3-a245-f71b148a61ef'::uuid,'Үндөн тынчтыкка чейин 🎶','Ызы-чуу оюндан кийинки күтүүсүз тынчтык аны чочутабы? Бөлмөгө «Ак ызы-чуу» бөлүмүнөн чач кургаткычтын үнүн коюп, ырааттуу үндүн уйкуга болгон тынчтандыруучу таасирин байкаңыз.','Helidest rahuni 🎶','Kas äkiline vaikus pärast lärmakat mängu ehmatab teda? Pane toas mängima ''Valge müra'' föönihääl ja jälgi ühtlase heli rahustavat mõju unele.'),
('54f26234-4c50-45b3-9088-6a5b0c08fcd2'::uuid,'Апанын суу балансы 💧','Башыңыз ооруп жатабы? Кичинекейиңиздин артынан чуркап жүрүп суусузданып калган болушуңуз мүмкүн! Дени сак бөлүмүбүздөгү сергитүүчү детокс суусундуктарынын рецепттерин колдонуп, денеңизди калыбына келтириңиз.','Emme vedelikutasakaal 💧','Kas pea valutab? Võid olla vedelikupuuduses, sest oled terve päeva lapse järel jooksnud! Turguta oma keha, proovides meie tervislike retseptide sektsioonist värskendavaid detox-vee retsepte.'),
('a27861d3-4efc-4b58-bec5-f3117fe589e3'::uuid,'Сорттоо оюну! 🔴🔵','Ал кызыл түстөгүлөрдү бир жакка, көктөрдү экинчи жакка бөлүштүргөндү жакшы көрөбү? Бул логикалык өнүгүүнү кызыктуураак кылуу үчүн Anacan AI''дан оюн идеяларын сураңыз.','Sorteerimismäng! 🔴🔵','Kas talle meeldib sorteerida punaseid ühele poole ja siniseid teisele? Et see loogiline areng oleks veelgi lõbusam, küsi Anacan AI-lt mänguideid.'),
('9387504c-dde1-4fdb-977d-53c3dfbb83a2'::uuid,'Коопсуз изилдөөлөр ⚠️','Шкафтар, тартмалар... Кичинекей изилдөөчүңүз үчүн кооптуу аймак! «Сунушталган өнүмдөр» бөлүмүнөн эмерек бекиткичтерин жана коопсуздук кулпуларын карап көрүңүз.','Ohutud avastusretked ⚠️','Kapid, sahtlid... Sinu väikese avastaja jaoks ohtlik tsoon! Vaata meie soovitatud toodete alt mööblikinnitusi ja turvalukke.'),
('bdef77ef-7476-4b14-a4a3-51d31635951f'::uuid,'Келгиле, режимди карап чыгалы ⏱️','Кичинекейиңиз түнкүсүн өтө көпкө ойгоо жатабы? Уйку таймерин иштетиңиз. Балким, күндүзгү уйкусун 15 мүнөткө кыскартуу керек чыгар.','Vaatame rutiini üle ⏱️','Kas su väike ime püsib öösel liiga kaua üleval? Pane unetaimer tööle. Võib-olla on aeg lühendada tema päevaund 15 minuti võrra.'),
('1221d1a0-4818-4be5-bd89-1e05d41e52f3'::uuid,'Апанын бели ооруп жатабы 🧘‍♀️','Кичинекейиңизди көтөрө берип белиңиз ооруп жатабы? Дени сак рецепттерибизден сезгенүүгө каршы жана калыбына келтирүүчү имбирлүү көк чай демдеп, өзүңүзгө кам көрүңүз.','Emme seljavalud 🧘‍♀️','Kas selg valutab lapse pidevast tõstmisest? Hoolitse enda eest ja valmista meie tervislike retseptide hulgast põletikuvastane ja taastav ingveri-rohelise tee jook.'),
('5e592d03-eefe-420f-a53e-496dd3dda1cc'::uuid,'''Туура эмес чөйчөк'' талашыбы? 🥤','Кызыл чөйчөктүн ордуна көк чөйчөктө суу сунуштаганыңыз үчүн эле баш аламандык чыктыбы? Мындай таң калыштуу наристелик кыялдарды тынчтандыруунун жолдорун дароо Anacan AI''дан сураңыз.','„Vale tassi“ lahing? 🥤','Kas puhkes kaos, sest pakkusid vett sinises tassis punase asemel? Küsi Anacan AI-lt kohe rahumeelseid lahendusi sellistele väikelaste näilistele jonnihoogudele.'),
('5fa9e0c4-2198-4898-832b-73dabf54c160'::uuid,'Жүрөгүңүздү бошотуңуз 📝','Бүгүн тынбай ыйлап, сизди чарчатып койдубу? Өзүңүздү күнөөлөбөңүз. Акыл-эсиңизди тазартып, эс алуу үчүн бардык чарчооңузду «Маанай күндөлүгүнө» жазып коюңуз.','Kergenda oma südant 📝','Kas ta nuttis täna lakkamatult ja oled kurnatud? Ära ennast süüdista. Kirjuta kogu oma väsimus meeleolupäevikusse, et mõtted selgeks saada ja lõõgastuda.'),
('d5617275-bfe2-4829-8f3f-d3b94dc34cfe'::uuid,'Келгиле, режимди карап чыгалы ⏱️','Кичинекейиңиз түнкүсүн өтө көпкө ойгоо жатабы? Уйку таймерин иштетип, графигин көзөмөлдөңүз. Балким, күндүзгү уйкусун 15 мүнөткө кыскартуу керек чыгар.','Vaatame rutiini üle ⏱️','Kas su väike ime püsib öösel liiga kaua üleval? Pane unetaimer tööle ja jälgi graafikut. Võib-olla on aeg lühendada tema päevaund 15 minuti võrra.'),
('17a5c3c0-5b0c-46d3-a055-3e4119a58d57'::uuid,'Аларга жомок айтып берүүгө мүмкүнчүлүк бериңиз 📖','Ал китептеги сүрөттөрдү карап, өз тилинде былдырап жатабы? Бул кереметтүү элестетүү көз ирмемин дароо «Ымыркай альбомуна» үн видеосу катары кошуп, келечек үчүн сактап коюңуз.','Lase neil lugu jutustada 📖','Kas ta vaatab raamatust pilte ja lobiseb omas keeles? Lisa see imeline kujutlusvõime hetk kohe häälvideona beebialbumisse ja salvesta see tulevikuks.'),
('200bc386-90fc-4565-9a45-00b11604777d'::uuid,'Төрт дубалдан чыгыңыз! 🌳','Кичинекейиңиз үйдүн ичинде секирип, башаламандык жаратып жатабы? «Энелер үчүн ыңгайлуу жайлар» картасын ачып, чуркаганга коопсуз аянтчасы бар сейил бакты табыңыз да, таза абада эс алдырыңыз.','Põgene nelja seina vahelt! 🌳','Kas su väike ime hüppab toas ringi ja teeb segadust? Ava ''Emadele sobivate kohtade'' kaart, leia park, kus on turvaline ruum jooksmiseks, ja lase tal värsket õhku nautida.'),
('f2808bcb-7bbf-4422-8d7a-f49af045384f'::uuid,'Кыйынчылыктар менен бөлүшүүбү? 🧸','Сейил бакта оюнчуктарын бөлүшкүсү келбей жатабы? 22 айлык балдарга кезек менен ойноону үйрөтүү боюнча «Блогдор» бөлүмүндөгү практикалык макаланы сөзсүз окуңуз.','Jagad muresid? 🧸','Ei taha pargis mänguasju jagada? Loe kindlasti meie praktilist artiklit blogide sektsioonist, kuidas õpetada 22-kuusele lapsele kordamööda mängimise põhimõtet.'),
('5ba12c84-c569-4cd8-9800-87090cc15d44'::uuid,'Сиздин кальций калканыңыз 🦴','Кальций сөөктөрдүн жана тиштердин бекем болушу үчүн абдан маанилүү. Балаңыздын күнүмдүк йогурт жана сыр нормасын аткарып жатканын текшерүү үчүн «Тамактануу трекерин» колдонуңуз.','Sinu kaltsiumikilp 🦴','Kaltsium on hädavajalik tugevate luude ja hammaste jaoks. Kasuta toitumisjälgijat, et tagada lapse igapäevane jogurti ja juustu tarbimine.'),
('7ecc82ad-1a38-4c53-9465-dd5ae12ea103'::uuid,'Бут кийим тар болуп жатабы? 📏','Кичинекейиңиз акыркы убакта чуркаганда көп чалынып жатабы? Буттары өсүп калган болушу мүмкүн! Физикалык өнүгүүсүн көзөмөлдөө үчүн учурдагы бою менен өлчөмдөрүн «Өсүү трекерине» киргизиңиз.','Kas kingad on kitsad? 📏','Kas su väike ime komistab viimasel ajal joostes tihti? Tema jalad võivad olla kasvanud! Sisesta tema praegune pikkus ja mõõdud kasvujälgijasse, et hoida silm peal tema füüsilisel arengul.'),
('d79dc60f-8bf8-4657-a15d-609886c6c332'::uuid,'Тамак кайра эле полдобу? 🥣','Эгер ал кашыктарды жана тамакты столдон ыргытып жатса, демек ал ток же тажады. Тамактануу таймерин токтотуп, диаграмма аркылуу табитинин тенденциясын талдап, тамактанууну аяктаңыз.','Toit jälle põrandal? 🥣','Kui ta loobib lusikaid ja toitu laualt maha, on ta kas kõhu täis söönud või tal on igav. Peata söötmistaimer, analüüsi graafiku abil tema isu suundumusi ja lõpeta söögikord.'),
('596bb7f3-6693-46d8-ab7c-2abd702c9a04'::uuid,'Коопсуздук сезими 🌌','Балаңыз жарыкты өчүргөндө коркуп жатабы? Ага тааныш, жылуу коопсуздук сезимин тартуулоо жана уйкуга акырындык менен киргизүү үчүн «Ак ызы-чуу» функциясынан жүрөктүн согушунун үнүн коюп бериңиз.','Turvatunne 🌌','Kas su laps kardab, kui tuled kustutad? Pane ''Valge müra'' alt mängima rahustav südamelöökide heli, et tekitada tuttav ja soe turvatunne ning aidata tal rahulikult uinuda.'),
('85644ffd-0693-4b98-8af6-f0210f7b50a9'::uuid,'Сизге да социалдык убакыт керек! ☕','Кичинекейиңиз менен гана сүйлөшүүдөн тажадыңызбы? Башка энелер чогулган, балдарга ыңгайлуу кафелерди табуу үчүн «Энелер үчүн ыңгайлуу жайлар» бөлүмүн колдонуп, өзүңүз үчүн жаңы социалдык чөйрө түзүңүз.','Ka sina vajad oma sotsiaalset aega! ☕','Tüdinenud vaid lapsega rääkimisest? Kasuta ''Emadele sobivaid kohti'', et leida lastesõbralikke kohvikuid, kus teised emad käivad, ja loo endale uus sotsiaalne keskkond.'),
('bafa81ec-ed9b-4642-a5cd-3249a43a8c84'::uuid,'Уруу жана түртүү жүрүм-туруму 🛑','Ал ачууланганда күтүлбөгөн жерден кол көтөрөбү? Бул куракка мүнөздүү болгон агрессивдүү эмоцияларды оюнга айландырып, кантип акырындык менен багыттоону Anacan AI''дан сураңыз.','Löömise ja tõukamise käitumine 🛑','Kas ta läheb vihastades äkki närvi? Küsi Anacan AI-lt, kuidas seda vanusele omast agressiivset emotsiooni õrnalt mänguks suunata.'),
('1b86b21d-6e02-4ac7-a965-21bdbcf95db5'::uuid,'Логикадагы секирик 🧩','Ал себеп-натыйжа байланышын түшүнө баштады. 22 айлык балдардын таанып-билүү жөндөмүн өстүрүүчү эң мыкты үй оюндары тууралуу «Блогдор» бөлүмүнөн окуп, колдонуп көрүңүз.','Hüpe loogilises mõtlemises 🧩','Ta hakkab mõistma põhjus-tagajärg seoseid. Loe ja rakenda blogide sektsioonist parimaid koduseid mänge, mis toetavad 22-kuuse lapse kognitiivset arengut.'),
('6351737e-949c-4fb6-a2b3-5af919c832cf'::uuid,'Күнүмдүк тартипти талдап көрөлү ⏱️','Наристеңиздин кечки ойгоо убактысы өтө узарып баратабы? Уйку таймерин иштетип, графикти көзөмөлдөңүз. Балким, алардын күндүзгү уйкусун 15 мүнөткө кыскартуунун дал убагыдыр.','Analüüsime rutiini ⏱️','Kas su pisikese õhtune ärkvelolekuaeg venib liiga pikaks? Käivita unetaimer ja jälgi graafikut. Võib-olla on ideaalne aeg lühendada nende päevaund 15 minuti võrra.'),
('f36fcaba-998e-48e4-a1c2-d085b47ccd2f'::uuid,'Темирдин деңгээлин текшерүү 🥩','Активдүү булчуңдар анемиянын алдын алуу үчүн жетиштүү темирге муктаж. «Тамактануу трекери» менен бүгүнкү темирдин өлчөмүн текшерип, жетишсиздикти дароо толуктаңыз.','Rauataseme kontroll 🥩','Aktiivsed lihased vajavad aneemia vältimiseks piisavalt rauda. Kontrolli tänast rauatarbimist toitumisjälgijaga ja veendu, et puudujäägid saaksid kiiresti kõrvaldatud.'),
('04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b'::uuid,'Пайдалуу кантсыз таттуулар 🍪','Дүкөндөн алынган печеньелердин кереги жок! «Ымыркайлар үчүн рецепттер» бөлүмүнөн анын таттууга болгон каалоосун канааттандыруу үчүн 10 мүнөттө даярдай турган пайдалуу, үй шартындагы курма жана алма таттууларын табыңыз.','Tervislikud suhkruvabad suupisted 🍪','Poeküpsiseid pole vaja! Avasta beebiretseptide sektsioonist tervislikud kodused datli- ja õunamaiused, mida saad 10 minutiga valmistada, et tema magusaisu rahuldada.'),
('7b343e4c-3369-4f05-b976-97c243e8ed13'::uuid,'Өсүү мезгили! 📏','Кичинекейиңиздин көйнөгүнүн жеңдери кайрадан кыскарып калдыбы? Анын бою тез өсүп жаткан болушу мүмкүн! Учурдагы өлчөмдөрүн «Өсүү трекерине» киргизип, өсүү графигиндеги ийгиликтерин сыймыктануу менен караңыз.','Kasvuspurt! 📏','Kas su väikese ime särgi varrukad on jälle lühikesed? Tal võib olla kasvuspurt! Sisesta tema praegused mõõdud kasvujälgijasse ja vaata uhkusega tema edusamme kasvugraafikul.'),
('7c55b3cc-0f0f-47b0-8148-d026b3b7590e'::uuid,'Жаңы сөздөр чыгып жатат! 🗣️','Көп үндөрдү чыгарып жатат, бирок али толук сөздөрдү айта албай жатабы? Анын пассивдүү сөз байлыгын активдүүгө айландыруу үчүн бул сүйкүмдүү былдыроолорун «Ымыркай альбомуна» үн жазуусу катары сактап коюңуз.','Uued sõnad tulevad! 🗣️','Teeb palju hääli, aga täissõnu veel ei ole? Salvesta need armsad lalinad häälmärkmetena beebialbumisse, et julgustada tema passiivset sõnavara aktiivseks muutuma.'),
('614145be-ebb6-498c-9b3f-26a829cb6b6d'::uuid,'Сиздин кичинекей жардамчыңыз 🧹','Кичинекейиңиз үй жумуштарына жардам бергиси келеби? 22,5 айлык балага жоопкерчилик сезимин кантип оюн түрүндө сиңирүү керектиги тууралуу «Блогдор» бөлүмүнөн окуп, иш жүзүндө колдонуңуз.','Sinu väike abiline 🧹','Sinu väike ime tahab kodutöödes aidata? Loe blogide sektsioonist, kuidas 22,5-kuuses lapses mänguliselt vastutustunnet kasvatada ja seda praktikas rakendada.'),
('6d017679-be1f-4b11-b8fd-36574013a33a'::uuid,'Элестетүү чексиз! 🧸','Кичинекейиңиз оюнчук аюусун тамактандырып жатабы же сизди «дарылап» жатабы? Эмпатиянын бул сонун өнүгүүсүн кыска видео катары тартып, «Ымыркай альбомуна» кошуп, өмүр бою сактала турган эстелик жаратыңыз.','Kujutlusvõimel pole piire! 🧸','Kas su väike põnn toidab oma mängukaru või teeskleb, et „ravib“ sind? Jäädvusta see kaunis empaatia areng lühivideona, lisa see „Beebi albumisse“ ja loo mälestus kogu eluks.'),
('f542a783-2187-4790-b865-10366397c49d'::uuid,'Коопсуз изилдөөлөр ⚠️','Шкафтар, тартмалар... Кичинекей изилдөөчүңүз үчүн коркунучтуу аймак! «Сунушталган өнүмдөр» бөлүмүнөн эмерек бекиткичтерин жана коопсуздук кулпуларын сөзсүз карап чыгыңыз.','Ohutud avastusretked ⚠️','Kapid, sahtlid... Sinu väikesele avastajale on see ohtlik tsoon! Vaata kindlasti meie „Soovitatud toodete“ alt mööblikinnitusi ja turvalukke.'),
('1a8b991b-0214-44d5-b2fa-cca54722c709'::uuid,'Дубалдагы сүрөттөр жаралууда 🎨','Калемди алып, дубалга сүрөт тартып койдубу? Капа болбоңуз! Жөн гана жылмайып, «Ымыркай фотосессиясындагы» кызыктуу жээкчелерди колдонуп, бул таттуу тентектикти альбомуна кошуп коюңуз.','Seinakunst valmimas 🎨','Kas ta haaras pliiatsi ja joonistas seinale? Ära pahanda! Naerata hoopis ja lisa see armas temp „Beebi fotosessiooni“ naljakate raamidega albumisse.'),
('5ded1b01-b65d-40da-8990-d4cd09688a69'::uuid,'Түнкүсүн кайра ойгонуп жатабы? ⏱️','Түн ортосунда ыйлап ойгонуп жатабы? Уйку таймеринин графигин текшериңиз. Эгерде күндүзгү уйкусу өтө кеч бүтсө, бул түнкүсүн терең уйкуга өтүүсүн кыйындатышы мүмкүн.','Kas öised ärkamised on tagasi? ⏱️','Kas ta ärkab öösel nutuga? Kontrolli unetaimeri graafikut. Kui päevane uinak lõpeb liiga hilja, võib see raskendada öösel sügavasse unne vajumist.'),
('79c4c89f-ba17-4c97-96b0-f5dc444414e9'::uuid,'Апамдын кофе ичүү тыныгуусу ☕','Өзүңүздү да унутпаңыз, апа! «Аялдар үчүн пайдалуу рецепттер» бөлүмүнөн сулудан жасалган энергия берүүчү тамакты даярдап, аны кофеңиз менен бирге ырахаттанып ичиңиз.','Ema kohvipaus ☕','Ära unusta iseennast, emme! Valmista „Naiste tervislike retseptide“ rubriigist üks kosutav kaeramaius ja naudi seda kohvi kõrvale.'),
('178de938-0734-4759-bd61-91671bd355ba'::uuid,'Туура горшокту тандоо 🚽','Горшокко үйрөтүүгө визуалдык даярдыкты баштайлы! Башка энелер тарабынан сыналган эң ыңгайлуу жана кызыктуу горшок моделдерин «Сунушталган өнүмдөр» бөлүмүнөн сөзсүз карап чыгыңыз.','Õige poti valimine 🚽','Las potitreeningu visuaalne ettevalmistus alata! Vaata kindlasti „Soovitatud toodete“ alt teiste emade poolt testitud kõige mugavamaid ja põnevamaid potimudeleid.'),
('2f6cc31a-8b1b-415e-861a-b476799ab26e'::uuid,'Наристеңизге Омега-3 жетиштүүбү? 🐟','Балык же жаңгак мээнин тез өнүгүүсү үчүн өтө маанилүү! «Тамактануу трекери» менен бул аптадагы Омега-3 нормаңызды текшерип, менюсун дароо жаңыртыңыз.','Kas su väike laps saab piisavalt oomega-3-rasvhappeid? 🐟','Kala või kreeka pähklid on aju kiireks arenguks hädavajalikud! Kontrolli sel nädalal toitumisjälgijaga oma Omega-3 tarbimist ja uuenda kohe lapse menüüd.'),
('f1e65e7a-efb2-4ee4-9b90-639511a93965'::uuid,'Кемчиликсиз болуунун кажети жок 💖','Бүгүн үй башаламан болуп кеттиби? Кечки тамак кечигип жатабы? Баары жайында! «Маанай күндөлүгүңүзгө» чыныгы сезимдериңизди жазыңыз жана кичинекейиңиз сизди кандай болсоңуз, ошондой бойдон чексиз сүйөрүн эсиңизден чыгарбаңыз.','Pole vaja olla täiuslik 💖','Kas kodus on täna täielik kaos? Kas õhtusöök hilineb? See on täiesti okei! Kirjuta oma tõelised tunded meeleolupäevikusse ja pea meeles, et su väike põnn armastab sind tingimusteta, just sellisena, nagu oled.'),
('0ec68466-1a64-4bc2-ab11-6f19a539925d'::uuid,'Дени сак сиңирүү үчүн суу ичүү 💧','Активдүү бөбөгүңүздүн ичеги-карыны кандай? Жоолук алмаштырганда белгилеп туруңуз. Эгер ич катуу коркунучу болсо, колдонмодон табигый булалуу азыктар боюнча сунуштарды караңыз.','Vedeliku tarbimine tervislikuks seedimiseks 💧','Kuidas su aktiivse põnni kõhuga lood on? Märgi mähkmevahetuse ajal märkmeid. Kui on kõhukinnisuse oht, vaata äpist looduslikke kiudainerikkaid toidusoovitusi.'),
('e1d32a6a-e4ea-4c4f-8731-157813de9284'::uuid,'Башка энелер менен баарлашуу 👯‍♀️','Сиз баарлашып жатканда балаңыз ойносун! «Энелер үчүн ыңгайлуу жайлар» картасынан оюн топтору бар борборду таап, үйдөн чыгып эс алыңыз.','Teiste emadega suhtlemine 👯‍♀️','Lase lapsel mängida, samal ajal kui sina suhtled! Leia „Emadesõbralike kohtade“ kaardilt mängugrupiga keskus ja saa kodust välja.'),
('2e576d6b-3baa-4d91-b939-7173553eee26'::uuid,'Кичинекей тиштерди жууп жатасызбы? 🪥','Тиш щеткасын көрөрү менен оозун бекем жаап алабы? Бул гигиеналык көнүгүүнү кызыктуу оюнга айлантуу боюнча Anacan AI''дан практикалык кеңештерди алыңыз.','Kas pesete juba pisikesi hambaid? 🪥','Kas ta surub suu kinni kohe, kui näeb hambaharja? Küsi Anacan AI-lt praktilisi nippe, kuidas muuta see hügieenirutiin lõbusaks mänguks.'),
('8e98b7fa-b3a5-48a4-896a-9431c201a988'::uuid,'Табигый тынчтандыруучу каражаттар 🍃','Бүгүн өтө ызы-чуулуу күн болдубу? Таймер токтоду. Үй жумуштарын унутуп, «Пайдалуу рецепттер» бөлүмүнөн өзүңүзгө эс алдыруучу лимон чөбүнөн чай демдеп, тынчтыктан ырахат алыңыз.','Looduslikud rahustajad 🍃','Kas oli eriti lärmakas päev? Taimer on peatunud. Unusta kodutööd, valmista endale tervislike retseptide rubriigist lõõgastavat melissiteed ja lihtsalt naudi vaikust.'),
('e49913ea-33f5-4d6e-8204-24fdfbb6dfec'::uuid,'Пайдалуу таттууларды табуу 🍎','Дүкөндөн алынган печеньелерди унутуңуз! «Ымыркай рецепттери» бөлүмүнөн 10 мүнөттө даярдала турган, табигый курма жана алма кошулган пайдалуу печеньелерди табыңыз.','Tervislike magusate suupistete leidmine 🍎','Jäta poeküpsistega hüvasti! Avasta „Beebiretseptide“ alt tervislikud kodused datli- ja õunaküpsised, mida saad valmistada vaid 10 minutiga, et lapse isu äratada.'),
('8566be64-ecf0-4dc1-8d90-20c831db74ad'::uuid,'Ажырашуу коркунучу кайра башталдыбы? 🌌','Бөлмөдөн чыгып кетсеңиз эле кичинекейиңиз артыңыздан ыйлайбы? Бул бөлүнүү тынчсыздануусу болушу мүмкүн. Ага коопсуздук сезимин тартуулоо жана уйкуга жеңил өтүүсү үчүн «Ак ызы-чуу» функциясынан жүрөктүн согушунун үнүн коюп бериңиз.','Kas lahusolekuärevus on tagasi? 🌌','Kas su väike põnn nutab su järele kohe, kui toast lahkud? See võib olla lahkumisärevus. Mängi valge müra funktsioonist rahustavat südamelöökide heli, et pakkuda talle turvatunnet ja aidata õrnalt uinuda.')) v(id,tk,bk,te,be) WHERE t.id=v.id;
UPDATE public.mommy_day_notifications t SET title_ky=coalesce(t.title_ky,v.tk), body_ky=coalesce(t.body_ky,v.bk), title_et=coalesce(t.title_et,v.te), body_et=coalesce(t.body_et,v.be)
 FROM (VALUES ('942d7419-7926-47e6-b70e-db59dc58e301'::uuid,'Дагы бир өсүү мезгили! 📏','Көйнөктүн жеңдери кыскарып баратабы? Бул өсүү мезгили окшойт! Учурдагы өлчөмдөрүн «Салмак трекерине» киргизип, анын өсүү графигине сыймыктануу менен көз салыңыз.','Järjekordne kasvuspurt! 📏','Kas särgi varrukad hakkavad kitsaks jääma? See kõlab nagu kasvuhüpe! Sisesta praegused mõõdud „Kaalujälgijasse“ ja vaata uhkusega tema kasvugraafikut.'),
('95ec49ae-492b-442d-be59-8db9c9f8c8e4'::uuid,'Сүйкүмдүү жаңы сөздөр 🗣️','Кээ бир сөздөрдү абдан таттуу, бирок туура эмес айтышат! Бул алтын көз ирмемдерди өткөрүп жибербеңиз. Аларды үн жазуу же видео катары «Ымыркай альбомуна» жүктөп, келечекте чогуу күлүңүздөр.','Armsad hääldused 🗣️','Nad ütlevad mõningaid sõnu nii armsalt, kuid valesti! Ära maga neid kuldseid hetki maha. Laadi need häälmärkmete või videotena üles beebi albumisse ja naerge tulevikus koos.'),
('25439bfb-873c-4735-bc03-f5aa2d6b8ff2'::uuid,'Белоктун өлчөмүн текшерүү 🍗','Белок булчуңдардын активдүү иштеши үчүн өтө маанилүү. «Тамактануу трекерин» колдонуп, анын күнүмдүк рационун баалаңыз жана менюсун ошого жараша байытыңыз.','Valgu tarbimise kontrollimine 🍗','Valk on aktiivsetele lihastele ülioluline. Kasuta „Toitumisjälgijat“, et hinnata lapse päevast toidulauda ja rikastada menüüd vastavalt.'),
('a458d5c8-d74f-4a15-a4a9-53e24632f8f7'::uuid,'Кийинип алуу кезеги меники! 👕','Эртең менен кийинүү чоң чыр-чатакка айланып жатабы? Anacan AI''дан баланын каршылыгын кантип жеңүү жана ага тандоо мүмкүнчүлүгүн берүү менен өзүнө болгон ишенимин кантип арттыруу керектигин үйрөнүңүз.','Minu kord riietuda! 👕','Kas hommikune riietumine muutub suureks nutukrambiks? Õpi Anacan AI-lt otse, kuidas trotsiga toime tulla ja kuidas lapsele valikuvõimaluste andmisega enesekindlust sisendada.'),
('f5dd0c22-b8ec-461e-a5b4-9045aa3ae282'::uuid,'Китепти жыртпай окуу 📖','Уктаар алдында жомок окуп жатканда китептин барактарын айрып жатабы? Окууга болгон сүйүүсүн өчүрбөстөн, бул көйгөйдү кантип чечүү керектигин «Блогдор» бөлүмүнөн дароо окуп чыгыңыз.','Lugemine, mitte rebimine 📖','Kas ta rebis unejutu ajal lehti? Loe blogide rubriigist kohe, kuidas seda probleemi lahendada ilma lapse lugemishuvi pärssimata.'),
('65db46df-45b6-4a1e-ae35-6797a38fafce'::uuid,'Кум жана ылай менен ойноо 🏖️','Кир болуудан коркпоңуз! Эң мыкты кинетикалык кум жана сезүү органдарын өнүктүрүүчү оюнчуктарды «Сунушталган өнүмдөр» бөлүмүнөн азыр табыңыз.','Liiva- ja mudamängud 🏖️','Ära karda, kui läheb segaduseks! Avasta parim kineetiline liiv ja sensoorse mängu tarvikud kohe meie „Soovitatud toodete“ rubriigist.'),
('dc3f8791-df91-4f2d-8dc5-44a0fff017da'::uuid,'Сиздин эмгегиңиз текке кетпейт! 🌟','Ар бир жаңы үйрөнгөн жөндөм, ар бир ишенимдүү кадам — сиздин эмгегиңиздин жемиши. «Маанай күндөлүгүңүздү» ачып, бүгүн өзүңүздү жана аракеттериңизди мактоо үчүн бир сап жазып коюңуз!','Sinu raske töö kannab vilja! 🌟','Iga uus õpitud oskus ja iga enesekindel samm on tõestus sinu raskest tööst. Ava oma „Meeleolupäevik“ ja kirjuta täna märge, et tähistada iseennast ja oma pingutusi!'),
('2dafd9b8-26be-4b73-a1b1-cede334643cd'::uuid,'Бүгүн канча жолу ''жок'' дедиңиз? 💆‍♀️','Абдан чарчадыңыз, ээ? Терең дем алыңыз. Бардык сезимдериңизди «Маанай күндөлүгүңүзгө» төгүп, күнөөлүү сезимдерди четке кагыңыз жана жөн гана эс алууга уруксат бериңиз.','Mitu „ei-d“ täna tuli? 💆‍♀️','Oled täiesti kurnatud, eks? Hinga sügavalt sisse. Vala kõik oma tunded meeleolupäevikusse, jäta süütunne kõrvale ja luba endal lihtsalt puhata.'),
('379a5991-8f1e-48b3-9f27-5e21468d8859'::uuid,'Кургак ойгонду! 🩲','Бүгүн эртең менен жалаягы кургак экенин байкадыңызбы? Горшокко үйрөтүүнү баштоо үчүн эң ылайыктуу убакыт жана психологиялык ыкмалар тууралуу Anacan AI''дан дароо сураңыз.','Ärkas kuiva mähkmega! 🩲','Kas märkasid täna hommikul kuiva mähet? Küsi Anacan AI-lt kohe täiuslikku ajastust ja psühholoogilisi meetodeid potitreeningu alustamiseks.'),
('9728ea76-627d-4390-8b60-df7f4a0dc917'::uuid,'Кекс сүйүүчүлөр 🧁','Таттуу бир нерсе жегиңиз келип жатабы? Дүкөнгө шашпаңыз. «Ымыркай рецепттеринен» 10 мүнөттө даярдалуучу, кантсыз, банан жана сулу кошулган кекс менен «Тамактануу трекериндеги» балансты сактап калыңыз.','Armastus koogikeste vastu 🧁','Kas tahaksid midagi magusat? Ära torma poodi. 10-minutiliste suhkruvabade banaani-kaeraküpsistega „Beebiretseptide“ rubriigist saad hoida „Toitumisjälgijas“ tervislikku tasakaalu.'),
('685f831c-092e-4c6a-aaf1-8fc0973b0182'::uuid,'5 мүнөттүк энергия заряды ⚡','Эртең менен туруп эле үй жумуштарына киришпеңиз. «Аялдар үчүн пайдалуу рецепттер» бөлүмүнөн антиоксиданттарга бай, мөмө-жемиш жана сулу кошулган тамак менен күчүңүздү калыбына келтириңиз.','5-minutiline energialaeng ⚡','Ära torma hommikul esimese asjana kodutöid tegema. Turguta oma keha antioksüdantiderikka marja-kaerapudruga „Naiste tervislike retseptide“ rubriigist.'),
('2ac666c9-f3bd-4794-a981-76652151d626'::uuid,'Көзүн ушалап жатабы? 🥱','Уйкусу келип жатканы байкалууда! Уйку таймерин иштетиңиз, «Ак ызы-чуу» функциясынан токойдун жумшак шыбырын коюп, аны тынч уктатыңыз жана графигин көзөмөлдөңүз.','Hõõrub silmi? 🥱','Unemärgid on kohal! Käivita unetaimer, mängi valge müra funktsioonist õrna metsakohinat, et laps vaikselt uinutada, ja jälgi graafikut.'),
('5ce76677-164d-4bc6-835d-9ba614b47d9b'::uuid,'Апалардын кофе ичүү убактысы ☕','Эс алуу убактысы! Балаңыз өз алдынча ойноп жатканда, «Аялдар үчүн пайдалуу рецепттер» бөлүмүндөгү идеяларды колдонуп, антиоксидантка бай көк чай же жеңил кофе менен күчүңүздү толуктаңыз.','Emme kohvitund ☕','On puhkepausi aeg! Samal ajal kui laps iseseisvalt mängib, taasta oma energiat antioksüdantiderikka rohelise tee või kerge kohviga, kasutades „Naiste tervislike retseptide“ ideid.'),
('35dcaff3-d09c-4c5a-87b5-8fa048fa86b8'::uuid,'Наристеңиз дубалга чыгып жатабы? 🧗','Анын энергиясын сарпташы өтө маанилүү! «Энелер үчүн ыңгайлуу жайлар» картасын ачып, чуркоочу аянтчасы жана слайды бар жаңы сейил бакты табыңыз да, эркин ойнотуңуз.','Kas su väike laps ronib mööda seinu? 🧗','Lapsele on ülioluline see energia välja elada! Ava „Emadesõbralike kohtade“ kaart, avasta uus park, kus on turvaline jooksu- ja liumägi, ning lase tal vabalt mängida.'),
('3eefbe35-a241-4512-8320-0993efa296ef'::uuid,'Дасторкондон качуу! 🏃‍♂️','Тамагын жарым калтырып, ойноп кеттиби? Тамактануу таймерин токтотуңуз. Мажбурлап тамактандыруунун ордуна, «Блогдор» бөлүмүнөн табитти табигый жол менен ачуунун сырларын окуп чыгыңыз.','Põgenemine söögilauast! 🏃‍♂️','Kas ta jätab söögi pooleli, et mängima joosta? Peata söötmistaimer. Sundimise asemel loe blogide rubriigist nippe, kuidas loomulikult lapse söögiisu stimuleerida.'),
('ecf28bb2-147f-47c5-8e81-503885a13db6'::uuid,'Эмне үчүн бут кийимим кысып жатат? 👟','Чуркап жатканда көп чалынып жатабы? Буту чоңоюп калган болушу мүмкүн! Учурдагы өлчөмдөрүн «Өсүү трекерине» киргизип, өсүү темпин талдап, өсүү мезгили келип-келбегенин текшериңиз.','Miks mu kingad tunduvad kitsad? 👟','Kas ta komistab joostes tihti? Tema jalad võisid kasvada! Analüüsi kasvu, sisestades praegused mõõdud kasvujälgijasse, ja kontrolli kohe, kas tegemist on kasvuhüppega.'),
('a2d43041-fecf-4b9c-87c8-b48f899e1810'::uuid,'Түнкү ойгонуулар ⏱️','Уйку таймерин иштетиңиз! Таймердин статистикалык графигин так талдап, бул түнкү коркунучтуу түшпү же уйкунун бузулушубу экенин билип, ага жараша күн тартибин тууралаңыз.','Öised ärkamised ⏱️','Käivita unetaimer! Analüüsi taimeri statistilist graafikut, et näha, kas tegemist on öise hirmuhoo või une regressiooniga, ning kohanda seejärel rutiini.'),
('ca7d5385-3628-4318-a29d-52e41611d6dd'::uuid,'Акыл-эс өнүгүүсү эч качан токтобойт 🧠','Алар баарын сорттогонду жакшы көрүшөт! Түстөрдү жана формаларды таанууну өркүндөтүүчү, мээнин өнүгүүсүнө түрткү берүүчү геометриялык табышмактарды «Сунушталган өнүмдөр» бөлүмүнөн дароо табыңыз.','Kognitiivne areng ei peatu kunagi 🧠','Talle meeldib kõike sorteerida! Avasta kohe meie „Soovitatud toodete“ alt geomeetrilised pusled, mis arendavad värvi- ja kujutuvastust ning stimuleerivad aju arengut.'),
('2c09d1ae-89ad-4429-b136-e47270b6a957'::uuid,'Бүгүн сиз жылдызсыз! 🌟','Кичинекейиңиздин ар бир жаңы үйрөнгөн жөндөмү — сиздин эмгегиңиздин жемиши. «Маанай күндөлүгүңүздү» ачып, бүгүн өзүңүз менен сыймыктана турган бир сап жазып коюңуз!','Oled tänane täht! 🌟','Iga uus oskus, mille su väike põnn omandab, on tõestus sinu raskest tööst. Ava oma meeleolupäevik ja kirjuta täna märge, mis paneb sind enda üle tõeliselt uhkust tundma!'),
('c795e5c9-7249-46e0-9227-8cae7b9774c9'::uuid,'Формаларды үйрөнүүдөбү? 🧩','Логикалык өнүгүүнү күчөткүңүз келеби? Жашына ылайыктуу геометриялык табышмактарды жана билим берүүчү жыгач оюнчуктарды «Сунушталган өнүмдөр» бөлүмүнөн азыр табыңыз!','Kujundite õppimine? 🧩','Soovid loogilist arengut turgutada? Leia eakohased geomeetrilised pusled ja harivad puidust mänguasjad kohe meie „Soovitatud toodete“ rubriigist!'),
('ce8c0e6d-8b04-4829-9134-54da2f1cc621'::uuid,'Белокту текшерүү! 🥚','Белок тез өсүп жаткан булчуңдар үчүн өтө маанилүү. «Тамактануу трекерин» колдонуп, бүгүнкү нормасын эсептеп чыгыңыз жана жетишсиз болсо, менюсун толуктаңыз.','Valgu kontroll! 🥚','Valk on kiiresti kasvavatele lihastele hädavajalik. Kasuta toitumisjälgijat, et arvutada tänane tarbimine ja vajadusel menüüd kohandada.'),
('d5a7dad1-9dd5-40f2-bc6d-27d7e6052c76'::uuid,'Биринчи чоң сүйлөшүүлөр 🗣️','Кичинекейиңиз өзүнүн тилинде сиз менен бир нерсени «талкуулап» жатабы? Бул баалуу жана таттуу көз ирмемди үнү менен кошо видеого тартып, «Ымыркай альбомуна» сактап коюңуз.','Esimesed pikad jutud 🗣️','Kas su väike põnn „arutab“ sinuga pikalt oma erilises keeles? Jäädvusta see väärtuslik ja armas hetk koos heliga videona ja salvesta see beebi albumisse.'),
('6d0154ad-03f9-4392-b21e-d18f214374b2'::uuid,'Капыстан кыйкырып ыйлоо! 🛑','Каалаган нерсеси болбой калганда жерге жатып алып ыйлайбы? 23 айлык курактагы бул эмоционалдык жарылууларды кантип оюнга айландыруу керектигин Anacan AI эксперттик жардамчыбыздан сураңыз.','Äkilised karjumishood! 🛑','Kas ta viskab end põrandale, kui ei saa seda, mida tahab? Küsi meie Anacan AI eksperdilt, kuidas muuta need 23-kuuse lapse emotsionaalsed pursked mänguks.'),
('9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c'::uuid,'Суу ичүүнү унутпаңыз! 💧','Бөбөгүңүздүн ичеги-карын саламаттыгына тынчсызданып жатасызбы? Жоолук алмаштырганда заңына көз салып туруңуз. Эгер ич катуудан шектенсеңиз, колдонмодон табигый булалуу азыктар боюнча сунуштарды сөзсүз караңыз.','Ära unusta juua vett! 💧','Kas muretsed lapse kõhutervise pärast? Jälgi mähkmevahetuse ajal väljutusi. Kui kahtlustad kõhukinnisust, vaata kindlasti äpist looduslikke kiudainerikkaid toidusoovitusi.'),
('bc4d0552-0cde-4c7a-bca8-4b2551c95ad7'::uuid,'Караңгыдан коркуубу? 🌌','Жарыкты өчүргөндө кичинекейиңиз ыйлайбы? Ага тааныш жана коопсуз сезим тартуулоо үчүн «Ак ызы-чуу» функциясынан эненин курсагындагы үндү (жүрөктүн согушун) коюп бериңиз.','Pimedusekartus? 🌌','Kas su väike põnn nutab, kui tuled kustutad? Mängi valge müra funktsioonist ema üsa rahustavat heli (südamelööke), et pakkuda talle seda tuttavat ja täiuslikku turvatunnet.'),
('8497fe17-ba82-4513-8de8-e30bada196eb'::uuid,'Узак күндөн кийин эс алуу 🛋️','Күнү бою кичинекейиңиздин артынан чуркап чарчадыңызбы? Ал уктап жатканда, бардык стрессиңизди «Маанай күндөлүгүңүзгө» жазып, өзүңүзгө бир чыны чөп чай демдеп ичиңиз.','Lõõgastu pärast pikka päeva 🛋️','Oled väsinud terve päeva lapse järel jooksmisest? Nüüd, kui ta magab, kirjuta kogu oma stress meeleolupäevikusse ja vala endale tassike rahustavat taimeteed.'),
('0347ce08-669e-4477-9fbc-63c1580b9edb'::uuid,'Сиз бүгүнкү күндүн каарманысыз 🌟','Ар бир жаңы үйрөнгөн жөндөмү, ар бир ишенимдүү кадамы — сиздин эмгегиңиздин жемиши. «Маанай күндөлүгүңүздү» ачып, бүгүн өзүңүздү мактап, сыймыктанган бир сап жазып коюңуз!','Oled tänane kangelane 🌟','Iga uus oskus, mille ta omandab, ja iga enesekindel samm on tõestus sinu raskest tööst. Ava oma meeleolupäevik ja kirjuta täna uhke märge, et tähistada iseennast!'),
('19e2869e-6998-4c65-b3a4-edbc6a06f435'::uuid,'Жашылчалардан качып жатабы? 🥦','Тамакты тандап жей баштадыбы? Бөбөгүңүздүн табитин ачуу үчүн биздин рецепттерден шпинат менен сабизди даамдуу куймакка кантип жашырып кошууга болорун билип алыңыз.','Kas jooksed köögiviljade eest ära? 🥦','Kas valiv söömine on alanud? Avasta meie beebiretseptidest, kuidas nutikalt spinatit ja porgandit maitsvatesse pannkookidesse peita, et lapse isu turgutada.'),
('b793a816-4035-4e2c-8e9a-647949d5fa3a'::uuid,'Кичинекей сүрөтчүңүз иштеп жатат! 🎨','Боёкко белинип калса да, капа болбоңуз! Бул көңүлдүү учурду «Бөбөктүн сүрөт сессиясы» бөлүмүндөгү шайыр стикерлер менен кооздоп, альбомуңузга жылмаюу тартуулаңыз.','Sinu väike kunstnik on töös! 🎨','Isegi kui nad on värviga koos, ära muretse! Naudi seda loomingulist hetke, lisades albumisse rõõmsameelseid kleebiseid jaotises ''Beebi fotosessioon'' ja üks naeratus.'),
('924176de-d987-4381-ba5c-3bdf618f72f9'::uuid,'Наристеңиз эт жебей жатабы? 🥩','Бөбөгүңүзгө белок керек, бирок эт жебей жатабы? «Бөбөктөр үчүн рецепттер» бөлүмүнөн чайноого оңой, даамдуу тоок котлеттерин табыңыз. Бул алардын «Тамактануу трекеринде» белгиленген күнүмдүк белок нормасын алууга жардам берет.','Kas su väike laps keeldub lihast? 🥩','Kas su väike laps vajab valku, aga keeldub lihast? Leia ''Beebiretseptidest'' kergesti näritavad ja maitsvad kanapallid, mis aitavad täita päevast valgunormi, mida saad jälgida ''Toitumise jälgijas''.'),
('75bd2c8f-8af9-437f-ac84-6c69bc76ea8c'::uuid,'Уктоо убактысынан качуу планы 🏃‍♂️','Бөбөгүңүз уктаар маалда бөлмөдөн качып кеткиси келеби? Уйку таймерин иштетип, «Ак ызы-чуу» (White Noise) функциясынан токойдун тынчтандыруучу үндөрүн коюп, бөлмөнү бейпил жайга айлантыңыз.','Põgenemisplaan magamamineku ajal 🏃‍♂️','Kas su väike laps üritab magamamineku ajal toast põgeneda? Käivita unetaimer, pane mängima rahustavad metsahelid funktsioonist ''Valge müra'' ja muuda nende tuba rahulikuks pelgupaigaks.'),
('bd146fb2-5002-4d8c-824b-58bbd81c0c9b'::uuid,'Эртең мененки ыйлоолор 🛑','«Муну кийбейм!» же «Муну жебейм!» деген өжөрлүк таңкы убактыңызды кыйындатып жатабы? Бул куракка мүнөздүү болгон чектерди сынап көрүү жүрүм-турумун кантип жөнгө салууну билүү үчүн дароо Anacan AI''дан сураңыз.','Hommikused jonnihoogud 🛑','Kas ''Ma ei pane seda selga!'' või ''Ma ei söö seda!'' jonnihood teevad hommikud keeruliseks? Küsi kohe Anacan AI-lt, kuidas nendele vanusele omastele piire katsetavatele käitumismustritele läheneda.'),
('fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7'::uuid,'Жаңы бийиктиктерди багындыруу! 🧗‍♂️','Бөбөгүңүз чыныгы шамдагай! Анын чексиз энергиясын сарптоо үчүн «Энелерге ыңгайлуу жайлар» бөлүмүнөн кенен ички оюн аянтчалары бар борборлорду таап, эркин ойнотуңуз.','Uute kõrguste vallutamine! 🧗‍♂️','Su väike laps on tõeline julge pealehakkaja! Et aidata neil piiramatut energiat kulutada, leia ''Emadele sobivate kohtade'' hulgast avara siseruumiga mängualad ja lase neil vabalt mängida.'),
('0b69ffc4-e10f-4228-a354-3609a2cf48bb'::uuid,'Тиштеп алуу! 🦖','Ачууланганда досторун же сизди тиштеп жатабы? Бул татаал жүрүм-турумду мээримдүүлүк менен кантип оңдоону билүү үчүн Anacan AI эксперттик жардамчыбыздан дароо сураңыз.','Hammustamine vihahoos! 🦖','Kas nad hammustavad vihastades oma sõpru või sind? Küsi kohe meie Anacan AI eksperdilt, kuidas seda keerulist käitumist armastavalt lahendada.'),
('0bd19a92-8f32-4626-9053-67019de34d6b'::uuid,'Балаңыз бир гана нан жеп жатабы? 🍞','Бөбөгүңүз белок менен жашылчаларды четке кагып, углеводдорду гана каалап жатабы? Тамактанууну көзөмөлдөө куралын колдонуп, анын күнүмдүк пайдалуу тамак-аш нормасын эсептеп, рационун тууралаңыз.','Kas su laps sööb ainult saia? 🍞','Kas su väike laps lükkab valgud ja köögiviljad kõrvale, ihaldades vaid süsivesikuid? Kasuta toitumise jälgimise tööriista, et arvutada nende kasulik päevane toidukogus ja vajadusel menüüd kohandada.'),
('3794ac2c-9f00-4406-8f93-da27c84ffed3'::uuid,'Китеп жыртуу: бул убактылуубу? 📖','Бөбөгүңүз уктаар алдында жомок окуп жатканда китептин барактарын айрып жатабы? Муну анын окууга болгон кызыгуусуна зыян келтирбей кантип чечүү керектигин билүү үчүн биздин блогдорду окуңуз.','Lehekülgede rebimine: kas see on faas? 📖','Kas su laps üritab unejutu ajal raamatulehti rebida? Loe meie blogisid, et teada saada, kuidas seda lahendada ilma nende lugemishuvi kahjustamata.'),
('21c31221-548f-42a2-945f-424351b307be'::uuid,'Дубалдагы сүрөт шедеврлери! 🎨','Калем алып дубалга сүрөт тартып койдубу? Капа болбоңуз! Жөн гана жылмайып, бул таттуу тентектикти «Бөбөктүн сүрөт сессиясы» бөлүмүндөгү күлкүлүү жээкчелер менен альбомуңузга кошуп коюңуз.','Seinakunsti meistriteosed! 🎨','Kas nad võtsid pliiatsi ja joonistasid seinale? Ära pahanda! Naerata lihtsalt ja lisa see armas pahandus oma albumisse naljakate raamidega beebi fotosessioonist.'),
('cb6101a7-dbfd-4d36-944e-5acbfd6bc964'::uuid,'Белиңиз ооруп жатабы? 🧘‍♀️','12+ кг салмактагы бөбөктү тынымсыз көтөрүү булчуңдарыңызга оордук келтириши мүмкүн. Биздин пайдалуу рецепттерден сезгенүүгө каршы имбирь чайын демдеп ичип, өзүңүзгө татыктуу эс алуу тартуулаңыз.','Kas selg valutab? 🧘‍♀️','Üle 12 kg kaaluva lapse pidev tõstmine võib lihastele koormav olla. Valmista endale meie tervislike retseptide järgi rahustavat põletikuvastast ingveriteed ja võta üks väljateenitud puhkepaus.'),
('e15645b0-86cf-412b-8fdc-f53e32110fb7'::uuid,'Керебеттен качуу оюну 🏃‍♂️','Уктаар маалда бешиктен же керебеттен чыгып кетеби? Уйку таймерин иштетип, «Ак ызы-чуу» функциясынан поезддин бир калыптагы үнүн коюп, аны акырындык менен уктатыңыз.','Suur voodist põgenemine 🏃‍♂️','Kas nad ronivad magamamineku ajal võrevoodist välja? Käivita unetaimer, pane mängima ''Valge müra'' alt rongi monotoonne heli ja uinuta nad õrnalt magama.'),
('97ab1430-c17a-4645-93d1-2d0b7261c822'::uuid,'Балаңыз бир гана нан жеп жатабы? 🍞','Бөбөгүңүз белок менен жашылчаларды четке кагып, углеводдорду гана каалап жатабы? Тамактанууну көзөмөлдөө куралын колдонуп, анын күнүмдүк пайдалуу тамак-аш нормасын эсептеп, рационун тууралаңыз.','Kas su laps sööb ainult saia? 🍞','Kas su väike laps lükkab valgud ja köögiviljad kõrvale, ihaldades vaid süsivesikuid? Kasuta toitumise jälgimise tööriista, et arvutada nende kasulik päevane toidukogus ja vajadusel menüüd kohandada.'),
